}
function loadSyncState(): array {
if (!file_exists(SYNC_STATE_FILE)) return [];
$d = @json_decode(@file_get_contents(SYNC_STATE_FILE) ?: '', true);
return is_array($d) ? $d : [];
}
function saveSyncState(array $s): bool {
