}
function parseCSVFile(string $filePath): array {
$rows = [];
$handle = fopen($filePath, 'r');
if (!$handle) return [];

$bom = fread($handle, 3);
if ($bom !== "\xEF\xBB\xBF") rewind($handle);
$headers = null;
while (($row = fgetcsv($handle, 0, ',')) !== false) {
if ($headers === null) { $headers = $row; continue; }
if (count($row) < count($headers)) continue;
$assoc = [];
foreach ($headers as $i => $h) {
$h = trim($h);
$assoc[$i] = $row[$i] ?? '';
}
$rows[] = ['headers' => $headers, 'values' => $assoc];
}
fclose($handle);
return ['headers' => $headers ?: [], 'rows' => $rows];
}
function parseExcelXML(string $filePath): array {
$content = file_get_contents($filePath);
if (!$content) return ['headers' => [], 'rows' => []];
libxml_use_internal_errors(true);
$xml = @simplexml_load_string($content);
if (!$xml) return ['headers' => [], 'rows' => []];
$ns = $xml->getNamespaces(true);
$ss = $ns['ss'] ?? 'urn:schemas-microsoft-com:office:spreadsheet';
$rows = [];
$headers = [];
$rowIdx = 0;
foreach ($xml->Worksheet->Table->Row as $row) {
$cells = [];
$colIdx = 0;
foreach ($row->Cell as $cell) {
$attrs = $cell->attributes($ss);
$idx = isset($attrs['Index']) ? (int)$attrs['Index'] - 1 : $colIdx;
$data = $cell->Data;
$dAttrs = $data ? $data->attributes($ss) : null;
$val = $data ? (string)$data : '';
$cells[$idx] = $val;
$colIdx = $idx + 1;
}
if ($rowIdx === 0) {
$headers = $cells;
} else {
$rows[] = ['headers' => $headers, 'values' => $cells];
}
$rowIdx++;
}
return ['headers' => array_values($headers), 'rows' => $rows];
}
function parseUploadedFile(string $filePath, string $ext): array {
$ext = strtolower($ext);
if ($ext === 'csv') return parseCSVFile($filePath);
if ($ext === 'xls' || $ext === 'xml') return parseExcelXML($filePath);
if ($ext === 'xlsx') {

if (class_exists('ZipArchive')) {
$zip = new ZipArchive();
if ($zip->open($filePath) === true) {
$sheet = $zip->getFromName('xl/worksheets/sheet1.xml');
$shared = $zip->getFromName('xl/sharedStrings.xml');
$zip->close();
if ($sheet) {
$strings = [];
if ($shared) {
$sx = @simplexml_load_string($shared);
if ($sx) {
$ns = $sx->getNamespaces(true);
foreach ($sx->children($ns[''] ?? '')->si as $si) {
$strings[] = (string)($si->children($ns[''] ?? '')->t);
}
}
}
$sxml = @simplexml_load_string($sheet);
if ($sxml) {
$ns = $sxml->getNamespaces(true);
$rows = [];
$headers = [];
$rowIdx = 0;
foreach ($sxml->children($ns[''] ?? '')->sheetData->row as $row) {
$cells = [];
foreach ($row->children($ns[''] ?? '')->c as $cell) {
$attrs = $cell->attributes();
$ref = (string)$attrs['r'];
$col = preg_replace('/\d/', '', $ref);
$colIdx = columnToIndex($col);
$type = (string)$attrs['t'];
$val = (string)$cell->v;
if ($type === 's' && isset($strings[(int)$val])) {
$val = $strings[(int)$val];
}
$cells[$colIdx] = $val;
}
if ($rowIdx === 0) { $headers = $cells; }
else { $rows[] = ['headers' => $headers, 'values' => $cells]; }
$rowIdx++;
}
return ['headers' => array_values($headers), 'rows' => $rows];
}
}
$zip->close();
}
}
return ['headers' => [], 'rows' => [], 'error' => 'قادر به خواندن فایل xlsx نیست (ZipArchive لازم است)'];
}
return ['headers' => [], 'rows' => [], 'error' => 'فرمت پشتیبانی نمی‌شود'];
}
function columnToIndex(string $col): int {
$idx = 0;
for ($i = 0; $i < strlen($col); $i++) {
$idx = $idx * 26 + (ord($col[$i]) - ord('A') + 1);
}
return $idx - 1;
}
function wooReq(string $u, string $ck, string $cs, string $m, string $ep, $d=null, int $timeout=60): array {
$url = rtrim($u,'/').'/wp-json/wc/v3/'.ltrim($ep,'/');$timeout=max(5,min(120,$timeout));
$traceReq=['layer'=>'http_actual','request'=>['destination'=>'woocommerce','method'=>$m,'endpoint'=>'wc/v3/'.ltrim($ep,'/'),'payload'=>function_exists('matrixFixTraceSanitize')?matrixFixTraceSanitize($d):$d]];
$ch=curl_init($url);
curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>1,CURLOPT_FOLLOWLOCATION=>1,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>$timeout,CURLOPT_SSL_VERIFYPEER=>0,CURLOPT_SSL_VERIFYHOST=>0,CURLOPT_USERPWD=>"$ck:$cs",CURLOPT_HTTPHEADER=>['Content-Type: application/json','Accept: application/json'],CURLOPT_CUSTOMREQUEST=>$m]);
if($d!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($d,JSON_UNESCAPED_UNICODE));
$b=curl_exec($ch);$e=curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);
$out=['ok'=>$code>=200&&$code<300,'code'=>$code,'error'=>$e,'body'=>@json_decode($b,true),'raw'=>$b];
if(!empty($GLOBALS['S4_MATRIX_ROW_TRACE_ACTIVE'])){$traceReq['at']=microtime(true);$traceReq['response']=function_exists('matrixFixTraceSanitize')?matrixFixTraceSanitize($out):$out;$GLOBALS['S4_MATRIX_ROW_TRACE'][]=$traceReq;}
return $out;
}

/**
 * v10.82: حالت همگام‌سازی ووکامرس
 *   sync_mode: api | direct
 *   sync_fallback: api_then_direct | direct_then_api | none
 */
function wooSyncMode(?array $w = null): string {
    $w = $w ?? ((loadConnections()['woocommerce'] ?? []) ?: []);
    $m = strtolower(trim((string)($w['sync_mode'] ?? 'api')));
    return in_array($m, ['api', 'direct'], true) ? $m : 'api';
}
function wooSyncFallback(?array $w = null): string {
    $w = $w ?? ((loadConnections()['woocommerce'] ?? []) ?: []);
    $f = strtolower(trim((string)($w['sync_fallback'] ?? 'api_then_direct')));
    $ok = ['api_then_direct', 'direct_then_api', 'none', 'api', 'direct'];
    if (!in_array($f, $ok, true)) $f = 'api_then_direct';
    // aliases
    if ($f === 'api') $f = 'api_then_direct';
    if ($f === 'direct') $f = 'direct_then_api';
    return $f;
}
/** آیا همگام مستقیم (CRUD وردپرس/ووکامرس) در این پردازه ممکن است؟ */
function wooDirectAvailable(): bool {
    return class_exists('WooCommerce')
        || class_exists('WC_Product_Simple')
        || function_exists('wc_get_product');
}

/**
 * v10.99: تشخیص محیط وردپرس/ووکامرس برای تست و راهنما.
 * @return array{in_wp:bool,has_wc:bool,wc_version:string,php:string,hints:list<string>,flags:array}
 */
function wooEnvProbe(): array {
    $hints = [];
    $inWp = defined('ABSPATH') || defined('WPINC') || class_exists('WP_Query') || function_exists('get_option');
    $hasWc = wooDirectAvailable();
    $wcVer = '';
    if (defined('WC_VERSION')) $wcVer = (string)WC_VERSION;
    elseif (function_exists('WC') && is_object(WC()) && !empty(WC()->version)) $wcVer = (string)WC()->version;
    elseif (class_exists('WooCommerce') && isset(WooCommerce::$instance) && is_object(WooCommerce::$instance) && !empty(WooCommerce::$instance->version)) {
        $wcVer = (string)WooCommerce::$instance->version;
    }
    $flags = [
        'ABSPATH' => defined('ABSPATH'),
        'WooCommerce' => class_exists('WooCommerce'),
        'WC_Product_Simple' => class_exists('WC_Product_Simple'),
        'wc_get_product' => function_exists('wc_get_product'),
        'WP_Query' => class_exists('WP_Query'),
        'media_sideload_image' => function_exists('media_sideload_image'),
    ];
    if (!$inWp) {
        $hints[] = 'این فایل خارج از وردپرس اجرا می‌شود — همگام «مستقیم» فقط وقتی اسکرپر داخل همان سایت ووکامرس (افزونه/embed ادمین) لود شود کار می‌کند.';
        $hints[] = 'از پنل ادمین وردپرس → اسکرپر → «فعال‌سازی اتصال مستقیم» استفاده کنید یا حالت API با Key/Secret بگذارید.';
    } elseif (!$hasWc) {
        $hints[] = 'وردپرس لود است ولی ووکامرس یافت نشد — افزونه WooCommerce را نصب و فعال کنید.';
    } else {
        $hints[] = 'ووکامرس در همین پردازه در دسترس است — همگام مستقیم باید کار کند.';
    }
    return [
        'in_wp' => $inWp,
        'has_wc' => $hasWc,
        'wc_version' => $wcVer,
        'php' => PHP_VERSION,
        'sapi' => PHP_SAPI,
        'hints' => $hints,
        'flags' => $flags,
    ];
}

/**
 * v10.99: تست اتصال ووکامرس — API و/یا مستقیم با جزئیات خطا.
 * @param array $opts store_url, consumer_key, consumer_secret, mode=auto|api|direct|both
 * @return array
 */
function wooTestConnection(array $opts = []): array {
    $url = rtrim(trim((string)($opts['store_url'] ?? '')), '/');
    $ck  = trim((string)($opts['consumer_key'] ?? ''));
    $cs  = trim((string)($opts['consumer_secret'] ?? ''));
    $mode = strtolower(trim((string)($opts['mode'] ?? 'both')));
    if (!in_array($mode, ['auto', 'api', 'direct', 'both'], true)) $mode = 'both';

    $env = wooEnvProbe();
    $out = [
        'ok' => false,
        'message' => '',
        'mode_requested' => $mode,
        'env' => $env,
        'api' => null,
        'direct' => null,
        'attempts' => [],
        'hints' => $env['hints'],
    ];

    $doApi = in_array($mode, ['api', 'both', 'auto'], true);
    $doDirect = in_array($mode, ['direct', 'both', 'auto'], true);
    if ($mode === 'auto') {
        /* اگر مستقیم آماده است اولویت با آن + API در صورت کلید */
        $doDirect = true;
        $doApi = ($ck !== '' && $cs !== '') || !$env['has_wc'];
    }

    /* ---- API REST ---- */
    if ($doApi) {
        $api = [
            'ok' => false, 'via' => 'api', 'http_code' => 0, 'curl_error' => '',
            'message' => '', 'detail' => '', 'version' => '', 'url' => '',
            'steps' => [],
        ];
        if ($url === '') {
            $api['message'] = 'آدرس فروشگاه خالی است';
            $api['detail'] = 'store_url الزامی است (مثلاً https://shop.example.com)';
            $api['steps'][] = ['step' => 'validate', 'ok' => false, 'info' => 'URL خالی'];
        } elseif ($ck === '' || $cs === '') {
            $api['message'] = 'Consumer Key یا Secret خالی است';
            $api['detail'] = 'در ووکامرس: ووکامرس ← تنظیمات ← پیشرفته ← REST API ← افزودن کلید';
            $api['steps'][] = ['step' => 'validate', 'ok' => false, 'info' => 'کلید ناقص'];
        } else {
            $api['steps'][] = ['step' => 'validate', 'ok' => true, 'info' => 'URL و کلیدها پر است'];
            $ep = 'system_status';
            $full = $url . '/wp-json/wc/v3/' . $ep;
            $api['url'] = $full;
            $t0 = microtime(true);
            $r = wooReq($url, $ck, $cs, 'GET', $ep);
            $ms = (int)round((microtime(true) - $t0) * 1000);
            $api['http_code'] = (int)($r['code'] ?? 0);
            $api['curl_error'] = (string)($r['error'] ?? '');
            $api['latency_ms'] = $ms;
            $raw = (string)($r['raw'] ?? '');
            $body = is_array($r['body'] ?? null) ? $r['body'] : null;

            if (!empty($r['ok']) && is_array($body)) {
                $envB = is_array($body['environment'] ?? null) ? $body['environment'] : [];
                $api['ok'] = true;
                $api['version'] = (string)($envB['woocommerce_version'] ?? ($body['settings']['version'] ?? '?'));
                $api['message'] = 'REST API متصل شد';
                $api['detail'] = 'HTTP ' . $api['http_code'] . ' · ' . $ms . 'ms · WC ' . $api['version'];
                if (!empty($envB['home_url'])) $api['home_url'] = $envB['home_url'];
                if (!empty($envB['site_url'])) $api['site_url'] = $envB['site_url'];
                $api['steps'][] = ['step' => 'system_status', 'ok' => true, 'info' => $api['detail']];
                /* products count sample */
                $t1 = microtime(true);
                $rp = wooReq($url, $ck, $cs, 'GET', 'products?per_page=1');
                $api['products_probe'] = [
                    'ok' => !empty($rp['ok']),
                    'http_code' => (int)($rp['code'] ?? 0),
                    'latency_ms' => (int)round((microtime(true) - $t1) * 1000),
                ];
                $api['steps'][] = ['step' => 'products', 'ok' => !empty($rp['ok']), 'info' => 'HTTP ' . (int)($rp['code'] ?? 0)];
            } else {
                $code = (int)($r['code'] ?? 0);
                $cerr = (string)($r['error'] ?? '');
                $msgBody = '';
                if (is_array($body)) {
                    $msgBody = (string)($body['message'] ?? $body['code'] ?? '');
                    if ($msgBody === '' && !empty($body['data']['status'])) $msgBody = 'status ' . $body['data']['status'];
                } elseif ($raw !== '') {
                    $msgBody = mb_substr(trim(strip_tags($raw)), 0, 180);
                }
                $api['ok'] = false;
                if ($cerr !== '' && $code === 0) {
                    $api['message'] = 'خطای شبکه/cURL';
                    $api['detail'] = $cerr;
                    if (stripos($cerr, 'resolve') !== false) $api['hint'] = 'DNS: دامنه resolve نشد — آدرس را چک کنید یا از اتصال غیرمستقیم هاست استفاده کنید.';
                    elseif (stripos($cerr, 'timed out') !== false) $api['hint'] = 'تایم‌اوت: فایروال هاست یا بلاک IP مقصد.';
                    elseif (stripos($cerr, 'SSL') !== false) $api['hint'] = 'مشکل گواهی SSL — روی بسیاری هاست‌ها CURLOPT_SSL_VERIFYPEER خاموش است؛ اگر باز خطا دیدید گواهی سایت را بررسی کنید.';
                } elseif ($code === 401 || $code === 403) {
                    $api['message'] = 'احراز هویت ناموفق (کلید اشتباه یا بدون دسترسی)';
                    $api['detail'] = 'HTTP ' . $code . ($msgBody !== '' ? (' — ' . $msgBody) : '');
                    $api['hint'] = 'کلید را با دسترسی Read/Write بسازید؛ Permalink وردپرس روی «نام نوشته» باشد؛ افزونه امنیتی REST را بلاک نکند.';
                } elseif ($code === 404) {
                    $api['message'] = 'endpoint ووکامرس پیدا نشد (404)';
                    $api['detail'] = $full . ($msgBody !== '' ? (' — ' . $msgBody) : '');
                    $api['hint'] = 'ووکامرس فعال است؟ پیوند یکتا را یک‌بار ذخیره کنید (تنظیمات ← پیوندهای یکتا). مسیر باید /wp-json/wc/v3/ باشد.';
                } elseif ($code >= 500) {
                    $api['message'] = 'خطای سرور مقصد';
                    $api['detail'] = 'HTTP ' . $code . ($msgBody !== '' ? (' — ' . $msgBody) : '');
                } elseif ($code === 0) {
                    $api['message'] = 'پاسخی از سرور نیامد';
                    $api['detail'] = $cerr !== '' ? $cerr : 'code=0';
                } else {
                    $api['message'] = 'پاسخ ناموفق';
                    $api['detail'] = 'HTTP ' . $code . ($msgBody !== '' ? (' — ' . $msgBody) : ($cerr ?: ''));
                }
                $api['steps'][] = ['step' => 'system_status', 'ok' => false, 'info' => $api['detail']];
                $api['raw_preview'] = mb_substr($raw, 0, 240);
            }
        }
        $out['api'] = $api;
        $out['attempts'][] = $api;
    }

    /* ---- Direct CRUD ---- */
    if ($doDirect) {
        $dir = [
            'ok' => false, 'via' => 'direct', 'message' => '', 'detail' => '',
            'version' => $env['wc_version'], 'steps' => [], 'product_id' => 0,
        ];
        $dir['steps'][] = ['step' => 'env', 'ok' => $env['in_wp'], 'info' => $env['in_wp'] ? 'داخل وردپرس' : 'خارج از وردپرس'];
        if (!$env['in_wp']) {
            $dir['message'] = 'همگام مستقیم اینجا در دسترس نیست';
            $dir['detail'] = 'scraper4.php به‌صورت standalone اجرا می‌شود و کلاس‌های WC لود نیستند.';
            $dir['hint'] = 'اسکرپر را از داخل افزونه وردپرس (منوی ادمین «پنل اسکرپر») باز کنید، یا دکمه «فعال‌سازی اتصال مستقیم از ادمین» را بزنید.';
            $dir['steps'][] = ['step' => 'wc_load', 'ok' => false, 'info' => 'WooCommerce class missing'];
        } elseif (!$env['has_wc']) {
            $dir['message'] = 'ووکامرس فعال نیست';
            $dir['detail'] = 'کلاس WooCommerce / wc_get_product یافت نشد';
            $dir['hint'] = 'افزونه WooCommerce را نصب و فعال کنید.';
            $dir['steps'][] = ['step' => 'wc_load', 'ok' => false, 'info' => implode(', ', array_keys(array_filter($env['flags'])))];
        } else {
            $dir['steps'][] = ['step' => 'wc_load', 'ok' => true, 'info' => 'WC ' . ($env['wc_version'] ?: '?')];
            try {
                /* شمارش محصولات */
                $count = 0;
                if (function_exists('wp_count_posts')) {
                    $c = wp_count_posts('product');
                    if (is_object($c)) $count = (int)($c->publish ?? 0) + (int)($c->draft ?? 0);
                }
                $dir['product_count_approx'] = $count;
                $dir['steps'][] = ['step' => 'count', 'ok' => true, 'info' => '≈' . $count . ' محصول'];

                /* upsert آزمایشی خیلی سبک — draft با sku یکتا سپس حذف */
                $sku = 'amphp-ping-' . substr(md5((string)microtime(true)), 0, 8);
                $wp = [
                    'name' => 'AMPHP اتصال‌آزمایشی (حذف می‌شود)',
                    'type' => 'simple',
                    'status' => 'draft',
                    'sku' => $sku,
                    'regular_price' => '1000',
                    'description' => 'تست اتصال مستقیم اسکرپر — خودکار حذف می‌شود',
                    'short_description' => 'تست',
                    'manage_stock' => false,
                    'stock_status' => 'instock',
                ];
                $t0 = microtime(true);
                $r = wooDirectUpsert($wp, null, 'amphp_conn_test');
                $ms = (int)round((microtime(true) - $t0) * 1000);
                $dir['latency_ms'] = $ms;
                if (!empty($r['ok']) && !empty($r['body']['id'])) {
                    $pid = (int)$r['body']['id'];
                    $dir['product_id'] = $pid;
                    $dir['steps'][] = ['step' => 'create_draft', 'ok' => true, 'info' => 'product #' . $pid . ' · ' . $ms . 'ms'];
                    /* cleanup */
                    $delOk = false;
                    if (function_exists('wp_delete_post')) {
                        $del = wp_delete_post($pid, true);
                        $delOk = !empty($del);
                    } elseif (function_exists('wp_trash_post')) {
                        $delOk = (bool)wp_trash_post($pid);
                    }
                    $dir['steps'][] = ['step' => 'cleanup', 'ok' => $delOk, 'info' => $delOk ? 'پیش‌نویس حذف شد' : 'حذف نشد — دستی پاک کنید #' . $pid];
                    $dir['ok'] = true;
                    $dir['message'] = 'اتصال مستقیم موفق';
                    $dir['detail'] = 'ساخت draft و ' . ($delOk ? 'حذف' : 'نگه‌داری') . ' محصول آزمایشی · WC ' . ($env['wc_version'] ?: '?') . ' · ' . $ms . 'ms';
                } else {
                    $dir['ok'] = false;
                    $dir['message'] = 'ساخت محصول آزمایشی ناموفق';
                    $dir['detail'] = (string)($r['error'] ?? 'unknown') . ' · code ' . (int)($r['code'] ?? 0);
                    $dir['hint'] = 'کاربر PHP باید capability مدیریت محصول داشته باشد؛ اگر CLI/cron است ممکن است caps کم باشد.';
                    $dir['steps'][] = ['step' => 'create_draft', 'ok' => false, 'info' => $dir['detail']];
                }
            } catch (Throwable $e) {
                $dir['ok'] = false;
                $dir['message'] = 'استثنای PHP در تست مستقیم';
                $dir['detail'] = $e->getMessage();
                $dir['steps'][] = ['step' => 'exception', 'ok' => false, 'info' => $e->getMessage()];
            }
        }
        $out['direct'] = $dir;
        $out['attempts'][] = $dir;
    }

    $apiOk = is_array($out['api']) && !empty($out['api']['ok']);
    $dirOk = is_array($out['direct']) && !empty($out['direct']['ok']);
    $out['ok'] = $apiOk || $dirOk;
    if ($apiOk && $dirOk) $out['message'] = 'API و مستقیم هر دو سالم‌اند';
    elseif ($apiOk) $out['message'] = 'اتصال API موفق' . ($doDirect && !$dirOk ? ' — مستقیم ناموفق/غیرفعال' : '');
    elseif ($dirOk) $out['message'] = 'اتصال مستقیم موفق' . ($doApi && !$apiOk ? ' — API ناموفق/بدون کلید' : '');
    else {
        $out['message'] = 'هیچ مسیری متصل نشد';
        if (is_array($out['api']) && !empty($out['api']['message'])) $out['hints'][] = 'API: ' . $out['api']['message'];
        if (is_array($out['direct']) && !empty($out['direct']['message'])) $out['hints'][] = 'مستقیم: ' . $out['direct']['message'];
    }
    if ($apiOk && !empty($out['api']['version'])) $out['version'] = $out['api']['version'];
    elseif ($dirOk && !empty($out['direct']['version'])) $out['version'] = $out['direct']['version'];

    return $out;
}

/**
 * ترتیب تلاش: primary سپس fallback (در صورت نیاز).
 * @return list<string> e.g. ['direct','api']
 */
function wooSyncAttemptOrder(?array $w = null): array {
    $mode = wooSyncMode($w);
    $fb = wooSyncFallback($w);
    $order = [$mode];
    if ($fb === 'none') return $order;
    if ($mode === 'api' && ($fb === 'api_then_direct' || $fb === 'direct_then_api')) {
        $order[] = 'direct';
    } elseif ($mode === 'direct' && ($fb === 'direct_then_api' || $fb === 'api_then_direct')) {
        $order[] = 'api';
    }
    // unique preserve order
    $out = [];
    foreach ($order as $x) {
        if ($x === 'direct' && !wooDirectAvailable()) continue;
        if (!in_array($x, $out, true)) $out[] = $x;
    }
    if (!$out) $out = ['api'];
    return $out;
}

/**
 * ساخت/آپدیت محصول با CRUD مستقیم ووکامرس (بدون REST).
 * @return array{ok:bool,code?:int,error?:string,body?:array,via?:string,raw?:string}
 */
function wooDirectUpsert(array $wp, ?int $existingId = null, string $productKey = ''): array {
    if (!wooDirectAvailable()) {
        return ['ok' => false, 'code' => 0, 'error' => 'ووکامرس در همین PHP لود نیست — همگام مستقیم ممکن نیست', 'via' => 'direct'];
    }
    try {
        if (!function_exists('wc_get_product') && !class_exists('WC_Product_Simple')) {
            return ['ok' => false, 'code' => 0, 'error' => 'WC_Product در دسترس نیست', 'via' => 'direct'];
        }
        $product = null;
        $isUpdate = false;
        if ($existingId && $existingId > 0 && function_exists('wc_get_product')) {
            $product = wc_get_product($existingId);
            if ($product) $isUpdate = true;
        }
        if (!$product && $productKey !== '' && class_exists('WP_Query')) {
            // meta lookup
            $q = new WP_Query([
                'post_type' => 'product', 'post_status' => 'any', 'posts_per_page' => 1,
                'fields' => 'ids', 'no_found_rows' => true,
                'meta_query' => [['key' => '_amphp_product_key', 'value' => $productKey]],
            ]);
            if (!empty($q->posts[0])) {
                $product = wc_get_product((int)$q->posts[0]);
                if ($product) { $isUpdate = true; $existingId = (int)$q->posts[0]; }
            }
            wp_reset_postdata();
        }
        if (!$product) {
            if (!empty($wp['sku']) && function_exists('wc_get_product_id_by_sku')) {
                $sid = (int)wc_get_product_id_by_sku((string)$wp['sku']);
                if ($sid > 0) {
                    $product = wc_get_product($sid);
                    if ($product) { $isUpdate = true; $existingId = $sid; }
                }
            }
        }
        if (!$product) {
            if (class_exists('WC_Product_Variable') && (($wp['type'] ?? '') === 'variable')) {
                $product = new WC_Product_Variable();
            } else {
                $product = class_exists('WC_Product_Simple') ? new WC_Product_Simple() : null;
            }
            if (!$product) {
                return ['ok' => false, 'code' => 0, 'error' => 'نمی‌توان WC_Product ساخت', 'via' => 'direct'];
            }
        }

        if (isset($wp['name'])) $product->set_name((string)$wp['name']);
        if (isset($wp['status'])) $product->set_status((string)$wp['status']);
        if (isset($wp['description'])) $product->set_description((string)$wp['description']);
        if (isset($wp['short_description'])) $product->set_short_description((string)$wp['short_description']);
        if (isset($wp['sku']) && $wp['sku'] !== '') {
            try { $product->set_sku((string)$wp['sku']); } catch (Throwable $e) { /* sku conflict */ }
        }
        if (isset($wp['regular_price'])) $product->set_regular_price((string)$wp['regular_price']);
        if (isset($wp['sale_price'])) $product->set_sale_price((string)$wp['sale_price']);
        if (array_key_exists('manage_stock', $wp)) $product->set_manage_stock(!empty($wp['manage_stock']));
        if (isset($wp['stock_quantity'])) $product->set_stock_quantity((int)$wp['stock_quantity']);
        if (isset($wp['stock_status'])) $product->set_stock_status((string)$wp['stock_status']);
        elseif (!empty($wp['manage_stock'])) $product->set_stock_status(((int)($wp['stock_quantity'] ?? 0) > 0) ? 'instock' : 'outofstock');
        else $product->set_stock_status('instock');

        if (!empty($wp['categories']) && is_array($wp['categories'])) {
            $ids = [];
            foreach ($wp['categories'] as $c) {
                if (is_array($c) && !empty($c['id'])) $ids[] = (int)$c['id'];
                elseif (is_numeric($c)) $ids[] = (int)$c;
            }
            if ($ids) $product->set_category_ids($ids);
        }

        // images: [{id: N}] or [{src: url}]
        if (!empty($wp['images']) && is_array($wp['images'])) {
            $imgIds = [];
            foreach ($wp['images'] as $im) {
                if (is_array($im) && !empty($im['id'])) $imgIds[] = (int)$im['id'];
                elseif (is_array($im) && !empty($im['src'])) {
                    $aid = wooDirectSideloadImage((string)$im['src'], (string)($wp['name'] ?? 'product'));
                    if ($aid > 0) $imgIds[] = $aid;
                }
            }
            if ($imgIds) {
                $product->set_image_id($imgIds[0]);
                if (count($imgIds) > 1) $product->set_gallery_image_ids(array_slice($imgIds, 1));
            }
        }

        if (!empty($wp['attributes']) && is_array($wp['attributes']) && method_exists($product, 'set_attributes')) {
            // leave complex attrs to API path if needed — best-effort skip
        }

        $id = $product->save();
        if (!$id || is_wp_error($id)) {
            $err = is_wp_error($id) ? $id->get_error_message() : 'save failed';
            return ['ok' => false, 'code' => 500, 'error' => $err, 'via' => 'direct'];
        }
        $id = (int)$id;
        if ($productKey !== '') {
            update_post_meta($id, '_amphp_product_key', $productKey);
        }
        update_post_meta($id, '_amphp_sync_via', 'direct');
        $body = ['id' => $id, 'name' => $product->get_name(), 'permalink' => $product->get_permalink()];
        return ['ok' => true, 'code' => $isUpdate ? 200 : 201, 'body' => $body, 'via' => 'direct', 'updated' => $isUpdate];
    } catch (Throwable $e) {
        return ['ok' => false, 'code' => 500, 'error' => $e->getMessage(), 'via' => 'direct'];
    }
}

/** sideload تصویر خارجی → attachment id */
function wooDirectSideloadImage(string $url, string $title = ''): int {
    if ($url === '' || !filter_var($url, FILTER_VALIDATE_URL)) return 0;
    if (!function_exists('media_sideload_image')) {
        if (!defined('ABSPATH')) return 0;
        @require_once ABSPATH . 'wp-admin/includes/media.php';
        @require_once ABSPATH . 'wp-admin/includes/file.php';
        @require_once ABSPATH . 'wp-admin/includes/image.php';
    }
    if (!function_exists('media_sideload_image')) return 0;
    try {
        $att = media_sideload_image($url, 0, $title !== '' ? $title : null, 'id');
        if (is_wp_error($att)) return 0;
        return (int)$att;
    } catch (Throwable $e) {
        return 0;
    }
}

/**
 * پیدا کردن محصول موجود: اول meta/کلید، بعد API search (اگر لازم).
 */
function wooFindExistingSmart(array $w, string $title, string $suffix = '', string $productKey = ''): ?array {
    if ($productKey !== '' && wooDirectAvailable() && class_exists('WP_Query') && class_exists('WooCommerce')) {
        try {
            $q = new WP_Query([
                'post_type' => 'product', 'post_status' => 'any', 'posts_per_page' => 1,
                'fields' => 'ids', 'no_found_rows' => true,
                'meta_query' => [['key' => '_amphp_product_key', 'value' => $productKey]],
            ]);
            if (!empty($q->posts[0])) {
                $pid = (int)$q->posts[0];
                wp_reset_postdata();
                return ['id' => $pid, 'name' => get_the_title($pid), 'via' => 'direct_meta'];
            }
            wp_reset_postdata();
        } catch (Throwable $e) {}
    }
    if (function_exists('wooFindExisting')) {
        $ex = wooFindExisting($w, $title, $suffix, $productKey);
        if (is_array($ex) && !empty($ex['id'])) return $ex;
    }
    return null;
}

/**
 * یک درخواست create/update با ترتیب sync_mode + fallback.
 * $wp = payload شبیه REST
 */
function wooUpsertWithMode(array $w, array $wp, ?array $existing = null, string $productKey = ''): array {
    $attempts = wooSyncAttemptOrder($w);
    $last = ['ok' => false, 'error' => 'no attempt', 'via' => ''];
    $exId = $existing ? (int)($existing['id'] ?? 0) : 0;
    foreach ($attempts as $via) {
        if ($via === 'direct') {
            $r = wooDirectUpsert($wp, $exId > 0 ? $exId : null, $productKey);
            $r['attempt'] = $via;
            if (!empty($r['ok'])) return $r;
            $last = $r;
            continue;
        }
        // API
        $store = (string)($w['store_url'] ?? '');
        $ck = (string)($w['consumer_key'] ?? '');
        $cs = (string)($w['consumer_secret'] ?? '');
        if ($store === '' || $ck === '' || $cs === '') {
            $last = ['ok' => false, 'error' => 'تنظیمات API ووکامرس ناقص', 'via' => 'api'];
            continue;
        }
        if ($exId > 0) {
            $r = wooReq($store, $ck, $cs, 'PUT', 'products/' . $exId, $wp);
        } else {
            $r = wooReq($store, $ck, $cs, 'POST', 'products', $wp);
        }
        $r['via'] = 'api';
        $r['attempt'] = 'api';
        if (!empty($r['ok'])) {
            // stamp meta if direct available
            $newId = (int)($r['body']['id'] ?? 0);
            if ($newId > 0 && $productKey !== '' && function_exists('update_post_meta') && wooDirectAvailable()) {
                try { update_post_meta($newId, '_amphp_product_key', $productKey); } catch (Throwable $e) {}
            }
            return $r;
        }
        $last = $r;
    }
    return $last;
}


/* =====================================================================
 *  v8.61: راه‌های عبور برای اتصال به سرویس‌های هوش مصنوعی
 *
 *  سرور داخل ایران است و مقصدهای خارجی یا با IP سرور بسته‌اند یا اصلاً
 *  DNS جواب نمی‌دهد. چند راه مستقل فراهم شده تا کاربر هرکدام را که روی
 *  سرورش کار می‌کند انتخاب کند:
 *
 *   direct     — بدون تغییر (پیش‌فرض؛ اگر سرور آزاد باشد)
 *   dns        — دور زدن DNS مسموم: نام دامنه همان می‌ماند ولی IP را
 *                خودمان می‌دهیم (CURLOPT_RESOLVE). گواهی SSL هم درست
 *                بررسی می‌شود چون نام میزبان عوض نشده.
 *   doh        — IP را از DNS-over-HTTPS (کلادفلر/گوگل) می‌گیریم و بعد
 *                مثل حالت dns وصل می‌شویم. برای وقتی DNS محلی خراب است.
 *   worker     — یک Cloudflare Worker (یا هر پروکسی معکوس) که خودتان
 *                بالا می‌آورید و درخواست را به مقصد اصلی می‌رساند.
 *   gateway    — سرویس واسط داخلی سازگار با OpenAI (مثل درگاه‌های ایرانی)
 *   proxy      — پروکسی HTTP یا SOCKS5 که خودتان دارید
 *
 *  ⚠️ هیچ آدرس یا کلیدی از پیش داخل کد نیست؛ همه را کاربر وارد می‌کند.
 * ===================================================================== */

/** تنظیمات عبور را با مقادیر پیش‌فرض برمی‌گرداند */
function aiNetCfg(?array $cn = null): array {
    if ($cn === null) $cn = loadConnections();
    $n = (array)($cn['ai_net'] ?? []);
    return [
        'mode'        => (string)($n['mode'] ?? 'direct'),
        'resolve_ip'  => trim((string)($n['resolve_ip'] ?? '')),
        'doh_url'     => trim((string)($n['doh_url'] ?? 'https://cloudflare-dns.com/dns-query')),
        'worker_url'  => trim((string)($n['worker_url'] ?? '')),
        'proxy'       => trim((string)($n['proxy'] ?? '')),
        'proxy_type'  => (string)($n['proxy_type'] ?? 'http'),
        'proxy_auth'  => trim((string)($n['proxy_auth'] ?? '')),
        'timeout'     => max(5, min(120, (int)($n['timeout'] ?? 25))),
        'ipv4'        => !isset($n['ipv4']) || !empty($n['ipv4']),
        'fallback'    => !empty($n['fallback']),
    ];
}

/**
 * IP یک دامنه را از DNS-over-HTTPS می‌گیرد.
 * چرا: وقتی DNS محلی پاسخ جعلی می‌دهد، این مسیر رمزگذاری‌شده است و
 * فیلترشکن هم لازم ندارد چون خودِ کلادفلر/گوگل از ایران در دسترس‌اند.
 */
/* =====================================================================
 *  v9.99: حافظهٔ مشترکِ DoH — IPهای سالم، IPهای «سوخته» و شکست‌های اخیر.
 *
 *  گزارش تست کاربر: برای huggingface و cerebras همهٔ مدل‌ها پشت‌سرهم
 *  «Connection timed out after 15002 ms» روی doh(65.8.131.16) گرفتند.
 *  علت: aiDohResolve فقط اولین رکورد A را می‌گرفت و آن را تا پایانِ
 *  پردازه کش می‌کرد؛ اگر آن IP بی‌ربط بود، هر ۲۶ مدل یکی‌یکی ۱۵ ثانیه
 *  می‌سوختند. حالا:
 *    • همهٔ رکوردهای A نگه داشته می‌شوند (نه فقط اولی)
 *    • IPی که به اتصال نرسید «سوخته» علامت می‌خورد و دیگر برنمی‌گردد
 *    • اگر خودِ DoH پاسخ نداد، ۹۰ ثانیه منفی-کش می‌شود تا زنجیرهٔ
 *      تایم‌اوت برای بقیهٔ مدل‌های همان ارائه‌دهنده تکرار نشود
 *    • اگر یک اندپوینتِ DoH خراب بود، اندپوینت بعدی امتحان می‌شود
 * ===================================================================== */
function &aiDohStore(): array {
    static $s = ['ips' => [], 'bad' => [], 'fail' => []];
    return $s;
}
/** یک IP را برای این میزبان «سوخته» علامت می‌زند تا دیگر استفاده نشود */
function aiDohMarkBad(string $host, string $ip): void {
    $host = strtolower(trim($host)); $ip = trim($ip);
    if ($host === '' || $ip === '') return;
    $s = &aiDohStore();
    $s['bad'][$host][$ip] = time();
    if (!empty($s['ips'][$host])) {
        $left = [];
        foreach ($s['ips'][$host] as $x) { if ($x !== $ip) $left[] = $x; }
        if ($left) $s['ips'][$host] = $left; else unset($s['ips'][$host]);
    }
}
/** فهرست اندپوینت‌های DoH: انتخابِ کاربر، سپس کلادفلر و گوگل */
function aiDohEndpoints(string $dohUrl): array {
    $list = [];
    $dohUrl = trim($dohUrl);
    if ($dohUrl !== '') $list[] = $dohUrl;
    foreach (['https://cloudflare-dns.com/dns-query', 'https://dns.google/resolve'] as $d) {
        if (!in_array($d, $list, true)) $list[] = $d;
    }
    return $list;
}
function aiDohResolve(string $host, string $dohUrl = '', int $timeout = 10): array {
    $host = strtolower(trim($host));
    if ($host === '') return ['ok' => false, 'error' => 'میزبان خالی'];
    if (filter_var($host, FILTER_VALIDATE_IP)) return ['ok' => true, 'ip' => $host, 'cached' => false];
    $s = &aiDohStore();
    if (!empty($s['ips'][$host]))
        return ['ok' => true, 'ip' => $s['ips'][$host][0], 'cached' => true, 'ips' => $s['ips'][$host]];
    /* منفی-کش: اگر همین الان DoH برای این میزبان شکست خورده، ۹۰ ثانیه
       دوباره امتحان نکن — وگرنه هر مدلِ بعدی دوباره تایم‌اوت می‌شود. */
    if (isset($s['fail'][$host]) && (time() - (int)$s['fail'][$host]['t']) < 90)
        return ['ok' => false, 'error' => (string)$s['fail'][$host]['e'], 'cachedFail' => true];
    $lastErr = '';
    foreach (aiDohEndpoints($dohUrl) as $dohEp) {
        if (aiTestStopRequested()) return ['ok' => false, 'error' => 'stopped'];
        $r = aiDohQuery($host, $dohEp, $timeout);
        if (!empty($r['stopped'])) return ['ok' => false, 'error' => 'stopped'];
        if (!empty($r['ok'])) {
            $ips = [];
            foreach ($r['ips'] as $ip) { if (!isset($s['bad'][$host][$ip])) $ips[] = $ip; }
            if ($ips) {
                $s['ips'][$host] = $ips;
                unset($s['fail'][$host]);
                return ['ok' => true, 'ip' => $ips[0], 'cached' => false, 'ips' => $ips];
            }
            $lastErr = 'همهٔ IPهای این میزبان قبلاً ناموفق بوده‌اند';
            continue;
        }
        $lastErr = (string)$r['error'];
    }
    $s['fail'][$host] = ['t' => time(), 'e' => $lastErr !== '' ? $lastErr : 'DoH ناموفق'];
    return ['ok' => false, 'error' => (string)$s['fail'][$host]['e']];
}
/** یک پرس‌وجوی DoH به یک اندپوینت مشخص — همهٔ رکوردهای A را برمی‌گرداند */
function aiDohQuery(string $host, string $dohUrl, int $timeout = 10): array {
    $url = $dohUrl . (strpos($dohUrl, '?') === false ? '?' : '&')
         . 'name=' . urlencode($host) . '&type=A';
    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => 1,
        CURLOPT_TIMEOUT        => $timeout,
        CURLOPT_CONNECTTIMEOUT => min(10, $timeout),
        CURLOPT_HTTPHEADER     => ['Accept: application/dns-json'],
        CURLOPT_SSL_VERIFYPEER => 0,
        CURLOPT_SSL_VERIFYHOST => 0,
    ]);
    /* v9.45: خودِ درخواست DoH هم می‌تواند روی سرورِ DNSِ بسته/مسموم قفل شود
       (تا سقف $timeout ثانیه). با همین progress-callback، اگر «توقف تست
       مدل‌ها» زده شده باشد، آن هم abort می‌شود تا کل حلقهٔ تست گیر نکند. */
    curl_setopt($ch, CURLOPT_NOPROGRESS, false);
    curl_setopt($ch, CURLOPT_PROGRESSFUNCTION, function ($ch2, $dlt, $dltT, $ult, $ultT) {
        return aiTestStopRequested() ? 1 : 0;
    });
    $body = curl_exec($ch);
    $err  = curl_error($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
    curl_close($ch);
    if (aiTestStopRequested()) return ['ok' => false, 'error' => 'stopped', 'stopped' => true];   // v9.45
    if ($code !== 200) return ['ok' => false, 'error' => 'DoH پاسخ نداد (HTTP ' . $code . ') ' . $err];
    $j = json_decode((string)$body, true);
    $ips = [];
    foreach ((array)($j['Answer'] ?? []) as $a) {
        $ip = trim((string)($a['data'] ?? ''));
        if ($ip !== '' && filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)
            && !in_array($ip, $ips, true)) $ips[] = $ip;
    }
    if ($ips) return ['ok' => true, 'ips' => $ips];
    return ['ok' => false, 'error' => 'رکورد A پیدا نشد'];
}

/* v10.218: حذفِ پورت پیش‌فرض از URL هدف. بعضی Workerها وقتی آدرسِ
   مقصد به‌شکل خام داخل path برود، قطعهٔ `https:` یا `:443` را پورتِ path
   می‌خوانند و خطای «bad/invalid port» می‌دهند. پیش از هر درخواستِ AI،
   پورت‌های پیش‌فرض 80/443 از URL پاک می‌شود تا هم direct/DoH سالم بماند
   و هم Worker با URL تمیزتری کار کند. */
function aiUrlStripDefaultPort(string $url): string {
    return (string)preg_replace_callback('~^(https?)://((?:[^/@?#]+@)?)(\[[^\]]+\]|[^:/?#]+):(80|443)([/?#]|$)~i',
        function ($m) {
            $scheme = strtolower((string)$m[1]);
            $port   = (string)$m[4];
            if (($scheme === 'https' && $port === '443') || ($scheme === 'http' && $port === '80')) {
                return $m[1] . '://' . $m[2] . $m[3] . $m[5];
            }
            return $m[0];
        }, $url);
}

/* v10.218: نرمال‌سازی آدرس Worker — فاصله، slash انتهایی و پورت پیش‌فرض
   خودِ Worker حذف می‌شود. اگر کاربر فقط دامنهٔ workers.dev را چسبانده باشد،
   https:// به ابتدا اضافه می‌شود. */
function aiWorkerNormalizeUrl(string $w): string {
    $w = trim($w);
    // v10.228: فرم‌های خراب ذخیره‌شده مثل }https://worker/?url={url}
    // را قبل از اعتبارسنجی تمیز کن؛ یک کاراکتر اضافه کافی بود Worker کاملاً از مدار خارج شود.
    $w = ltrim($w, " \t\n\r\0\x0B}])>");
    if (!preg_match('~^https?://~i', $w) && preg_match('~https?://~i', $w, $m, PREG_OFFSET_CAPTURE)) {
        $pos = (int)($m[0][1] ?? 0);
        if ($pos > 0 && $pos <= 8) $w = substr($w, $pos);
    }
    if ($w === '') return '';
    if (!preg_match('~^https?://~i', $w) && preg_match('~^[a-z0-9.-]+(?:/|$|\?)~i', $w)) $w = 'https://' . $w;
    $w = aiUrlStripDefaultPort($w);
    return rtrim($w, '/');
}

/* v10.218: ساختِ URL امن برای Worker. نسخهٔ قدیمی آدرسِ کامل مقصد را خام
   به path می‌چسباند (worker/https://api...). بعضی Workerها/URL-parserها آن
   را با خطای پورت رد می‌کنند. پیش‌فرض جدید، مقصد را هم در queryِ encoded و
   هم در هدر X-Target-URL می‌فرستد. الگوهای سفارشی هم پشتیبانی می‌شوند:
     {url} یا {target}        = rawurlencode(target)
     {url.raw} یا {target.raw}= target خام (برای Workerهای legacy)
     {url.b64} یا {target.b64}= base64url(target)
 */
function aiWorkerBuildRequestUrl(string $workerUrl, string $targetUrl): array {
    $w = aiWorkerNormalizeUrl($workerUrl);
    $targetUrl = aiUrlStripDefaultPort($targetUrl);
    if ($w === '') return ['ok' => false, 'url' => '', 'style' => '', 'error' => 'آدرس Worker خالی است'];
    $enc = rawurlencode($targetUrl);
    $b64 = rtrim(strtr(base64_encode($targetUrl), '+/', '-_'), '=');
    $repl = [
        '{url}' => $enc, '{target}' => $enc,
        '{url.raw}' => $targetUrl, '{target.raw}' => $targetUrl,
        '{url.b64}' => $b64, '{target.b64}' => $b64,
    ];
    foreach ($repl as $ph => $rv) {
        if (strpos($w, $ph) !== false) {
            $built = strtr($w, $repl);
            if (!filter_var($built, FILTER_VALIDATE_URL)) return ['ok' => false, 'url' => '', 'style' => '', 'error' => 'قالب Worker پس از جایگذاری URL نامعتبر شد'];
            return ['ok' => true, 'url' => $built, 'style' => 'template', 'target' => $targetUrl];
        }
    }
    if (!filter_var($w, FILTER_VALIDATE_URL)) return ['ok' => false, 'url' => '', 'style' => '', 'error' => 'آدرس Worker نامعتبر است'];
    $sep = (strpos($w, '?') === false) ? '?' : '&';
    return ['ok' => true, 'url' => $w . $sep . 'url=' . $enc, 'style' => 'query:url', 'target' => $targetUrl];
}

/* =====================================================================
 *  v9.99: aiHttp به سه بخش شکسته شد تا همان منطق هم به‌صورت تکی و هم
 *  به‌صورت موازی (curl_multi) قابل استفاده باشد:
 *     aiHttpPrepare() → یک هندلِ curl آمادهٔ اجرا + فراداده می‌سازد
 *     aiHttpFinish()  → خروجیِ خامِ curl را به نتیجهٔ استاندارد تبدیل می‌کند
 *     aiHttp()        → همان رفتارِ قبلی (prepare ➜ exec ➜ finish)
 *  هیچ رفتاری برای مسیرهای موجود عوض نمی‌شود؛ فقط قابلِ‌اشتراک شد.
 * ===================================================================== */
function aiHttpPrepare(string $url, array $headers, ?array $payload, array $net, ?string $forceMode = null): array {
    $url = aiUrlStripDefaultPort($url);
    $mode = $forceMode ?? ($net['mode'] ?? 'direct');
    $parts = parse_url($url);
    $host  = (string)($parts['host'] ?? '');
    $reqUrl = $url;
    $extraHeaders = [];
    $via = $mode;
    $pinnedIp = '';   // v9.99: IPی که با DoH/دستی به curl تحمیل شده
    $workerStyle = '';

    if ($mode === 'worker') {
        // v10.218: مقصد را خام داخل path نگذار؛ برای جلوگیری از خطای bad port
        // در Worker/URL-parser، هدف encoded در query و نیز در هدرها فرستاده می‌شود.
        $wb = aiWorkerBuildRequestUrl((string)($net['worker_url'] ?? ''), $url);
        if (empty($wb['ok'])) {
            return ['err' => ['ok' => false, 'code' => 0, 'error' => (string)($wb['error'] ?? 'آدرس Worker نامعتبر است'), 'via' => $mode, 'mode' => $mode]];
        }
        $reqUrl = (string)$wb['url'];
        $url    = (string)($wb['target'] ?? $url);
        $workerStyle = (string)($wb['style'] ?? '');
        $tParts = parse_url($url);
        $base = (string)($tParts['scheme'] ?? 'https') . '://' . (string)($tParts['host'] ?? '');
        $tPort = isset($tParts['port']) ? (int)$tParts['port'] : 0;
        if ($tPort > 0) $base .= ':' . $tPort;
        $tPath = (string)($tParts['path'] ?? '/');
        if (isset($tParts['query']) && $tParts['query'] !== '') $tPath .= '?' . $tParts['query'];
        if ($workerStyle !== 'template') {
            $extraHeaders[] = 'X-Target-URL: ' . $url;
            $extraHeaders[] = 'X-Target-Base: ' . $base;
            $extraHeaders[] = 'X-Target-Path: ' . $tPath;
        }
        foreach ($headers as $hdrLine) {
            if (stripos($hdrLine, 'Authorization:') === 0) {
                $authVal = trim(substr($hdrLine, strlen('Authorization:')));
                if ($authVal !== '') $extraHeaders[] = 'X-Authorization: ' . $authVal;
            } elseif (stripos($hdrLine, 'x-api-key:') === 0) {
                $akVal = trim(substr($hdrLine, strlen('x-api-key:')));
                if ($akVal !== '') $extraHeaders[] = 'X-API-Key-Fwd: ' . $akVal;
            }
        }
        $via = 'worker' . ($workerStyle !== '' ? '(' . $workerStyle . ')' : '');
    } elseif ($mode === 'gateway') {
        // درگاه واسط: کاربر Base URL را مستقیم در بخش هوش مصنوعی می‌گذارد،
        // پس اینجا کاری لازم نیست جز اینکه مثل direct عمل کنیم.
        $via = 'gateway';
    }

    /* v10.444: افزودن هدرهای استاندارد User-Agent و Accept در صورت نبودن؛
       فقدان User-Agent در cURL خام باعث بلاک ۴۰۳ کلادفلر (کد 1010) روی Groq،
       OpenRouter، Together، Mistral و دروازه‌های سازگار می‌شد. */
    $hasUa = false; $hasAccept = false;
    foreach ($headers as $hl) {
        if (stripos($hl, 'User-Agent:') === 0) $hasUa = true;
        elseif (stripos($hl, 'Accept:') === 0) $hasAccept = true;
    }
    if (!$hasAccept) $extraHeaders[] = 'Accept: application/json';
    if (!$hasUa) $extraHeaders[] = 'User-Agent: Mozilla/5.0 (compatible; S4AI/10.444; +https://openapi.basalam.com)';

    $ch = curl_init($reqUrl);
    $opt = [
        CURLOPT_RETURNTRANSFER => 1,
        CURLOPT_TIMEOUT        => (int)$net['timeout'],
        CURLOPT_CONNECTTIMEOUT => min(15, (int)$net['timeout']),
        CURLOPT_HTTPHEADER     => array_merge($headers, $extraHeaders),
        CURLOPT_SSL_VERIFYPEER => 0,
        CURLOPT_SSL_VERIFYHOST => 0,
        CURLOPT_FOLLOWLOCATION => 1,
        CURLOPT_MAXREDIRS      => 3,
    ];
    if (!empty($net['ipv4']) && defined('CURL_IPRESOLVE_V4')) {
        $opt[CURLOPT_IPRESOLVE] = CURL_IPRESOLVE_V4;
    }
    if ($payload !== null) {
        $opt[CURLOPT_POST] = true;
        if (defined('CURL_REDIR_POST_ALL')) $opt[CURLOPT_POSTREDIR] = CURL_REDIR_POST_ALL;
        $opt[CURLOPT_POSTFIELDS] = json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    }

    if ($mode === 'dns' || $mode === 'doh') {
        $ip = '';
        if ($mode === 'dns') {
            $ip = (string)$net['resolve_ip'];
            if ($ip === '') { curl_close($ch); return ['err' => ['ok' => false, 'code' => 0, 'error' => 'IP دستی وارد نشده', 'via' => $mode, 'mode' => $mode]]; }
        } else {
            $r = aiDohResolve($host, (string)$net['doh_url'], min(10, (int)$net['timeout']));
            if (empty($r['ok'])) { curl_close($ch); return ['err' => ['ok' => false, 'code' => 0, 'error' => 'DoH: ' . ($r['error'] ?? '?'), 'via' => $mode, 'mode' => $mode]]; }
            $ip = (string)$r['ip'];
            $via = 'doh(' . $ip . ')';
        }
        $port = (int)($parts['port'] ?? (($parts['scheme'] ?? 'https') === 'https' ? 443 : 80));
        // نام میزبان دست‌نخورده می‌ماند، فقط مقصد TCP عوض می‌شود
        $opt[CURLOPT_RESOLVE] = [$host . ':' . $port . ':' . $ip];
        $pinnedIp = $ip;   // v9.99: اگر این IP به اتصال نرسید، «سوخته» علامتش می‌زنیم
    }

    if ($mode === 'proxy') {
        $px = (string)$net['proxy'];
        if ($px === '') { curl_close($ch); return ['err' => ['ok' => false, 'code' => 0, 'error' => 'آدرس پروکسی خالی است', 'via' => $mode, 'mode' => $mode]]; }
        $opt[CURLOPT_PROXY] = $px;
        $map = [
            'http'   => CURLPROXY_HTTP,
            'socks5' => defined('CURLPROXY_SOCKS5_HOSTNAME') ? CURLPROXY_SOCKS5_HOSTNAME : CURLPROXY_SOCKS5,
            'socks4' => defined('CURLPROXY_SOCKS4') ? CURLPROXY_SOCKS4 : CURLPROXY_HTTP,
        ];
        $opt[CURLOPT_PROXYTYPE] = $map[(string)$net['proxy_type']] ?? CURLPROXY_HTTP;
        if (!empty($net['proxy_auth'])) $opt[CURLOPT_PROXYUSERPWD] = (string)$net['proxy_auth'];
    }

    curl_setopt_array($ch, $opt);
    /* v9.43: اگر کاربر «توقف تست مدل‌ها» را زده، این درخواست شبکه را همین حالا
       قطع کن. CURLOPT_PROGRESSFUNCTION مرتباً (در طول هر انتقال) صدا زده می‌شود و
       اگر فایل توقف ساخته شده باشد، برگرداندنِ غیرصفر باعث می‌شود curl فوراً با
       خطای abort بایستد. بدون این، وقتی مدل/اندپوینت غیرقابل‌دسترس است، هر فراخوانی
       تا سقف تایم‌اوت (و چند روشِ اتصال پشت‌سرهم) بلاک می‌شود و دکمهٔ توقف تا پایانِ
       همان فراخوانی هیچ اثری ندارد. کش stat هم پاک می‌شود تا فایلِ تازه دیده شود. */
    curl_setopt($ch, CURLOPT_NOPROGRESS, false);
    curl_setopt($ch, CURLOPT_PROGRESSFUNCTION, function ($ch2, $dlt, $dltT, $ult, $ultT) {
        return aiTestStopRequested() ? 1 : 0;   // غیرصفر → abort
    });
    return ['ch' => $ch, 'mode' => $mode, 'via' => $via, 'host' => $host,
            'pinnedIp' => $pinnedIp, 'reqUrl' => $reqUrl, 'workerStyle' => $workerStyle];
}

/** خروجیِ خامِ یک هندلِ curlِ اجراشده را به نتیجهٔ استاندارد تبدیل می‌کند */
function aiHttpFinish(array $h, $raw, string $err, int $code, string $eurl): array {
    $host = (string)($h['host'] ?? '');
    $pinnedIp = (string)($h['pinnedIp'] ?? '');
    /* v9.99: اگر IP را خودمان (DoH) تحمیل کرده بودیم و اتصال اصلاً برقرار
       نشد، آن IP را «سوخته» علامت بزن تا مدل‌های بعدیِ همان ارائه‌دهنده
       دوباره ۱۵ ثانیه روی همان IP بی‌ربط نسوزند. */
    if ($pinnedIp !== '' && $code === 0 && $err !== '' && !aiTestStopRequested()) {
        $el = strtolower($err);
        if (strpos($el, 'timed out') !== false || strpos($el, 'connect') !== false
            || strpos($el, 'refused') !== false || strpos($el, 'reset') !== false
            || strpos($el, 'unreachable') !== false) {
            aiDohMarkBad($host, $pinnedIp);
        }
    }
    return ['ok' => $code >= 200 && $code < 300, 'code' => $code, 'error' => $err,
            'body' => @json_decode((string)$raw, true), 'raw' => $raw,
            'via' => (string)($h['via'] ?? ''), 'effective_url' => $eurl,
            'req_url' => (string)($h['reqUrl'] ?? ''), 'mode' => (string)($h['mode'] ?? ''),
            'worker_style' => (string)($h['workerStyle'] ?? '')];
}

/**
 * درخواست HTTP با اعمال روش عبور انتخاب‌شده.
 * خروجی: ['ok','code','body','raw','error','via','effective_url']
 */
function aiHttp(string $url, array $headers, ?array $payload, array $net, ?string $forceMode = null): array {
    $h = aiHttpPrepare($url, $headers, $payload, $net, $forceMode);
    if (isset($h['err'])) return $h['err'];
    $ch = $h['ch'];
    $raw  = curl_exec($ch);
    $err  = curl_error($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
    $eurl = (string)curl_getinfo($ch, CURLINFO_EFFECTIVE_URL);
    curl_close($ch);
    return aiHttpFinish($h, $raw, $err, $code, $eurl);
}

/* =====================================================================
 *  v9.20: چند-ارائه‌دهندهٔ هوش مصنوعی (فرمت JSON قابل درون‌ریزی)
 *
 *  تا ۹.۱۹ فقط یک «AI» با یک کلید و یک base_url وجود داشت. حالا یک
 *  فهرست از ارائه‌دهنده‌ها (provider) ذخیره می‌شود که هرکدام URL، کلید
 *  و فهرست مدل‌های خود را دارد — دقیقاً با همان فرمتی که کاربر از
 *  OpenRouter/Together/Groq/... درون‌ریزی می‌کند. تمام نقاطی که قبلاً
 *  «AI» می‌خواندند حالا از «ارائه‌دهندهٔ فعال» (active provider) می‌روند.
 * ===================================================================== */

/** فهرست ارائه‌دهنده‌ها را از دیسک می‌خواند: [id => {id,name,vendor,url,apiKey,enabled,models[]}] */
function aiProvidersLoad(): array {
    $p = [];
    if (is_file(AI_PROVIDERS_FILE)) {
        $d = json_decode((string)@file_get_contents(AI_PROVIDERS_FILE), true);
        if (is_array($d)) $p = $d;
    }
    if ($p && function_exists('aiRepairProvidersConfig') && function_exists('aiKeyStateLoad')) {
        $kst = aiKeyStateLoad();
        if (($kst['_repaired_ver'] ?? '') !== APP_VERSION) {
            $kst['_repaired_ver'] = APP_VERSION;
            aiKeyStateSave($kst);
            aiRepairProvidersConfig($p, true);
            @writeJsonFile(AI_PROVIDERS_FILE, $p);
        }
    }
    return $p;
}
/** فهرست ارائه‌دهنده‌ها را ذخیره می‌کند */
function aiProvidersSave(array $p): bool {
    return writeJsonFile(AI_PROVIDERS_FILE, $p)['ok'];
}

/* =====================================================================
 *  v10.01 (۱۵): چند کلید API برای هر ارائه‌دهنده
 *
 *  مسئله: سرویس‌های رایگان سهمیهٔ روزانه/ماهانه دارند. وقتی اعتبارِ یک
 *  کلید تمام می‌شود همهٔ مدل‌های آن ارائه‌دهنده «قرمز» می‌شوند، در حالی
 *  که کاربر معمولاً چند کلید (چند حساب) دارد. تا نسخهٔ ۱۰٫۰۰ هر
 *  ارائه‌دهنده فقط یک رشتهٔ apiKey داشت.
 *
 *  راه‌حل:
 *    ۱) هر ارائه‌دهنده آرایهٔ apiKeys[] می‌گیرد؛ فیلدِ قدیمیِ apiKey هم
 *       سرِ جایش می‌ماند (سازگاریِ عقب‌رو + برون‌ریزی/درون‌ریزیِ قدیمی)
 *       و همیشه آینهٔ «کلیدِ اولِ سالم» است.
 *    ۲) وضعیتِ سلامتِ هر کلید در فایلِ جدا (AI_KEY_STATE_FILE) می‌نشیند.
 *    ۳) هر فراخوانی، «اولین کلیدِ سالم» را برمی‌دارد؛ اگر خطای اعتبار/
 *       ریت‌لیمیت/کلیدِ نامعتبر گرفت، همان کلید علامت می‌خورد و درخواست
 *       بی‌درنگ با کلیدِ بعدی تکرار می‌شود.
 *    ۴) کلیدِ تازه هیچ سابقه‌ای ندارد ⇒ خطای کلیدِ قبلی به آن سرایت
 *       نمی‌کند؛ افزودنِ کلید حتی نتیجهٔ «اعتبار تمام شده»ی مدل‌ها را
 *       پاک می‌کند تا دوباره تست شوند.
 * ===================================================================== */

/**
 * v10.16: آیا این ارائه‌دهنده کنارِ توکن «شمارهٔ حساب» هم می‌خواهد؟
 *
 * فقط کلادفلر. تشخیص از روی آدرس است، نه شناسهٔ ثابت، چون کاربر می‌تواند
 * ارائه‌دهندهٔ دستیِ کلادفلری با هر نامی بسازد.
 */
function aiProviderNeedsAccount(array $p): bool {
    $url = strtolower(trim((string)($p['url'] ?? '')));
    if ($url === '') return (string)($p['id'] ?? '') === 'cloudflare';
    return strpos($url, '/ai/run') !== false
        || strpos($url, 'api.cloudflare.com') !== false;
}

/**
 * v10.16: پاک‌سازیِ ورودیِ شمارهٔ حساب.
 * کاربر معمولاً کلِ آدرسِ داشبورد را کپی می‌کند
 * (dash.cloudflare.com/<acct>/ai یا api.cloudflare.com/.../accounts/<acct>/...)
 * پس اگر چیزی شبیهِ آدرس بود، شناسه را از دلش بیرون می‌کشیم.
 */
function aiNormalizeAccountId(string $raw): string {
    $raw = trim($raw);
    if ($raw === '') return '';
    if (preg_match('~accounts/([0-9a-f]{16,})~i', $raw, $m)) return strtolower($m[1]);
    if (preg_match('~cloudflare\.com/([0-9a-f]{16,})~i', $raw, $m)) return strtolower($m[1]);
    if (preg_match('~^[0-9a-f]{16,}$~i', $raw)) return strtolower($raw);
    /* چیزی که نه هگز است نه آدرس: همان را برمی‌گردانیم تا خطای واقعیِ
       سرویس به کاربر نشان داده شود، نه یک «قبول شد»ِ دروغین. */
    return preg_replace('~[^0-9A-Za-z._-]~', '', $raw);
}

/** شناسهٔ کوتاه و پایدارِ یک کلید — خودِ کلید هیچ‌جا در شناسه نمی‌آید */
function aiKeyId(string $key): string {
    $key = trim($key);
    return $key === '' ? '' : substr(sha1($key), 0, 10);
}

/**
 * ارقام لاتین ⇒ فارسی.
 * توجه: strtr سه‌آرگومانی بایت‌به‌بایت کار می‌کند و برای ارقامِ چندبایتیِ
 * فارسی خروجیِ خرابِ UTF-8 می‌سازد (json_encode بعداً false برمی‌گرداند)؛
 * پس حتماً باید از نگاشتِ آرایه‌ای استفاده شود.
 */
function aiFaNum($n): string {
    return strtr((string)$n, ['0'=>'۰','1'=>'۱','2'=>'۲','3'=>'۳','4'=>'۴',
                              '5'=>'۵','6'=>'۶','7'=>'۷','8'=>'۸','9'=>'۹']);
}

/** نمایشِ ماسک‌شدهٔ کلید برای رابط کاربری */
function aiKeyPreview(string $key): string {
    $key = trim($key);
    if ($key === '') return '';
    if (mb_strlen($key) <= 10) return mb_substr($key, 0, 2) . str_repeat('•', 4);
    return mb_substr($key, 0, 5) . '…' . mb_substr($key, -4);
}

/**
 * فهرستِ نرمال‌شدهٔ کلیدهای یک ارائه‌دهنده:
 * [ ['id','key','label','enabled'], … ]
 * کلیدِ تکراری حذف می‌شود و فیلدِ قدیمیِ apiKey هم — اگر در فهرست نباشد —
 * به‌عنوان کلیدِ اول در نظر گرفته می‌شود.
 */
function aiProviderKeys(array $p): array {
    $out = []; $seen = [];
    foreach ((array)($p['apiKeys'] ?? []) as $row) {
        if (is_array($row)) {
            $k     = trim((string)($row['key'] ?? ''));
            $label = trim((string)($row['label'] ?? ''));
            $en    = ($row['enabled'] ?? true) !== false;
            $acct  = trim((string)($row['acct'] ?? ''));
        } else {
            $k = trim((string)$row); $label = ''; $en = true; $acct = '';
        }
        if ($k === '' || isset($seen[$k])) continue;
        $seen[$k] = true;
        $out[] = ['id' => aiKeyId($k), 'key' => $k, 'label' => $label,
                  'enabled' => $en, 'acct' => $acct];
    }
    $legacy = trim((string)($p['apiKey'] ?? ''));
    if ($legacy !== '' && !isset($seen[$legacy])) {
        /* v10.16: کلیدِ قدیمی شمارهٔ حسابِ جدا ندارد؛ حسابش همان است که در
           آدرسِ ارائه‌دهنده نوشته شده. acct خالی دقیقاً یعنی همین. */
        array_unshift($out, ['id' => aiKeyId($legacy), 'key' => $legacy,
                             'label' => '', 'enabled' => true, 'acct' => '']);
    }
    return $out;
}

/** آرایهٔ کلیدها را به شکلِ ذخیره‌شدنی (با apiKey آینه) روی provider می‌نشاند */
function aiProviderSetKeys(array $p, array $keys): array {
    $rows = []; $seen = [];
    foreach ($keys as $k) {
        $key = trim((string)($k['key'] ?? ''));
        if ($key === '' || isset($seen[$key])) continue;
        $seen[$key] = true;
        $rows[] = ['id'      => aiKeyId($key),
                   'key'     => $key,
                   'label'   => trim((string)($k['label'] ?? '')),
                   'enabled' => ($k['enabled'] ?? true) !== false,
                   /* v10.16: شمارهٔ حسابِ اختصاصیِ این کلید (فعلاً کلادفلر).
                      خالی = از آدرسِ خودِ ارائه‌دهنده استفاده کن. */
                   'acct'    => trim((string)($k['acct'] ?? '')),
                   'addedAt' => (int)($k['addedAt'] ?? time())];
    }
    $p['apiKeys'] = $rows;
    /* apiKey همیشه آینهٔ «اولین کلیدِ روشن» است تا کدها و فایل‌های قدیمی
       (و برون‌ریزیِ نسخه‌های پیشین) دقیقاً مثل قبل کار کنند. */
    $mirror = '';
    foreach ($rows as $r) { if ($r['enabled']) { $mirror = $r['key']; break; } }
    if ($mirror === '' && $rows) $mirror = $rows[0]['key'];
    $p['apiKey'] = $mirror;
    return $p;
}

/** وضعیتِ سلامتِ کلیدها از دیسک */
function aiKeyStateLoad(): array {
    if (!is_file(AI_KEY_STATE_FILE)) return [];
    $d = json_decode((string)@file_get_contents(AI_KEY_STATE_FILE), true);
    return is_array($d) ? $d : [];
}
function aiKeyStateSave(array $st): bool {
    return writeJsonFile(AI_KEY_STATE_FILE, $st)['ok'];
}

/**
 * سلامتِ یک کلید:
 *   blocked=true یعنی «برای درخواستِ بعدی سراغش نرو».
 *   اعتبار/اشتراک و کلیدِ نامعتبر تا وقتی کاربر پاک نکند (یا کلید دوباره
 *   موفق شود) باقی می‌ماند؛ ریت‌لیمیت فقط چند ثانیه.
 */
function aiKeyHealth(string $pid, string $kid, ?array $state = null): array {
    $st = $state === null ? aiKeyStateLoad() : $state;
    $row = $st[$pid . '|' . $kid] ?? null;
    $base = ['blocked' => false, 'kind' => '', 'label' => '', 'msg' => '', 'at' => 0,
             'fails' => 0, 'okAt' => 0, 'retryIn' => 0];
    if (!is_array($row)) return $base;
    $kind = (string)($row['kind'] ?? '');
    $at   = (int)($row['at'] ?? 0);
    $lbl  = (string)($row['label'] ?? '');
    $msg  = (string)($row['msg'] ?? '');
    /* v10.469: خطاهای سطحِ مدل (tier/plan/labs مثل Mistral tier_not_allowed) یا ۴۲۹ موقتی که لینک /billing داشته
       نباید کل کلید را «اعتبار تمام» نگه دارند؛ در خواندنِ وضعیت هم خودکار آزادشان می‌کنیم. */
    if ($kind === 'billing') {
        $chkFalseBill = strtolower($lbl . ' ' . $msg);
        if (strpos($chkFalseBill, 'subscription tier') !== false
            || strpos($chkFalseBill, 'tier_not_allowed') !== false
            || strpos($lbl, 'سطحِ اشتراک') !== false
            || strpos($lbl, 'پلن رایگان') !== false
            || strpos($lbl, 'مدل Labs') !== false
            || strpos($chkFalseBill, 'labs_not_enabled') !== false
            || strpos($chkFalseBill, 'retry in ') !== false
            || strpos($chkFalseBill, 'too many ') !== false) {
            return $base;
        }
    }
    $base['kind']  = $kind;
    $base['label'] = $lbl;
    $base['msg']   = $msg;
    $base['at']    = $at;
    $base['fails'] = (int)($row['fails'] ?? 0);
    $base['okAt']  = (int)($row['okAt'] ?? 0);
    if ($kind === 'rate') {
        $left = AI_KEY_RATE_COOLDOWN - (time() - $at);
        $base['retryIn'] = max(0, $left);
        $base['blocked'] = $left > 0;
    } elseif ($kind === 'billing' || $kind === 'auth') {
        $base['blocked'] = true;
    }
    return $base;
}

/** خطای این پاسخ «مالِ کلید» است یا نه (اعتبار / ریت‌لیمیت / کلیدِ نامعتبر) */
function aiKeyFailureKind(array $r): array {
    if (!empty($r['ok'])) return ['kind' => '', 'label' => '', 'msg' => ''];
    $code = (int)($r['code'] ?? 0);
    /* خطایی که از Worker/پروکسی آمده یا ناشی از حذف هدر Authorization در واسطه است
       ربطی به خود کلید ندارد — کلیدِ سالم را بی‌خود نسوزانیم. */
    if (!empty($r['proxy_blocked']) || !empty($r['auth_stripped_suspect'])) {
        return ['kind' => '', 'label' => '', 'msg' => ''];
    }
    $mode = (string)($r['mode'] ?? '');
    if (in_array($mode, ['worker', 'proxy'], true) && ($code === 401 || ($code === 400 && aiIsMissingAuthHeaderError($r)))) {
        return ['kind' => '', 'label' => '', 'msg' => ''];
    }
    $bill = aiBillingFailure($r);
    /* v10.469: فقط اتمام واقعی اعتبار حساب (credit) مربوط به کل کلید است؛
       خطاهای tier / plan / labs / trial مربوط به همان مدل خاص هستند، نه کل اکانت! */
    if ($bill['is']) {
        if (($bill['kind'] ?? '') === 'credit') {
            return ['kind' => 'billing', 'label' => $bill['label'], 'msg' => (string)$bill['msg']];
        }
        return ['kind' => '', 'label' => '', 'msg' => ''];
    }
    if ($code === 429) return ['kind' => 'rate',
        'label' => 'محدودیت نرخ (۴۲۹) — سهمیهٔ لحظه‌ای این کلید پر شده', 'msg' => ''];
    if ($code === 401) return ['kind' => 'auth',
        'label' => 'کلید نامعتبر است (۴۰۱) — پاکش کنید یا کلیدِ درست بگذارید', 'msg' => ''];
    return ['kind' => '', 'label' => '', 'msg' => ''];
}

/** ثبتِ خطای یک کلید */
function aiKeyMarkFail(string $pid, string $kid, string $kind, string $label = '', string $msg = ''): void {
    if ($pid === '' || $kid === '' || $kind === '') return;
    $st = aiKeyStateLoad();
    $k  = $pid . '|' . $kid;
    $prev = is_array($st[$k] ?? null) ? $st[$k] : [];
    $st[$k] = ['kind'  => $kind,
               'label' => mb_substr($label, 0, 200),
               'msg'   => mb_substr($msg, 0, 200),
               'at'    => time(),
               'fails' => (int)($prev['fails'] ?? 0) + 1,
               'okAt'  => (int)($prev['okAt'] ?? 0)];
    aiKeyStateSave($st);
}

/** کلید جواب داد ⇒ هر برچسبِ خطای قبلی پاک می‌شود */
function aiKeyMarkOk(string $pid, string $kid): void {
    if ($pid === '' || $kid === '') return;
    $st = aiKeyStateLoad();
    $k  = $pid . '|' . $kid;
    $prev = is_array($st[$k] ?? null) ? $st[$k] : [];
    if (($prev['kind'] ?? '') === '' && (int)($prev['okAt'] ?? 0) > time() - 60) return;  // نوشتنِ بی‌خود
    $st[$k] = ['kind' => '', 'label' => '', 'msg' => '', 'at' => 0,
               'fails' => 0, 'okAt' => time()];
    aiKeyStateSave($st);
}

/** پاک‌کردنِ دستیِ وضعیت — $kid خالی یعنی همهٔ کلیدهای این ارائه‌دهنده */
function aiKeyClearState(string $pid, string $kid = ''): int {
    $st = aiKeyStateLoad();
    $n = 0;
    foreach (array_keys($st) as $k) {
        if ($kid === '') { if (strpos($k, $pid . '|') === 0) { unset($st[$k]); $n++; } }
        elseif ($k === $pid . '|' . $kid)                    { unset($st[$k]); $n++; }
    }
    if ($n) aiKeyStateSave($st);
    return $n;
}

/**
 * انتخابِ کلید برای درخواستِ بعدی: اولین کلیدِ روشن و سالم.
 * اگر همه سوخته باشند، باز هم اولین کلیدِ روشن برمی‌گردد (با healthy=false)
 * تا دست‌کم یک تلاش انجام شود — چون ممکن است سهمیه تازه شده باشد.
 */
function aiPickApiKey(array $p, string $pid = '', array $skip = []): array {
    if ($pid === '') $pid = (string)($p['id'] ?? '');
    $keys = aiProviderKeys($p);
    $state = aiKeyStateLoad();
    $fallback = null;
    foreach ($keys as $k) {
        if (!$k['enabled']) continue;
        if (in_array($k['id'], $skip, true)) continue;
        if ($fallback === null) $fallback = $k;
        $h = aiKeyHealth($pid, $k['id'], $state);
        if (!$h['blocked']) return $k + ['healthy' => true, 'total' => count($keys)];
    }
    if ($fallback !== null) return $fallback + ['healthy' => false, 'total' => count($keys)];
    return ['id' => '', 'key' => '', 'label' => '', 'enabled' => true,
            'healthy' => false, 'total' => count($keys), 'none' => true];
}

/** چند کلیدِ سالمِ آماده‌به‌کار دارد (برای نمایش و تصمیمِ چرخش) */
function aiHealthyKeyCount(array $p, string $pid = ''): int {
    if ($pid === '') $pid = (string)($p['id'] ?? '');
    $state = aiKeyStateLoad();
    $n = 0;
    foreach (aiProviderKeys($p) as $k) {
        if (!$k['enabled']) continue;
        if (!aiKeyHealth($pid, $k['id'], $state)['blocked']) $n++;
    }
    return $n;
}

/**
 * v10.17 (۳۰): «اسلاتِ تست» — هر کلیدِ فعالِ یک ارائه‌دهنده یک ردیفِ جداگانه
 * در «تست مدل‌ها» می‌گیرد، چون در دسترس بودنِ یک مدل به کلید بستگی دارد
 * (اعتبارِ تمام‌شده، سهمیهٔ پرشده یا حسابِ متفاوت روی همان مدل).
 *
 * قرارداد:
 *   • صفر یا یک کلید ⇒ یک اسلاتِ «بی‌پسوند» با id خالی؛ رفتارِ نسخه‌های قبل
 *     دقیقاً حفظ می‌شود (هیچ کلیدی پین نمی‌شود و چرخشِ عادی کار می‌کند).
 *   • دو کلید یا بیشتر ⇒ به‌ازای هر کلید یک اسلات با پسوندِ یکتا؛ پس تعدادِ
 *     ردیف‌های تست در همان ارائه‌دهنده ضرب‌درِ تعدادِ کلید می‌شود.
 * پسوند از برچسبِ کلید ساخته می‌شود و اگر برچسب نداشت «#k1، #k2، …».
 */
function aiTestKeySlots(array $p): array {
    $on = [];
    foreach (aiProviderKeys($p) as $k) {
        if (empty($k['enabled'])) continue;
        $on[] = $k;
    }
    if (count($on) < 2) {
        return [['id' => '', 'label' => '', 'suffix' => '', 'n' => 1,
                 'key' => $on ? (string)$on[0]['key'] : '',
                 'acct' => $on ? (string)($on[0]['acct'] ?? '') : '']];
    }
    $out = []; $i = 0; $seen = [];
    foreach ($on as $k) {
        $i++;
        $lab = trim((string)($k['label'] ?? ''));
        $sfx = $lab !== '' ? $lab : ('k' . $i);
        $sfx = trim(preg_replace('~\s+~u', '_', $sfx));
        if ($sfx === '' || isset($seen[$sfx])) $sfx = ($sfx === '' ? 'k' : $sfx . '_') . $i;
        $seen[$sfx] = true;
        $out[] = ['id' => (string)$k['id'], 'label' => $lab, 'suffix' => '#' . $sfx, 'n' => $i,
                  'key' => (string)$k['key'], 'acct' => (string)($k['acct'] ?? '')];
    }
    return $out;
}

/** همان اسلات، از روی شناسهٔ کلید (برای اجرا؛ خودِ کلید در صف ذخیره نمی‌شود) */
function aiTestKeySlot(array $p, string $kid): ?array {
    if ($kid === '') return null;
    foreach (aiTestKeySlots($p) as $sl) if ($sl['id'] === $kid) return $sl;
    return null;
}

/**
 * v10.17: نسخه‌ای از ارائه‌دهنده که فقط همان یک کلید را دارد (کلید «پین» شده).
 * چون فهرستِ کلیدها به یک عضو کاهش می‌یابد، aiProviderCall خودش مسیرِ
 * تک‌کلیدی را می‌رود و هیچ چرخشی به کلیدِ دیگر انجام نمی‌دهد — دقیقاً همان
 * چیزی که برای «تستِ این مدل با این کلید» لازم است. شمارهٔ حسابِ کلید هم
 * (کلادفلر) اعمال می‌شود.
 */
function aiPinProviderKey(array $p, string $kid): array {
    if ($kid === '') return $p;
    $sl = aiTestKeySlot($p, $kid);
    if ($sl === null || (string)$sl['key'] === '') return $p;
    $p['apiKey']  = (string)$sl['key'];
    $p['apiKeys'] = [['id' => $kid, 'key' => (string)$sl['key'], 'label' => (string)$sl['label'],
                      'enabled' => true, 'acct' => (string)$sl['acct']]];
    return aiApplyKeyAccount($p, ['acct' => (string)$sl['acct']]);
}

/** کلیدِ یکتای یک ردیفِ تست: مدل + (در حالتِ چندکلیدی) شناسهٔ کلید */
function aiTestRowKey(string $pid, string $mid, string $kid = ''): string {
    return $pid . '|' . $mid . ($kid !== '' ? '#' . $kid : '');
}

/**
 * v10.17: «این مدل با این کلید قبلاً تست شده؟» — پایهٔ تیکِ «فقط تست‌نشده».
 * با یک کلید همان پرچمِ قدیمیِ tested است؛ با چند کلید، هر کلید حسابِ خودش
 * را دارد تا افزودنِ کلیدِ تازه باعثِ تستِ دوبارهٔ کلیدهای قبلی نشود.
 */
function aiModelKeyTested(array $m, string $kid): bool {
    if ($kid === '') return !empty($m['tested']);
    $kt = $m['keyTests'] ?? null;
    if (!is_array($kt) || !isset($kt[$kid]) || !is_array($kt[$kid])) return false;
    return !empty($kt[$kid]['tested']);
}

/**
 * وقتی کلیدِ تازه‌ای اضافه می‌شود، نتیجهٔ «اعتبار/سهمیه»ی مدل‌ها دیگر معتبر
 * نیست: کلیدِ نو ممکن است همان مدل‌ها را باز کند. پس آن ردیف‌ها به حالتِ
 * «تست‌نشده» برمی‌گردند تا در تستِ بعدی (حتی با تیکِ «فقط تست‌نشده») دوباره
 * سنجیده شوند. مدل‌هایی که با خطای فنی رد شده‌اند دست‌نخورده می‌مانند.
 */
function aiResetKeyRelatedFailures(array $p): array {
    foreach ((array)($p['models'] ?? []) as $i => $m) {
        if (!is_array($m)) continue;
        $bill  = (string)($m['billingIssue'] ?? '');
        $stat  = (int)($m['testDetails']['status'] ?? 0);
        $rate  = !empty($m['rateLimited']);
        if ($bill === '' && !$rate && !in_array($stat, [401, 402, 429], true)) continue;
        unset($p['models'][$i]['billingIssue']);
        $p['models'][$i]['tested']      = false;
        $p['models'][$i]['available']   = false;
        $p['models'][$i]['rateLimited'] = false;
        if (isset($p['models'][$i]['testDetails']) && is_array($p['models'][$i]['testDetails'])) {
            $p['models'][$i]['testDetails']['keyReset']   = true;
            $p['models'][$i]['testDetails']['resetAt']    = gmdate('c');
        }
    }
    return $p;
}
/* =====================================================================
 *  v9.24: حالتِ کارِ پس‌زمینهٔ «تست مدل‌ها»
 *
 *  تست به‌صورت یک پردازهٔ جدا از مرورگر (detached) اجرا می‌شود؛ پس از
 *  ریفرش یا بستن پنجره ادامه پیدا می‌کند. مرورگر فقط وضعیت را poll می‌کند.
 * ===================================================================== */
function aiTestStateLoad(): array {
    return localTaskStateRead(AI_TEST_STATE_FILE, ['running' => false, 'done' => false, 'items' => []]);
}
function aiTestStateSave(array $st): void {
    $st['updated_at'] = time();
    writeJsonFile(AI_TEST_STATE_FILE, $st);
}
/** قفلِ واقعی تست مدل‌ها؛ state به‌تنهایی برای جلوگیری از اجرای موازی کافی نیست. */
function aiTestLockOpen() {
    $fp = @fopen(AI_TEST_LOCK_FILE, 'c');
    if (!$fp || !@flock($fp, LOCK_EX | LOCK_NB)) {
        if ($fp) @fclose($fp);
        return null;
    }
    return $fp;
}
function aiTestLockHeld(): bool {
    if (!is_file(AI_TEST_LOCK_FILE)) return false;
    $fp = @fopen(AI_TEST_LOCK_FILE, 'c');
    if (!$fp) return false;
    $free = @flock($fp, LOCK_EX | LOCK_NB);
    if ($free) @flock($fp, LOCK_UN);
    @fclose($fp);
    return !$free;
}
function aiTestLockClose($fp): void {
    if (is_resource($fp)) {
        @flock($fp, LOCK_UN); @fclose($fp);
    }
    /* AI_TEST_LOCK_FILE مسیرِ دائمی دارد؛ مالکیت با flock آزاد شد. */
}
/* v9.45: آیا «توقف تست مدل‌ها» درخواست شده؟ کش stat را پاک می‌کند تا فایلِ
   تازه‌ساخته‌شده هم دیده شود (همان الگوی bslReq). این یک نقطهٔ مشترک است تا
   همهٔ حلقه‌های شبکه — نه فقط aiHttp — سیگنال توقف را ببینند. */
function aiTestStopRequested(): bool {
    clearstatcache(true, AI_TEST_STOP_FILE);
    return is_file(AI_TEST_STOP_FILE);
}
/** آیا یک درخواستِ پاسخ‌نشده واقعاً «قطع/ناپذیر» بود (نه خطای منطقی API)؟ */
/* v10.218: متنِ خطا را از همهٔ شکل‌های رایج بیرون بکش. Workerها گاهی
   خطای port/fetch را به‌صورت متن خام یا {success:false,error:'...'} می‌دهند؛
   اگر فقط curl_error را بخوانیم، کاربر فقط HTTP 500/400 می‌بیند. */
function aiHttpErrorMessage(array $r): string {
    $body = $r['body'] ?? null;
    /* v10.444: Gemini خطاها را به‌صورت آرایهٔ یک‌عضوی [{"error":{"code":400,"message":"..."}}]
       برمی‌گرداند و برخی سرویس‌های FastAPI/Mistral فیلد detail را آرایه‌ای از خطاهای
       اعتبارسنجی می‌دهند؛ بازکردنِ آرایه باعث می‌شود متنِ دقیق خطا دیده شود. */
    if (is_array($body) && isset($body[0]) && is_array($body[0]) && !isset($body['error']) && !isset($body['message'])) {
        $body = $body[0];
    }
    $msg = '';
    if (is_array($body)) {
        $e = $body['error'] ?? null;
        if (is_array($e)) $msg = (string)($e['message'] ?? ($e['error'] ?? ($e['detail'] ?? '')));
        elseif (is_string($e)) $msg = $e;
        if ($msg === '' && isset($body['message']) && is_string($body['message'])) $msg = $body['message'];
        if ($msg === '' && isset($body['detail'])) {
            if (is_string($body['detail'])) $msg = $body['detail'];
            elseif (is_array($body['detail'])) {
                $dParts = [];
                foreach ($body['detail'] as $dItem) {
                    if (is_array($dItem) && !empty($dItem['msg'])) {
                        $loc = is_array($dItem['loc'] ?? null) ? implode('.', $dItem['loc']) : '';
                        $dParts[] = ($loc !== '' ? ($loc . ': ') : '') . (string)$dItem['msg'];
                    } elseif (is_string($dItem)) $dParts[] = $dItem;
                }
                if ($dParts) $msg = implode(' | ', $dParts);
            }
        }
        if ($msg === '' && isset($body['errors'][0]['message'])) $msg = (string)$body['errors'][0]['message'];
    } elseif (is_string($body) && $body !== '') {
        $msg = $body;
    }
    if ($msg === '') $msg = (string)($r['error'] ?? '');
    if ($msg === '') {
        $raw = trim((string)($r['raw'] ?? ''));
        if ($raw !== '') {
            $plain = trim((string)preg_replace('~<[^>]+>~', ' ', $raw));
            $plain = trim((string)preg_replace('~\s+~u', ' ', html_entity_decode($plain, ENT_QUOTES | ENT_HTML5, 'UTF-8')));
            if ($plain !== '') $msg = $plain;
        }
    }
    if (!empty($r['cf_error'])) $msg = (string)$r['cf_error'];
    return mb_substr($msg, 0, 500);
}

/**
 * v10.444: آیا خطا صراحتاً می‌گوید «هیچ کلید/هدر احراز هویتی نرسیده»؟
 * وقتی ما خودمان یک کلید غیرخالی فرستاده‌ایم ولی پاسخِ Worker/پروکسی می‌گوید
 * «Missing API key» یا «no api key supplied» یا «Missing or invalid Authorization header»،
 * یعنی واسطه هدر Authorization را در میانهٔ راه حذف کرده است.
 */
function aiIsMissingAuthHeaderError(array $r): bool {
    $code = (int)($r['code'] ?? 0);
    if (!in_array($code, [400, 401, 403], true)) return false;
    $hay = strtolower(aiHttpErrorMessage($r) . ' ' . (string)($r['raw'] ?? ''));
    foreach ([
        'missing api key', 'no api key supplied', 'api key is missing',
        'missing or invalid authorization header', 'authorization header is missing',
        'missing authorization header', 'provide an api key', 'no authorization header',
        'authentication credentials were not provided', 'x-api-key header is required',
    ] as $sig) {
        if (strpos($hay, $sig) !== false) return true;
    }
    return false;
}

/**
 * v10.444: تشخیص بلاک جغرافیایی/تحریمی یا فایروال لبه روی مسیر مستقیم/DoH
 * (مثلاً Groq 403 Forbidden، Google User location is not supported،
 * Ollama Cloud 403 Your client does not have permission) تا aiProviderCallOnce
 * به‌جای توقف زودهنگام سراغ Worker/Proxy برود.
 */
function aiIsGeoOrEdgeBlock(array $r, string $mode = ''): bool {
    $code = (int)($r['code'] ?? 0);
    if (!in_array($code, [400, 403, 451], true)) return false;
    if (aiBillingFailure($r)['is']) return false;
    $hay = strtolower(aiHttpErrorMessage($r) . ' ' . (string)($r['raw'] ?? ''));
    foreach ([
        'user location is not supported', 'location is not supported',
        'country, region, or territory not supported', 'not available in your country',
        'not available in your region', 'your client does not have permission to get url',
        'access denied by security policy', 'error code: 1020', 'error code: 1010',
        'blocked in your region', 'unavailable in your region',
    ] as $sig) {
        if (strpos($hay, $sig) !== false) return true;
    }
    if ($code === 403 && in_array($mode, ['direct', 'doh', 'dns'], true)) {
        $msg = strtolower(trim(aiHttpErrorMessage($r)));
        if ($msg === '' || $msg === 'forbidden' || $msg === 'access denied' || $msg === '403 forbidden') {
            return true;
        }
    }
    return false;
}

function aiTestNetworkFailure(array $r): array {
    $code = (int)($r['code'] ?? 0);
    $msg  = aiHttpErrorMessage($r);
    $err  = strtolower($msg . ' ' . (string)($r['error'] ?? '') . ' ' . (string)($r['raw'] ?? ''));
    $cat  = 'ok'; $label = ''; $reachable = true;
    if ($code === 0 && $err !== '') {
        $reachable = false;
        if (strpos($err, 'bad port') !== false || strpos($err, 'invalid port') !== false || strpos($err, 'port is not allowed') !== false || strpos($err, 'disallowed port') !== false) { $cat = 'port'; $label = 'خطای پورت در مسیر Worker/URL مقصد'; }
        elseif (strpos($err, 'resolve') !== false)            { $cat = 'dns';    $label = 'DNS — دامنه‌ای که قابل‌حل نیست (مسموم/بسته)'; }
        elseif (strpos($err, 'timed out') !== false)      { $cat = 'timeout';$label = 'تایم‌اوت — سرور پاسخ نداد'; }
        elseif (strpos($err, 'refused') !== false)        { $cat = 'refused';$label = 'اتصال رد شد (Connection refused)'; }
        elseif (strpos($err, 'connect') !== false)        { $cat = 'connect';$label = 'برقراری اتصال ناموفق'; }
        elseif (strpos($err, 'ssl') !== false)            { $cat = 'ssl';    $label = 'خطای SSL/TLS'; }
        else                                              { $cat = 'network';$label = 'خطای شبکه: ' . mb_substr($msg, 0, 80); }
    } elseif ($code > 0) {
        if (strpos($err, 'bad port') !== false || strpos($err, 'invalid port') !== false || strpos($err, 'port is not allowed') !== false || strpos($err, 'disallowed port') !== false) { $cat = 'port'; $label = 'خطای پورت در Worker — آدرس مقصد/قالب Worker اصلاح شود'; }
        elseif ($code === 401)      { $cat = 'auth';   $label = 'کلید API نامعتبر (401)'; }
        elseif ($code === 403)  { $cat = 'forbidden'; $label = 'دسترسی رد شد (403) — IP هاست احتمالاً بلاک است'; }
        elseif ($code === 404)  { $cat = 'notfound';$label = 'مدل/اندپوینت پیدا نشد (404)'; }
        elseif ($code === 429)  { $cat = 'ratelimit';$label = 'محدودیت نرخ (429)'; }
        elseif ($code === 400)  { $cat = 'badreq'; $label = 'درخواست نامعتبر (400)'; }
        elseif ($code === 422)  { $cat = 'badreq'; $label = 'درخواست نامعتبر (422)'; }
        else                    { $cat = 'http';   $label = 'HTTP ' . $code; }
    }
    return ['code' => $code, 'cat' => $cat, 'label' => $label, 'reachable' => $reachable, 'error' => $msg];
}
/* =====================================================================
 *  v9.99: تشخیصِ «خطا از واسطه است، نه از خودِ سرویس»
 *
 *  گزارش تست کاربر: ۴۹ مدل از ۵۰ مدلِ OpenRouter و هر ۱۵ مدلِ Groq با
 *  HTTP 403 رد شدند، ولی بدنهٔ پاسخ این بود:
 *      {"success":false,"error":"Access denied by security policy."}
 *  این متنِ خودِ Worker/پروکسیِ واسط است، نه پاسخِ OpenRouter. برای
 *  Together هم صفحهٔ HTMLِ «Sorry, you have been blocked» کلادفلر آمده بود.
 *
 *  اهمیتش: aiProviderCall روی کدهای ۴۰۰/۴۰۳/۴۰۴/۴۲۹ عمداً می‌ایستد (تا
 *  خطای منطقیِ سرویس را با تلاشِ بی‌فایده قاطی نکند). ولی وقتی ۴۰۳ از
 *  واسطه آمده، ایستادن یعنی مسیرِ «مستقیم» که سالم است هرگز امتحان
 *  نمی‌شود و همهٔ مدل‌ها بی‌دلیل «ناموفق» ثبت می‌شوند.
 *
 *  این تابع امضاهای واسطه را می‌شناسد تا حلقه به‌جای ایستادن، روشِ بعدی
 *  را امتحان کند و در گزارش هم «مشکل از مسیر عبور» برچسب بخورد.
 * ===================================================================== */
function aiProxyLevelFailure(array $r, string $mode = ''): bool {
    $code = (int)($r['code'] ?? 0);
    if ($code < 400) return false;
    $mode = $mode !== '' ? $mode : (string)($r['mode'] ?? '');
    $viaProxy = in_array($mode, ['worker', 'proxy', 'gateway'], true);
    $raw = (string)($r['raw'] ?? '');
    $body = $r['body'] ?? null;
    $low = strtolower($raw);

    // ۱) امضاهای متنیِ صریحِ واسطه/CDN — حتی اگر روش «مستقیم» باشد
    //    (چون ممکن است base_url خودش یک درگاه واسط باشد)
    $sigs = ['access denied by security policy', 'sorry, you have been blocked',
             'you have been blocked', 'attention required! | cloudflare',
             'cf-error-details', 'error code: 1020', 'proxy.php',
             'x-target-url', 'bad gateway', 'gateway timeout',
             'bad port', 'invalid port', 'port is not allowed', 'disallowed port'];
    foreach ($sigs as $sig) {
        if ($sig !== '' && strpos($low, $sig) !== false) return true;
    }

    // ۲) پاسخِ HTML به‌جای JSON: هر API واقعی برای خطا JSON می‌دهد.
    //    صفحهٔ HTML یعنی چیزی وسطِ راه جواب داده است.
    $t = ltrim($raw);
    if ($t !== '' && (stripos($t, '<!doctype') === 0 || stripos($t, '<html') === 0)) return true;

    // ۳) پوستهٔ {"success":false,"error":"..."} که فرمتِ OpenAI نیست
    if (is_array($body) && array_key_exists('success', $body) && $body['success'] === false
        && isset($body['error']) && is_string($body['error'])
        && !isset($body['error']['message'])) return true;

    // ۴) از مسیر واسطه، خطای ۴۰۳/۵۰۲/۵۰۳ با پیامِ تهی یا صرفاً «Forbidden»
    if ($viaProxy) {
        if (in_array($code, [502, 503, 504], true)) return true;
        if ($code === 403) {
            $msg = '';
            if (is_array($body)) {
                $msg = (string)($body['error']['message'] ?? ($body['message'] ?? (is_string($body['error'] ?? null) ? $body['error'] : '')));
            }
            $msg = strtolower(trim($msg));
            if ($msg === '' || $msg === 'forbidden' || $msg === 'access denied') return true;
        }
    }
    return false;
}

/* v9.99: آیا این خطا مربوط به «اعتبار/اشتراک/سهمیه» است؟
   این دسته عمداً «رفع» نمی‌شود — با هیچ تغییری در کد درست نمی‌شود و فقط
   باید درست برچسب بخورد تا کاربر بداند باید شارژ/ارتقا بدهد یا مدل را
   کنار بگذارد. (خواستهٔ صریح: خطاهای اعتبار را رفع نکن، دسته‌بندی کن.) */
function aiBillingFailure(array $r): array {
    $code = (int)($r['code'] ?? 0);
    $raw  = strtolower((string)($r['raw'] ?? ''));
    $body = $r['body'] ?? null;
    $msg  = '';
    if (is_array($body) && isset($body[0]) && is_array($body[0]) && !isset($body['error'])) $body = $body[0];
    if (is_array($body)) {
        $msg = (string)($body['error']['message'] ?? ($body['message'] ?? ''));
        if ($msg === '' && isset($body['error']) && is_string($body['error'])) $msg = $body['error'];
        if ($msg === '' && !empty($body['errors'][0]['message'])) $msg = (string)$body['errors'][0]['message'];
    } elseif (is_string($body) && $body !== '') {
        // v9.99: بعضی سرویس‌ها بدنه را متنِ خام می‌فرستند (نه JSON). اگر فقط
        // به raw تکیه کنیم، متنِ خطا از دست می‌رود و همه‌چیز «۴۰۲ = اعتبار»
        // برچسب می‌خورد؛ در حالی که ممکن است «پلن» یا «اشتراک» باشد.
        $msg = $body;
    }
    $hay = strtolower($msg) . ' ' . $raw;
    /* v10.469: خطاهای موقت نرخ (۴۲۹) که در متن راهنما لینک /billing دارند (مثل llm7 / mistral)
       نباید «اعتبار تمام شده» برچسب بخورند. */
    if ($code === 429) {
        foreach (['too many ', 'rate limit', 'requests per ', 'tokens per ', 'retry in ', 'try again in ', 'service_tier_capacity_exceeded'] as $rlSig) {
            if (strpos($hay, $rlSig) !== false
                && strpos($hay, 'insufficient_quota') === false
                && strpos($hay, 'insufficient credits') === false
                && strpos($hay, 'no remaining credits') === false
                && strpos($hay, 'out of credit') === false) {
                return ['is' => false, 'kind' => '', 'label' => '', 'msg' => ''];
            }
        }
    }
    // v9.99: ترتیبِ قانون‌ها مهم است — دسته‌های دقیق‌تر (پلن/اشتراک/Labs/آزمایشی)
    // پیش از دستهٔ عمومیِ «اعتبار» سنجیده می‌شوند، وگرنه واژه‌های عامی مثل
    // «billing» یا «payment required» همه را «credit» برچسب می‌زنند.
    $rules = [
        ['plan',    ['not available on the workers free plan', 'is not allowed to access',
                     'upgrade your plan', 'requires a paid plan', 'paid plan'],
                    'پلن رایگان اجازه نمی‌دهد — نیاز به ارتقای پلن'],
        ['tier',    ['tier_not_allowed', 'not available in your subscription tier',
                     'subscription tier', 'model_not_in_tier', 'free tier can only be used'],
                    'مدل در سطحِ اشتراکِ شما نیست — نیاز به ارتقای اشتراک'],
        ['labs',    ['labs_not_enabled', 'admin must enable', 'admin to enable', 'labs model'],
                    'مدل Labs غیرفعال است — ادمینِ حساب باید فعالش کند'],
        ['trial',   ['trial key', 'trial keys are limited', '1000 api calls'],
                    'کلید آزمایشی سقف ماهانه دارد — کلید تولیدی لازم است'],
        ['credit',  ['depleted your monthly included credits', 'monthly included credits',
                     'insufficient credits', 'insufficient balance', 'insufficient_quota', 'exceeded your current quota',
                     'no remaining credits', 'payment required', 'billing hard limit', 'billing_not_active',
                     'account is delinquent', 'add credits', 'out of credit', 'top up your balance'],
                    'اعتبار تمام شده — باید حساب را شارژ کنید (رفع‌شدنی با کد نیست)'],
    ];
    foreach ($rules as $ru) {
        foreach ($ru[1] as $needle) {
            if ($needle !== '' && strpos($hay, $needle) !== false)
                return ['is' => true, 'kind' => $ru[0], 'label' => $ru[2], 'msg' => mb_substr($msg, 0, 200)];
        }
    }
    if ($code === 402) return ['is' => true, 'kind' => 'credit',
        'label' => 'اعتبار تمام شده (۴۰۲) — باید حساب را شارژ کنید', 'msg' => mb_substr($msg, 0, 200)];
    return ['is' => false, 'kind' => '', 'label' => '', 'msg' => ''];
}

/* =====================================================================
 *  v9.99: مدل‌هایی که اصلاً «چت» نیستند
 *
 *  در گزارشِ تستِ کاربر ده‌ها ردیفِ Cloudflare با خطاهایی مثل
 *    AiError: Bad input… required properties are 'text' / 'query,contexts'
 *    {"code":7000,"message":"No route for that URI"}
 *  شکست خورده بودند. این‌ها مدلِ خرابی نیستند — مدلِ embedding، تبدیل
 *  متن‌به‌گفتار، تشخیصِ گفتار، تولید تصویر یا rerank اند و ورودیِ چت
 *  نمی‌گیرند. تستِ چت روی آن‌ها همیشه شکست می‌خورد و فقط گزارش را شلوغ
 *  و زمانِ تست را چند برابر می‌کند. این‌ها «رد شد» نیستند، «قابل‌تست
 *  نیستند» و باید از صف کنار بروند.
 * ===================================================================== */
function aiNonChatModel(string $modelId, array $m = []): string {
    $id = strtolower(trim($modelId));
    if ($id === '') return '';
    // اگر کاربر دستی علامت زده باشد، حرفِ او مقدم است
    if (isset($m['chat'])) return empty($m['chat']) ? 'کاربر آن را غیرچت علامت زده' : '';
    $rules = [
        ['امبدینگ (متن را به بردار تبدیل می‌کند، پاسخ متنی ندارد)',
         ['bge-', 'embeddinggemma', '/embed', 'text-embedding', '-embedding', 'embed-', 'e5-', 'gte-', 'jina-embed']],
        ['بازچینش نتایج (rerank) — ورودی‌اش query و contexts است',
         ['rerank', 'bge-reranker']],
        ['تولید تصویر یا ویدیو — خروجی‌اش رسانه است نه متن',
         ['flux', 'stable-diffusion', 'sd-', 'sdxl', 'xl-lightning', 'dreamshaper', 'phoenix-1', 'text-to-image',
          'imagen', 'gpt-image', 'firefly-', '-image', 'veo-', 'kling-', 'seedance', 'lyria-', 'diffusion', 'chroma-v.', 'dark-beast-krea', 'imagine-1']],
        ['تبدیل گفتار به متن یا صوت زنده (ASR/Audio)',
         ['whisper', 'nova-3', 'speech-to-text', 'transcribe', 'voxtral', 'native-audio', '-live-preview', '-live-translate']],
        ['تبدیل متن به گفتار (TTS)',
         ['melotts', 'aura-1', 'aura-2', 'aura-', 'orpheus-', 'text-to-speech', 'tts-', '-tts']],
        ['طبقه‌بندی/بینایی/خلاصه‌سازی غیرچت',
         ['resnet', 'detr-', 'uform', 'clip-', 'image-classification', 'bart-large-cnn', 'distilbert-sst', 'mistral-ocr']],
        ['ترجمهٔ تخصصی — ورودی‌اش قالبِ چت نیست', ['m2m100', 'opus-mt']],
        ['تشخیصِ نوبتِ گفتار', ['smart-turn']],
        ['محافظ/مدیریت محتوا — پاسخِ گفت‌وگویی نمی‌دهد',
         ['guard', 'shieldstral', 'moderation', 'llamaguard', 'llama-guard']],
        ['اندپوینت غیرچت (Batch ناهمگام / فایل وزن خام GGUF-MLX / عامل اختصاصی)',
         [':batch', '-gguf', '.gguf', '-mlx-', 'computer-use', 'robotics-er', 'deep-research-']],
    ];
    foreach ($rules as $ru) {
        foreach ($ru[1] as $needle) {
            if ($needle !== '' && strpos($id, $needle) !== false) return $ru[0];
        }
    }
    return '';
}

/* =====================================================================
 *  v9.99: اعتبارسنجیِ پاسخِ «ظاهراً موفق»
 *
 *  در گزارشِ تستِ کاربر ۹ مدلِ Cloudflare با available=true ثبت شده بودند
 *  در حالی که متنِ پاسخشان JSONِ خامِ یک مدلِ دیگر بود
 *  (model:"@cf/meta/llama-3.1-8b-fast-v2") و چند مدل هم پاسخی مثل
 *  «OOOOO…» یا یک عبارتِ تکراری داده بودند. این‌ها مثبتِ کاذب‌اند: مدل
 *  در عمل کار نمی‌کند ولی سبز ثبت می‌شود و بعداً در تولید خطا می‌دهد.
 *
 *  خروجی: رشتهٔ خالی = پاسخ سالم، وگرنه دلیلِ مشکوک‌بودن.
 * ===================================================================== */
function aiSuspectAnswer(string $text, string $modelId = ''): string {
    $t = trim($text);
    if ($t === '') return 'پاسخ خالی است';
    // ۱) خودِ پاسخ یک JSONِ خام است (پوستهٔ سرویس، نه متنِ مدل)
    if ((strpos($t, '{') === 0 || strpos($t, '[') === 0)) {
        $j = json_decode($t, true);
        if (is_array($j) && (isset($j['model']) || isset($j['choices']) || isset($j['result'])
            || isset($j['usage']) || isset($j['object']))) {
            $other = trim((string)($j['model'] ?? ''));
            if ($other !== '' && $modelId !== '' && strcasecmp($other, $modelId) !== 0)
                return 'پاسخ در واقع JSONِ خامِ مدلِ دیگری است: ' . mb_substr($other, 0, 60);
            return 'به‌جای متن، JSONِ خامِ سرویس برگشته است';
        }
    }
    // ۲) تکرارِ یک نویسه (مثل «OOOOO…») — نشانهٔ خرابیِ تولید
    $len = mb_strlen($t);
    if ($len >= 12) {
        $chars = preg_split('//u', preg_replace('/\s+/u', '', $t), -1, PREG_SPLIT_NO_EMPTY);
        if ($chars && count($chars) >= 12) {
            $uniq = count(array_unique($chars));
            if ($uniq <= 2) return 'پاسخ فقط تکرارِ یک نویسه است — خروجیِ خراب';
        }
    }
    // ۳) تکرارِ یک عبارت پشت‌سرهم بیش از ۵ بار
    if (preg_match('/(.{4,40}?)\1{5,}/u', $t)) return 'پاسخ یک عبارتِ تکرارشونده است — خروجیِ خراب';
    return '';
}

/** انتخاب فعال {provider,model} را از connections می‌خواند */
function aiSelected(): array {
    $s = loadConnections()['ai_selected'] ?? [];
    return ['provider' => (string)($s['provider'] ?? ''), 'model' => (string)($s['model'] ?? '')];
}
/** انتخاب فعال را ذخیره می‌کند */
function aiSaveSelected(string $provider, string $model): void {
    $cn = loadConnections();
    $cn['ai_selected'] = ['provider' => $provider, 'model' => $model];
    saveConnections($cn);
}
/** ایمیلی/برچسب را از روی URL یا مدل به‌صورت امن بیرون می‌کشد */
function aiModelKey(string $s): string {
    $s = trim($s);
    // ابتدا پیوند مارک‌داون را باز کن
    if (preg_match('~^\[([^]]+)\]\(([^)]+)\)$~', $s, $m)) $s = $m[1];
    return $s;
}
/* =====================================================================
 *  v9.94: مدل‌های «استدلالی» (reasoning)
 *
 *  گزارش کاربر: مدلِ رایگانِ استدلالیِ Together AI (و بقیهٔ مدل‌های
 *  استدلالی) در «تست مدل‌ها» پاسخ می‌دادند ولی در «دسته‌بندی» و
 *  «پاسخ به مشتری» هیچ‌وقت جواب نمی‌دادند.
 *
 *  دو علتِ واقعی:
 *   ۱) سقفِ توکن. دسته‌بندی max_tokens=20 و پاسخ به مشتری 160 می‌فرستاد.
 *      مدلِ استدلالی اول کلِ بودجه را صرفِ «فکر کردن» می‌کند و به content
 *      نمی‌رسد؛ پس رشتهٔ خالی برمی‌گشت. (تستِ مدل‌ها ۳۰۰ می‌فرستاد و
 *      به همین دلیل کار می‌کرد.)
 *   ۲) استخراجِ متن. سه مسیرِ تولیدی مستقیماً
 *      choices[0].message.content را می‌خواندند و فیلدهای
 *      reasoning / reasoning_content را نمی‌دیدند — برخلاف aiExtractText.
 *
 *  حل: هر دو مسیر از aiExtractText عبور می‌کنند، سقفِ توکن برای مدلِ
 *  استدلالی چند برابر می‌شود، و متنِ «فکر کردن» پیش از استفاده تمیز
 *  می‌شود. تشخیص خودکار است ولی کاربر هم می‌تواند دستی تیک بزند.
 * ===================================================================== */

/** الگوهای نامِ مدل‌های استدلالیِ شناخته‌شده */
function aiReasoningPatterns(): array {
    return ['deepseek-r1', 'deepseek-reason', 'deepseek-v4', 'qwq', 'qwen3', 'qwen-3', 'thinking', 'think',
            'reasoner', 'reasoning', 'gpt-oss', 'gpt-5', 'o1-', 'o1', 'o3-', 'o3', 'o4-', 'magistral', 'leanstral',
            'phi-4-reasoning', 'nemotron', 'skywork-o1', 'marco-o1', 'sky-t1', 'exaone-deep', 'r1-distill',
            'bonsai', 'ternary-bonsai', 'hy3', 'kimi-k2', 'kimi-k3', 'glm-5', 'glm-4.7', 'grok-4',
            'gemini-2.5-pro', 'gemini-3', 'minimax-m2', 'minimax-m3', 'mimo', 'command-a-reasoning',
            'claude-opus-4', 'claude-opus-5', 'claude-sonnet-4', 'claude-sonnet-5', 'claude-fable'];
}

/**
 * آیا این مدل استدلالی است؟
 * اولویت با تیکِ دستیِ کاربر ($m['reasoning']) است؛ اگر تیک نخورده باشد
 * از روی نامِ مدل حدس می‌زنیم.
 */
function aiIsReasoningModel(?array $m, string $modelId = ''): bool {
    if (is_array($m)) {
        if (array_key_exists('reasoning', $m)) return !empty($m['reasoning']);
        if ($modelId === '') $modelId = (string)($m['id'] ?? '');
    }
    $low = strtolower(trim($modelId));
    if ($low === '') return false;
    foreach (aiReasoningPatterns() as $kw) if (strpos($low, $kw) !== false) return true;
    return false;
}

/** ردیفِ مدل را داخل ارائه‌دهنده پیدا می‌کند */
function aiFindModelRow(?array $p, string $modelId): ?array {
    if (!is_array($p)) return null;
    foreach ((array)($p['models'] ?? []) as $m) {
        if (is_array($m) && (string)($m['id'] ?? '') === $modelId) return $m;
    }
    return null;
}

/**
 * سقفِ توکن را برای مدل‌های استدلالی بزرگ می‌کند.
 * مدلِ عادی همان عددِ قبلی را می‌گیرد تا رفتار و هزینه‌اش تغییر نکند.
 */
function aiReasoningBudget(int $want, bool $isReasoning): int {
    if (!$isReasoning) return $want;
    return max(1024, $want * 8);
}

/**
 * بلوکِ «فکر کردن» را از متنِ مدلِ استدلالی جدا می‌کند.
 * خیلی از مدل‌ها زنجیرهٔ فکر را داخل <think>…</think> می‌گذارند و بعد
 * جوابِ نهایی را می‌نویسند؛ اگر پاک نشود، پاسخِ مشتری پر از فکرِ مدل
 * می‌شود و دسته‌بندی هم اولین عددِ داخلِ فکر را برمی‌دارد.
 */
function aiStripReasoning(string $text): string {
    $t = $text;
    // بلوکِ کاملِ فکر
    $t = preg_replace('~<(think|thinking|reasoning|thought)>.*?</\1>~is', ' ', $t) ?? $t;
    // بلوکِ بازِ بدونِ بسته (وقتی توکن تمام شده) — هرچه بعدش آمده فکر است
    $t = preg_replace('~<(think|thinking|reasoning|thought)>.*$~is', ' ', $t) ?? $t;
    // بلوکِ بسته بدونِ باز (وقتی سرویس تگِ باز را جدا فرستاده)
    if (preg_match('~</(?:think|thinking|reasoning|thought)>~i', $t)) {
        $t = preg_replace('~^.*</(?:think|thinking|reasoning|thought)>~is', '', $t) ?? $t;
    }
    // نشانه‌های متنیِ رایج
    $t = preg_replace('~^\s*(?:Thought|Reasoning|Analysis|Final Answer)\s*:\s*~i', '', $t) ?? $t;
    return trim($t);
}

/**
 * v9.94: شناسهٔ دسته را از متنِ پاسخ بیرون می‌کشد.
 *
 * مدلِ غیراستدلالی فقط یک عدد می‌نویسد. مدلِ استدلالی گاهی چند شناسه را
 * بلند بلند بررسی می‌کند و «انتخابِ نهایی» ته متن می‌آید؛ پس اگر بیش از
 * یک عدد دیدیم، آخری را برمی‌داریم. اگر جمله‌ای مثل «ID: 1234» یا
 * «answer is 1234» بود، همان اولویت دارد.
 */
function aiPickCategoryId(string $text): int {
    $t = trim($text);
    if ($t === '') return 0;
    // الگوهای صریحِ «جوابِ نهایی»
    if (preg_match('~(?:final(?:\s+answer)?|answer|category(?:\s*id)?|id)\s*[:=]?\s*#?(\d{2,})~i', $t, $m)) {
        return (int)$m[1];
    }
    if (!preg_match_all('/\d+/', $t, $mm) || empty($mm[0])) return 0;
    // شناسه‌های دسته چندرقمی‌اند؛ عددهای تک‌رقمیِ داخلِ توضیح را نادیده بگیر
    $big = array_values(array_filter($mm[0], fn($n) => strlen($n) >= 2));
    $pick = $big ? end($big) : end($mm[0]);
    return (int)$pick;
}

/**
 * متنِ مفیدِ پاسخ را از بدنه بیرون می‌کشد — نسخهٔ آگاه به مدل استدلالی.
 * اول aiExtractText (که همهٔ شکل‌های پاسخ را می‌شناسد) و بعد پاکسازیِ فکر.
 * اگر بعد از پاکسازی چیزی نماند، خودِ متنِ خام برگردانده می‌شود تا
 * دست‌کم چیزی برای نمایش/تطبیق وجود داشته باشد.
 */
function aiExtractAnswer($body): string {
    $raw = trim(aiExtractText($body));
    if ($raw === '') return '';
    $clean = aiStripReasoning($raw);
    return $clean !== '' ? $clean : $raw;
}

/* v10.219: ساختِ بدنه‌های جایگزین برای خطاهای شکل payload.
   این‌ها خطای اعتبار یا ریت‌لیمیت نیستند؛ معمولاً تفاوتِ لهجهٔ OpenAI-compatible
   است: مدل‌های reasoning بعضی سرویس‌ها max_tokens را نمی‌پذیرند و
   max_completion_tokens می‌خواهند، یا temperature را فقط مقدار پیش‌فرض قبول
   می‌کنند. به‌جای قرمز کردن مدل، همان درخواست یک بار با بدنهٔ اصلاح‌شده
   امتحان می‌شود. */
function aiPayloadRepairVariants(array $payload, array $r, string $model = ''): array {
    $code = (int)($r['code'] ?? 0);
    if (!in_array($code, [400, 422], true)) return [];
    if (aiBillingFailure($r)['is'] || $code === 429) return [];
    $hay = strtolower(aiHttpErrorMessage($r) . ' ' . (string)($r['raw'] ?? ''));
    $out = [];
    $add = function (array $p, string $why) use (&$out) {
        unset($p['_s4_no_repair']);
        $k = md5(json_encode($p, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
        if (!isset($out[$k])) $out[$k] = ['payload' => $p, 'repair' => $why];
    };
    $mentionsMaxTokens = strpos($hay, 'max_tokens') !== false || strpos($hay, 'max tokens') !== false;
    $mentionsMaxCompletion = strpos($hay, 'max_completion_tokens') !== false;
    $unsupported = strpos($hay, 'unsupported') !== false || strpos($hay, 'not supported') !== false
        || strpos($hay, 'unknown parameter') !== false || strpos($hay, 'unrecognized') !== false
        || strpos($hay, 'invalid parameter') !== false || strpos($hay, 'extra inputs') !== false
        || strpos($hay, 'not permitted') !== false;
    if ($mentionsMaxTokens && ($unsupported || $mentionsMaxCompletion) && isset($payload['max_tokens'])) {
        $p2 = $payload;
        $p2['max_completion_tokens'] = (int)$payload['max_tokens'];
        unset($p2['max_tokens']);
        $add($p2, 'max_tokens→max_completion_tokens');
        if (array_key_exists('temperature', $p2)) {
            $p3 = $p2;
            unset($p3['temperature']);
            $add($p3, 'max_completion_tokens بدون temperature');
        }
    }
    if ($mentionsMaxCompletion && ($unsupported || strpos($hay, 'unknown') !== false) && isset($payload['max_completion_tokens'])) {
        $p2 = $payload;
        $p2['max_tokens'] = (int)$payload['max_completion_tokens'];
        unset($p2['max_completion_tokens']);
        $add($p2, 'max_completion_tokens→max_tokens');
    }
    $mentionsTemp = strpos($hay, 'temperature') !== false;
    if ($mentionsTemp && (strpos($hay, 'unsupported') !== false || strpos($hay, 'not support') !== false
        || strpos($hay, 'only the default') !== false || strpos($hay, 'does not support') !== false
        || strpos($hay, 'invalid') !== false || strpos($hay, 'must be') !== false)
        && array_key_exists('temperature', $payload)) {
        $p2 = $payload;
        unset($p2['temperature'], $p2['top_p']);
        $add($p2, 'حذف temperature');
    }
    /* v10.444: سقف max_tokens بالاتر از حد مجاز مدل (مثلاً 9600 > 8192 یا 4096) */
    if (($mentionsMaxTokens || $mentionsMaxCompletion)
        && (strpos($hay, 'maximum') !== false || strpos($hay, 'less than') !== false
            || strpos($hay, 'at most') !== false || strpos($hay, 'exceed') !== false
            || strpos($hay, '<=') !== false)) {
        $cap = 2048;
        if (preg_match('~(?:<=|less than or equal to|at most|maximum[^\d]{0,20})(\d{3,6})~i', $hay, $cm)) {
            $cap = max(128, min(32768, (int)$cm[1]));
        }
        $p2 = $payload;
        if (isset($p2['max_tokens']) && (int)$p2['max_tokens'] > $cap) {
            $p2['max_tokens'] = $cap;
            $add($p2, 'کاهش max_tokens به ' . $cap);
        }
        if (isset($p2['max_completion_tokens']) && (int)$p2['max_completion_tokens'] > $cap) {
            $p2['max_completion_tokens'] = $cap;
            $add($p2, 'کاهش max_completion_tokens به ' . $cap);
        }
    }
    /* v10.444: مدل‌هایی که نقش system/developer را قبول نمی‌کنند (مثلاً gemma-2 یا o1-mini) */
    if ((strpos($hay, 'system') !== false || strpos($hay, 'developer instruction') !== false)
        && (strpos($hay, 'not supported') !== false || strpos($hay, 'unsupported') !== false
            || strpos($hay, 'not enabled') !== false || strpos($hay, 'invalid role') !== false)
        && !empty($payload['messages']) && is_array($payload['messages'])) {
        $sysTxt = []; $rest = [];
        foreach ($payload['messages'] as $mm) {
            if (!is_array($mm)) continue;
            if (in_array((string)($mm['role'] ?? ''), ['system', 'developer'], true)) {
                $c = is_string($mm['content'] ?? null) ? trim($mm['content']) : '';
                if ($c !== '') $sysTxt[] = $c;
            } else {
                $rest[] = $mm;
            }
        }
        if ($sysTxt && $rest) {
            $prefix = implode("\n\n", $sysTxt) . "\n\n";
            if (($rest[0]['role'] ?? '') === 'user' && is_string($rest[0]['content'] ?? null)) {
                $rest[0]['content'] = $prefix . $rest[0]['content'];
            } else {
                array_unshift($rest, ['role' => 'user', 'content' => trim($prefix)]);
            }
            $p2 = $payload;
            $p2['messages'] = $rest;
            $add($p2, 'ادغام نقش system در پیام user');
        }
    }
    /* v10.444: خطای پارامترهای اضافی در اعتبارسنج‌های سخت‌گیر (Mistral/Cohere 422 Extra inputs) */
    if ($code === 422 || strpos($hay, 'extra inputs') !== false || strpos($hay, 'additional properties') !== false
        || strpos($hay, 'unknown field') !== false || strpos($hay, 'unrecognized field') !== false) {
        $p2 = [];
        foreach (['model', 'messages', 'max_tokens', 'temperature', 'tools', 'tool_choice'] as $allowK) {
            if (array_key_exists($allowK, $payload)) $p2[$allowK] = $payload[$allowK];
        }
        if (!isset($p2['max_tokens']) && isset($payload['max_completion_tokens'])) {
            $p2['max_tokens'] = (int)$payload['max_completion_tokens'];
        }
        if (empty($p2['tools'])) unset($p2['tools'], $p2['tool_choice']);
        $add($p2, 'پاک‌سازی فیلدهای غیرمجاز 422');
    }
    return array_values($out);
}

