        'variations' => '.variations_form, .snappshop-variation-group',
    ];
}

function digikalaDetailSyntheticHtml(array $payloadData, string $sourceUrl): string {
    $prod = is_array($payloadData['product'] ?? null) ? $payloadData['product'] : $payloadData;
    $id = (int)($prod['id'] ?? 0);
    $sku = $id > 0 ? ('dkp-' . $id) : '';
    $title = normalize_text((string)($prod['title_fa'] ?? ($prod['title_en'] ?? '')));
    $brand = normalize_text((string)($prod['brand']['title_fa'] ?? ($prod['brand']['title_en'] ?? '')));
    $dkStatus = strtolower(trim((string)($prod['status'] ?? '')));
    $defVar = is_array($prod['default_variant'] ?? null) ? $prod['default_variant'] : [];
    $defPriceObj = is_array($defVar['price'] ?? null) ? $defVar['price'] : [];
    $bestToman = 0;
    $origToman = 0;
    $inStock = ($dkStatus === 'marketable');
    if ($inStock && !empty($defPriceObj)) {
        $sr = (int)round((float)($defPriceObj['selling_price'] ?? 0));
        $rr = (int)round((float)($defPriceObj['rrp_price'] ?? 0));
        if ($sr > 0) {
            $bestToman = intdiv($sr, 10);
            $origToman = $rr > $sr ? intdiv($rr, 10) : $bestToman;
        }
    }

    $imgs = [];
    $pushImg = static function($raw) use (&$imgs) {
        if (is_array($raw)) {
            if (isset($raw['url'])) {
                $u = is_array($raw['url']) ? (string)($raw['url'][0] ?? '') : (string)$raw['url'];
                $c = digikalaCleanImageUrl($u);
                if ($c !== '' && !in_array($c, $imgs, true)) $imgs[] = $c;
                return;
            }
            foreach ($raw as $v) {
                $u = is_array($v) ? (string)($v['url'][0] ?? ($v[0] ?? '')) : (string)$v;
                $c = digikalaCleanImageUrl($u);
                if ($c !== '' && !in_array($c, $imgs, true)) $imgs[] = $c;
            }
            return;
        }
        if (is_string($raw)) {
            $c = digikalaCleanImageUrl($raw);
            if ($c !== '' && !in_array($c, $imgs, true)) $imgs[] = $c;
        }
    };
    $pushImg($prod['images']['main'] ?? null);
    foreach ((array)($prod['images']['list'] ?? []) as $li) {
        $pushImg($li);
    }
    $mainImg = $imgs[0] ?? '';
    $galleryHtml = '';
    foreach ($imgs as $gi) {
        $galleryHtml .= '<div class="woocommerce-product-gallery__image image-thumbnail"><a href="' . h($gi) . '"><img src="' . h($gi) . '" data-large_image="' . h($gi) . '" alt="' . h($title) . '"></a></div>';
    }

    $attrMeta = [];
    $comboBest = [];
    $warrantyNames = [];
    $sellerNames = [];
    $allVariants = (array)($prod['variants'] ?? []);
    if (empty($allVariants) && !empty($defVar)) $allVariants = [$defVar];
    foreach ($allVariants as $vr) {
        if (!is_array($vr)) continue;
        $vSt = strtolower(trim((string)($vr['status'] ?? 'marketable')));
        $vAvail = ($vSt === 'marketable');
        $vpObj = is_array($vr['price'] ?? null) ? $vr['price'] : [];
        $vSell = $vAvail ? intdiv((int)round((float)($vpObj['selling_price'] ?? 0)), 10) : 0;
        $vOrig = $vAvail ? intdiv((int)round((float)($vpObj['rrp_price'] ?? 0)), 10) : 0;
        if ($vAvail && $vSell > 0 && $bestToman <= 0) {
            $bestToman = $vSell;
            $origToman = $vOrig > $vSell ? $vOrig : $vSell;
        }
        $wt = normalize_text((string)($vr['warranty']['title_fa'] ?? ($vr['warranty']['title'] ?? '')));
        if ($wt !== '' && !in_array($wt, $warrantyNames, true)) $warrantyNames[] = $wt;
        $st = normalize_text((string)($vr['seller']['title'] ?? ''));
        if ($st !== '' && !in_array($st, $sellerNames, true)) $sellerNames[] = $st;

        $varAttrs = [];
        if (is_array($vr['color'] ?? null)) {
            $cid = trim((string)($vr['color']['id'] ?? ''));
            $ctitle = normalize_text((string)($vr['color']['title'] ?? ''));
            if ($ctitle !== '') {
                $ckey = $cid !== '' ? $cid : md5($ctitle);
                if (!isset($attrMeta['color'])) $attrMeta['color'] = ['title' => 'رنگ', 'values' => []];
                if (!isset($attrMeta['color']['values'][$ckey])) {
                    $attrMeta['color']['values'][$ckey] = ['title' => $ctitle, 'hex' => trim((string)($vr['color']['hex_code'] ?? '')), 'price' => 0];
                }
                if ($vSell > 0 && ($attrMeta['color']['values'][$ckey]['price'] <= 0 || $vSell < $attrMeta['color']['values'][$ckey]['price'])) {
                    $attrMeta['color']['values'][$ckey]['price'] = $vSell;
                }
                $varAttrs['attribute_color'] = $ctitle;
            }
        }
        if (is_array($vr['size'] ?? null)) {
            $sid = trim((string)($vr['size']['id'] ?? ''));
            $stitle = normalize_text((string)($vr['size']['title'] ?? ''));
            if ($stitle !== '') {
                $skey = $sid !== '' ? $sid : md5($stitle);
                if (!isset($attrMeta['size'])) $attrMeta['size'] = ['title' => 'سایز', 'values' => []];
                if (!isset($attrMeta['size']['values'][$skey])) {
                    $attrMeta['size']['values'][$skey] = ['title' => $stitle, 'hex' => '', 'price' => 0];
                }
                if ($vSell > 0 && ($attrMeta['size']['values'][$skey]['price'] <= 0 || $vSell < $attrMeta['size']['values'][$skey]['price'])) {
                    $attrMeta['size']['values'][$skey]['price'] = $vSell;
                }
                $varAttrs['attribute_size'] = $stitle;
            }
        }
        if (!empty($varAttrs) && $vSell > 0) {
            $cSig = implode('|', $varAttrs);
            if (!isset($comboBest[$cSig]) || $vSell < (int)$comboBest[$cSig]['display_price']) {
                $comboBest[$cSig] = [
                    'variation_id'          => (string)($vr['id'] ?? ''),
                    'display_price'         => $vSell,
                    'display_regular_price' => $vOrig > $vSell ? $vOrig : $vSell,
                    'is_in_stock'           => $vAvail,
                    'attributes'            => $varAttrs,
                ];
            }
        }
    }
    if ($bestToman <= 0) $inStock = false;
    $wcVariationsJson = array_values($comboBest);
    $variationsHtml = '';
    if (!empty($attrMeta)) {
        $groupsHtml = '';
        $listGroupsHtml = '';
        foreach ($attrMeta as $aid => $gInfo) {
            if (empty($gInfo['values'])) continue;
            $optsHtml = '';
            $liHtml = '';
            foreach ($gInfo['values'] as $vInfo) {
                $vp = (int)($vInfo['price'] ?? 0);
                $pAttr = $vp > 0 ? (' data-price="' . $vp . '"') : '';
                $optsHtml .= '<option value="' . h($vInfo['title']) . '"' . $pAttr . '>' . h($vInfo['title']) . '</option>';
                $liHtml .= '<li data-value="' . h($vInfo['title']) . '"' . $pAttr . '>' . h($vInfo['title']) . '</li>';
            }
            $groupsHtml .= '<div class="variations snappshop-variation-group" data-name="' . h($gInfo['title']) . '" aria-label="' . h($gInfo['title']) . '">'
                . '<label>' . h($gInfo['title']) . '</label>'
                . '<select name="attribute_' . h($aid) . '" data-attribute_name="' . h($gInfo['title']) . '">' . $optsHtml . '</select>'
                . '</div>';
            $listGroupsHtml .= '<ul class="list-unstyled snappshop-variation-list" data-name="' . h($gInfo['title']) . '" aria-label="' . h($gInfo['title']) . '" style="display:none">' . $liHtml . '</ul>';
        }
        if ($groupsHtml !== '') {
            $varJsonAttr = $wcVariationsJson ? (' data-product_variations="' . h((string)json_encode($wcVariationsJson, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)) . '"') : '';
            $variationsHtml = '<form class="variations_form cart"' . $varJsonAttr . '>' . $groupsHtml . $listGroupsHtml . '</form>';
        }
    }

    $seenAttrTitles = [];
    $attrRows = '';
    $shortItems = '';
    $shortCount = 0;
    $weightVal = '';
    $appendSpecRow = static function(string $k, string $v) use (&$seenAttrTitles, &$attrRows, &$shortItems, &$shortCount, &$weightVal) {
        $k = normalize_text($k);
        $v = normalize_text($v);
        if ($k === '' || $v === '') return;
        $sig = mb_strtolower($k);
        if (isset($seenAttrTitles[$sig])) return;
        $seenAttrTitles[$sig] = true;
        $attrRows .= '<tr><th>' . h($k) . '</th><td>' . h($v) . '</td></tr>';
        if ($shortCount < 6 && mb_strlen($v) <= 120) {
            $shortItems .= '<li>' . h($k . ': ' . $v) . '</li>';
            $shortCount++;
        }
        if ($weightVal === '' && preg_match('~(?:^|\s)وزن(?:\s|$|‌)~u', $k)) {
            $weightVal = $v;
        }
    };
    foreach ((array)($prod['review']['attributes'] ?? []) as $ra) {
        if (!is_array($ra)) continue;
        $rk = (string)($ra['title'] ?? '');
        $rv = is_array($ra['values'] ?? null) ? implode('، ', array_filter(array_map('strval', $ra['values']))) : (string)($ra['values'] ?? '');
        $appendSpecRow($rk, $rv);
    }
    foreach ((array)($prod['specifications'] ?? []) as $sg) {
        if (!is_array($sg)) continue;
        foreach ((array)($sg['attributes'] ?? []) as $sa) {
            if (!is_array($sa)) continue;
            $sk = (string)($sa['title'] ?? '');
            $sv = is_array($sa['values'] ?? null) ? implode('، ', array_filter(array_map('strval', $sa['values']))) : (string)($sa['values'] ?? '');
            $appendSpecRow($sk, $sv);
        }
    }
    $_dkRawWeight = (int)($prod['dimension']['weight'] ?? ($prod['properties']['weight'] ?? 0));
    if ($weightVal === '' && $_dkRawWeight > 0) {
        $weightVal = $_dkRawWeight . ' گرم';
        $appendSpecRow('وزن', $weightVal);
    }
    if (!empty($warrantyNames)) {
        $appendSpecRow('گارانتی', implode('، ', array_slice($warrantyNames, 0, 3)));
    }
    if (!empty($sellerNames)) {
        $appendSpecRow('فروشنده', implode('، ', array_slice($sellerNames, 0, 4)));
    }

    $cats = [];
    $catLinksHtml = [];
    foreach ((array)($prod['breadcrumb'] ?? []) as $bc) {
        if (!is_array($bc)) continue;
        $ct = normalize_text((string)($bc['title'] ?? ''));
        if ($ct === '' || $ct === 'دیجی‌کالا' || $ct === 'دیجی کالا' || mb_strpos($ct, 'فروشگاه اینترنتی دیجی') !== false) continue;
        if ($ct === $title) continue;
        $curi = trim((string)($bc['url']['uri'] ?? ''));
        $cats[] = $ct;
        $catLinksHtml[] = '<a href="' . h($curi !== '' ? make_absolute_url($curi, 'https://www.digikala.com') : '#') . '">' . h($ct) . '</a>';
    }
    if (empty($cats) && !empty($prod['category']['title_fa'])) {
        $ct = normalize_text((string)$prod['category']['title_fa']);
        if ($ct !== '') {
            $cats[] = $ct;
            $catLinksHtml[] = '<a href="#">' . h($ct) . '</a>';
        }
    }

    $descRaw = trim((string)($prod['review']['description'] ?? ''));
    if ($descRaw !== '') {
        $descRaw = preg_replace('~<br\s*/?>~i', "\n", $descRaw) ?? $descRaw;
        $descRaw = preg_replace('~</p\s*>~i', "\n\n", $descRaw) ?? $descRaw;
        $descRaw = trim(html_entity_decode(strip_tags($descRaw), ENT_QUOTES | ENT_HTML5, 'UTF-8'));
    }
    $specHtml = $attrRows !== '' ? ('<table class="woocommerce-product-attributes shop_attributes"><tbody>' . $attrRows . '</tbody></table>') : '';
    $descNorm = $descRaw !== '' ? str_replace(["\r\n", "\r"], "\n", $descRaw) : '';
    $longInner = ($descNorm !== '' ? ('<div class="snappshop-desc-text">' . nl2br(h($descNorm), false) . '</div>') : '') . $specHtml;
    $descHtml = $longInner !== '' ? ('<div id="tab-description" class="product-description entry-content woocommerce-Tabs-panel--description">' . $longInner . '</div>') : '';
    $shortHtml = $shortItems !== '' ? ('<div class="short-description product-short-description woocommerce-product-details__short-description"><ul>' . $shortItems . '</ul></div>') : '';
    $tagItems = [];
    if ($brand !== '') $tagItems[] = '<a href="#">' . h($brand) . '</a>';
    foreach (array_slice($cats, -2) as $cTag) $tagItems[] = '<a href="#">' . h($cTag) . '</a>';
    $metaHtml = '<div class="product_meta">'
        . ($sku !== '' ? '<span class="sku_wrapper">SKU: <span class="sku">' . h($sku) . '</span></span> ' : '')
        . ($catLinksHtml ? '<span class="posted_in">' . implode('، ', $catLinksHtml) . '</span> ' : '')
        . ($tagItems ? '<span class="tagged_as">' . implode('، ', $tagItems) . '</span> ' : '')
        . ($brand !== '' ? '<span class="brand product-brand">' . h($brand) . '</span> ' : '')
        . ($weightVal !== '' ? '<span class="weight product-weight">' . h($weightVal) . '</span>' : '')
        . '</div>';
    $priceFormatted = ($inStock && $bestToman > 0) ? (number_format($bestToman) . ' تومان') : '';
    $ld = [
        '@context'    => 'https://schema.org',
        '@type'       => 'Product',
        'name'        => $title,
        'url'         => $sourceUrl,
        'sku'         => $sku,
        'image'       => $imgs,
        'description' => mb_substr($descRaw, 0, 2000),
    ];
    if ($brand !== '') $ld['brand'] = ['@type' => 'Brand', 'name' => $brand];
    if ($bestToman > 0) {
        $ld['offers'] = [
            '@type'         => 'Offer',
            'price'         => (string)$bestToman,
            'priceCurrency' => 'IRT',
            'availability'  => $inStock ? 'https://schema.org/InStock' : 'https://schema.org/OutOfStock',
            'url'           => $sourceUrl,
        ];
    }
    return '<!doctype html><html lang="fa" dir="rtl"><head><meta charset="UTF-8">'
        . '<title>' . h($title) . '</title>'
        . ($mainImg !== '' ? '<meta property="og:image" content="' . h($mainImg) . '">' : '')
        . ($bestToman > 0 ? '<meta property="product:price:amount" content="' . (int)$bestToman . '">' : '')
        . '<meta property="product:availability" content="' . ($inStock ? 'in stock' : 'out of stock') . '">'
        . '<style>body{font-family:tahoma,sans-serif;background:#f8fafc;color:#0f172a;margin:0;padding:20px;line-height:1.9}.single-product{max-width:980px;margin:0 auto;background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:22px}.product-gallery{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.product-gallery img{width:150px;height:150px;object-fit:contain;border:1px solid #e2e8f0;border-radius:10px;background:#fff}.price{font-size:18px;font-weight:800;color:#dc2626;margin:10px 0}.old-price{color:#94a3b8;font-weight:400;margin-left:8px}.shop_attributes{width:100%;border-collapse:collapse;margin-top:14px}.shop_attributes th,.shop_attributes td{border:1px solid #e2e8f0;padding:8px 12px;text-align:right}.shop_attributes th{background:#f1f5f9;width:220px}.snappshop-variation-group{margin:10px 0;padding:10px;background:#f8fafc;border:1px solid #cbd5e1;border-radius:10px}.product_meta span{display:inline-block;margin-left:12px;font-size:12px;color:#475569}</style>'
        . '<script type="application/ld+json">' . (string)json_encode($ld, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . '</script>'
        . '</head><body data-snappshop-api-detail="1" data-digikala-api-detail="1"><main class="product single-product"><div class="summary entry-summary">'
        . ($cats ? '<nav class="woocommerce-breadcrumb breadcrumb">' . h(implode(' / ', $cats)) . '</nav>' : '')
        . '<h1 class="product_title entry-title product-title">' . h($title) . '</h1>'
        . '<p class="price product-price">'
        . ($origToman > $bestToman ? '<del class="old-price">' . h(number_format($origToman) . ' تومان') . '</del> ' : '')
        . ($priceFormatted !== '' ? '<ins><span class="amount text-bold">' . h($priceFormatted) . '</span></ins>' : '')
        . '</p>'
        . '<p class="stock ' . ($inStock ? 'in-stock' : 'out-of-stock') . '">' . ($inStock ? 'موجود' : 'ناموجود') . '</p>'
        . $variationsHtml
        . $shortHtml
        . $metaHtml
        . '</div><div class="product-gallery gallery woocommerce-product-gallery images-box">' . $galleryHtml . '</div>'
        . $descHtml
        . '</main></body></html>';
}

function digikalaNeedsApiFallback(string $url, string $html): bool {
    if (!isDigikalaUrl($url)) return false;
    $route = digikalaParseTargetRoute($url);
    if (empty($route['ok'])) return false;
    if (trim($html) === '') return true;
    if (stripos($html, 'data-digikala-api-list="1"') !== false
        || stripos($html, 'data-digikala-api-detail="1"') !== false
        || stripos($html, 'data-jina-reader="1"') !== false) {
        return false;
    }
    if (($route['kind'] ?? '') === 'product') {
        return stripos($html, 'product:price:amount') === false && stripos($html, 'application/ld+json') === false;
    }
    return stripos($html, '/product/dkp-') === false;
}

function digikalaDetailFromSeoHtml(string $rawHtml, string $sourceUrl): string {
    if (trim($rawHtml) === '') return '';
    [$dom, $xp] = load_dom($rawHtml);
    $prod = null;
    $ldNodes = @$xp->query("//script[translate(@type,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz')='application/ld+json']");
    if ($ldNodes && $ldNodes->length) {
        foreach ($ldNodes as $ln) {
            $raw = trim((string)($ln->textContent ?? ''));
            if ($raw === '') continue;
            $j = @json_decode($raw, true);
            if (!is_array($j)) continue;
            $items = isset($j['@graph']) && is_array($j['@graph']) ? $j['@graph'] : [$j];
            foreach ($items as $it) {
                if (!is_array($it)) continue;
                $tp = $it['@type'] ?? '';
                $isProd = is_array($tp) ? in_array('Product', $tp, true) : (stripos((string)$tp, 'Product') !== false);
                if ($isProd) { $prod = $it; break 2; }
            }
        }
    }
    if (!is_array($prod)) return '';
    $title = normalize_text((string)($prod['name'] ?? ''));
    if ($title === '') return '';
    $offersRaw = $prod['offers'] ?? [];
    $offerList = isset($offersRaw[0]) ? $offersRaw : (is_array($offersRaw) && !empty($offersRaw) ? [$offersRaw] : []);
    $bestRial = 0;
    $inStock = false;
    foreach ($offerList as $of) {
        if (!is_array($of)) continue;
        $pNum = (int)round((float)($of['price'] ?? ($of['lowPrice'] ?? 0)));
        $cur = strtoupper(trim((string)($of['priceCurrency'] ?? 'IRR')));
        $rial = ($cur === 'IRT') ? ($pNum * 10) : $pNum;
        $avail = strtolower((string)($of['availability'] ?? ''));
        $avOk = ($avail === '' || strpos($avail, 'instock') !== false || strpos($avail, 'in_stock') !== false);
        if ($avOk && $rial > 0) {
            $inStock = true;
            if ($bestRial <= 0 || $rial < $bestRial) $bestRial = $rial;
        }
    }
    $imgsRaw = $prod['image'] ?? [];
    if (is_string($imgsRaw)) $imgsRaw = [$imgsRaw];
    $cleanImgs = [];
    foreach ((array)$imgsRaw as $im) {
        if (is_string($im) && trim($im) !== '') $cleanImgs[] = ['url' => [digikalaCleanImageUrl($im)]];
    }
    if (empty($cleanImgs)) {
        $ogImgNodes = @$xp->query("//meta[@property='og:image']/@content");
        if ($ogImgNodes && $ogImgNodes->length) {
            $ogU = digikalaCleanImageUrl(trim((string)$ogImgNodes->item(0)->nodeValue));
            if ($ogU !== '') $cleanImgs[] = ['url' => [$ogU]];
        }
    }
    if ($bestRial <= 0 && empty($cleanImgs)) return '';
    $pidNum = 0;
    if (preg_match('~/product/dkp-(\d+)~i', $sourceUrl, $pm)) $pidNum = (int)$pm[1];
    $brandName = is_array($prod['brand'] ?? null) ? (string)($prod['brand']['name'] ?? '') : (string)($prod['brand'] ?? '');
    return digikalaDetailSyntheticHtml([
        'product' => [
            'id' => $pidNum,
            'title_fa' => $title,
            'status' => $inStock ? 'marketable' : 'out_of_stock',
            'brand' => ['title_fa' => normalize_text($brandName)],
            'images' => [
                'main' => $cleanImgs[0] ?? ['url' => []],
                'list' => array_slice($cleanImgs, 1),
            ],
            'default_variant' => $bestRial > 0 ? ['price' => ['selling_price' => $bestRial, 'rrp_price' => $bestRial]] : [],
            'review' => ['description' => (string)($prod['description'] ?? '')],
        ],
    ], $sourceUrl);
}

function fetch_html_digikala_api(string $url, int $timeout = 25, array $prev = [], int $redirectDepth = 0): array {
    $route = digikalaParseTargetRoute($url);
    $target = (string)($route['url'] ?? $url);
    if (empty($route['ok'])) {
        return ['ok' => false, 'error' => (string)($prev['error'] ?? 'آدرس دیجی‌کالا پشتیبانی نمی‌شود'), 'code' => (int)($prev['code'] ?? 0), 'url' => $target, 'html' => '', 'mode' => 'digikala-api'];
    }
    if (($route['kind'] ?? '') === 'product') {
        $pid = rawurlencode((string)($route['product_id'] ?? ''));
        $epCandidates = ['v2/product/' . $pid . '/', 'v1/product/' . $pid . '/'];
        $lastRes = [];
        $lastKeys = [];
        foreach ($epCandidates as $ep) {
            $res = digikalaApiHttpRequest($ep, $timeout);
            $lastRes = $res;
            $d = is_array($res['data']['data'] ?? null) ? $res['data']['data'] : [];
            if (is_array($d)) $lastKeys = array_keys($d);
            if ($redirectDepth < 2 && !empty($res['ok'])) {
                $redirUri = (string)($d['redirect_url']['uri'] ?? ($res['data']['redirect_url']['uri'] ?? ''));
                if ($redirUri !== '' && preg_match('~/product/dkp-(\d+)~i', $redirUri, $rm) && (string)$rm[1] !== (string)($route['product_id'] ?? '')) {
                    $redirUrl = 'https://www.digikala.com/product/dkp-' . $rm[1] . '/';
                    return fetch_html_digikala_api($redirUrl, $timeout, $prev, $redirectDepth + 1);
                }
            }
            $prodNode = is_array($d['product'] ?? null) ? $d['product'] : ((isset($d['id']) && (isset($d['title_fa']) || isset($d['title_en']))) ? $d : []);
            if (!empty($res['ok']) && !empty($prodNode) && (isset($prodNode['id']) || isset($prodNode['title_fa']) || isset($prodNode['images']))) {
                if (empty($d['product'])) $d['product'] = $prodNode;
                $html = digikalaDetailSyntheticHtml($d, $target);
                return [
                    'ok'                  => true,
                    'error'               => '',
                    'code'                => (int)($res['code'] ?? 200),
                    'url'                 => $target,
                    'html'                => $html,
                    'mode'                => 'digikala-api',
                    'digikala_api'        => (string)($res['api_url'] ?? ''),
                    'digikala_api_via'    => (string)($res['via'] ?? 'direct'),
                    'digikala_route_kind' => 'product',
                    'jina_product_count'  => 1,
                ];
            }
            /* v10.475: روی ۴۰۴ نسخهٔ v2 حلقه را قطع نکن تا v1/product/{pid}/ هم امتحان شود */
        }
        /* v10.475: پشتیبان وب برای تشخیص ریدایرکت dkp جدید یا استخراج SEO/JSON-LD از صفحهٔ وب */
        if ($redirectDepth < 2 && function_exists('curl_init')) {
            $chWeb = @curl_init($target);
            if ($chWeb) {
                @curl_setopt_array($chWeb, [
                    CURLOPT_RETURNTRANSFER => true,
                    CURLOPT_FOLLOWLOCATION => true,
                    CURLOPT_MAXREDIRS      => 4,
                    CURLOPT_TIMEOUT        => max(5, min(12, $timeout)),
                    CURLOPT_CONNECTTIMEOUT => 5,
                    CURLOPT_SSL_VERIFYPEER => false,
                    CURLOPT_SSL_VERIFYHOST => 0,
                    CURLOPT_ENCODING       => '',
                    CURLOPT_RANGE          => '0-262143',
                    CURLOPT_USERAGENT      => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36',
                ]);
                $webBody = @curl_exec($chWeb);
                $webCode = (int)@curl_getinfo($chWeb, CURLINFO_HTTP_CODE);
                $effWebUrl = (string)@curl_getinfo($chWeb, CURLINFO_EFFECTIVE_URL);
                @curl_close($chWeb);
                if ($effWebUrl !== '' && preg_match('~/product/dkp-(\d+)~i', $effWebUrl, $wm) && (string)$wm[1] !== (string)($route['product_id'] ?? '')) {
                    return fetch_html_digikala_api('https://www.digikala.com/product/dkp-' . $wm[1] . '/', $timeout, $prev, $redirectDepth + 1);
                }
                if (is_string($webBody) && $webBody !== '' && in_array($webCode, [200, 206], true)) {
                    $seoSynth = digikalaDetailFromSeoHtml($webBody, $effWebUrl !== '' ? $effWebUrl : $target);
                    if ($seoSynth !== '') {
                        return [
                            'ok'                  => true,
                            'error'               => '',
                            'code'                => 200,
                            'url'                 => $effWebUrl !== '' ? $effWebUrl : $target,
                            'html'                => $seoSynth,
                            'mode'                => 'digikala-seo-fallback',
                            'digikala_route_kind' => 'product',
                            'jina_product_count'  => 1,
                        ];
                    }
                }
            }
        }
        $errMsg = trim((string)($lastRes['error'] ?? ''));
        if ($errMsg === '') {
            $errMsg = 'Digikala product API empty (status=' . (int)($lastRes['api_status'] ?? ($lastRes['code'] ?? 0))
                . ($lastKeys ? ', keys=' . implode(',', array_slice($lastKeys, 0, 6)) : '') . ')';
        }
        return [
            'ok'    => false,
            'error' => $errMsg,
            'code'  => (int)($lastRes['code'] ?? 0),
            'url'   => $target,
            'html'  => '',
            'mode'  => 'digikala-api',
        ];
    }

    $reqPage = max(1, (int)($route['page'] ?? 1));
    if ($reqPage > 100) {
        return [
            'ok'                    => true,
            'error'                 => '',
            'code'                  => 200,
            'url'                   => $target,
            'html'                  => digikalaSyntheticListHtml([], $target, 'سقف ۱۰۰ صفحهٔ API دیجی‌کالا', ['current_page' => $reqPage, 'total_pages' => 100]),
            'mode'                  => 'digikala-api',
            'digikala_api_via'      => 'ceiling-guard',
            'digikala_route_kind'   => (string)($route['kind'] ?? 'category'),
            'digikala_end_of_pages' => true,
            'digikala_total_pages'  => 100,
            'jina_product_count'    => 0,
        ];
    }

    $ep = digikalaBuildApiEndpoint($route);
    $res = digikalaApiHttpRequest($ep, $timeout);
    if (empty($res['ok']) && ($route['kind'] ?? '') === 'category_brand') {
        $fbRoute = $route;
        $fbRoute['kind'] = 'category';
        $fbRoute['filters']['q'] = trim(((string)($fbRoute['filters']['q'] ?? '')) . ' ' . str_replace('-', ' ', (string)($route['brand_slug'] ?? '')));
        $resFb = digikalaApiHttpRequest(digikalaBuildApiEndpoint($fbRoute), $timeout);
        if (!empty($resFb['ok'])) $res = $resFb;
    } elseif (empty($res['ok']) && ($route['kind'] ?? '') === 'category_or_search') {
        $fbRoute = $route;
        $fbRoute['kind'] = 'search';
        $fbRoute['filters']['q'] = str_replace('-', ' ', (string)($route['category_slug'] ?? ''));
        $resFb = digikalaApiHttpRequest(digikalaBuildApiEndpoint($fbRoute), $timeout);
        if (!empty($resFb['ok'])) $res = $resFb;
    }

    if (!empty($res['ok']) && is_array($res['data'] ?? null)) {
        $rawPayload = $res['data'];
        $redirUri = trim((string)($rawPayload['data']['redirect_url']['uri'] ?? ($rawPayload['redirect_url']['uri'] ?? '')));
        if ($redirUri !== '' && $redirectDepth < 2 && empty($rawPayload['data']['products'])) {
            $redirUrl = make_absolute_url($redirUri, 'https://www.digikala.com');
            if ($reqPage > 1) {
                $redirUrl .= (strpos($redirUrl, '?') === false ? '?' : '&') . 'page=' . $reqPage;
            }
            return fetch_html_digikala_api($redirUrl, $timeout, $prev, $redirectDepth + 1);
        }
        $apiMeta = [];
        $ps = digikalaProductsFromApiPayload($rawPayload, $target, $reqPage, $apiMeta);
        $totPages = (int)($apiMeta['total_pages'] ?? 0);
        if (empty($ps) && $reqPage > 1 && empty($apiMeta['exceeded_total_pages']) && empty($apiMeta['all_rows_out_of_stock']) && (int)($apiMeta['raw_rows_count'] ?? 0) === 0 && $totPages > 0 && $reqPage < $totPages) {
            usleep(300000);
            $resRetry = digikalaApiHttpRequest($ep, $timeout);
            if (!empty($resRetry['ok']) && is_array($resRetry['data'] ?? null)) {
                $res = $resRetry;
                $apiMeta = [];
                $ps = digikalaProductsFromApiPayload($res['data'], $target, $reqPage, $apiMeta);
                $totPages = (int)($apiMeta['total_pages'] ?? $totPages);
            }
        }
        if (!empty($ps)) {
            $note = 'Digikala API (' . (string)($route['kind'] ?? 'list') . ' · via ' . (string)($res['via'] ?? 'direct') . ')';
            return [
                'ok'                    => true,
                'error'                 => '',
                'code'                  => (int)($res['code'] ?? 200),
                'url'                   => $target,
                'html'                  => digikalaSyntheticListHtml($ps, $target, $note, $apiMeta),
                'mode'                  => 'digikala-api',
                'digikala_api'          => (string)($res['api_url'] ?? ''),
                'digikala_api_via'      => (string)($res['via'] ?? 'direct'),
                'digikala_route_kind'   => (string)($route['kind'] ?? 'category'),
                'digikala_total_pages'  => $totPages,
                'digikala_end_of_pages' => false,
                'jina_product_count'    => count($ps),
            ];
        }
        /* v10.475: اگر هیچ ردیف خامی پیش از total_pages نیامد، خطای موقت API است نه پایان طبیعی کاتالوگ */
        if ($reqPage > 1 && empty($apiMeta['exceeded_total_pages']) && empty($apiMeta['all_rows_out_of_stock']) && (int)($apiMeta['raw_rows_count'] ?? 0) === 0 && $totPages > 0 && $reqPage < $totPages) {
            return [
                'ok'                 => false,
                'error'              => 'Digikala API empty page ' . $reqPage . ' before total_pages=' . $totPages,
                'code'               => (int)($res['code'] ?? 200),
                'url'                => $target,
                'html'               => '',
                'mode'               => 'digikala-api',
                'jina_product_count' => 0,
            ];
        }
        if ($reqPage > 1 || !empty($apiMeta['all_rows_out_of_stock'])) {
            $endPages = !empty($apiMeta['all_rows_out_of_stock']) ? max(1, $reqPage - 1) : ($totPages > 0 ? $totPages : max(1, $reqPage - 1));
            return [
                'ok'                    => true,
                'error'                 => '',
                'code'                  => (int)($res['code'] ?? 200),
                'url'                   => $target,
                'html'                  => digikalaSyntheticListHtml([], $target, 'پایان کالاهای موجود دیجی‌کالا در صفحهٔ ' . $endPages, $apiMeta),
                'mode'                  => 'digikala-api',
                'digikala_api'          => (string)($res['api_url'] ?? ''),
                'digikala_api_via'      => (string)($res['via'] ?? 'direct'),
                'digikala_route_kind'   => (string)($route['kind'] ?? 'category'),
                'digikala_end_of_pages' => true,
                'digikala_total_pages'  => $endPages,
                'jina_product_count'    => 0,
            ];
        }
        return [
            'ok'                 => false,
            'error'              => 'Digikala API returned 0 products for page 1',
            'code'               => (int)($res['code'] ?? 200),
            'url'                => $target,
            'html'               => '',
            'mode'               => 'digikala-api',
            'jina_product_count' => 0,
        ];
    }
    return [
        'ok'                 => false,
        'error'              => (string)($res['error'] ?? 'Digikala API failed'),
        'code'               => (int)($res['code'] ?? 0),
        'url'                => $target,
        'html'               => '',
        'mode'               => 'digikala-api',
        'jina_product_count' => 0,
    ];
}

function snappshopNeedsApiFallback(string $url, string $html): bool {
    if (!isSnappshopUrl($url)) return false;
    $route = snappshopParseTargetRoute($url);
    if (empty($route['ok'])) return false;
    if (trim($html) === '') return true;
    if (stripos($html, 'data-snappshop-api-detail="1"') !== false || stripos($html, 'data-jina-reader="1"') !== false || stripos($html, 'data-snappshop-fallback="1"') !== false) {
        return false;
    }
    if (($route['kind'] ?? '') === 'product') {
        return stripos($html, 'product:price:amount') === false && stripos($html, 'application/ld+json') === false;
    }
    return stripos($html, '/product/snp-') === false;
}

function fetch_html_snappshop_public_fallback(string $url, int $timeout = 25, array $prev = []): array {
    if (!isSnappshopUrl($url)) {
        return ['ok' => false, 'error' => 'not snappshop', 'code' => 0, 'url' => $url, 'html' => '', 'mode' => ''];
    }
    $timeout = max(8, min(60, $timeout));
    $last = ['ok' => false, 'error' => (string)($prev['error'] ?? 'Empty'), 'code' => (int)($prev['code'] ?? 0), 'url' => $url, 'html' => '', 'mode' => 'snappshop-public'];
    $oldSkip = $GLOBALS['_s4SkipSnappApiInFetchHtml'] ?? null;
    $GLOBALS['_s4SkipSnappApiInFetchHtml'] = true;
    $raw = fetch_html($url, $timeout);
    if ($oldSkip === null) unset($GLOBALS['_s4SkipSnappApiInFetchHtml']); else $GLOBALS['_s4SkipSnappApiInFetchHtml'] = $oldSkip;
    $raw['snappshop_public_fallback'] = 'fetch-html';
    $rawBody = (string)($raw['html'] ?? '');
    if (!empty($raw['ok']) && !empty(parse_snappshop_products_html($rawBody, $url))) {
        $raw['url'] = $url;
        $raw['mode'] = 'snappshop-fetch-html';
        return $raw;
    }
    $last = $raw + $last;
    $jr = fetch_html_jina_reader($url, $timeout, $prev);
    $body = (string)($jr['html'] ?? '');
    if (!empty($jr['ok']) && trim($body) !== '') {
        $ps = snappshopProductsFromReaderText($body, $url);
        if (empty($ps)) $ps = parse_snappshop_products_html($body, $url);
        if (!empty($ps)) {
            $viaLabel = (string)($jr['jina_reader_via'] ?? '') === 'snappshop-apix' ? 'SnappShop Public API' : 'Jina Reader';
            $modeLabel = (string)($jr['jina_reader_via'] ?? '') === 'snappshop-apix' ? 'snappshop-apix' : 'snappshop-jina-reader';
            return ['ok' => true, 'error' => '', 'code' => (int)($jr['code'] ?? 200), 'url' => $url,
                    'html' => snappshopSyntheticHtml($ps, $url, $viaLabel), 'mode' => $modeLabel,
                    'snappshop_public_fallback' => $modeLabel === 'snappshop-apix' ? 'snappshop-apix' : 'jina-reader',
                    'jina_reader' => (string)($jr['jina_reader'] ?? ''),
                    'jina_reader_via' => (string)($jr['jina_reader_via'] ?? ''), 'jina_product_count' => count($ps),
                    'jina_reader_trace' => is_array($jr['jina_reader_trace'] ?? null) ? $jr['jina_reader_trace'] : [],
                    'jina_reader_modes' => is_array($jr['jina_reader_modes'] ?? null) ? $jr['jina_reader_modes'] : [],
                    'source_error' => (string)($prev['error'] ?? '')];
        }
        if (stripos($body, 'data-snappshop-api-detail="1"') !== false || !empty($jr['snappshop_end_of_pages'])) {
            return $jr;
        }
    }
    $last = $jr + $last;
    $apiDirect = fetch_html_snappshop_api($url, $timeout, $last);
    if (!empty($apiDirect['ok'])) {
        $apiDirect['snappshop_public_fallback'] = 'snappshop-apix';
        $apiDirect['jina_reader_trace'] = is_array($jr['jina_reader_trace'] ?? null) ? $jr['jina_reader_trace'] : [];
        $apiDirect['jina_reader_modes'] = is_array($jr['jina_reader_modes'] ?? null) ? $jr['jina_reader_modes'] : [];
        return $apiDirect;
    }
    return ['ok' => false, 'error' => trim((string)($last['error'] ?? '')) !== '' ? (string)$last['error'] : (string)($prev['error'] ?? 'Empty'),
            'code' => (int)($last['code'] ?? ($prev['code'] ?? 0)), 'url' => $url, 'html' => '',
            'mode' => (string)($last['mode'] ?? 'snappshop-jina-reader'), 'snappshop_public_fallback' => (string)($last['snappshop_public_fallback'] ?? 'jina-reader'),
            'jina_reader' => (string)($last['jina_reader'] ?? ''), 'jina_reader_via' => (string)($last['jina_reader_via'] ?? ''),
            'jina_product_count' => (int)($last['jina_product_count'] ?? 0),
            'jina_reader_trace' => is_array($last['jina_reader_trace'] ?? null) ? $last['jina_reader_trace'] : [],
            'jina_reader_modes' => is_array($last['jina_reader_modes'] ?? null) ? $last['jina_reader_modes'] : []];
}


/* v9.00: راه عبور برای سایت مبدأ — DoH / IP دستی / پروکسی / Worker.
   v9.77: اگر تیک «استفاده از روش‌های جایگزین» روشن باشد و روشِ اصلی شکست
   بخورد (تایم‌اوت، اتصال، بلاک ۴۰۳/۴۲۹)، به ترتیبِ روش‌هایِ فعالِ دیگر هم
   امتحان می‌شود تا اولین موفق برگردد. */
function fetch_html(string $url, int $timeout = 25): array {
    /* v10.453: صفحات محصول اسنپ‌شاپ (snappshop.ir/product/snp-*) همیشه پوستهٔ خالی
       Next.js CSR هستند و گالری/تنوع در HTML خام آن‌ها وجود ندارد؛ ارسال هزاران
       درخواست بی‌فایده به snappshop.ir پیش از apix باعث فعال شدن WAF 429 می‌شود.
       مستقیماً سراغ fetch_html_snappshop_api برویم. */
    if (empty($GLOBALS['_s4SkipSnappApiInFetchHtml']) && function_exists('isSnappshopUrl') && isSnappshopUrl($url) && function_exists('snappshopParseTargetRoute')) {
        $__snFastRoute = snappshopParseTargetRoute($url);
        if (($__snFastRoute['kind'] ?? '') === 'product') {
            $__snDirectPdp = fetch_html_snappshop_api($url, $timeout, []);
            if (!empty($__snDirectPdp['ok'])) return $__snDirectPdp;
            /* v10.457: اگر سطل نرخ apix روی 429 است، ارسال درخواست اضافی به snappshop.ir
               (که پشت همان Sotoon CDN است و فقط پوستهٔ خالی customer_production_ir_csr برمی‌گرداند)
               فقط پنجرهٔ لغزندهٔ CDN را ریست می‌کند؛ بلافاصله متادیتای cooldown را برگردان. */
            if (empty($__snDirectPdp['snappshop_rate_limited']) && (int)($__snDirectPdp['code'] ?? 0) !== 429) {
                $__seoNet = function_exists('loadConnections') ? srcNetCfg() : ['mode'=>'direct','ipv4'=>true];
                $__seoRaw = srcNetFetchAttempt($url, min(12, $timeout), $__seoNet, 'direct');
                if (!empty($__seoRaw['ok']) && !empty($__seoRaw['html']) && function_exists('snappshopDetailFromSeoHtml')) {
                    $__seoSynth = snappshopDetailFromSeoHtml((string)$__seoRaw['html'], $url);
                    if ($__seoSynth !== '') {
                        return ['ok' => true, 'error' => '', 'code' => 200, 'url' => $url, 'html' => $__seoSynth, 'mode' => 'snappshop-seo-ldjson'];
                    }
                }
            }
            return ['ok' => false,
                    'error' => trim((string)($__snDirectPdp['error'] ?? '')) !== '' ? (string)$__snDirectPdp['error'] : 'SnappShop apix PDP failed',
                    'code' => (int)($__snDirectPdp['code'] ?? 0),
                    'url' => $url,
                    'html' => '',
                    'mode' => 'snappshop-apix',
                    'snappshop_rate_limited' => !empty($__snDirectPdp['snappshop_rate_limited']) || ((int)($__snDirectPdp['code'] ?? 0) === 429),
                    'snappshop_deferred' => !empty($__snDirectPdp['snappshop_deferred']),
                    'snappshop_cooldown_sec' => (int)($__snDirectPdp['snappshop_cooldown_sec'] ?? 0)];
        }
    }
    if (empty($GLOBALS['_s4SkipDigikalaApiInFetchHtml']) && function_exists('isDigikalaUrl') && isDigikalaUrl($url) && function_exists('digikalaParseTargetRoute')) {
        $__dkFastRoute = digikalaParseTargetRoute($url);
        if (($__dkFastRoute['kind'] ?? '') === 'product') {
            $__dkDirectPdp = fetch_html_digikala_api($url, $timeout, []);
            if (!empty($__dkDirectPdp['ok'])) return $__dkDirectPdp;
            if ((int)($__dkDirectPdp['code'] ?? 0) === 404) {
                return [
                    'ok'    => false,
                    'error' => trim((string)($__dkDirectPdp['error'] ?? '')) !== '' ? (string)$__dkDirectPdp['error'] : 'Digikala API PDP 404',
                    'code'  => 404,
                    'url'   => $url,
                    'html'  => '',
                    'mode'  => 'digikala-api',
                ];
            }
        }
    }
    $__profileForcedDirect = array_key_exists('_srcNetProfileIndirect', $GLOBALS) && empty($GLOBALS['_srcNetProfileIndirect']);
    $__srcNet = function_exists('loadConnections') ? srcNetCfg() : ['mode'=>'direct','gap_ms'=>0,'hosts'=>'','fallback'=>false];
    $parsed = parse_url($url); $__srcHost = strtolower((string)($parsed['host'] ?? ''));
    srcPace($__srcHost, (int)($__srcNet['gap_ms'] ?? 0));

    $modes = [];
    // روش اصلی
    if (srcNetApplies($__srcNet, $__srcHost)) $modes[] = (string)$__srcNet['mode'];
    // روش‌های جایگزینِ فعال (فقط اگر تیک روشن باشد)
    if (!empty($__srcNet['fallback'])) {
        $order = ['doh','dns','proxy','worker'];
        foreach ($order as $m) {
            if (in_array($m, $modes, true)) continue;
            if ($m === 'dns'    && trim((string)($__srcNet['resolve_ip'] ?? '')) === '') continue;
            if ($m === 'doh'    && trim((string)($__srcNet['doh_url'] ?? '')) === '') continue;
            if ($m === 'proxy'  && trim((string)($__srcNet['proxy'] ?? '')) === '') continue;
            if ($m === 'worker' && trim((string)($__srcNet['worker_url'] ?? '')) === '') continue;
            $modes[] = $m;
        }
    }
    if (empty($modes)) $modes[] = 'direct';

    $last = null;
    foreach ($modes as $m) {
        $last = srcNetFetchAttempt($url, $timeout, $__srcNet, $m);
        $emallsNoProducts = !empty($last['ok']) && function_exists('isEmallsUrl') && isEmallsUrl($url)
            && function_exists('emallsNeedsProductSignal') && emallsNeedsProductSignal($url)
            && stripos((string)($last['html'] ?? ''), '~id~') === false;
        $snappEmptyShell = empty($GLOBALS['_s4SkipSnappApiInFetchHtml']) && !empty($last['ok'])
            && function_exists('snappshopNeedsApiFallback') && snappshopNeedsApiFallback($url, (string)($last['html'] ?? ''));
        $digikalaEmptyShell = empty($GLOBALS['_s4SkipDigikalaApiInFetchHtml']) && !empty($last['ok'])
            && function_exists('digikalaNeedsApiFallback') && digikalaNeedsApiFallback($url, (string)($last['html'] ?? ''));
        if (!empty($last['ok']) && !$emallsNoProducts && !$snappEmptyShell && !$digikalaEmptyShell) return $last;
        if ($digikalaEmptyShell) {
            $last['digikala_empty_shell'] = true;
            $__dkApi = fetch_html_digikala_api($url, $timeout, is_array($last) ? $last : []);
            if (!empty($__dkApi['ok'])) return $__dkApi;
            $last['ok'] = false;
            $last['code'] = (int)($__dkApi['code'] ?? ($last['code'] ?? 0));
            $last['error'] = trim((string)($__dkApi['error'] ?? '')) !== '' ? (string)$__dkApi['error'] : 'Digikala empty JS shell (API unavailable)';
            return $last;
        }
        if ($snappEmptyShell) {
            $last['snappshop_empty_shell'] = true;
            $__snApi = fetch_html_snappshop_api($url, $timeout, is_array($last) ? $last : []);
            if (!empty($__snApi['ok'])) return $__snApi;
            /* v10.453: هرگز پوستهٔ خالی CSR را با ok=true برنگردان؛ وگرنه فاز ۲
               فکر می‌کند صفحهٔ محصول قیمت ندارد و کالا را به اشتباه ناموجود می‌کند! */
            $last['ok'] = false;
            $last['code'] = (int)($__snApi['code'] ?? ($last['code'] ?? 0));
            $last['error'] = trim((string)($__snApi['error'] ?? '')) !== '' ? (string)$__snApi['error'] : 'SnappShop empty JS shell (apix unavailable)';
            return $last;
        }
        if ($emallsNoProducts) {
            /* v10.249: HTTP 200 پوسته/صفحهٔ ضدربات پاسخ منطقی نیست. قبلاً break
               می‌کرد و proxy/worker بعدی هرگز امتحان نمی‌شد. */
            $last['error'] = 'Emalls HTTP 200 without product links';
            $last['emalls_empty_shell'] = true;
            continue;
        }
        // اگر خطای قطعیِ منطقی (مثل ۴۰۴/۴۰۰) بود، امتحانِ روشِ دیگر بی‌فایده است
        if ($last['code'] > 0 && !in_array($last['code'], [403, 429], true)) break;
    }

    /* v10.252: اگر transport مستقیم حتی پاسخ HTTP نگرفت، DNS رمزگذاری‌شده
       را خودکار یک بار امتحان کن. این برای رکورد DNS/مسیر قدیمی دیتاسنتر است،
       نه دورزدن تنظیم پروفایل؛ فقط ایمالز و فقط code=0. */
    if(function_exists('isEmallsUrl')&&isEmallsUrl($url)&&(int)($last['code']??0)===0){
        $__dohNet=$__srcNet;$__dohNet['doh_url']=trim((string)($__dohNet['doh_url']??''))?:'https://cloudflare-dns.com/dns-query';
        $__doh=srcNetFetchAttempt($url,min(20,$timeout),$__dohNet,'doh');$__doh['emalls_auto_doh']=true;
        $__dohGood=!empty($__doh['ok'])&&(!emallsNeedsProductSignal($url)||stripos((string)($__doh['html']??''),'~id~')!==false);
        if($__dohGood)return $__doh;$last=$__doh;
    }

    /* v10.191: بعضی پروفایل‌های قدیمیِ ایمالز با «اتصال غیرمستقیم» خاموش
       ذخیره شده‌اند. آن حالت عمداً تنظیم سراسری src_net را به direct تبدیل
       می‌کند؛ اما ایمالز ممکن است direct را با خطای TLS/بلاک IP ببندد و خروجی
       بصری/استخراج صفر شود. فقط برای ایمالز و فقط بعد از شکست direct، یک بار
       تنظیم سراسریِ proxy/worker/DoH را بدون اجبارِ پروفایل امتحان می‌کنیم. */
    if ($__profileForcedDirect && function_exists('isEmallsUrl') && isEmallsUrl($url)) {
        $__oldProfileIndirect = $GLOBALS['_srcNetProfileIndirect'] ?? null;
        unset($GLOBALS['_srcNetProfileIndirect']);
        $__srcNet2 = function_exists('loadConnections') ? srcNetCfg() : ['mode'=>'direct','gap_ms'=>0,'hosts'=>'','fallback'=>false];
        $__modes2 = [];
        if (srcNetApplies($__srcNet2, $__srcHost)) $__modes2[] = (string)$__srcNet2['mode'];
        if (!empty($__srcNet2['fallback'])) {
            foreach (['doh','dns','proxy','worker'] as $__m) {
                if (in_array($__m, $__modes2, true)) continue;
                if ($__m === 'dns'    && trim((string)($__srcNet2['resolve_ip'] ?? '')) === '') continue;
                if ($__m === 'doh'    && trim((string)($__srcNet2['doh_url'] ?? '')) === '') continue;
                if ($__m === 'proxy'  && trim((string)($__srcNet2['proxy'] ?? '')) === '') continue;
                if ($__m === 'worker' && trim((string)($__srcNet2['worker_url'] ?? '')) === '') continue;
                $__modes2[] = $__m;
            }
        }
        foreach ($__modes2 as $__m) {
            if ($__m === 'direct') continue;
            $__try = srcNetFetchAttempt($url, $timeout, $__srcNet2, $__m);
            $__try['profile_direct_emalls_fallback'] = true;
            $__hasProducts = !emallsNeedsProductSignal($url) || stripos((string)($__try['html'] ?? ''), '~id~') !== false;
            if (!empty($__try['ok']) && $__hasProducts) { $GLOBALS['_srcNetProfileIndirect'] = $__oldProfileIndirect; return $__try; }
            if (!empty($__try['ok']) && !$__hasProducts) {
                $__try['ok'] = false; $__try['error'] = 'Emalls fallback returned HTTP 200 without product links';
                $__try['emalls_empty_shell'] = true; $last = $__try;
                continue;
            }
            $last = $__try;
            if ($__try['code'] > 0 && !in_array($__try['code'], [403, 429], true)) break;
        }
        $GLOBALS['_srcNetProfileIndirect'] = $__oldProfileIndirect;
    }
    if (function_exists('fetch_html_emalls_public_fallback') && function_exists('isEmallsUrl') && isEmallsUrl($url)) {
        $__pub = fetch_html_emalls_public_fallback($url, $timeout, is_array($last) ? $last : []);
        if (!empty($__pub['ok'])) return $__pub;
        if (is_array($__pub) && trim((string)($__pub['error'] ?? '')) !== '') $last = $__pub;
    }
    if (empty($GLOBALS['_s4SkipSnappApiInFetchHtml']) && function_exists('fetch_html_snappshop_api') && function_exists('isSnappshopUrl') && isSnappshopUrl($url)) {
        $__snApi = fetch_html_snappshop_api($url, $timeout, is_array($last) ? $last : []);
        if (!empty($__snApi['ok'])) return $__snApi;
        if (is_array($__snApi) && trim((string)($__snApi['error'] ?? '')) !== '') $last = $__snApi;
    }
    return $last ?? ['ok' => false, 'error' => 'Empty', 'code' => 0, 'url' => $url, 'html' => '', 'mode' => ''];
}

/* =====================================================================
 * v10.173: رندرِ جاوااسکریپت (Playwright/Selenium) برای سایت‌های SPA
 * ---------------------------------------------------------------------
 * بعضی سایت‌ها (React/Vue/Nuxt/Next) با واکشِ معمولی فقط یک «پوستهٔ خالی»
 * برمی‌گردانند و محتوایشان با جاوااسکریپت ساخته می‌شود. یک میکروسرویسِ
 * جداگانهٔ رندر (browser-php/ بدون Node، یا browser/ به‌صورت اختیاری) با CDP/Playwright
 * و در صورت شکست Selenium صفحه را واقعاً رندر می‌کند؛ این توابع کلاینتِ آن سرویس‌اند.
 *
 * پیکربندی در connections.json زیر کلیدِ "render":
 *   {"render":{"enabled":true,
 *              "url":"http://127.0.0.1:3100",
 *              "token":"...",
 *              "timeout_ms":60000,
 *              "mode":"auto",        // auto | js
 *              "scroll":false,
 *              "wait_until":"domcontentloaded"}}   // load|domcontentloaded|networkidle
 *
 * mode=auto : اول واکشِ ایستا؛ فقط اگر «پوستهٔ JS» تشخیص داده شد رندر (گران است)
 * mode=js   : همیشه رندر (وقتی می‌دانیم سایت SPA است)
 * =================================================================== */
function renderCfg(?array $cn = null): array {
    if ($cn === null) $cn = function_exists('loadConnections') ? loadConnections() : [];
    $r = (array)($cn['render'] ?? []);
    $mode = (string)($r['mode'] ?? 'auto');
    $wu = (string)($r['wait_until'] ?? 'domcontentloaded');
    return [
        'enabled'    => !empty($r['enabled']),
        'url'        => rtrim(trim((string)($r['url'] ?? 'http://127.0.0.1:3100')), '/'),
        'token'      => (string)($r['token'] ?? ''),
        'timeout_ms' => max(5000, min(120000, (int)($r['timeout_ms'] ?? 60000))),
        'mode'       => in_array($mode, ['auto','js'], true) ? $mode : 'auto',
        'scroll'     => !empty($r['scroll']),
        'wait_until' => in_array($wu, ['load','domcontentloaded','networkidle'], true) ? $wu : 'domcontentloaded',
    ];
}

/* تشخیص «پوستهٔ JS»: صفحه‌ای که فقط اسکلتِ اپ را دارد. محافظ‌کار است تا
   رندرهای اضافی انجام نشود (هر رندر ۱۵-۶۰ ثانیه طول می‌کشد). */
function looks_like_js_shell(string $html): bool {
    if ($html === '' || strlen($html) < 1500) return false;
    $visible = (string)preg_replace('~<(script|style|noscript|template)[^>]*>.*?</\\1>~is', ' ', $html);
    $visible = trim((string)strip_tags($visible));
    $visibleLen = mb_strlen((string)preg_replace('~\\s+~u', ' ', $visible));
    if ($visibleLen >= 400) return false;
    // نشانهٔ ۱: متنِ «جاوااسکریپت را فعال کنید»
    if (preg_match('~(you need to enable javascript|javascript is required|please enable javascript|جاوااسکریپت را (فعال|روشن)|لطفاً? جاوااسکریپت)~iu', $html)) return true;
    // نشانهٔ ۲: ظرفِ خالیِ رایجِ SPA
    if (preg_match('~<(div|main|section)[^>]+(?:id|class)=["\'][^"\']*(?:__next|__nuxt|app-root|ng-|id="root"|id="app"|\\broot\\b|\\bapp\\b)[^"\']*["\'][^>]*>\\s*(?:<[^a/][^>]*>\\s*){0,3}</(div|main|section)>~i', $html)) return true;
    // نشانهٔ ۳: تودهٔ اسکریپتِ خارجی + نشانهٔ فریم‌ورک + متنِ تقریباً صفر
    if ($visibleLen < 120 && preg_match_all('~<script[^>]+src=~i', $html, $m) && count($m[0]) >= 2) {
        if (preg_match('~(data-reactroot|window\\.__NUXT__|ng-version|__NEXT_DATA__)~i', $html)) return true;
    }
    return false;
}

function fetch_html_render(string $url, array $rcfg, array $opts = []): array {
    $base = (string)($rcfg['url'] ?? '');
    if ($base === '' || !preg_match('~^https?://~i', $base)) {
        return ['ok'=>false,'error'=>'renderer url not configured','code'=>0,'url'=>$url,'html'=>'','mode'=>'render'];
    }
    $payload = [
        'url'       => $url,
        'waitUntil' => (string)($opts['wait_until'] ?? ($rcfg['wait_until'] ?? 'domcontentloaded')),
        'timeout'   => (int)($rcfg['timeout_ms'] ?? 60000),
        'scroll'    => (bool)($opts['scroll'] ?? ($rcfg['scroll'] ?? false)),
    ];
    if (!empty($opts['selector'])) $payload['selector'] = (string)$opts['selector'];
    if (!empty($opts['driver']) && in_array((string)$opts['driver'], ['playwright','selenium'], true)) {
        $payload['driver'] = (string)$opts['driver'];
    }
    $headers = ['Content-Type: application/json', 'Accept: application/json'];
    if ((string)($rcfg['token'] ?? '') !== '') $headers[] = 'Authorization: Bearer ' . (string)$rcfg['token'];
    $ch = curl_init($base . '/render');
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true, CURLOPT_POST => true,
        CURLOPT_POSTFIELDS => json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
        CURLOPT_HTTPHEADER => $headers,
        CURLOPT_CONNECTTIMEOUT => 5,
        CURLOPT_TIMEOUT => (int)ceil(((int)$payload['timeout']) / 1000) + 10,
    ]);
    $body = curl_exec($ch); $err = curl_error($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
    curl_close($ch);
    $j = is_string($body) ? json_decode($body, true) : null;
    if ($body === false || $code < 200 || $code >= 300 || !is_array($j) || empty($j['ok'])) {
        $e = is_array($j) ? (string)($j['error'] ?? '') : '';
        if ($e === '') $e = $err !== '' ? $err : ('render failed (HTTP ' . $code . ')');
        return ['ok'=>false,'error'=>$e,'code'=>$code,'url'=>$url,'html'=>'','mode'=>'render'];
    }
    return ['ok'=>true,'error'=>'','code'=>(int)($j['code'] ?? 200),
            'url'=>(string)($j['url'] ?? $url) ?: $url,'html'=>(string)($j['html'] ?? ''),
            'mode'=>'render','driver'=>(string)($j['driver'] ?? ''),'took_ms'=>(int)($j['took_ms'] ?? 0)];
}

/* v10.174: پینگِ /health سرویس رندر — برای دکمهٔ «آزمایش اتصال» در تنظیمات */
function fetch_html_render_health(array $rcfg): array {
    $base = (string)($rcfg['url'] ?? '');
    if ($base === '' || !preg_match('~^https?://~i', $base)) {
        return ['ok'=>false,'error'=>'renderer url not configured'];
    }
    $ch = curl_init($base . '/health');
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_CONNECTTIMEOUT => 3, CURLOPT_TIMEOUT => 6,
    ]);
    $body = curl_exec($ch);
    $err  = curl_error($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
    curl_close($ch);
    if ($body === false) return ['ok'=>false,'error'=>$err !== '' ? $err : 'connect failed'];
    if ($code < 200 || $code >= 300) return ['ok'=>false,'error'=>'HTTP ' . $code];
    $j = json_decode($body, true);
    if (!is_array($j)) return ['ok'=>false,'error'=>'invalid health response'];
    return ['ok'=>true,'driver'=>(string)($j['driver'] ?? ''),
            'available'=>is_array($j['available'] ?? null) ? $j['available'] : [],
            'max_concurrency'=>(int)($j['max_concurrency'] ?? 0),
            'active'=>(int)($j['active'] ?? 0)];
}

/* v10.196: راه‌اندازی امن و محدودِ سرویس رندر محلی از همان صفحهٔ عیب‌یابی.
   فقط اسکریپت ثابت browser-php/start.sh را روی localhost اجرا می‌کند؛ هیچ فرمان
   یا مسیر دلخواهی از ورودی کاربر گرفته نمی‌شود. */
function s4RenderLocalEndpoint(array $rcfg): array {
    $base = (string)($rcfg['url'] ?? 'http://127.0.0.1:3100');
    $parts = parse_url($base);
    $host = strtolower((string)($parts['host'] ?? '127.0.0.1'));
    if ($host === '[::1]') $host = '::1';
    if (!in_array($host, ['127.0.0.1', 'localhost', '::1'], true)) {
        return ['ok'=>false, 'error'=>'render URL must be localhost for managed launch'];
    }
    $port = (int)($parts['port'] ?? 3100);
    if ($port < 1 || $port > 65535) return ['ok'=>false, 'error'=>'invalid render port'];
    return ['ok'=>true, 'host'=>$host === 'localhost' ? '127.0.0.1' : $host, 'port'=>$port];
}
function s4LaunchRenderService(array $rcfg, bool $force = false): array {
    if (!function_exists('shell_exec')) return ['ok'=>false, 'error'=>'shell_exec disabled'];
    $ep = s4RenderLocalEndpoint($rcfg);
    if (empty($ep['ok'])) return $ep;
    $dir = __DIR__;
    $start = $dir . '/browser-php/start.sh';
    $boot  = $dir . '/browser-php/bootstrap.sh';
    if (!is_file($start)) return ['ok'=>false, 'error'=>'browser-php/start.sh missing'];
    @mkdir($dir . '/logs', 0777, true);
    @mkdir($dir . '/run', 0777, true);
    $log = $dir . '/logs/render.log';
    $pidfile = $dir . '/run/render-service.pid';
    $oldPid = (int)trim((string)@file_get_contents($pidfile));
    if ($oldPid > 0 && trim((string)@shell_exec('kill -0 ' . (int)$oldPid . ' 2>/dev/null && echo alive')) === 'alive') {
        if (!$force) return ['ok'=>true, 'running'=>true, 'pid'=>$oldPid, 'log'=>basename(dirname($log)) . '/' . basename($log)];
        @shell_exec('pkill -TERM -P ' . (int)$oldPid . ' 2>/dev/null; kill ' . (int)$oldPid . ' 2>/dev/null');
        usleep(300000);
    }
    $host = (string)$ep['host'];
    $port = (int)$ep['port'];
    $maxc = max(1, min(4, (int)($rcfg['max_concurrency'] ?? 2)));
    $bootCmd = is_file($boot) ? ($force ? 'bash browser-php/bootstrap.sh; ' : 'if [ ! -x browser-php/bin/chrome-headless-shell ] && [ ! -x browser-php/bin/chromedriver ]; then bash browser-php/bootstrap.sh; fi; ') : '';
    $cmd = 'cd ' . escapeshellarg($dir)
         . ' && ( export RENDER_HOST=' . escapeshellarg($host)
         . ' RENDER_PORT=' . escapeshellarg((string)$port)
         . ' RENDER_MAX_CONCURRENCY=' . escapeshellarg((string)$maxc)
         . ' PHP=${PHP:-php}; '
         . $bootCmd
         . 'exec bash browser-php/start.sh ) >> ' . escapeshellarg($log) . ' 2>&1 & echo $!';
    $pid = (int)trim((string)@shell_exec($cmd));
    if ($pid > 0) @file_put_contents($pidfile, (string)$pid);
    return ['ok'=>$pid > 0, 'started'=>$pid > 0, 'pid'=>$pid, 'port'=>$port,
            'log'=>basename(dirname($log)) . '/' . basename($log),
            'error'=>$pid > 0 ? '' : 'failed to spawn render service'];
}

function s4RenderLogTail(int $lines = 80): string {
    $lines = max(10, min(250, $lines));
    $log = __DIR__ . '/logs/render.log';
    if (!is_file($log)) return '';
    if (function_exists('shell_exec')) {
        $txt = (string)@shell_exec('tail -n ' . (int)$lines . ' ' . escapeshellarg($log) . ' 2>/dev/null');
        if ($txt !== '') return mb_substr($txt, -20000);
    }
    $txt = (string)@file_get_contents($log);
    $rows = preg_split("~\R~", $txt) ?: [];
    return mb_substr(implode("
", array_slice($rows, -$lines)), -20000);
}

/* لایهٔ تصمیم: واکشِ ایستا یا رندر. فقط برای صفحه‌های فهرست استفاده می‌شود
   (همان جایی که خروجیِ خالی معنای «صفر محصول» می‌گرفت). */
function fetch_html_smart(string $url, int $timeout = 25, ?array $rcfg = null): array {
    $rc = $rcfg ?? renderCfg();
    $renderReady = !empty($rc['enabled']) && (string)($rc['url'] ?? '') !== '';
    if (!$renderReady) {
        $s = fetch_html($url, $timeout);
        if (!empty($s['ok']) && looks_like_js_shell((string)($s['html'] ?? '')) && function_exists('fetch_html_jina_reader')) {
            $_jr = fetch_html_jina_reader($url, $timeout, is_array($s) ? $s : []);
            if (!empty($_jr['ok']) && (int)($_jr['jina_product_count'] ?? 0) > 0) {
                $_jr['js_shell_detected'] = true;
                $_jr['jina_js_fallback'] = true;
                return $_jr;
            }
            $s['js_shell_detected'] = true;
            $s['jina_error'] = (string)($_jr['error'] ?? '');
            $s['jina_reader'] = (string)($_jr['jina_reader'] ?? '');
            $s['jina_reader_via'] = (string)($_jr['jina_reader_via'] ?? '');
            $s['jina_product_count'] = (int)($_jr['jina_product_count'] ?? 0);
            if (is_array($_jr['jina_reader_trace'] ?? null)) $s['jina_reader_trace'] = $_jr['jina_reader_trace'];
            if (is_array($_jr['jina_reader_modes'] ?? null)) $s['jina_reader_modes'] = $_jr['jina_reader_modes'];
        }
        return $s;
    }
    if (($rc['mode'] ?? 'auto') === 'js') {
        $r = fetch_html_render($url, $rc);
        if (!empty($r['ok'])) return $r;
        $s = fetch_html($url, $timeout);            // رندر نشد ← ایستا تا چیزی گم نشود
        $s['render_error'] = (string)($r['error'] ?? '');
        return $s;
    }
    $s = fetch_html($url, $timeout);
    if (empty($s['ok']) && function_exists('isEmallsUrl') && isEmallsUrl($url) && function_exists('fetch_html_emalls_public_fallback')) {
        $pf = fetch_html_emalls_public_fallback($url, $timeout, is_array($s) ? $s : []);
        if (!empty($pf['ok'])) return $pf;
    }
    if (empty($s['ok']) && function_exists('isSnappshopUrl') && isSnappshopUrl($url) && function_exists('fetch_html_snappshop_public_fallback')) {
        $pf = fetch_html_snappshop_public_fallback($url, $timeout, is_array($s) ? $s : []);
        if (!empty($pf['ok'])) return $pf;
    }
    if (empty($s['ok']) && function_exists('isEmallsUrl') && isEmallsUrl($url)) {
        $r = fetch_html_render($url, $rc);
        if (!empty($r['ok'])) {
            $r['emalls_static_error'] = (string)($s['error'] ?? '');
            return $r;
        }
        $s['render_error'] = (string)($r['error'] ?? '');
    }
    if (!empty($s['ok']) && looks_like_js_shell((string)$s['html'])) {
        $was = strlen((string)$s['html']);
        $r = fetch_html_render($url, $rc);
        if (!empty($r['ok']) && strlen((string)$r['html']) > $was) {
            $r['js_shell_detected'] = true;
            return $r;
        }
        $s['js_shell_detected'] = true;             // تشخیص دادیم ولی رندر نشد
        $s['render_error'] = (string)($r['error'] ?? '');
        /* v10.227: اگر صفحه SPA است و رندر محلی روی هاست بالا نیست، برای
           دامنه‌هایی مثل SnappShop/Digikala همان مسیر Reader را هم امتحان کن؛
           این دقیقاً همان نقش موتور Jina در سایت‌های JS-layered است، بدون اینکه
           رفتار سریع صفحات HTML معمولی عوض شود. */
        $_canJinaJs = function_exists('fetch_html_jina_reader');
        if ($_canJinaJs) {
            $_jr = fetch_html_jina_reader($url, $timeout, is_array($s) ? $s : []);
            if (!empty($_jr['ok']) && (int)($_jr['jina_product_count'] ?? 0) > 0) {
                $_jr['js_shell_detected'] = true;
                $_jr['render_error'] = (string)($s['render_error'] ?? '');
                $_jr['jina_js_fallback'] = true;
                return $_jr;
            }
            $s['jina_error'] = (string)($_jr['error'] ?? '');
            $s['jina_reader'] = (string)($_jr['jina_reader'] ?? '');
            $s['jina_reader_via'] = (string)($_jr['jina_reader_via'] ?? '');
            $s['jina_product_count'] = (int)($_jr['jina_product_count'] ?? 0);
            if (is_array($_jr['jina_reader_trace'] ?? null)) $s['jina_reader_trace'] = $_jr['jina_reader_trace'];
        }
    }
    return $s;
}

function extractImageFromHtml(string $html, string $pageUrl): string {
if(empty($html)) return '';
$parsed=parse_url($pageUrl);
$base=($parsed['scheme']??'https').'://'.($parsed['host']??'');

if(preg_match('/<meta[^>]+property=["\']og:image["\'][^>]+content=["\']([^"\']+)["\']/i',$html,$m)) return resolveUrl($m[1],$base,$pageUrl);
if(preg_match('/<meta[^>]+content=["\']([^"\']+)["\'][^>]+property=["\']og:image["\']/i',$html,$m)) return resolveUrl($m[1],$base,$pageUrl);

if(preg_match('/<meta[^>]+name=["\']twitter:image["\'][^>]+content=["\']([^"\']+)["\']/i',$html,$m)) return resolveUrl($m[1],$base,$pageUrl);

if(preg_match_all('/<img[^>]+>/i',$html,$imgs)){
$bestUrl='';$bestScore=0;
foreach($imgs[0] as $img){
$src='';$class='';$id='';$w=0;$h=0;$alt='';
if(preg_match('/src=["\']([^"\']+)["\']/i',$img,$sm))$src=$sm[1];
if(preg_match('/class=["\']([^"\']+)["\']/i',$img,$cm))$class=$cm[1];
if(preg_match('/id=["\']([^"\']+)["\']/i',$img,$im))$id=$im[1];
if(preg_match('/width=["\'](\d+)["\']/i',$img,$wm))$w=(int)$wm[1];
if(preg_match('/height=["\'](\d+)["\']/i',$img,$hm))$h=(int)$hm[1];
if(preg_match('/alt=["\']([^"\']+)["\']/i',$img,$am))$alt=$am[1];
if(!$src||preg_match('/^(data:|javascript:|#)/i',$src))continue;

$score=($w>200&&$h>200?10:0)+($w*$h>50000?5:0);

$kw='product|main|big|large|gallery|featured|hero|primary|item|detail';
if(preg_match('/'.$kw.'/i',$class.$id))$score+=8;
if(preg_match('/'.$kw.'/i',$alt))$score+=3;

if(preg_match('/logo|icon|badge|thumb|avatar|sprite|social|banner|slider/i',$class.$id))$score-=10;
if($score>$bestScore){$bestScore=$score;$bestUrl=$src;}
}
if($bestUrl&&$bestScore>=3)return resolveUrl($bestUrl,$base,$pageUrl);
}

if(preg_match('/<img[^>]+src=["\']([^"\']+)["\'][^>]*>/i',$html,$m)){
$u=$m[1];if(!preg_match('/^(data:|javascript:|#|[\w]+-icon)/i',$u)&&strlen($u)>10)return resolveUrl($u,$base,$pageUrl);
}
return '';
}

function resolveUrl(string $url, string $base, string $pageUrl): string {
if(preg_match('/^https?:\/\//i',$url))return $url;
if(strpos($url,'//')===0)return 'https:'.$url;
if(strpos($url,'/')===0)return $base.$url;
return rtrim($pageUrl,'/').'/'.ltrim($url,'/');
}

/* v10.194: URLهایی که کاربر از مرورگر فارسی کپی می‌کند گاهی IRI هستند
   (مسیرِ فارسی خام دارند) و FILTER_VALIDATE_URL در PHP آن‌ها را رد می‌کند.
   قبل از اعتبارسنجی، فقط کاراکترهای غیر ASCII/فاصله را percent-encode می‌کنیم؛
   نشانی‌های از قبل encode شده دست‌نخورده می‌مانند و کلید پروفایل هم پایدار می‌شود. */
function s4NormalizeInputUrl(string $url): string {
$url = trim(html_entity_decode($url, ENT_QUOTES | ENT_HTML5, 'UTF-8'));
if ($url === '') return '';
if (filter_var($url, FILTER_VALIDATE_URL)) return $url;
$enc = @preg_replace_callback('~[^\x21-\x7E]~u', function ($m) { return rawurlencode($m[0]); }, $url);
if (!is_string($enc) || $enc === '') {
    $enc = @preg_replace_callback('~[^\x21-\x7E]~', function ($m) {
        $out = '';
        foreach (str_split($m[0]) as $ch) $out .= '%' . strtoupper(bin2hex($ch));
        return $out;
    }, $url);
}
return is_string($enc) && $enc !== '' ? $enc : $url;
}

function s4ValidInputUrl(string $url): bool {
$url = s4NormalizeInputUrl($url);
return $url !== '' && filter_var($url, FILTER_VALIDATE_URL) !== false;
}

/* =====================================================================
 *  بررسی نسخه — فقط خواندنی
 *  ---------------------------------------------------------------
 *  این بخش عمداً هیچ کدی دانلود نمی‌کند و هیچ فایل PHP ای نمی‌نویسد.
 *  فقط شناسهٔ نسخهٔ گیت‌هاب را با فایل فعلی مقایسه می‌کند و نتیجه را
 *  گزارش می‌دهد. نصب عادی همچنان می‌تواند با deploy.php باشد؛ از v10.266
 *  endpoint جدا و احراز‌شدهٔ code_update نیز فقط از منبع ثابت، با کنترل
 *  SHA، lint، backup و جایگزینی اتمیک فایل کامل را نصب می‌کند.
 * ===================================================================== */

const VC_FILE = __DIR__ . '/.versioncheck.json';

function vc_defaults(): array {
    return [
        'check_on_load'   => false,
        'repo'            => 'fazilatma/new',
        'branch'          => 'arena/e868e86a-new',
        'branches'        => ['arena/e868e86a-new'],
        'pinned_branch'   => '',
        'pinned_at'       => 0,
        'pinned_max_unix' => 0,
        // v8.68: نام فایل در مخزن. اگر فایل را با نام دیگری نصب کرده‌اید،
        // خودِ همان نام مبنا قرار می‌گیرد تا به‌روزرسانی دنبال فایل اشتباه نگردد.
        'path'            => basename(__FILE__),
        'github_token'    => '',
        'deploy_file'     => 'deploy.php',
        'deploy_token'    => '',
        'last_check'      => 0,
    ];
}

function vc_load(): array {
    $d = vc_defaults();
    if (!is_file(VC_FILE)) return $d;
    $j = json_decode((string)@file_get_contents(VC_FILE), true);
    if (!is_array($j)) return $d;
    $c = array_merge($d, $j);
    // v8.70: مسیر ذخیره‌شده از قبلِ تغییرِ نام فایل، مسیر اشتباه است.
    // بدون این، به‌روزرسانی برای همیشه فایل قدیمی مخزن را می‌سنجید و
    // «به‌روز هستید» می‌گفت، در حالی که نسخهٔ تازه هرگز نصب نمی‌شد.
    $saved = trim((string)($c['path'] ?? ''));
    $self  = basename(__FILE__);
    if ($saved === '' || ($saved !== $self && basename($saved) !== $self
        && preg_match('~^scraper[-_v0-9.]*\.php$~i', basename($saved)))) {
        $c['path'] = $self;
    }
    /* v10.409: migrate the former single branch without losing it. */
    $rawBranches=array_key_exists('branches',$j)&&is_array($j['branches'])
        ? $j['branches'] : [(string)($c['branch']??'')];
    $c['branches']=vc_normalize_branches($rawBranches);
    if(!$c['branches'])$c['branches']=['arena/e868e86a-new'];
    if(!in_array((string)$c['branch'],$c['branches'],true))$c['branch']=$c['branches'][0];
    $pin=trim((string)($c['pinned_branch']??''));
    if($pin!==''&&!in_array($pin,$c['branches'],true)){
        $c['pinned_branch']='';$c['pinned_at']=0;$c['pinned_max_unix']=0;
    }
    return $c;
}
/**
 * v10.446: اگر کاربر به‌صورت دستی روی «⬇ آپدیت از این برنچ» کلیک کرده باشد،
 * تا زمانی که هیچ برنچ دیگری کامیت تازه‌تر از لحظهٔ انتخاب دستی دریافت نکرده،
 * همان برنچ انتخابی حفظ می‌شود و برنچِ قدیمی‌ترِ دیگر آن را بازنویسی نمی‌کند.
 */
function vc_pick_target_branch(array $c, array $candidates): ?array {
    if (empty($candidates)) return null;
    $newest = $candidates[0];
    $pinned = trim((string)($c['pinned_branch'] ?? ''));
    if ($pinned !== '') {
        $pinnedRow = null;
        foreach ($candidates as $row) {
            if (($row['branch'] ?? '') === $pinned) { $pinnedRow = $row; break; }
        }
        $baseline = max((int)($c['pinned_at'] ?? 0), (int)($c['pinned_max_unix'] ?? 0));
        if ($pinnedRow !== null && (int)($newest['unix'] ?? 0) <= $baseline) {
            return $pinnedRow;
        }
    }
    return $newest;
}
function vc_normalize_branches(array $branches):array{
    $out=[];foreach($branches as $branch){$branch=trim((string)$branch);
        if($branch===''||strlen($branch)>180||preg_match('~[\x00-\x20\x7f]|\.\.|^/|/$|//~',$branch))continue;
        if(!in_array($branch,$out,true))$out[]=$branch;if(count($out)>=20)break;
    }return $out;
}
/** Probe configured branches and order them by their newest path commit time. */
function vc_probe_branches(array $c):array{
    $rows=[];$errors=[];$repo=(string)$c['repo'];$path=(string)$c['path'];$token=(string)$c['github_token'];
    foreach(vc_normalize_branches((array)($c['branches']??[])) as $branch){
        $commitUrl='https://api.github.com/repos/'.$repo.'/commits?sha='.rawurlencode($branch).'&path='.rawurlencode($path).'&per_page=1';
        $cr=vc_get_json_auto($commitUrl,$token,25);
        $metaUrl='https://api.github.com/repos/'.$repo.'/contents/'.implode('/',array_map('rawurlencode',explode('/',$path))).'?ref='.rawurlencode($branch);
        $mr=vc_get_json_auto($metaUrl,$token,25);
        if(empty($cr['ok'])||empty($cr['data'][0])||empty($mr['ok'])||empty($mr['data']['sha'])){$errors[$branch]=(string)($mr['error']??$cr['error']??'probe_failed');continue;}
        $commit=$cr['data'][0];$date=(string)($commit['commit']['committer']['date']??$commit['commit']['author']['date']??'');
        $rows[]=['branch'=>$branch,'timestamp'=>$date,'unix'=>$date!==''?(int)strtotime($date):0,
            'commit_sha'=>(string)($commit['sha']??''),'sha'=>(string)$mr['data']['sha'],'size'=>(int)($mr['data']['size']??0),'download_url'=>(string)($mr['data']['download_url']??'')];
    }
    usort($rows,static fn($a,$b)=>(int)$b['unix']<=>(int)$a['unix']);
    return ['rows'=>$rows,'errors'=>$errors];
}

function vc_save(array $c): bool {
    $ok = @file_put_contents(VC_FILE, json_encode($c, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), LOCK_EX) !== false;
    if ($ok) @chmod(VC_FILE, 0600);
    return $ok;
}

/** شناسهٔ محتوا با همان الگوریتم گیت، برای مقایسه با پاسخ API */
function vc_content_id(string $data): string {
    return sha1('blob ' . strlen($data) . "\0" . $data);
}

/** پیام خطای گویا برای کدهای رایج گیت‌هاب */
function vc_http_error(int $code, string $fallback, bool $hadToken): string {
    if ($code === 401) {
        return 'توکن گیت‌هاب نامعتبر یا منقضی است (۴۰۱) — چون ریپو عمومی است، توکن را حذف کنید';
    }
    if ($code === 403) {
        return $hadToken
            ? 'دسترسی رد شد (۴۰۳) — توکن مجوز لازم را ندارد'
            : 'محدودیت نرخ گیت‌هاب (۴۰۳) — ساعتی ۶۰ درخواست برای هر IP؛ کمی بعد دوباره تلاش کنید';
    }
    if ($code === 404) return 'فایل، برنچ یا ریپو پیدا نشد (۴۰۴)';
    return $fallback ?: ('خطا HTTP ' . $code);
}

/**
 * درخواست GET فقط برای خواندن اطلاعات (متادیتا)، نه کد.
 * اگر توکن نامعتبر باشد و ریپو عمومی، یک‌بار بدون توکن دوباره تلاش می‌کند
 * تا یک توکن خراب کل قابلیت را از کار نیندازد.
 */
function vc_get_json_auto(string $url, string $token = '', int $timeout = 25): array {
    $r = vc_get_json($url, $token, $timeout);
    if (!$r['ok'] && $r['code'] === 401 && $token !== '') {
        $retry = vc_get_json($url, '', $timeout);
        if ($retry['ok']) {
            $retry['token_rejected'] = true;   // به UI بگو توکن بد است
            return $retry;
        }
    }
    $r['token_rejected'] = false;
    return $r;
}

/** درخواست GET فقط برای خواندن اطلاعات (متادیتا)، نه کد */
function vc_get_json(string $url, string $token = '', int $timeout = 25): array {
    $hdr = [
        'User-Agent: scraper-version-check',
        'Accept: application/vnd.github+json',
        'Cache-Control: no-cache',
    ];
    if ($token !== '') $hdr[] = 'Authorization: Bearer ' . $token;

    if (function_exists('curl_init')) {
        $ch = curl_init($url);
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => true, CURLOPT_MAXREDIRS => 5,
            CURLOPT_CONNECTTIMEOUT => 12, CURLOPT_TIMEOUT => $timeout, CURLOPT_ENCODING => '',
            CURLOPT_HTTPHEADER => $hdr,
        ]);
        $b = curl_exec($ch);
        $e = curl_error($ch);
        $c = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
        curl_close($ch);
        if ($b === false) return ['ok' => false, 'code' => 0, 'error' => $e ?: 'ارتباط ناموفق', 'data' => null];
        if ($c !== 200)   return ['ok' => false, 'code' => $c, 'error' => 'HTTP ' . $c, 'data' => null];
        $d = json_decode((string)$b, true);
        return is_array($d) ? ['ok' => true, 'code' => 200, 'error' => '', 'data' => $d]
                            : ['ok' => false, 'code' => 200, 'error' => 'پاسخ نامعتبر', 'data' => null];
    }

    $ctx = stream_context_create([
        'http' => ['method' => 'GET', 'timeout' => $timeout, 'header' => implode("\r\n", $hdr), 'ignore_errors' => true],
        'ssl'  => ['verify_peer' => true, 'verify_peer_name' => true],
    ]);
    $b = @file_get_contents($url, false, $ctx);
    if ($b === false) return ['ok' => false, 'code' => 0, 'error' => 'ارتباط ناموفق', 'data' => null];
    $d = json_decode((string)$b, true);
    return is_array($d) ? ['ok' => true, 'code' => 200, 'error' => '', 'data' => $d]
                        : ['ok' => false, 'code' => 0, 'error' => 'پاسخ نامعتبر', 'data' => null];
}

/* =====================================================================
 * v10.266: endpoint امن نصب کل فایل پس از push.
 * منبع عمداً به branch همین نشست قفل است؛ پارامتر درخواست نمی‌تواند repo،
 * branch، path یا URL دلخواه تزریق کند. نصب فقط با deploy_token ذخیره‌شده یا
 * مدیر وردپرس + nonce، به‌صورت POST و جایگزینی اتمیک انجام می‌شود.
 * ===================================================================== */
const S4_CODE_UPDATE_REPO='fazilatma/new';
const S4_CODE_UPDATE_BRANCH='arena/e868e86a-new';
const S4_CODE_UPDATE_PATH='scraper4.php';
const S4_CODE_UPDATE_STATE_FILE=__DIR__.'/.scraper4-auto-update.json';
const S4_CODE_UPDATE_INTERVAL=120;

function s4CodeUpdateHttp(string $url,string $token='',int $timeout=90):array{
    if(!function_exists('curl_init'))return ['ok'=>false,'code'=>0,'error'=>'curl_unavailable','body'=>''];
    $h=['User-Agent: scraper4-code-updater','Accept: application/octet-stream','Cache-Control: no-cache'];
    if($token!=='')$h[]='Authorization: Bearer '.$token;
    $ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,
        CURLOPT_CONNECTTIMEOUT=>15,CURLOPT_TIMEOUT=>$timeout,CURLOPT_ENCODING=>'',CURLOPT_HTTPHEADER=>$h,
        CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);
    $body=curl_exec($ch);$err=(string)curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);
    return ['ok'=>$body!==false&&$code>=200&&$code<300,'code'=>$code,'error'=>$err?:($code>=200&&$code<300?'':'HTTP '.$code),'body'=>$body===false?'':(string)$body];
}
function s4CodeUpdateAdminAuth():array{
    /* direct endpoint نباید wp-load را وسط فایل ۶MB دوباره bootstrap کند؛ در
       اجرای plugin توابع وردپرس از قبل حاضرند، و در اجرای مستقیم token کافی است. */
    $admin=function_exists('current_user_can')&&current_user_can('manage_options');
    $nonce=(string)($_POST['_wpnonce']??($_SERVER['HTTP_X_WP_NONCE']??''));
    return ['admin'=>$admin,'ok'=>$admin&&function_exists('wp_verify_nonce')&&wp_verify_nonce($nonce,'s4_code_update')];
}
function s4DiskCodeMeta():array{
    clearstatcache(true,__FILE__);
    $raw=(string)@file_get_contents(__FILE__);
    if($raw==='')return ['version'=>APP_VERSION,'sha'=>''];
    $ver=APP_VERSION;
    if(preg_match("~const\\s+APP_VERSION\\s*=\\s*'([^']+)'~",substr($raw,0,65536),$m))$ver=(string)$m[1];
    $sha=substr(vc_content_id($raw),0,12);
    if($ver!==APP_VERSION&&function_exists('opcache_invalidate'))@opcache_invalidate(__FILE__,true);
    return ['version'=>$ver,'sha'=>$sha];
}
function s4SyncAutoUpdateStateToDisk(string $branch='',bool $clearForPendingDeploy=false):array{
    $now=time();
    if($clearForPendingDeploy){
        /* v10.446: پیش از اجرای deploy.php مقدار to_version را خالی می‌کنیم تا حتی اگر
           برنچ مقصد نسخهٔ قدیمی‌ترِ قبل از 10.446 باشد، s4WatchInstalledCode در حلقهٔ رفرش نیفتد. */
        $save=['checked_at'=>$now,'finished_at'=>$now,'ok'=>true,'updated'=>false,'from_version'=>'','to_version'=>'','error'=>'','sha'=>'','branch'=>$branch,'manual_pending'=>true];
        @file_put_contents(S4_CODE_UPDATE_STATE_FILE,json_encode($save,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX);
        return $save;
    }
    $meta=s4DiskCodeMeta();
    $save=['checked_at'=>$now,'finished_at'=>$now,'ok'=>true,'updated'=>false,'from_version'=>$meta['version'],'to_version'=>$meta['version'],'error'=>'','sha'=>$meta['sha'],'branch'=>$branch];
    @file_put_contents(S4_CODE_UPDATE_STATE_FILE,json_encode($save,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX);
    return $save;
}
function s4CodeUpdateDownloadVerified(array $picked,string $ghToken=''):array{
    $remoteSha=(string)($picked['sha']??'');
    $commitSha=trim((string)($picked['commit_sha']??''));
    $urls=[];
    /* اولویت ۱: آدرس تغییرناپذیر مبتنی بر commit_sha که هرگز کش ۵ دقیقه‌ای نام برنچ در CDN گیت‌هاب را ندارد */
    if($commitSha!==''){
        $encPath=implode('/',array_map('rawurlencode',explode('/',S4_CODE_UPDATE_PATH)));
        $urls[]=['url'=>'https://raw.githubusercontent.com/'.S4_CODE_UPDATE_REPO.'/'.rawurlencode($commitSha).'/'.$encPath,'raw_api'=>false];
    }
    $dl=(string)($picked['download_url']??'');
    if($dl!==''){
        if($remoteSha!=='')$dl.=(strpos($dl,'?')===false?'?':'&').'s4sha='.rawurlencode($remoteSha);
        $urls[]=['url'=>$dl,'raw_api'=>false];
    }
    if($remoteSha!==''){
        $urls[]=['url'=>'https://api.github.com/repos/'.S4_CODE_UPDATE_REPO.'/git/blobs/'.rawurlencode($remoteSha),'raw_api'=>true];
    }
    $lastErr=['ok'=>false,'http'=>502,'error'=>'github_download_failed'];
    foreach($urls as $cand){
        if(!empty($cand['raw_api'])){
            if(!function_exists('curl_init'))continue;
            $h=['User-Agent: scraper4-code-updater','Accept: application/vnd.github.raw+json','Cache-Control: no-cache'];
            if($ghToken!=='')$h[]='Authorization: Bearer '.$ghToken;
            $ch=curl_init($cand['url']);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,
                CURLOPT_CONNECTTIMEOUT=>15,CURLOPT_TIMEOUT=>120,CURLOPT_ENCODING=>'',CURLOPT_HTTPHEADER=>$h,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);
            $body=curl_exec($ch);$err=(string)curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);
            $got=['ok'=>$body!==false&&$code>=200&&$code<300,'code'=>$code,'error'=>$err?:($code>=200&&$code<300?'':'HTTP '.$code),'body'=>$body===false?'':(string)$body];
        }else{
            $got=s4CodeUpdateHttp($cand['url'],$ghToken,120);
        }
        if(empty($got['ok'])){
            $lastErr=['ok'=>false,'http'=>502,'error'=>'github_download_failed','code'=>(int)$got['code'],'detail'=>(string)$got['error']];
            continue;
        }
        $code=(string)$got['body'];
        if($remoteSha!==''&&vc_content_id($code)!==$remoteSha){
            $lastErr=['ok'=>false,'http'=>422,'error'=>'git_blob_sha_mismatch'];
            continue;
        }
        return ['ok'=>true,'body'=>$code];
    }
    return $lastErr;
}
function s4CodeUpdateRun(bool $trustedAuto=false):array{
    $cfg=vc_load();
    if(!$trustedAuto){
        $expected=trim((string)($cfg['deploy_token']??''));
        $given=trim((string)($_SERVER['HTTP_X_S4_UPDATE_TOKEN']??($_POST['token']??'')));
        $tokenOk=$expected!==''&&$given!==''&&hash_equals($expected,$given);$wp=s4CodeUpdateAdminAuth();
        if(!$tokenOk&&empty($wp['ok']))return ['ok'=>false,'http'=>403,'error'=>'unauthorized: deploy_token یا مدیر وردپرس با nonce لازم است'];
    }
    $lock=@fopen(__DIR__.'/.scraper4-code-update.lock','c');if(!$lock||!@flock($lock,LOCK_EX|LOCK_NB)){if($lock)@fclose($lock);return ['ok'=>false,'http'=>409,'error'=>'update_already_running'];}
    $tmp='';
    try{
        $ghToken=trim((string)($cfg['github_token']??''));
        $allowed=vc_normalize_branches((array)($cfg['branches']??[]));
        $requested=trim((string)($_POST['branch']??''));
        if($requested!==''&&!in_array($requested,$allowed,true))return ['ok'=>false,'http'=>403,'error'=>'branch_not_configured'];
        $probeCfg=$cfg;$probeCfg['repo']=S4_CODE_UPDATE_REPO;$probeCfg['path']=S4_CODE_UPDATE_PATH;$probeCfg['branches']=$requested!==''?[$requested]:$allowed;
        $probe=vc_probe_branches($probeCfg);
        $picked=($requested!=='')?($probe['rows'][0]??null):vc_pick_target_branch($cfg,$probe['rows']);
        if(!$picked)return ['ok'=>false,'http'=>502,'error'=>'github_metadata_failed','detail'=>json_encode($probe['errors'],JSON_UNESCAPED_UNICODE)];
        $sourceBranch=(string)$picked['branch'];$remoteSha=(string)$picked['sha'];
        $localCode=(string)@file_get_contents(__FILE__);$localSha=vc_content_id($localCode);preg_match("~const APP_VERSION\\s*=\\s*'([^']+)'~",$localCode,$lvm);$diskVersion=(string)($lvm[1]??APP_VERSION);
        if(!$trustedAuto&&$requested!==''){
            $maxUnix=time();foreach($probe['rows'] as $pr){if((int)($pr['unix']??0)>$maxUnix)$maxUnix=(int)$pr['unix'];}
            $cfg['branch']=$sourceBranch;$cfg['pinned_branch']=$sourceBranch;$cfg['pinned_at']=time();$cfg['pinned_max_unix']=$maxUnix;
            vc_save($cfg);
        }
        if($remoteSha!==''&&hash_equals($remoteSha,$localSha)){
            s4SyncAutoUpdateStateToDisk($sourceBranch,false);
            return ['ok'=>true,'updated'=>false,'same'=>true,'version'=>$diskVersion,'branch'=>$sourceBranch,'restart_required'=>$diskVersion!==APP_VERSION,'sha'=>substr($remoteSha,0,12)];
        }
        $dlRes=s4CodeUpdateDownloadVerified($picked,$ghToken);
        if(empty($dlRes['ok']))return $dlRes;
        $code=(string)$dlRes['body'];$size=strlen($code);
        if($size<1000000||strncmp($code,"<?php",5)!==0||strpos($code,'const APP_VERSION')===false||strpos($code,'function matrixBuild')===false)
            return ['ok'=>false,'http'=>422,'error'=>'download_validation_failed','size'=>$size];
        if($remoteSha!==''&&vc_content_id($code)!==$remoteSha)return ['ok'=>false,'http'=>422,'error'=>'git_blob_sha_mismatch'];
        preg_match("~const APP_VERSION\\s*=\\s*'([^']+)'~",$code,$vm);$remoteVersion=(string)($vm[1]??'unknown');
        $allowDowngrade=!empty($_POST['allow_downgrade'])||(!$trustedAuto&&$requested!=='');
        if($remoteVersion!=='unknown'&&version_compare($remoteVersion,$diskVersion,'<')&&!$allowDowngrade){
            if($trustedAuto){
                s4SyncAutoUpdateStateToDisk($sourceBranch,false);
                return ['ok'=>true,'updated'=>false,'same'=>true,'downgrade_skipped'=>true,'current'=>$diskVersion,'remote'=>$remoteVersion,'version'=>$diskVersion,'branch'=>$sourceBranch,'restart_required'=>$diskVersion!==APP_VERSION];
            }
            return ['ok'=>false,'http'=>409,'error'=>'downgrade_refused','current'=>$diskVersion,'remote'=>$remoteVersion,'version'=>$diskVersion];
        }
        $tmp=__FILE__.'.update.'.getmypid().'.tmp';
        if(@file_put_contents($tmp,$code,LOCK_EX)!==$size){
            @unlink($tmp);if(function_exists('s4ReclaimPluginQuotaBloat'))s4ReclaimPluginQuotaBloat(true);
            if(@file_put_contents($tmp,$code,LOCK_EX)!==$size){@unlink($tmp);return ['ok'=>false,'http'=>500,'error'=>'temporary_write_failed'];}
        }
        @chmod($tmp,(int)(@fileperms(__FILE__)&0777));
        if(function_exists('exec')){
            $lint=[];$rc=0;$lintPhp=function_exists('s4CliPhpBinary')?s4CliPhpBinary():(defined('PHP_BINARY')?(string)PHP_BINARY:'php');
            if(stripos(basename($lintPhp),'lsphp')!==false){$plain=dirname($lintPhp).'/php';if(is_file($plain)&&is_executable($plain))$lintPhp=$plain;}
            $lintBase=function_exists('s4CliPhpCommand')?s4CliPhpCommand($lintPhp,'256M'):escapeshellarg($lintPhp);
            @exec($lintBase.' -l '.escapeshellarg($tmp).' 2>&1',$lint,$rc);
            if($rc!==0)return ['ok'=>false,'http'=>422,'error'=>'php_lint_failed','binary'=>$lintPhp,'exit_code'=>$rc,'detail'=>implode("\n",array_slice($lint,-5))];
        }
        $backup=__FILE__.'.before-code-update';@unlink($backup);
        $hasBackup=@copy(__FILE__,$backup);
        if(!$hasBackup){@unlink($backup);if(function_exists('s4ReclaimPluginQuotaBloat'))s4ReclaimPluginQuotaBloat(true);$hasBackup=@copy(__FILE__,$backup);if(!$hasBackup)@unlink($backup);}
        $installed=@rename($tmp,__FILE__);if(!$installed){$installed=@copy($tmp,__FILE__);if($installed)@unlink($tmp);}
        if(!$installed){if(!empty($hasBackup)&&is_file($backup))@copy($backup,__FILE__);return ['ok'=>false,'http'=>500,'error'=>'atomic_replace_failed'];}
        clearstatcache(true,__FILE__);if(function_exists('opcache_invalidate'))@opcache_invalidate(__FILE__,true);
        if($trustedAuto&&!empty($cfg['pinned_branch'])&&$cfg['pinned_branch']!==$sourceBranch){
            $cfg['branch']=$sourceBranch;$cfg['pinned_branch']='';$cfg['pinned_at']=0;$cfg['pinned_max_unix']=0;vc_save($cfg);
        }
        s4SyncAutoUpdateStateToDisk($sourceBranch,false);
        $recycledExtractPids=function_exists('s4RecycleOutdatedExtractSlotProcesses')?s4RecycleOutdatedExtractSlotProcesses($remoteVersion):[];
        $worker=['safe_restart'=>'worker پس از پایان job اختلاف نسخه RAM را تشخیص می‌دهد','recycled_extract_pids'=>$recycledExtractPids];
        return ['ok'=>true,'updated'=>true,'from_version'=>APP_VERSION,'to_version'=>$remoteVersion,'disk_version'=>$remoteVersion,'disk_sha'=>substr($remoteSha,0,12),'bytes'=>$size,'sha'=>substr($remoteSha,0,12),
            'source'=>S4_CODE_UPDATE_REPO.'@'.$sourceBranch.':'.S4_CODE_UPDATE_PATH,'branch'=>$sourceBranch,'backup'=>basename($backup),'worker'=>$worker,
            'next'=>'نسخهٔ تازه نصب شد؛ ops_feedback=1&repair=1 را روی همین مسیر فراخوانی کنید'];
    }finally{if($tmp!==''&&is_file($tmp))@unlink($tmp);@flock($lock,LOCK_UN);@fclose($lock);}
}
function s4RecycleOutdatedExtractSlotProcesses(?string $expectedVer = null): array {
    $expected = $expectedVer !== null && $expectedVer !== '' ? $expectedVer : (function_exists('s4DiskCodeMeta') ? (string)(s4DiskCodeMeta()['version'] ?? APP_VERSION) : APP_VERSION);
    $recycled = [];
    $sig = defined('SIGTERM') ? SIGTERM : 15;
    $myPid = (int)@getmypid();
    $killFn = static function(int $pid) use ($sig): bool {
        if ($pid <= 0) return false;
        if (function_exists('posix_kill') && @posix_kill($pid, $sig)) return true;
        if (function_exists('exec')) {
            $out = []; $rc = 1;
            @exec('kill -TERM ' . (int)$pid . ' >/dev/null 2>&1', $out, $rc);
            if ($rc === 0) return true;
        }
        return false;
    };
    if (function_exists('extractLockKnownSlotFiles')) {
        foreach (extractLockKnownSlotFiles() as $slotFile) {
            if (!is_file($slotFile)) continue;
            $fp = @fopen($slotFile, 'c');
            if (!$fp) continue;
            $held = !@flock($fp, LOCK_EX | LOCK_NB);
            if (!$held) { @flock($fp, LOCK_UN); @fclose($fp); continue; }
            $meta = @json_decode((string)@file_get_contents($slotFile), true);
            @fclose($fp);
            if (!is_array($meta)) continue;
            $slotVer = trim((string)($meta['code_version'] ?? ''));
            $spid = (int)($meta['pid'] ?? 0);
            if ($spid > 0 && $spid !== $myPid && $slotVer !== $expected && !in_array($spid, $recycled, true)) {
                if ($killFn($spid)) $recycled[] = $spid;
            }
        }
    }
    if (function_exists('s4WorkerLoadQueue')) {
        $_pgUp = function_exists('readProgress') ? readProgress(EXTRACT_PROGRESS_FILE) : [];
        if (!empty($_pgUp['error']) && empty($_pgUp['done'])) {
            foreach ((array)(s4WorkerLoadQueue()['entries'] ?? []) as $_weUp) {
                if (!is_array($_weUp) || ($_weUp['type'] ?? '') !== 'backend_extract' || ($_weUp['status'] ?? '') !== 'running') continue;
                $_wpid = (int)($_weUp['worker_pid'] ?? 0);
                if ($_wpid > 0 && $_wpid !== $myPid && !in_array($_wpid, $recycled, true) && $killFn($_wpid)) {
                    $recycled[] = $_wpid;
                }
            }
        }
    }
    return $recycled;
}
/** بدون deploy.php: هر پردازه حداکثر هر دو دقیقه branch ثابت را بررسی می‌کند.
 * flock قبل از شبکه گرفته می‌شود تا ده request همزمان سهمیه GitHub را نسوزانند. */
function s4AutoCodeUpdateTick(bool $force=false):array{
    $now=time();$disk=s4DiskCodeMeta();$diskVer=$disk['version'];$diskSha=$disk['sha'];
    $state=[];if(is_file(S4_CODE_UPDATE_STATE_FILE)){$j=json_decode((string)@file_get_contents(S4_CODE_UPDATE_STATE_FILE),true);if(is_array($j))$state=$j;}
    if(!empty($state['to_version'])&&(string)$state['to_version']!==$diskVer&&empty($state['checking'])){
        /* فایل روی دیسک بیرون از auto-updater (مثلاً توسط deploy.php روی برنچ دستی) عوض شده است؛
           state کهنه را بلافاصله با دیسک واقعی همگام کن تا مرورگر وارد حلقهٔ رفرش بی‌نهایت نشود. */
        $state['to_version']=$diskVer;$state['sha']=$diskSha;
        @file_put_contents(S4_CODE_UPDATE_STATE_FILE,json_encode($state,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX);
    }
    if(!$force&&$now-(int)($state['checked_at']??0)<S4_CODE_UPDATE_INTERVAL){
        $restart=($diskVer!==APP_VERSION);
        return ['ok'=>true,'skipped'=>true,'restart_required'=>$restart,'disk_version'=>$diskVer,'disk_sha'=>$diskSha,'state'=>$state];
    }
    $gate=@fopen(__DIR__.'/.scraper4-auto-update.lock','c');if(!$gate||!@flock($gate,LOCK_EX|LOCK_NB)){if($gate)@fclose($gate);return ['ok'=>true,'skipped'=>true,'reason'=>'busy','disk_version'=>$diskVer,'disk_sha'=>$diskSha,'restart_required'=>($diskVer!==APP_VERSION)];}
    try{
        clearstatcache(true,S4_CODE_UPDATE_STATE_FILE);$latest=[];if(is_file(S4_CODE_UPDATE_STATE_FILE)){$j=json_decode((string)@file_get_contents(S4_CODE_UPDATE_STATE_FILE),true);if(is_array($j))$latest=$j;}
        if(!$force&&$now-(int)($latest['checked_at']??0)<S4_CODE_UPDATE_INTERVAL){
            $disk2=s4DiskCodeMeta();
            if(!empty($latest['to_version'])&&(string)$latest['to_version']!==$disk2['version']){$latest['to_version']=$disk2['version'];$latest['sha']=$disk2['sha'];}
            $restart=($disk2['version']!==APP_VERSION);
            return ['ok'=>true,'skipped'=>true,'restart_required'=>$restart,'disk_version'=>$disk2['version'],'disk_sha'=>$disk2['sha'],'state'=>$latest];
        }
        /* پیش از شبکه timestamp بنویس تا شکست GitHub نیز requestهای بعدی را طوفانی نکند. */
        @file_put_contents(S4_CODE_UPDATE_STATE_FILE,json_encode(['checked_at'=>$now,'checking'=>true,'local_version'=>$diskVer,'to_version'=>$diskVer,'sha'=>$diskSha],JSON_UNESCAPED_UNICODE),LOCK_EX);
        $res=s4CodeUpdateRun(true);
        $afterDisk=s4DiskCodeMeta();
        $save=['checked_at'=>$now,'finished_at'=>time(),'ok'=>!empty($res['ok']),
            'updated'=>!empty($res['updated']),'from_version'=>$diskVer,'to_version'=>$afterDisk['version'],
            'error'=>(string)($res['error']??''),'sha'=>$afterDisk['sha'],'branch'=>(string)($res['branch']??'')];
        @file_put_contents(S4_CODE_UPDATE_STATE_FILE,json_encode($save,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX);
        return $res+['auto'=>true,'disk_version'=>$afterDisk['version'],'disk_sha'=>$afterDisk['sha'],'restart_required'=>($afterDisk['version']!==APP_VERSION)];
    }finally{@flock($gate,LOCK_UN);@fclose($gate);}
}
/* مرورگر endpoint سبک زیر را دوره‌ای صدا می‌زند؛ worker نیز پایین loop آن را
 * اجرا می‌کند. requestهای عادی هرگز منتظر شبکهٔ GitHub نمی‌مانند. */
if(isset($_GET['code_auto_update'])){
    header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store');
    $_tickRes=s4AutoCodeUpdateTick(!empty($_GET['force']??$_POST['force']??null));
    $_slotRecycled=function_exists('s4RecycleOutdatedExtractSlotProcesses')?s4RecycleOutdatedExtractSlotProcesses((string)($_tickRes['disk_version']??APP_VERSION)):[];
    if($_slotRecycled)$_tickRes['recycled_extract_slot_pids']=$_slotRecycled;
    echo json_encode($_tickRes,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;
}
if(isset($_GET['code_update_sync_state'])){
    header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store');
    $br=trim((string)($_POST['branch']??($_GET['branch']??'')));
    $st=s4SyncAutoUpdateStateToDisk($br,false);
    echo json_encode(['ok'=>true,'version'=>$st['to_version'],'sha'=>$st['sha'],'branch'=>$br],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;
}
if(isset($_GET['code_update_status'])){
    header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');$cfg=vc_load();$wp=s4CodeUpdateAdminAuth();
    $disk=s4DiskCodeMeta();
    $auto=[];if(is_file(S4_CODE_UPDATE_STATE_FILE)){$aj=json_decode((string)@file_get_contents(S4_CODE_UPDATE_STATE_FILE),true);if(is_array($aj))$auto=$aj;}
    echo json_encode(['ok'=>true,'version'=>APP_VERSION,'disk_version'=>$disk['version'],'disk_sha'=>$disk['sha'],'endpoint'=>basename(__FILE__).'?code_update=1','method'=>'POST',
        'auto_update'=>true,'auto_interval'=>S4_CODE_UPDATE_INTERVAL,'auto_endpoint'=>'?code_auto_update=1','auto_state'=>$auto,
        'deploy_php_required'=>false,'source'=>S4_CODE_UPDATE_REPO.'@'.implode(',',vc_normalize_branches((array)($cfg['branches']??[]))).':'.S4_CODE_UPDATE_PATH,
        'branches'=>vc_normalize_branches((array)($cfg['branches']??[])),'pinned_branch'=>(string)($cfg['pinned_branch']??''),'token_configured'=>trim((string)($cfg['deploy_token']??''))!=='','admin'=>!empty($wp['admin']),
        'nonce'=>!empty($wp['admin'])&&function_exists('wp_create_nonce')?wp_create_nonce('s4_code_update'):''],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;
}
if(isset($_GET['code_update'])||($_POST['action']??'')==='code_update'){
    header('Content-Type: application/json; charset=UTF-8');
    if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST'){http_response_code(405);echo json_encode(['ok'=>false,'error'=>'POST required'],JSON_UNESCAPED_UNICODE);exit;}
    $r=s4CodeUpdateRun();if(empty($r['ok']))http_response_code((int)($r['http']??500));unset($r['http']);echo json_encode($r,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;
}

/** Store Online Chat Human Support Desk API */
if (isset($_GET['store_chat_api']) || isset($_POST['store_chat_api'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $api_action = $_GET['store_chat_api'] ?: ($_POST['store_chat_api'] ?? 'get_threads');
    $threads_file = __DIR__ . '/chat_threads.json';

    // Auto-bootstrap WordPress if available
    if (!function_exists('get_option')) {
        $wp_loader_candidates = [
            __DIR__ . '/wp-load.php',
            dirname(__DIR__) . '/wp-load.php',
            dirname(dirname(__DIR__)) . '/wp-load.php',
            dirname(dirname(dirname(__DIR__))) . '/wp-load.php',
        ];
        foreach ($wp_loader_candidates as $loader) {
            if (file_exists($loader)) {
                @require_once $loader;
                break;
            }
        }
    }

    $threads = [];
    if (function_exists('get_option')) {
        $threads = get_option('scraper_chat_threads', []);
    }
    if (empty($threads) && file_exists($threads_file)) {
        $threads = @json_decode(file_get_contents($threads_file), true) ?: [];
    }
    if (!is_array($threads)) $threads = [];

    if ($api_action === 'get_threads') {
        $unread_total = 0;
        foreach ($threads as $t) {
            if (!empty($t['unread_admin'])) $unread_total++;
        }
        echo json_encode(['ok' => true, 'threads' => $threads, 'unread_total' => $unread_total], JSON_UNESCAPED_UNICODE);
        exit;
    }

    if ($api_action === 'send_reply') {
        $thread_id = trim((string)($_POST['thread_id'] ?? ''));
        $reply_text = trim((string)($_POST['reply_text'] ?? ''));
        if ($thread_id === '' || $reply_text === '') {
            echo json_encode(['ok' => false, 'error' => 'متن پاسخ یا شناسه گفتگو خالی است.'], JSON_UNESCAPED_UNICODE);
            exit;
        }

        $now = time();
        $time_str = date('H:i');
        $found = false;
        $updated_thread = null;

        foreach ($threads as &$t) {
            if (($t['id'] ?? '') === $thread_id) {
                $t['unread_admin'] = false;
                $t['status'] = 'replied';
                $t['updated_at'] = $now;
                $admin_msg = [
                    'id' => 'msg_' . $now . '_' . rand(100, 999),
                    'sender' => 'admin',
                    'sender_name' => 'ادمین فروشگاه (پاسخ انسانی از اسکریپر)',
                    'text' => $reply_text,
                    'time' => $time_str,
                    'timestamp' => $now,
                ];
                if (!isset($t['messages']) || !is_array($t['messages'])) {
                    $t['messages'] = [];
                }
                $t['messages'][] = $admin_msg;
                $found = true;
                $updated_thread = $t;
                break;
            }
        }
        unset($t);

        if (!$found) {
            echo json_encode(['ok' => false, 'error' => 'گفتگوی مورد نظر یافت نشد.'], JSON_UNESCAPED_UNICODE);
            exit;
        }

        // Save to JSON file and WP DB
        @file_put_contents($threads_file, json_encode($threads, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE), LOCK_EX);
        if (function_exists('update_option')) {
            update_option('scraper_chat_threads', $threads, false);
        }

        // Dispatch to Messengers (Bale, Telegram, Rubika)
        $conn = [];
        if (function_exists('loadConnections')) {
            $conn = loadConnections();
        } elseif (file_exists(__DIR__ . '/connections.json')) {
            $conn = @json_decode(file_get_contents(__DIR__ . '/connections.json'), true) ?: [];
        }

        $c_name = $updated_thread['name'] ?? 'مشتری فروشگاه';
        $c_phone = $updated_thread['phone'] ?? '';
        $dispatch_msg = "🧑‍💼 پاسخ انسانی ادمین به مشتری (ثبت شده از اسکریپر):\n👤 مشتری: {$c_name}" . ($c_phone ? " ({$c_phone})" : '') . "\n💬 پاسخ: {$reply_text}\n⏰ زمان: {$time_str}";

        // Telegram
        $tg_bot = $conn['telegram_bot_token'] ?? ($conn['telegram_token'] ?? '');
        $tg_chat = $conn['telegram_chat_id'] ?? '';
        if ($tg_bot && $tg_chat) {
            @file_get_contents('https://api.telegram.org/bot' . urlencode($tg_bot) . '/sendMessage?chat_id=' . urlencode($tg_chat) . '&text=' . urlencode($dispatch_msg));
        }

        // Bale
        $bale_bot = $conn['bale_token'] ?? ($conn['bale_bot_token'] ?? '');
        $bale_chat = $conn['bale_chat_id'] ?? '';
        if ($bale_bot && $bale_chat) {
            @file_get_contents('https://tapi.bale.ai/bot' . urlencode($bale_bot) . '/sendMessage?chat_id=' . urlencode($bale_chat) . '&text=' . urlencode($dispatch_msg));
        }

        echo json_encode(['ok' => true, 'thread' => $updated_thread, 'msg' => 'پاسخ با موفقیت به مشتری و پیام‌رسان‌ها ارسال شد.'], JSON_UNESCAPED_UNICODE);
        exit;
    }
}

/** مقایسهٔ نسخه — هیچ چیزی دانلود یا نوشته نمی‌شود */
if (isset($_GET['vc_check'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $c = vc_load();

    if (empty($_GET['force']) && empty($c['check_on_load'])) {
        echo json_encode(['ok' => true, 'skipped' => true, 'update' => false]);
        exit;
    }
    if (trim((string)$c['repo']) === '' || trim((string)$c['path']) === '') {
        echo json_encode(['ok' => false, 'error' => 'ریپو یا مسیر فایل تنظیم نشده'], JSON_UNESCAPED_UNICODE);
        exit;
    }

    $local = vc_content_id((string)@file_get_contents(__FILE__));
    $probe=vc_probe_branches($c);$candidates=$probe['rows'];
    if(!$candidates){
        echo json_encode(['ok'=>false,'error'=>'هیچ‌یک از برنچ‌های تنظیم‌شده قابل بررسی نبود','branch_errors'=>$probe['errors']],JSON_UNESCAPED_UNICODE);exit;
    }
    $winner=empty($_GET['force'])?(vc_pick_target_branch($c,$candidates)??$candidates[0]):$candidates[0];
    $c['last_check']=time();$c['branch']=$winner['branch'];vc_save($c);
    echo json_encode([
        'ok'=>true,'update'=>$winner['sha']!==$local,'local_id'=>substr($local,0,8),
        'remote_id'=>substr($winner['sha'],0,8),'remote_size'=>$winner['size'],
        'local_size'=>(int)@filesize(__FILE__),'branch'=>$winner['branch'],'commit_time'=>$winner['timestamp'],
        'branches'=>$candidates,'branch_errors'=>$probe['errors'],'path'=>$c['path'],
        'deploy_ready'=>$c['deploy_token']!==''&&is_file(__DIR__.'/'.basename($c['deploy_file'])),
        'deploy_file'=>basename($c['deploy_file']),
    ],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    exit;
}

/** فهرست برنچ‌ها — فقط خواندنی */
if (isset($_GET['vc_branches'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $c = vc_load();
    $repo = trim((string)($_GET['repo'] ?? $c['repo']));
    if (!preg_match('~^[\w.-]+/[\w.-]+$~', $repo)) {
        echo json_encode(['ok' => false, 'error' => 'نام ریپو نامعتبر است (قالب: user/repo)'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $r = vc_get_json_auto('https://api.github.com/repos/' . $repo . '/branches?per_page=100', $c['github_token']);
    if (!$r['ok']) {
        echo json_encode([
            'ok' => false,
            'error' => vc_http_error((int)$r['code'], (string)$r['error'], $c['github_token'] !== ''),
            'code' => (int)$r['code'],
            'bad_token' => (int)$r['code'] === 401,
        ], JSON_UNESCAPED_UNICODE);
        exit;
    }
    if (!empty($r['token_rejected'])) { $c['github_token'] = ''; vc_save($c); }
    $out = [];
    foreach ($r['data'] as $b) {
        if (!empty($b['name'])) $out[] = ['name' => $b['name'], 'sha' => substr((string)($b['commit']['sha'] ?? ''), 0, 7)];
    }
    echo json_encode(['ok' => true, 'branches' => $out], JSON_UNESCAPED_UNICODE);
    exit;
}

/** فهرست فایل‌های PHP یک برنچ — فقط خواندنی */
if (isset($_GET['vc_files'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $c = vc_load();
    $repo   = trim((string)($_GET['repo'] ?? $c['repo']));
    $branch = trim((string)($_GET['branch'] ?? $c['branch']));
    if (!preg_match('~^[\w.-]+/[\w.-]+$~', $repo) || $branch === '') {
        echo json_encode(['ok' => false, 'error' => 'ریپو و برنچ لازم است'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $r = vc_get_json_auto('https://api.github.com/repos/' . $repo . '/git/trees/' . rawurlencode($branch) . '?recursive=1', $c['github_token'], 30);
    if (!$r['ok'] || !isset($r['data']['tree'])) {
        echo json_encode([
            'ok' => false,
            'error' => vc_http_error((int)$r['code'], (string)$r['error'], $c['github_token'] !== ''),
            'code' => (int)$r['code'],
            'bad_token' => (int)$r['code'] === 401,
        ], JSON_UNESCAPED_UNICODE);
        exit;
    }
    if (!empty($r['token_rejected'])) { $c['github_token'] = ''; vc_save($c); }
    $files = [];
    foreach ($r['data']['tree'] as $n) {
        if (($n['type'] ?? '') !== 'blob') continue;
        $p = (string)$n['path'];
        if (!preg_match('~\.php\d?$~i', $p)) continue;
        $files[] = ['path' => $p, 'size' => (int)($n['size'] ?? 0)];
    }
    usort($files, fn($a, $b) => $b['size'] <=> $a['size']);
    echo json_encode(['ok' => true, 'files' => $files], JSON_UNESCAPED_UNICODE);
    exit;
}

/** تنظیمات بررسی نسخه */
if (isset($_GET['vc_settings'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $c = vc_load();
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
        if (!empty($_POST['pin_only']) || !empty($_POST['unpin_only'])) {
            if (!empty($_POST['pin_only'])) {
                $pinB = trim((string)($_POST['pin_branch'] ?? ''));
                if ($pinB !== '' && in_array($pinB, $c['branches'], true)) {
                    $maxUnix = time();
                    if (!empty($c['repo']) && !empty($c['path'])) {
                        $pr = vc_probe_branches($c);
                        foreach ($pr['rows'] as $r0) { if ((int)($r0['unix'] ?? 0) > $maxUnix) $maxUnix = (int)$r0['unix']; }
                    }
                    $c['branch'] = $pinB;
                    $c['pinned_branch'] = $pinB;
                    $c['pinned_at'] = time();
                    $c['pinned_max_unix'] = $maxUnix;
                    vc_save($c);
                }
                s4SyncAutoUpdateStateToDisk($pinB, true);
            } else {
                $c['pinned_branch'] = '';
                $c['pinned_at'] = 0;
                $c['pinned_max_unix'] = 0;
                vc_save($c);
                s4SyncAutoUpdateStateToDisk('', true);
            }
            echo json_encode(['ok' => true, 'pinned_branch' => $c['pinned_branch']], JSON_UNESCAPED_UNICODE);
            exit;
        }
        $c['check_on_load'] = !empty($_POST['check_on_load']);
        if (isset($_POST['repo']))        $c['repo']        = trim((string)$_POST['repo']);
        if (isset($_POST['branches'])) {
            $decoded=json_decode((string)$_POST['branches'],true);
            if(!is_array($decoded)){$decoded=preg_split('~[\r\n,]+~',(string)$_POST['branches']);}
            $c['branches']=vc_normalize_branches((array)$decoded);
        }
        if (isset($_POST['branch']))      $c['branch']      = trim((string)$_POST['branch']);
        if(!$c['branches'])$c['branches']=vc_normalize_branches([(string)$c['branch']]);
        if(!in_array((string)$c['branch'],$c['branches'],true))$c['branch']=$c['branches'][0]??'arena/e868e86a-new';
        if (isset($_POST['path']))        $c['path']        = ltrim(trim((string)$_POST['path']), '/');
        if (isset($_POST['deploy_file'])) $c['deploy_file'] = basename(trim((string)$_POST['deploy_file']));
        foreach (['github_token', 'deploy_token'] as $k) {
            $v = (string)($_POST[$k] ?? '');
            if ($v === '__CLEAR__')  $c[$k] = '';
            elseif (trim($v) !== '') $c[$k] = trim($v);
        }
        if (!vc_save($c)) { echo json_encode(['ok' => false, 'error' => 'ذخیرهٔ تنظیمات ناموفق']); exit; }
    }
    $deployPath = __DIR__ . '/' . basename($c['deploy_file']);
    $out = $c;
    $out['github_token']   = '';
    $out['deploy_token']   = '';
    $out['has_gh_token']   = $c['github_token'] !== '';
    $out['has_dep_token']  = $c['deploy_token'] !== '';
    $out['deploy_present'] = is_file($deployPath);
    $out['self_name']      = basename(__FILE__);
    $out['local_id']       = substr(vc_content_id((string)@file_get_contents(__FILE__)), 0, 8);
    $out['local_size']     = (int)@filesize(__FILE__);
    echo json_encode(['ok' => true, 'settings' => $out], JSON_UNESCAPED_UNICODE);
    exit;
}

