/** Resolve a matrix row to one saved profile. Destination-only coded rows are
 * assigned only when exactly one profile suffix occurs in their destination
 * title; uncoded rows deliberately remain miscellaneous. */
function matrixRowProfileScopeKey(array $row,array $profiles):string{
    $pk=(string)($row['profile_key']??'');if($pk!==''&&isset($profiles[$pk]))return$pk;
    $titles=[(string)($row['title']??'')];if(is_array($row['woo']??null))$titles[]=(string)($row['woo']['title']??'');
    foreach((array)($row['shops']??[])as$c)if(is_array($c))$titles[]=(string)($c['title']??'');
    $hits=[];foreach($profiles as$key=>$profile){if(!is_array($profile))continue;$suffix=trim((string)($profile['titleSuffix']??''));if($suffix==='')continue;
        foreach($titles as$title)if($title!==''&&mb_strpos($title,$suffix)!==false){$hits[(string)$key]=true;break;}}
    return count($hits)===1?(string)array_key_first($hits):'';
}
/** ردیف متفرقه فقط محصول واقعاً فعال و قابل فروش باسلام است. دادهٔ archive
 * قدیمی با status خالی و stock=0 در ماتریس می‌ماند، اما موجودی فروشگاه نیست. */
function startMatrixMiscBslCellIsSellable(array $cell):bool{
    $status=$cell['status']??'';if(is_array($status))$status=$status['value']??$status['id']??'';
    return (string)$status==='2976'&&(int)($cell['stock']??0)>0;
}
/** v10.426: destination inventory per saved profile, derived only from the
 * latest completed discrepancy matrix (no destination network requests). */
function startMatrixDestinationStats(array $matrix,array $profiles):array{
    $selected=array_values((array)($matrix['selected_destinations']??[]));$selectedSet=array_fill_keys($selected,true);
    $dest=[];
    if(isset($selectedSet['woo']))$dest['woo']=['key'=>'woo','type'=>'woo','label'=>'ووکامرس'];
    foreach((array)($matrix['shops']??[]) as $shop){
        if(!is_array($shop))continue;$vid=(int)($shop['vendor_id']??0);$key='bsl:'.$vid;
        if($vid<=0||!isset($selectedSet[$key]))continue;
        $dest[$key]=['key'=>$key,'type'=>'bsl','vendor_id'=>$vid,'label'=>(string)($shop['name']??('غرفه '.$vid))];
    }
    $known=array_fill_keys(array_map('strval',array_keys($profiles)),true);$ids=[];$uncoded=[];$priceMismatch=[];
    foreach($known as $pk=>$_)foreach($dest as $dk=>$_d){$ids[$pk][$dk]=[];$priceMismatch[$pk][$dk]=[];}
    foreach($dest as$dk=>$meta)if(($meta['type']??'')==='bsl')$uncoded[$dk]=[];
    foreach((array)($matrix['rows']??[]) as $ri=>$row){
        if(!is_array($row))continue;
        foreach($dest as$dk=>$meta){if(($meta['type']??'')!=='bsl')continue;$vid=(int)$meta['vendor_id'];$cells=[];
            $main=$row['shops'][$vid]??$row['shops'][(string)$vid]??null;if(is_array($main))$cells[]=$main;
            foreach((array)($row['shop_extra'][$vid]??$row['shop_extra'][(string)$vid]??[])as$ex)if(is_array($ex))$cells[]=$ex;
            foreach($cells as$c){$id=(int)($c['id']??0);$title=(string)($c['title']??$row['title']??'');
                $coded=matrixTitleHasCode($title)||matrixRowHasCode($row);
                if($id>0&&startMatrixMiscBslCellIsSellable($c)&&!$coded)$uncoded[$dk][(string)$id]=[
                'id'=>$id,'title'=>$title!==''?$title:'بدون عنوان','price'=>(int)($c['price']??0),
                'stock'=>(int)($c['stock']??0),'status'=>(string)($c['status']??''),
                'destination'=>$dk,'shop'=>(string)($meta['label']??''),
                'url'=>'https://basalam.com/p/'.$id];}
        }
        $pk=matrixRowProfileScopeKey($row,$profiles);if($pk===''||!isset($known[$pk]))continue;
        if(isset($dest['woo'])&&is_array($row['woo']??null)){
            $id=(int)($row['woo']['id']??0);if($id>0)$ids[$pk]['woo'][(string)$id]=true;
            /* woo_tone is calculated by matrixPriceTone after applying the
               saved profile + destination adjustment coefficients. */
            if($id>0&&in_array((string)($row['woo_tone']??'na'),['bad','warn'],true))$priceMismatch[$pk]['woo'][(string)$ri]=true;
            foreach((array)($row['woo_extra']??[]) as $ex){$id=(int)($ex['id']??0);if($id>0)$ids[$pk]['woo'][(string)$id]=true;}
        }
        foreach($dest as $dk=>$meta){if(($meta['type']??'')!=='bsl')continue;$vid=(int)$meta['vendor_id'];
            $cell=$row['shops'][$vid]??$row['shops'][(string)$vid]??null;
            if(is_array($cell)){$id=(int)($cell['id']??0);if($id>0)$ids[$pk][$dk][(string)$id]=true;if($id>0&&in_array((string)($cell['tone']??'na'),['bad','warn'],true))$priceMismatch[$pk][$dk][(string)$ri]=true;}
            $extras=$row['shop_extra'][$vid]??$row['shop_extra'][(string)$vid]??[];
            foreach((array)$extras as $ex){$id=(int)($ex['id']??0);if($id>0)$ids[$pk][$dk][(string)$id]=true;}
        }
    }
    $counts=[];$totals=array_fill_keys(array_keys($dest),0);$mismatchCounts=[];$mismatchTotals=array_fill_keys(array_keys($dest),0);
    foreach($known as $pk=>$_){foreach($dest as $dk=>$_d){
        $n=count($ids[$pk][$dk]??[]);$counts[$pk][$dk]=$n;$totals[$dk]+=$n;
        $mn=count($priceMismatch[$pk][$dk]??[]);$mismatchCounts[$pk][$dk]=$mn;$mismatchTotals[$dk]+=$mn;
    }}
    foreach($dest as$dk=>&$meta)$meta['uncoded']=count($uncoded[$dk]??[]);unset($meta);
    $uncodedProducts=[];foreach($uncoded as$dk=>$items)$uncodedProducts[$dk]=array_values($items);
    return ['generated_at'=>(int)($matrix['generated_at']??0),'source'=>(string)($matrix['source']??''),
        'destinations'=>array_values($dest),'counts'=>$counts,'totals'=>$totals,
        'price_mismatch_counts'=>$mismatchCounts,'price_mismatch_totals'=>$mismatchTotals,
        'uncoded'=>array_map('count',$uncoded),'uncoded_products'=>$uncodedProducts];
}

/* v10.434: one safe, independently retriable action for the Start-tab
   miscellaneous modal. The browser batches selected rows with limited
   concurrency, so a large select-all never depends on one long HTTP request. */
if(isset($_POST['start_misc_product_action'])){
    header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store');
    $action=(string)($_POST['misc_action']??'');$destination=trim((string)($_POST['destination']??''));
    $pid=(int)($_POST['product_id']??0);$title=trim((string)($_POST['title']??''));
    if(!in_array($action,['archive','rename'],true)||!preg_match('~^bsl:(\d+)$~',$destination,$dm)||$pid<=0){
        http_response_code(400);echo json_encode(['ok'=>false,'error'=>'درخواست محصول متفرقه نامعتبر است'],JSON_UNESCAPED_UNICODE);exit;
    }
    $vid=(int)$dm[1];$matrix=matrixResultLoad();$stats=startMatrixDestinationStats($matrix,loadProfiles());$allowed=[];
    foreach((array)($stats['uncoded_products'][$destination]??[])as$p)if((int)($p['id']??0)>0)$allowed[(int)$p['id']]=$p;
    if(!isset($allowed[$pid])){http_response_code(409);echo json_encode(['ok'=>false,'error'=>'این محصول دیگر در فهرست متفرقهٔ فعال نیست؛ جدول را تازه کنید'],JSON_UNESCAPED_UNICODE);exit;}
    $cn=loadConnections();$shop=null;foreach(bslAllShops($cn)as$sh)if((int)($sh['vendor_id']??0)===$vid){$shop=$sh;break;}
    $tk=trim((string)($shop['token']??''));if($tk===''){http_response_code(400);echo json_encode(['ok'=>false,'error'=>'توکن این غرفه در دسترس نیست'],JSON_UNESCAPED_UNICODE);exit;}
    if($action==='rename'){
        $len=mb_strlen($title);if($len<2||$len>120){http_response_code(422);echo json_encode(['ok'=>false,'error'=>'عنوان باید بین ۲ تا ۱۲۰ نویسه باشد'],JSON_UNESCAPED_UNICODE);exit;}
        $r=bslEditProduct($tk,$vid,$pid,['name'=>$title]);
        if(empty($r['ok'])){http_response_code(422);echo json_encode(['ok'=>false,'error'=>bslApiError($r,'تغییر عنوان ناموفق','products/'.$pid)],JSON_UNESCAPED_UNICODE);exit;}
        $msg='عنوان محصول #'.$pid.' تغییر کرد';
    }else{
        $r=bslSetProductStatus($tk,$vid,$pid,4184,'auto');
        if(empty($r['ok'])){http_response_code(422);echo json_encode(['ok'=>false,'error'=>bslApiError($r,'حذف/بایگانی ناموفق','products/'.$pid)],JSON_UNESCAPED_UNICODE);exit;}
        $msg='محصول #'.$pid.' از غرفه حذف/بایگانی شد';
    }
