    echo json_encode(['ok'=>true,'action'=>$action,'destination'=>$destination,'product_id'=>$pid,'title'=>$title,'msg'=>$msg],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;
