if(isset($_POST['start_profile_destination_equalize'])){
    header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store');
    $pk=trim((string)($_POST['profile_key']??''));$destination=trim((string)($_POST['destination']??''));
    $profiles=loadProfiles();$cn=loadConnections();$allowed=matrixNormalizeDestinations([$destination],$cn);
    if($pk===''||!isset($profiles[$pk])){http_response_code(404);echo json_encode(['ok'=>false,'error'=>'profile_not_found'],JSON_UNESCAPED_UNICODE);exit;}
    if($destination===''||!in_array($destination,$allowed,true)){http_response_code(400);echo json_encode(['ok'=>false,'error'=>'destination_not_enabled'],JSON_UNESCAPED_UNICODE);exit;}
    $requested=time();$chain='cell_equalize|'.substr(sha1($pk.'|'.$destination),0,16);
    /* v10.436: equalization is owned by a real full-profile destination queue.
       It must not wait for, or fail because of, stale/missing Start-table counts
       or a busy discrepancy build. The matrix refresh below is best-effort only. */
    $sendProfile=$profiles[$pk];$sendProfile['name']=(string)($profiles[$pk]['name']??$pk).' · برابر‌سازی مقصد';$sendProfile['syncConfig']=array_merge((array)($sendProfile['syncConfig']??[]),[
        'target'=>$destination==='woo'?'woo':'bsl','actionBasis'=>'profile','wooOnlyChanged'=>false,'bslOnlyChanged'=>false]);
    $sendOpts=['target'=>$destination==='woo'?'woo':'bsl','trigger'=>'cell_equalize','replace_waiting'=>false,'allow_parallel'=>true];
    $targetVid=str_starts_with($destination,'bsl:')?(int)substr($destination,4):0;if($targetVid>0)$sendOpts['bsl_vendor_id']=$targetVid;
    $queueIds=[];$existingQ=$destination==='woo'?wooReadQueue():bslReadQueue();
    foreach((array)($existingQ['entries']??[])as$qe){if(!is_array($qe)||(string)($qe['profile_key']??'')!==$pk||!in_array((string)($qe['status']??''),['waiting','running','paused'],true))continue;
        if($targetVid>0&&(int)($qe['shop_vendor_id']??$qe['config']['shop_vendor_id']??0)!==$targetVid)continue;$queueIds[]=(string)($qe['id']??'');}
    $queueIds=array_values(array_unique(array_filter($queueIds)));
    $send=$queueIds?['ok'=>true,'existing'=>true,'queue_ids'=>$queueIds,'log'=>['صف فعال همین سلول دوباره استفاده شد']]
        :manualSyncEnqueueSends($pk,$sendProfile,$cn,['ok'=>true],$sendOpts);
    if(!$queueIds)$queueIds=array_values(array_unique(array_filter(array_map('strval',(array)($send['queue_ids']??[])))));
    if(!$queueIds){
        $sendError=(string)($send['error']??implode(' · ',array_filter(array_map('strval',(array)($send['log']??[])))));
        if($sendError==='')$sendError='برای این پروفایل و مقصد صف ارسالی ساخته نشد';
        syncPipelineMark($pk,(string)($profiles[$pk]['name']??$pk),'error','manual',[
            'pipeline_key'=>'cell:'.$pk.':'.$destination,'operation'=>'cell_equalize','destination'=>$destination,
            'message'=>'ساخت صف واقعی مقصد ناموفق بود','error'=>$sendError]);
        http_response_code(409);echo json_encode(['ok'=>false,'error'=>$sendError,'code'=>'send_queue_not_created','send'=>$send],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;
    }

    /* Refresh/correction is useful for destination-only removals, but it is no
       longer a prerequisite for add/update equalization. Busy/deduplicated
       matrix workers are reported without turning the button action into an error. */
    $build=s4WorkerEnqueueMatrixBuild(['profile'=>$pk,'parallel_destinations'=>false,'live_fill'=>true,
        'selected_destinations'=>[$destination],'slice_seconds'=>20,'source'=>'start_cell_equalize','dedup_key'=>'matrix_build|'.$chain],false);
    $fix=['ok'=>false,'skipped'=>'build_not_queued'];
    if(!empty($build['ok']))$fix=s4WorkerEnqueueMatrixFix(['scope'=>$destination==='woo'?'woo':'bsl','source'=>'start_cell_equalize','delay_ms'=>120,
        'duplicate_keep'=>'newest','view_filters'=>['target_profile_key'=>$pk],
        'selected_destinations'=>[$destination],'min_matrix_generated_at'=>$requested,'dedup_key'=>'matrix_fix|'.$chain],false);
    $matrixOptional=['build_queued'=>!empty($build['ok']),'fix_queued'=>!empty($fix['ok']),
        'build_error'=>(string)($build['error']??''),'fix_error'=>(string)($fix['error']??$fix['skipped']??'')];
    syncPipelineMark($pk,(string)($profiles[$pk]['name']??$pk),'send','manual',[
        'pipeline_key'=>'cell:'.$pk.':'.$destination,
        'operation'=>'cell_equalize','destination'=>$destination,'send_queue_ids'=>$queueIds,
        'matrix_build_job_id'=>(string)($build['job_id']??''),'matrix_fix_job_id'=>(string)($fix['job_id']??''),
        'matrix_refresh_optional'=>$matrixOptional,
        'message'=>'برابر‌سازی مستقیم از پروفایل ذخیره‌شده؛ تازه‌سازی شمارش‌ها اختیاری است',
        'stage_details'=>['send'=>syncSendStageDetails(['queued'=>(int)($send['woo_total']??$send['bsl_total']??0),
            'message'=>'صف واقعی مقصد مستقل از شمارش جدول ساخته شد؛ پایداری و ادامه از تب ارسال'])]]);
    $sendDispatch=function_exists('s4DispatchPendingSendQueue')
        ?s4DispatchPendingSendQueue($destination==='woo'?'woo':'bsl',(string)($queueIds[0]??''))
        :['ok'=>false,'reason'=>'helper_missing'];
    $spawn=s4WorkerIsActive()?['ok'=>true,'already_active'=>true]:s4SpawnPersistentWorker();
    echo json_encode(['ok'=>true,'queued'=>true,'profile_key'=>$pk,'destination'=>$destination,
        'build_job_id'=>(string)($build['job_id']??''),'fix_job_id'=>(string)($fix['job_id']??''),'matrix_refresh_optional'=>$matrixOptional,
        'send_queue_ids'=>$queueIds,'send'=>$send,'send_dispatch'=>$sendDispatch,'worker'=>$spawn,
        'message'=>'صف برابر‌سازی مستقیم ساخته شد؛ شمارش جدول شرط اجرا نیست'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);exit;
}

if (isset($_GET['start_product_stats'])) {
    header('Content-Type: application/json; charset=UTF-8');
    header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
    $defs = ['total','priced','no_price','in_stock','out_stock','stock_unknown','with_image','no_image',
        'gallery','variations','linked','sku','description','category','brand','ready'];
    $totals = array_fill_keys($defs, 0); $byProfile = []; $samples = array_fill_keys($defs, []);
    $profiles = loadProfiles();
    $matrixStats=startMatrixDestinationStats(function_exists('matrixResultLoad')?matrixResultLoad():[],$profiles);
    foreach ($profiles as $pk => $profile) {
        if (!is_array($profile)) continue;
        $pn = trim((string)($profile['name'] ?? $pk)); $pm = array_fill_keys($defs, 0);
        foreach (profileProductsMap($profile) as $productKey => $p) {
            if (!is_array($p)) continue;
            $priceOk = extractPriceNum($p['price'] ?? 0) > 0;
            $images = productImageList($p); $imageOk = count($images) > 0;
            $linkRaw = trim((string)($p['link'] ?? $p['url'] ?? ''));
            $linkOk = $linkRaw !== '' && (bool)preg_match('#^https?://#i', $linkRaw);
            $skuOk = trim((string)($p['sku'] ?? '')) !== '';
            $descOk = trim((string)($p['shortDesc'] ?? $p['short_desc'] ?? $p['longDesc'] ?? $p['description'] ?? '')) !== '';
            $cat = $p['category'] ?? $p['categories'] ?? ''; $catOk = is_array($cat) ? count($cat) > 0 : trim((string)$cat) !== '';
            $brandOk = trim((string)($p['brand'] ?? '')) !== '';
            $vars = $p['variations'] ?? []; $varOk = is_array($vars) ? count($vars) > 0 : trim((string)$vars) !== '';
            $hasStock = array_key_exists('stock', $p) || array_key_exists('inventory', $p) || array_key_exists('stock_quantity', $p) || array_key_exists('stock_status', $p);
            $stockRaw = $p['stock'] ?? $p['inventory'] ?? $p['stock_quantity'] ?? null;
            $stockStatus = strtolower(trim((string)($p['stock_status'] ?? '')));
            $stockIn = $hasStock && ($stockStatus === 'instock' || (is_numeric($stockRaw) && (int)$stockRaw > 0));
            $stockOut = $hasStock && ($stockStatus === 'outofstock' || $stockStatus === 'out_of_stock' || (is_numeric($stockRaw) && (int)$stockRaw <= 0));
            $flags = ['total'=>true,'priced'=>$priceOk,'no_price'=>!$priceOk,'in_stock'=>$stockIn,'out_stock'=>$stockOut,
                'stock_unknown'=>!$stockIn&&!$stockOut,'with_image'=>$imageOk,'no_image'=>!$imageOk,'gallery'=>count($images)>1,
                'variations'=>$varOk,'linked'=>$linkOk,'sku'=>$skuOk,'description'=>$descOk,'category'=>$catOk,'brand'=>$brandOk,
                'ready'=>$priceOk&&$imageOk&&$linkOk];
            $sample = ['title'=>mb_substr(trim((string)($p['title'] ?? $productKey)),0,100),'profile'=>$pn,
                'price'=>extractPriceNum($p['price'] ?? 0),'images'=>count($images),'link'=>$linkOk ? $linkRaw : ''];
            foreach ($flags as $metric => $yes) if ($yes) { $totals[$metric]++; $pm[$metric]++; if (count($samples[$metric]) < 8) $samples[$metric][] = $sample; }
        }
        $detailSummary=extractProfileDetailSummary($profile);
        $byProfile[] = ['key'=>(string)$pk,'name'=>$pn,'updated_at'=>(int)($profile['updatedAt'] ?? 0),
            'counts'=>$pm,'detail'=>$detailSummary,'destinations'=>(array)($matrixStats['counts'][(string)$pk]??[]),
            'price_mismatches'=>(array)($matrixStats['price_mismatch_counts'][(string)$pk]??[])];
    }
    usort($byProfile, static fn($a,$b) => (int)$b['counts']['total'] <=> (int)$a['counts']['total']);
    echo json_encode(['ok'=>true,'generated_at'=>time(),'profiles'=>count($profiles),'totals'=>$totals,'by_profile'=>$byProfile,'samples'=>$samples,
        'matrix'=>['generated_at'=>(int)$matrixStats['generated_at'],'source'=>(string)$matrixStats['source'],
            'destinations'=>$matrixStats['destinations'],'totals'=>$matrixStats['totals'],
            'price_mismatch_totals'=>$matrixStats['price_mismatch_totals'],
            'uncoded_products'=>$matrixStats['uncoded_products']]],
        JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE); exit;
}

if (!empty($_GET['load_profile'])) {
header('Content-Type: application/json; charset=UTF-8');
$rawLoad = trim((string)($_GET['load_profile'] ?? ''));
$url = s4NormalizeInputUrl($rawLoad);
