if (($_POST['action'] ?? '') === 'save_profile') {
s4SettingsPriorityRequestBegin();
header('Content-Type: application/json; charset=UTF-8');
$url = s4NormalizeInputUrl((string)($_POST['url'] ?? ''));
if (!$url || !filter_var($url, FILTER_VALIDATE_URL)) {
echo json_encode(['ok' => false, 'error' => 'Invalid URL']);
exit;
}
$profiles = loadProfiles();
$targetKeyIn = trim((string)($_POST['target_key'] ?? ''));
$key = s4ResolveSaveProfileTargetKey($url, $targetKeyIn, $profiles);
$existingProfile = is_array($profiles[$key] ?? null) ? $profiles[$key] : [];
/* v10.336 + v10.439: autosave یک تب قدیمی، فرمی که هنوز profile را نگرفته،
   یا پروفایلی که تازه حذف شده است هرگز نباید روی سرور دوباره ساخته شود. */
$isAutosave = !empty($_POST['autosave']);
$loadedUpdatedAt = max(0, (int)($_POST['loaded_updated_at'] ?? 0));
$serverUpdatedAt = max(0, (int)($existingProfile['updatedAt'] ?? 0));
if ($isAutosave && (!$existingProfile || s4IsProfileDeletedTombstone($key) || $loadedUpdatedAt <= 0 || $serverUpdatedAt > $loadedUpdatedAt)) {
    http_response_code(409);
    echo json_encode(['ok'=>false,'error'=>!$existingProfile?'profile_deleted':'stale_profile','message'=>!$existingProfile?'پروفایل حذف شده است؛ ذخیرهٔ خودکار لغو شد.':'پروفایل روی سرور تازه‌تر است؛ آن را دوباره بارگذاری کنید.','key'=>$key,'updated_at'=>$serverUpdatedAt], JSON_UNESCAPED_UNICODE);
    exit;
}
if (!$isAutosave) {
    s4ClearProfileDeletedTombstone($key, $url);
}
$detailSelectors = json_decode($_POST['detailSelectors'] ?? '{}', true) ?: [];
$productsData = json_decode($_POST['products'] ?? '[]', true) ?: [];
$productsOrder = json_decode($_POST['productsOrder'] ?? '[]', true) ?: [];
/* v8.83: ذخیرهٔ پروفایل از مرورگر، محصولات را عیناً می‌نوشت.
   مشکل واقعی این بود: استخراج خودکار روی سرور اجرا می‌شود و گالری را به
   محصولات اضافه می‌کند، ولی تبِ بازِ مرورگر هنوز نسخهٔ قدیمیِ همان
   محصولات را در حافظه دارد. اولین ذخیره — حتی یک ذخیرهٔ خودکار پس از
   تغییر یک تنظیم کوچک — همان نسخهٔ قدیمی را می‌فرستاد و گالری‌ها پاک
   می‌شد. توضیحات و تنوع‌ها سالم می‌ماندند چون در تب هم بودند؛ فقط
   چیزهایی گم می‌شدند که سمت سرور اضافه شده بودند.
   حالا همان تابع ادغامِ استخراج اینجا هم به کار می‌رود. */
/* v8.86: تطبیق فقط با «کلید» کافی نبود.
   ۸.۸۳ محصول را وقتی نجات می‌داد که کلیدش عیناً روی دیسک باشد. ولی سه
   حالت واقعی هست که کلید نمی‌خورد و گالری باز هم پاک می‌شد:
   ۱) تبِ قدیمی کلیدِ فرمولِ قبلی را دارد (یا لینک پارامتر گرفته)،
   ۲) ردیف بدون کلید فرستاده می‌شود،
   ۳) محصولات به‌شکل آرایهٔ تخت می‌آیند، نه جفتِ [کلید، داده].
   حالا اگر کلید نخورد، با لینک و بعد با عنوانِ نرمال‌شده هم می‌گردیم. */
if ($productsData && function_exists('extractMergeDetail')) {
    $prevOnDisk = []; $prevByLink = []; $prevByTitle = [];
    foreach ((array)($profiles[$key]['products'] ?? []) as $e) {
        $pk = null; $pv = null;
        if (is_array($e) && count($e) >= 2 && is_string($e[0]) && is_array($e[1])) {
            $pk = $e[0]; $pv = $e[1];
        } elseif (is_array($e) && isset($e['title'])) {           // شکل تخت
            $pv = $e; $pk = (string)($e['key'] ?? '');
        }
        if (!is_array($pv)) continue;
        if ($pk !== null && $pk !== '') $prevOnDisk[$pk] = $pv;
        $lnk = trim((string)($pv['link'] ?? ''));
        if ($lnk !== '') {
            $lnk = rtrim(preg_replace('~[?#].*$~', '', $lnk), '/');
            if (!isset($prevByLink[$lnk])) $prevByLink[$lnk] = $pv;
        }
        $ttl = function_exists('reconNormTitle') ? reconNormTitle((string)($pv['title'] ?? '')) : '';
        if ($ttl !== '' && !isset($prevByTitle[$ttl])) $prevByTitle[$ttl] = $pv;
    }
    if ($prevOnDisk || $prevByLink || $prevByTitle) {
        foreach ($productsData as $i => $entry) {
            // هر دو شکل پذیرفته می‌شود: [کلید، داده] و شیءِ تخت
            $isPair = is_array($entry) && count($entry) >= 2 && is_array($entry[1] ?? null);
            $cur = $isPair ? $entry[1] : (is_array($entry) ? $entry : null);
            if (!is_array($cur)) continue;

            $k = $isPair ? (string)$entry[0] : (string)($cur['key'] ?? '');
            $prev = ($k !== '' && isset($prevOnDisk[$k])) ? $prevOnDisk[$k] : null;
            if ($prev === null) {
                $lnk = trim((string)($cur['link'] ?? ''));
                if ($lnk !== '') {
                    $lnk = rtrim(preg_replace('~[?#].*$~', '', $lnk), '/');
                    if (isset($prevByLink[$lnk])) $prev = $prevByLink[$lnk];
                }
            }
            if ($prev === null && function_exists('reconNormTitle')) {
                $ttl = reconNormTitle((string)($cur['title'] ?? ''));
                if ($ttl !== '' && isset($prevByTitle[$ttl])) $prev = $prevByTitle[$ttl];
            }
            if ($prev === null) continue;

            $merged = extractMergeDetail($cur, $prev);
            if ($isPair) $productsData[$i][1] = $merged;
            else         $productsData[$i]    = $merged;
        }
    }
}
/* =====================================================================
   v8.91: تنظیماتِ پرزحمت را یک فرمِ پرنشده پاک نکند.

   این دومین علتِ «سلکتورهای گالری فراموش می‌شوند» بود. ذخیرهٔ خودکار
   هر ۲ ثانیه بعد از هر تغییر کوچکی اجرا می‌شود و هرچه در فرم است را
   می‌فرستد. اگر آن لحظه فرم هنوز پر نشده باشد — تبی که تازه باز شده و
   پروفایل هنوز از سرور نیامده، تبِ باز مانده از دیروز، رفرشی که وسط
   بارگذاری قطع شده — سلکتورها و تنظیم گالری خالی می‌رفتند و روی نسخهٔ
   سالمِ روی دیسک می‌نشستند. کاربر هیچ کاری نکرده بود، ولی «روش گالری»
   برمی‌گشت روی «خاموش» و استخراج بعدی دیگر گالری نمی‌گرفت.

   تفاوت «فرم پر نشده» و «کاربر عمداً پاک کرده» از روی سلکتور اصلیِ
   فهرست فهمیده می‌شود: بدون container اصلاً استخراجی در کار نیست، پس
   چنین درخواستی نمی‌تواند یک ذخیرهٔ معنادار باشد. وقتی container هست،
   خاموش کردن گالری کاملاً محترم است.
   ===================================================================== */
$selectorsIn  = json_decode($_POST['selectors'] ?? '{}', true) ?: [];
$selectorsOld = (array)($profiles[$key]['selectors'] ?? []);
$formIsBlank  = empty($selectorsIn['container']) && !empty($selectorsOld['container']);
$selectorsFinal = $formIsBlank ? $selectorsOld : $selectorsIn;
if ($formIsBlank && empty($detailSelectors)) {
    $detailSelectors = (array)($profiles[$key]['detailSelectors'] ?? []);
}
$galleryIn  = array_key_exists('gallery', $_POST)
    ? galleryNormalizeCfg($_POST['gallery'])
    : galleryNormalizeCfg($profiles[$key]['gallery'] ?? []);
$galleryOld = galleryNormalizeCfg($profiles[$key]['gallery'] ?? []);
$galleryFinal = ($formIsBlank && ((!$galleryIn['enabled'] && $galleryOld['enabled']) || (!s4NormalizeImageEditCfg($galleryIn)['active'] && s4NormalizeImageEditCfg($galleryOld)['active'])))
    ? $galleryOld : $galleryIn;
$listImgEditIn  = array_key_exists('listImageEdit', $_POST)
    ? listImageEditNormalizeCfg($_POST['listImageEdit'])
    : listImageEditNormalizeCfg($profiles[$key]['listImageEdit'] ?? []);
$listImgEditOld = listImageEditNormalizeCfg($profiles[$key]['listImageEdit'] ?? []);
$listImgEditFinal = ($formIsBlank && !s4NormalizeImageEditCfg($listImgEditIn)['active'] && s4NormalizeImageEditCfg($listImgEditOld)['active'])
    ? $listImgEditOld : $listImgEditIn;
// v8.55: اگر syncConfig در درخواست نباشد، تنظیم قبلی حفظ شود.
// قبلاً هر ذخیرهٔ جزئی، بازهٔ همگام‌سازی را پاک می‌کرد و پروفایل
// دوباره «هر بار فراخوانی» می‌شد.
$syncConfig = array_key_exists('syncConfig', $_POST)
    ? (json_decode((string)$_POST['syncConfig'], true) ?: [])
    : (array)($profiles[$key]['syncConfig'] ?? []);
$profilePatch = [
'url' => $url,
/* نام خالی هرگز نام معتبر قبلی را به host تبدیل نکند. host فقط برای
   ساخت نخستین پروفایلِ واقعاً بی‌نام fallback است. */
'name' => ($isAutosave && trim((string)($existingProfile['name'] ?? ''))!=='')
    ? trim((string)$existingProfile['name'])
    : (trim((string)($_POST['name'] ?? '')) !== ''
        ? trim((string)$_POST['name'])
        : (trim((string)($existingProfile['name'] ?? '')) ?: parse_url($url, PHP_URL_HOST))),
'pages' => array_key_exists('pages', $_POST)
    ? max(0, (int)$_POST['pages'])
    : max(0, (int)($profiles[$key]['pages'] ?? 10)),
// v10.177: تنظیم صفحه‌بندی هم مثل دسته‌ها (v8.43) در ذخیرهٔ جزئی حفظ شود —
//   پیش‌تر هر ذخیره‌ای که این کلیدها را نمی‌فرستاد، الگو به حالت پیش‌فرض
//   برمی‌گشت و کاربر «به صفحهٔ بعد نمی‌رود» می‌دید.
'pagType' => array_key_exists('pagType', $_POST)
    ? (string)$_POST['pagType']
    : (string)($profiles[$key]['pagType'] ?? 'query_page'),
'pagVal' => array_key_exists('pagVal', $_POST)
    ? trim((string)$_POST['pagVal'])
    : (string)($profiles[$key]['pagVal'] ?? ''),
'selectors' => $selectorsFinal,
// v10.181: PHP-native extraction engine; missing key preserves legacy CSS-selector behavior.
'extractionEngine' => array_key_exists('extractionEngine', $_POST)
    ? normalizeExtractionEngine((string)$_POST['extractionEngine'])
    : normalizeExtractionEngine((string)($profiles[$key]['extractionEngine'] ?? 'selectors')),
'detailSelectors' => $detailSelectors,
// v8.64: تنظیمات گالری چندعکسی — اگر در درخواست نباشد مقدار قبلی می‌ماند
'gallery' => $galleryFinal,
// v10.445: تنظیمات ویرایش تصویر فهرست (مربع سفید گوشه / برش پایین عکس)
'listImageEdit' => $listImgEditFinal,
'titleSuffix' => array_key_exists('titleSuffix', $_POST) ? (string)$_POST['titleSuffix'] : (string)($existingProfile['titleSuffix'] ?? ''),
'priceMode' => array_key_exists('priceMode', $_POST) ? (string)$_POST['priceMode'] : (string)($existingProfile['priceMode'] ?? 'none'),
'priceVal' => array_key_exists('priceVal', $_POST) ? (float)$_POST['priceVal'] : (float)($existingProfile['priceVal'] ?? 0),
'roundPrice' => array_key_exists('roundPrice', $_POST) ? (string)$_POST['roundPrice'] : (string)($existingProfile['roundPrice'] ?? '0'),
'minPrice' => array_key_exists('minPrice', $_POST) ? (int)$_POST['minPrice'] : (int)($existingProfile['minPrice'] ?? 10000),
'useCustomCol' => array_key_exists('useCustomCol', $_POST) ? !empty($_POST['useCustomCol']) : !empty($existingProfile['useCustomCol']),
'fullMode' => array_key_exists('fullMode', $_POST) ? !empty($_POST['fullMode']) : !empty($existingProfile['fullMode']),
'customColName' => array_key_exists('customColName', $_POST) ? (string)$_POST['customColName'] : (string)($existingProfile['customColName'] ?? ''),
'customColVal' => array_key_exists('customColVal', $_POST) ? (string)$_POST['customColVal'] : (string)($existingProfile['customColVal'] ?? ''),
'iframeHeight' => array_key_exists('iframeHeight', $_POST) ? max(200, (int)$_POST['iframeHeight']) : (int)($existingProfile['iframeHeight'] ?? 600),
'products' => (!array_key_exists('products', $_POST) || (empty($productsData) && !empty($existingProfile['products']) && empty($_POST['allow_empty_products'])))
    ? (array)($existingProfile['products'] ?? [])
    : $productsData,
'productsOrder' => (!array_key_exists('productsOrder', $_POST) || (empty($productsData) && !empty($existingProfile['products']) && empty($_POST['allow_empty_products'])))
    ? (array)($existingProfile['productsOrder'] ?? [])
    : $productsOrder,
'syncConfig' => $syncConfig,
// v8.43: اگر این فیلدها در درخواست نباشند، مقدار قبلی حفظ شود.
// قبلاً هر ذخیره‌ای که آن‌ها را نمی‌فرستاد، دستهٔ پروفایل را صفر می‌کرد.
'bslCategoryId' => array_key_exists('bslCategoryId', $_POST)
    ? (int)$_POST['bslCategoryId']
    : (int)($profiles[$key]['bslCategoryId'] ?? 0),
'bslFallbackCatIds' => array_key_exists('bslFallbackCatIds', $_POST)
    ? array_values(array_filter(array_map('intval', json_decode((string)$_POST['bslFallbackCatIds'], true) ?: []), function($v){return $v>0;}))
    : (array)($profiles[$key]['bslFallbackCatIds'] ?? []),
// v8.56: دستهٔ ووکامرس مخصوص این پروفایل — مثل باسلام، اگر در درخواست
// نباشد مقدار قبلی حفظ می‌شود تا ذخیره‌های جزئی آن را صفر نکنند.
'wooCategoryId' => array_key_exists('wooCategoryId', $_POST)
    ? (int)$_POST['wooCategoryId']
    : (int)($profiles[$key]['wooCategoryId'] ?? 0),
// v9.67: اتصال غیرمستقیمِ این پروفایل (فقط همین پروفایل). مقدار پیش‌فرض: غیرفعال = مستقیم.
'net_indirect' => array_key_exists('net_indirect', $_POST)
    ? !empty($_POST['net_indirect'])
    : !empty($profiles[$key]['net_indirect']),
// v10.217: per-profile source selector. Additive metadata only; products keep the legacy shape.
'productSource' => array_key_exists('productSource', $_POST)
    ? (json_decode((string)$_POST['productSource'], true) ?: ['mode'=>'direct'])
    : (array)($profiles[$key]['productSource'] ?? ['mode'=>'direct']),
'backendExtractWithDetail' => array_key_exists('backendExtractWithDetail', $_POST)
    ? !empty($_POST['backendExtractWithDetail'])
    : (array_key_exists('backendExtractWithDetail', (array)($profiles[$key] ?? [])) ? !empty($profiles[$key]['backendExtractWithDetail']) : true),
'detailExtractMode' => normalizeDetailExtractMode($_POST['detailExtractMode'] ?? ($profiles[$key]['detailExtractMode'] ?? 'two_stage')),
'updatedAt' => time()
];
if (!empty($_POST['partial_meta_only']) && !empty($existingProfile)) {
    $profilePatch = [
        'url' => $url,
        'updatedAt' => time(),
    ];
    if (!$isAutosave && trim((string)($_POST['name'] ?? '')) !== '') {
        $profilePatch['name'] = trim((string)$_POST['name']);
    }
}
/* metadataهای lifecycle/extraction که save_profile مالکشان نیست حفظ شوند. */
$lfSave = @fopen(PROFILES_FILE . '.extract.lock', 'c');
if ($lfSave && !@flock($lfSave, LOCK_EX)) { @fclose($lfSave); $lfSave = null; }
$profiles = s4StripDeletedProfiles(loadProfiles());
$key = s4ResolveSaveProfileTargetKey($url, $targetKeyIn, $profiles);
$existingProfile = is_array($profiles[$key] ?? null) ? $profiles[$key] : $existingProfile;
$oldProfilePriceSig=json_encode([(string)($existingProfile['priceMode']??'none'),(string)($existingProfile['priceVal']??0),(string)($existingProfile['roundPrice']??0)]);
if (empty($_POST['partial_meta_only']) && !empty($existingProfile['products']) && empty($_POST['allow_empty_products'])) {
    if (empty($productsData)) {
        $profilePatch['products'] = (array)$existingProfile['products'];
        $profilePatch['productsOrder'] = (array)($existingProfile['productsOrder'] ?? []);
    } elseif ($isAutosave && empty($_POST['allow_shrink_products'])) {
        $_autoPrevValid = extractCountValidProducts((array)$existingProfile['products']);
        $_autoNewValid  = extractCountValidProducts($productsData);
        $_autoStage     = (string)($existingProfile['_extract_stage'] ?? '');
        $_autoGuard     = extractShouldBlockShrinkage($_autoPrevValid, $_autoNewValid, [
            'autosave'   => true,
            'incomplete' => (!empty($existingProfile['_extract_list_incomplete']) || !empty($existingProfile['_extract_resume_needed']) || in_array($_autoStage, ['list', 'detail'], true)),
        ]);
        if (!empty($_autoGuard['blocked'])) {
            $profilePatch['products'] = (array)$existingProfile['products'];
            $profilePatch['productsOrder'] = (array)($existingProfile['productsOrder'] ?? []);
        }
    }
}
$profiles[$key] = array_merge($existingProfile, $profilePatch);
$_saved = writeJsonFile(PROFILES_FILE, $profiles);
if ($lfSave) { @flock($lfSave, LOCK_UN); @fclose($lfSave); }
if ($_saved['ok']) {
$newProfilePriceSig=json_encode([(string)($profiles[$key]['priceMode']??'none'),(string)($profiles[$key]['priceVal']??0),(string)($profiles[$key]['roundPrice']??0)]);
$mxRefresh=$oldProfilePriceSig!==$newProfilePriceSig?matrixRefreshExpectedPrices('profile_price_change'):['ok'=>true,'changed'=>false,'rows'=>0];
$savedProdCount = is_array($profiles[$key]['products'] ?? null) ? count($profiles[$key]['products']) : 0;
echo json_encode(['ok' => true, 'key' => $key, 'url' => (string)($profiles[$key]['url'] ?? $url), 'name' => (string)($profiles[$key]['name'] ?? ''), 'product_count' => $savedProdCount, 'updated_at'=>(int)($profiles[$key]['updatedAt']??time()), 'message' => 'پروفایل ذخیره شد', 'pages'=>(int)($profiles[$key]['pages']??10), 'matrix_repriced'=>$mxRefresh, 'selectors' => $profiles[$key]['selectors'] ?? [], 'has_selectors' => !empty($profiles[$key]['selectors']['container'])], JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE);
} else {
// v9.24: علت واقعی را به کاربر بدهیم (ترموکس/استوریج معمولاً قفل یا مجوز است)
echo json_encode(['ok' => false, 'error' => 'خطا در نوشتن فایل: ' . ($_saved['error'] ?? 'نامشخص')]);
}
exit;
}

if (($_POST['action'] ?? '') === 'duplicate_profile') {
header('Content-Type: application/json; charset=UTF-8');
$sourceRef = trim((string)($_POST['source_key'] ?? ($_POST['key'] ?? ($_POST['url'] ?? ''))));
if ($sourceRef === '') {
    echo json_encode(['ok' => false, 'error' => 'پروفایل مبدأ مشخص نشده است'], JSON_UNESCAPED_UNICODE);
    exit;
}
$reqName = trim((string)($_POST['name'] ?? ''));
$reqUrl = trim((string)($_POST['new_url'] ?? ''));
$incProds = !isset($_POST['include_products']) || !in_array((string)$_POST['include_products'], ['0', 'false', 'off'], true);
$returnFull = !isset($_POST['return_full']) || !in_array((string)$_POST['return_full'], ['0', 'false', 'off'], true);
$lfDup = @fopen(PROFILES_FILE . '.extract.lock', 'c');
if ($lfDup && !@flock($lfDup, LOCK_EX)) { @fclose($lfDup); $lfDup = null; }
$profiles = s4StripDeletedProfiles(loadProfiles());
$dupRes = s4DuplicateProfileOnDisk($profiles, $sourceRef, [
    'name' => $reqName,
    'url' => $reqUrl,
    'include_products' => $incProds,
]);
if (empty($dupRes['ok'])) {
    if ($lfDup) { @flock($lfDup, LOCK_UN); @fclose($lfDup); }
    echo json_encode(['ok' => false, 'error' => (string)($dupRes['error'] ?? 'خطا در داپلیکیت پروفایل')], JSON_UNESCAPED_UNICODE);
    exit;
}
$newKey = (string)$dupRes['key'];
s4ClearProfileDeletedTombstone($newKey, '');
$savedDup = writeJsonFile(PROFILES_FILE, $profiles);
if ($lfDup) { @flock($lfDup, LOCK_UN); @fclose($lfDup); }
if (!$savedDup['ok']) {
    echo json_encode(['ok' => false, 'error' => 'خطا در نوشتن فایل پروفایل: ' . ($savedDup['error'] ?? 'نامشخص')], JSON_UNESCAPED_UNICODE);
    exit;
}
$outDup = [
    'ok' => true,
    'source_key' => (string)$dupRes['source_key'],
    'key' => $newKey,
    'profile_summary' => $dupRes['profile_summary'],
    'message' => 'کپی پروفایل ساخته شد',
];
if ($returnFull) {
    $outDup['profile'] = $dupRes['profile'];
}
echo json_encode($outDup, JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE);
exit;
}

if (($_POST['action'] ?? '') === 'delete_profile') {
header('Content-Type: application/json; charset=UTF-8');
$keyIn = trim((string)($_POST['key'] ?? ''));
$url = s4NormalizeInputUrl((string)($_POST['url'] ?? ''));
if ($keyIn === '' && !$url) {
echo json_encode(['ok' => false, 'error' => 'No URL or key']);
exit;
}
$lfDel = @fopen(PROFILES_FILE . '.extract.lock', 'c');
if ($lfDel && !@flock($lfDel, LOCK_EX)) { @fclose($lfDel); $lfDel = null; }
$profiles = loadProfiles();
$key = '';
if ($keyIn !== '' && isset($profiles[$keyIn])) {
    $key = $keyIn;
} elseif ($keyIn !== '') {
    $key = profileResolveKey($keyIn, $profiles) ?: '';
}
if ($key === '' && $url !== '') {
    $key = profileResolveKey($url, $profiles) ?: (strpos($url, '://') !== false ? profileKey($url) : '');
}
if ($key !== '' && isset($profiles[$key])) {
$removedUrl = (string)($profiles[$key]['url'] ?? $url);
unset($profiles[$key]);
$normRemovedKey = ($removedUrl !== '' && strpos($removedUrl, '://') !== false) ? profileKey(s4NormalizeInputUrl($removedUrl)) : '';
$siblingSharesUrl = false;
foreach ($profiles as $remK => $remP) {
    if (!is_array($remP)) continue;
    if (($normRemovedKey !== '' && (string)$remK === $normRemovedKey) || ($removedUrl !== '' && trim((string)($remP['url'] ?? '')) === trim($removedUrl))) {
        $siblingSharesUrl = true;
        break;
    }
}
s4MarkProfileDeletedTombstone($key, $siblingSharesUrl ? '' : $removedUrl);
// v9.92: حذفِ صریحِ کاربر — محافظِ ضدِ حذفِ ناخواسته باید کنار برود
$delOk = saveProfiles($profiles, true);
if ($lfDel) { @flock($lfDel, LOCK_UN); @fclose($lfDel); }
if ($delOk) {
    s4CleanupDeletedProfileArtifacts($key, $siblingSharesUrl ? '' : $removedUrl);
    echo json_encode(['ok' => true, 'key' => $key, 'url' => $removedUrl, 'sibling_preserved' => $siblingSharesUrl, 'remaining' => count($profiles), 'message' => 'پروفایل حذف شد'], JSON_UNESCAPED_UNICODE);
} else {
    echo json_encode(['ok' => false, 'error' => 'خطا در ذخیرهٔ حذف پروفایل'], JSON_UNESCAPED_UNICODE);
}
} else {
$fallbackDelKey = $keyIn !== '' ? $keyIn : (($url !== '' && strpos($url, '://') !== false) ? profileKey($url) : '');
$siblingHasUrl = false;
if ($url !== '') {
    foreach ($profiles as $remP) {
        if (is_array($remP) && trim((string)($remP['url'] ?? '')) === trim($url)) { $siblingHasUrl = true; break; }
    }
}
if ($fallbackDelKey !== '' || $url !== '') s4MarkProfileDeletedTombstone($fallbackDelKey, $siblingHasUrl ? '' : $url);
if ($lfDel) { @flock($lfDel, LOCK_UN); @fclose($lfDel); }
echo json_encode(['ok' => true, 'key' => $fallbackDelKey, 'already_deleted' => true, 'message' => 'پروفایل از قبل حذف شده بود'], JSON_UNESCAPED_UNICODE);
}
exit;
}

if (!empty($_GET['test_selector'])) {
header('Content-Type: application/json; charset=UTF-8');
$url = trim($_GET['test_selector']);
$type = $_GET['type'] ?? 'text';
$selector = $_GET['selector'] ?? '';

if (!filter_var($url, FILTER_VALIDATE_URL) || !$selector) {
echo json_encode(['ok' => false, 'error' => 'Invalid params']);
exit;
}

$res = fetch_html($url, 15);
if (!$res['ok']) {
echo json_encode(['ok' => false, 'error' => $res['error']]);
exit;
}

[$dom, $xp] = load_dom($res['html']);
$baseUrl = $res['url'];

$xpath = cssToXpath($selector);
$nodes = @$xp->query($xpath);

if (!$nodes || !$nodes->length) {
echo json_encode(['ok' => false, 'error' => 'المان یافت نشد']);
exit;
}

$node = $nodes->item(0);
$result = ['ok' => true, 'count' => $nodes->length];

if ($type === 'title') {
$result['value'] = normalize_text($node->textContent);
} elseif ($type === 'price') {
$result['value'] = extractPrice($node->textContent);
} elseif ($type === 'link') {
$link = '';
if ($node instanceof DOMElement) {
if ($node->tagName === 'a') {
$link = $node->getAttribute('href') ?: $node->getAttribute('data-href') ?: '';
} else {

foreach (['data-href', 'data-link', 'data-url', 'data-product-url'] as $attr) {
$v = $node->getAttribute($attr);
if ($v && $v !== '#') { $link = $v; break; }
}
if (!$link) {
$aNodes = @$xp->query('.//a[@href]', $node);
if ($aNodes && $aNodes->length) {
$link = $aNodes->item(0)->getAttribute('href');
}
}
if (!$link) {

$parent = $node->parentNode;
for ($i = 0; $i < 5 && $parent instanceof DOMElement; $i++) {
if ($parent->tagName === 'a' && $parent->getAttribute('href')) {
$link = $parent->getAttribute('href');
break;
}
foreach (['data-href', 'data-link', 'data-url', 'data-product-url'] as $attr) {
$v = $parent->getAttribute($attr);
if ($v && $v !== '#') { $link = $v; break 2; }
}
$parent = $parent->parentNode;
}
}
}
}
$result['value'] = make_absolute_url($link, $baseUrl);
} elseif ($type === 'image') {
$img = '';
if ($node instanceof DOMElement) {
if ($node->tagName === 'img') {
foreach (['data-src', 'data-lazy-src', 'data-original', 'src'] as $attr) {
$v = $node->getAttribute($attr);
if ($v && url_is_image($v)) { $img = $v; break; }
}
} else {
$imgNodes = @$xp->query('.//img', $node);
if ($imgNodes && $imgNodes->length) {
foreach (['data-src', 'data-lazy-src', 'data-original', 'src'] as $attr) {
$v = $imgNodes->item(0)->getAttribute($attr);
if ($v && url_is_image($v)) { $img = $v; break; }
}
}
}
}
$result['value'] = make_absolute_url($img, $baseUrl);
} else {
$result['value'] = normalize_text($node->textContent);
}

$result['value'] = mb_substr($result['value'], 0, 500);
echo json_encode($result, JSON_UNESCAPED_UNICODE);
exit;
}

if (isset($_GET['s4_feedback'])) {
header('Content-Type: application/json; charset=UTF-8');
@set_time_limit(180);
$kind = trim((string)$_GET['s4_feedback']);
if (strtolower($kind) === 'snappshop_pdp_probe') {
    $pid = preg_replace('~[^0-9]~', '', (string)($_GET['id'] ?? '389034409'));
    if ($pid === '') $pid = '389034409';
    $st = s4SnappApixStateRead();
    $now = time();
    $remCd = max(0, (int)($st['pdp_cooldown_until'] ?? 0) - $now);
    $out = [
        'ok' => true,
        'version' => APP_VERSION,
        'cooldown_remaining_sec' => $remCd,
        'pdp_429_streak' => (int)($st['pdp_429_streak'] ?? 0),
        'last_200_at' => (int)($st['last_200_at'] ?? 0),
        'last_429_at' => (int)($st['last_429_at'] ?? 0),
        'total_200' => (int)($st['total_200'] ?? 0),
        'total_429' => (int)($st['total_429'] ?? 0),
        'has_guest_token' => trim((string)($st['guest_token'] ?? '')) !== '',
        'guest_token_age_sec' => !empty($st['guest_token_at']) ? ($now - (int)$st['guest_token_at']) : null,
    ];
    if (!empty($_GET['reset_cooldown'])) {
        s4SnappApixStateWithLock(static function(array &$sState, bool &$dirty) {
            $sState['pdp_cooldown_until'] = 0;
            $sState['pdp_429_streak'] = 0;
            $dirty = true;
            return $sState;
        });
        $out['cooldown_reset'] = true;
        $out['cooldown_remaining_sec'] = 0;
    }
    if (!empty($_GET['diag'])) {
        $psLines = [];
        if (function_exists('exec')) {
            @exec('ps -eo pid,etime,args 2>/dev/null | grep -i php | grep -v grep', $psLines);
        }
        $dnsInfo = [];
        foreach (['apix.snappshop.ir', 'snappshop.ir', 'statics.delivery.sotoon.ir'] as $dh) {
            $recs = @dns_get_record($dh, DNS_A + DNS_AAAA);
            $ips = [];
            if (is_array($recs)) {
                foreach ($recs as $rc) {
                    $ip = (string)($rc['ip'] ?? ($rc['ipv6'] ?? ''));
                    if ($ip !== '') $ips[] = $ip;
                }
            }
            $dnsInfo[$dh] = $ips;
        }
        $tok = s4SnappApixEnsureGuestToken(6, false);
        $baseH = [
            'Accept: application/json, text/plain, */*',
            'Origin: https://snappshop.ir',
            'Referer: https://snappshop.ir/',
            'X-Origin: https://snappshop.ir',
            'x-origin: https://snappshop.ir',
        ];
        if ($tok !== '') $baseH[] = 'Authorization: Bearer ' . $tok;
        $tryReq = static function(string $u, array $h, array $extraOpt = [], ?string $postJson = null): array {
            $zrk = '';
            $ch = curl_init($u);
            curl_setopt_array($ch, [
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_CONNECTTIMEOUT => 3,
                CURLOPT_TIMEOUT        => 5,
                CURLOPT_ENCODING       => '',
                CURLOPT_SSL_VERIFYPEER => false,
                CURLOPT_SSL_VERIFYHOST => 0,
                CURLOPT_HTTPHEADER     => $h,
                CURLOPT_HEADERFUNCTION => static function($c, $hl) use (&$zrk) {
                    if (stripos($hl, 'x-zrk-sn:') === 0) $zrk = trim(substr($hl, 9));
                    return strlen($hl);
                },
            ] + $extraOpt);
            if ($postJson !== null) {
                curl_setopt($ch, CURLOPT_CUSTOMREQUEST, 'POST');
                curl_setopt($ch, CURLOPT_POSTFIELDS, $postJson);
            }
