        'selector_container_count' => $selContainerCount,
        'products' => [
            'profile_engine' => ['engine'=>$eng, 'used'=>$usedProfile, 'count'=>count($profileRows)],
            'auto' => ['used'=>$usedAuto, 'count'=>count($auto)],
            'heuristic' => ['used'=>$usedHeu, 'count'=>count($heu)],
