['selector' => 'span.woocommerce-Price-amount', 'xpath' => ".//span[contains(@class,'woocommerce-Price')]"],
['selector' => 'p.price', 'xpath' => ".//p[contains(@class,'price')]"],
];

$suggestions['price'] = array_map(fn($p) => ['selector' => $p['selector']], $pricePatterns);

$suggestions['link'] = [
['selector' => 'a[href*="~id~"]'],
['selector' => 'a.woocommerce-LoopProduct-link'],
['selector' => 'a.product-link'],
['selector' => 'a[href*="product"]'],
['selector' => 'h2 a'],
['selector' => 'h3 a'],
['selector' => 'a.title'],
];

$suggestions['image'] = [
['selector' => 'img.wp-post-image'],
['selector' => 'img.product-image'],
['selector' => 'img.attachment-woocommerce'],
['selector' => 'img[data-src]'],
['selector' => 'img.lazy'],
['selector' => 'img'],
];

echo json_encode(['ok' => true, 'suggestions' => $suggestions], JSON_UNESCAPED_UNICODE);
exit;
}

/**
 * v8.64: آزمایش گالری روی یک صفحهٔ محصول واقعی.
 * ?gallery_test=<آدرس صفحهٔ محصول>&gallery=<JSON تنظیمات>
 * چیزی ذخیره نمی‌کند؛ فقط می‌گوید چند عکس و کدام‌ها پیدا شد.
 */
if (!empty($_GET['gallery_test'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(60);
    $url = trim((string)$_GET['gallery_test']);
    if (!filter_var($url, FILTER_VALIDATE_URL)) {
        echo json_encode(['ok' => false, 'error' => 'آدرس نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    $cfg = galleryEffectiveCfgForUrl(galleryNormalizeCfg($_GET['gallery'] ?? ($_POST['gallery'] ?? [])), $url);
    if (!$cfg['enabled']) {
        echo json_encode(['ok' => false, 'error' => 'حالت گالری خاموش است'], JSON_UNESCAPED_UNICODE); exit;
    }
    /* v8.99: همان مهلت قابل تنظیم پراکسی — این هم از روی سرور می‌گیرد */
    $_sgT = (int)(loadConnections()['proxy_timeout_sec'] ?? 0);
    if ($_sgT <= 0) $_sgT = 45;
    $res = fetch_html($url, max(10, min(180, $_sgT)));
    if (empty($res['ok'])) {
        echo json_encode(['ok' => false, 'error' => 'صفحه باز نشد: '
            . mb_substr((string)($res['error'] ?? 'خطا'), 0, 120)], JSON_UNESCAPED_UNICODE); exit;
    }
    [$gd, $gx] = load_dom($res['html']);
    $g = galleryExtract($gx, null, $res['url'], $cfg);
    echo json_encode(['ok' => true, 'mode' => $g['mode'], 'count' => count($g['images']),
        'tried' => $g['tried'], 'note' => $g['note'], 'images' => $g['images'],
        'page' => $res['url']], JSON_UNESCAPED_UNICODE);
    exit;
}

/**
 * v8.64: پیشنهاد خودکار «باکس عکس‌ها» روی یک صفحهٔ محصول.
 * ?gallery_suggest=<آدرس> — چند سلکتور نامزد را با تعداد عکسشان برمی‌گرداند.
 */
if (!empty($_GET['gallery_suggest'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(60);
    $url = trim((string)$_GET['gallery_suggest']);
    if (!filter_var($url, FILTER_VALIDATE_URL)) {
        echo json_encode(['ok' => false, 'error' => 'آدرس نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    /* v8.99: همان مهلت قابل تنظیم پراکسی — این هم از روی سرور می‌گیرد */
    $_sgT = (int)(loadConnections()['proxy_timeout_sec'] ?? 0);
    if ($_sgT <= 0) $_sgT = 45;
    $res = fetch_html($url, max(10, min(180, $_sgT)));
    if (empty($res['ok'])) {
        echo json_encode(['ok' => false, 'error' => 'صفحه باز نشد'], JSON_UNESCAPED_UNICODE); exit;
    }
    [$gd, $gx] = load_dom($res['html']);
    // نامزدهای رایج گالری در ووکامرس و قالب‌های ایرانی
    $cands = ['.woocommerce-product-gallery', '.flex-control-thumbs', '.product-gallery',
              'div.image-thumbnail', '.product-images', '.thumbnails', '.gallery', '.swiper-wrapper',
              '.slick-track', '.owl-stage', '.product-thumbs', '.image-gallery',
              '.pro-gallery', '.product-photos', '.detail-gallery'];
    $out = [];
    foreach ($cands as $c) {
        $xpq = cssToXpath($c, false);
        if ($xpq === '') continue;
        $ns = @$gx->query($xpq);
        if (!$ns || !$ns->length) continue;
        $imgs = [];
        foreach ($ns as $b) foreach (galleryImgsInside($gx, $b, $res['url']) as $u) $imgs[] = $u;
        $imgs = galleryDedupe($imgs);
        if (count($imgs) < 2) continue;      // یک عکس یعنی گالری نیست
        $out[] = ['selector' => $c, 'count' => count($imgs),
                  'sample' => array_slice($imgs, 0, 4)];
    }
    usort($out, fn($a, $b) => $b['count'] <=> $a['count']);
    echo json_encode(['ok' => true, 'page' => $res['url'], 'suggestions' => $out],
        JSON_UNESCAPED_UNICODE);
    exit;
}

if (!empty($_GET['suggest_detail_selectors'])) {
header('Content-Type: application/json; charset=UTF-8');
$url = s4NormalizeInputUrl((string)($_GET['suggest_detail_selectors'] ?? ''));
if (!filter_var($url, FILTER_VALIDATE_URL)) {
echo json_encode(['ok' => false, 'error' => 'Invalid URL']);
exit;
}

$res = fetch_html($url, 15);
if (!$res['ok']) {
echo json_encode(['ok' => false, 'error' => $res['error']]);
exit;
}

$html = $res['html'];
libxml_use_internal_errors(true);
$dom = new DOMDocument('1.0', 'UTF-8');
@$dom->loadHTML('<?xml encoding="UTF-8"><meta charset="UTF-8">' . $html, LIBXML_NOERROR);
$xp = new DOMXPath($dom);
libxml_clear_errors();

$suggestions = [
/* v10.15: قیمت. ترتیب مهم است: ins (قیمتِ پس از تخفیف) قبل از خودِ .price
   می‌آید تا روی محصولِ حراج‌دار عددِ درست پیشنهاد شود نه قیمتِ خط‌خورده. */
'price' => [
'p.price ins .amount',
'p.price ins',
'.summary p.price ins .amount',
'.summary p.price .amount',
'p.price .amount',
'p.price',
'.summary .price',
],
'shortDesc' => [
'div.woocommerce-product-details__short-description',
'div.product-short-description',
'.summary .woocommerce-product-details__short-description',
'.summary > p',
],
'longDesc' => [
'div.woocommerce-Tabs-panel--description',
'div#tab-description',
'.woocommerce-tabs .panel',
'div.product-description',
'#description',
],
'sku' => [
'span.sku',
'span.sku_wrapper',
'.product_meta .sku',
],
'category' => [
'span.posted_in a',
'.product_meta .posted_in a',
'.product_meta .posted_in',
],
'tags' => [
'span.tagged_as a',
'.product_meta .tagged_as a',
],
'weight' => [
'tr.woocommerce-product-attributes-item--weight td',
'td.product_weight',
'.product_meta .product-weight',
'[itemprop="weight"]',
'span.weight',
'.product_meta .weight',
],
'stock' => [
'p.stock',
'span.stock',
'.stock.in-stock',
],
'brand' => [
'.product_meta .brand',
'span.posted_in a',
],
'variations' => [
'.snappshop-variation-group',
'table.variations select',
'form.variations_form .variations',
],
];

$found = [];
foreach ($suggestions as $field => $selectors) {
$found[$field] = [];
foreach ($selectors as $sel) {
$xpath = cssToXpath($sel);
if (!$xpath) continue;
$nodes = @$xp->query($xpath);
if ($nodes && $nodes->length) {
$text = trim($nodes->item(0)->textContent);
/* v10.15: برای قیمت، پیش‌نمایش همان عددی است که واقعاً برداشته می‌شود.
   اگر سلکتور به گره‌ای بخورد که عددِ قابل‌فهمی ندارد، اصلاً پیشنهاد نشود —
   وگرنه کاربر سلکتوری را می‌پذیرد که موقعِ استخراج رشتهٔ خالی می‌دهد. */
if ($field === 'price') {
$pv = extractPrice($text);
if ($pv !== '') $found[$field][] = ['selector' => $sel, 'preview' => $pv];
continue;
}
if ($text && mb_strlen($text) < 5000) {
$found[$field][] = [
'selector' => $sel,
'preview' => mb_substr($text, 0, 80) . (mb_strlen($text) > 80 ? '...' : '')
];
}
}
}
}

echo json_encode(['ok' => true, 'suggestions' => $found], JSON_UNESCAPED_UNICODE);
exit;
}

if (!empty($_GET['detail_proxy'])) {
$url = s4NormalizeInputUrl((string)($_GET['detail_proxy'] ?? ''));
if (!filter_var($url, FILTER_VALIDATE_URL)) { http_response_code(400); echo 'Invalid URL'; exit; }

/* v8.99: همان مهلت قابل تنظیم و همان تلاش دوم که در visual_proxy هست —
   انتخابگر جزئیات هم از روی سرور صفحه را می‌گیرد و همان محدودیت را دارد. */
$cnDP = loadConnections();
$dpTimeout = (int)($cnDP['proxy_timeout_sec'] ?? 0);
if ($dpTimeout <= 0) $dpTimeout = 45;
$dpTimeout = max(10, min(180, $dpTimeout));
$dpWaitMs = max(0, min(30000, (int)($_GET['wait_ms'] ?? ($_GET['selector_wait_ms'] ?? 0))));

// v9.75: اتصالِ این صفحه را مطابقِ «اتصال غیرمستقیم»ِ پروفایلِ انتخاب‌شده بگذار
srcNetSetProfileIndirect((string)($_GET['pk'] ?? ''));

$res = fetch_html($url, $dpTimeout);
if (!$res['ok']) {
    $e1 = (string)($res['error'] ?? '');
    if (stripos($e1, 'timed out') !== false || stripos($e1, 'timeout') !== false
        || stripos($e1, 'Empty') !== false) {
        $res = fetch_html($url, min(180, $dpTimeout * 2));
    }
}
if (!$res['ok']) {
http_response_code(500);
$err = $res['error'] ?? 'Unknown';
$_dpHint = '<div style="margin-top:22px;padding:14px 16px;background:#1e293b;border:1px solid #334155;border-radius:10px;line-height:2;font-size:13px;color:#cbd5e1">'
  . 'صفحه را <b>سرور</b> می‌گیرد، نه مرورگر شما — پس این خطا یعنی مسیر شبکهٔ سرور به این سایت کند یا محدود است.<br>'
  . 'در تنظیمات ← <b>مهلت بارگذاری صفحه</b> را بالاتر ببرید (الان ' . (int)$dpTimeout . ' ثانیه، دو بار تلاش شد).'
  . '</div>';
$_dpTitle = (stripos($err, 'resolve') !== false) ? '❌ دامنه پیدا نشد'
          : ((stripos($err, 'timed out') !== false || stripos($err, 'timeout') !== false)
             ? '⏱ خطای تایم‌اوت' : '❌ بارگذاری ناموفق');
echo '<html><body style="background:#0f172a;color:#fbbf24;font-family:var(--app-font,Tahoma,sans-serif);padding:40px;direction:rtl">'
   . '<h2>' . $_dpTitle . '</h2><p><b>سرورِ ما</b> نتوانست <b>' . h($url) . '</b> را بگیرد.</p>'
   . '<p style="color:#94a3b8">پیام: ' . h($err) . '</p>' . $_dpHint . '</body></html>';
exit;
}
$html = $res['html'];
$baseUrl = $res['url'];
$fullMode = !empty($_GET['full']);
if ($fullMode) {
$html = preg_replace("~<script[^>]*(?:google|analytics|gtag|facebook|snapchat|doubleclick)[^>]*>.*?</script>~is", "", $html);
} else {
$html = preg_replace("~<script[^>]*>.*?</script>~is", "", $html);
}
$html = preg_replace("~<iframe[^>]*>.*?</iframe>~is", "", $html);
$html = preg_replace("~<video[^>]*>.*?</video>~is", "", $html);
$html = preg_replace("~<audio[^>]*>.*?</audio>~is", "", $html);

$html = preg_replace_callback("~\\bsrc\\s*=\\s*\"([^\"]+)\"~i", function($m) use ($baseUrl) {
if (preg_match("~^(data:|blob:|javascript:|#|mailto:)~i", $m[1])) return $m[0];
if (strpos($m[1], "?rp=") === 0) return $m[0];
return "src=\"?rp=" . rawurlencode(make_absolute_url($m[1], $baseUrl)) . "\"";
}, $html);
$html = preg_replace_callback("~\\bsrc\\s*=\\s*'([^']+)'~i", function($m) use ($baseUrl) {
if (preg_match("~^(data:|blob:|javascript:|#|mailto:)~i", $m[1])) return $m[0];
if (strpos($m[1], "?rp=") === 0) return $m[0];
return "src='?rp=" . rawurlencode(make_absolute_url($m[1], $baseUrl)) . "'";
}, $html);
$html = preg_replace_callback("~\\bdata-src\\s*=\\s*\"([^\"]+)\"~i", function($m) use ($baseUrl) {
if (preg_match("~^(data:|blob:|#)~i", $m[1])) return $m[0];
return "data-src=\"?rp=" . rawurlencode(make_absolute_url($m[1], $baseUrl)) . "\"";
}, $html);
$html = preg_replace_callback("~<link\\b([^>]*?)\\bhref\\s*=\\s*\"([^\"]+)\"~i", function($m) use ($baseUrl) {
if (preg_match("~^(data:|blob:|#)~i", $m[2])) return $m[0];
if (strpos($m[2], "?rp=") === 0) return $m[0];
return "<link" . $m[1] . "href=\"?rp=" . rawurlencode(make_absolute_url($m[2], $baseUrl)) . "\"";
}, $html);
$html = preg_replace_callback("~<link\\b([^>]*?)\\bhref\\s*=\\s*'([^']+)'~i", function($m) use ($baseUrl) {
if (preg_match("~^(data:|blob:|#)~i", $m[2])) return $m[0];
