  <div class="__prow">
    <!-- v9.90: فلش‌های خواهر/برادر برگشتند (در v8.77 حذف شده بودند). -->
    <button class="__pb" id="__pup"   onclick="__go('up')"   title="والد (کلید ↑)">⬆</button>
    <button class="__pb" id="__pdn"   onclick="__go('down')" title="فرزند (کلید ↓)">⬇</button>
    <button class="__pb" id="__pprv"  onclick="__go('prev')" title="آیتم قبلی (کلید →)">⬅</button>
    <button class="__pb" id="__pnxt"  onclick="__go('next')" title="آیتم بعدی (کلید ←)">➡</button>
    <span class="__psep"></span>
    <button class="__pb" id="__pfprev" onclick="__field(-1)" title="فیلد قبلی (Shift+Tab)">‹</button>
    <button class="__pb __pfld" id="__pfld" onclick="__field(1)" title="فیلد بعدی (کلید Tab یا Space)">—</button>
    <button class="__pb" id="__pfnext" onclick="__field(1)" title="فیلد بعدی (Tab)">›</button>
    <span class="__psep"></span>
    <i id="__pcnt"></i>
    <button class="__pb __pause" id="__ppause" onclick="__togglePickPause()" title="توقف موقت انتخاب برای بازکردن پاپ‌آپ، کشویی یا تب داخل صفحه">⏸</button>
    <button class="__pb __okb" onclick="__done()" title="اتمام و ارسال (کلید Enter)">✓</button>
  </div>
  <div class="__prow2">
    <b id="__psel">—</b>
    <em id="__ppv"></em>
    <span id="__ver" style="opacity:.65"></span>
  </div>
</div>
<script>
(function(){
var S={},cur=null,picked=null;var MODE='shortDesc';
var __selectorWaitMs=__S4_SELECTOR_WAIT_MS__;
var __pickPaused=__selectorWaitMs>0;
function __pauseUi(){
  try{document.documentElement.classList.toggle('__pick-paused',__pickPaused);}catch(e){}
  ['__pauseBtn','__ppause'].forEach(function(id){var b=document.getElementById(id);if(!b)return;b.classList.toggle('__on',__pickPaused);b.textContent=(id==='__pauseBtn')?(__pickPaused?'▶ انتخاب':'⏸ انتخاب'):(__pickPaused?'▶':'⏸');});
  if(__pickPaused&&cur&&cur!==picked){try{cur.classList.remove('__h');}catch(e){}}
}
window.__togglePickPause=function(force){__pickPaused=(typeof force==='boolean')?force:!__pickPaused;__pauseUi();__post('picker_pause_state',{on:__pickPaused});};
if(__selectorWaitMs>0){
  try{var __wsel=document.getElementById('__sel');if(__wsel)__wsel.textContent='⏳ انتظار برای بارگذاری JS سایت...';}catch(e){}
  setTimeout(function(){__pickPaused=false;__pauseUi();try{var __wsel=document.getElementById('__sel');if(__wsel)__wsel.textContent='روی عنصر دلخواه کلیک کنید…';}catch(e){}__post('picker_pause_state',{on:false,wait_done:true});},__selectorWaitMs);
}
/* v8.88: روی موبایل، صفحه را خودکار جابه‌جا نکن.
   حرکت در درخت المان‌ها هر بار صفحه را وسط‌چین می‌کرد؛ روی صفحهٔ کوچک
   این یعنی کاربر مدام جای خودش را گم می‌کند. نوار شناور کنار المان
   می‌ماند، پس دیدنِ انتخاب بدون پرش هم ممکن است. */
function __mob(){try{return (window.innerWidth||document.documentElement.clientWidth||0)<=820;}catch(e){return false;}}
function __mayScroll(){try{var v=localStorage.getItem('scraper_autoscroll');if(v==='1')return true;if(v==='0')return false;}catch(e){}return !__mob();}
function __softScroll(el,o){if(!el||!__mayScroll())return;try{el.scrollIntoView(o||{block:'center'});}catch(e){}}
var GAL=[];   // v8.66: سلکتورهای تک‌عکسِ انتخاب‌شده برای گالری

/* v8.76: همان فهرست فیلدهای پنل والد، این‌بار داخل خود صفحه.
   قبلاً برای عوض کردن فیلد باید تا بالای صفحه اسکرول می‌کردید، یک گزینه
   از منو برمی‌داشتید و دوباره تا محل المان پایین می‌آمدید. */
var FIELDS=[
  ['price','قیمت'],
  ['shortDesc','توضیح کوتاه'],['longDesc','توضیح بلند'],['sku','SKU'],
  ['category','دسته‌بندی'],['tags','برچسب‌ها'],['weight','وزن'],
  ['stock','موجودی'],['brand','برند'],['variations','تنوع‌ها (گالری عکس)'],
  ['galleryBox','باکس گالری'],['galleryOne','تک‌عکس گالری'],['image','عکس اصلی']
];
function fieldLabel(k){
  for(var i=0;i<FIELDS.length;i++)if(FIELDS[i][0]===k)return FIELDS[i][1];
  return k;
}
function fieldIndex(k){
  for(var i=0;i<FIELDS.length;i++)if(FIELDS[i][0]===k)return i;
  return 0;
}

/**
 * v8.76: رفتن به فیلد بعدی/قبلی از داخل خود صفحه.
 * جهت +1 فیلدهای پرنشده را ترجیح می‌دهد، چون کار طبیعی «بعدی چه مانده؟» است؛
 * ولی اگر همه پر باشند باز هم می‌چرخد تا بشود ویرایش کرد.
 */
function __field(step){
  var n=FIELDS.length, i=fieldIndex(MODE), pick=null;
  if(step>0){
    for(var k=1;k<=n;k++){
      var c=FIELDS[(i+k)%n][0];
      if(!String(S[c]||'').trim()){pick=c;break;}
    }
  }
  if(!pick)pick=FIELDS[((i+step)%n+n)%n][0];
  __setMode(pick);
  // پنل والد هم باید همین فیلد را نشان بدهد وگرنه دو جا دو چیز می‌گویند
  __post('picker_field',{mode:pick});
}

/**
 * v8.66: ساخت سلکتور.
 * ترتیب عوض شد: id قبل از class می‌آید چون یکتاست و قابل اعتمادتر است.
 * قبلاً اگر عنصری هم id و هم کلاس داشت، کلاس انتخاب می‌شد و روی صفحه‌ای
 * که چند عنصر همان کلاس را داشتند، سلکتور به عنصر اشتباه می‌خورد.
 */
function gs(el){
  if(!el||el.tagName=='BODY'||el.tagName=='HTML')return'';
  var t=el.tagName.toLowerCase();
  if(el.id&&el.id.length<40&&!/^__/.test(el.id)&&!/^\d/.test(el.id))return t+'#'+el.id;
  var c=Array.from(el.classList).filter(function(x){
    // کلاس‌های حالت و کلاس‌های ساخته‌شدهٔ خودمان به درد سلکتور نمی‌خورند
    return !x.startsWith('__')&&x.length<40&&x.length>1
      &&!/^(active|open|show|hide|hidden|selected|current|is-|js-|has-)/.test(x);
  });
  if(c.length)return t+'.'+c.slice(0,3).join('.');
  // نه id دارد نه کلاس: با والدِ کلاس‌دار مسیر بساز تا یکتا شود
  var p=el.parentElement,depth=0;
  while(p&&depth<4){
    var pc=Array.from(p.classList).filter(function(x){return !x.startsWith('__')&&x.length>1&&x.length<40});
    if(p.id&&!/^__/.test(p.id))return p.tagName.toLowerCase()+'#'+p.id+' '+t;
    if(pc.length)return p.tagName.toLowerCase()+'.'+pc[0]+' '+t;
    p=p.parentElement;depth++;
  }
  return t;
}

/** چند تصویر داخل این عنصر هست؟ برای بازخورد باکس گالری */
function countImgs(el){
  if(!el)return 0;
  if(el.tagName==='IMG')return 1;
  try{ return el.querySelectorAll('img,source,[data-src],[data-large_image]').length; }catch(e){ return 0; }
}

/** همهٔ عناصری که سلکتور فعلی به آن‌ها می‌خورد — برای نشان دادن دقت انتخاب */
function countMatch(sel){
  if(!sel)return 0;
  try{ return document.querySelectorAll(sel).length; }catch(e){ return 0; }
}

/**
 * چند «تصویر» با فهرست سلکتورهای گالری برداشته می‌شود.
 * سلکتورها ممکن است کلی باشند (مثلاً div.slide img که به هر سه عکس می‌خورد)،
 * پس شمردن خودِ سلکتورها گمراه‌کننده است — عکس‌های یکتا شمرده می‌شوند.
 */
function countGalImgs(list){
  var seen={},n=0;
  (list||[]).forEach(function(sel){
    try{
      Array.prototype.forEach.call(document.querySelectorAll(sel),function(x){
        var els=x.tagName==='IMG'?[x]:Array.prototype.slice.call(x.querySelectorAll('img'));
        els.forEach(function(im){
          var u=getImageUrl(im)||im.getAttribute('src')||'';
          if(u&&!seen[u]){seen[u]=1;n++;}
        });
      });
    }catch(e){}
  });
  return n;
}

/* =====================================================================
 *  v8.85: همان منطق استخراج تنوع که سمت سرور اجرا می‌شود، این‌بار داخل
 *  انتخابگر — تا «پیش‌نمایش» دقیقاً خروجی نهایی را نشان بدهد و کاربر
 *  قبل از ذخیره ببیند چه چیزی برداشته می‌شود.
 * ===================================================================== */
function __varNoise(v){
  if(!v)return true;
  if(v.length>60)return true;
  var bad=['انتخاب کنید','یک گزینه را انتخاب کنید','choose an option',
           'select option','انتخاب گزینه','---','--','select'];
  var lv=v.toLowerCase();
  for(var i=0;i<bad.length;i++)if(lv===bad[i].toLowerCase())return true;
  return false;
}
/** مقدار یک گزینه — آینهٔ variationValueOf در PHP */
function __varValueOf(n){
  if(!n||n.nodeType!==1)return '';
  var tag=n.tagName.toLowerCase(),a,v,i;
  if(tag==='input'||tag==='option'){
    var f1=['data-value','value','title','aria-label'];
    for(i=0;i<f1.length;i++){v=(n.getAttribute(f1[i])||'').trim();
      if(v&&v.toLowerCase()!=='choose an option')return v;}
  }
  var f2=['data-value','data-title','data-slug','data-color','data-colour',
          'data-name','data-option','data-original-title','title','aria-label','alt'];
  for(i=0;i<f2.length;i++){v=(n.getAttribute(f2[i])||'').trim();if(v)return v;}
  var t=(n.textContent||'').replace(/\s+/g,' ').trim();
  if(t)return t;
  // رنگ به‌صورت عکس: alt/title، بعد نام فایل
  var img=tag==='img'?n:n.querySelector('img');
  if(img){
    var f3=['alt','title','data-title'];
    for(i=0;i<f3.length;i++){v=(img.getAttribute(f3[i])||'').trim();if(v)return v;}
    var f4=['src','data-src','data-lazy-src'];
    for(i=0;i<f4.length;i++){
      var src=(img.getAttribute(f4[i])||'').trim();
      if(!src)continue;
      var b=src.replace(/[?#].*$/,'').split('/').pop()
              .replace(/\.(png|jpe?g|gif|webp|svg|avif)$/i,'')
              .replace(/[-_]|%20/g,' ').trim();
      if(b&&!/^\d+$/.test(b)&&b.length<=40)return b;
    }
  }
  var st=(n.getAttribute('style')||'');
  var m=st.match(/background(?:-color)?\s*:\s*([^;]+)/i);
  if(m&&m[1].indexOf('url(')<0)return m[1].trim();
  var cm=(n.getAttribute('class')||'').match(/(?:color|colour|swatch)[-_]([a-z]{3,20})/i);
  if(cm)return cm[1];
  return '';
}
/** فهرست گزینه‌ها — آینهٔ variationsInside در PHP */
function __varValues(box){
  if(!box)return [];
  var out=[],seen={};
  function push(v){
    v=(v||'').trim();
    if(__varNoise(v))return;
    var k=v.toLowerCase();
    if(seen[k])return; seen[k]=1; out.push(v);
  }
  ['option','input[type=radio]','input[type=checkbox]'].forEach(function(q){
    Array.prototype.forEach.call(box.querySelectorAll(q),function(n){push(__varValueOf(n));});
  });
  if(out.length)return out;
  var sels=['li','label','button','a','span[data-value]','[class*=swatch]',
            '[class*=variation]','[class*=color]','[class*=colour]',
            '[class*=attribute]','[data-attribute_name]','img'];
  for(var i=0;i<sels.length;i++){
    Array.prototype.forEach.call(box.querySelectorAll(sels[i]),function(n){push(__varValueOf(n));});
    if(out.length>1)return out;
  }
  // فرزندان تکرارشونده (مثل مانتو پاتریس: هر رنگ یک div با عکس و برچسب)
  if(out.length<=1){
    var kids=Array.prototype.filter.call(box.children,function(c){
      return ['SCRIPT','STYLE','BR'].indexOf(c.tagName)<0;});
    if(kids.length>1){
      var multi=[];
      kids.forEach(function(c){var v=(__varValueOf(c)||'').trim();
        if(v&&!__varNoise(v))multi.push(v);});
      var uniq={},nu=0;
      multi.forEach(function(v){if(!uniq[v]){uniq[v]=1;nu++;}});
      if(nu>1){out=[];seen={};multi.forEach(push);if(out.length>1)return out;}
    }
  }
  if(!out.length)push(__varValueOf(box));
  return out;
}

function extractPrice(t){
  t=t.replace(/\s+/g,' ').trim();
  // v7.82: Match number with unit — pick longest
  var allU=t.match(/([\d۰-۹٠-٩][,،٬\s\d۰-۹٠-٩]*[\d۰-۹٠-٩])\s*(تومان|تومن|ریال)/g);
  if(allU&&allU.length){
    allU.sort(function(a,b){return b.replace(/[^\d]/g,'').length-a.replace(/[^\d]/g,'').length;});
    var parts=allU[0].match(/([\d۰-۹٠-٩][,،٬\s\d۰-۹٠-٩]*[\d۰-۹٠-٩])/);
    if(parts)return parts[1].trim();
  }
  var m=t.match(/([\d۰-۹٠-٩]{1,3}[,،٬][\d۰-۹٠-٩]{3}(?:[,،٬][\d۰-۹٠-٩]{3})*)/);
  if(m)return m[1].trim();
  // v7.82: Plain number without separators
  var plain=t.match(/[\d۰-۹٠-٩]{4,}/g);
  if(plain&&plain.length){
    plain.sort(function(a,b){return b.replace(/[^\d]/g,'').length-a.replace(/[^\d]/g,'').length;});
    return plain[0];
  }
  return '';
}

function getImageUrl(el){
  if(!el)return '';
  if(el.tagName==='IMG'){
    var attrs=['data-src','data-lazy-src','data-original','src'];
    for(var i=0;i<attrs.length;i++){
      var v=el.getAttribute(attrs[i]);
      if(v&&v.indexOf('placeholder')<0&&v.indexOf('1x1')<0)return v;
    }
  }
  var img=el.querySelector('img');
  if(img){
    var attrs=['data-src','data-lazy-src','data-original','src'];
    for(var i=0;i<attrs.length;i++){
      var v=img.getAttribute(attrs[i]);
      if(v&&v.indexOf('placeholder')<0&&v.indexOf('1x1')<0)return v;
    }
  }
  return '';
}

function getPreview(el, mode){
  if(!el)return '';
  // v8.66: پیش‌نمایش حالت‌های تصویری
  if(mode==='galleryBox'){
    var n=countImgs(el);
    if(!n)return '';
    var first=getImageUrl(el);
    return n+' عکس داخل این ظرف'+(first?(' — نمونه: '+first.split('/').pop().substring(0,40)):'');
  }
  if(mode==='galleryOne'||mode==='image'){
    var u=getImageUrl(el);
    return u?u.split('/').pop().substring(0,60):'';
  }
  // v8.68: تنوع‌ها — گزینه‌ها را جدا نشان بده، نه متن به‌هم‌چسبیده
  if(mode==='variations'){
    /* v8.85 + v10.116: گزینه‌ها + شمارش تصاویر سواچ (گالری) */
    var vv=__varValues(el);
    var ni=0;
    try{
      var imgs=el.querySelectorAll('img');
      ni=imgs?imgs.length:0;
      if(!ni){
        var st=el.querySelectorAll('[style*="background"],[data-image],[data-img],[data-src]');
        ni=st?st.length:0;
      }
    }catch(e){}
    if(!vv.length){
      var t=(el.textContent||'').replace(/\s+/g,' ').trim();
      return t?('چیزی پیدا نشد — متن ظرف: '+t.substring(0,60)):(ni?('🖼 '+ni+' تصویر سواچ'):'(خالی)');
    }
    return vv.length+' گزینه'+(ni?(' · 🖼 '+ni+' عکس → گالری'):'')+' ← '+vv.join(' · ');
  }
  /* v10.15: پیش‌نمایشِ قیمت دقیقاً از همان extractPrice می‌آید که سمتِ سرور
     هم استفاده می‌شود، تا آنچه اینجا می‌بینید همان چیزی باشد که ذخیره می‌شود. */
  if(mode==='price'){
    var pt=extractPrice(el.textContent||'');
    if(!pt)return '(قیمتی پیدا نشد — والد یا فرزند را امتحان کنید)';
    return '💰 '+pt;
  }
  if(mode==='shortDesc'||mode==='longDesc'){
    var t=(el.textContent||'').replace(/\s+/g,' ').trim();
    return t||'(خالی)';
  }
  if(mode==='sku'){
    var t=(el.textContent||'').replace(/\s+/g,' ').trim();
    return t.replace(/[^a-zA-Z0-9-_]/g,'')||t;
  }
  if(mode==='category'||mode==='tags'||mode==='brand'){
    var links=el.querySelectorAll('a');
    var arr=[];
    links.forEach(function(l){arr.push(l.textContent.trim());});
    if(arr.length)return arr.join('، ');
    return (el.textContent||'').replace(/\s+/g,' ').trim();
  }
  if(mode==='weight'){
    var t=(el.textContent||'').replace(/\s+/g,' ').trim();
    return t;
  }
  if(mode==='stock'){
    var t=(el.textContent||'').replace(/\s+/g,' ').trim();
    return t;
  }
  return (el.textContent||'').replace(/\s+/g,' ').trim().substring(0,120);
}

function selectEl(el){
  if(!el||el.tagName=='BODY'||el.tagName=='HTML'||el.closest('.__bar')||el.closest('.__pop'))return;
  var m=MODE;
  var s=gs(el);
  if(picked)picked.classList.remove('__s');
  el.classList.add('__s');
  el.classList.remove('__h');
  picked=el;

  // v8.66: حالت‌های گالری جداگانه ذخیره می‌شوند
  if(m==='galleryOne'){
    if(GAL.indexOf(s)<0)GAL.push(s);
    S.galleryOne=GAL.join('\n');
  }else{
    S[m]=s;
  }

  var _se=document.getElementById('__sel');if(_se)_se.textContent=s;
  var _tg=document.getElementById('__tag');if(_tg)_tg.textContent=el.tagName.toLowerCase()+(el.className?' .'+Array.from(el.classList).slice(0,2).join('.'):'');
  __paintGallery(m);
  __navState();

  // شمارندهٔ عکس/تطبیق روی نوار کوچک داخل صفحه
  var cntEl=document.getElementById('__cnt');
  var nMatch=countMatch(s);
  if(cntEl){
    if(m==='galleryBox'){
      cntEl.style.display='';
      cntEl.textContent='🖼 '+countImgs(el)+' عکس'+(nMatch>1?(' · '+nMatch+' ظرف'):'');
    }else if(m==='galleryOne'){
      cntEl.style.display='';
      cntEl.textContent='➕ '+countGalImgs(GAL)+' عکس';
    }else{
      cntEl.style.display=nMatch>1?'':'none';
      cntEl.textContent=nMatch>1?('⚠ '+nMatch+' تطبیق'):'';
    }
  }
  // v8.75: نوار کوچک را بالای همین المان بگذار
  __placePop(el,s,nMatch,m);
  // v8.68: وضعیت کامل به پنجرهٔ والد می‌رود تا کنترل‌های بیرونی به‌روز شوند
  __report();
}

/**
 * v8.75: نوار کنترل را دقیقاً بالای المان انتخاب‌شده می‌نشاند.
 * اگر بالای المان جا نبود، می‌رود زیرش؛ و افقی داخل صفحه نگه داشته می‌شود
 * تا هیچ‌وقت نصفه بیرون نیفتد.
 */
/**
 * v8.76: نوشتن محتوای نوار، جدا از جاگذاری آن.
 * قبلاً هر دو کار داخل __placePop بود و آن تابع بدون «المان انتخاب‌شده»
 * زود برمی‌گشت؛ نتیجه این بود که با Tab یا Esc فیلد عوض می‌شد ولی روی نوار
 * هیچ چیزی تغییر نمی‌کرد و معلوم نبود الان روی کدام فیلد هستید.
 */
function __popMeta(el,sel,nMatch,mode){
  var sEl=document.getElementById('__psel');
  if(sEl)sEl.textContent=sel||'— برای این فیلد هنوز چیزی انتخاب نشده —';
  // نام فیلد جاری روی خود نوار؛ سبز یعنی قبلاً پر شده
  var fEl=document.getElementById('__pfld');
  if(fEl){
    fEl.textContent=fieldLabel(mode);
    if(String(S[mode]||'').trim())fEl.classList.add('__fdone');
    else fEl.classList.remove('__fdone');
    var done=0;
    for(var q=0;q<FIELDS.length;q++)if(String(S[FIELDS[q][0]]||'').trim())done++;
    fEl.title='فیلد جاری — '+done+' از '+FIELDS.length+' پر شده. کلیک = فیلد بعدیِ خالی (Tab)';
  }
  // پیش‌نمایش همان چیزی که برداشته می‌شود، کنار دست کاربر
  var pv=document.getElementById('__ppv');
  if(pv){
    var txt='';
    if(el){ try{ txt=String(getPreview(el,mode)||''); }catch(e){ txt=''; } }
    pv.textContent=el?(txt?txt.substring(0,90):'(خالی)'):'روی عنصر دلخواه کلیک کنید';
    if(txt)pv.classList.remove('__warn'); else pv.classList.add('__warn');
  }
  var cEl=document.getElementById('__pcnt');
  if(cEl){
    if(mode==='galleryBox')      cEl.textContent=el?('🖼'+countImgs(el)):'';
    else if(mode==='galleryOne') cEl.textContent='➕'+countGalImgs(GAL);
    else                         cEl.textContent=(nMatch>1?('⚠'+nMatch):'');
  }
}

function __placePop(el,sel,nMatch,mode){
  var pop=document.getElementById('__pop');
  if(!pop)return;
  __popMeta(el,sel,nMatch,mode);
  if(!el)return;
  pop.classList.add('__on');
  var r=el.getBoundingClientRect();
  var sx=window.pageXOffset||document.documentElement.scrollLeft||0;
  var sy=window.pageYOffset||document.documentElement.scrollTop||0;
  var pw=pop.offsetWidth||260, ph=pop.offsetHeight||28;
  /* v8.76: نوار با position:absolute نسبت به «نزدیک‌ترین والدِ جای‌گرفته»
     می‌نشیند، نه نسبت به صفحه. خیلی از قالب‌ها روی body یا یک wrapper
     position:relative دارند و در آن صورت نوار با فاصلهٔ آن wrapper جابه‌جا
     و از کنار المان پرت می‌شد. مبدأ واقعی را اندازه می‌گیریم و کم می‌کنیم. */
  var ox=0,oy=0;
  try{
    var op=pop.offsetParent;
    if(op&&op!==document.body&&op!==document.documentElement){
      var orc=op.getBoundingClientRect();
      ox=orc.left+sx; oy=orc.top+sy;
    }else if(op===document.body){
      var bs=window.getComputedStyle(document.body);
      if(bs&&bs.position!=='static'){
        var brc=document.body.getBoundingClientRect();
        ox=brc.left+sx; oy=brc.top+sy;
      }
    }
  }catch(e){}
  var top=r.top+sy-ph-6;
  if(r.top-ph-6<0)top=r.bottom+sy+6;            // جا نبود → برو زیرش
  /* v9.90: مثل پیش‌نمایش فهرست — وسط‌چین روی المان و clamp به viewport
     تا دکمهٔ سمت راست (والد) هیچ‌وقت بیرون نزند. */
  var vw=document.documentElement.clientWidth||window.innerWidth||360;
  var left=r.left+sx+(r.width-pw)/2;
  var minL=sx+4, maxL=sx+vw-pw-8;
  if(maxL<minL)maxL=minL;
  if(left>maxL)left=maxL;
  if(left<minL)left=minL;
  pop.style.top=(Math.max(sy+2,top)-oy)+'px';
  pop.style.left=(left-ox)+'px';
  var d=function(id,on){var b=document.getElementById(id);if(b)b.disabled=!on;};
  // v9.90: هر چهار جهت وضعیت فعال/غیرفعال می‌گیرند
  d('__pup',   !!(el.parentElement&&el.parentElement.tagName!=='BODY'));
  d('__pdn',   !!el.firstElementChild);
  d('__pprv',  !!el.previousElementSibling);
  d('__pnxt',  !!el.nextElementSibling);
}

/** رنگ‌آمیزی تصاویری که با انتخاب فعلی برداشته می‌شوند */
function __paintGallery(m){
  Array.prototype.forEach.call(document.querySelectorAll('.__gal'),function(x){x.classList.remove('__gal');});
  try{
    if(m==='galleryBox'&&picked){
      Array.prototype.forEach.call(picked.querySelectorAll('img'),function(im){im.classList.add('__gal');});
      if(picked.tagName==='IMG')picked.classList.add('__gal');
    }else if(m==='galleryOne'){
      GAL.forEach(function(sel){
        Array.prototype.forEach.call(document.querySelectorAll(sel),function(x){
          if(x.tagName==='IMG')x.classList.add('__gal');
          else Array.prototype.forEach.call(x.querySelectorAll('img'),function(im){im.classList.add('__gal');});
        });
      });
    }
  }catch(e){}
}

/** v8.66: حرکت در درخت — والد / فرزند / هم‌سطح */
function __go(dir){
  if(!picked){__post('picker_hint',{msg:'اول روی یک عنصر کلیک کنید.'});return;}
  var t=null;
  if(dir==='up')   t=picked.parentElement;
  if(dir==='down') t=picked.firstElementChild;
  if(dir==='prev') t=picked.previousElementSibling;
  if(dir==='next') t=picked.nextElementSibling;
  // از نوار خودمان و ریشه رد شو
  while(t&&t.closest&&(t.closest('.__bar')||t.closest('.__pop'))) t=(dir==='prev')?t.previousElementSibling:t.nextElementSibling;
  if(!t||t.tagName==='BODY'||t.tagName==='HTML'){
    __post('picker_hint',{msg:'در این جهت عنصری نیست.'});
    return;
  }
  __post('picker_hint',{msg:''});
  selectEl(t);
  // v8.75: فقط وقتی اسکرول کن که المان از دید بیرون باشد. اسکرولِ همیشگی
  // باعث می‌شد صفحه زیر دست کاربر مدام بپرد و کار کند شود.
  try{
    var r=t.getBoundingClientRect();
    var vh=window.innerHeight||document.documentElement.clientHeight;
    if(r.top<60||r.bottom>vh-20) __softScroll(t,{block:'center',behavior:'smooth'});
    setTimeout(function(){ __placePop(t,S[MODE]||gs(t),countMatch(gs(t)),MODE); },320);
  }catch(e){}
}

/* v8.75: میان‌برهای صفحه‌کلید — دست از موس برداشته نمی‌شود.
   ↑ والد · ↓ فرزند · → قبلی · ← بعدی · Enter اتمام · Esc پنهان کردن */
document.addEventListener('keydown',function(e){
  if(__pickPaused)return;
  var t=e.target;
  if(t&&(t.tagName==='INPUT'||t.tagName==='TEXTAREA'||t.isContentEditable))return;
  /* v8.76: Tab بین فیلدها می‌چرخد و به المان دست نمی‌زند، پس حتی وقتی هنوز
     چیزی انتخاب نشده هم باید کار کند. بقیهٔ کلیدها به المان نیاز دارند. */
  if(e.key==='Tab'){
    e.preventDefault();e.stopPropagation();
    __field(e.shiftKey?-1:1);
    return;
  }
  if(!picked)return;
  var map={ArrowUp:'up',ArrowDown:'down',ArrowRight:'prev',ArrowLeft:'next'};
  if(map[e.key]){e.preventDefault();e.stopPropagation();__go(map[e.key]);return;}
  // v8.76: Space = ثبت همین المان و پریدن به فیلد بعدیِ خالی
  if(e.key===' '||e.key==='Spacebar'){
    e.preventDefault();e.stopPropagation();
    __field(1);
    return;
  }
  if(e.key==='Enter'){e.preventDefault();__done();return;}
  // v8.76: Esc انتخاب فعلی همین فیلد را پس می‌گیرد (نه کل کار را)
  if(e.key==='Escape'){
    e.preventDefault();e.stopPropagation();
    if(MODE==='galleryOne'){GAL=[];delete S.galleryOne;__paintGallery('galleryOne');}
    else delete S[MODE];
    if(picked)picked.classList.remove('__s');
    picked=null;
    var pop=document.getElementById('__pop');if(pop)pop.classList.remove('__on');
    __post('picker_hint',{msg:'انتخاب «'+fieldLabel(MODE)+'» پاک شد.'});
    __report();
    return;
  }
},true);

/* نوار باید موقع اسکرول و تغییر اندازه، چسبیده به المان بماند */
var __rp=null;
function __repos(){
  if(!picked)return;
  clearTimeout(__rp);
  __rp=setTimeout(function(){
    try{ __placePop(picked,S[MODE]||gs(picked),countMatch(gs(picked)),MODE); }catch(e){}
  },40);
}
window.addEventListener('scroll',__repos,true);
window.addEventListener('resize',__repos);
window.__go=__go;

function __navState(){
  var d=function(id,on){var b=document.getElementById(id);if(b)b.disabled=!on;};
  d('__up',   !!(picked&&picked.parentElement&&picked.parentElement.tagName!=='BODY'));
  d('__down', !!(picked&&picked.firstElementChild));
  d('__prev', !!(picked&&picked.previousElementSibling));
  d('__next', !!(picked&&picked.nextElementSibling));
}

document.addEventListener('mouseover',function(e){
  if(__pickPaused)return;
  if(e.target.closest('.__bar')||e.target.closest('.__pop'))return;
  if(cur&&cur!==picked)cur.classList.remove('__h');
  cur=e.target;
  if(cur!==picked)cur.classList.add('__h');
},true);

document.addEventListener('mouseout',function(e){
  if(__pickPaused)return;
  if(e.target&&e.target!==picked)e.target.classList.remove('__h');
},true);

document.addEventListener('click',function(e){
  if(__pickPaused)return;
  if(e.target.closest('.__bar')||e.target.closest('.__pop'))return;
  e.preventDefault();e.stopPropagation();
  selectEl(e.target);
},true);

window.__hideBar=function(){var b=document.getElementById('__bar');if(b)b.classList.add('__off');};

/* v8.68: کنترل‌ها به پنجرهٔ والد رفتند. این iframe فقط فرمان می‌گیرد و
   وضعیت را برمی‌گرداند، پس ارتفاع صفحهٔ محصول دیگر خورده نمی‌شود. */
function __post(t,d){ try{ parent.postMessage(Object.assign({type:t},d||{}),'*'); }catch(e){} }

/**
 * v8.76: یک مسیر واحد برای عوض کردن فیلد — چه از پنل والد بیاید چه از
 * دکمهٔ داخل صفحه. قبلاً فقط داخل شنوندهٔ پیام بود و دکمهٔ درون‌صفحه‌ای
 * نمی‌توانست از آن استفاده کند.
 */
function __setMode(m){
  MODE=String(m||'shortDesc');
  __paintGallery(MODE);
  // اگر این فیلد قبلاً انتخاب شده، همان را دوباره نشان بده
  try{
    if(S[MODE]){
      var prev=document.querySelector(String(S[MODE]).split('\n')[0]);
      if(prev){
        if(picked)picked.classList.remove('__s');
        prev.classList.add('__s'); picked=prev;
        __placePop(prev,S[MODE],countMatch(S[MODE]),MODE);
        var r=prev.getBoundingClientRect(),vh=window.innerHeight||600;
        if(r.top<60||r.bottom>vh-20)__softScroll(prev,{block:'center'});
      }
    }else if(picked){
      // فیلد تازه است ولی المانی در دست داریم: نوار همان‌جا بماند تا
      // بشود بدون کلیک دوباره، همین المان را برای فیلد جدید ثبت کرد
      __placePop(picked,'',0,MODE);
    }else{
      /* v8.76: هیچ المانی در دست نیست. نوار را پنهان نمی‌کنیم بلکه نام فیلد
         جدید را رویش می‌نویسیم، وگرنه با Tab فیلد عوض می‌شد و کاربر هیچ
         نشانه‌ای نمی‌دید. اگر هنوز هیچ‌جا جای نگرفته، بالای صفحه بنشیند. */
      __popMeta(null,'',0,MODE);
      var pop=document.getElementById('__pop');
      if(pop){
        pop.classList.add('__on');
        if(!pop.style.top){
          var sy0=window.pageYOffset||document.documentElement.scrollTop||0;
          pop.style.top=(sy0+8)+'px'; pop.style.left='8px';
        }
      }
    }
  }catch(e){}
  __report();
}

function __report(){
  /* v10.116: شمارش تصاویر سواچ در حالت تنوع برای پنل بیرونی */
  var _varImgs=0;
  if(MODE==='variations'&&picked){
    try{
      _varImgs=(picked.querySelectorAll('img')||[]).length;
      if(!_varImgs) _varImgs=(picked.querySelectorAll('[style*="background"],[data-image],[data-img],[data-src]')||[]).length;
    }catch(e){}
  }
  __post('picker_state',{
    mode:MODE, sel:S[MODE]||'', gal:GAL.slice(),
    tag:picked?picked.tagName.toLowerCase():'',
    nav:{up:!!(picked&&picked.parentElement&&picked.parentElement.tagName!=='BODY'),
         down:!!(picked&&picked.firstElementChild),
         prev:!!(picked&&picked.previousElementSibling),
         next:!!(picked&&picked.nextElementSibling)},
    imgs:MODE==='galleryBox'?countImgs(picked):(MODE==='galleryOne'?countGalImgs(GAL):(MODE==='variations'?_varImgs:0)),
    varImgs:_varImgs,
    matches:countMatch(S[MODE]||''),
    preview:picked?String(getPreview(picked,MODE)||'').substring(0,150):'',
    // v8.85: فهرست کاملِ تنوع‌ها، جدا از متن کوتاه‌شدهٔ پیش‌نمایش، تا پنل
    // بتواند خروجی نهایی را کامل و گزینه‌به‌گزینه نشان دهد
    vars:(MODE==='variations'&&picked)?__varValues(picked).slice(0,60):null,
    all:S
  });
}

window.addEventListener('message',function(e){
  var d=e.data||{};
  if(d.type==='picker_mode'){
    __setMode(String(d.mode||'shortDesc'));
  }else if(d.type==='picker_go'){
    __go(String(d.dir||'up'));
  }else if(d.type==='picker_pause'){
    window.__togglePickPause(!!d.on);
  }else if(d.type==='picker_popbar'){
    /* v9.90: نمایش/پنهان‌کردن نوار شناور از روی چک‌باکس پنل بیرونی */
    var pop=document.getElementById('__pop');
    if(pop){ if(d.on===false)pop.classList.add('__off'); else pop.classList.remove('__off'); }
  }else if(d.type==='picker_clear_gal'){
    GAL=[];delete S.galleryOne;__paintGallery('galleryOne');__report();
  }else if(d.type==='picker_done'){
    if(GAL.length)S.galleryOne=GAL.join('\n');
    __post('detail_selectors',{data:S});
  }
});

window.__done=function(){
  if(GAL.length)S.galleryOne=GAL.join('\n');
  __post('detail_selectors',{data:S});
};

/* v9.90: __field داخل IIFE بود و onclickهای HTML به آن نمی‌رسیدند، پس
   دکمه‌های ‹ › و نام فیلد روی نوار شناور بی‌اثر بودند. */
window.__field=__field;

__navState();
__post('picker_ready',{});
})();
</script>
SCRIPT;

// v8.67: نسخه را داخل نوار انتخابگر بنویس. اگر کاربر فایل را روی هاست
// به‌روز نکرده باشد، همین‌جا معلوم می‌شود که نسخهٔ قدیمی باز شده و
// نبودِ گزینه‌های گالری از همان است، نه از خرابی.
/* v8.67: نسخه را داخل نوار انتخابگر بنویس تا اگر فایل روی هاست قدیمی
   مانده باشد همان‌جا معلوم شود.
   v8.76: این جایگزینی از ۸.۶۸ تا حالا بی‌اثر بود — بازچینی نوار عنصرِ
   «__ver» را برداشته بود و str_replace چیزی برای پیدا کردن نداشت، پس
   شمارهٔ نسخه هیچ‌وقت نمایش داده نمی‌شد. عنصر برگشت و رشتهٔ جست‌وجو
   کوتاه شد تا به بازچینی‌های بعدی حساس نباشد. */
$script = str_replace('id="__ver" style="opacity:.65">',
    'id="__ver" style="opacity:.65">v' . APP_VERSION,
    $script);
$script = str_replace('__S4_SELECTOR_WAIT_MS__', (string)$dpWaitMs, $script);

/* v9.93: فونتِ انتخابیِ کاربر روی نوارها و پاپ‌آپِ خودِ ما هم اعمال شود.
   فقط متغیر --app-font تعریف می‌شود؛ CSS خودِ سایتِ مقصد دست نمی‌خورد. */
/* v9.94: رنگ‌بندی هم فقط روی نوار/پاپ‌آپِ خودِ ما ترجمه می‌شود، نه روی
   HTMLِ سایتِ مقصد (وگرنه ظاهرِ سایتِ مبدأ به‌هم می‌ریخت). */
$script = app_theme_filter(app_font_boot() . $script);
$html = preg_replace('~</body>~i', $script . '</body>', $html);
if (stripos($html, '</body>') === false) $html .= $script;

$html = preg_replace('~<a ([^>]*)href=~i', '<a $1data-href=', $html);

header('Content-Type: text/html; charset=UTF-8');
echo $html;
exit;
}

if (!empty($_GET['visual_proxy'])) {
$url = s4NormalizeInputUrl((string)($_GET['visual_proxy'] ?? ''));
if (!filter_var($url, FILTER_VALIDATE_URL)) { http_response_code(400); echo 'Invalid URL'; exit; }

/* v8.99: مهلت طولانی‌تر و یک تلاش دوم.

   کاربر گزارش داد «بارگذاری صفحه» تایم‌اوت می‌دهد ولی «بارگذاری مستقیم»
   همان صفحه را کامل باز می‌کند. این دو اصلاً یک کار نمی‌کنند:

     بارگذاری مستقیم → مرورگرِ شما صفحه را می‌گیرد (از ایران، با DNS و
                        مسیر شبکهٔ خودتان)
     بارگذاری صفحه   → سرورِ ما صفحه را می‌گیرد و بعد به شما می‌دهد

   پس تایم‌اوت یعنی «سرور من نتوانست»، نه «سایت خراب است». روی هاست
   ایرانی این خیلی عادی است: مسیر شبکهٔ دیتاسنتر کندتر است، بعضی مقصدها
   محدود شده‌اند، و سایت‌های سنگین بیش از ۲۰ ثانیه طول می‌کشند.

   مهلت حالا قابل تنظیم است (پیش‌فرض ۴۵ ثانیه به‌جای ۲۰) و اگر بار اول
   فقط به‌خاطر کندی نشد، یک بار دیگر با مهلت بیشتر تلاش می‌شود. */
$cnVP = loadConnections();
$vpTimeout = (int)($cnVP['proxy_timeout_sec'] ?? 0);
if ($vpTimeout <= 0) $vpTimeout = 45;
$vpTimeout = max(10, min(180, $vpTimeout));
$vpWaitMs = max(0, min(30000, (int)($_GET['wait_ms'] ?? ($_GET['selector_wait_ms'] ?? 0))));

// v9.75: اتصالِ این صفحه را مطابقِ «اتصال غیرمستقیم»ِ پروفایلِ انتخاب‌شده بگذار
srcNetSetProfileIndirect((string)($_GET['pk'] ?? ''));

$res = fetch_html($url, $vpTimeout);
if (!$res['ok']) {
    $e1 = (string)($res['error'] ?? '');
    // فقط برای کندی دوباره تلاش کن؛ برای DNS/۴۰۴ تلاش دوم بی‌فایده است
    if (stripos($e1, 'timed out') !== false || stripos($e1, 'timeout') !== false
        || stripos($e1, 'Empty') !== false) {
        $res = fetch_html($url, min(180, $vpTimeout * 2));
    }
}
if ((!$res['ok'] || (isEmallsUrl($url) && stripos((string)($res['html'] ?? ''), '~id~') === false))
    && function_exists('fetch_html_smart')) {
    $_smart = fetch_html_smart($url, min(180, $vpTimeout));
    if (!empty($_smart['ok']) && (stripos((string)($_smart['html'] ?? ''), '~id~') !== false || strlen((string)($_smart['html'] ?? '')) > strlen((string)($res['html'] ?? '')))) $res = $_smart;
}
if (!$res['ok']) {
http_response_code(500);
$err = $res['error'] ?? 'Unknown';
$_vpHint = '<div style="margin-top:26px;padding:16px 18px;background:#1e293b;border:1px solid #334155;border-radius:10px;line-height:2;font-size:13px;color:#cbd5e1">'
  . '<b style="color:#e2e8f0">چه کنم؟</b><br>'
  . '۱) دکمهٔ <b style="color:#4ade80">🌐 بارگذاری مستقیم</b> را بزنید — صفحه را مرورگر خودتان می‌گیرد، نه سرور. برای انتخاب سلکتور کاملاً کافی است.<br>'
  . '۲) اگر سایت فقط کند است: در تنظیمات ← <b>مهلت بارگذاری صفحه</b> را بالاتر ببرید (الان '
  . (int)$vpTimeout . ' ثانیه، دو بار تلاش شد).<br>'
