}
$sheetRows .= '</row>';

foreach ($products as $i => $p) {
$row = $i + 2;
$sheetRows .= '<row r="'.$row.'">';
$vals = [($i + 1), $p['title'] ?? '', $p['origPrice'] ?? '', $p['price'] ?? '', $p['link'] ?? '', $p['image'] ?? ''];
foreach ($detailFields as $f) {
$val = $p[$f['key']] ?? '';
