}
if ($useCustom) $vals[] = $p['custom'] ?? '';
for ($c = 0; $c < $cols; $c++) {
$col = chr(65 + $c);
if ($c === 0) {
$sheetRows .= '<c r="'.$col.$row.'"><v>'.($i + 1).'</v></c>';
} else {
$sheetRows .= '<c r="'.$col.$row.'" t="s"><v>'.ssIdx($vals[$c] ?? '').'</v></c>';
}
}
$sheetRows .= '</row>';
}

