if (isset($_POST['auto_resume_all_cron'])) $conn['auto_resume_all_cron'] = !empty($_POST['auto_resume_all_cron']) && $_POST['auto_resume_all_cron'] !== 'false';
if (isset($_POST['keep_reports']))      $conn['keep_reports']      = max(1, min(200, (int)$_POST['keep_reports']));
// v8.69: آپدیت محتوای تازه روی محصولات موجود (پیش‌فرض روشن)
if (isset($_POST['content_sync']))      $conn['content_sync']      = !empty($_POST['content_sync']) && $_POST['content_sync'] !== 'false';
// v8.60: چند کلمهٔ اول برای یادگیری و دسته‌بندی خودکار
if (isset($_POST['catlearn_words']))    $conn['catlearn_words']    = max(1, min(CATLEARN_MAX_WORDS, (int)$_POST['catlearn_words']));
// v8.64: پاسخ خودکار به پیام مشتریان
if (isset($_POST['autoreply'])) {
    $ar = json_decode((string)$_POST['autoreply'], true) ?: [];
    $conn['autoreply'] = [
        'enabled'       => !empty($ar['enabled']),
        'grace_min'     => max(0, min(1440, (int)($ar['grace_min'] ?? 10))),
        'per_chat_min'  => max(0, min(10080, (int)($ar['per_chat_min'] ?? 180))),
        'max_per_run'   => max(1, min(50, (int)($ar['max_per_run'] ?? 5))),
        'only_offhours' => !empty($ar['only_offhours']),
        'work_from'     => max(0, min(23, (int)($ar['work_from'] ?? 9))),
        'work_to'       => max(0, min(23, (int)($ar['work_to'] ?? 21))),
        'sign'          => mb_substr(trim((string)($ar['sign'] ?? '')), 0, 120),
        'notify'        => !empty($ar['notify']),
        'scan_limit'    => max(5, min(50, (int)($ar['scan_limit'] ?? 20))),
        // v9.33: وقتی هیچ قاعده‌ای نخورد، یکی از سه حالت:
        //   none    → بدون پاسخ
        //   premade → پاسخ از پیش آماده (fallback_text)
        //   ai      → پاسخ با هوش مصنوعی (مدل فعال)
        'fallback'      => in_array(($ar['fallback'] ?? ''), ['none','premade','ai'], true) ? $ar['fallback'] : 'none',
        'fallback_text' => mb_substr(trim((string)($ar['fallback_text'] ?? '')), 0, 500),
        // v9.37: پیام سیستمیِ هوش مصنوعی — default (پیش‌فرض) یا custom (سفارشی)
        'ai_system_mode' => in_array((string)($ar['ai_system_mode'] ?? 'default'), ['default','custom'], true) ? $ar['ai_system_mode'] : 'default',
        'ai_system_text' => mb_substr(trim((string)($ar['ai_system_text'] ?? '')), 0, 2000),
        // v9.38: ترتیب اولویت پاسخ‌دهی — بین قواعد آماده و هوش مصنوعی
        //   rules_first → اول قواعد، اگر هیچ قاعده‌ای نخورد هوش مصنوعی
        //   ai_first    → اول هوش مصنوعی، اگر خطا داد قواعد
        //   rules_only  → فقط قواعد آماده
        //   ai_only     → فقط هوش مصنوعی
        'reply_order'   => in_array((string)($ar['reply_order'] ?? 'rules_first'), ['rules_first','ai_first','rules_only','ai_only'], true) ? $ar['reply_order'] : 'rules_first',
    ];
}
// v8.62: گزارش شبانه
if (isset($_POST['digest_enabled']))    $conn['digest_enabled']    = !empty($_POST['digest_enabled']) && $_POST['digest_enabled'] !== 'false';
if (isset($_POST['digest_hour']))       $conn['digest_hour']       = max(0, min(23, (int)$_POST['digest_hour']));
if (isset($_POST['digest_hours']))      $conn['digest_hours']      = max(1, min(168, (int)$_POST['digest_hours']));
if (isset($_POST['digest_tz']))         $conn['digest_tz']         = trim((string)$_POST['digest_tz']);
$_savedC = writeJsonFile(CONNECTIONS_FILE, $conn);
if ($_savedC['ok']) {
    /* Shop-picker changes are operational controls, not merely settings for a
       future queue. Apply them now; a live backend rechecks before next item. */
    $bslShopSelectionApply=isset($_POST['basalam'])?bslReconcileDisabledShopsNow($conn):null;
    $newMxShopSig=function_exists('shopPricingSignature')?shopPricingSignature($conn):'';
    $mxRefresh=$oldMxShopSig!==$newMxShopSig?matrixRefreshExpectedPrices('destination_price_change'):['ok'=>true,'changed'=>false,'rows'=>0];
    $modeTransition=null;
    if(isset($_POST['recon_auto'])){
        $newExecMode=(string)($conn['recon_auto']['execution_mode']??'cron_first');
        /* Apply even when the name did not change: Save acts as an immediate
           control pulse and wakes a job paused under an expired lease. */
        $modeTransition=matrixExecutionApplyMode($newExecMode);
        if($oldMatrixExecMode!==$newExecMode){
            matrixProgress(['log_add'=>['⚡ روش اجرا همان لحظه از '.$oldMatrixExecMode.' به '.$newExecMode.' تغییر کرد']]);
            matrixFixProgress(['log_add'=>['⚡ روش اجرا همان لحظه از '.$oldMatrixExecMode.' به '.$newExecMode.' تغییر کرد']]);
        }
        if(!empty($conn['recon_auto']['build_only'])&&function_exists('s4WorkerQueueMutate')){
            s4WorkerQueueMutate(static function(&$q){
                $now=time();
                foreach((array)($q['entries']??[]) as $idx=>$e){
                    if(!is_array($e)||(string)($e['type']??'')!=='matrix_fix'
                        ||!in_array((string)($e['status']??''),['pending','paused','running'],true))continue;
                    $dk=(string)($e['dedup_key']??'');
                    $src=(string)($e['payload']['source']??'');
                    if($src!=='recon_auto'&&strpos($dk,'matrix_fix|recon_auto')!==0)continue;
                    $q['entries'][$idx]['updated_at']=$now;
                    $q['entries'][$idx]['error']='periodic_build_only_enabled';
                    if((string)($e['status']??'')==='running'){
                        /* Let the owned worker reach its next safe checkpoint; the live guard
                           in matrixFixRun will prevent any further periodic mutation. */
                        $q['entries'][$idx]['periodic_build_only_requested_at']=$now;
                    }else{
                        $q['entries'][$idx]['status']='cancelled';
                        $q['entries'][$idx]['done_at']=$now;
                    }
                }
                return ['ok'=>true];
            });
        }
    }
    echo json_encode(['ok'=>true,'message'=>'ذخیره شد','matrix_repriced'=>$mxRefresh,'matrix_execution'=>$modeTransition,
        'bsl_shop_selection'=>$bslShopSelectionApply], JSON_UNESCAPED_UNICODE);
} else echo json_encode(['ok'=>false,'error'=>'خطا در ذخیره: '.($_savedC['error']??'نامشخص')], JSON_UNESCAPED_UNICODE);
exit;
}

if (($_POST['action'] ?? '') === 'upload_import') {
header('Content-Type: application/json; charset=UTF-8');
if (empty($_FILES['importFile']) || $_FILES['importFile']['error'] !== UPLOAD_ERR_OK) {
