}
$tmpPath = $_FILES['importFile']['tmp_name'];
$origName = $_FILES['importFile']['name'];
$ext = strtolower(pathinfo($origName, PATHINFO_EXTENSION));
if (!in_array($ext, ['csv','xls','xlsx','xml'])) {
