}
if (!is_dir(UPLOAD_DIR)) @mkdir(UPLOAD_DIR, 0755, true);
$savePath = UPLOAD_DIR . 'import_' . time() . '.' . $ext;
move_uploaded_file($tmpPath, $savePath);
$parsed = parseUploadedFile($savePath, $ext);
if (!empty($parsed['error'])) {
