/* Delete only a stopped/terminal row after atomically verifying that no worker
   job or extraction slot still owns it; otherwise the worker could write it back. */
if(isset($_GET['extract_queue_delete'])){
    header('Content-Type: application/json; charset=UTF-8');
    $qid=trim((string)($_GET['queue_id']??''));
    if($qid===''){echo json_encode(['ok'=>false,'error'=>'missing_queue_id'],JSON_UNESCAPED_UNICODE);exit;}
    extractQueueFinalizeStopIfIdle($qid);
    $deleted=extractQueueDeleteSafe($qid);
    if(!empty($deleted['ok'])&&(int)($deleted['removed']??0)>0){
        @unlink(extractReportFile($qid));extractClearStopSignalForQueue($qid);
    }
    echo json_encode($deleted,JSON_UNESCAPED_UNICODE);exit;
}

/* پاک کردن ردیف‌های تکمیل‌شده — همتای woo_queue_clear_done */
if(isset($_GET['extract_queue_clear_done'])){
header('Content-Type: application/json; charset=UTF-8');
$queue=extractReadQueue();
$before=count($queue['entries']);
foreach($queue['entries'] as $e){
    if(in_array(($e['status']??''),['done','failed','superseded'],true)) @unlink(extractReportFile($e['id']??''));
}
$queue['entries']=array_values(array_filter($queue['entries'],fn($e)=>!in_array(($e['status']??''),['done','failed','superseded'],true)));
extractWriteQueue($queue);
echo json_encode(['ok'=>true,'removed'=>$before-count($queue['entries'])],JSON_UNESCAPED_UNICODE);exit;
}

if(isset($_GET['extract_stop'])){
    header('Content-Type: application/json; charset=UTF-8');
    $stopQid=trim((string)($_GET['queue_id']??''));
    $prev=readProgress(EXTRACT_PROGRESS_FILE);
    /* Record the explicit user decision under the queue lock first. Worker
       snapshots can then no longer erase it while the matching child exits. */
    $requested=extractQueueRequestStop($stopQid);
    if(empty($requested['ok'])){
        echo json_encode(['ok'=>false,'error'=>(string)($requested['error']??'queue_write_failed')],JSON_UNESCAPED_UNICODE);exit;
    }
    $stopped=[];$pending=[];$terminated=[];$results=[];
    foreach((array)($requested['rows']??[])as$stopRow){
        if(!is_array($stopRow))continue;$id=trim((string)($stopRow['id']??''));if($id==='')continue;
        extractStopSignalSetForQueue($id);
        $cancel=extractCancelWorkerForQueueRow($stopRow);
        $final=extractQueueFinalizeStopIfIdle($id);
        $isPending=empty($final['ok'])||!empty($final['active']);
        if(!empty($final['finalized']))$stopped[]=$id;
        if($isPending)$pending[]=$id;
        if(!empty($cancel['signal_sent']))$terminated[]=(int)($cancel['pid']??0);
        if(!empty($requested['progress_owned'][$id])
            &&(string)($prev['queue_id']??'')===$id){
            $phase=(string)($stopRow['resume_phase']??$stopRow['phase']??$prev['phase']??'list');
            $phase=$phase==='detail'?'detail':'list';
            $log=$isPending?'⏳ درخواست توقف ثبت شد؛ پردازه در حال آزادکردن قفل است':'❌ متوقف شد — checkpoint حفظ شد';
            $patch=['running'=>$isPending,'done'=>!$isPending,'cancelled'=>!$isPending,
                'stopped'=>!$isPending,'stop_requested'=>$isPending,'stop_pending'=>$isPending,
                'stopped_by_user'=>true,'partial'=>true,'resumable'=>true,'resume_phase'=>$phase,
                'profile_key'=>(string)($stopRow['profile_key']??$prev['profile_key']??''),
                'last_progress_ts'=>time(),'recent_log'=>array_slice(array_merge((array)($prev['recent_log']??[]),[$log]),-40),
                'total_log_count'=>max((int)($prev['total_log_count']??0)+1,count((array)($prev['recent_log']??[]))+1)];
            writeProgress(EXTRACT_PROGRESS_FILE,array_merge($prev,$patch));
        }
        $results[]=['queue_id'=>$id,'job_id'=>(string)($cancel['job_id']??''),
            'signal_sent'=>!empty($cancel['signal_sent']),'termination_pending'=>$isPending,
            'finalized'=>!empty($final['finalized'])];
    }
    echo json_encode(['ok'=>true,'stopped'=>$stopped,'requested'=>array_values(array_unique(array_map(
        static fn($r)=>(string)($r['id']??''),(array)($requested['rows']??[])))),
        'stop_pending'=>$pending,'terminated_pids'=>$terminated,'results'=>$results],JSON_UNESCAPED_UNICODE);
    exit;
}

/* v10.122: ادامهٔ استخراج از یک صفحه قبل از محل گیر — نه از صفر */
if (isset($_GET['extract_resume']) || (($_POST['action'] ?? '') === 'extract_resume')) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(0);
    @ignore_user_abort(true);
    $pk = trim((string)($_GET['profile_key'] ?? $_POST['profile_key'] ?? ''));
    $qid = trim((string)($_GET['queue_id'] ?? $_POST['queue_id'] ?? ''));
    if ($pk === '' && $qid !== '') {
        $q = extractReadQueue();
        foreach ((array)($q['entries'] ?? []) as $e) {
            if ((string)($e['id'] ?? '') === $qid) {
                $pk = (string)($e['profile_key'] ?? '');
                break;
            }
        }
    }
    if ($pk === '') {
        echo json_encode(['ok' => false, 'error' => 'profile_key لازم است'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $profiles = loadProfiles();
    if (!isset($profiles[$pk]) || !is_array($profiles[$pk])) {
        echo json_encode(['ok' => false, 'error' => 'پروفایل یافت نشد'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $pr = $profiles[$pk];
    /* v10.136: آماده‌سازی، بستن blocker و mutation پروفایل فقط زیرِ
       reservation انجام می‌شود؛ بعد worker همان handle را مصرف می‌کند. */
    $prep = extractResumePrepare($pk, loadConnections(), $qid, true);
    if (empty($prep['ok'])) {
        $_prepReason=(string)($prep['reason']??'');
        $_prepMsg=$_prepReason==='resume_row_not_found_or_not_resumable'
            ? 'همان ردیف دیگر قابل ادامه نیست؛ ردیف تازه‌ای ساخته نشد'
            : 'استخراجِ دیگری در حال اجراست — اجرای موازی ساخته نشد';
        echo json_encode(['ok'=>false,'error'=>$_prepMsg,'reason'=>$_prepReason],JSON_UNESCAPED_UNICODE);
        exit;
    }
    $meta = extractListResumeMeta(loadProfiles()[$pk] ?? $pr);
    $phase = (string)$prep['phase'];
    $prNowResume = loadProfiles()[$pk] ?? $pr;
    $runPhaseResume = ($phase === 'list' && !empty($prNowResume['_extract_want_detail'])) ? 'all' : $phase;
    $detailModeResume = normalizeDetailExtractMode($prNowResume['detailExtractMode'] ?? 'two_stage');
    if(s4WorkerIsActive()){
        extractLockRelease((string)($prep['queue_id']??''));
        $enq=s4WorkerEnqueueBackendExtract($pk,$runPhaseResume,false,true,-1,(string)($prep['queue_id']??''),true,$detailModeResume);
        echo json_encode(['ok'=>!empty($enq['ok']),'started'=>!empty($enq['ok']),'resuming'=>true,'worker'=>true,
            'profile_key'=>$pk,'phase'=>$phase,'run_phase'=>$runPhaseResume,'start_page'=>(int)$meta['start_page'],'page_ok'=>(int)$meta['page_ok'],
            'page_try'=>(int)$meta['page_try'],'message'=>'ادامهٔ مرحلهٔ '.$phase.' از checkpoint به worker سپرده شد']+$enq,JSON_UNESCAPED_UNICODE);
        exit;
    }
    if(function_exists('s4SpawnBackendExtractChild')){
        extractLockRelease((string)($prep['queue_id']??''));
        $spResume=s4SpawnBackendExtractChild($pk,$runPhaseResume,false,true,-1,$detailModeResume,(string)($prep['queue_id']??''));
        if(!empty($spResume['ok'])){
            echo json_encode(['ok'=>true,'started'=>true,'resuming'=>true,'worker_child'=>true,
                'profile_key'=>$pk,'phase'=>$phase,'run_phase'=>$runPhaseResume,'start_page'=>(int)$meta['start_page'],
                'queue_id'=>(string)($prep['queue_id']??''),'pid'=>(int)($spResume['pid']??0)],JSON_UNESCAPED_UNICODE);
            exit;
        }
        $prep = extractResumePrepare($pk, loadConnections(), $qid, true);
        if (empty($prep['ok'])) {
            echo json_encode(['ok'=>false,'error'=>'ادامه ممکن نشد','reason'=>(string)($prep['reason']??'')],JSON_UNESCAPED_UNICODE);
            exit;
        }
    }
    /* exec-disabled hosting: keep this browser POST attached. Detaching here
       caused Apache/LiteSpeed to kill the resume before its next page. */
    header('Cache-Control: no-store');header('X-Accel-Buffering: no');@ini_set('zlib.output_compression','0');
    $resumeResult=null;
    try {
        $resumeResult=runBackendExtract($pk, 'manual_resume', false, $runPhaseResume, false, (string)($prep['queue_id'] ?? ''), -1, $detailModeResume);
    } catch (Throwable $e) {
        $failed = readProgress(EXTRACT_PROGRESS_FILE);
        if (!$failed) $failed = $pr;
        $failed['running'] = false; $failed['done'] = false; $failed['paused'] = true;
        $failed['resume_needed'] = true; $failed['stale'] = true; $failed['partial'] = true; $failed['resumable'] = true;
        $failed['error'] = 'ادامه ناموفق: ' . $e->getMessage();
        $failed['last_progress_ts'] = time();
        $failed['recent_log'] = array_slice(array_merge((array)($failed['recent_log'] ?? []),
            ['❌ ادامه ناموفق؛ checkpoint حفظ شد: ' . $e->getMessage()]), -40);
        writeProgress(EXTRACT_PROGRESS_FILE, $failed);
        $_rq=extractReadQueue();foreach($_rq['entries'] as &$_re){
            if((string)($_re['id']??'')!==(string)($prep['queue_id']??''))continue;
            $_re['status']='paused';$_re['resumable']=true;$_re['resume_needed']=1;
            $_re['error']='ادامه ناموفق: '.mb_substr($e->getMessage(),0,180);unset($_re['done_at']);break;
        }unset($_re);extractWriteQueue($_rq);
        $resumeResult=['ok'=>false,'error'=>$e->getMessage()];
    }
    echo json_encode(['ok'=>!empty($resumeResult['ok']),'started'=>true,'resuming'=>true,'browser_held'=>true,
        'profile_key'=>$pk,'phase'=>$phase,'start_page'=>(int)$meta['start_page'],'result'=>$resumeResult],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);
    exit;
}

if (isset($_GET['extract_recover_stuck']) || isset($_POST['extract_recover_stuck'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $nowRec = time();
    $fixedRows = [];
    $exQRec = extractReadQueue();
    $dirtyRec = false;
    foreach ((array)($exQRec['entries'] ?? []) as $iRec => $rRec) {
        if (!is_array($rRec)) continue;
        $qidRec = trim((string)($rRec['id'] ?? ''));
        $stRec  = (string)($rRec['status'] ?? '');
        if (!empty($rRec['stopped_by_user']) || (string)($rRec['paused_by'] ?? '') === 'user') continue;
        if (!empty($rRec['resuming']) && !extractLockHeldForQueue($qidRec)) {
            unset($exQRec['entries'][$iRec]['resuming'], $exQRec['entries'][$iRec]['resume_requested_at']);
            $dirtyRec = true;
            $fixedRows[] = ['id' => $qidRec, 'fix' => 'cleared_stale_resuming'];
        }
        if ($stRec === 'running' && $qidRec !== '' && !extractLockHeldForQueue($qidRec)) {
            $prodRec = max((int)($rRec['run_extracted'] ?? 0), (int)($rRec['products_count'] ?? 0), (int)($rRec['extracted'] ?? 0));
            if ($prodRec > 0) {
                $exQRec['entries'][$iRec]['status'] = 'paused';
                $exQRec['entries'][$iRec]['resumable'] = true;
                $exQRec['entries'][$iRec]['resume_needed'] = 1;
                $exQRec['entries'][$iRec]['updated_at'] = $nowRec;
                unset($exQRec['entries'][$iRec]['done_at'], $exQRec['entries'][$iRec]['resuming'], $exQRec['entries'][$iRec]['resume_requested_at']);
                $dirtyRec = true;
                $fixedRows[] = ['id' => $qidRec, 'fix' => 'paused_ownerless_running'];
            }
        }
    }
    if ($dirtyRec) extractWriteQueue($exQRec);
    $arRec = s4AutoResumeInterruptedExtractions('manual_recover', false);
    echo json_encode([
        'ok' => true,
        'memory_limit' => (string)@ini_get('memory_limit'),
        'fixed_rows' => $fixedRows,
        'auto_resume' => $arRec,
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

if(isset($_GET['poll_extract'])){
header('Content-Type: application/json; charset=UTF-8');
$_arPoll = s4AutoResumeInterruptedExtractions('poll_extract', true);
clearstatcache(true,EXTRACT_PROGRESS_FILE);
$p=readProgress(EXTRACT_PROGRESS_FILE);
$_pQueuedPending=false;
if(!empty($p['worker'])&&!empty($p['job_id'])){
    $_wqNow=s4WorkerLoadQueue();
    foreach((array)($_wqNow['entries']??[])as $_wj){
        if(!is_array($_wj)||(string)($_wj['id']??'')!==(string)$p['job_id'])continue;
        $_wst=(string)($_wj['status']??'');
        if(in_array($_wst,['pending','running'],true)&&!s4WorkerBackendExtractRowIsDeadOrphan($_wj)){
            $_pQueuedPending=$_wst==='pending';$p['running']=true;$p['done']=false;$p['stalled']=false;
            $p['worker_waiting']=$_pQueuedPending;$p['worker_job_status']=$_wst;$p['error']='';
            if($_pQueuedPending)$p['recent_log']=array_slice(array_merge((array)($p['recent_log']??[]),
                ['⏳ استخراج در صف worker است و به‌صورت خودکار ادامه می‌یابد']),-12);
        }
        break;
    }
}
/* v8.97: استخراج دستی هم نگهبان می‌خواهد.

   نگهبان فقط داخل کران بود، پس وقتی استخراجِ دستی وسط کار می‌مُرد
   (که روی این هاست عادی است) نه فایل پیشرفت بسته می‌شد نه ردیف صف —
   مرورگر تا ابد «در حال استخراج» نشان می‌داد و کاربر فکر می‌کرد
   نگهبانی در کار نیست. این اندپوینت همان چیزی است که مرورگر هر ۱.۵
   ثانیه صدا می‌زند، پس بهترین جا برای تشخیص است. */
if(!empty($p['running'])&&empty($p['done'])&&!$_pQueuedPending){
    /* v10.36 (۴۹الف): قفلِ استخراج هم شاهد است. بدونِ آن، اجرایی که وسطِ
       یک صفحهٔ کندِ سایتِ مبدأ منتظر مانده (fetch با مهلتِ ۲۰ ثانیه، چند
       بار پشتِ‌هم) می‌توانست بی‌حرکت به نظر برسد و رابط کاربری وسطِ کار
       «رها شد» اعلام کند. */
    $_pTs=tasksHeartbeat($p);
    $_pLkAt=extractLockBeatForQueue((string)($p['queue_id']??''));
    if($_pLkAt>$_pTs)$_pTs=$_pLkAt;
    if(function_exists('s4WorkerExtractBeatForRow')){
        $_pW=s4WorkerExtractBeatForRow((string)($p['queue_id']??''),(string)($p['profile_key']??''));
        $_pWAt=(int)($_pW['beat']??0);
        if($_pWAt>$_pTs)$_pTs=$_pWAt;
        if($_pWAt>0)$p['worker_alive']=true;
    }
    $_pIdle=$_pTs>0?(time()-$_pTs):PHP_INT_MAX;
    $_pMax=max(90,(int)(loadConnections()['stall_after']??180));
    if($_pIdle>$_pMax){
        $_stalePhase=((string)($p['phase']??$p['resume_phase']??'list'))==='detail'?'detail':'list';
        $_hasProds=((int)($p['extracted']??0))>0;
        $_rp = max(1, (int)($p['page'] ?? $p['resume_page'] ?? 1));
        if ($_rp > 1) $_rp = max(1, $_rp - 1);
        $p['running']=false;$p['done']=false;$p['paused']=true;
        $p['resume_needed']=true;$p['stalled']=true;$p['resumable']=true;
        $p['retryable']=!$_hasProds;$p['retry_reason']=$_hasProds?'':'worker_stalled_before_products';
        $p['resume_phase']=$_stalePhase;
        if($_stalePhase==='list')$p['resume_page']=$_rp;
        $p['error']=$_hasProds
            ? ('استخراج '.$_pIdle.' ثانیه بی‌حرکت ماند — در حال ادامهٔ خودکار از checkpoint')
            : ('استخراج پیش از ثبت محصول بی‌حرکت ماند؛ ادامهٔ امن دوباره صف می‌شود');
        $p['recent_log']=array_slice(array_merge((array)($p['recent_log']??[]),
            $_hasProds
                ? ['♻️ توقف پردازش پس از '.$_pIdle.' ثانیه — کارِ انجام‌شده ذخیره شده و خودکار ادامه می‌یابد ('
                   .($_stalePhase==='detail'?'فاز ۲: جزئیات':('فاز ۱: از صفحه '.$_rp)).')']
                : ['♻️ استخراج پیش از دریافت محصول متوقف شد؛ checkpoint امن برای تلاش دوباره نگه داشته شد']),-40);
        writeProgress(EXTRACT_PROGRESS_FILE,$p);
        $_pkSave = (string)($p['profile_key'] ?? '');
        if ($_pkSave !== '' ) {
            try {
                $_ps = loadProfiles();
                if (isset($_ps[$_pkSave]) && is_array($_ps[$_pkSave])) {
                    $_ps[$_pkSave]['_extract_resume_phase']=$_stalePhase;
                    $_ps[$_pkSave]['_extract_list_incomplete'] = $_stalePhase==='list';
                    if($_stalePhase==='list'){
                        $_ps[$_pkSave]['_extract_list_page_try'] = (int)($p['page'] ?? $_rp + 1);
                        $_ps[$_pkSave]['_extract_list_page_ok'] = max(0, $_rp);
                        $_ps[$_pkSave]['_extract_resume_from'] = $_rp;
                    }
                    $_ps[$_pkSave]['_extract_stage'] = 'stopped';
                    $_ps[$_pkSave]['_extract_stage_at'] = time();
                    saveOneProfileAtomic($_pkSave,$_ps[$_pkSave]);
                }
            } catch (Throwable $e) {}
        }
        $_q=extractReadQueue();$_qd=false;
        foreach($_q['entries'] as &$_qe){
            if(($_qe['status']??'')!=='running'||!empty($_qe['stopped_by_user'])||(string)($_qe['paused_by']??'')==='user')continue;
            if(((string)($p['queue_id']??''))!==''&&((string)($_qe['id']??''))!==((string)$p['queue_id']))continue;
            $_qe['status']='paused';
            $_qe['error']=$_hasProds
                ? 'بی‌حرکت ماند ('.$_pIdle.'ث) — ادامهٔ خودکار در همین ردیف'
                : 'بی‌حرکت ماند پیش از ثبت محصول — ادامهٔ امن دوباره صف می‌شود';
            $_qe['resumable']=true;$_qe['resume_needed']=1;$_qe['resume_phase']=$_stalePhase;
            $_qe['retryable']=!$_hasProds;
            $_qe['retry_reason']=$_hasProds?'':'worker_stalled_before_products';
            if($_stalePhase==='list')$_qe['resume_page']=$_rp;
            unset($_qe['done_at'],$_qe['auto_resume_blocked'],$_qe['auto_resume_blocked_at']);
            $_qd=true;
        }
        unset($_qe);
        if($_qd)extractWriteQueue($_q);
        elseif(!$_hasProds&&$_pkSave!=='')
            s4QueueRetryableExtraction($_pkSave,$_stalePhase,(int)($p['max_pages']??-1),(string)($p['detail_mode']??''));
        $_arPoll = s4AutoResumeInterruptedExtractions('poll_stall', false);
        clearstatcache(true,EXTRACT_PROGRESS_FILE);
        $p=readProgress(EXTRACT_PROGRESS_FILE);
    }
}
if((!empty($p['done']) || !empty($p['ran_out']) || !empty($p['resume_needed']) || !empty($p['paused']))
    && (!empty($p['resume_needed']) || !empty($p['ran_out']) || !empty($p['paused']))
    && empty($p['cancelled']) && empty($p['stopped_by_user'])){
    $_pContinuing = false;
    if(function_exists('s4WorkerExtractBeatForRow')){
        $_pW=s4WorkerExtractBeatForRow((string)($p['queue_id']??''),(string)($p['profile_key']??''));
        if((int)($_pW['beat']??0)>0){ $_pContinuing = true; $p['worker_alive']=true; }
    }
    if(!$_pContinuing){
        $_pPk=(string)($p['profile_key']??''); $_pQid=(string)($p['queue_id']??'');
        foreach((array)(s4WorkerLoadQueue()['entries']??[])as $_wjC){
            if(!is_array($_wjC)||(string)($_wjC['type']??'')!=='backend_extract')continue;
            if(!in_array((string)($_wjC['status']??''),['pending','running'],true)||s4WorkerBackendExtractRowIsDeadOrphan($_wjC))continue;
            if($_pPk!==''&&(string)($_wjC['payload']['profile_key']??'')===$_pPk){ $_pContinuing = true; break; }
            if($_pQid!==''&&(string)($_wjC['payload']['extract_queue_id']??'')===$_pQid){ $_pContinuing = true; break; }
        }
        if(!$_pContinuing && !empty($_arPoll['resumed'])){
            foreach((array)$_arPoll['resumed'] as $_arItem){
                if($_pPk!==''&&(string)($_arItem['key']??'')===$_pPk){ $_pContinuing = true; break; }
            }
        }
    }
    if($_pContinuing){
        $p['running']=true;$p['done']=false;$p['worker_continuing']=true;$p['auto_resuming']=true;
        $p['recent_log']=array_slice(array_merge((array)($p['recent_log']??[]),
            ['♻️ ادامهٔ خودکار از checkpoint در حال اجراست…']),-40);
    }elseif(!empty($_arPoll['browser_resume'])&&is_array($_arPoll['browser_resume'])){
        $p['running']=true;$p['done']=false;$p['auto_resuming']=true;
        $p['auto_resume_browser']=$_arPoll['browser_resume'];
    }
}
$p['avg_ppm'] = extractAvgPpmValue($p);
echo json_encode($p,JSON_UNESCAPED_UNICODE);exit;
}

/**
 * v8.27: هستهٔ مشترک استخراج بک‌اند.
 * هم دکمهٔ دستی و هم کران‌جاب دقیقاً همین تابع را صدا می‌زنند تا رفتار
 * یکسان باشد و صف/پیشرفت/گزارش در هر دو حالت ثبت شود. تنها تفاوت،
 * برچسب trigger است که در ردیف صف ذخیره می‌شود.
 */
/**
 * v8.94: محصولات را همین حالا روی دیسک بنویس، بدون اینکه منتظر پایان کار بمانیم.
 *
 * تا ۸.۹۳ ذخیره فقط یک بار و در انتهای همه‌چیز انجام می‌شد. یعنی اگر
 * پردازه وسط فاز جزئیات می‌مُرد — که روی هاستی که پردازه‌ها را می‌کشد
 * دقیقاً همان‌جا اتفاق می‌افتد، چون طولانی‌ترین بخش است — تمام کار
 * انجام‌شده دور ریخته می‌شد. محصولات از فاز فهرست هم ذخیره نمی‌شدند،
 * چه رسد به گالری‌هایی که تا آن لحظه جمع شده بود.
 *
 * حالا هر چند محصول یک بار «نقطهٔ امن» ثبت می‌شود. اگر کار نیمه‌کاره
 * بماند، دفعهٔ بعد از همان‌جا ادامه پیدا می‌کند نه از صفر.
 *
 * همان قاعدهٔ ۸.۹۱ رعایت می‌شود: پروفایل دوباره از دیسک خوانده می‌شود و
 * فقط محصولات روی آن نوشته می‌شوند، تا تنظیماتی که کاربر حین اجرا عوض
 * کرده — و پروفایل‌های دیگر — به عقب برنگردند.
 */
function extractInstallDetailFatalGuard(): void {
    if(!empty($GLOBALS['_extractDetailFatalGuardInstalled']))return;
    $GLOBALS['_extractDetailFatalGuardInstalled']=true;
    register_shutdown_function(function(){
        $ctx=is_array($GLOBALS['_extractDetailFatalCtx']??null)?$GLOBALS['_extractDetailFatalCtx']:[];
        if(empty($ctx['active']))return;
        $e=error_get_last();
        if(!$e||!in_array((int)($e['type']??0),[E_ERROR,E_PARSE,E_CORE_ERROR,E_COMPILE_ERROR,E_USER_ERROR],true))return;
        $pk=(string)($ctx['profile_key']??'');$qid=(string)($ctx['queue_id']??'');$now=time();
        try{
            /* v10.470: اول فایل‌های سبک صف و پیشرفت را ذخیره کن تا حتی هنگام خطای کمبود حافظه (OOM)، ردیف روی running گیر نکند */
            $q=extractReadQueue();
            foreach($q['entries'] as &$qe){if((string)($qe['id']??'')!==$qid)continue;
                $qe['status']='paused';$qe['resumable']=true;$qe['resume_needed']=1;$qe['resume_phase']='detail';
                $qe['updated_at']=$now;$qe['error']='detail_fatal: '.mb_substr((string)($e['message']??''),0,180);
                unset($qe['done_at'],$qe['resuming'],$qe['resume_requested_at']);break;
            }unset($qe);extractWriteQueue($q);
            $pg=readProgress(EXTRACT_PROGRESS_FILE);
            if($qid===''||(string)($pg['queue_id']??'')===$qid){
                $pg['running']=false;$pg['done']=false;$pg['paused']=true;$pg['resume_needed']=true;
                $pg['phase']='detail';$pg['resume_phase']='detail';$pg['extract_stage']='detail';
                $pg['last_progress_ts']=$now;$pg['recent_log']=array_slice(array_merge((array)($pg['recent_log']??[]),
                    ['♻️ پردازهٔ جزئیات قطع شد؛ کران از آخرین checkpoint ادامه می‌دهد']),-12);
                writeProgress(EXTRACT_PROGRESS_FILE,$pg);
            }
        }catch(Throwable $_fatalGuardQ){}
        try{
            $ps=loadProfiles();
            if($pk!==''&&is_array($ps[$pk]??null)){
                $ps[$pk]['_extract_stage']='detail';$ps[$pk]['_extract_stage_at']=$now;
                $ps[$pk]['_extract_resume_phase']='detail';$ps[$pk]['_extract_resume_needed']=1;
                if(!empty($ctx['detail_cycle']))$ps[$pk]['_extract_detail_cycle']=(string)$ctx['detail_cycle'];
                saveProfiles($ps,true);
            }
            unset($ps);
        }catch(Throwable $_fatalGuard){}
    });
}

/**
 * v10.475: تحلیل شمارشی محصولات معتبر/کاندید و محافظ سراسری جلوگیری از کاهش محصولات پروفایل
 * هنگام خطا، توقف زودهنگام صفحه‌بندی، یا گیرکردن فاز جزئیات.
 */
function extractAnalyzeProductSet(array $productsMapOrPairs, bool $detailSuppliesPrice = false): array {
    $total = 0;
    $valid = 0;
    $inStockValid = 0;
    $detailCand = 0;
    foreach ($productsMapOrPairs as $k => $entry) {
        $p = null;
        if (is_array($entry) && array_key_exists(0, $entry) && array_key_exists(1, $entry) && is_string($entry[0]) && is_array($entry[1])) {
            $p = $entry[1];
        } elseif (is_array($entry)) {
            $p = $entry;
        }
        if (!is_array($p)) continue;
        $total++;
        $hasTitle = trim(strip_tags((string)($p['title'] ?? ''))) !== '';
        $hasLink  = trim((string)($p['link'] ?? '')) !== '';
        $isValid  = $hasTitle && extractPriceNum($p['price'] ?? '') > 0;
        $isInStock = !array_key_exists('in_stock', $p) || !empty($p['in_stock']);
        if ($isValid) {
            $valid++;
            if ($isInStock) $inStockValid++;
        }
        if ($hasTitle && ($hasLink || $isValid) && $isInStock) {
            $detailCand++;
        }
    }
    return [
        'total'            => $total,
        'valid'            => $valid,
        'in_stock_valid'   => $inStockValid,
        'detail_candidate' => $detailSuppliesPrice ? $detailCand : $valid,
    ];
}

function extractCountValidProducts(array $productsMapOrPairs): int {
    $an = extractAnalyzeProductSet($productsMapOrPairs, false);
    return (int)$an['valid'];
}

function extractShouldBlockShrinkage(int $prevCount, int $newCount, array $ctx = []): array {
    $res = [
        'blocked'  => false,
        'reason'   => '',
        'prev'     => max(0, $prevCount),
        'new'      => max(0, $newCount),
        'lost'     => max(0, $prevCount - $newCount),
        'loss_pct' => $prevCount > 0 ? round(max(0, $prevCount - $newCount) * 100 / $prevCount, 1) : 0.0,
    ];
    if (!empty($ctx['allow_shrink']) || $prevCount <= 0 || $newCount >= $prevCount) {
        return $res;
    }
    $lost = $prevCount - $newCount;
    if ($newCount <= 0) {
        $res['blocked'] = true;
        $res['reason']  = 'empty_new_set';
        return $res;
    }
    if (!empty($ctx['incomplete']) || !empty($ctx['stopped_before_api_total'])) {
        $res['blocked'] = true;
        $res['reason']  = !empty($ctx['stopped_before_api_total']) ? 'stopped_before_api_total' : 'incomplete_run';
        return $res;
    }
    if (!empty($ctx['autosave'])) {
        $autoMinLoss = ($prevCount >= 50) ? min(15, (int)ceil($prevCount * 0.10)) : max(3, (int)ceil($prevCount * 0.15));
        if ($lost >= $autoMinLoss) {
            $res['blocked'] = true;
            $res['reason']  = 'autosave_shrinkage';
            return $res;
        }
    }
    if (!empty($ctx['had_errors']) || !empty($ctx['stopped_early'])) {
        $errMinLoss = ($prevCount >= 100) ? min(25, max(5, (int)ceil($prevCount * 0.05))) : max(4, (int)ceil($prevCount * 0.08));
        if ($lost >= $errMinLoss) {
            $res['blocked'] = true;
            $res['reason']  = !empty($ctx['stopped_early']) ? 'early_stop_shrinkage' : 'error_run_shrinkage';
            return $res;
        }
    }
    if ($prevCount >= 8) {
        $collapseMinLoss = ($prevCount >= 200) ? min(80, (int)ceil($prevCount * 0.18)) : max(6, (int)ceil($prevCount * 0.18));
        if ($lost >= $collapseMinLoss) {
            $res['blocked'] = true;
            $res['reason']  = 'catalog_collapse';
            return $res;
        }
    } elseif ($prevCount >= 4 && $lost >= (int)ceil($prevCount * 0.50)) {
        $res['blocked'] = true;
        $res['reason']  = 'small_catalog_collapse';
        return $res;
    }
    return $res;
}

function detailPageHasExplicitOosSignal(?DOMXPath $xp, string $html = ''): bool {
    if ($html !== '') {
        if (stripos($html, 'property="product:availability" content="in stock"') !== false
            || stripos($html, "property='product:availability' content='in stock'") !== false) {
            return false;
        }
        if (stripos($html, 'property="product:availability" content="out of stock"') !== false
            || stripos($html, "property='product:availability' content='out of stock'") !== false) {
            return true;
        }
        if (preg_match('~"availability"\s*:\s*"https?://schema\.org/(OutOfStock|SoldOut|Discontinued)"~i', $html)
            && !preg_match('~"availability"\s*:\s*"https?://schema\.org/InStock"~i', $html)) {
            return true;
        }
    }
    if ($xp instanceof DOMXPath) {
        $inStockNodes = @$xp->query("//*[contains(concat(' ',normalize-space(@class),' '),' in-stock ')]");
        if ($inStockNodes && $inStockNodes->length > 0) return false;
        $oosClassNodes = @$xp->query("//*[contains(concat(' ',normalize-space(@class),' '),' out-of-stock ') or contains(concat(' ',normalize-space(@class),' '),' outofstock ') or contains(concat(' ',normalize-space(@class),' '),' sold-out ') or contains(concat(' ',normalize-space(@class),' '),' unavailable ')]");
        if ($oosClassNodes && $oosClassNodes->length > 0) return true;
        $stockNodes = @$xp->query("//*[contains(@class,'stock') or contains(@class,'availability') or contains(@class,'status') or contains(@class,'price')]");
        if ($stockNodes && $stockNodes->length > 0) {
            $checked = 0;
            foreach ($stockNodes as $sn) {
                if (++$checked > 12) break;
                $txt = normalize_text((string)($sn->textContent ?? ''));
                if ($txt === '' || mb_strlen($txt, 'UTF-8') > 120) continue;
                if (preg_match('/(ناموجود|اتمام\s*موجودی|توقف\s*تولید|موجود\s*نیست|تماس\s*بگیرید)/u', $txt)) {
                    return true;
                }
            }
        }
    }
    return false;
}

function extractWriteStagingRawFile(string $pkFinal, array $stagedProducts, string $stageCycle = ''): void {
    if ($pkFinal === '') return;
    $file = extractStagingFile($pkFinal);
    $tmp  = $file . '.tmp.' . (int)@getmypid();
    $json = json_encode([
        'profile_key' => $pkFinal,
        'saved_at'    => time(),
        'stage_cycle' => $stageCycle,
        'products'    => $stagedProducts,
    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE);
    if (is_string($json) && $json !== '') {
        if (@file_put_contents($tmp, $json, LOCK_EX) !== false) {
            @rename($tmp, $file);
        } else {
            @unlink($tmp);
        }
    }
    unset($json);
}

function extractCheckpoint(string $pkFinal, array $allProducts, array $extra = []): void {
    if ($pkFinal === '') return;
    $productsData = [];
    foreach ($allProducts as $k => $p) $productsData[] = [$k, $p];
    $lfp = @fopen(PROFILES_FILE . '.extract.lock', 'c');
    if ($lfp) @flock($lfp, LOCK_EX);
    try {
    $profilesNow = loadProfiles();
    if (!isset($profilesNow[$pkFinal]) || !is_array($profilesNow[$pkFinal])) return;
    $one=$profilesNow[$pkFinal];
    $diskValid = extractCountValidProducts((array)($one['products'] ?? []));
    $newValid  = extractCountValidProducts($allProducts);
    $cpStage   = (string)($extra['_extract_stage'] ?? '');
    $cpGuard   = extractShouldBlockShrinkage($diskValid, $newValid, [
        'checkpoint' => true,
        'incomplete' => in_array($cpStage, ['list', 'detail'], true) || !empty($extra['_extract_resume_needed']),
        'stage'      => $cpStage !== '' ? $cpStage : 'checkpoint',
    ]);
    if (!empty($cpGuard['blocked'])) {
        /* v10.475: محصولات معتبر قبلی روی دیسک هرگز با مجموعهٔ کوچکتر/بی‌قیمت بازنویسی نشود؛
           بافر کاری در فایل staging ذخیره می‌شود تا ادامهٔ فاز ۲ بدون از دست رفتن هیچ محصولی انجام شود. */
        $cyc = (string)($extra['_extract_detail_cycle'] ?? ($one['_extract_detail_cycle'] ?? ''));
        extractWriteStagingRawFile($pkFinal, $allProducts, $cyc);
        foreach ($extra as $k => $v) {
            if ($k === 'products' || $k === 'productsOrder' || $k === 'updatedAt') continue;
            $one[$k] = $v;
        }
    } else {
        $one['products']=$productsData;$one['productsOrder']=array_keys($allProducts);$one['updatedAt']=time();
        foreach($extra as $k=>$v)$one[$k]=$v;
    }
    unset($productsData);
    $profilesNow[$pkFinal]=$one;
    unset($one);
    saveProfiles($profilesNow,true);
    unset($profilesNow);
    } finally {
        if ($lfp) { @flock($lfp, LOCK_UN); @fclose($lfp); }
    }
    if (function_exists('gc_collect_cycles')) @gc_collect_cycles();
}

/**
 * v10.471: حافظهٔ مرحله‌ای (Staging) برای استخراج لیست صفحات.
 * تا زمانی که استخراج به انتهای آخرین صفحه نرسیده است، محصولات نیمه‌کاره هرگز در
 * $profile['products'] و تب نتایج قرار نمی‌گیرند و نتایج قبلی دست‌نخورده می‌ماند.
 */
function extractStagingFile(string $pkFinal): string {
    return __DIR__ . '/extract_staging_' . md5($pkFinal) . '.json';
}

function extractSaveListStaging(string $pkFinal, ?array $stagedProducts, array $metaExtra = [], string $stageCycle = ''): void {
    if ($pkFinal === '') return;
    if (is_array($stagedProducts)) {
        extractWriteStagingRawFile($pkFinal, $stagedProducts, $stageCycle);
    }
    if (!empty($metaExtra)) {
        $lfp = @fopen(PROFILES_FILE . '.extract.lock', 'c');
        if ($lfp) @flock($lfp, LOCK_EX);
        try {
            $profilesNow = loadProfiles();
            if (!isset($profilesNow[$pkFinal]) || !is_array($profilesNow[$pkFinal])) return;
            $one = $profilesNow[$pkFinal];
            foreach ($metaExtra as $mk => $mv) {
                if ($mk === 'products' || $mk === 'productsOrder' || $mk === 'updatedAt') continue;
                $one[$mk] = $mv;
            }
            $profilesNow[$pkFinal] = $one;
            unset($one);
            saveProfiles($profilesNow, true);
            unset($profilesNow);
        } finally {
            if ($lfp) { @flock($lfp, LOCK_UN); @fclose($lfp); }
        }
    }
    if (function_exists('gc_collect_cycles')) @gc_collect_cycles();
}

function extractLoadListStagingPayload(string $pkFinal): array {
    if ($pkFinal === '') return ['products' => [], 'stage_cycle' => '', 'saved_at' => 0];
    $file = extractStagingFile($pkFinal);
    if (!is_file($file)) return ['products' => [], 'stage_cycle' => '', 'saved_at' => 0];
    $raw = @file_get_contents($file);
    if (!is_string($raw) || $raw === '') return ['products' => [], 'stage_cycle' => '', 'saved_at' => 0];
    $j = @json_decode($raw, true);
    unset($raw);
    if (!is_array($j) || !is_array($j['products'] ?? null)) return ['products' => [], 'stage_cycle' => '', 'saved_at' => 0];
    $out = [];
    foreach ($j['products'] as $k => $p) {
        if (is_string($k) && $k !== '' && is_array($p)) $out[$k] = $p;
    }
    return [
        'products'    => $out,
        'stage_cycle' => (string)($j['stage_cycle'] ?? ''),
        'saved_at'    => (int)($j['saved_at'] ?? 0),
    ];
}

function extractLoadListStaging(string $pkFinal): array {
    $pl = extractLoadListStagingPayload($pkFinal);
    return (array)($pl['products'] ?? []);
}

function extractClearListStaging(string $pkFinal): void {
    if ($pkFinal === '') return;
    $file = extractStagingFile($pkFinal);
    if (is_file($file)) @unlink($file);
}

/** v10.294: فقط استخراج واقعاً نیمه‌کاره باید از checkpoint صفحه ادامه یابد.
 * list_done یعنی فهرست قبلی کامل شده؛ page_try آن نباید اجرای دوره‌ای تازه را
 * از صفحات پایانی آغاز کند یا محصولات قبلی را seen فرض کند. */
function extractListShouldResume(array $profile, string $trigger): bool {
    if (!empty($profile['_extract_list_incomplete']) || !empty($profile['_extract_resume_req'])) return true;
    if ((string)($profile['_extract_stage'] ?? '') === 'list') return true;
    return in_array($trigger, ['manual_resume','watchdog_resume','auto_resume'], true);
}

/** v10.122: صفحهٔ شروعِ ادامه — یک صفحه قبل از جایی که گیر کرده */
function extractResumeStartPage(array $profile): int {
    $try = (int)($profile['_extract_list_page_try'] ?? 0);
    $ok  = (int)($profile['_extract_list_page_ok'] ?? 0);
    $base = $try > 0 ? $try : ($ok > 0 ? $ok + 1 : 0);
    if ($base <= 1) return 1;
    return max(1, $base - 1); // یک صفحه قبل از گیر
}

function extractListResumeMeta(array $profile): array {
    return [
        'start_page' => extractResumeStartPage($profile),
        'page_ok'    => (int)($profile['_extract_list_page_ok'] ?? 0),
        'page_try'   => (int)($profile['_extract_list_page_try'] ?? 0),
        'next_url'   => (string)($profile['_extract_list_next_url'] ?? ''),
        'last_url'   => (string)($profile['_extract_list_last_url'] ?? ''),
        'incomplete' => !empty($profile['_extract_list_incomplete']),
        'max_pages'  => (int)($profile['pages'] ?? 0),
    ];
}

/** Stable dispatch slots. Slot one keeps the legacy path for safe upgrades. */
function extractLockSlotFiles(?int $limit = null): array {
    $limit=$limit??extractTaskConcurrency();$out=[];
    for($i=1;$i<=max(1,$limit);$i++)$out[]=$i===1?EXTRACT_LOCK_FILE:(EXTRACT_LOCK_FILE.'.slot'.$i);
    return $out;
}
/** Probe configured slots plus older on-disk slots without expanding capacity. */
function extractLockKnownSlotFiles(): array {
    $slots=[];foreach(extractLockSlotFiles()as$i=>$file)$slots[$i+1]=$file;
    foreach((array)@glob(EXTRACT_LOCK_FILE.'.slot*')as$file){
        if(!is_string($file)||!preg_match('~\\.slot([0-9]+)$~',$file,$m))continue;
        $slot=(int)$m[1];if($slot>=2)$slots[$slot]=$file;
    }
    ksort($slots,SORT_NUMERIC);return array_values($slots);
}
function extractLockBeatForQueue(string $queueId): int {
    if($queueId==='')return 0;
    foreach(extractLockKnownSlotFiles()as$file){$m=@json_decode((string)@file_get_contents($file),true);
        if(is_array($m)&&(string)($m['queue_id']??'')===$queueId)return(int)($m['at']??0);}
    return 0;
}
/** Is a worker lock held by this queue row, not merely by any extractor? */
function extractLockHeldForQueue(string $queueId): bool {
    if($queueId==='')return extractLockIsHeld();
    foreach(extractLockKnownSlotFiles()as$file){
        $fp=@fopen($file,'c');if(!$fp)return true;
        $held=!@flock($fp,LOCK_EX|LOCK_NB);
        if(!$held){@flock($fp,LOCK_UN);@fclose($fp);continue;}
        $meta=@json_decode((string)@file_get_contents($file),true);@fclose($fp);
        /* An empty owner is the tiny slot-acquisition window; defer rather
           than risk recovering a row just as a child is claiming it. */
        if(!is_array($meta)||trim((string)($meta['queue_id']??''))==='')return true;
        if((string)($meta['queue_id']??'')===$queueId)return true;
    }
    return false;
}
/** فقط flock می‌گوید دست‌کم یک extraction واقعاً در حال اجراست. */
function extractLockIsHeld(): bool {
    foreach(extractLockKnownSlotFiles() as $file){
        $fp=@fopen($file,'c');if(!$fp)return true;
        $held=!@flock($fp,LOCK_EX|LOCK_NB);if(!$held)@flock($fp,LOCK_UN);@fclose($fp);
        if($held)return true;
    }
    return false;
}
function extractLockHeldCount():int{
    $count=0;foreach(extractLockKnownSlotFiles()as$file){$fp=@fopen($file,'c');if(!$fp){$count++;continue;}
        $held=!@flock($fp,LOCK_EX|LOCK_NB);if($held)$count++;else @flock($fp,LOCK_UN);@fclose($fp);}
    return$count;
}
function extractQueueMarkRetryWaiting(string $queueId,string $reason,int $retryAt):bool{
    if($queueId==='')return false;$lf=@fopen(EXTRACT_QUEUE_FILE.'.lock','c');if(!$lf||!@flock($lf,LOCK_EX)){if($lf)@fclose($lf);return false;}
    $changed=false;try{$q=extractReadQueue();foreach($q['entries']as&$row){
        if(!is_array($row)||(string)($row['id']??'')!==$queueId||!empty($row['stopped_by_user']))continue;
        if((string)($row['status']??'')==='running')$row['status']='waiting';
        $row['resumable']=true;$row['resume_needed']=1;$row['retry_after']=$retryAt;$row['retry_reason']=$reason;
        $row['updated_at']=time();unset($row['done_at']);$changed=true;break;
    }unset($row);if($changed){$json=json_encode($q,JSON_UNESCAPED_UNICODE);$changed=$json!==false&&@file_put_contents(EXTRACT_QUEUE_FILE,$json,LOCK_EX)!==false;}}
    finally{@flock($lf,LOCK_UN);@fclose($lf);}return$changed;
}

/** One stop-signal file per extraction row; the legacy file remains an all-row signal. */
function extractStopSignalFileForQueue(string $queueId): string {
    return EXTRACT_STOP_FILE.'.q.'.substr(hash('sha256',$queueId),0,24).'.json';
}
function extractStopSignalSetForQueue(string $queueId): bool {
    $path=$queueId!==''?extractStopSignalFileForQueue($queueId):EXTRACT_STOP_FILE;
    $body=['stop'=>true,'time'=>time(),'queue_id'=>$queueId];
    return @file_put_contents($path,json_encode($body,JSON_UNESCAPED_UNICODE),LOCK_EX)!==false;
}
function extractStopSignalStateForQueue(string $queueId): array {
    $candidates=[];
    if($queueId!=='')$candidates[]=['file'=>extractStopSignalFileForQueue($queueId),'row_specific'=>true];
    $candidates[]=['file'=>EXTRACT_STOP_FILE,'row_specific'=>false];
    foreach($candidates as$c){
        $file=(string)$c['file'];if(!is_file($file))continue;
        $data=@json_decode((string)@file_get_contents($file),true);$data=is_array($data)?$data:[];
        $target=trim((string)($data['queue_id']??''));
        $at=(int)($data['time']??$data['at']??@filemtime($file));
        /* Keep row-targeted stops until that row is resumed/deleted; only an
           untargeted legacy stop-all signal has a short expiry. */
        if($at>0&&time()-$at>900&&empty($c['row_specific'])&&$target===''){@unlink($file);continue;}
        if($target!==''&&$target!==$queueId)continue;
        if($queueId===''&&$target!=='')continue;
        return ['found'=>true,'file'=>$file,'at'=>$at,'row_specific'=>!empty($c['row_specific']),
            'target'=>$target,'global_all'=>empty($c['row_specific'])&&$target===''];
    }
    return ['found'=>false];
}
function extractStopRequestedForQueue(string $queueId,bool $consumeSpecific=true): bool {
    $state=extractStopSignalStateForQueue($queueId);if(empty($state['found']))return false;
    if($queueId!==''&&!empty($state['global_all'])){
        /* Explicit Continue after a legacy stop-all signal overrides that
           older signal for this row only; other rows still observe it. */
        foreach((array)(extractReadQueue()['entries']??[])as$row){
            if(is_array($row)&&(string)($row['id']??'')===$queueId
                &&(int)($row['resume_requested_at']??0)>=(int)($state['at']??PHP_INT_MAX))return false;
        }
    }
    /* An untargeted legacy signal means stop all current extractors; each one
       must be allowed to observe it instead of the first worker consuming it. */
    $specific=!empty($state['row_specific'])||trim((string)($state['target']??''))!=='';
    if($consumeSpecific&&$specific)@unlink((string)$state['file']);
    return true;
}
function extractClearStopSignalForQueue(string $queueId): void {
    if($queueId==='')return;
    @unlink(extractStopSignalFileForQueue($queueId));
    $data=@json_decode((string)@file_get_contents(EXTRACT_STOP_FILE),true);
    if(is_array($data)&&(string)($data['queue_id']??'')===$queueId)@unlink(EXTRACT_STOP_FILE);
}
function extractLockActiveMetaForQueue(string $queueId): array {
    if($queueId==='')return [];
    foreach(extractLockKnownSlotFiles()as$file){
        $fp=@fopen($file,'c');if(!$fp)continue;
        $held=!@flock($fp,LOCK_EX|LOCK_NB);
        if(!$held){@flock($fp,LOCK_UN);@fclose($fp);continue;}
        $meta=@json_decode((string)@file_get_contents($file),true);@fclose($fp);
        if(is_array($meta)&&(string)($meta['queue_id']??'')===$queueId)return $meta;
    }
    return [];
}
function extractWorkerJobForQueueRow(array $row): array {
    $queueId=trim((string)($row['id']??''));$wanted=trim((string)($row['worker_job_id']??''));
    if(!function_exists('s4WorkerLoadQueue'))return [];
    foreach((array)(s4WorkerLoadQueue()['entries']??[])as$job){
        if(!is_array($job)||(string)($job['type']??'')!=='backend_extract')continue;
        $jobId=(string)($job['id']??'');$payload=is_array($job['payload']??null)?$job['payload']:[];
        $boundId=trim((string)($payload['extract_queue_id']??''));
        if(($wanted!==''&&$jobId===$wanted&&($queueId===''||$boundId===''||$boundId===$queueId))
            ||($queueId!==''&&$boundId===$queueId))return $job;
    }
    return [];
}
function extractQueueRowHasLiveOwner(array $row): bool {
    $queueId=trim((string)($row['id']??''));
    if($queueId!==''&&extractLockHeldForQueue($queueId))return true;
    $job=extractWorkerJobForQueueRow($row);$status=(string)($job['status']??'');
    if(in_array($status,['pending','running'],true))return true;
    /* A cancelled child can still be exiting before it acquired its slot.
       Terminal jobs and stale lock metadata are not process-liveness evidence. */
    if($status!=='cancelled')return false;
    $pid=(int)($job['worker_pid']??0);
    $daemonPid=function_exists('s4WorkerStateLoad')?(int)(s4WorkerStateLoad()['pid']??0):0;
    return $pid>0&&$pid!==$daemonPid&&$pid!==getmypid()
        &&function_exists('s4WorkerPidAlive')&&s4WorkerPidAlive($pid);
}
function extractQueueClearUserStopForResume(string $queueId): bool {
    if($queueId==='')return false;
    $lf=@fopen(EXTRACT_QUEUE_FILE.'.lock','c');if(!$lf)return false;
    if(!@flock($lf,LOCK_EX)){@fclose($lf);return false;}
    $ok=false;
    try{
        $q=extractReadQueue();$entries=is_array($q['entries']??null)?$q['entries']:[];
        foreach($entries as$i=>$row){
            if(!is_array($row)||(string)($row['id']??'')!==$queueId)continue;
            if(!in_array((string)($row['status']??''),['waiting','paused','failed'],true))return false;
            unset($row['stopped_by_user'],$row['paused_by'],$row['stop_requested'],$row['stop_requested_at']);
            $row['resume_requested_at']=time();$row['updated_at']=time();$row['error']='';unset($row['done_at']);
            $entries[$i]=$row;$q['entries']=array_values($entries);$json=json_encode($q,JSON_UNESCAPED_UNICODE);
            $ok=$json!==false&&@file_put_contents(EXTRACT_QUEUE_FILE,$json,LOCK_EX)!==false;break;
        }
    }finally{@flock($lf,LOCK_UN);@fclose($lf);}
    if($ok)extractClearStopSignalForQueue($queueId);
    return $ok;
}
function extractPersistStoppedCheckpoint(array $row): void {
    $profileKey=trim((string)($row['profile_key']??''));if($profileKey==='')return;
    try{
        $profiles=loadProfiles();$profile=is_array($profiles[$profileKey]??null)?$profiles[$profileKey]:null;
        if($profile===null)return;
        $phase=(string)($row['resume_phase']??$row['phase']??'list');$phase=$phase==='detail'?'detail':'list';
        $extra=['_extract_stage'=>'stopped','_extract_stage_at'=>time(),
            '_extract_resume_phase'=>$phase,'_extract_list_incomplete'=>$phase==='list'];
        if($phase==='list'){
            $resumePage=max(1,(int)($row['resume_page']??1));
            $extra['_extract_list_page_try']=$resumePage+1;
            $extra['_extract_list_page_ok']=$resumePage;
            $extra['_extract_resume_from']=$resumePage;
        }else{
            $extra['_extract_detail_done']=max(0,(int)($row['detail_done']??$row['current']??0));
            $extra['_extract_detail_total']=max(0,(int)($row['detail_total']??$row['total']??0));
        }
        extractCheckpoint($profileKey,extractPrevMap($profile),$extra);
    }catch(Throwable $_stopCheckpointError){}
}
function extractQueueFinalizeStopIfIdle(string $queueId): array {
    if($queueId==='')return ['ok'=>false,'error'=>'missing_queue_id'];
    $lf=@fopen(EXTRACT_QUEUE_FILE.'.lock','c');if(!$lf)return ['ok'=>false,'error'=>'queue_lock_unavailable'];
    if(!@flock($lf,LOCK_EX)){@fclose($lf);return ['ok'=>false,'error'=>'queue_lock_unavailable'];}
    $out=['ok'=>true,'finalized'=>false,'active'=>false];
    try{
        $q=extractReadQueue();$entries=is_array($q['entries']??null)?$q['entries']:[];$idx=-1;
        foreach($entries as$i=>$row)if(is_array($row)&&(string)($row['id']??'')===$queueId){$idx=$i;break;}
        if($idx<0)return $out;$row=$entries[$idx];
        if(empty($row['stopped_by_user'])||empty($row['stop_requested']))return $out;
        if(extractQueueRowHasLiveOwner($row)){$out['active']=true;return $out;}
        $now=time();$row['status']='paused';$row['resumable']=true;$row['resume_needed']=1;
        $row['paused_at']=$now;$row['done_at']=$now;$row['updated_at']=$now;
        $row['error']='با درخواست کاربر متوقف شد؛ checkpoint حفظ شد';
        unset($row['stop_requested'],$row['stop_requested_at']);
        $entries[$idx]=$row;$q['entries']=array_values($entries);$json=json_encode($q,JSON_UNESCAPED_UNICODE);
        if($json===false||@file_put_contents(EXTRACT_QUEUE_FILE,$json,LOCK_EX)===false){$out=['ok'=>false,'error'=>'queue_write_failed'];return $out;}
        $out['finalized']=true;$out['row']=$row;
    }finally{@flock($lf,LOCK_UN);@fclose($lf);}
    if(!empty($out['finalized'])&&is_array($out['row']??null)){
        extractClearStopSignalForQueue($queueId);
        extractPersistStoppedCheckpoint($out['row']);
    }
    return $out;
}
function extractQueueRequestStop(string $queueId=''): array {
    $lf=@fopen(EXTRACT_QUEUE_FILE.'.lock','c');if(!$lf)return ['ok'=>false,'error'=>'queue_lock_unavailable','rows'=>[]];
    if(!@flock($lf,LOCK_EX)){@fclose($lf);return ['ok'=>false,'error'=>'queue_lock_unavailable','rows'=>[]];}
    $out=['ok'=>true,'rows'=>[],'progress_owned'=>[]];
    try{
        $q=extractReadQueue();$entries=is_array($q['entries']??null)?$q['entries']:[];
        $progress=readProgress(EXTRACT_PROGRESS_FILE);$runningRows=0;
        foreach($entries as$entry)if(is_array($entry)&&(string)($entry['status']??'')==='running')$runningRows++;
        $now=time();$changed=false;
        foreach($entries as$i=>$row){
            if(!is_array($row))continue;$id=trim((string)($row['id']??''));
            if($queueId!==''&&$id!==$queueId)continue;
            $status=(string)($row['status']??'');
            if(!in_array($status,['running','waiting'],true)&&empty($row['stop_requested']))continue;
            $owned=queueProgressBelongsToRow($progress,$row,$runningRows);
            $phase=(string)($owned?($progress['phase']??$row['resume_phase']??$row['phase']??'list'):
                ($row['resume_phase']??$row['phase']??'list'));
            $phase=$phase==='detail'?'detail':'list';
            if($owned){
                foreach(['total','current','new','price_changed','removed','unchanged','products_count','detail_done','detail_total']as$key)
                    if(array_key_exists($key,$progress))$row[$key]=$progress[$key];
            }
            $row['stopped_by_user']=true;$row['stop_requested']=true;$row['stop_requested_at']=$now;
            $row['resumable']=true;$row['resume_needed']=1;$row['resume_phase']=$phase;$row['updated_at']=$now;
            $row['error']='درخواست توقف ثبت شد؛ در حال آزادشدن پردازش…';
            if($phase==='list'){
                $page=max(1,(int)($owned?($progress['page']??$progress['current']??$row['current']??1):($row['resume_page']??$row['current']??1)));
                $row['resume_page']=max(1,$page-1);
            }
            unset($row['done_at']);$entries[$i]=$row;$out['rows'][]=$row;$out['progress_owned'][$id]=$owned;$changed=true;
        }
        if($queueId!==''&&empty($out['rows'])){
            foreach((array)(function_exists('s4WorkerLoadQueue')?(s4WorkerLoadQueue()['entries']??[]):[])as$job){
                $payload=is_array($job['payload']??null)?$job['payload']:[];
                if(is_array($job)&&(string)($job['type']??'')==='backend_extract'
                    &&(string)($payload['extract_queue_id']??'')===$queueId){
                    $out['rows'][]=['id'=>$queueId,'worker_job_id'=>(string)($job['id']??''),
                        'profile_key'=>(string)($payload['profile_key']??''),'status'=>(string)($job['status']??'running')];break;
                }
            }
        }
        if($changed){$q['entries']=array_values($entries);$json=json_encode($q,JSON_UNESCAPED_UNICODE);
            if($json===false||@file_put_contents(EXTRACT_QUEUE_FILE,$json,LOCK_EX)===false){$out=['ok'=>false,'error'=>'queue_write_failed','rows'=>[]];}}
    }finally{@flock($lf,LOCK_UN);@fclose($lf);}
    return $out;
}
function extractCancelWorkerForQueueRow(array $row,string $reason='user'): array {
    $queueId=trim((string)($row['id']??''));$job=extractWorkerJobForQueueRow($row);
    $automatic=$reason!=='user';
    $jobId=(string)($job['id']??'');$jobStatus=(string)($job['status']??'');$pid=(int)($job['worker_pid']??0);$cancelled=false;
    if($jobId!==''&&function_exists('s4WorkerQueueMutate')){
        s4WorkerQueueMutate(function(&$q)use($jobId,$queueId,$reason,&$cancelled){$now=time();
            foreach($q['entries']as&$entry){
                if(!is_array($entry)||(string)($entry['id']??'')!==$jobId||(string)($entry['type']??'')!=='backend_extract')continue;
                $payload=is_array($entry['payload']??null)?$entry['payload']:[];
                $boundId=trim((string)($payload['extract_queue_id']??''));
                if($queueId!==''&&$boundId!==''&&$boundId!==$queueId)break;
                if(in_array((string)($entry['status']??''),['pending','running'],true)){
                    $entry['status']='cancelled';$entry['cancel_requested_at']=$now;$entry['updated_at']=$now;
                    $entry['done_at']=$now;$entry['error']=$reason==='user'?'stopped_by_user':'stalled_auto_recovery';$cancelled=true;
                }
                break;
            }unset($entry);return ['ok'=>true,'cancelled'=>$cancelled];
        });
    }
    $activeLockMeta=extractLockActiveMetaForQueue($queueId);
    if($pid<=0)$pid=(int)($activeLockMeta['pid']??0);
    $daemonPid=function_exists('s4WorkerStateLoad')?(int)(s4WorkerStateLoad()['pid']??0):0;
    $pidAlive=$pid>0&&function_exists('s4WorkerPidAlive')&&s4WorkerPidAlive($pid);$signalSent=false;
    $pidOwnsThisLock=!empty($activeLockMeta)&&$pid>0&&(int)($activeLockMeta['pid']??0)===$pid;
    /* User stop never kills the persistent daemon. Automatic stale recovery
       may retire it when that daemon itself owns the frozen extraction, but a
       cron executing inside that same PID defers to the next external pulse. */
    $maySignalOwner=$pid!==getmypid()&&($pid!==$daemonPid||$automatic);
    if($pidAlive&&$pidOwnsThisLock&&$maySignalOwner&&function_exists('posix_kill'))
        $signalSent=(bool)@posix_kill($pid,defined('SIGTERM')?SIGTERM:15);
    return ['job_id'=>$jobId,'job_status'=>$jobStatus,'cancelled_job'=>$cancelled,
        'pid'=>$pid,'pid_alive'=>$pidAlive,'signal_sent'=>$signalSent];
}
function extractQueueDeleteSafe(string $queueId): array {
    if($queueId==='')return ['ok'=>false,'error'=>'missing_queue_id'];
    $lf=@fopen(EXTRACT_QUEUE_FILE.'.lock','c');if(!$lf)return ['ok'=>false,'error'=>'queue_lock_unavailable'];
    if(!@flock($lf,LOCK_EX)){@fclose($lf);return ['ok'=>false,'error'=>'queue_lock_unavailable'];}
    $out=['ok'=>false,'removed'=>0];
    try{
        $q=extractReadQueue();$entries=is_array($q['entries']??null)?$q['entries']:[];$idx=-1;
        foreach($entries as$i=>$row)if(is_array($row)&&(string)($row['id']??'')===$queueId){$idx=$i;break;}
        if($idx<0)return ['ok'=>true,'removed'=>0,'not_found'=>true];
        $row=$entries[$idx];$status=(string)($row['status']??'');
        if(in_array($status,['running','waiting'],true)||!empty($row['stop_requested'])||extractQueueRowHasLiveOwner($row))
            return ['ok'=>false,'removed'=>0,'error'=>'row_active_stop_first',
                'message'=>'ردیف هنوز worker یا قفل فعال دارد؛ ابتدا توقف را کامل کنید.'];
        if(!in_array($status,['paused','failed','done','superseded'],true))
            return ['ok'=>false,'removed'=>0,'error'=>'row_not_stopped','message'=>'فقط ردیف متوقف یا تمام‌شده قابل حذف است.'];
        array_splice($entries,$idx,1);$q['entries']=array_values($entries);$json=json_encode($q,JSON_UNESCAPED_UNICODE);
        if($json===false||@file_put_contents(EXTRACT_QUEUE_FILE,$json,LOCK_EX)===false)
            return ['ok'=>false,'removed'=>0,'error'=>'queue_write_failed'];
        $out=['ok'=>true,'removed'=>1];
    }finally{@flock($lf,LOCK_UN);@fclose($lf);}
    return $out;
}
function extractStopActiveRows(string $profileKey=''): array {
    $results=[];
    foreach((array)(extractReadQueue()['entries']??[])as$row){
        if(!is_array($row)||($profileKey!==''&&(string)($row['profile_key']??'')!==$profileKey))continue;
        if(!in_array((string)($row['status']??''),['running','waiting'],true)&&empty($row['stop_requested']))continue;
        $id=trim((string)($row['id']??''));if($id==='')continue;
        $request=extractQueueRequestStop($id);if(empty($request['ok']))continue;
        extractStopSignalSetForQueue($id);$target=$request['rows'][0]??$row;
        $cancel=extractCancelWorkerForQueueRow($target);$final=extractQueueFinalizeStopIfIdle($id);
        $results[]=['queue_id'=>$id,'signal_sent'=>!empty($cancel['signal_sent']),
            'termination_pending'=>!empty($final['active']),'finalized'=>!empty($final['finalized'])];
    }
    return $results;
}
function extractStopManualSyncProfileWorkers(): array {
    $progress=readProgress(MANUAL_SYNC_PROGRESS_FILE);
    $checkpoint=is_array($progress['checkpoint']??null)?$progress['checkpoint']:[];
    $extract=is_array($checkpoint['extract']??null)?$checkpoint['extract']:[];
    $profileKey=trim((string)($progress['profile_key']??$checkpoint['profile_key']??''));
    $queueId=trim((string)($extract['queue_id']??$progress['extract_queue_id']??''));
    $rows=[];
    foreach((array)(extractReadQueue()['entries']??[])as$row){
        if(!is_array($row))continue;
        if($queueId!==''&&(string)($row['id']??'')!==$queueId)continue;
        if($queueId===''&&($profileKey===''||(string)($row['profile_key']??'')!==$profileKey))continue;
        if(!in_array((string)($row['status']??''),['running','waiting'],true)&&empty($row['stop_requested']))continue;
        $rows[]=$row;
    }
    if(!$rows&&$queueId!==''){
        $job=extractWorkerJobForQueueRow(['id'=>$queueId]);
        $orphan=['id'=>$queueId,'worker_job_id'=>(string)($job['id']??''),
            'profile_key'=>$profileKey,'status'=>'running'];
        if(extractQueueRowHasLiveOwner($orphan))$rows[]=$orphan;
    }
    $results=[];
    foreach($rows as$row){
        $id=trim((string)($row['id']??''));if($id==='')continue;
        $request=extractQueueRequestStop($id);if(empty($request['ok']))continue;
        extractStopSignalSetForQueue($id);
        $target=$request['rows'][0]??$row;$cancel=extractCancelWorkerForQueueRow($target);
        $final=extractQueueFinalizeStopIfIdle($id);
        $results[]=['queue_id'=>$id,'signal_sent'=>!empty($cancel['signal_sent']),
            'termination_pending'=>!empty($final['active']),'finalized'=>!empty($final['finalized'])];
    }
    return $results;
}

/** Persist product progress against its queue row, not merely the shared
 * compatibility progress file which another parallel extractor may replace. */
function extractQueueRecordRunProgress(string $queueId,int $extracted,int $at=0): bool {
    static $saved=[];
    if($queueId===''||$extracted<=0||$extracted<=(int)($saved[$queueId]??0))return false;
    $lf=@fopen(EXTRACT_QUEUE_FILE.'.lock','c');if(!$lf)return false;
    if(!@flock($lf,LOCK_EX|LOCK_NB)){@fclose($lf);return false;}
    $ok=false;
    try{
        $q=extractReadQueue();$entries=is_array($q['entries']??null)?$q['entries']:[];
        foreach($entries as$i=>$row){
            if(!is_array($row)||(string)($row['id']??'')!==$queueId)continue;
            $old=max((int)($row['run_extracted']??0),(int)($row['products_count']??0));
            if($extracted>$old){
                $row['run_extracted']=$extracted;$row['last_product_progress_at']=$at>0?$at:time();
                $row['updated_at']=max((int)($row['updated_at']??0),$row['last_product_progress_at']);
                $entries[$i]=$row;$q['entries']=array_values($entries);
                $json=json_encode($q,JSON_UNESCAPED_UNICODE);
                $ok=$json!==false&&@file_put_contents(EXTRACT_QUEUE_FILE,$json,LOCK_EX)!==false;
            }else $ok=true;
            break;
        }
    }finally{@flock($lf,LOCK_UN);@fclose($lf);}
    if($ok)$saved[$queueId]=$extracted;
    return $ok;
}

/** Positive product evidence must belong to this exact queue run. Historical
 * profile products intentionally do not count. */
function extractQueueRunProductCount(array $row,array $progress=[],int $runningRows=1): int {
    $count=max((int)($row['run_extracted']??0),(int)($row['products_count']??0),
        (int)($row['extracted']??0));
    if($progress&&queueProgressBelongsToRow($progress,$row,max(1,$runningRows)))
        $count=max($count,(int)($progress['extracted']??0));
    return max(0,$count);
}
function extractQueueRunHasProducts(array $row,array $progress=[],int $runningRows=1): bool {
    return extractQueueRunProductCount($row,$progress,$runningRows)>0;
}

/**
 * Atomically close one abandoned/stale extraction row without replacing its
 * ID or checkpoint. Zero-product stalls remain retryable with the normal
 * auto-resume backoff instead of becoming a permanent dead end.
 * When $ownerAbsent is true, definitive owner loss is enough and no age wait
 * is imposed. Otherwise the row must have at least $staleAfter seconds without
 * real progress. The live lock/PID is rechecked while mutating the row.
 */
function extractQueuePauseStaleRow(string $queueId, int $staleAfter, bool $ownerAbsent=false): ?array {
    if($queueId==='')return null;
    $lf=@fopen(EXTRACT_QUEUE_FILE.'.lock','c');if(!$lf)return null;
    if(!@flock($lf,LOCK_EX)){@fclose($lf);return null;}
    $result=null;
    try{
        $q=extractReadQueue();$entries=is_array($q['entries']??null)?$q['entries']:[];$idx=-1;
        foreach($entries as$i=>$row)if(is_array($row)&&(string)($row['id']??'')===$queueId){$idx=$i;break;}
        if($idx<0||($entries[$idx]['status']??'')!=='running')return null;
        $row=$entries[$idx];
        if(!empty($row['stopped_by_user'])||(string)($row['paused_by']??'')==='user')return null;
        if(extractLockHeldForQueue($queueId))return null;
        $jobId=(string)($row['worker_job_id']??'');
        if($jobId!=='')foreach((array)(s4WorkerLoadQueue()['entries']??[])as$job){
            if(!is_array($job)||(string)($job['id']??'')!==$jobId||(string)($job['status']??'')!=='running')continue;
            if(s4WorkerPidAlive((int)($job['worker_pid']??0)))return null;
        }
        $progress=readProgress(EXTRACT_PROGRESS_FILE);
        $runningRows=0;foreach($entries as$entry)if(is_array($entry)&&($entry['status']??'')==='running')$runningRows++;
        $progressOwned=queueProgressBelongsToRow($progress,$row,$runningRows);
        $now=time();
        $idleInfo=queueRowIdle('extract',$row,$progress,$now,
            ['lock'=>extractLockBeatForQueue($queueId)],$runningRows);
        $idle=(int)($idleInfo['idle']??0);
        /* v10.470: مهلتِ بوتِ ۴۰ ثانیه‌ای برای فرزندِ تازهٔ CLI پیش از اخذ قفل و دریافت صفحهٔ ۱ */
        $recentBoot=max((int)($row['started_at']??0),(int)($row['resume_requested_at']??0),(int)($row['updated_at']??0));
        if($ownerAbsent&&$idle<40&&$recentBoot>0&&($now-$recentBoot)<40)return null;
        if(!$ownerAbsent&&$idle<$staleAfter)return null;
        $progressForRow=$progressOwned?$progress:[];
        $phase=(string)($progressForRow['phase']??$row['resume_phase']??$row['phase']??'list');
        $phase=$phase==='detail'?'detail':'list';
        $productCount=extractQueueRunProductCount($row,$progress,$runningRows);
        $row['run_extracted']=max((int)($row['run_extracted']??0),$productCount);
        $row['updated_at']=$now;$row['paused_at']=$now;
        if($productCount>0){
            $row['status']='paused';$row['resumable']=true;$row['resume_needed']=1;
            $row['resume_phase']=$phase;$row['error']='بی‌حرکت ماند ('.$idle.'ث) — ادامه در همین ردیف';
            unset($row['done_at'],$row['auto_resume_blocked'],$row['auto_resume_blocked_at'],$row['resuming'],$row['resume_requested_at']);
        }else{
            $row['status']='paused';$row['resumable']=true;$row['resume_needed']=1;
            $row['retryable']=true;$row['retry_reason']='worker_stalled_before_products';
            $row['resume_phase']=$phase;
            if($phase==='list')$row['resume_page']=max(1,(int)($row['resume_page']??$row['current']??1));
            $row['error']='استخراج پیش از ثبت محصول متوقف شد؛ تلاش امن بعدی با backoff انجام می‌شود';
            unset($row['done_at'],$row['auto_resume_blocked'],$row['auto_resume_blocked_at'],$row['resuming'],$row['resume_requested_at']);
        }
        $entries[$idx]=$row;$q['entries']=array_values($entries);
        $json=json_encode($q,JSON_UNESCAPED_UNICODE);
        if($json===false||@file_put_contents(EXTRACT_QUEUE_FILE,$json,LOCK_EX)===false)return null;
        $result=['row'=>$row,'idle'=>$idle,'phase'=>$phase,'progress_owned'=>$progressOwned,
            'progress'=>$progressForRow,'products'=>$productCount,'resumable'=>true,
            'retryable_empty'=>$productCount<=0,'terminal_zero_products'=>false,'owner_absent'=>$ownerAbsent];
    }finally{@flock($lf,LOCK_UN);@fclose($lf);}
    return $result;
}

/** Profile whose manual sync was explicitly cancelled; auto-resume must not
 * turn that user's Stop into an implicit Continue. Manual actions reset this
 * progress record or explicitly resume the saved queue row. */
function extractManualStopProfileKey(): string {
    if(!defined('MANUAL_SYNC_PROGRESS_FILE'))return '';
    $progress=readProgress(MANUAL_SYNC_PROGRESS_FILE);
    clearstatcache(true,MANUAL_SYNC_STOP_FILE);
    $stopSignal=is_file(MANUAL_SYNC_STOP_FILE)
        &&(time()-(int)@filemtime(MANUAL_SYNC_STOP_FILE))<=900;
    $stopped=$stopSignal||!empty($progress['cancelled'])||!empty($progress['stopped'])
        ||!empty($progress['stopped_by_user'])||(string)($progress['paused_by']??'')==='user';
    if(!$stopped)return '';
    $checkpoint=is_array($progress['checkpoint']??null)?$progress['checkpoint']:[];
    return trim((string)($progress['profile_key']??$checkpoint['profile_key']??''));
}

/**
 * v10.123: آماده‌سازیِ «ادامهٔ خودکار» برای یک پروفایلِ رهاشده.
 *
 *  همان کاری که دکمهٔ «▶ ادامه» می‌کند، ولی سرورساید و در تیکِ کران:
 *  فازِ مناسب را برمی‌گرداند (detail اگر وسطِ جزئیات مانده، وگرنه all)،
 *  پرچمِ resume را روی پروفایل می‌نشاند؛ worker بعد از گرفتنِ همان lock،
 *  blockerهای صف را زیرِ مالکیتِ اتمیک می‌بندد تا محافظِ تکراری جلوی ادامه را نگیرد.
 *
 *  @return ['ok'=>bool, 'phase'=>string, 'reason'=>string]
 */
function extractResumeQueueId(string $profileKey, string $preferredQueueId = ''): string {
    $q=extractReadQueue();$entries=is_array($q['entries']??null)?$q['entries']:[];
    if($preferredQueueId!=='')foreach($entries as $e){
        if(!is_array($e)||(string)($e['id']??'')!==$preferredQueueId)continue;
        $_st=(string)($e['status']??'');
        if((string)($e['profile_key']??'')===$profileKey
            &&(in_array($_st,['waiting','paused','failed'],true)
               ||($_st==='running'&&!extractLockHeldForQueue($preferredQueueId))))return $preferredQueueId;
        return '';
    }
    for($i=count($entries)-1;$i>=0;$i--){$e=$entries[$i]??null;
        if(!is_array($e)||(string)($e['profile_key']??'')!==$profileKey)continue;
        $_st=(string)($e['status']??'');$_eid=(string)($e['id']??'');
        if(in_array($_st,['paused','failed'],true)
           ||($_st==='running'&&$_eid!==''&&!extractLockHeldForQueue($_eid)))return $_eid;
    }
    return '';
}

/** Use the saved checkpoint phase rather than inferring from a fresh-run default. */
function extractResumePhase(array $profile): string {
    $stage=(string)($profile['_extract_stage']??'');
    $savedPhase=(string)($profile['_extract_resume_phase']??'');
    if(!in_array($savedPhase,['list','detail'],true))$savedPhase='';
    if($stage==='stopped'&&$savedPhase!=='')return $savedPhase;
    if($stage==='detail'||($stage==='list_done'&&empty($profile['_extract_list_incomplete'])))return 'detail';
    if($stage==='list'||!empty($profile['_extract_list_incomplete'])
        ||(int)($profile['_extract_resume_from']??0)>0)return 'list';
    return 'all';
}
/** Preserve a retryable extraction checkpoint without touching saved products. */
function extractRememberRetryableCheckpoint(string $profileKey,string $phase,string $reason='extract_lock_busy'):bool{
    if($profileKey==='')return false;$phase=$phase==='detail'?'detail':'list';
    try{$profiles=loadProfiles();$profile=$profiles[$profileKey]??null;if(!is_array($profile))return false;
        $now=time();$stage=(string)($profile['_extract_stage']??'');
        if($phase==='list'){
            if(empty($profile['_extract_list_incomplete'])&&!in_array($stage,['list','stopped'],true)){
                $profile['_extract_resume_from']=1;$profile['_extract_list_page_try']=1;$profile['_extract_list_page_ok']=0;
            }elseif(empty($profile['_extract_resume_from']))$profile['_extract_resume_from']=extractResumeStartPage($profile);
            $profile['_extract_stage']='list';$profile['_extract_list_incomplete']=true;
        }else{$profile['_extract_stage']='detail';$profile['_extract_list_incomplete']=false;}
        $profile['_extract_stage_at']=$now;$profile['_extract_resume_phase']=$phase;
        $profile['_extract_resume_needed']=1;$profile['_extract_resume_req']=$now;
        $profile['_extract_retry_at']=$now;$profile['_extract_retry_reason']=$reason;
        return saveOneProfileAtomic($profileKey,$profile);
    }catch(Throwable $e){return false;}
}
function s4QueueRetryableExtraction(string $profileKey,string $phase,int $maxPages=-1,string $detailMode=''):array{
    extractRememberRetryableCheckpoint($profileKey,$phase,'extract_lock_busy');
    $enq=s4WorkerEnqueueBackendExtract($profileKey,$phase,false,true,$maxPages,'',true,$detailMode);
    if(!empty($enq['ok'])&&!s4WorkerIsActive())s4SpawnPersistentWorker();
    return$enq;
}

function extractResumePrepare(string $profileKey, array $cn, string $preferredQueueId = '', bool $allowUserStopped = false): array {
    $out = ['ok' => false, 'phase' => 'all', 'reason' => '', 'queue_id' => '', 'reused_row' => false];
    if ($profileKey === '') { $out['reason'] = 'no_key'; return $out; }
    $profiles = loadProfiles();
    $pr = is_array($profiles[$profileKey] ?? null) ? $profiles[$profileKey] : null;
    unset($profiles);
    if ($pr === null) { $out['reason'] = 'no_profile'; return $out; }
    /* v10.136: probe و mutation پشتِ یک reservation واقعی.
       صرفاً probe کردن و بعداً flock گرفتن، بین دو resume پنجرهٔ race می‌ساخت. */
    $resumeQueueId=extractResumeQueueId($profileKey,$preferredQueueId);
    if($preferredQueueId!==''&&$resumeQueueId===''){
        $out['reason']='resume_row_not_found_or_not_resumable';
        return $out;
    }
    if(!$allowUserStopped&&$resumeQueueId!==''&&extractQueueRowStoppedByUser($resumeQueueId)){
        $out['reason']='explicit_user_stop';
        return $out;
    }
    $reusedRow=$resumeQueueId!=='';
    if($resumeQueueId==='')$resumeQueueId='exresume_'.$profileKey.'_'.time().'_'.substr(bin2hex(random_bytes(3)),0,6);
    $lk = extractLockAcquire($resumeQueueId, $profileKey);
    if (empty($lk['ok'])) {
        $out['reason'] = 'lock_held';
        $out['busy_queue_id'] = (string)($lk['queue_id'] ?? '');
        return $out;
    }
    /* List checkpoints stay page-only; detail checkpoints keep their saved phase. */
    $phase = extractResumePhase($pr);
    $pr['_extract_resume_req'] = time();
    if ($phase === 'list' && empty($pr['_extract_resume_from'])) {
        $pr['_extract_resume_from'] = extractResumeStartPage($pr);
    }
    /* A detail checkpoint must not be rewritten as an incomplete list. */
    $pr['_extract_list_incomplete'] = $phase === 'list';
    $pr['_extract_resume_phase'] = $phase === 'detail' ? 'detail' : 'list';
    try {
        saveOneProfileAtomic($profileKey,$pr);
    } catch (Throwable $e) {
        extractLockRelease($resumeQueueId);
        $out['reason'] = 'profile_save';
        return $out;
    }
    if($allowUserStopped&&$reusedRow&&!extractQueueClearUserStopForResume($resumeQueueId)){
        extractLockRelease($resumeQueueId);
        $out['reason']='resume_row_update_failed';
        return $out;
    }
    if($allowUserStopped)extractClearStopSignalForQueue($resumeQueueId);
    /* runBackendExtract با همین handle ردیف stale را زیر مالکیت lock می‌بندد؛
       cleanup جداگانه بعد از probe لازم نیست و خودش race ایجاد می‌کرد. */
    $out['ok'] = true;
    $out['phase'] = $phase;
    $out['queue_id'] = $resumeQueueId;
    $out['reused_row'] = $reusedRow;
    return $out;
}

/**
 * v10.124: امضای پیشرفتِ استخراجِ یک پروفایل — برای تشخیصِ «پیشرفت» بین دو
 *  تلاشِ ادامه. اگر بین دو تیکِ کران این امضا عوض شده باشد یعنی ادامهٔ قبلی
 *  واقعاً جلو رفته (صفحه/جزئیات/محصول تازه‌ای ثبت شده) و سقفِ ضدِ حلقه نباید
 *  جلوی ادامهٔ بعدی را بگیرد. اگر عوض نشده باشد یعنی پروفایل واقعاً گیر کرده.
 */
function extractResumeSig(array $profile): string {
    $stage  = (string)($profile['_extract_stage'] ?? '');
    $pageOk = (int)($profile['_extract_list_page_ok'] ?? 0);
    $pageTr = (int)($profile['_extract_list_page_try'] ?? 0);
    $det    = (int)($profile['_extract_detail_done'] ?? 0);
    $n      = count((array)($profile['products'] ?? []));
    /* Segment-local detail_done commonly repeats (for example 27 products per
       cron pulse). Count durable cycle markers as the real cursor, otherwise a
       healthy detail crawl looks stuck and exponential backoff throttles it. */
    $cycle=(string)($profile['_extract_detail_cycle']??'');$cycleDone=0;$cycleAt=0;
    if($cycle!=='')foreach((array)($profile['products']??[])as $_ep){
        $_p=(is_array($_ep)&&isset($_ep[0],$_ep[1])&&is_array($_ep[1]))?$_ep[1]:$_ep;
        if(!is_array($_p)||(string)($_p['_detail_cycle']??'')!==$cycle)continue;
        $cycleDone++;$cycleAt=max($cycleAt,(int)($_p['_detail_checked_at']??0));
    }
    return $stage . '|' . $pageOk . '|' . $pageTr . '|' . $det . '|' . $n
        . '|' . $cycle . '|' . $cycleDone . '|' . $cycleAt;
}

/** Collect every eligible extraction checkpoint, with at most one owner per profile. */
function extractQueueRowStoppedByUser(string $queueId): bool {
    if($queueId==='')return false;
    foreach((array)(extractReadQueue()['entries']??[])as $e){
        if(is_array($e)&&(string)($e['id']??'')===$queueId)
            return !empty($e['stopped_by_user'])||(string)($e['paused_by']??'')==='user';
    }
    return false;
}

/** Update only resume metadata under the shared profile-write lock. */
function extractResumeMetaSaveAtomic(string $profileKey,array $meta): bool {
    if($profileKey==='')return false;
    $lock=@fopen(PROFILES_FILE.'.extract.lock','c');
    if(!$lock||!@flock($lock,LOCK_EX)){if($lock)@fclose($lock);return false;}
    $profiles=loadProfiles();
    if(!is_array($profiles[$profileKey]??null)){@flock($lock,LOCK_UN);@fclose($lock);return false;}
    $profiles[$profileKey]['_extract_resume_meta']=$meta;
    $ok=saveProfiles($profiles);
    @flock($lock,LOCK_UN);@fclose($lock);
    return $ok;
}

function cronExtractResumeCandidates(array $profiles,array $queueEntries,array $watchdogKeys=[]): array {
    $latestRows=[];$resumeBarriers=[];$busy=[];$profileCheckpointKeys=[];$watchdog=[];$seq=0;
    $progress=readProgress(EXTRACT_PROGRESS_FILE);$runningRows=0;
    foreach($queueEntries as$_countRow)if(is_array($_countRow)&&(string)($_countRow['status']??'')==='running')$runningRows++;
    foreach($queueEntries as $e){
        $seq++;if(!is_array($e))continue;
        $key=trim((string)($e['profile_key']??''));if($key==='')continue;
        $status=(string)($e['status']??'');
        if($status==='running'){$busy[$key]=true;continue;}
        $cronPendingWait=$status==='waiting'&&!empty($e['cron_resume_pending']);
        if($status==='waiting'&&!$cronPendingWait){$busy[$key]=true;continue;}
        if(!in_array($status,['paused','failed'],true)&&!$cronPendingWait)continue;
        $at=max((int)($e['updated_at']??0),(int)($e['done_at']??0),(int)($e['paused_at']??0),(int)($e['started_at']??0));
        /* Historical profile products alone never prove that a run progressed.
           Explicitly retryable zero-product stalls (including legacy rows blocked
           by the old watchdog) are allowed back through the normal backoff; a
           newer non-retryable zero-product row remains a barrier. */
        $runProducts=extractQueueRunProductCount($e,$progress,max(1,$runningRows));
        $notUserStopped=empty($e['stopped_by_user'])&&(string)($e['paused_by']??'')!=='user';
        $legacyZeroRetry=$runProducts<=0&&$status==='failed'
            &&(string)($e['auto_resume_blocked']??'')==='zero_products'&&$notUserStopped;
        $legacyLockRetry=$runProducts<=0&&$status==='failed'&&$notUserStopped
            &&preg_match('~(?:قفل|در حال اجراست|lock[_ -]?held|another extraction is (?:already )?in progress)~iu',(string)($e['error']??''))===1;
        $retryableEmpty=$runProducts<=0&&(!empty($e['retryable'])||$legacyZeroRetry||$legacyLockRetry);
        if((!empty($e['auto_resume_blocked'])&&!$legacyZeroRetry&&!$legacyLockRetry)||($runProducts<=0&&!$retryableEmpty)){
            $oldBarrier=$resumeBarriers[$key]??null;
            if(!is_array($oldBarrier)||$at>(int)($oldBarrier['updated_at']??0)
                ||($at===(int)($oldBarrier['updated_at']??0)&&$seq>(int)($oldBarrier['sequence']??0)))
                $resumeBarriers[$key]=['updated_at'=>$at,'sequence'=>$seq];
            continue;
        }
        $profile=is_array($profiles[$key]??null)?$profiles[$key]:[];
        $stage=(string)($profile['_extract_stage']??'');
        $hasProfileCheckpoint=in_array($stage,['list','list_done','detail','stopped'],true)
            ||!empty($profile['_extract_list_incomplete'])||!empty($profile['_extract_resume_req'])
            ||(int)($profile['_extract_resume_from']??0)>0;
        $hasRowCheckpoint=!empty($e['resumable'])||!empty($e['resume_needed'])||!empty($e['partial'])
            ||(int)($e['resume_page']??0)>0||in_array((string)($e['resume_phase']??''),['list','detail'],true);
        if(!$hasProfileCheckpoint&&!$hasRowCheckpoint&&!$retryableEmpty)continue;
        if(!isset($latestRows[$key])||$at>(int)$latestRows[$key]['updated_at']
            ||($at===(int)$latestRows[$key]['updated_at']&&$seq>(int)$latestRows[$key]['sequence'])){
            $latestRows[$key]=['queue_id'=>(string)($e['id']??''),'updated_at'=>$at,'sequence'=>$seq,
                'run_extracted'=>$runProducts,'retryable_empty'=>$retryableEmpty,
                'user_stopped'=>!empty($e['stopped_by_user'])||(string)($e['paused_by']??'')==='user'];
        }
    }
    foreach($watchdogKeys as $key){$key=trim((string)$key);if($key!=='')$watchdog[$key]=true;}
    foreach($profiles as $key=>$profile){
        if(!is_array($profile))continue;
        $stage=(string)($profile['_extract_stage']??'');
        if(in_array($stage,['list','list_done','detail','stopped'],true)||!empty($profile['_extract_list_incomplete'])
            ||!empty($profile['_extract_resume_req'])||(int)($profile['_extract_resume_from']??0)>0)
            $profileCheckpointKeys[(string)$key]=true;
    }
    $keys=array_unique(array_merge(array_keys($latestRows),array_keys($profileCheckpointKeys),array_keys($watchdog)));
    $out=[];
    foreach($keys as $key){
        if($key===''||!isset($profiles[$key])||!is_array($profiles[$key])||!empty($busy[$key]))continue;
        $row=$latestRows[$key]??null;
        /* A profile checkpoint without an eligible queue row cannot prove that
           this interrupted run extracted anything; never infer it from the
           profile's historical product catalogue. */
        if(!is_array($row)||((int)($row['run_extracted']??0)<=0&&empty($row['retryable_empty'])))continue;
        $barrier=$resumeBarriers[$key]??null;
        if(is_array($barrier)){
            $barrierAt=(int)($barrier['updated_at']??0);$rowAt=(int)($row['updated_at']??0);
            if($barrierAt>$rowAt||($barrierAt===$rowAt
                &&(int)($barrier['sequence']??0)>(int)($row['sequence']??0)))continue;
        }
        /* Explicit Stop belongs to the user: an older duplicate row must not
           override it, while a newer automatic checkpoint remains eligible. */
        if(!empty($row['user_stopped']))continue;
        $profile=$profiles[$key];
        $stage=(string)($profile['_extract_stage']??'');
        $hasCheckpoint=in_array($stage,['list','list_done','detail','stopped'],true)
            ||!empty($profile['_extract_list_incomplete'])||!empty($profile['_extract_resume_req'])
            ||(int)($profile['_extract_resume_from']??0)>0||is_array($row);
        if(!$hasCheckpoint)continue;
        $queueId=is_array($row)?(string)($row['queue_id']??''):extractResumeQueueId((string)$key);
        $out[]=['key'=>(string)$key,'queue_id'=>$queueId,
            'updated_at'=>(int)($row['updated_at']??$profile['_extract_stage_at']??0),
            'sequence'=>(int)($row['sequence']??0),'source'=>is_array($row)?'queue':(!empty($watchdog[$key])?'watchdog':'profile')];
    }
    usort($out,static function($a,$b){
        $cmp=(int)($a['updated_at']??0)<=>(int)($b['updated_at']??0);
        if($cmp!==0)return $cmp;
        $cmp=(int)($a['sequence']??0)<=>(int)($b['sequence']??0);
        return $cmp!==0?$cmp:strcmp((string)$a['key'],(string)$b['key']);
    });
    return $out;
}

/** Mark duplicate automatic pauses as superseded once their profile checkpoint has an owner. */
function extractQueueSupersedeOlderPausedRows(string $profileKey,string $keeperQueueId): int {
    if($profileKey===''||$keeperQueueId==='')return 0;
    $lock=@fopen(EXTRACT_QUEUE_FILE.'.lock','c');
    if(!$lock||!@flock($lock,LOCK_EX)){if($lock)@fclose($lock);return 0;}
    $q=json_decode((string)@file_get_contents(EXTRACT_QUEUE_FILE),true);
    if(!is_array($q))$q=['entries'=>[]];
    $entries=is_array($q['entries']??null)?$q['entries']:[];$keeperFound=false;
    foreach($entries as $e){
        if(!is_array($e)||(string)($e['id']??'')!==$keeperQueueId)continue;
        if((string)($e['profile_key']??'')===$profileKey&&in_array((string)($e['status']??''),['waiting','running','paused','failed','done'],true))$keeperFound=true;
        break;
    }
    if(!$keeperFound){@flock($lock,LOCK_UN);@fclose($lock);return 0;}
    $now=time();$changed=0;
    foreach($entries as &$e){
        if(!is_array($e)||(string)($e['profile_key']??'')!==$profileKey||(string)($e['id']??'')===$keeperQueueId
            ||!empty($e['stopped_by_user'])||(string)($e['paused_by']??'')==='user')continue;
        $_oldStatus=(string)($e['status']??'');
        $_retryableFailed=$_oldStatus==='failed'
            &&(!empty($e['retryable'])||(string)($e['auto_resume_blocked']??'')==='zero_products'
                ||preg_match('~(?:قفل|در حال اجراست|lock[_ -]?held|another extraction is (?:already )?in progress)~iu',(string)($e['error']??''))===1);
        if($_oldStatus!=='paused'&&!$_retryableFailed)continue;
        $e['status']='superseded';$e['superseded_by']=$keeperQueueId;$e['superseded_at']=$now;
        $e['updated_at']=$now;$e['done_at']=$now;$e['error']='این checkpoint با ردیف تازه‌تر ادامه می‌یابد: '.$keeperQueueId;$changed++;
    }unset($e);
    if($changed>0){$q['entries']=$entries;@file_put_contents(EXTRACT_QUEUE_FILE,json_encode($q,JSON_UNESCAPED_UNICODE),LOCK_EX);}
    @flock($lock,LOCK_UN);@fclose($lock);
    return $changed;
}

/** Queue every eligible direct-mode checkpoint for later cron pulses without creating a new row. */
function extractQueueScheduleResumeCandidates(array $candidates): array {
    if(tasksResumeExplicitlyStopped('extract',[],readProgress(EXTRACT_PROGRESS_FILE)))
        return ['ok'=>false,'scheduled'=>0,'queue_ids'=>[],'user_stopped'=>true];
    $wanted=[];
    foreach($candidates as $candidate){
        if(!is_array($candidate))continue;
        $id=trim((string)($candidate['queue_id']??''));if($id!=='')$wanted[$id]=true;
    }
    if(!$wanted)return ['ok'=>true,'scheduled'=>0,'queue_ids'=>[]];
    $lock=@fopen(EXTRACT_QUEUE_FILE.'.lock','c');
    if(!$lock||!@flock($lock,LOCK_EX)){if($lock)@fclose($lock);return ['ok'=>false,'scheduled'=>0,'queue_ids'=>[],'error'=>'queue_lock'];}
    if(tasksResumeExplicitlyStopped('extract',[],readProgress(EXTRACT_PROGRESS_FILE))){
        @flock($lock,LOCK_UN);@fclose($lock);return ['ok'=>false,'scheduled'=>0,'queue_ids'=>[],'user_stopped'=>true];
    }
    $q=json_decode((string)@file_get_contents(EXTRACT_QUEUE_FILE),true);
    if(!is_array($q))$q=['entries'=>[]];
    $now=time();$scheduled=[];$changed=false;
    foreach((array)($q['entries']??[])as&$entry){
        if(!is_array($entry)||(string)($entry['id']??'')===''||empty($wanted[(string)$entry['id']]))continue;
        if(!empty($entry['stopped_by_user'])||(string)($entry['paused_by']??'')==='user')continue;
        $status=(string)($entry['status']??'');
        if(in_array($status,['paused','failed'],true)){
            $entry['status']='waiting';$entry['cron_resume_pending']=true;$entry['updated_at']=$now;
            unset($entry['done_at']);$changed=true;$scheduled[]=(string)$entry['id'];
        }elseif($status==='waiting'&&!empty($entry['cron_resume_pending']))$scheduled[]=(string)$entry['id'];
    }unset($entry);
    if($changed)@file_put_contents(EXTRACT_QUEUE_FILE,json_encode($q,JSON_UNESCAPED_UNICODE),LOCK_EX);
    @flock($lock,LOCK_UN);@fclose($lock);
    return ['ok'=>true,'scheduled'=>count(array_unique($scheduled)),'queue_ids'=>array_values(array_unique($scheduled))];
}

function s4AutoResumeInterruptedExtractions(string $source = 'auto', bool $throttled = true): array {
    $cn = loadConnections();
    if (isset($cn['auto_resume']) && empty($cn['auto_resume'])) return ['ok' => true, 'disabled' => true, 'source' => $source];
    $pulseLockFile = __DIR__ . '/_auto_resume_pulse.lock';
    $lf = @fopen($pulseLockFile, 'c');
    if (!$lf || !@flock($lf, LOCK_EX | LOCK_NB)) { if ($lf) @fclose($lf); return ['ok' => true, 'busy' => true, 'source' => $source]; }
    try {
        clearstatcache(true, $pulseLockFile);
        $now = time();
        $minGap = $source === 'worker_loop' ? 8 : 5;
        $lastPulse = (int)@filemtime($pulseLockFile);
        if ($throttled && $lastPulse > 0 && ($now - $lastPulse) < $minGap) return ['ok' => true, 'throttled' => true, 'source' => $source];
        @touch($pulseLockFile, $now);
        /* v10.470: اول ردیف‌های runningِ بی‌مالک/متوقف و پرچم‌های کهنهٔ resuming را سامان بده، سپس dispatch موازی را صدا بزن */
        $stallCfg = in_array($source, ['worker_loop', 'parallel_finish', 'cron'], true)
            ? 60 : max(75, min(180, (int)($cn['stall_after'] ?? 120)));
        $exQ = extractReadQueue();
        $exProg = readProgress(EXTRACT_PROGRESS_FILE);
        $runningRows = 0;
        $staleResumingCleared = false;
        foreach ((array)($exQ['entries'] ?? []) as $_iQ => $_cntR) {
            if (!is_array($_cntR)) continue;
            $_stQ = (string)($_cntR['status'] ?? '');
            if ($_stQ === 'running') $runningRows++;
            elseif (!empty($_cntR['resuming']) && ($now - (int)($_cntR['resume_requested_at'] ?? $_cntR['updated_at'] ?? 0)) > 40
                && !extractLockHeldForQueue((string)($_cntR['id'] ?? ''))) {
                unset($exQ['entries'][$_iQ]['resuming'], $exQ['entries'][$_iQ]['resume_requested_at']);
                $staleResumingCleared = true;
            }
        }
        if ($staleResumingCleared) extractWriteQueue($exQ);
        $pausedKeys = [];
        foreach ((array)($exQ['entries'] ?? []) as $qe) {
            if (!is_array($qe) || (string)($qe['status'] ?? '') !== 'running') continue;
            if (!empty($qe['stop_requested']) || !empty($qe['stopped_by_user']) || (string)($qe['paused_by'] ?? '') === 'user') continue;
            $qid = trim((string)($qe['id'] ?? ''));
            if ($qid === '') continue;
            $lkBeat = extractLockBeatForQueue($qid);
            $workerAlive = false;
            $wjId = trim((string)($qe['worker_job_id'] ?? ''));
            if ($wjId !== '') {
                foreach ((array)(s4WorkerLoadQueue()['entries'] ?? []) as $_we) {
                    if (!is_array($_we) || (string)($_we['id'] ?? '') !== $wjId || (string)($_we['status'] ?? '') !== 'running') continue;
                    $workerAlive = s4WorkerPidAlive((int)($_we['worker_pid'] ?? 0));
                    break;
                }
            }
            $lockHeld = extractLockHeldForQueue($qid);
            $ownerPresent = $lockHeld || $workerAlive;
            $iw = queueRowIdle('extract', $qe, $exProg, $now, ['lock' => $lkBeat], max(1, $runningRows));
            $idle = (int)($iw['idle'] ?? 0);
            $recentBoot = max((int)($qe['started_at'] ?? 0), (int)($qe['resume_requested_at'] ?? 0), (int)($qe['updated_at'] ?? 0));
            if (!$ownerPresent && $idle < 40 && $recentBoot > 0 && ($now - $recentBoot) < 40) continue;
            if ($ownerPresent && $idle < $stallCfg) continue;
            if ($ownerPresent) {
                $retire = extractCancelWorkerForQueueRow($qe, 'stalled_auto_recovery');
                if (!empty($retire['signal_sent'])) usleep(200000);
            }
            $paused = extractQueuePauseStaleRow($qid, $stallCfg, !$ownerPresent);
            if (!is_array($paused)) continue;
            $pk = trim((string)($paused['row']['profile_key'] ?? $qe['profile_key'] ?? ''));
            $exPhase = (string)($paused['phase'] ?? 'list') === 'detail' ? 'detail' : 'list';
            if (!empty($paused['resumable']) && $pk !== '') {
                $pausedKeys[] = $pk;
                $ps = loadProfiles();
                if (isset($ps[$pk]) && is_array($ps[$pk])) {
                    $oneP = $ps[$pk];
                    unset($ps);
                    $oneP['_extract_stage'] = 'stopped';
                    $oneP['_extract_resume_phase'] = $exPhase;
                    $oneP['_extract_list_incomplete'] = ($exPhase === 'list');
                    if ($exPhase === 'list' && empty($oneP['_extract_resume_from'])) {
                        $rp = max(1, (int)($paused['row']['resume_page'] ?? $paused['row']['current'] ?? 1));
                        if ($rp > 1) $rp = max(1, $rp - 1);
                        $oneP['_extract_resume_from'] = $rp;
                    }
                    $oneP['_extract_stage_at'] = time();
                    saveOneProfileAtomic($pk, $oneP);
                    unset($oneP);
                } else {
                    unset($ps);
                }
                if (!empty($paused['progress_owned'])) {
                    $latestPg = readProgress(EXTRACT_PROGRESS_FILE);
                    if ((string)($latestPg['queue_id'] ?? '') === $qid || $runningRows <= 1) {
                        $latestPg['running'] = false;$latestPg['done'] = false;$latestPg['paused'] = true;
                        $latestPg['resume_needed'] = true;$latestPg['stalled'] = true;$latestPg['resumable'] = true;
                        $latestPg['resume_phase'] = $exPhase;
                        $latestPg['recent_log'] = array_slice(array_merge((array)($latestPg['recent_log'] ?? []), [
                            '♻️ توقف ناخواسته تشخیص داده شد — آماده‌سازی ادامهٔ خودکار از checkpoint (' . ($exPhase === 'detail' ? 'فاز ۲: جزئیات' : 'فاز ۱: لیست') . ')…'
                        ]), -15);
                        writeProgress(EXTRACT_PROGRESS_FILE, $latestPg);
                    }
                }
            }
        }
        $dispatch0 = s4ParallelExtractSupported() ? s4DispatchParallelExtractJobs() : [];
        $queueNow = extractReadQueue();
        $hasEligibleQueueRow = !empty($pausedKeys);
        if (!$hasEligibleQueueRow) {
            foreach ((array)($queueNow['entries'] ?? []) as $_qCand) {
                if (!is_array($_qCand)) continue;
                $_qSt = (string)($_qCand['status'] ?? '');
                if (in_array($_qSt, ['paused', 'failed'], true) && empty($_qCand['auto_resume_blocked']) && empty($_qCand['stopped_by_user'])) {
                    $hasEligibleQueueRow = true; break;
                }
                if ($_qSt === 'waiting' && !empty($_qCand['cron_resume_pending'])) {
                    $hasEligibleQueueRow = true; break;
                }
            }
        }
        if (!$hasEligibleQueueRow) {
            return ['ok' => true, 'source' => $source, 'paused_stalled' => [], 'resumed' => [], 'skipped' => [], 'browser_resume' => null, 'dispatch' => $dispatch0, 'fast_no_candidates' => true];
        }
        $profiles = loadProfiles();
        $candidates = cronExtractResumeCandidates($profiles, (array)($queueNow['entries'] ?? []), $pausedKeys);
        $candProfiles = [];
        foreach ($candidates as $_cItem) {
            $_ck = trim((string)($_cItem['key'] ?? ''));
            if ($_ck !== '' && isset($profiles[$_ck]) && is_array($profiles[$_ck])) $candProfiles[$_ck] = $profiles[$_ck];
        }
        unset($profiles);
        $manualStopPk = extractManualStopProfileKey();
        $tryLimit = max(1, min(10, (int)($cn['auto_resume_max'] ?? 3)));
        $resumed = [];$skipped = [];$browserResume = null;
        $workerActive = s4WorkerIsActive();
        if (!$workerActive && s4ParallelExtractSupported() && function_exists('s4SpawnPersistentWorker') && $candidates) {
            try { s4SpawnPersistentWorker(); usleep(150000); $workerActive = s4WorkerIsActive(); } catch (Throwable $_spEx) {}
        }
        foreach ($candidates as $cand) {
            $rk = trim((string)($cand['key'] ?? ''));
            $rqId = trim((string)($cand['queue_id'] ?? ''));
            if ($rk === '') continue;
            if ($manualStopPk !== '' && $rk === $manualStopPk) { $skipped[] = ['key' => $rk, 'queue_id' => $rqId, 'reason' => 'explicit_manual_sync_stop']; continue; }
            $pgChk = readProgress(EXTRACT_PROGRESS_FILE);
            $samePgRow = $rqId === '' || (string)($pgChk['queue_id'] ?? '') === $rqId;
            if (tasksResumeExplicitlyStopped('extract', [], $samePgRow ? $pgChk : [])) { $skipped[] = ['key' => $rk, 'queue_id' => $rqId, 'reason' => 'explicit_user_stop']; continue; }
            if ($rqId !== '' && extractQueueRowStoppedByUser($rqId)) { $skipped[] = ['key' => $rk, 'queue_id' => $rqId, 'reason' => 'stopped_by_user']; continue; }
            $prFresh = $candProfiles[$rk] ?? null;
            if (!is_array($prFresh)) continue;
            $qFresh = extractReadQueue();
            $alreadyActive = false;
            foreach ((array)($qFresh['entries'] ?? []) as $fr) {
                if (!is_array($fr) || (string)($fr['profile_key'] ?? '') !== $rk) continue;
                if ($rqId !== '' && (string)($fr['id'] ?? '') === $rqId) continue;
                if (in_array((string)($fr['status'] ?? ''), ['running', 'waiting'], true)) { $alreadyActive = true; break; }
            }
            if ($alreadyActive) { $skipped[] = ['key' => $rk, 'queue_id' => $rqId, 'reason' => 'already_running_or_queued']; continue; }
            $rSig = extractResumeSig($prFresh);
            $rMeta = is_array($prFresh['_extract_resume_meta'] ?? null) ? $prFresh['_extract_resume_meta'] : [];
            $rPrevSig = (string)($rMeta['sig'] ?? '');
            $rPrevAt = (int)($rMeta['at'] ?? 0);
            $rPrevVer = (string)($rMeta['ver'] ?? '');
            $rTries = (int)($rMeta['tries'] ?? 0);
            if ($rPrevVer === APP_VERSION && $rPrevSig !== '' && $rPrevSig === $rSig && ($now - $rPrevAt) < AUTO_RESUME_WINDOW) $rTries++; else $rTries = 0;
            if ($rTries >= $tryLimit) {
                $backoff = min(900, 30 * (2 ** min(5, max(0, $rTries - $tryLimit))));
                if (($now - $rPrevAt) < $backoff) { $skipped[] = ['key' => $rk, 'queue_id' => $rqId, 'reason' => 'backoff', 'retry_after' => $backoff - ($now - $rPrevAt)]; continue; }
            }
            $rPhase = extractResumePhase($prFresh);
            $runPhase = ($rPhase === 'list' && !empty($prFresh['_extract_want_detail'])) ? 'all' : $rPhase;
            $dMode = normalizeDetailExtractMode($prFresh['detailExtractMode'] ?? 'two_stage');
            if ($workerActive || s4ParallelExtractSupported()) {
                extractResumeMetaSaveAtomic($rk, ['sig' => $rSig, 'at' => $now, 'tries' => $rTries, 'ver' => APP_VERSION]);
                $enq = s4WorkerEnqueueBackendExtract($rk, $runPhase, false, true, -1, $rqId, false, $dMode);
                if (!empty($enq['ok'])) {
                    $actualQid = (string)($enq['queue_id'] ?? $rqId);
                    if ($actualQid !== '') extractQueueSupersedeOlderPausedRows($rk, $actualQid);
                    $resumed[] = ['key' => $rk, 'queue_id' => $actualQid, 'phase' => $runPhase, 'via' => 'worker', 'job_id' => (string)($enq['job_id'] ?? '')];
                    continue;
                }
            }
            if (function_exists('s4SpawnBackendExtractChild')) {
                extractResumeMetaSaveAtomic($rk, ['sig' => $rSig, 'at' => $now, 'tries' => $rTries, 'ver' => APP_VERSION]);
                $sp = s4SpawnBackendExtractChild($rk, $runPhase, false, true, -1, $dMode, $rqId);
                if (!empty($sp['ok'])) {
                    if ($rqId !== '') extractQueueSupersedeOlderPausedRows($rk, $rqId);
                    $resumed[] = ['key' => $rk, 'queue_id' => $rqId, 'phase' => $runPhase, 'via' => 'cli_child', 'pid' => (int)($sp['pid'] ?? 0)];
                    continue;
                }
            }
            if ($browserResume === null) {
                $browserResume = ['profile_key' => $rk, 'queue_id' => $rqId, 'phase' => $rPhase, 'resume_page' => $rPhase === 'list' ? extractResumeStartPage($prFresh) : 0];
            }
        }
        return ['ok' => true, 'source' => $source, 'paused_stalled' => $pausedKeys, 'resumed' => $resumed, 'skipped' => $skipped, 'browser_resume' => $browserResume, 'dispatch' => $dispatch0];
    } finally {
        @flock($lf, LOCK_UN);
        @fclose($lf);
    }
}


/**
 * v9.01: استخراج در مراحل جدا.
 *
 * $phase:
 *   'all'    — فهرست + جزئیات، مثل همیشه (دکمهٔ دستی)
 *   'list'   — فقط صفحهٔ فهرست؛ فاز جزئیات اصلاً اجرا نمی‌شود
 *   'detail' — فقط جزئیاتِ محصولاتی که روی دیسک هستند و هنوز کامل نیستند
 *
 * چرا: کاربر می‌خواهد کران‌جاب اول فهرست را بگیرد، بعد «استخراج تفصیلی»
 * را جدا اجرا کند و تازه بعد از آن سراغ ارسال برود. با این پارامتر هر سه
 * از یک موتور می‌گذرند و رفتارشان نمی‌تواند از هم جدا بیفتد.
 */
/* v9.44: استخراج جزئیاتِ یک محصول به‌صورت درجا (inline) — بجای «فاز ۲»ی جداگانه.
   وقتی محصول از فهرست گرفته می‌شود، همین‌جا صفحهٔ خودش باز و جزئیاتش (فیلدها،
   گالری، تنوع‌ها) استخراج می‌شود. چون کران‌جاب (cron-job.org) منتظر کارِ
   پس‌زمینه نمی‌ماند، اگر جزئیات «بعداً» و در نوبتِ جدا اجرا شود ممکن است هرگز
   کامل نشود؛ درحالی‌که این‌جا به‌محض استخراج هر محصول کامل می‌شود و چک‌پوینتِ
   هر محصول همان لحظه نوشته می‌شود. */
function extractProductDetailInline(array &$allProducts, string $key, array $detailSelectors, array $galleryCfg, bool $forceAll): array {
    $out = ['ok' => false, 'opened' => false, 'fields' => 0, 'imgs' => 0, 'vars' => 0, 'error' => ''];
    if (!isset($allProducts[$key])) return $out;
    $p = &$allProducts[$key];
    if (empty($p['link'])) return $out;
    $out['opened'] = true;
    $dr = fetch_html($p['link'], 10);
    if (!$dr['ok']) {
        $out['error'] = trim((string)($dr['error'] ?? ''));
        if ($out['error'] === '') $out['error'] = 'HTTP ' . (int)($dr['code'] ?? 0);
        return $out;
    }
    $out['ok'] = true;
    [$domInl, $xpInl] = load_dom($dr['html']);
    $_inlineSnappSynth = strpos($dr['html'], 'data-snappshop-api-detail="1"') !== false
        || strpos($dr['html'], 'data-digikala-api-detail="1"') !== false;
    $galleryCfg = galleryEffectiveCfgForUrl($galleryCfg, (string)($p['link'] ?? ''));
    $fields = 0; $imgs = 0; $vars = 0;
    foreach ($detailSelectors as $field => $selStr) {
        if (empty($selStr)) continue;
        if ($field === 'variations') {
            /* v10.116: baseUrl برای مطلق‌کردن تصاویر سواچ */
            $vr = variationsExtract($xpInl, null, $selStr, (string)($dr['url'] ?? ''));
            if (!empty($vr['values'])) {
                $p['variations'] = $vr['values'];
                $p['variation_groups'] = $vr['groups'];
                $p['variations_text'] = implode('، ', $vr['values']);
                $vars = count($vr['values']); $fields++;
                if (!empty($vr['prices'])) {
                    $p['variation_prices'] = $vr['prices'];
                    $p['price_min'] = $vr['price_min'];
                    $p['price_max'] = $vr['price_max'];
                    $p['price_varies'] = !empty($vr['price_varies']);
                }
                if (!empty($vr['combinations']) && is_array($vr['combinations'])) {
                    $p['variation_combinations'] = $vr['combinations'];
                }
            }
            /* تصاویر تنوع → گالری محصول */
            if (!empty($vr['images']) && is_array($vr['images'])) {
                $ni = galleryApplyToProduct($p, $vr['images'], $forceAll);
                if ($ni > $imgs) $imgs = $ni;
                $p['variation_images'] = $vr['images'];
                $p['variation_images_count'] = count($vr['images']);
            }
            continue;
        }
        $xPath = cssToXpath($selStr);
        $ns = $xPath ? @$xpInl->query($xPath) : null;
        if ((!$ns || !$ns->length) && $_inlineSnappSynth && function_exists('snappshopFallbackSelectorForField')) {
            $_fbInl = snappshopFallbackSelectorForField((string)$field);
            if ($_fbInl !== '') {
                $_fbXpInl = cssToXpath($_fbInl);
                if ($_fbXpInl) $ns = @$xpInl->query($_fbXpInl);
            }
        }
        if ($ns && $ns->length) {
            $val = '';
            if ($field === 'image') {
                $val = galleryImgFromNode($ns->item(0), $dr['url']);
            } elseif ($field === 'price') {
                $val = extractPrice($ns->item(0)->textContent);
            } else {
                $val = s4ExtractDetailNodeValue((string)$field, $ns, (string)($dr['url'] ?? ''));
            }
            if ($val) { $p[$field] = $val; $fields++; }
        }
    }
    if ($_inlineSnappSynth && empty($p['specs'])) {
        $_snTblInl = @$xpInl->query('//table[contains(@class,"shop_attributes")]');
        if ($_snTblInl && $_snTblInl->length) {
            $_snSpInl = s4ExtractDetailNodeValue('specs', $_snTblInl, (string)($dr['url'] ?? ''));
            if ($_snSpInl !== '') { $p['specs'] = $_snSpInl; $fields++; }
        }
    }
    if (!empty($p['weight']) && function_exists('s4ParseWeightGrams') && s4ParseWeightGrams($p['weight']) <= 0) {
        $p['weight'] = '';
    }
    if (empty($p['weight']) && !empty($p['specs']) && function_exists('s4ExtractWeightsFromSpecs')) {
        $_spWtInl = s4ExtractWeightsFromSpecs($p['specs']);
        if (!empty($_spWtInl['raw']) && (($_spWtInl['net_g'] ?? 0) > 0 || ($_spWtInl['pkg_g'] ?? 0) > 0)) {
            $p['weight'] = (string)$_spWtInl['raw'];
            if (($_spWtInl['pkg_g'] ?? 0) > 0) $p['package_weight'] = (int)$_spWtInl['pkg_g'] . ' گرم';
            $fields++;
        }
    }
    if (empty($p['weight']) && function_exists('s4AutoExtractWeightFromDetailDom')) {
        $_domWtInl = s4AutoExtractWeightFromDetailDom($xpInl, (string)($dr['html'] ?? ''));
        if (!empty($_domWtInl['weight'])) { $p['weight'] = (string)$_domWtInl['weight']; $fields++; }
        if (!empty($_domWtInl['package_weight']) && empty($p['package_weight'])) $p['package_weight'] = (string)$_domWtInl['package_weight'];
    }
    if (empty($p['image'])) {
        $ogImg = @$xpInl->query("//meta[@property='og:image']/@content");
        if ($ogImg && $ogImg->length) {
            $imgUrl = $ogImg->item(0)->nodeValue;
            if ($imgUrl && url_is_image($imgUrl)) $p['image'] = make_absolute_url($imgUrl, $dr['url']);
        }
    }
    if ($galleryCfg['enabled']) {
        $gal = galleryExtract($xpInl, null, $dr['url'], $galleryCfg);
        if (!empty($gal['images'])) {
            $imgs = galleryApplyToProduct($p, $gal['images'], $forceAll);
        }
    }
    $out['fields'] = $fields; $out['imgs'] = $imgs; $out['vars'] = $vars;
    return $out;
}

function runBackendExtract(string $profileKey, string $trigger = 'manual', bool $emitEarlyResponse = false, string $phase = 'all', bool $forceAll = false, string $reservedLockQueueId = '', int $maxPagesOverride = -1, string $detailModeOverride = ''): array {
if (!in_array($phase, ['all', 'list', 'detail'], true)) $phase = 'all';
@set_time_limit(0); @ignore_user_abort(true);
/* v10.134: فایل‌های مشترکِ پیشرفت/توقف فقط بعد از گرفتنِ lock پاک می‌شوند؛
   درخواستِ تکراری نباید پیشرفتِ workerِ زنده را محو کند. */

$startedAt=time();
$profiles=loadProfiles();
$releaseResumeReservation = function () use ($reservedLockQueueId): void {
    if ($reservedLockQueueId === '') return;
    $fp = $GLOBALS['_extractLockFp'] ?? null;
    if (is_resource($fp) && (string)($GLOBALS['_extractLockQueueId'] ?? '') === $reservedLockQueueId)
        extractLockRelease($reservedLockQueueId);
};

$profile=isset($profiles[$profileKey])?$profiles[$profileKey]:null;
/* v10.470: آزادسازی فوری ~۱۸۰ مگابایت کاتالوگ کامل profiles.json از RAM؛ از این نقطه فقط پروفایلِ هدف لازم است */
unset($profiles);
if (function_exists('gc_collect_cycles')) @gc_collect_cycles();
// v9.67: اتصال غیرمستقیمِ به‌ازای هر پروفایل — آفلاینِ هر فراخوانیِ استخراج
// مقدارِ پیش‌فرض «مستقیم» (غیرفعال) است مگر اینکه پروفایل صریحاً روشن کرده باشد.
$GLOBALS['_srcNetProfileIndirect'] = netIndirectOn($profile['net_indirect'] ?? false);
if(!$profile){
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'error'=>'پروفایل یافت نشد','total'=>0,'current'=>0,'started_at'=>$startedAt,'recent_log'=>['❌ پروفایل یافت نشد'],'total_log_count'=>1]);
$releaseResumeReservation();
return ['__early_sent'=>$emitEarlyResponse, 'ok'=>false,'error'=>'پروفایل یافت نشد'];
}

$url=s4NormalizeInputUrl((string)($profile['url']??''));
$savedMaxPages=max(0,(int)($profile['pages']??10));
$pageSetting=$maxPagesOverride>=0?max(0,$maxPagesOverride):$savedMaxPages;
$autoPageMode=$pageSetting===0;
/* Auto mode needs a failsafe only for broken pagination that never ends.
   It is not a user-facing page limit and normal end detection stops far sooner. */
$maxPages=$autoPageMode?10000:max(1,$pageSetting);
$progressPageTarget=$autoPageMode?0:$maxPages;
$selectors=$profile['selectors']??[];
$extractEngine=normalizeExtractionEngine((string)($profile['extractionEngine'] ?? 'selectors'));
if(function_exists('isDigikalaUrl') && isDigikalaUrl($url) && $extractEngine==='selectors' && (empty($selectors) || empty($selectors['container']))){
    $extractEngine='digikala_api';
}
$GLOBALS['_s4ActiveDigikalaApiEngine']=($extractEngine==='digikala_api');
$pagType=$profile['pagType']??'query_page';
$pagVal=$profile['pagVal']??'';
$detailSelectors=extractNormalizeDetailSelectors($profile['detailSelectors']??[]);
if(empty($detailSelectors) && $extractEngine==='digikala_api' && function_exists('digikalaDefaultDetailSelectors')){
    $detailSelectors=digikalaDefaultDetailSelectors();
}
$_detailExtractMode=normalizeDetailExtractMode($detailModeOverride!==''?$detailModeOverride:($profile['detailExtractMode']??'two_stage'));
$detailConfigured=!empty($detailSelectors);
$_isResumeRun=($reservedLockQueueId!=='')||!empty($profile['_extract_resume_req'])
    ||in_array((string)$trigger,['manual_resume','watchdog_resume','auto_resume','cron_resume'],true);
if($phase==='list'&&$_isResumeRun&&!empty($profile['_extract_want_detail'])&&$detailConfigured){
    $phase='all';
}
$_wantDetailAfterList=($phase==='all'||($phase==='detail'&&!empty($profile['_extract_want_detail'])))&&$detailConfigured?1:0;
$_detailSkippedNoSelectors=false;
/* No enabled selector means there is no stage two. Gallery configuration by
   itself is not permission to open every product page. */
if(!$detailConfigured&&$phase==='all'){$phase='list';$_detailSkippedNoSelectors=true;}
if(!$detailConfigured&&$phase==='detail'){
    $_detailSkippedNoSelectors=true;
    $profile['_extract_stage']='complete';$profile['_extract_stage_at']=time();
    $profile['_extract_resume_needed']=0;$profile['_extract_resume_phase']='';
    $profile['_extract_list_incomplete']=false;$profile['_extract_resume_req']=0;
    saveOneProfileAtomic($profileKey,$profile);
    writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'skipped'=>true,
        'detail_skip_why'=>'no_detail_selectors','profile_key'=>$profileKey,'phase'=>'list',
        'total'=>0,'current'=>0,'started_at'=>$startedAt,'finished_at'=>time(),
        'recent_log'=>['⏭ مرحلهٔ دوم اجرا نشد — هیچ سلکتور جزئیات فعالی برای این پروفایل ذخیره نشده است'],'total_log_count'=>1]);
    if($reservedLockQueueId!==''){$sq=extractReadQueue();foreach($sq['entries']as&$se){if((string)($se['id']??'')!==$reservedLockQueueId)continue;
        $se['status']='done';$se['done_at']=time();$se['updated_at']=time();$se['detail_skip_why']='no_detail_selectors';
        $se['detail_total']=0;$se['current']=0;$se['total']=0;$se['resumable']=false;$se['resume_needed']=0;break;}unset($se);extractWriteQueue($sq);}
    $releaseResumeReservation();
    return ['__early_sent'=>$emitEarlyResponse,'ok'=>true,'skipped'=>true,'detail_skipped'=>true,
        'detail_skip_why'=>'no_detail_selectors','phase'=>'list','extracted'=>count((array)($profile['products']??[]))];
}
$prevProducts=$profile['products']??[];
$prevOrder=$profile['productsOrder']??[];

if(!filter_var($url,FILTER_VALIDATE_URL)){
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'error'=>'URL نامعتبر','total'=>0,'current'=>0,'started_at'=>$startedAt,'recent_log'=>['❌ URL نامعتبر'],'total_log_count'=>1]);
$releaseResumeReservation();
return ['__early_sent'=>$emitEarlyResponse, 'ok'=>false,'error'=>'URL نامعتبر'];
}
/* v10.21 (۳۴الف): سلکتورِ «فهرست» فقط برای پیمایشِ صفحهٔ دسته لازم است.
   پروفایل‌های ساخته‌شده با درون‌ریزیِ اکسل/CSV هیچ‌وقت صفحهٔ فهرست ندارند —
   محصولاتشان از فایل آمده و هرکدام لینکِ صفحهٔ خودشان را دارند. تا اینجا
   همین گیت، فازِ جزئیاتِ آن‌ها را هم رد می‌کرد و سینکِ دوره‌ای بی‌صدا شکست
   می‌خورد. حالا در فازِ detail فقط سلکتورِ جزئیات لازم است. */
if($phase==='detail'){
if(empty($detailSelectors)){
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'error'=>'سلکتورِ جزئیات ذخیره نشده','total'=>0,'current'=>0,'started_at'=>$startedAt,'recent_log'=>['❌ سلکتورِ جزئیات ذخیره نشده'],'total_log_count'=>1]);
$releaseResumeReservation();
return ['__early_sent'=>$emitEarlyResponse, 'ok'=>false,'error'=>'سلکتورِ جزئیات ذخیره نشده'];
}
} elseif($extractEngine==='selectors' && (empty($selectors)||empty($selectors['container']))){
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'error'=>'سلکتورها ذخیره نشده — ابتدا سلکتور بگذارید یا موتور Auto/Heuristic/Playwright/Selenium را انتخاب کنید','total'=>0,'current'=>0,'started_at'=>$startedAt,'recent_log'=>['❌ سلکتورها ذخیره نشده — موتور فعلی به CSS selector نیاز دارد'],'total_log_count'=>1]);
$releaseResumeReservation();
return ['__early_sent'=>$emitEarlyResponse, 'ok'=>false,'error'=>'سلکتورها ذخیره نشده'];
}

/* قفل باید پیش از هر probe/تغییرِ صف گرفته شود؛ وگرنه دو درخواست هر دو
   ردیفِ قبلی را stale می‌دیدند و یکی را می‌بستند، پیش از آنکه flock دوم رد شود.
   اگر آماده‌سازیِ resume همین request را رزرو کرده، همان handle و queue_id را
   مصرف کن؛ worker فرزندِ جداگانه reservation را در action backend می‌گیرد. */
$queueId = trim($reservedLockQueueId);
if ($queueId === '') $queueId='ex_'.$profileKey.'_'.time().'_'.substr(bin2hex(random_bytes(3)),0,6);
$_reservedOwn = $queueId !== ''
    && is_resource($GLOBALS['_extractLockFp'] ?? null)
    && (string)($GLOBALS['_extractLockQueueId'] ?? '') === $queueId
    && (string)(($GLOBALS['_extractLockMeta']['profile_key'] ?? '')) === $profileKey;
$_lk = $_reservedOwn ? ['ok' => true, 'reused' => true] : extractLockAcquire($queueId,$profileKey);
if(empty($_lk['ok'])){
    $_lkWho=trim((string)($_lk['profile_name']??''));
    if($_lkWho==='')$_lkWho=trim((string)($_lk['profile_key']??''));
    $msg='استخراجِ دیگری در حال اجراست'.($_lkWho!==''?(' («'.$_lkWho.'»)'):'')
        .' — '.(int)($_lk['age']??0).' ثانیه پیش شروع شده. برای اینکه دو اجرا'
        .' نتایج همدیگر را خراب نکنند، این نوبت رد شد.';
    /* A rejected contender does not own EXTRACT_PROGRESS_FILE. Writing there
       used to erase the live extractor's queue_id/heartbeat and made watchdogs
       mark healthy work stale. Preserve products and persist a retry checkpoint. */
    extractRememberRetryableCheckpoint($profileKey,$phase,'extract_lock_busy');
    return ['__early_sent'=>$emitEarlyResponse,'ok'=>false,'retryable'=>true,'resume_needed'=>true,
    'queued'=>true,'error'=>$msg,'locked'=>true,'phase'=>$phase,'profile_key'=>$profileKey,
    'queue_id'=>$reservedLockQueueId,'retry_reason'=>'extract_lock_busy',
    'busy_queue_id'=>(string)($_lk['queue_id']??'')];
}
/* A cancelled worker may have been spawned just before its queue row was
   deleted. Recheck job + row-specific user-stop state after taking the slot,
   before creating/upserting the visible row, so that late children cannot
   resurrect a deleted queue ID. */
$_currentWorkerJobId=(string)($GLOBALS['_s4WorkerJobId']??'');
if(($_currentWorkerJobId!==''&&s4WorkerJobIsCancelled($_currentWorkerJobId))
    ||extractStopRequestedForQueue($queueId,false)||extractQueueRowStoppedByUser($queueId)){
    extractLockRelease($queueId);
    return ['__early_sent'=>$emitEarlyResponse,'ok'=>false,'cancelled'=>true,
        'queue_id'=>$queueId,'error'=>'stopped_by_user'];
}
$queue=extractReadQueue();
/* Resume owns the old visible queue row. Reusing its id keeps logs, report
   links and UI history attached to one row instead of appending a clone. */
$_resumeRowIndex=-1;
if($reservedLockQueueId!=='')foreach((array)($queue['entries']??[])as $_ri=>$_re){
    if(!is_array($_re)||(string)($_re['id']??'')!==$queueId)continue;
    if((string)($_re['profile_key']??'')===$profileKey)$_resumeRowIndex=(int)$_ri;
    break;
}
$_reuseQueueRow=$_resumeRowIndex>=0;
/* v8.55: اگر همین پروفایل هنوز در صف استخراج است، دوباره اضافه نشود.
   v9.03: ولی گام جزئیات استثناست. کران عمداً بلافاصله بعد از گام فهرست
   آن را صدا می‌زند و ردیفِ همان گامِ فهرست هنوز در صف است؛ اگر محافظ
   اینجا جلویش را بگیرد، مرحلهٔ جزئیات هیچ‌وقت اجرا نمی‌شود. این دقیقاً
   همان چیزی بود که کاربر می‌دید. دو گامِ یک اجرا «تکراری» نیستند. */
if(queueDedupOn() && $phase!=='detail' && !$_reuseQueueRow){
/* v9.03: ردیفی که پردازه‌اش دیگر زنده نیست نباید جلوی اجرای تازه را
   بگیرد. معیار همان معیار نگهبان است: اگر فایل پیشرفت مالِ آن ردیف
   نیست یا مدت‌هاست چیزی ننوشته، آن اجرا مرده و ردیفش بی‌اعتبار است.
   بدون این، یک ردیفِ جامانده تا دو ساعت هر اجرای خودکار را رد می‌کرد. */
$dup=queueHasProfile($queue['entries'],$profileKey,queueDedupStale());
if($dup!==null){
    $_dupProg=readProgress(EXTRACT_PROGRESS_FILE);
    $_dupMine=((string)($_dupProg['queue_id']??''))===((string)($dup['id']??''));
    $_dupTs=$_dupMine?(int)($_dupProg['last_progress_ts']??0):0;
    if($_dupTs<=0)$_dupTs=(int)($dup['started_at']??0);
    $_dupIdle=$_dupTs>0?(time()-$_dupTs):PHP_INT_MAX;
    $_dupMax=max(120,(int)(loadConnections()['stall_after']??300));
    /* v10.79/v10.80: دستی = آستانهٔ کوتاه؛ خودکار هم waiting/paused و running مرده را برمی‌دارد
       (قبلاً waiting با started_at=0 تا ابد جلوی enqueue می‌ایستاد). */
    $_dupIsManual = in_array((string)$trigger, ['manual', 'manual_sync', 'manual_resume', 'worker', 'worker_child'], true);
    $_dupIsAuto   = in_array((string)$trigger, ['auto', 'cron', 'periodic_sync', 'watchdog_resume', 'auto_resume', 'cron_resume'], true);
    $_dupSt = (string)($dup['status'] ?? '');
    $_dupQid = (string)($dup['id'] ?? '');
    if ($_dupSt === 'running' && $_dupQid !== '' && !extractLockHeldForQueue($_dupQid)) {
        $_dupIdle = PHP_INT_MAX;
    } elseif ($_dupIsManual) {
        $_dupMax = min($_dupMax, 90);
        if ((string)$trigger === 'manual_resume'
            || $_dupSt === 'waiting' || $_dupSt === 'paused') {
            /* lock همین resume گرفته شده؛ running قبلی اگر مانده، worker ندارد
               و باید جایگزین شود، نه اینکه از checkpoint جدید جلوگیری کند. */
            $_dupIdle = PHP_INT_MAX; // force replace
        }
    } elseif ($_dupIsAuto) {
        if ($_dupSt === 'waiting' || $_dupSt === 'paused') {
            // ردیف منتظر بدون ضربان — برای کران مانع دائمی نباشد
            if ($_dupIdle === PHP_INT_MAX || $_dupIdle > min(300, $_dupMax)) {
                $_dupIdle = PHP_INT_MAX;
            }
        }
        // running مرده: همان $_dupMax (stall) کافی است
    }
    if($_dupIdle>$_dupMax){
        // مرده است — ردیفش را ببند و ادامه بده
        foreach($queue['entries'] as &$_qe){
            if(($_qe['id']??'')!==($dup['id']??''))continue;
            $_qe['status']='failed';
            $_qe['error']='بی‌حرکت ماند ('.($_dupIdle===PHP_INT_MAX?'—':$_dupIdle).' ثانیه) — اجرای تازه جایش را گرفت';
            $_qe['done_at']=time();
        }
        unset($_qe);
        extractWriteQueue($queue);
        $dup=null;
    }
}
if($dup!==null){
$msg='این پروفایل هم‌اکنون در صف استخراج است ('.($dup['status']??'').')';
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'error'=>$msg,
'total'=>0,'current'=>0,'started_at'=>$startedAt,'recent_log'=>['⏭ '.$msg],'total_log_count'=>1]);
extractLockRelease($queueId);
return ['__early_sent'=>$emitEarlyResponse,'ok'=>false,'error'=>$msg,
'duplicate'=>true,'queue_id'=>$dup['id']??''];
}
}
/* v8.91: شناسه فقط تا ثانیه دقت داشت. دو اجرای پشت‌سرهمِ یک پروفایل
   (که وقتی اجرای اول فوراً شکست می‌خورد کاملاً عادی است) شناسهٔ یکسان
   می‌گرفتند؛ آن‌وقت به‌روزرسانی وضعیت روی ردیف اشتباهی می‌نشست و گزارش
   هر کدام گزارش دیگری را بازنویسی می‌کرد. */
/* queueId و lock پیش از dedup ساخته شدند تا probe و بستنِ ردیف بدون مالکیت
   انجام نشود؛ اکنون فقط workerِ صاحبِ lock فایلِ مشترک را آغاز می‌کند. */
localTaskDbForget(EXTRACT_PROGRESS_FILE); @unlink(EXTRACT_PROGRESS_FILE);
/* Stop signals are cleared only by an explicit resume for this queue_id. */
$_runRow=['id'=>$queueId,'status'=>'running','profile_key'=>$profileKey,'url'=>$url,
    'profile_name'=>$profile['name']??$profileKey,'products_count'=>0,'total'=>0,'current'=>0,
    'new'=>0,'price_changed'=>0,'removed'=>0,'unchanged'=>0,'trigger'=>$trigger,'phase'=>$phase,
    'sync_stage'=>in_array((string)$trigger,['manual_sync','periodic_sync'],true),
    'updated_at'=>time(),'segment_started_at'=>time()];
if($_reuseQueueRow){
    $_oldRow=is_array($queue['entries'][$_resumeRowIndex]??null)?$queue['entries'][$_resumeRowIndex]:[];
    $_runRow=array_merge($_oldRow,$_runRow);
    $_runRow['started_at']=(int)($_oldRow['started_at']??time());
    $_runRow['resume_count']=(int)($_oldRow['resume_count']??0)+1;
    foreach(['products_count','total','current','new','price_changed','removed','unchanged'] as $_keepCounter)
        if(array_key_exists($_keepCounter,$_oldRow))$_runRow[$_keepCounter]=$_oldRow[$_keepCounter];
    $_runRow['resuming']=true;$_runRow['resumable']=true;$_runRow['error']='';
    unset($_runRow['done_at'],$_runRow['stopped_by_user'],$_runRow['cron_resume_pending']);
    $queue['entries'][$_resumeRowIndex]=$_runRow;
}else{
    $_runRow['started_at']=time();
    $queue['entries'][]=$_runRow;
}
extractWriteQueue($queue);

// v8.22: نسخهٔ قبلی را همین ابتدا بخوان تا مقایسه بتواند زنده انجام شود
$livePrevMap=extractPrevMap($profile);
/* v10.180: خطِ آغازِ هر اجرا — برای resumeها برچسب «ادامه» تا در لاگ
   راه‌افتادنِ جدید از تکرارِ خطِ قدیمی تشخیص داده شود. */
$_rsmHint = !empty($profile['_extract_list_incomplete']) || !empty($profile['_extract_resume_req'])
    || in_array((string)$trigger, ['manual_resume','watchdog_resume','auto_resume'], true);
$__startLine = $_rsmHint ? '⏯ ادامهٔ استخراج بک‌اند…' : '⏳ شروع استخراج بک‌اند...';
$__startLogs = [$__startLine, '⚙ موتور استخراج: ' . extractionEngineLabel($extractEngine),
    $autoPageMode
        ? '📄 هدف این اجرا: خودکار تا آخرین صفحهٔ واقعی'
        : ('📄 هدف این اجرا: '.$maxPages.' صفحه'.($maxPagesOverride>=0?' (snapshot صف)':' (پروفایل ذخیره‌شده)'))];
unset($_rsmHint);
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>true,'done'=>false,'max_pages'=>$pageSetting,'page_mode'=>$autoPageMode?'auto':'fixed','total'=>($phase==='detail'?0:$progressPageTarget),'current'=>0,'started_at'=>$startedAt,'queue_id'=>$queueId,'recent_log'=>$__startLogs,'total_log_count'=>count($__startLogs),'extracted'=>0,'new'=>0,'price_changed'=>0,'removed'=>0,'unchanged'=>0,'price_up'=>0,'price_down'=>0,'url'=>$url,'profile_name'=>$profile['name']??$profileKey]);
unset($__startLine, $__startLogs);

// v8.27: پاسخ زودهنگام فقط برای درخواست مرورگر معنا دارد تا کاربر منتظر
// نماند و بقیهٔ کار در پس‌زمینه ادامه یابد. وقتی کران‌جاب این تابع را
// صدا می‌زند نباید چیزی چاپ شود، وگرنه خروجی JSON دوتکه می‌شود.
if($emitEarlyResponse){
while(@ob_get_level())@ob_end_clean();
$initResp=json_encode(['ok'=>true,'started'=>true,'profile_key'=>$profileKey,'url'=>$url,'max_pages'=>$pageSetting,'page_mode'=>$autoPageMode?'auto':'fixed'],JSON_UNESCAPED_UNICODE);
header('Content-Type: application/json; charset=UTF-8');
header('Content-Length: '.strlen($initResp));
header('Connection: close');
echo $initResp;
if(function_exists('fastcgi_finish_request')){fastcgi_finish_request();}
@ob_flush();@flush();
}

/* v8.81: نقشهٔ محصولات اجرای قبلی، همین اول ساخته می‌شود.
   تا حالا فقط بعد از استخراج و صرفاً برای «آمار مقایسه» ساخته می‌شد و
   هیچ‌وقت با نتیجهٔ تازه ادغام نمی‌شد. چون $allProducts از نو و فقط از
   روی صفحهٔ فهرست پر می‌شود، هر چیزی که در فاز جزئیات به دست آمده بود —
   گالری، تنوع‌ها، توضیحات، SKU، برند — موقع ذخیره پاک می‌شد. */
$prevByKey=[];
if(!empty($prevProducts)){
$pfe=reset($prevProducts);
if(is_array($pfe)&&count($pfe)>=2&&is_string($pfe[0])){
foreach($prevProducts as $entry){if(is_array($entry)&&count($entry)>=2)$prevByKey[$entry[0]]=$entry[1];}
}else{$prevByKey=$prevProducts;}
}
/* Old malformed rows (notably imported Avand Printer placeholders) are removed
   from the source snapshot baseline without becoming destination retirements. */
$_invalidOld=0;
foreach($prevByKey as $_ivk=>$_ivp){if(!is_array($_ivp)||!extractedProductIsValid($_ivp)){unset($prevByKey[$_ivk]);$_invalidOld++;}}

$allProducts=[];$seenKeys=[];$nextUrl=null;$totalPages=0;$fetchFail='';
/* A single duplicate/empty page is not a trustworthy end marker on sources
   such as eMalls: transient cache/anti-bot responses often repeat page 1.
   Probe a short consecutive gap before declaring the catalogue finished. */
$_noFreshStreak=0;$_noFreshLimit=(function_exists('isEmallsUrl')&&isEmallsUrl($url))?5:3;
$_stoppedByEarlySignal=false;
$_lastGoodListPage=0;
$_hadListFetchErrors=false;
$_knownApiTotalPages=0;
$_detailSuppliesPrice=($_wantDetailAfterList && !empty($detailSelectors['price']) && empty($selectors['price']));
/* v10.122: ادامه از صفحه — اگر استخراج قبلی وسط فهرست مرده باشد */
$_listResume=false;
$_startPage=1;
$_resumeFrom=0;
$_listBudget=0;$_listDeadline=0;$_listRanOut=false;
$_listReachedLastPage=false;
$_pkStageInit=$profileKey!==''?$profileKey:profileKey($url);
if($phase!=='detail'){
    $_inc=extractListShouldResume($profile,(string)$trigger);
    $_stagedByKey=$_inc ? extractLoadListStaging($_pkStageInit) : [];
    $_hasStaged=count($_stagedByKey)>0;
    $_resumeReq=!empty($profile['_extract_resume_req'])
        || in_array((string)$trigger,['manual_resume','watchdog_resume','auto_resume','cron_resume'],true);
    if($_inc && $_hasStaged && ($phase==='all'||$phase==='list')){
        $_startPage=extractResumeStartPage($profile);
        if(!empty($profile['_extract_resume_from'])){
            $_rf=(int)$profile['_extract_resume_from'];
            if($_rf>0) $_startPage=max(1,$_rf);
        }
        $_lastGoodListPage=max(0,$_startPage-1);
        if($_startPage>1 || $_resumeReq){
            $_listResume=true;
            $_resumeFrom=$_startPage;
            /* v10.471: ادامه از حافظهٔ مرحله‌ای (staging) بدون دست‌زدن به محصولات قبلی پروفایل */
            $allProducts=$_stagedByKey;
            foreach($allProducts as $_k=>$_v)$seenKeys[$_k]=1;
            $nextUrl=trim((string)($profile['_extract_list_next_url']??''));
            if($nextUrl==='')$nextUrl=null;
        }
    } elseif(!$_inc) {
        extractClearListStaging($_pkStageInit);
    }
    unset($_stagedByKey);
    /* بودجهٔ زمانی فاز فهرست — مثل جزئیات، تمیز بایست و بعد ادامه بده */
    $cnList=loadConnections();
    $_listBudget=(int)($cnList['list_budget_sec']??0);
    if($_listBudget<=0){
        $_ini=(int)@ini_get('max_execution_time');
        // v10.181: console/PHP built-in deployments run with max_execution_time=0;
        // the previous 120s artificial budget made long catalogues pause every few pages.
        $_listBudget=$_ini>0?max(45,(int)($_ini*0.65)):900;
    }
    $_listBudget=max(40,min(3600,$_listBudget));
    if(isset($GLOBALS['_extractCronSliceSec']))$_listBudget=max(20,min($_listBudget,(int)$GLOBALS['_extractCronSliceSec']));
    $_pagePauseMs=max(0,min(5000,(int)($cnList['extract_page_pause_ms']??80)));
    $_listDeadline=time()+$_listBudget;
}
/* v9.01: در حالت «فقط جزئیات» صفحهٔ فهرست اصلاً باز نمی‌شود؛ محصولات
   همان‌هایی هستند که اجرای قبلی روی دیسک گذاشته. اینطور مرحلهٔ جزئیات
   یک گام مستقل است و یک بار دیگر کل فهرست را نمی‌گیرد. */
if($phase==='detail'){
    $_oldDetailCyclePre=trim((string)($profile['_extract_detail_cycle']??''));
    $_oldStagePre=(string)($profile['_extract_stage']??'');
    $_stagedDetailPl=($_oldDetailCyclePre!=='' && in_array($_oldStagePre,['detail','list_done','stopped'],true))
        ? extractLoadListStagingPayload($_pkStageInit) : ['products'=>[],'stage_cycle'=>''];
    if(!empty($_stagedDetailPl['products']) && (string)($_stagedDetailPl['stage_cycle']??'')===$_oldDetailCyclePre){
        $allProducts=(array)$_stagedDetailPl['products'];
    } else {
        $allProducts=$prevByKey;
    }
    unset($_stagedDetailPl,$_oldDetailCyclePre,$_oldStagePre);
    foreach($allProducts as $_k=>$_v)$seenKeys[$_k]=1;
    $totalPages=0;
    if(empty($allProducts)){
        writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'total'=>0,'current'=>0,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'recent_log'=>['⏭ محصولی برای گرفتن جزئیات نیست — اول استخراج فهرست را اجرا کنید'],'total_log_count'=>1,'extracted'=>0,'products_saved'=>false]);
        $queue=extractReadQueue();
        /* v9.09: این مسیر ردیف را بدون هیچ توضیحی می‌بست. مودال آن‌وقت
           به پیام عمومی «این مرحله چیزی برای انجام نداشت» می‌افتاد —
           دقیقاً همان چیزی که کاربر دید، در حالی که علت مشخص بود:
           پروفایل روی دیسک محصولی ندارد. */
        foreach($queue['entries'] as &$qe){if(($qe['id']??'')===$queueId){$qe['status']='done';$qe['done_at']=time();$qe['products_count']=0;$qe['detail_skip_why']='no_products';$qe['detail_total']=0;$qe['detail_no_link']=0;$qe['detail_already']=0;break;}}unset($qe);
        extractWriteQueue($queue);
        extractLockRelease($queueId);   // v10.32 (۴۵ب)
        return ['__early_sent'=>$emitEarlyResponse,'ok'=>true,'queue_id'=>$queueId,'extracted'=>0,'phase'=>'detail','note'=>'فهرستی وجود ندارد'];
    }
}
/* v9.44: جزئیات «هم‌زمان با» استخراج هر محصول انجام می‌شود — بجای فاز ۲ی جداگانه.
   چون کران‌جاب (cron-job.org) منتظر کارِ پس‌زمینه نمی‌ماند، جزئیات نباید در
   نوبتی جدا و بعداً اجرا شود که ممکن است هرگز به آن نرسد. اینجا هر محصول
   به‌محض گرفتن از فهرست، صفحهٔ خودش هم باز و کامل می‌شود (فقط اگر ناقص باشد —
   دامنهٔ «فقط ناقص‌ها»). */
$galleryCfg=galleryEffectiveCfgForUrl(galleryNormalizeCfg($profile['gallery']??[]),$url);
$_wantKeys=[];
foreach($detailSelectors as $_f=>$_sv){ if(!empty($_sv))$_wantKeys[]=$_f; }
$_inlineDetailDone=0;   // شمارندهٔ جزئیاتِ درجایِ همین اجرا (برای چک‌پوینت)
$_inlineDetailOk=0; $_inlineDetailFail=0; $_inlineDetailFields=0;
$_inlineGalleryFound=0; $_inlineGalleryImgs=0; $_inlineVarFound=0;
$pkFinal=$profileKey!==''?$profileKey:profileKey($url);
$_oldDetailCycle=trim((string)($profile['_extract_detail_cycle']??''));
$_oldStage=(string)($profile['_extract_stage']??'');
$_detailCycle=($phase==='detail'&&in_array($_oldStage,['detail','stopped'],true)&&$_oldDetailCycle!=='')
    ? $_oldDetailCycle : ('dc_'.time().'_'.substr(md5($queueId),0,8));
if($_listResume && $_startPage>1){
    writeProgress(EXTRACT_PROGRESS_FILE,['running'=>true,'done'=>false,'total'=>$progressPageTarget,'current'=>$_startPage,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'recent_log'=>[
        '▶️ ادامهٔ استخراج از صفحه '.$_startPage.' (یک صفحه قبل از محل گیر)',
        '   • محصولات حفظ‌شده: '.count($allProducts),
        '   • سقف زمانی این نوبت فهرست: '.$_listBudget.' ثانیه',
    ],'total_log_count'=>3,'extracted'=>count($allProducts),'page'=>$_startPage,'resuming'=>true,'resume_from'=>$_startPage]);
}
for($page=$_startPage;$phase!=='detail'&&$page<=$maxPages;$page++){
/* Each parallel row consumes only its own stop signal. */
if(extractStopRequestedForQueue($queueId,true)){
$pkTmp=$profileKey!==''?$profileKey:profileKey($url);
extractSaveListStaging($pkTmp,$allProducts,[
    '_extract_stage'=>'stopped','_extract_stage_at'=>time(),
    '_extract_resume_phase'=>'list','_extract_list_incomplete'=>true,
    '_extract_list_page_try'=>$page,'_extract_list_page_ok'=>max(0,$page-1),
    '_extract_resume_from'=>max(1,$page-1),
    '_extract_list_next_url'=>$nextUrl?:'','_extract_list_last_url'=>'']);
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'cancelled'=>true,'stopped'=>true,'partial'=>true,'products_saved'=>false,
    'resumable'=>true,'resume_phase'=>'list','total'=>count($allProducts),'current'=>$page,'page'=>$page,
    'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'profile_key'=>$pkTmp,
    'recent_log'=>['⏹ توقف کاربر پیش از آخرین صفحه — نتایج قبلی دست‌نخورده ماند','   • '.count($allProducts).' محصول در حافظهٔ موقت ادامه نگهداری شد'],'total_log_count'=>2,'extracted'=>count($allProducts)]);
$queue=extractReadQueue();
foreach($queue['entries'] as &$qe){if(($qe['id']??'')===$queueId){$qe['status']='paused';$qe['done_at']=time();$qe['paused_at']=time();$qe['updated_at']=time();$qe['resumable']=true;$qe['resume_needed']=1;$qe['partial']=true;$qe['stopped_by_user']=true;$qe['resume_phase']='list';$qe['resume_page']=max(1,$page-1);$qe['products_count']=count($allProducts);$qe['error']='با دکمهٔ توقف متوقف شد؛ checkpoint حفظ شد';unset($qe['stop_requested'],$qe['stop_requested_at']);break;}}unset($qe);
extractWriteQueue($queue);
extractLockRelease($queueId);
return ['__early_sent'=>$emitEarlyResponse, 'ok'=>true,'queue_id'=>$queueId,'cancelled'=>true,'extracted'=>count($allProducts),'partial'=>true,'products_saved'=>false];
}
/* v10.122: بودجهٔ فهرست — تمیز بایست تا نوبت بعد از صفحهٔ قبلی ادامه دهد */
if($_listDeadline>0 && $page>$_startPage && time()>=$_listDeadline && count($allProducts)>0){
    $_listRanOut=true;
    extractSaveListStaging($pkFinal,$allProducts,[
        '_extract_stage'=>'list','_extract_stage_at'=>time(),
        '_extract_want_detail'=>$_wantDetailAfterList,
        '_extract_list_incomplete'=>true,
        '_extract_list_page_ok'=>max(0,$page-1),
        '_extract_list_page_try'=>$page,
        '_extract_list_next_url'=>$nextUrl?:'',
        '_extract_list_last_url'=>'',
        '_extract_resume_from'=>max(1,$page-1),
    ]);
    writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'ran_out'=>true,'resumable'=>true,'products_saved'=>false,
        'resume_page'=>max(1,$page-1),'total'=>$progressPageTarget,'current'=>$page,'started_at'=>$startedAt,
        'last_progress_ts'=>time(),'queue_id'=>$queueId,'extracted'=>count($allProducts),
        'recent_log'=>['⏸ سقف زمانی فهرست — ادامه از صفحه '.max(1,$page-1),
            '   • '.count($allProducts).' محصول در حافظهٔ مرحله‌ای نگه داشته شد (نتایج قبلی دست‌نخورده است)',
            '   • پس از رسیدن به پایان آخرین صفحه، محصولات نهایی ثبت می‌شوند'],
        'total_log_count'=>3,'page'=>$page,'profile_key'=>$pkFinal]);
    $queue=extractReadQueue();
    foreach($queue['entries'] as &$qe){
        if(($qe['id']??'')===$queueId){
            $qe['status']='paused';$qe['done_at']=time();
            $qe['resumable']=true;$qe['resume_page']=max(1,$page-1);
            $qe['products_count']=count($allProducts);
            $qe['error']='سقف زمانی — ادامه از صفحه '.max(1,$page-1);
            break;
        }
    }unset($qe);
    extractWriteQueue($queue);
    extractLockRelease($queueId);
    return ['__early_sent'=>$emitEarlyResponse,'ok'=>true,'queue_id'=>$queueId,'extracted'=>count($allProducts),
        'ran_out'=>true,'resume_needed'=>true,'resume_page'=>max(1,$page-1),'partial'=>true,
        'products_saved'=>false,'profile_key'=>$pkFinal];
}
/* ثبت صفحه‌ای که الان تلاش می‌شود — برای resume = try-1 (بدون دست زدن به products) */
if($pkFinal!==''){
    extractSaveListStaging($pkFinal,null,[
        '_extract_stage'=>'list','_extract_stage_at'=>time(),
        '_extract_list_incomplete'=>true,
        '_extract_list_page_try'=>$page,
    ]);
}
if($page===1){$pageUrl=$url;}
elseif($pagType==='next_selector'&&$nextUrl){$pageUrl=$nextUrl;}
elseif($pagType==='next_selector'&&!$nextUrl){if($page>1&&count($allProducts)>0){$totalPages=max(1,$page-1);$_listReachedLastPage=true;}break;}
else{$pageUrl=build_page_url_custom($url,$url,$page,$pagType,$pagVal);}
/* روی resume با next_selector: اگر last_url ذخیره شده و page==start، از آن شروع کن */
if($_listResume && $page===$_startPage && $pagType==='next_selector'){
    $_lu=trim((string)($profile['_extract_list_last_url']??''));
    if($_lu!=='')$pageUrl=$_lu;
}

/* v10.173: مانند مسیر SSE — فهرست با fetch_html_smart واکشی می‌شود تا
   سایت‌های SPA (پوستهٔ خالی بدون رندر) هم محصول بدهند. */
$res=fetch_html_for_engine($pageUrl,20,$extractEngine,$selectors);
$totalPages=$page;
/* v10.177: نشانیِ کامل + کدِ HTTP در لاگ — نشانی‌های بلندِ پارسی ۶۰ کاراکترِ
   اول هیچ‌چیزی نشان نمی‌دادند و دیباگِ صفحه‌بندی کور می‌ماند.
   v10.178: وقتی سرور نشانی را ریدایرکت کرد (نهایی ≠ خواسته‌شده) نقشهٔ کامل
   همین‌جا چاپ می‌شود — الگوی بی‌معنی به‌وضوح دیده می‌شود. */
$_finUrl=(string)($res['url']??'');
$_finNote=($_finUrl!=='' && rtrim($_finUrl,'/')!==rtrim($pageUrl,'/')) ? ('  ← نهایی: '.$_finUrl) : '';
$logs=['📄 صفحه '.$page.': '.($res['ok']?'✓':'✗').' (HTTP '.(int)($res['code']??0).') — '.$pageUrl.$_finNote];
unset($_finUrl,$_finNote);
if(!$res['ok']){
$logs[]='❌ خطا: '.mb_substr($res['error']??'HTTP error',0,80);
/* v10.280: 404/410 بعد از حداقل یک صفحهٔ موفق، خطای اتصال نیست؛ پاسخ
   استانداردِ بسیاری از فروشگاه‌ها برای «صفحهٔ بعدی وجود ندارد» است.
   قبلاً صفحهٔ ۵۷ و ۵۸ آوند هر دو 404 می‌شدند و ۱۱۰۳ محصولِ کامل به‌غلط
   failed/resumable ثبت می‌شد. اینجا پایان طبیعی اعلام می‌کنیم و اجازه
   می‌دهیم final compare/save عادی پایین اجرا شود. */
$_httpCode=(int)($res['code']??0);
if($page>1 && count($allProducts)>0 && in_array($_httpCode,[404,410],true)){
    $totalPages=max(1,$page-1);
    $_listReachedLastPage=true;
    if($page<$maxPages) $_stoppedByEarlySignal=true;
    $logs[]='🏁 HTTP '.$_httpCode.' در صفحهٔ '.$page.' — صفحهٔ قبلی آخرین صفحه بود؛ استخراج کامل است.';
    $_qEnd=extractReadQueue();foreach($_qEnd['entries'] as &$_qeEnd){if(($_qeEnd['id']??'')!==$queueId)continue;
        $_qeEnd['pag_stop_reason']='پایان طبیعی صفحه‌بندی: HTTP '.$_httpCode.' در صفحهٔ '.$page;
        $_qeEnd['pag_stop_url']=$pageUrl;$_qeEnd['resumable']=false;$_qeEnd['resume_page']=0;break;}unset($_qeEnd);extractWriteQueue($_qEnd);
    writeProgress(EXTRACT_PROGRESS_FILE,['running'=>true,'done'=>false,'total'=>$progressPageTarget,'current'=>$totalPages,
        'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'recent_log'=>$logs,
        'total_log_count'=>$page+1,'extracted'=>count($allProducts),'page'=>$totalPages,'page_ok'=>true,
        'resumable'=>false,'resume_page'=>0,'natural_end'=>true,'profile_key'=>$pkFinal]);
    unset($_qEnd,$_httpCode);break;
}
unset($_httpCode);
$_hadListFetchErrors=true;
// v8.91: علت شکست صفحهٔ اول را نگه دار تا محافظِ پایین بداند
// «صفر محصول» به‌خاطر قطعی بوده، نه به‌خاطر خالی شدن فروشگاه.
if($page===1)$fetchFail='صفحهٔ اول باز نشد: '.mb_substr($res['error']??('HTTP '.(int)($res['code']??0)),0,60);
extractLockTouch($queueId);
if($page>1 && count($allProducts)>0){
    $_rpF=max(1,$page-1);
    extractSaveListStaging($pkFinal,$allProducts,[
        '_extract_stage'=>'list','_extract_stage_at'=>time(),
        '_extract_list_incomplete'=>true,
        '_extract_list_page_try'=>$page,
        '_extract_list_page_ok'=>$_rpF,
        '_extract_resume_from'=>$_rpF,
        '_extract_list_last_url'=>$pageUrl,
    ]);
}
if(!isset($_pageFailStreak))$_pageFailStreak=0;
$_pageFailStreak++;
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>true,'done'=>false,'products_saved'=>false,'total'=>$progressPageTarget,'current'=>$page,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'recent_log'=>$logs,'total_log_count'=>$page,'extracted'=>count($allProducts),'page'=>$page,'page_ok'=>false,'resumable'=>$page>1,'resume_page'=>max(1,$page-1)]);
if($page===1)break;
if($_pageFailStreak>=2 && count($allProducts)>0){
    $_rpF=max(1,$page-1);
    writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'products_saved'=>false,'error'=>'صفحات متوالی باز نشد','resumable'=>true,'resume_page'=>$_rpF,'extracted'=>count($allProducts),'page'=>$page,'queue_id'=>$queueId,'started_at'=>$startedAt,'last_progress_ts'=>time(),'recent_log'=>array_merge($logs,['⏸ دو صفحه پشت‌سرهم شکست — نتایج قبلی دست‌نخورده ماند؛ ادامه از صفحه '.$_rpF]),'total_log_count'=>$page+1,'profile_key'=>$pkFinal]);
    $queue=extractReadQueue();
    foreach($queue['entries'] as &$qe){
        if(($qe['id']??'')===$queueId){
            $qe['status']='failed';$qe['done_at']=time();$qe['resumable']=true;$qe['resume_page']=$_rpF;
            $qe['products_count']=count($allProducts);
            $qe['error']='صفحه باز نشد — ادامه از '.$_rpF;break;
        }
    }unset($qe);
    extractWriteQueue($queue);
    extractLockRelease($queueId);
    return ['__early_sent'=>$emitEarlyResponse,'ok'=>true,'queue_id'=>$queueId,'extracted'=>count($allProducts),'partial'=>true,'resume_needed'=>true,'resume_page'=>$_rpF,'products_saved'=>false,'profile_key'=>$pkFinal];
}
continue;
}
$_pageFailStreak=0;
/* v10.451 / v10.471: تشخیص فوری پایان صفحه‌بندی API اسنپ‌شاپ و دیجی‌کالا */
if($page>1 && count($allProducts)>0 && (!empty($res['snappshop_end_of_pages']) || !empty($res['digikala_end_of_pages'])) && (int)($res['jina_product_count']??0)===0){
    $totalPages=max(1,$page-1);
    $_listReachedLastPage=true;
    $_isDkEnd=!empty($res['digikala_end_of_pages']);
    $_snLim=(int)($_isDkEnd ? ($res['digikala_total_pages']??$totalPages) : ($res['snappshop_total_pages']??$totalPages));
    $_srcEndLbl=$_isDkEnd ? 'دیجی‌کالا' : 'اسنپ‌شاپ';
    $logs[]='🏁 پایان طبیعی صفحه‌بندی '.$_srcEndLbl.' در صفحهٔ '.$totalPages.($_snLim>0?' (سقف دسته‌بندی: '.$_snLim.' صفحه)':'').' — استخراج لیست کامل شد.';
    $_qEnd=extractReadQueue();foreach($_qEnd['entries'] as &$_qeEnd){if(($_qeEnd['id']??'')!==$queueId)continue;
        $_qeEnd['pag_stop_reason']='پایان طبیعی صفحه‌بندی '.$_srcEndLbl.' در صفحهٔ '.$totalPages;
        $_qeEnd['pag_stop_url']=$pageUrl;$_qeEnd['resumable']=false;$_qeEnd['resume_page']=0;break;}unset($_qeEnd);extractWriteQueue($_qEnd);
    writeProgress(EXTRACT_PROGRESS_FILE,['running'=>true,'done'=>false,'total'=>$progressPageTarget,'current'=>$totalPages,
        'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'recent_log'=>$logs,
        'total_log_count'=>$page+1,'extracted'=>count($allProducts),'page'=>$totalPages,'page_ok'=>true,
        'resumable'=>false,'resume_page'=>0,'natural_end'=>true,'profile_key'=>$pkFinal]);
    unset($_qEnd,$_snLim,$_isDkEnd,$_srcEndLbl);break;
}

$_usedEngine='';
$pageProducts=parse_list_by_engine($res['html'],$res['url'],$selectors,$extractEngine,$_usedEngine);
if($_usedEngine!=='' && ($_usedEngine!==$extractEngine || $page===1)){
    $logs[]='⚙ موتورِ استفاده‌شده: '.extractionEngineLabel($_usedEngine);
}

/* v10.274: ایمالز گاهی در یکی از transportهای fallback برای ~page~N همان
   محتوای صفحهٔ ۱ را برمی‌گرداند. URL درست است ولی محافظِ duplicate اجرای
   سالم را همان صفحهٔ ۲ تمام می‌کرد. پیش از تصمیم به توقف، صفحهٔ بدون محصول
   تازه را با transportهای مستقل و بدون زنجیرهٔ cache دوباره می‌خوانیم؛ فقط
   پاسخی پذیرفته می‌شود که واقعاً حداقل یک productKey تازه داشته باشد. */
$_freshPageRows=static function(array $rows,array $seen):int{$n=0;foreach($rows as $k=>$_p)if(!isset($seen[$k]))$n++;return $n;};
if($page>$_startPage && function_exists('isEmallsUrl') && isEmallsUrl($pageUrl)
    && $_freshPageRows($pageProducts,$seenKeys)===0){
    $logs[]='♻️ ایمالز: پاسخ صفحهٔ '.$page.' تکراری بود؛ بازخوانی مستقل پیش از توقف…';
    $_retryFetchers=[];
    $_retryFetchers['direct']=static function()use($pageUrl){
        $net=['ipv4'=>true,'hosts'=>'','fallback'=>false,'resolve_ip'=>'','doh_url'=>'','worker_url'=>'','proxy'=>'','proxy_type'=>'http','proxy_auth'=>''];
        return srcNetFetchAttempt($pageUrl,25,$net,'direct');
    };
    if(function_exists('emallsPhpStreamFetch'))$_retryFetchers['php-stream']=static fn()=>emallsPhpStreamFetch($pageUrl,25);
    if(function_exists('fetch_html_jina_reader'))$_retryFetchers['jina-reader']=static fn()=>fetch_html_jina_reader($pageUrl,25,[]);
    foreach($_retryFetchers as $_retryMode=>$_retryFn){
        usleep(250000);
        try{$_rr=$_retryFn();}catch(Throwable $_re){$_rr=['ok'=>false,'error'=>$_re->getMessage()];}
        if(empty($_rr['ok'])||trim((string)($_rr['html']??''))===''){
            $logs[]='   • '.$_retryMode.': ناموفق '.mb_substr((string)($_rr['error']??''),0,70);continue;
        }
        $_retryUsed='';$_retryRows=parse_list_by_engine((string)$_rr['html'],(string)($_rr['url']??$pageUrl),$selectors,$extractEngine,$_retryUsed);
        $_retryFresh=$_freshPageRows($_retryRows,$seenKeys);
        $logs[]='   • '.$_retryMode.': '.count($_retryRows).' محصول · '.$_retryFresh.' تازه';
        if($_retryFresh>0){$res=$_rr;$pageProducts=$_retryRows;$_usedEngine=$_retryUsed;$logs[]='✅ صفحهٔ '.$page.' با '.$_retryMode.' بازیابی شد';break;}
    }
    unset($_retryFetchers,$_retryMode,$_retryFn,$_rr,$_retryRows,$_retryFresh,$_retryUsed);
}
unset($_freshPageRows);

/* 🔍 v9.88 — تشخیصِ «مرورگر ۲۰ تا نشان می‌دهد ولی استخراج کم می‌آورد».
   انتخابگرِ بصری سایت را داخل iframe و با جاوااسکریپتِ کامل بارگذاری می‌کند،
   پس شمارشِ «N مورد مشابه» روی سندِ *رندرشده* است. اما استخراج با cURL انجام
   می‌شود که جاوااسکریپت اجرا نمی‌کند و فقط HTML خامِ سرور را می‌گیرد. در
   سایت‌های SPA / اسکرول بی‌نهایت / لِیزی‌لود، آن HTML خام یا هیچ کارتی ندارد
   یا فقط چند کارتِ اول را دارد. آن‌وقت سلکتور کاملاً درست است ولی خروجی صفر
   یا ۱ محصول می‌شود — بدون هیچ توضیحی. اینجا اختلاف را صریح گزارش می‌کنیم. */
if ($page === 1 && !empty($selectors['container'])) {
    $_diagN = 0;
    if (!empty($selectors['container'])) {
        [$_dDom, $_dXp] = load_dom($res['html']);
        $_dq = cssToXpath($selectors['container'], true);
        $_dn = $_dq ? @$_dXp->query($_dq) : null;
        if (!$_dn || $_dn->length === 0) {
            $_dq = cssToXpath($selectors['container'], false);
            $_dn = $_dq ? @$_dXp->query($_dq) : null;
        }
        $_diagN = $_dn ? $_dn->length : 0;
    }
    $GLOBALS['_extractDiag'] = [
        'containers_in_raw_html' => $_diagN,
        'products_parsed'        => count($pageProducts),
        'html_bytes'             => strlen($res['html']),
    ];
    if ($_diagN === 0) {
        $logs[] = '⚠️ سلکتور ظرف در HTMLِ خامِ سرور هیچ تطبیقی ندارد (۰ عدد).';
        $logs[] = '⚠️ یعنی صفحه محتوایش را با جاوااسکریپت می‌سازد؛ cURL آن را نمی‌بیند.';
    } elseif ($_diagN < 3 && $_diagN > 0) {
        $logs[] = '⚠️ در HTMLِ خام فقط ' . $_diagN . ' ظرف هست (مرورگر بیشتر نشان می‌دهد).';
        $logs[] = '⚠️ بقیهٔ کارت‌ها با اسکرول/جاوااسکریپت بارگذاری می‌شوند.';
    }
}

$newCount=0;
foreach($pageProducts as $key=>$p){
if(isset($seenKeys[$key]))continue;
$seenKeys[$key]=1;
$p['_detail_new_pending']=1;
$allProducts[$key]=$p;
$newCount++;
/* v9.44: استخراج جزئیاتِ همین محصول، همین‌لحظه (درجا) — بجای فاز ۲ی جداگانه.
   فقط اگر ناقص باشد (دامنهٔ «فقط ناقص‌ها»): گالری روشن است یا فیلدی خواسته‌شده
   هنوز خالی است یا عکس/قیمت ندارد. برای تصمیم‌گیری، دادهٔ اجرای قبلی هم ادغام
   می‌شود تا محصولی که قبلاً کامل شده دوباره باز نشود. صفحهٔ محصول باز و
   فیلدها/گالری/تنوع‌ها استخراج می‌شود؛ بعد هر محصول چک‌پوینت می‌شود تا اگر
   هاست وسط کار کشته شد، محصولاتِ تا آن لحظه کامل روی دیسک بمانند. */
/* v9.72: رفعِ «استخراج خودکار جزئیات» — این بلوکِ درجا داخلِ حلقهٔ فهرست بود و
   برای فازِ list هم اجرا می‌شد (یعنی هر کران صفحهٔ جزئیاتِ محصولات را باز می‌کرد).
   حالا فقط وقتی اجرا می‌شود که فاز list نباشد (یعنی all/detail = دکمهٔ دستی). */
if($phase!=='list'){
if($_detailExtractMode==='inline'){
$_mrg = (isset($prevByKey[$key]) && is_array($prevByKey[$key]))
    ? extractMergeDetail($p, $prevByKey[$key]) : $p;
$_galDoneNow = $galleryCfg['enabled']
    && count($p['images'] ?? ($_mrg['images'] ?? [])) > 1
    && !empty($p['image'] ?? $_mrg['image'] ?? '')
    && !empty($p['price'] ?? $_mrg['price'] ?? '');
$_fieldMissingNow = false;
foreach ($_wantKeys as $_wk) {
    if ($_wk === 'variations') { if (empty($_mrg['variations'])) { $_fieldMissingNow = true; break; } continue; }
    $_cur = $_mrg[$_wk] ?? '';
    if (is_array($_cur) ? empty($_cur) : (trim((string)$_cur) === '')) { $_fieldMissingNow = true; break; }
}
if (!($_galDoneNow && !$_fieldMissingNow)) {
    $_inlineDetailDone++;
    $_inlineTitle = mb_substr((string)($p['title'] ?? $key), 0, 45);
    msAlive('جزئیات: ' . $_inlineTitle);   /* v10.61 (۷۵) */
    extractLockTouch($queueId);
    if ($_inlineDetailDone === 1 || $_inlineDetailDone % 3 === 0) {
        $_inlineLogs = array_slice(array_merge($logs, ['🔍 جزئیات درجای صفحه '.$page.' — محصول '.$_inlineDetailDone.': '.$_inlineTitle]), -12);
        writeProgress(EXTRACT_PROGRESS_FILE, array_merge(['running'=>true,'done'=>false,'total'=>$progressPageTarget,'current'=>$page,
            'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'profile_key'=>$pkFinal,'detail_extract_mode'=>$_detailExtractMode,'recent_log'=>$_inlineLogs,
            'total_log_count'=>$page+$_inlineDetailDone,'extracted'=>count($allProducts),'phase'=>'list_detail',
            'page'=>$page,'inline_detail_current'=>$_inlineDetailDone], extractLiveCompare($allProducts,$livePrevMap)));
    }
    $_inlineRes=extractProductDetailInline($allProducts, $key, $detailSelectors, $galleryCfg, false);
    if(!empty($_inlineRes['ok'])){
        $_inlineDetailOk++;
        $_inlineDetailFields+=(int)($_inlineRes['fields']??0);
        if((int)($_inlineRes['imgs']??0)>1){$_inlineGalleryFound++;$_inlineGalleryImgs+=(int)$_inlineRes['imgs'];}
        if((int)($_inlineRes['vars']??0)>0)$_inlineVarFound++;
        $allProducts[$key]['_inlineDetailDone']=true;
        $allProducts[$key]['_detail_cycle']=$_detailCycle;
        unset($allProducts[$key]['_detail_new_pending']);
        if((int)($_inlineRes['fields']??0)>0||(int)($_inlineRes['imgs']??0)>0||(int)($_inlineRes['vars']??0)>0)
            $allProducts[$key]['_detail_checked_at']=time();
    } else {
        $_inlineDetailFail++;
    }
    extractLockTouch($queueId);
    extractSaveListStaging($pkFinal, $allProducts,
        ['_extract_stage' => 'list', '_extract_stage_at' => time(),
         '_extract_list_incomplete' => true,
         '_extract_detail_cycle' => $_detailCycle,
         '_extract_detail_done' => $_inlineDetailDone, '_extract_detail_total' => 0]);
} else {
    $allProducts[$key] = $_mrg;
    $allProducts[$key]['_detail_cycle'] = $_detailCycle;
    unset($allProducts[$key]['_detail_new_pending']);
}
}
}
}
$logs[]='✓ +'.($newCount).' محصول (کل: '.count($allProducts).')';
// v8.22: مقایسهٔ زنده — شمارنده‌ها و لیست‌ها همان لحظه محاسبه می‌شوند
$liveCmp=extractLiveCompare($allProducts,$livePrevMap);
msAlive('صفحه ' . $page . ' — ' . count($allProducts) . ' محصول');   /* v10.61 (۷۵) */
writeProgress(EXTRACT_PROGRESS_FILE,array_merge(['running'=>true,'done'=>false,'products_saved'=>false,'total'=>$progressPageTarget,'current'=>$page,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'profile_key'=>$pkFinal,'detail_extract_mode'=>$_detailExtractMode,'phase'=>($_detailExtractMode==='inline'&&$phase!=='list'?'list_detail':'list'),'recent_log'=>$logs,'total_log_count'=>$page,'extracted'=>count($allProducts),'page'=>$page,'page_ok'=>true,'page_new'=>$newCount,'page_total'=>count($allProducts),'resumable'=>true,'resume_page'=>max(1,$page)],$liveCmp));
if($pagType==='next_selector'&&!empty($pagVal)){
[$dom,$xp]=load_dom($res['html']);
$xpath=cssToXpath($pagVal);
$nodes=@$xp->query($xpath);
if($nodes&&$nodes->length&&$nodes->item(0) instanceof DOMElement){
$href=$nodes->item(0)->getAttribute('href');
if($href&&$href!=='#'&&!preg_match('~^(javascript:|data:)~i',$href)){
$nextUrl=make_absolute_url($href,$res['url']);
}else{$nextUrl=null;}
}else{$nextUrl=null;}
}
/* v10.122 / v10.471: ذخیرهٔ مرحله‌ای بعد از nextUrl بدون دست‌زدن به محصولات قبلی پروفایل */
extractLockTouch($queueId);
extractSaveListStaging($pkFinal,$allProducts,[
    '_extract_stage'=>'list','_extract_stage_at'=>time(),
    '_extract_want_detail'=>$_wantDetailAfterList,
    '_extract_list_incomplete'=>true,
    '_extract_list_page_ok'=>$page,
    '_extract_list_page_try'=>$page,
    '_extract_list_next_url'=>is_string($nextUrl)?(string)$nextUrl:((string)($nextUrl??'')),
    '_extract_list_last_url'=>$pageUrl,
    '_extract_resume_from'=>$page,
    '_extract_resume_req'=>0,
]);
$_qLive=extractReadQueue();
foreach($_qLive['entries'] as &$_qeL){
    if(($_qeL['id']??'')===$queueId){
        $_qeL['resume_page']=$page;$_qeL['resumable']=true;
        $_qeL['products_count']=count($allProducts);$_qeL['current']=$page;$_qeL['total']=$progressPageTarget;
        break;
    }
}unset($_qeL);
extractWriteQueue($_qLive);
$_apiTotPagesNow = max((int)($res['snappshop_total_pages']??0), (int)($res['digikala_total_pages']??0));
if($_apiTotPagesNow>$_knownApiTotalPages) $_knownApiTotalPages=$_apiTotPagesNow;
if($newCount>0) $_lastGoodListPage=$page;
if(count($allProducts)>0 && $_apiTotPagesNow>0 && $page>=$_apiTotPagesNow && $page<=$maxPages){
    $_snTotP=$_apiTotPagesNow;
    $totalPages=$page;
    $_listReachedLastPage=true;
    $_apiSrcLbl=((int)($res['digikala_total_pages']??0)>0)?'دیجی‌کالا':'اسنپ‌شاپ';
    $logs[]='🏁 آخرین صفحهٔ دسته‌بندی '.$_apiSrcLbl.' (صفحهٔ '.$page.' از '.$_snTotP.') کامل شد — ورود به مرحلهٔ بعد.';
    $_qEnd2=extractReadQueue();foreach($_qEnd2['entries'] as &$_qeEnd2){if(($_qeEnd2['id']??'')!==$queueId)continue;
        $_qeEnd2['pag_stop_reason']='آخرین صفحهٔ دسته‌بندی '.$_apiSrcLbl.' (صفحهٔ '.$page.' از '.$_snTotP.')';
        $_qeEnd2['pag_stop_url']=$pageUrl;$_qeEnd2['resumable']=false;$_qeEnd2['resume_page']=0;break;}unset($_qeEnd2);extractWriteQueue($_qEnd2);
    writeProgress(EXTRACT_PROGRESS_FILE,['running'=>true,'done'=>false,'total'=>$progressPageTarget,'current'=>$page,
        'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'recent_log'=>$logs,
        'total_log_count'=>$page+1,'extracted'=>count($allProducts),'page'=>$page,'page_ok'=>true,
        'resumable'=>false,'resume_page'=>0,'natural_end'=>true,'profile_key'=>$pkFinal]);
    unset($_qEnd2,$_snTotP,$_apiTotPagesNow,$_apiSrcLbl);break;
}
unset($_apiTotPagesNow);
$_noFreshStreak=$newCount===0?($_noFreshStreak+1):0;
/* v10.177: توقفِ صفحه‌بندی به‌خاطر «صفرِ تازه» دیگر خاموش نیست — علت و نشانی
   ثبت می‌شود تا معلوم شود سرور نشانه را نادیده گرفت/چالش داد/فهرست تمام شد.
   v10.178: اگر نهایی به نشانیِ پایه برگشته، مستقیم بگو الگو از نگاه سرور غلط است. */
if($page>$_startPage&&$newCount===0){
    if($_noFreshStreak<$_noFreshLimit && $page<$maxPages){
        $logs[]='⚠️ صفحهٔ '.$page.' محصول تازه نداشت؛ پایان قطعی نیست — بررسی صفحهٔ بعد ('
            .$_noFreshStreak.'/'.$_noFreshLimit.')';
        writeProgress(EXTRACT_PROGRESS_FILE,['running'=>true,'done'=>false,'products_saved'=>false,'max_pages'=>$pageSetting,'page_mode'=>$autoPageMode?'auto':'fixed','total'=>$progressPageTarget,
            'current'=>$page,'page'=>$page,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,
            'recent_log'=>$logs,'total_log_count'=>count($logs),'extracted'=>count($allProducts),
            'empty_page_streak'=>$_noFreshStreak,'empty_page_limit'=>$_noFreshLimit,'profile_key'=>$pkFinal]);
        $_qProbe=extractReadQueue();foreach($_qProbe['entries']as&$_qeProbe){if(($_qeProbe['id']??'')!==$queueId)continue;
            $_qeProbe['pag_probe_streak']=$_noFreshStreak;$_qeProbe['pag_probe_page']=$page;break;}unset($_qeProbe);extractWriteQueue($_qProbe);
        if(isset($_pagePauseMs)&&$_pagePauseMs>0)usleep($_pagePauseMs*1000);
        continue;
    }
    if(count($allProducts)>0) $_listReachedLastPage=true;
    if($page<$maxPages) $_stoppedByEarlySignal=true;
    $logs[]='⛳ '.$_noFreshStreak.' صفحهٔ پیاپی محصولِ تازه‌ای نداشت — صفحه‌بندی متوقف شد.';
    if($pagType!=='next_selector'){
        $logs[]='   • نشانیِ امتحان‌شده: '.$pageUrl;
        $_fin2=rtrim((string)($res['url']??''),'/');
        if($_fin2!=='' && $_fin2!==rtrim($pageUrl,'/') && strcasecmp($_fin2,rtrim($url,'/'))===0){
            $logs[]='   • تشخیص: سرور صفحهٔ '.$page.' را به نشانیِ صفحهٔ ۱ ریدایرکت کرد — الگوی «'.$pagType.'» ('.($pagVal!==''?$pagVal:'(پیش‌فرض)').') برای این سایت معتبر نیست؛ با 🧪 «آزمایش صفحه‌بندی» الگوی درست را پیدا کنید.';
        }else{
            $logs[]='   • اگر این نشانی در مرورگر محتوای متفاوتی دارد، با 🧪 «آزمایش صفحه‌بندی» کنارِ فرم علت دقیق (چالش ربات/ریدایرکت/الگوی نادرست) را ببینید.';
        }
        unset($_fin2);
    }
    writeProgress(EXTRACT_PROGRESS_FILE,['running'=>($phase!=='list'),'done'=>($phase==='list'),'error'=>null,'resumable'=>false,'extracted'=>count($allProducts),'page'=>$page,'queue_id'=>$queueId,'started_at'=>$startedAt,'last_progress_ts'=>time(),'recent_log'=>$logs,'total_log_count'=>count($logs),'profile_key'=>$pkFinal]);
    $queue=extractReadQueue();
    foreach($queue['entries'] as &$qe){
        if(($qe['id']??'')===$queueId){
            $qe['pag_stop_reason']=$_noFreshStreak.' صفحهٔ پیاپی تا صفحهٔ '.$page.' محصول تازه‌ای نداشت — پایان طبیعی';
            $qe['pag_stop_url']=$pageUrl;
            break;
        }
    }unset($qe);
    extractWriteQueue($queue);
    break;
}
if($page>=$maxPages && count($allProducts)>0){
    $_listReachedLastPage=true;
}
if(isset($_pagePauseMs) && $_pagePauseMs>0) usleep($_pagePauseMs*1000);
}

/* =====================================================================
   v8.91: محافظ «استخراج بی‌نتیجه چیزی را پاک نکند»

   این علتِ واقعیِ ناپدید شدن گالری‌ها بود و سلکتورها هیچ ربطی به آن
   نداشتند. سناریو دقیقاً این است:

     ۱) اجرای خودکار شروع می‌شود.
     ۲) سایت مبدأ همان لحظه در دسترس نیست — 503، تایم‌اوت، قطعی DNS،
        یا فایروالی که ربات را چند دقیقه بلاک کرده. هر سایتی این را
        روزی چند بار دارد.
     ۳) حلقهٔ بالا از صفحهٔ اول بیرون می‌زند و $allProducts خالی می‌ماند.
     ۴) کد پایین همان آرایهٔ خالی را در پروفایل می‌نوشت.

   نتیجه: کل محصولات پروفایل با همهٔ گالری‌ها، تنوع‌ها و توضیحاتی که
   ساعت‌ها طول کشیده بود، در یک لحظه صفر می‌شد. چون اجرای بعدی دوباره
   محصولات را از فهرست پیدا می‌کرد، محصول‌ها برمی‌گشتند — ولی بدون گالری،
   چون گالری فقط از صفحهٔ محصول می‌آید و «ادغام با اجرای قبلی» دیگر
   چیزی برای ادغام نداشت. برای همین به نظر می‌رسید «سلکتورهای گالری
   پاک شده‌اند»، در حالی که سلکتورها سر جایشان بودند.

   قاعده: اگر قبلاً محصول داشتیم و حالا هیچ نداریم، به این اجرا اعتماد
   نکن. چیزی ذخیره نکن و علتش را بگو. یک فروشگاه واقعاً خالی‌شده هم با
   اجرای بعدی و پیام صریح قابل تشخیص است — ولی داده‌ای که رفته برنمی‌گردد.
   ===================================================================== */
/* v8.98: پروفایل خالی هم باید علتش را بگوید.

   تا اینجا این محافظ فقط وقتی کار می‌کرد که از قبل محصولی داشتیم. اگر
   پروفایل تازه بود و صفحهٔ فهرست باز نمی‌شد (تایم‌اوت، ۵۰۳، سلکتور
   اشتباه)، اجرا بی‌صدا با صفر محصول «تکمیل» می‌شد و کاربر فقط می‌دید
   هیچ‌چیز استخراج نشده، بدون هیچ توضیحی. */
if(empty($allProducts)&&$phase!=='detail'){
$_why=$fetchFail!==''?$fetchFail:'صفحهٔ فهرست باز شد ولی هیچ محصولی با سلکتورها پیدا نشد';
/* v9.88: اگر سلکتور درست است ولی HTMLِ خام کارتی ندارد، علتِ واقعی را بگو. */
$_dg=$GLOBALS['_extractDiag']??null;
if($fetchFail===''&&is_array($_dg)&&(int)($_dg['containers_in_raw_html']??-1)===0){
$_why='این صفحه محتوایش را با جاوااسکریپت می‌سازد — سلکتور شما درست است ولی در HTMLِ خامِ سرور هیچ کارتی وجود ندارد';
}
$_kept=count($prevByKey);
$_guardLog=[$_kept>0
    ?'🛡 استخراج بی‌نتیجه بود — داده‌های قبلی دست‌نخورده ماند'
    :'❌ استخراج هیچ محصولی پیدا نکرد'];
$_guardLog[]='   • علت: '.$_why;
if($_kept>0)$_guardLog[]='   • '.$_kept.' محصول ذخیره‌شده حفظ شد (گالری و جزئیاتشان پاک نشد)';
else $_guardLog[]='   • سلکتور «کانتینر» را روی صفحهٔ فهرست بررسی کنید، یا سایت مبدأ در دسترس نبوده';
/* v9.88: راهنمای عملی برای سایت‌های جاوااسکریپتی */
if(is_array($_dg)){
$_guardLog[]='   • تشخیص: در HTMLِ خام '.(int)($_dg['containers_in_raw_html']??0).' ظرف پیدا شد (حجم صفحه '.number_format((int)($_dg['html_bytes']??0)).' بایت)';
if((int)($_dg['containers_in_raw_html']??-1)===0){
$_guardLog[]='   • انتخابگرِ بصری سایت را با جاوااسکریپتِ کامل در iframe نشان می‌دهد،';
$_guardLog[]='     ولی استخراج با cURL انجام می‌شود و جاوااسکریپت اجرا نمی‌کند.';
$_guardLog[]='   • راه‌حل: آدرسِ API خودِ سایت را به‌جای صفحهٔ HTML بدهید (در تب';
$_guardLog[]='     Network مرورگر، درخواستی که محصولات را JSON برمی‌گرداند)';
}}
$_guardLog[]='   • اگر سایت مبدأ واقعاً خالی شده، اجرای بعدی هم همین را می‌گوید';
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'total'=>$progressPageTarget,'current'=>$totalPages,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'recent_log'=>$_guardLog,'total_log_count'=>count($_guardLog),'extracted'=>0,'error'=>'استخراج بی‌نتیجه — '.$_why,'guard'=>'empty_result','kept'=>count($prevByKey),'products_saved'=>false]);
$queue=extractReadQueue();
foreach($queue['entries'] as &$qe){if(($qe['id']??'')===$queueId){$qe['status']='failed';$qe['error']='بی‌نتیجه — '.$_why.($_kept>0?(' · '.$_kept.' محصول قبلی حفظ شد'):'');$qe['done_at']=time();break;}}unset($qe);
extractWriteQueue($queue);
notifRunFailure(loadConnections(),'استخراج',$profile['name']??$profileKey,
  ($_kept>0
    ?'استخراج هیچ محصولی برنگرداند و متوقف شد تا داده‌های قبلی پاک نشوند. علت: '
    :'استخراج هیچ محصولی پیدا نکرد. علت: ').$_why);
extractLockRelease($queueId);   // v10.32 (۴۵ب)
return ['__early_sent'=>$emitEarlyResponse,'ok'=>false,'queue_id'=>$queueId,'error'=>'استخراج بی‌نتیجه — '.$_why,
        'guard'=>'empty_result','kept'=>count($prevByKey),'products_saved'=>false];
}

/* v10.471: تا زمانی که استخراج به انتهای آخرین صفحه نرسیده است، حتی اگر حلقه به هر دلیلی
   (مثل خطای HTTP در صفحهٔ آخر) پیش از پایان کامل خارج شده باشد، محصولات نیمه‌کاره هرگز
   وارد پروفایل و تب نتایج نمی‌شوند و نتایج قبلی دست‌نخورده باقی می‌ماند. */
if($phase!=='detail' && !$_listReachedLastPage){
    $_rpGuard=max(1,$totalPages-1);
    extractSaveListStaging($pkFinal,$allProducts,[
        '_extract_stage'=>'list','_extract_stage_at'=>time(),
        '_extract_want_detail'=>$_wantDetailAfterList,
        '_extract_list_incomplete'=>true,
        '_extract_list_page_ok'=>$_rpGuard,
        '_extract_list_page_try'=>max(1,$totalPages),
        '_extract_resume_from'=>$_rpGuard,
    ]);
    writeProgress(EXTRACT_PROGRESS_FILE,[
        'running'=>false,'done'=>true,'partial'=>true,'resumable'=>true,'products_saved'=>false,
        'resume_page'=>$_rpGuard,'extracted'=>count($allProducts),'page'=>$totalPages,
        'queue_id'=>$queueId,'started_at'=>$startedAt,'last_progress_ts'=>time(),'profile_key'=>$pkFinal,
        'error'=>'استخراج پیش از پایان آخرین صفحه متوقف شد — نتایج قبلی حفظ شد',
        'recent_log'=>[
            '⏸ استخراج هنوز به انتهای آخرین صفحه نرسیده است (صفحهٔ '.$totalPages.')',
            '   • '.count($allProducts).' محصول در حافظهٔ مرحله‌ای نگه داشته شد تا از صفحهٔ '.$_rpGuard.' ادامه یابد',
            '   • محصولات قبلی در تب نتایج دست‌نخورده باقی ماندند',
        ],
        'total_log_count'=>3,
    ]);
    $queue=extractReadQueue();
    foreach($queue['entries'] as &$qe){
        if(($qe['id']??'')===$queueId){
            $qe['status']='paused';$qe['done_at']=time();$qe['resumable']=true;$qe['resume_needed']=1;
            $qe['partial']=true;$qe['resume_phase']='list';$qe['resume_page']=$_rpGuard;
            $qe['products_count']=count($allProducts);
            $qe['error']='پیش از آخرین صفحه متوقف شد — ادامه از صفحهٔ '.$_rpGuard;
            break;
        }
    }unset($qe);
    extractWriteQueue($queue);
    extractLockRelease($queueId);
    return ['__early_sent'=>$emitEarlyResponse,'ok'=>true,'queue_id'=>$queueId,'extracted'=>count($allProducts),
        'partial'=>true,'resume_needed'=>true,'resume_page'=>$_rpGuard,'products_saved'=>false,'profile_key'=>$pkFinal];
}

/* v8.81: جزئیاتِ اجرای قبلی را برگردان، قبل از اینکه تصمیم بگیریم کدام
   محصول لازم است دوباره باز شود. صفحهٔ فهرست فقط عنوان، قیمت، لینک و یک
   عکس دارد؛ بقیه فقط از صفحهٔ محصول می‌آید. اگر اینجا ادغام نکنیم، همان
   داده‌ها موقع ذخیره دور ریخته می‌شوند. */
foreach($allProducts as $key=>$p){
if(!isset($prevByKey[$key])||!is_array($prevByKey[$key]))continue;
$allProducts[$key]=extractMergeDetail($p,$prevByKey[$key]);
}

/* v10.121 / v10.475: محافظ جامع جلوگیری از کاهش/حذف محصولات پروفایل هنگام خطا یا گیرکردن فهرست */
if ($phase !== 'detail') {
    $_prevAn = extractAnalyzeProductSet($prevByKey, $_detailSuppliesPrice);
    $_newAn  = extractAnalyzeProductSet($allProducts, $_detailSuppliesPrice);
    $_prevN  = $_detailSuppliesPrice
        ? max(count($prevByKey), (int)$_prevAn['detail_candidate'])
        : (int)($_prevAn['valid'] > 0 ? $_prevAn['valid'] : count($prevByKey));
    $_newN   = $_detailSuppliesPrice ? (int)$_newAn['detail_candidate'] : (int)$_newAn['valid'];
    $_apiTargetPages = ($_knownApiTotalPages > 0) ? min($maxPages, $_knownApiTotalPages) : 0;
    $_stoppedBeforeApiTotal = ($_apiTargetPages > 0 && $totalPages < $_apiTargetPages);
    $_listShrink = extractShouldBlockShrinkage($_prevN, $_newN, [
        'incomplete'               => !$_listReachedLastPage,
        'had_errors'               => $_hadListFetchErrors,
        'stopped_early'            => $_stoppedByEarlySignal,
        'stopped_before_api_total' => $_stoppedBeforeApiTotal,
        'stage'                    => 'list_done',
    ]);
    if (!empty($_listShrink['blocked'])) {
        $pkGuard = $profileKey !== '' ? $profileKey : profileKey($url);
        $_shrinkTries = (int)($profile['_extract_shrink_guard_tries'] ?? 0) + 1;
        $_canStageResume = ($_stoppedByEarlySignal || $_hadListFetchErrors || $_stoppedBeforeApiTotal)
            && $_lastGoodListPage >= 1 && $_lastGoodListPage < $maxPages && $_shrinkTries <= 2;
        if ($_canStageResume) {
            $_rpShrink = max(1, $_lastGoodListPage);
            $_whyRetry = 'توقف زودهنگام فهرست در صفحهٔ ' . $totalPages . ' (' . $_newN . ' از ' . $_prevN . ' محصول قبلی) — نتایج قبلی حفظ شد؛ ادامه از صفحهٔ ' . $_rpShrink . ' (تلاش ' . $_shrinkTries . '/2)';
            extractSaveListStaging($pkGuard, $allProducts, [
                '_extract_stage'              => 'list',
                '_extract_stage_at'           => time(),
                '_extract_want_detail'        => $_wantDetailAfterList,
                '_extract_list_incomplete'    => true,
                '_extract_list_page_ok'       => $_rpShrink,
                '_extract_list_page_try'      => $_rpShrink + 1,
                '_extract_resume_from'        => $_rpShrink,
                '_extract_resume_needed'      => 1,
                '_extract_resume_phase'       => 'list',
                '_extract_shrink_guard_tries' => $_shrinkTries,
            ]);
            writeProgress(EXTRACT_PROGRESS_FILE, [
                'running' => false, 'done' => false, 'paused' => true, 'partial' => true,
                'resumable' => true, 'resume_needed' => true, 'resume_phase' => 'list', 'resume_page' => $_rpShrink,
                'error' => $_whyRetry, 'guard' => 'shrinkage_retry', 'products_saved' => false,
                'kept' => $_prevN, 'extracted' => $_newN, 'started_at' => $startedAt,
                'last_progress_ts' => time(), 'queue_id' => $queueId, 'profile_key' => $pkGuard,
                'recent_log' => [
                    '🛡 گارد حفاظت نتایج: فهرست در میانهٔ راه متوقف شد (' . $_newN . ' محصول در برابر ' . $_prevN . ' محصول قبلی)',
                    '   • نتایج قبلی در پروفایل و تب نتایج ۱۰۰٪ ثابت و دست‌نخورده باقی ماند',
                    '   • ادامهٔ خودکار از صفحهٔ ' . $_rpShrink . ' (تلاش ' . $_shrinkTries . ' از ۲)',
                ],
                'total_log_count' => 3,
            ]);
            $queue = extractReadQueue();
            foreach ($queue['entries'] as &$qe) {
                if (($qe['id'] ?? '') === $queueId) {
                    $qe['status'] = 'paused'; $qe['done_at'] = time(); $qe['resumable'] = true; $qe['resume_needed'] = 1;
                    $qe['partial'] = true; $qe['resume_phase'] = 'list'; $qe['resume_page'] = $_rpShrink;
                    $qe['products_count'] = $_prevN; $qe['products_saved'] = false; $qe['guard'] = 'shrinkage_retry';
                    $qe['error'] = $_whyRetry;
                    break;
                }
            }
            unset($qe);
            extractWriteQueue($queue);
            extractLockRelease($queueId);
            return ['__early_sent' => $emitEarlyResponse, 'ok' => true, 'partial' => true, 'resume_needed' => true,
                'resume_page' => $_rpShrink, 'queue_id' => $queueId, 'guard' => 'shrinkage_retry',
                'kept' => $_prevN, 'extracted' => $_newN, 'products_saved' => false, 'profile_key' => $pkGuard];
        }
        $_why = 'گارد حفاظت کاتالوگ: قبلاً ' . $_prevN . ' محصول معتبر، این نوبت ' . $_newN . ' محصول (' . $_listShrink['reason'] . ') — نتایج قبلی ثابت نگه داشته شد';
        extractClearListStaging($pkGuard);
        extractSaveListStaging($pkGuard, null, [
            '_extract_stage'              => 'complete',
            '_extract_stage_at'           => time(),
            '_extract_list_incomplete'    => false,
            '_extract_resume_needed'      => 0,
            '_extract_resume_phase'       => '',
            '_extract_resume_req'         => 0,
            '_extract_resume_from'        => 0,
            '_extract_shrink_guard_tries' => 0,
            '_extract_last_guard'         => (string)$_listShrink['reason'],
        ]);
        writeProgress(EXTRACT_PROGRESS_FILE, [
            'running' => false, 'done' => true, 'resumable' => false, 'resume_needed' => false,
            'error' => $_why, 'guard' => 'soft_collapse',
            'kept' => $_prevN, 'extracted' => $_newN, 'started_at' => $startedAt,
            'last_progress_ts' => time(), 'queue_id' => $queueId, 'profile_key' => $pkGuard,
            'recent_log' => [
                '🛡 گارد پایداری: استخراج ناقص/ناموفق متوقف شد تا محصولات پروفایل کم نشوند',
                '   • قبلی: ' . $_prevN . ' محصول · این نوبت: ' . $_newN . ' محصول',
                '   • تمام ' . $_prevN . ' محصول قبلی کاملاً ثابت و دست‌نخورده باقی ماندند',
            ],
            'total_log_count' => 3, 'products_saved' => false,
        ]);
        $queue = extractReadQueue();
        foreach ($queue['entries'] as &$qe) {
            if (($qe['id'] ?? '') === $queueId) {
                $qe['status'] = 'failed'; $qe['done_at'] = time(); $qe['resumable'] = false; $qe['resume_needed'] = 0;
                $qe['error'] = $_why; $qe['products_count'] = $_prevN; $qe['products_saved'] = false; $qe['guard'] = 'soft_collapse';
                break;
            }
        }
        unset($qe);
        extractWriteQueue($queue);
        extractLockRelease($queueId);
        return ['__early_sent' => $emitEarlyResponse, 'ok' => false, 'queue_id' => $queueId, 'error' => $_why,
            'guard' => 'soft_collapse', 'kept' => $_prevN, 'extracted' => $_newN, 'products_saved' => false];
    }
}

/* v8.94: مرحلهٔ ۱ تمام شد — همین‌جا ذخیره کن.

   این نقطهٔ امنِ اول است. فاز بعدی (باز کردن صفحهٔ تک‌تک محصول‌ها برای
   گالری و جزئیات) طولانی‌ترین بخش کار است و روی هاست ما معمولاً همان‌جا
   پردازه کشته می‌شود. تا ۸.۹۳ در آن حالت هیچ‌چیز ذخیره نشده بود — حتی
   خودِ محصولاتی که از صفحهٔ فهرست به دست آمده بودند. */
$pkFinal=$profileKey!==''?$profileKey:profileKey($url);
/* A detail cycle is the durable cursor across process/cron segments. Products
   already resolved in this cycle are skipped on resume, so a price selector
   that is intentionally refreshed can no longer restart from product one. */
$_listSavedForResults = count($allProducts) > 0;
$_listSavedAt = ($phase === 'detail' && !empty($profile['_extract_list_saved_at']))
    ? (int)$profile['_extract_list_saved_at']
    : ($_listSavedForResults ? time() : 0);
$_listSavedCount = ($phase === 'detail' && !empty($profile['_extract_list_saved_count']))
    ? (int)$profile['_extract_list_saved_count']
    : count($allProducts);
if ($phase !== 'detail') {
    extractCheckpoint($pkFinal,$allProducts,['_extract_stage'=>'list_done','_extract_stage_at'=>time(),
        'detailExtractMode'=>$_detailExtractMode,
        '_extract_want_detail'=>$_wantDetailAfterList,
        '_extract_list_saved_at'=>$_listSavedAt,
        '_extract_list_saved_count'=>$_listSavedCount,
        '_extract_detail_cycle'=>$_detailCycle,
        '_extract_list_incomplete'=>false,
        '_extract_list_page_ok'=>$totalPages,
        '_extract_list_page_try'=>$totalPages,
        '_extract_resume_req'=>0,
        '_extract_resume_from'=>0,
        '_extract_shrink_guard_tries'=>0,
    ]);
    if (!$_detailSuppliesPrice) {
        extractClearListStaging($pkFinal);
    }
}
$_stageProgressMeta = [
    'detail_extract_mode' => $_detailExtractMode,
    'list_done' => ($_detailExtractMode === 'two_stage' && $_listSavedForResults),
    'list_saved_for_results' => ($_detailExtractMode === 'two_stage' && $_listSavedForResults),
    'list_saved_at' => $_listSavedAt,
    'list_saved_count' => $_listSavedCount,
];
if ($phase !== 'detail' && $phase !== 'list' && $_detailExtractMode === 'two_stage' && $_listSavedForResults) {
    $_stage1Logs = array_slice(array_merge($logs, [
        '✅ مرحلهٔ ۱ (استخراج لیست) کامل شد: ' . count($allProducts) . ' محصول استخراج و در پروفایل و تب نتایج ذخیره شد',
        '⏳ ورود خودکار به مرحلهٔ ۲ (استخراج جزئیات محصولات)...',
    ]), -12);
    writeProgress(EXTRACT_PROGRESS_FILE, array_merge([
        'running' => true, 'done' => false,
        'total' => ($autoPageMode ? $totalPages : $maxPages),
        'current' => $totalPages, 'started_at' => $startedAt, 'last_progress_ts' => time(),
        'queue_id' => $queueId, 'profile_key' => $pkFinal,
        'phase' => 'list_done', 'extract_stage' => 'list_done',
        'products_saved' => true, 'extracted' => count($allProducts),
        'recent_log' => $_stage1Logs, 'total_log_count' => $totalPages + 1,
    ], $_stageProgressMeta, extractLiveCompare($allProducts, $livePrevMap)));
}

// v8.64 / v10.453: اگر گالری روشن است (یا کادر گالری اسنپ‌شاپ پر شده)، صفحهٔ همهٔ محصولات
// باید باز شود — نه فقط آن‌هایی که عکس یا قیمت ندارند. وگرنه محصولی که یک عکس دارد هرگز
// بقیهٔ عکس‌هایش را نمی‌گیرد.
$galleryCfg=galleryEffectiveCfgForUrl(galleryNormalizeCfg($profile['gallery']??[]),$url);
if($phase!=='list'&&function_exists('isSnappshopUrl')&&isSnappshopUrl($url)&&!empty($allProducts)){
    $_snHealed453=0;
    foreach($allProducts as $_hk=>$_hp){
        if(!is_array($_hp)||empty($_hp['link']))continue;
        $_falseOut=(($_hp['in_stock']??null)===false&&($_hp['stock_src']??'')==='detail_price'&&!empty($_hp['price'])&&(trim((string)($_hp['stock']??''))==='موجود'||empty($_hp['longDesc'])));
        $_missedGal=($galleryCfg['enabled']&&(string)($_hp['_detail_cycle']??'')===$_detailCycle&&empty($_hp['_snapp_gal_v453'])&&count((array)($_hp['images']??[]))<=1);
        if($_falseOut){
            $allProducts[$_hk]['in_stock']=true;
            $allProducts[$_hk]['stock_src']='snappshop_heal_453';
            unset($allProducts[$_hk]['_detail_cycle']);
            $allProducts[$_hk]['_detail_new_pending']=1;
            $_snHealed453++;
        }elseif($_missedGal){
            unset($allProducts[$_hk]['_detail_cycle']);
            $allProducts[$_hk]['_detail_new_pending']=1;
            $_snHealed453++;
        }
    }
    if($_snHealed453>0){
        extractCheckpoint($pkFinal,$allProducts,['_extract_detail_cycle'=>$_detailCycle]);
    }
}
/* v9.02: انتخاب محصولاتی که باید صفحه‌شان باز شود.

   باگی که کاربر گزارش کرد: وقتی گالری خاموش بود ولی سلکتورهای جزئیات
   تنظیم شده بودند، این حلقه هیچ‌کس را انتخاب نمی‌کرد. شرط قدیمی فقط
   «عکس یا قیمت ندارد» را می‌سنجید، و محصولی که هر دو را از صفحهٔ فهرست
   گرفته بود کنار گذاشته می‌شد — یعنی توضیحات، SKU، برند و تنوع‌ها هرگز
   استخراج نمی‌شدند و مرحلهٔ جزئیات عملاً کاری نمی‌کرد.

   قاعدهٔ درست: اگر فیلدی از صفحهٔ محصول خواسته شده و هنوز نداریمش،
   باید صفحه را باز کنیم. */
$_wantKeys=[];
foreach($detailSelectors as $_f=>$_sv){ if(!empty($_sv))$_wantKeys[]=$_f; }
/* v9.05: چرا هیچ محصولی انتخاب نشد؟ سه علتِ کاملاً متفاوت وجود دارد و
   تا حالا هر سه یک پیام می‌گرفتند: «همه از قبل کامل بودند». این پیام
   وقتی گالری اصلاً نیامده کاملاً گمراه‌کننده است. حالا شمرده می‌شوند. */
$_noLink=0;$_alreadyDone=0;
$needDetail=[];
/* v9.10: دامنهٔ «همهٔ محصولات». وقتی استخراج دوره‌ای جزئیات با
   scope=all اجرا شود، محصولی که قبلاً گالری گرفته هم دوباره باز
   می‌شود — برای وقتی که سلکتور گالری عوض شده یا مبدأ عکس‌ها را
   به‌روز کرده است. */
$_forceAll=($phase==='detail'&&$forceAll);
/* v10.486: a synchronization cycle may supply explicit linked profile
   products lacking resolved detail data. This scope is independent of the
   destination action basis and survives checkpoints until the pass completes. */
$_syncScope=[];
if($phase==='detail'&&!$_forceAll){
    foreach((array)($profile['_sync_detail_scope_keys']??[]) as $_sk){
        $_sk=trim((string)$_sk);if($_sk!=='')$_syncScope[$_sk]=true;
    }
}
foreach($allProducts as $key=>$p){
if(empty($p['link'])){$_noLink++;continue;}
if((string)($p['_detail_cycle']??'')===$_detailCycle){$_alreadyDone++;continue;}
if($_forceAll){$needDetail[$key]=$p;continue;}
if($_syncScope){
    if(isset($_syncScope[(string)$key]))$needDetail[$key]=$p;else $_alreadyDone++;
    continue;
}
/* Normal extraction only details products discovered in this cycle. Existing
   catalogue rows retain their saved details and are not reopened merely because
   a detail selector (especially price) is enabled. */
if(empty($p['_detail_new_pending'])){$_alreadyDone++;continue;}
/* v8.81: محصولی که گالری‌اش را قبلاً گرفته‌ایم دوباره باز نمی‌شود.
   پیش از این با روشن بودن گالری، هر بار همهٔ صفحات محصول از نو گرفته
   می‌شد که هم کند بود و هم بی‌دلیل. */
$_galDone=$galleryCfg['enabled']&&count($p['images']??[])>1&&!empty($p['image'])&&!empty($p['price']);
// کدام فیلدِ خواسته‌شده هنوز خالی است؟
$_fieldMissing=false;
foreach($_wantKeys as $_wk){
    /* v10.15: قیمت همیشه «کهنه» حساب می‌شود — همان قاعدهٔ سمتِ مرورگر در
       startDetailExtraction. p.price از فازِ فهرست پر است، پس با سنجشِ
       «خالی است؟» صفحهٔ هیچ محصولی برای تازه‌کردنِ قیمت باز نمی‌شد. */
    if($_wk==='price'){$_fieldMissing=true;break;}
    if($_wk==='variations'){ if(empty($p['variations'])){$_fieldMissing=true;break;} continue; }
    $_cur=$p[$_wk]??'';
    if(is_array($_cur)?empty($_cur):(trim((string)$_cur)==='')){$_fieldMissing=true;break;}
}
if($_galDone&&!$_fieldMissing){$_alreadyDone++;continue;}   // هم گالری دارد هم فیلدها
if($galleryCfg['enabled']||$_fieldMissing||empty($p['image'])||empty($p['price'])){
$needDetail[$key]=$p;
}
}
$detailTotal=count($needDetail);
$detailDone=0;
$galleryFound=0;$galleryImgsTotal=0;
/* v8.90: شمارنده‌های تفصیلی تا لاگ بگوید واقعاً چه اتفاقی افتاد، نه فقط
   «۵ از ۲۰». تا حالا اگر صفحه‌ای باز نمی‌شد یا سلکتوری چیزی پیدا نمی‌کرد،
   هیچ ردی در لاگ نمی‌ماند و کاربر فقط می‌دید کار کند است. */
$detailOk=0;$detailFail=0;$detailFields=0;$detailNoField=0;$varFound=0;$imgMain=0;
$_detailIncomplete=false;
$failSamples=[];$emptySamples=[];
// v10.21 (۳۴الف): شمارندهٔ تغییرِ موجودی که از روی قیمت تشخیص داده شد
$_stockOut=0;$_stockBack=0;
// v8.97: وقتی فاز جزئیات اصلاً اجرا نشود هم باید تعریف‌شده باشد
$_ranOut=false;
$detailLog=[];   // چند خط آخر، برای نمایش در نوار پیشرفت
$pushLog=function(string $line) use (&$detailLog){
    $detailLog[]=$line;
    if(count($detailLog)>6)$detailLog=array_slice($detailLog,-6);
};
/* v9.05: اگر فاز جزئیات اجرا نمی‌شود، دلیلش را ثبت کن. سکوت باعث شد
   کاربر پیام «همه از قبل کامل بودند» ببیند در حالی که گالری نیامده بود. */
$_skipWhy='';
if($phase==='list'&&!$detailConfigured)              $_skipWhy='no_detail_selectors';
elseif($phase==='list')                               $_skipWhy='';           // عمدی
elseif(empty($detailSelectors))                       $_skipWhy='no_config';
elseif($detailTotal===0&&$_noLink>0&&$_alreadyDone===0)  $_skipWhy='no_link';
elseif($detailTotal===0&&$_alreadyDone>0)                $_skipWhy='already_done';
elseif($detailTotal===0)                                 $_skipWhy='nothing_selected';

if($phase!=='list'&&$detailTotal>0&&(!empty($detailSelectors)||$galleryCfg['enabled'])){
extractInstallDetailFatalGuard();
$GLOBALS['_extractDetailFatalCtx']=['active'=>true,'profile_key'=>$pkFinal,'queue_id'=>$queueId,
    'detail_cycle'=>$_detailCycle,'started_at'=>time()];
$_wantFields=[];
foreach($detailSelectors as $_f=>$_sv){ if(!empty($_sv))$_wantFields[]=$_f; }

/* v8.97: فاز جزئیات باید «قبل» از سقف زمانی هاست تمیز تمام شود.

   این علت واقعی کرش بود و همهٔ تلاش‌های ۸.۹۴ تا ۸.۹۶ کنارش رد شدند.
   حساب سرانگشتی: هر محصول یک درخواست HTTP است (تا ۱۰ ثانیه تایم‌اوت)
   به‌علاوهٔ ۰.۲ ثانیه مکث. برای ۵۰۰ محصول یعنی ۱۷ دقیقه در حالت متوسط
   و بیش از یک ساعت اگر مبدأ کند باشد. هیچ هاست اشتراکی‌ای چنین
   درخواستی را زنده نگه نمی‌دارد؛ پردازه وسط کار کشته می‌شود.

   set_time_limit(0) هم کمکی نمی‌کند، چون آنچه پردازه را می‌کشد
   معمولاً max_execution_time نیست بلکه سقف خودِ وب‌سرور است
   (FcgidIOTimeout / proxy_read_timeout / request_terminate_timeout)
   و آن از داخل PHP قابل تغییر نیست.

   پس به‌جای جنگیدن با سقف، زودتر از آن می‌ایستیم: تا هر جا که رسیدیم
   کار می‌کنیم، ذخیره می‌کنیم و «ناتمام» علامت می‌زنیم. اجرای بعدی —
   چه کران چه دکمه — از همان‌جا ادامه می‌دهد، چون needDetail فقط
   محصولاتی را برمی‌دارد که هنوز گالری/فیلد ندارند. */
$cn0=loadConnections();
$_budget=(int)($cn0['detail_budget_sec']??0);
if($_budget<=0){
    // اگر تنظیم نشده، از max_execution_time حدس بزن و حاشیهٔ امن بگذار.
    // در worker/CLI محدودیت وب‌سرور نداریم؛ ۹۰ ثانیه باعث pauseهای چندمحصولی می‌شد.
    $_ini=(int)@ini_get('max_execution_time');
    $_budget=$_ini>0?max(30,(int)($_ini*0.7)):((isCliRun()||(string)$trigger==='worker')?900:90);
}
$_budget=max(20,min(3600,$_budget));
if(isset($GLOBALS['_extractCronSliceSec']))$_budget=max(20,min($_budget,(int)$GLOBALS['_extractCronSliceSec']));
/* v8.98: مهلت از «شروع فاز جزئیات» حساب می‌شود، نه از شروع کل اجرا.

   در ۸.۹۷ نوشته بودم $startedAt + $budget که $startedAt لحظهٔ شروع کل
   استخراج است. ولی قبل از فاز جزئیات، فاز فهرست اجرا می‌شود که خودش
   می‌تواند دقایقی طول بکشد (هر صفحه تا ۲۰ ثانیه تایم‌اوت + نیم ثانیه
   مکث، ضربدر تعداد صفحات). اگر فهرست به‌تنهایی بودجه را می‌خورد، همان
   اولین تکرارِ فاز جزئیات می‌دید که مهلت گذشته و بی‌درنگ break می‌کرد —
   یعنی «حتی یک محصول هم جزئیات نمی‌گرفت».

   دکمهٔ دستی سالم به نظر می‌رسید چون معمولاً روی فروشگاه کوچک و
   تک‌صفحه‌ای امتحان می‌شد و فهرستش سریع تمام می‌شد. */
$_detailStart=time();
$_deadline=$_detailStart+$_budget;
$_ranOut=false;
/* محافظ: حداقل چند محصول در هر نوبت باید پردازش شود، وگرنه اگر بودجه
   کوچک و مبدأ کند باشد هر نوبت صفر محصول جلو می‌رویم و کار هرگز تمام
   نمی‌شود. */
/* External cron providers often close HTTP requests near 30 seconds. One
   checkpointed product is sufficient progress there; worker/internal-browser
   drivers keep the larger batch for throughput. */
$_minPerRun=isset($GLOBALS['_externalCronHttpKeep'])?1:3;

$logs=['🔍 فاز ۲ — باز کردن صفحهٔ محصول‌ها: '.$detailTotal.' محصول'];
$logs[]='   • فیلدها: '.($_wantFields?implode('، ',$_wantFields):'—')
        .($galleryCfg['enabled']?(' · گالری: روشن ('.$galleryCfg['mode'].')'):' · گالری: خاموش');
$logs[]='   • ⏱ سقف زمانی این نوبت: '.$_budget.' ثانیه — بقیه در نوبت بعد ادامه می‌یابد';
/* v10.32 (۴۵الف): 'queue_id' و 'last_progress_ts' اینجا جا افتاده بودند.
   writeProgress کلِ فایل را بازنویسی می‌کند، پس نبودِ کلید یعنی حذفش. از
   لحظه‌ای که فازِ جزئیات شروع می‌شد، فایلِ پیشرفت دیگر نمی‌گفت مالِ کدام
   ردیفِ صف است؛ آن‌وقت شرطِ $mine در نگهبان و در extract_queue_status
   false می‌شد، زمانِ بی‌حرکتی از started_at حساب می‌شد و ردیفِ کاملاً
   زنده «پردازش نیمه‌کاره رها شد» می‌خورد. دقیقاً همان چیزی که کاربر
   می‌دید: صف «خطا» ولی کار در جریان. */
writeProgress(EXTRACT_PROGRESS_FILE,array_merge(['running'=>true,'done'=>false,'total'=>(($autoPageMode?$totalPages:$maxPages)+$detailTotal),'current'=>$totalPages+$detailDone,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'profile_key'=>$pkFinal,'resume_phase'=>'detail','extract_stage'=>'detail','recent_log'=>$logs,'total_log_count'=>$totalPages+1,'extracted'=>count($allProducts),'phase'=>'detail','detail_current'=>0,'detail_total'=>$detailTotal],$_stageProgressMeta));

$GLOBALS['_s4SnappDetailDeadline'] = $_deadline;
$GLOBALS['_s4SnappDetailQueueId'] = $queueId;
$GLOBALS['_s4SnappCooldownHeartbeat'] = function(int $leftSec) use ($autoPageMode, $totalPages, $maxPages, &$detailTotal, &$detailDone, $startedAt, $queueId, $pkFinal, &$detailLog, &$allProducts, $_stageProgressMeta): void {
    writeProgress(EXTRACT_PROGRESS_FILE, array_merge([
        'running' => true, 'done' => false,
        'total' => (($autoPageMode ? $totalPages : $maxPages) + $detailTotal),
        'current' => $totalPages + $detailDone,
        'started_at' => $startedAt, 'last_progress_ts' => time(),
        'queue_id' => $queueId, 'profile_key' => $pkFinal,
        'resume_phase' => 'detail', 'extract_stage' => 'detail',
        'recent_log' => array_merge(['🔍 جزئیات ' . $detailDone . ' از ' . $detailTotal, '   • ⏳ تنفس ضد محدودیت Sotoon CDN اسنپ‌شاپ (' . $leftSec . ' ثانیه تا ادامه)...'], $detailLog),
        'total_log_count' => $totalPages + $detailDone + 1,
        'extracted' => count($allProducts), 'phase' => 'detail',
        'detail_current' => $detailDone, 'detail_total' => $detailTotal,
    ], $_stageProgressMeta));
};
$_detailCapped=0;
foreach($needDetail as $key=>$p){
/* v8.97: وقت تمام شد؟ تمیز بیرون بیا، نه اینکه منتظر بمانی تا هاست بکشد.
   v8.98: ولی حداقل چند محصول باید انجام شود، وگرنه پیشرفتی حاصل نمی‌شود
   و هر نوبت دقیقاً از همان جای قبل شروع می‌کند. */
if($detailDone>=$_minPerRun&&time()>=$_deadline){$_ranOut=true;break;}
if($detailDone>0&&(($detailDone&7)===0)&&function_exists('s4DiskCodeMeta')&&(s4DiskCodeMeta()['version']??APP_VERSION)!==APP_VERSION){$_ranOut=true;break;}
/* Each parallel row consumes only its own stop signal. */
if(extractStopRequestedForQueue($queueId,true)){
extractCheckpoint($pkFinal,$allProducts,
    ['_extract_stage'=>'stopped','_extract_stage_at'=>time(),
     '_extract_resume_phase'=>'detail','_extract_list_incomplete'=>false,
     '_extract_detail_done'=>$detailDone,'_extract_detail_total'=>$detailTotal]);
writeProgress(EXTRACT_PROGRESS_FILE,['running'=>false,'done'=>true,'cancelled'=>true,'stopped'=>true,'partial'=>true,
    'resumable'=>true,'resume_phase'=>'detail','extracted'=>count($allProducts),'started_at'=>$startedAt,
    'last_progress_ts'=>time(),'queue_id'=>$queueId,'profile_key'=>$pkFinal,'phase'=>'detail',
    'detail_current'=>$detailDone,'detail_total'=>$detailTotal,
    'recent_log'=>['⏹ توقف کاربر — جزئیات ذخیره شد','   • '.$detailDone.' / '.$detailTotal],'total_log_count'=>$totalPages+$detailDone+1]);
$queue=extractReadQueue();
foreach($queue['entries'] as &$qe){if(($qe['id']??'')===$queueId){$qe['status']='paused';$qe['done_at']=time();$qe['paused_at']=time();$qe['updated_at']=time();$qe['resumable']=true;$qe['resume_needed']=1;$qe['partial']=true;$qe['stopped_by_user']=true;$qe['resume_phase']='detail';$qe['products_count']=count($allProducts);$qe['detail_done']=$detailDone;$qe['error']='با دکمهٔ توقف متوقف شد؛ checkpoint حفظ شد';unset($qe['stop_requested'],$qe['stop_requested_at']);break;}}unset($qe);
extractWriteQueue($queue);
extractLockRelease($queueId);
unset($GLOBALS['_s4SnappDetailDeadline'],$GLOBALS['_s4SnappDetailQueueId'],$GLOBALS['_s4SnappCooldownHeartbeat']);
return ['__early_sent'=>$emitEarlyResponse, 'ok'=>true,'queue_id'=>$queueId,'cancelled'=>true,'extracted'=>count($allProducts),'partial'=>true,'detail_done'=>$detailDone];
}
$detailDone++;
$_pTitle=mb_substr(trim((string)($p['title']??$key)),0,42);
$_gotFields=0;$_gotImgs=0;$_gotVars=0;$_detailResolved=false;$_isIn=null;
/* v10.21 (۳۴الف): قیمتِ برداشته‌شده در همین دور، جدا از مقدارِ قبلی.
   وقتی سلکتور چیزی پیدا نکند مقدارِ قدیمی دست‌نخورده می‌ماند (عمدی، تا یک
   خطای موقتی داده را پاک نکند) — ولی برای تشخیصِ ناموجودی همان «پیدا نشد»
   دقیقاً همان سیگنالی است که لازم داریم. پس قضاوتِ موجودی روی این متغیر
   انجام می‌شود، نه روی $allProducts[$key]['price']. */
$_freshPrice=null;
$dr=fetch_html($p['link'],10);
if(!$dr['ok'] && (int)($dr['code']??0)===429 && function_exists('isSnappshopUrl') && isSnappshopUrl((string)$p['link'])){
$_cdWait=max(10,min(315,(int)($dr['snappshop_cooldown_sec']??68)));
if(empty($dr['snappshop_deferred']) && (time()+$_cdWait+10)<$_deadline){
$pushLog('  ⏳ محدودیت نرخ ۴۲۹ اسنپ‌شاپ — سکوت '.$_cdWait.' ثانیه برای تخلیهٔ پنجرهٔ Sotoon CDN...');
$_remSleep=$_cdWait;
$_stoppedDuringCd=false;
while($_remSleep>0){
$_stStep=min(5,$_remSleep);
sleep($_stStep);
$_remSleep-=$_stStep;
if(extractStopRequestedForQueue($queueId,false)){$_stoppedDuringCd=true;break;}
if(is_callable($GLOBALS['_s4SnappCooldownHeartbeat']??null))@($GLOBALS['_s4SnappCooldownHeartbeat'])($_remSleep);
}
if(!$_stoppedDuringCd){
$dr=fetch_html($p['link'],15);
}
}
if(!$dr['ok'] && (int)($dr['code']??0)===429){
$detailDone--;
$_ranOut=true;
$pushLog('  ⏸ مکث هوشمند اسنپ‌شاپ تا تخلیهٔ کامل محدودیت ۴۲۹ — ادامهٔ خودکار از همین کالا');
break;
}
}
if($dr['ok']){
$detailOk++;
[$dom2,$xp2]=load_dom($dr['html']);
$_isSnappSynth=(strpos($dr['html'],'data-snappshop-api-detail="1"')!==false
    || strpos($dr['html'],'data-digikala-api-detail="1"')!==false);

foreach($detailSelectors as $field=>$selStr){
if(empty($selStr))continue;
// v8.68: تنوع‌ها فهرست‌اند نه یک متن، پس مسیر جداگانه دارند
if($field==='variations'){
/* v10.116: تنوع + تصاویر سواچ به‌عنوان گالری */
$vr=variationsExtract($xp2,null,$selStr,(string)($dr['url']??''));
if(!empty($vr['values'])){
$allProducts[$key]['variations']=$vr['values'];
$allProducts[$key]['variation_groups']=$vr['groups'];
$allProducts[$key]['variations_text']=implode('، ',$vr['values']);
$_gotVars=count($vr['values']);$varFound++;$_gotFields++;
// v8.81: قیمت هر گزینه
if(!empty($vr['prices'])){
$allProducts[$key]['variation_prices']=$vr['prices'];
$allProducts[$key]['price_min']=$vr['price_min'];
$allProducts[$key]['price_max']=$vr['price_max'];
$allProducts[$key]['price_varies']=!empty($vr['price_varies']);
}
if(!empty($vr['combinations'])&&is_array($vr['combinations'])){
$allProducts[$key]['variation_combinations']=$vr['combinations'];
}
}
if(!empty($vr['images'])&&is_array($vr['images'])){
$nImg=galleryApplyToProduct($allProducts[$key],$vr['images'],$_forceAll);
if($nImg>1){$galleryFound++;$galleryImgsTotal+=$nImg;if($nImg>$_gotImgs)$_gotImgs=$nImg;}
elseif($nImg>$_gotImgs)$_gotImgs=$nImg;
$allProducts[$key]['variation_images']=$vr['images'];
$allProducts[$key]['variation_images_count']=count($vr['images']);
}
continue;
}
$xPath=cssToXpath($selStr);
$ns=$xPath?@$xp2->query($xPath):null;
if((!$ns||!$ns->length)&&$_isSnappSynth&&function_exists('snappshopFallbackSelectorForField')){
$_fbTwo=snappshopFallbackSelectorForField((string)$field);
if($_fbTwo!==''){
$_fbXpTwo=cssToXpath($_fbTwo);
if($_fbXpTwo)$ns=@$xp2->query($_fbXpTwo);
}
}
if($ns&&$ns->length){
$val='';
if($field==='image'){
// v8.66: getAttribute در DOMElement رشتهٔ خالی برمی‌گرداند نه null، پس ??
// هیچ‌وقت به data-src نمی‌رسید و عکس‌های lazy از دست می‌رفتند.
// حالا از همان تابع مشترک گالری استفاده می‌شود که srcset را هم می‌فهمد.
$val=galleryImgFromNode($ns->item(0),$dr['url']);
}elseif($field==='price'){
$val=extractPrice($ns->item(0)->textContent);
$_freshPrice=(string)$val; // v10.21: حتی اگر خالی باشد، یعنی «این بار قیمتی نبود»
}else{
/* v9.19 / v10.458: توضیحات، مشخصات جدولی (specs) و هر گره دارای ساختار جدول
   به‌جای textContent با ساختار تمیز HTML/Table حفظ می‌شوند تا در مودال تب نتایج
   و در ارسال به باسلام و ووکامرس به‌صورت جدول رندر شوند. */
$val=s4ExtractDetailNodeValue((string)$field,$ns,(string)$dr['url']);
}
if($val){$allProducts[$key][$field]=$val;$_gotFields++;if($field==='image')$imgMain++;}
}
}
if($_isSnappSynth&&empty($allProducts[$key]['specs'])){
$_snTblTwo=@$xp2->query('//table[contains(@class,"shop_attributes")]');
if($_snTblTwo&&$_snTblTwo->length){
$_snSpTwo=s4ExtractDetailNodeValue('specs',$_snTblTwo,(string)$dr['url']);
if($_snSpTwo!==''){$allProducts[$key]['specs']=$_snSpTwo;$_gotFields++;}
}
}
if(!empty($allProducts[$key]['weight'])&&function_exists('s4ParseWeightGrams')&&s4ParseWeightGrams($allProducts[$key]['weight'])<=0){
$allProducts[$key]['weight']='';
}
if(empty($allProducts[$key]['weight'])&&!empty($allProducts[$key]['specs'])&&function_exists('s4ExtractWeightsFromSpecs')){
$_spWtTwo=s4ExtractWeightsFromSpecs($allProducts[$key]['specs']);
if(!empty($_spWtTwo['raw'])&&(($_spWtTwo['net_g']??0)>0||($_spWtTwo['pkg_g']??0)>0)){
$allProducts[$key]['weight']=(string)$_spWtTwo['raw'];
if(($_spWtTwo['pkg_g']??0)>0)$allProducts[$key]['package_weight']=(int)$_spWtTwo['pkg_g'].' گرم';
$_gotFields++;
}
}
if(empty($allProducts[$key]['weight'])&&function_exists('s4AutoExtractWeightFromDetailDom')){
$_domWtTwo=s4AutoExtractWeightFromDetailDom($xp2,(string)($dr['html']??''));
if(!empty($_domWtTwo['weight'])){$allProducts[$key]['weight']=(string)$_domWtTwo['weight'];$_gotFields++;}
if(!empty($_domWtTwo['package_weight'])&&empty($allProducts[$key]['package_weight']))$allProducts[$key]['package_weight']=(string)$_domWtTwo['package_weight'];
}

if(empty($allProducts[$key]['image'])){
$ogImg=@$xp2->query("//meta[@property='og:image']/@content");
if($ogImg&&$ogImg->length){
$imgUrl=$ogImg->item(0)->nodeValue;
if($imgUrl&&url_is_image($imgUrl))$allProducts[$key]['image']=make_absolute_url($imgUrl,$dr['url']);
}
}

// v8.64: گالری — بقیهٔ عکس‌های همین صفحهٔ محصول
if($galleryCfg['enabled']){
$gal=galleryExtract($xp2,null,$dr['url'],$galleryCfg);
if($_isSnappSynth)$allProducts[$key]['_snapp_gal_v453']=1;
if(!empty($gal['images'])){
$nImg=galleryApplyToProduct($allProducts[$key],$gal['images'],$_forceAll);
$_gotImgs=$nImg;
if($nImg>1){$galleryFound++;$galleryImgsTotal+=$nImg;}
}
}
$detailFields+=$_gotFields;
/* v10.21 (۳۴الف): «موجود بودن» از روی قیمتِ صفحهٔ محصول.

   خواستهٔ کاربر برای پروفایل‌های اکسل/CSV این بود که سینکِ دوره‌ای هم
   قیمت و هم موجودی را تازه کند. سایت‌ها معمولاً محصولِ ناموجود را با
   حذفِ قیمت (یا «تماس بگیرید») نشان می‌دهند، پس همین سیگنال کافی است و
   نیازی به سلکتورِ تازه ندارد.

   محافظه‌کارانه: فقط وقتی صفحه واقعاً باز شده باشد قضاوت می‌کنیم. اگر
   مبدأ در دسترس نبود، دست به موجودی نمی‌زنیم — وگرنه یک قطعیِ چنددقیقه‌ای
   کلِ غرفه را ناموجود می‌کرد. */
if(!empty($detailSelectors['price'])){
    $_wasIn = !array_key_exists('in_stock',$allProducts[$key]) || !empty($allProducts[$key]['in_stock']);
    $_isIn  = detailStockFromPrice(['price'=>($_freshPrice===null?'':$_freshPrice)], true);
    if($_isSnappSynth && $_isIn === false && strpos($dr['html'], '<meta property="product:availability" content="in stock">') !== false){
        $_isIn = true;
    }
    /* v10.475: جلوگیری از ناموجودشدن دسته‌جمعی کاذب وقتی صفحهٔ جزئیات رندر نشده/سلکتور قیمت تطبیق نداده
       اما نشانهٔ صریح ناموجودی (ناموجود / OutOfStock / تماس بگیرید) در صفحه نیست. */
    if($_isIn === false && ($_freshPrice === null || trim((string)$_freshPrice) === '')){
        $_explicitOos = detailPageHasExplicitOosSignal($xp2, (string)($dr['html'] ?? ''));
        $_hadPriorPrice = extractPriceNum($allProducts[$key]['price'] ?? '') > 0;
        if(!$_explicitOos && (($_gotFields === 0 && $_gotImgs <= 1 && $_gotVars === 0) || $_hadPriorPrice)){
            $_isIn = null;
        }
    }
    if($_isIn !== null){
        $allProducts[$key]['in_stock']    = $_isIn;
        $allProducts[$key]['stock_src']   = 'detail_price';
        $allProducts[$key]['stock_at']    = time();
        if($_wasIn && !$_isIn){ $_stockOut++;  $pushLog('  ⛔ '.$_pTitle.' — قیمت ندارد ⇒ ناموجود'); }
        elseif(!$_wasIn && $_isIn){ $_stockBack++; $pushLog('  ✅ '.$_pTitle.' — دوباره موجود شد'); }
    }
}
/* A page is resolved only when it yielded requested detail, a real gallery,
   or a trustworthy out-of-stock result. Invalid selectors/empty proxy pages
   remain retryable instead of being silently called complete. */
$_detailResolved=($_gotFields>0||$_gotImgs>1||($_isIn===false&&!empty($detailSelectors['price'])));
if($_detailResolved){
    $allProducts[$key]['_detail_cycle']=$_detailCycle;
    $allProducts[$key]['_detail_checked_at']=time();
    unset($allProducts[$key]['_detail_new_pending'],$allProducts[$key]['_detail_fail_tries'],$allProducts[$key]['_detail_fail_cycle'],$allProducts[$key]['_detail_capped']);
} else {
    $_nfPrevCyc=(string)($allProducts[$key]['_detail_fail_cycle']??'');
    $_nfTries=($_nfPrevCyc===$_detailCycle)?((int)($allProducts[$key]['_detail_fail_tries']??0)+1):1;
    $allProducts[$key]['_detail_fail_cycle']=$_detailCycle;
    $allProducts[$key]['_detail_fail_tries']=$_nfTries;
    if($_nfTries>=3){
        $allProducts[$key]['_detail_cycle']=$_detailCycle;
        $allProducts[$key]['_detail_checked_at']=time();
        $allProducts[$key]['_detail_capped']='nofield';
        unset($allProducts[$key]['_detail_new_pending']);
        $_detailCapped++;
    } else {
        unset($allProducts[$key]['_detail_cycle']);
        $detailNoField++;
        if(count($emptySamples)<3)$emptySamples[]=$_pTitle;
    }
}
$pushLog('  ✓ '.$_pTitle.' — '
  .($_gotFields?($_gotFields.' فیلد'):'بدون فیلد')
  .($_gotVars?(' · '.$_gotVars.' تنوع'):'')
  .($_gotImgs>1?(' · 🖼 '.$_gotImgs.' عکس'):($_gotImgs===1?' · ۱ عکس':'')));
}else{
/* v8.90 / v10.475: ثبت علت خطا + سقف تلاش به ازای هر محصول تا صفحات ۴۰۴/خراب حلقهٔ بی‌نهایت (۱۷۵+ دور) نسازند و اطلاعات قبلی محصول حفظ شود */
$_dErrCode=(int)($dr['code']??0);
$_maxFailTries=in_array($_dErrCode,[404,410],true)?2:3;
$_fPrevCyc=(string)($allProducts[$key]['_detail_fail_cycle']??'');
$_fTries=($_fPrevCyc===$_detailCycle)?((int)($allProducts[$key]['_detail_fail_tries']??0)+1):1;
$allProducts[$key]['_detail_fail_cycle']=$_detailCycle;
$allProducts[$key]['_detail_fail_tries']=$_fTries;
$_err=trim((string)($dr['error']??''));
if($_err==='')$_err='HTTP '.$_dErrCode;
if($_fTries>=$_maxFailTries){
    $allProducts[$key]['_detail_cycle']=$_detailCycle;
    $allProducts[$key]['_detail_checked_at']=time();
    $allProducts[$key]['_detail_capped']='http_'.$_dErrCode;
    unset($allProducts[$key]['_detail_new_pending']);
    $_detailCapped++;
    $pushLog('  ⏭ '.$_pTitle.' — صفحه باز نشد ('.mb_substr($_err,0,40).')؛ دادهٔ قبلی محصول حفظ شد');
} else {
    $detailFail++;
    if(count($failSamples)<3)$failSamples[]=$_pTitle.' ('.mb_substr($_err,0,40).')';
    $pushLog('  ✗ '.$_pTitle.' — صفحه باز نشد: '.mb_substr($_err,0,50));
}
}
/* v8.90: هر ۲ محصول به‌روزرسانی کن (قبلاً هر ۵ تا) و به‌جای یک خط
   خشک، بگو چه چیزی به دست آمده و چه چیزی نه. */
if($detailDone%2===0||$detailDone==$detailTotal){
$_pct=$detailTotal>0?(int)round($detailDone/$detailTotal*100):0;
$logs=['🔍 جزئیات '.$detailDone.' از '.$detailTotal.' ('.$_pct.'٪)'];
$_sum='   • ✅ '.$detailOk.' صفحه باز شد';
if($detailFail>0)$_sum.=' · ❌ '.$detailFail.' باز نشد';
if($_detailCapped>0)$_sum.=' · 🛡 '.$_detailCapped.' با حفظ دادهٔ قبلی رد شد';
if($detailFields>0)$_sum.=' · 🏷 '.$detailFields.' فیلد';
if($varFound>0)$_sum.=' · 🎨 '.$varFound.' محصول تنوع‌دار';
$logs[]=$_sum;
if($galleryCfg['enabled']){
$logs[]='   • 🖼 گالری: '.$galleryFound.' محصول چندعکسی · مجموع '.$galleryImgsTotal.' تصویر'
        .($galleryFound>0?(' · میانگین '.round($galleryImgsTotal/max(1,$galleryFound),1).' عکس'):'');
}
if($detailNoField>0)$logs[]='   • ⚠️ '.$detailNoField.' محصول هیچ فیلدی نداد'
        .($emptySamples?(' — مثل: '.implode('، ',$emptySamples)):'');
if($failSamples)$logs[]='   • ✗ نمونهٔ خطا: '.implode(' | ',$failSamples);
foreach($detailLog as $_dl)$logs[]=$_dl;
// قیمت‌ها در این مرحله ممکن است تکمیل شوند، پس مقایسه دوباره محاسبه می‌شود
$liveCmp=extractLiveCompare($allProducts,$livePrevMap);
extractLockTouch($queueId);   // v10.32 (۴۵ب): ضربان، تا قفلِ اجرای سالم کهنه نشود
writeProgress(EXTRACT_PROGRESS_FILE,array_merge(['running'=>true,'done'=>false,'total'=>(($autoPageMode?$totalPages:$maxPages)+$detailTotal),'current'=>$totalPages+$detailDone,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'profile_key'=>$pkFinal,'resume_phase'=>'detail','extract_stage'=>'detail','recent_log'=>$logs,'total_log_count'=>$totalPages+$detailDone,'extracted'=>count($allProducts),'phase'=>'detail','detail_current'=>$detailDone,'detail_total'=>$detailTotal,'detail_ok'=>$detailOk,'detail_fail'=>$detailFail,'detail_fields'=>$detailFields,'detail_nofield'=>$detailNoField,'gallery_products'=>$galleryFound,'gallery_images'=>$galleryImgsTotal,'variation_products'=>$varFound],$_stageProgressMeta,$liveCmp));
}
/* v8.94: هر ۵ محصول، کارِ انجام‌شده روی دیسک بنشیند.

   نوشتن فایل پیشرفت فقط برای نمایش است؛ خودِ گالری‌ها در $allProducts
   می‌مانند و تا ۸.۹۳ فقط در انتها ذخیره می‌شدند. اگر هاست وسط این حلقه
   پردازه را می‌کشت، همهٔ عکس‌های جمع‌شده دور ریخته می‌شد.
   حالا بدترین حالت، از دست رفتن کارِ ۵ محصول آخر است. */
/* v9.06: هر محصول، نه هر ۵ محصول.

   با فاصلهٔ ۵ تایی، اگر پردازه قبل از پنجمین محصول کشته می‌شد، کارِ
   هر چهار محصول قبلی هم دور ریخته می‌شد و اجرای بعدی از صفر شروع
   می‌کرد. روی هاستی که هر بار وسط فاز جزئیات می‌مُرد، این یعنی هیچ
   گالری‌ای هرگز روی دیسک نمی‌نشست — همان چیزی که کاربر می‌دید.
   هزینهٔ نوشتن یک فایل در برابر یک درخواست HTTP ناچیز است. */
extractCheckpoint($pkFinal,$allProducts,
    ['_extract_stage'=>'detail','_extract_stage_at'=>time(),
     '_extract_detail_done'=>$detailDone,'_extract_detail_total'=>$detailTotal]);
usleep(200000);
}
unset($GLOBALS['_s4SnappDetailDeadline'],$GLOBALS['_s4SnappDetailQueueId'],$GLOBALS['_s4SnappCooldownHeartbeat']);
/* v8.94: پایان فاز جزئیات — قبل از هر کار دیگری ذخیره کن.
   v8.97: اگر وقت تمام شده و کار ناتمام مانده، نشانه را «detail» بگذار
   نه «detail_done»، تا اجرای بعدی بداند باید ادامه بدهد. */
$_detailIncomplete=($_ranOut||$detailDone<$detailTotal||$detailFail>0||$detailNoField>0);
extractCheckpoint($pkFinal,$allProducts,
    ['_extract_stage'=>$_detailIncomplete?'detail':'detail_done','_extract_stage_at'=>time(),
     '_extract_resume_needed'=>$_detailIncomplete?1:0,
     '_extract_detail_cycle'=>$_detailCycle,
     '_extract_detail_done'=>$detailDone,'_extract_detail_total'=>$detailTotal]);
/* v8.90: جمع‌بندی پایان فاز ۲ — یک نگاه و می‌فهمی چه شد. */
$_sumLines=$_detailIncomplete
  ? ['⏸ فاز ۲ هنوز کامل نیست — '.max(0,$detailDone-$detailFail-$detailNoField).' از '.$detailTotal.' محصول این نوبت حل شد',
     '   • باقی‌مانده و خطاهای قابل‌تلاش در چک‌پوینت حفظ شدند',
     '   • اجرای بعدی از اولین محصول حل‌نشده ادامه می‌دهد، نه از محصول اول']
  : ['✅ فاز ۲ تمام شد — '.$detailDone.' محصول بررسی شد'];
$_sumLines[]='   • ✅ '.$detailOk.' صفحه باز شد'
  .($detailFail>0?(' · ❌ '.$detailFail.' باز نشد'):'')
  .($_detailCapped>0?(' · 🛡 '.$_detailCapped.' با حفظ دادهٔ قبلی رد شد'):'')
  .' · 🏷 '.$detailFields.' فیلد استخراج شد';
if($galleryCfg['enabled'])
$_sumLines[]='   • 🖼 گالری: '.$galleryImgsTotal.' تصویر از '.$galleryFound.' محصول';
if($varFound>0)$_sumLines[]='   • 🎨 '.$varFound.' محصول تنوع دارد';
if($detailNoField>0)$_sumLines[]='   • ⚠️ '.$detailNoField.' محصول هیچ فیلدی نداد — سلکتورهای جزئیات را بررسی کنید';
if($detailFail>0&&$failSamples)$_sumLines[]='   • ✗ '.implode(' | ',$failSamples);
/* v9.00: اگر همهٔ صفحه‌ها بسته بودند و علتش ۴۰۳/۴۲۹ بود، یعنی سایت مبدأ
   IP سرور را بلاک کرده. این حالت دقیقاً شبیه «گالری استخراج نمی‌شود» به
   نظر می‌رسد ولی ربطی به سلکتور ندارد، پس صریح گفته می‌شود. */
$_blockHint='';
foreach($failSamples as $_fs){ if(strpos($_fs,'403')!==false||strpos($_fs,'429')!==false){$_blockHint=$_fs;break;} }
if($detailOk===0&&$detailFail>0&&$_blockHint!==''){
$_sumLines[]='   • ⛔ سایت مبدأ صفحهٔ محصولات را به سرور نمی‌دهد (۴۰۳/۴۲۹)';
$_sumLines[]='   • یعنی IP هاست بلاک یا محدود شده — سلکتورها سالم‌اند';
$_sumLines[]='   • تنظیمات ← «اتصال به سایت مبدأ»: فاصلهٔ بین درخواست‌ها را زیاد کنید یا پروکسی بگذارید';
}
$liveCmp=extractLiveCompare($allProducts,$livePrevMap);
writeProgress(EXTRACT_PROGRESS_FILE,array_merge(['running'=>true,'done'=>false,'total'=>(($autoPageMode?$totalPages:$maxPages)+$detailTotal),'current'=>$totalPages+$detailDone,'started_at'=>$startedAt,'last_progress_ts'=>time(),'queue_id'=>$queueId,'profile_key'=>$pkFinal,'resume_phase'=>'detail','extract_stage'=>'detail','recent_log'=>$_sumLines,'total_log_count'=>$totalPages+$detailDone+1,'extracted'=>count($allProducts),'phase'=>'detail','detail_current'=>$detailDone,'detail_total'=>$detailTotal,'detail_ok'=>$detailOk,'detail_fail'=>$detailFail,'detail_fields'=>$detailFields,'detail_nofield'=>$detailNoField,'gallery_products'=>$galleryFound,'gallery_images'=>$galleryImgsTotal,'variation_products'=>$varFound],$_stageProgressMeta,$liveCmp));
}
if ($_detailExtractMode === 'inline' && $_inlineDetailDone > 0) {
    $detailTotal += $_inlineDetailDone;
    $detailDone += $_inlineDetailDone;
    $detailOk += $_inlineDetailOk;
    $detailFail += $_inlineDetailFail;
    $detailFields += $_inlineDetailFields;
    $galleryFound += $_inlineGalleryFound;
    $galleryImgsTotal += $_inlineGalleryImgs;
    $varFound += $_inlineVarFound;
    if ($_skipWhy === 'already_done') $_skipWhy = '';
}

/* Never persist parser placeholders as products. Detail extraction gets the
   first chance to supply missing title/price; anything still invalid is now
   discarded. Invalid historical rows were also removed from the comparison
   baseline above, so this cleanup does not archive destination products.
   v10.475: هنگام ناتمام‌بودن فاز ۲ برای پروفایل‌هایی که قیمت را از صفحهٔ جزئیات می‌گیرند،
   آیتم‌های هنوز بازنشده را حذف نکن تا در برش بعدی قیمتشان استخراج شود. */
$_invalidExtracted=0;
foreach($allProducts as $_ivk=>$_ivp){
    if(!is_array($_ivp)){unset($allProducts[$_ivk]);$_invalidExtracted++;continue;}
    if(!extractedProductIsValid($_ivp)){
        if(!empty($_detailIncomplete) && $_detailSuppliesPrice
            && trim(strip_tags((string)($_ivp['title']??'')))!==''
            && trim((string)($_ivp['link']??''))!==''
            && (string)($_ivp['_detail_cycle']??'')!==$_detailCycle){
            continue;
        }
        unset($allProducts[$_ivk]);
        $_invalidExtracted++;
    }
}

$newCount=0;$priceChanged=0;$unchanged=0;$removedCount=0;
$newItems=[];$changedItems=[];$removedItems=[];

/* v9.04: در حالت «فقط جزئیات» مبنای مقایسه همان محصولاتی است که این
   اجرا رویشان کار کرده، نه نسخهٔ قبل‌تر. وگرنه چون گام فهرست جداگانه
   ذخیره کرده بود، مقایسه همه را «حذف‌شده» می‌دید و کران گزارش
   removed=6 می‌داد در حالی که هیچ محصولی حذف نشده بود. */
$prevMap=[];
if($phase==='detail'){
    $prevMap=$prevByKey;
}elseif(!empty($prevProducts)){
$firstEntry=reset($prevProducts);
if(is_array($firstEntry)&&count($firstEntry)>=2&&is_string($firstEntry[0])){

foreach($prevProducts as $entry){if(is_array($entry)&&count($entry)>=2)$prevMap[$entry[0]]=$entry[1];}
}else{

$prevMap=$prevProducts;
}
}
foreach($prevMap as $_ivk=>$_ivp){if(!is_array($_ivp)||!extractedProductIsValid($_ivp))unset($prevMap[$_ivk]);}

// v8.22: همان تابعی که در حین اجرا استفاده شد، تا نتیجهٔ نهایی با
// شمارنده‌های زنده اختلاف نداشته باشد.
// v8.39: سقف بالاتر برای مقایسهٔ نهایی — این لیست‌ها مبنای «ارسال فقط
// تغییرات» هستند، پس اگر بریده شوند محصولی بی‌صدا جا می‌ماند.
/* v10.238: محصولی که اجرای کامل مبدأ صریحاً ناموجود تشخیص داده است
   دیگر در snapshot پروفایل نگه داشته نمی‌شود. بنابراین خودِ پروفایل منبع
   حقیقت چرخهٔ افزودن/آپدیت/حذف می‌ماند: این unset پیش از مقایسه، محصول را
   وارد removed_items می‌کند تا مقصدها هم بازنشسته شوند. روی اجرای ناقص یا
   فقط-list اعمال نمی‌شود تا خطای موقت استخراج باعث حذف کاذب نشود. */
$_profilePrunedUnavailable = [];
$_oosPruneBlocked = false;
if ($phase !== 'list' && empty($_detailIncomplete) && empty($_listRanOut)) {
    $_candOosKeys = [];
    foreach ($allProducts as $_apuKey => $_apuProduct) {
        if (is_array($_apuProduct) && array_key_exists('in_stock', $_apuProduct) && empty($_apuProduct['in_stock'])) {
            $_candOosKeys[] = $_apuKey;
        }
    }
    if (!empty($_candOosKeys)) {
        $_preOosValid  = max(count($prevMap), extractCountValidProducts($allProducts));
        $_postOosValid = max(0, extractCountValidProducts($allProducts) - count($_candOosKeys));
        $_oosGuard = extractShouldBlockShrinkage($_preOosValid, $_postOosValid, [
            'had_errors' => ($detailFail > 0 || $detailNoField > 0 || ($_detailCapped ?? 0) > 0),
            'stage'      => 'oos_prune',
        ]);
        if (!empty($_oosGuard['blocked'])) {
            $_oosPruneBlocked = true;
            foreach ($_candOosKeys as $_rkOos) {
                if (isset($prevMap[$_rkOos]) && (!array_key_exists('in_stock', $prevMap[$_rkOos]) || !empty($prevMap[$_rkOos]['in_stock']))) {
                    $allProducts[$_rkOos]['in_stock'] = true;
                }
            }
        } else {
            foreach ($_candOosKeys as $_apuKey) {
                $_apuProduct = $allProducts[$_apuKey];
                $_apuProduct['key'] = (string)$_apuKey;
                $_apuProduct['reason'] = 'ناموجود در مبدأ — حذف از snapshot پروفایل';
                $_profilePrunedUnavailable[] = $_apuProduct;
                unset($allProducts[$_apuKey]);
            }
        }
    }
    unset($_candOosKeys);
}
$finalCmp=extractLiveCompare($allProducts,$prevMap,100000);
if ($_profilePrunedUnavailable) {
    $finalCmp['removed_items'] = mergeRetireItems((array)($finalCmp['removed_items'] ?? []), $_profilePrunedUnavailable);
    $finalCmp['removed'] = count($finalCmp['removed_items']);
}
$newCount=$finalCmp['new'];
$priceChanged=$finalCmp['price_changed'];
$removedCount=$finalCmp['removed'];
$unchanged=$finalCmp['unchanged'];
$newItems=$finalCmp['new_items'];
$changedItems=$finalCmp['changed_items'];
$removedItems=$finalCmp['removed_items'];
$priceUp=$finalCmp['price_up'];
$priceDown=$finalCmp['price_down'];

$productsData=[];$productsOrder=array_keys($allProducts);
foreach($allProducts as $key=>$p){$productsData[]=[$key,$p];}
/* v8.91: پروفایل را دوباره از دیسک بخوان و فقط محصولات را روی آن بنویس.

   سومین علتِ گم شدن تنظیمات. $profiles همان نسخه‌ای است که در ثانیهٔ
   اولِ اجرا خوانده شد. یک استخراج با گالری روشن چند دقیقه تا چند ساعت
   طول می‌کشد و در تمام آن مدت کاربر بیدار است: سلکتور گالری را عوض
   می‌کند، دستهٔ مقصد را تنظیم می‌کند، پروفایل دیگری را ویرایش می‌کند.
   نوشتنِ آن نسخهٔ کهنه، همهٔ آن تغییرات را — و حتی پروفایل‌های دیگر را —
   به عقب برمی‌گرداند. کاربر می‌دید تنظیمی که خودش نیم ساعت پیش ذخیره
   کرده بود، بی‌دلیل به حالت قبل برگشته.

   حالا فقط چیزی نوشته می‌شود که واقعاً حاصل این اجراست.
   v8.94: $pkFinal بالاتر — قبل از اولین نقطهٔ امن — تعیین شده است. */
$_productsSavedFinal = true;
$_finalShrinkGuard = '';
$_finalPrevValidCount = count($prevMap);
$_endLfp=@fopen(PROFILES_FILE.'.extract.lock','c');if($_endLfp)@flock($_endLfp,LOCK_EX);
try{
$profilesNow=loadProfiles();
$profileOnDisk=is_array($profilesNow[$pkFinal]??null)?$profilesNow[$pkFinal]:$profile;
$_diskValidNow = extractCountValidProducts((array)($profileOnDisk['products'] ?? []));
$_finalPrevValidCount = max($_finalPrevValidCount, $_diskValidNow);
$_finalNewValidCount  = extractCountValidProducts($allProducts);
$_finalShrinkRes = extractShouldBlockShrinkage($_finalPrevValidCount, $_finalNewValidCount, [
    'incomplete'    => (!empty($_detailIncomplete) || !empty($_listRanOut)),
    'had_errors'    => ($detailFail > 0 || $detailNoField > 0 || ($_detailCapped ?? 0) > 0 || !empty($_hadListFetchErrors)),
    'stopped_early' => !empty($_stoppedByEarlySignal),
    'stage'         => 'final_save',
]);
if (!empty($_finalShrinkRes['blocked'])) {
    /* v10.475: حفظ ۱۰۰٪ نتایج استخراج قبلی روی دیسک در صورت خطا/گیرکردن/کاهش غیرعادی */
    $_productsSavedFinal = false;
    $_finalShrinkGuard = (string)$_finalShrinkRes['reason'];
    $removedItems = [];
    $removedCount = 0;
    if (!empty($_detailIncomplete) && $_detailSuppliesPrice) {
        extractWriteStagingRawFile($pkFinal, $allProducts, $_detailCycle);
    } else {
        extractClearListStaging($pkFinal);
    }
} else {
    $profileOnDisk['products']=$productsData;
    $profileOnDisk['productsOrder']=$productsOrder;
    $profileOnDisk['updatedAt']=time();
    $profileOnDisk['_extract_shrink_guard_tries']=0;
    if (empty($_detailIncomplete) && empty($_listRanOut)) {
        extractClearListStaging($pkFinal);
    }
}
/* v8.94: کار تمام شد — نشانهٔ «نیمه‌کاره» برداشته شود، وگرنه محافظِ
   ارسال تا ابد بسته می‌ماند و هیچ محصولی هرگز فرستاده نمی‌شود. */
/* v8.97: اگر فاز جزئیات به‌خاطر سقف زمانی ناتمام مانده، «complete»
   ننویس — وگرنه اجرای بعدی فکر می‌کند کار تمام شده و بقیهٔ محصولات
   هیچ‌وقت گالری نمی‌گیرند، و دروازهٔ ارسال هم زودتر از موعد باز می‌شود. */
/* v9.01: اجرای «فقط فهرست» تمام‌شده حساب نمی‌شود — هنوز مرحلهٔ جزئیات
   مانده. با نشانهٔ list_done، هم دروازهٔ ارسال بسته می‌ماند و هم اجرای
   بعدی می‌داند باید جزئیات را بگیرد. */
$profileOnDisk['_extract_stage']=($phase==='list'&&$detailConfigured)?'list_done':((!empty($_detailIncomplete)||!empty($_listRanOut))?'detail':'complete');
$profileOnDisk['_extract_detail_cycle']=$_detailCycle;
$profileOnDisk['_extract_resume_needed']=(!empty($_detailIncomplete)||!empty($_listRanOut))?1:0;
if(empty($_detailIncomplete)&&empty($_listRanOut)&&($phase!=='list'||!$detailConfigured)){
    $profileOnDisk['_extract_list_incomplete']=false;
    $profileOnDisk['_extract_resume_req']=0;
    $profileOnDisk['_extract_resume_from']=0;
    $profileOnDisk['_extract_resume_phase']='';
    $profileOnDisk['_extract_want_detail']=0;
}
if(!empty($_listRanOut)){
    $profileOnDisk['_extract_stage']='list';
    $profileOnDisk['_extract_list_incomplete']=true;
}
$profileOnDisk['_extract_stage_at']=time();
$profileOnDisk['_extract_detail_done']=$detailDone;
$profileOnDisk['_extract_detail_total']=$detailTotal;
/* The explicit incomplete-profile scope survives checkpoints, then is cleared
   only after its detail pass really finishes. */
if($phase==='detail'&&empty($_detailIncomplete)&&empty($_listRanOut)){
    unset($profileOnDisk['_sync_detail_scope_keys'],$profileOnDisk['_sync_detail_scope_meta']);
}
$profilesNow[$pkFinal]=$profileOnDisk;
saveProfiles($profilesNow,true);
unset($profilesNow);
}finally{if($_endLfp){@flock($_endLfp,LOCK_UN);@fclose($_endLfp);}}
$profile=$profileOnDisk;
if(isset($GLOBALS['_extractDetailFatalCtx']))$GLOBALS['_extractDetailFatalCtx']['active']=false;

/* v10.83: اگر تیک «تولید خودکار توضیحات» روشن است، فقط روی محصولاتِ همین
   پروفایل که توضیح/دسته ندارند AI بزن — قبل از ارسال به باسلام. */
try {
    $_aiCfg = aiContentAutoCfg(loadConnections());
    if (!empty($_aiCfg['enabled']) && $phase !== 'list' && $_productsSavedFinal) {
        $_aiN = 0; $_aiFilled = 0;
        $_aiMax = min(12, (int)$_aiCfg['per_run']);
        $_aiProds = is_array($profileOnDisk['products'] ?? null) ? $profileOnDisk['products'] : [];
        $_aiChanged = false;
        foreach ($_aiProds as $_aiI => $_aiE) {
            if ($_aiN >= $_aiMax) break;
            $_aiPair = is_array($_aiE) && count($_aiE) === 2 && is_array($_aiE[1] ?? null);
            $_aiP = $_aiPair ? $_aiE[1] : (is_array($_aiE) ? $_aiE : null);
            if (!is_array($_aiP) || !aiProductNeedsContent($_aiP)) continue;
            $_aiN++;
            $_aiR = aiFillProductContent($_aiP, !empty($_aiCfg['web_search']), !empty($_aiCfg['bsl_cats']));
            if (!empty($_aiR['filled'])) {
                if ($_aiPair) $_aiProds[$_aiI][1] = $_aiR['product'];
                else $_aiProds[$_aiI] = $_aiR['product'];
                $_aiChanged = true;
                $_aiFilled++;
            }
        }
        if ($_aiChanged) {
            $profileOnDisk['products'] = $_aiProds;
            saveOneProfileAtomic($pkFinal,$profileOnDisk);
            $profile = $profileOnDisk;
            $GLOBALS['_aiContentFilled'] = $_aiFilled;
        }
    }
} catch (Throwable $_aiEx) { /* never break extract */ }

/* v8.90: خلاصهٔ پایانی، جزئیات فاز ۲ را هم نگه دارد.
   قبلاً این نوشتن آخر، همهٔ لاگ و شمارنده‌های جزئیات را پاک می‌کرد و
   کاربر فقط یک خط «تکمیل شد» می‌دید — یعنی همان چیزی که می‌خواست بداند
   (چند صفحه باز شد، چند عکس آمد، چه چیزی نیامد) از بین می‌رفت. */
$_finalComplete=($phase==='list'||(empty($_detailIncomplete)&&empty($_listRanOut)));
$finalLog=$_finalComplete
    ? ['✅ استخراج تکمیل شد — '.($_productsSavedFinal?count($allProducts):$_finalPrevValidCount).' محصول']
    : ['⏸ استخراج جزئیات موقتاً متوقف شد — صفِ باقی‌مانده حفظ شده است'];
if(!$_productsSavedFinal){
    $finalLog[]='🛡 گارد حفاظت نتایج: '.$_finalPrevValidCount.' محصول قبلی ثابت نگه داشته شد (خروجی ناقص/کاهش‌یافته ذخیره نشد)';
}
if($_oosPruneBlocked){
    $finalLog[]='🛡 گارد حفاظت موجودی: حذف دسته‌جمعی ناموجودهای مشکوک متوقف شد تا کاتالوگ پروفایل آسیب نبیند';
}
if($_invalidOld>0||$_invalidExtracted>0)$finalLog[]='🧹 '.($_invalidOld+$_invalidExtracted).' ردیف بدون عنوان یا قیمت از پروفایل کنار گذاشته شد';
if (!empty($GLOBALS['_aiContentFilled'])) {
    $finalLog[] = '   • 🤖 تولید خودکار توضیح/دسته: ' . (int)$GLOBALS['_aiContentFilled'] . ' محصول';
    unset($GLOBALS['_aiContentFilled']);
}
$finalLog[]='   • 🆕 '.$newCount.' جدید · 💰 '.$priceChanged.' تغییر قیمت · ❌ '.$removedCount.' حذف‌شده · ⏭ '.$unchanged.' بدون تغییر';
if($detailTotal>0){
$finalLog[]='   • 🔍 جزئیات: '.$detailOk.' صفحه باز شد'
  .($detailFail>0?(' · '.$detailFail.' باز نشد'):'')
  .((($_detailCapped??0)>0)?(' · '.($_detailCapped??0).' با حفظ دادهٔ قبلی رد شد'):'')
  .' · '.$detailFields.' فیلد';
if($galleryCfg['enabled'])
$finalLog[]='   • 🖼 گالری: '.$galleryImgsTotal.' تصویر از '.$galleryFound.' محصول';
/* v9.09: گالری روشن بود، صفحه‌ها هم باز شدند، ولی هیچ عکسی نیامد.
   تا حالا این حالت «موفق» گزارش می‌شد و کاربر فقط می‌دید گالری خالی
   است بدون هیچ توضیحی. علت تقریباً همیشه یکی از این دوتاست: سلکتور
   «کادر گالری» با ساختار صفحهٔ محصول نمی‌خواند، یا عکس‌ها با
   جاوااسکریپت بعداً تزریق می‌شوند و در HTML خام نیستند. */
if($galleryCfg['enabled']&&$detailOk>0&&$galleryImgsTotal===0){
$finalLog[]='   • ⛔ گالری روشن است ولی هیچ تصویری پیدا نشد'
  .($galleryCfg['box']!==''?(' — کادر گالری: '.mb_substr($galleryCfg['box'],0,40)):' — کادر گالری تنظیم نشده');
$finalLog[]='   • یعنی سلکتور کادر با صفحهٔ محصول نمی‌خواند، یا عکس‌ها با جاوااسکریپت می‌آیند';
}
if($varFound>0)$finalLog[]='   • 🎨 '.$varFound.' محصول تنوع دارد';
// v10.21 (۳۴الف): تغییرِ موجودی که از روی قیمتِ صفحه تشخیص داده شد
if($_stockOut>0||$_stockBack>0)
$finalLog[]='   • 📦 موجودی: '.$_stockOut.' ناموجود شد · '.$_stockBack.' دوباره موجود شد';
if($detailNoField>0)$finalLog[]='   • ⚠️ '.$detailNoField.' محصول هیچ فیلدی نداد — سلکتورها را بررسی کنید';
if($failSamples)$finalLog[]='   • ✗ '.implode(' | ',$failSamples);
}
$_reportedFinalCount = $_productsSavedFinal ? count($allProducts) : $_finalPrevValidCount;
writeProgress(EXTRACT_PROGRESS_FILE,array_merge(['running'=>false,'done'=>$_finalComplete,'paused'=>!$_finalComplete,'resume_needed'=>!$_finalComplete,'total'=>(($autoPageMode?$totalPages:$maxPages)+$detailTotal),'current'=>$totalPages+$detailDone,'started_at'=>$startedAt,'finished_at'=>time(),'avg_ppm'=>max(0,(int)round(count($allProducts)*60/max(1,time()-$startedAt))),'last_progress_ts'=>time(),'queue_id'=>$queueId,'recent_log'=>$finalLog,'total_log_count'=>$totalPages+$detailDone+1,'extracted'=>$_reportedFinalCount,'new'=>$newCount,'price_changed'=>$priceChanged,'removed'=>$removedCount,'unchanged'=>$unchanged,'price_up'=>$priceUp,'price_down'=>$priceDown,'new_items'=>$newItems,'changed_items'=>$changedItems,'removed_items'=>$removedItems,'products_saved'=>$_productsSavedFinal,'guard'=>$_finalShrinkGuard,'profile_key'=>$profileKey??profileKey($url),'total_pages'=>$totalPages,'detail_current'=>$detailDone,'detail_skip_why'=>$_skipWhy,'detail_no_link'=>$_noLink,'detail_already'=>$_alreadyDone,'phase'=>(($phase!=='list'&&$detailTotal>0)?($_detailExtractMode==='inline'&&$phase!=='detail'?'list_detail':'detail'):'list'),'detail_ok'=>$detailOk,'detail_fail'=>$detailFail,'detail_capped'=>$_detailCapped??0,'detail_fields'=>$detailFields,'detail_nofield'=>$detailNoField,'detail_total'=>$detailTotal,'gallery_products'=>$galleryFound,'gallery_images'=>$galleryImgsTotal,'variation_products'=>$varFound],$_stageProgressMeta));

$queue=extractReadQueue();
// v8.25: نتیجهٔ کامل هر اجرا جداگانه ذخیره می‌شود تا مودالِ کارهای
// تمام‌شده هم بتواند فهرست محصولات را نشان دهد، نه فقط لاگ زنده.
extractSaveReport($queueId, [
    'new_items'     => $newItems,
    'changed_items' => $changedItems,
    'removed_items' => $removedItems,
    'unchanged'     => $unchanged,
    'price_up'      => $priceUp,
    'price_down'    => $priceDown,
    'extracted'     => $_reportedFinalCount,
    'products_saved'=> $_productsSavedFinal,
    'guard'         => $_finalShrinkGuard,
