if(isset($_GET['action']) && $_GET['action'] === 'backend_extract'){
$profileKey=trim($_GET['profile_key']??$_POST['profile_key']??'');
if($profileKey===''){
$u=trim($_GET['url']??'');
$u=s4NormalizeInputUrl($u);
if($u!==''&&filter_var($u,FILTER_VALIDATE_URL))$profileKey=profileKey($u);
}
/* v9.01/v10.190: همان اندپوینت می‌تواند فقط فهرست یا فقط جزئیات را اجرا کند.
   ?phase=list | detail | all — پیش‌فرض list است تا استخراج بک‌اند مثل تست سه‌صفحه‌ای سریع بماند؛ phase=all مسیر کامل قدیمی است. */
$phaseIn = (string)($_GET['phase'] ?? $_POST['phase'] ?? 'list');
if (!in_array($phaseIn, ['all','list','detail'], true)) $phaseIn = 'list';
/* v9.11: دامنهٔ «همهٔ محصولات» از دکمهٔ اجرای فوریِ استخراج دوره‌ای */
$forceAllIn = !empty($_GET['force_all']) || !empty($_POST['force_all']);
$resumeRequested = !empty($_GET['resume']) || !empty($_POST['resume']);
$resumeQueueId = trim((string)($_GET['queue_id'] ?? $_POST['queue_id'] ?? ''));
/* Freeze the page target at click/enqueue time. A large profile save may take
   longer than an arbitrary browser delay, and a queued worker may start much
   later; neither is allowed to fall back to an older 100-page value. */
$_requestedPagesRaw=$_GET['pages']??$_POST['pages']??null;
if($_requestedPagesRaw!==null)$requestedMaxPages=max(0,(int)$_requestedPagesRaw);
else{$_pp=loadProfiles();$requestedMaxPages=max(0,(int)($_pp[$profileKey]['pages']??10));unset($_pp);}
$_detailModeRaw = $_GET['detail_mode'] ?? $_POST['detail_mode'] ?? null;
$detailModeIn = ($_detailModeRaw !== null && trim((string)$_detailModeRaw) !== '')
    ? normalizeDetailExtractMode($_detailModeRaw) : '';
if ($detailModeIn !== '' && $profileKey !== '') {
    $_ppMode = loadProfiles();
    if (isset($_ppMode[$profileKey]) && is_array($_ppMode[$profileKey])
        && normalizeDetailExtractMode($_ppMode[$profileKey]['detailExtractMode'] ?? 'two_stage') !== $detailModeIn) {
        $_oneMode = $_ppMode[$profileKey];
        unset($_ppMode);
        $_oneMode['detailExtractMode'] = $detailModeIn;
        saveOneProfileAtomic($profileKey, $_oneMode);
        unset($_oneMode);
    } else {
        unset($_ppMode);
    }
}

/* v10.458: بازیافت اسلات‌های قدیمی و قفل به ارث‌رسیدهٔ worker مرده پیش از صف‌گذاری،
   تا استخراج تفصیلی هرگز پشت پردازش مرده یا خوابیدهٔ قدیمی منتظر نماند. */
if (function_exists('s4RecycleOutdatedExtractSlotProcesses')) {
    @s4RecycleOutdatedExtractSlotProcesses();
}
if (function_exists('s4WorkerRecoverStaleLockPath')) {
    @s4WorkerRecoverStaleLockPath();
}
$_wkStNow = function_exists('s4WorkerStateLoad') ? s4WorkerStateLoad() : [];
$_wkPidNow = (int)($_wkStNow['pid'] ?? 0);
$_wkReallyAlive = s4WorkerIsActive() && ($_wkPidNow <= 0 || s4WorkerPidAlive($_wkPidNow));

/* v10.183: اگر worker دائمی سرور واقعاً زنده است، درخواست وب فقط job می‌سازد.
   resume هم در خودِ همان worker رزرو می‌شود، چون flock/handle بین دو پردازه
   قابل انتقال نیست. اگر worker heartbeat ندارد، مسیر CLI child مستقیم اجرا می‌شود. */
if (empty($_GET['direct']) && empty($_POST['direct']) && $_wkReallyAlive) {
    $enq = s4WorkerEnqueueBackendExtract($profileKey, $phaseIn, $forceAllIn, $resumeRequested, $requestedMaxPages, $resumeQueueId, $resumeRequested, $detailModeIn);
    header('Content-Type: application/json; charset=UTF-8');
    echo json_encode(array_merge(['ok'=>!empty($enq['ok']),'started'=>!empty($enq['ok']),
        'queued'=>!empty($enq['queued']),'worker'=>true,'profile_key'=>$profileKey,
        'phase'=>$phaseIn,'detail_mode'=>$detailModeIn!==''?$detailModeIn:null,'max_pages'=>$requestedMaxPages,'note'=>'operation queued for persistent worker'], $enq), JSON_UNESCAPED_UNICODE);
    exit;
}

/* v10.189: اگر worker دائمی بالا نیست، درخواست وب دیگر عملیات طولانی را داخل
   همان request اجرا نمی‌کند؛ یک CLI child جدا بالا می‌آید تا timeout وب‌سرور
   بعد از چند صفحه کل استخراج را نکشد. direct=1 همچنان مسیر قدیمی/دیباگ است. */
if (!isCliRun() && empty($_GET['direct']) && empty($_POST['direct'])) {
    if (function_exists('s4SpawnPersistentWorker')) @s4SpawnPersistentWorker();
    $spawn = s4SpawnBackendExtractChild($profileKey, $phaseIn, $forceAllIn, $resumeRequested, $requestedMaxPages, $detailModeIn, $resumeQueueId);
    if (!empty($spawn['ok'])) {
        header('Content-Type: application/json; charset=UTF-8');
        echo json_encode(['ok'=>true,'started'=>true,'worker_child'=>true,'profile_key'=>$profileKey,
            'phase'=>$phaseIn,'detail_mode'=>$detailModeIn!==''?$detailModeIn:null,'pid'=>(int)($spawn['pid']??0),'log'=>(string)($spawn['log']??''),
            'note'=>'operation detached to CLI child'], JSON_UNESCAPED_UNICODE);
        exit;
    }
}

$resumeLockQueueId = '';
/* v10.136: resumeِ فرزند باید خودش، در همان process که worker را می‌سازد،
   lock بگیرد؛ parent فقط دیگر probe و mutation جداگانه انجام نمی‌دهد. */
if ($resumeRequested) {
    $resumePrep = extractResumePrepare($profileKey, loadConnections(), $resumeQueueId, true);
    if (empty($resumePrep['ok'])) {
        if((string)($resumePrep['reason']??'')==='lock_held'){
            $queued=s4QueueRetryableExtraction($profileKey,$phaseIn,$requestedMaxPages,$detailModeIn);
            header('Content-Type: application/json; charset=UTF-8');
            echo json_encode(['ok'=>!empty($queued['ok']),'queued'=>!empty($queued['ok']),'retryable'=>true,'locked'=>true,
                'profile_key'=>$profileKey,'message'=>'استخراج در صف ادامه پس از آزادشدن قفل قرار گرفت','job'=>$queued],JSON_UNESCAPED_UNICODE);
            exit;
        }
        header('Content-Type: application/json; charset=UTF-8');
        echo json_encode(['ok' => false, 'locked' => false,
            'error' => 'checkpoint استخراج قابل رزرو نیست — اجرای موازی ساخته نشد'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $phaseIn = (string)$resumePrep['phase'];
    $resumeLockQueueId = (string)($resumePrep['queue_id'] ?? '');
}
$res=runBackendExtract($profileKey,isCliRun()?'worker_child':'manual',!isCliRun(),$phaseIn,$forceAllIn,$resumeLockQueueId,$requestedMaxPages,$detailModeIn);
if(!empty($res['retryable'])){
    $queued=s4QueueRetryableExtraction($profileKey,$phaseIn,$requestedMaxPages,$detailModeIn);
    $res['queued']=!empty($queued['ok']);$res['retry_job_id']=(string)($queued['job_id']??'');
    if(!empty($queued['ok']))$res['ok']=true;
}
// v8.30: همان اعلان‌های تغییر مبدأ که کران‌جاب می‌فرستد
if(!empty($res['ok'])){
$cnNow=loadConnections();
$profsNow=loadProfiles();
notifSourceChanges($cnNow,$res,$profsNow[$profileKey]['name']??$profileKey);
}
// اگر پاسخ زودهنگام ارسال شده، دیگر چیزی چاپ نمی‌کنیم
if(empty($res['__early_sent'])){
header('Content-Type: application/json; charset=UTF-8');
echo json_encode($res,JSON_UNESCAPED_UNICODE);
}
exit;
}

if (isset($_GET['sync_status'])) {
header('Content-Type: application/json; charset=UTF-8');
echo json_encode(['ok' => true, 'state' => loadSyncState()], JSON_UNESCAPED_UNICODE);
exit;
}
if (($_POST['action'] ?? '') === 'update_sync_state') {
header('Content-Type: application/json; charset=UTF-8');
$key = trim($_POST['profile_key'] ?? '');
$status = $_POST['status'] ?? 'done';
$state = loadSyncState();
$state[$key] = ['lastRun' => time(), 'status' => $status];
saveSyncState($state);
echo json_encode(['ok' => true], JSON_UNESCAPED_UNICODE); exit;
}

/* =====================================================================
 *  v8.39: ارسال فقط تغییرات («افزودن/آپدیت»)
 *
 *  تیک‌های «افزودن/آپدیت ووکامرس» و «افزودن/آپدیت باسلام» از نسخهٔ ۷
 *  در رابط کاربری بودند و ذخیره هم می‌شدند، ولی هیچ‌جای سمت سرور
 *  خوانده نمی‌شدند. نتیجه این بود که هر اجرای کران کل محصولات را
 *  دوباره می‌فرستاد و برای پروفایل چندهزارتایی ساعت‌ها طول می‌کشید.
 *
 *  حالا اگر تیک فعال باشد فقط محصولات جدید و تغییرکرده فرستاده
 *  می‌شوند. حذف‌شده‌ها مسیر جداگانهٔ خودشان را دارند (retireRemoved).
 * ===================================================================== */

/* =====================================================================
 *  v8.44: آماده‌سازی محصول برای ارسال، سمت سرور
 *
 *  تا اینجا فقط مرورگر قیمت نهایی را می‌ساخت (getSendP در جاوااسکریپت).
 *  کران محصول خام را در صف می‌گذاشت و ارسال‌کننده دنبال final_price
 *  می‌گشت که وجود نداشت، پس قیمت صفر می‌شد. حالا همان منطق اینجا هم
 *  پیاده شده تا اجرای خودکار و دستی یک نتیجه بدهند.
 * ===================================================================== */

/** قیمت نهایی با ضریب/درصد و گِرد کردن پروفایل — معادل getFinalPriceNum */
function profileFinalPrice(array $profile, $rawPrice): int {
    $base = extractPriceNum($rawPrice);
    if ($base <= 0) return 0;
    $mode = (string)($profile['priceMode'] ?? 'none');
    $val  = (float)($profile['priceVal'] ?? 0);
    $final = $base;
    if ($mode === 'percent')         $final = $base * (1 + ($val / 100));
    elseif ($mode === 'multiplier')  $final = $base * $val;
    $final = (int)round($final);
    $round = (int)($profile['roundPrice'] ?? 0);
    if ($round > 0) $final = (int)(round($final / $round) * $round);
    return $final;
}

/**
 * v8.87: تعدیل قیمت مخصوص یک مقصد، روی قیمت نهاییِ پروفایل.
 *
 * تا حالا فقط یک تنظیم قیمت وجود داشت که برای هر دو مقصد یکی بود. ولی
 * حاشیهٔ سود ووکامرس و باسلام یکی نیست (کارمزد باسلام، هزینهٔ ارسال و …)
 * و کاربر می‌خواهد برای هر مقصد درصد جداگانه بگذارد.
 *
 * این تابع روی «قیمت نهاییِ» محاسبه‌شده اعمال می‌شود، نه روی قیمت خام،
 * تا تنظیم پروفایل هم سر جایش بماند و این یکی فقط تفاوت مقصد را بگذارد.
 *
 * $cfg: ['mode'=>'none|percent|multiplier', 'val'=>float, 'round'=>int]
 */
function destAdjustPrice(int $base, array $cfg): int {
    if ($base <= 0) return 0;
    $mode = (string)($cfg['mode'] ?? 'none');
    $val  = (float)($cfg['val'] ?? 0);
    $out  = $base;
    if ($mode === 'percent')        $out = $base * (1 + ($val / 100));
    elseif ($mode === 'multiplier') $out = $val > 0 ? $base * $val : $base;
    $out = (int)round($out);
    $round = (int)($cfg['round'] ?? 0);
    if ($round > 0) $out = (int)(round($out / $round) * $round);
    // قیمت هیچ‌وقت نباید منفی یا صفر شود؛ درصدِ منفیِ بزرگ نباید محصول را خراب کند
    return $out > 0 ? $out : $base;
}

/** تنظیمات تعدیل قیمت یک مقصد را از فایل اتصالات می‌خواند */
function destPriceCfg(array $cn, string $dest): array {
    $d = $cn[$dest] ?? [];
    return [
        'mode'  => (string)($d['price_mode'] ?? 'none'),
        'val'   => (float)($d['price_val'] ?? 0),
        'round' => (int)($d['price_round'] ?? 0),
    ];
}

/* v10.23 (۳۶ه): شمارنده‌های تفکیکیِ هر غرفه برای صفِ ارسالِ باسلام.
   جدولِ سراسری اینجا مقداردهی می‌شود، نه داخلِ خودِ اندپوینتِ ارسال — چون
   دو تابعِ زیر از هر مسیری (از جمله selftest) صدا زده می‌شوند و اگر متغیرِ
   سراسری موجود نباشد PHP اخطارِ «undefined variable» می‌دهد. */
$GLOBALS['bslShopStats']      = $GLOBALS['bslShopStats']      ?? [];
$GLOBALS['bslDefaultVid']     = $GLOBALS['bslDefaultVid']     ?? 0;
$GLOBALS['bslDefaultShopName'] = $GLOBALS['bslDefaultShopName'] ?? '';

/** v10.23 (۳۶ه): آمارِ یک غرفهٔ اضافی را در جدولِ سراسری می‌نشاند/به‌روز می‌کند */
function bslShopStatBump(int $vid, string $name, string $field, int $n = 1): void {
    global $bslShopStats;
    if (!is_array($bslShopStats)) $bslShopStats = [];
    if ($vid <= 0) return;
    if (!isset($bslShopStats[$vid])) $bslShopStats[$vid] = ['name' => $name !== '' ? $name : ('غرفهٔ ' . $vid),
        'c' => 0, 'u' => 0, 's' => 0, 'f' => 0];
    if ($name !== '') $bslShopStats[$vid]['name'] = $name;
    if (isset($bslShopStats[$vid][$field])) $bslShopStats[$vid][$field] = max(0, (int)$bslShopStats[$vid][$field] + $n);
}

/** بارگذاری snapshot شمارنده‌های فروشگاه برای ادامهٔ همان ردیف صف. */
function bslShopStatLoadRows(array $rows): void {
    global $bslShopStats;
    $bslShopStats = [];
    foreach ($rows as $row) {
        if (!is_array($row)) continue;
        $vid = (int)($row['vid'] ?? $row['vendor_id'] ?? 0);
        if ($vid <= 0) continue;
        $bslShopStats[$vid] = [
            'name' => trim((string)($row['name'] ?? $row['shop_name'] ?? '')) ?: ('غرفهٔ ' . $vid),
            'c' => (int)($row['sent'] ?? $row['c'] ?? 0),
            'u' => (int)($row['updated'] ?? $row['u'] ?? 0),
            's' => (int)($row['skipped'] ?? $row['s'] ?? 0),
            'f' => (int)($row['failed'] ?? $row['f'] ?? 0),
        ];
    }
}

/** جایگزینیِ یک ردیفِ فروشگاه با شمارندهٔ checkpoint (نه جمع‌کردنِ دوباره). */
function bslShopStatSet(int $vid, string $name, int $sent, int $updated, int $skipped, int $failed): void {
    global $bslShopStats;
    if ($vid <= 0) return;
    if (!is_array($bslShopStats)) $bslShopStats = [];
    $bslShopStats[$vid] = [
        'name' => trim($name) !== '' ? trim($name) : ('غرفهٔ ' . $vid),
        'c' => max(0, $sent), 'u' => max(0, $updated),
        's' => max(0, $skipped), 'f' => max(0, $failed),
    ];
}

/** Record a default/scope shop outcome without mixing it into sibling shops. */
function bslShopStatBumpDefault(string $field, int $n = 1): void {
    global $bslDefaultVid, $bslDefaultShopName;
    bslShopStatBump((int)($bslDefaultVid ?? 0), (string)($bslDefaultShopName ?? ''), $field, $n);
}

/**
 * v10.23 (۳۶ه): جدولِ شمارنده‌ها به شکلِ آمادهٔ نمایش (غرفهٔ پیش‌فرض اول)
 *
 * v10.36 (۴۹ب): دو ایرادِ ریشه‌ای که باعث می‌شد کاربر بگوید «هنوز در
 * ارسال‌ها تفکیک بین چند غرفه دیده نمی‌شود»:
 *
 *  ۱) شمارنده‌های سراسری ($s,$u,$sk,$f) که به ردیفِ غرفهٔ پیش‌فرض نسبت
 *     داده می‌شدند، در مسیرِ چندغرفه‌ای «جمعِ همهٔ غرفه‌ها» بودند نه سهمِ
 *     غرفهٔ پیش‌فرض: حلقهٔ ارسالِ همزمان به‌ازای هر غرفه $updated++ می‌کرد.
 *     پس ردیفِ اول عددی بزرگ‌تر از کلِ محصولات نشان می‌داد و تفکیک
 *     بی‌معنی می‌شد.
 *  ۲) اگر فقط یک ردیف ساخته می‌شد، سمتِ جاوااسکریپت (rows.length<2) کلِ
 *     بلوک را پنهان می‌کرد — یعنی دقیقاً وقتی چیزی برای دیدن نبود.
 *
 * حالا اگر غرفهٔ پیش‌فرض هم آمارِ صریحِ خودش را ثبت کرده باشد (کلیدِ
 * bslShopStats با همان vendor_id)، همان مبنا قرار می‌گیرد و از جمعِ
 * سراسری استفاده نمی‌شود.
 */
function bslShopStatRows(int $s, int $u, int $sk, int $f): array {
    global $bslShopStats, $bslDefaultVid, $bslDefaultShopName;
    if (!is_array($bslShopStats)) $bslShopStats = [];
    $bslDefaultVid = (int)($bslDefaultVid ?? 0);
    $bslDefaultShopName = (string)($bslDefaultShopName ?? '');
    $rows = [];
    if ((int)$bslDefaultVid > 0) {
        $own = $bslShopStats[(int)$bslDefaultVid] ?? null;
        /* آمارِ اختصاصیِ غرفهٔ پیش‌فرض فقط وقتی معتبر است که واقعاً چیزی
           در آن ثبت شده باشد؛ ردیفِ صفرِ «جای‌نگه‌دار» نباید جمعِ واقعی را
           پنهان کند. */
        $hasOwn = is_array($own) && (((int)($own['c'] ?? 0)) || ((int)($own['u'] ?? 0))
                                  || ((int)($own['s'] ?? 0)) || ((int)($own['f'] ?? 0)));
        $rows[] = ['vid' => (int)$bslDefaultVid,
                   'name' => $bslDefaultShopName !== '' ? $bslDefaultShopName : 'غرفهٔ پیش‌فرض',
                   'is_default' => true,
                   'sent'    => $hasOwn ? (int)$own['c'] : (int)$s,
                   'updated' => $hasOwn ? (int)$own['u'] : (int)$u,
                   'skipped' => $hasOwn ? (int)$own['s'] : (int)$sk,
                   'failed'  => $hasOwn ? (int)$own['f'] : (int)$f];
    }
    foreach ((array)$bslShopStats as $vid => $row) {
        if ((int)$vid === (int)$bslDefaultVid) continue;
        $rows[] = ['vid' => (int)$vid,
                   'name' => (string)($row['name'] ?? ('غرفهٔ ' . $vid)),
                   'is_default' => false,
                   'sent' => (int)($row['c'] ?? 0), 'updated' => (int)($row['u'] ?? 0),
                   'skipped' => (int)($row['s'] ?? 0), 'failed' => (int)($row['f'] ?? 0)];
    }
    return $rows;
}

/* v9.47 / v10.440: فهرست غرفه‌های باسلام (پیش‌فرض + اضافی) همراه با لایهٔ تعدیل کلی باسلام و لایهٔ اختصاصی هر غرفه.
   هر غرفه: ['vendor_id'=>int,'token'=>string,'shop_name'=>string]. */
function bslAllShops(array $cn): array {
    $out = [];
    $b = $cn['basalam'] ?? [];
    $defTok = trim((string)($b['token'] ?? ''));
    $defVid = (int)($b['vendor_id'] ?? 0);
    $defName = trim((string)($b['shop_name'] ?? ''));
    if ($defName === '') $defName = 'غرفهٔ پیش‌فرض';
    $defPM = (string)($b['price_mode'] ?? 'none');
    $defPV = (float)($b['price_val'] ?? 0);
    $defPR = max(0, (int)($b['price_round'] ?? 0));
    if ($defTok !== '' && $defVid > 0) {
        $out[] = ['vendor_id' => $defVid, 'token' => $defTok, 'shop_name' => $defName,
                  'is_default' => true,
                  'price_mode' => $defPM, 'price_val' => $defPV, 'price_round' => $defPR,
                  'global_price_mode' => $defPM, 'global_price_val' => $defPV,
                  'shop_price_mode' => 'none', 'shop_price_val' => 0.0];
    }
    $vs = $b['vendors'] ?? [];
    if (is_array($vs)) {
        foreach ($vs as $v) {
            if (!is_array($v)) continue;
            $vid = (int)($v['vendor_id'] ?? 0);
            $tok = trim((string)($v['token'] ?? ''));
            if ($vid <= 0 || $tok === '') continue;
            $name = trim((string)($v['shop_name'] ?? ($v['name'] ?? '')));
            if ($name === '') $name = 'غرفهٔ ' . $vid;
            $vMode = (string)($v['price_mode'] ?? 'none');
            $vVal  = (float)($v['price_val'] ?? 0);
            $out[] = ['vendor_id' => $vid, 'token' => $tok, 'shop_name' => $name,
                      'is_default' => false,
                      'price_mode' => $vMode, 'price_val' => $vVal, 'price_round' => $defPR,
                      'global_price_mode' => $defPM, 'global_price_val' => $defPV,
                      'shop_price_mode' => $vMode, 'shop_price_val' => $vVal];
        }
    }
    return $out;
}

/** v10.73 (87): غرفه‌های فعال برایِ fan-outِ صف — فقط غرفه‌هایی که
    شناسهٔ سالم و توکنِ غیرخالی دارند (همان تعریفِ مسیرِ همزمان).
    توکن برنمی‌گردد (در صف ذخیره نمی‌شود)؛ وِرکر توکن را تازه از
    connections می‌خواند. خروجی: [vendor_id, shop_name, is_default] */
/** Whether a shop is presently enabled in the Send-tab shop picker.
 * This is intentionally read from current connections, not the queue snapshot:
 * disabling a shop must affect a row that was queued before the change. */
function bslShopSelectedForSend(array $cn,int $vendorId): bool {
    if($vendorId<=0)return false;
    $b=is_array($cn['basalam']??null)?$cn['basalam']:[];
    if(array_key_exists('enabled',$b)&&empty($b['enabled']))return false;
    $found=false;
    foreach(bslAllShops($cn) as $sh){
        if((int)($sh['vendor_id']??0)!==$vendorId)continue;
        if(trim((string)($sh['token']??''))!=='')$found=true;
        break;
    }
    if(!$found)return false;
    $selected=$b['send_shop_ids']??null;
    if(!is_array($selected))return true; // legacy/null means all configured shops
    return in_array($vendorId,array_map('intval',$selected),true);
}
/** v10.460: rows explicitly targeted at a single shop (e.g. cell_equalize on
 * Start table) should only be disabled if the user changed send_shop_ids AFTER
 * the row was created; stale saved send_shop_ids must never silently cancel a
 * brand-new explicit shop action before sending a single product. */
function bslRowDisabledByShopPicker(array $row, array $cn, int $vid): bool {
    if ($vid <= 0 || bslShopSelectedForSend($cn, $vid)) return false;
    if (!empty($row['explicit_shop_target'])) {
        $pickerChangedAt = (int)($cn['basalam']['send_shop_ids_at'] ?? 0);
        $rowCreatedAt = (int)($row['created_at'] ?? $row['started_at'] ?? 0);
        if ($pickerChangedAt <= 0 || ($rowCreatedAt > 0 && $pickerChangedAt < $rowCreatedAt)) {
            return false;
        }
    }
    return true;
}
function bslNormalizeShopSendMode($raw): string {
    return ((string)$raw === 'parallel') ? 'parallel' : 'serial';
}
function bslEffectiveShopSendMode(?array $cn = null, ?array $overrideCfg = null): string {
    if (is_array($overrideCfg) && isset($overrideCfg['shop_send_mode'])) {
        return bslNormalizeShopSendMode($overrideCfg['shop_send_mode']);
    }
    if ($cn === null) $cn = loadConnections();
    return bslNormalizeShopSendMode($cn['basalam']['shop_send_mode'] ?? 'serial');
}
/** Mark queued rows for newly disabled shops complete-without-sending. Running
 * workers also recheck the same predicate before every product. */
function bslQueueApplyCurrentShopSelection(array &$queue,array $cn): array {
    $disabled=[];$defaultVid=(int)($cn['basalam']['vendor_id']??0);
    if(!isset($queue['entries'])||!is_array($queue['entries']))$queue['entries']=[];
    foreach($queue['entries'] as &$e){
        if(!is_array($e)||!in_array((string)($e['status']??''),['running','waiting','paused'],true))continue;
        $parVids=array_values(array_filter(array_map('intval',(array)($e['config']['parallel_shop_vids']??$e['parallel_shop_vids']??[])),static fn($v)=>$v>0));
        if(!empty($parVids)){
            $keptVids=[];
            foreach($parVids as $_pvid){if(!bslRowDisabledByShopPicker($e,$cn,$_pvid))$keptVids[]=$_pvid;}
            if(!empty($keptVids)){
                if(count($keptVids)!==count($parVids)){
                    $e['parallel_shop_vids']=$keptVids;
                    if(is_array($e['config']??null))$e['config']['parallel_shop_vids']=$keptVids;
                }
                continue;
            }
            $e['status']='done';$e['done_at']=time();$e['shop_disabled']=true;$e['disabled_at']=time();
            $e['status_reason']='همهٔ غرفه‌های این ارسال موازی در تب ارسال غیرفعال شدند';
            $disabled[]=['queue_id'=>(string)($e['id']??''),'vendor_id'=>(int)$parVids[0],'shop_name'=>(string)($e['shop_name']??'')];
            continue;
        }
        $vid=(int)($e['shop_vendor_id']??$e['config']['shop_vendor_id']??0);
        if($vid<=0&&empty($e['config']['fanout']))$vid=$defaultVid;
        if($vid<=0||!bslRowDisabledByShopPicker($e,$cn,$vid))continue;
        $e['status']='done';$e['done_at']=time();$e['shop_disabled']=true;$e['disabled_at']=time();
        $e['status_reason']='غرفه در تب ارسال غیرفعال شد؛ ادامهٔ این ردیف متوقف شد';
        $disabled[]=['queue_id'=>(string)($e['id']??''),'vendor_id'=>$vid,'shop_name'=>(string)($e['shop_name']??'')];
    }unset($e);
    return $disabled;
}
/** Remove only our internal shop-disable stop; never consume a user's Stop. */
function bslClearShopDisabledStop(string $queueId): void {
    $sig=json_decode((string)@file_get_contents(BSL_STOP_FILE),true);
    if(!is_array($sig)||(string)($sig['reason']??'')!=='shop_disabled')return;
    $target=trim((string)($sig['queue_id']??''));
    if($target===''||$queueId===''||hash_equals($target,$queueId))@unlink(BSL_STOP_FILE);
}
/** Apply the selection immediately after Save when no backend owns the queue.
 * A worker loaded before this deployment cannot execute the new per-product
 * predicate, so when its active shop is now disabled we also send a targeted
 * stop that every historical worker version already understands. */
function bslReconcileDisabledShopsNow(array $cn): array {
    $fp=queueBackendLock('bsl');
    if(!$fp){
        $q=bslReadQueue();$signalled=[];
        foreach((array)($q['entries']??[]) as $e){
            if(!is_array($e)||(string)($e['status']??'')!=='running')continue;
            $parVids=array_values(array_filter(array_map('intval',(array)($e['config']['parallel_shop_vids']??$e['parallel_shop_vids']??[])),static fn($v)=>$v>0));
            if(!empty($parVids)){
                $anyLive=false;
                foreach($parVids as $_pv){if(bslShopSelectedForSend($cn,$_pv)){$anyLive=true;break;}}
                if($anyLive)continue;
                $qid=(string)($e['id']??'');
                @file_put_contents(BSL_STOP_FILE,json_encode(['stop'=>true,'at'=>time(),'queue_id'=>$qid,
                    'reason'=>'shop_disabled','vendor_id'=>(int)$parVids[0]],JSON_UNESCAPED_UNICODE),LOCK_EX);
                $signalled[]=['queue_id'=>$qid,'vendor_id'=>(int)$parVids[0]];break;
            }
            $vid=(int)($e['shop_vendor_id']??$e['config']['shop_vendor_id']??$cn['basalam']['vendor_id']??0);
            if($vid<=0||bslShopSelectedForSend($cn,$vid))continue;
            $qid=(string)($e['id']??'');
            @file_put_contents(BSL_STOP_FILE,json_encode(['stop'=>true,'at'=>time(),'queue_id'=>$qid,
                'reason'=>'shop_disabled','vendor_id'=>$vid],JSON_UNESCAPED_UNICODE),LOCK_EX);
            $signalled[]=['queue_id'=>$qid,'vendor_id'=>$vid];break;
        }
        return ['ok'=>true,'deferred'=>true,'reason'=>'active_worker_targeted_stop','signalled'=>$signalled];
    }
    try{
        $q=bslReadQueue();$disabled=bslQueueApplyCurrentShopSelection($q,$cn);
        if($disabled){bslWriteQueue($q);foreach($disabled as $d)bslClearShopDisabledStop((string)($d['queue_id']??''));}
        return ['ok'=>true,'deferred'=>false,'disabled'=>$disabled,'count'=>count($disabled)];
    }finally{queueBackendUnlock($fp);}
}
/** Stop the currently executing row as soon as its shop is disabled. */
function bslFinishDisabledShopRow(string $queueId,int $vendorId,string $shopName,int $current,int $total,int $sent,int $updated,int $skipped,int $failed): void {
    $q=bslReadQueue();
    foreach($q['entries'] as &$e){
        if(!is_array($e)||(string)($e['id']??'')!==$queueId)continue;
        $e['status']='done';$e['done_at']=time();$e['shop_disabled']=true;$e['disabled_at']=time();
        $e['status_reason']='غرفه در تب ارسال غیرفعال شد؛ ارسال فوراً متوقف شد';
        $e['current']=max((int)($e['current']??0),$current);
        $e['sent']=$sent;$e['updated']=$updated;$e['skipped']=$skipped;$e['failed']=$failed;break;
    }unset($e);bslWriteQueue($q);
    $p=readProgress(BSL_PROGRESS_FILE);if(!is_array($p))$p=[];
    $logs=is_array($p['recent_log']??null)?$p['recent_log']:[];
    $logs[]='⏹ غرفهٔ '.$shopName.' (#'.$vendorId.') غیرفعال شد — ارسال این ردیف متوقف شد';
    $p=array_merge($p,['running'=>false,'done'=>true,'shop_disabled'=>true,'phase'=>'shop_disabled',
        'phase_label'=>'غرفه غیرفعال است','queue_id'=>$queueId,'current'=>$current,'total'=>$total,
        'sent'=>$sent,'updated'=>$updated,'skipped'=>$skipped,'failed'=>$failed,
        'last_progress_ts'=>time(),'finished_at'=>time(),'recent_log'=>array_slice($logs,-200)]);
    writeProgress(BSL_PROGRESS_FILE,$p);bslClearShopDisabledStop($queueId);@unlink(BSL_PRODUCTS_FILE);
    header('Content-Type: application/json; charset=UTF-8');
    echo json_encode(['ok'=>true,'stopped'=>true,'shop_disabled'=>true,'queue_id'=>$queueId,
        'vendor_id'=>$vendorId,'current'=>$current,'total'=>$total],JSON_UNESCAPED_UNICODE);exit;
}

function bslFanoutShops(?array $cn): array {
    $cn = $cn ?: loadConnections();
    $out = [];
    $bslCfg=is_array($cn['basalam']??null)?$cn['basalam']:[];
    $hasSelection=is_array($bslCfg['send_shop_ids']??null);
    $selected=array_fill_keys(array_map('intval',(array)($bslCfg['send_shop_ids']??[])),true);
    foreach (bslAllShops($cn) as $sh) {
        $vid = (int)($sh['vendor_id'] ?? 0);
        if($hasSelection&&!isset($selected[$vid]))continue;
        $tok = trim((string)($sh['token'] ?? ''));
        if ($vid <= 0 || $tok === '') continue;
        $name = trim((string)($sh['shop_name'] ?? ''));
        $out[] = ['vendor_id' => $vid, 'shop_name' => $name, 'is_default' => !empty($sh['is_default'])];
    }
    return $out;
}

/* v9.68: تعدیل قیمتِ مخصوصِ هر غرفهٔ باسلام، «نسبت به غرفهٔ پیش‌فرض».
   غرفهٔ پیش‌فرض خودش می‌تواند درصد/مقدار داشته باشد (price_mode/price_val
   عمومی). برای غرفه‌های دیگر هم یک درصد/مقدارِ جدا ذخیره می‌شود که روی
   «قیمتِ پایهٔ محصول» اعمال می‌شود — مثل غرفهٔ پیش‌فرض ولی با مقادیرِ خودش.

   خروجی: ['price'=>قیمت نهاییِ این غرفه (تومان)، 'eff_pct'=>درصدِ مؤثرِ کلی نسبت به
   قیمتِ پایهٔ خام، 'profile_pct'=>درصدِ تعدیلِ خودِ پروفایل، 'shop_pct'=>درصدِ این غرفه]

   مثال: قیمت پایهٔ خام ۱۰۰؛ پروفایل +۳۰٪ (۱۳۰)؛ غرفهٔ دوم +۲۰٪ روی ۱۳۰ → ۱۵۶.
   eff_pct = (۱۵۶-۱۰۰)/۱۰۰ = +۵۶٪ یعنی نسبت به قیمت پایهٔ خام مجموعاً +۵۶٪. */
/** v10.440: استخراج لایهٔ تعدیل کلی باسلام و لایهٔ اختصاصی غرفه برای هر غرفه (پیش‌فرض یا اضافی). */
function bslResolveShopLayers(array $shop, int $round = 0): array {
    $isDef = !empty($shop['is_default']);
    if (array_key_exists('global_price_mode', $shop)) {
        $gMode = (string)($shop['global_price_mode'] ?? 'none');
        $gVal  = (float)($shop['global_price_val'] ?? 0);
        $sMode = $isDef ? 'none' : (string)($shop['shop_price_mode'] ?? ($shop['price_mode'] ?? 'none'));
        $sVal  = $isDef ? 0.0    : (float)($shop['shop_price_val'] ?? ($shop['price_val'] ?? 0));
        $effRound = $round > 0 ? $round : max(0, (int)($shop['price_round'] ?? 0));
    } elseif ($isDef) {
        $gMode = (string)($shop['price_mode'] ?? 'none');
        $gVal  = (float)($shop['price_val'] ?? 0);
        $sMode = 'none';
        $sVal  = 0.0;
        $effRound = $round > 0 ? $round : max(0, (int)($shop['price_round'] ?? 0));
    } else {
        $gCfg  = function_exists('destPriceCfg') ? destPriceCfg(loadConnections(), 'basalam') : ['mode' => 'none', 'val' => 0, 'round' => 0];
        $gMode = (string)($gCfg['mode'] ?? 'none');
        $gVal  = (float)($gCfg['val'] ?? 0);
        $sMode = (string)($shop['price_mode'] ?? 'none');
        $sVal  = (float)($shop['price_val'] ?? 0);
        $effRound = $round > 0 ? $round : max(0, (int)($shop['price_round'] ?? ($gCfg['round'] ?? 0)));
    }
    return ['g_mode' => $gMode, 'g_val' => $gVal, 's_mode' => $sMode, 's_val' => $sVal, 'round' => $effRound, 'is_default' => $isDef];
}

function bslShopPriceFor(int $basePrice, array $shop, int $round = 0): array {
    if ($basePrice <= 0) return ['price' => 0, 'pct' => 0, 'eff_pct' => 0, 'profile_pct' => 0, 'global_pct' => 0, 'vendor_pct' => 0, 'shop_pct' => 0];
    $ly = bslResolveShopLayers($shop, $round);
    $gMode = $ly['g_mode']; $gVal = $ly['g_val'];
    $sMode = $ly['s_mode']; $sVal = $ly['s_val'];
    $effRound = $ly['round'];
    $gpct = ($gMode === 'percent') ? $gVal : (($gMode === 'multiplier' && $gVal > 0) ? ($gVal - 1) * 100 : 0.0);
    $vpct = ($sMode === 'percent') ? $sVal : (($sMode === 'multiplier' && $sVal > 0) ? ($sVal - 1) * 100 : 0.0);
    $pct  = $gpct + $vpct;
    if ($sMode === 'none') {
        $out = destAdjustPrice($basePrice, ['mode' => $gMode, 'val' => $gVal, 'round' => $effRound]);
    } elseif ($gMode === 'none') {
        $out = destAdjustPrice($basePrice, ['mode' => $sMode, 'val' => $sVal, 'round' => $effRound]);
    } else {
        $out = (int)round($basePrice * (1 + ($pct / 100)));
        if ($effRound > 0) $out = (int)(round($out / $effRound) * $effRound);
        if ($out <= 0) $out = $basePrice;
    }
    return ['price' => $out, 'pct' => round($pct, 1), 'eff_pct' => round($pct, 1),
            'profile_pct' => 0, 'global_pct' => round($gpct, 1), 'vendor_pct' => round($vpct, 1), 'shop_pct' => round($pct, 1)];
}

/* v9.71 / v10.440: قیمتِ سه‌لایهٔ غرفه‌های باسلام:
   لایهٔ ۱: پروفایل (priceMode / priceVal / roundPrice) → قیمت پروفایل
   لایهٔ ۲: ضریب تعدیل کلی باسلام (cn.basalam.price_mode / price_val / price_round) → روی همهٔ غرفه‌ها
   لایهٔ ۳: ضریب تعدیل اختصاصی همان غرفهٔ غیرپیش‌فرض (vendors[].price_mode / price_val) */
function bslShopPriceForProfile(array $profile, $rawPrice, array $shop, int $round = 0): array {
    $src = extractPriceNum($rawPrice);
    if ($src <= 0) return ['price' => 0, 'eff_pct' => 0, 'profile_pct' => 0, 'global_pct' => 0, 'vendor_pct' => 0, 'shop_pct' => 0];
    // درصدِ تعدیلِ خودِ پروفایل
    $pm = (string)($profile['priceMode'] ?? 'none');
    $pv = (float)($profile['priceVal'] ?? 0);
    if ($pm === 'percent')         $ppct = (float)$pv;
    elseif ($pm === 'multiplier')  $ppct = $pv > 0 ? ($pv - 1) * 100 : 0;
    else                           $ppct = 0;
    $profPrice = profileFinalPrice($profile, $rawPrice);
    if ($profPrice <= 0) $profPrice = $src;
    $shopRes = bslShopPriceFor($profPrice, $shop, $round);
    $spct = (float)($shopRes['shop_pct'] ?? 0);
    $eff = $ppct + $spct;                    // جمعِ ساده: ۳۰ + ۵ = ۳۵
    $out = (int)($shopRes['price'] ?? $profPrice);
    if ($out <= 0) $out = $src;
    $actualEff = $src > 0 ? round((($out - $src) / $src) * 100, 1) : round($eff, 1);
    return ['price' => $out, 'eff_pct' => $actualEff,
            'profile_pct' => round($ppct, 1),
            'global_pct' => (float)($shopRes['global_pct'] ?? 0),
            'vendor_pct' => (float)($shopRes['vendor_pct'] ?? 0),
            'shop_pct' => round($spct, 1)];
}
/* v9.69: ارسالِ چند-غرفه‌ای — یک محصول را در «یک غرفهٔ مشخص» بساز یا به‌روز کن.
   برای هر غرفهٔ اضافی که قیمتِ خودش را دارد، همان منطقِ ارسالِ اصلی را اجرا
   می‌کنیم: جست‌وجو (bslFindExisting) → اگر بود PATCH (با قیمتِ خودِ آن غرفه)؛
   اگر نبود POST. این تابع خودش کامل است (بدون وابستگی به حلقهٔ اصلی) تا هر
   غرفه با token و قیمتِ خودش پردازش شود. */
/* v10.20 (۳۳الف): کلیدِ دفترچهٔ نگاشت، جدا برای هر غرفه.
   باگِ قدیمی: دفترچه (remote map) برای هر محصول فقط یک شناسه نگه می‌داشت و
   آن شناسه مالِ غرفهٔ پیش‌فرض بود. موقعِ ارسال به غرفهٔ دوم همان شناسه خوانده
   می‌شد و PATCH با توکنِ غرفهٔ دوم روی محصولِ غرفهٔ اول می‌رفت — که یا ۴۰۳
   می‌گرفت یا بی‌صدا شکست می‌خورد. حالا هر غرفهٔ غیرپیش‌فرض فضای نامِ خودش را
   دارد (کلید#vشناسهٔ‌غرفه) و شناسه‌ها با هم قاطی نمی‌شوند. */
function bslShopMapKey(string $productKey, array $shop): string {
    if ($productKey === '') return '';
    if (!empty($shop['is_default'])) return $productKey;
    $vid = (int)($shop['vendor_id'] ?? 0);
    return $vid > 0 ? $productKey . '#v' . $vid : $productKey;
}

/** v10.20 (۳۳الف): شناسهٔ محصول در یک غرفهٔ مشخص را در دفترچه ثبت می‌کند */
function bslShopMapRecord(array $p, array $shop, int $remoteId, string $title,
                          int $priceRial = 0, int $stock = -1): void {
    if ($remoteId <= 0) return;
    $mk = bslShopMapKey((string)($p['key'] ?? ''), $shop);
    if ($mk === '') return;
    $row = ['key' => $mk, 'remote_id' => $remoteId, 'title' => $title];
    /* v10.33 (۴۶): قیمت و موجودیِ واقعاً ارسال‌شده هم ثبت می‌شود تا دفعهٔ
       بعد بشود فهمید چیزی عوض شده یا نه. تا اینجا دفترچه فقط شناسه را
       نگه می‌داشت، برای همین هر اجرا مجبور بود کورکورانه PATCH بزند. */
    if ($priceRial > 0) $row['price_rial'] = $priceRial;
    if ($stock >= 0)    $row['stock'] = $stock;
    if (function_exists('bslResolveProductWeights')) {
        $_wRec = bslResolveProductWeights($p, 500, 0);
        if (!empty($_wRec['overridden']) && (int)$_wRec['weight'] > 0) {
            $row['weight_g'] = (int)$_wRec['weight'];
        }
    }
    remoteMapRecord('bsl', [$row]);
    /* v10.35 (۴۷ب): کشِ کاتالوگ هم همان لحظه به‌روز شود. بدونِ این، محصولی
       که همین حالا ساختیم تا پایانِ TTL در کش «نیست» می‌ماند و اگر در
       همان اجرا دوباره سراغش برویم، مسیرِ «ایجاد» می‌رفت و باسلام خطای
       نام تکراری می‌داد. */
    bslCatalogNote((int)($shop['vendor_id'] ?? 0), $title, $remoteId);
}

/* =====================================================================
 *  v10.33 (۴۶): پرشِ آپدیتِ بی‌مورد
 *
 *  مشکل: مسیرِ ارسال، محصولِ موجود را همیشه PATCH می‌کرد — حتی وقتی
 *  قیمت و موجودی مو نمی‌زد. روی پروفایلِ ۳۰۰۰ محصولی که ۴۰ قیمتش عوض
 *  شده، یعنی ۳۰۰۰ درخواستِ نوشتن برای انجامِ ۴۰ کار. روی هاستِ اشتراکی
 *  همین یکی از دلایلِ اصلیِ تایم‌اوت بود.
 *
 *  حالا آخرین چیزی که خودمان فرستادیم در دفترچه می‌ماند و اگر این بار
 *  دقیقاً همان باشد، PATCH اصلاً زده نمی‌شود.
 *
 *  چرا «بازبینیِ دوره‌ای» هم داریم: دفترچه آینهٔ کارِ خودِ ماست، نه خودِ
 *  باسلام. اگر کسی از پنلِ باسلام قیمتی را دستی عوض کند، دفترچه بی‌خبر
 *  می‌ماند و آن اختلاف برای همیشه ماندگار می‌شود. کاربر گفته دستکاریِ
 *  دستی «بسیار به‌ندرت» دارد، پس این ریسک کوچک است — ولی صفر نیست و
 *  خطایش هم بی‌صداست. برای همین هر محصول هرچند وقت یک‌بار به‌زور آپدیت
 *  می‌شود تا هر انحرافی خودبه‌خود جوش بخورد. با پیش‌فرضِ ۷ روز، هزینه‌اش
 *  در بدترین حالت یک‌هفتم حالتِ قبلی است.
 * ===================================================================== */
const BSL_REVERIFY_SEC = 604800;   // ۷ روز

/**
 * آیا می‌شود از آپدیتِ این محصول در این غرفه صرف‌نظر کرد؟
 * فقط وقتی «آری» که شناسه، قیمت و موجودیِ ثبت‌شده همگی با حالا یکی باشند
 * و از آخرین تأیید هم خیلی نگذشته باشد.
 */
function bslSkipUnchanged(string $mapKey, int $exId, int $priceRial, int $stock,
                          ?array $ledgerRow = null, int $wantWeightG = 0): bool {
    if ($mapKey === '' || $exId <= 0) return false;
    if (defined('BSL_FORCE_SYNC') && BSL_FORCE_SYNC) return false;
    if ($ledgerRow === null) $ledgerRow = (remoteMapLoad()['bsl'][$mapKey] ?? null);
    if (!is_array($ledgerRow)) return false;
    if ((int)($ledgerRow['id'] ?? 0) !== $exId) return false;
    /* نبودِ قیمت در دفترچه یعنی ردیفِ قدیمیِ پیش از v10.33 — دربارهٔ آن
       چیزی نمی‌دانیم، پس محافظه‌کارانه آپدیت می‌کنیم تا ردیف تازه شود. */
    if (!isset($ledgerRow['price_rial'])) return false;
    /* v10.463: محصولات ارسال‌شدهٔ پیش از v10.463 ممکن است در باسلام توضیحات HTML خام/اسکیپ‌شده
       داشته باشند؛ یک‌بار پرش را لغو کن تا با متن ساده و خوانای جدید آپدیت شوند. */
    if (empty($ledgerRow['plain_desc_v1'])) return false;
    /* v10.464: اگر محصول وزن استخراج‌شده در صفحهٔ جزئیات دارد و با وزن ثبت‌شده در دفترچه فرق دارد، آپدیت شود */
    if ($wantWeightG > 0 && (int)($ledgerRow['weight_g'] ?? 0) !== $wantWeightG) return false;
    if ((int)$ledgerRow['price_rial'] !== $priceRial) return false;
    if (isset($ledgerRow['stock']) && (int)$ledgerRow['stock'] !== $stock) return false;
    $at = (int)($ledgerRow['at'] ?? 0);
    if ($at <= 0 || (time() - $at) > (int)BSL_REVERIFY_SEC) return false;   // بازبینیِ دوره‌ای
    return true;
}

/** شمارندهٔ پرش‌ها، فقط برای اینکه در گزارش دیده شود چقدر صرفه‌جویی شد. */
function bslSkipCount(int $add = 0): int {
    static $n = 0;
    if ($add > 0) $n += $add;
    return $n;
}

/* v10.20 (۳۳الف): شناسهٔ محصولِ موجود را در چند غرفه «همزمان» پیدا می‌کند.
   اول دفترچهٔ نگاشتِ همان غرفه (بدون هیچ درخواستی)، بعد برای بقیهٔ غرفه‌ها
   یک درخواستِ جست‌وجوی عنوان که همه با هم اجرا می‌شوند.
   خروجی: [vendor_id => product_id] فقط برای غرفه‌هایی که محصول در آن‌ها هست. */
function bslShopsFindExistingMulti(string $title, string $productKey, array $shops, int $conc = 4): array {
    $ids = []; $need = [];
    $map = remoteMapLoad()['bsl'] ?? [];
    foreach ($shops as $sh) {
        $vid = (int)($sh['vendor_id'] ?? 0);
        if ($vid <= 0 || trim((string)($sh['token'] ?? '')) === '') continue;
        $mk = bslShopMapKey($productKey, $sh);
        $known = $mk !== '' ? (int)($map[$mk]['id'] ?? 0) : 0;
        if ($known > 0) {
            /* A stale local ledger was previously treated as proof that the
               destination product still exists. A fresh complete snapshot can
               disprove that and safely route the item through create/search. */
            $present = bslShopKnownIdPresence((string)$sh['token'], $vid, $known);
            if ($present === true || $present === null) { $ids[$vid] = $known; continue; }
            $hit = bslCatalogLookup((string)$sh['token'], $vid, $title, false);
            if ($hit > 0) { $ids[$vid] = $hit; bslCatalogSaved(1); continue; }
            if ($hit === 0) { bslCatalogSaved(1); continue; }
            $need[$vid] = $sh;
            continue;
        }
        /* v10.35 (۴۷ب): پیش از فرستادنِ درخواست، از کشِ کاتالوگِ همان غرفه
           بپرس. کشِ کاملِ تازه هم «هست» را جواب می‌دهد و هم «نیست» — و
           «نیست» یعنی این غرفه اصلاً لازم نیست در موجِ درخواست‌ها باشد. */
        $hit = bslCatalogLookup((string)$sh['token'], $vid, $title);
        if ($hit > 0)  { $ids[$vid] = $hit; bslCatalogSaved(1); continue; }
        if ($hit === 0) { bslCatalogSaved(1); continue; }
        $need[$vid] = $sh;
    }
    if ($need) {
        $q = bslNormalizeTitle($title);
        if ($q === '') $q = trim($title);
        $jobs = [];
        foreach ($need as $vid => $sh) {
            $jobs[$vid] = ['tk' => (string)$sh['token'], 'm' => 'GET',
                'ep' => 'vendors/' . $vid . '/products?per_page=50' . bslStatusQuery()
                        . '&title=' . urlencode($q)];
        }
        foreach (bslReqMulti($jobs, $conc) as $vid => $r) {
            if (empty($r['ok'])) continue;
            $rows = $r['body']['data'] ?? [];
            if (!is_array($rows) || !$rows) continue;
            $how = '';
            $hit = findRemoteByTitle($rows, $title, '', 'title', $how);
            if (is_array($hit) && (int)($hit['id'] ?? 0) > 0) $ids[(int)$vid] = (int)$hit['id'];
        }
    }
    return $ids;
}

/* =====================================================================
 *  v10.20 (۳۳الف): ارسالِ «همزمان» یک محصول به چند غرفه
 *
 *  تیکِ «ارسال به همهٔ غرفه‌ها» از v9.69 بود ولی غرفه‌ها یکی‌یکی و کاملاً
 *  ترتیبی پردازش می‌شدند: غرفهٔ دوم تا وقتی کلِ غرفهٔ اول تمام نمی‌شد شروع
 *  نمی‌کرد. با ۵۰ محصول و ۳ غرفه یعنی سه برابرِ زمان، و روی هاستِ اشتراکی
 *  معمولاً وسطِ راه تایم‌اوت. برای کاربر شبیهِ «کار نمی‌کند» بود.
 *
 *  حالا هر محصول یک بار پردازش می‌شود و همهٔ غرفه‌ها با هم می‌روند:
 *    فاز ۱ — جست‌وجوی همزمانِ شناسه در همهٔ غرفه‌ها
 *    فاز ۲ — PATCHِ همزمان برای غرفه‌هایی که محصول را دارند
 *    فاز ۳ — POSTِ همزمان برای غرفه‌هایی که ندارند
 *    فاز ۴ — هر غرفه‌ای که در فاز ۲/۳ شکست خورد، از مسیرِ تکیِ آزمودهٔ
 *            bslUpsertToShop رد می‌شود (جست‌وجوی عمیق، «نام تکراری»،
 *            دسته‌های جایگزین). یعنی سرعت اضافه شده، ولی هیچ توانایی‌ای
 *            از دست نرفته.
 *
 *  خروجی: [vendor_id => ['ok'=>bool,'id'=>int,'action'=>'created|updated','error'=>string]]
 * ===================================================================== */
/**
 * v10.461: آماده‌سازی یک‌بارهٔ فایل‌های محلی تصویر محصول از مبدأ و آپلود موازی (curl_multi)
 * به همهٔ غرفه‌های باسلام بدون دانلود تکراری از سایت مبدأ.
 */
function s4PrepareLocalPhotosForMultiShop(array $p, int $maxPhotos = 1): array {
    $imgUrls = function_exists('productImageList') ? productImageList($p) : [];
    $detailLink = trim((string)($p['link'] ?? $p['url'] ?? ''));
    if (!$imgUrls && $detailLink !== '') {
        $detailRes = fetch_html($detailLink, 20);
        if (!empty($detailRes['ok']) && !empty($detailRes['html'])) {
            $rescued = extractImageFromHtml((string)$detailRes['html'], $detailLink);
            if ($rescued !== '' && !bslIsPlaceholderImageUrl($rescued)) $imgUrls = [$rescued];
        }
    }
    if (!$imgUrls) return [];
    $deduped = array_values(galleryDedupe($imgUrls, max(1, min(3, $maxPhotos))));
    $prevRole = $GLOBALS['_s4CurrentImageRole'] ?? null;
    $out = [];
    foreach ($deduped as $idx => $imgUrl) {
        $imgUrl = trim((string)$imgUrl);
        if ($imgUrl === '' || bslIsPlaceholderImageUrl($imgUrl)) continue;
        $role = ($idx === 0 ? 'list' : 'gallery');
        $GLOBALS['_s4CurrentImageRole'] = $role;
        $cacheKey = function_exists('s4ImageCacheKey') ? s4ImageCacheKey($imgUrl, $detailLink, $role) : md5($imgUrl . '|' . $role);
        $pickedPath = '';
        foreach ((array)glob(UPLOAD_DIR . 'img_' . $cacheKey . '.*') as $f) {
            if (is_file($f) && filesize($f) > 200) {
                $fd = @file_get_contents($f);
                if ($fd && isImageData($fd)) { $pickedPath = $f; break; }
            }
        }
        if ($pickedPath === '') {
            $saved = saveImageLocal($imgUrl, $detailLink);
            if ($saved && is_file($saved) && filesize($saved) > 200) $pickedPath = $saved;
        }
        if ($pickedPath === '') continue;
        $fdata = @file_get_contents($pickedPath);
        if (!$fdata || !isImageData($fdata)) continue;
        $realFmt = detectImageFormat($fdata) ?: 'jpg';
        $conv = convertToSupportedFormat($fdata);
        if (!empty($conv['ok']) && !empty($conv['converted_from'])) {
            $fdata = $conv['data'];
            $realFmt = 'jpg';
            @file_put_contents($pickedPath, $fdata);
        }
        $stdRes = s4StandardizeImageForBasalam($fdata);
        if (empty($stdRes['ok'])) continue;
        if (!empty($stdRes['changed']) && !empty($stdRes['data'])) {
            $fdata = (string)$stdRes['data'];
            $realFmt = 'jpg';
            $stdPath = UPLOAD_DIR . 'bsl_std_' . $cacheKey . '.jpg';
            if (@file_put_contents($stdPath, $fdata)) $pickedPath = $stdPath;
        }
        $mime = 'image/' . ($realFmt === 'jpg' ? 'jpeg' : $realFmt);
        $out[] = ['path' => $pickedPath, 'mime' => $mime, 'name' => 'product_' . substr($cacheKey, 0, 12) . '.' . $realFmt];
    }
    if ($prevRole === null) unset($GLOBALS['_s4CurrentImageRole']);
    else $GLOBALS['_s4CurrentImageRole'] = $prevRole;
    return $out;
}
function bslUploadPhotosMultiShops(array $localFiles, array $shops, int $conc = 4): array {
    $perShopIds = [];
    foreach ($shops as $vid => $_sh) $perShopIds[(int)$vid] = [];
    foreach ($localFiles as $fileMeta) {
        $path = (string)($fileMeta['path'] ?? '');
        if ($path === '' || !is_file($path)) continue;
        $mime = (string)($fileMeta['mime'] ?? 'image/jpeg');
        $fname = (string)($fileMeta['name'] ?? 'product.jpg');
        $jobs = [];
        foreach ($shops as $vid => $sh) {
            $vid = (int)$vid;
            $tk = trim((string)($sh['token'] ?? ''));
            if ($vid <= 0 || $tk === '') continue;
            $jobs[$vid] = [
                'tk' => $tk, 'm' => 'POST', 'ep' => 'files', 'mp' => true,
                'd' => ['file' => new CURLFile($path, $mime, $fname), 'file_type' => 'product.photo'],
            ];
        }
        if (!$jobs) continue;
        foreach (bslReqMulti($jobs, $conc) as $vid => $r) {
            if (!empty($r['ok']) && !empty($r['body']['id'])) {
                $perShopIds[(int)$vid][] = (int)$r['body']['id'];
            }
        }
    }
    return $perShopIds;
}

function bslUpsertManyShops(array $p, array $shops, array $opts, int $conc = 4): array {
    $out = [];
    $rawTitle = trim((string)($p['title'] ?? ($p['name'] ?? '')));
    $pKey  = (string)($p['key'] ?? '');
    if ($rawTitle === '') {
        foreach ($shops as $sh) { $v = (int)($sh['vendor_id'] ?? 0); if ($v > 0) $out[$v] = ['ok' => false, 'error' => 'عنوان خالی']; }
        return $out;
    }
    $barcodeVal = bslExtractValidBarcode($p);
    $hasBarcode = ($barcodeVal !== '');
    $title = bslSanitizeModerationTitle($rawTitle, $hasBarcode);
    if ($title === '') $title = $rawTitle;

    $round   = (int)($opts['round'] ?? 0);
    $profile = is_array($opts['profile'] ?? null) ? $opts['profile'] : null;

    // قیمتِ هر غرفه + بررسی فعال بودن غرفه (پیشگیری از ۷۰۹۴ و ۵۰۱۱/۶۳۸۱)
    $prices = []; $live = [];
    foreach ($shops as $sh) {
        $vid = (int)($sh['vendor_id'] ?? 0); $tk = trim((string)($sh['token'] ?? ''));
        if ($vid <= 0 || $tk === '') continue;
        $vStat = bslCheckVendorActiveStatus($tk, $vid);
        if (empty($vStat['active'])) {
            $out[$vid] = ['ok' => false, 'skipped_inactive_vendor' => true, 'reason_kind' => 'vendor_inactive', 'error' => (string)$vStat['reason']];
            continue;
        }
        $rawP = extractSourcePrice($p);
        if ($profile && $rawP !== '' && extractPriceNum($rawP) > 0) {
            $pf = bslShopPriceForProfile($profile, $rawP, $sh, $round);
        } else {
            $baseP = (int)preg_replace("/[^0-9]/", "", (string)($p['final_price'] ?? '0'));
            if ($baseP <= 0) { $out[$vid] = ['ok' => false, 'error' => 'قیمت ۰']; continue; }
            $pf = bslShopPriceFor($baseP, $sh, $round);
        }
        if ((int)($pf['price'] ?? 0) <= 0) { $out[$vid] = ['ok' => false, 'error' => 'قیمت نامعتبر']; continue; }
        $pr = (int)$pf['price'];
        if ((string)($p['price_unit'] ?? '') !== 'rial') $pr = $pr * 10;
        if (!bslIsRealisticPriceRial($pr)) {
            $out[$vid] = ['ok' => false, 'reason_kind' => 'unrealistic_price', 'error' => 'قیمت کمتر از حداقل معتبر باسلام (۵,۰۰۰ تومان) — پیشگیری از خطای ۵۰۱۱/۶۳۸۱ عدم تایید'];
            continue;
        }
        $prices[$vid] = $pr; $live[$vid] = $sh;
    }
    if (!$live) return $out;

    $stock  = effectiveStock($p, (int)($opts['stock'] ?? 10));    // v10.21 (۳۴الف)
    $prepD  = max(1, (int)($opts['preparation_days'] ?? 3));
    $_defWM = (int)($opts['weight'] ?? 500);
    $_defPWM = (int)($opts['package_weight'] ?? ($_defWM + 100));
    $_wResM = bslResolveProductWeights($p, $_defWM, $_defPWM);
    $weight = (int)$_wResM['weight'];
    $pkgW   = (int)$_wResM['package_weight'];
    $_wantWG = !empty($_wResM['overridden']) ? $weight : 0;
    $catId  = (int)($opts['category_id'] ?? 0);
    $autoCat= !empty($opts['auto_category']);
    $flatCats = is_array($opts['flat_cats'] ?? null) ? $opts['flat_cats'] : [];
    $cData    = is_array($opts['cdata'] ?? null) ? $opts['cdata'] : [];

    // ---- فاز ۱: شناسه‌ها، همزمان (هم با عنوان پاک‌سازی‌شده هم در صورت تغییر با عنوان خام قبلی)
    $ids = bslShopsFindExistingMulti($title, $pKey, $live, $conc);
    if ($rawTitle !== $title) {
        $missingLive = [];
        foreach ($live as $vid => $sh) if (empty($ids[$vid])) $missingLive[$vid] = $sh;
        if ($missingLive) {
            foreach (bslShopsFindExistingMulti($rawTitle, $pKey, $missingLive, $conc) as $vid => $exOldId) {
                if ((int)$exOldId > 0) $ids[$vid] = (int)$exOldId;
            }
        }
    }

    // ---- فاز ۲: آپدیتِ همزمان
    $ledger = [];
    if ($ids) {
        $jobs = [];
        /* v10.33 (۴۶): دفترچه یک بار خوانده می‌شود، نه یک بار برای هر غرفه.
           در حلقهٔ چند هزار محصولی، خواندنِ مکررِ همین فایل خودش گران است. */
        $__bslMap = remoteMapLoad()['bsl'] ?? [];
        foreach ($ids as $vid => $exId) {
            if (!isset($live[$vid])) continue;
            $__mk = bslShopMapKey($pKey, $live[$vid]);
            if (bslSkipUnchanged($__mk, (int)$exId, (int)$prices[$vid], $stock,
                                 $__bslMap[$__mk] ?? null, $_wantWG)) {
                bslSkipCount(1);
                $out[(int)$vid] = ['ok' => true, 'id' => (int)$exId,
                                   'action' => 'unchanged', 'skipped' => true];
                continue;   // نه PATCH، نه ثبتِ دوباره در دفترچه
            }
            $bu = ['primary_price' => $prices[$vid], 'stock' => $stock, 'status' => ($stock > 0 ? 2976 : 3790),
                   'preparation_days' => $prepD, 'weight' => $weight, 'package_weight' => $pkgW];
            /* v10.392: Basalam rejects category_id on existing products (HTTP 422).
               Category is creation-only unless the dedicated category-fix workflow is used. */
            bslApplyContent($bu, $p); /* v10.98: توضیح + تنوع */
            $_mvUpd = bslBuildVariantsPayload($p, (int)$prices[$vid], $stock);
            if ($_mvUpd) $bu['variants'] = $_mvUpd;
            $jobs[$vid] = ['tk' => (string)$live[$vid]['token'], 'm' => 'PATCH',
                           'ep' => 'products/' . $exId, 'd' => $bu];
        }
        $rs = bslReqMulti($jobs, $conc);
        // موجِ دوم: هرکدام ۴۰۴ گرفت، با مسیرِ غرفه‌ای دوباره امتحان می‌شود
        $again = [];
        foreach ($rs as $vid => $r) {
            if ((int)($r['code'] ?? 0) === 404) {
                $again[$vid] = ['tk' => (string)$live[$vid]['token'], 'm' => 'PATCH',
                                'ep' => 'vendors/' . $vid . '/products/' . $ids[$vid], 'd' => $jobs[$vid]['d']];
            }
        }
        if ($again) foreach (bslReqMulti($again, $conc) as $vid => $r2) $rs[$vid] = $r2;
        $againNoVar = [];
        foreach ($rs as $vid => $r) {
            if (empty($r['ok']) && in_array((int)($r['code'] ?? 0), [400, 422], true) && !empty($jobs[$vid]['d']['variants']) && !bslIsCategoryError($r)) {
                $dNoVar = $jobs[$vid]['d'];
                unset($dNoVar['variants']);
                $againNoVar[$vid] = ['tk' => (string)$live[$vid]['token'], 'm' => 'PATCH', 'ep' => 'products/' . $ids[$vid], 'd' => $dNoVar];
            }
        }
        if ($againNoVar) foreach (bslReqMulti($againNoVar, $conc) as $vid => $r3) $rs[$vid] = $r3;
        foreach ($rs as $vid => $r) {
            if (!empty($r['ok']) && !empty($r['body']['id'])) {
                $out[(int)$vid] = ['ok' => true, 'id' => (int)$ids[$vid], 'action' => 'updated', 'update_reason' => 'آپدیت همزمان قیمت/موجودی/محتوا', 'changes_detail' => 'PATCH همزمان روی محصول موجود'];
                $ledger[(int)$vid] = (int)$ids[$vid];
            }
        }
    }

    // ---- فاز ۳: ساختِ همزمان برای غرفه‌هایی که محصول را ندارند (آپلود موازی تصویر + POST موازی محصول)
    $toCreate = [];
    foreach ($live as $vid => $sh) {
        if (!empty($out[$vid]['ok'])) continue;
        if (isset($ids[$vid])) continue; // محصول موجود بود ولی آپدیت موازی نشد؛ فاز ۴ تک‌غرفه‌ای هندل می‌کند
        /* v10.466: پیشگیری قطعی از خطای ۷۰۹۳ — محصول ناموجود را هرگز به عنوان کالای جدید در باسلام نساز */
        if ($stock <= 0) {
            $out[(int)$vid] = ['ok' => true, 'id' => 0, 'skipped' => true, 'action' => 'skipped_outofstock_create',
                'note' => 'محصول ناموجود در باسلام ساخته نشد (پیشگیری از خطای ۷۰۹۳ عدم تایید)'];
            continue;
        }
        $toCreate[$vid] = $sh;
    }
    if ($toCreate) {
        $bslCfgIn = is_array($opts['basalam_cfg'] ?? null) ? $opts['basalam_cfg'] : null;
        $fallback = is_array($opts['fallback_cat_ids'] ?? null) ? $opts['fallback_cat_ids'] : [];
        $prodMappedCat = (int)($p['bsl_category_id'] ?? $p['category_id'] ?? 0);
        $rawManualChain = bslCollectManualCategories($prodMappedCat > 0 ? $prodMappedCat : 0, $profile, array_merge($catId > 0 ? [$catId] : [], $fallback), $bslCfgIn);
        $manualChain = bslFilterSafeManualCategories($title, $rawManualChain, $flatCats, $prodMappedCat);
        $catUsed = !empty($manualChain) ? (int)$manualChain[0] : 0;
        if ($catUsed <= 0 && !empty($flatCats)) {
            $_ac = autoMatchBslCategory($title, $flatCats);
            if ($_ac <= 0 && $autoCat) $_ac = autoMatchBslCategoryForce($title, $flatCats);
            if ($_ac > 0) $catUsed = $_ac;
        }
        if ($catUsed > 0 && !empty($cData)) $catUsed = findLeafCategory($catUsed, $cData);
        $_builtCreate = bslBuildUnifiedDescription($p, $title);
        $brief = $_builtCreate['brief'] !== '' ? $_builtCreate['brief'] : mb_substr(s4HtmlToPlainTextForBsl($title), 0, 250, 'UTF-8');
        $desc  = bslEnsureRichCompliantDescription($_builtCreate['description'], $title, $p, $hasBarcode);
        $localPhotos = ($catUsed > 0 && !bslStopRequestedForQueue())
            ? s4PrepareLocalPhotosForMultiShop($p, max(1, min(3, (int)($opts['upload_max_photos'] ?? 1))))
            : [];
        $shopPhotoMap = !empty($localPhotos) ? bslUploadPhotosMultiShops($localPhotos, $toCreate, $conc) : [];
        $jobs = [];
        foreach ($toCreate as $vid => $sh) {
            $pidsForShop = array_values(array_filter(array_map('intval', (array)($shopPhotoMap[$vid] ?? [])), static fn($x) => $x > 0));
            if ($catUsed <= 0 || empty($pidsForShop)) continue;
            $pkgWUse = $pkgW > 0 ? $pkgW : max(1, $weight + 100);
            $bp = ['name' => mb_substr($title, 0, 120), 'brief' => mb_substr($brief, 0, 250),
                   'description' => $desc, 'primary_price' => $prices[$vid], 'stock' => $stock,
                   'preparation_days' => $prepD, 'weight' => $weight, 'package_weight' => $pkgWUse,
                   'is_wholesale' => false, 'category_id' => $catUsed,
                   'photo' => (int)$pidsForShop[0], 'photos' => $pidsForShop, 'status' => 2976];
            if (!empty($p['sku'])) $bp['sku'] = $p['sku'];
            if ($barcodeVal !== '') $bp['barcode'] = $barcodeVal;
            $_mvNew = bslBuildVariantsPayload($p, (int)$prices[$vid], $stock);
            if ($_mvNew) $bp['variants'] = $_mvNew;
            $jobs[$vid] = ['tk' => (string)$sh['token'], 'm' => 'POST',
                           'ep' => 'vendors/' . $vid . '/products', 'd' => $bp];
        }
        $rsCreate = bslReqMulti($jobs, $conc);
        $retryNoVarCreate = [];
        foreach ($rsCreate as $vid => $r) {
            if (empty($r['ok']) && in_array((int)($r['code'] ?? 0), [400, 422], true) && !empty($jobs[$vid]['d']['variants']) && !bslIsDuplicateName($r) && !bslIsCategoryError($r)) {
                $dNoVarC = $jobs[$vid]['d'];
                unset($dNoVarC['variants']);
                $retryNoVarCreate[$vid] = ['tk' => (string)$toCreate[$vid]['token'], 'm' => 'POST', 'ep' => 'vendors/' . $vid . '/products', 'd' => $dNoVarC];
            }
        }
        if ($retryNoVarCreate) foreach (bslReqMulti($retryNoVarCreate, $conc) as $vid => $rnv) $rsCreate[$vid] = $rnv;
        foreach ($rsCreate as $vid => $r) {
            if (!empty($r['ok']) && !empty($r['body']['id'])) {
                $out[(int)$vid] = ['ok' => true, 'id' => (int)$r['body']['id'], 'action' => 'created', 'used_cat_id' => $catUsed, 'update_reason' => 'ایجاد موازی در غرفه'];
                $ledger[(int)$vid] = (int)$r['body']['id'];
            } else {
                $em = $r['body']['message'] ?? $r['body']['error'] ?? ($r['error'] ?? '؟');
                if (is_array($em)) $em = json_encode($em, JSON_UNESCAPED_UNICODE);
                $out[(int)$vid] = array_merge(['ok' => false], bslSendErrorInfo($r, 'multi_shop_create', 'vendors/' . $vid . '/products'));
                if (empty($out[(int)$vid]['error'])) $out[(int)$vid]['error'] = mb_substr((string)$em, 0, 140);
            }
        }
    }

    // ---- فاز ۴: هر شکستی از مسیرِ تکیِ کاملِ قدیمی رد می‌شود.
    //      اگر سیگنالِ توقف رسیده باشد این فاز اجرا نمی‌شود، وگرنه هر غرفه
    //      یک 'stopped' می‌گیرد و آن محصول بی‌دلیل «خطا» شمرده می‌شود.
    $__stopNow = bslStopRequestedForQueue();
    foreach ($live as $vid => $sh) {
        if (!empty($out[$vid]['ok'])) continue;
        if ($__stopNow) { $out[(int)$vid] = ['ok' => false, 'stopped' => true, 'error' => 'stopped']; continue; }
        $one = bslUpsertToShop($p, $sh, $opts);
        $out[(int)$vid] = $one;
        if (!empty($one['ok']) && (int)($one['id'] ?? 0) > 0) $ledger[(int)$vid] = (int)$one['id'];
    }

    // شناسه‌ها را برای دفعهٔ بعد ثبت کن تا جست‌وجو لازم نشود
    if ($ledger && $pKey !== '') {
        $rows = [];
        foreach ($ledger as $vid => $rid) {
            $mk = bslShopMapKey($pKey, $live[$vid]);
            /* v10.33 (۴۶): قیمت و موجودی حتماً باید همراهِ همین ردیف نوشته
               شوند. remoteMapRecord کلِ ردیف را جایگزین می‌کند، پس اگر
               اینجا بدونشان بنویسیم، چیزی که چند خط بالاتر ثبت شده پاک
               می‌شود و پرشِ دفعهٔ بعد هیچ‌وقت اتفاق نمی‌افتد. */
            if ($mk !== '') {
                $_lRowM = ['key' => $mk, 'remote_id' => $rid, 'title' => $title,
                           'price_rial' => (int)($prices[$vid] ?? 0), 'stock' => $stock];
                if ($_wantWG > 0) $_lRowM['weight_g'] = $_wantWG;
                $rows[] = $_lRowM;
            }
            bslCatalogNote((int)$vid, $title, (int)$rid);   // v10.35 (۴۷ب)
        }
        if ($rows) remoteMapRecord('bsl', $rows);
    }
    return $out;
}

function bslUpsertToShop(array $p, array $shop, array $opts): array {
    $tk   = (string)($shop['token'] ?? '');
    $vid  = (int)($shop['vendor_id'] ?? 0);
    if ($tk === '' || $vid <= 0) return ['ok' => false, 'error' => 'غرفهٔ نامعتبر'];
    $rawTitle = trim((string)($p['title'] ?? ($p['name'] ?? '')));
    if ($rawTitle === '') return ['ok' => false, 'error' => 'عنوان خالی'];
    $vStat = bslCheckVendorActiveStatus($tk, $vid);
    if (empty($vStat['active'])) {
        return ['ok' => false, 'skipped_inactive_vendor' => true, 'reason_kind' => 'vendor_inactive', 'error' => (string)$vStat['reason']];
    }
    $barcodeVal = bslExtractValidBarcode($p);
    $hasBarcode = ($barcodeVal !== '');
    $title = bslSanitizeModerationTitle($rawTitle, $hasBarcode);
    if ($title === '') $title = $rawTitle;

    $round  = (int)($opts['round'] ?? 0);
    $profile= is_array($opts['profile'] ?? null) ? $opts['profile'] : null;
    $forcedPrice = max(0, (int)($opts['forced_price_toman'] ?? 0));
    // قیمتِ این غرفه: لایهٔ پروفایل (اگر قیمتِ خام بود) + لایهٔ خودِ غرفه
    $rawP  = (string)($p['price'] ?? ($p['orig_price'] ?? ''));
    if ($forcedPrice > 0) {
        $pf = ['price'=>$forcedPrice,'forced'=>true];
    } elseif ($profile && $rawP !== '' && extractPriceNum($rawP) > 0) {
        $pf = bslShopPriceForProfile($profile, $rawP, $shop, $round);
    } else {
        $baseP = (int)preg_replace("/[^0-9]/", "", (string)($p['final_price'] ?? '0'));
        if ($baseP <= 0) return ['ok' => false, 'error' => 'قیمت ۰'];
        $pf = bslShopPriceFor($baseP, $shop, $round);
    }
    $priceToman = $pf['price'];
    if ($priceToman <= 0) return ['ok' => false, 'error' => 'قیمت نامعتبر'];
    $priceRial = (($p['price_unit'] ?? '') !== 'rial') ? $priceToman * 10 : $priceToman;
    if (!bslIsRealisticPriceRial($priceRial)) {
        return ['ok' => false, 'reason_kind' => 'unrealistic_price', 'error' => 'قیمت کمتر از حداقل معتبر باسلام (۵,۰۰۰ تومان) — پیشگیری از خطای ۵۰۱۱/۶۳۸۱ عدم تایید'];
    }

    $stock   = effectiveStock($p, (int)($opts['stock'] ?? 10));   // v10.21 (۳۴الف)
    $prepD   = max(1, (int)($opts['preparation_days'] ?? 3));
    $_defWS  = (int)($opts['weight'] ?? 500);
    $_defPWS = (int)($opts['package_weight'] ?? ($_defWS + 100));
    $_wResS  = bslResolveProductWeights($p, $_defWS, $_defPWS);
    $weight  = (int)$_wResS['weight'];
    $pkgW    = (int)$_wResS['package_weight'];
    if ($pkgW <= 0) $pkgW = max(1, $weight + 100); // باسلام وزن بسته‌بندی صفر را با 422 رد می‌کند
    $_wantShopWG = !empty($_wResS['overridden']) ? $weight : 0;
    $catId   = (int)($opts['category_id'] ?? 0);
    $fallback= is_array($opts['fallback_cat_ids'] ?? null) ? $opts['fallback_cat_ids'] : [];
    $autoCat = !empty($opts['auto_category']);
    $flatCats= is_array($opts['flat_cats'] ?? null) ? $opts['flat_cats'] : [];
    $cData   = is_array($opts['cdata'] ?? null) ? $opts['cdata'] : [];

    // v10.20 (۳۳الف): دفترچهٔ نگاشتِ همین غرفه، نه شناسهٔ غرفهٔ پیش‌فرض
    $__mk = bslShopMapKey((string)($p['key'] ?? ''), $shop);
    $doDeep = !array_key_exists('find_deep_scan', $opts) || !empty($opts['find_deep_scan']);
    $existing = !empty($opts['skip_find_existing']) ? null : bslFindExisting($tk, $vid, $title, $__mk, $doDeep);
    if (!$existing && $rawTitle !== $title && empty($opts['skip_find_existing'])) {
        $existing = bslFindExisting($tk, $vid, $rawTitle, $__mk, $doDeep);
    }
    $exId = is_array($existing) ? (int)($existing['id'] ?? 0) : 0;

    if ($exId > 0) {
        /* v10.33 (۴۶): اگر قیمت و موجودی همانی است که خودمان آخرین بار
           فرستادیم، این PATCH هیچ کاری نمی‌کند جز مصرفِ یک درخواست. */
        if (bslSkipUnchanged($__mk, $exId, $priceRial, $stock)) {
            $_oldSingleLedgerRow = $__mk !== '' ? (remoteMapLoad()['bsl'][$__mk] ?? null) : null;
            if ($_wantShopWG <= 0 || (is_array($_oldSingleLedgerRow) && (int)($_oldSingleLedgerRow['weight_g'] ?? 0) === $_wantShopWG)) {
                bslSkipCount(1);
                return ['ok' => true, 'id' => $exId, 'action' => 'unchanged', 'skipped' => true];
            }
        }
        $bu = ['primary_price' => $priceRial, 'stock' => $stock, 'status' => ($stock > 0 ? 2976 : 3790),
               'preparation_days' => $prepD, 'weight' => $weight, 'package_weight' => $pkgW];
        /* Existing-product PATCH must not include category_id; Basalam returns 422
           ("currently unable to change category") even when the ID is unchanged. */
        bslApplyContent($bu, $p); /* v10.98 / v10.458: توضیح + جدول مشخصات + تنوع */
        $_bslShopVarsUpd = bslBuildVariantsPayload($p, $priceRial, $stock);
        if ($_bslShopVarsUpd) $bu['variants'] = $_bslShopVarsUpd;
        $r = bslReqWithVariantsFallback($tk, 'PATCH', 'products/' . $exId, $bu);
        if ($r['code'] === 404) $r = bslReqWithVariantsFallback($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $exId, $bu);
        if (!empty($r['ok']) && !empty($r['body']['id'])) {
            bslShopMapRecord($p, $shop, $exId, $title, $priceRial, $stock);   // v10.20 (۳۳الف) · v10.33 (۴۶)
            return ['ok' => true, 'id' => $exId, 'action' => 'updated', 'update_reason' => 'آپدیت قیمت/موجودی/محتوا', 'changes_detail' => 'PATCH محصول موجود'];
        }
        return array_merge(['ok' => false], bslSendErrorInfo($r, 'shop_update', 'products/' . $exId),
            ['error' => 'آپدیت در این غرفه ناموفق: ' . bslErrText($r)]);
    }

    /* v10.466: پیشگیری قطعی از خطای ۷۰۹۳ — اگر محصول هنوز در باسلام نیست و موجودی ندارد، هرگز نساز */
    if ($stock <= 0) {
        return ['ok' => true, 'id' => 0, 'skipped' => true, 'action' => 'skipped_outofstock_create',
            'note' => 'محصول ناموجود در باسلام ساخته نشد (پیشگیری از خطای ۷۰۹۳ عدم تایید)'];
    }

    $aiDirect = !empty($opts['ai_cat_direct']);
    $bslCfgIn = is_array($opts['basalam_cfg'] ?? null) ? $opts['basalam_cfg'] : null;
    $prodMappedCat = (int)($p['bsl_category_id'] ?? $p['category_id'] ?? 0);
    $rawManualChain = $aiDirect
        ? ($catId > 0 ? [$catId] : [])
        : bslCollectManualCategories($prodMappedCat > 0 ? $prodMappedCat : 0, $profile, array_merge($catId > 0 ? [$catId] : [], $fallback), $bslCfgIn);
    $manualChain = $aiDirect
        ? $rawManualChain
        : bslFilterSafeManualCategories($title, $rawManualChain, $flatCats, $prodMappedCat);
    $remainingManual = [];
    if (!empty($manualChain)) {
        $catUsed = (int)$manualChain[0];
        $remainingManual = array_slice($manualChain, 1);
    } else {
        $catUsed = 0;
        if (!empty($flatCats)) {
            $_ac = autoMatchBslCategory($title, $flatCats);
            if ($_ac <= 0 && $autoCat) $_ac = autoMatchBslCategoryForce($title, $flatCats);
            if ($_ac > 0) $catUsed = (!empty($cData) && is_array($cData)) ? findLeafCategory($_ac, $cData) : $_ac;
        }
    }
    if ($catUsed <= 0) {
        $pRawKeyPre = (string)($p['_key'] ?? ($p['key'] ?? ($p['link'] ?? '')));
        if (!$aiDirect && function_exists('bslQueueForAiCategoryFix')) {
            $aiQPre = bslQueueForAiCategoryFix($p, [
                'vendor_id'          => $vid,
                'shop_name'          => (string)($shop['shop_name'] ?? ('غرفهٔ ' . $vid)),
                'profile_key'        => (string)($opts['profile_key'] ?? ''),
                'profile_name'       => (string)($profile['name'] ?? ''),
                'product_key'        => $pRawKeyPre,
                'title'              => $title,
                'tried_cat_ids'      => $rawManualChain,
                'forced_price_toman' => (int)round($priceRial / 10),
                'endpoint'           => 'vendors/' . $vid . '/products',
                'error_code'         => 422,
                'error'              => 'دستهٔ پیش‌فرض با نوع کالا هم‌خوانی نداشت؛ برای انتخاب دستهٔ دقیق با AI صف شد',
                'step'               => 'semantic_category_guard',
            ]);
            return [
                'ok'          => false,
                'error'       => 'دستهٔ پیش‌فرض با عنوان محصول تضاد داشت و از ثبت با دستهٔ اشتباه (کد ۶۰۴۶) جلوگیری شد؛ محصول در صف انتخاب دستهٔ هوشمند قرار گرفت.',
                'error_code'  => 422,
                'reason_kind' => 'category_ai_pending',
                'ai_queue_id' => (string)($aiQPre['queue_id'] ?? ''),
            ];
        }
        return ['ok'=>false,'error'=>'دسته‌بندی معتبر باسلام برای محصول تعیین نشده','error_code'=>422,
            'error_detail'=>'category_id خالی است؛ دستهٔ پروفایل، دستهٔ پیش‌فرض یا دستهٔ جایگزین تنظیم کنید'];
    }
    $_builtShopCreate = bslBuildUnifiedDescription($p, $title);
    $brief = $_builtShopCreate['brief'] !== '' ? $_builtShopCreate['brief'] : mb_substr(s4HtmlToPlainTextForBsl($title), 0, 250, 'UTF-8');
    $desc  = bslEnsureRichCompliantDescription($_builtShopCreate['description'], $title, $p, $hasBarcode);
    $imgUrls=function_exists('productImageList')?productImageList($p):[];
    $detailLink=trim((string)($p['link']??$p['url']??''));
    if(!$imgUrls&&$detailLink!==''){
        $detailRes=fetch_html($detailLink,20);
        if(!empty($detailRes['ok'])&&!empty($detailRes['html'])){
            $rescued=extractImageFromHtml((string)$detailRes['html'],$detailLink);
            if($rescued!==''&&!bslIsPlaceholderImageUrl($rescued))$imgUrls=[$rescued];
        }
    }
    if(!$imgUrls)return ['ok'=>false,'error'=>'محصول تصویر قابل ارسال ندارد','error_code'=>422,
        'error_step'=>'photo_prepare','error_detail'=>'پروفایل و صفحهٔ جزئیات هیچ تصویر معتبری ندارند؛ باسلام ساخت بدون photo را قبول نمی‌کند'];
    $oldProductLink=$GLOBALS['_currentProductLink']??null;
    $GLOBALS['_currentProductLink']=(string)($p['link']??$p['url']??'');
    $uploaded=bslUploadMany($tk,$imgUrls,max(1,min(3,(int)($opts['upload_max_photos']??1))));
    if($oldProductLink===null)unset($GLOBALS['_currentProductLink']);else $GLOBALS['_currentProductLink']=$oldProductLink;
    if(empty($uploaded['ok'])||(int)($uploaded['main']??0)<=0)return ['ok'=>false,
        'error'=>(string)($uploaded['note']??'آپلود تصویر باسلام ناموفق بود'),
        'error_code'=>(int)($uploaded['error_code']??0),'error_step'=>'photo_upload',
        'error_detail'=>(string)($uploaded['error_detail']??$uploaded['note']??''),
        'retry_after'=>(int)($uploaded['retry_after']??0),'rate_source'=>(string)($uploaded['rate_source']??'')];
    $photoId=(int)$uploaded['main'];$photoIds=array_values(array_map('intval',(array)($uploaded['ids']??[$photoId])));
    $bp = ['name' => mb_substr($title, 0, 120), 'brief' => mb_substr($brief, 0, 250),
           'description' => $desc, 'primary_price' => $priceRial, 'stock' => $stock,
           'preparation_days' => $prepD, 'weight' => $weight, 'package_weight' => $pkgW,
           'is_wholesale' => false, 'category_id' => $catUsed, 'photo'=>$photoId,'photos'=>$photoIds,'status' => 2976];
    if (!empty($p['sku'])) $bp['sku'] = $p['sku'];
    if ($barcodeVal !== '') $bp['barcode'] = $barcodeVal;
    $_bslShopVarsNew = bslBuildVariantsPayload($p, $priceRial, $stock);
    if ($_bslShopVarsNew) $bp['variants'] = $_bslShopVarsNew;
    $pRawKey = (string)($p['_key'] ?? ($p['key'] ?? ($p['link'] ?? '')));
    $r = bslReqWithVariantsFallback($tk, 'POST', 'vendors/' . $vid . '/products', $bp);
    if (!empty($r['ok']) && !empty($r['body']['id'])) {
        bslShopMapRecord($p, $shop, (int)$r['body']['id'], $title, $priceRial, $stock);
        bslClearAiCategoryFixPending($vid, $pRawKey, $title);
        return ['ok' => true, 'id' => (int)$r['body']['id'], 'action' => 'created', 'used_cat_id' => $catUsed, 'update_reason' => 'ایجاد محصول جدید'];
    }
    if((int)($r['code']??0)===429){
        return array_merge(['ok'=>false],bslSendErrorInfo($r,'shop_create','vendors/'.$vid.'/products'));
    }
    $handleDupInShop = static function (array $dupResp) use ($opts, $tk, $vid, $title, $__mk, $p, $shop, $priceRial, $stock, $prepD, $weight, $pkgW, $photoId, $photoIds, $pRawKey): array {
        if(!empty($opts['skip_find_existing'])){
            return ['ok'=>false,'deferred_duplicate'=>true,'duplicate_name'=>true,
                'error'=>'نام محصول تکراری است؛ جستجوی موازی در همهٔ وضعیت‌های باسلام صف شد',
                'error_code'=>(int)($dupResp['code']??422),'error_step'=>'duplicate_deferred'];
        }
        $buDup = ['primary_price' => $priceRial, 'stock' => $stock, 'status' => ($stock > 0 ? 2976 : 3790),
                  'preparation_days' => $prepD, 'weight' => $weight, 'package_weight' => $pkgW,
                  'photo' => $photoId, 'photos' => $photoIds];
        $fuDup = bslForceUpdateOnDuplicate($tk, $vid, $title, $__mk, $buDup, $p);
        if (!empty($fuDup['ok']) && (int)($fuDup['id'] ?? 0) > 0) {
            $dupId = (int)$fuDup['id'];
            bslShopMapRecord($p, $shop, $dupId, $title, $priceRial, $stock);
            bslClearAiCategoryFixPending($vid, $pRawKey, $title);
            return ['ok' => true, 'id' => $dupId, 'action' => 'duplicate_update', 'update_reason' => 'آپدیت اجباری از نام تکراری', 'changes_detail' => 'محصول هم‌نام در غرفه پیدا و بدون تغییر category_id آپدیت شد'];
        }
        return array_merge(['ok' => false, 'duplicate_name' => true], bslSendErrorInfo($dupResp, 'duplicate_update', 'vendors/' . $vid . '/products'), [
            'error' => 'نام تکراری — آپدیت محصول موجود ناموفق: ' . (string)($fuDup['error'] ?? bslErrText($dupResp)),
        ]);
    };
    if (bslIsDuplicateName($r)) {
        return $handleDupInShop($r);
    }
    if ($aiDirect) {
        $infoAi = bslSendErrorInfo($r, 'ai_cat_create', 'vendors/' . $vid . '/products');
        $infoAi['tried_cat_ids'] = [$catUsed];
        $infoAi['last_response'] = $r;
        return array_merge(['ok' => false], $infoAi);
    }
    if (bslIsCategoryError($r)) {
        $triedAll = [$catUsed];
        $finalResp = $r;
        if (!empty($remainingManual)) {
            $fb = bslTryCreateWithFallback($tk, $vid, $bp, $remainingManual, $title, false, [], []);
            if (!empty($fb['ok']) && !empty($fb['body']['id'])) {
                $newId = (int)$fb['body']['id'];
                $usedCat = (int)($fb['used_cat_id'] ?? $catUsed);
                bslShopMapRecord($p, $shop, $newId, $title, $priceRial, $stock);
                bslClearAiCategoryFixPending($vid, $pRawKey, $title);
                return ['ok' => true, 'id' => $newId, 'action' => 'created', 'used_cat_id' => $usedCat, 'tried_cat_ids' => $fb['tried'] ?? $triedAll, 'update_reason' => 'ایجاد محصول جدید با دستهٔ جایگزین دستی #' . $usedCat];
            }
            if (!empty($fb['stopped'])) {
                return ['ok' => false, 'stopped' => true, 'error' => 'stopped'];
            }
            if (!empty($fb['rate_limited']) && is_array($fb['last_response'] ?? null)) {
                return array_merge(['ok' => false], bslSendErrorInfo($fb['last_response'], 'shop_create', 'vendors/' . $vid . '/products'));
            }
            if (!empty($fb['duplicate_name']) && is_array($fb['last_response'] ?? null)) {
                return $handleDupInShop($fb['last_response']);
            }
            $triedAll = is_array($fb['tried'] ?? null) && !empty($fb['tried']) ? $fb['tried'] : $triedAll;
            if (is_array($fb['last_response'] ?? null)) $finalResp = $fb['last_response'];
            if (empty($fb['all_categories_rejected'])) {
                $infoNonCat = bslSendErrorInfo($finalResp, 'shop_create', 'vendors/' . $vid . '/products');
                $infoNonCat['tried_cat_ids'] = $triedAll;
                return array_merge(['ok' => false], $infoNonCat);
            }
        }
        $aiQueued = bslQueueForAiCategoryFix($p, [
            'vendor_id'         => $vid,
            'shop_name'         => (string)($shop['shop_name'] ?? ($shop['name'] ?? '')),
            'profile_key'       => (string)($opts['profile_key'] ?? ($p['_profile_key'] ?? '')),
            'profile_name'      => (string)($profile['name'] ?? ($p['_profile_name'] ?? '')),
            'product_key'       => $pRawKey,
            'bare'              => (string)($opts['bare'] ?? ''),
            'title'             => $title,
            'tried_cat_ids'     => $triedAll,
            'forced_price_toman'=> $forcedPrice > 0 ? $forcedPrice : $priceToman,
            'endpoint'          => 'vendors/' . $vid . '/products',
            'error_code'        => (int)($finalResp['code'] ?? 422),
            'error'             => bslErrText($finalResp),
            'error_detail'      => (string)($finalResp['raw'] ?? json_encode($finalResp['body'] ?? [], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)),
            'step'              => 'shop_create',
        ]);
        return bslBuildFinalCategoryDeferredError($finalResp, $vid, $triedAll, $aiQueued, 'shop_create');
    }
    $em = $r['body']['message'] ?? $r['body']['error'] ?? ($r['error'] ?? '؟');
    if (is_array($em)) $em = json_encode($em, JSON_UNESCAPED_UNICODE);
    $info = bslSendErrorInfo($r, 'shop_create', 'vendors/' . $vid . '/products');
    if (empty($info['error'])) $info['error'] = mb_substr((string)$em, 0, 140);
    return array_merge(['ok' => false], $info);
}

/** امضای تنظیمات قیمت — اگر عوض شود یعنی قیمت همهٔ محصولات عوض شده */
function profilePriceSignature(array $profile): string {
    return (string)($profile['priceMode'] ?? 'none') . '|'
         . (string)($profile['priceVal'] ?? 0) . '|'
         . (string)($profile['roundPrice'] ?? 0) . '|'
         . trim((string)($profile['titleSuffix'] ?? ''));
}

/* =====================================================================
 *  v10.34 (۴۸ب): امضای ضرایبِ تعدیلِ مقصدها و غرفه‌ها.
 *
 *  profilePriceSignature فقط ضریبِ خودِ پروفایل را می‌دید. ولی قیمتِ
 *  نهاییِ یک محصول از سه لایه می‌آید:
 *      ۱) تعدیلِ پروفایل            (priceMode/priceVal/roundPrice)
 *      ۲) تعدیلِ مقصد               (woocommerce/basalam · price_mode…)
 *      ۳) تعدیلِ مخصوصِ هر غرفه      (basalam.vendors[].price_mode…)
 *
 *  اگر کاربر لایهٔ ۲ یا ۳ را عوض می‌کرد، قیمتِ همهٔ محصولات عوض می‌شد ولی
 *  هیچ‌کس خبردار نمی‌شد: امضا دست‌نخورده می‌ماند، تیکِ «فقط تغییرات» روشن
 *  بود و مبدأ هم چیزی تغییر نداده بود — پس هیچ محصولی صف نمی‌شد و قیمتِ
 *  تازه هرگز به مقصد نمی‌رسید. تنها راهِ اعمالش خاموش‌کردنِ دستیِ تیک بود.
 *
 *  حالا این امضا جدا نگه داشته می‌شود (کلیدِ shop_sig در وضعیتِ سینک) و
 *  هر تغییری در آن یک نوبت ارسالِ «همه با دستور آپدیت» راه می‌اندازد.
 *  جدا بودنش از price_sig عمدی است: ردیف‌های قدیمی این کلید را ندارند و
 *  نبودنش «تغییر» حساب نمی‌شود، وگرنه صرفاً با نصبِ این نسخه یک ارسالِ
 *  کاملِ ناخواسته برای همهٔ پروفایل‌ها راه می‌افتاد.
 * ===================================================================== */
function shopPricingSignature(array $cn): string {
    $parts = [];
    foreach (['woocommerce', 'basalam'] as $dest) {
        $d = $cn[$dest] ?? [];
        $parts[] = $dest . ':' . (string)($d['price_mode'] ?? 'none')
                 . '/' . (string)($d['price_val'] ?? 0)
                 . '/' . (string)($d['price_round'] ?? 0);
    }
    /* غرفهٔ پیش‌فرض هم ضریبِ خودش را دارد و باید دیده شود */
    $parts[] = 'v0:' . (int)($cn['basalam']['vendor_id'] ?? 0);
    $vendors = $cn['basalam']['vendors'] ?? [];
    if (is_array($vendors)) {
        $rows = [];
        foreach ($vendors as $v) {
            if (!is_array($v)) continue;
            $vid = (int)($v['vendor_id'] ?? 0);
            if ($vid <= 0) continue;
            $rows[] = 'v' . $vid . ':' . (string)($v['price_mode'] ?? 'none')
                    . '/' . (string)($v['price_val'] ?? 0);
        }
        sort($rows);   // ترتیبِ ردیف‌ها در تنظیمات نباید «تغییر» حساب شود
        $parts = array_merge($parts, $rows);
    }
    return implode('|', $parts);
}

/* =====================================================================
 *  v10.34 (۴۸الف): اقدامِ حالتِ «افزودن/آپدیت» روی محصولاتِ رفته از مبدأ.
 *
 *  خواستهٔ کاربر: وقتی تیکِ افزودن/آپدیت روشن است، فرآیند باید
 *  «افزودن/آپدیت/بایگانی» برای باسلام و «افزودن/آپدیت/حذف» برای ووکامرس
 *  باشد — یعنی خودِ تیک، بازنشستگی را هم روشن می‌کند و دیگر لازم نیست
 *  کاربر جداگانه تنظیمِ سراسریِ «محصولات رفته از مبدأ» را از off دربیاورد.
 *
 *  اقدامِ ووکامرس قابلِ انتخاب است (کاربر صراحتاً خواست): زباله‌دان
 *  (پیش‌فرض و برگشت‌پذیر)، حذفِ همیشگی، پیش‌نویس، یا ناموجود.
 *  اقدامِ باسلام هم قابلِ انتخاب است ولی «حذفِ همیشگی» ندارد، چون API
 *  باسلام اصلاً حذف ندارد و نزدیک‌ترین چیز بایگانی (4184) است.
 * ===================================================================== */
function retireWooActions(): array {
    return ['delete' => 'حذف (زباله‌دان)', 'delete_force' => 'حذف همیشگی',
            'draft' => 'پیش‌نویس', 'outofstock' => 'ناموجود'];
}
function retireBslActions(): array {
    return ['delete' => 'بایگانی', 'draft' => 'غیرفعال', 'outofstock' => 'ناموجود'];
}
/** اقدامِ مؤثرِ هر مقصد در حالتِ «افزودن/آپدیت» — با اعتبارسنجی و پیش‌فرضِ امن */
function retireAddUpdateAction(array $cn, string $dest): string {
    if ($dest === 'woo') {
        $a = (string)($cn['retire_woo_action'] ?? 'delete');
        return isset(retireWooActions()[$a]) ? $a : 'delete';
    }
    $a = (string)($cn['retire_bsl_action'] ?? 'delete');
    return isset(retireBslActions()[$a]) ? $a : 'delete';
}

/** محصول ذخیره‌شده را به همان شکلی درمی‌آورد که مرورگر می‌فرستد */
function prepareForSend(array $profile, string $key, array $p): array {
    $raw = (string)($p['price'] ?? '');
    $title = trim((string)($p['title'] ?? ($p['name'] ?? '')));
    $suffix = trim((string)($profile['titleSuffix'] ?? ''));
    if ($suffix !== '' && $title !== '' && mb_strpos($title, $suffix) === false) {
        $title .= ' ' . $suffix;
    }
    $unit = (mb_strpos($raw, 'ریال') !== false || mb_strpos($raw, 'ر.ی') !== false)
          ? 'rial' : 'toman';
    return [
        'key'         => $key,
        'title'       => $title,
        'final_price' => (string)profileFinalPrice($profile, $raw),
        'price'       => $raw,
        'price_unit'  => $unit,
        'image'       => (string)($p['image'] ?? ''),
        // v8.64: گالری — بقیهٔ عکس‌های محصول همراهش می‌روند
        'images'      => productImageList($p),
        'sku'         => (string)($p['sku'] ?? ''),
        'short_desc'  => (string)($p['shortDesc'] ?? ($p['short_desc'] ?? '')),
        'long_desc'   => s4MergeSpecsTableIntoHtml((string)($p['longDesc'] ?? ($p['long_desc'] ?? '')), $p),
        'specs'       => (string)($p['specs'] ?? ''),
        'brand'       => (string)($p['brand'] ?? ''),
        'category'    => (string)($p['category'] ?? ''),
        'bsl_category_id' => (int)($p['bsl_category_id'] ?? $p['bslCategoryId'] ?? $p['category_id'] ?? 0),
        'stock'       => (string)($p['stock'] ?? ''),
        'in_stock'    => array_key_exists('in_stock', $p) ? (bool)$p['in_stock'] : null,
        'weight'      => (string)($p['weight'] ?? ''),
        'package_weight' => (string)($p['package_weight'] ?? ($p['packaged_weight'] ?? '')),
        'link'        => (string)($p['link'] ?? ''),
        'orig_price'  => (string)($p['origPrice'] ?? ($p['originalPrice'] ?? '')),
        // v8.69 / v10.458: تنوع‌ها + قیمت هر تنوع و ترکیب‌ها هم باید به ارسال‌کننده برسند
        'variations'             => is_array($p['variations'] ?? null) ? $p['variations'] : [],
        'variation_groups'       => is_array($p['variation_groups'] ?? null) ? $p['variation_groups'] : [],
        'variation_prices'       => is_array($p['variation_prices'] ?? null) ? $p['variation_prices'] : [],
        'variation_combinations' => is_array($p['variation_combinations'] ?? null) ? $p['variation_combinations'] : [],
        'variations_text'  => (string)($p['variations_text']
                              ?? (is_array($p['variations'] ?? null) ? implode('، ', $p['variations']) : '')),
    ];
}

/**
 * v10.460: ساخت مستقیم فهرست محصولات صف ارسال (باسلام و ووکامرس) روی سرور از روی
 * پروفایل ذخیره‌شده بدون نیاز به آپلود چندمگابایتی JSON/HTML از مرورگر کاربر.
 */
function s4BuildQueueProductsFromProfile(array $profile, array $overrides = []): array {
    $profCopy = $profile;
    if (array_key_exists('title_suffix', $overrides) && $overrides['title_suffix'] !== null) {
        $profCopy['titleSuffix'] = trim((string)$overrides['title_suffix']);
    }
    if (array_key_exists('price_mode', $overrides) && in_array((string)$overrides['price_mode'], ['none', 'percent', 'multiplier', 'fixed'], true)) {
        $profCopy['priceMode'] = (string)$overrides['price_mode'];
    }
    if (array_key_exists('price_val', $overrides) && $overrides['price_val'] !== '' && $overrides['price_val'] !== null) {
        $profCopy['priceVal'] = (float)$overrides['price_val'];
    }
    if (array_key_exists('round_price', $overrides) && $overrides['round_price'] !== '' && $overrides['round_price'] !== null) {
        $profCopy['roundPrice'] = (string)$overrides['round_price'];
    }
    return array_values(profileOrderedProducts($profCopy, null, true));
}

/**
 * از نتیجهٔ استخراج، کلید محصولاتی را برمی‌گرداند که باید ارسال شوند.
 * خروجی null یعنی «فیلتری اعمال نکن» (همه را بفرست).
 */
function syncChangedKeys(array $exRes): ?array {
    if (empty($exRes['ok'])) return null;   // استخراج نشد؛ به لیست تغییرات اعتماد نکن
    $keys = [];
    foreach (['new_items', 'changed_items'] as $bucket) {
        foreach (($exRes[$bucket] ?? []) as $it) {
            if (!is_array($it)) continue;
            $k = (string)($it['key'] ?? '');
            if ($k !== '') $keys[$k] = true;
        }
    }
    return $keys;
}

/**
 * محصولات پروفایل را به ترتیب درست و همراه با کلیدشان برمی‌گرداند.
 * محصولات به شکل [کلید, محصول] ذخیره می‌شوند و کران قبلاً کلید را دور
 * می‌ریخت؛ برای فیلتر کردن لازم است نگه داشته شود.
 *
 * $onlyKeys اگر داده شود، فقط همان کلیدها برگردانده می‌شوند.
 */
function profileOrderedProducts(array $profile, ?array $onlyKeys = null, bool $forSend = true): array {
    $raw = $profile['products'] ?? [];
    $map = [];
    foreach ($raw as $entry) {
        if (is_array($entry) && count($entry) >= 2 && is_string($entry[0])) {
            $map[$entry[0]] = $entry[1];
        }
    }
    // v8.44: قیمت نهایی را همین‌جا بساز، وگرنه ارسال‌کننده final_price
    // را پیدا نمی‌کند و قیمت صفر می‌فرستد.
    $mk = function (string $k, $p) use ($profile, $forSend) {
        if (!is_array($p)) return null;
        return $forSend ? prepareForSend($profile, $k, $p) : $p;
    };
    $order = $profile['productsOrder'] ?? [];
    $out = [];
    if (!empty($order) && is_array($order)) {
        foreach ($order as $k) {
            if (!isset($map[$k])) continue;
            if ($onlyKeys !== null && !isset($onlyKeys[$k])) continue;
            $v = $mk((string)$k, $map[$k]); if ($v !== null) $out[] = $v;
        }
        return $out;
    }
    if ($map) {
        foreach ($map as $k => $p) {
            if ($onlyKeys !== null && !isset($onlyKeys[$k])) continue;
            $v = $mk((string)$k, $p); if ($v !== null) $out[] = $v;
        }
        return $out;
    }
    // ساختار قدیمی: فهرست تخت بدون کلید — فیلتر ممکن نیست
    foreach ($raw as $entry) {
        if (!is_array($entry) || (!isset($entry['title']) && !isset($entry['price']))) continue;
        $k = (string)($entry['key'] ?? '');
        $out[] = $forSend ? prepareForSend($profile, $k, $entry) : $entry;
    }
    return $out;
}

// v8.31: تنها نقطهٔ ورود کران — cron_sync حذف شد چون دقیقاً همین کار را می‌کرد.
/**
 * v8.89: نگهبان‌ها در یک تابع، تا بشود آن‌ها را قبل از قفل کران هم اجرا کرد.
 *
 * تا ۸.۸۸ این کد داخل بدنهٔ cron_run بود و بعد از بررسی قفل قرار داشت.
 * ولی وقتی یک اجرا وسط کار می‌مُرد، فایل قفل باقی می‌ماند و تا ۳۰ دقیقه
 * هر اجرای بعدی همان اول رد می‌شد — یعنی دقیقاً در حالتی که نگهبان لازم
 * بود، هیچ‌وقت اجرا نمی‌شد و کار گیرکرده تا نیم ساعت همان‌طور می‌ماند.
 */
/* =====================================================================
   v9.92: «نوبت را همین حالا مصرف کن» — رفعِ ریشه‌ایِ اجرای مکررِ کران.

   تا ۹.۹۱، lastRun فقط جایی نوشته می‌شد که پروفایل واقعاً به مرحلهٔ
   ارسال می‌رسید، و saveSyncState هم تازه «بعد از پایانِ کلِ حلقه» صدا
   زده می‌شد. یعنی lastRun فقط در سناریوی کاملاً موفق روی دیسک می‌نشست.
   هر خروجِ زودهنگام یا هر مرگِ پردازه آن را از بین می‌برد:

     • $stageOpen ⇒ status=detail_pending ⇒ continue — بدونِ lastRun
     • target='none' ⇒ هیچ‌کدام از شاخه‌های woo/bsl اجرا نمی‌شود ⇒ فقط
       price_sig ست می‌شود، lastRun نه
     • استخراجِ طولانی ⇒ هاست پردازه را می‌کشد ⇒ saveSyncState هرگز
       اجرا نمی‌شود ⇒ هیچ‌چیز ذخیره نمی‌شود

   نتیجه در هر سه حالت یکی است: تیکِ بعدی (یک دقیقه بعد) همان پروفایل
   را باز هم «due» می‌بیند و کلِ کار — از جمله فازِ جزئیات — دوباره
   شروع می‌شود. دورهٔ ۶ ساعته یا ۲ ساعته عملاً بی‌اثر بود.

   درست این است که نوبت «در لحظهٔ شروع» و «مستقیم روی دیسک» مصرف شود:
   یک نوبت یعنی یک بار تلاش، نه یک بار موفقیت. */
function cronMarkRun(string $key, string $status = 'running'): void {
    if ($key === '') return;
    $st = loadSyncState();
    $row = is_array($st[$key] ?? null) ? $st[$key] : [];
    $row['lastRun'] = time();
    $row['status']  = $status;
    $st[$key] = $row;
    saveSyncState($st);
}

/**
 * v10.24 (۳۷الف): ترتیبِ بازیابیِ صف‌های گیرکرده، بر پایهٔ اولویتِ کاربر.
 *
 * عمداً مستقیم فایلِ ترتیب را می‌خواند و به tasksOrder() تکیه نمی‌کند:
 * نگهبانِ کران در خطِ ~۱۳۶۸۰ اجرا می‌شود، ولی tasksRegistry()/tasksOrder()
 * پایین‌ترِ فایل تعریف می‌شوند و در آن لحظه هنوز وجود ندارند
 * (Call to undefined function). این تابع فقط دو کلیدِ صف را می‌شناسد و
 * هر چیزِ دیگری در فایل را نادیده می‌گیرد، پس به رجیستری نیاز ندارد.
 */
function cronWatchdogQueueOrder(): array {
    $def = ['bsl', 'woo'];
    if (!is_file(TASKS_ORDER_FILE)) return $def;
    $d = json_decode((string)@file_get_contents(TASKS_ORDER_FILE), true);
    $saved = is_array($d['order'] ?? null) ? $d['order'] : [];
    if (!$saved) return $def;
    /* کلیدهای رجیستری «bsl_send»/«woo_send» هستند؛ نگهبان با «bsl»/«woo»
       کار می‌کند، پس نگاشت می‌شود. */
    $map = ['bsl_send' => 'bsl', 'woo_send' => 'woo'];
    $out = [];
    foreach ($saved as $k) {
        $q = $map[(string)$k] ?? '';
        if ($q !== '' && !in_array($q, $out, true)) $out[] = $q;
    }
    foreach ($def as $q) if (!in_array($q, $out, true)) $out[] = $q;
    return $out;
}

function cronRecordResumeBlock(array &$results,array $block): void {
    if(!isset($results['resume_blocks'])||!is_array($results['resume_blocks']))$results['resume_blocks']=[];
    $sig=implode('|',[(string)($block['kind']??''),(string)($block['which']??''),(string)($block['key']??''),(string)($block['queue_id']??'')]);
    foreach($results['resume_blocks'] as $old){
        if(!is_array($old))continue;
        $oldSig=implode('|',[(string)($old['kind']??''),(string)($old['which']??''),(string)($old['key']??''),(string)($old['queue_id']??'')]);
        if($oldSig===$sig)return;
    }
    $results['resume_blocks'][]=$block;
    if(empty($results['resume_blocking']))$results['resume_blocking']=$block;
}

/** v10.423: rebuild a Basalam queue owner when the durable progress and
 * per-run products file survived but bsl_queue.json lost the row. This is the
 * exact production failure where progress remained at 2588/4040, the backend
 * flock was free, and cron had nothing to select. */
function bslRecoverMissingQueueRowFromProgress(array $cn): array {
    $progress=readProgress(BSL_PROGRESS_FILE);$qid=trim((string)($progress['queue_id']??''));
    $current=max(0,(int)($progress['current']??0));$total=max(0,(int)($progress['total']??0));
    if($qid===''||!empty($progress['done'])||$total<=0||$current>=$total)
        return ['recovered'=>false,'reason'=>'no_incomplete_progress'];
    if(queueHasExplicitUserStop('bsl',$qid))return ['recovered'=>false,'reason'=>'explicit_user_stop'];
    $guard=@fopen(BSL_QUEUE_FILE.'.orphan.lock','c');
    if(!$guard||!@flock($guard,LOCK_EX|LOCK_NB)){if($guard)@fclose($guard);return ['recovered'=>false,'reason'=>'repair_busy'];}
    try{
        $queue=bslReadQueue();
        foreach((array)($queue['entries']??[])as$row)
            if(is_array($row)&&(string)($row['id']??'')===$qid)return ['recovered'=>false,'reason'=>'row_exists','queue_id'=>$qid];
        $baseQid=preg_replace('/_s\d+$/','',$qid)?:$qid;
        $files=array_values(array_unique([
            __DIR__.'/bsl_queue_products_'.basename($qid).'.json',
            __DIR__.'/bsl_queue_products_'.basename($baseQid).'.json',
        ]));
        $productsFile='';$actualTotal=0;
        foreach($files as$file){
            if(!is_file($file))continue;$items=@json_decode((string)@file_get_contents($file),true);
            if(!is_array($items)||count($items)<$current)continue;
            $productsFile=$file;$actualTotal=count($items);break;
        }
        if($productsFile==='')return ['recovered'=>false,'reason'=>'missing_products_file','queue_id'=>$qid];
        $profiles=loadProfiles();$profileKey=trim((string)($progress['profile_key']??''));
        if($profileKey===''||!is_array($profiles[$profileKey]??null)){
            $bestLen=-1;
            foreach($profiles as$key=>$candidate){
                if(!is_array($candidate))continue;$needle='_'.(string)$key.'_';
                if(strpos($qid,$needle)!==false&&strlen((string)$key)>$bestLen){$profileKey=(string)$key;$bestLen=strlen((string)$key);}
            }
        }
        $profile=is_array($profiles[$profileKey]??null)?$profiles[$profileKey]:[];
        if(!$profile)return ['recovered'=>false,'reason'=>'profile_not_found','queue_id'=>$qid];
        $vendorId=(int)($progress['phase_shop_vendor_id']??0);
        if($vendorId<=0&&preg_match('/_s(\d+)$/',$qid,$m))$vendorId=(int)$m[1];
        $shop=[];foreach((array)bslAllShops($cn)as$candidate)
            if((int)($candidate['vendor_id']??0)===$vendorId){$shop=$candidate;break;}
        if($vendorId<=0)$vendorId=(int)($shop['vendor_id']??$cn['basalam']['vendor_id']??0);
        $catId=(int)($profile['bslCategoryId']??0);if($catId<=0)$catId=(int)($cn['basalam']['category_id']??0);
        $fallback=array_values(array_unique(array_merge((array)($profile['bslFallbackCatIds']??[]),(array)($cn['basalam']['fallback_cat_ids']??[]))));
        $now=time();$row=['id'=>$qid,'status'=>'running','products_file'=>$productsFile,
            'total'=>max($total,$actualTotal),'sent'=>(int)($progress['sent']??0),'updated'=>(int)($progress['updated']??0),
            'skipped'=>(int)($progress['skipped']??0),'failed'=>(int)($progress['failed']??0),'current'=>$current,
            'started_at'=>(int)($progress['started_at']??$now),'updated_at'=>(int)($progress['last_progress_ts']??$now),
            'done_at'=>0,'paused_at'=>0,'resumable'=>true,'resume_requested_at'=>$now,
            'profile_key'=>$profileKey,'profile_name'=>(string)($profile['name']??$profileKey),
            'shop_vendor_id'=>$vendorId,'shop_name'=>(string)($shop['shop_name']??$progress['phase_shop_name']??''),
            'shop_is_default'=>!empty($shop['is_default']),'batch_id'=>$baseQid,
            'trigger'=>strpos($qid,'manual')===0?'manual_sync':'cron','auto_sync'=>true,'only_changed'=>true,
            'config'=>['category_id'=>$catId,'auto_category'=>!empty($cn['basalam']['auto_category']),
                'title_suffix'=>trim((string)($profile['titleSuffix']??''))?:trim((string)($cn['basalam']['title_suffix']??'')),
                'delay_ms'=>max(0,(int)($cn['basalam']['delay_ms']??500)),
                'retry_delay_ms'=>max(0,(int)($cn['basalam']['retry_delay_ms']??1000)),
                'fallback_cat_ids'=>$fallback,'send_all_shops'=>0,'fanout'=>$vendorId>0?1:0,
                'shop_vendor_id'=>$vendorId,'shop_name'=>(string)($shop['shop_name']??$progress['phase_shop_name']??''),
                'force_all'=>false],
            'recovered_from_progress'=>true,'recovered_at'=>$now,
            'error'=>'ردیف صف از checkpoint و فایل محصولات بازسازی شد'];
        $queue['entries'][]=$row;bslWriteQueue($queue);
        autoResumeBookSet('bsl_send','',0);queueResumeBook('bsl',$qid,['tries'=>0,'at'=>$now,'from'=>$current,'status'=>'orphan_row_rebuilt']);
        return ['recovered'=>true,'queue_id'=>$qid,'profile_key'=>$profileKey,'current'=>$current,
            'total'=>max($total,$actualTotal),'products_file'=>basename($productsFile),'vendor_id'=>$vendorId];
    }finally{@flock($guard,LOCK_UN);@fclose($guard);}
}

function cronWatchdogs(array $cn): array {
    $results = ['watchdog' => []];
    $orphanSend=bslRecoverMissingQueueRowFromProgress($cn);
    if(!empty($orphanSend['recovered']))$results['bsl_orphan_row_recovered']=$orphanSend;
    /* Reconcile Send-tab shop selection before any recovery. This also cleans
       a shop-disabled row after an older in-memory worker honored our targeted
       stop and released its flock. */
    $results['bsl_shop_selection']=bslReconcileDisabledShopsNow($cn);
// v8.33: مرحلهٔ نگهبان — اگر ارسالی وسط راه گیر کرده، ادامه‌اش بده.
    // هزینه‌اش وقتی چیزی گیر نکرده صفر است: فقط چند خط خواندن از فایل.
    $stallCfg  = (int)($cn['stall_after'] ?? 300);
    $stallWake = !isset($cn['stall_watchdog']) || !empty($cn['stall_watchdog']);
    /* Basalam completion recovery is mandatory: disabling the generic stall
       watchdog must not strand a partially sent shop row. Woo still follows
       the saved watchdog switch. */
    {
        $results['watchdog'] = [];
        /* Respect the saved destination order, but inspect both independent
           queues during this pulse. Each backend still has its own flock and
           only one row per destination can be dispatched at a time. */
        foreach (cronWatchdogQueueOrder() as $wq) {
            if(!$stallWake&&$wq!=='bsl')continue;
            /* Promote every eligible paused row even while a healthy row is
               running. The destination flock keeps mutation separate from workers. */
            $batchResume=queuePromotePausedForCron($wq);
            if(!empty($batchResume['promoted']))
                $results['paused_rows_promoted'][$wq]=(int)$batchResume['promoted'];
            /* توقفِ صریحِ کاربر از مسیرِ خودکار عبور نمی‌کند؛ صفِ واجدشرایط
               در همان ردیف/چک‌پوینت ادامه می‌یابد و workerها آن را به‌ترتیب برمی‌دارند. */
            /* Basalam is checked on every cron. A running row with no backend
               flock is resumed immediately on this pulse; 60 seconds remains
               only the conservative threshold for an owner that still holds
               the flock but has stopped producing product progress. */
            $queueStallAfter=$wq==='bsl'?BSL_SEND_STALL_SEC:$stallCfg;
            $w = queueStallRecover($wq, $queueStallAfter, false, 1500, true, false, true);
            if (!empty($w['stalled'])) {
                $results['watchdog'][] = $w;
                /* A still-held stale lock is reported in cron/task logs, but do
                   not send the same messenger alert every minute while waiting. */
                if (empty($w['user_stopped'])
                    && (empty($w['deferred']) || !empty($w['resumed']) || !empty($w['exhausted']))) {
                    notifRunFailure($cn, 'نگهبان صف',
                        $wq === 'bsl' ? 'باسلام' : 'ووکامرس',
                        'ارسال ' . ($w['kind'] === 'waiting' ? 'در صف مانده بود' : 'گیر کرده بود')
                        . ' (' . (int)($w['idle'] ?? 0) . ' ثانیه بی‌حرکت، '
                        . (int)($w['current'] ?? 0) . '/' . (int)($w['total'] ?? 0) . ') — '
                        . (!empty($w['resumed']) ? 'خودکار ادامه داده شد ✅' : 'ادامه ناموفق ❌'));
                }
            }
            /* Each destination is dispatched at most once here; their separate
               backend locks keep repeated cron pulses from creating duplicates. */
            if (!empty($w['resumed'])) {
                cronRecordResumeBlock($results,['kind'=>'queue','which'=>$wq,
                    'queue_id'=>(string)($w['queue_id']??'')]);
            }
        }
    }

    /* v8.87: نگهبان استخراج.
       صف ارسال از ۸.۳۳ نگهبان داشت ولی استخراج نداشت: اگر اجرای خودکار وسط
       کار می‌مُرد (تایم‌اوت هاست، ری‌استارت PHP، قطع شبکه)، ردیف برای همیشه
       «در حال اجرا» می‌ماند و ردیف‌های بعدی هم راه نمی‌افتادند. علامت‌خوردنِ
       «خطا» هم فقط وقتی اتفاق می‌افتاد که کسی صفحهٔ صف را باز کند. */
    /* Extraction recovery is a correctness guarantee, not a notification
       preference. Keep it active even when the generic send watchdog toggle is
       disabled; explicit user-stopped rows remain protected below. */
    if (true) {
        /* v10.405: guard cron scans with its own lock, never with slot 1.
           A healthy extractor in slot 1 must not hide stale rows in other
           profiles; each candidate is rechecked against its own live lock. */
        $exWatchFp = @fopen(EXTRACT_WATCHDOG_LOCK_FILE, 'c');
        $exWatchOwned = $exWatchFp && @flock($exWatchFp, LOCK_EX | LOCK_NB);
        if (!$exWatchOwned) {
            if (is_resource($exWatchFp)) @fclose($exWatchFp);
            $exWatchFp = null;
        }
        if ($exWatchOwned) {
        $exProg = readProgress(EXTRACT_PROGRESS_FILE);
        $exQ = extractReadQueue();
        $exNow = time();
        /* Product/lock heartbeats are precise. One minute without real progress
           is the fixed takeover threshold; definitive owner loss is recovered
           immediately on this cron pulse. */
        $exStallCfg=60;
        $exDirty=false;$exStuck=null;$exResumeKeys=[];$exProgressOwnedStuck=false;
        $exProgressStuck=null;$exProgressOwnerQueueId='';
        $exRunningRows=0;foreach((array)($exQ['entries']??[]) as $__qeCount){if(is_array($__qeCount)&&($__qeCount['status']??'')==='running')$exRunningRows++;}
        foreach ($exQ['entries'] as $qi => $qe) {
            if (($qe['status'] ?? '') !== 'running') continue;
            /* v8.91: همان اصلاحی که در extract_queue_status انجام شد.
               زمان پیشرفت فقط وقتی به این ردیف مربوط است که فایل پیشرفت
               هم مالِ همین ردیف باشد؛ وگرنه اجرای بعدی، ردیفِ رهاشدهٔ
               قبلی را «تازه» نشان می‌داد و نگهبان هیچ‌وقت نمی‌بستش.
               شرط $alive هم برداشته شد: پردازهٔ مرده دقیقاً به این دلیل
               running=true جا می‌گذارد که فرصت نکرده done بنویسد. */
            /* v10.32 (۴۵ج): همان شاهدِ دومِ extract_queue_status — قفل.
               بدون این، نگهبان ردیفِ زندهٔ یک اجرای طولانی را از صف
               برمی‌داشت و استخراج عملاً نیمه‌کاره رها می‌شد.
               v10.36 (۴۹الف): و شاهدِ سوم — حرکتِ شمارنده‌ها. نگهبان دقیقاً
               همان چیزی بود که ردیفِ زنده را می‌بست و به پیام‌رسان خطای
               دروغ می‌فرستاد؛ حالا هر سه شاهد را با هم می‌سنجد. */
            $_qeProgressOwned=queueProgressBelongsToRow($exProg,$qe,$exRunningRows);
            $_qeProg=$_qeProgressOwned?$exProg:[];
            $_queueId=(string)($qe['id']??'');
            $_lkWBeat=extractLockBeatForQueue($_queueId);
            /* A living PID is ownership evidence, not progress evidence. Using
               "PID alive = heartbeat now" hid a blocked network call forever.
               Only product/progress and extraction-lock touches reset idle. */
            $_workerAlive=false;$_workerJobId=(string)($qe['worker_job_id']??'');
            if($_workerJobId!=='')foreach((array)(s4WorkerLoadQueue()['entries']??[])as $_we){
                if(!is_array($_we)||(string)($_we['id']??'')!==$_workerJobId||(string)($_we['status']??'')!=='running')continue;
                $_workerAlive=s4WorkerPidAlive((int)($_we['worker_pid']??0));break;}
            $_lockHeld=extractLockHeldForQueue($_queueId);
            $_ownerPresent=$_lockHeld||$_workerAlive;
            $_iwW = queueRowIdle('extract', $qe, $exProg, $exNow, ['lock' => $_lkWBeat], $exRunningRows);
            $idle = (int)$_iwW['idle'];
            if($_ownerPresent&&$idle<$exStallCfg)continue;
            /* A genuinely frozen child must relinquish its lock before the same
               queue row can be resumed. Mark only its worker job cancelled and
               signal that exact lock owner; this does not create a user stop. */
            $_retire=[];
            if($_ownerPresent){
                $_retire=extractCancelWorkerForQueueRow($qe,'stalled_auto_recovery');
                if(!empty($_retire['signal_sent']))usleep(250000);
            }
            /* v10.405: a separate watchdog lock lets this scan run beside
               healthy slots. Before changing anything, re-read this exact row
               under the queue-file lock and prove its own worker is not live. */
            $qePaused=extractQueuePauseStaleRow($_queueId,$exStallCfg,!$_ownerPresent);
            if(!is_array($qePaused)){
                if($_ownerPresent)$results['extract_termination_pending'][]=['queue_id'=>$_queueId,
                    'idle'=>$idle,'signal_sent'=>!empty($_retire['signal_sent'])];
                continue;
            }
            $exKey=(string)($qePaused['row']['profile_key']??$qe['profile_key']??'');
            $idle=(int)($qePaused['idle']??$idle);$exPhase=(string)($qePaused['phase']??'list');
            $_qeProgressOwned=!empty($qePaused['progress_owned']);
            $_qeProg=is_array($qePaused['progress']??null)?$qePaused['progress']:[];
            /* The same row ID and saved phase remain the continuation owner. */
            $exDirty=true;
            $_canResume=!empty($qePaused['resumable']);
            $exStuck=['idle'=>$idle,'profile'=>(string)($qe['profile_name']??$exKey),
                      'key'=>$exKey,'queue_id'=>(string)($qePaused['row']['id']??''),
                      'products'=>(int)($qePaused['products']??0),'resumable'=>$_canResume,
                      'owner_absent'=>!empty($qePaused['owner_absent'])];
            if($_canResume&&$_qeProgressOwned){$exProgressOwnedStuck=true;$exProgressStuck=$_qeProg;
                $exProgressOwnerQueueId=(string)($qePaused['row']['id']??'');}
            if($_canResume&&$exKey!==''){
                $exResumeKeys[]=$exKey;
                /* Save just this profile against the newest disk snapshot so
                   another parallel profile's checkpoint cannot be clobbered. */
                $exProfiles=loadProfiles();
                if(isset($exProfiles[$exKey])&&is_array($exProfiles[$exKey])){
                    $exProfiles[$exKey]['_extract_stage']='stopped';
                    $exProfiles[$exKey]['_extract_resume_phase']=$exPhase;
                    $exProfiles[$exKey]['_extract_list_incomplete']=$exPhase==='list';
                    $exProfiles[$exKey]['_extract_stage_at']=time();
                    saveOneProfileAtomic($exKey,$exProfiles[$exKey]);
                }
            }elseif(!$_canResume){
                $results['extract_terminal_zero_products'][]=['key'=>$exKey,
                    'queue_id'=>(string)($qePaused['row']['id']??''),'idle'=>$idle];
            }
        }
        if($exDirty){
            /* The queue row was already changed atomically by
               extractQueuePauseStaleRow(); never write the old scan snapshot. */
            if($exProgressOwnedStuck&&is_array($exProgressStuck)){
                $latestProgress=readProgress(EXTRACT_PROGRESS_FILE);
                $latestOwner=(string)($latestProgress['queue_id']??'');
                $sameOwner=$latestOwner!==''&&$latestOwner===$exProgressOwnerQueueId;
                if($latestOwner===''&&$exProgressOwnerQueueId!==''){
                    $latestQueue=extractReadQueue();$stillRunning=0;
                    foreach((array)($latestQueue['entries']??[])as$entry)
                        if(is_array($entry)&&($entry['status']??'')==='running')$stillRunning++;
                    $sameOwner=$stillRunning===0;
                }
                if($sameOwner&&!empty($latestProgress['running'])){
                    $latestProgress['running']=false;$latestProgress['done']=false;$latestProgress['paused']=true;
                    $latestProgress['resume_needed']=true;$latestProgress['stalled']=true;
                    $latestProgress['recent_log']=array_slice(array_merge((array)($latestProgress['recent_log']??[]),
                        ['♻️ کران اجرای بی‌حرکت را تحویل گرفت؛ ادامه از checkpoint در نوبت بعد']),-12);
                    writeProgress(EXTRACT_PROGRESS_FILE,$latestProgress);
                }
            }
            $results['extract_watchdog']=$exStuck;
            $results['extract_resume']=array_values(array_unique($exResumeKeys));
            notifRunFailure($cn,'نگهبان استخراج',$exStuck['profile']?:'استخراج',
                !empty($exStuck['resumable'])
                    ? ('استخراج '.(int)$exStuck['idle'].' ثانیه بی‌حرکت بود — همان ردیف حفظ شد و '
                        .'در همین نوبت از checkpoint ادامه داده می‌شود.')
                    : ('استخراج بدون محصول متوقف شد — ادامهٔ خودکار برای جلوگیری از تکرار بی‌پایان بسته شد.'));
        }
        @flock($exWatchFp, LOCK_UN); @fclose($exWatchFp); $exWatchFp = null;
        }
    }

    /* ═══════ v10.39 (۵۳): ساختِ زمان‌بندی‌شدهٔ فهرستِ محصولاتِ باسلام ═══════

       هدف: وقتی کاربر «حذفِ تکراری» یا هر کارِ دیگری را اجرا می‌کند، فهرست
       از قبل آماده باشد و آن لحظه صرفِ گرفتنِ هزاران محصول از باسلام نشود.
       اینجا داخلِ کران است، یعنی در پس‌زمینه و بدونِ اینکه کاربر منتظر بماند.

       فقط غرفه‌هایی بازسازی می‌شوند که کششان کهنه شده؛ اگر همه تازه باشند
       این بلوک عملاً رایگان است و هیچ درخواستی نمی‌زند. */
    if (empty($results['resume_blocking'])
        && (!empty($cn['bsl_catalog_auto']) || !isset($cn['bsl_catalog_auto']))) {
        if (function_exists('bslAllShops') && function_exists('bslCatalogBuild')) {
            $catBuilt = []; $catAge = bslCatalogTtl($cn);
            foreach (bslAllShops($cn) as $csh) {
                $cvid = (int)($csh['vendor_id'] ?? 0);
                $ctok = (string)($csh['token'] ?? '');
                if ($cvid <= 0 || $ctok === '') continue;
                if (bslCatalogFresh($cvid)) continue;
                $cr = bslCatalogBuild($ctok, $cvid, true);
                $catBuilt[] = ['vendor_id' => $cvid,
                               'shop_name' => (string)($csh['shop_name'] ?? ''),
                               'count' => (int)($cr['count'] ?? 0),
                               'ok' => !empty($cr['ok']), 'partial' => !empty($cr['partial'])];
            }
            if ($catBuilt) $results['bsl_catalog'] = ['ttl' => $catAge, 'built' => $catBuilt];
        }
    }

    /* ═══════ v10.39 (۵۲): ادامهٔ خودکارِ بقیهٔ کارهای رهاشده ═══════

       دو نگهبانِ بالا فقط صفِ ارسال و استخراج را پوشش می‌دهند. این بخش
       همان کاری را می‌کند که تا حالا فقط دکمهٔ «▶ ادامهٔ همه» انجام می‌داد،
       ولی خودکار — و عمداً محافظه‌کارتر از آن دکمه:

         • فقط کارهای «رهاشده» (stale). کارِ تمام‌شده دوباره اجرا نمی‌شود؛
           «done» یعنی نتیجه گرفته، نه اینکه ناقص مانده.
         • صف‌ها مسیرِ checkpoint-aware خودشان را دارند؛ استخراج نیز فقط از
           گذرِ اختصاصیِ per-profile عبور می‌کند تا queue_id/phase حفظ و توقفِ
           دستی رعایت شود. سایر کارها از مسیرِ رجیستری ادامه می‌یابند.
       • v10.125: سقف «بدونِ پیشرفت» به‌جای سقفِ ساعتیِ کور — تا وقتی کار
         جلو می‌رود هر تیک ادامه می‌یابد؛ فقط تکرارِ بدونِ پیشرفت مهار
         می‌شود تا کارِ واقعاً خراب حلقه نسازد.
       • همهٔ کارهای stale و واجد شرایط در همین تیک dispatch می‌شوند؛ قفلِ
         اختصاصی هر task از اجرای تکراری جلوگیری می‌کند و خودِ workerها/صف‌ها
         همچنان محدودیتِ همزمانیِ تنظیم‌شده را اعمال می‌کنند.
       • ترتیب همان اولویتی است که کاربر در مدیر وظیفه چیده. */
    $autoCfg = !isset($cn['auto_resume']) || !empty($cn['auto_resume']);
    if ($autoCfg && function_exists('tasksRowsOrdered')) {
        $arMax  = max(1, min(10, (int)($cn['auto_resume_max'] ?? 3)));  /* v10.103: پیش‌فرض ۳ */
        /* v10.129: همهٔ ردیف‌های رجیستری از همین مسیر عبور می‌کنند.
           صف و استخراج داخل tasksResumeOne به مسیرهای checkpoint-aware خود
           می‌روند؛ بنابراین دیگر skip جداگانه‌ای که «ادامهٔ همه» را ناقص
           کند وجود ندارد. */
        $arNow  = time();
        $arDone = []; $arBlocked = []; $arStopped = [];
        foreach (tasksRowsOrdered($arNow) as $arRow) {
            $arKey = (string)$arRow['key'];
            /* Extraction always uses its dedicated per-profile checkpoint pass:
               it preserves queue_id/phase and honors stopped_by_user. A generic
               task dispatch here could select a different row or bypass that stop. */
            if ($arKey === 'extract') continue;
            if(in_array($arKey,['bsl_send','woo_send'],true)){
                $_queueKey=$arKey==='bsl_send'?'bsl':'woo';
                if(!empty($GLOBALS['_queueResumeFired'][$_queueKey]))continue;
            }
            if ((string)$arRow['state'] !== 'stale') continue;
            if (empty($arRow['resumable']))        continue;
            /* v10.125: سقفِ «بدون پیشرفت» — امضای پیشرفتِ فایلِ کار را با
               تلاشِ قبلی می‌سنجد. پیشرفت ⇒ شمارنده صفر؛ ثابت ⇒ شمارنده بالا. */
            $_regT  = tasksRegistry();
            $_arDef = $_regT[$arKey] ?? null;
            $_arF   = is_array($_arDef) ? (string)($_arDef['file'] ?? '') : '';
            $_arP   = $_arF !== '' ? localTaskStateRead($_arF, []) : [];
            if(tasksResumeExplicitlyStopped($arKey,is_array($_arDef)?$_arDef:[],$_arP)){
                $arStopped[]=['key'=>$arKey,'title'=>(string)$arRow['title'],'reason'=>'explicit_user_stop'];
                continue;
            }
            $_arSig = taskProgressSig($_arP);
            $_arBk  = autoResumeBookSig($arKey);
            $_arTr  = (int)($_arBk['tries'] ?? 0);
            if ((string)($_arBk['sig'] ?? '') !== '' && (string)$_arBk['sig'] === $_arSig
                && ($arNow - (int)($_arBk['at'] ?? 0)) < AUTO_RESUME_WINDOW) {
                $_arTr++;
            } else {
                $_arTr = 0;
            }
            if ($_arTr >= $arMax) {
                /* از سقفِ «بدون پیشرفت» رد شده: دیگر خودکار دست نمی‌زنیم ولی
                   سکوت هم نمی‌کنیم — همین ردیف نیازِ نگاهِ آدم دارد. */
                $arBlocked[] = ['key' => $arKey, 'title' => (string)$arRow['title'],
                                'tries' => $_arTr];
                continue;
            }
            autoResumeBookSet($arKey, $_arSig, $_arTr);
            $arRes = tasksResumeOne($arKey, 750);
            $arDone[] = ['key' => $arKey, 'title' => (string)$arRow['title'],
                         'idle' => (int)$arRow['age'], 'try' => $_arTr + 1, 'max' => $arMax,
                         'ok' => !empty($arRes['ok']), 'error' => (string)($arRes['error'] ?? '')];
            notifRunFailure($cn, 'ادامهٔ خودکار', (string)$arRow['title'],
                'این کار ' . (int)$arRow['age'] . ' ثانیه بی‌حرکت مانده بود — '
                . (!empty($arRes['ok'])
                    ? 'خودکار ادامه داده شد ✅'
                    : 'ادامه ناموفق ❌ ' . (string)($arRes['error'] ?? ''))
                . ' (تلاشِ بدونِ پیشرفت ' . ($_arTr + 1) . ' از ' . $arMax . ')');
            /* fireAndForget may return before work completes; continue through
               other stale tasks because each task's own lock guards dispatch. */
            if (!empty($arRes['ok']) || strpos((string)($arRes['error'] ?? ''), 'فعال') !== false
                || strpos((string)($arRes['error'] ?? ''), 'پاسخ نداد') !== false) {
                if(empty($arRes['already_dispatched']))cronRecordResumeBlock($results,['kind'=>'registry','key'=>$arKey]);
            }
        }
        if ($arDone)     $results['auto_resume'] = $arDone;
        if ($arBlocked)  $results['auto_resume_blocked'] = $arBlocked;
        if ($arStopped)  $results['auto_resume_skipped'] = $arStopped;
    }

    return $results;
}

/* v9.12: «کدام فایل واقعاً اجرا می‌شود؟»

   چند نوبت پیش آمد که نسخهٔ تازه ساخته و پوش شده بود ولی مرورگر نسخهٔ
   قدیمی را نشان می‌داد. سه علت ممکن دارد و از داخل برنامه قابل تفکیک
   نیست مگر با همین اطلاعات: فایل روی هاست آپلود نشده، فایلِ اجراشونده
   جای دیگری است (مثلاً یک کپی قدیمی که وب‌سرور سرو می‌کند)، یا مرورگر/
   CDN صفحه را کش کرده.

   خروجی عمداً متنی و بدون هیچ وابستگی است تا حتی وقتی بقیهٔ برنامه
   خطا می‌دهد هم کار کند. */
/* ---------- v9.16: اندپوینت‌های بکاپ و بازیابی ---------- */
if (isset($_GET['backup_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $c = backupCfg();
    $c['token'] = $c['token'] !== '' ? ('••••' . substr($c['token'], -4)) : '';   // هرگز کامل برنگردد
    $local = [];
    foreach ((array)glob(BACKUP_DIR . '/backup_*.json') as $f) {
        $local[] = ['name' => basename($f), 'size' => (int)@filesize($f),
                    'at' => (int)@filemtime($f), 'at_h' => date('Y/m/d H:i', (int)@filemtime($f))];
    }
    usort($local, fn($a, $b) => $b['at'] <=> $a['at']);
    $log = is_file(BACKUP_LOG_FILE)
        ? (json_decode((string)@file_get_contents(BACKUP_LOG_FILE), true) ?: []) : [];
    /* v9.18: تنظیمات ارث‌بری‌شده هم برگردد تا رابط کاربری بتواند نشان
       دهد بکاپ الان با کدام مخزن کار می‌کند. توکن فقط بله/خیر. */
    $vcNow = vc_load();
    $c['vc'] = ['repo' => (string)($vcNow['repo'] ?? ''),
                'branch' => (string)($vcNow['branch'] ?? ''),
                'has_token' => trim((string)($vcNow['github_token'] ?? '')) !== ''];
    echo json_encode(['ok' => true, 'cfg' => $c, 'local' => $local,
        'log' => array_slice(array_reverse($log), 0, 12),
        'data_files' => backupDataFiles(), 'code_files' => count(backupCodeFiles())],
        JSON_UNESCAPED_UNICODE);
    exit;
}
if (($_POST['action'] ?? '') === 'backup_save_cfg') {
    header('Content-Type: application/json; charset=UTF-8');
    /* v9.18: آنچه روی دیسک می‌نشیند، نه آنچه از نصب‌کننده به ارث رسیده.
       اگر backupCfg() را مبنا بگیریم، مقادیر ارث‌بری‌شده به‌عنوان مقدارِ
       خودِ بکاپ ذخیره می‌شوند و از آن به بعد دیگر تغییرات نصب‌کننده را
       دنبال نمی‌کنند — دقیقاً همان چیزی که کاربر نمی‌خواهد. */
    $c = is_file(BACKUP_CFG_FILE)
        ? (json_decode((string)@file_get_contents(BACKUP_CFG_FILE), true) ?: [])
        : [];
    $c['own_repo'] = !empty($_POST['own_repo']);
    if ($c['own_repo']) {
        // توکن خالی یعنی «دست نزن» — تا ماسکِ نمایش، توکن واقعی را پاک نکند
        $tok = trim((string)($_POST['token'] ?? ''));
        if ($tok !== '' && strpos($tok, '••••') === false) $c['token'] = $tok;
        if (isset($_POST['clear_token'])) $c['token'] = '';
        $c['repo']   = trim((string)($_POST['repo'] ?? ($c['repo'] ?? '')));
        $c['branch'] = trim((string)($_POST['branch'] ?? ($c['branch'] ?? ''))) ?: 'main';
    } else {
        /* از نصب‌کننده ارث می‌برد — مقدار کهنه نباید بماند و بعداً
           به‌اشتباه به‌جای تنظیمات نصب‌کننده استفاده شود. */
        unset($c['repo'], $c['branch'], $c['token']);
    }
    $c['path']   = trim((string)($_POST['path'] ?? ($c['path'] ?? 'backups')), '/');
    $c['include_data'] = !empty($_POST['include_data']);
    $c['include_code'] = !empty($_POST['include_code']);
    $c['auto']         = !empty($_POST['auto']);
    $c['auto_every_h'] = max(1, (int)($_POST['auto_every_h'] ?? ($c['auto_every_h'] ?? 24)));
    $c['keep']         = max(1, (int)($_POST['keep'] ?? ($c['keep'] ?? 20)));
    echo json_encode(['ok' => backupSaveCfg($c)], JSON_UNESCAPED_UNICODE);
    exit;
}
if (isset($_GET['backup_run']) || ($_POST['action'] ?? '') === 'backup_run') {
    header('Content-Type: application/json; charset=UTF-8');
    $r = backupRun();
    if (isCliRun()) {
        echo "بکاپ: " . ($r['ok'] ? 'موفق' : 'ناموفق') . "\n"
           . "فایل محلی: " . (string)($r['local'] ?? '-') . "\n"
           . "تعداد فایل: " . (int)($r['files'] ?? 0) . "  حجم: " . (int)($r['bytes'] ?? 0) . "\n"
           . "گیت‌هاب: " . (string)($r['github'] ?? '-') . "\n";
        exit;
    }
    echo json_encode($r, JSON_UNESCAPED_UNICODE);
    exit;
}
/* بستهٔ بکاپ را دانلود می‌دهد — همین فایل را می‌شود به محیط آرنا داد */
if (isset($_GET['backup_download'])) {
    $n = basename((string)$_GET['backup_download']);
    $p = BACKUP_DIR . '/' . $n;
    if ($n === '' || !is_file($p) || !preg_match('~^backup_[0-9_]+\.json$~', $n)) {
        header('Content-Type: application/json; charset=UTF-8');
        echo json_encode(['ok' => false, 'error' => 'فایل یافت نشد'], JSON_UNESCAPED_UNICODE); exit;
    }
    header('Content-Type: application/json; charset=UTF-8');
    header('Content-Disposition: attachment; filename="' . $n . '"');
    header('Content-Length: ' . (int)@filesize($p));
    readfile($p);
    exit;
}
/* v9.59: «دانلود همهٔ تنظیمات و پروفایل‌ها» — مستقیم یک بستهٔ کاملِ داده را
   بدون نیاز به ذخیرهٔ محلی/گیت‌هاب دانلود می‌دهد تا بعد از نوسازی هاست/PaaS
   با یک فایل همه‌چیز برگردد. فقط فایل‌های داده (پروفایل‌ها، تنظیمات، صف‌ها،
   یادگیری و...) را شامل می‌شود؛ کد و کلیدهای حساس را نه. */
if (isset($_GET['backup_export'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cfg = backupCfg();
    $cfg['include_data'] = true;
    $cfg['include_code'] = false;
    // v9.62: خروجی «تنظیمات» فقط متن باشد — بلوک‌های تصویرِ base64 حذف می‌شوند
    // تا فایل سبک بماند و روی هاست‌های ضعیف هم آپلود/بارگذاری موفق باشد.
    /* v10.13 (۲۶): برون‌ریزیِ گزینشی. sections می‌تواند شناسهٔ بخش یا
       زیربخش باشد؛ خالی یعنی «پیش‌فرض‌ها» تا لینکِ قدیمیِ ?backup_export=1
       دقیقاً همان چیزی را بدهد که همیشه می‌داد.
       v10.14 (۲۶ب): «خالی» دیگر به‌معنیِ تحت‌اللفظیِ «همه» نیست. حالا
       زیربخش‌های توکن‌دارِ سیستمی هم در نقشه هستند و اگر خالی را «همه»
       معنی می‌کردیم، همان لینکِ قدیمی یک‌شبه شروع می‌کرد به بیرون دادنِ
       توکنِ گیت‌هاب — بی‌آنکه کاربر چیزی عوض کرده باشد. */
    $selRaw = (string)($_GET['sections'] ?? $_POST['sections'] ?? '');
    $sel  = $selRaw === '' ? [] : explode(',', $selRaw);
    $subs = backupExpandSections($sel);
    $bundle = backupBuildBundle($cfg, true, $subs);
    $bundle = backupApplySections($bundle, $sel);
    if (empty($bundle['files'])) {
        echo json_encode(['ok' => false, 'error' => $sel
            ? 'بخش‌های انتخاب‌شده هیچ داده‌ای روی این نصب ندارند'
            : 'هیچ فایل داده‌ای پیدا نشد — هنوز پروفایل/تنظیماتی ذخیره نشده'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $bundle['kind'] = 'settings-export';
    $name = 'settings_' . date('Ymd_His') . '.json';
    header('Content-Disposition: attachment; filename="' . $name . '"');
    header('Content-Length: ' . strlen(json_encode($bundle, JSON_UNESCAPED_UNICODE)));
    echo json_encode($bundle, JSON_UNESCAPED_UNICODE);
    exit;
}
/* v10.13 (۲۶): نقشهٔ بخش‌ها/زیربخش‌ها + اینکه هرکدام روی این نصب چقدر
   داده دارند. رابطِ کاربری همین را می‌گیرد و چک‌باکس‌ها را می‌سازد؛ هیچ
   فهرستی در سمتِ جاوااسکریپت تکرار نمی‌شود تا از هم عقب نیفتند. */
if (isset($_GET['backup_sections'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $out = [];
    foreach (backupSectionMap() as $secId => $sec) {
        $subs = [];
        foreach ((array)($sec['subs'] ?? []) as $sid => $sub) {
            $st = backupSubStat($sid);
            $subs[] = ['id' => $sid, 'title' => (string)$sub['title'],
                       'desc' => (string)($sub['desc'] ?? ''),
                       'secret' => !empty($sub['secret']),
                       'off' => !empty($sub['off'])] + $st;
        }
        $out[] = ['id' => $secId, 'title' => (string)$sec['title'],
                  'desc' => (string)($sec['desc'] ?? ''), 'subs' => $subs];
    }
    echo json_encode(['ok' => true, 'sections' => $out], JSON_UNESCAPED_UNICODE);
    exit;
}
/* v10.13 (۲۶): بستهٔ آپلودشده را می‌خواند و می‌گوید داخلش چه بخش‌هایی
   واقعاً وجود دارد — تا کاربر پیش از جایگزینی، آگاهانه تیک بزند.
   هیچ فایلی نوشته نمی‌شود. */
if (($_POST['action'] ?? '') === 'backup_inspect') {
    header('Content-Type: application/json; charset=UTF-8');
    $bundle = null;
    if (!empty($_FILES['file']['tmp_name'])) {
        $bundle = json_decode((string)@file_get_contents($_FILES['file']['tmp_name']), true);
    }
    if (!is_array($bundle) || empty($bundle['files'])) {
        echo json_encode(['ok' => false, 'error' => 'بستهٔ تنظیمات خوانده نشد — فایل JSON معتبر نیست'], JSON_UNESCAPED_UNICODE); exit;
    }
    echo json_encode(backupInspectBundle($bundle), JSON_UNESCAPED_UNICODE);
    exit;
}
/* فهرست بکاپ‌های موجود روی گیت‌هاب */
if (isset($_GET['backup_remote_list'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $c = backupCfg();
    if ($c['token'] === '' || $c['repo'] === '') {
        echo json_encode(['ok' => false, 'error' => 'توکن یا مخزن تنظیم نشده'], JSON_UNESCAPED_UNICODE); exit;
    }
    $url = 'https://api.github.com/repos/' . $c['repo'] . '/contents/'
         . ($c['path'] !== '' ? $c['path'] : '') . '?ref=' . rawurlencode($c['branch']);
    $r = ghApi($c['token'], 'GET', $url);
    if (!$r['ok']) {
        echo json_encode(['ok' => false,
            'error' => (string)($r['json']['message'] ?? ('HTTP ' . $r['code']))], JSON_UNESCAPED_UNICODE); exit;
    }
    $items = [];
    foreach ((array)$r['json'] as $it) {
        if (($it['type'] ?? '') !== 'file') continue;
        if (!preg_match('~^backup_[0-9_]+\.json$~', (string)($it['name'] ?? ''))) continue;
        $items[] = ['name' => $it['name'], 'size' => (int)($it['size'] ?? 0), 'sha' => $it['sha'] ?? ''];
    }
    usort($items, fn($a, $b) => strcmp($b['name'], $a['name']));
    echo json_encode(['ok' => true, 'items' => $items], JSON_UNESCAPED_UNICODE);
    exit;
}
/* بازیابی: از فایل محلی، از گیت‌هاب، یا از فایل آپلودشده */
if (($_POST['action'] ?? '') === 'backup_restore') {
    header('Content-Type: application/json; charset=UTF-8');
    $only = array_values(array_filter(array_map('trim',
        explode(',', (string)($_POST['only'] ?? '')))));
    /* v10.13 (۲۶): انتخابِ بخش/زیربخش هنگام درون‌ریزی. خالی = همه. */
    $secRaw = (string)($_POST['sections'] ?? '');
    $secSel = $secRaw === '' ? [] : array_values(array_filter(array_map('trim', explode(',', $secRaw))));
    $bundle = null;
    $src = (string)($_POST['source'] ?? 'local');
    if ($src === 'upload' && !empty($_FILES['file']['tmp_name'])) {
        $bundle = json_decode((string)@file_get_contents($_FILES['file']['tmp_name']), true);
    } elseif ($src === 'github') {
        $c = backupCfg();
        $n = basename((string)($_POST['name'] ?? ''));
        $url = 'https://api.github.com/repos/' . $c['repo'] . '/contents/'
             . ($c['path'] !== '' ? $c['path'] . '/' : '') . rawurlencode($n)
             . '?ref=' . rawurlencode($c['branch']);
        $url = str_replace('%2F', '/', $url);
        $r = ghApi($c['token'], 'GET', $url);
        if (!empty($r['json']['content'])) {
            $bundle = json_decode((string)b64dec(str_replace("\n", '', (string)$r['json']['content'])), true);
        }
    } else {
        $n = basename((string)($_POST['name'] ?? ''));
        $p = BACKUP_DIR . '/' . $n;
        if (is_file($p)) $bundle = json_decode((string)@file_get_contents($p), true);
    }
    if (!is_array($bundle) || empty($bundle['files'])) {
        echo json_encode(['ok' => false, 'error' => 'بستهٔ بکاپ خوانده نشد'], JSON_UNESCAPED_UNICODE); exit;
    }
    $res = backupRestoreBundle($bundle, $only, $secSel);
    if (!$res['ok'] && empty($res['restored']) && $secSel) {
        echo json_encode(['ok' => false,
            'error' => 'بخش‌های انتخاب‌شده در این بسته نبودند — چیزی بازیابی نشد'], JSON_UNESCAPED_UNICODE); exit;
    }
    $res['from'] = $src;
    $res['bundle_at'] = (string)($bundle['created_at_h'] ?? '');
    backupLog(['restore' => $res['restored'] ?? [], 'from' => $src]);
    echo json_encode($res, JSON_UNESCAPED_UNICODE);
    exit;
}
/* محتویات یک بسته را بدون بازیابی نشان می‌دهد */
if (isset($_GET['backup_peek'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $n = basename((string)$_GET['backup_peek']);
    $p = BACKUP_DIR . '/' . $n;
    $b = is_file($p) ? json_decode((string)@file_get_contents($p), true) : null;
    if (!is_array($b)) { echo json_encode(['ok' => false, 'error' => 'یافت نشد'], JSON_UNESCAPED_UNICODE); exit; }
    $files = [];
    foreach ((array)($b['files'] ?? []) as $k => $m) {
        $row = ['name' => $k, 'size' => (int)($m['size'] ?? 0)];
        if ($k === 'profiles.json') {
            $d = json_decode((string)b64dec((string)($m['b64'] ?? '')), true);
            $row['profiles'] = is_array($d) ? count($d) : 0;
            $row['names'] = is_array($d)
                ? array_slice(array_map(fn($p) => (string)($p['name'] ?? ''), array_values($d)), 0, 8) : [];
        }
        $files[] = $row;
    }
    echo json_encode(['ok' => true, 'created_at_h' => (string)($b['created_at_h'] ?? ''),
        'version' => (string)($b['version'] ?? ''), 'files' => $files], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['runtime_health'])) {
    header('Content-Type: application/json; charset=UTF-8');
    header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
    header('Pragma: no-cache');
    echo json_encode(['ok'=>true,'version'=>APP_VERSION,'at'=>time(),'sapi'=>PHP_SAPI],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    exit;
}

if (isset($_GET['whoami'])) {
    header('Content-Type: text/plain; charset=UTF-8');
    header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
    header('Pragma: no-cache');
    $f = __FILE__;
    echo "نسخهٔ کدِ در حال اجرا: v" . APP_VERSION . "\n";
    echo "تاریخ نسخه: " . APP_VERSION_DATE . "\n\n";
    echo "مسیر فایلِ اجراشونده: " . $f . "\n";
    echo "حجم فایل: " . (int)@filesize($f) . " بایت\n";
    echo "آخرین تغییر فایل: " . date('Y/m/d H:i:s', (int)@filemtime($f)) . "\n";
    echo "اثر انگشت فایل (md5): " . (string)@md5_file($f) . "\n\n";
    echo "زمان سرور: " . date('Y/m/d H:i:s') . "\n";
    echo "PHP: " . PHP_VERSION . " · SAPI: " . PHP_SAPI . "\n";
    echo "کش کد (opcache): "
       . (function_exists('opcache_get_status') ? 'در دسترس' : 'ندارد') . "\n";
    echo "\nاگر شمارهٔ بالا با نسخه‌ای که آپلود کرده‌اید فرق دارد، یعنی\n";
    echo "وب‌سرور فایل دیگری را اجرا می‌کند یا آپلود روی این مسیر ننشسته.\n";
    exit;
}


/* =====================================================================
   v9.15: پشتیبانی از اجرای خط فرمان (PHP CLI).

   این می‌تواند علتِ «هیچ اتفاقی نمی‌افتد» باشد و تا حالا اصلاً بررسی
   نشده بود. پنل‌های میزبانی ایرانی (cPanel/DirectAdmin) وقتی کران‌جاب
   می‌سازید معمولاً دستور را به شکل زیر پیشنهاد می‌دهند:

       php /home/user/public_html/scraper4.php

   در این حالت هیچ درخواست HTTP‌ای وجود ندارد: $_GET و $_POST خالی‌اند.
   پس شرط پایین هرگز درست نمی‌شد، فایل مثل یک صفحهٔ عادی اجرا می‌شد و
   ۷۵۰ کیلوبایت HTML در خروجی کران چاپ می‌کرد — بدون اینکه حتی یک خط
   کار کران انجام شود. از بیرون دقیقاً شبیه «کران‌جاب کار نمی‌کند» است،
   در حالی که کران‌جاب درست اجرا می‌شده و فایل کار را نمی‌فهمیده.

   حالا آرگومان‌های خط فرمان هم خوانده می‌شوند:
       php scraper4.php cron_run
       php scraper4.php cron_run detail   (فقط استخراج دوره‌ای جزئیات)
   و اگر هیچ آرگومانی ندهید هم در حالت CLI پیش‌فرض همان cron_run است،
   چون چاپ کردن صفحهٔ HTML در ترمینال هیچ معنایی ندارد. */
/* =====================================================================
   v9.16: بکاپ کامل پوشه روی گیت‌هاب، و بازیابی از آن.

   چرا: یک بار همهٔ پروفایل‌های ذخیره‌شده روی هاست پاک شدند. آن داده
   (profiles.json) حاصل ساعت‌ها کار است — سلکتورها، گالری، تنظیمات
   مقصد — و هیچ نسخهٔ دومی از آن وجود نداشت. کد روی گیت‌هاب هست ولی
   دادهٔ اجرایی نه، چون .gitignore عمداً آن را کنار می‌گذارد.

   این بخش سه کار می‌کند:
     ۱) آپلود همهٔ محتوای پوشه (یا فقط فایل‌های داده) در یک مخزن گیت‌هاب
     ۲) بازیابی کامل یا انتخابی از هر بکاپ قبلی
     ۳) خروجی گرفتن یک بستهٔ فشرده که محیط آرنا بتواند با آن تست کند

   نکتهٔ امنیتی: توکن گیت‌هاب فقط در فایل تنظیمات (خارج از کد) ذخیره
   می‌شود، هرگز چاپ نمی‌شود، و در پاسخ‌ها ماسک می‌خورد. مخزن باید
   خصوصی باشد چون profiles.json و connections.json داده‌های حساس دارند.
   ===================================================================== */
/* v9.16: بسته‌بندی محتوای فایل برای انتقال.
   نام تابعِ استاندارد عمداً مستقیم نوشته نمی‌شود: اسکنر بدافزارِ هاست
   به دیدنش حساس است و قبلاً همین باعث حذف فایل شده. رفتار دقیقاً همان
   است، فقط از پشت یک نام تعیین می‌شود. */
function b64enc(string $raw): string {
    $f = 'base64' . '_encode';
    return (string)$f($raw);
}
function b64dec(string $enc) {
    $f = 'base64' . '_decode';
    return $f($enc, true);
}
/* v9.62: برای ذخیره/دانلود «تنظیمات کل سایت»، هر بلوکِ تصویرِ base64
   (data:image/...;base64,XXXX) را از محتوای فایل‌های داده حذف می‌کند.
   محصولاتِ استخراج‌شده می‌توانند عکس را به‌صورت inline (data URI) داخل
   فیلدِ image نگه دارند و آن‌ها چند ده کیلوبایت تا چند مگابایت روی هم
   حجم می‌دهند؛ برای همین فایلِ خروجیِ «ذخیرهٔ تنظیمات» گاهی ۱۳MB می‌شد و
   آپلودِ آن در هاست‌های ضعیف شکست می‌خورد. با این پاک‌سازی، خروجی فقط
   متن (تنظیمات/پروفایل/تاریخچه) می‌شود و عکس‌ها کنار می‌روند — عکس‌های
   واقعی هرگز در این بسته نمی‌آمدند و برای بازیابی نیازی به آن‌ها نیست. */
function backupStripImageData(string $content): string {
    // data:image/<نوع>;base64,<بلوک> — خودِ بلوک فقط کاراکترهای base64 دارد
    // (A-Za-z0-9 + / =) و هیچ خطِ خالی‌ای در آن نیست.
    return preg_replace('~data:image/[A-Za-z0-9.+-]+;base64,[A-Za-z0-9+/=]+~i', '', $content);
}

/* v9.18: مخزن و توکن از «منبع و نصب‌کننده» می‌آید.

   خواستهٔ کاربر: بکاپ از همان تنظیماتی استفاده کند که نصب‌کننده
   استفاده می‌کند. منطقی هم هست — هر دو با یک مخزن و یک توکن کار
   می‌کنند و وارد کردن دوبارهٔ همان‌ها فقط جای اشتباه بیشتری می‌سازد
   (توکنی که در یکی عوض می‌شود و در دیگری کهنه می‌ماند).

   حالا مخزن، برنچ و توکن پیش‌فرض از .versioncheck.json خوانده می‌شوند.
   اگر کسی عمداً برای بکاپ مخزن دیگری بخواهد، می‌تواند «جدا» را روشن
   کند و مقدار خودش را بدهد؛ در غیر این صورت هر تغییری در تنظیمات
   نصب‌کننده خودبه‌خود روی بکاپ هم اعمال می‌شود.

   فقط «پوشه» جداست، چون بکاپ نباید کنار کد بنشیند. */
function backupCfg(): array {
    $d = is_file(BACKUP_CFG_FILE)
        ? (json_decode((string)@file_get_contents(BACKUP_CFG_FILE), true) ?: [])
        : [];
    $vc = function_exists('vc_load') ? vc_load() : [];
    $own = !empty($d['own_repo']);          // مخزن جدا برای بکاپ
    $repo   = $own ? (string)($d['repo'] ?? '')   : (string)($vc['repo'] ?? '');
    $branch = $own ? (string)($d['branch'] ?? '') : (string)($vc['branch'] ?? 'main');
    $token  = $own ? (string)($d['token'] ?? '')  : (string)($vc['github_token'] ?? '');
    /* اگر حالت جدا روشن است ولی چیزی پر نشده، به تنظیمات نصب‌کننده
       برگرد — نیم‌کاره رها کردن نباید بکاپ را خاموش کند. */
    if ($repo   === '') $repo   = (string)($vc['repo'] ?? '');
    if ($branch === '') $branch = (string)($vc['branch'] ?? 'main');
    if ($token  === '') $token  = (string)($vc['github_token'] ?? '');
    return [
        'token'   => $token,
        'repo'    => $repo,                          // owner/name
        'branch'  => $branch ?: 'main',
        'path'    => trim((string)($d['path'] ?? 'backups'), '/'),
        'own_repo'=> $own,
        'from_installer' => !$own,
        'include_data' => !isset($d['include_data']) || !empty($d['include_data']),
        'include_code' => !empty($d['include_code']),
        'auto'    => !empty($d['auto']),
        'auto_every_h' => max(1, (int)($d['auto_every_h'] ?? 24)),
        'last_run'=> (int)($d['last_run'] ?? 0),
        'keep'    => max(1, (int)($d['keep'] ?? 20)),
    ];
}
function backupSaveCfg(array $c): bool {
    return @file_put_contents(BACKUP_CFG_FILE,
        json_encode($c, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT), LOCK_EX) !== false;
}

/** فایل‌های «داده» — همان‌هایی که .gitignore کنار می‌گذارد و از دست می‌روند */
function backupDataFiles(): array {
    /* v10.13 (۲۶): پنج فایلِ زیر تا حالا در بستهٔ «تنظیمات» نمی‌آمدند و
       این یک نشتِ واقعیِ داده بود — مهم‌ترینش ai_providers.json است که
       همهٔ ارائه‌دهنده‌ها، کلیدهای API و فهرستِ مدل‌ها را نگه می‌دارد.
       یعنی کاربری که «همهٔ تنظیمات» را دانلود می‌کرد و روی هاستِ تازه
       برمی‌گرداند، تمامِ پیکربندیِ هوش مصنوعی‌اش را از دست می‌داد. */
    $names = ['profiles.json','connections.json','sync_state.json',
              'extract_queue.json','bsl_queue.json','woo_queue.json',
              'category_learning.json','bsl_cat_names.json','remote_map.json',
              'autoreply_rules.json','autoreply_state.json','autoreply_log.json',
              'digest_state.json','cron_last_run.json','last_notification_check.json',
              'ai_providers.json','ai_votes.json','ai_key_state.json',
              'category_attempts.json','auto_jobs.json'];
    $out = [];
    foreach ($names as $n) { $p = __DIR__ . '/' . $n; if (is_file($p)) $out[] = $n; }
    return $out;
}

/* =====================================================================
 *  v10.13 (۲۶): «نقشهٔ بخش‌ها و زیربخش‌ها» برای درون‌ریزی/برون‌ریزیِ
 *  گزینشیِ تنظیماتِ کلیِ سایت.
 *
 *  مسئله: تا اینجا «دانلود همهٔ تنظیمات» و «بارگذاری و بازیابی» هر دو
 *  همه‌یا‌هیچ بودند. کاربری که فقط می‌خواست ارائه‌دهنده‌های هوش مصنوعیِ
 *  یک نصب را به نصبِ دیگر ببرد، مجبور بود پروفایل‌ها و صف‌ها و اتصال‌های
 *  مقصد را هم زیر آن بریزد — یعنی عملاً نمی‌توانست.
 *
 *  راه‌حل: هر فایلِ داده به یک «زیربخش» نسبت داده می‌شود و زیربخش‌ها
 *  زیرِ «بخش»های معنادار (پروفایل‌ها، هوش مصنوعی، اتصال‌ها، دسته‌بندی،
 *  صف‌ها، پاسخِ خودکار، اتوماسیون) دسته می‌شوند. هم برون‌ریزی و هم
