/**
 * v10.14: زیربخش‌هایی که پیش‌فرض روشن‌اند — یعنی همان چیزی که تا نسخهٔ
 * قبل در بستهٔ «همهٔ تنظیمات» می‌آمد. زیربخش‌های نشان‌دارِ off (توکن‌دار
 * یا صرفاً تاریخچه) باید آگاهانه تیک بخورند.
 */
function backupDefaultSubIds(): array {
    $out = [];
    foreach (backupSectionMap() as $sec) {
        foreach ((array)($sec['subs'] ?? []) as $sid => $sub) {
            if (empty($sub['off'])) $out[] = $sid;
        }
    }
    return $out;
}

/** فهرستِ شناسهٔ همهٔ زیربخش‌ها، به ترتیبِ نقشه */
function backupAllSubIds(): array {
    $out = [];
    foreach (backupSectionMap() as $sec) {
        foreach ((array)($sec['subs'] ?? []) as $sid => $_) $out[] = $sid;
    }
    return $out;
}

/**
 * ورودیِ کاربر می‌تواند شناسهٔ «بخش» یا «زیربخش» باشد؛ خروجی همیشه
 * فهرستِ زیربخش‌هاست. فهرستِ خالی یعنی «همه» — تا رفتارِ نسخه‌های قبل
 * (که اصلاً پارامتری نمی‌فرستادند) عیناً حفظ شود.
 */
function backupExpandSections(array $sel): array {
    $sel = array_values(array_filter(array_map('trim', $sel), fn($v) => $v !== ''));
    /* v10.14: خالی ⇒ پیش‌فرض‌ها (نه تحت‌اللفظیِ «همه»). زیربخش‌های
       نشان‌دارِ off توکن دارند و نباید بدونِ تیکِ صریح راه بیفتند. */
    if (!$sel) return backupDefaultSubIds();
    $map = backupSectionMap();
    $out = [];
    foreach ($sel as $id) {
        if (isset($map[$id])) {
            foreach ((array)($map[$id]['subs'] ?? []) as $sid => $_) $out[] = $sid;
            continue;
        }
        foreach ($map as $sec) {
            if (isset($sec['subs'][$id])) { $out[] = $id; break; }
        }
    }
    return array_values(array_unique($out));
}

/** تعریفِ یک زیربخش را برمی‌گرداند (یا null) */
function backupSubDef(string $subId): ?array {
    foreach (backupSectionMap() as $sec) {
        if (isset($sec['subs'][$subId])) return $sec['subs'][$subId];
    }
    return null;
}

/** فایل‌هایی که این مجموعه زیربخش لمس می‌کنند */
function backupSubsFiles(array $subs): array {
    $out = [];
    foreach ($subs as $sid) {
        $d = backupSubDef($sid);
        if (!$d) continue;
        if (!empty($d['file']))  $out[] = (string)$d['file'];
        foreach ((array)($d['files'] ?? []) as $f) $out[] = (string)$f;
    }
    return array_values(array_unique($out));
}

/**
 * برشِ profiles.json: هر پروفایل یک نگاشت است و کلیدهای products/
 * productsOrder را یا نگه می‌داریم یا دور می‌ریزیم.
 * $mode = 'only' (فقط همان کلیدها) یا 'omit' (همه‌چیز جز آن‌ها).
 */
function backupSliceEntries($data, string $mode, array $keys) {
    if (!is_array($data)) return $data;
    $out = [];
    foreach ($data as $k => $entry) {
        if (!is_array($entry)) { if ($mode === 'omit') $out[$k] = $entry; continue; }
        $row = [];
        foreach ($entry as $ek => $ev) {
            $hit = in_array((string)$ek, $keys, true);
            if (($mode === 'only' && $hit) || ($mode === 'omit' && !$hit)) $row[$ek] = $ev;
        }
        /* در حالتِ only، رکوردی که همهٔ مقادیرِ برش‌خورده‌اش خالی است
           اصلاً وارد بسته نمی‌شود. اگر وارد می‌شد، بازیابی «محصولات» از
           بسته‌ای که پروفایلش هیچ محصولی نداشت، محصولاتِ مقصد را با
           آرایهٔ خالی پاک می‌کرد — یعنی دقیقاً برعکسِ خواستهٔ کاربر. */
        if ($mode === 'omit') { $out[$k] = $row; continue; }
        foreach ($row as $rv) { if ($rv !== [] && $rv !== null && $rv !== '') { $out[$k] = $row; break; } }
    }
    return $out;
}

/**
 * محتوای یک فایل را بر اساسِ زیربخش‌های انتخاب‌شده فیلتر می‌کند.
 * خروجیِ null یعنی «این فایل اصلاً انتخاب نشده».
 */
function backupFilterFileContent(string $file, string $content, array $subs) {
    $whole = false; $slices = [];
    foreach ($subs as $sid) {
        $d = backupSubDef($sid);
        if (!$d) continue;
        if (in_array($file, (array)($d['files'] ?? []), true)) { $whole = true; continue; }
        if ((string)($d['file'] ?? '') === $file) $slices[] = $d;
    }
    if ($whole) return $content;
    if (!$slices) return null;
    $data = json_decode($content, true);
    if (!is_array($data)) return $content;   // نمی‌شناسیمش ⇒ دست‌نخورده
    /* اگر هر دو برشِ یک فایل انتخاب شده‌اند، یعنی کلِ فایل */
    $modes = array_map(fn($d) => (string)($d['slice'] ?? ''), $slices);
    if (in_array('only', $modes, true) && in_array('omit', $modes, true)) return $content;
    $d = $slices[0];
    $sliced = backupSliceEntries($data, (string)($d['slice'] ?? 'omit'), (array)($d['keys'] ?? []));
    return (string)json_encode($sliced, JSON_UNESCAPED_UNICODE);
}

/**
 * بستهٔ ساخته‌شده را به بخش‌های انتخابی می‌برد: فایل‌های خارج از انتخاب
 * حذف و فایل‌های نیمه‌انتخاب‌شده برش داده می‌شوند.
 */
function backupApplySections(array $bundle, array $sel): array {
    $subs = backupExpandSections($sel);
    $all  = backupAllSubIds();
    $cmp  = $subs; sort($cmp); sort($all);
    /* v10.14: میان‌برِ «همه ⇒ دست نزن» فقط وقتی درست است که واقعاً همهٔ
       زیربخش‌ها تیک خورده باشند. با انتخابِ پیش‌فرض باید فیلتر اجرا شود،
       وگرنه فایلِ سیستمیِ تیک‌نخورده در بسته می‌ماند. */
    if ($cmp === $all) return $bundle;
    $files = []; $bytes = 0;
    foreach ((array)($bundle['files'] ?? []) as $name => $meta) {
        $raw = b64dec((string)($meta['b64'] ?? ''));
        if ($raw === false) continue;
        $f = backupFilterFileContent((string)$name, (string)$raw, $subs);
        if ($f === null) continue;
        $bytes += strlen($f);
        $files[$name] = ['size' => strlen($f), 'b64' => b64enc($f)];
    }
    $bundle['files'] = $files;
    $bundle['total_files'] = count($files);
    $bundle['total_bytes'] = $bytes;
    $bundle['sections'] = array_values($subs);
    return $bundle;
}

/**
 * v10.13 (۲۶): بستهٔ آمادهٔ درون‌ریزی را می‌کاود و می‌گوید داخلش چه
 * بخش‌هایی واقعاً هست — تا کاربر پیش از جایگزینی آگاهانه تیک بزند.
 * هیچ فایلی نوشته نمی‌شود.
 */
function backupInspectBundle(array $bundle): array {
    $have = [];
    foreach ((array)($bundle['files'] ?? []) as $n => $m) $have[basename((string)$n)] = (int)($m['size'] ?? 0);
    $out = [];
    foreach (backupSectionMap() as $secId => $sec) {
        $subs = [];
        foreach ((array)($sec['subs'] ?? []) as $sid => $sub) {
            $files = !empty($sub['file']) ? [(string)$sub['file']] : (array)($sub['files'] ?? []);
            $bytes = 0; $in = false; $count = 0;
            foreach ($files as $f) {
                if (!isset($have[$f])) continue;
                $in = true;
                $raw = (string)b64dec((string)($bundle['files'][$f]['b64'] ?? ''));
                if (!empty($sub['slice'])) {
                    $cut = backupFilterFileContent($f, $raw, [$sid]);
                    $raw = $cut === null ? '' : (string)$cut;
                }
                $bytes += strlen($raw);
                $j = json_decode($raw, true);
                if (is_array($j)) {
                    if ($sid === 'profiles_products') {
                        foreach ($j as $e) $count += is_array($e) ? count((array)($e['products'] ?? [])) : 0;
                    } else { $count += count($j); }
                }
            }
            /* برشِ خالی (بسته پروفایل دارد ولی هیچ محصولی داخلش نیست)
               نباید «موجود» شمرده شود، وگرنه کاربر تیک می‌زند و انتظارِ
               بازگشتِ چیزی را دارد که اصلاً در بسته نبوده. */
            if ($in && !empty($sub['slice']) && $count === 0) $in = false;
            $subs[] = ['id' => $sid, 'title' => (string)$sub['title'],
                       'desc' => (string)($sub['desc'] ?? ''),
                       'secret' => !empty($sub['secret']),
                       'off' => !empty($sub['off']),
                       'exists' => $in, 'bytes' => $bytes, 'count' => $count];
        }
        $out[] = ['id' => $secId, 'title' => (string)$sec['title'],
                  'desc' => (string)($sec['desc'] ?? ''), 'subs' => $subs];
    }
    return ['ok' => true, 'sections' => $out,
        'created_at_h' => (string)($bundle['created_at_h'] ?? ''),
        'version' => (string)($bundle['version'] ?? ''),
        'kind' => (string)($bundle['kind'] ?? ''),
        'total_files' => count($have)];
}

/** چند رکورد داخل هر فایلِ داده هست — برای نمایش کنارِ هر زیربخش */
function backupSubStat(string $subId): array {
    $d = backupSubDef($subId);
    if (!$d) return ['exists' => false, 'bytes' => 0, 'count' => 0];
    $files = !empty($d['file']) ? [(string)$d['file']] : (array)($d['files'] ?? []);
    $bytes = 0; $count = 0; $exists = false;
    foreach ($files as $f) {
        $p = __DIR__ . '/' . $f;
        if (!is_file($p)) continue;
        $exists = true;
        $raw = (string)@file_get_contents($p);
        if ($f === 'profiles.json' && !empty($d['slice'])) {
            $raw = (string)backupFilterFileContent($f, $raw, [$subId]);
        }
        $bytes += strlen($raw);
        $j = json_decode($raw, true);
        if (is_array($j)) {
            if ($subId === 'profiles_products') {
                foreach ($j as $e) $count += is_array($e) ? count((array)($e['products'] ?? [])) : 0;
            } else {
                $count += count($j);
            }
        }
    }
    return ['exists' => $exists, 'bytes' => $bytes, 'count' => $count];
}
/** فایل‌های کد و مستندات همین پوشه (بدون زیرپوشه‌های سنگین و بدون رازها) */
function backupCodeFiles(): array {
    $out = [];
    foreach ((array)@scandir(__DIR__) as $f) {
        if ($f === '.' || $f === '..') continue;
        $p = __DIR__ . '/' . $f;
        if (!is_file($p)) continue;
        if ($f[0] === '.') continue;                       // .backup-config.json و امثالش
        if (preg_match('~\.(log|lock)$~i', $f)) continue;
        if (in_array($f, backupDataFiles(), true)) continue;
        if (@filesize($p) > 8 * 1024 * 1024) continue;     // فایل غول‌پیکر نه
        $out[] = $f;
    }
    return $out;
}
/**
 * v10.14 (۲۶ب): «تنظیماتِ سیستمی» — سه فایلِ پیکربندیِ سطحِ نصب. اسمشان
 * با نقطه شروع می‌شود و backupCodeFiles() صراحتاً ردشان می‌کند
 * ($f[0] === '.')، پس تا این نسخه در هیچ مسیری بکاپ نمی‌شدند: نه
 * به‌عنوان داده، نه به‌عنوان کد. یعنی با نوسازیِ هاست، مخزن و برنچ و
 * توکن و کلِ زمان‌بندیِ بکاپ از بین می‌رفت و باید دستی بازساخته می‌شد.
 *
 * عمداً در backupDataFiles() نیست: آن فهرست را backupRun() می‌خورد و
 * بی‌سروصدا روی گیت‌هاب پوش می‌کند. اگر اینجا می‌گذاشتیمش، توکنِ گیت‌هاب
 * خودبه‌خود داخلِ مخزنِ بکاپ می‌نشست. فقط با تیکِ صریح سفر می‌کند.
 */
function backupSystemFiles(): array {
    return ['.versioncheck.json', '.backup-config.json', '.backup-log.json'];
}

/** آیا این نام یکی از فایل‌های سیستمیِ توکن‌دار است؟ */
function backupIsSecretFile(string $name): bool {
    return in_array($name, ['.versioncheck.json', '.backup-config.json'], true);
}

function backupFileList(array $cfg, array $subs = []): array {
    $list = [];
    if (!empty($cfg['include_data'])) $list = array_merge($list, backupDataFiles());
    if (!empty($cfg['include_code'])) $list = array_merge($list, backupCodeFiles());
    /* فایل‌های سیستمی فقط وقتی که زیربخششان صراحتاً انتخاب شده باشد */
    foreach ($subs as $sid) {
        $d = backupSubDef((string)$sid);
        if (!$d) continue;
        foreach ((array)($d['files'] ?? []) as $f) {
            if (in_array($f, backupSystemFiles(), true)) $list[] = $f;
        }
    }
    return array_values(array_unique($list));
}

/** درخواست به API گیت‌هاب */
function ghApi(string $token, string $method, string $url, ?array $body = null): array {
    $ch = curl_init($url);
    $hdr = ['Accept: application/vnd.github+json',
            'User-Agent: scraper-backup',
            'X-GitHub-Api-Version: 2022-11-28'];
    if ($token !== '') $hdr[] = 'Authorization: Bearer ' . $token;
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => 1, CURLOPT_CUSTOMREQUEST => $method,
        CURLOPT_HTTPHEADER => $hdr, CURLOPT_TIMEOUT => 45,
        CURLOPT_CONNECTTIMEOUT => 15, CURLOPT_SSL_VERIFYPEER => 0,
        CURLOPT_SSL_VERIFYHOST => 0,
    ]);
    if ($body !== null) curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($body, JSON_UNESCAPED_UNICODE));
    $raw = curl_exec($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $err = curl_error($ch);
    curl_close($ch);
    $j = json_decode((string)$raw, true);
    return ['ok' => $code >= 200 && $code < 300, 'code' => $code,
            'json' => is_array($j) ? $j : [], 'raw' => (string)$raw, 'error' => $err];
}

/** یک بستهٔ بکاپ می‌سازد: همهٔ فایل‌ها به‌صورت base64 داخل یک JSON */
function backupBuildBundle(array $cfg, bool $stripImages = false, array $subs = []): array {
    $files = backupFileList($cfg, $subs);
    $bundle = ['app' => 'scraper', 'version' => APP_VERSION,
               'created_at' => time(), 'created_at_h' => date('Y/m/d H:i:s'),
               'host' => (string)($_SERVER['HTTP_HOST'] ?? 'cli'),
               'files' => []];
    $bytes = 0;
    foreach ($files as $f) {
        $p = __DIR__ . '/' . $f;
        $c = @file_get_contents($p);
        if ($c === false) continue;
        // v9.62: حالتِ «فقط متن» — بلوک‌های تصویرِ base64 را حذف کن
        if ($stripImages) {
            $stripped = backupStripImageData($c);
            if ($stripped !== $c) { $c = $stripped; $bundle['stripped_images'] = true; }
        }
        $bytes += strlen($c);
        $bundle['files'][$f] = ['size' => strlen($c), 'b64' => b64enc($c)];
    }
    $bundle['total_files'] = count($bundle['files']);
    $bundle['total_bytes'] = $bytes;
    return $bundle;
}

/** بکاپ محلی (همیشه، حتی وقتی گیت‌هاب تنظیم نشده) */
function backupWriteLocal(array $bundle): string {
    if (!is_dir(BACKUP_DIR)) @mkdir(BACKUP_DIR, 0775, true);
    $name = 'backup_' . date('Ymd_His') . '.json';
    @file_put_contents(BACKUP_DIR . '/' . $name,
        json_encode($bundle, JSON_UNESCAPED_UNICODE), LOCK_EX);
    // نگه‌داشتن فقط چند نسخهٔ آخر
    $all = glob(BACKUP_DIR . '/backup_*.json') ?: [];
    sort($all);
    $keep = max(1, (int)(backupCfg()['keep'] ?? 20));
    while (count($all) > $keep) { @unlink(array_shift($all)); }
    return $name;
}

/** آپلود بسته روی گیت‌هاب */
function backupPushGithub(array $cfg, array $bundle, string $name): array {
    if ($cfg['token'] === '' || $cfg['repo'] === '')
        return ['ok' => false, 'error' => 'توکن یا مخزن تنظیم نشده'];
    $path = ($cfg['path'] !== '' ? $cfg['path'] . '/' : '') . $name;
    $url  = 'https://api.github.com/repos/' . $cfg['repo'] . '/contents/' . rawurlencode($path);
    $url  = str_replace('%2F', '/', $url);
    // اگر فایل هست، sha لازم است
    $cur = ghApi($cfg['token'], 'GET', $url . '?ref=' . rawurlencode($cfg['branch']));
    $body = ['message' => 'backup ' . $bundle['created_at_h'] . ' (v' . APP_VERSION . ')',
             'content' => b64enc(json_encode($bundle, JSON_UNESCAPED_UNICODE)),
             'branch'  => $cfg['branch']];
    if (!empty($cur['json']['sha'])) $body['sha'] = $cur['json']['sha'];
    $r = ghApi($cfg['token'], 'PUT', $url, $body);
    if (!$r['ok']) {
        $msg = (string)($r['json']['message'] ?? $r['error'] ?? ('HTTP ' . $r['code']));
        return ['ok' => false, 'error' => $msg, 'code' => $r['code']];
    }
    return ['ok' => true, 'path' => $path,
            'html_url' => (string)($r['json']['content']['html_url'] ?? '')];
}

function backupLog(array $row): void {
    $log = is_file(BACKUP_LOG_FILE)
        ? (json_decode((string)@file_get_contents(BACKUP_LOG_FILE), true) ?: []) : [];
    $log[] = $row + ['at' => time(), 'at_h' => date('Y/m/d H:i:s')];
    if (count($log) > 50) $log = array_slice($log, -50);
    @file_put_contents(BACKUP_LOG_FILE, json_encode($log, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/** اجرای کامل یک بکاپ */
function backupRun(?array $cfg = null): array {
    $cfg = $cfg ?? backupCfg();
    $bundle = backupBuildBundle($cfg);
    if (empty($bundle['files'])) {
        $res = ['ok' => false, 'error' => 'هیچ فایلی برای بکاپ انتخاب نشده'];
        backupLog($res); return $res;
    }
    $local = backupWriteLocal($bundle);
    $res = ['ok' => true, 'local' => $local,
            'files' => $bundle['total_files'], 'bytes' => $bundle['total_bytes']];
    if ($cfg['token'] !== '' && $cfg['repo'] !== '') {
        $gh = backupPushGithub($cfg, $bundle, $local);
        $res['github'] = $gh['ok'] ? 'ok' : ('failed: ' . (string)($gh['error'] ?? '?'));
        if (!empty($gh['html_url'])) $res['url'] = $gh['html_url'];
        if (!$gh['ok']) $res['ok'] = false;
    } else {
        $res['github'] = 'skipped';
    }
    $c = backupCfg(); $c['last_run'] = time(); backupSaveCfg($c);
    backupLog($res);
    return $res;
}

/** بازیابی از یک بسته */
function backupRestoreBundle(array $bundle, array $only = [], array $sections = []): array {
    /* v10.13 (۲۶): درون‌ریزیِ گزینشی.
       $only  — فهرستِ نامِ فایل (رفتار قدیمی، دست‌نخورده)
       $sections — شناسهٔ بخش/زیربخش. خالی یعنی همه.

       نکتهٔ ظریف: وقتی فقط یکی از دو برشِ profiles.json انتخاب شده،
       نوشتنِ فایل به‌صورت کامل یعنی نابود کردنِ برشِ دیگر. مثلاً کاربری
       که فقط «تنظیماتِ پروفایل‌ها» را برمی‌گرداند، انتظار ندارد محصولاتِ
       فعلی‌اش پاک شوند. برای همین برشِ انتخاب‌شده با فایلِ روی دیسک
       ادغام می‌شود، نه جایگزینِ آن. */
    $subs = $sections ? backupExpandSections($sections) : [];
    $done = []; $skipped = []; $merged = [];
    foreach ((array)($bundle['files'] ?? []) as $name => $meta) {
        $safe = basename((string)$name);
        if ($safe === '' || $safe !== $name) { $skipped[] = $name; continue; }
        if ($only && !in_array($safe, $only, true)) continue;
        /* v10.14: فایلِ سیستمی فقط با انتخابِ صریح بازیابی می‌شود.
           انتخابِ خالی یعنی «هرچه در بسته هست» و اگر استثنا نمی‌گذاشتیم،
           بازیابیِ یک بستهٔ توکن‌دار روی هاستِ مقصد، مخزن و زمان‌بندیِ
           بکاپِ خودِ آن هاست را هم بی‌خبر بازنویسی می‌کرد. */
        if (!$subs && in_array($safe, backupSystemFiles(), true)) { $skipped[] = $safe; continue; }
        $data = b64dec((string)($meta['b64'] ?? ''));
        if ($data === false) { $skipped[] = $safe; continue; }
        $dst = __DIR__ . '/' . $safe;
        if ($subs) {
            $cut = backupFilterFileContent($safe, (string)$data, $subs);
            if ($cut === null) continue;                       // این فایل انتخاب نشده
            if ($cut !== (string)$data) {
                // برشِ ناقص ⇒ باید با محتوای فعلی ادغام شود
                $data = backupMergeSlice($dst, (string)$cut);
                $merged[] = $safe;
            } else { $data = $cut; }
        }
        // نسخهٔ فعلی کنار گذاشته شود تا بازیابیِ اشتباه هم برگشت‌پذیر باشد
        if (is_file($dst)) @copy($dst, $dst . '.before-restore');
        if (@file_put_contents($dst, $data, LOCK_EX) !== false) {
            /* v10.14: فایل‌های سیستمیِ توکن‌دار با 0600 نوشته می‌شوند —
               دقیقاً مثل vc_save(). بدونِ این، بازیابی توکن را با مجوزِ
               پیش‌فرض روی دیسک می‌گذاشت و برای بقیهٔ کاربرانِ هاست
               خواندنی می‌شد. */
            if (backupIsSecretFile($safe)) @chmod($dst, 0600);
            $done[] = $safe;
        }
        else $skipped[] = $safe;
    }
    $res = ['ok' => !empty($done), 'restored' => $done, 'skipped' => $skipped];
    if ($subs)   $res['sections'] = array_values($subs);
    if ($merged) $res['merged'] = array_values(array_unique($merged));
    return $res;
}

/**
 * v10.13 (۲۶): برشِ تازه را روی محتوای فعلیِ فایل می‌نشاند.
 * فقط کلیدهایی که در برش آمده‌اند عوض می‌شوند؛ بقیهٔ کلیدهای هر رکورد
 * (و رکوردهایی که اصلاً در برش نیستند) دست‌نخورده می‌مانند.
 */
function backupMergeSlice(string $dstPath, string $sliceJson): string {
    $slice = json_decode($sliceJson, true);
    if (!is_array($slice)) return $sliceJson;
    $cur = is_file($dstPath) ? json_decode((string)@file_get_contents($dstPath), true) : [];
    if (!is_array($cur)) $cur = [];
    foreach ($slice as $k => $row) {
        if (!is_array($row) || !is_array($cur[$k] ?? null)) { $cur[$k] = $row; continue; }
        /* array_merge کلیدهای عددی را از نو شماره‌گذاری می‌کند و رکوردِ
           پروفایل را خراب می‌کند؛ حلقهٔ صریح امن‌تر است. */
        foreach ($row as $ck => $cv) $cur[$k][$ck] = $cv;
    }
    return (string)json_encode($cur, JSON_UNESCAPED_UNICODE);
}

if (isCliRun()) {
    /* $argv در همهٔ پیکربندی‌ها تعریف نمی‌شود (register_argc_argv=Off)،
       پس $_SERVER['argv'] هم بررسی می‌شود. */
    $_cliArgv = (array)($GLOBALS['argv'] ?? $_SERVER['argv'] ?? []);
    if (!$_cliArgv && function_exists('s4CliFallbackArgv')) $_cliArgv = s4CliFallbackArgv($_cliArgv);
    $_cliArgs = array_slice($_cliArgv, 1);
    $_cliCmd  = strtolower(trim((string)($_cliArgs[0] ?? 'cron_run')));
    $_cliCmd  = preg_replace('~^-+~', '', $_cliCmd);          // --cron_run هم قبول
    $_cliCmd  = ltrim($_cliCmd, '?');                          // ?cron_run هم قبول
    if ($_cliCmd === '' || $_cliCmd === 'cron' || $_cliCmd === 'cron_run') {
        $_GET['cron_run'] = '1';
    } elseif ($_cliCmd === 'queue_backend') {
        $encodedQueueJob=(string)($_cliArgs[1]??'');$encodedQueueJob=strtr($encodedQueueJob,'-_','+/');
        $padQueueJob=strlen($encodedQueueJob)%4;if($padQueueJob)$encodedQueueJob.=str_repeat('=',4-$padQueueJob);
        $queueJob=json_decode((string)base64_decode($encodedQueueJob,true),true);
        $queueAction=(string)($queueJob['get']['action']??'');
        if(!is_array($queueJob)||!in_array($queueAction,['bsl_backend','woo_backend'],true)){
            if(defined('STDERR'))fwrite(STDERR,"invalid queue_backend payload\n");exit(2);
        }
        foreach((array)($queueJob['get']??[])as$queueGetKey=>$queueGetValue)$_GET[(string)$queueGetKey]=$queueGetValue;
        $_POST=is_array($queueJob['post']??null)?$queueJob['post']:[];
    } elseif ($_cliCmd === 'task_dispatch') {
        $encodedTaskJob=(string)($_cliArgs[1]??'');$encodedTaskJob=strtr($encodedTaskJob,'-_','+/');
        $padTaskJob=strlen($encodedTaskJob)%4;if($padTaskJob)$encodedTaskJob.=str_repeat('=',4-$padTaskJob);
        $taskJob=json_decode((string)base64_decode($encodedTaskJob,true),true);
        if(!is_array($taskJob)||!is_array($taskJob['get']??null)){
            if(defined('STDERR'))fwrite(STDERR,"invalid task_dispatch payload\n");exit(2);
        }
        $taskGet=(array)$taskJob['get'];
        if(((string)($taskGet['action']??''))==='backend_extract'){
            $_GET['backend_extract_cli']='1';
            if(isset($taskGet['profile_key']))$_GET['profile_key']=(string)$taskGet['profile_key'];
            elseif(isset($taskGet['url']))$_GET['profile_key']=profileKey((string)$taskGet['url']);
            $_GET['phase']=(string)($taskGet['phase']??'list');
            if(!empty($taskGet['resume']))$_GET['resume']='1';
            if(!empty($taskGet['force_all']))$_GET['force_all']='1';
            $_GET['direct']='1';
        }else{
            foreach($taskGet as $tgk=>$tgv)$_GET[(string)$tgk]=$tgv;
            $_POST=is_array($taskJob['post']??null)?$taskJob['post']:[];
        }
    } elseif ($_cliCmd === 'worker' || $_cliCmd === 'queue_worker') {
        $_GET['worker_run'] = '1';                 // php scraper4.php worker
    } elseif ($_cliCmd === 'worker_once') {
        $_GET['worker_run'] = '1'; $_GET['worker_once'] = '1';
    } elseif ($_cliCmd === 'worker_status') {
        $_GET['worker_status'] = '1';
    } elseif ($_cliCmd === 'worker_extract_job') {
        $_GET['worker_extract_job'] = '1';
        $_GET['worker_job_id'] = (string)($_cliArgs[1] ?? '');
    } elseif ($_cliCmd === 'manual_sync') {
        $_GET['manual_sync'] = '1';                 // php scraper4.php manual_sync <profile_key>
        $_GET['profile'] = (string)($_cliArgs[1] ?? '');
        $_GET['force'] = '1';
        $_GET['direct'] = '1';                      // childِ worker دوباره enqueue نکند
        if (in_array('resume', $_cliArgs, true) || in_array('--resume', $_cliArgs, true)) $_GET['resume'] = '1';
    } elseif ($_cliCmd === 'matrix_build' || $_cliCmd === 'matrix') {
        $_GET['matrix_build_cli'] = '1';
        $_GET['matrix_payload'] = (string)($_cliArgs[1] ?? '');
    } elseif ($_cliCmd === 'matrix_fix') {
        $_GET['matrix_fix_cli'] = '1';
        $_GET['matrix_fix_payload'] = (string)($_cliArgs[1] ?? '');
    } elseif ($_cliCmd === 'bsl_duplicate_worker') {
        $_GET['bsl_duplicate_worker_cli'] = '1';
    } elseif ($_cliCmd === 'backend_extract' || $_cliCmd === 'extract') {
        $_GET['backend_extract_cli'] = '1';         // php scraper4.php backend_extract <profile_key>
        $_GET['profile_key'] = (string)($_cliArgs[1] ?? '');
        $_GET['phase'] = 'list';
        foreach ($_cliArgs as $_a) {
            $_a = (string)$_a;
            if (preg_match('~^--phase=(all|list|detail)$~', $_a, $_m)) $_GET['phase'] = $_m[1];
            elseif ($_a === '--force-all' || $_a === 'force_all') $_GET['force_all'] = '1';
            elseif ($_a === '--resume' || $_a === 'resume') $_GET['resume'] = '1';
            elseif (preg_match('~^--pages=(\d+)$~', $_a, $_pm)) $_GET['pages'] = $_pm[1];
            elseif (preg_match('~^--detail-mode=(two_stage|inline)$~', $_a, $_dm)) $_GET['detail_mode'] = $_dm[1];
            elseif (preg_match('~^--queue-id=([A-Za-z0-9._-]+)$~', $_a, $_qm)) $_GET['queue_id'] = $_qm[1];
        }
        $_GET['direct'] = '1';
    } elseif ($_cliCmd === 'whoami') {
        $_GET['whoami'] = '1';
    } elseif ($_cliCmd === 'backup') {
        $_GET['backup_run'] = '1';                 // php scraper4.php backup
    } else {
        $_GET['cron_run'] = '1';
    }
}

/* v10.184: در CLI، آرگومان‌ها تازه در بلوک بالا به $_GET تبدیل می‌شوند.
   endpoint اولیهٔ worker_status/worker_run بالاتر از این نقطه است و برای HTTP
   کافی است، اما برای `php scraper4.php worker` باید بعد از parse دوباره اجرا شود. */
if (isset($_GET['worker_status'])) {
    $q = s4WorkerLoadQueue(); $st = s4WorkerStateLoad();
    echo json_encode(['ok'=>true,'active'=>s4WorkerIsActive(),'state'=>$st,'queue'=>$q], JSON_UNESCAPED_UNICODE) . PHP_EOL;
    exit;
}
if (isset($_GET['worker_run'])) {
    if (!isCliRun()) {
        header('Content-Type: application/json; charset=UTF-8');
        echo json_encode(['ok'=>false,'error'=>'worker فقط از CLI اجرا می‌شود: php scraper4.php worker'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    s4WorkerLoopFromCli();
    exit;
}
if(isset($_GET['worker_extract_job'])){
    if(!isCliRun()){http_response_code(403);echo json_encode(['ok'=>false,'error'=>'CLI only']);exit;}
    $resParallel=s4RunParallelExtractJob(trim((string)($_GET['worker_job_id']??'')));
    echo json_encode($resParallel,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL;
    exit(!empty($resParallel['ok'])?0:1);
}
if (isset($_GET['matrix_build_cli'])) {
    $enc=trim((string)($_GET['matrix_payload']??''));
    $enc=strtr($enc,'-_','+/');$pad=strlen($enc)%4;if($pad)$enc.=str_repeat('=',4-$pad);
    $payload=json_decode((string)base64_decode($enc,true),true);
    if(!is_array($payload)){$resMxCli=['ok'=>false,'error'=>'invalid_matrix_payload'];}
    else{$resMxCli=s4WorkerRunMatrixBuild($payload);}
    echo json_encode($resMxCli,JSON_UNESCAPED_UNICODE).PHP_EOL;
    /* پایان سالمِ یک time-slice الزاماً ok نهایی ندارد؛ yielded یعنی checkpoint
       معتبر نوشته شده و parent باید برش بعد را اجرا کند، نه اینکه exit 1 را crash بداند. */
    $matrixSliceOk=!empty($resMxCli['ok'])||!empty($resMxCli['yielded'])||!empty($resMxCli['resume_needed']);
    exit($matrixSliceOk?0:1);
}
if (isset($_GET['matrix_fix_cli'])) {
    $enc=trim((string)($_GET['matrix_fix_payload']??''));$enc=strtr($enc,'-_','+/');$pad=strlen($enc)%4;if($pad)$enc.=str_repeat('=',4-$pad);
    $payload=json_decode((string)base64_decode($enc,true),true);$resFixCli=is_array($payload)?s4WorkerRunMatrixFix($payload):['ok'=>false,'error'=>'invalid_matrix_fix_payload'];
    echo json_encode($resFixCli,JSON_UNESCAPED_UNICODE).PHP_EOL;exit(!empty($resFixCli['ok'])?0:1);
}
if(isset($_GET['bsl_duplicate_worker_cli'])){
    $resDupCli=matrixBslDuplicateWorkerLoop();
    echo json_encode($resDupCli,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL;
    exit(!empty($resDupCli['ok'])?0:1);
}
if (isset($_GET['backend_extract_cli'])) {
    $pk = trim((string)($_GET['profile_key'] ?? ''));
    $phaseCli = (string)($_GET['phase'] ?? 'list');
    if (!in_array($phaseCli, ['all','list','detail'], true)) $phaseCli = 'list';
    $initialPhaseCli = $phaseCli;
    $forceCli = !empty($_GET['force_all']);
    $resumeCli = !empty($_GET['resume']);
    $reservedCli = '';
    $preferredQidCli = trim((string)($_GET['queue_id'] ?? ''));
    if ($resumeCli) {
        $_prCli0 = loadProfiles()[$pk] ?? null;
        if ($initialPhaseCli === 'list' && is_array($_prCli0) && !empty($_prCli0['_extract_want_detail'])) {
            $initialPhaseCli = 'all';
        }
        $prepCli = extractResumePrepare($pk, loadConnections(), $preferredQidCli, true);
        if (empty($prepCli['ok'])) {
            if((string)($prepCli['reason']??'')==='lock_held'){
                $retryCli=s4QueueRetryableExtraction($pk,$phaseCli,-1,'');
                echo json_encode(['ok'=>!empty($retryCli['ok']),'retryable'=>true,'queued'=>!empty($retryCli['ok']),
                    'resume_needed'=>true,'locked'=>true,'job_id'=>(string)($retryCli['job_id']??'')],JSON_UNESCAPED_UNICODE).PHP_EOL;
                exit(!empty($retryCli['ok'])?0:2);
            }
            echo json_encode(['ok'=>false,'error'=>'checkpoint استخراج قابل رزرو نیست: '.(string)($prepCli['reason']??'')], JSON_UNESCAPED_UNICODE) . PHP_EOL;
            exit(2);
        }
        $phaseCli = (string)($prepCli['phase'] ?? $phaseCli);
        if ($initialPhaseCli === 'all' && $phaseCli === 'list') $phaseCli = 'all';
        $reservedCli = (string)($prepCli['queue_id'] ?? '');
    }
    $pagesCli=array_key_exists('pages',$_GET)?max(0,(int)$_GET['pages']):-1;
    $detailModeCli=isset($_GET['detail_mode'])&&trim((string)$_GET['detail_mode'])!==''?normalizeDetailExtractMode($_GET['detail_mode']):'';
    $resCli = runBackendExtract($pk, 'worker_child', false, $phaseCli, $forceCli, $reservedCli, $pagesCli, $detailModeCli);
    if(!empty($resCli['retryable'])){
        $retryCli=s4QueueRetryableExtraction($pk,$phaseCli,$pagesCli,$detailModeCli);
        $resCli['queued']=!empty($retryCli['ok']);$resCli['retry_job_id']=(string)($retryCli['job_id']??'');
        if(!empty($retryCli['ok']))$resCli['ok']=true;
    }
    $cliSegs = 1;
    $cliTransientRetries = 0;
    while (!empty($resCli['ok']) && empty($resCli['cancelled'])
           && (!empty($resCli['ran_out']) || (!empty($resCli['resume_needed']) && $cliTransientRetries < 10))
           && $cliSegs < 60) {
        if (empty($resCli['ran_out'])) $cliTransientRetries++;
        sleep(!empty($resCli['ran_out']) ? 2 : min(30, 5 + ($cliTransientRetries * 3)));
        $prepNext = extractResumePrepare($pk, loadConnections(), (string)($resCli['queue_id'] ?? ''), false);
        if (empty($prepNext['ok'])) {
            if((string)($prepNext['reason']??'')==='lock_held'){
                $retryCli=s4QueueRetryableExtraction($pk,$phaseCli,$pagesCli,$detailModeCli);
                $resCli['retryable']=true;$resCli['resume_needed']=true;$resCli['queued']=!empty($retryCli['ok']);
                $resCli['retry_job_id']=(string)($retryCli['job_id']??'');if(!empty($retryCli['ok']))$resCli['ok']=true;
            }
            break;
        }
        $nextPh = (string)($prepNext['phase'] ?? 'detail');
        if ($initialPhaseCli === 'all' && $nextPh === 'list') $nextPh = 'all';
        $resCli = runBackendExtract($pk, 'worker_child', false, $nextPh, $forceCli, (string)($prepNext['queue_id'] ?? ''), $pagesCli, $detailModeCli);
        $cliSegs++;
    }
    echo json_encode($resCli, JSON_UNESCAPED_UNICODE) . PHP_EOL;
    exit(!empty($resCli['ok']) ? 0 : 1);
}

/* =====================================================================
 *  v10.35 (۴۷ه): «همگام‌سازیِ دستی» — یک دکمه، کلِ زنجیره
 *
 *  ?manual_sync=1&profile=<key>[&force=1]
 *
 *  کاری که می‌کند: پرچمِ کار را می‌گذارد و بعد دقیقاً همان چرخهٔ کران را
 *  اجرا می‌کند (استخراج ⇒ بازنشستگی ⇒ صف‌سازی ⇒ ارسال ⇒ گزارش). چون از
 *  همان مسیر رد می‌شود، هر بهبودی که به کران داده شود خودبه‌خود اینجا هم
 *  هست و هیچ‌وقت دو رفتارِ متفاوت پیدا نمی‌کنند.
 *
 *  ?manual_sync_stop=1 سیگنالِ توقف می‌گذارد؛ حلقه بینِ دو پروفایل و
 *  ارسال‌کننده‌ها در اولین بررسی می‌ایستند.
 * ===================================================================== */
if (isset($_GET['manual_sync_stop'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @file_put_contents(MANUAL_SYNC_STOP_FILE, json_encode(['at' => time()]));
    /* v10.55 (۶۹): توقفِ دستی باید به پردازنده‌هایِ در حالِ اجرایِ ارسال/استخراج
       هم برسد. استخراج فقط برای همان پروفایل/queue_id سیگنال می‌گیرد تا اجرای
       هم‌زمانِ پروفایل‌های دیگر با یک فایلِ مشترک تصادفاً متوقف نشود. */
    @file_put_contents(BSL_STOP_FILE, json_encode(['stop' => true, 'time' => time()], LOCK_EX));
    @file_put_contents(WOO_STOP_FILE, json_encode(['stop' => true, 'time' => time()], LOCK_EX));
    $msStopResults=extractStopManualSyncProfileWorkers();
    echo json_encode(['ok' => true, 'stopped' => true,'extraction_stop'=>$msStopResults], JSON_UNESCAPED_UNICODE);
    exit;
}
if (isset($_GET['manual_sync_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $msSt = readProgress(MANUAL_SYNC_PROGRESS_FILE);
    /* v10.58 (۷۲): اجرایِ دستیِ کشته‌شدهٔ هاست، فایل را تا ابد «در حال
       اجرا» جا می‌گذارد — رابط روی همان تصویر می‌ماند، دکمه می‌گوید
       «شغال»، و از دید کاربر «اصلاً کار نمی‌کند». همین‌جا همان معیارِ
       زنده‌بودنِ نگهبان اعمال می‌شود: اگر پیشرفت بیش از stall_after بی‌حرکت
       باشد، آن اجرا مرده است. با پیامِ روشن بسته می‌شود تا رابط برگردد و
       کاربر دوباره امتحان کند — بخشِ انجام‌شده روی دیسک است و
       چک‌پوینت جلوی تکرارِ کار را می‌گیرد. */
    if (!empty($msSt['running']) && empty($msSt['done'])) {
        $msIdleD = time() - (int)($msSt['last_progress_ts'] ?? ($msSt['ts'] ?? 0));
        $msMaxD  = max(120, (int)(loadConnections()['stall_after'] ?? 300));
