            $agg=['queued'=>0,'sent'=>0,'updated'=>0,'failed'=>0,'skipped'=>0];$dest=[];$ownedQueueIds=array_values(array_filter(array_map('strval',(array)($sr['send_queue_ids']??[]))));$ownedQueueSet=$ownedQueueIds?array_fill_keys($ownedQueueIds,true):[];
