            . (!empty($_msEx['price_changed']) ? (' · قیمت ' . (int)$_msEx['price_changed']) : ''));
        try {
            $cnN = loadConnections();
            notifSourceChanges($cnN, $_msEx, $_msName);
        } catch (Throwable $e) {}
        /* پروفایل تازه بعد از extract */
        $_msAll = loadProfiles();
        $_msProf = $_msAll[$_msKey] ?? $_msProf;
        unset($_msAll);
    } else {
        $_msErr = (string)($_msEx['error'] ?? 'استخراج ناموفق');
        if (!empty($_msEx['duplicate'])) $_msErr .= ' (ردیف فعال در صف)';
        if (!empty($_msEx['locked'])) $_msErr .= ' (قفل استخراج)';
        manualSyncProgress(['phase' => 'خطای استخراج'], '❌ ' . mb_substr($_msErr, 0, 280));
        /* استخراج fail نباید کل همگام را بکشد اگر محصول روی دیسک هست — ادامه برای ارسال */
        if (empty($_msProf['products'])) {
            syncPipelineMark($_msKey, $_msName, 'error', 'manual', [
                'failed_stage' => 'extract',
                'error' => $_msErr,
                'message' => $_msErr,
            ]);
            writeProgress(MANUAL_SYNC_PROGRESS_FILE, array_merge(readProgress(MANUAL_SYNC_PROGRESS_FILE), [
                'running' => false, 'done' => true, 'stale' => true, 'error' => $_msErr,
                'checkpoint' => array_merge(
                    (array)(readProgress(MANUAL_SYNC_PROGRESS_FILE)['checkpoint'] ?? []),
                    ['profile_key' => $_msKey, 'phase' => 'خطا', 'current' => 1, 'total' => 4,
                     'started_at' => (int)(readProgress(MANUAL_SYNC_PROGRESS_FILE)['started_at'] ?? time())]),
                'phase' => 'خطا', 'ts' => time(), 'last_progress_ts' => time(),
            ]));
            if (PHP_SAPI === 'cli') {
                echo json_encode(['ok' => false, 'error' => $_msErr], JSON_UNESCAPED_UNICODE) . PHP_EOL;
            }
            /* keep-conn: final line */ try { if (defined('MS_KEEP_CONN')) { echo json_encode(['done'=>true], JSON_UNESCAPED_UNICODE)."
"; @ob_flush(); @flush(); } } catch (Throwable $e) {}
            exit;
        }
        manualSyncProgress([], '⚠️ استخراج شکست — ادامه با محصولات ذخیره‌شده برای ارسال');
    }

    /* ── ۲) ذخیره و اعمال ضرایب ──
       profile تازهٔ ذخیره‌شده و connections دوباره خوانده می‌شوند؛ payload
       ارسال در مرحلهٔ بعد با prepareForSend همین ضرایب را واقعاً اعمال می‌کند. */
    $_msAll=loadProfiles();$_msProf=$_msAll[$_msKey]??$_msProf;unset($_msAll);$_msCn=loadConnections();
    $_msPricing=syncPricingSnapshot((array)$_msProf,$_msCn);
    manualSyncProgress(['phase'=>'ذخیره و اعمال ضرایب','current'=>2,'pricing'=>$_msPricing],
        '💰 ضرایب ذخیره‌شده بارگذاری و برای '.(int)$_msPricing['products'].' محصول فعال شد');
    syncPipelineMark($_msKey,$_msName,'pricing','manual',['pricing'=>$_msPricing,
        'stage_details'=>['pricing'=>['counts'=>['products'=>(int)$_msPricing['products']],
            'data'=>$_msPricing,'report'=>'تنظیمات قیمت پروفایل، مقصد و غرفه‌ها دوباره از دیسک خوانده و روی payload ارسال اعمال شد']],
        'message'=>'ضرایب ذخیره و اعمال شد']);

    if (manualSyncStopped()) {
        writeProgress(MANUAL_SYNC_PROGRESS_FILE, array_merge(readProgress(MANUAL_SYNC_PROGRESS_FILE), [
            'running' => false, 'done' => true, 'stale' => true, 'cancelled' => true,
            'partial' => true, 'resumable' => true,
            'phase' => 'متوقف شد', 'checkpoint' => array_merge(
                (array)(readProgress(MANUAL_SYNC_PROGRESS_FILE)['checkpoint'] ?? []),
                ['profile_key' => $_msKey, 'phase' => 'متوقف شد',
                 'current' => (int)(readProgress(MANUAL_SYNC_PROGRESS_FILE)['current'] ?? 0), 'total' => 4,
                 'started_at' => (int)(readProgress(MANUAL_SYNC_PROGRESS_FILE)['started_at'] ?? time())]),
            'ts' => time(), 'last_progress_ts' => time(),
        ]));
        /* keep-conn: final line */ try { if (defined('MS_KEEP_CONN')) { echo json_encode(['done'=>true], JSON_UNESCAPED_UNICODE)."
"; @ob_flush(); @flush(); } } catch (Throwable $e) {}
        exit;
    }

    /* ── ۳) صف‌سازی و ارسال (باسلام / ووکامرس) ── */
    syncPipelineMark($_msKey,$_msName,'send','manual',['pricing'=>$_msPricing??[],'message'=>'صف‌سازی و ارسال']);
    if ($_msResumeQueueDone && (string)($_msResumeCp['profile_key'] ?? '') === $_msKey) {
        $_msTarget = (string)($_msResumeCp['target'] ?? ($_msSyncCfg['target'] ?? 'woo'));
        if (!in_array($_msTarget, ['woo', 'bsl', 'both', 'none'], true)) $_msTarget = 'woo';
        $_msResults['target'] = $_msTarget;
        $_msResults['enqueue'] = $_msResumeCp['enqueue'];
        if (is_array($_msResumeCp['extract'] ?? null)) $_msEx = $_msResumeCp['extract'];
        manualSyncProgress(['phase' => 'صف ارسال تمام', 'current' => 3],
            '↻ صف ارسالِ checkpoint دوباره ساخته نشد');
    } else {
    manualSyncProgress(['phase' => 'صف ارسال', 'current' => 3], '📤 آماده‌سازی صف ارسال…');
    msAlive('queue_send');
    try {
        $_msCn = loadConnections();
        $_msTarget = (string)($_msSyncCfg['target'] ?? 'woo');
        if (!in_array($_msTarget, ['woo', 'bsl', 'both', 'none'], true)) $_msTarget = 'woo';
        $_msResults['target'] = $_msTarget;

        /* v10.101 / v10.475: بازنشستگی مشترک فقط وقتی مجاز است که استخراج کامل و بدون گارد کاهش ذخیره شده باشد */
        if (!empty($_msEx['ok']) && empty($_msEx['partial']) && empty($_msEx['ran_out']) && empty($_msEx['resume_needed']) && empty($_msEx['cancelled']) && ($_msEx['products_saved'] ?? true) !== false && (string)($_msEx['guard'] ?? '') === '') {
            try {
                /* پروفایل تازه از دیسک بعد از extract */
                $_msProfRet = is_array($_msProf) ? $_msProf : [];
                $_msRetPack = retireAfterExtract($_msCn, $_msProfRet, $_msEx, (string)$_msTarget, $_msSyncCfg, (string)$_msKey);
                if (!empty($_msRetPack['result'])) {
                    $_msRt = $_msRetPack['result'];
                    $_msResults['retire'] = [
                        'mode' => $_msRetPack['mode'],
                        'target' => $_msRetPack['target'],
                        'checked' => (int)($_msRt['checked'] ?? 0),
                        'retired' => (int)($_msRt['retired'] ?? 0),
                        'not_found' => (int)($_msRt['not_found'] ?? 0),
                        'failed' => (int)($_msRt['failed'] ?? 0),
                        'skipped' => (string)($_msRetPack['skipped'] ?? ''),
                        'oos_merged' => (int)($_msRetPack['oos_merged'] ?? 0),
                        'woo_action' => $_msRetPack['woo_action'] ?? '',
                        'bsl_action' => $_msRetPack['bsl_action'] ?? '',
                    ];
                    if (!empty($_msRetPack['oos_merged'])) {
                        manualSyncProgress([], '⛔ ' . (int)$_msRetPack['oos_merged'] . ' کالای ناموجود روی دیسک → بازنشستگی');
                    }
                    if (!empty($_msRetPack['skipped'])) {
                        manualSyncProgress([], '⏭ بازنشستگی: ' . (string)$_msRetPack['skipped']);
                    } else {
                        manualSyncProgress([], '✅ بازنشستگی: ' . (int)($_msRt['retired'] ?? 0)
                            . ' انجام · ' . (int)($_msRt['not_found'] ?? 0) . ' یافت‌نشد · '
                            . (int)($_msRt['failed'] ?? 0) . ' خطا');
                    }
                } elseif (($_msRetPack['skipped'] ?? '') === 'no_items') {
                    manualSyncProgress([], '✓ موردی برای بایگانی/حذف از مبدأ نبود');
                } elseif (!empty($_msRetPack['skipped'])) {
                    manualSyncProgress([], 'ℹ️ بازنشستگی: ' . (string)$_msRetPack['skipped']);
                }
            } catch (Throwable $e) {
