    return $out;
}

/** دوره‌های زمانیِ قابلِ انتخاب (دقیقه) */
function autoIntervals(): array {
    return [
        15     => 'هر ۱۵ دقیقه',
        30     => 'هر نیم‌ساعت',
        60     => 'هر ساعت',
        180    => 'هر ۳ ساعت',
        360    => 'هر ۶ ساعت',
        720    => 'هر ۱۲ ساعت',
        1440   => 'روزی یک‌بار',
        4320   => 'هر ۳ روز',
        10080  => 'هفته‌ای یک‌بار',
        43200  => 'ماهی یک‌بار',
    ];
}

/** خواندنِ کارهای ذخیره‌شده */
function autoLoadJobs(): array {
    if (!is_file(AUTO_JOBS_FILE)) return [];
    $j = json_decode((string)@file_get_contents(AUTO_JOBS_FILE), true);
    if (!is_array($j)) return [];
    $out = [];
    foreach ($j as $row) {
        if (!is_array($row) || empty($row['id'])) continue;
        $out[] = autoNormalizeJob($row);
    }
    return $out;
}

/** یک کار را به شکلِ استاندارد در می‌آورد (تا فیلدِ گمشده خطا ندهد) */
function autoNormalizeJob(array $r): array {
    return [
        'id'       => (string)$r['id'],
        'title'    => (string)($r['title'] ?? 'بی‌نام'),
        'prompt'   => (string)($r['prompt'] ?? ''),
        'mode'     => in_array(($r['mode'] ?? 'dry'), ['sim', 'dry', 'live'], true) ? (string)$r['mode'] : 'dry',
        'every'    => max(5, (int)($r['every'] ?? 1440)),
        'enabled'  => !empty($r['enabled']),
        'model'    => (string)($r['model'] ?? ''),
        'created'  => (int)($r['created'] ?? time()),
        'last_run' => (int)($r['last_run'] ?? 0),
        'last_ok'  => isset($r['last_ok']) ? (bool)$r['last_ok'] : null,
        'last_msg' => (string)($r['last_msg'] ?? ''),
        'runs'     => (int)($r['runs'] ?? 0),
        'fails'    => (int)($r['fails'] ?? 0),
        'changes'  => (int)($r['changes'] ?? 0),
    ];
}

/** نوشتنِ اتمیکِ کارها (تا اگر وسطِ نوشتن قطع شد، فایل نصفه نماند) */
function autoSaveJobs(array $jobs): bool {
    $tmp = AUTO_JOBS_FILE . '.tmp';
    $ok  = @file_put_contents($tmp, json_encode(array_values($jobs),
        JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT)) !== false;
    if (!$ok) return false;
    return @rename($tmp, AUTO_JOBS_FILE);
}

/** شناسهٔ یکتا برای کارِ تازه */
function autoNewId(): string {
    return 'job_' . dechex(time()) . dechex(random_int(0x100, 0xfff));
}

/** آیا وقتِ اجرای این کار رسیده؟ */
function autoJobDue(array $job, int $now): bool {
    if (empty($job['enabled'])) return false;
    if ($job['prompt'] === '') return false;
    $due = (int)$job['last_run'] + ((int)$job['every'] * 60);
    return $now >= $due;
}

/** زمانِ اجرای بعدی به شکلِ خوانا */
function autoNextRunLabel(array $job, int $now): string {
    if (empty($job['enabled'])) return 'خاموش';
    if ((int)$job['last_run'] === 0) return 'در اولین تیکِ کران';
    $due = (int)$job['last_run'] + ((int)$job['every'] * 60);
    $d   = $due - $now;
    if ($d <= 0) return 'همین حالا';
    if ($d < 3600)  return 'تا ' . aiFaNum((int)ceil($d / 60)) . ' دقیقهٔ دیگر';
    if ($d < 86400) return 'تا ' . aiFaNum((int)ceil($d / 3600)) . ' ساعتِ دیگر';
    return 'تا ' . aiFaNum((int)ceil($d / 86400)) . ' روزِ دیگر';
}

/** افزودنِ یک ردیف به لاگِ یک کار.
 *
 *  لاگِ هر کار جداست تا مودالِ لاگ سریع باز شود؛ اگر همه در یک فایل
 *  بودند، با چند ده کار فایل چند مگابایتی می‌شد و هر بار باز کردنِ
 *  مودال کلِ آن را می‌خواند.
 */
function autoLogAppend(string $jobId, array $entry): void {
    if (!is_dir(AUTO_LOG_DIR)) @mkdir(AUTO_LOG_DIR, 0775, true);
    $f    = AUTO_LOG_DIR . '/' . preg_replace('~[^a-z0-9_]~i', '', $jobId) . '.json';
    $rows = [];
    if (is_file($f)) {
        $j = json_decode((string)@file_get_contents($f), true);
        if (is_array($j)) $rows = $j;
    }
    $rows[] = $entry;
    // فقط آخرین N اجرا بماند — وگرنه فایل بی‌نهایت رشد می‌کند
    if (count($rows) > AUTO_LOG_KEEP) $rows = array_slice($rows, -AUTO_LOG_KEEP);
    @file_put_contents($f, json_encode($rows, JSON_UNESCAPED_UNICODE));
}

/** خواندنِ لاگِ یک کار (تازه‌ترین اول) */
function autoLogRead(string $jobId): array {
    $f = AUTO_LOG_DIR . '/' . preg_replace('~[^a-z0-9_]~i', '', $jobId) . '.json';
    if (!is_file($f)) return [];
    $j = json_decode((string)@file_get_contents($f), true);
    if (!is_array($j)) return [];
    return array_reverse($j);
}

/** پاک کردنِ لاگِ یک کار */
function autoLogClear(string $jobId): void {
    $f = AUTO_LOG_DIR . '/' . preg_replace('~[^a-z0-9_]~i', '', $jobId) . '.json';
    @unlink($f);
}

/** اجرای یک کار و ثبتِ نتیجه در لاگ.
 *
 *  عمداً از همان agentRun استفاده می‌کند تا رفتارِ کارِ زمان‌بندی‌شده
 *  دقیقاً همان رفتارِ اجرای دستی باشد — اگر دو مسیرِ جدا می‌ساختیم،
 *  کاربر چیزی را دستی تست می‌کرد و در اجرای خودکار نتیجهٔ دیگری می‌گرفت.
 */
function autoRunJob(array $cn, array $job): array {
    $t0 = microtime(true);
    $entry = ['t' => time(), 'mode' => $job['mode'], 'ok' => false,
              'summary' => '', 'calls' => 0, 'changes' => 0, 'took' => 0.0, 'error' => ''];
    try {
        $res = agentRun($cn, $job['prompt'], $job['mode'], (string)($job['model'] ?? ''));
        $entry['ok']      = !empty($res['ok']);
        $entry['summary'] = (string)($res['summary'] ?? '');
        $entry['calls']   = (int)($res['calls'] ?? 0);
        $entry['changes'] = is_array($res['changes'] ?? null) ? count($res['changes']) : 0;
        $entry['applied'] = (int)($res['applied'] ?? 0);
        $entry['detail']  = array_slice(is_array($res['changes'] ?? null) ? $res['changes'] : [], 0, 25);
        if (empty($res['ok'])) $entry['error'] = (string)($res['error'] ?? 'خطای نامشخص');
    } catch (Throwable $e) {
        $entry['error'] = 'استثنا: ' . $e->getMessage();
    }
    $entry['took'] = round(microtime(true) - $t0, 2);
    autoLogAppend($job['id'], $entry);
    return $entry;
}

/** تیکِ زمان‌بند — از داخلِ کران صدا زده می‌شود.
 *
 *  در هر تیک حداکثر AUTO_MAX_PER_TICK کار اجرا می‌شود. دلیلش ساده است:
 *  هر اجرای ایجنت می‌تواند ده‌ها ثانیه طول بکشد و هاستِ اشتراکی
 *  max_execution_time دارد. اگر ۱۰ کار هم‌زمان سررسید شوند و همه را
 *  یک‌جا بدویم، کران وسطِ کار کشته می‌شود و هیچ‌کدام نتیجه‌شان ثبت
 *  نمی‌شود. با سقفِ هر تیک، بقیه در تیکِ بعدی می‌آیند.
 */
function autoTick(array $cn, int $now = 0): array {
    if ($now <= 0) $now = time();
    $out = ['ran' => 0, 'skipped' => 0, 'jobs' => []];
    $jobs = autoLoadJobs();
    if (!$jobs) return $out;

    /* قفلِ واقعیِ تیک: وجود/سنِ path معیار مالکیت نیست. با fopen(c)+flock
       همان inode در تمام عمرِ قفل ثابت می‌ماند و مرگِ پردازه آن را خودکار
       آزاد می‌کند؛ پس probe و worker دوم پنجرهٔ unlink ندارند. */
    $lock = AUTO_LOCK_FILE;
    $lockFp = @fopen($lock, 'c');
    if (!$lockFp || !@flock($lockFp, LOCK_EX | LOCK_NB)) {
        if ($lockFp) @fclose($lockFp);
        $out['locked'] = true;
        return $out;
    }
    @ftruncate($lockFp, 0); @rewind($lockFp);
    @fwrite($lockFp, (string)$now); @fflush($lockFp);

    try {
        $ran = 0;
        foreach ($jobs as $i => $job) {
            if ($ran >= AUTO_MAX_PER_TICK) { $out['skipped']++; continue; }
            if (!autoJobDue($job, $now)) continue;
            $e = autoRunJob($cn, $job);
            $ran++;
            $jobs[$i]['last_run'] = $now;
            $jobs[$i]['last_ok']  = $e['ok'];
            $jobs[$i]['last_msg'] = $e['ok'] ? (string)$e['summary'] : (string)$e['error'];
            $jobs[$i]['runs']     = (int)$job['runs'] + 1;
            if (!$e['ok']) $jobs[$i]['fails'] = (int)$job['fails'] + 1;
            $jobs[$i]['changes']  = (int)$job['changes'] + (int)$e['changes'];
            $out['jobs'][] = ['id' => $job['id'], 'title' => $job['title'],
                              'ok' => $e['ok'], 'changes' => $e['changes']];
            $out['ran']++;
        }
        if ($out['ran'] > 0) autoSaveJobs($jobs);
    } finally {
        @flock($lockFp, LOCK_UN); @fclose($lockFp);
    }
    return $out;
}

/* ── v10.05 (۱۹): اندپوینت‌های اتوماسیونِ ایجنتی ── */

/** کاتالوگ: مدل‌های رایگانِ ابزاردار + کارهای پیشنهادی + دوره‌ها */
if (isset($_GET['auto_catalog'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $iv = [];
    foreach (autoIntervals() as $m => $lbl) $iv[] = ['m' => $m, 'label' => $lbl];
    echo json_encode([
        'ok'        => true,
        'models'    => autoFreeToolModels(),
        'providers' => autoProviderInfo(),
        'tags'      => autoModelTags(),
        'tasks'     => autoTaskCatalog(),
        'intervals' => $iv,
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

/* ==================================================================
 *  v10.19 (۳۲): مدیر وظیفه — یک پنجرهٔ واحد برای همهٔ کارهای پس‌زمینه
 *
 *  مسئله: کارهای بلندمدت این برنامه هرکدام در تبِ خودشان دفن شده‌اند —
 *  ارسال به باسلام در یک تب، استخراج در تبی دیگر، حذفِ تکراری، ایجنت،
 *  تستِ مدل‌ها و کارهای زمان‌بندی‌شده هرکدام جای دیگر. کاربر برای اینکه
 *  بفهمد «الان چه چیزی در حال اجراست» باید تب‌به‌تب بگردد، و برای توقفِ
 *  یک کار باید همان تب را پیدا کند. اگر یک کار نصفه‌کاره مانده باشد
 *  (پردازه مرده ولی فایلِ پیشرفت هنوز running=true است) هیچ‌جا معلوم
 *  نمی‌شود.
 *
 *  راه‌حل: همهٔ کارها یک «رجیستری» مشترک دارند. هر ردیفِ رجیستری می‌گوید
 *  وضعیتش را از کدام فایل بخوان، چطور درصد و برچسبش را بساز، و با کدام
 *  اندپوینت متوقفش کن. مدیر وظیفه فقط روی همین رجیستری کار می‌کند، پس
 *  افزودنِ کارِ جدید در آینده یعنی یک ردیفِ تازه — نه دست‌کاریِ رابط.
 *
 *  عمداً هیچ مسیرِ اجرایی‌ای بازنویسی نشد: مدیر وظیفه همان فایل‌های
 *  پیشرفتِ موجود را می‌خواند و همان اندپوینت‌های توقفِ موجود را صدا
 *  می‌زند. پس رفتارِ هر کار دقیقاً همان است که در تبِ خودش بود.
 * ================================================================== */

/** کارِ پس‌زمینه‌ای که بیش از این بی‌خبر بماند، «رهاشده» حساب می‌شود.
 *  هر کارِ زنده حداقل هر چند ثانیه یک‌بار فایلِ پیشرفتش را لمس می‌کند؛
 *  اگر مدت‌ها خبری نشد یعنی پردازه وسطِ کار کشته شده (تایم‌اوتِ هاست،
 *  ری‌استارتِ PHP-FPM). چنین کاری تا ابد «در حال اجرا» می‌ماند و دکمهٔ
 *  شروعِ دوباره را قفل می‌کند. */
/* TASKS_STALE_SEC is declared with the early queue constants because cron
   priority calculation can call tasksState() before execution reaches here. */

/** رجیستریِ کارهای پس‌زمینه.
 *
 *  هر ردیف: کلید ⇒ [عنوان، ایموجی، فایلِ پیشرفت، اندپوینتِ توقف یا ''،
 *  تبِ مربوطه، تابعِ خلاصه‌ساز]. خلاصه‌ساز از آرایهٔ خامِ پیشرفت،
 *  «شمارنده‌های خوانا» می‌سازد چون هر کار واژگانِ خودش را دارد
 *  (ارسال «sent/failed» دارد، حذفِ تکراری «groups/deleted»).
 *
 *  v10.23 (۳۶الف): سه فیلدِ ناوبری اضافه شد. تا اینجا فیلدِ `tab` فقط یک
 *  *برچسبِ متنی* بود («ارسال»، «ابزارها») و کلیک روی کارت هیچ کاری نمی‌کرد؛
 *  کاربر باید خودش می‌گشت تا پنجرهٔ اصلیِ آن کار را پیدا کند. حالا هر ردیف
 *  می‌گوید دقیقاً کجا باز شود:
 *    pane  — کدام تبِ اصلی (id پنل بدونِ پیشوندِ pane-)
 *    smenu — اگر جایش داخلِ پنلِ تنظیمات است، تکه‌ای از عنوانِ آن آکاردئون
 *    ai    — اگر داخلِ بخشِ «هوش مصنوعی» است، نامِ زیرتبِ آن
 *    el    — شناسهٔ عنصری که باید به آن اسکرول و چند لحظه برجسته شود
 *    open  — نامِ تابعی که پنجرهٔ اصلیِ آن کار را باز می‌کند
 *
 *  v10.23 (۳۶ج): فیلدِ `resume` — اندپوینتِ *شروعِ اصلیِ* همان کار. برای
 *  کارِ رهاشده تا حالا فقط «🗑 پاک» بود؛ یعنی کاربر باید ردِ کار را پاک
 *  می‌کرد، بعد خودش می‌گشت و دکمهٔ شروع را دوباره می‌زد. حالا مدیر وظیفه
 *  خودش می‌تواند همان اندپوینت را صدا بزند.
 */
function tasksRegistry(): array {
    return [
        /* v10.35 (۴۷ه): «همگام‌سازیِ دستی» — بالای فهرست، چون وقتی کاربر
           دکمه را می‌زند دقیقاً همین را دنبال می‌کند. سه گامِ ثابت دارد
           (استخراج ⇒ ارسال ⇒ گزارش) پس نوارِ پیشرفتش معنی‌دار است. */
        'manual_sync' => [
            'title' => 'همگام‌سازیِ دستی', 'icon' => '🔄', 'file' => MANUAL_SYNC_PROGRESS_FILE,
            'stop' => 'manual_sync_stop', 'tab' => 'شروع',
            'pane' => 'start', 'el' => 'manualSyncBox', 'resume' => 'manual_sync=1',
            'stat' => function (array $p): array {
                return ['پروفایل' => (int)($p['profiles_done'] ?? 0)];
            },
        ],
        'bsl_catalog' => [
            'title' => 'بازسازی کاتالوگ باسلام', 'icon' => '🏪', 'file' => BSL_CATALOG_PROGRESS_FILE,
            'stop' => 'bsl_catalog_stop', 'tab' => 'باسلام', 'pane' => 'send',
            'resume' => '',
            'stat' => function (array $p): array {
                return ['صفحه' => (int)($p['page'] ?? 0), 'محصول' => (int)($p['rows'] ?? 0)];
            },
        ],
        'bsl_send' => [
            'title' => 'ارسال به باسلام', 'icon' => '🚀', 'file' => BSL_PROGRESS_FILE,
            'stop' => 'bsl_stop', 'tab' => 'ارسال',
            'pane' => 'send', 'el' => 'bslQueueSection', 'resume' => 'action=bsl_backend',
            'stat' => function (array $p): array {
                return ['ارسال' => (int)($p['sent'] ?? 0), 'به‌روز' => (int)($p['updated'] ?? 0),
                        'رد' => (int)($p['skipped'] ?? 0), 'ناموفق' => (int)($p['failed'] ?? 0)];
            },
        ],
        'woo_send' => [
            'title' => 'ارسال به ووکامرس', 'icon' => '🛍', 'file' => WOO_PROGRESS_FILE,
            'stop' => 'woo_stop', 'tab' => 'ارسال',
            'pane' => 'send', 'el' => 'wooQueueSection', 'resume' => 'action=woo_backend',
            'stat' => function (array $p): array {
                return ['ارسال' => (int)($p['sent'] ?? 0), 'به‌روز' => (int)($p['updated'] ?? 0),
                        'رد' => (int)($p['skipped'] ?? 0), 'ناموفق' => (int)($p['failed'] ?? 0)];
            },
        ],
        'extract' => [
            'title' => 'استخراج محصولات', 'icon' => '🔎', 'file' => EXTRACT_PROGRESS_FILE,
            'stop' => 'extract_stop', 'tab' => 'استخراج',
            'pane' => 'start', 'el' => 'extractProgress', 'resume' => 'action=backend_extract',
            'stat' => function (array $p): array {
                return ['استخراج' => (int)($p['extracted'] ?? 0), 'تازه' => (int)($p['new'] ?? 0),
                        'تغییرِ قیمت' => (int)($p['price_changed'] ?? 0), 'حذف‌شده' => (int)($p['removed'] ?? 0)];
            },
        ],
        'dedup' => [
            'title' => 'حذف/بایگانیِ محصولات تکراری', 'icon' => '🧹', 'file' => DEDUP_PROGRESS_FILE,
            'stop' => 'dedup_stop', 'tab' => 'ابزارها',
            /* یک کارِ dedup هست ولی دو خانه دارد (ووکامرس و باسلام) — کدام
               باز شود از خودِ فایلِ پیشرفت (target) خوانده می‌شود. */
            'pane' => 'send', 'open' => 'dedupOpenLast', 'resume' => 'dedup_start=1',
            'stat' => function (array $p): array {
                return ['گروه' => (int)($p['groups'] ?? 0), 'تکراری' => (int)($p['dups'] ?? 0),
                        'حذف‌شده' => (int)($p['deleted'] ?? 0), 'ناموفق' => (int)($p['failed'] ?? 0)];
            },
        ],
