}



/* =====================================================================
 *  v10.113: ماتریس مقایسه — کاملاً سرورساید + جاب پس‌زمینه + دوره‌ای
 *  ساخت: ?sync_matrix_start=1  (یا POST action=sync_matrix_start)
 *  وضعیت: ?sync_matrix_status=1
 *  خواندن صفحه‌بندی‌شده از نتیجهٔ ذخیره‌شده: ?sync_matrix=1&page=&per_page=
 *  اجرا داخل cron همراه reconAutoTick وقتی build_matrix روشن است
 * ===================================================================== */
function matrixCollectSuffixes(): array {
    $sfx = [];
    foreach (loadProfiles() as $p) {
        $s = trim((string)($p['titleSuffix'] ?? ''));
        if ($s !== '') $sfx[$s] = true;
    }
    return array_keys($sfx);
}
/** آیا عنوان شناسهٔ صریح محصول مثل «(کد:۱۲۳)» دارد؟
 * عنوان مقصد ممکن است پس از ۱۲۰ نویسه بریده شود؛ بنابراین این تابع قالب کامل
 * را با ارقام فارسی/عربی، فاصله و نویسه‌های جهت‌دهی Unicode تشخیص می‌دهد و
 * caller برای عنوان بریده‌شده از عنوان کامل ردیف نیز fallback می‌گیرد. */
function matrixTitleHasCode(string $title): bool {
    $t = function_exists('persianToEnglish') ? persianToEnglish(trim($title)) : trim($title);
    $t=(string)preg_replace('~[\p{Cf}\x{00A0}\x{2007}\x{202F}]~u','',$t);
    $t=strtr($t,['（'=>'(', '）'=>')', '﹙'=>'(', '﹚'=>')']);
    if((bool)preg_match('~\(\s*(?:کد|کُد|code|sku)\s*[:：]\s*[^()\s][^()]*?\s*\)~iu',$t))return true;
    /* Basalam may truncate its 120-character title at any byte of the suffix,
       e.g. "...(ک", "...(کد:" or "...(cod". Such a terminal fragment is
       coded/indeterminate, never genuinely uncoded miscellaneous inventory. */
    return (bool)preg_match('~\(\s*(?:ک(?:ُ?د)?|c(?:o(?:d(?:e)?)?)?|s(?:k(?:u)?)?)\s*[:：]?\s*[0-9]*\s*$~iu',$t);
}
function matrixRowHasCode(array $r): bool {
    if (matrixTitleHasCode((string)($r['title'] ?? ''))) return true;
    if (is_array($r['woo'] ?? null) && matrixTitleHasCode((string)($r['woo']['title'] ?? ''))) return true;
    foreach ((array)($r['shops'] ?? []) as $cell) {
        if (is_array($cell) && matrixTitleHasCode((string)($cell['title'] ?? ''))) return true;
    }
    return false;
}
function matrixBareTitle(string $title, array $suffixes = []): string {
    $t = trim($title);
    usort($suffixes, function ($a, $b) {
        return mb_strlen((string)$b) <=> mb_strlen((string)$a);
    });
    foreach ($suffixes as $s) {
        $s = trim((string)$s);
        if ($s === '') continue;
        if (function_exists('mb_substr') && mb_strlen($t) >= mb_strlen($s)
            && mb_substr($t, -mb_strlen($s)) === $s) {
            $t = trim(mb_substr($t, 0, mb_strlen($t) - mb_strlen($s)));
        } elseif (strlen($t) >= strlen($s) && substr($t, -strlen($s)) === $s) {
            $t = trim(substr($t, 0, -strlen($s)));
        }
    }
    return reconNormTitle($t);
}
function matrixPriceTone(int $src, int $dst): string {
    if ($src <= 0 && $dst <= 0) return 'na';
    if ($src <= 0) return 'no_src';
    if ($dst <= 0) return 'missing_dst';
    if ($src === $dst) return 'ok';
    $diff = abs($src - $dst) / max($src, 1);
    if ($diff <= 0.01) return 'ok';
    if ($diff <= 0.05) return 'warn';
    return 'bad';
}
/** v10.338: checkpoint بزرگ ماتریس از progress/API جداست. progress فقط metadata
 * کوچک دارد؛ child بعدی نسخهٔ gzip را مستقیم از دیسک hydrate می‌کند. */
function matrixCheckpointSave(array $cp): array {
    $json=json_encode($cp,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    if($json===false)return ['_external'=>true,'error'=>'encode_failed'];
    $blob=function_exists('gzencode')?gzencode($json,3):$json;if($blob===false)$blob=$json;
    $tmp=SYNC_MATRIX_CHECKPOINT_FILE.'.tmp.'.getmypid();$ok=@file_put_contents($tmp,$blob,LOCK_EX)!==false;
    if($ok){$ok=@rename($tmp,SYNC_MATRIX_CHECKPOINT_FILE);if(!$ok){$ok=@copy($tmp,SYNC_MATRIX_CHECKPOINT_FILE);@unlink($tmp);}}else @unlink($tmp);
    return ['_external'=>true,'ok'=>$ok,'file'=>basename(SYNC_MATRIX_CHECKPOINT_FILE),'bytes'=>$ok?(int)@filesize(SYNC_MATRIX_CHECKPOINT_FILE):0,
        'phase'=>(string)($cp['phase']??''),'started_at'=>(int)($cp['started_at']??0),
        'profile_rows'=>count((array)($cp['profile_rows']??[])),'woo_page'=>(int)($cp['woo_page']??0),
        'shop_pages'=>(array)($cp['shop_pages']??[]),'selected_destinations'=>(array)($cp['selected_destinations']??[])];
}
function matrixCheckpointLoad(): ?array {
    if(!is_file(SYNC_MATRIX_CHECKPOINT_FILE))return null;$blob=(string)@file_get_contents(SYNC_MATRIX_CHECKPOINT_FILE);if($blob==='')return null;
    if(substr($blob,0,2)==="\x1f\x8b"&&function_exists('gzdecode')){$raw=@gzdecode($blob);if($raw!==false)$blob=$raw;}
    $cp=json_decode($blob,true);return is_array($cp)?$cp:null;
}
function matrixProgress(array $patch): void {
    if(array_key_exists('checkpoint',$patch)){
        if(is_array($patch['checkpoint'])&&empty($patch['checkpoint']['_external']))$patch['checkpoint']=matrixCheckpointSave($patch['checkpoint']);
        elseif($patch['checkpoint']===null)@unlink(SYNC_MATRIX_CHECKPOINT_FILE);
    }
    $cur = localTaskStateRead(SYNC_MATRIX_PROGRESS_FILE, []);
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) {
            $log[] = ['t' => time(), 'm' => (string)$l];
        }
        if (count($log) > 120) $log = array_slice($log, -120);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok', 'stop_requested', 'yielded'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log;
    $cur['ts'] = time();
    writeProgress(SYNC_MATRIX_PROGRESS_FILE, $cur);
}
function matrixStopRequested(): bool {
    if (!is_file(SYNC_MATRIX_STOP_FILE)) return false;
    $runAt = (float)($GLOBALS['_matrixRunStartedAt'] ?? 0);
    if ($runAt <= 0) return true;
    $sig = json_decode((string)@file_get_contents(SYNC_MATRIX_STOP_FILE), true);
    $stopAt = (float)($sig['at'] ?? 0);
    /* signal قدیمی برای worker یتیم است؛ اجرای تازه آن را مصرف نمی‌کند. */
    return $stopAt <= 0 || $stopAt > $runAt;
}
/** The driver is read on every loop. Cron-driving removes the deadline; a
 * live switch back to worker mode makes the already-expired deadline yield. */
function matrixSliceExpired(): bool {
    $driver=matrixExecutionDecision();
    if(empty($driver['can_run']))return true;
    if(!empty($driver['accelerated']))return false;
    $d = (float)($GLOBALS['_matrixSliceDeadline'] ?? 0);
    return $d > 0 && microtime(true) >= $d;
}
function matrixStopClear(): void { @unlink(SYNC_MATRIX_STOP_FILE); }
/** توقف سختِ runner پس از ثبت signal/state. برای child ماتریس یا request اصلاح
 * است؛ PID daemon مشترک هرگز به‌عنوان runner ثبت نمی‌شود. */
function matrixTerminateRunner(array $state): array {
    $pid=(int)($state['runner_pid']??0);$self=(int)@getmypid();
    $out=['pid'=>$pid,'signalled'=>false,'killed'=>false];
    if($pid<=1||$pid===$self||!function_exists('posix_kill'))return $out;
    $alive=@posix_kill($pid,0);if(!$alive)return $out;
    $out['signalled']=@posix_kill($pid,defined('SIGTERM')?SIGTERM:15);usleep(250000);
    if(@posix_kill($pid,0))$out['killed']=@posix_kill($pid,defined('SIGKILL')?SIGKILL:9);
    return $out;
}

function matrixProgressRead(bool $hydrateCheckpoint=true): array {
    $s=localTaskStateRead(SYNC_MATRIX_PROGRESS_FILE, []);
    if($hydrateCheckpoint&&is_array($s['checkpoint']??null)&&!empty($s['checkpoint']['_external'])){
        $cp=matrixCheckpointLoad();if($cp!==null)$s['checkpoint']=$cp;
        else{$s['checkpoint_error']='external_checkpoint_missing_or_invalid';$s['checkpoint']=null;}
    }
    return $s;
}
/** مقصدهای قابل انتخاب ماتریس: woo و bsl:<vendor_id>. null یعنی سازگاری
 * با نسخه‌های قبلی و انتخاب همه؛ آرایهٔ خالی عمداً هیچ مقصدی است. */
function matrixNormalizeDestinations($raw, ?array $cn=null): array {
    $cn=$cn??loadConnections();$valid=['woo'=>true];
    foreach((function_exists('bslAllShops')?bslAllShops($cn):[]) as $sh){$vid=(int)($sh['vendor_id']??0);if($vid>0)$valid['bsl:'.$vid]=true;}
    if($raw===null)return array_keys($valid);
    if(is_string($raw)){$decoded=json_decode($raw,true);$raw=is_array($decoded)?$decoded:preg_split('/\s*,\s*/',trim($raw),-1,PREG_SPLIT_NO_EMPTY);}
    $out=[];foreach((array)$raw as $key){$key=trim((string)$key);if(isset($valid[$key]))$out[$key]=true;}
    return array_keys($out);
}
/** v10.264: checkpointهای نسخه‌های قبل raw و map را همزمان نگه می‌داشتند و
 * هر resume شناسهٔ Woo یکسان را دوباره به woo_extra می‌افزود. این مهاجرت
 * درجا checkpoint موجود را بدون واکشی شبکه کوچک و idempotent می‌کند. */
function matrixCompactCheckpoint(array &$cp): array {
    if(!is_array($cp['profile_rows']??null))$cp['profile_rows']=[];$rows=&$cp['profile_rows'];$mappedWoo=0;$removedExtra=0;
    foreach($rows as &$r){if(!is_array($r))continue;$primary=(int)($r['woo']['id']??0);if($primary>0)$mappedWoo++;$clean=[];$seen=[];
        foreach((array)($r['woo_extra']??[])as$ex){$id=(int)($ex['id']??0);if($id<=0||$id===$primary||isset($seen[$id])){$removedExtra++;continue;}$seen[$id]=true;$clean[]=$ex;}
        if($clean){$r['woo_extra']=$clean;$r['woo_dup']=true;}else{unset($r['woo_extra'],$r['woo_dup']);}
    }unset($r);$droppedWoo=0;$droppedShops=0;
    if(!empty($cp['woo_done'])&&$mappedWoo>0){$droppedWoo=count((array)($cp['woo_rows']??[]));$cp['woo_rows']=[];if((string)($cp['phase']??'')==='woo_fetch')$cp['phase']='bsl_fetch';}
    /* raw کاملِ غرفه فقط وقتی حذف شود که واقعاً داخل profile_rows map شده.
       حذف صرفاً بر اساس shop_done در resume، مقصد را خالی نشان می‌داد. */
    foreach((array)($cp['shop_done']??[])as$vid=>$done){
        if(!$done||empty($cp['shop_rows'][(string)$vid]))continue;$mappedShop=false;
        foreach($rows as $mappedRow)if(!empty($mappedRow['shops'][(int)$vid])){$mappedShop=true;break;}
        if($mappedShop){$droppedShops+=count((array)$cp['shop_rows'][(string)$vid]);$cp['shop_rows'][(string)$vid]=[];}
    }
    return ['mapped_woo'=>$mappedWoo,'removed_extra'=>$removedExtra,'dropped_woo_raw'=>$droppedWoo,'dropped_shop_raw'=>$droppedShops];
}

function matrixPricingFingerprint(?array $profiles=null, ?array $cn=null): string {
    $profiles=$profiles??loadProfiles();$cn=$cn??loadConnections();$parts=['matrix-pricing-schema-v4-live-shop-rounding','matrix-pricing-schema-v5-global-dest-all-shops'];
    foreach($profiles as $pk=>$p){if(!is_array($p))continue;$parts[]=(string)$pk.'|'.(string)($p['priceMode']??'none').'|'.(string)($p['priceVal']??0).'|'.(string)($p['roundPrice']??0);}
    sort($parts,SORT_STRING);$parts[]='dest|'.shopPricingSignature($cn);
    return hash('sha256',implode("\n",$parts));
}

/** بدون واکشی دوبارهٔ مقصدها، قیمت‌های مورد انتظار و وضعیت تمام ردیف‌ها را
 * با آخرین ضرایب پروفایل/ووکامرس/باسلام/غرفه‌ها بازسازی می‌کند. */
function matrixRefreshExpectedPrices(string $reason='settings_save'): array {
    if(!is_file(SYNC_MATRIX_RESULT_FILE))return ['ok'=>true,'changed'=>false,'reason'=>'no_result'];
    $run=matrixProgressRead();$fixRun=function_exists('matrixFixProgressRead')?matrixFixProgressRead():[];
    if(!empty($run['running'])||!empty($fixRun['running']))return ['ok'=>true,'changed'=>false,'reason'=>!empty($run['running'])?'matrix_running':'fix_running'];
    $lf=@fopen(__DIR__.'/.sync_matrix_reprice.lock','c');
    if(!$lf||!@flock($lf,LOCK_EX|LOCK_NB)){if($lf)@fclose($lf);return ['ok'=>true,'changed'=>false,'reason'=>'busy'];}
    try{
        $data=matrixResultLoad();if(!$data||!is_array($data['rows']??null))return ['ok'=>true,'changed'=>false,'reason'=>'empty'];
        $profiles=loadProfiles();$cn=loadConnections();$wooCfg=destPriceCfg($cn,'woocommerce');$bslCfg=destPriceCfg($cn,'basalam');
        $repriceSelected=matrixNormalizeDestinations($data['selected_destinations']??null,$cn);$repriceSet=array_fill_keys($repriceSelected,true);$repriceWoo=isset($repriceSet['woo']);
        $shopList=function_exists('bslAllShops')?bslAllShops($cn):[];$shopBy=[];$shopsMeta=[];
        foreach($shopList as $sh){if(!is_array($sh))continue;$vid=(int)($sh['vendor_id']??0);if($vid<=0||!isset($repriceSet['bsl:'.$vid]))continue;$shopBy[$vid]=$sh;$shopsMeta[]=['vendor_id'=>$vid,'name'=>(string)($sh['shop_name']??$sh['name']??('#'.$vid)),'is_default'=>!empty($sh['is_default'])];}
        $sum=['total'=>0,'ok'=>0,'price_mismatch'=>0,'missing_woo'=>0,'missing_bsl'=>0,'extra_woo'=>0,'extra_bsl'=>0,'dup_profile'=>0,'dup_woo'=>0,'dup_bsl'=>0,'in_all'=>0,'only_profile'=>0,'only_dest'=>0];$changed=0;
        foreach($data['rows'] as &$r){
            if(!is_array($r)||!empty($r['is_report'])||str_starts_with((string)($r['bare']??''),'__report_'))continue;
            $before=json_encode([(int)($r['profile_price']??0),(int)($r['woo_expect']??0),(int)($r['bsl_expect']??0),(array)($r['shop_expect']??[]),(string)($r['status']??''),(array)($r['flags']??[])]);
            $pk=(string)($r['profile_key']??'');$profile=is_array($profiles[$pk]??null)?$profiles[$pk]:null;$hasProf=(int)($r['profile_hits']??0)>0;
            if($hasProf&&$profile){$raw=(int)($r['src_price']??0);$pp=profileFinalPrice($profile,(string)$raw);$r['profile_price']=$pp;$r['woo_expect']=$pp>0?destAdjustPrice($pp,$wooCfg):0;$r['bsl_expect']=$pp>0?destAdjustPrice($pp,$bslCfg):0;}
            $hasWoo=$repriceWoo&&!empty($r['woo']);$wooTone=$repriceWoo?($hasProf&&$hasWoo?matrixPriceTone((int)($r['woo_expect']??0),(int)($r['woo']['price']??0)):($hasProf?'missing_dst':($hasWoo?'extra':'na'))):'na';
            $r['woo_tone']=$wooTone;$shopCount=0;$shopOk=0;$shopBad=0;$shopMiss=0;$dupBsl=false;
            foreach($shopsMeta as $sm){
                $vid=(int)$sm['vendor_id'];
                $cell=is_array($r['shops'][$vid]??null)?$r['shops'][$vid]:(is_array($r['shops'][(string)$vid]??null)?$r['shops'][(string)$vid]:null);
                $base=(int)($r['bsl_expect']??0);$pp=(int)($r['profile_price']??0);$raw=(string)($r['src_price']??'0');$expect=$base>0?$base:$pp;
                /* v10.296: انتظار هر غرفه حتی وقتی محصول هنوز در آن مقصد نیست
                   باید ساخته شود؛ وگرنه job ارسال missing به expect عمومی
                   باسلام برمی‌گشت و ضریب غرفهٔ غیرپیش‌فرض ناپدید می‌شد. */
                if($hasProf&&isset($shopBy[$vid])){
                    $adj=($profile&&extractPriceNum($raw)>0)
                        ?bslShopPriceForProfile($profile,$raw,$shopBy[$vid],(int)($bslCfg['round']??0))
                        :bslShopPriceFor($expect,$shopBy[$vid],(int)($bslCfg['round']??0));
                    if((int)($adj['price']??0)>0)$expect=(int)$adj['price'];
                    $r['shop_expect'][$vid]=$expect;
                }
                if($cell){
                    $shopCount++;$cell['expect']=$expect;$cell['tone']=matrixPriceTone($expect,(int)($cell['price']??0));$cell['shop_name']=(string)$sm['name'];
                    if($cell['tone']==='ok')$shopOk++;elseif(in_array($cell['tone'],['bad','warn'],true))$shopBad++;
                    if(!empty($cell['dup']))$dupBsl=true;$r['shops'][$vid]=$cell;
                }elseif($hasProf)$shopMiss++;
            }
            $flags=array_values(array_filter(array_map('strval',(array)($r['flags']??[])),static function($f){return str_starts_with($f,'dup_');}));
            if(matrixProfileDuplicateCount($r)>0){$flags[]='dup_profile';$sum['dup_profile']++;}if(!empty($r['woo_dup'])){$flags[]='dup_woo';$sum['dup_woo']++;}if($dupBsl){$flags[]='dup_bsl';$sum['dup_bsl']++;}
            if($wooTone==='missing_dst'){$flags[]='missing_woo';$sum['missing_woo']++;}if($wooTone==='extra'){$flags[]='extra_woo';$sum['extra_woo']++;}if(in_array($wooTone,['bad','warn'],true)||$shopBad>0){$flags[]='price_mismatch';$sum['price_mismatch']++;}if($shopMiss>0&&$hasProf){$flags[]='missing_bsl';$sum['missing_bsl']++;}
            $r['flags']=array_values(array_unique($flags));$r['shop_ok']=$shopOk;$r['shop_bad']=$shopBad;$r['shop_miss']=$shopMiss;
            $wooOk=!$repriceWoo||($hasWoo&&$wooTone==='ok');$hasAnySelectedDest=($repriceWoo&&$hasWoo)||$shopCount>0;
            if($hasProf&&$wooOk&&$shopMiss===0&&$shopBad===0){$r['status']='ok';$sum['ok']++;$sum['in_all']++;}
            elseif($hasProf&&!$hasAnySelectedDest){$r['status']='only_profile';$sum['only_profile']++;}
            elseif(!$hasProf){$r['status']='only_dest';$sum['only_dest']++;}elseif(($repriceWoo&&in_array($wooTone,['bad','warn'],true))||$shopBad>0)$r['status']='mismatch';elseif(($repriceWoo&&$wooTone==='missing_dst')||$shopMiss>0)$r['status']='missing';else$r['status']='partial';
            $sum['total']++;$after=json_encode([(int)($r['profile_price']??0),(int)($r['woo_expect']??0),(int)($r['bsl_expect']??0),(array)($r['shop_expect']??[]),(string)($r['status']??''),(array)($r['flags']??[])]);if($before!==$after)$changed++;
        }unset($r);
        $order=['mismatch'=>0,'missing'=>1,'only_profile'=>2,'only_dest'=>3,'partial'=>4,'ok'=>5];
        usort($data['rows'],static function($a,$b)use($order){$ar=!empty($a['is_report'])||str_starts_with((string)($a['bare']??''),'__report_');$br=!empty($b['is_report'])||str_starts_with((string)($b['bare']??''),'__report_');if($ar!==$br)return$ar?1:-1;$oa=$order[(string)($a['status']??'')]??9;$ob=$order[(string)($b['status']??'')]??9;return$oa!==$ob?$oa<=>$ob:strcmp((string)($a['bare']??''),(string)($b['bare']??''));});
        $data['summary']=$sum;$data['woo_cfg']=$wooCfg;$data['bsl_cfg']=$bslCfg;$data['shops']=$shopsMeta;$data['pricing_signature']=matrixPricingFingerprint($profiles,$cn);$data['repriced_at']=time();$data['repriced_reason']=$reason;
        $ok=matrixResultSave($data);if($ok)matrixProgress(['pricing_refreshed_at'=>time(),'pricing_refreshed_rows'=>$changed,'log_add'=>['⚡ ضرایب تازه فوراً روی جدول اعمال شد: '.$changed.' ردیف']]);
        return ['ok'=>$ok,'changed'=>$ok,'rows'=>$changed,'signature'=>$data['pricing_signature']];
    }finally{@flock($lf,LOCK_UN);@fclose($lf);}
}

function matrixResultLoad(): array {
    if (!is_file(SYNC_MATRIX_RESULT_FILE)) return [];
    $d = json_decode((string)@file_get_contents(SYNC_MATRIX_RESULT_FILE), true);
    return is_array($d) ? $d : [];
}
function matrixResultSave(array $data): bool {
    $data['generated_at'] = $data['generated_at'] ?? time();
    $data['version'] = APP_VERSION;
    $json = json_encode($data, JSON_UNESCAPED_UNICODE);
    if ($json === false) return false;
    // فایل می‌تواند بزرگ باشد
    return false !== @file_put_contents(SYNC_MATRIX_RESULT_FILE, $json, LOCK_EX);
}

/** v10.247: از checkpoint جاری یک snapshot قابل‌نمایش می‌سازد. این فایل
 * نتیجهٔ نهایی را بازنویسی نمی‌کند و فقط برای سوییچ «پر شدن زنده» است. */
function matrixLiveSnapshot(array $cp, array $cn, string $source = 'manual'): bool {
    $rows = is_array($cp['profile_rows'] ?? null) ? $cp['profile_rows'] : [];
    $codedOnly = false;
    $suffixes = matrixCollectSuffixes();
    $liveSelected=matrixNormalizeDestinations($cp['selected_destinations']??null,$cn);$liveSet=array_fill_keys($liveSelected,true);$liveWoo=isset($liveSet['woo']);
    $shops = function_exists('bslAllShops') ? bslAllShops($cn) : [];
    $shopsMeta = [];
    foreach($shops as $sh){if(!is_array($sh))continue;$vid=(int)($sh['vendor_id']??0);if($vid<=0||!isset($liveSet['bsl:'.$vid]))continue;
        $shopsMeta[]=['vendor_id'=>$vid,'name'=>(string)($sh['shop_name']??($sh['name']??('غرفه '.$vid))),
            'is_default'=>!empty($sh['is_default'])];}
    $ensure = static function(string $bare,string $title) use (&$rows): void {
        if(isset($rows[$bare]))return;
        $rows[$bare]=['bare'=>$bare,'title'=>$title,'key'=>'','profile'=>'','profile_key'=>'','src_price'=>0,
            'profile_price'=>0,'woo_expect'=>0,'bsl_expect'=>0,'profile_hits'=>0,'woo'=>null,'shops'=>[]];
    };
    foreach(($liveWoo?(array)($cp['woo_rows']??[]):[]) as $wr){if(!is_array($wr))continue;
        if($codedOnly&&!matrixTitleHasCode((string)($wr['title']??'')))continue;
        $bare=matrixBareTitle((string)($wr['title']??''),$suffixes);if($bare==='')continue;$ensure($bare,(string)($wr['title']??''));
        $rows[$bare]['woo']=['id'=>(int)($wr['id']??0),'title'=>(string)($wr['title']??''),
            'price'=>(int)($wr['price']??0),'status'=>(string)($wr['status']??'')];}
    foreach((array)($cp['shop_rows']??[]) as $vid=>$remote){if(!isset($liveSet['bsl:'.(int)$vid]))continue;foreach((array)$remote as $br){if(!is_array($br))continue;
        if($codedOnly&&!matrixTitleHasCode((string)($br['title']??'')))continue;
        $bare=matrixBareTitle((string)($br['title']??''),$suffixes);if($bare==='')continue;$ensure($bare,(string)($br['title']??''));
        $expect=(int)($rows[$bare]['bsl_expect']??0);$actual=(int)($br['price_toman']??0);
        $rows[$bare]['shops'][(int)$vid]=['id'=>(int)($br['id']??0),'title'=>(string)($br['title']??''),
            'price'=>$actual,'price_rial'=>(int)($br['price']??0),'status'=>(int)($br['status']??0),
            'stock'=>(int)($br['stock']??0),'expect'=>$expect,'tone'=>matrixPriceTone($expect,$actual)];}}
    $outRows=[];$sum=['total'=>0,'ok'=>0,'price_mismatch'=>0,'missing_woo'=>0,'missing_bsl'=>0,
        'extra_woo'=>0,'extra_bsl'=>0,'dup_profile'=>0,'dup_woo'=>0,'dup_bsl'=>0,'in_all'=>0,'only_profile'=>0];
    foreach($rows as $r){if(!is_array($r))continue;$hasProf=(int)($r['profile_hits']??0)>0;$hasWoo=!empty($r['woo']);
        $wooTone=($hasProf&&$hasWoo)?matrixPriceTone((int)($r['woo_expect']??0),(int)($r['woo']['price']??0)):'na';
        $bad=$wooTone==='bad'||$wooTone==='warn';foreach((array)($r['shops']??[]) as $sc){$t=(string)($sc['tone']??'na');if($t==='bad'||$t==='warn')$bad=true;}
        $r['woo_tone']=$wooTone;$r['flags']=$bad?['price_mismatch']:[];
        $r['status']=$bad?'mismatch':($hasProf&&($hasWoo||!empty($r['shops']))?'partial':($hasProf?'only_profile':'only_dest'));
        if($bad)$sum['price_mismatch']++;if($r['status']==='only_profile')$sum['only_profile']++;
        $sum['total']++;$outRows[]=$r;}
    usort($outRows,static function($a,$b){return strcmp((string)($a['bare']??''),(string)($b['bare']??''));});
    $data=['ok'=>true,'live_partial'=>true,'generated_at'=>time(),'source'=>$source,'coded_only'=>$codedOnly,'selected_destinations'=>$liveSelected,'shops'=>$shopsMeta,
        'woo_cfg'=>destPriceCfg($cn,'woocommerce'),'bsl_cfg'=>destPriceCfg($cn,'basalam'),'summary'=>$sum,
        'rows'=>$outRows,'woo_count'=>count((array)($cp['woo_rows']??[])),'row_count'=>count($outRows)];
    $json=json_encode($data,JSON_UNESCAPED_UNICODE);if($json===false)return false;
    return false!==@file_put_contents(SYNC_MATRIX_LIVE_FILE,$json,LOCK_EX);
}

/**
 * v10.244: واکشی یک/چند دور از همهٔ مقصدها به‌صورت واقعی و هم‌زمان.
 * در هر دور یک صفحهٔ Woo و یک صفحه از هر غرفه داخل یک curl_multi می‌رود.
 */
function matrixFetchDestinationsParallel(array $cn, array $shops,
        array &$wooRows, bool &$wooDone, int &$wooPage, bool &$wooComplete,
        array &$shopRows, array &$shopPages, array &$shopDone, bool $includeWoo=true): array {
    foreach(['curl_multi_init','curl_multi_add_handle','curl_multi_exec','curl_multi_select','curl_multi_getcontent','curl_multi_remove_handle','curl_multi_close'] as $mf)
        if(!function_exists($mf))return ['ok'=>false,'fallback'=>true,'error'=>$mf.' unavailable'];
    $w = is_array($cn['woocommerce'] ?? null) ? $cn['woocommerce'] : [];
    $round = 0; $requests = 0;
    while (!matrixSliceExpired()) {
        if (matrixStopRequested()) return ['ok' => true, 'stopped' => true, 'rounds' => $round, 'requests' => $requests];
        /* round تازه را در چند ثانیهٔ آخر شروع نکن؛ یک API کند می‌تواند تا
           ۱۵ ثانیه طول بکشد و از سقف رایج ۳۰ ثانیهٔ proxy عبور کند. */
        $deadline=(float)($GLOBALS['_matrixSliceDeadline']??0);
        if($round>0&&$deadline>0&&($deadline-microtime(true))<5.0)break;
        $jobs = [];
        if ($includeWoo && !$wooDone && trim((string)($w['store_url'] ?? '')) !== ''
            && trim((string)($w['consumer_key'] ?? '')) !== '') {
            $cur = reconFetchCursorLoad('woo', 0);
            if (count((array)($cur['rows'] ?? [])) > count($wooRows)) $wooRows = (array)$cur['rows'];
            $page = max(1, (int)($cur['page'] ?? 0) + 1);
            $url = rtrim((string)$w['store_url'], '/') . '/wp-json/wc/v3/products?per_page=100&status=any&page=' . $page;
            $ch = curl_init($url);
            /* v10.245: درخواست HTTP دستی نباید از پنجرهٔ کوتاه worker بیرون بزند؛
               در cli-server پاسخ اولیه تا پایان PHP واقعاً تحویل proxy نمی‌شود و
               timeout بلند، به 500 دروازه و قفل ظاهری رابط منجر می‌شد. */
            curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>1, CURLOPT_FOLLOWLOCATION=>1,
                CURLOPT_CONNECTTIMEOUT=>6, CURLOPT_TIMEOUT=>15, CURLOPT_SSL_VERIFYPEER=>0,
                CURLOPT_SSL_VERIFYHOST=>0, CURLOPT_USERPWD=>(string)$w['consumer_key'].':'.(string)($w['consumer_secret']??''),
                CURLOPT_HTTPHEADER=>['Accept: application/json']]);
            $jobs[] = ['kind'=>'woo','page'=>$page,'ch'=>$ch];
        } elseif ($includeWoo && !$wooDone) {
            return ['ok'=>false,'error'=>'تنظیمات API ووکامرس ناقص است'];
        }
        foreach ($shops as $sh) {
            if (!is_array($sh)) continue;
            $vid=(int)($sh['vendor_id']??0); $tk=trim((string)($sh['token']??($cn['basalam']['token']??'')));
            if ($vid<=0 || $tk==='' || !empty($shopDone[(string)$vid])) continue;
            $cur = reconFetchCursorLoad('bsl_active', $vid);
            if (count((array)($cur['rows'] ?? [])) > count((array)($shopRows[(string)$vid] ?? [])))
                $shopRows[(string)$vid] = (array)$cur['rows'];
            $page=max(1,(int)($cur['page']??0)+1);
            $ep='vendors/'.$vid.'/products?page='.$page.'&per_page=100'.bslActiveStatusQuery();
            $net=bslNetCfg($cn); $mode=!empty($net['indirect'])?(string)($net['mode']??'direct'):'direct';
            $ch=curl_init(); $bslOpts=bslCurlOpts(bslApiBase().$ep,$tk,'GET',null,false,$net,$mode);
            /* همان سقف کوتاه Woo برای جلوگیری از 500/worker hang. گزینه‌ها اینجا
               override می‌شوند تا رفتار عمومی درخواست‌های باسلام تغییر نکند. */
            $bslOpts[CURLOPT_CONNECTTIMEOUT]=6; $bslOpts[CURLOPT_TIMEOUT]=15;
            curl_setopt_array($ch,$bslOpts);
            $jobs[]=['kind'=>'bsl','vid'=>$vid,'page'=>$page,'ch'=>$ch];
        }
        if (!$jobs) return ['ok'=>true,'complete'=>true,'rounds'=>$round,'requests'=>$requests];
        $mh=curl_multi_init(); foreach($jobs as $j) curl_multi_add_handle($mh,$j['ch']);
        /* v10.246: روی libcurl قدیمی، curl_multi_exec می‌تواند
           CURLM_CALL_MULTI_PERFORM برگرداند؛ این خطا نیست و باید فوراً دوباره
           صدا زده شود. حلقهٔ قبلی همان‌جا خارج می‌شد و handle ناتمام را به شکل
           HTTP 0 با error خالی گزارش می‌کرد. select=-1 هم با مکث کوتاه retry می‌شود. */
        $running=0; $st=CURLM_OK;
        do {
            do {
                $st=curl_multi_exec($mh,$running);
            } while(defined('CURLM_CALL_MULTI_PERFORM') && $st===CURLM_CALL_MULTI_PERFORM);
            if($st!==CURLM_OK) break;
            if($running>0){$selected=curl_multi_select($mh,.35);if($selected===-1)usleep(10000);}
        } while($running>0);
        $round++; $requests += count($jobs); $failures=[];
        foreach ($jobs as $j) {
            $ch=$j['ch']; $raw=(string)curl_multi_getcontent($ch); $err=(string)curl_error($ch);
            $code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE); $body=@json_decode($raw,true);
            curl_multi_remove_handle($mh,$ch); curl_close($ch);
            if ($code<200 || $code>=300 || $err!=='' || $st!==CURLM_OK) {
                $multiMsg=$st!==CURLM_OK ? ('curl_multi '.(function_exists('curl_multi_strerror')?curl_multi_strerror($st):(string)$st)) : '';
                $why=trim($err.' '.$multiMsg);
                if($why==='')$why='پاسخ HTTP دریافت نشد (اتصال یا libcurl ناتمام)';
                $failures[]=($j['kind']==='woo'?'Woo':'Basalam #'.(int)($j['vid']??0)).' HTTP '.$code.' — '.$why;
                continue;
            }
            if ($j['kind']==='woo') {
                $batch=is_array($body)?$body:[]; $pageRows=[];
                foreach($batch as $pr) if(is_array($pr) && trim((string)($pr['name']??''))!=='')
                    $pageRows[]=['id'=>(int)($pr['id']??0),'title'=>(string)$pr['name'],
                        'price'=>(int)preg_replace('~\D~','',(string)($pr['regular_price']??'0')),
                        'status'=>(string)($pr['status']??''),'via'=>'api_parallel'];
                if($pageRows){$wooRows=array_merge($wooRows,$pageRows);reconFetchCursorAppend('woo',0,(int)$j['page'],$pageRows);}
                $wooPage=(int)$j['page'];
                if(count($batch)<100){$wooDone=true;$wooComplete=true;}
                $line='⚡ موازی · Woo صفحه '.$wooPage.': '.count($batch).' (مجموع '.count($wooRows).')';
                matrixProgress(['phase'=>'parallel_fetch','woo_page'=>$wooPage,'woo_fetched'=>count($wooRows),'log_add'=>[$line]]);
            } else {
                $vid=(int)$j['vid']; $batch=is_array($body['data']??null)?$body['data']:[]; $pageRows=[];
                foreach($batch as $pr){if(!is_array($pr))continue;$rev=$pr['revision']['data']??[];
                    $name=trim((string)($pr['title']??($pr['name']??($rev['title']??''))));if($name==='')continue;
                    $rial=(int)($rev['primary_price']??($pr['primary_price']??0));
                    $pageRows[]=['id'=>(int)($pr['id']??0),'title'=>$name,'price'=>$rial,'price_toman'=>(int)round($rial/10),
                        'status'=>(int)(is_array($pr['status']??null)?($pr['status']['value']??0):($pr['status']??0)),
                        'stock'=>(int)($rev['stock']??($rev['inventory']??($pr['stock']??0)))];}
                if(!isset($shopRows[(string)$vid]))$shopRows[(string)$vid]=[];
                if($pageRows){$shopRows[(string)$vid]=array_merge($shopRows[(string)$vid],$pageRows);reconFetchCursorAppend('bsl_active',$vid,(int)$j['page'],$pageRows);}
                $shopPages[(string)$vid]=(int)$j['page']; if(count($batch)<100)$shopDone[(string)$vid]=true;
                matrixProgress(['phase'=>'parallel_fetch','vendor_id'=>$vid,'page'=>(int)$j['page'],
                    'log_add'=>['⚡ موازی · غرفه #'.$vid.' صفحه '.(int)$j['page'].': '.count($batch).' (مجموع '.count($shopRows[(string)$vid]).')']]);
            }
        }
        curl_multi_close($mh);
        /* موفق‌های همین round حتی اگر مقصد دیگری شکست خورد checkpoint شدند؛
           سپس خطای دقیقِ نخست برگردانده می‌شود تا کاربر صفحه‌های موفق را از دست ندهد. */
        if($failures)return ['ok'=>false,'error'=>$failures[0],
            'errors'=>$failures,'rounds'=>$round,'requests'=>$requests];
        /* v10.254: دورهای بعدی تا پایان پنجرهٔ قابل‌تنظیم ادامه دارند. timeout
           هر درخواست شبکه همچنان محدود است و cursor هر صفحه مستقل ذخیره می‌شود. */
        $allDone=!$includeWoo||$wooDone;
        foreach($shops as $doneShop){
            if(!is_array($doneShop))continue;
            $doneVid=(int)($doneShop['vendor_id']??0);
            $doneTk=trim((string)($doneShop['token']??($cn['basalam']['token']??'')));
            if($doneVid>0 && $doneTk!=='' && empty($shopDone[(string)$doneVid])){$allDone=false;break;}
        }
        if($allDone)return ['ok'=>true,'complete'=>true,'rounds'=>$round,'requests'=>$requests];
        /* مقصدهای ناتمام در round بعد، تا deadline همین برش، یک صفحهٔ دیگر می‌گیرند. */
    }
    return ['ok'=>true,'yielded'=>true,'rounds'=>$round,'requests'=>$requests];
}

/**
 * ساخت کامل ماتریس روی سرور با گزارش پیشرفت.
 * $opts: profile, source (manual|recon_auto|cron)
 */
function matrixProfileExactTitle(string $title): string {
    $t = trim(strtr($title, ['ي'=>'ی','ك'=>'ک','۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9']));
    $t = preg_replace('/[\x{200c}\x{200e}\x{200f}]+/u', ' ', $t);
    $t = trim((string)preg_replace('/\s+/u', ' ', $t));
    return function_exists('mb_strtolower') ? mb_strtolower($t, 'UTF-8') : strtolower($t);
}

function matrixProfileDuplicateCount(array $row): int {
    return max(0, (int)($row['profile_duplicate_hits'] ?? 0));
}

function matrixBuild(array $opts = []): array {
    @set_time_limit(0);
    @ignore_user_abort(true);
    $cn = loadConnections();
    $suffixes = matrixCollectSuffixes();
    $profileFilter = trim((string)($opts['profile'] ?? 'all'));
    $source = (string)($opts['source'] ?? 'manual');
    $parallelDest = !empty($opts['parallel_destinations']);
    $liveFill = !empty($opts['live_fill']);
    $codedOnly = false;
    $rawSelected=array_key_exists('selected_destinations',$opts)?$opts['selected_destinations']:null;
    $selectedDestinations=matrixNormalizeDestinations($rawSelected,$cn);
    $selectedSet=array_fill_keys($selectedDestinations,true);$includeWoo=isset($selectedSet['woo']);
    /* v10.254: زمان هر برش دستی قابل تنظیم است؛ ۲..۲۰ ثانیه تا هم تعداد
       بسته‌ها کم/زیاد شود و هم از timeout رایج proxy ها عبور نکند. */
    $sliceSeconds = max(2, min(20, (int)($opts['slice_seconds'] ?? 8)));
    /* PHP built-in/CLI server تا پایان درخواست، درخواست توقف دوم را نمی‌خواند.
       اجرای دستی به برش‌های کوتاه تقسیم می‌شود و UI بین برش‌ها خودکار resume می‌کند. */
    $GLOBALS['_matrixRunStartedAt'] = (float)($opts['run_started_at'] ?? microtime(true));
    $GLOBALS['_matrixSliceDeadline'] = in_array($source, ['manual','worker'], true) ? microtime(true) + $sliceSeconds : 0;
    $resumeCp = is_array($opts['checkpoint'] ?? null) ? $opts['checkpoint'] : [];
    /* v10.347: matrix pages have a private append-only cursor. Legacy recon,
       suffix reports, and a fresh periodic run may clear their own cursor but
       can no longer send an active matrix build back to Woo page one. */
    matrixActivateFetchCursor($resumeCp);
    if(array_key_exists('selected_destinations',$resumeCp)){$selectedDestinations=matrixNormalizeDestinations($resumeCp['selected_destinations'],$cn);$selectedSet=array_fill_keys($selectedDestinations,true);$includeWoo=isset($selectedSet['woo']);}
    $compactStats=$resumeCp?matrixCompactCheckpoint($resumeCp):[];
    $startedAt = (int)($resumeCp['started_at'] ?? time());
    $profileRows = is_array($resumeCp['profile_rows'] ?? null) ? $resumeCp['profile_rows'] : [];
    $profilesDone = array_values(array_unique(array_map('strval', (array)($resumeCp['profiles_done'] ?? []))));
    $profilesDoneSet = $profilesDone ? array_fill_keys($profilesDone, true) : [];
    $matrixWooCp = is_array($resumeCp['woo_rows'] ?? null) ? $resumeCp['woo_rows'] : [];
    $matrixWooDone = !empty($resumeCp['woo_done']);
    $matrixWooPage = (int)($resumeCp['woo_page'] ?? 0);
    $matrixWooComplete = !empty($resumeCp['woo_complete']);
    $matrixShopCp = is_array($resumeCp['shop_rows'] ?? null) ? $resumeCp['shop_rows'] : [];
    $matrixShopPages = is_array($resumeCp['shop_pages'] ?? null) ? $resumeCp['shop_pages'] : [];
    $matrixShopDone = is_array($resumeCp['shop_done'] ?? null) ? $resumeCp['shop_done'] : [];
    if (!array_key_exists('shop_done', $resumeCp) && $matrixShopCp) {
        foreach ($matrixShopCp as $savedVid => $_savedRows) $matrixShopDone[(string)$savedVid] = true;
    }
    $matrixCp = static function (string $phase, array $rows, array $done, array $woo, array $shops, int $at, bool $wooDone = false) use ($profileFilter, &$parallelDest, &$liveFill, &$codedOnly, &$sliceSeconds, &$matrixWooPage, &$matrixWooComplete, &$matrixShopPages, &$matrixShopDone, &$selectedDestinations): array {
        /* raw destination rows already live in append-only cursors. Repeating a
           growing 10k+ catalog inside every JSON checkpoint caused OOM/worker death. */
        $cpShops=[];foreach($shops as $vid=>$raw)if(!empty($matrixShopDone[(string)$vid]))$cpShops[$vid]=$raw;
        return ['phase' => $phase, 'profile_filter' => ($profileFilter ?: 'all'), 'selected_destinations'=>$selectedDestinations,
            'profile_rows' => $rows, 'profiles_done' => $done, 'woo_rows' => $wooDone ? $woo : [],
            'woo_done' => $wooDone, 'woo_page' => $matrixWooPage, 'woo_complete' => $matrixWooComplete,
            'shop_rows' => $cpShops, 'shop_pages' => $matrixShopPages, 'shop_done' => $matrixShopDone,
            'started_at' => $at, 'fetch_mode' => $parallelDest ? 'parallel' : 'serial', 'live_fill' => $liveFill, 'coded_only' => $codedOnly, 'slice_seconds' => $sliceSeconds];
    };

    matrixProgress([
        'running' => true, 'done' => false, 'error' => '',
        'phase' => 'profiles', 'pct' => $profilesDone ? 2 : 2, 'source' => $source,
        'profile' => $profileFilter, 'started_at' => $startedAt, 'runner_pid'=>(int)@getmypid(), 'runner_kind'=>'matrix_build', 'fetch_mode' => $parallelDest ? 'parallel' : 'serial', 'live_fill' => $liveFill, 'coded_only' => $codedOnly, 'selected_destinations'=>$selectedDestinations, 'slice_seconds' => $sliceSeconds,
        'checkpoint' => $matrixCp('profiles', $profileRows, $profilesDone, $matrixWooCp, $matrixShopCp, $startedAt, $matrixWooDone),
        'log_add' => ['🚀 ' . ($profilesDone ? 'ادامه ساخت جدول مقایسه' : 'شروع ساخت جدول مقایسه')
            . ' (سرورساید) — منبع: ' . $source],
    ]);

    $wooCfg = destPriceCfg($cn, 'woocommerce');
    $bslCfg = destPriceCfg($cn, 'basalam');

    $rowsByKey = $profileRows;
    /* فقط یک owner برای آرایهٔ بزرگ بماند؛ وگرنه نخستین map به‌علت COW یک
       کپی کامل دیگر از checkpoint می‌سازد و سقف ۵۱۲MB را می‌شکند. */
    unset($profileRows,$resumeCp,$opts['checkpoint']);
    $stopMatrix = static function (string $phase) use (&$rowsByKey, &$profilesDone, &$matrixWooCp,
        &$matrixShopCp, &$startedAt, &$matrixWooDone, &$matrixWooPage, &$matrixWooComplete,
        &$matrixShopPages, &$matrixShopDone, $profileFilter, &$parallelDest, &$codedOnly, &$sliceSeconds, &$selectedDestinations): array {
        $cpShops=[];foreach($matrixShopCp as $vid=>$raw)if(!empty($matrixShopDone[(string)$vid]))$cpShops[$vid]=$raw;
        $cp = ['phase' => $phase, 'profile_filter' => ($profileFilter ?: 'all'), 'selected_destinations'=>$selectedDestinations,
            'profile_rows' => $rowsByKey, 'profiles_done' => $profilesDone,
            'woo_rows' => $matrixWooDone ? $matrixWooCp : [], 'woo_done' => $matrixWooDone,
            'woo_page' => $matrixWooPage, 'woo_complete' => $matrixWooComplete,
            'shop_rows' => $cpShops, 'shop_pages' => $matrixShopPages, 'shop_done' => $matrixShopDone,
            'started_at' => $startedAt, 'fetch_mode' => $parallelDest ? 'parallel' : 'serial', 'coded_only' => $codedOnly, 'slice_seconds' => $sliceSeconds];
        matrixProgress(['running' => false, 'done' => true, 'stopped' => true, 'partial' => true,
            'stale' => true, 'phase' => 'stopped', 'checkpoint' => $cp,
            'log_add' => ['⏹ ساخت جدول متوقف شد — checkpoint حفظ شد']]);
        matrixStopClear();
        return ['ok' => true, 'stopped' => true, 'partial' => true, 'checkpoint' => $cp];
    };
    $yieldMatrix = static function (string $phase, int $retryAfter=0) use (&$rowsByKey, &$profilesDone, &$matrixWooCp,
        &$matrixShopCp, &$startedAt, &$matrixWooDone, &$matrixWooPage, &$matrixWooComplete,
        &$matrixShopPages, &$matrixShopDone, $profileFilter, &$parallelDest, &$liveFill, &$codedOnly, &$sliceSeconds, $cn, $source, &$selectedDestinations): array {
        $cpShops=[];foreach($matrixShopCp as $vid=>$raw)if(!empty($matrixShopDone[(string)$vid]))$cpShops[$vid]=$raw;
        $cp = ['phase' => $phase, 'profile_filter' => ($profileFilter ?: 'all'), 'selected_destinations'=>$selectedDestinations,
            'profile_rows' => $rowsByKey, 'profiles_done' => $profilesDone,
            'woo_rows' => $matrixWooDone ? $matrixWooCp : [], 'woo_done' => $matrixWooDone,
            'woo_page' => $matrixWooPage, 'woo_complete' => $matrixWooComplete,
            'shop_rows' => $cpShops, 'shop_pages' => $matrixShopPages, 'shop_done' => $matrixShopDone,
