                $oldCell = $rowsByKey[$bare]['shops'][$vid] ?? null;
                if (is_array($oldCell)) {
                    $existingIds = [];
                    foreach ((array)($rowsByKey[$bare]['shop_extra'][$vid] ?? []) as $ex) $existingIds[(int)($ex['id'] ?? 0)] = true;
                    $oldId = (int)($oldCell['id'] ?? 0);
