        }
        $remoteCount=count($remote);
        /* غرفهٔ کامل داخل rowsByKey map شده؛ raw آن از checkpoint حذف شود تا
           غرفهٔ دوم و compare با دو نسخهٔ کامل کاتالوگ وارد OOM نشوند. */
        $matrixShopCp[(string)$vid]=[];$remote=[];
        matrixProgress(['checkpoint'=>$matrixCp('bsl_mapped',$rowsByKey,$profilesDone,$matrixWooCp,$matrixShopCp,$startedAt,$matrixWooDone),
            'log_add'=>['  ✓ '.$sname.': '.$remoteCount.' محصول · checkpoint فشرده شد']]);
    }

    matrixProgress(['phase' => 'compare', 'pct' => 85, 'log_add' => ['⚖️ محاسبه وضعیت‌ها...']]);

    $rows = [];
    $sum = [
        'total' => 0, 'ok' => 0, 'price_mismatch' => 0, 'missing_woo' => 0,
        'missing_bsl' => 0, 'extra_woo' => 0, 'extra_bsl' => 0,
        'dup_profile' => 0, 'dup_woo' => 0, 'dup_bsl' => 0,
        'in_all' => 0, 'only_profile' => 0, 'only_dest' => 0,
    ];
    $matrixShopByVid = [];
    foreach ($shopList as $matrixShopCfg) if (is_array($matrixShopCfg) && (int)($matrixShopCfg['vendor_id'] ?? 0) > 0) $matrixShopByVid[(int)$matrixShopCfg['vendor_id']] = $matrixShopCfg;
    foreach ($rowsByKey as $bare => $r) {
        $hasProf = ($r['profile_hits'] ?? 0) > 0;
        $rowProfileKey = (string)($r['profile_key'] ?? '');
        $rowProfileCfg = is_array($profiles[$rowProfileKey] ?? null) ? $profiles[$rowProfileKey] : null;
        $hasWoo = $includeWoo && !empty($r['woo']);
        $shopCount = 0; $shopOk = 0; $shopBad = 0; $shopMiss = 0;
        foreach ($shopsMeta as $sm) {
            $vid = (int)$sm['vendor_id'];
            $shopExpected = (int)($r['shop_expect'][$vid] ?? $r['bsl_expect'] ?? 0);
            if ($hasProf && $rowProfileCfg && isset($matrixShopByVid[$vid])) {
                $rawForShop = (string)($r['src_price'] ?? '0');
                if (extractPriceNum($rawForShop) > 0) {
                    $shopCalc = bslShopPriceForProfile($rowProfileCfg, $rawForShop, $matrixShopByVid[$vid], (int)($bslCfg['round'] ?? 0));
                    if ((int)($shopCalc['price'] ?? 0) > 0) $shopExpected = (int)$shopCalc['price'];
                }
            }
            if ($hasProf) $r['shop_expect'][$vid] = $shopExpected;
            if (!empty($r['shops'][$vid])) {
                $shopCount++;
                $r['shops'][$vid]['expect'] = $shopExpected;
                $r['shops'][$vid]['tone'] = matrixPriceTone($shopExpected, (int)($r['shops'][$vid]['price'] ?? 0));
                $t = $r['shops'][$vid]['tone'];
                if ($t === 'ok') $shopOk++;
                elseif ($t === 'bad' || $t === 'warn') $shopBad++;
            } elseif ($hasProf) {
                $shopMiss++;
            }
        }
        $wooTone = 'na';
        if ($includeWoo && $hasProf && $hasWoo) {
            $wooTone = matrixPriceTone((int)$r['woo_expect'], (int)($r['woo']['price'] ?? 0));
        } elseif ($includeWoo && $hasProf && !$hasWoo) {
            $wooTone = 'missing_dst';
        } elseif ($includeWoo && !$hasProf && $hasWoo) {
            $wooTone = 'extra';
        }
        $flags = [];
        if (matrixProfileDuplicateCount($r) > 0) { $flags[] = 'dup_profile'; $sum['dup_profile']++; }
        if (!empty($r['woo_dup'])) { $flags[] = 'dup_woo'; $sum['dup_woo']++; }
        foreach ($r['shops'] as $sc) {
            if (!empty($sc['dup'])) { $flags[] = 'dup_bsl'; $sum['dup_bsl']++; break; }
        }
        if ($wooTone === 'missing_dst') { $flags[] = 'missing_woo'; $sum['missing_woo']++; }
        if ($wooTone === 'extra') { $flags[] = 'extra_woo'; $sum['extra_woo']++; }
        if ($wooTone === 'bad' || $wooTone === 'warn') { $flags[] = 'price_mismatch'; }
        if ($shopMiss > 0 && $hasProf) { $flags[] = 'missing_bsl'; $sum['missing_bsl']++; }
        if ($shopBad > 0) { $flags[] = 'price_mismatch'; }
        $flags = array_values(array_unique($flags));
        if (in_array('price_mismatch', $flags, true)) { $sum['price_mismatch']++; }

        $status = 'partial';
        $wooOk=!$includeWoo||($hasWoo&&$wooTone==='ok');
        $hasAnySelectedDest=($includeWoo&&$hasWoo)||$shopCount>0;
        if ($hasProf && $wooOk && $shopMiss === 0 && $shopBad === 0) {
            $status = 'ok'; $sum['ok']++; $sum['in_all']++;
        } elseif ($hasProf && !$hasAnySelectedDest) {
            $status = 'only_profile'; $sum['only_profile']++;
        } elseif (!$hasProf) {
            $status = 'only_dest'; $sum['only_dest']++;
        } elseif (($includeWoo&&($wooTone === 'bad' || $wooTone === 'warn')) || $shopBad > 0) {
            $status = 'mismatch';
        } elseif (($includeWoo&&$wooTone === 'missing_dst') || $shopMiss > 0) {
            $status = 'missing';
        }

        $r['woo_tone'] = $wooTone;
        $r['status'] = $status;
        $r['flags'] = $flags;
        $r['shop_ok'] = $shopOk;
        $r['shop_bad'] = $shopBad;
        $r['shop_miss'] = $shopMiss;
        unset($r['_profile_exact'], $r['_profile_ref'], $r['_profile_variants']);
        $rows[] = $r;
        $sum['total']++;
    }

    $order = ['mismatch' => 0, 'missing' => 1, 'only_profile' => 2, 'only_dest' => 3, 'partial' => 4, 'ok' => 5];
    usort($rows, function ($a, $b) use ($order) {
        $oa = $order[$a['status']] ?? 9;
        $ob = $order[$b['status']] ?? 9;
        if ($oa !== $ob) return $oa <=> $ob;
        return strcmp((string)$a['bare'], (string)$b['bare']);
    });

    $out = [
        'ok' => true,
        'generated_at' => time(),
        'source' => $source,
        'coded_only' => $codedOnly,
        'selected_destinations'=>$selectedDestinations,
        'pricing_signature' => matrixPricingFingerprint($profiles, $cn),
        'suffixes' => $suffixes,
        'shops' => $shopsMeta,
        'woo_cfg' => $wooCfg,
        'bsl_cfg' => $bslCfg,
        'summary' => $sum,
        'rows' => $rows,
        'woo_error' => $wooErr,
        'bsl_error' => $bslErr,
        'woo_count' => $wooCount,
        'profile_count' => count($profiles),
        'row_count' => count($rows),
    ];
    matrixProgress([
        'phase' => 'save', 'pct' => 95,
        'log_add' => ['💾 ذخیره ' . count($rows) . ' ردیف روی سرور...'],
    ]);
    if (!matrixResultSave($out)) {
        $out['ok'] = false;
        $out['error'] = 'نوشتن فایل نتیجه ناموفق بود (فضا/مجوز؟)';
        matrixProgress(['running' => false, 'done' => true, 'error' => $out['error'], 'pct' => 100,
            'log_add' => ['❌ ' . $out['error']]]);
        return $out;
    }
    @unlink(SYNC_MATRIX_LIVE_FILE);
    matrixProgress([
        'running' => false, 'done' => true, 'error' => '', 'pct' => 100,
        'phase' => 'done', 'summary' => $sum, 'row_count' => count($rows),
        'checkpoint' => null, 'finished_at' => time(),
        'log_add' => [
            '✅ جدول آماده: ' . count($rows) . ' ردیف',
            '📊 یکسان ' . (int)$sum['ok'] . ' · مغایرت ' . (int)$sum['price_mismatch']
                . ' · نیست در WC ' . (int)$sum['missing_woo'],
        ],
    ]);
    return $out;
}

/**
 * اجرای جاب ساخت ماتریس با قفل فایل.
 * background=true → پاسخ زود و ادامه در همان درخواست پس از flush (مثل recon)
 */

/* =====================================================================
 *  v10.117: اصلاح مغایرت از روی جدول مقایسه (سرورساید + لاگ زنده)
 *  start:  ?sync_matrix_fix_start=1  (یا POST action=)
 *  status: ?sync_matrix_fix_status=1
 *  stop:   ?sync_matrix_fix_stop=1
 *  از نتیجهٔ sync_matrix_result.json می‌خواند و قیمت WC/غرفه‌ها را
 *  طبق «انتظار» اصلاح می‌کند؛ هر ردیف همان لحظه در فایل نتیجه به‌روز می‌شود.
 * ===================================================================== */

function matrixFixProgress(array $patch): void {
    $cur = localTaskStateRead(SYNC_MATRIX_FIX_PROGRESS_FILE, []);
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) {
            $log[] = ['t' => time(), 'm' => (string)$l];
        }
        if (count($log) > 400) $log = array_slice($log, -400);
        unset($patch['log_add']);
    }
    if (isset($patch['live_add']) && is_array($patch['live_add'])) {
        $live = is_array($cur['live'] ?? null) ? $cur['live'] : [];
        $item = $patch['live_add'];
        if (empty($item['title'])) $item['title'] = (string)($cur['current_title'] ?? $item['bare'] ?? '');
        if (empty($item['bare'])) $item['bare'] = (string)($cur['current_bare'] ?? '');
        if (empty($item['kind'])) $item['kind'] = (string)($cur['current_kind'] ?? '');
        $live[] = $item;
        /* فهرست زنده برای مودال شمارنده‌ها؛ کران حافظه از بادکردن state جلوگیری می‌کند. */
        if (count($live) > 500) $live = array_slice($live, -500);
        $cur['live'] = $live;
        unset($patch['live_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok', 'stop_requested'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log;
    $cur['ts'] = time();
    writeProgress(SYNC_MATRIX_FIX_PROGRESS_FILE, $cur);
}

function matrixFixProgressRead(): array {
    return localTaskStateRead(SYNC_MATRIX_FIX_PROGRESS_FILE, []);
}

/** یک منبع مشترک برای هر دو status endpoint؛ مقصد خارج از تیک حتی اگر در
 * log قدیمی روی دیسک مانده باشد هرگز به UI برنمی‌گردد. */
function matrixFixVisibleProgress(array $prog, $requestedDestinations=null): array {
    $selected=$requestedDestinations!==null
        ? matrixNormalizeDestinations($requestedDestinations)
        : array_values((array)($prog['selected_destinations']??[]));
    if($selected)$prog['selected_destinations']=$selected;
    $runStarted=(int)($prog['started_at']??0);
    if($runStarted>0)$prog['log']=array_values(array_filter((array)($prog['log']??[]),static fn($row)=>(int)($row['t']??0)>=$runStarted));
    if($selected&&!in_array('woo',$selected,true)){
        $prog['log']=array_values(array_filter((array)($prog['log']??[]),static function($row){$m=(string)($row['m']??'');return stripos($m,'WC')===false&&mb_stripos($m,'ووکامرس')===false;}));
        foreach(['planned','live'] as $k)$prog[$k]=array_values(array_filter((array)($prog[$k]??[]),static fn($x)=>!str_ends_with((string)($x['kind']??''),'_woo')));
    }
    return $prog;
}

function matrixFixStopRequested(): bool {
    return is_file(SYNC_MATRIX_FIX_STOP_FILE);
}

function matrixFixStopClear(): void {
    @unlink(SYNC_MATRIX_FIX_STOP_FILE);
}
/** Stop باقی‌مانده از اجرای قبلی نباید job تازهٔ صف را فوراً متوقف کند؛ اما
 * stopی که پس از ثبت همین job نوشته شده است درخواست واقعی کاربر است. */
function matrixFixClearStaleStop(float $requestedAt): void {
    if (!is_file(SYNC_MATRIX_FIX_STOP_FILE)) return;
    $d=json_decode((string)@file_get_contents(SYNC_MATRIX_FIX_STOP_FILE),true);
    $stopAt=is_array($d)?(float)($d['at']??0):0.0;
    if($requestedAt>0&&($stopAt<=0||$stopAt<$requestedAt))@unlink(SYNC_MATRIX_FIX_STOP_FILE);
}

/** v10.329: حذف‌های موفق checkpoint را روی snapshot اعمال می‌کند. نسخه‌های
 * پیشین در حذف BSL آرایهٔ shops خالی را merge می‌کردند و cell قدیمی در فایل
 * می‌ماند؛ done_jobs حقیقت قطعی عملیات API است و repair idempotent است. */
function matrixApplyCompletedDeleteOverlay(array &$data,array $doneJobs): int {
    if(!is_array($data['rows']??null)||!$doneJobs)return 0;$byBare=[];
    foreach($data['rows']as$i=>$r)if(is_array($r)&&isset($r['bare']))$byBare[(string)$r['bare']]=$i;$changed=0;
    foreach(array_unique(array_map('strval',$doneJobs))as$key){$parts=explode('|',$key);if(count($parts)<4)continue;
        $kind=array_shift($parts);$vid=(int)array_pop($parts);$id=(int)array_pop($parts);$bare=implode('|',$parts);
        if(!in_array($kind,['del_bsl','del_woo'],true)||!isset($byBare[$bare]))continue;$i=$byBare[$bare];$r=$data['rows'][$i];
        if($kind==='del_woo'){$cur=(int)($r['woo']['id']??0);if($cur>0&&($id<=0||$cur===$id)){$data['rows'][$i]['woo']=null;$data['rows'][$i]['woo_tone']='na';$changed++;}}
        else{$shops=is_array($r['shops']??null)?$r['shops']:[];$cell=is_array($shops[$vid]??null)?$shops[$vid]:(is_array($shops[(string)$vid]??null)?$shops[(string)$vid]:null);$cur=(int)($cell['id']??0);
            if($cur>0&&($id<=0||$cur===$id)){unset($shops[$vid],$shops[(string)$vid]);$data['rows'][$i]['shops']=$shops;$changed++;}}
    }
    return $changed;
}

/** v10.333: خطای کوتاه هر ردیف مستقل از بازسازی snapshot حفظ می‌شود. */
function matrixFixErrorsLoad(): array {
    $d=localTaskStateRead(SYNC_MATRIX_FIX_ERRORS_FILE,[]);
    return is_array($d['rows']??null)?$d['rows']:[];
}
function matrixFixErrorShort(string $error): string {
    $error=trim((string)preg_replace('/\s+/u',' ',$error));
    return mb_substr($error!==''?$error:'خطای نامشخص',0,140);
}
function matrixFixRecordRowError(string $bare,string $kind,string $error): void {
    if($bare==='')return;$fp=@fopen(SYNC_MATRIX_FIX_ERRORS_LOCK,'c');if(!$fp||!@flock($fp,LOCK_EX)){if($fp)@fclose($fp);return;}
    try{$rows=matrixFixErrorsLoad();$rows[$bare]=['error'=>matrixFixErrorShort($error),'kind'=>$kind,'at'=>time()];
        @file_put_contents(SYNC_MATRIX_FIX_ERRORS_FILE,json_encode(['version'=>APP_VERSION,'rows'=>$rows],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX);
    }finally{@flock($fp,LOCK_UN);@fclose($fp);}
}
function matrixFixClearRowError(string $bare): void {
    $fp=@fopen(SYNC_MATRIX_FIX_ERRORS_LOCK,'c');if(!$fp||!@flock($fp,LOCK_EX)){if($fp)@fclose($fp);return;}
    try{$rows=matrixFixErrorsLoad();if(!isset($rows[$bare]))return;unset($rows[$bare]);
        @file_put_contents(SYNC_MATRIX_FIX_ERRORS_FILE,json_encode(['version'=>APP_VERSION,'rows'=>$rows],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX);
    }finally{@flock($fp,LOCK_UN);@fclose($fp);}
}
function matrixFixApplyErrors(array &$data): void {
    $holds=matrixFixErrorsLoad();if(!$holds)return;
    foreach((array)($data['rows']??[]) as $i=>$r){$bare=(string)($r['bare']??'');if($bare!==''&&isset($holds[$bare])){$data['rows'][$i]['fix_error']=(string)($holds[$bare]['error']??'خطا');$data['rows'][$i]['fix_error_kind']=(string)($holds[$bare]['kind']??'');$data['rows'][$i]['fix_error_at']=(int)($holds[$bare]['at']??0);}}
}

/** v10.335: صف مستقل بازیابی نام تکراری؛ worker اصلی matrix را مسدود نمی‌کند. */
function matrixBslDupQueueMutate(callable $fn): array {
    $fp=@fopen(BSL_DUP_RECOVERY_QUEUE_LOCK,'c');
    if(!$fp||!@flock($fp,LOCK_EX)){if($fp)@fclose($fp);return ['ok'=>false,'error'=>'duplicate_queue_lock_failed'];}
    try{
        $q=is_file(BSL_DUP_RECOVERY_QUEUE_FILE)?json_decode((string)@file_get_contents(BSL_DUP_RECOVERY_QUEUE_FILE),true):[];
        if(!is_array($q))$q=[];if(!is_array($q['entries']??null))$q['entries']=[];
        $ret=$fn($q);$q['version']=APP_VERSION;$q['updated_at']=time();
        @file_put_contents(BSL_DUP_RECOVERY_QUEUE_FILE,json_encode($q,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX);
        return is_array($ret)?$ret:['ok'=>true];
    }finally{@flock($fp,LOCK_UN);@fclose($fp);}
}
function matrixSpawnBslDuplicateWorker(): array {
    if(!function_exists('exec'))return ['ok'=>false,'error'=>'exec_disabled'];
    if(strtoupper(substr(PHP_OS,0,3))==='WIN')return ['ok'=>false,'error'=>'windows_detach_unsupported'];
    if(!is_dir(__DIR__.'/logs'))@mkdir(__DIR__.'/logs',0755,true);
    $php=s4CliPhpBinary();$mem=(string)@ini_get('memory_limit');if($mem==='')$mem='512M';
    $log=__DIR__.'/logs/bsl-duplicate-recovery.log';
    $cmd='nohup '.s4CliPhpCommand($php,$mem).' '.escapeshellarg(__FILE__)
        .' bsl_duplicate_worker >> '.escapeshellarg($log).' 2>&1 < /dev/null & echo $!';
    $out=[];$rc=0;@exec($cmd,$out,$rc);$pid=0;foreach($out as $line){$line=trim((string)$line);if(ctype_digit($line)){$pid=(int)$line;break;}}
    return ($rc===0&&$pid>0)?['ok'=>true,'pid'=>$pid,'log'=>$log]:['ok'=>false,'error'=>'duplicate_worker_spawn_failed','exit_code'=>$rc];
}
function matrixQueueBslDuplicateRecovery(array $task): array {
    $bare=trim((string)($task['bare']??''));$vid=(int)($task['vendor_id']??0);
    if($bare===''||$vid<=0)return ['ok'=>false,'error'=>'duplicate_task_invalid'];
    $key=sha1($bare.'|'.$vid);$ret=matrixBslDupQueueMutate(function(&$q)use($task,$key){
        foreach($q['entries']as&$old){if(!is_array($old)||(string)($old['status']??'')!=='running')continue;$pid=(int)($old['pid']??0);if((time()-(int)($old['started_at']??0)>1800)||($pid>0&&!s4WorkerPidAlive($pid))){$old['status']='pending';$old['pid']=0;$old['recovered_at']=time();}}unset($old);
        foreach($q['entries']as$e)if(is_array($e)&&(string)($e['key']??'')===$key&&in_array((string)($e['status']??''),['pending','running'],true))return ['ok'=>true,'duplicate'=>true,'task_id'=>(string)($e['id']??'')];
        $id='dup_'.time().'_'.substr($key,0,10);$q['entries'][]=['id'=>$id,'key'=>$key,'status'=>'pending','created_at'=>time(),'task'=>$task];
        return ['ok'=>true,'queued'=>true,'task_id'=>$id];
    });
    if(empty($ret['ok']))return $ret;$spawn=matrixSpawnBslDuplicateWorker();
    /* اگر worker دیگری lock را دارد، پردازهٔ تازه فوراً خارج می‌شود ولی همان
       worker موجود task صف‌شده را می‌بیند؛ spawn موفق برای wake-up کافی است. */
    if(empty($spawn['ok']))return ['ok'=>false,'error'=>(string)($spawn['error']??'duplicate_worker_spawn_failed'),'task_id'=>(string)($ret['task_id']??'')];
    return array_merge($ret,['worker_spawn'=>$spawn,'parallel'=>true]);
}
function matrixBslDuplicateRecoverOne(array $task): array {
    $bare=trim((string)($task['bare']??''));$vid=(int)($task['vendor_id']??0);$expect=max(0,(int)($task['expect']??0));
    $found=matrixFixFindProduct($bare,(string)($task['profile_key']??''),(string)($task['product_key']??''));
    if(!$found)throw new RuntimeException('محصول در پروفایل برای بازیابی نام تکراری پیدا نشد');
    $cn=loadConnections();$shop=null;foreach(bslAllShops($cn)as$sh)if((int)($sh['vendor_id']??0)===$vid){$shop=$sh;break;}
    if(!is_array($shop))throw new RuntimeException('غرفهٔ باسلام برای بازیابی پیدا نشد');
    $tk=trim((string)($shop['token']??($cn['basalam']['token']??'')));if($tk==='')throw new RuntimeException('توکن غرفه برای بازیابی موجود نیست');
    $p=(array)$found['product'];$profile=(array)$found['profile'];$title=trim((string)($p['title']??$p['name']??$task['title']??$bare));
    $mk=bslShopMapKey((string)($p['key']??$task['product_key']??''),$shop);
    /* trustCatalogMiss=false: active snapshot may miss an archived/inactive item. */
    $dup=bslFindExisting($tk,$vid,$title,$mk,true,false,RECON_FETCH_MAX_PAGES);$id=(int)($dup['id']??0);
    if($id<=0)throw new RuntimeException('محصول هم‌نام در همهٔ وضعیت‌های فعال و غیرفعال پیدا نشد');
    $b=(array)($cn['basalam']??[]);$raw=extractSourcePrice($p);$adj=extractPriceNum($raw)>0?bslShopPriceForProfile($profile,$raw,$shop,(int)($b['price_round']??0)):[];
    $price=$expect>0?$expect:(int)($adj['price']??0);if($price<=0)throw new RuntimeException('قیمت معتبر برای به‌روزرسانی محصول هم‌نام موجود نیست');
    $stock=effectiveStock($p,(int)($b['stock']??10));
    $_wResDupRec=bslResolveProductWeights($p,(int)($b['weight']??500),(int)($b['package_weight']??0));
    $weight=(int)$_wResDupRec['weight'];$pkg=(int)$_wResDupRec['package_weight'];
    $bu=['primary_price'=>$price*10,'stock'=>$stock,'status'=>2976,'preparation_days'=>(int)($b['preparation_days']??3),'weight'=>$weight,'package_weight'=>$pkg];
    bslApplyContent($bu,$p);$r=bslReq($tk,'PATCH','vendors/'.$vid.'/products/'.$id,$bu,false,null,false,1);
    if(empty($r['ok']))$r=bslReq($tk,'PATCH','products/'.$id,$bu,false,null,false,1);
    /* ledger قدیمی ممکن است به شناسهٔ حذف‌شده اشاره کند؛ در این حالت جستجوی
       کامل را بدون ledger تکرار کن تا محصول واقعاً هم‌نام پیدا شود. */
    if(empty($r['ok'])&&$mk!==''){
        $dup2=bslFindExisting($tk,$vid,$title,'',true,false,RECON_FETCH_MAX_PAGES);$id2=(int)($dup2['id']??0);
        if($id2>0&&$id2!==$id){$id=$id2;$r=bslReq($tk,'PATCH','vendors/'.$vid.'/products/'.$id,$bu,false,null,false,1);if(empty($r['ok']))$r=bslReq($tk,'PATCH','products/'.$id,$bu,false,null,false,1);}
    }
    if(empty($r['ok']))throw new RuntimeException('محصول هم‌نام پیدا شد اما فعال‌سازی/به‌روزرسانی شکست خورد: '.bslErrText($r));
    bslShopMapRecord($p,$shop,$id,$title,$price*10,$stock);bslCatalogNote($vid,$title,$id);matrixFixClearRowError($bare);
    matrixResultPatchRow($bare,['shops'=>[$vid=>['id'=>$id,'price'=>$price,'price_rial'=>$price*10,'tone'=>'ok','expect'=>$price,'shop_name'=>(string)($shop['name']??$shop['shop_name']??('#'.$vid)),'title'=>$title]],'fix_pending'=>'','fix_error'=>'','fix_error_kind'=>'','fix_duplicate_recovered_at'=>time()]);
    return ['ok'=>true,'id'=>$id,'bare'=>$bare,'vendor_id'=>$vid,'price'=>$price];
}
function matrixBslDuplicateWorkerLoop(): array {
    $proc=@fopen(BSL_DUP_RECOVERY_LOCK_FILE,'c');if(!$proc||!@flock($proc,LOCK_EX|LOCK_NB)){if($proc)@fclose($proc);return ['ok'=>true,'already_running'=>true];}
    $done=$failed=0;
    try{
        for($guard=0;$guard<500;$guard++){
            $claim=matrixBslDupQueueMutate(function(&$q){foreach($q['entries']as&$e){if(!is_array($e)||(string)($e['status']??'')!=='pending')continue;$e['status']='running';$e['started_at']=time();$e['pid']=(int)getmypid();$x=$e;unset($e);return ['ok'=>true,'entry'=>$x];}unset($e);return ['ok'=>true,'entry'=>null];});
            $entry=$claim['entry']??null;if(!is_array($entry))break;$id=(string)($entry['id']??'');
            try{$res=matrixBslDuplicateRecoverOne((array)($entry['task']??[]));$done++;$status='done';$err='';}
            catch(Throwable $e){$failed++;$status='failed';$err=matrixFixErrorShort($e->getMessage());$task=(array)($entry['task']??[]);$bare=(string)($task['bare']??'');matrixFixRecordRowError($bare,'duplicate_recovery',$err);matrixResultPatchRow($bare,['fix_pending'=>'','fix_error'=>$err,'fix_error_kind'=>'duplicate_recovery','fix_error_at'=>time()]);$res=['ok'=>false,'error'=>$err];}
            matrixBslDupQueueMutate(function(&$q)use($id,$status,$err,$res){foreach($q['entries']as&$e){if(is_array($e)&&(string)($e['id']??'')===$id){$e['status']=$status;$e['finished_at']=time();$e['error']=$err;$e['result']=$res;break;}}unset($e);$terminal=array_values(array_filter($q['entries'],static fn($x)=>is_array($x)&&!in_array((string)($x['status']??''),['pending','running'],true)));$active=array_values(array_filter($q['entries'],static fn($x)=>is_array($x)&&in_array((string)($x['status']??''),['pending','running'],true)));if(count($terminal)>100)$terminal=array_slice($terminal,-100);$q['entries']=array_merge($active,$terminal);return ['ok'=>true];});
        }
        return ['ok'=>true,'done'=>$done,'failed'=>$failed];
    }finally{@flock($proc,LOCK_UN);@fclose($proc);}
}

/** به‌روزرسانی یک ردیف در فایل نتیجهٔ ماتریس (با کلید bare) */
function matrixResultPatchRow(string $bare, array $rowPatch, ?array $summaryPatch = null): bool {
    $patchFp=@fopen(SYNC_MATRIX_RESULT_PATCH_LOCK,'c');
    if(!$patchFp||!@flock($patchFp,LOCK_EX)){if($patchFp)@fclose($patchFp);return false;}
    try{
    $data = matrixResultLoad();
    if (!$data || empty($data['rows']) || !is_array($data['rows'])) return false;
    $found = false;
    foreach ($data['rows'] as $i => $r) {
        if (!is_array($r)) continue;
        if ((string)($r['bare'] ?? '') !== $bare) continue;
        $data['rows'][$i] = array_merge($r, $rowPatch);
        /* nested shops merge — null cell = حذف */
        if (array_key_exists('shops', $rowPatch) && is_array($rowPatch['shops'])) {
            $shops = is_array($r['shops'] ?? null) ? $r['shops'] : [];
            /* اگر کلیدها فقط عددی/vid هستند merge؛ اگر جایگزینی کامل لیست خالی/بازنویسی */
            foreach ($rowPatch['shops'] as $vid => $cell) {
                if ($cell === null) {
                    unset($shops[$vid]);
                } elseif (is_array($cell) && isset($shops[$vid]) && is_array($shops[$vid])) {
                    $shops[$vid] = array_merge($shops[$vid], $cell);
                } else {
                    $shops[$vid] = $cell;
                }
            }
            $data['rows'][$i]['shops'] = $shops;
        }
        if (array_key_exists('woo', $rowPatch)) {
            if ($rowPatch['woo'] === null) {
                $data['rows'][$i]['woo'] = null;
            } elseif (is_array($rowPatch['woo'])) {
                $w0 = is_array($r['woo'] ?? null) ? $r['woo'] : [];
                $data['rows'][$i]['woo'] = array_merge($w0, $rowPatch['woo']);
            }
        }
        $found = true;
        break;
    }
    if (!$found) return false;
    if (is_array($summaryPatch)) {
        $sum = is_array($data['summary'] ?? null) ? $data['summary'] : [];
        $data['summary'] = array_merge($sum, $summaryPatch);
    }
    $data['fix_at'] = time();
    return matrixResultSave($data);
    }finally{@flock($patchFp,LOCK_UN);@fclose($patchFp);}
}

/**
 * ووکامرس: قیمت را با API یا مستقیم DB تنظیم می‌کند.
 * $priceToman عدد صحیح تومان.
 */
function matrixFixWooPrice(array $cn, int $pid, int $priceToman): array {
    if ($pid <= 0 || $priceToman <= 0) {
        return ['ok' => false, 'error' => 'شناسه/قیمت نامعتبر'];
    }
    /* direct when in WP */
    if (function_exists('wooDirectAvailable') && wooDirectAvailable() && function_exists('wc_get_product')) {
        try {
            $p = wc_get_product($pid);
            if ($p && is_object($p)) {
                $p->set_regular_price((string)$priceToman);
                if (method_exists($p, 'set_price')) $p->set_price((string)$priceToman);
                $p->save();
                return ['ok' => true, 'via' => 'direct', 'id' => $pid, 'price' => $priceToman];
            }
        } catch (Throwable $e) {
            /* fall through to API */
        }
    }
    $w = $cn['woocommerce'] ?? [];
    if (empty($w['store_url']) || empty($w['consumer_key'])) {
        return ['ok' => false, 'error' => 'تنظیمات WC ناقص و direct در دسترس نیست'];
    }
    $r = wooEditProduct($w, $pid, [
        'regular_price' => (string)$priceToman,
        'price' => (string)$priceToman,
    ]);
    if (!empty($r['ok'])) return ['ok' => true, 'via' => 'api', 'id' => $pid, 'price' => $priceToman];
    return ['ok' => false, 'error' => (string)($r['error'] ?? ('HTTP ' . ($r['code'] ?? 0))), 'code' => (int)($r['code'] ?? 0)];
}

/** باسلام: قیمت تومان → ریال ×۱۰ */
function matrixFixBslPrice(string $tk, int $vid, int $pid, int $priceToman): array {
    if ($pid <= 0 || $priceToman <= 0 || $tk === '') {
        return ['ok' => false, 'error' => 'ورودی ناقص'];
    }
    $rial = $priceToman * 10;
    $bu = ['primary_price' => $rial];
    $r = bslReq($tk, 'PATCH', 'products/' . $pid, $bu);
    if ((int)($r['code'] ?? 0) === 404 && $vid > 0) {
        $r = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $pid, $bu);
    }
    if (in_array((int)($r['code'] ?? 0), [401, 403, 422], true) && $vid > 0 && empty($r['ok'])) {
        $r2 = bslReq($tk, 'PATCH', 'vendors/' . $vid . '/products/' . $pid, $bu);
        if (!empty($r2['ok']) || (int)($r2['code'] ?? 0) !== 404) $r = $r2;
    }
    if (!empty($r['ok'])) return ['ok' => true, 'id' => $pid, 'price' => $priceToman, 'rial' => $rial];
    return ['ok' => false, 'error' => (string)($r['error'] ?? ('HTTP ' . ($r['code'] ?? 0))), 'code' => (int)($r['code'] ?? 0)];
}

/**
 * جمع‌آوری کارهای اصلاح از ردیف‌های ماتریس.
 * فقط مغایرت قیمت روی مقصدهایی که محصول دارند (id موجود).
 * $scope: all|woo|bsl
 */
/**
 * v10.118: کارهای اصلاح از ماتریس —
 *   price_woo / price_bsl  — اصلاح قیمت
 *   send_woo / send_bsl    — در پروفایل هست، در مقصد نیست → ارسال
 *   del_woo / del_bsl      — در پروفایل نیست، در مقصد هست → حذف/بایگانی
 */
function matrixFixDuplicateSplit(array $items, string $keep, bool $preferCoded = false): array {
    $items = array_values(array_filter($items, static function ($x) {
        return is_array($x) && (int)($x['id'] ?? 0) > 0;
    }));
    if (!$items) return ['keep' => null, 'drop' => []];
    if (count($items) === 1) return ['keep' => $items[0], 'drop' => []];
    foreach ($items as &$it) {
        if (isset($it['status']) && is_string($it['status'])) $it['wstatus'] = $it['status'];
    }
    unset($it);
    $pool=$items;$codedPreferred=false;
    if($preferCoded){
        $coded=[];$uncoded=[];
        foreach($items as $it){if(matrixTitleHasCode((string)($it['title']??'')))$coded[]=$it;else$uncoded[]=$it;}
        /* Apply this override only to a real coded/uncoded pair. All-coded or
           all-uncoded duplicate groups still honor newest/most-expensive. */
        if($coded&&$uncoded){$pool=$coded;$codedPreferred=true;}
    }
    $picked=dedupPickKeeper($pool, [
        'keep' => in_array($keep, ['newest', 'expensive'], true) ? $keep : 'newest',
        'tie' => 'newest',
        'prefer_active' => false,
    ]);
    if($codedPreferred&&is_array($picked['keep']??null)){
        $keeperId=(int)($picked['keep']['id']??0);$picked['drop']=array_values(array_filter($items,static fn($it)=>(int)($it['id']??0)!==$keeperId));
        $picked['coded_preferred']=true;
    }
    return $picked;
}

function matrixFixProfileMembership(array $data): array {
    $profiles = loadProfiles();
    $wanted = (string)($data['profile_filter'] ?? $data['profile'] ?? 'all');
    $suffixes = function_exists('matrixCollectSuffixes') ? matrixCollectSuffixes() : [];
    $keys = []; $bares = [];
    foreach ($profiles as $pk => $profile) {
        if (!is_array($profile)) continue;
        if ($wanted !== '' && $wanted !== 'all' && (string)$pk !== $wanted) continue;
        foreach (profileOrderedProducts($profile, null, true) as $p) {
            if (!is_array($p)) continue;
            $key = trim((string)($p['key'] ?? ''));
            $rec=['profile_key'=>(string)$pk,'profile'=>$profile,'product'=>$p];
            if ($key !== '') $keys[$key] = $rec;
            $bare = matrixBareTitle((string)($p['title'] ?? $p['name'] ?? ''), $suffixes);
            if ($bare !== '') $bares[$bare] = $rec;
        }
    }
    return ['keys'=>$keys, 'bares'=>$bares];
}

/** ردیابی امنٔ اجرای تک‌ردیفی؛ هیچ token/secret/header محرمانه‌ای برنمی‌گرداند. */
function matrixFixTraceSanitize($v,int $depth=0){
    if($depth>5)return '[depth-limited]';
    if(is_string($v))return mb_substr($v,0,4000);
    if(!is_array($v))return $v;
    $out=[];$n=0;foreach($v as $k=>$x){if(++$n>60){$out['_truncated']=true;break;}$lk=strtolower((string)$k);if(preg_match('/token|secret|authorization|consumer_key|cookie|password/',$lk)){$out[$k]='[redacted]';continue;}$out[$k]=matrixFixTraceSanitize($x,$depth+1);}return $out;
}
function matrixFixTraceExchange(array $job,array $response): void {
    if(empty($GLOBALS['S4_MATRIX_ROW_TRACE_ACTIVE']))return;
    $kind=(string)($job['kind']??'');$id=(int)($job['id']??0);$vid=(int)($job['vendor_id']??0);
    $req=['operation'=>$kind,'destination'=>str_ends_with($kind,'_woo')?'woocommerce':'basalam','method'=>'','endpoint'=>'','payload'=>[]];
    if($kind==='price_woo'){$req['method']='PUT';$req['endpoint']='products/'.$id;$req['payload']=['regular_price'=>(string)(int)($job['to']??0),'price'=>(string)(int)($job['to']??0)];}
    elseif($kind==='price_bsl'){$req['method']='PATCH';$req['endpoint']='vendors/'.$vid.'/products/'.$id;$req['payload']=['primary_price'=>(int)($job['to']??0)*10];}
    elseif($kind==='send_woo'){$req['method']='POST';$req['endpoint']='products';$req['payload']=['title'=>(string)($job['title']??''),'expected_price'=>(int)($job['expect']??0),'product_key'=>(string)($job['product_key']??'')];}
    elseif($kind==='send_bsl'){$req['method']='POST';$req['endpoint']='vendors/'.$vid.'/products';$req['payload']=['title'=>(string)($job['title']??''),'expected_price'=>(int)($job['expect']??0),'photo'=>'uploaded-before-create','product_key'=>(string)($job['product_key']??'')];}
    elseif($kind==='del_woo'||$kind==='dedup_woo'){$req['method']='DELETE';$req['endpoint']='products/'.$id;$req['payload']=['force'=>true];}
    elseif($kind==='del_bsl'||$kind==='dedup_bsl'){$req['method']='PATCH';$req['endpoint']='vendors/'.$vid.'/products/'.$id;$req['payload']=['status'=>'archived'];}
    $GLOBALS['S4_MATRIX_ROW_TRACE'][]=['layer'=>'operation_summary','at'=>microtime(true),'request'=>$req,'response'=>matrixFixTraceSanitize($response)];
}

function matrixFixCollectJobs(array $data, string $scope = 'all', array $viewFilters = [], string $duplicateKeep = 'newest'): array {
    $jobs = [];
    $errorHolds=matrixFixErrorsLoad();
    $exactRetry=trim((string)($viewFilters['exact_bare']??''));
    if($exactRetry!=='')matrixFixClearRowError($exactRetry);
    if (!in_array($duplicateKeep, ['newest', 'expensive'], true)) $duplicateKeep = 'newest';
    $preferCodedDuplicate=!empty($viewFilters['prefer_coded_duplicate']);
    /* عضویت را از خود پروفایل‌های ذخیره‌شده می‌خوانیم، نه فیلدهای قدیمی
       profile_price/profile_key در نتیجهٔ ماتریس. آن فیلدهای stale باعث می‌شدند
       محصول حذف‌شده از پروفایل، هنوز «دارای پروفایل» فرض و در مقصد باقی بماند. */
    $membership = matrixFixProfileMembership($data);
    $cnNow=loadConnections();$wooCfgNow=destPriceCfg($cnNow,'woocommerce');$bslCfgNow=destPriceCfg($cnNow,'basalam');
    $shopNow=[];foreach(bslAllShops($cnNow) as $shNow){$vNow=(int)($shNow['vendor_id']??0);if($vNow>0)$shopNow[$vNow]=$shNow;}
    $shopsMeta = [];
    foreach ((array)($data['shops'] ?? []) as $sh) {
        if (!is_array($sh)) continue;
        $vid = (int)($sh['vendor_id'] ?? 0);
        if ($vid > 0) $shopsMeta[$vid] = $sh;
    }
    $orderedRows=array_values((array)($data['rows']??[]));
    /* Match the visible table order, including a user-selected server-side sort. */
    $rowSort=trim((string)($viewFilters['sort']??''));$rowSortDir=strtolower((string)($viewFilters['sort_dir']??'asc'))==='desc'?'desc':'asc';
    $validRowSort=['title','profile','src_price','profile_price','woo_expect','woo_actual','status'];
    if($rowSort!==''&&(in_array($rowSort,$validRowSort,true)||preg_match('/^shop:\d+$/',$rowSort))){
        $statusRank=['mismatch'=>0,'missing'=>1,'only_profile'=>2,'only_dest'=>3,'partial'=>4,'ok'=>5];
        usort($orderedRows,static function($a,$b)use($rowSort,$rowSortDir,$statusRank){
            $numeric=in_array($rowSort,['src_price','profile_price','woo_expect','woo_actual'],true)||str_starts_with($rowSort,'shop:');
            if($rowSort==='title'){$av=(string)($a['title']??$a['bare']??'');$bv=(string)($b['title']??$b['bare']??'');}
            elseif($rowSort==='profile'){$av=(string)($a['profile']??'');$bv=(string)($b['profile']??'');}
            elseif($rowSort==='status'){$av=(int)($statusRank[(string)($a['status']??'')]??99);$bv=(int)($statusRank[(string)($b['status']??'')]??99);$numeric=true;}
            elseif($rowSort==='woo_actual'){$av=(int)($a['woo']['price']??0);$bv=(int)($b['woo']['price']??0);}
            elseif(str_starts_with($rowSort,'shop:')){$vid=(int)substr($rowSort,5);$av=(int)($a['shops'][$vid]['price']??$a['shops'][(string)$vid]['price']??0);$bv=(int)($b['shops'][$vid]['price']??$b['shops'][(string)$vid]['price']??0);}
            else{$av=(int)($a[$rowSort]??0);$bv=(int)($b[$rowSort]??0);}
            $cmp=$numeric?($av<=>$bv):strnatcasecmp((string)$av,(string)$bv);if($cmp===0)$cmp=strnatcasecmp((string)($a['bare']??''),(string)($b['bare']??''));return$rowSortDir==='desc'?-$cmp:$cmp;
        });
    }
    foreach ($orderedRows as $r) {
        if (!is_array($r) || !empty($r['is_report']) || !matrixRowMatchesViewFilters($r, $data, $viewFilters)) continue;
        $bare = (string)($r['bare'] ?? '');
        /* bulk pass temporarily ignores rows that failed previously; clicking that exact
           row is an explicit retry and clears the hold above. */
        if($exactRetry===''&&isset($errorHolds[$bare]))continue;
        $title = (string)($r['title'] ?? $bare);
        $productKey = trim((string)($r['key'] ?? ''));
        $member = $productKey !== '' ? ($membership['keys'][$productKey] ?? null) : null;
        if (!$member && $bare !== '') $member=$membership['bares'][$bare]??null;
        $hasProf = is_array($member);
        $memberProfile=$hasProf&&is_array($member['profile']??null)?$member['profile']:null;
        $memberProduct=$hasProf&&is_array($member['product']??null)?$member['product']:null;
        $memberRaw=$memberProduct?extractSourcePrice($memberProduct):(string)($r['src_price']??'0');
        $memberProfilePrice=$memberProfile?profileFinalPrice($memberProfile,$memberRaw):0;
        $wooExpectedNow=$memberProfilePrice>0?destAdjustPrice($memberProfilePrice,$wooCfgNow):0;
        /* job باید شناسهٔ واقعیِ عضو فعلی پروفایل را حمل کند. profile_key/key
           قدیمیِ ماتریس علت اصلی «در پروفایل پیدا نشد» در ارسال باسلام بود. */
        $resolvedProductKey=trim((string)($memberProduct['key']??$productKey));
        $base = ['bare' => $bare, 'title' => $title, 'only_dest' => !$hasProf,
            'profile_key' => (string)($member['profile_key'] ?? $r['profile_key'] ?? ''),
            'product_key' => $resolvedProductKey];

        $wooItems = [];
        if (is_array($r['woo'] ?? null)) $wooItems[] = $r['woo'];
        foreach ((array)($r['woo_extra'] ?? []) as $x) if (is_array($x)) $wooItems[] = $x;
        $wooPick = matrixFixDuplicateSplit($wooItems, $duplicateKeep, $preferCodedDuplicate);
        $woo = is_array($wooPick['keep'] ?? null) ? $wooPick['keep'] : null;
        if (($scope === 'all' || $scope === 'woo') && count($wooItems) > 1) {
            if ($hasProf) {
                foreach ((array)$wooPick['drop'] as $drop) $jobs[] = $base + [
                    'kind' => 'dedup_woo', 'id' => (int)$drop['id'], 'keeper' => $woo,
                    'duplicate_keep' => $duplicateKeep, 'prefer_coded_duplicate'=>$preferCodedDuplicate,
                ];
            } else {
                foreach ($wooItems as $drop) $jobs[] = $base + ['kind' => 'del_woo', 'id' => (int)$drop['id']];
                $woo = null; // all destination-only copies are removed
            }
        }

        if ($scope === 'all' || $scope === 'woo') {
            if ($hasProf && $woo) {
                $exp = $wooExpectedNow>0?$wooExpectedNow:(int)($r['woo_expect'] ?? 0); $got = (int)($woo['price'] ?? 0);
                if ($exp > 0 && $got > 0 && $exp !== $got) $jobs[] = $base + [
                    'kind' => 'price_woo', 'id' => (int)($woo['id'] ?? 0), 'from' => $got, 'to' => $exp,
                ];
            } elseif ($hasProf && !$woo && ($wooExpectedNow>0||(int)($r['woo_expect']??0)>0)) {
                $jobs[] = $base + ['kind' => 'send_woo', 'expect' => $wooExpectedNow>0?$wooExpectedNow:(int)$r['woo_expect']];
            } elseif (!$hasProf && $woo) {
                $jobs[] = $base + ['kind' => 'del_woo', 'id' => (int)($woo['id'] ?? 0)];
            }
        }

        $shopIds = array_unique(array_merge(array_keys($shopsMeta), array_keys((array)($r['shops'] ?? [])), array_keys((array)($r['shop_extra'] ?? []))));
        foreach ($shopIds as $vidRaw) {
            $vid = (int)$vidRaw; if ($vid <= 0) continue;
            $cellItems = [];
            $mainCell = $r['shops'][$vid] ?? $r['shops'][(string)$vid] ?? null;
            if (is_array($mainCell)) $cellItems[] = $mainCell;
            $extraCells = $r['shop_extra'][$vid] ?? $r['shop_extra'][(string)$vid] ?? [];
            foreach ((array)$extraCells as $x) if (is_array($x)) $cellItems[] = $x;
            $pick = matrixFixDuplicateSplit($cellItems, $duplicateKeep, $preferCodedDuplicate);
            $cell = is_array($pick['keep'] ?? null) ? $pick['keep'] : null;
            $sh = $shopsMeta[$vid] ?? [];
            $sname = (string)($cell['shop_name'] ?? $sh['name'] ?? $sh['shop_name'] ?? ('غرفه ' . $vid));
            if (($scope === 'all' || $scope === 'bsl') && count($cellItems) > 1) {
                if ($hasProf) {
                    foreach ((array)$pick['drop'] as $drop) $jobs[] = $base + [
                        'kind' => 'dedup_bsl', 'id' => (int)$drop['id'], 'vendor_id' => $vid,
                        'shop_name' => $sname, 'keeper' => $cell, 'duplicate_keep' => $duplicateKeep,
                        'prefer_coded_duplicate'=>$preferCodedDuplicate,
                    ];
                } else {
                    foreach ($cellItems as $drop) $jobs[] = $base + [
                        'kind' => 'del_bsl', 'id' => (int)$drop['id'], 'vendor_id' => $vid, 'shop_name' => $sname,
                    ];
                    $cell = null;
                }
            }
            if ($scope !== 'all' && $scope !== 'bsl') continue;
            $expectMap = (array)($r['shop_expect'] ?? []);
            $exp = (int)($cell['expect'] ?? $expectMap[$vid] ?? $expectMap[(string)$vid] ?? $r['bsl_expect'] ?? $r['profile_price'] ?? 0);
            if($hasProf&&$memberProfile&&isset($shopNow[$vid])&&extractPriceNum($memberRaw)>0){$curAdj=bslShopPriceForProfile($memberProfile,$memberRaw,$shopNow[$vid],(int)($bslCfgNow['round']??0));if((int)($curAdj['price']??0)>0)$exp=(int)$curAdj['price'];}
            if ($hasProf && $cell) {
                $got = (int)($cell['price'] ?? 0);
                if ($exp > 0 && $got > 0 && $exp !== $got) $jobs[] = $base + [
                    'kind' => 'price_bsl', 'id' => (int)($cell['id'] ?? 0), 'vendor_id' => $vid,
                    'shop_name' => $sname, 'from' => $got, 'to' => $exp,
                ];
            } elseif ($hasProf && !$cell && $exp > 0) {
                $jobs[] = $base + ['kind' => 'send_bsl', 'vendor_id' => $vid, 'shop_name' => $sname, 'expect' => $exp];
            } elseif (!$hasProf && $cell) {
                $jobs[] = $base + ['kind' => 'del_bsl', 'id' => (int)($cell['id'] ?? 0),
                    'vendor_id' => $vid, 'shop_name' => $sname];
            }
        }
    }
    return $jobs;
}

/** پیدا کردن محصول پروفایل با bare title / key */
function matrixFixFindProduct(string $bare, string $profileKey = '', string $productKey = ''): ?array {
    $suffixes = function_exists('matrixCollectSuffixes') ? matrixCollectSuffixes() : [];
    $profiles = loadProfiles();
    $tryList = [];
    if ($profileKey !== '' && isset($profiles[$profileKey])) {
        $tryList[$profileKey] = $profiles[$profileKey];
    } else {
        foreach ($profiles as $pk => $pr) {
            if (!is_array($pr)) continue;
            if ($profileKey !== '') {
                $nm = trim((string)($pr['name'] ?? $pk));
                if ($pk !== $profileKey && mb_strtolower($nm) !== mb_strtolower($profileKey)) continue;
            }
            $tryList[$pk] = $pr;
        }
        if (!$tryList) $tryList = $profiles;
    }
    foreach ($tryList as $pk => $profile) {
        if (!is_array($profile)) continue;
        $only = null;
        if ($productKey !== '') $only = [$productKey => true];
        $list = profileOrderedProducts($profile, $only, true);
        if ($productKey !== '' && !$list) {
            $list = profileOrderedProducts($profile, null, true);
        }
        foreach ($list as $p) {
            if (!is_array($p)) continue;
            if ($productKey !== '' && (string)($p['key'] ?? '') === $productKey) {
                return ['product' => $p, 'profile' => $profile, 'profile_key' => (string)$pk];
            }
            $b = matrixBareTitle((string)($p['title'] ?? ''), $suffixes);
            if ($b !== '' && $b === $bare) {
                return ['product' => $p, 'profile' => $profile, 'profile_key' => (string)$pk];
            }
        }
    }
    return null;
}

/** ساخت payload ووکامرس از محصول پروفایل */
function matrixFixBuildWooPayload(array $p, array $profile, array $cn): array {
    $w = $cn['woocommerce'] ?? [];
    $title = trim((string)($p['title'] ?? ''));
    $sfx = trim((string)($profile['titleSuffix'] ?? ''));
    if ($sfx === '') $sfx = trim((string)($cn['basalam']['title_suffix'] ?? ''));
    if ($sfx !== '' && mb_strpos($title, $sfx) === false) $title = trim($title . ' ' . $sfx);
    /* Never trust stored final_price here: coefficient/rounding changes make it
       stale. Correction must use the same current canonical calculation shown
       in Results. */
    $rawPrice=function_exists('extractSourcePrice')?extractSourcePrice($p):(string)($p['price']??'');
    $price = profileFinalPrice($profile, $rawPrice);
    $wooCfg = function_exists('destPriceCfg') ? destPriceCfg($cn, 'woocommerce') : ['mode' => 'none'];
    if ($price > 0 && ($wooCfg['mode'] ?? 'none') !== 'none' && function_exists('destAdjustPrice')) {
        $price = destAdjustPrice($price, $wooCfg);
    }
    $stock = function_exists('effectiveStock')
        ? effectiveStock($p, (int)($w['stock_quantity'] ?? 10))
        : (int)($w['stock_quantity'] ?? 10);
    $wp = [
        'name' => mb_substr($title, 0, 200),
        'type' => 'simple',
        'regular_price' => (string)max(0, $price),
        'status' => (string)($w['default_status'] ?? 'publish'),
        'manage_stock' => !empty($w['manage_stock']),
        'stock_quantity' => $stock,
    ];
    if (!empty($p['shortDesc']) || !empty($p['short_desc'])) {
        $wp['short_description'] = (string)($p['shortDesc'] ?? $p['short_desc']);
    }
    if (!empty($p['longDesc']) || !empty($p['long_desc'])) {
        $wp['description'] = (string)($p['longDesc'] ?? $p['long_desc']);
    }
    $img = trim((string)($p['image'] ?? ''));
    if ($img !== '' && preg_match('~^https?://~i', $img)) {
        $wp['images'] = [['src' => $img]];
    }
    $cat = (int)($profile['wooCategoryId'] ?? 0);
    if ($cat <= 0) $cat = (int)($w['default_category'] ?? 0);
    if ($cat > 0) $wp['categories'] = [['id' => $cat]];
    return $wp;
}

function matrixFixSendWoo(array $cn, array $found, int $expect = 0): array {
    $p = $found['product'];
    $profile = $found['profile'];
    $w = $cn['woocommerce'] ?? [];
    $wp = matrixFixBuildWooPayload($p, $profile, $cn);
    if ($expect > 0) $wp['regular_price'] = (string)$expect;
    $key = (string)($p['key'] ?? '');
    if (function_exists('wooUpsertWithMode')) {
        $r = wooUpsertWithMode($w, $wp, null, $key);
    } else {
        $r = ['ok' => false, 'error' => 'wooUpsertWithMode نیست'];
    }
    $id = (int)($r['body']['id'] ?? ($r['id'] ?? 0));
    if (!empty($r['ok']) && $id <= 0 && !empty($r['body']) && is_array($r['body'])) {
        $id = (int)($r['body']['id'] ?? 0);
    }
    /* direct may return id differently */
    if (!empty($r['ok']) && $id <= 0) $id = (int)($r['product_id'] ?? $r['id'] ?? 0);
    if (!empty($r['ok'])) {
        $price = (int)preg_replace('~\D~', '', (string)($wp['regular_price'] ?? '0'));
        return ['ok' => true, 'id' => $id, 'price' => $price, 'via' => (string)($r['via'] ?? 'api'), 'action' => (string)($r['action'] ?? 'upsert')];
    }
    return ['ok' => false, 'error' => (string)($r['error'] ?? ($r['message'] ?? 'ارسال WC ناموفق'))];
}

function matrixFixSendBsl(array $cn, array $found, int $vid, string $tok, int $expect = 0): array {
    $p = $found['product'];
    $profile = $found['profile'];
    /* محصول با قیمت خام خودش می‌رود؛ bslUpsertToShop تعدیل پروفایل و همان
       غرفه را دقیقاً یک بار اعمال می‌کند. نوشتن expect داخل price باعث اعمال
       دوبارهٔ ضریب روی قیمتِ از قبل تعدیل‌شده می‌شد. */
    $shop = null;
    foreach (function_exists('bslAllShops') ? bslAllShops($cn) : [] as $sh) {
        if ((int)($sh['vendor_id'] ?? 0) === $vid) { $shop = $sh; break; }
    }
    if (!$shop) {
        $shop = ['vendor_id' => $vid, 'token' => $tok, 'shop_name' => 'غرفه ' . $vid];
    } else {
        $shop['token'] = $tok !== '' ? $tok : (string)($shop['token'] ?? '');
    }
    $b = $cn['basalam'] ?? [];
    $opts = [
        'profile' => $profile,
        /* expect قیمت نهاییِ همان غرفه در ماتریس است؛ با گزینهٔ صریح از
           اعمال دوبارهٔ ضریب جلوگیری و همان عدد دقیق ارسال می‌شود. */
        'forced_price_toman' => max(0, $expect),
        /* ماتریس همین غرفه را کامل واکشی کرده؛ پیمایش دوبارهٔ کل کاتالوگ
           برای هر missing هم عملیات را متوقف‌نما می‌کرد هم بسیار کند بود. */
        'find_deep_scan' => false,
        'skip_find_existing' => true,
        'round' => (int)($b['price_round'] ?? 0),
        'stock' => (int)($b['stock'] ?? 10),
        'preparation_days' => (int)($b['preparation_days'] ?? 3),
        'weight' => (int)($b['weight'] ?? 500),
        'package_weight' => (int)($b['package_weight'] ?? 0),
        /* اصلاح انبوه برای ساخت فقط تصویر شاخص را آپلود می‌کند؛ گالری بعداً
           قابل تکمیل است و درخواست اضافه باعث rate-limit نمی‌شود. */
        'upload_max_photos' => 1,
        'profile_key' => (string)($found['profile_key'] ?? ''),
        'basalam_cfg' => $b,
        'category_id' => (int)($profile['bslCategoryId'] ?? ($b['category_id'] ?? 0)),
        'fallback_cat_ids' => bslCollectManualCategories(0, $profile, (array)($b['fallback_cat_ids'] ?? []), $b),
        'auto_category' => !empty($b['auto_category']) || (int)($profile['bslCategoryId'] ?? ($b['category_id'] ?? 0)) <= 0,
        'flat_cats' => function_exists('bslCatsAll') ? bslCatsAll($tok) : [],
        'cdata' => [],
    ];
    if (!function_exists('bslUpsertToShop')) {
        return ['ok' => false, 'error' => 'bslUpsertToShop نیست'];
    }
    $r = bslUpsertToShop($p, $shop, $opts);
    if (!empty($r['ok'])) {
        $id = (int)($r['id'] ?? 0);
        $rawCanonical = extractSourcePrice($p);
        $canonical = extractPriceNum($rawCanonical)>0
            ? bslShopPriceForProfile($profile,$rawCanonical,$shop,(int)($b['price_round']??0)) : [];
        $price = $expect > 0 ? $expect : (int)($canonical['price'] ?? 0);
        $profP = (int)($p['final_price'] ?? 0);
        if ($profP <= 0) $profP = profileFinalPrice($profile, (string)($p['price'] ?? ''));
        $bslCfg = function_exists('destPriceCfg') ? destPriceCfg($cn, 'basalam') : ['mode' => 'none'];
        if ($profP > 0 && ($bslCfg['mode'] ?? 'none') !== 'none' && function_exists('destAdjustPrice')) {
            $profP = destAdjustPrice($profP, $bslCfg);
        }
        if ($price <= 0 && $profP > 0 && function_exists('bslShopPriceFor')) {
            $adj = bslShopPriceFor($profP, $shop, (int)($bslCfg['round'] ?? 0));
            if (!empty($adj['price'])) $price = (int)$adj['price'];
        }
        if ($price <= 0) $price = $profP;
        return ['ok' => true, 'id' => $id, 'price' => $price, 'action' => (string)($r['action'] ?? 'upsert'), 'used_cat_id' => (int)($r['used_cat_id'] ?? 0)];
    }
    return ['ok' => false, 'error' => (string)($r['error'] ?? 'ارسال باسلام ناموفق'),
        'error_code'=>(int)($r['error_code']??0),'error_detail'=>(string)($r['error_detail']??''),
        'reason_kind'=>(string)($r['reason_kind']??''),
        'ai_cat_queued'=>!empty($r['ai_cat_queued']),
        'ai_cat_queue_id'=>(string)($r['ai_cat_queue_id']??''),
        'tried_cat_ids'=>array_values((array)($r['tried_cat_ids']??[])),
        'retry_after'=>max(0,(int)($r['retry_after']??0)),
        'rate_source'=>trim((string)($r['rate_source']??'')),
        'repair_attempted'=>!empty($r['repair_attempted']),
        'deferred_duplicate'=>!empty($r['deferred_duplicate']),'duplicate_name'=>!empty($r['duplicate_name'])];
}

function matrixFixDelWoo(array $cn, int $pid): array {
    if ($pid <= 0) return ['ok' => false, 'error' => 'id نامعتبر'];
    /* direct trash */
    if (function_exists('wooDirectAvailable') && wooDirectAvailable() && function_exists('wp_trash_post')) {
        try {
            $r = wp_trash_post($pid);
            if ($r) return ['ok' => true, 'via' => 'direct', 'id' => $pid];
        } catch (Throwable $e) { /* api */ }
    }
    $w = $cn['woocommerce'] ?? [];
    if (empty($w['store_url'])) return ['ok' => false, 'error' => 'WC تنظیمات ناقص'];
    $r = wooDeleteProduct($w, $pid, false);
    if (!empty($r['ok'])) return ['ok' => true, 'via' => 'api', 'id' => $pid];
    return ['ok' => false, 'error' => (string)($r['error'] ?? ('HTTP ' . ($r['code'] ?? 0)))];
}

function matrixFixDelBsl(array $cn, int $pid, int $vid): array {
    if ($pid <= 0) return ['ok' => false, 'error' => 'id نامعتبر'];
    if (function_exists('bslArchiveSmart')) {
        $r = bslArchiveSmart($cn, $pid, $vid);
        if (!empty($r['ok'])) return ['ok' => true, 'id' => $pid, 'vendor_id' => (int)($r['vendor_id'] ?? $vid)];
        return ['ok' => false, 'error' => (string)($r['msg'] ?? ('HTTP ' . ($r['code'] ?? 0)))];
    }
    $tok = function_exists('bslShopTokenFor') ? bslShopTokenFor($cn, $vid) : '';
    if ($tok === '') $tok = trim((string)($cn['basalam']['token'] ?? ''));
    if ($tok === '' || !function_exists('bslArchiveProduct')) {
        return ['ok' => false, 'error' => 'آرشیو باسلام در دسترس نیست'];
    }
    $r = bslArchiveProduct($tok, $vid, $pid);
    if (!empty($r['ok'])) return ['ok' => true, 'id' => $pid];
    return ['ok' => false, 'error' => (string)($r['error'] ?? 'آرشیو ناموفق')];
}

/** جزئیات استانداردِ یک اصلاح برای شمارنده‌ها و مودالِ مقصد */
function matrixFixDetail(string $target, string $destination, string $kind, string $title,
                         bool $ok, string $label, int $id = 0, array $extra = []): array {
    return array_merge([
        'ok' => $ok, 'fixed' => $ok, 'target' => $target,
        'destination' => $destination, 'kind' => $kind,
        'title' => $title, 'id' => $id, 'label' => $label,
    ], $extra);
}

/** افزودن/به‌روزرسانی دو ردیف گزارش در انتهای جدول */
function matrixFixAppendReportRows(array $stats): void {
    $data = matrixResultLoad();
    if (!$data || !isset($data['rows']) || !is_array($data['rows'])) return;
    $rows = [];
    foreach ($data['rows'] as $r) {
        if (!is_array($r)) continue;
        if (!empty($r['is_report']) || str_starts_with((string)($r['bare'] ?? ''), '__report_')) continue;
        $rows[] = $r;
    }
    $ok = (int)($stats['ok'] ?? 0);
    $fail = (int)($stats['fail'] ?? 0);
    $total = (int)($stats['total'] ?? 0);
    $sent = (int)($stats['sent'] ?? 0);
    $del = (int)($stats['deleted'] ?? 0);
    $priced = (int)($stats['priced'] ?? 0);
    $scope = (string)($stats['scope'] ?? 'all');
    $stopped = !empty($stats['stopped']);
    $details = is_array($stats['details'] ?? null) ? $stats['details'] : [];
    $lines = [];
    foreach (array_slice($details, -40) as $d) {
        if (!is_array($d)) continue;
        $mark = !empty($d['ok']) ? '✅' : '❌';
        $lines[] = $mark . ' ' . (string)($d['label'] ?? $d['title'] ?? '');
    }
    $summaryTxt = ($stopped ? '⏹ متوقف — ' : '✅ تمام — ')
        . "موفق {$ok} · ناموفق {$fail} از {$total}"
        . " · 💰قیمت {$priced} · 📤ارسال {$sent} · 🗑حذف {$del}"
        . ' · محدوده ' . $scope;
    /* خلاصهٔ مقصدها داخل خودِ ردیف گزارش هم بماند؛ UI جدید آن را به
       شمارندهٔ کلیک‌پذیر تبدیل می‌کند و UIهای قدیمی دست‌خالی نمی‌مانند. */
    $destinationLines = [];
    $destinationCounts = [];
    foreach ($details as $d) {
        if (!is_array($d) || empty($d['ok']) || empty($d['target'])) continue;
        $dest = (string)($d['destination'] ?? ($d['target'] === 'woo' ? 'ووکامرس' : 'باسلام'));
        $destinationCounts[$dest] = (int)($destinationCounts[$dest] ?? 0) + 1;
    }
    foreach ($destinationCounts as $dest => $nDest) {
        $destinationLines[] = '📍 ' . $dest . ': ' . $nDest . ' اصلاح موفق';
    }

    $rowWork = [
        'bare' => '__report_work__',
        'title' => '📋 گزارش کار انجام‌شده',
        'is_report' => true,
        'report_type' => 'work',
        'profile' => '—',
        'profile_key' => '',
        'profile_hits' => 0,
        'src_price' => 0,
        'profile_price' => 0,
        'woo_expect' => 0,
        'bsl_expect' => 0,
        'woo' => null,
        'shops' => [],
        'woo_tone' => 'na',
        'status' => 'report',
        'flags' => ['report'],
        'report_text' => $summaryTxt,
        'report_lines' => array_merge([
            '💰 اصلاح قیمت: ' . $priced,
            '📤 ارسال (در مقصد نبود): ' . $sent,
            '🗑 حذف/بایگانی (فقط مقصد): ' . $del,
            'محدوده: ' . $scope,
            'زمان: ' . date('Y-m-d H:i:s', (int)($stats['at'] ?? time())),
        ], $destinationLines),
        'fix_at' => time(),
    ];
    $rowResult = [
        'bare' => '__report_result__',
        'title' => '📊 نتیجهٔ عملیات',
        'is_report' => true,
        'report_type' => 'result',
        'profile' => '—',
        'profile_key' => '',
        'profile_hits' => 0,
        'src_price' => 0,
        'profile_price' => 0,
        'woo_expect' => 0,
        'bsl_expect' => 0,
        'woo' => null,
        'shops' => [],
        'woo_tone' => 'na',
        'status' => 'report',
        'flags' => ['report'],
        'report_text' => $summaryTxt,
        'report_lines' => array_merge($destinationLines, $lines ?: ['موردی ثبت نشد']),
        'report_ok' => $ok,
        'report_fail' => $fail,
        'report_total' => $total,
        'fix_at' => time(),
    ];
    $rows[] = $rowWork;
    $rows[] = $rowResult;
    $data['rows'] = $rows;
    $data['row_count'] = count($rows);
    $data['fix_stats'] = $stats;
    $data['fix_at'] = time();
    $data['reports'] = [$rowWork, $rowResult];
    $okSave = matrixResultSave($data);
    if (!$okSave) {
        matrixFixProgress(['log_add' => ['❌ ذخیرهٔ ردیف گزارش در فایل نتیجه ناموفق بود']]);
    } else {
        matrixFixProgress(['log_add' => ['💾 گزارش در فایل نتیجه ذخیره شد (' . count($rows) . ' ردیف)']]);
    }
}

/**
 * اجرای کامل اصلاح از روی ماتریس — سرورساید با progress/log زنده.
 * v10.118: قیمت + ارسال missing + حذف extra + دو ردیف گزارش.
 */
function matrixFixRun(array $opts = []): array {
    @set_time_limit(0);
    @ignore_user_abort(true);
    /* stop را caller پس از گرفتنِ lockِ واقعیِ همین کار مصرف می‌کند؛ این
       تابع از recon_auto هم صدا زده می‌شود و نباید در شروع، درخواستِ تازهٔ
       کاربر را بین lock و اولینِ probe پاک کند. */
    $scope = (string)($opts['scope'] ?? 'all');
    if (!in_array($scope, ['all', 'woo', 'bsl'], true)) $scope = 'all';
    $delayMs = max(50, min(2000, (int)($opts['delay_ms'] ?? 180)));
    $source = (string)($opts['source'] ?? 'manual');
    $periodicSource = (string)($opts['periodic_source'] ?? $source);
    $rowMode=!empty($opts['row_mode']);
    if (s4PeriodicMatrixFixBlocked($periodicSource)) {
        matrixFixProgress(['running'=>false,'done'=>true,'queued'=>false,'stale'=>false,
            'periodic_build_only'=>true,'phase'=>'periodic_build_only','source'=>'recon_auto',
            'log_add'=>['⏭ اصلاح دوره‌ای اجرا نشد؛ گزینهٔ «فقط ساخت جدول» روشن است']]);
        return ['ok'=>true,'skipped'=>true,'periodic_build_only'=>true,'reason'=>'build_only'];
    }
    $fixCp = is_array($opts['checkpoint'] ?? null) ? $opts['checkpoint'] : [];
    $duplicateKeep = (string)($fixCp['duplicate_keep'] ?? $opts['duplicate_keep'] ?? 'newest');
    if (!in_array($duplicateKeep, ['newest', 'expensive'], true)) $duplicateKeep = 'newest';
    $doneJobs = array_values(array_unique(array_map('strval', (array)($fixCp['done_jobs'] ?? []))));
    $doneJobSet = $doneJobs ? array_fill_keys($doneJobs, true) : [];
    /* شکست قطعی در همان اجرای worker فقط یک بار امتحان می‌شود. بدون این لیست،
       archive_first هر segment را از صفر می‌خواند و ۲۰ شکست اول تا ابد تکرار
       می‌شدند؛ cur کارت‌ها نیز دائماً ۱..۲۰ می‌چرخید. 429 عمداً attempted نیست. */
    $attemptedJobs=array_values(array_unique(array_map('strval',(array)($fixCp['attempted_jobs']??[]))));
    $attemptedJobSet=$attemptedJobs?array_fill_keys($attemptedJobs,true):[];
    $fixStartedAt = (int)($fixCp['started_at'] ?? time());
    /* v10.298: اگر child/هاست میان کار قطع شد، حتی شکست‌های پیشین نباید
       باعث بازگشت cursor به ابتدای صف شوند. اجرای دستی تازه بدون checkpoint
       همچنان همهٔ موارد را از اول ارزیابی می‌کند. */
    $resumeCursor = max(0, (int)($fixCp['cur'] ?? 0));
    /* هر اصلاح موفق فهرست jobهای snapshot را کوچک می‌کند؛ cursor عددی روی
       فهرست کوچک‌شده، کارهای باقی‌مانده را جا می‌اندازد. done_jobs مرجع resume
       است، پس برای ترتیب‌های patchشونده cursor همیشه از صفر ارزیابی می‌شود. */
    if(in_array((string)($fixCp['job_order']??''),['archive_first','row_order'],true))$resumeCursor=0;
    $jobKey = static function (array $j): string {
        return (string)($j['kind'] ?? '') . '|' . (string)($j['bare'] ?? '') . '|'
            . (int)($j['id'] ?? 0) . '|' . (int)($j['vendor_id'] ?? 0);
    };

    $data = matrixResultLoad();
    /* repair ردیف‌های حذف‌شدهٔ segmentهای قبلی، سپس ادامهٔ worker. زیر lock
       اختصاصی matrix-fix هستیم، پس ذخیره با patch همزمان race ندارد. */
    if($data&&$doneJobs&&matrixApplyCompletedDeleteOverlay($data,$doneJobs)>0)matrixResultSave($data);
    $minMatrixAt=max(0,(int)($opts['min_matrix_generated_at']??0));
    if (!$data || empty($data['rows'])) {
        matrixFixProgress([
            'running' => false, 'done' => true, 'error' => 'جدول مقایسه موجود نیست — اول بسازید',
            'pct' => 100, 'log_add' => ['❌ جدول مقایسه روی سرور نیست'],
        ]);
        return ['ok' => false, 'error' => 'no_matrix'];
    }
    if($minMatrixAt>0&&(int)($data['generated_at']??0)<$minMatrixAt){
        $msg='بازسازی تازهٔ جدول کامل نشد؛ اصلاح روی نتیجهٔ قدیمی اجرا نشد';
        matrixFixProgress(['running'=>false,'done'=>true,'error'=>$msg,'pct'=>100,'phase'=>'build_failed',
            'log_add'=>['❌ '.$msg]]);
        return ['ok'=>false,'error'=>'fresh_matrix_not_ready'];
    }

    $viewFilters=is_array($opts['view_filters']??null)?$opts['view_filters']:[];
    if(is_array($fixCp['view_filters']??null))$viewFilters=$fixCp['view_filters'];
    $jobs = matrixFixCollectJobs($data, $scope, $viewFilters, $duplicateKeep);
    /* مقصد خاموش اصلاً job و log اصلاح تولید نمی‌کند؛ نتیجهٔ قدیمی ماتریس
       نباید ووکامرس خاموش را دوباره وارد صف کند. */
    $cn = loadConnections();
    $requestedDest=array_key_exists('selected_destinations',$opts)&&is_array($opts['selected_destinations'])?$opts['selected_destinations']:($data['selected_destinations']??null);
    $selectedFix=array_fill_keys(matrixNormalizeDestinations($requestedDest,$cn),true);
    if (empty($cn['woocommerce']['enabled']) || !isset($selectedFix['woo'])) $jobs = array_values(array_filter($jobs, static fn($j) => !str_ends_with((string)($j['kind'] ?? ''), '_woo')));
    if (empty($cn['basalam']['enabled'])) $jobs = array_values(array_filter($jobs, static fn($j) => !str_ends_with((string)($j['kind'] ?? ''), '_bsl')));
    $jobs=array_values(array_filter($jobs,static function($j)use($selectedFix){return !str_ends_with((string)($j['kind']??''),'_bsl')||isset($selectedFix['bsl:'.(int)($j['vendor_id']??0)]);}));
    /* v10.333: matrixFixCollectJobs already emits every operation of row 1, then
       every operation of row 2, etc. Never regroup globally by operation type. */
    $total = count($jobs);
    $nPrice = $nSend = $nDel = $nOnlyDestDel = 0;
    foreach ($jobs as $j) {
        $k = (string)($j['kind'] ?? '');
        if (str_starts_with($k, 'price_')) $nPrice++;
        elseif (str_starts_with($k, 'send_')) $nSend++;
        elseif (str_starts_with($k, 'del_') || str_starts_with($k, 'dedup_')) { $nDel++; if(!empty($j['only_dest'])&&str_starts_with($k,'del_'))$nOnlyDestDel++; }
    }
    matrixFixProgress([
        'running' => true, 'done' => false, 'error' => '', 'pct' => 1,
        'phase' => 'start', 'started_at' => $fixStartedAt, 'source' => $source,
        'scope' => $scope, 'delay_ms' => $delayMs, 'duplicate_keep' => $duplicateKeep, 'job' => 'fix',
        'total' => $total, 'cur' => $resumeCursor, 'ok_n' => (int)($fixCp['ok_n'] ?? 0),
        'fail_n' => (int)($fixCp['fail_n'] ?? 0), 'skip_n' => (int)($fixCp['skip_n'] ?? 0),
        'sent_n' => (int)($fixCp['sent_n'] ?? 0), 'del_n' => (int)($fixCp['del_n'] ?? 0),
        'price_n' => (int)($fixCp['price_n'] ?? 0), 'done_jobs' => $doneJobs,
        'planned' => array_map(static function(array $j): array { return [
            'kind'=>(string)($j['kind']??''), 'title'=>(string)($j['title']??$j['bare']??''),
            'bare'=>(string)($j['bare']??''), 'id'=>(int)($j['id']??0),
            'shop'=>(string)($j['shop_name']??''), 'only_dest'=>!empty($j['only_dest']),
        ]; }, array_slice($jobs, 0, 500)),
        'planned_total' => $total, 'planned_limited' => $total > 500,
        'checkpoint' => ['scope' => $scope, 'duplicate_keep' => $duplicateKeep, 'job_order'=>'row_order', 'done_jobs' => $doneJobs, 'attempted_jobs'=>$attemptedJobs, 'view_filters' => $viewFilters, 'started_at' => $fixStartedAt,
            'ok_n' => (int)($fixCp['ok_n'] ?? 0), 'fail_n' => (int)($fixCp['fail_n'] ?? 0), 'skip_n'=>(int)($fixCp['skip_n']??0),
            'sent_n' => (int)($fixCp['sent_n'] ?? 0), 'del_n' => (int)($fixCp['del_n'] ?? 0),
            'price_n' => (int)($fixCp['price_n'] ?? 0)],
        'live' => [],
        'log_add' => array_merge([
            '🔧 شروع مغایرت‌گیری کامل از جدول — محدوده: ' . $scope . ' · نگه‌داری تکراری: ' . dedupKeepLabel($duplicateKeep),
            '📋 ' . $total . ' کار: 💰' . $nPrice . ' قیمت · 📤' . $nSend . ' ارسال · 🗑' . $nDel . ' حذف (فقط مقصد: ' . $nOnlyDestDel . ')',
        ], array_map(function ($j) {
            return '  → ' . (string)($j['kind'] ?? '') . ' · ' . mb_substr((string)($j['title'] ?? $j['bare'] ?? ''), 0, 40);
        }, array_slice($jobs, 0, 8))),
    ]);

    if ($total === 0) {
        /* وقتی جدول کاری برای اجرا ندارد، فقط یک نتیجهٔ عادی ثبت کن؛ جزئیات
           داخلیِ ردیف‌ها و نمونه‌های تشخیصی نباید در گزارش کاربر پخش شوند. */
        $emptyMsg = 'هیچ مغایرت قابل اجرایی در جدول پیدا نشد';
        $stats = [
            'at' => time(), 'ok' => 0, 'fail' => 0, 'total' => 0,
            'sent' => 0, 'deleted' => 0, 'priced' => 0,
            'stopped' => false, 'scope' => $scope, 'duplicate_keep' => $duplicateKeep, 'view_filters' => $viewFilters,
            'details' => [['ok' => true, 'label' => $emptyMsg]],
        ];
        if(!$rowMode)matrixFixAppendReportRows($stats);
        matrixFixProgress([
            'running' => false, 'done' => true, 'pct' => 100, 'phase' => 'done',
            'ok_n' => 0, 'fail_n' => 0, 'total' => 0, 'cur' => 0,
            'sent_n' => 0, 'del_n' => 0, 'price_n' => 0,
            'log_add' => ['ℹ️ ' . $emptyMsg],
            'finished_at' => time(),
        ]);
        return ['ok' => true, 'total' => 0, 'ok_n' => 0, 'fail_n' => 0, 'empty' => true];
    }

    $shopTok = [];
    foreach (function_exists('bslAllShops') ? bslAllShops($cn) : [] as $sh) {
        if (!is_array($sh)) continue;
        $vid = (int)($sh['vendor_id'] ?? 0);
        $tok = trim((string)($sh['token'] ?? ($cn['basalam']['token'] ?? '')));
        if ($vid > 0 && $tok !== '') $shopTok[$vid] = $tok;
    }
    $defTok = trim((string)($cn['basalam']['token'] ?? ''));

    $okN = (int)($fixCp['ok_n'] ?? 0); $failN = (int)($fixCp['fail_n'] ?? 0); $skipN=(int)($fixCp['skip_n']??0);
    /* checkpoint قدیمی attempted_jobs نداشت و همان ۲۰ خطا را هزاران بار
       می‌شمرد؛ شمار ناموفق را یک بار برای مهاجرت این run از نو آغاز کن. */
    if(!array_key_exists('attempted_jobs',$fixCp)&&$failN>0)$failN=0;
    $sentN = (int)($fixCp['sent_n'] ?? 0); $delN = (int)($fixCp['del_n'] ?? 0); $priceN = (int)($fixCp['price_n'] ?? 0);
    $stopped = false;
    $periodicBuildOnlyStop = false;
    $details = [];
    $rateLimited=false;$rateRetryAfter=0;
    $maxItems = max(0, (int)($opts['max_items'] ?? 0)); $segmentItems = 0;
    $continuousCronRun = $maxItems === 0 && !empty(matrixExecutionDecision()['accelerated']);

    foreach ($jobs as $ji => $job) {
        $jk = $jobKey($job);
        if ($ji < $resumeCursor || isset($doneJobSet[$jk]) || isset($attemptedJobSet[$jk])) continue;
        if (s4PeriodicMatrixFixBlocked($periodicSource, loadConnections())) {
            $periodicBuildOnlyStop = true;
            $stopCheckpoint=['scope'=>$scope,'duplicate_keep'=>$duplicateKeep,'job_order'=>'row_order',
                'done_jobs'=>$doneJobs,'attempted_jobs'=>$attemptedJobs,'view_filters'=>$viewFilters,
                'started_at'=>$fixStartedAt,'ok_n'=>$okN,'fail_n'=>$failN,'skip_n'=>$skipN,
                'sent_n'=>$sentN,'del_n'=>$delN,'price_n'=>$priceN,'cur'=>count($doneJobSet)+count($attemptedJobSet),'total'=>$total];
            matrixFixProgress(['running'=>false,'done'=>true,'queued'=>false,'stale'=>false,
                'periodic_build_only'=>true,'phase'=>'periodic_build_only','source'=>'recon_auto',
                'checkpoint'=>$stopCheckpoint,'finished_at'=>time(),
                'log_add'=>['⏭ گزینهٔ «فقط ساخت جدول» روشن شد؛ اصلاح دوره‌ای پیش از کار بعدی متوقف شد']]);
            break;
        }
        if (matrixFixStopRequested()) {
            $stopped = true;
            matrixFixProgress(['log_add' => ['⏹ توقف توسط کاربر']]);
            break;
        }
        $n = $ji + 1;
        $jobOk = false; $err = '';
        $pct = 5 + (int)round(90 * $n / max(1, $total));
        $title = mb_substr((string)$job['title'], 0, 48);
        $bare = (string)$job['bare'];
        $kind = (string)($job['kind'] ?? '');
        matrixFixProgress(['current_title'=>$title,'current_bare'=>$bare,'current_kind'=>$kind]);

        /* ========== PRICE WOO ========== */
        if ($kind === 'price_woo') {
            $from = (int)$job['from']; $to = (int)$job['to'];
            matrixFixProgress([
                'phase' => 'woo_fix', 'pct' => $pct, 'cur' => $n, 'total' => $total,
                'log_add' => ['💰 [' . $n . '/' . $total . '] WC قیمت · ' . $title
                    . ' — ' . number_format($from) . ' → ' . number_format($to)],
            ]);
            $res = matrixFixWooPrice($cn, (int)$job['id'], $to);
            matrixFixTraceExchange($job,$res);
            if (!empty($res['ok'])) {
                $jobOk = true; $okN++; $priceN++;
                matrixResultPatchRow($bare, [
                    'woo' => ['price' => $to, 'id' => (int)$job['id']],
                    'woo_tone' => 'ok', 'fix_woo_at' => time(), 'fix_woo_ok' => true,
                ]);
                $details[] = matrixFixDetail('woo', 'ووکامرس', 'price', $title, true, 'قیمت WC · ' . $title . ' → ' . number_format($to), (int)$job['id'], ['from' => $from, 'to' => $to]);
                matrixFixProgress([
                    'ok_n' => $okN, 'fail_n' => $failN, 'price_n' => $priceN,
                    'log_add' => ['  ✅ WC #' . (int)$job['id'] . ' · ' . number_format($to) . ' (' . ($res['via'] ?? '') . ')'],
                    'live_add' => ['title' => $title, 'bare' => $bare, 'ok' => true, 'kind' => 'price_woo', 'to' => $to, 't' => time()],
                ]);
            } else {
                $failN++;
                $err = (string)($res['error'] ?? 'خطا');
                $details[] = matrixFixDetail('woo', 'ووکامرس', 'price', $title, false, 'قیمت WC · ' . $title . ' — ' . $err, (int)$job['id'], ['error' => $err]);
                matrixFixProgress([
                    'ok_n' => $okN, 'fail_n' => $failN,
                    'log_add' => ['  ❌ WC · ' . $title . ' — ' . $err],
                    'live_add' => ['title' => $title, 'bare' => $bare, 'ok' => false, 'kind' => 'price_woo', 'error' => $err, 't' => time()],
                ]);
            }
        }
        /* ========== PRICE BSL ========== */
        elseif ($kind === 'price_bsl') {
            $from = (int)$job['from']; $to = (int)$job['to'];
            $vid = (int)($job['vendor_id'] ?? 0);
            $tok = $shopTok[$vid] ?? $defTok;
            $sname = (string)($job['shop_name'] ?? ('#' . $vid));
            matrixFixProgress([
                'phase' => 'bsl_fix', 'pct' => $pct, 'cur' => $n, 'total' => $total,
                'log_add' => ['💰 [' . $n . '/' . $total . '] ' . $sname . ' قیمت · ' . $title
                    . ' — ' . number_format($from) . ' → ' . number_format($to)],
            ]);
            if ($tok === '') {
                $failN++;
                $details[] = matrixFixDetail('bsl', $sname, 'price', $title, false, 'قیمت ' . $sname . ' · بدون توکن', (int)($job['id'] ?? 0), ['vendor_id' => $vid, 'error' => 'بدون توکن']);
                matrixFixProgress(['fail_n' => $failN, 'log_add' => ['  ❌ توکن غرفه نیست']]);
            } else {
                $res = matrixFixBslPrice($tok, $vid, (int)$job['id'], $to);
            matrixFixTraceExchange($job,$res);
                if (!empty($res['ok'])) {
                    $jobOk = true; $okN++; $priceN++;
                    matrixResultPatchRow($bare, [
                        'shops' => [$vid => [
                            'price' => $to, 'price_rial' => $to * 10, 'tone' => 'ok',
                            'id' => (int)$job['id'], 'expect' => $to,
                        ]],
                        'fix_bsl_at' => time(),
                    ]);
                    $details[] = matrixFixDetail('bsl', $sname, 'price', $title, true, 'قیمت ' . $sname . ' · ' . $title . ' → ' . number_format($to), (int)$job['id'], ['vendor_id' => $vid, 'from' => $from, 'to' => $to]);
                    matrixFixProgress([
                        'ok_n' => $okN, 'fail_n' => $failN, 'price_n' => $priceN,
                        'log_add' => ['  ✅ ' . $sname . ' #' . (int)$job['id'] . ' · ' . number_format($to)],
                        'live_add' => ['title' => $title, 'bare' => $bare, 'ok' => true, 'kind' => 'price_bsl', 'shop' => $sname, 'to' => $to, 't' => time()],
                    ]);
                } else {
                    $failN++;
                    $err = (string)($res['error'] ?? 'خطا');
                    $details[] = matrixFixDetail('bsl', $sname, 'price', $title, false, 'قیمت ' . $sname . ' · ' . $title . ' — ' . $err, (int)$job['id'], ['vendor_id' => $vid, 'error' => $err]);
                    matrixFixProgress([
                        'ok_n' => $okN, 'fail_n' => $failN,
                        'log_add' => ['  ❌ ' . $sname . ' · ' . $err],
                        'live_add' => ['title' => $title, 'bare' => $bare, 'ok' => false, 'kind' => 'price_bsl', 'error' => $err, 't' => time()],
                    ]);
                }
            }
        }
        /* ========== SEND WOO ========== */
        elseif ($kind === 'send_woo') {
            matrixFixProgress([
                'phase' => 'woo_send', 'pct' => $pct, 'cur' => $n, 'total' => $total,
                'log_add' => ['📤 [' . $n . '/' . $total . '] ارسال WC · ' . $title],
            ]);
            $found = matrixFixFindProduct($bare, (string)($job['profile_key'] ?? ''), (string)($job['product_key'] ?? ''));
            if (!$found) {
                $failN++;
                $details[] = matrixFixDetail('woo', 'ووکامرس', 'send', $title, false, 'ارسال WC · محصول در پروفایل پیدا نشد: ' . $title, 0, ['error' => 'در پروفایل پیدا نشد']);
                matrixFixProgress(['fail_n' => $failN, 'log_add' => ['  ❌ در پروفایل پیدا نشد']]);
            } else {
                $res = matrixFixSendWoo($cn, $found, (int)($job['expect'] ?? 0));
            matrixFixTraceExchange($job,$res);
                if (!empty($res['ok'])) {
                    $jobOk = true; $okN++; $sentN++;
                    $id = (int)($res['id'] ?? 0);
                    $price = (int)($res['price'] ?? 0);
                    matrixResultPatchRow($bare, [
                        'woo' => ['id' => $id, 'price' => $price, 'status' => 'publish', 'title' => $title],
                        'woo_tone' => 'ok',
                        'status' => 'ok',
                        'fix_send_woo_at' => time(),
                    ]);
                    $details[] = matrixFixDetail('woo', 'ووکامرس', 'send', $title, true, 'ارسال WC · ' . $title . ($id ? (' #' . $id) : ''), $id, ['to' => $price]);
                    matrixFixProgress([
                        'ok_n' => $okN, 'fail_n' => $failN, 'skip_n'=>$skipN, 'sent_n' => $sentN,
                        'log_add' => ['  ✅ ارسال WC' . ($id ? (' #' . $id) : '') . ' · ' . ($res['via'] ?? '')],
                        'live_add' => ['title' => $title, 'bare' => $bare, 'ok' => true, 'kind' => 'send_woo', 'id' => $id, 't' => time()],
                    ]);
                } else {
                    $failN++;
                    $err = (string)($res['error'] ?? 'خطا');
                    $details[] = matrixFixDetail('woo', 'ووکامرس', 'send', $title, false, 'ارسال WC · ' . $title . ' — ' . $err, 0, ['error' => $err]);
                    matrixFixProgress([
                        'ok_n' => $okN, 'fail_n' => $failN,
                        'log_add' => ['  ❌ ارسال WC — ' . $err],
                        'live_add' => ['title' => $title, 'bare' => $bare, 'ok' => false, 'kind' => 'send_woo', 'error' => $err, 't' => time()],
                    ]);
                }
            }
        }
        /* ========== SEND BSL ========== */
        elseif ($kind === 'send_bsl') {
            $vid = (int)($job['vendor_id'] ?? 0);
            $tok = $shopTok[$vid] ?? $defTok;
            $sname = (string)($job['shop_name'] ?? ('#' . $vid));
            matrixFixProgress([
                'phase' => 'bsl_send', 'pct' => $pct, 'cur' => $n, 'total' => $total,
                'log_add' => ['📤 [' . $n . '/' . $total . '] ارسال ' . $sname . ' · ' . $title],
            ]);
            $found = matrixFixFindProduct($bare, (string)($job['profile_key'] ?? ''), (string)($job['product_key'] ?? ''));
            if (!$found) {
                $failN++;
                $details[] = matrixFixDetail('bsl', $sname, 'send', $title, false, 'ارسال ' . $sname . ' · محصول پیدا نشد: ' . $title, 0, ['vendor_id' => $vid, 'error' => 'در پروفایل پیدا نشد']);
                matrixFixProgress(['fail_n' => $failN, 'log_add' => ['  ❌ در پروفایل پیدا نشد']]);
            } elseif ($tok === '') {
                $failN++;
                $details[] = matrixFixDetail('bsl', $sname, 'send', $title, false, 'ارسال ' . $sname . ' · بدون توکن', 0, ['vendor_id' => $vid, 'error' => 'بدون توکن']);
                matrixFixProgress(['fail_n' => $failN, 'log_add' => ['  ❌ توکن غرفه نیست']]);
            } else {
                $res = matrixFixSendBsl($cn, $found, $vid, $tok, (int)($job['expect'] ?? 0));
            matrixFixTraceExchange($job,$res);
                if(!empty($res['deferred_duplicate'])){
                    $queued=matrixQueueBslDuplicateRecovery([
                        'bare'=>$bare,'title'=>$title,'vendor_id'=>$vid,'shop_name'=>$sname,
                        'expect'=>(int)($job['expect']??0),'profile_key'=>(string)($job['profile_key']??''),
                        'product_key'=>(string)($job['product_key']??''),'queued_at'=>time(),
                    ]);
                    if(!empty($queued['ok'])){
                        /* این job در حلقهٔ اصلی مصرف می‌شود؛ نتیجهٔ واقعی بعداً از
                           پردازهٔ موازی مستقیماً روی همین ردیف patch می‌شود. */
                        $jobOk=true;$skipN++;
                        matrixResultPatchRow($bare,['fix_pending'=>'جستجوی موازی محصول هم‌نام در همهٔ وضعیت‌های باسلام','fix_pending_kind'=>'duplicate_recovery','fix_pending_at'=>time()]);
                        $details[]=matrixFixDetail('bsl',$sname,'duplicate_recovery_queued',$title,true,'جستجوی موازی نام تکراری · '.$title,0,['vendor_id'=>$vid,'fixed'=>false,'pending'=>true,'task_id'=>(string)($queued['task_id']??'')]);
                        matrixFixProgress(['skip_n'=>$skipN,'log_add'=>['  🧵 نام تکراری به پردازهٔ موازی سپرده شد؛ اصلاح اصلی ادامه دارد'],'live_add'=>['title'=>$title,'bare'=>$bare,'ok'=>true,'fixed'=>false,'pending'=>true,'kind'=>'duplicate_recovery','shop'=>$sname,'t'=>time()]]);
                    }else{
                        $failN++;$err='راه‌اندازی جستجوی موازی نام تکراری ناموفق بود: '.(string)($queued['error']??'خطا');
                        $details[]=matrixFixDetail('bsl',$sname,'duplicate_recovery',$title,false,$err,0,['vendor_id'=>$vid,'error'=>$err]);
                        matrixFixProgress(['fail_n'=>$failN,'log_add'=>['  ❌ '.$err]]);
                    }
                } elseif (!empty($res['ok'])) {
                    $jobOk = true; $okN++; $sentN++;
                    $id = (int)($res['id'] ?? 0);
                    $price = (int)($res['price'] ?? 0);
                    matrixResultPatchRow($bare, [
                        'shops' => [$vid => [
                            'id' => $id, 'price' => $price, 'price_rial' => $price * 10,
                            'tone' => 'ok', 'expect' => $price, 'shop_name' => $sname,
                            'title' => $title,
                        ]],
                        'fix_send_bsl_at' => time(),
                    ]);
                    $details[] = matrixFixDetail('bsl', $sname, 'send', $title, true, 'ارسال ' . $sname . ' · ' . $title . ($id ? (' #' . $id) : ''), $id, ['vendor_id' => $vid, 'to' => $price]);
                    matrixFixProgress([
                        'ok_n' => $okN, 'fail_n' => $failN, 'skip_n'=>$skipN, 'sent_n' => $sentN,
                        'log_add' => ['  ✅ ارسال ' . $sname . ($id ? (' #' . $id) : '') . ' · ' . ($res['action'] ?? '')],
                        'live_add' => ['title' => $title, 'bare' => $bare, 'ok' => true, 'kind' => 'send_bsl', 'shop' => $sname, 'id' => $id, 't' => time()],
                    ]);
                } else {
                    $err = (string)($res['error'] ?? 'خطا');
                    if((int)($res['error_code']??0)===429){
                        $rateLimited=true;$rateRetryAfter=max(30,min(300,(int)($res['retry_after']??0)));
                        $rateOrigin=trim((string)($res['rate_source']??''));
                        matrixFixProgress(['phase'=>'bsl_rate_wait','log_add'=>['⏳ HTTP 429 واقعی دریافت شد'.($rateOrigin!==''?' از '.$rateOrigin:'').'؛ همین محصول حفظ شد و worker پس از '.$rateRetryAfter.' ثانیه از checkpoint دوباره تلاش می‌کند']]);
                    }else{
                        $failN++;
                        if (!empty($res['ai_cat_queued'])) {
                            matrixResultPatchRow($bare, [
                                'fix_pending'      => 'کنار گذاشته شد برای تصحیح دسته‌بندی با هوش مصنوعی',
                                'fix_pending_kind' => 'category_ai_pending',
                                'fix_pending_at'   => time(),
                            ]);
                        }
                        $details[] = matrixFixDetail('bsl', $sname, 'send', $title, false, 'ارسال ' . $sname . ' · ' . $title . ' — ' . $err, 0, [
                            'vendor_id'     => $vid,
                            'error'         => $err,
                            'ai_cat_queued' => !empty($res['ai_cat_queued']),
                            'tried_cat_ids' => (array)($res['tried_cat_ids'] ?? []),
                        ]);
                        matrixFixProgress([
                            'ok_n' => $okN, 'fail_n' => $failN,
                            'log_add' => ['  ' . (!empty($res['ai_cat_queued']) ? '🤖❌ ' : '❌ ') . 'ارسال ' . $sname . ' — ' . $err . (!empty($res['error_detail'])?(' · '.mb_substr((string)$res['error_detail'],0,180)):'')],
                            'live_add' => ['title' => $title, 'bare' => $bare, 'ok' => false, 'kind' => (!empty($res['ai_cat_queued']) ? 'send_bsl_ai_cat' : 'send_bsl'), 'error' => $err, 't' => time()],
                        ]);
                    }
                }
            }
        }
        /* ========== DEL WOO ========== */
        elseif ($kind === 'del_woo' || $kind === 'dedup_woo') {
            $isDuplicateDelete = $kind === 'dedup_woo';
            matrixFixProgress([
                'phase' => 'woo_del', 'pct' => $pct, 'cur' => $n, 'total' => $total,
                'log_add' => ['🗑 [' . $n . '/' . $total . '] ' . ($isDuplicateDelete ? ('حذف تکراری WC (' . dedupKeepLabel((string)($job['duplicate_keep'] ?? 'newest')) . ') · ') : 'حذف WC · ') . $title . ' #' . (int)$job['id']],
            ]);
            $res = matrixFixDelWoo($cn, (int)$job['id']);
            matrixFixTraceExchange($job,$res);
            if (!empty($res['ok'])) {
                $jobOk = true; $okN++; $delN++;
                if ($isDuplicateDelete) {
                    $dataNow = matrixResultLoad();
                    foreach ((array)($dataNow['rows'] ?? []) as $rr) {
                        if ((string)($rr['bare'] ?? '') !== $bare) continue;
                        $keeper = is_array($job['keeper'] ?? null) ? $job['keeper'] : ($rr['woo'] ?? null);
                        $extras = [];
                        foreach ((array)($rr['woo_extra'] ?? []) as $x) {
                            $xid = (int)($x['id'] ?? 0);
                            if ($xid !== (int)$job['id'] && $xid !== (int)($keeper['id'] ?? 0)) $extras[] = $x;
                        }
                        if (is_array($keeper)) unset($keeper['dup']);
                        $patch = ['woo' => $keeper, 'woo_extra' => $extras, 'fix_dedup_woo_at' => time()];
                        if (!$extras) {
                            $patch['woo_dup'] = false;
                            $patch['flags'] = array_values(array_filter((array)($rr['flags'] ?? []), static fn($f) => $f !== 'dup_woo'));
                        }
                        matrixResultPatchRow($bare, $patch);
                        break;
                    }
                } else {
                    matrixResultPatchRow($bare, ['woo' => null, 'woo_tone' => 'na',
                        'status' => 'only_dest_removed', 'fix_del_woo_at' => time(), 'flags' => []]);
                    $dataNow = matrixResultLoad();
                    foreach ((array)($dataNow['rows'] ?? []) as $rr) {
                        if ((string)($rr['bare'] ?? '') !== $bare) continue;
                        $stillBsl = false;
                        foreach ((array)($rr['shops'] ?? []) as $c) if (!empty($c['id'])) $stillBsl = true;
                        matrixResultPatchRow($bare, ['woo' => null, 'woo_tone' => 'na',
                            'status' => $stillBsl ? 'only_dest' : 'removed',
                            'title' => $title . ' (حذف‌شده از WC)']);
                        break;
                    }
                }
                $details[] = matrixFixDetail('woo', 'ووکامرس', $isDuplicateDelete ? 'deduplicate' : 'delete', $title, true,
                    ($isDuplicateDelete ? ('حذف تکراری WC (' . dedupKeepLabel((string)($job['duplicate_keep'] ?? 'newest')) . ') · ') : 'حذف WC · ') . $title . ' #' . (int)$job['id'],
                    (int)$job['id'], $isDuplicateDelete ? ['criterion' => (string)($job['duplicate_keep'] ?? 'newest')] : []);
                matrixFixProgress([
                    'ok_n' => $okN, 'fail_n' => $failN, 'del_n' => $delN,
                    'log_add' => ['  ✅ حذف/زباله‌دان WC #' . (int)$job['id']],
                    'live_add' => ['title' => $title, 'bare' => $bare, 'ok' => true, 'kind' => $kind, 'id' => (int)$job['id'], 't' => time()],
                ]);
            } else {
                $failN++;
                $err = (string)($res['error'] ?? 'خطا');
                $details[] = matrixFixDetail('woo', 'ووکامرس', 'delete', $title, false, 'حذف WC · ' . $title . ' — ' . $err, (int)$job['id'], ['error' => $err]);
                matrixFixProgress([
                    'ok_n' => $okN, 'fail_n' => $failN,
                    'log_add' => ['  ❌ حذف WC — ' . $err],
                    'live_add' => ['title' => $title, 'bare' => $bare, 'ok' => false, 'kind' => 'del_woo', 'error' => $err, 't' => time()],
                ]);
            }
        }
        /* ========== DEL BSL ========== */
        elseif ($kind === 'del_bsl' || $kind === 'dedup_bsl') {
            $isDuplicateDelete = $kind === 'dedup_bsl';
            $vid = (int)($job['vendor_id'] ?? 0);
            $sname = (string)($job['shop_name'] ?? ('#' . $vid));
            matrixFixProgress([
                'phase' => 'bsl_del', 'pct' => $pct, 'cur' => $n, 'total' => $total,
                'log_add' => ['🗑 [' . $n . '/' . $total . '] ' . ($isDuplicateDelete ? ('بایگانی تکراری (' . dedupKeepLabel((string)($job['duplicate_keep'] ?? 'newest')) . ') ') : 'بایگانی ') . $sname . ' · ' . $title . ' #' . (int)$job['id']],
            ]);
            $res = matrixFixDelBsl($cn, (int)$job['id'], $vid);
            matrixFixTraceExchange($job,$res);
            if (!empty($res['ok'])) {
                $jobOk = true; $okN++; $delN++;
                $dataNow = matrixResultLoad();
                foreach ((array)($dataNow['rows'] ?? []) as $rr) {
                    if ((string)($rr['bare'] ?? '') !== $bare) continue;
                    $shops = is_array($rr['shops'] ?? null) ? $rr['shops'] : [];
                    $shopExtra = is_array($rr['shop_extra'] ?? null) ? $rr['shop_extra'] : [];
                    if ($isDuplicateDelete) {
                        $keeper = is_array($job['keeper'] ?? null) ? $job['keeper'] : ($shops[$vid] ?? null);
                        $shops[$vid] = $keeper;
                        $left = [];
                        foreach ((array)($shopExtra[$vid] ?? []) as $x) {
                            $xid = (int)($x['id'] ?? 0);
                            if ($xid !== (int)$job['id'] && $xid !== (int)($keeper['id'] ?? 0)) $left[] = $x;
                        }
                        $shopExtra[$vid] = $left;
                        if (is_array($keeper)) unset($shops[$vid]['dup']);
                        $stillDup = false;
                        foreach ($shopExtra as $more) if (!empty($more)) { $stillDup = true; break; }
                        $patch = ['shops' => $shops, 'shop_extra' => $shopExtra, 'fix_dedup_bsl_at' => time()];
                        if (!$stillDup) $patch['flags'] = array_values(array_filter((array)($rr['flags'] ?? []), static fn($f) => $f !== 'dup_bsl'));
                        matrixResultPatchRow($bare, $patch);
                    } else {
                        unset($shops[$vid],$shops[(string)$vid]);
                        matrixResultPatchRow($bare, ['shops' => [$vid=>null],
                            'status' => empty($shops) && empty($rr['woo']) ? 'removed' : (string)($rr['status'] ?? 'only_dest'),
                            'title' => $title . ' (بایگانی از ' . $sname . ')', 'fix_del_bsl_at' => time()]);
                    }
                    break;
                }
                $details[] = matrixFixDetail('bsl', $sname, $isDuplicateDelete ? 'deduplicate' : 'delete', $title, true,
                    ($isDuplicateDelete ? ('بایگانی تکراری (' . dedupKeepLabel((string)($job['duplicate_keep'] ?? 'newest')) . ') ') : 'بایگانی ') . $sname . ' · ' . $title . ' #' . (int)$job['id'],
                    (int)$job['id'], ['vendor_id' => $vid, 'criterion' => (string)($job['duplicate_keep'] ?? '')]);
                matrixFixProgress([
                    'ok_n' => $okN, 'fail_n' => $failN, 'del_n' => $delN,
                    'log_add' => ['  ✅ بایگانی ' . $sname . ' #' . (int)$job['id']],
                    'live_add' => ['title' => $title, 'bare' => $bare, 'ok' => true, 'kind' => $kind, 'shop' => $sname, 'id' => (int)$job['id'], 't' => time()],
                ]);
            } else {
                $failN++;
                $err = (string)($res['error'] ?? 'خطا');
                $details[] = matrixFixDetail('bsl', $sname, 'delete', $title, false, 'بایگانی ' . $sname . ' · ' . $title . ' — ' . $err, (int)$job['id'], ['vendor_id' => $vid, 'error' => $err]);
                matrixFixProgress([
                    'ok_n' => $okN, 'fail_n' => $failN,
                    'log_add' => ['  ❌ بایگانی ' . $sname . ' — ' . $err],
                    'live_add' => ['title' => $title, 'bare' => $bare, 'ok' => false, 'kind' => 'del_bsl', 'error' => $err, 't' => time()],
                ]);
            }
        }

        if(!$jobOk&&!$rateLimited){
            $lastDetail=$details?end($details):[];
            $rowError=$err!==''?$err:(string)($lastDetail['error']??$lastDetail['label']??'عملیات ناموفق');
            matrixFixRecordRowError($bare,$kind,$rowError);
            matrixResultPatchRow($bare,['fix_error'=>matrixFixErrorShort($rowError),'fix_error_kind'=>$kind,'fix_error_at'=>time()]);
        }
        if($rateLimited){
            $retryCp=['scope'=>$scope,'duplicate_keep'=>$duplicateKeep,'job_order'=>'row_order','done_jobs'=>$doneJobs,'attempted_jobs'=>$attemptedJobs,'view_filters'=>$viewFilters,'started_at'=>$fixStartedAt,
                'ok_n'=>$okN,'fail_n'=>$failN,'skip_n'=>$skipN,'sent_n'=>$sentN,'del_n'=>$delN,'price_n'=>$priceN,'cur'=>$ji,'total'=>$total];
            matrixFixProgress(['running'=>true,'done'=>false,'checkpoint'=>$retryCp,'cur'=>$ji,'total'=>$total]);
            return ['ok'=>true,'yielded'=>true,'resume_needed'=>true,'rate_limited'=>true,'retry_after'=>$rateRetryAfter,'total'=>$total,'cur'=>$ji];
        }

        /* موفق و ناموفق هر دو در این run مصرف می‌شوند؛ اجرای دستی تازه می‌تواند
           شکست‌ها را دوباره امتحان کند. rate-limit بالاتر return شده و مصرف نمی‌شود. */
        if ($jobOk) { $doneJobs[] = $jk; $doneJobSet[$jk] = true; }
        else { $attemptedJobs[]=$jk; $attemptedJobSet[$jk]=true; }
        $processedN=count($doneJobSet)+count($attemptedJobSet);
        $incomplete = $stopped;
        matrixFixProgress(['done_jobs' => $doneJobs,'attempted_jobs'=>$attemptedJobs,'processed_n'=>$processedN,
            'checkpoint' => ['scope' => $scope, 'duplicate_keep' => $duplicateKeep, 'job_order'=>'row_order', 'done_jobs' => $doneJobs, 'attempted_jobs'=>$attemptedJobs, 'view_filters' => $viewFilters, 'started_at' => $fixStartedAt,
                'ok_n' => $okN, 'fail_n' => $failN, 'skip_n'=>$skipN, 'sent_n' => $sentN, 'del_n' => $delN,
                'price_n' => $priceN, 'cur' => $n, 'total' => $total],
            'cur' => $n, 'total' => $total]);
        $effectiveDelayMs=str_ends_with($kind,'_bsl')?max(1000,$delayMs):$delayMs;
        usleep($effectiveDelayMs * 1000);
        $segmentItems++;
        /* Re-read the mode after every corrected row. Entering cron mode removes
           the old item cap now; leaving cron mode checkpoints now. */
        $liveDriver=matrixExecutionDecision();
        if($maxItems>0&&$segmentItems>=$maxItems&&!empty($liveDriver['accelerated'])){$maxItems=0;$continuousCronRun=true;}
        $driverHandoff=$continuousCronRun&&empty($liveDriver['accelerated']);
        if (($driverHandoff || ($maxItems > 0 && $segmentItems >= $maxItems)) && $n < $total) {
            $waitCron=empty($liveDriver['can_run']);
            matrixFixProgress(['running'=>true,'done'=>false,'worker'=>true,
                'phase'=>$waitCron?'در انتظار ضربان کران':'تحویل checkpoint به worker',
                'processed_n'=>count($doneJobSet)+count($attemptedJobSet),'checkpoint'=>['scope'=>$scope,'duplicate_keep'=>$duplicateKeep,'job_order'=>'row_order','done_jobs'=>$doneJobs,'attempted_jobs'=>$attemptedJobs,'view_filters'=>$viewFilters,
                    'started_at'=>$fixStartedAt,'ok_n'=>$okN,'fail_n'=>$failN,'skip_n'=>$skipN,'sent_n'=>$sentN,'del_n'=>$delN,'price_n'=>$priceN,'cur'=>$n,'total'=>$total]]);
            return ['ok'=>true,'yielded'=>true,'resume_needed'=>true,'scheduler_wait'=>$waitCron,'total'=>$total,'cur'=>$n,'checkpoint'=>true];
        }
    }

    if ($periodicBuildOnlyStop) {
        return ['ok'=>true,'skipped'=>true,'periodic_build_only'=>true,'reason'=>'build_only_enabled_during_run',
            'total'=>$total,'cur'=>count($doneJobSet)+count($attemptedJobSet)];
    }

    /* recount summary؛ با patch پردازهٔ duplicate موازی race نکند. */
    $sumFp=@fopen(SYNC_MATRIX_RESULT_PATCH_LOCK,'c');if($sumFp)@flock($sumFp,LOCK_EX);
    try{
        $dataF = matrixResultLoad();$mm = 0; $okRows = 0; $miss = 0;
        foreach ((array)($dataF['rows'] ?? []) as $rr) {
            if (!is_array($rr) || !empty($rr['is_report'])) continue;
            if ((string)($rr['status'] ?? '') === 'ok') $okRows++;
            if (in_array('price_mismatch', (array)($rr['flags'] ?? []), true) || (string)($rr['status'] ?? '') === 'mismatch') $mm++;
            if ((string)($rr['status'] ?? '') === 'missing' || (string)($rr['status'] ?? '') === 'only_profile') $miss++;
        }
        if ($dataF) {$sum=is_array($dataF['summary']??null)?$dataF['summary']:[];$sum['price_mismatch']=$mm;$sum['ok']=$okRows;$dataF['summary']=$sum;matrixResultSave($dataF);}
    }finally{if($sumFp){@flock($sumFp,LOCK_UN);@fclose($sumFp);}}

    $incomplete = $stopped || $failN > 0;
    $processedN=count($doneJobSet)+count($attemptedJobSet);
    $stats = [
        'at' => time(),
        'ok' => $okN, 'fail' => $failN, 'total' => $total,
        'partial' => $incomplete,
        'sent' => $sentN, 'deleted' => $delN, 'priced' => $priceN,
        'stopped' => $stopped, 'scope' => $scope, 'duplicate_keep' => $duplicateKeep, 'view_filters' => $viewFilters,
        'details' => $details,
    ];
    if(!$rowMode)matrixFixAppendReportRows($stats);

    matrixFixProgress([
        'running' => false, 'done' => true, 'partial' => $incomplete,
        'stale' => $incomplete, 'pct' => 100,
        'phase' => $stopped ? 'stopped' : ($incomplete ? 'partial' : 'done'),
        'ok_n' => $okN, 'fail_n' => $failN, 'skip_n'=>$skipN, 'cur' => $n ?? $total, 'total' => $total,
        'sent_n' => $sentN, 'del_n' => $delN, 'price_n' => $priceN, 'processed_n'=>$processedN,
        'finished_at' => time(),
        'done_jobs' => $doneJobs, 'attempted_jobs'=>$attemptedJobs,
        'checkpoint' => $incomplete ? ['scope' => $scope, 'duplicate_keep' => $duplicateKeep, 'job_order'=>'row_order', 'done_jobs' => $doneJobs, 'attempted_jobs'=>$attemptedJobs, 'view_filters' => $viewFilters, 'started_at' => $fixStartedAt,
            'ok_n' => $okN, 'fail_n' => $failN, 'skip_n'=>$skipN, 'sent_n' => $sentN, 'del_n' => $delN, 'price_n' => $priceN,
            'cur' => $n ?? 0, 'total' => $total] : null,
        'log_add' => [
            ($stopped ? '⏹ متوقف شد — ' : '✅ تمام — ')
            . 'موفق ' . $okN . ' · ناموفق ' . $failN . ' از ' . $total
            . ' · 💰' . $priceN . ' · 📤' . $sentN . ' · 🗑' . $delN,
            '📋 دو ردیف گزارش به انتهای جدول اضافه شد',
        ],
    ]);
    matrixFixStopClear();
    return [
        'ok' => true, 'partial' => $incomplete, 'total' => $total, 'ok_n' => $okN, 'fail_n' => $failN,
        'sent' => $sentN, 'deleted' => $delN, 'priced' => $priceN, 'stopped' => $stopped,
    ];
}

function matrixJobRun(array $opts = []): array {
    $bg = !empty($opts['background']);
    /* v10.129: cron و فراخوانی‌های داخلی هم باید همان checkpoint رابط را
       مصرف کنند؛ فقط دکمهٔ صریحِ resume نباید قادر به ادامه باشد. */
    if (!is_array($opts['checkpoint'] ?? null)) {
        $mp = matrixProgressRead();
        $mcp = is_array($mp['checkpoint'] ?? null) ? $mp['checkpoint'] : null;
        if (!empty($mcp) && empty($mp['done']) && is_array($mcp['profile_rows'] ?? null)) {
            $opts['checkpoint'] = $mcp;
        }
    }
    $lockFile = SYNC_MATRIX_LOCK_FILE;
    $fp = @fopen($lockFile, 'c');
    if (!$fp || !flock($fp, LOCK_EX | LOCK_NB)) {
        if ($fp) @fclose($fp);
        return ['ok' => false, 'error' => 'یک ساخت جدول در حال اجراست', 'running' => true];
    }
    $release = function () use ($fp, $lockFile) {
        @flock($fp, LOCK_UN);
        @fclose($fp);
    };
    if ($bg) {
        // caller already sent early response
    }
    try {
        $res = matrixBuild($opts);
    } catch (Throwable $e) {
        matrixProgress([
            'running' => false, 'done' => true, 'error' => $e->getMessage(), 'pct' => 100,
            'log_add' => ['❌ ' . $e->getMessage()],
        ]);
        $release();
        return ['ok' => false, 'error' => $e->getMessage()];
    }
    $release();
    return $res;
}

/** v10.262: فیلترهای چندگانهٔ امن و backward-compatible برای نمایش و اصلاح. */
function matrixNormalizeViewFilterRules(array $opts): array {
    $valid=['status','profile','present_dest','missing_dest','mismatch_dest','duplicate','presence','price','code_suffix'];
    $raw=is_array($opts['filters']??null)?$opts['filters']:[];$out=[];
    foreach($raw as $rule){
        if(!is_array($rule))continue;$type=trim((string)($rule['type']??''));$value=trim((string)($rule['value']??''));
        if($value!==''&&in_array($type,$valid,true))$out[]=['type'=>$type,'value'=>$value];
        if(count($out)>=20)break;
    }
    /* clients from v10.258–10.261 still send one legacy pair */
    if(!$out){$type=trim((string)($opts['filter_type']??''));$value=trim((string)($opts['filter_value']??''));if($value!==''&&in_array($type,$valid,true))$out[]=['type'=>$type,'value'=>$value];}
    return $out;
}
function matrixRowMatchesOneViewFilter(array $r,array $data,string $type,string $value): bool {
    $flags=(array)($r['flags']??[]);$st=(string)($r['status']??'');
    $hasProf=(int)($r['profile_hits']??0)>0||trim((string)($r['profile_key']??''))!=='';$dest=null;
    if($value==='woo')$dest=is_array($r['woo']??null)?$r['woo']:null;
    elseif(preg_match('/^bsl:(\d+)$/',$value,$m)){$vid=(int)$m[1];$dest=is_array($r['shops'][$vid]??null)?$r['shops'][$vid]:(is_array($r['shops'][(string)$vid]??null)?$r['shops'][(string)$vid]:null);}
    if($type==='status')return $st===$value;
    if($type==='profile')return (string)($r['profile_key']??'')===$value||(string)($r['profile']??'')===$value;
    if($type==='present_dest')return $dest!==null;
    if($type==='missing_dest')return $hasProf&&$dest===null;
    if($type==='mismatch_dest'){$tone=$value==='woo'?(string)($r['woo_tone']??''):(string)($dest['tone']??'');return $dest!==null&&in_array($tone,['bad','warn'],true);}
    if($type==='duplicate'){
        if($value==='any')return (bool)preg_grep('/^dup_/',$flags)||!empty($r['woo_dup'])||matrixProfileDuplicateCount($r)>0;
        if($value==='profile')return in_array('dup_profile',$flags,true)||matrixProfileDuplicateCount($r)>0;
        if($value==='woo')return in_array('dup_woo',$flags,true)||!empty($r['woo_dup']);
        return in_array('dup_bsl',$flags,true);
    }
    if($type==='presence'){
        $hasWoo=!empty($r['woo']);$shopN=count(array_filter((array)($r['shops']??[]),'is_array'));$shopTotal=count((array)($data['shops']??[]));
        if($value==='only_profile')return $hasProf&&!$hasWoo&&$shopN===0;
        if($value==='only_dest')return !$hasProf&&($hasWoo||$shopN>0);
        if($value==='in_all')return $hasProf&&$hasWoo&&$shopN>=$shopTotal;
        return $hasProf&&(!$hasWoo||$shopN<$shopTotal);
    }
    if($type==='price'){
        $pp=(int)($r['profile_price']??0);$wp=(int)($r['woo']['price']??0);$we=(int)($r['woo_expect']??0);
        if($value==='has_price')return $pp>0;if($value==='no_price')return $pp<=0;
        if($value==='woo_higher')return $wp>0&&$we>0&&$wp>$we;
        return $wp>0&&$we>0&&$wp<$we;
    }
    if($type==='code_suffix'){$has=matrixTitleHasCode((string)($r['title']??$r['bare']??''));return$value==='has_code'?$has:!$has;}
    return true;
}
/** جستجو/فیلترهای سریع همیشه AND هستند؛ قواعد پیشرفته با AND یا OR انتخابی ترکیب می‌شوند. */
function matrixRowMatchesViewFilters(array $r, array $data, array $opts): bool {
    $rowBare=(string)($r['bare']??'');
    /* Cell equalization may touch only this profile's source rows and coded
       destination-only rows carrying that profile's unique suffix. Uncoded
       miscellaneous products are never archived by this action. */
    $targetProfile=trim((string)($opts['target_profile_key']??''));
    if($targetProfile!==''){
        $profiles=loadProfiles();
        if(matrixRowProfileScopeKey($r,$profiles)!==$targetProfile)return false;
    }
    $exactBare=trim((string)($opts['exact_bare']??''));
    if($exactBare!==''&&!hash_equals($exactBare,$rowBare))return false;
    $selectedBares=array_values(array_unique(array_filter(array_map('strval',(array)($opts['selected_bares']??[])),static fn($x)=>$x!=='')));
    if($selectedBares&&!in_array($rowBare,$selectedBares,true))return false;
    $excludedBares=array_values(array_unique(array_filter(array_map('strval',(array)($opts['excluded_bares']??[])),static fn($x)=>$x!=='')));
    if($excludedBares&&in_array($rowBare,$excludedBares,true))return false;
    $q=matrixBareTitle((string)($opts['q']??''),[]);
    if($q!==''&&mb_strpos((string)($r['bare']??''),$q)===false
        &&mb_strpos(matrixBareTitle((string)($r['title']??''),[]),$q)===false)return false;
    $flags=(array)($r['flags']??[]);$st=(string)($r['status']??'');
    $hasAnyProblem=$st!=='ok'||!empty($r['fix_error'])||(bool)preg_grep('/^dup_/',$flags)||!empty($r['woo_dup'])||matrixProfileDuplicateCount($r)>0;
    if(!empty($opts['only_problem'])&&!$hasAnyProblem)return false;
    if(!empty($opts['only_dup'])&&!preg_grep('/^dup_/',$flags)&&empty($r['woo_dup'])&&matrixProfileDuplicateCount($r)<1)return false;
    if(!empty($opts['only_mismatch'])&&$st!=='mismatch'&&!in_array('price_mismatch',$flags,true))return false;
    if(!empty($opts['only_missing'])&&$st!=='missing'&&$st!=='only_profile'
        &&!in_array('missing_woo',$flags,true)&&!in_array('missing_bsl',$flags,true))return false;
    $rules=matrixNormalizeViewFilterRules($opts);if(!$rules)return true;
    $join=strtolower((string)($opts['filter_join']??'and'))==='or'?'or':'and';
    foreach($rules as $rule){$hit=matrixRowMatchesOneViewFilter($r,$data,$rule['type'],$rule['value']);if($join==='and'&&!$hit)return false;if($join==='or'&&$hit)return true;}
    return $join==='and';
}

/** v10.328: وضعیت chipها از خود ردیف‌های جاری محاسبه می‌شود، نه summary
 * زمان ساخت. اصلاح worker هر ردیف را patch می‌کند و این تابع همان لحظه اثرش را
 * در کل فایل/یکسان/مغایرت/missing/فقط مقصد/تکراری منعکس می‌کند. */
function matrixRowIsLiveActive(array $r): bool {
    if(!empty($r['is_report'])||str_starts_with((string)($r['bare']??''),'__report_'))return false;
    if((int)($r['profile_hits']??0)>0||trim((string)($r['profile_key']??''))!=='')return true;
    if(!empty($r['woo']['id']))return true;
    foreach((array)($r['shops']??[])as$c)if(is_array($c)&&!empty($c['id']))return true;
    return false;
}
function matrixLiveSummary(array $data): array {
    $sum=['total'=>0,'ok'=>0,'price_mismatch'=>0,'missing_woo'=>0,'missing_bsl'=>0,
        'extra_woo'=>0,'extra_bsl'=>0,'dup_profile'=>0,'dup_woo'=>0,'dup_bsl'=>0,
        'in_all'=>0,'only_profile'=>0,'only_dest'=>0];
    $selected=matrixNormalizeDestinations($data['selected_destinations']??null);$set=array_fill_keys($selected,true);$useWoo=isset($set['woo']);
    $shopIds=[];foreach((array)($data['shops']??[])as$sh){$vid=(int)($sh['vendor_id']??0);if($vid>0&&isset($set['bsl:'.$vid]))$shopIds[]=$vid;}
    foreach((array)($data['rows']??[])as$r){
        if(!is_array($r)||!matrixRowIsLiveActive($r))continue;$sum['total']++;
        $hasProf=(int)($r['profile_hits']??0)>0||trim((string)($r['profile_key']??''))!=='';
        $hasWoo=$useWoo&&!empty($r['woo']['id']);$wooBad=false;$wooMissing=false;
        if($useWoo&&$hasProf){if(!$hasWoo)$wooMissing=true;else$wooBad=in_array(matrixPriceTone((int)($r['woo_expect']??0),(int)($r['woo']['price']??0)),['bad','warn'],true);}
        $shopPresent=0;$shopMissing=0;$shopBad=false;$dupBsl=false;
        foreach($shopIds as$vid){$c=is_array($r['shops'][$vid]??null)?$r['shops'][$vid]:(is_array($r['shops'][(string)$vid]??null)?$r['shops'][(string)$vid]:null);
            if($c&&!empty($c['id'])){$shopPresent++;$expect=(int)($c['expect']??$r['shop_expect'][$vid]??$r['bsl_expect']??0);if(in_array(matrixPriceTone($expect,(int)($c['price']??0)),['bad','warn'],true))$shopBad=true;if(!empty($c['dup']))$dupBsl=true;}
            elseif($hasProf)$shopMissing++;
            foreach((array)($r['shop_extra'][$vid]??[])as$x)if(is_array($x)&&!empty($x['id'])){$dupBsl=true;break;}
        }
        if(matrixProfileDuplicateCount($r)>0)$sum['dup_profile']++;
        if(!empty($r['woo_dup'])||!empty($r['woo_extra']))$sum['dup_woo']++;
        if($dupBsl)$sum['dup_bsl']++;
        if($wooMissing)$sum['missing_woo']++;if($shopMissing>0)$sum['missing_bsl']++;
        if($wooBad||$shopBad)$sum['price_mismatch']++;
        if(!$hasProf&&$hasWoo)$sum['extra_woo']++;if(!$hasProf&&$shopPresent>0)$sum['extra_bsl']++;
        $anyDest=$hasWoo||$shopPresent>0;
        $allOk=(!$useWoo||($hasWoo&&!$wooBad))&&$shopMissing===0&&!$shopBad;
        if($hasProf&&$allOk){$sum['ok']++;$sum['in_all']++;}
        elseif($hasProf&&!$anyDest)$sum['only_profile']++;
        elseif(!$hasProf&&$anyDest)$sum['only_dest']++;
    }
    return $sum;
}

/** فیلتر + صفحه‌بندی روی نتیجهٔ ذخیره‌شده (بدون rebuild) */
function matrixQueryPage(array $opts = []): array {
    $prog = matrixProgressRead(false);
    $useLive = !empty($opts['live_fill']) && is_file(SYNC_MATRIX_LIVE_FILE)
        && (!empty($prog['running']) || !empty($prog['yielded']) || !empty($prog['partial']));
    $data = $useLive ? json_decode((string)@file_get_contents(SYNC_MATRIX_LIVE_FILE), true) : matrixResultLoad();
    if (!is_array($data)) $data = [];
    if($data)matrixFixApplyErrors($data);
    $liveFixProg=function_exists('matrixFixProgressRead')?matrixFixProgressRead():[];
    if($data&&is_array($liveFixProg['checkpoint']['done_jobs']??null))matrixApplyCompletedDeleteOverlay($data,$liveFixProg['checkpoint']['done_jobs']);
    if(!$useLive&&$data&&((string)($data['pricing_signature']??'')!==matrixPricingFingerprint())){
        matrixRefreshExpectedPrices('lazy_signature_check');$data=matrixResultLoad();
    }
    if (!$data || empty($data['rows'])) {
        return [
            'ok' => false,
            'error' => 'هنوز جدولی ساخته نشده',
            'need_build' => true,
            'running' => !empty($prog['running']),
            'progress' => $prog,
        ];
    }
    $filterRules=matrixNormalizeViewFilterRules($opts);
    $filterJoin=strtolower((string)($opts['filter_join']??'and'))==='or'?'or':'and';
    $opts['filters']=$filterRules;$opts['filter_join']=$filterJoin;
    /* legacy response fields remain for old embedded/plugin clients */
    $filterType=(string)($filterRules[0]['type']??'');$filterValue=(string)($filterRules[0]['value']??'');
    /* گزینه‌های دراپ‌داون از کل فایل نتیجه ساخته می‌شوند، نه فقط صفحهٔ فعلی. */
    $profileOptions = [];
    foreach ((array)$data['rows'] as $fr) {
        if (!is_array($fr) || !empty($fr['is_report'])) continue;
        $fk=trim((string)($fr['profile_key']??'')); $fn=trim((string)($fr['profile']??''));
        if ($fk!=='' || $fn!=='') $profileOptions[$fk!==''?$fk:$fn]=$fn!==''?$fn:$fk;
    }
    natcasesort($profileOptions);
    $all = [];
    foreach ((array)$data['rows'] as $r) {
        if (!is_array($r)) continue;
        $isRep = !empty($r['is_report']) || str_starts_with((string)($r['bare'] ?? ''), '__report_');
        if(!$isRep&&!matrixRowIsLiveActive($r))continue;
        if (!$isRep && !matrixRowMatchesViewFilters($r,$data,$opts)) continue;
        $all[] = $r;
    }
    /* گزارش‌ها را جدا کن و فقط در صفحهٔ آخر بچسبان */
    $reports = [];
    $main = [];
    foreach ($all as $rr) {
        if (!empty($rr['is_report']) || str_starts_with((string)($rr['bare'] ?? ''), '__report_')) $reports[] = $rr;
        else $main[] = $rr;
    }
    $filteredStatusCounts = [];
    foreach ($main as $mr) {
        $ms = (string)($mr['status'] ?? 'unknown');
        $filteredStatusCounts[$ms] = ($filteredStatusCounts[$ms] ?? 0) + 1;
    }
    /* v10.257: مرتب‌سازی واقعی سمت سرور، پیش از صفحه‌بندی؛ نه فقط ردیف‌های صفحهٔ جاری. */
    $sort = trim((string)($opts['sort'] ?? ''));
    $sortDir = strtolower((string)($opts['sort_dir'] ?? 'asc')) === 'desc' ? 'desc' : 'asc';
    $validSort = ['title','profile','src_price','profile_price','woo_expect','woo_actual','status'];
    if ($sort !== '' && !in_array($sort, $validSort, true) && !preg_match('/^shop:\d+$/', $sort)) $sort = '';
    if ($sort !== '') {
        $statusRank = ['mismatch'=>0,'missing'=>1,'only_profile'=>2,'only_dest'=>3,'partial'=>4,'ok'=>5];
        usort($main, static function ($a, $b) use ($sort, $sortDir, $statusRank) {
            $numeric = in_array($sort, ['src_price','profile_price','woo_expect','woo_actual'], true) || str_starts_with($sort, 'shop:');
            if ($sort === 'title') { $av=(string)($a['title']??$a['bare']??''); $bv=(string)($b['title']??$b['bare']??''); }
            elseif ($sort === 'profile') { $av=(string)($a['profile']??''); $bv=(string)($b['profile']??''); }
            elseif ($sort === 'status') { $av=(int)($statusRank[(string)($a['status']??'')]??99); $bv=(int)($statusRank[(string)($b['status']??'')]??99); $numeric=true; }
            elseif ($sort === 'woo_actual') { $av=(int)($a['woo']['price']??0); $bv=(int)($b['woo']['price']??0); }
            elseif (str_starts_with($sort, 'shop:')) { $vid=(int)substr($sort,5); $av=(int)($a['shops'][$vid]['price']??$a['shops'][(string)$vid]['price']??0); $bv=(int)($b['shops'][$vid]['price']??$b['shops'][(string)$vid]['price']??0); }
            else { $av=(int)($a[$sort]??0); $bv=(int)($b[$sort]??0); }
            $cmp=$numeric?($av<=>$bv):strnatcasecmp((string)$av,(string)$bv);
            if ($cmp===0) $cmp=strnatcasecmp((string)($a['bare']??''),(string)($b['bare']??''));
            return $sortDir==='desc' ? -$cmp : $cmp;
        });
    }
    $page = max(1, (int)($opts['page'] ?? 1));
    $per = (int)($opts['per_page'] ?? 50);
    if ($per < 10) $per = 10;
    if ($per > 500) $per = 500;
    $total = count($main) + count($reports);
    $pages = max(1, (int)ceil(max(1, count($main)) / max(1, $per)));
    if ($page > $pages) $page = $pages;
    $slice = array_slice($main, ($page - 1) * $per, $per);
    if ($page >= $pages && $reports) {
        $slice = array_merge($slice, $reports);
    }
    $prog = matrixProgressRead(false);
    $fixProg = $liveFixProg;$queryFixRunning=!empty($fixProg['running'])&&empty($fixProg['queued']);
    /* گزارش‌ها همیشه جداگانه هم برگردند (نه فقط صفحهٔ آخر) */
    $allReports = [];
    if (!empty($data['reports']) && is_array($data['reports'])) {
        foreach ($data['reports'] as $rr) {
            if (is_array($rr)) $allReports[] = $rr;
        }
    }
    if (!$allReports) {
        foreach ((array)($data['rows'] ?? []) as $rr) {
            if (!is_array($rr)) continue;
            if (!empty($rr['is_report']) || str_starts_with((string)($rr['bare'] ?? ''), '__report_')) {
                $allReports[] = $rr;
            }
        }
    }
    $querySelected=matrixNormalizeDestinations($data['selected_destinations']??null);
    $destOptions = in_array('woo',$querySelected,true)?[['value'=>'woo','label'=>'ووکامرس']]:[];
    foreach ((array)($data['shops']??[]) as $ds) {
        if (!is_array($ds) || (int)($ds['vendor_id']??0)<=0) continue;
        $destOptions[]=['value'=>'bsl:'.(int)$ds['vendor_id'],'label'=>(string)($ds['name']??('#'.(int)$ds['vendor_id']))];
    }
    $profileOptionRows=[]; foreach($profileOptions as $pv=>$pl)$profileOptionRows[]=['value'=>(string)$pv,'label'=>(string)$pl];
    $liveSummaryAll=matrixLiveSummary($data);
    /* chipهای وضعیت باید دقیقاً دربارهٔ «این فیلتر» باشند؛ فقط chip کل فایل
       summary کل را نشان می‌دهد. بنابراین هر تغییر جستجو/AND/OR همان لحظه
       همهٔ شمارنده‌های وضعیت را نیز بازحساب می‌کند. */
    $filteredData=$data;$filteredData['rows']=$main;$liveSummary=matrixLiveSummary($filteredData);
    return [
        'ok' => true,
        'from_file' => true,
        'server_side' => true,
        'filter_type'=>$filterType, 'filter_value'=>$filterValue,
        'filters'=>$filterRules, 'filter_join'=>$filterJoin,
        'filter_options'=>['destinations'=>$destOptions,'profiles'=>$profileOptionRows],
        'sort' => $sort, 'sort_dir' => $sortDir,
        'page' => $page,
        'per_page' => $per,
        'pages' => $pages,
        'total' => $total,
        'actionable_total' => count($main),
        'filtered_status_counts' => (object)$filteredStatusCounts,
        'summary' => $liveSummary,
        'summary_all' => $liveSummaryAll,
        'selected_destinations'=>$querySelected,
        'shops' => $data['shops'] ?? [],
        'woo_cfg' => $data['woo_cfg'] ?? [],
        'bsl_cfg' => $data['bsl_cfg'] ?? [],
        'rows' => $slice,
        'reports' => $allReports,
        'fix_stats' => is_array($data['fix_stats'] ?? null) ? $data['fix_stats'] : null,
        'fix_at' => (int)($data['fix_at'] ?? 0),
        'woo_error' => $data['woo_error'] ?? '',
        'bsl_error' => $data['bsl_error'] ?? '',
        'woo_count' => $data['woo_count'] ?? 0,
        'generated_at' => $data['generated_at'] ?? 0,
        'source' => $data['source'] ?? '',
        'row_count_all' => (int)$liveSummaryAll['total'],
        'live_partial' => !empty($data['live_partial']),
        'running' => !empty($prog['running']) || $queryFixRunning || !empty($fixProg['queued']),
        'progress' => $queryFixRunning || (!empty($fixProg['done']) && empty($prog['running']) && empty($fixProg['queued'])) ? $fixProg : $prog,
        'fix_progress' => $queryFixRunning ? $fixProg : array_intersect_key($fixProg,array_fill_keys(['running','queued','done','phase','pct','cur','total','ok_n','fail_n','processed_n'],true)),
        'note' => 'خواندن از فایل سرور · بدون rebuild · صفحه‌بندی سمت سرور',
    ];
}

// --- endpoints ---
/* v10.238: توقف مستقل ساخت جدول؛ checkpoint در اولین نقطهٔ امن حفظ می‌شود. */
if (isset($_GET['sync_matrix_stop']) || (($_POST['action'] ?? '') === 'sync_matrix_stop')) {
    header('Content-Type: application/json; charset=UTF-8');
    @file_put_contents(SYNC_MATRIX_STOP_FILE, json_encode(['at' => microtime(true), 'by' => 'user'], JSON_UNESCAPED_UNICODE), LOCK_EX);
    /* اگر job هنوز pending است، همان‌جا از صف لغو شود؛ در حالت running فایل stop
       را در اولین مرز امن می‌بیند. این مانع شروع دیرهنگام بعد از زدن توقف است. */
    if (function_exists('s4WorkerQueueMutate')) {
        s4WorkerQueueMutate(function (&$q) {
            $now=time();
            foreach ($q['entries'] as &$e) {
                if (!is_array($e) || (string)($e['type']??'')!=='matrix_build' || !in_array((string)($e['status']??''),['pending','running'],true)) continue;
                $e['status']='cancelled'; $e['updated_at']=$now; $e['done_at']=$now; $e['cancel_requested_at']=$now; $e['error']='stopped_by_user';
            }
            unset($e); return ['ok'=>true];
        });
    }
    /* v10.240: وضعیت UI همان لحظه متوقف می‌شود؛ worker اگر هنوز زنده باشد
       فایل stop را در نقطهٔ امن بعدی می‌بیند و همین checkpoint را تثبیت می‌کند. */
    $stopState = matrixProgressRead();
    matrixProgress(['running' => false, 'done' => true, 'stopped' => true, 'partial' => true,
        'stop_requested' => true, 'phase' => 'stopped', 'finished_at' => time(),
        'checkpoint' => is_array($stopState['checkpoint'] ?? null) ? $stopState['checkpoint'] : null,
        'log_add' => ['⏹ ساخت جدول متوقف شد؛ checkpoint حفظ شد']]);
    $terminated=matrixTerminateRunner($stopState);
    echo json_encode(['ok' => true, 'stop_requested' => true, 'stopped' => true,'runner'=>$terminated], JSON_UNESCAPED_UNICODE);
    exit;
}
/* v10.242: endpoint فیدبک جمع‌وجور؛ بدون dump کردن هزاران ردیف checkpoint. */
if (isset($_GET['sync_matrix_feedback']) || (($_POST['action'] ?? '') === 'sync_matrix_feedback')) {
