        $probe = ['ok' => !empty($r['ok']), 'page'=>$probePage,'code' => (int)($r['code'] ?? 0),
            'ms' => (int)round((microtime(true) - $t0) * 1000),
            'rows' => is_array($r['body'] ?? null) ? count($r['body']) : 0,
            'error' => mb_substr((string)($r['error'] ?? ''), 0, 180)];
    }
    $logs = array_slice(is_array($p['log'] ?? null) ? $p['log'] : [], -12);
    echo json_encode(['ok' => true, 'version' => APP_VERSION,
        'running' => !empty($p['running']), 'phase' => (string)($p['phase'] ?? ''),
        'pct' => (int)($p['pct'] ?? 0), 'fetch_mode' => (string)($p['fetch_mode'] ?? 'serial'),
        'slice_seconds' => (int)($p['slice_seconds'] ?? ($cp['slice_seconds'] ?? 8)), 'stopped' => !empty($p['stopped']),
        'yielded' => !empty($p['yielded']), 'error' => (string)($p['error'] ?? ''),
        'lock_held' => $lockHeld, 'lock_recovered' => !empty($p['lock_recovered']),
        'profile_rows' => count((array)($cp['profile_rows'] ?? [])),
        'profiles_done' => count((array)($cp['profiles_done'] ?? [])),
        'woo_checkpoint_rows' => count((array)($cp['woo_rows'] ?? [])),
        'woo_checkpoint_page' => (int)($cp['woo_page'] ?? 0),
        'woo_done' => !empty($cp['woo_done']),
        'woo_cursor_rows' => count((array)($wooCur['rows'] ?? [])),
        'woo_cursor_page' => (int)($wooCur['page'] ?? 0),
        'woo_fetched_live' => (int)($p['woo_fetched'] ?? 0),
        'woo_page_live' => (int)($p['woo_page'] ?? 0),
        'probe' => $probe, 'logs' => $logs], JSON_UNESCAPED_UNICODE);
    exit;
}

/* v10.369: نبض مرورگر برای کران داخلی. مرجع ثابت در JS این endpoint را
   صدا می‌زند؛ خود receiver تنظیم ذخیره‌شده و فاصله را اعمال می‌کند. */
if(isset($_GET['internal_cron_feedback'])){
    header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store');
    header('Access-Control-Allow-Origin: *');
    $cn=loadConnections();$enabled=!array_key_exists('internal_cron_enabled',$cn)||!empty($cn['internal_cron_enabled']);
    $sec=max(5,min(86400,(int)($cn['internal_cron_sec']??60)));$now=time();
    if(!$enabled){echo json_encode(['ok'=>true,'enabled'=>false,'version'=>APP_VERSION,'reference'=>'https://scraper4.42web.io/scraper4.php'],JSON_UNESCAPED_SLASHES);exit;}
    $workerBefore=s4WorkerIsActive();$workerAction=[];$workerState=s4WorkerStateLoad();
    if($workerBefore&&(string)($workerState['version']??'')!==APP_VERSION){
        $oldPid=(int)($workerState['pid']??0);$pidAlive=$oldPid>1&&s4WorkerPidAlive($oldPid);$signalled=false;
        if($pidAlive&&function_exists('posix_kill'))$signalled=@posix_kill($oldPid,defined('SIGTERM')?SIGTERM:15);
        $workerAction['version_restart']=['pid'=>$oldPid,'pid_alive'=>$pidAlive,'from'=>(string)($workerState['version']??''),'to'=>APP_VERSION,'signalled'=>$signalled];
        if(!$pidAlive)$workerBefore=false;
        elseif($signalled){for($wi=0;$wi<10;$wi++){usleep(200000);if(!s4WorkerIsActive(1))break;}$workerBefore=s4WorkerIsActive(1);}
    }
    if(!$workerBefore){$workerAction['spawn']=s4SpawnPersistentWorker();usleep(350000);}
    $workerActive=s4WorkerIsActive();$stateFile=__DIR__.'/.internal_cron_feedback.json';
    $lock=@fopen(__DIR__.'/.internal_cron_feedback.lock','c');
    if(!$lock||!@flock($lock,LOCK_EX|LOCK_NB)){
        if($lock)@fclose($lock);echo json_encode(['ok'=>true,'enabled'=>true,'busy'=>true,'worker_active'=>$workerActive,'interval'=>$sec]);exit;
    }
    $prev=json_decode((string)@file_get_contents($stateFile),true);if(!is_array($prev))$prev=[];
    $last=(int)($prev['at']??0);$due=$last<=0||($now-$last)>=$sec;$pulse=[];$cron=[];$resumeAll=[];
    if($due){
        /* Reserve before spawn: simultaneous tabs cannot create a process storm.
           cron's own flock remains the final overlap guard. */
        $next=['at'=>$now,'version'=>APP_VERSION,'source'=>'browser_internal','interval'=>$sec];
        @file_put_contents($stateFile,json_encode($next,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX);
        $pulse=matrixCronPulse('browser_internal');
        $resumeAll=s4CronAutoResumeAllTasks('internal_browser_feedback');
        $cron=s4SpawnInternalCronDetached('browser_feedback');
        /* Shared hosting may disable exec/nohup. Keep the browser-assisted mode
           useful there by firing the same protected cron route over loopback HTTP. */
        if(empty($cron['ok']))$cron['http_fallback']=fireAndForget('cron_run=1&internal_browser=1',1800);
    }
    @flock($lock,LOCK_UN);@fclose($lock);
    echo json_encode(['ok'=>true,'enabled'=>true,'due'=>$due,'interval'=>$sec,'last_at'=>$due?$now:$last,
        'worker_active'=>$workerActive,'worker_action'=>$workerAction,'matrix_pulse'=>$pulse,'cron'=>$cron,
        'tasks_resume_all'=>$resumeAll,
        'reference'=>'https://scraper4.42web.io/scraper4.php'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;
}

/* v10.372: روی هاست بدون exec، مرورگر یکی از jobهای ماتریس را مستقیماً
   claim می‌کند. request تا checkpoint/پایان باز می‌ماند و flock مانع هم‌پوشانی است. */
if(isset($_GET['internal_matrix_feedback'])){
    header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store');header('Access-Control-Allow-Origin: *');header('X-Accel-Buffering: no');
    $cn=loadConnections();$enabled=!array_key_exists('internal_cron_enabled',$cn)||!empty($cn['internal_cron_enabled']);
    if(!$enabled){echo json_encode(['ok'=>true,'skipped'=>'internal_cron_disabled']);exit;}
    if(s4WorkerIsActive()){echo json_encode(['ok'=>true,'skipped'=>'persistent_worker_active','revived_fix'=>s4WorkerReviveFailedMatrixFix()]);exit;}
    $job=s4WorkerClaimMatrixWebJob();if(!$job){echo json_encode(['ok'=>true,'skipped'=>'no_pending_matrix_job']);exit;}
    $jid=(string)($job['id']??'');$type=(string)($job['type']??'');$payload=is_array($job['payload']??null)?$job['payload']:[];$payload['resume']=true;
    try{
        if($type==='matrix_build')$res=s4WorkerRunMatrixBuild($payload);
        else{$payload['max_items']=30;$res=s4WorkerRunMatrixFix($payload);}
        $ok=!empty($res['ok']);$again=!empty($res['yielded'])||!empty($res['resume_needed']);
        if($ok&&$again){s4WorkerRequeueForRecycle($jid);$status='pending';}
        else{$status=$ok?'done':'failed';s4WorkerFinishJob($jid,$status,['ok'=>$ok,'browser_held'=>true,'resume_needed'=>$again],$ok?'':(string)($res['error']??'matrix web job failed'));}
        echo json_encode(['ok'=>$ok,'job_id'=>$jid,'type'=>$type,'status'=>$status,'result'=>$res],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);
    }catch(Throwable $e){s4WorkerFinishJob($jid,'failed',[],$e->getMessage());echo json_encode(['ok'=>false,'job_id'=>$jid,'type'=>$type,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
    exit;
}

/* v10.466: ممیزی کم‌مصرف و جامع علل عدم تایید محصولات باسلام در همهٔ غرفه‌ها */
if (isset($_GET['bsl_rejection_audit'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(120);
    try {
        $cn = loadConnections();
        $shops = function_exists('bslAllShops') ? bslAllShops($cn) : [];
        $srcMode = trim((string)($_GET['source'] ?? 'both'));
        $onlyShop = (int)($_GET['shop_id'] ?? 0);
        $maxPages = max(1, min(60, (int)($_GET['pages'] ?? 5)));
        $singlePid = (int)($_GET['product_id'] ?? 0);

        if ($singlePid > 0) {
            $found = null; $foundShop = null;
            foreach ($shops as $sh) {
                $sTk = trim((string)($sh['token'] ?? '')); $sVid = (int)($sh['vendor_id'] ?? 0);
                if ($sTk === '' || $sVid <= 0) continue;
                if ($onlyShop > 0 && $sVid !== $onlyShop) continue;
                $r1 = bslReqRead($sTk, 'products/' . $singlePid);
                if (empty($r1['ok'])) $r1 = bslReqRead($sTk, 'vendors/' . $sVid . '/products/' . $singlePid);
                if (!empty($r1['ok']) && is_array($r1['body'] ?? null)) {
                    $found = $r1['body']['data'] ?? $r1['body'];
                    $foundShop = ['vendor_id' => $sVid, 'shop_name' => (string)($sh['shop_name'] ?? '')];
                    break;
                }
            }
            echo json_encode(['ok' => $found !== null, 'shop' => $foundShop, 'product' => $found], JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE);
            exit;
        }

        $reasonStats = [];
        $metaPatterns = [];
        $scannedRows = 0;
        $recordItem = static function (array $p, int $vid, string $shopName) use (&$reasonStats, &$metaPatterns, &$scannedRows): void {
            $scannedRows++;
            $pid = (int)($p['id'] ?? 0);
            $title = trim((string)($p['title'] ?? ($p['name'] ?? ($p['revision']['data']['title'] ?? ''))));
            $rev = is_array($p['revision'] ?? null) ? $p['revision'] : [];
            $revData = is_array($rev['data'] ?? null) ? $rev['data'] : [];
            $catObj = $revData['category'] ?? ($p['category'] ?? null);
            $catId = is_array($catObj) ? (int)($catObj['id'] ?? 0) : (int)($p['category_id'] ?? 0);
            $catTitle = is_array($catObj) ? (string)($catObj['title'] ?? '') : '';
            $metaDesc = trim((string)($rev['metadata']['description'] ?? ''));
            $rejs = is_array($rev['rejection_reasons'] ?? null) ? $rev['rejection_reasons'] : [];
            if (!$rejs) {
                $stDesc = is_array($p['status'] ?? null) ? trim((string)($p['status']['description'] ?? '')) : '';
                $revStDesc = is_array($rev['status'] ?? null) ? trim((string)($rev['status']['description'] ?? '')) : '';
                $rejs = [['value' => 0, 'name' => '(بدون rejection_reasons)', 'description' => $revStDesc !== '' ? $revStDesc : $stDesc]];
            }
            foreach ($rejs as $rr) {
                if (!is_array($rr)) continue;
                $rv = (int)($rr['value'] ?? ($rr['id'] ?? 0));
                $rn = trim((string)($rr['name'] ?? ($rr['title'] ?? '')));
                $rd = trim((string)($rr['description'] ?? ''));
                $rk = $rv . '|' . $rn;
                if (!isset($reasonStats[$rk])) {
                    $reasonStats[$rk] = ['value' => $rv, 'name' => $rn, 'count' => 0, 'by_shop' => [], 'desc_samples' => [], 'product_samples' => []];
                }
                $reasonStats[$rk]['count']++;
                $reasonStats[$rk]['by_shop'][(string)$vid] = (int)($reasonStats[$rk]['by_shop'][(string)$vid] ?? 0) + 1;
                if ($rd !== '' && count($reasonStats[$rk]['desc_samples']) < 8) {
                    $shortRd = mb_substr($rd, 0, 260, 'UTF-8');
                    if (!in_array($shortRd, $reasonStats[$rk]['desc_samples'], true)) {
                        $reasonStats[$rk]['desc_samples'][] = $shortRd;
                    }
                }
                if (count($reasonStats[$rk]['product_samples']) < 5) {
                    $reasonStats[$rk]['product_samples'][] = [
                        'id' => $pid, 'vid' => $vid, 'shop' => $shopName,
                        'title' => mb_substr($title, 0, 100, 'UTF-8'),
                        'cat_id' => $catId, 'cat_title' => $catTitle,
                        'reason_desc' => mb_substr($rd, 0, 240, 'UTF-8'),
                        'meta_desc' => mb_substr($metaDesc, 0, 240, 'UTF-8'),
                    ];
                }
            }
            if ($metaDesc !== '') {
                $normMeta = preg_replace('~«[^»]{1,120}»|"[^"]{1,120}"|\d+~u', '#', mb_substr($metaDesc, 0, 180, 'UTF-8')) ?? $metaDesc;
                if (!isset($metaPatterns[$normMeta])) {
                    $metaPatterns[$normMeta] = ['count' => 0, 'example' => mb_substr($metaDesc, 0, 260, 'UTF-8'), 'sample_id' => $pid, 'sample_title' => mb_substr($title, 0, 90, 'UTF-8')];
                }
                $metaPatterns[$normMeta]['count']++;
            }
        };

        $cursorCount = 0;
        if (($srcMode === 'cursor' || $srcMode === 'both') && is_file(CATFIX_FETCH_CURSOR_FILE)) {
            $fp = @fopen(CATFIX_FETCH_CURSOR_FILE, 'rb');
            if (is_resource($fp)) {
                while (($line = fgets($fp)) !== false) {
                    $d = json_decode($line, true);
                    unset($line);
                    if (!is_array($d)) continue;
                    $vidC = (int)($d['vid'] ?? 0);
                    if ($onlyShop > 0 && $vidC !== $onlyShop) continue;
                    foreach ((array)($d['rows'] ?? []) as $rowC) {
                        if (!is_array($rowC)) continue;
                        $cursorCount++;
                        $recordItem($rowC, $vidC, 'cursor#' . $vidC);
                    }
                    unset($d);
                }
                @fclose($fp);
            }
        }

        $shopTotals = [];
        if ($srcMode === 'live' || ($srcMode === 'both' && $cursorCount === 0)) {
            $statusList = [3567, 2977, 2978, 3248, 3568, 3790, 4184, 4221];
            foreach ($shops as $sh) {
                $sTk = trim((string)($sh['token'] ?? '')); $sVid = (int)($sh['vendor_id'] ?? 0);
                $sName = (string)($sh['shop_name'] ?? ('#' . $sVid));
                if ($sTk === '' || $sVid <= 0) continue;
                if ($onlyShop > 0 && $sVid !== $onlyShop) continue;
                $stCounts = [];
                if (!empty($_GET['all_statuses'])) {
                    foreach ($statusList as $stCode) {
                        $rs = bslReqRead($sTk, 'vendors/' . $sVid . '/products?page=1&per_page=1&statuses=' . $stCode);
                        $stCounts[(string)$stCode] = !empty($rs['ok']) ? bslMetaInt($rs['body'], 'total_count', count(bslRowsOf($rs['body']))) : -1;
                    }
                }
                $rejTotal = 0;
                $livePerPage = max(1, min(100, (int)($_GET['per_page'] ?? 20)));
                $vInfo = bslReqRead($sTk, 'vendors/' . $sVid);
                $vBody = is_array($vInfo['body'] ?? null) ? ($vInfo['body']['data'] ?? $vInfo['body']) : [];
                $vStVal = is_array($vBody['status'] ?? null) ? (int)($vBody['status']['value'] ?? 0) : (int)($vBody['status'] ?? 0);
                $vStName = is_array($vBody['status'] ?? null) ? (string)($vBody['status']['name'] ?? '') : '';
                for ($pg = 1; $pg <= $maxPages; $pg++) {
                    $r = bslReqRead($sTk, 'vendors/' . $sVid . '/products?page=' . $pg . '&per_page=' . $livePerPage . '&statuses=3567');
                    if (empty($r['ok'])) break;
                    if ($pg === 1) $rejTotal = bslMetaInt($r['body'], 'total_count', 0);
                    $rows = bslRowsOf($r['body']);
                    if (!$rows) break;
                    foreach ($rows as $rowL) {
                        if (is_array($rowL)) $recordItem($rowL, $sVid, $sName);
                    }
                    $tp = bslMetaInt($r['body'], 'total_page', 1);
                    unset($rows, $r);
                    if ($pg >= $tp) break;
                }
                $shopTotals[] = ['vendor_id' => $sVid, 'shop_name' => $sName, 'vendor_status' => $vStVal, 'vendor_status_name' => $vStName, 'vendor_is_active' => $vBody['is_active'] ?? null, 'rejected_3567_total' => $rejTotal, 'status_counts' => $stCounts];
            }
        }

        uasort($reasonStats, static fn($a, $b) => ($b['count'] <=> $a['count']));
        uasort($metaPatterns, static fn($a, $b) => ($b['count'] <=> $a['count']));
        $pendingAi = function_exists('bslAiCatPendingLoad') ? count(bslAiCatPendingLoad(null, false)) : 0;

        echo json_encode([
            'ok' => true,
            'source' => $srcMode,
            'scanned_rows' => $scannedRows,
            'cursor_rows' => $cursorCount,
            'pending_ai_create_count' => $pendingAi,
            'shop_totals' => $shopTotals,
            'reasons' => array_values($reasonStats),
            'top_meta_patterns' => array_slice(array_values($metaPatterns), 0, 25),
        ], JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE);
    } catch (Throwable $e) {
        echo json_encode(['ok' => false, 'error' => $e->getMessage(), 'line' => $e->getLine()], JSON_UNESCAPED_UNICODE);
    }
    exit;
}

/* v10.263: فیدبک یکپارچهٔ عملیات + ترمیم. برای loop مانیتورینگ خارجی:
   ?ops_feedback=1&repair=1 — پاسخ کوتاه و idempotent است. */
if(isset($_GET['ops_feedback'])||(($_POST['action']??'')==='ops_feedback')){
    header('Content-Type: application/json; charset=UTF-8');$now=time();$repair=!empty($_GET['repair']??$_POST['repair']??null);
    try {
    $actions=[];
    if($repair&&function_exists('s4ReclaimPluginQuotaBloat'))$actions['quota_reclaim']=s4ReclaimPluginQuotaBloat(true);
    $profilesCount=count(loadProfiles());
    $staleWorkerLock=$repair?s4WorkerRecoverStaleLockPath():['recovered'=>false];
    $wst=s4WorkerStateLoad();$wq=s4WorkerLoadQueue();$whb=(int)($wst['heartbeat']??0);$workerActive=s4WorkerIsActive();
    $mx=matrixProgressRead(false);$mxBeat=function_exists('tasksHeartbeat')?tasksHeartbeat($mx):(int)($mx['ts']??0);$mxAge=$mxBeat>0?max(0,$now-$mxBeat):null;
    $mxFp=@fopen(SYNC_MATRIX_LOCK_FILE,'c');$mxLocked=false;if($mxFp){$free=@flock($mxFp,LOCK_EX|LOCK_NB);$mxLocked=!$free;if($free)@flock($mxFp,LOCK_UN);@fclose($mxFp);}
    $cronFile=__DIR__.'/cron_last_run.json';$cronAt=is_file($cronFile)?(int)@filemtime($cronFile):0;$cronAge=$cronAt>0?max(0,$now-$cronAt):null;
    $active=[];foreach((array)($wq['entries']??[])as$e)if(is_array($e)&&in_array((string)($e['status']??''),['pending','running'],true))$active[]=['id'=>(string)($e['id']??''),'type'=>(string)($e['type']??''),'status'=>(string)($e['status']??''),'attempts'=>(int)($e['attempts']??0)];
    $tailLog=static function(string $name):array{$f=__DIR__.'/logs/'.$name;if(!is_file($f))return[];$sz=(int)@filesize($f);$raw=(string)@file_get_contents($f,false,null,max(0,$sz-16000));$ls=preg_split('/\R/',$raw);return array_slice(array_values(array_filter($ls,static fn($x)=>trim((string)$x)!=='')),-15);};
    if(!empty($staleWorkerLock['recovered']))$actions['stale_worker_lock']=$staleWorkerLock;
    /* daemon قدیمی پس از deploy همان کد قبلی را تا ابد در RAM دارد. در repair
       فقط با PID و version ثبت‌شدهٔ خودش پایانش می‌دهیم تا worker تازه بالا آید. */
    if($repair&&$workerActive&&(string)($wst['version']??'')!==APP_VERSION){
        $oldPid=(int)($wst['pid']??0);
        $sigOk=false;
        if($oldPid>0){
            if(function_exists('posix_kill'))$sigOk=@posix_kill($oldPid,defined('SIGTERM')?SIGTERM:15);
            elseif(function_exists('exec')){$_ko=[];$_kr=1;@exec('kill -TERM '.(int)$oldPid.' 2>/dev/null',$_ko,$_kr);$sigOk=($_kr===0);}
        }
        $actions['old_worker_restart']=['pid'=>$oldPid,'from'=>(string)($wst['version']??''),'to'=>APP_VERSION,'signalled'=>$sigOk];usleep(500000);$workerActive=s4WorkerIsActive(1);
    }
    if($repair&&!$workerActive){$actions['worker']=s4SpawnPersistentWorker();usleep(350000);$workerActive=s4WorkerIsActive();$wst=s4WorkerStateLoad();$whb=(int)($wst['heartbeat']??0);}
    if($repair&&!empty($mx['running'])&&!$mxLocked&&($mxAge===null||$mxAge>120)){
        matrixProgress(['running'=>false,'done'=>false,'yielded'=>true,'partial'=>true,'stale'=>true,'phase'=>'بازیابی خودکار','log_add'=>['♻️ فیدبک عملیات: worker ماتریس مرده بود؛ ادامه از checkpoint']]);
        $mxResumeCp=is_array($mx['checkpoint']??null)?$mx['checkpoint']:[];
        $mxResumeOpts=['profile'=>(string)($mx['profile']??'all'),'parallel_destinations'=>(string)($mx['fetch_mode']??'')==='parallel','live_fill'=>!empty($mx['live_fill']),'selected_destinations'=>array_key_exists('selected_destinations',$mxResumeCp)?array_values((array)$mxResumeCp['selected_destinations']):(array_key_exists('selected_destinations',$mx)?array_values((array)$mx['selected_destinations']):null),'slice_seconds'=>max(2,min(20,(int)($mx['slice_seconds']??8)))];
        /* daemon زنده مالک recovery باشد تا child را wait و exit/OOM را ثبت کند؛
           detached فقط fallback نصب‌هایی است که daemon واقعاً بالا نمی‌آید. */
        $actions['matrix']=$workerActive?s4WorkerEnqueueMatrixBuild($mxResumeOpts,true):s4SpawnMatrixBuildChild($mxResumeOpts,true);
    }
    $healthy=$workerActive&&($cronAge===null||$cronAge<900)&&!( !empty($mx['running'])&&!$mxLocked&&($mxAge===null||$mxAge>120));
    echo json_encode(['ok'=>true,'version'=>APP_VERSION,'now'=>$now,'healthy'=>$healthy,'repair'=>$repair,
        'profiles_count'=>$profilesCount,'profiles_corrupt'=>!empty($GLOBALS['_profilesCorrupt']),
        'worker'=>['active'=>$workerActive,'heartbeat_age'=>$whb>0?max(0,$now-$whb):null,'state'=>$wst,'active_jobs'=>$active],
        'cron'=>['last_at'=>$cronAt,'age'=>$cronAge,'stale'=>$cronAge===null||$cronAge>=900],
        'matrix'=>['running'=>!empty($mx['running']),'phase'=>(string)($mx['phase']??''),'heartbeat_age'=>$mxAge,'lock_held'=>$mxLocked,'checkpoint'=>is_array($mx['checkpoint']??null)],
        'logs'=>['worker'=>$tailLog('worker.log'),'matrix'=>$tailLog('matrix-worker.log'),'queue_watchdog'=>$tailLog('queue-watchdog.log')],
        'code_update'=>['status'=>'?code_update_status=1','endpoint'=>'?code_update=1','method'=>'POST','source'=>S4_CODE_UPDATE_REPO.'@'.S4_CODE_UPDATE_BRANCH],
        'actions'=>$actions,'next'=>'worker داخلی فعال است؛ cron خارجی لازم نیست. رابط باز نیز هر ۵ دقیقه repair pulse می‌زند'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);
    } catch (Throwable $_opsErr) {
        echo json_encode(['ok'=>false,'version'=>APP_VERSION,'error'=>$_opsErr->getMessage(),'line'=>$_opsErr->getLine()],JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);
    }
    exit;
}

if (isset($_GET['sync_matrix_status']) || (($_POST['action'] ?? '') === 'sync_matrix_status')) {
    header('Content-Type: application/json; charset=UTF-8');
    header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
    $prog = matrixProgressRead(false);
    $fix = function_exists('matrixFixProgressRead') ? matrixFixProgressRead() : [];
    $visibleDestRaw=$_GET['selected_destinations']??$_POST['selected_destinations']??null;
    if(function_exists('matrixFixVisibleProgress'))$fix=matrixFixVisibleProgress($fix,$visibleDestRaw);
    /* running یتیمِ build را خود status ترمیم می‌کند؛ UI نباید پنج دقیقه منتظر
       ops_feedback بماند یا دکمه را قفل‌شده ببیند. heartbeat کهنه + flock آزاد
       شرط اجباری است تا فاصلهٔ کوتاه بین دو child سالم recovery کاذب نسازد. */
    $progBeat=function_exists('tasksHeartbeat')?tasksHeartbeat($prog):(int)($prog['ts']??$prog['started_at']??0);
    if(!empty($prog['running'])&&$progBeat>0&&(time()-$progBeat)>180){
        $mf=@fopen(SYNC_MATRIX_LOCK_FILE,'c');$matrixFree=$mf&&@flock($mf,LOCK_EX|LOCK_NB);
        if($matrixFree){
            @flock($mf,LOCK_UN);
            matrixProgress(['running'=>false,'done'=>false,'yielded'=>true,'partial'=>true,'stale'=>true,'phase'=>'بازیابی خودکار',
                'log_add'=>['♻️ running یتیم شناسایی شد؛ قفل آزاد است و ادامه از checkpoint به worker سپرده شد']]);
            $resumeState=matrixProgressRead(true);
            $rcp=is_array($resumeState['checkpoint']??null)?$resumeState['checkpoint']:[];
            $ro=['profile'=>(string)($prog['profile']??$rcp['profile_filter']??'all'),
                'parallel_destinations'=>(string)($prog['fetch_mode']??$rcp['fetch_mode']??'')==='parallel',
                'live_fill'=>!empty($prog['live_fill']??$rcp['live_fill']??false),
                'selected_destinations'=>array_key_exists('selected_destinations',$rcp)?array_values((array)$rcp['selected_destinations']):(array_key_exists('selected_destinations',$prog)?array_values((array)$prog['selected_destinations']):null),
                'slice_seconds'=>max(2,min(20,(int)($prog['slice_seconds']??$rcp['slice_seconds']??8)))];
            if(function_exists('s4WorkerIsActive')&&s4WorkerIsActive())s4WorkerEnqueueMatrixBuild($ro,true);
            elseif(function_exists('s4SpawnMatrixBuildChild'))s4SpawnMatrixBuildChild($ro,true);
            $prog=matrixProgressRead(false);
        }
        if($mf)@fclose($mf);
    }
    /* state قدیمیِ running نباید دکمهٔ ساخت را برای همیشه قفل کند. فقط وقتی
       heartbeat کهنه و lock واقعاً آزاد است، آن را stopped می‌کنیم. */
    if(!empty($fix['running'])&&empty($fix['queued'])&&(time()-(int)($fix['ts']??$fix['started_at']??0))>180){
        $ff=@fopen(SYNC_MATRIX_FIX_LOCK_FILE,'c');$free=$ff&&@flock($ff,LOCK_EX|LOCK_NB);
        if($free){@flock($ff,LOCK_UN);matrixFixProgress(['running'=>false,'done'=>true,'stopped'=>true,'stale'=>true,'phase'=>'stopped','finished_at'=>time(),'log_add'=>['⏹ state قدیمی اصلاح آزاد شد']]);$fix=matrixFixProgressRead();}
        if($ff)@fclose($ff);
    }
    if(function_exists('matrixFixVisibleProgress'))$fix=matrixFixVisibleProgress($fix,$visibleDestRaw);
    $actualFixRunning=!empty($fix['running'])&&empty($fix['queued']);
    $has = is_file(SYNC_MATRIX_RESULT_FILE);$resultAt=$has?(int)@filemtime(SYNC_MATRIX_RESULT_FILE):0;
    $age = $has ? (time() - $resultAt) : -1;
    $statusResult=$has?matrixResultLoad():[];
    $anyRun = !empty($prog['running']) || $actualFixRunning || !empty($fix['queued']);
    /* A completed correction may be useful after refresh, but only while it is
       newer than the latest matrix build/result. Previously an old build_failed
       correction from hours earlier masked a later successful build forever. */
    $buildAt=max($resultAt,(int)($prog['finished_at']??0),(int)($prog['ts']??0),(int)($prog['started_at']??0));
    $fixAt=max((int)($fix['finished_at']??0),(int)($fix['ts']??0),(int)($fix['started_at']??0));
    $preferFinishedFix=!$actualFixRunning&&empty($fix['queued'])&&!empty($fix['done'])&&$fixAt>=$buildAt;
    $buildOwnState = !empty($prog['running']) || !empty($prog['yielded'])
        || !empty($prog['stop_requested']) || !empty($prog['stopped'])
        || (!empty($prog['done'])&&!$preferFinishedFix);
    /* v10.339: status هر ثانیه poll می‌شود. فرستادن progress اصلاح قدیمی با
       صدها detail/live و تکرار log ساخت، UI را ظاهراً منجمد می‌کرد. */
    $buildView=$prog;unset($buildView['log']);
    $fixView=$fix;
    if(!$actualFixRunning){
        $keep=['running','queued','done','phase','pct','cur','total','ok_n','fail_n','skip_n','sent_n','del_n','price_n','processed_n','finished_at','error','stopped','stale','selected_destinations'];
        $fixView=array_intersect_key($fixView,array_fill_keys($keep,true));
    }
    $shownProgress=$actualFixRunning?$fix:($buildOwnState?$prog:($preferFinishedFix?$fixView:$prog));
    $shownJob=$actualFixRunning||!empty($fix['queued'])||$preferFinishedFix?'fix':'build';
    echo json_encode([
        'ok' => true,
        'running' => $anyRun,
        'build_running' => !empty($prog['running']),
        'fix_running' => $actualFixRunning,
        'fix_queued' => !empty($fix['queued']),
        'done' => !empty($prog['done']) || !empty($fix['done']),
        'progress' => $shownProgress,
        'build_progress' => $buildView,
        'fix_progress' => $fixView,
        'has_result' => $has,
        'result_age_sec' => $age,
        'result_rows' => $has ? (int)($statusResult['row_count'] ?? count((array)($statusResult['rows']??[]))) : 0,
        'result_destinations'=>array_values((array)($statusResult['selected_destinations']??[])),
        'result_pricing_stale'=>$has&&((string)($statusResult['pricing_signature']??'')!==matrixPricingFingerprint()),
        'job'=>$shownJob,
        'state_order'=>['build_at'=>$buildAt,'fix_at'=>$fixAt,'preferred'=>$shownJob],
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['sync_matrix_start']) || (($_POST['action'] ?? '') === 'sync_matrix_start')) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(0);
    @ignore_user_abort(true);
    $opts = [
        'profile' => (string)($_GET['profile'] ?? $_POST['profile'] ?? 'all'),
        'source' => (string)($_GET['source'] ?? $_POST['source'] ?? 'manual'),
        'background' => true,
        'run_started_at' => microtime(true),
        'parallel_destinations' => !empty($_GET['parallel_destinations'] ?? $_POST['parallel_destinations'] ?? null),
        'live_fill' => !empty($_GET['live_fill'] ?? $_POST['live_fill'] ?? null),
        'selected_destinations' => matrixNormalizeDestinations($_GET['selected_destinations'] ?? $_POST['selected_destinations'] ?? null),
        'coded_only' => false,
        'slice_seconds' => max(2, min(20, (int)($_GET['slice_seconds'] ?? $_POST['slice_seconds'] ?? 8))),
    ];
    if(!$opts['selected_destinations']){echo json_encode(['ok'=>false,'error'=>'حداقل ووکامرس یا یک غرفه را انتخاب کنید'],JSON_UNESCAPED_UNICODE);exit;}
    /* v10.255: اگر worker دائمی حاضر است، request وب اصلاً سازندهٔ جدول نیست؛
       فقط job ثبت می‌کند. بنابراین ادامه به polling/جاوااسکریپت و بیدارماندن گوشی وابسته نیست. */
    if (function_exists('s4WorkerIsActive') && s4WorkerIsActive()) {
        $matrixLockHeld = false; $matrixProbe = @fopen(SYNC_MATRIX_LOCK_FILE, 'c');
        if ($matrixProbe) {
            $matrixLockHeld = !@flock($matrixProbe, LOCK_EX | LOCK_NB);
            if (!$matrixLockHeld) @flock($matrixProbe, LOCK_UN);
            @fclose($matrixProbe);
        }
        if ($matrixLockHeld) {
            echo json_encode(['ok'=>false,'error'=>'یک ساخت جدول در worker در حال اجراست','running'=>true], JSON_UNESCAPED_UNICODE);
            exit;
        }
        $resumeRequested = !empty($_GET['resume'] ?? $_POST['resume'] ?? null);
        $enq = s4WorkerEnqueueMatrixBuild($opts, $resumeRequested);
        if (empty($enq['ok'])) {
            echo json_encode(['ok'=>false,'error'=>'ثبت job ماتریس در worker ناموفق بود: '.(string)($enq['error']??'unknown')], JSON_UNESCAPED_UNICODE);
            exit;
        }
        echo json_encode(['ok'=>true,'started'=>true,'queued'=>true,'worker'=>true,
            'duplicate'=>!empty($enq['duplicate']),'job_id'=>(string)($enq['job_id']??''),
            'message'=>'ساخت به worker دائمی سرور سپرده شد'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    /* v10.259: بدون worker دائمی هم request مرورگر ادامه‌دهنده نیست؛ در صورت
       دسترسی PHP CLI، یک child کاملاً detached مالک همهٔ برش‌ها می‌شود. */
    $matrixLockHeld=false;$matrixProbe=@fopen(SYNC_MATRIX_LOCK_FILE,'c');
    if($matrixProbe){$matrixLockHeld=!@flock($matrixProbe,LOCK_EX|LOCK_NB);if(!$matrixLockHeld)@flock($matrixProbe,LOCK_UN);@fclose($matrixProbe);}
    if($matrixLockHeld){echo json_encode(['ok'=>false,'error'=>'یک ساخت جدول در پردازهٔ سرور در حال اجراست','running'=>true],JSON_UNESCAPED_UNICODE);exit;}
    $resumeRequested=!empty($_GET['resume']??$_POST['resume']??null);
    $spawn=function_exists('s4SpawnMatrixBuildChild')?s4SpawnMatrixBuildChild($opts,$resumeRequested):['ok'=>false,'error'=>'spawn_unavailable'];
    if(!empty($spawn['ok'])){
        echo json_encode(['ok'=>true,'started'=>true,'worker'=>true,'worker_child'=>true,
            'pid'=>(int)($spawn['pid']??0),'message'=>'ساخت در پردازهٔ مستقل سرور شروع شد؛ مرورگر قابل بستن است'],JSON_UNESCAPED_UNICODE);exit;
    }
    /* فقط روی هاست‌هایی که exec/PHP CLI را بسته‌اند fallback قدیمی اجرا می‌شود. */
    $opts['spawn_error']=(string)($spawn['error']??'unknown');
    /* v10.129: مرحلهٔ خواندن پروفایل‌ها checkpoint دارد. دادهٔ محلیِ کامل
       ذخیره می‌شود؛ اگر قطع در یکی از واکشی‌های مقصد رخ دهد، فقط آن واکشی
       دوباره انجام می‌شود و پروفایل‌های مبدأ از ابتدا تکرار نمی‌شوند. */
    $matrixCp = null;
    if (!empty($_GET['resume'] ?? $_POST['resume'] ?? null) && is_file(SYNC_MATRIX_PROGRESS_FILE)) {
        $oldMatrix = json_decode((string)@file_get_contents(SYNC_MATRIX_PROGRESS_FILE), true);
        $oldCp = is_array($oldMatrix['checkpoint'] ?? null) ? $oldMatrix['checkpoint'] : null;
        if (is_array($oldCp) && empty($oldCp['coded_only'])
            && (string)($oldCp['profile_filter'] ?? 'all') === ($opts['profile'] ?: 'all')
            && is_array($oldCp['profile_rows'] ?? null)) {
            $matrixCp = $oldCp;
        }
    }
    if ($matrixCp && isset($matrixCp['fetch_mode']))
        $opts['parallel_destinations'] = ((string)$matrixCp['fetch_mode'] === 'parallel');
    if ($matrixCp && array_key_exists('live_fill', $matrixCp))
        $opts['live_fill'] = !empty($matrixCp['live_fill']);
    if ($matrixCp && isset($matrixCp['selected_destinations']))
        $opts['selected_destinations'] = array_values((array)$matrixCp['selected_destinations']);
    if ($matrixCp && isset($matrixCp['slice_seconds']))
        $opts['slice_seconds'] = max(2, min(20, (int)$matrixCp['slice_seconds']));
    $opts['checkpoint'] = $matrixCp;
    // قفل زود — حذف cursor و مصرف stop فقط بعد از مالکیت واقعی انجام می‌شود.
    $lockFile = SYNC_MATRIX_LOCK_FILE;
    $fp = @fopen($lockFile, 'c');
    $lockRecovered = false;
    if (!$fp || !flock($fp, LOCK_EX | LOCK_NB)) {
        if ($fp) @fclose($fp);
        $staleState = matrixProgressRead();
        $canRecover = empty($staleState['running']) && !empty($staleState['stopped'])
            && is_file(SYNC_MATRIX_STOP_FILE);
        if (!$canRecover) {
            echo json_encode(['ok' => false, 'error' => 'یک ساخت جدول در حال اجراست', 'running' => true,
                'lock_recoverable' => false], JSON_UNESCAPED_UNICODE);
            exit;
        }
        /* v10.241: flock پردازهٔ یتیم را نمی‌توان unlock کرد؛ inode قفل را
           کنار می‌گذاریم و روی مسیر تازه قفل می‌گیریم. signal قدیمی باقی
           می‌ماند تا worker قبلی متوقف شود، ولی اجرای تازه با زمان signal
           آن را نادیده می‌گیرد. */
        $orphanLock = $lockFile . '.orphan.' . date('Ymd_His') . '.' . substr(md5(uniqid('', true)), 0, 6);
        if (!@rename($lockFile, $orphanLock)) {
            echo json_encode(['ok' => false, 'error' => 'قفل متوقف‌شده قابل بازیابی نیست',
                'running' => false, 'lock_recoverable' => true], JSON_UNESCAPED_UNICODE);
            exit;
        }
        $fp = @fopen($lockFile, 'c');
        if (!$fp || !flock($fp, LOCK_EX | LOCK_NB)) {
            if ($fp) @fclose($fp);
            echo json_encode(['ok' => false, 'error' => 'گرفتن قفل تازه ناموفق بود'], JSON_UNESCAPED_UNICODE);
            exit;
        }
        $lockRecovered = true;
        $opts['run_started_at'] = microtime(true);
    }
    if ($matrixCp === null && function_exists('matrixFetchCursorFile')) @unlink(matrixFetchCursorFile());
    if ($matrixCp === null || empty($opts['live_fill'])) @unlink(SYNC_MATRIX_LIVE_FILE);
    if (!$lockRecovered) matrixStopClear();
    matrixProgress([
        'running' => true, 'done' => false, 'error' => '', 'pct' => 1,
        'phase' => 'start', 'started_at' => (int)($matrixCp['started_at'] ?? time()),
        'source' => $opts['source'], 'profile' => $opts['profile'], 'coded_only' => $opts['coded_only'], 'lock_recovered' => $lockRecovered,
        'checkpoint' => $matrixCp ?: ['phase' => 'profiles', 'profile_filter' => ($opts['profile'] ?: 'all'),
            'profile_rows' => [], 'profiles_done' => [], 'coded_only' => $opts['coded_only'], 'selected_destinations'=>$opts['selected_destinations'], 'started_at' => time()],
        'log_add' => [($lockRecovered ? '♻️ قفل یتیم بازیابی شد — ' : '🚀 ') . ($matrixCp ? 'ادامه ساخت جدول از checkpoint' : 'جاب ساخت جدول در صف سرور') . '...'],
    ]);
    $early = json_encode(['ok' => true, 'started' => true, 'lock_recovered' => $lockRecovered, 'message' => 'ساخت روی سرور شروع شد'], JSON_UNESCAPED_UNICODE);
    header('Connection: close');
    header('Content-Length: ' . strlen($early));
    echo $early;
    @ob_end_flush();
    @ob_flush();
    @flush();
    if (function_exists('fastcgi_finish_request')) {
        @fastcgi_finish_request();
    }
    register_shutdown_function(function () use ($fp, $lockFile) {
        @flock($fp, LOCK_UN);
        @fclose($fp);
    });
    try {
        $matrixRunResult=matrixBuild($opts);
        matrixStopClear();
        if(!empty($matrixRunResult['yielded'])&&!empty($opts['spawn_error'])){
            s4ScheduleMatrixServerContinuation($opts);
        }
    } catch (Throwable $e) {
        $matrixErrState = matrixProgressRead();
        matrixStopClear();
        matrixProgress([
            'running' => false, 'done' => true, 'stale' => true, 'error' => $e->getMessage(), 'pct' => 100,
            'checkpoint' => is_array($matrixErrState['checkpoint'] ?? null) ? $matrixErrState['checkpoint'] : null,
            'log_add' => ['❌ ' . $e->getMessage() . ' — checkpoint حفظ شد'],
        ]);
    }
    exit;
}

if (isset($_GET['sync_matrix']) || (($_POST['action'] ?? '') === 'sync_matrix')) {
