/* v10.117: اصلاح مغایرت از جدول مقایسه */
if (isset($_GET['sync_matrix_fix_status']) || (($_POST['action'] ?? '') === 'sync_matrix_fix_status')) {
    header('Content-Type: application/json; charset=UTF-8');
    $prog = matrixFixVisibleProgress(matrixFixProgressRead(),$_GET['selected_destinations']??$_POST['selected_destinations']??null);
    $since = max(0, (int)($_GET['since'] ?? $_POST['since'] ?? 0));
    $log = is_array($prog['log'] ?? null) ? $prog['log'] : [];
    $logTotal = count($log);
    if ($since > 0 && $since < $logTotal) {
        $prog['log_delta'] = array_slice($log, $since);
    } else {
        $prog['log_delta'] = array_slice($log, -40);
    }
    $prog['log_total'] = $logTotal;
    /* keep full log for UI that wants it, but also delta */
    echo json_encode([
        'ok' => true,
        'running' => !empty($prog['running']),
        'done' => !empty($prog['done']),
        'progress' => $prog,
        'job' => 'fix',
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

/* فیدبک متمرکز اصلاح باسلام: کوچک، read-only و مناسب پایش بیرونی؛ برخلاف
   ops_feedback کل صف/لاگ‌های بزرگ را برنمی‌گرداند و روی هاست 500 نمی‌شود. */
if(isset($_GET['sync_matrix_fix_feedback'])||(($_POST['action']??'')==='sync_matrix_fix_feedback')){
    header('Content-Type: application/json; charset=UTF-8');
    $p=matrixFixProgressRead();$runAt=(int)($p['started_at']??0);$logs=array_values(array_filter((array)($p['log']??[]),static fn($r)=>$runAt<=0||(int)($r['t']??0)>=$runAt));$codes=[];$photoRequired=0;$rateN=0;
    foreach($logs as $row){$m=(string)(is_array($row)?($row['m']??''):$row);
        if(preg_match_all('~HTTP\s*(\d{3})~i',$m,$mm))foreach($mm[1] as $c)$codes[$c]=($codes[$c]??0)+1;
        if(stripos($m,'photo')!==false||mb_stripos($m,'شناسه تصویر')!==false)$photoRequired++;
        if(stripos($m,'429')!==false)$rateN++;
    }
    $data=matrixResultLoad();$sample=[];$sendJobs=$data?matrixFixCollectJobs($data,'bsl',[],'newest'):[];
    foreach($sendJobs as $j){if((string)($j['kind']??'')!=='send_bsl')continue;
        $f=matrixFixFindProduct((string)($j['bare']??''),(string)($j['profile_key']??''),(string)($j['product_key']??''));
        $imgs=$f&&function_exists('productImageList')?productImageList((array)$f['product']):[];
        $fp=$f?(array)$f['product']:[];$detailLink=trim((string)($fp['link']??$fp['url']??''));
        $sample[]=['title'=>(string)($j['title']??''),'vendor_id'=>(int)($j['vendor_id']??0),'found'=>(bool)$f,
            'images'=>count($imgs),'detail_rescue_available'=>$detailLink!==''];
        if(count($sample)>=10)break;
    }
    $w=s4WorkerStateLoad();
    echo json_encode(['ok'=>true,'version'=>APP_VERSION,'running'=>!empty($p['running']),'phase'=>(string)($p['phase']??''),
        'cur'=>(int)($p['cur']??0),'total'=>(int)($p['total']??0),'ok_n'=>(int)($p['ok_n']??0),'fail_n'=>(int)($p['fail_n']??0),
        'http_codes'=>$codes,'photo_required_logs'=>$photoRequired,'rate_429_logs'=>$rateN,
        'worker'=>['active'=>s4WorkerIsActive(),'version'=>(string)($w['version']??''),'pid'=>(int)($w['pid']??0)],
        'send_readiness_sample'=>$sample,
        'repairs'=>['create_uploads_photo'=>true,'photo_429_stops_immediately'=>true,'create_requires_local_image'=>true]],JSON_UNESCAPED_UNICODE);exit;
}

/* v10.319: اصلاح واقعی یک ردیف + trace امن request/response برای عیب‌یابی مودال. */
if(isset($_GET['sync_matrix_fix_row'])||(($_POST['action']??'')==='sync_matrix_fix_row')){
    header('Content-Type: application/json; charset=UTF-8');
    if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST'){http_response_code(405);echo json_encode(['ok'=>false,'error'=>'POST required'],JSON_UNESCAPED_UNICODE);exit;}
    $bare=trim((string)($_POST['bare']??''));$scope=(string)($_POST['scope']??'all');if(!in_array($scope,['all','woo','bsl'],true))$scope='all';
    $selected=matrixNormalizeDestinations($_POST['selected_destinations']??null);$keep=(string)($_POST['duplicate_keep']??'newest');if(!in_array($keep,['newest','expensive'],true))$keep='newest';
    if($bare===''||!$selected){http_response_code(422);echo json_encode(['ok'=>false,'error'=>'ردیف یا مقصد انتخاب‌شده معتبر نیست'],JSON_UNESCAPED_UNICODE);exit;}
    $data=matrixResultLoad();$row=null;foreach((array)($data['rows']??[])as$rr){if(is_array($rr)&&empty($rr['is_report'])&&hash_equals($bare,(string)($rr['bare']??''))){$row=$rr;break;}}
    if(!$row){http_response_code(404);echo json_encode(['ok'=>false,'error'=>'ردیف در snapshot فعلی پیدا نشد؛ جدول را تازه کنید'],JSON_UNESCAPED_UNICODE);exit;}
    $fp=@fopen(SYNC_MATRIX_FIX_LOCK_FILE,'c');$locked=$fp&&@flock($fp,LOCK_EX|LOCK_NB);$lockRecovery=null;
    if(!$locked){
        $busyState=matrixFixProgressRead();$busyPid=(int)($busyState['runner_pid']??$busyState['child_pid']??0);$busyPidAlive=$busyPid>0&&s4WorkerPidAlive($busyPid);
        $recoverable=!empty($busyState['queued'])||(empty($busyState['running'])&&(!empty($busyState['stale'])||!empty($busyState['stopped'])||!empty($busyState['done'])));
        if($recoverable){
            $lockRecovery=['attempted'=>true,'phase'=>(string)($busyState['phase']??''),'queued'=>!empty($busyState['queued']),'runner_pid'=>$busyPid,'runner_alive'=>$busyPidAlive];
            $lockRecovery['runner']=matrixTerminateRunner($busyState);
            $staleJobId=(string)($busyState['job_id']??'');
            if($staleJobId!==''&&function_exists('s4WorkerQueueMutate'))s4WorkerQueueMutate(function(&$q)use($staleJobId){$now=time();foreach($q['entries']as&$e){if(!is_array($e)||(string)($e['id']??'')!==$staleJobId||(string)($e['type']??'')!=='matrix_fix'||(string)($e['status']??'')!=='running')continue;$e['status']='cancelled';$e['updated_at']=$now;$e['done_at']=$now;$e['error']='stale_lock_recovered_by_row_fix';}unset($e);return['ok'=>true];});
            for($try=0;$try<25&&!$locked;$try++){usleep(100000);$locked=$fp&&@flock($fp,LOCK_EX|LOCK_NB);}
            $lockRecovery['acquired']=$locked;
            if($locked)matrixFixProgress(['running'=>false,'done'=>true,'stale'=>false,'stopped'=>true,'phase'=>'stale_lock_recovered','log_add'=>['♻️ قفل یتیم اصلاح پیش از اجرای تک‌ردیف آزاد شد']]);
        }
        if(!$locked){if($fp)@fclose($fp);http_response_code(409);echo json_encode(['ok'=>false,'busy'=>true,'error'=>$recoverable?'قفل پردازهٔ یتیم هنوز آزاد نشد؛ چند ثانیه دیگر دوباره تلاش کنید':'یک اصلاح زندهٔ دیگر در حال اجراست؛ برای جلوگیری از عملیات همزمان صبر کنید','lock'=>['phase'=>(string)($busyState['phase']??''),'running'=>!empty($busyState['running']),'queued'=>!empty($busyState['queued']),'stale'=>!empty($busyState['stale']),'stopped'=>!empty($busyState['stopped']),'runner_pid'=>$busyPid,'runner_alive'=>$busyPidAlive],'recovery'=>$lockRecovery],JSON_UNESCAPED_UNICODE);exit;}
    }
    $GLOBALS['S4_MATRIX_ROW_TRACE_ACTIVE']=true;$GLOBALS['S4_MATRIX_ROW_TRACE']=[];$before=matrixFixProgressRead();$started=microtime(true);
    try{
        matrixFixStopClear();
        $opts=['scope'=>$scope,'delay_ms'=>180,'source'=>'row_modal','duplicate_keep'=>$keep,'selected_destinations'=>$selected,'row_mode'=>true,
            'view_filters'=>['exact_bare'=>$bare,'prefer_coded_duplicate'=>!empty($_POST['prefer_coded_duplicate'])],'checkpoint'=>null];
        $result=matrixFixRun($opts);$after=matrixFixProgressRead();$logs=array_values(array_filter((array)($after['log']??[]),static fn($x)=>(int)($x['t']??0)>=(int)$started));
        echo json_encode(['ok'=>!empty($result['ok'])&&empty($result['partial']),'version'=>APP_VERSION,'row'=>['bare'=>$bare,'title'=>(string)($row['title']??$bare)],
            'selected_destinations'=>$selected,'result'=>$result,'requests_responses'=>$GLOBALS['S4_MATRIX_ROW_TRACE'],
            'logs'=>array_slice($logs,-80),'lock_recovery'=>$lockRecovery,'elapsed_ms'=>(int)round((microtime(true)-$started)*1000)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);
    }catch(Throwable $e){http_response_code(500);echo json_encode(['ok'=>false,'error'=>$e->getMessage(),'requests_responses'=>$GLOBALS['S4_MATRIX_ROW_TRACE']],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}
    finally{$GLOBALS['S4_MATRIX_ROW_TRACE_ACTIVE']=false;@flock($fp,LOCK_UN);@fclose($fp);}exit;
}

if (isset($_GET['sync_matrix_fix_stop']) || (($_POST['action'] ?? '') === 'sync_matrix_fix_stop')) {
    header('Content-Type: application/json; charset=UTF-8');
    @file_put_contents(SYNC_MATRIX_FIX_STOP_FILE, json_encode(['at' => microtime(true),'by'=>'user']), LOCK_EX);
    if(function_exists('s4WorkerQueueMutate'))s4WorkerQueueMutate(function(&$q){$now=time();foreach($q['entries'] as &$e){if(!is_array($e)||(string)($e['type']??'')!=='matrix_fix'||!in_array((string)($e['status']??''),['pending','running'],true))continue;$e['status']='cancelled';$e['updated_at']=$now;$e['done_at']=$now;$e['cancel_requested_at']=$now;$e['error']='stopped_by_user';}unset($e);return ['ok'=>true];});
    $fixStopState=matrixFixProgressRead();
    matrixFixProgress(['running'=>false,'done'=>true,'stopped'=>true,'cancelled'=>true,'stop_requested'=>true,
        'phase'=>'stopped','finished_at'=>time(),'log_add'=>['⏹ اصلاح فوراً توسط کاربر متوقف شد']]);
    $terminated=matrixTerminateRunner($fixStopState);
    echo json_encode(['ok' => true, 'stopping' => false,'stopped'=>true,'runner'=>$terminated], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['sync_matrix_fix_start']) || (($_POST['action'] ?? '') === 'sync_matrix_fix_start')) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(0);
    @ignore_user_abort(true);
    $opts = [
        'scope' => (string)($_GET['scope'] ?? $_POST['scope'] ?? 'all'),
        'delay_ms' => (int)($_GET['delay_ms'] ?? $_POST['delay_ms'] ?? 180),
        'source' => (string)($_GET['source'] ?? $_POST['source'] ?? 'manual'),
        'duplicate_keep' => (string)($_GET['duplicate_keep'] ?? $_POST['duplicate_keep'] ?? 'newest'),
        'selected_destinations' => matrixNormalizeDestinations($_GET['selected_destinations'] ?? $_POST['selected_destinations'] ?? null),
        'view_filters' => [
            'q'=>(string)($_GET['q']??$_POST['q']??''),
            'only_problem'=>!empty($_GET['only_problem']??$_POST['only_problem']??null),
            'only_dup'=>!empty($_GET['only_dup']??$_POST['only_dup']??null),
            'prefer_coded_duplicate'=>!empty($_GET['prefer_coded_duplicate']??$_POST['prefer_coded_duplicate']??null),
            'only_mismatch'=>!empty($_GET['only_mismatch']??$_POST['only_mismatch']??null),
            'only_missing'=>!empty($_GET['only_missing']??$_POST['only_missing']??null),
            'filter_type'=>(string)($_GET['filter_type']??$_POST['filter_type']??''),
            'filter_value'=>(string)($_GET['filter_value']??$_POST['filter_value']??''),
            'filters'=>(static function($raw){$v=json_decode((string)$raw,true);return is_array($v)?$v:[];})(($_GET['filters_json']??$_POST['filters_json']??'[]')),
            'filter_join'=>(string)($_GET['filter_join']??$_POST['filter_join']??'and'),
            'sort'=>(string)($_GET['sort']??$_POST['sort']??''),
            'sort_dir'=>(string)($_GET['sort_dir']??$_POST['sort_dir']??'asc'),
            'selected_bares'=>(static function($raw){$v=json_decode((string)$raw,true);return is_array($v)?array_values(array_unique(array_filter(array_map('strval',$v)))):[];})(($_GET['selected_bares_json']??$_POST['selected_bares_json']??'[]')),
            'excluded_bares'=>(static function($raw){$v=json_decode((string)$raw,true);return is_array($v)?array_values(array_unique(array_filter(array_map('strval',$v)))):[];})(($_GET['excluded_bares_json']??$_POST['excluded_bares_json']??'[]')),
        ],
    ];
    if (!$opts['selected_destinations']) {
        echo json_encode(['ok'=>false,'error'=>'حداقل یک مقصد مشمول برای اصلاح انتخاب کنید'],JSON_UNESCAPED_UNICODE); exit;
    }
    $workflow=(string)($_GET['workflow']??$_POST['workflow']??'fix_only');
    if(!in_array($workflow,['fix_only','build_and_fix'],true))$workflow='fix_only';
    $combinedWorkflow=$workflow==='build_and_fix';
    $matrixFixCp = null;
    $oldFix = [];
    if (!empty($_GET['resume']) && is_file(SYNC_MATRIX_FIX_PROGRESS_FILE)) {
        $oldFix = json_decode((string)@file_get_contents(SYNC_MATRIX_FIX_PROGRESS_FILE), true);
        if (!is_array($oldFix)) $oldFix = [];
        $oldFixCp = is_array($oldFix['checkpoint'] ?? null) ? $oldFix['checkpoint'] : null;
        if (is_array($oldFixCp) && (string)($oldFixCp['scope'] ?? 'all') === $opts['scope']
            && is_array($oldFixCp['done_jobs'] ?? null)) $matrixFixCp = $oldFixCp;
    }
    $opts['checkpoint'] = $matrixFixCp;
    matrixFixStopClear();
    /* اصلاح دستی روی snapshot تازه اجرا می‌شود، اما snapshot همین چند دقیقهٔ
       اخیر تازه است و checkpoint ناتمام همیشه باید قبل از هر rebuild ادامه یابد. */
    $fixMatrix=is_file(SYNC_MATRIX_RESULT_FILE)?matrixResultLoad():[];
    if (!empty($_GET['resume']) && !isset($_GET['selected_destinations']) && !isset($_POST['selected_destinations'])) {
        $inheritedDest = !empty($oldFix['selected_destinations']) ? $oldFix['selected_destinations'] : ($fixMatrix['selected_destinations'] ?? null);
        if (is_array($inheritedDest) && $inheritedDest) {
            $normInh = matrixNormalizeDestinations($inheritedDest);
            if ($normInh) $opts['selected_destinations'] = $normInh;
        }
    }
    $fixHave=array_values((array)($fixMatrix['selected_destinations']??[]));sort($fixHave);
    $fixWant=array_values($opts['selected_destinations']);sort($fixWant);
    /* An unfinished build wins over correction's freshness request. Queue/resume
       that exact checkpoint and put fix behind it; never clear its cursor. */
    $mxBeforeFix=matrixProgressRead();$mxCp=is_array($mxBeforeFix['checkpoint']??null)?$mxBeforeFix['checkpoint']:null;
    if($mxCp&&!$combinedWorkflow){
        echo json_encode(['ok'=>false,'error'=>'ساخت جدول ناتمام است؛ برای ادامهٔ ساخت و سپس اصلاح از دکمهٔ «ساخت جدول + اصلاح کلی» استفاده کنید',
            'code'=>'matrix_build_incomplete','checkpoint_preserved'=>true],JSON_UNESCAPED_UNICODE);exit;
    }
    if($mxCp&&$combinedWorkflow){
        $wa=s4WorkerIsActive();if(!$wa){s4SpawnPersistentWorker();usleep(400000);$wa=s4WorkerIsActive();}
        if(!$wa){echo json_encode(['ok'=>false,'error'=>'worker پایدار برای ادامهٔ checkpoint آماده نشد'],JSON_UNESCAPED_UNICODE);exit;}
        $resumeRequestedAt=time();
        $buildEnq=s4WorkerEnqueueMatrixBuild(['profile'=>(string)($mxCp['profile_filter']??'all'),
            'parallel_destinations'=>(string)($mxCp['fetch_mode']??'serial')==='parallel','live_fill'=>!empty($mxCp['live_fill']),
            'selected_destinations'=>$opts['selected_destinations'],'slice_seconds'=>(int)($mxCp['slice_seconds']??8)],true);
        if(empty($buildEnq['ok'])){echo json_encode(['ok'=>false,'error'=>'ادامهٔ checkpoint در صف قرار نگرفت','matrix_job'=>$buildEnq],JSON_UNESCAPED_UNICODE);exit;}
        $opts['min_matrix_generated_at']=$resumeRequestedAt;$fixEnq=s4WorkerEnqueueMatrixFix($opts,false);
        echo json_encode(['ok'=>!empty($fixEnq['ok']),'started'=>!empty($fixEnq['ok']),'running'=>true,
            'resuming_matrix'=>true,'waiting_for_matrix'=>true,'combined_workflow'=>true,'message'=>'ابتدا همان checkpoint ناتمام ادامه می‌یابد؛ سپس اصلاح کلی اجرا می‌شود',
            'matrix_job'=>$buildEnq,'fix_job'=>$fixEnq],JSON_UNESCAPED_UNICODE);exit;
    }
    /* Correction-only means exactly the matrix currently visible: age alone must
       never trigger a surprise rebuild. The explicit combined workflow is the
       only manual action allowed to create a fresh build before correction. */
    $fixNeedsBuild=!$fixMatrix||$fixHave!==$fixWant
        ||(empty($_GET['resume']) && (string)($fixMatrix['pricing_signature']??'')!==matrixPricingFingerprint());
    if($fixNeedsBuild&&!$combinedWorkflow){
        echo json_encode(['ok'=>false,'error'=>'جدول فعلی برای این مقصدها آماده/سازگار نیست؛ ابتدا جدول را بسازید یا دکمهٔ «ساخت جدول + اصلاح کلی» را بزنید',
            'code'=>'matrix_not_ready_for_fix','needs_build'=>true],JSON_UNESCAPED_UNICODE);exit;
    }
    if($combinedWorkflow){
        /* This named action intentionally builds even when a recent result exists. */
        $opts['view_filters']=[];$opts['scope']='all';
        $wa=s4WorkerIsActive();if(!$wa){s4SpawnPersistentWorker();usleep(400000);$wa=s4WorkerIsActive();}
        if(!$wa){echo json_encode(['ok'=>false,'error'=>'worker پایدار برای زنجیرهٔ ساخت و اصلاح آماده نشد'],JSON_UNESCAPED_UNICODE);exit;}
        $freshRequestedAt=time();
        $buildEnq=s4WorkerEnqueueMatrixBuild(['profile'=>'all',
            'parallel_destinations'=>!empty($_GET['parallel_destinations']??$_POST['parallel_destinations']??null),
            'live_fill'=>!array_key_exists('live_fill',$_POST)||!empty($_POST['live_fill']),
            'selected_destinations'=>$opts['selected_destinations'],'coded_only'=>false,
            'slice_seconds'=>max(2,min(20,(int)($_GET['slice_seconds']??$_POST['slice_seconds']??8)))],false);
        if(empty($buildEnq['ok'])){
            echo json_encode(['ok'=>false,'error'=>'بازسازی تازهٔ جدول در صف قرار نگرفت','matrix_job'=>$buildEnq],JSON_UNESCAPED_UNICODE);exit;
        }
        $opts['min_matrix_generated_at']=$freshRequestedAt;
        $fixEnq=s4WorkerEnqueueMatrixFix($opts,false);
        if(empty($fixEnq['ok'])){
            echo json_encode(['ok'=>false,'error'=>'ساخت جدول صف شد اما اصلاح در صف قرار نگرفت','matrix_job'=>$buildEnq,'fix_job'=>$fixEnq],JSON_UNESCAPED_UNICODE);exit;
        }
        echo json_encode(['ok'=>true,'started'=>true,'running'=>true,'refreshing_matrix'=>true,'combined_workflow'=>true,
            'message'=>'زنجیرهٔ صریح آغاز شد: ابتدا ساخت کامل جدول، سپس اصلاح کلی همان نتیجه','matrix_job'=>$buildEnq,'fix_job'=>$fixEnq],JSON_UNESCAPED_UNICODE);exit;
    }
    /* don't run while matrix build is running */
    $mxProg = matrixProgressRead();
    if (!empty($mxProg['running'])) {
        if(s4WorkerIsActive()){
            $fixEnq=s4WorkerEnqueueMatrixFix($opts,false);
            echo json_encode(['ok'=>!empty($fixEnq['ok']),'started'=>!empty($fixEnq['ok']),'running'=>true,
                'waiting_for_matrix'=>true,'message'=>'اصلاح در صف است و خودکار پس از پایان ساخت جدول آغاز می‌شود']+$fixEnq,JSON_UNESCAPED_UNICODE);exit;
        }
        echo json_encode(['ok' => false, 'error' => 'ساخت جدول در حال اجراست ولی worker پایدار در دسترس نیست', 'running' => true], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $lockFile = SYNC_MATRIX_FIX_LOCK_FILE;
    /* endpoint شروع خودش worker را تضمین می‌کند؛ برگشتن به PHP-FPM همان علت
       اصلی قطع‌شدن وسط راه بود. اگر worker بالا نیاید، صریح خطا بده. */
    $fixWorkerActive=s4WorkerIsActive();
    if(!$fixWorkerActive){$spawnFixWorker=s4SpawnPersistentWorker();usleep(400000);$fixWorkerActive=s4WorkerIsActive();}
    /* روی هاست exec-disabled، همان request مرورگر مالک fallback می‌شود. UI
       هم‌زمان status را poll می‌کند و checkpoint برای wake بعدی می‌ماند. */
    $fixBrowserKeep=!$fixWorkerActive&&!empty($_GET['browser_keep']??$_POST['browser_keep']??null);
    /* کار بلند اصلاح را به child مستقل worker بسپار. ابتدا lock را probe
       می‌کنیم تا اجرای worker دیگر دوباره‌کاری نسازد. */
    if ($fixWorkerActive) {
        $probe = @fopen($lockFile, 'c');
        $free = $probe && @flock($probe, LOCK_EX | LOCK_NB);
        if (!$free) {
            if ($probe) @fclose($probe);
            echo json_encode(['ok'=>false,'error'=>'یک اصلاح در حال اجراست','running'=>true],JSON_UNESCAPED_UNICODE); exit;
        }
        @flock($probe, LOCK_UN); @fclose($probe);
        $oldFix = matrixFixProgressRead();
        $oldCp = is_array($oldFix['checkpoint'] ?? null) ? $oldFix['checkpoint'] : null;
        $sameFilters = $oldCp && json_encode($oldCp['view_filters'] ?? []) === json_encode($opts['view_filters']);
        $sameDestinations = !$oldCp || json_encode(array_values((array)($oldFix['selected_destinations']??[]))) === json_encode($opts['selected_destinations']);
        $resumeWorker = $oldCp && ((int)($oldCp['cur'] ?? 0) > 0 || !empty($oldCp['done_jobs']))
            && (string)($oldCp['scope'] ?? 'all') === $opts['scope']
            && (string)($oldCp['duplicate_keep'] ?? 'newest') === $opts['duplicate_keep'] && $sameFilters && $sameDestinations;
        matrixFixStopClear();
        $enq = s4WorkerEnqueueMatrixFix($opts, (bool)$resumeWorker);
        echo json_encode(array_merge(['ok'=>!empty($enq['ok']),'started'=>!empty($enq['ok']),
            'running'=>!empty($enq['ok']),'worker'=>true,'resumed'=>(bool)$resumeWorker],$enq),JSON_UNESCAPED_UNICODE); exit;
    }
    $fp = @fopen($lockFile, 'c');
    if (!$fp || !flock($fp, LOCK_EX | LOCK_NB)) {
        if ($fp) @fclose($fp);
        echo json_encode(['ok' => false, 'error' => 'یک اصلاح در حال اجراست', 'running' => true], JSON_UNESCAPED_UNICODE);
        exit;
    }
    /* stopِ قدیمی را فقط پس از مالکیتِ lock مصرف کن؛ stopی که بعد از این
       خط نوشته شود دست‌نخورده می‌ماند و worker در اولینِ probe آن را می‌بیند. */
    matrixFixStopClear();
    matrixFixProgress([
        'running' => true, 'done' => false, 'error' => '', 'pct' => 1,
        'phase' => 'queued', 'started_at' => (int)($matrixFixCp['started_at'] ?? time()), 'runner_pid'=>(int)@getmypid(), 'runner_kind'=>'matrix_fix', 'source' => $opts['source'],
        'scope' => $opts['scope'], 'delay_ms' => $opts['delay_ms'],
        'job' => 'fix', 'log' => [], 'live' => [],
        'checkpoint' => $matrixFixCp ?: ['scope' => $opts['scope'], 'duplicate_keep' => $opts['duplicate_keep'], 'done_jobs' => [], 'started_at' => time()],
        'log_add' => ['🚀 ' . ($matrixFixCp ? 'ادامه اصلاح مغایرت از checkpoint' : 'جاب اصلاح مغایرت در صف سرور') . '…'],
    ]);
    if(!$fixBrowserKeep){
        $early = json_encode(['ok' => true, 'started' => true, 'message' => 'اصلاح روی سرور شروع شد', 'running' => true], JSON_UNESCAPED_UNICODE);
        header('Connection: close');header('Content-Length: ' . strlen($early));echo $early;
        @ob_end_flush();@ob_flush();@flush();
        if (function_exists('fastcgi_finish_request')) @fastcgi_finish_request();
    }else{
        header('Cache-Control: no-store');header('X-Accel-Buffering: no');@ini_set('zlib.output_compression','0');
    }
    register_shutdown_function(function () use ($fp, $lockFile) {
        @flock($fp, LOCK_UN);@fclose($fp);
    });
    $fixWebResult=null;
    try {
        $fixWebResult=matrixFixRun($opts);
    } catch (Throwable $e) {
        $fixErrState = matrixFixProgressRead();
        matrixFixProgress([
            'running' => false, 'done' => true, 'stale' => true, 'error' => $e->getMessage(), 'pct' => 100,
            'checkpoint' => is_array($fixErrState['checkpoint'] ?? null) ? $fixErrState['checkpoint'] : null,
            'log_add' => ['❌ ' . $e->getMessage() . ' — checkpoint حفظ شد'],
        ]);
        $fixWebResult=['ok'=>false,'error'=>$e->getMessage()];
    }
    if($fixBrowserKeep)echo json_encode(['ok'=>!empty($fixWebResult['ok']),'started'=>true,
        'browser_held'=>true,'result'=>$fixWebResult],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    exit;
}


if (isset($_GET['remote_map'])) {
    ob_clean();
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(180);
    $clr = (string)($_GET['clear'] ?? '');
    if ($clr === 'woo' || $clr === 'bsl') {
        $m = remoteMapLoad(); $m[$clr] = []; remoteMapSave($m);
        echo json_encode(['ok' => true, 'cleared' => $clr], JSON_UNESCAPED_UNICODE); exit;
    }
    $rb = (string)($_GET['rebuild'] ?? '');
    if ($rb === 'woo' || $rb === 'bsl') {
        // یک بار با عنوان تطبیق می‌دهیم و شناسه‌ها را ثبت می‌کنیم، تا از این
        // به بعد تغییر نام محصول دیگر تطبیق را خراب نکند.
        $cnR = loadConnections();
        $st = null;
        $exp = reconExpected($rb, true, $st);
        $byTitleKey = [];
        foreach (loadProfiles() as $pk => $pv) {
            foreach (profileOrderedProducts($pv) as $pp) {
                $t = reconNormTitle((string)($pp['title'] ?? ''));
                $kk = trim((string)($pp['key'] ?? ''));
                if ($t !== '' && $kk !== '' && !isset($byTitleKey[$t])) $byTitleKey[$t] = ['key' => $kk, 'title' => $pp['title'] ?? ''];
            }
        }
        if ($rb === 'woo') {
            $w = $cnR['woocommerce'] ?? [];
            if (empty($w['store_url'])) { echo json_encode(['ok' => false, 'error' => 'تنظیمات ووکامرس ناقص'], JSON_UNESCAPED_UNICODE); exit; }
            $remote = reconFetchWoo($w);
        } else {
            $tk = (string)($cnR['basalam']['token'] ?? ''); $vid = (int)($cnR['basalam']['vendor_id'] ?? 0);
            if ($tk === '' || $vid <= 0) { echo json_encode(['ok' => false, 'error' => 'تنظیمات باسلام ناقص'], JSON_UNESCAPED_UNICODE); exit; }
            $remote = reconFetchBsl($tk, $vid);
        }
        $rows = [];
        foreach ($remote as $r) {
            $t = reconNormTitle((string)$r['title']);
            if (!isset($byTitleKey[$t])) continue;
            $rows[] = ['key' => $byTitleKey[$t]['key'], 'remote_id' => (int)$r['id'],
                       'title' => (string)$r['title']];
        }
        $n = remoteMapRecord($rb, $rows);
        echo json_encode(['ok' => true, 'rebuilt' => $rb, 'recorded' => $n,
            'remote_seen' => count($remote), 'profile_titles' => count($byTitleKey),
            'note' => $n . ' شناسه ثبت شد — از این به بعد تغییر نام محصول تطبیق را خراب نمی‌کند'],
            JSON_UNESCAPED_UNICODE);
        exit;
    }
    $m = remoteMapLoad();
    $sample = [];
    foreach (['woo', 'bsl'] as $t) {
        $i = 0;
        foreach ($m[$t] as $k => $v) {
            if ($i++ >= 5) break;
            $sample[$t][] = ['key' => mb_substr($k, 0, 10), 'id' => (int)($v['id'] ?? 0),
                             'title' => (string)($v['title'] ?? '')];
        }
    }
    echo json_encode(['ok' => true, 'woo' => count($m['woo']), 'bsl' => count($m['bsl']),
        'sample' => $sample], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['ar_rules'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cnAR = loadConnections();
    // ?defaults=1 قواعد کارخانه را برمی‌گرداند بدون اینکه چیزی را ذخیره کند
    $rulesAR = !empty($_GET['defaults']) ? arDefaultRules() : arLoadRules();
    echo json_encode(['ok' => true, 'rules' => $rulesAR, 'cfg' => arCfg($cnAR),
        'saved' => is_file(AUTOREPLY_RULES_FILE),
        'offhours_now' => arIsOffHours(arCfg($cnAR), time())], JSON_UNESCAPED_UNICODE);
    exit;
}

if (($_POST['action'] ?? '') === 'ar_save_rules') {
    header('Content-Type: application/json; charset=UTF-8');
    $rules = json_decode((string)($_POST['rules'] ?? '[]'), true);
    if (!is_array($rules)) { echo json_encode(['ok' => false, 'error' => 'قواعد نامعتبر'], JSON_UNESCAPED_UNICODE); exit; }
    $ok = arSaveRules($rules);
    echo json_encode(['ok' => $ok, 'count' => count($rules),
        'error' => $ok ? '' : 'نوشتن فایل قواعد ناموفق بود'], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['ar_test'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $txt = (string)($_GET['text'] ?? '');
    if (trim($txt) === '') { echo json_encode(['ok' => false, 'error' => 'متن خالی است'], JSON_UNESCAPED_UNICODE); exit; }
    $rules = arLoadRules();
    $cfgAR = arCfg();
    $all = [];
    foreach ($rules as $r) {
        $all[] = ['id' => $r['id'] ?? '', 'on' => !empty($r['on']),
                  'match' => arRuleMatches($r, $txt)];
    }
    /* v9.38: آزمایش طبق «ترتیب اولویت» انتخاب‌شده اجرا می‌شود (rules_first /
       ai_first / rules_only / ai_only) تا نتیجه‌اش همان چیزی باشد که در عمل
       اتفاق می‌افتد. هوش مصنوعی واقعاً صدا زده می‌شود.
       v9.35: مهلت کوتاه (۸ ثانیه) تا دکمهٔ آزمایش هرگز کاربر را معطل نکند
       و سریع جواب بدهد. */
    @set_time_limit(40);
    $order = (string)($cfgAR['reply_order'] ?? 'rules_first');
    $aiOk = false; $aiText = ''; $aiErr = '';
    $hit = null; $ruleReply = ''; $ruleId = '';
    if ($order === 'ai_first' || $order === 'ai_only') {
        $aiRes = arAiReplyText($txt, 8);
        $aiOk = !empty($aiRes['ok']);
        $aiText = $aiOk ? ($aiRes['text'] . ($cfgAR['sign'] !== '' ? "\n" . $cfgAR['sign'] : '')) : '';
        $aiErr = $aiOk ? '' : (string)($aiRes['error'] ?? 'خطا');
        if (!$aiOk && $order === 'ai_first') $hit = arPickRule($rules, $txt);
    } elseif ($order === 'rules_first') {
        $hit = arPickRule($rules, $txt);
        if ($hit === null) {
            $aiRes = arAiReplyText($txt, 8);
            $aiOk = !empty($aiRes['ok']);
            $aiText = $aiOk ? ($aiRes['text'] . ($cfgAR['sign'] !== '' ? "\n" . $cfgAR['sign'] : '')) : '';
            $aiErr = $aiOk ? '' : (string)($aiRes['error'] ?? 'خطا');
        }
    } else { // rules_only
        $hit = arPickRule($rules, $txt);
    }
    if ($hit) {
        $ruleId = (string)$hit['id'];
        $ruleReply = $hit['reply'] . ($cfgAR['sign'] !== '' ? "\n" . $cfgAR['sign'] : '');
    }
    $finalReply = $aiOk ? $aiText : $ruleReply;
    $source = $aiOk ? 'ai' : ($hit ? 'rule' : 'none');
    echo json_encode(['ok' => true, 'normalized' => arNormText($txt),
        'order' => $order,
        'ai_ok' => $aiOk, 'ai_error' => $aiErr, 'ai_reply' => $aiText,
        'rule' => $ruleId, 'rule_reply' => $ruleReply,
        'source' => $source, 'reply' => $finalReply,
        'checked' => $all], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['ar_log'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $stAR = arLoadState();
    echo json_encode(['ok' => true, 'log' => array_slice(arLogRead(), 0, 30),
        'last_run' => (int)($stAR['last_run'] ?? 0), 'daily' => $stAR['daily'] ?? []],
        JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v10.55 (69): پاسخ دستی به پیام‌های مشتری
 *
 *  خواستهٔ کاربر: برای جواب دادن به مشتری نباید رفت پلتفرمِ باسلام را
 *  باز کرد. گفتگوها داخلِ پنل باز می‌شوند و پاسخ همین‌جا فرستاده می‌شود.
 *  • bsl_chats         — فهرستِ گفتگوهایِ تازه (با شمارِ خوانده‌نشده)
 *  • bsl_chat_messages — تاریخچهٔ کاملِ یک گفتگو (هر دو طرف)
 *  • bsl_chat_reply    — ارسالِ پاسخ (فرستندهٔ واقعی همان bslSendChatMessage
 *                        است — یک فرستنده برای همهٔ پاسخ‌ها)
 * ===================================================================== */
if (isset($_GET['bsl_chats'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(60);
    $cnMR = loadConnections();
    $shopsMR = bslChatShops($cnMR);
    if (!$shopsMR) { echo json_encode(['ok' => false, 'error' => 'غرفهٔ باسلامی با توکن تنظیم نشده است'], JSON_UNESCAPED_UNICODE); exit; }
    $limMR = max(5, min(50, (int)($_GET['limit'] ?? 30)));
    $onlyMR = (int)($_GET['shop'] ?? 0);   // 0 = همهٔ غرفه‌ها
    /* v10.57 (۷۱): کشِ ۲ ثانیه‌ای — رابط کاربری هر ثانیه پُل می‌زند؛ با کش
       هر غرفه در هر ۲ ثانیه یک‌بار به API می‌رسد، نه هر ثانیه. */
    $cFileMR = __DIR__ . '/bsl_chats_cache.json';
    $cachedMR = [];
    if (is_file($cFileMR) && time() - (int)@filemtime($cFileMR) <= 2) {
        $cD = json_decode((string)@file_get_contents($cFileMR), true);
        if (is_array($cD) && is_array($cD['rows'] ?? null)) $cachedMR = $cD['rows'];
    }
    $rowsMR = []; $shopErrMR = []; $shopOutMR = [];
    foreach ($shopsMR as $shMR) {
        if ($onlyMR > 0 && (int)$shMR['shop'] !== $onlyMR) continue;
        $kMR = (string)$shMR['shop'];
        if (isset($cachedMR[$kMR])) {
            $rowsMR = array_merge($rowsMR, $cachedMR[$kMR]);
            $shopOutMR[] = ['shop' => (int)$shMR['shop'], 'name' => $shMR['name'], 'ok' => true, 'n' => count($cachedMR[$kMR])];
            continue;
        }
        $outShMR = [];
        $rMR = bslReqRead($shMR['token'], 'chats?limit=' . $limMR . '&order_by=updated_at');
        if (empty($rMR['ok'])) {
            $shopErrMR[] = ['shop' => (int)$shMR['shop'], 'name' => $shMR['name'],
                            'error' => bslApiError($rMR, 'دریافت گفتگوها ناموفق', 'chats', 'customer.chat.read')];
            $shopOutMR[] = ['shop' => (int)$shMR['shop'], 'name' => $shMR['name'], 'ok' => false, 'n' => 0];
            continue;
        }
        $myIdMR = bslMyUserId($shMR['token']);
        $rawMR = $rMR['body']['data']['chats'] ?? ($rMR['body']['data'] ?? []);
        if (!is_array($rawMR)) $rawMR = [];
        foreach ($rawMR as $cMR) {
            if (!is_array($cMR)) continue;
            $ncMR = bslNormalizeChat($cMR);
            $lmMR = is_array($cMR['last_message'] ?? null) ? $cMR['last_message'] : [];
            if ($ncMR['chat_id'] <= 0) continue;
            /* v10.62 (۷۶): آدرسِ تصویرِ آخرین پیام (اگر پیام تصویر باشد) —
               پیش‌نمایش در کارتِ نوتیف و لیستِ گفتگوها. از همهٔ شکل‌هایِ
               ممکنِ پاسخ برداشته می‌شود (همان الگوی bslChatThread). */
            $lmImgMR = '';
            foreach ([$lmMR['attachment']['files'][0]['url'] ?? null,
                      $lmMR['content']['url'] ?? null,
                      $lmMR['content']['files'][0]['url'] ?? null,
                      $lmMR['url'] ?? null,
                      $lmMR['content']['image'] ?? null,
                      $lmMR['image'] ?? null] as $uImgMR) {
                if (is_string($uImgMR) && strncmp($uImgMR, 'http', 4) === 0) { $lmImgMR = $uImgMR; break; }
            }
            $outShMR[] = [
                'chat_id'      => $ncMR['chat_id'],
                'who'          => $ncMR['who'],
                'text'         => $ncMR['text'],
                'unseen'       => $ncMR['unseen'],
                'updated_at'   => $ncMR['updated_at'],
                'last_is_mine' => ($myIdMR > 0 && (int)($lmMR['sender']['id'] ?? 0) === $myIdMR),
                /* v10.60 (۷۴): شناسهٔ آخرین پیام — مبنای کشفِ پیامِ تازهٔ مشتری
                   برای نوتیفیکیشنِ زنده (کارتِ سوایپ‌شونده). */
                'last_msg_id'  => (int)($lmMR['id'] ?? 0),
                'last_img'     => $lmImgMR,
                'last_type'    => (string)($lmMR['message_type'] ?? ''),
                'shop'         => (int)$shMR['shop'],
                'shop_name'    => $shMR['name'],
                'vendor_id'    => (int)$shMR['vendor_id'],
            ];
        }
        $rowsMR = array_merge($rowsMR, $outShMR);
        $cachedMR[$kMR] = $outShMR;
        $shopOutMR[] = ['shop' => (int)$shMR['shop'], 'name' => $shMR['name'], 'ok' => true, 'n' => count($outShMR)];
    }
    @file_put_contents($cFileMR, json_encode(['rows' => $cachedMR], JSON_UNESCAPED_UNICODE), LOCK_EX);
    usort($rowsMR, function ($a, $b) { return strcmp((string)($b['updated_at'] ?? ''), (string)($a['updated_at'] ?? '')); });
    echo json_encode(['ok' => true, 'chats' => $rowsMR, 'shops' => $shopOutMR, 'shop_errors' => $shopErrMR], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['bsl_chat_messages'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(60);
    $cnMR = loadConnections();
    $shopsMR = bslChatShops($cnMR);
    if (!$shopsMR) { echo json_encode(['ok' => false, 'error' => 'غرفهٔ باسلامی با توکن تنظیم نشده است'], JSON_UNESCAPED_UNICODE); exit; }
    $chatIdMR = (int)($_GET['chat_id'] ?? 0);
    $limMR = max(1, min(50, (int)($_GET['limit'] ?? 30)));
    $shopNMR = (int)($_GET['shop'] ?? 0);
    if ($chatIdMR <= 0) { echo json_encode(['ok' => false, 'error' => 'شناسهٔ گفتگو نامعتبر'], JSON_UNESCAPED_UNICODE); exit; }
    /* v10.57 (۷۱): اگر شمارهٔ غرفه آمده فقط همان؛ وگرنه گفتگو ممکن است از
       هر غرفه‌ای باشد — به ترتیب امتحان می‌کنیم تا یکی جواب بدهد. */
    $tryMR = ($shopNMR > 0)
        ? array_values(array_filter($shopsMR, function ($x) use ($shopNMR) { return (int)$x['shop'] === $shopNMR; }))
        : $shopsMR;
    $msgsMR = []; $shMR = null;
    foreach ($tryMR as $candMR) {
        $msgsMR = bslChatThread($candMR['token'], $chatIdMR, $limMR);
        if ($msgsMR) { $shMR = $candMR; break; }
    }
    echo json_encode(['ok' => true, 'messages' => $msgsMR,
                      'shop' => $shMR ? (int)$shMR['shop'] : 0,
                      'shop_name' => $shMR ? $shMR['name'] : ''], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['bsl_chat_reply'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(90);
    @ini_set('post_max_size', '16M');
    @ini_set('upload_max_filesize', '16M');
    $cnMR = loadConnections();
    $shopsMR = bslChatShops($cnMR);
    if (!$shopsMR) { echo json_encode(['ok' => false, 'error' => 'غرفهٔ باسلامی با توکن تنظیم نشده است'], JSON_UNESCAPED_UNICODE); exit; }
    $chatIdMR = (int)($_POST['chat_id'] ?? $_GET['chat_id'] ?? 0);
    $textMR = trim((string)($_POST['text'] ?? $_GET['text'] ?? ''));
    $shopNMR = (int)($_POST['shop'] ?? $_GET['shop'] ?? 0);
    $shMR = $shopNMR > 0 ? bslShopByNum($shopsMR, $shopNMR) : null;
    if ($shMR === null) $shMR = $shopsMR[0];   // عقب‌نشینی: اولینِ (پیش‌فرض)
    if ($chatIdMR <= 0) { echo json_encode(['ok' => false, 'error' => 'شناسهٔ گفتگو لازم است'], JSON_UNESCAPED_UNICODE); exit; }
    /* v10.57 (۷۱): تصویر (dataURL یا base64) — اول به سرویسِ آپلودِ باسلام
       می‌رود (chat.photo)، بعد به‌صورتِ attachment به گفتگو پیوست می‌شود. */
    $fileMR = null;
    $imgB64MR = trim((string)($_POST['image_b64'] ?? ''));
    $imgNameMR = trim((string)($_POST['image_name'] ?? ''));
    if ($imgNameMR === '') $imgNameMR = 'تصویر';
    $imgMimeMR = trim((string)($_POST['image_mime'] ?? ''));
    if ($imgB64MR !== '') {
        if (preg_match('/^data:(image\/[^;]+);base64,(.+)$/is', $imgB64MR, $mImgMR)) {
            $imgMimeMR = $mImgMR[1]; $imgB64MR = $mImgMR[2];
        }
        $b64LenMR = strlen($imgB64MR);
        if ($b64LenMR < 100 || $b64LenMR > 9500000) {
            echo json_encode(['ok' => false, 'error' => 'تصویر نامعتبر است (بیش‌ازحد بزرگ — حداکثر حدود ۷ مگابایت)'], JSON_UNESCAPED_UNICODE); exit;
        }
        $binMR = base64_decode($imgB64MR, true);
        if ($binMR === false) { echo json_encode(['ok' => false, 'error' => 'فایلِ تصویر خراب است'], JSON_UNESCAPED_UNICODE); exit; }
        $tmpMR = tempnam(sys_get_temp_dir(), 'mrimg_');
        if ($tmpMR === false || file_put_contents($tmpMR, $binMR) === false) {
            echo json_encode(['ok' => false, 'error' => 'ذخیرهٔ موقتِ تصویر ناموفق بود'], JSON_UNESCAPED_UNICODE); exit;
        }
        $isImgMR = (strpos($imgMimeMR, 'image/') === 0);
        $upMR = bslChatUploadFile($shMR['token'], $tmpMR, $imgMimeMR, $imgNameMR, $isImgMR ? 'chat.photo' : 'chat.file');
        @unlink($tmpMR);
        if (empty($upMR['ok'])) {
            echo json_encode(['ok' => false, 'error' => 'آپلود تصویر: ' . ($upMR['error'] ?? 'ناموفق')], JSON_UNESCAPED_UNICODE); exit;
        }
        $fileMR = ['id' => $upMR['id'], 'url' => $upMR['url'], 'width' => $upMR['width'],
                   'height' => $upMR['height'], 'size' => $upMR['size'],
                   'name' => $imgNameMR, 'type' => $isImgMR ? 'picture' : 'file'];
    }
    if ($textMR === '' && $fileMR === null) {
        echo json_encode(['ok' => false, 'error' => 'متنِ پیام یا یک تصویر لازم است'], JSON_UNESCAPED_UNICODE); exit;
    }
    $rMR = bslChatSendEx($shMR['token'], $chatIdMR, $textMR, $fileMR);
    /* پاسخِ دستی (متن یا تصویر) هم در همان لاگِ پاسخ‌ها ثبت می‌شود. */
    arLogAdd(['type' => 'manual', 'chat_id' => $chatIdMR, 'who' => '',
              'text' => mb_substr($textMR !== '' ? $textMR : '🖼 تصویر', 0, 90),
              'ok' => !empty($rMR['ok']), 'source' => 'manual',
              'shop' => (int)$shMR['shop'], 'has_image' => $fileMR !== null]);
    if (empty($rMR['ok'])) {
        echo json_encode(['ok' => false, 'error' => $rMR['error'] ?? 'ارسال ناموفق'], JSON_UNESCAPED_UNICODE); exit;
    }
    echo json_encode(['ok' => true, 'shop' => (int)$shMR['shop']], JSON_UNESCAPED_UNICODE);
    exit;
}

/* v9.36: محیط چتِ آزمایش پاسخ خودکار (مودال).
   مثل ar_test ولی با اطلاعات بیشتر برای نمایش در یک پنجرهٔ چت:
   منبع (هوش مصنوعی / قاعده / بدون پاسخ)، مدلِ استفاده‌شده، تأخیر، و پیام خطا. */
if (isset($_GET['ar_chat'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(40);
    $txt = (string)($_GET['msg'] ?? ($_GET['text'] ?? ''));
    if (trim($txt) === '') { echo json_encode(['ok' => false, 'error' => 'متن خالی است'], JSON_UNESCAPED_UNICODE); exit; }
    $rules = arLoadRules();
    $cfgAR = arCfg();
    $t0 = microtime(true);
    $order = (string)($cfgAR['reply_order'] ?? 'rules_first');
    $aiOk = false; $aiText = ''; $aiErr = ''; $modelUsed = '';
    $hit = null; $ruleReply = ''; $ruleId = '';
    if ($order === 'ai_first' || $order === 'ai_only') {
        $aiRes = arAiReplyText($txt, 8);
        $aiOk = !empty($aiRes['ok']);
        $aiText = $aiOk ? ($aiRes['text'] . ($cfgAR['sign'] !== '' ? "\n" . $cfgAR['sign'] : '')) : '';
        $aiErr = $aiOk ? '' : (string)($aiRes['error'] ?? 'خطا');
        $modelUsed = (string)($aiRes['model'] ?? '');
        if (!$aiOk && $order === 'ai_first') $hit = arPickRule($rules, $txt);
    } elseif ($order === 'rules_first') {
        $hit = arPickRule($rules, $txt);
        if ($hit === null) {
            $aiRes = arAiReplyText($txt, 8);
            $aiOk = !empty($aiRes['ok']);
            $aiText = $aiOk ? ($aiRes['text'] . ($cfgAR['sign'] !== '' ? "\n" . $cfgAR['sign'] : '')) : '';
            $aiErr = $aiOk ? '' : (string)($aiRes['error'] ?? 'خطا');
            $modelUsed = (string)($aiRes['model'] ?? '');
        }
    } else { // rules_only
        $hit = arPickRule($rules, $txt);
    }
    $latMs = (int)round((microtime(true) - $t0) * 1000);
    if ($hit) {
        $ruleId = (string)$hit['id'];
        $ruleReply = $hit['reply'] . ($cfgAR['sign'] !== '' ? "\n" . $cfgAR['sign'] : '');
    }
    $finalReply = $aiOk ? $aiText : $ruleReply;
    $source = $aiOk ? 'ai' : ($hit ? 'rule' : 'none');
    echo json_encode([
        'ok' => true,
        'order' => $order,
        'source' => $source,
        'reply' => $finalReply,
        'ai_ok' => $aiOk,
        'ai_error' => $aiErr,
        'model' => $modelUsed,
        'rule' => $ruleId,
        'latency_ms' => $latMs,
        'matched_rules' => array_values(array_filter(array_map(function ($r) use ($txt) {
            return ['id' => $r['id'] ?? '', 'reply' => $r['reply'] ?? ''];
        }, $rules), function ($x) use ($txt) {
            return $x['reply'] !== '';
        })),
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['ar_run'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(180);
    $cnAR = loadConnections();
    $dryAR = !empty($_GET['dry']);
    // ?now=1 یعنی مهلت ادب را نادیده بگیر — برای وقتی کاربر دستی اجرا می‌کند
    $resAR = autoReplyRun($cnAR, $dryAR, !empty($_GET['now']));
    if (!$dryAR && !empty($resAR['ok']) && (int)$resAR['replied'] > 0 && arCfg($cnAR)['notify']) {
        $resAR['delivery'] = notifSend($cnAR, arMsg($resAR));
    }
    echo json_encode($resAR, JSON_UNESCAPED_UNICODE);
    exit;
}

/** v8.49: نتیجهٔ کامل آخرین مغایرت‌گیری */

/**
 * v10.108: صف‌کردن دستی «در مقصد نیست»
 * ?recon_enqueue=1&target=woo|bsl
 * اختیاری: body/POST missing=json  یا از آخرین recon_result.json
 */
if (isset($_GET['recon_enqueue'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $target = (string)($_GET['target'] ?? '');
    if ($target !== 'woo' && $target !== 'bsl') {
        echo json_encode(['ok' => false, 'error' => 'مقصد نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    $cn = loadConnections();
    $missing = [];
    $raw = (string)($_POST['missing'] ?? $_GET['missing'] ?? '');
    if ($raw !== '') {
        $d = json_decode($raw, true);
        if (is_array($d)) $missing = $d;
    }
    if (!$missing && is_file(__DIR__ . '/recon_result.json')) {
        $rr = json_decode((string)@file_get_contents(__DIR__ . '/recon_result.json'), true);
        if (is_array($rr) && (string)($rr['target'] ?? '') === $target) {
            $missing = is_array($rr['missing'] ?? null) ? $rr['missing'] : [];
        } elseif (is_array($rr) && empty($rr['target']) && $target === 'bsl') {
            $missing = is_array($rr['missing'] ?? null) ? $rr['missing'] : [];
        }
    }
    if (!$missing) {
        echo json_encode(['ok' => false, 'error' => 'لیست «در مقصد نیست» خالی است — اول مغایرت‌گیری کنید'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $max = max(1, min(5000, (int)($_GET['max'] ?? $_POST['max'] ?? 2000)));
    $res = reconEnqueueMissingProducts($cn, $target, $missing, [
        'max' => $max,
        'vendor_id' => (int)($_GET['vendor_id'] ?? 0),
    ]);
    echo json_encode($res, JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['recon_result'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $f = __DIR__ . '/recon_result.json';
    if (!is_file($f)) { echo json_encode(['ok' => false, 'error' => 'نتیجه‌ای نیست'], JSON_UNESCAPED_UNICODE); exit; }
    echo (string)@file_get_contents($f);
    exit;
}

/**
 * v8.48: مدیریت حافظهٔ یادگیری دسته‌بندی.
 * ?catlearn=1                 → فهرست آموخته‌ها
 * &forget=<کلمه>              → فراموش کردن یک کلمه
 * &clear=1                    → پاک کردن همه
 * &test=<عنوان>               → ببین برای این عنوان چه پیشنهاد می‌دهد
 */
/**
 * v8.61: عیب‌یابی اتصال هوش مصنوعی.
 * ?ai_probe=1  → همهٔ روش‌های عبور را یکی‌یکی امتحان می‌کند و می‌گوید
 *                کدام روی این سرور جواب می‌دهد.
 * هیچ چیزی ذخیره نمی‌شود؛ فقط گزارش می‌دهد.
 */
/* v9.00: آزمایش اتصال به سایت مبدأ با تنظیمات فعلی.
   می‌گوید صفحهٔ فهرست و یک صفحهٔ محصول از روی سرور باز می‌شوند یا نه —
   چون همین دو تا هستند که استخراج به آن‌ها نیاز دارد. */
/* v10.177: آزمایش صفحه‌بندی — وقتی «به صفحهٔ بعد نمی‌رود» علت را از خودِ سرور می‌گوید.
   سه‌گانهٔ کلاسیک: چالشِ ضدربات (آروان/ک‌لادفلر = 200 با HTML بی‌کارت)،
   ریدایرکت/نادیده‌گرفتنِ نشانه (همان صفحهٔ ۱ برمی‌گردد)، یا الگوی ناسازگار (4xx). */
if (isset($_GET['pag_probe'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $u = s4NormalizeInputUrl((string)($_GET['url'] ?? ''));
    if ($u === '' || !filter_var($u, FILTER_VALIDATE_URL)) {
        echo json_encode(['ok' => false, 'diagnosis' => 'آدرس نامعتبر است.'], JSON_UNESCAPED_UNICODE); exit;
    }
    $pt = (string)($_GET['pagType'] ?? 'query_page');
    $pv = trim((string)($_GET['pagVal'] ?? ''));
    $built2 = ($pt === 'next_selector') ? '' : build_page_url_custom($u, $u, 2, $pt, $pv);
    $sel = [];
    if (!empty($_GET['selectors'])) {
        $__tmp = json_decode((string)$_GET['selectors'], true);
        if (is_array($__tmp)) $sel = $__tmp;
    }
    $probeEngine = normalizeExtractionEngine((string)($_GET['extractionEngine'] ?? (!empty($sel['container']) ? 'selectors' : 'heuristic')));
    $pagProbeFetch = function (string $link) use ($sel, $probeEngine): array {
        $r = fetch_html_for_engine($link, 25, $probeEngine, $sel);
        $html = (string)($r['html'] ?? '');
        $prods = [];
        $samples = [];
        if (!empty($r['ok']) && $html !== '') {
            $_probeUsed = '';
            $prods = parse_list_by_engine($html, (string)($r['url'] ?? $link), $sel, $probeEngine, $_probeUsed);
            foreach ($prods as $p) {
                if (count($samples) >= 3) break;
                $samples[] = mb_substr((string)($p['title'] ?? $p['link'] ?? ''), 0, 60);
            }
        }
        /* <title> صفحه — می‌فهمیم سندِ متفاوت آیا اصلاً آمده */
        $title = '';
        if ($html !== '' && preg_match('~<title[^>]*>(.*?)</title>~is', $html, $tm)) {
            $title = trim((string)preg_replace('~\s+~u', ' ', html_entity_decode($tm[1], ENT_QUOTES | ENT_HTML5, 'UTF-8')));
            $title = mb_substr($title, 0, 80);
        }
        return ['r' => $r, 'keys' => array_keys($prods), 'html' => $html,
                'samples' => $samples, 'title' => $title];
    };
    /* v10.179: «کارتِ واقعاً صفحه‌بندی‌شونده» را پیدا کن — برای وقتی‌که کارت‌های
       گرفته‌شده روی همهٔ صفحات یکی‌اند (بلاکِ ثابتِ بالای صفحه، مشکلِ واقعیِ
       ایمالز: نوارِ ۴۰تاییِ پیشنهادها که روی همهٔ صفحات تکرار می‌شود). لینک‌ها
       را بر اساس امضای جدِ تکرارشونده دسته می‌کنیم و آن‌هایی را امتیاز می‌دهیم
       که روی صفحهٔ ۲ تازه‌اند. */
    $pagProbeCandidates = function (string $hA, string $hB): array {
        $collect = function (string $h): array {
            $out = [];
            if ($h === '') return $out;
            [,$xp] = load_dom($h);
            if (!$xp) return $out;
            $nodes = @$xp->query('//a[@href]');
            if (!$nodes) return $out;
            foreach ($nodes as $a) {
                $href = (string)$a->getAttribute('href');
                if ($href === '' || strlen($href) > 400) continue;
                $anc = $a;
                $sig = '';
                for ($i = 0; $i < 4 && $anc; $i++) {
                    $anc = $anc->parentNode;
                    if (!$anc || !($anc instanceof DOMElement)) break;
                    $t = strtolower($anc->tagName);
                    if (in_array($t, ['li', 'article', 'section', 'div'], true)) {
                        $cls = preg_split('~\s+~', trim((string)$anc->getAttribute('class')) ?: '');
                        $sig = $t . (!empty($cls[0]) ? ('.' . $cls[0]) : '');
                        break;
                    }
                }
                if ($sig === '') continue;
                $out[$sig][md5($href)] = 1;
            }
            return $out;
        };
        $A = $collect($hA); $B = $collect($hB);
        $cands = [];
        foreach ($B as $sig => $hrefsB) {
            $totalB = count($hrefsB);
            if ($totalB < 4) continue;
            $hrefA = $A[$sig] ?? [];
            $newB = count(array_diff_key($hrefsB, $hrefA));
            if ($newB < 1) continue;
            $cands[] = ['sig' => $sig, 'on_page2' => $totalB, 'new_on_page2' => $newB];
        }
        usort($cands, function ($x, $y) { return $y['new_on_page2'] <=> $x['new_on_page2']; });
        return array_slice($cands, 0, 3);
    };
    $p1 = $pagProbeFetch($u);
    $p2 = ($built2 !== '' && $built2 !== $u) ? $pagProbeFetch($built2) : null;
    $r1 = $p1['r']; $n1 = count($p1['keys']);
    $rc = renderCfg();
    $out = [
        'ok' => false, 'built_url' => $built2,
        'page1_products' => $n1, 'engine' => $probeEngine, 'render_enabled' => !empty($rc['enabled']),
    ];
    if (empty($r1['ok'])) {
        $out['diagnosis'] = 'حتی صفحهٔ ۱ باز نشد: ' . (string)($r1['error'] ?? ('HTTP ' . (int)($r1['code'] ?? 0)));
        echo json_encode($out, JSON_UNESCAPED_UNICODE); exit;
    }
    if ($p2 === null) {
        $out['diagnosis'] = 'برای حالتِ «' . $pt . '» نشانیِ صفحهٔ ۲ ثابت ساخته نمی‌شود — این آزمون برای الگوهای مسیر/پارامتر است.';
        echo json_encode($out, JSON_UNESCAPED_UNICODE); exit;
    }
    $r2 = $p2['r']; $n2 = count($p2['keys']);
    $new2 = count(array_diff($p2['keys'], $p1['keys']));
    $out += [
        'final_url' => (string)($r2['url'] ?? ''),
        'code'      => (int)($r2['code'] ?? 0),
        'bytes'     => strlen((string)($r2['html'] ?? '')),
        'page2_products' => $n2, 'new_in_page2' => $new2,
    ];
    $finalTrim = rtrim((string)($r2['url'] ?? ''), '/');
    $builtTrim = rtrim($built2, '/');
    $baseTrim  = rtrim($u, '/');
    $bouncedTo1 = !empty($r2['ok']) && $finalTrim !== '' && $finalTrim !== $builtTrim
        && strcasecmp($finalTrim, $baseTrim) === 0;
    if (empty($r2['ok'])) {
        $c = (int)($r2['code'] ?? 0);
        if ($c === 404 || $c === 400) {
            $out['diagnosis'] = 'صفحهٔ ۲ → HTTP ' . $c . ': الگوی صفحه‌بندی با این سایت نمی‌خورد. نشانیِ امتحان‌شده را در مرورگر باز کنید و با نشانیِ واقعیِ «صفحهٔ ۲» مقایسه کنید و الگو را اصلاح کنید.';
        } elseif ($c === 401 || $c === 403 || $c === 429) {
            $out['diagnosis'] = 'صفحهٔ ۲ → HTTP ' . $c . ': سرور درخواستِ دومِ متوالی را محدود/بلاک کرد. «فاصلهٔ بین درخواست‌ها» (src_net) را چند ثانیه بالا ببرید یا سرویس رندر/پروکسی را برای این دامنه فعال کنید.';
        } else {
            $out['diagnosis'] = 'صفحهٔ ۲ باز نشد: ' . (string)($r2['error'] ?? ('HTTP ' . $c));
        }
    } elseif ($bouncedTo1) {
        /* v10.178: ریدایرکت به صفحهٔ ۱ — الگوی فعلی از نگاه سرور بی‌معنی است
           (موردِ واقعیِ ایمالز: ?page=N به نشانیِ canonical برمی‌گردد). */
        $out['diagnosis'] = 'سرور نشانیِ صفحهٔ ۲ را گرفت و به «نشانیِ صفحهٔ ۱» ریدایرکت کرد — یعنی روش/الگوی فعلیِ صفحه‌بندی (' . $pt . ' = ' . ($pv !== '' ? $pv : '(پیش‌فرض)') . ') از نگاهِ این سایت معتبر نیست. «الگوی مسیر» را انتخاب کنید و مقدار را دقیقاً همان تکه‌ای بگذارید که در نشانیِ صفحهٔ ۲ی مرورگر دیده می‌شود — برای ایمالز: ~page~{page}';
    } elseif ($new2 > 0) {
        $out['ok'] = true;
        $out['diagnosis'] = 'الگو درست است! صفحهٔ ۲ با ' . $new2 . ' محصولِ تازه جواب داد (صفحهٔ ۱: ' . $n1 . '). اگر استخراجِ واقعی هنوز توقف می‌کند، پروفایل را یک‌بار کامل ذخیره و دوباره اجرا کنید تا تنظیمِ تازه خوانده شود.';
    } elseif ($n2 > 0 && $new2 === 0) {
        /* v10.179: دو تشخیص متفاوت که قبلاً یکی شمرده می‌شدند:
           الف) سندِ صفحهٔ ۲ متفاوت آمده ولی کارتِ سلکتور ثابت است → سلکتور روی
              بلاکِ ثابتِ بالای صفحه (نوارِ پیشنهادها/برترین‌ها) است، نه گریدِ
              صفحه‌بندی‌شونده — با نامزدهای کارتِ درست راهنما می‌شویم.
           ب) سندها یکی‌اند → سرور واقعاً نشانه را نادیده گرفته. */
        $h1 = (string)$p1['html']; $h2 = (string)$p2['html'];
        $sameDoc = ($h1 !== '' && $h1 === $h2);
        $cands = $pagProbeCandidates($h1, $h2);
        $out['samples_page1'] = $p1['samples']; $out['samples_page2'] = $p2['samples'];
        $out['title_page1'] = $p1['title']; $out['title_page2'] = $p2['title'];
        $out['candidates'] = $cands;
        if (!$sameDoc) {
            $out['diagnosis'] = 'سندِ صفحهٔ ۲ واقعاً متفاوت است ولی سلکتورِ فعلی همان بلاکِ ثابتِ بالای صفحه (نوارِ پیشنهادها/برترین فروشگاه‌ها) را می‌گیرد، نه گریدِ صفحه‌بندی‌شونده را. سلکتورِ ظرف را روی کارت‌های گرید (نوعِ نامزدها را پایین همین جعبه ببینید) تنظیم کنید و دوباره امتحان کنید.';
            if (!empty($cands)) {
                $sugs = [];
                foreach ($cands as $c) { $sugs[] = $c['sig'] . ' (' . $c['on_page2'] . ' کارت · ' . $c['new_on_page2'] . ' کارتِ تازه)'; }
                $out['diagnosis'] .= ' نامزدهای گرید: ' . implode(' | ', $sugs);
            }
        } else {
            $out['diagnosis'] = 'صفحهٔ ۲ ' . $n2 . ' کارت داشت ولی همه با صفحهٔ ۱ یکی بودند — یعنی سرور نشانهٔ صفحه را نادیده می‌گیرد (ریدایرکت به صفحهٔ اول؟). «نشانی نهایی» را با نشانیِ ساخته‌شده مقایسه کنید؛ اگر متفاوت است سرعت/روش واکشیِ دامنه (src_net) را بررسی کنید.';
        }
    } else {
        $h2 = (string)($r2['html'] ?? '');
        if (looks_like_js_shell($h2)) {
            $out['diagnosis'] = 'صفحهٔ ۲ «پوستهٔ JS» است — سرویس رندر (تنظیمات ← رندر جاوااسکریپت) را فعال و سالم نگه‌دارید تا این دامنه رندر شود.';
        } elseif (preg_match('~(آروان|arvancloud|__arc|cf-chl|__cf_chl|checking your browser|ddos-guard|کمی صبر|لطفاً? (چند لحظه )?(صبر|منتظر))~iu', $h2)) {
            $out['diagnosis'] = 'صفحهٔ ۲ یک «چالش ضدربات» (آروان/کلادفلر) است — مرورگرِ واقعی لازم است: سرویس رندر را فعال کنید، یا فاصلهٔ درخواست‌ها را در تنظیمات عبور (src_net) بالا ببرید و دوباره امتحان کنید.';
        } else {
            $out['diagnosis'] = 'در صفحهٔ ۲ هیچ کارتی شناخته نشد (بایت: ' . $out['bytes'] . '). سلکتور ظرف را بازبینی کنید یا این می‌تواند یعنی پایانِ واقعیِ فهرست/تغییر قالب روی صفحهٔ ۲.';
        }
    }
    echo json_encode($out, JSON_UNESCAPED_UNICODE); exit;
}

/* v10.182: تست سه‌صفحه‌ای همهٔ موتورهای PHP-native روی پروفایل جاری.
   این همان ایدهٔ benchmark پروژهٔ Node است، با این تفاوت که اینجا فقط موتورهایی
   اجرا می‌شوند که داخل همین تک‌فایل PHP و بدون وابستگی Node/Python قابل اجرا هستند. */
if (isset($_GET['engine_benchmark'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(0); @ignore_user_abort(true);
    $u = s4NormalizeInputUrl((string)($_POST['url'] ?? $_GET['url'] ?? ''));
    if ($u === '' || !filter_var($u, FILTER_VALIDATE_URL)) {
        echo json_encode(['ok' => false, 'error' => 'آدرس پروفایل نامعتبر است.'], JSON_UNESCAPED_UNICODE); exit;
    }
    $pt = (string)($_POST['pagType'] ?? $_GET['pagType'] ?? 'query_page');
    $pv = trim((string)($_POST['pagVal'] ?? $_GET['pagVal'] ?? ''));
    $benchPages = 3;
    $sel = [];
    if (isset($_POST['selectors'])) {
        $__tmp = json_decode((string)$_POST['selectors'], true);
        if (is_array($__tmp)) $sel = $__tmp;
    } elseif (!empty($_GET['selectors'])) {
        $__tmp = json_decode((string)$_GET['selectors'], true);
        if (is_array($__tmp)) $sel = $__tmp;
    }
    $engines = extractionEngineAllowed();
    $results = [];
    $startedAll = microtime(true);
    foreach ($engines as $engine) {
        $rowStart = microtime(true);
        $errors = [];
        $seen = [];
        $usedLayers = [];
        $pageRows = [];
        $totalParsed = 0;
        $unique = 0;
        $nextUrl = null;
        if ($engine === 'selectors' && empty($sel['container'])) {
            $results[] = [
                'engine' => $engine, 'label' => extractionEngineLabel($engine), 'ok' => false,
                'pages_scanned' => 0, 'products_total' => 0, 'products_unique' => 0,
                'products_duplicate' => 0,
                'elapsed_ms' => 0, 'products_per_minute' => 0,
                'errors' => ['برای موتور CSS selectors، سلکتور container لازم است.'],
                'pages' => [], 'used_layers' => [], 'hint' => 'اگر می‌خواهید بدون سلکتور تست کنید، موتور Structural/heuristic یا Auto smart را ببینید.'
            ];
            continue;
        }
        for ($page = 1; $page <= $benchPages; $page++) {
            if ($page === 1) $pageUrl = $u;
            elseif ($pt === 'next_selector' && $nextUrl) $pageUrl = $nextUrl;
            elseif ($pt === 'next_selector' && !$nextUrl) { $errors[] = 'صفحهٔ بعد پیدا نشد (next_selector).'; break; }
            else $pageUrl = build_page_url_custom($u, $u, $page, $pt, $pv);

            $fetchStart = microtime(true);
            $res = fetch_html_for_engine($pageUrl, 20, $engine, $sel);
            $fetchMs = (int)round((microtime(true) - $fetchStart) * 1000);
            $html = (string)($res['html'] ?? '');
            $parseStart = microtime(true);
            $used = '';
            $products = !empty($res['ok']) ? parse_list_by_engine($html, (string)($res['url'] ?? $pageUrl), $sel, $engine, $used) : [];
            $parseMs = (int)round((microtime(true) - $parseStart) * 1000);
            if ($used !== '') $usedLayers[$used] = true;
            $new = 0;
            $sample = [];
            foreach ($products as $k => $p) {
                $totalParsed++;
                if (count($sample) < 3) {
                    $sample[] = [
                        'title' => (string)($p['title'] ?? ''),
                        'link'  => (string)($p['link'] ?? ''),
                        'price' => (string)($p['price'] ?? ''),
                    ];
                }
                if (isset($seen[$k])) continue;
                $seen[$k] = true; $new++;
            }
            $unique = count($seen);
            $perr = '';
            if (empty($res['ok'])) {
                $perr = (string)($res['error'] ?? ('HTTP ' . (int)($res['code'] ?? 0)));
                $errors[] = 'page ' . $page . ': ' . $perr;
            }
            $pageRows[] = [
                'page' => $page, 'ok' => !empty($res['ok']), 'code' => (int)($res['code'] ?? 0),
                'url' => $pageUrl, 'final_url' => (string)($res['url'] ?? ''),
                'bytes' => strlen($html), 'products' => count($products), 'new' => $new,
                'used_engine' => $used, 'fetch_ms' => $fetchMs, 'parse_ms' => $parseMs,
                'sample' => $sample,
                'error' => $perr,
            ];
            if ($pt === 'next_selector' && !empty($pv) && !empty($res['ok'])) {
                [$dom, $xp] = load_dom($html);
                $xpath = cssToXpath($pv);
                $nodes = $xpath ? @$xp->query($xpath) : null;
                if ($nodes && $nodes->length && $nodes->item(0) instanceof DOMElement) {
                    $href = $nodes->item(0)->getAttribute('href');
                    $nextUrl = ($href && $href !== '#' && !preg_match('~^(javascript:|data:)~i', $href))
                        ? make_absolute_url($href, (string)($res['url'] ?? $pageUrl)) : null;
                } else $nextUrl = null;
            }
        }
        $elapsedMs = (int)round((microtime(true) - $rowStart) * 1000);
        $duplicates = max(0, $totalParsed - $unique);
        $ppm = $elapsedMs > 0 ? (int)round(($unique * 60000) / max(1, $elapsedMs)) : 0;
        $results[] = [
            'engine' => $engine, 'label' => extractionEngineLabel($engine),
            'ok' => $unique > 0 && count($errors) === 0,
            'pages_scanned' => count($pageRows), 'products_total' => $totalParsed,
            'products_unique' => $unique, 'products_duplicate' => $duplicates,
            'elapsed_ms' => $elapsedMs,
            'products_per_minute' => $ppm, 'errors' => $errors,
            'pages' => $pageRows, 'used_layers' => array_keys($usedLayers),
            'hint' => $unique > 0 ? ($totalParsed > $unique ? 'بعضی محصولات بین صفحات تکراری بودند؛ unique معیار بهتر است.' : 'محصول یکتا پیدا شد.') : 'این موتور روی سه صفحهٔ اول محصولی پیدا نکرد.',
        ];
    }
    $fastest = null;
    foreach ($results as $r) {
        if (($r['products_unique'] ?? 0) <= 0) continue;
        if ($fastest === null || (int)$r['products_per_minute'] > (int)$fastest['products_per_minute']) $fastest = $r;
    }
    echo json_encode([
        'ok' => true, 'url' => $u, 'pages_target' => $benchPages,
        'took_ms' => (int)round((microtime(true) - $startedAll) * 1000),
        'results' => $results,
        'fastest' => $fastest ? ['engine' => $fastest['engine'], 'label' => $fastest['label'], 'products_per_minute' => $fastest['products_per_minute'], 'products_unique' => $fastest['products_unique']] : null,
    ], JSON_UNESCAPED_UNICODE); exit;
}

/* v10.201: پروب تک‌صفحه‌ای مستقیمِ رندر مرورگری؛ برای حلقهٔ فیدبک سایت‌هایی
   مثل SnappShop که benchmark چندصفحه‌ای ممکن است از سقف اتصال عبور کند. */
if (isset($_GET['render_page_probe'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(90);
    $u = s4NormalizeInputUrl((string)($_GET['url'] ?? ''));
    if ($u === '' || !filter_var($u, FILTER_VALIDATE_URL)) {
        echo json_encode(['ok'=>false,'error'=>'آدرس نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    $driver = strtolower((string)($_GET['driver'] ?? 'playwright'));
    if (!in_array($driver, ['playwright','selenium'], true)) $driver = 'playwright';
    $rc = renderCfg();
    $rc['timeout_ms'] = max(5000, min(30000, (int)($_GET['timeout_ms'] ?? 15000)));
    $opts = ['driver'=>$driver, 'wait_until'=>(string)($_GET['wait_until'] ?? 'domcontentloaded'), 'scroll'=>!empty($_GET['scroll'])];
    $t0 = microtime(true);
    $r = fetch_html_render($u, $rc, $opts);
    if (empty($r['ok']) && function_exists('isSnappshopUrl') && isSnappshopUrl($u) && function_exists('fetch_html_snappshop_public_fallback')) {
        $renderErr = (string)($r['error'] ?? '');
        $pf = fetch_html_snappshop_public_fallback($u, 20, is_array($r) ? $r : []);
        if (!empty($pf['ok'])) { $r = $pf; $r['render_error'] = $renderErr; }
    }
    $html = (string)($r['html'] ?? '');
    $title = '';
    if ($html !== '' && preg_match('~<title[^>]*>(.*?)</title>~isu', $html, $tm)) $title = normalize_text(strip_tags($tm[1]));
    $usedAuto=''; $usedHeu=''; $usedJson='';
    $auto = !empty($r['ok']) ? parse_list_by_engine($html, (string)($r['url'] ?? $u), [], 'auto', $usedAuto) : [];
    $heu  = !empty($r['ok']) ? parse_list_by_engine($html, (string)($r['url'] ?? $u), [], 'heuristic', $usedHeu) : [];
    $json = !empty($r['ok']) ? parse_list_by_engine($html, (string)($r['url'] ?? $u), [], 'jsonld', $usedJson) : [];
    $brief = function(array $rows): array {
        $out = [];
        foreach ($rows as $p) {
            $out[] = ['title'=>mb_substr((string)($p['title'] ?? ''),0,100), 'price'=>mb_substr((string)($p['price'] ?? ''),0,50), 'link'=>mb_substr((string)($p['link'] ?? ''),0,180)];
            if (count($out) >= 5) break;
        }
        return $out;
    };
    $blocked = false;
    if ($html !== '' && preg_match('~(Access Denied|403 Forbidden|turn off VPN|خاموش.*vpn|آروان|captcha|cloudflare|ddos-guard|429)~iu', $html)) $blocked = true;
    echo json_encode([
        'ok'=>!empty($r['ok']), 'driver'=>$driver, 'render_driver'=>(string)($r['driver'] ?? ''),
        'code'=>(int)($r['code'] ?? 0), 'final_url'=>(string)($r['url'] ?? $u),
        'ms'=>(int)round((microtime(true)-$t0)*1000), 'render_ms'=>(int)($r['took_ms'] ?? 0),
        'bytes'=>strlen($html), 'title'=>mb_substr($title,0,180), 'blocked_hint'=>$blocked,
        'error'=>(string)($r['error'] ?? ''), 'render_error'=>(string)($r['render_error'] ?? ''), 'mode'=>(string)($r['mode'] ?? ''),
        'counts'=>['auto'=>count($auto), 'heuristic'=>count($heu), 'jsonld'=>count($json)],
        'used'=>['auto'=>$usedAuto, 'heuristic'=>$usedHeu, 'jsonld'=>$usedJson],
        'samples'=>['auto'=>$brief($auto), 'heuristic'=>$brief($heu), 'jsonld'=>$brief($json)],
        'text_sample'=>mb_substr(normalize_text(strip_tags(preg_replace('~<(script|style|noscript|template)[^>]*>.*?</\1>~isu',' ',$html))),0,500),
    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); exit;
}

/* v10.174: آزمون اتصال به سرویس رندر (browser/) — مانند src_probe ولی به
   اندپوینتِ /health خودِ سرویس نه به یک صفحهٔ وب. */
if (isset($_GET['render_probe'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $rc = renderCfg();
    $out = ['ok' => false, 'enabled' => !empty($rc['enabled']), 'url' => (string)($rc['url'] ?? '')];
    $renderDisabledNote = empty($rc['enabled']) ? 'رندر خودکار در تنظیمات خاموش است؛ اما موتورهای Playwright/Selenium هنگام انتخاب شدن همین سرویس را اجباری صدا می‌زنند. ' : '';
    if ((string)$rc['url'] === '' || !preg_match('~^https?://~i', (string)$rc['url'])) {
        $out['diagnosis'] = 'آدرس سرویس رندر تنظیم نشده است (پیش‌فرض: http://127.0.0.1:3100).';
        echo json_encode($out, JSON_UNESCAPED_UNICODE); exit;
    }
    $t0 = microtime(true);
    $hc = function_exists('fetch_html_render_health') ? fetch_html_render_health($rc) : ['ok' => false, 'error' => 'fn missing'];
    $wantsLaunch = isset($_GET['launch']) || isset($_GET['start']);
    $forceLaunch = isset($_GET['force']) || isset($_GET['repair']) || isset($_GET['bootstrap']);
    $drvUnavailable = !empty($hc['ok']) && ((string)($hc['driver'] ?? '') === 'unavailable'
        || (is_array($hc['available'] ?? null) && empty($hc['available']['cdp']) && empty($hc['available']['selenium'])));
    if ($wantsLaunch && (empty($hc['ok']) || ($forceLaunch && $drvUnavailable))) {
        $out['launch'] = s4LaunchRenderService($rc, $forceLaunch);
        usleep(700000);
        $hc = function_exists('fetch_html_render_health') ? fetch_html_render_health($rc) : $hc;
    }
    $out['ms'] = (int)round((microtime(true) - $t0) * 1000);
    $out = array_merge($out, $hc);
    if (isset($_GET['log']) || isset($_GET['tail'])) {
        $out['log_tail'] = s4RenderLogTail((int)($_GET['lines'] ?? 100));
    }
    if (empty($out['ok'])) {
        $launchHint = (isset($_GET['launch']) || isset($_GET['start'])) ? '' : ' برای راه‌اندازی محدود از همین عیب‌یاب، launch=1 را هم بفرستید.';
        $out['diagnosis'] = $renderDisabledNote . 'به سرویس رندر وصل نشد — سرویس browser-php/start.sh باید روی 127.0.0.1:3100 بالا باشد.' . $launchHint
                          . ' خطا: ' . mb_substr((string)($out['error'] ?? ''), 0, 120);
    } else {
        $avail = is_array($out['available'] ?? null) ? $out['available'] : [];
        $drvNote = (!empty($avail) && empty($avail['cdp']) && empty($avail['selenium'])) ? ' ولی هیچ مرورگر/درایوری پیدا نشده؛ bootstrap مرورگر لازم است.' : '';
        $out['diagnosis'] = $renderDisabledNote . 'سرویس رندر سالم است' . $drvNote . '؛ در حالتِ خودکار فقط صفحه‌های «پوستهٔ JS» رندر می‌شوند.';
    }
    echo json_encode($out, JSON_UNESCAPED_UNICODE); exit;
}

if (isset($_GET['src_probe'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $u = s4NormalizeInputUrl((string)($_GET['url'] ?? ''));
    if ($u === '' || !filter_var($u, FILTER_VALIDATE_URL)) {
        echo json_encode(['ok' => false, 'error' => 'آدرس نامعتبر'], JSON_UNESCAPED_UNICODE); exit;
    }
    $net = srcNetCfg();
    $host = strtolower((string)parse_url($u, PHP_URL_HOST));
    $t0 = microtime(true);
    $r = fetch_html($u, 30);
    $ms = (int)round((microtime(true) - $t0) * 1000);
    $out = ['ok' => !empty($r['ok']), 'code' => (int)($r['code'] ?? 0),
            'ms' => $ms, 'host' => $host,
            'mode' => $net['mode'], 'applies' => srcNetApplies($net, $host),
            'gap_ms' => (int)$net['gap_ms'],
            'error' => (string)($r['error'] ?? ''),
            'bytes' => strlen((string)($r['html'] ?? ''))];
    $code = (int)($r['code'] ?? 0);
    if ($code === 403 || $code === 429) {
        $out['diagnosis'] = 'سایت مبدأ درخواست سرور را رد کرد (' . $code . ') — یعنی IP هاست بلاک یا محدود شده. '
                          . 'تغییر DNS اینجا فایده ندارد؛ فاصلهٔ بین درخواست‌ها را زیاد کنید یا پروکسی بگذارید.';
    } elseif (!empty($r['ok'])) {
        $out['diagnosis'] = 'اتصال سالم است — صفحه در ' . $ms . ' میلی‌ثانیه گرفته شد.';
    } elseif (stripos((string)$r['error'], 'resolve') !== false) {
        $out['diagnosis'] = 'نام دامنه از روی سرور پیدا نشد — اینجا DoH یا IP دستی کمک می‌کند.';
    } else {
        $out['diagnosis'] = 'اتصال برقرار نشد: ' . (string)$r['error'];
    }
    echo json_encode($out, JSON_UNESCAPED_UNICODE); exit;
}

if (isset($_GET['ai_probe'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(120);
    $cn  = loadConnections();
    $ai  = $cn['ai'] ?? [];
    $net = aiNetCfg($cn);
    // اجازهٔ آزمایش مقادیر واردشده در فرم، بدون ذخیره
    foreach (['mode','resolve_ip','doh_url','worker_url','proxy','proxy_type','proxy_auth'] as $k) {
        if (isset($_GET['net_' . $k])) $net[$k] = trim((string)$_GET['net_' . $k]);
    }
    /* v9.27: از «ارائه‌دهندهٔ فعال» آدرس واقعی و کلید/مدل را بگیر.
       تا ۹.۲۶ این بخش به فیلدهای تک-AI قدیمی (base_url) وابسته بود که در
       بازنویسی چند-ارائه‌دهنده حذف شدند — برای همین host خالی می‌آمد و
       عیب‌یابی همیشه «میزبان خالی» می‌گفت. حالا از خودِ ارائه‌دهندهٔ فعال
       و مدلِ فعال استفاده می‌شود. */
    $probeUrl = '';
    $apiKey   = '';
    $model    = '';
    $provId   = '';
    $provName = '';
    $_ac = aiActiveConfig();
    if (!empty($_ac['provider'])) {
        $provId   = (string)($_ac['provider']['id'] ?? '');
        $provName = (string)($_ac['provider']['name'] ?? $provId);
        /* v10.01: عیب‌یابی هم با «کلیدِ سالم» انجام شود، نه با کلیدی که
           اعتبارش تمام شده — وگرنه گزارش، خطای اعتبار را به‌جای خطای شبکه
           نشان می‌دهد. */
        $_pk      = aiPickApiKey($_ac['provider'], $provId);
        $apiKey   = trim((string)($_pk['key'] ?? ''));
        if ($apiKey === '') $apiKey = trim((string)($_ac['provider']['apiKey'] ?? ''));
        $model    = (string)($_ac['model'] ?? '');
        $ep = aiProviderEndpoint($_ac['provider'], $model);
        // برای تستِ عیب‌یابی، آدرس chat/completions را می‌سنجیم
        $probeUrl = (string)($ep['url'] ?? '');
        // Cloudflare آدرس مستقیم مدل می‌دهد؛ برای هاست هم همان را بگیر
        if ($probeUrl === '') $probeUrl = (string)($_ac['provider']['url'] ?? '');
    }
    // سازگاری: اگر ارائه‌دهنده‌ای نیست، به مقادیر قدیمی برگرد
    if ($probeUrl === '') {
        $baseUrl0 = trim((string)($_GET['base_url'] ?? ($ai['base_url'] ?? 'https://dashscope.aliyuncs.com/compatible-mode/v1')));
        $probeUrl = rtrim($baseUrl0, '/') . '/chat/completions';
        $apiKey   = $apiKey !== '' ? $apiKey : trim((string)($ai['api_key'] ?? ''));
        $model    = $model !== '' ? $model : trim((string)($ai['model'] ?? 'qwen-plus'));
    }
    $host = (string)(parse_url($probeUrl, PHP_URL_HOST) ?? '');
    $port = (int)(parse_url($probeUrl, PHP_URL_PORT) ?? (parse_url($probeUrl, PHP_URL_SCHEME) === 'https' ? 443 : 80));

    $out = ['ok' => true, 'host' => $host, 'port' => $port, 'base_url' => $probeUrl,
            'provider' => $provId, 'provider_name' => $provName, 'model' => $model,
            'has_key' => $apiKey !== '', 'steps' => [], 'modes' => []];

    // ۱) DNS محلی چه می‌گوید؟
    $t0 = microtime(true);
    $localIp = $host !== '' ? @gethostbyname($host) : '';
    $out['steps'][] = ['name' => 'DNS محلی سرور', 'ok' => ($localIp !== '' && $localIp !== $host),
        'detail' => ($localIp !== '' && $localIp !== $host) ? $localIp : 'پاسخ نداد',
        'ms' => (int)((microtime(true) - $t0) * 1000)];

    // ۲) DoH در دسترس است؟ (فقط حلِ DNS — هنوز به اندپوینت وصل نشده)
    $t0 = microtime(true);
    $doh = aiDohResolve($host !== '' ? $host : 'example.com', (string)$net['doh_url'], 10);
    $out['steps'][] = ['name' => 'DNS-over-HTTPS (' . parse_url((string)$net['doh_url'], PHP_URL_HOST) . ')',
        'ok' => !empty($doh['ok']), 'detail' => $doh['ok'] ? $doh['ip'] : ($doh['error'] ?? '?'),
        'ms' => (int)((microtime(true) - $t0) * 1000)];
    if (!empty($doh['ok']) && !empty($localIp) && $localIp !== $host && $localIp !== $doh['ip']) {
        $out['steps'][] = ['name' => '⚠️ DNS محلی با DoH فرق دارد', 'ok' => false,
            'detail' => 'محلی=' . $localIp . ' · واقعی=' . $doh['ip'] . ' — احتمال DNS آلوده'];
    }

    // ۳) هر روش را با یک درخواست واقعی بسنج
    $probeModes = ['direct', 'doh'];
    if ($net['resolve_ip'] !== '') $probeModes[] = 'dns';
    if ($net['worker_url'] !== '') $probeModes[] = 'worker';
    if ($net['proxy'] !== '')      $probeModes[] = 'proxy';

    $payload = ['model' => $model, 'max_tokens' => 5,
                'messages' => [['role' => 'user', 'content' => 'ping']]];
    $url = $probeUrl; // v9.27: از ارائه‌دهندهٔ فعال گرفته شد
    $headers = ['Content-Type: application/json', 'Authorization: Bearer ' . ($apiKey !== '' ? $apiKey : 'probe')];

    $working = [];
    foreach ($probeModes as $m) {
        $t0 = microtime(true);
        $r  = aiHttp($url, $headers, $payload, $net, $m);
        $ms = (int)((microtime(true) - $t0) * 1000);
        $code = (int)$r['code'];
        // 401 یعنی خودِ سرویس رسید ولی کلید غلط است؛ اما خطای Worker/پروکسیِ واسط «رسیدن به مقصد» نیست.
        $connNote = '';
        if ($m === 'doh' && $code === 0) {
            $connNote = ' ⚠️ DoH دامنه را حل کرد ولی اتصال به IP مقصد برقرار نشد — DNS سالم است ولی مسیر IP بسته است؛ پروکسی/Worker لازم است';
        }
        $emsg = aiHttpErrorMessage($r);
        $diag = aiTestNetworkFailure($r);
        $reached = $code > 0 && ($diag['cat'] ?? '') !== 'port' && !aiProxyLevelFailure($r, $m);
        $note = $code === 0 ? ('نرسید: ' . mb_substr($emsg, 0, 90) . $connNote)
              : ($code === 401 ? 'رسید ✓ (کلید نامعتبر یا خالی)'
              : ($code >= 200 && $code < 300 ? 'کامل ✓' : 'رسید ✓ (HTTP ' . $code . ($emsg !== '' ? ' — ' . mb_substr($emsg, 0, 90) : '') . ')'));
        if (($diag['cat'] ?? '') === 'port') $note = 'خطای پورت Worker/URL: ' . mb_substr($emsg, 0, 90) . ' — قالب Worker را اصلاح کنید یا DoH را بگذارید';
        if ($reached) $working[] = $m;
        $out['modes'][] = ['mode' => $m, 'reached' => $reached, 'http' => $code,
                           'ms' => $ms, 'note' => $note, 'via' => $r['via'] ?? $m,
                           'diag' => (string)($diag['cat'] ?? ''), 'worker_style' => (string)($r['worker_style'] ?? '')];
    }
    $out['working'] = $working;
    $out['recommended'] = $working[0] ?? '';
    $out['summary'] = empty($working)
        ? 'هیچ روشی به مقصد نرسید — Worker یا پروکسی لازم است (DoH فقط DNS را حل می‌کند، نه مسیر IP)'
        : ('روش‌های کارآمد: ' . implode(' · ', $working));
    echo json_encode($out, JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v10.218: endpoint حلقهٔ فیدبک برای رفع خطاهای فنی AI
 *
 *  ?ai_feedback_fix=1[&apply=1]
 *    ۱) روش‌های direct/doh/worker را با اندپوینت واقعیِ ارائه‌دهندهٔ فعال
 *       می‌سنجد و خطای پورت Worker را صریح تشخیص می‌دهد.
 *    ۲) اگر Worker خراب است ولی DoH/direct می‌رسد، در حالت apply روش امن را
 *       ذخیره می‌کند (rate-limit و credit را «رفع» حساب نمی‌کند).
 *    ۳) مدل‌های قرمزِ غیرِ credit/rate-limit را با تنظیم اصلاح‌شده دوباره
 *       تست می‌کند و فقط همان‌ها را به‌روز می‌کند.
 * ===================================================================== */
function aiNetPublic(array $n): array {
    if (isset($n['proxy_auth']) && $n['proxy_auth'] !== '') $n['proxy_auth'] = '***';
    return $n;
}

function aiFeedbackSkipReason(array $m): string {
    if (!empty($m['feedbackExcluded'])) return 'invalid';
    if(aiNonChatModel((string)($m['id']??''),$m)!=='')return 'nonchat';
    if (!empty($m['available'])) return 'available';
    $d = is_array($m['testDetails'] ?? null) ? (array)$m['testDetails'] : [];
    $code = (int)($d['status'] ?? 0);
    $kind = (string)($d['kind'] ?? '');
    $txt = strtolower((string)($d['error'] ?? '') . ' ' . (string)($d['note'] ?? '') . ' ' . (string)($d['raw'] ?? ''));
    if (!empty($m['billingIssue']) || strpos($kind, 'billing') === 0) return 'billing';
    $bill = aiBillingFailure(['code' => $code, 'raw' => $txt, 'body' => ['error' => ['message' => $txt]]]);
    if (!empty($bill['is'])) return 'billing';
    if (!empty($m['rateLimited']) || $code === 429 || strpos($txt, 'rate limit') !== false || strpos($txt, 'too many requests') !== false) return 'ratelimit';
    if (empty($m['tested']) && !$d) return 'untested';
    return '';
}

function aiFeedbackPermanentInvalid(array $m): bool {
    if(!empty($m['feedbackExcluded']))return true;
    $d=is_array($m['testDetails']??null)?$m['testDetails']:[];
    $kind=strtolower((string)($d['kind']??''));$code=(int)($d['status']??0);
    $txt=strtolower((string)($d['error']??'').' '.(string)($d['note']??'').' '.(string)($d['raw']??''));
    if($kind==='badmodel'||strpos($txt,'only supports interactions api')!==false
        ||strpos($txt,'does not support chat endpoints')!==false)return true;
    if(in_array($code,[400,404],true)&&(strpos($txt,'model')!==false)&&(
        strpos($txt,'not supported')!==false||strpos($txt,'no longer available')!==false
        ||strpos($txt,'model is unavailable')!==false||strpos($txt,'is currently unavailable')!==false
        ||strpos($txt,'invalid model')!==false||strpos($txt,'model not found')!==false))return true;
    return false;
}

function aiFeedbackExcludeInvalid(array &$m,string $reason=''): void {
    $m['feedbackExcluded']=true;$m['feedbackExcludedAt']=time();
    $m['feedbackExcludeReason']=$reason!==''?mb_substr($reason,0,300):'permanent_invalid_model';
    $m['available']=false;$m['rateLimited']=false;
}

function aiFeedbackProbeModes(array $net, string $url, string $apiKey, string $model, array $p = []): array {
    $modes = ['direct', 'doh'];
    if (!empty($net['resolve_ip'])) $modes[] = 'dns';
    if (!empty($net['worker_url'])) $modes[] = 'worker';
    if (!empty($net['proxy'])) $modes[] = 'proxy';
    $ep = $p ? aiProviderEndpoint($p, $model) : ['kind' => 'openai', 'url' => $url, 'model' => $model, 'dialect' => aiDetectProviderDialect($p, $url)];
    $headers = aiBuildProviderHeaders($p, $ep, $apiKey);
    $payload = aiBuildOpenAiPayload(['max_tokens' => 8, 'messages' => [['role' => 'user', 'content' => 'ping']]], $model, (string)($ep['dialect'] ?? ''), $p);
    $out = [];
    foreach ($modes as $m) {
        $t0 = microtime(true);
        $r = aiHttp($url, $headers, $payload, $net, $m);
        $diag = aiTestNetworkFailure($r);
        $msg = aiHttpErrorMessage($r);
        $code = (int)($r['code'] ?? 0);
        $proxyFailure = aiProxyLevelFailure($r, $m);
        $authStripped = ($apiKey !== '' && in_array($m, ['worker', 'proxy'], true)
            && ($code === 401 || ($code === 400 && aiIsMissingAuthHeaderError($r))));
        $geoBlocked = (in_array($m, ['direct', 'doh', 'dns'], true) && aiIsGeoOrEdgeBlock($r, $m));
        $out[$m] = [
            'mode' => $m,
            'reached' => ($code > 0 && ($diag['cat'] ?? '') !== 'port' && !$proxyFailure && !$authStripped && !$geoBlocked),
            'ok' => $code >= 200 && $code < 300,
            'http' => $code, 'diag' => (string)($diag['cat'] ?? ''),
            'label' => (string)($diag['label'] ?? ''), 'error' => mb_substr($msg, 0, 220),
            'via' => (string)($r['via'] ?? $m), 'worker_style' => (string)($r['worker_style'] ?? ''),
            'proxy_failure' => $proxyFailure,
            'auth_stripped' => $authStripped,
            'geo_blocked'   => $geoBlocked,
            'ms' => (int)round((microtime(true) - $t0) * 1000),
        ];
    }
    return $out;
}

function aiFeedbackBestMode(array $probe, array $net): array {
    $cur = (string)($net['mode'] ?? 'direct');
    $pick = $cur;
    $why = 'روش فعلی قابل استفاده است';
    if (isset($probe[$cur]) && !empty($probe[$cur]['ok'])) {
        return ['mode' => $pick, 'why' => $why, 'changed' => false];
    }
    foreach (['doh', 'direct', 'worker', 'dns', 'proxy'] as $m) {
        if (isset($probe[$m]) && !empty($probe[$m]['ok'])) {
            $why = ($m !== $cur && !empty($probe[$cur]['auth_stripped']))
                ? ('واسطهٔ ' . $cur . ' هدر Authorization را حذف کرد (۴۰۱) و ' . $m . ' پاسخ ۲۰۰ داد')
                : ('روش ' . $m . ' پاسخ مستقیم ۲۰۰ داد');
            return ['mode' => $m, 'why' => $why, 'changed' => $m !== $cur];
        }
    }
    if (isset($probe[$cur]) && !empty($probe[$cur]['reached']) && ($probe[$cur]['diag'] ?? '') !== 'port'
        && empty($probe[$cur]['proxy_failure']) && empty($probe[$cur]['auth_stripped']) && empty($probe[$cur]['geo_blocked'])) {
        return ['mode' => $pick, 'why' => $why, 'changed' => false];
    }
    foreach (['doh', 'direct', 'worker', 'dns', 'proxy'] as $m) {
        if (isset($probe[$m]) && !empty($probe[$m]['reached'])) {
            $pick = $m;
            $why = !empty($probe[$cur]['auth_stripped'])
                ? ('واسطهٔ ' . $cur . ' هدر احراز هویت را حذف کرد و ' . $m . ' سالم به اندپوینت رسید')
                : (($cur === 'worker' ? 'Worker خطای مسیر/پورت داد و ' : 'روش فعلی نرسید و ') . $m . ' به اندپوینت رسید');
            return ['mode' => $pick, 'why' => $why, 'changed' => $pick !== $cur];
        }
    }
    return ['mode' => $pick, 'why' => 'هیچ روش جایگزینی به اندپوینت نرسید؛ فقط گزارش شد', 'changed' => false];
}

function aiFeedbackStoreResult(array &$providers, string $pid, int $idx, string $mid, array $r, array $j, int $latency, string $testMsg): void {
    $ok = !empty($j['ok']);
    $code = (int)($j['code'] ?? 0);
    $prevModel = is_array($providers[$pid]['models'][$idx] ?? null) ? $providers[$pid]['models'][$idx] : ['id' => $mid];
    $prevStats = aiModelNormalizeTestStats($prevModel);
    $providers[$pid]['models'][$idx]['tested'] = true;
    $providers[$pid]['models'][$idx]['available'] = $ok;
    $providers[$pid]['models'][$idx]['rateLimited'] = false;
    if ($ok) unset($providers[$pid]['models'][$idx]['billingIssue']);
    $providers[$pid]['models'][$idx]['testDetails'] = [
        'status' => $code, 'error' => mb_substr((string)($j['error'] ?? ''), 0, 300),
        'response' => mb_substr((string)($j['response'] ?? ''), 0, 300),
        'testMsg' => $testMsg, 'testCat' => '', 'latencyMs' => $latency,
        'testedAt' => gmdate('c'), 'raw' => mb_substr((string)($r['raw'] ?? ''), 0, 4000),
        'via' => (string)($r['via'] ?? ''), 'kind' => (string)($j['kind'] ?? ''),
        'note' => (string)($j['note'] ?? ''), 'feedbackFix' => true,
        'workerStyle' => (string)($r['worker_style'] ?? ''),
        'payloadRepair' => (string)($r['payload_repair'] ?? ''),
    ];
    $providers[$pid]['models'][$idx]['testStats'] = aiModelUpdateTestStats($prevStats, $ok, null, $latency, 0, $code, (string)($j['kind'] ?? ''), time());
}

if (isset($_GET['ai_feedback_fix'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(0);
    /* A bulk test and feedback retest must not mutate the same provider rows.
       Once no test owns the lock, remove its durable stop signal; otherwise all
       feedback calls immediately return "stopped" without touching a model. */
    if(aiTestLockHeld()){
        http_response_code(409);echo json_encode(['ok'=>false,'running'=>true,'error'=>'تست گروهی هنوز فعال است؛ پس از توقف/پایان دوباره فیدبک را اجرا کنید'],JSON_UNESCAPED_UNICODE);exit;
    }
    @unlink(AI_TEST_STOP_FILE);clearstatcache(true,AI_TEST_STOP_FILE);
    $apply = !empty($_GET['apply']) && $_GET['apply'] !== 'false';
    $limit = max(1, min(80, (int)($_GET['limit'] ?? 25)));
    $testMsg = trim((string)($_GET['msg'] ?? 'سلام'));
    if ($testMsg === '') $testMsg = 'سلام';

    $cn = loadConnections();
    $net = aiNetCfg($cn);
    foreach (['mode','resolve_ip','doh_url','worker_url','proxy','proxy_type','proxy_auth'] as $k) {
        if (isset($_GET['net_' . $k])) $net[$k] = trim((string)$_GET['net_' . $k]);
    }
    if (isset($_GET['net_fallback'])) $net['fallback'] = !empty($_GET['net_fallback']) && $_GET['net_fallback'] !== 'false';
    if (isset($_GET['net_timeout'])) $net['timeout'] = max(5, min(120, (int)$_GET['net_timeout']));
    $origWorker = (string)($net['worker_url'] ?? '');
    $normWorker = aiWorkerNormalizeUrl($origWorker);
    if ($normWorker !== $origWorker) $net['worker_url'] = $normWorker;

    $providers = aiProvidersLoad();
    $active = aiActiveConfig();
    $probe = [];
    $best = ['mode' => (string)($net['mode'] ?? 'direct'), 'why' => 'ارائه‌دهندهٔ فعال برای probe پیدا نشد', 'changed' => false];
    $probeProvider = '';
    if (!empty($active['provider']) && (string)($active['model'] ?? '') !== '') {
        $ap = (array)$active['provider'];
        $probeProvider = (string)($ap['name'] ?? ($ap['id'] ?? ''));
        $pk = aiPickApiKey($ap, (string)($ap['id'] ?? ''));
        $ep = aiProviderEndpoint($ap, (string)$active['model']);
        if (!empty($ep['url'])) {
            $probe = aiFeedbackProbeModes($net, (string)$ep['url'], (string)($pk['key'] ?? ''), (string)$active['model'], $ap);
            $best = aiFeedbackBestMode($probe, $net);
        }
    }

    $fixNet = $net;
    $changes = [];
    if ($normWorker !== $origWorker) $changes[] = 'Worker URL normalized';
    if (!empty($best['changed'])) {
        $fixNet['mode'] = (string)$best['mode'];
        $fixNet['fallback'] = true;
        $changes[] = 'AI network mode -> ' . $best['mode'];
    }
    if ($apply && ($changes || $normWorker !== $origWorker)) {
        if (!isset($cn['ai_net']) || !is_array($cn['ai_net'])) $cn['ai_net'] = [];
        $cn['ai_net']['worker_url'] = (string)($fixNet['worker_url'] ?? '');
        $cn['ai_net']['mode'] = (string)($fixNet['mode'] ?? 'direct');
        $cn['ai_net']['fallback'] = !empty($fixNet['fallback']);
        saveConnections($cn);
    }

    $providerFilter=trim((string)($_GET['provider']??''));
    $preExcluded=0;
    $configRepairs=[];
    if($apply){
        $configRepairs = aiRepairProvidersConfig($providers, true);
        if (!empty($configRepairs['urls_fixed'])) $changes[] = 'Provider URLs repaired: ' . $configRepairs['urls_fixed'];
        if (!empty($configRepairs['models_renamed'])) $changes[] = 'Model IDs normalized: ' . $configRepairs['models_renamed'];
        if (!empty($configRepairs['keys_unblocked'])) $changes[] = 'Suspect blocked keys cleared: ' . $configRepairs['keys_unblocked'];
        foreach($providers as $px=>&$pp){
            if(!is_array($pp['models']??null))continue;
            foreach($pp['models'] as $mx=>&$mm){
                if(!is_array($mm)||!empty($mm['feedbackExcluded'])||!aiFeedbackPermanentInvalid($mm))continue;
                $dd=is_array($mm['testDetails']??null)?$mm['testDetails']:[];
                aiFeedbackExcludeInvalid($mm,(string)($dd['error']??$dd['note']??'permanent_invalid_model'));$preExcluded++;
            }unset($mm);
        }unset($pp);
    }
    $targets = [];$cursor=(string)($_GET['cursor']??'');$pastCursor=$cursor==='';$remaining=0;
    $skipped = ['available'=>0,'billing'=>0,'ratelimit'=>0,'untested'=>0,'invalid'=>0,'nonchat'=>0];
    foreach ($providers as $pid => $p) {
        if (($p['enabled'] ?? true) === false || ($providerFilter!==''&&!hash_equals($providerFilter,(string)$pid))) continue;
        foreach ((array)($p['models'] ?? []) as $idx => $m) {
            if (!is_array($m)) continue;
            $mid = (string)($m['id'] ?? '');
            if ($mid === '') continue;
            $rowCursor=(string)$pid.'|'.$mid;
            if(!$pastCursor){if(hash_equals($cursor,$rowCursor))$pastCursor=true;continue;}
            $sr = aiFeedbackSkipReason($m);
            if ($sr !== '') { if (isset($skipped[$sr])) $skipped[$sr]++; continue; }
            if(count($targets)<$limit)$targets[]=['pid'=>(string)$pid,'idx'=>(int)$idx,'mid'=>$mid,'cursor'=>$rowCursor];
            else $remaining++;
        }
    }
    $nextCursor=$targets?(string)($targets[count($targets)-1]['cursor']??''):'';

    $results = [];
    $fixed = 0; $stillFailed = 0; $nowExcluded = 0; $invalidExcluded=$preExcluded;
    foreach ($targets as $t) {
        $pid = (string)$t['pid']; $idx = (int)$t['idx']; $mid = (string)$t['mid'];
        if (!isset($providers[$pid])) continue;
        $t0 = microtime(true);
        $r = aiProviderCall((array)$providers[$pid], $mid,
            ['messages'=>[['role'=>'user','content'=>$testMsg]], 'temperature'=>0.2, 'max_tokens'=>300], $fixNet);
        $lat = (int)round((microtime(true) - $t0) * 1000);
        $j = aiTestJudge($r, $mid, $pid);
        $code = (int)($j['code'] ?? 0);
        $excluded = ((string)($j['billing'] ?? '') !== '' || strpos((string)($j['kind'] ?? ''), 'billing') === 0 || $code === 429);
        $permanentInvalid=(string)($j['kind']??'')==='badmodel';
        if ($excluded) {
            $nowExcluded++;
            if($apply)aiFeedbackStoreResult($providers,$pid,$idx,$mid,$r,$j,$lat,$testMsg);
        } elseif($permanentInvalid) {
            if($apply){aiFeedbackStoreResult($providers,$pid,$idx,$mid,$r,$j,$lat,$testMsg);
                aiFeedbackExcludeInvalid($providers[$pid]['models'][$idx],(string)($j['error']??'permanent_invalid_model'));}
            $invalidExcluded++;
        } else {
            if ($apply) aiFeedbackStoreResult($providers, $pid, $idx, $mid, $r, $j, $lat, $testMsg);
            if (!empty($j['ok'])) $fixed++; else $stillFailed++;
        }
        $results[] = ['provider'=>$pid, 'model'=>$mid, 'ok'=>!empty($j['ok']), 'code'=>$code,
            'kind'=>(string)($j['kind'] ?? ''), 'billing'=>(string)($j['billing'] ?? ''),
            'diag'=>(string)($j['diag']['cat'] ?? ''), 'error'=>mb_substr((string)($j['error'] ?? ''), 0, 180),
            'via'=>(string)($r['via'] ?? ''), 'payloadRepair'=>(string)($r['payload_repair'] ?? ''),
            'latencyMs'=>$lat, 'invalid_excluded'=>$permanentInvalid, 'saved'=>$apply];
    }
    if ($apply && ($results||$preExcluded>0)) aiProvidersSave($providers);

    echo json_encode(['ok'=>true, 'applied'=>$apply, 'probe_provider'=>$probeProvider,
        'probe'=>$probe, 'recommended'=>$best, 'net_before'=>aiNetPublic($net), 'net_after'=>aiNetPublic($fixNet),
        'changes'=>$changes, 'limit'=>$limit, 'provider_filter'=>$providerFilter, 'cursor'=>$cursor, 'next_cursor'=>$nextCursor,
        'has_more'=>$remaining>0, 'remaining'=>$remaining, 'candidates'=>count($targets),
        'fixed'=>$fixed, 'still_failed'=>$stillFailed, 'excluded_after_retest'=>$nowExcluded,
        'invalid_excluded'=>$invalidExcluded, 'invalid_preexcluded'=>$preExcluded, 'skipped'=>$skipped, 'results'=>$results,
        'summary'=>($apply ? 'حلقهٔ فیدبک اجرا و تغییرهای مجاز ذخیره شد' : 'حلقهٔ فیدبک در حالت گزارش اجرا شد')], JSON_UNESCAPED_UNICODE);
    exit;
}

/**
 * v8.62: درون‌ریزی حافظهٔ یادگیری.
 * اگر فایل کد را با نام یا در پوشهٔ دیگری نصب کنید، آموخته‌ها همراهش
 * نمی‌آیند چون کنار خودِ فایل ذخیره می‌شوند. با این دو اندپوینت می‌شود
 * حافظه را از نصب قبلی بیرون کشید و در نصب تازه ریخت.
 */
/* v10.12 (۲۵): مدیریتِ حافظهٔ «دسته‌های امتحان‌شده».
   op=stats  ⇒ آمار کلی
   op=list   ⇒ تلاش‌های یک محصول (برای نمایش زیر ردیفِ فاز ۲)
   op=clear  ⇒ پاک‌کردنِ یک محصول (pid) یا کلِ حافظه (pid=0) */
if (($_POST['action'] ?? '') === 'cat_tried') {
    header('Content-Type: application/json; charset=UTF-8');
    $op  = (string)($_POST['op'] ?? 'stats');
    $pid = (int)($_POST['pid'] ?? 0);
    if ($op === 'clear') {
        $n = catTriedClear($pid);
        echo json_encode(['ok' => true, 'cleared' => $n,
            'msg' => $pid > 0 ? 'حافظهٔ تلاش این محصول پاک شد' : 'کل حافظهٔ تلاش‌ها پاک شد (' . aiFaNum($n) . ' محصول)'],
            JSON_UNESCAPED_UNICODE); exit;
    }
    if ($op === 'list') {
        $row = catTriedRow($pid);
        $out = [];
        foreach ((array)($row['tried'] ?? []) as $cid => $info) {
            $out[] = ['id' => (int)$cid, 'name' => (string)($info['name'] ?? ''),
                      'n' => (int)($info['n'] ?? 1), 'at' => (int)($info['at'] ?? 0),
                      'by' => (string)($info['by'] ?? ''), 'res' => (string)($info['res'] ?? '')];
        }
        usort($out, function ($a, $b) { return $b['at'] <=> $a['at']; });
        echo json_encode(['ok' => true, 'pid' => $pid, 'cur' => (int)($row['cur'] ?? 0),
                          'title' => (string)($row['t'] ?? ''), 'tried' => $out], JSON_UNESCAPED_UNICODE); exit;
    }
    echo json_encode(['ok' => true] + catTriedStats(), JSON_UNESCAPED_UNICODE); exit;
}

if (($_POST['action'] ?? '') === 'catlearn_import') {
    header('Content-Type: application/json; charset=UTF-8');
    $inc = json_decode((string)($_POST['data'] ?? '{}'), true);
    if (!is_array($inc) || empty($inc)) {
        echo json_encode(['ok' => false, 'error' => 'داده‌ای برای درون‌ریزی نیست'], JSON_UNESCAPED_UNICODE); exit;
    }
    $replace = !empty($_POST['replace']);
    $cur = $replace ? [] : catLearnLoad();
    $added = 0; $merged = 0;
    foreach ($inc as $w => $row) {
        $w = (string)$w;
        if ($w === '' || !is_array($row) || empty($row['cats']) || !is_array($row['cats'])) continue;
        if (!isset($cur[$w])) { $cur[$w] = $row; $added++; continue; }
        // ادغام: شمارش‌ها جمع می‌شوند تا انتخاب پرتکرارتر برنده بماند
        foreach ($row['cats'] as $cid => $info) {
            $cid = (string)$cid;
            $prevN = (int)($cur[$w]['cats'][$cid]['n'] ?? 0);
            $cur[$w]['cats'][$cid] = [
                'n'    => $prevN + (int)($info['n'] ?? 0),
                'name' => (string)($info['name'] ?? ($cur[$w]['cats'][$cid]['name'] ?? '')),
                'at'   => max((int)($info['at'] ?? 0), (int)($cur[$w]['cats'][$cid]['at'] ?? 0)),
            ];
        }
        $cur[$w]['n'] = (int)($cur[$w]['n'] ?? 0) + (int)($row['n'] ?? 0);
        $cur[$w]['last'] = max((int)($cur[$w]['last'] ?? 0), (int)($row['last'] ?? 0));
        $merged++;
    }
    catLearnSave($cur);
    echo json_encode(['ok' => true, 'added' => $added, 'merged' => $merged,
        'total' => count($cur), 'replaced' => $replace], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['catlearn'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $d = catLearnLoad();

    // v8.62: برون‌بری کامل برای انتقال به نصب دیگر
    if (!empty($_GET['export'])) {
        echo json_encode(['ok' => true, 'count' => count($d), 'file' => CATLEARN_FILE,
            'exported_at' => time(), 'data' => $d], JSON_UNESCAPED_UNICODE); exit;
    }

    $forget = trim((string)($_GET['forget'] ?? ''));
    if ($forget !== '') {
        $w = catFirstWord($forget) ?: $forget;
        unset($d[$w]);
        catLearnSave($d);
        echo json_encode(['ok' => true, 'forgot' => $w, 'left' => count($d)], JSON_UNESCAPED_UNICODE); exit;
    }
    if (!empty($_GET['clear'])) {
        catLearnSave([]);
        echo json_encode(['ok' => true, 'cleared' => true], JSON_UNESCAPED_UNICODE); exit;
    }
    $test = trim((string)($_GET['test'] ?? ''));
    if ($test !== '') {
        // v8.60: هر دور را جداگانه نشان بده تا معلوم شود کدام طول جواب داد
        $maxN = catLearnWordCount();
        $rounds = [];
        for ($i = 1; $i <= $maxN; $i++) {
            $k = catFirstWords($test, $i);
            $rounds[] = ['words' => $i, 'key' => $k, 'cat_id' => catLearnBestFor($k, $d)];
        }
        echo json_encode(['ok' => true, 'title' => $test, 'first_word' => catFirstWord($test),
            'word_count' => $maxN, 'rounds' => $rounds,
            'learned_cat' => catLearnLookup($test, $d)], JSON_UNESCAPED_UNICODE); exit;
    }

    $rows = [];
    foreach ($d as $w => $row) {
        if (!is_array($row)) continue;
        $bestId = 0; $bestN = 0; $bestName = '';
        foreach (($row['cats'] ?? []) as $cid => $info) {
            if ((int)($info['n'] ?? 0) > $bestN) {
                $bestN = (int)$info['n']; $bestId = (int)$cid;
                $bestName = (string)($info['name'] ?? '');
            }
        }
        $rows[] = ['word' => $w, 'cat_id' => $bestId, 'cat_name' => $bestName,
                   'times' => $bestN, 'total' => (int)($row['n'] ?? 0),
                   'variants' => count($row['cats'] ?? []), 'last' => (int)($row['last'] ?? 0)];
    }
    usort($rows, fn($a, $b) => $b['last'] <=> $a['last']);
    echo json_encode(['ok' => true, 'count' => count($rows),
        'rows' => array_slice($rows, 0, 300)], JSON_UNESCAPED_UNICODE);
    exit;
}

/** v8.33: بررسی/ادامهٔ دستی صف گیرکرده */
if (isset($_GET['queue_watchdog'])) {
    ob_clean();
    header('Content-Type: application/json; charset=UTF-8');
    $cn = loadConnections();
    $after = (int)($_GET['after'] ?? ($cn['stall_after'] ?? 300));
    $dry   = !empty($_GET['dry']);
    $which = (string)($_GET['which'] ?? 'both');
    $out = [];
    foreach (($which === 'both' ? ['bsl', 'woo'] : [$which]) as $wq) {
        if ($wq !== 'bsl' && $wq !== 'woo') continue;
        $out[] = queueStallRecover($wq, max(30, $after), $dry);
    }
    echo json_encode(['ok' => true, 'checks' => $out], JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v8.35: خودآزمون — «آیا واقعاً همان کدی که فکر می‌کنم روی سرور است؟»
 *
 *  چند بار پیش آمده که تغییری ساخته شده ولی روی هاست نصب نشده و
 *  به نظر رسیده کار نکرده است. این صفحه بدون حدس‌زدن جواب می‌دهد:
 *  هر قابلیت را واقعاً در همین فایلِ در حال اجرا بررسی می‌کند.
 * ===================================================================== */
if (isset($_GET['selftest'])) {
    @set_time_limit(180);
    $wantJson = isset($_GET['json']);
    header('Content-Type: ' . ($wantJson ? 'application/json' : 'text/html') . '; charset=UTF-8');
    $__selftestFinished = false;
    register_shutdown_function(static function () use (&$__selftestFinished, $wantJson): void {
        if ($__selftestFinished) return;
        $err = error_get_last();
        @http_response_code(200);
        if ($wantJson) {
            echo json_encode(['ok' => false, 'selftest_fatal' => $err], JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE);
        }
    });
    try {

    $checks = [];
    $add = function (string $ver, string $name, bool $ok, string $detail = '') use (&$checks) {
        $checks[] = ['ver' => $ver, 'name' => $name, 'ok' => $ok, 'detail' => $detail];
    };

    // ۱) وجود توابع کلیدی هر نسخه — اگر نصب ناقص باشد اینجا لو می‌رود
    $fnMap = [
        ['8.32', 'مودال استعلام سفارش‌ها و گفتگوها', 'bslNormalizeParcel'],
        ['8.32', 'خواندن درست نام مشتری', 'bslParcelCustomerName'],
        ['8.33', 'متن کامل پیام‌های مشتری', 'bslFetchChatMessages'],
        ['8.33', 'نگهبان صف ارسال', 'queueStallCheck'],
        ['8.34', 'بازنشستگی محصولات رفته از مبدأ', 'retireRemoved'],
        ['8.34', 'محافظ ایمنی بازنشستگی', 'retireGuard'],
    ];
    foreach ($fnMap as [$v, $label, $fn]) {
        $add($v, $label, function_exists($fn), $fn . '()');
    }

    // ۲) رفع خطای ۴۲۲ — نباید هیچ sort نامعتبری در کد مانده باشد
    $selfSrc = (string)@file_get_contents(__FILE__);
    $sharedMxFixture=['vendor_id'=>710223,'at'=>time(),'partial'=>true,'scope_complete'=>true,
        'status_scope'=>'active_2976','rows'=>[
            ['id'=>11,'name'=>'محصول فعال','status'=>2976,'price'=>125000,'stock'=>4],
            ['id'=>12,'name'=>'محصول غیرفعال','status'=>3790,'price'=>90000,'stock'=>0],
        ]];
    $sharedMxRows=function_exists('bslCatalogRowsForMatrix')?bslCatalogRowsForMatrix(710223,$sharedMxFixture):null;
    $add('10.495','ماتریس از کش مشترکِ کاملِ active فقط محصول قابل مشاهده را می‌گیرد',
        is_array($sharedMxRows)&&count($sharedMxRows)===1&&(int)($sharedMxRows[0]['id']??0)===11
        &&(int)($sharedMxRows[0]['price']??0)===125000);
    $add('10.496','پاک‌سازیِ معوق با ورود کران هم دوباره بررسی می‌شود',
        strpos($selfSrc,'function_exists(' . "'tasksStopAllClearCheckpoints'))tasksStopAllClearCheckpoints()")!==false
        &&strpos($selfSrc,"{v:'10." . "496'")!==false&&version_compare(APP_VERSION,'10.' . '496','>='));
    $add('10.495','توقف همه، پاک‌سازی checkpoint امن و دکمهٔ مدیر وظیفه حاضرند',
        function_exists('tasksStopAllRequest')&&function_exists('tasksStopAllClearCheckpoints')
        &&strpos($selfSrc,'tasks_' . 'stop_all')!==false
        &&strpos($selfSrc,'tmStop' . 'All()')!==false
        &&strpos($selfSrc,'shared_catalog_' . 'matrix_delta')!==false
        &&strpos($selfSrc,"{v:'10." . "495'")!==false&&version_compare(APP_VERSION,'10.' . '495','>='));
    $__stVerFilter = trim((string)($_GET['ver'] ?? ''));
    $__stModernOnly = !empty($_GET['fast']) || ($__stVerFilter !== '' && (bool)preg_match('/^10\.(?:4(?:3[7-9]|[4-9]\d)|[5-9]\d\d)$/', $__stVerFilter));
    if (!$__stModernOnly) {
    // رشته را تکه‌تکه می‌سازیم تا خودِ همین خط در شمارش نیفتد و
    // «هشدار الکی» ندهد — خودآزمون نباید خودش را پیدا کند.
    $badSort = substr_count($selfSrc, 'sort=' . 'created_at');
    $add('8.33', 'رفع خطای ۴۲۲ (حذف sort نامعتبر)', $badSort === 0,
         $badSort === 0 ? 'پاک است' : $badSort . ' مورد باقی مانده');

    // ۳) اندپوینت‌های تازه واقعاً در همین فایل هستند؟
    foreach ([['8.32', 'bsl_orders_list'], ['8.32', 'bsl_chats_list'],
              ['8.32', 'bsl_notify_selected'], ['8.33', 'queue_watchdog'],
              ['8.34', 'retire_run']] as [$v, $ep]) {
        $add($v, 'اندپوینت ?' . $ep, strpos($selfSrc, "'" . $ep . "'") !== false);
    }

    // v8.56: پارسر واقعاً داخل ظرف محصول می‌ماند؟
    // این همان باگی است که باعث می‌شد قیمتِ ویجت کناری روی محصول بی‌قیمت
    // بنشیند. اینجا با یک صفحهٔ کوچک ساختگی، رفتار واقعی سنجیده می‌شود.
    if (function_exists('parse_with_selectors')) {
        $tHtml = '<html><body>'
               . '<div class="widget"><span class="price">۹۹۹,۹۹۹ تومان</span>'
               . '<img class="pimg" src="http://t.test/sidebar.jpg"></div>'
               . '<div class="p"><h2 class="ptitle">کالای بی‌قیمت</h2></div>'
               . '<div class="p"><h2 class="ptitle">کالای سالم</h2>'
               . '<span class="price">۵۰۰,۰۰۰ تومان</span>'
               . '<img class="pimg" src="http://t.test/ok.jpg"></div>'
               . '</body></html>';
        $tSel = ['container' => '.p', 'title' => '.ptitle', 'price' => '.price', 'image' => '.pimg'];
        $tOut = array_values(parse_with_selectors($tHtml, 'http://t.test/', $tSel));
        $noLeakPrice = isset($tOut[0]) && trim((string)$tOut[0]['price']) === '';
        $noLeakImage = isset($tOut[0]) && trim((string)$tOut[0]['image']) === '';
        $goodKept    = isset($tOut[1]) && extractPriceNum($tOut[1]['price']) === 500000;
        $add('8.56', 'قیمت از ویجت کناری به محصول نشت نمی‌کند', $noLeakPrice,
             $noLeakPrice ? 'محصول بی‌قیمت، بی‌قیمت ماند' : 'نشت: ' . ($tOut[0]['price'] ?? '?'));
        $add('8.56', 'عکس از نوار کناری به محصول نشت نمی‌کند', $noLeakImage,
             $noLeakImage ? 'محصول بی‌عکس، بی‌عکس ماند' : 'نشت: ' . ($tOut[0]['image'] ?? '?'));
        $add('8.56', 'محصول سالم قیمت درست خودش را می‌گیرد', $goodKept);
    }

    // v8.57: تصویر ووکامرس — وقتی آپلود به کتابخانهٔ رسانه ممکن نیست،
    // آدرس باید به خود ووکامرس سپرده شود، نه اینکه محصول بی‌تصویر برود.
    if (function_exists('wooImagePayload')) {
        $noteImg = null;
        $wBad = ['store_url' => 'http://127.0.0.1:9/', 'consumer_key' => 'ck', 'consumer_secret' => 'cs'];
        $payload = wooImagePayload($wBad, 'https://example.test/pic.jpg', $noteImg);
        $srcFallback = !empty($payload[0]['src']);
        $add('8.57', 'تصویر: در نبودِ آپلود، آدرس به ووکامرس سپرده می‌شود', $srcFallback,
             $srcFallback ? 'images[0].src' : 'خالی برگشت');
        $noteEmpty = null;
        $add('8.57', 'تصویر: آدرس خالی چیزی نمی‌فرستد', wooImagePayload($wBad, '', $noteEmpty) === []);
    }

    // v8.63: تصویر جدا از ساخت محصول وصل می‌شود
    $noInlineCreate = strpos($selfSrc, "if(!empty(\$wooNewImgs))\$wp['images']=\$wooNewImgs;") === false
                   && strpos($selfSrc, "if(!empty(\$wooStreamImgs))\$wp['images']=\$wooStreamImgs;") === false;
    $add('8.63', 'تصویر داخل درخواست ساخت محصول نمی‌رود', $noInlineCreate);
    $add('8.63', 'تصویر با درخواست جدا وصل می‌شود (روش عکس‌دار کردن)',
         strpos($selfSrc, "wooEditProduct(\$w,\$newId,['images'=>\$wooNewImgs])") !== false
         && strpos($selfSrc, "wooEditProduct(\$w,\$newId,['images'=>\$wooStreamImgs])") !== false);
    // رشته تکه‌تکه، تا خودآزمون خودش را پیدا نکند (درس v8.35)
