             $th = app_themes_registry();
             if (count($th) < 10) return false;
             foreach ($th as $k => $v) {
                 if (trim((string)($v['label'] ?? '')) === '') return false;
                 foreach (['nHue', 'nSat', 'nLift', 'aRot', 'aSat'] as $f) {
                     if (!array_key_exists($f, $v)) return false;
