/* =====================================================================
 *  v10.35 (۴۷د): گزارشِ کاملِ هر همگام‌سازی
 *
 *  خواستهٔ کاربر: «بعد از هر عملیاتِ همگام‌سازی، یک گزارشِ کامل در مدیرِ
 *  وظایف ثبت کن و همان گزارش را به پیام‌رسان هم بفرست».
 *
 *  تا اینجا هر تکه از کار جای خودش را داشت — اعلانِ تغییرِ مبدأ یک پیام،
 *  اعلانِ بایگانی یک پیام، پینگِ کران یک پیام دیگر — ولی هیچ‌جا یک تصویرِ
 *  واحد از «این نوبت چه اتفاقی افتاد» نبود. و هیچ‌کدام روی دیسک نمی‌ماند،
 *  پس اگر پیام‌رسان تنظیم نبود یا پیام گم می‌شد، هیچ ردی باقی نمی‌ماند.
 *
 *  حالا یک ردیفِ گزارشِ ماندگار ساخته می‌شود که همه‌چیز را یک‌جا دارد و
 *  هم در مدیر وظیفه دیده می‌شود، هم به پیام‌رسان می‌رود.
 * ===================================================================== */

function syncReportRead(): array {
    if (!is_file(SYNC_REPORT_FILE)) return ['items' => [], 'updated' => 0];
    $d = json_decode((string)@file_get_contents(SYNC_REPORT_FILE), true);
    if (!is_array($d) || !is_array($d['items'] ?? null)) return ['items' => [], 'updated' => 0];
    return $d;
}

/** تازه‌ترین گزارش بالای فهرست می‌نشیند */
function syncReportAdd(array $rep): int {
    $log = syncReportRead();
    $rep['at'] = (int)($rep['at'] ?? time());
    array_unshift($log['items'], $rep);
    if (count($log['items']) > (int)SYNC_REPORT_KEEP)
        $log['items'] = array_slice($log['items'], 0, (int)SYNC_REPORT_KEEP);
    $log['updated'] = time();
    @file_put_contents(SYNC_REPORT_FILE, json_encode($log, JSON_UNESCAPED_UNICODE), LOCK_EX);
    return count($log['items']);
}

/**
 * از نتیجهٔ یک پروفایل در حلقهٔ کران (یا همگام‌سازیِ دستی) یک ردیفِ گزارش
 * می‌سازد. فقط چیزهایی که واقعاً عدد دارند وارد می‌شوند تا گزارش پر از
 * صفر نشود.
 */
function syncReportBuild(array $p, string $trigger = 'cron', int $startedAt = 0): array {
    $rep = [
        'at'       => time(),
        'trigger'  => $trigger,
        'profile'  => (string)($p['name'] ?? ($p['key'] ?? '')),
        'key'      => (string)($p['key'] ?? ''),
        'target'   => (string)($p['target'] ?? ''),
        'status'   => (string)($p['status'] ?? ''),
        'took'     => $startedAt > 0 ? max(0, time() - $startedAt) : 0,
    ];
    foreach (['extracted', 'new', 'price_changed', 'removed', 'unchanged',
              'price_up', 'price_down', 'gone_from_site', 'no_price'] as $k) {
        if ((int)($p[$k] ?? 0) !== 0) $rep['extract'][$k] = (int)$p[$k];
    }
    if (!empty($p['extract_error'])) $rep['extract_error'] = (string)$p['extract_error'];
    if (!empty($p['retire']))        $rep['retire']  = $p['retire'];
    if (isset($p['woo']))            $rep['woo']     = ['state' => (string)$p['woo'], 'total' => (int)($p['woo_total'] ?? 0)];
    if (isset($p['bsl']))            $rep['bsl']     = ['state' => (string)$p['bsl'], 'total' => (int)($p['bsl_total'] ?? 0)];
    if (isset($p['changed_only']))   $rep['changed_only'] = (int)$p['changed_only'];
    if (isset($p['catalog_size']))   $rep['catalog_size'] = (int)$p['catalog_size'];
    if (!empty($p['pricing_changed']))      $rep['pricing_changed'] = true;
    if (!empty($p['shop_pricing_changed'])) $rep['shop_pricing_changed'] = true;
    if (!empty($p['add_update_hold']))      $rep['hold'] = (string)$p['add_update_hold'];
    /* v10.35 (۴۷ب): صرفه‌جوییِ کش هم بخشی از گزارش است — کاربر باید ببیند
       این نسخه چقدر درخواستِ بی‌مورد را حذف کرده. */
    $saved = bslCatalogSaved();
    if ($saved > 0) $rep['catalog_hits'] = $saved;
    $skips = function_exists('bslSkipCount') ? bslSkipCount() : 0;
    if ($skips > 0) $rep['unchanged_skips'] = $skips;
    return $rep;
}

/** همان گزارش، به شکلِ متنِ خوانا برای پیام‌رسان و برای مدیر وظیفه */
function syncReportText(array $r): string {
    $trig = ['cron' => 'خودکار', 'manual' => 'دستی', 'manual_sync' => 'دستی'][(string)($r['trigger'] ?? '')] ?? (string)($r['trigger'] ?? '');
    $L = ['🔄 گزارشِ همگام‌سازی — ' . (string)($r['profile'] ?? '?')
          . ($trig !== '' ? ' (' . $trig . ')' : '')];
    $L[] = '🕐 ' . date('Y/m/d H:i', (int)($r['at'] ?? time()))
         . ((int)($r['took'] ?? 0) > 0 ? ' · ' . (int)$r['took'] . ' ثانیه' : '');

    $ex = is_array($r['extract'] ?? null) ? $r['extract'] : [];
    if ($ex) {
        $lbl = ['extracted' => 'استخراج', 'new' => 'تازه', 'price_changed' => 'تغییرِ قیمت',
                'removed' => 'رفته از مبدأ', 'unchanged' => 'بی‌تغییر', 'price_up' => 'گران',
                'price_down' => 'ارزان', 'gone_from_site' => 'حذف از سایت', 'no_price' => 'بی‌قیمت'];
        $parts = [];
        foreach ($ex as $k => $v) $parts[] = ($lbl[$k] ?? $k) . ': ' . (int)$v;
        $L[] = '📦 ' . implode(' · ', $parts);
    }
    if (!empty($r['extract_error'])) $L[] = '❌ استخراج: ' . (string)$r['extract_error'];

    if (!empty($r['retire']) && is_array($r['retire'])) {
        $rt = $r['retire'];
        $L[] = '🗂 بازنشستگی: انجام‌شده ' . (int)($rt['retired'] ?? 0)
             . ' · یافت‌نشده ' . (int)($rt['not_found'] ?? 0)
             . ' · ناموفق ' . (int)($rt['failed'] ?? 0)
             . ((int)($rt['not_owned'] ?? 0) > 0 ? ' · مالِ پروفایلِ دیگر ' . (int)$rt['not_owned'] : '')
             . (!empty($rt['skipped']) ? ' — ' . (string)$rt['skipped'] : '');
    }

    $stLbl = ['queued' => 'صف شد', 'already_queued' => 'از قبل در صف بود',
              'no_changes' => 'تغییری نبود', 'no_products' => 'محصولی نبود',
              'file_save_error' => 'خطای ذخیرهٔ فایل'];
    foreach ([['woo', '🛍 ووکامرس'], ['bsl', '🏪 باسلام']] as [$k, $ttl]) {
        if (empty($r[$k]) || !is_array($r[$k])) continue;
        $s = (string)($r[$k]['state'] ?? '');
        $L[] = $ttl . ': ' . ($stLbl[$s] ?? $s)
             . ((int)($r[$k]['total'] ?? 0) > 0 ? ' — ' . (int)$r[$k]['total'] . ' محصول' : '');
    }
    if (isset($r['changed_only']))
        $L[] = '🎯 فقط تغییرات: ' . (int)$r['changed_only']
             . (isset($r['catalog_size']) ? ' از ' . (int)$r['catalog_size'] : '');
    if (!empty($r['pricing_changed']))      $L[] = '💰 ضریبِ پروفایل عوض شده بود — یک نوبت ارسالِ کامل';
    if (!empty($r['shop_pricing_changed'])) $L[] = '💰 ضریبِ مقصد/غرفه عوض شده بود — یک نوبت ارسالِ کامل';
    if (!empty($r['hold']))                 $L[] = '⏸ ارسال نگه داشته شد: ' . (string)$r['hold'];
    if ((int)($r['catalog_hits'] ?? 0) > 0)
        $L[] = '⚡ ' . (int)$r['catalog_hits'] . ' جست‌وجو از کشِ غرفه جواب گرفت';
    if ((int)($r['unchanged_skips'] ?? 0) > 0)
        $L[] = '⏭ ' . (int)$r['unchanged_skips'] . ' محصولِ بی‌تغییر رد شد';
    return implode("\n", $L);
}

/** ثبت + ارسالِ گزارش. خروجی: ['logged'=>int,'delivery'=>array|null] */
function syncReportEmit(array $cn, array $rep): array {
    $out = ['logged' => syncReportAdd($rep), 'delivery' => null];
    /* پیش‌فرض روشن است (خواستهٔ صریحِ کاربر)؛ کاربر می‌تواند خاموشش کند. */
    $ne = $cn['notif_events'] ?? [];
    if (isset($ne['sync_report']) && empty($ne['sync_report'])) {
        $out['skipped'] = 'disabled'; return $out;
    }
    $hasMsgr = notifMessengerConfigured($cn, 'baleh')
            || notifMessengerConfigured($cn, 'rubika')
            || notifMessengerConfigured($cn, 'telegram');
    if (!$hasMsgr) { $out['skipped'] = 'no_messenger'; return $out; }
    $out['delivery'] = notifSend($cn, syncReportText($rep), 'sync');
    return $out;
}

/** اعلان نتیجهٔ بازنشستگی به پیام‌رسان‌ها */
function notifRetire(array $cn, array $res, string $profileName = ''): array {
    /* v10.45 (۵۹): نبودِ کلید = روشن — همان چیزی که رابط نشان می‌دهد. */
    if (!notifEventOn($cn['notif_events'] ?? [], 'retire')) return ['ok' => true, 'skipped' => 'disabled'];
    /* v10.102: برای بایگانی فقط پیام‌رسان لازم است (توکن باسلام اجباری نیست). */
    $hasMsgr = notifMessengerConfigured($cn, 'baleh')
            || notifMessengerConfigured($cn, 'rubika')
            || notifMessengerConfigured($cn, 'telegram');
    if (!$hasMsgr) return ['ok' => false, 'error' => 'no_messenger'];

    $modeLbl = retireModes()[$res['mode'] ?? ''] ?? (string)($res['mode'] ?? '');
    $modeW = (string)($res['mode_woo'] ?? $res['woo_action'] ?? '');
    $modeB = (string)($res['mode_bsl'] ?? $res['bsl_action'] ?? '');
    $wooActs = function_exists('retireWooActions') ? retireWooActions() : [];
    $bslActs = function_exists('retireBslActions') ? retireBslActions() : [];
    $wooLbl = $wooActs[$modeW] ?? ($modeW !== '' ? $modeW : ($modeLbl !== '' ? $modeLbl : 'حذف/بایگانی'));
    $bslLbl = $bslActs[$modeB] ?? ($modeB !== '' ? $modeB : ($modeLbl !== '' ? $modeLbl : 'بایگانی'));

    $guardBlocked = !empty($res['guard']['blocked'])
        || (!empty($res['guard']) && empty($res['guard']['allow']) && !empty($res['guard']['reason']));
    if ($guardBlocked) {
        return ['ok' => true, 'delivery' => notifSend($cn,
            "🛑 بازنشستگی خودکار متوقف شد" . ($profileName !== '' ? "\nپروفایل: {$profileName}" : '')
            . "\nعلت: " . ($res['guard']['reason'] ?? ($res['skipped'] ?? ''))
            . "\nهیچ محصولی تغییر نکرد — اگر درست است، دستی اجرا کنید.", 'retire')];
    }
    $nRet = (int)($res['retired'] ?? 0);
    $nFail = (int)($res['failed'] ?? 0);
    $nNf = (int)($res['not_found'] ?? 0);
    $nChk = (int)($res['checked'] ?? 0);
    if ($nRet <= 0 && $nFail <= 0) return ['ok' => true, 'skipped' => 'nothing'];

    $lines = ["🗂 بایگانی / حذف محصولات ناموجود" . ($profileName !== '' ? " — {$profileName}" : '')];
    $lines[] = "🛒 ووکامرس: {$wooLbl}";
    $lines[] = "🟢 باسلام: {$bslLbl}";
    $lines[] = "✅ انجام‌شده: {$nRet}"
             . ($nChk > 0 ? " · بررسی: {$nChk}" : '')
             . " · یافت‌نشده: {$nNf}"
             . " · ناموفق: {$nFail}";
    $n = 0;
    foreach ((array)($res['items'] ?? []) as $it) {
        if ($n >= 12) break;
        if (!is_array($it)) continue;
        $title = mb_substr(trim((string)($it['title'] ?? '')), 0, 50);
        if ($title === '') continue;
        $bits = [];
        $reason = trim((string)($it['reason'] ?? ''));
        if ($reason !== '') $bits[] = $reason;
        $w = trim((string)($it['woo'] ?? ''));
        $b = trim((string)($it['bsl'] ?? ''));
        $didW = $w !== '' && (strpos($w, 'انجام شد') !== false || strpos($w, 'حذف') !== false);
        $didB = $b !== '' && (strpos($b, 'بایگانی') !== false || strpos($b, 'انجام شد') !== false);
        $failW = $w !== '' && strpos($w, 'خطا') !== false;
        $failB = $b !== '' && strpos($b, 'خطا') !== false;
        if (!$didW && !$didB && !$failW && !$failB) continue;
        if ($didW || $failW) $bits[] = 'ووکامرس: ' . $w;
        if ($didB || $failB) $bits[] = 'باسلام: ' . $b;
        $lines[] = '• ' . $title . ' — ' . implode(' | ', $bits);
        $n++;
    }
    if ($nRet > $n && $n > 0) $lines[] = '… و ' . max(0, $nRet - $n) . ' مورد دیگر';
    $lines[] = '🕐 ' . date('Y/m/d H:i');
    return ['ok' => true, 'delivery' => notifSend($cn, implode("\n", $lines), 'retire'), 'sent_lines' => count($lines)];
}

/**
 * v8.30: اعلان تغییرات سایت مبدأ.
 * نتیجهٔ استخراج را می‌گیرد و گران/ارزان شدن و موجود/ناموجود شدن را
 * به پیام‌رسان‌ها گزارش می‌کند. برای جلوگیری از هرزنامه، به‌جای یک پیام
 * برای هر محصول، یک خلاصهٔ فشرده با نمونه‌ها فرستاده می‌شود.
 */
function notifSourceChanges(array $cn, array $res, string $profileName = '', int $sampleLimit = 5): array {
    $ne = $cn['notif_events'] ?? [];
    /* v10.45 (۵۹): نبودِ کلید = روشن — همان چیزی که رابط نشان می‌دهد. */
    $wantPrice = notifEventOn($ne, 'src_price');
    $wantStock = notifEventOn($ne, 'src_stock');
    if (!$wantPrice && !$wantStock) return ['ok' => true, 'skipped' => 'disabled'];
    if (notifPrereq($cn) !== null) return ['ok' => false, 'error' => notifPrereq($cn)];

    $up = (int)($res['price_up'] ?? 0);
    $down = (int)($res['price_down'] ?? 0);
    $noPrice = (int)($res['no_price'] ?? 0);
    $gone = (int)($res['gone_from_site'] ?? 0);
    $back = 0;
    foreach (($res['new_items'] ?? []) as $it) {
        if (($it['reason'] ?? '') === 'دوباره موجود شد') $back++;
    }

    $blocks = [];

    if ($wantPrice && ($up > 0 || $down > 0)) {
        $lines = ["💰 تغییر قیمت در سایت مبدأ" . ($profileName !== '' ? " — {$profileName}" : '')];
        $lines[] = "▲ گران شد: {$up}   ▼ ارزان شد: {$down}";
        $n = 0;
        foreach (($res['changed_items'] ?? []) as $it) {
            if ($n >= $sampleLimit) break;
            $arrow = ($it['dir'] ?? '') === 'up' ? '▲' : '▼';
            $pct = isset($it['pct']) ? (($it['pct'] > 0 ? '+' : '') . $it['pct'] . '٪') : '';
            $lines[] = $arrow . ' ' . mb_substr((string)($it['title'] ?? ''), 0, 40)
                     . "\n   " . ($it['old_price'] ?? '') . ' ← ' . ($it['new_price'] ?? '') . ' ' . $pct;
            $n++;
        }
        $rest = ($up + $down) - $n;
        if ($rest > 0) $lines[] = "... و {$rest} مورد دیگر";
        $blocks[] = implode("\n", $lines);
    }

    if ($wantStock && ($noPrice > 0 || $gone > 0 || $back > 0)) {
        $lines = ["📦 تغییر موجودی در سایت مبدأ" . ($profileName !== '' ? " — {$profileName}" : '')];
        if ($noPrice > 0) $lines[] = "🚫 ناموجود شد: {$noPrice}";
        if ($gone > 0)    $lines[] = "❌ از سایت حذف شد: {$gone}";
        if ($back > 0)    $lines[] = "✅ دوباره موجود شد: {$back}";
        $n = 0;
        foreach (($res['removed_items'] ?? []) as $it) {
            if ($n >= $sampleLimit) break;
            $why = $it['reason'] ?? '';
            if ($why === 'بدون قیمت') continue;   // محصول تازه‌ای که هیچ‌وقت قیمت نداشته
            $lines[] = '• ' . mb_substr((string)($it['title'] ?? ''), 0, 45) . ' — ' . $why;
            $n++;
        }
        $blocks[] = implode("\n", $lines);
    }

    if (!$blocks) return ['ok' => true, 'sent' => 0, 'nothing' => true];

    $sentCount = 0; $last = [];
    foreach ($blocks as $b) { $last = notifSend($cn, $b, 'price'); $sentCount++; }
    return ['ok' => true, 'sent' => $sentCount, 'price_up' => $up, 'price_down' => $down,
            'no_price' => $noPrice, 'gone' => $gone, 'back' => $back, 'delivery' => $last];
}

/**
 * v8.30: اعلان شکست یک اجرا. سکوت بدترین حالت است — اگر کران‌جاب
 * خراب شود باید خبردار شوید، نه اینکه روزها بی‌صدا بماند.
 */
function notifRunFailure(array $cn, string $stage, string $profileName, string $error): array {
    /* v10.45 (۵۹): پیش‌فرض روشن — سکوت در شکست بدترین حالت است. */
    if (!notifEventOn($cn['notif_events'] ?? [], 'run_fail')) return ['ok' => true, 'skipped' => 'disabled'];
    if (notifPrereq($cn) !== null) return ['ok' => false];
    $msg = "⚠️ خطا در اجرای خودکار\nمرحله: {$stage}"
         . ($profileName !== '' ? "\nپروفایل: {$profileName}" : '')
         . "\nعلت: " . mb_substr($error, 0, 200);
    return ['ok' => true, 'delivery' => notifSend($cn, $msg, 'error')];
}

/**
 * اجرای همهٔ بررسی‌های فعال — همان چیزی که کران‌جاب صدا می‌زند.
 * ترتیب عمدی: سفارش (پول)، پیام (مشتری منتظر است)، محصول (اطلاعی).
 *
 * v10.45 (۵۹): سه تغییر:
 *  ۱) دیگر یک پیش‌نیازِ سراسری (غرفهٔ پیش‌فرض) کلِ بلوک را خاموش
 *     نمی‌کند: هر غرفه‌ای که توکن دارد، با توکنِ خودش چک می‌شود.
 *  ۲) خطاهای هر غرفه دیگر دور ریخته نمی‌شوند؛ در 'errors' برمی‌گردند
 *     تا در گزارشِ آخرین اجرا و پینگِ بعدی دیده شوند.
 *  ۳) روشن/خاموشِ هر رویداد با notifEventOn سنجیده می‌شود: نبودِ کلید
 *     یعنی روشن — دقیقاً همان چیزی که رابطِ کاربری نشان می‌داد.
 */
function bslCheckNotifications(array $cn): array {
    $ne = $cn['notif_events'] ?? [];
    /* Keep polling with valid credentials while channel switches are off.
       This advances event state and avoids replaying downtime after re-enable. */
    $hasMsgr = notifMessengerConfigured($cn, 'baleh')
            || notifMessengerConfigured($cn, 'rubika')
            || notifMessengerConfigured($cn, 'telegram');
    if (!$hasMsgr) return [];   // هیچ پیام‌رسانی برای رهگیریِ رویدادها پیکربندی نشده
    $shops = array_values(array_filter(bslAllShops($cn),
        fn($s) => trim((string)($s['token'] ?? '')) !== ''));
    if (!$shops) return ['skipped' => 'no_basalam_shops'];

    /* v10.392: browser pulse, internal cron and external cron may arrive together.
       Only one scan may decide/send events; the others leave immediately. */
    $_notifLock = @fopen(NOTIF_SCAN_LOCK_FILE, 'c');
    if (!$_notifLock || !@flock($_notifLock, LOCK_EX | LOCK_NB)) {
        if ($_notifLock) @fclose($_notifLock);
        return ['skipped' => 'scan_already_running'];
    }

    $out = [];
    $errors = [];
    $seen = ['orders' => 0, 'chats' => 0, 'products' => 0];
    $found = ['orders' => 0, 'chats' => 0, 'products' => 0];
    $pending = 0; /* v10.47 (۶۱): چند گفتگوی بی‌جواب است (موردِ یادآوری) */
    if (!(notifEventOn($ne, 'order_new') || notifEventOn($ne, 'order_status')
          || notifEventOn($ne, 'chat_msg') || notifEventOn($ne, 'product_status')
          || notifEventOn($ne, 'product_new'))) $out['events_off'] = true;
    if (notifEventOn($ne, 'order_new') || notifEventOn($ne, 'order_status')) {
        $r = notifCheckOrders($cn);
        $seen['orders'] += (int)($r['total_seen'] ?? 0);
        $found['orders'] += (int)($r['found'] ?? 0) + (int)($r['reminded'] ?? 0);
        if ($found['orders'] > 0) $out['orders'] = $found['orders'];
        if (!empty($r['errors'])) $errors = array_merge($errors, (array)$r['errors']);
    }
    if (notifEventOn($ne, 'chat_msg')) {
        $r = notifCheckChats($cn);
        $seen['chats'] += (int)($r['total_seen'] ?? 0);
        $found['chats'] += (int)($r['found'] ?? 0) + (int)($r['reminded'] ?? 0);
        $pending += (int)($r['pending'] ?? 0);
        if ($found['chats'] > 0) $out['chats'] = $found['chats'];
        if (!empty($r['errors'])) $errors = array_merge($errors, (array)$r['errors']);
    }
    if (notifEventOn($ne, 'product_status') || notifEventOn($ne, 'product_new')) {
        $r = notifCheckProducts($cn);
        $seen['products'] += (int)($r['total_seen'] ?? 0);
        $found['products'] += (int)($r['found'] ?? 0) + (int)($r['reminded'] ?? 0);
        if ($found['products'] > 0) $out['products'] = $found['products'];
        if (!empty($r['errors'])) $errors = array_merge($errors, (array)$r['errors']);
    }
    if ($errors) $out['errors'] = array_values(array_unique($errors));
    /* v10.47 (۶۱): پینگ (که کاربر هر بار آن را می‌بیند) همین اعداد را
       نمایش می‌دهد؛ پس «چرا اعلانی نیامد» از همان پینگ خوانده می‌شود. */
    $out['seen_chats'] = $seen['chats'];
    $out['seen_orders'] = $seen['orders'];
    $out['seen_products'] = $seen['products'];
    if ($pending > 0) $out['pending_chats'] = $pending;
    $_ft = $found['orders'] + $found['chats'] + $found['products'];
    if ($_ft > 0) $out['found_total'] = $_ft;

    /* v10.46 (۶۰): هر دور، خلاصهٔ «چرا چیزی نیامد» روی دیسک بنشیند —
       حتی وقتی هیچ رویدادی نباشد. این دقیقاً همان سوالی است که کاربر
       می‌پرسد: «آیا اصلاً بررسی شده؟ چه دیده؟» جوابش در بخشِ اعلان‌ها
       و سلامتِ اعلان‌ها می‌درخشد. */
    try {
        $stN = notifLoadState();
        $stN['last_notif_run'] = time();
        $stN['last_notif_seen'] = $seen;
        $stN['last_notif_pending'] = $pending; /* v10.47 (۶۱) */
        $stN['last_notif_found'] = $found;
        $stN['last_notif_errors'] = $errors ?: [];
        notifSaveState($stN);
    } catch (Throwable $e) { /* خطای نوشتنِ وضعیت نباید خودِ اعلان را بکشد */ }
    @flock($_notifLock, LOCK_UN); @fclose($_notifLock);
    return $out;
}

/** v10.79 (93): لاگِ آخرینِ پینگ‌ها */
if (isset($_GET['ping_log'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $dL = json_decode((string)@file_get_contents(__DIR__ . '/notif_ping_log.json'), true);
    $logL = (is_array($dL) && is_array($dL['log'] ?? null)) ? $dL['log'] : [];
    echo json_encode(['ok' => true, 'log' => array_slice($logL, 0, 30)], JSON_UNESCAPED_UNICODE);
    exit;
}
/* v10.81 (95): لاگِ ارسال‌هایِ پیام‌رسان — هر تلاش و پاسخِ آن */
if (isset($_GET['msgr_log'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $dM = json_decode((string)@file_get_contents(__DIR__ . '/msgr_send_log.json'), true);
    $rowsM = (is_array($dM) && is_array($dM['rows'] ?? null)) ? $dM['rows'] : [];
    echo json_encode(['ok' => true, 'rows' => array_slice($rowsM, -25)], JSON_UNESCAPED_UNICODE);
    exit;
}
/* دکمه‌های تست — هر بررسی را جدا اجرا و نتیجه را گزارش می‌کند */
if (isset($_GET['notif_test'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $GLOBALS['_s4ManualNotifSend'] = true;
    $kind = $_GET['kind'] ?? '';
    $cn = loadConnections();
    /* v10.45 (۵۹): پینگ و تستِ تغییراتِ مبدأ به باسلام کاری ندارند
       (فقط پیام‌رسان لازم است — همان قاعدهٔ v10.22). بقیهٔ تست‌ها فقط
       به «حداقل یک غرفه با توکن» نیاز دارند، نه به کامل‌بودنِ
       غرفهٔ پیش‌فرض. */
    $hasMsgrN = notifMessengerConfigured($cn, 'baleh')
             || notifMessengerConfigured($cn, 'rubika')
             || notifMessengerConfigured($cn, 'telegram');
    $why = null;
    if (!$hasMsgrN) {
        $why = 'هیچ پیام‌رسانی تنظیم نشده (بله/روبیکا/تلگرام)';
    } elseif ($kind !== 'ping' && $kind !== 'source'
             && !array_values(array_filter(bslAllShops($cn), fn($s) => trim((string)($s['token'] ?? '')) !== ''))) {
        $why = 'تنظیمات باسلام ناقص است (توکن غرفه)';
    }
    if ($why !== null) { echo json_encode(['ok' => false, 'error' => $why], JSON_UNESCAPED_UNICODE); exit; }

    try {
    if ($kind === 'orders')        $r = notifCheckOrders($cn, true);
    elseif ($kind === 'chats')     $r = notifCheckChats($cn, true);
    elseif ($kind === 'products')  $r = notifCheckProducts($cn, true);
    elseif ($kind === 'ping') {
        // v8.37: پینگ آزمایشی — فاصلهٔ زمانی را نادیده می‌گیرد و
        // وضعیت را ذخیره نمی‌کند تا پینگ واقعی بعدی از دست نرود
        $pr = notifCronPing($cn, ['profiles' => []], true);
        $r = ['ok' => !empty($pr['ok']), 'found' => 1, 'total_seen' => 1,
              'sent' => $pr['delivery'] ?? [], 'sample' => $pr['message'] ?? ''];
        if (!empty($pr['error'])) { $r['ok'] = false; $r['error'] = $pr['error']; }
    }
    elseif ($kind === 'source') {
        // v8.30: از آخرین گزارش استخراج استفاده می‌کند تا پیام واقعی باشد
        $rep = null;
        foreach (glob(__DIR__ . '/extract_report_*.json') ?: [] as $f) {
            $d = json_decode((string)@file_get_contents($f), true);
            if (is_array($d) && (($d['price_up'] ?? 0) || ($d['price_down'] ?? 0)
                || ($d['no_price'] ?? 0) || ($d['gone_from_site'] ?? 0))) { $rep = $d; break; }
            if ($rep === null && is_array($d)) $rep = $d;
        }
        if ($rep === null) {
            $rep = ['price_up' => 1, 'price_down' => 1, 'no_price' => 1, 'gone_from_site' => 0,
                'changed_items' => [
                    ['title' => 'نمونه — کالای گران‌شده', 'old_price' => '100,000', 'new_price' => '130,000', 'dir' => 'up', 'pct' => 30],
                    ['title' => 'نمونه — کالای ارزان‌شده', 'old_price' => '80,000', 'new_price' => '60,000', 'dir' => 'down', 'pct' => -25]],
                'removed_items' => [['title' => 'نمونه — کالای ناموجود', 'reason' => 'ناموجود شد']],
                'new_items' => []];
        }
        // در حالت تست، هر دو نوع اعلان را صرف‌نظر از تنظیمات بفرست
        $cnTest = $cn;
        $cnTest['notif_events']['src_price'] = true;
        $cnTest['notif_events']['src_stock'] = true;
        $sr = notifSourceChanges($cnTest, $rep, 'تست');
        $r = ['ok' => !empty($sr['ok']), 'found' => (int)($sr['sent'] ?? 0),
              'total_seen' => (int)($rep['extracted'] ?? 0),
              'sent' => $sr['delivery'] ?? [],
              'sample' => '▲ گران: ' . (int)($sr['price_up'] ?? 0)
                        . ' | ▼ ارزان: ' . (int)($sr['price_down'] ?? 0)
                        . ' | 🚫 ناموجود: ' . (int)($sr['no_price'] ?? 0)];
        if (!empty($sr['nothing'])) $r['sample'] = 'تغییری برای گزارش نبود';
    }
    else { echo json_encode(['ok' => false, 'error' => 'نوع تست نامعتبر']); exit; }
    } catch (Throwable $__e) {
        /* v10.79 (93): خطایِ داخلی را نشان بده — نه پاسخِ خالی که
           مرورگر به‌عنوانِ «خطای شبکه» گزارش می‌کرد. */
        echo json_encode(['ok' => false, 'error' => 'خطای داخلی: ' . mb_substr($__e->getMessage(), 0, 200)], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $__outT = json_encode($r, JSON_UNESCAPED_UNICODE);
    echo ($__outT === false) ? '{"ok":false,"error":"ساختِ پاسخ ناموفق"}' : $__outT;
    exit;
}

/* =====================================================================
 *  v8.32: اندپوینت‌های مودال استعلام
 *  دکمه‌های استعلام حالا اول لیست را نشان می‌دهند، بعد کاربر تصمیم
 *  می‌گیرد چه چیزی به پیام‌رسان‌ها برود.
 * ===================================================================== */

/** لیست سفارش‌های غرفه — برای مودال (پشتیبانی از همهٔ غرفه‌های متصل) */
if (isset($_GET['bsl_orders_list'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cn = loadConnections();
    $shops = array_values(array_filter(bslAllShops($cn),
        fn($s) => trim((string)($s['token'] ?? '')) !== '' && (int)($s['vendor_id'] ?? 0) > 0));
    if (!$shops) {
        echo json_encode(['ok' => false, 'error' => 'تنظیمات باسلام ناقص است'], JSON_UNESCAPED_UNICODE); exit;
    }
    $wantShop = (int)($_GET['shop_id'] ?? 0);
    if ($wantShop > 0) {
        $shops = array_values(array_filter($shops, fn($s) => (int)($s['vendor_id'] ?? 0) === $wantShop));
        if (!$shops) {
            echo json_encode(['ok' => false, 'error' => 'غرفهٔ انتخاب‌شده یافت نشد'], JSON_UNESCAPED_UNICODE); exit;
        }
    }
    $per = min(30, max(5, (int)($_GET['per_page'] ?? 20)));   // سقف مستندات: ۳۰
    $filter = (string)($_GET['filter'] ?? 'all');
    $extra = [];
    if ($filter === 'unsent') $extra['statuses'] = bslUnsentStatuses();
    $cur = trim((string)($_GET['cursor'] ?? ''));
    if ($cur !== '') $extra['cursor'] = $cur;

    $netBsl = bslNetCfg($cn);
    $rows = [];
    $seenParcels = [];
    $shopErrors = [];
    $okShops = 0;
    $nextCursor = '';
    foreach ($shops as $sh) {
        $tk = trim((string)$sh['token']);
        $vid = (int)$sh['vendor_id'];
        $sName = trim((string)($sh['shop_name'] ?? ''));
        $r = bslFetchVendorParcels($tk, $vid, $per, $extra, $netBsl);
        if (empty($r['ok'])) {
            $shopErrors[] = ($sName !== '' ? $sName . ': ' : '')
                          . bslApiError($r, 'دریافت سفارش‌ها ناموفق', 'vendor-parcels', 'vendor.parcel.read');
            continue;
        }
        $okShops++;
        if (count($shops) === 1) $nextCursor = (string)($r['body']['next_cursor'] ?? '');
        foreach (($r['body']['data'] ?? []) as $o) {
            if (!is_array($o)) continue;
            $np = bslNormalizeParcel($o, $sName, $vid);
            $pid = (int)($np['parcel_id'] ?? 0);
            if ($pid > 0) {
                if (isset($seenParcels[$pid])) continue;
                $seenParcels[$pid] = true;
            }
            $rows[] = $np;
        }
    }
    if ($okShops === 0) {
        echo json_encode(['ok' => false,
            'error' => $shopErrors ? implode(' | ', $shopErrors) : 'دریافت سفارش‌ها ناموفق'],
            JSON_UNESCAPED_UNICODE); exit;
    }
    if (count($shops) > 1 && count($rows) > 1) {
        usort($rows, fn($a, $b) => strcmp((string)($b['created_at'] ?? ''), (string)($a['created_at'] ?? ''))
                                ?: ((int)($b['parcel_id'] ?? 0) <=> (int)($a['parcel_id'] ?? 0)));
    }
    $unsent = 0;
    foreach ($rows as $n) { if ($n['unsent']) $unsent++; }
    echo json_encode(['ok' => true, 'rows' => $rows, 'total' => count($rows), 'unsent' => $unsent,
        'filter' => $filter, 'next_cursor' => $nextCursor,
        'shops_queried' => count($shops), 'shops_ok' => $okShops, 'shop_errors' => $shopErrors],
        JSON_UNESCAPED_UNICODE);
    exit;
}

/** لیست گفتگوها — برای مودال */
if (isset($_GET['bsl_chats_list'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cn = loadConnections();
    $tk = trim((string)($cn['basalam']['token'] ?? ''));
    if ($tk === '') {
        echo json_encode(['ok' => false, 'error' => 'توکن باسلام تنظیم نشده'], JSON_UNESCAPED_UNICODE); exit;
    }
    $limit = min(50, max(5, (int)($_GET['limit'] ?? 20)));
    $filter = (string)($_GET['filter'] ?? 'all');
    $ep = 'chats?limit=' . $limit . '&order_by=updated_at';
    if ($filter === 'unseen') $ep .= '&filters=unseen';   // فیلتر رسمی مستندات

    $r = bslReqRead($tk, $ep);
    if (!$r['ok']) {
        echo json_encode(['ok' => false,
            'error' => bslApiError($r, 'دریافت گفتگوها ناموفق', 'chats', 'customer.chat.read')],
            JSON_UNESCAPED_UNICODE); exit;
    }
    $raw = $r['body']['data']['chats'] ?? ($r['body']['data'] ?? []);
    $rows = [];
    foreach ($raw as $c) { if (is_array($c)) $rows[] = bslNormalizeChat($c); }
    $unseen = 0;
    foreach ($rows as $n) { if ($n['unseen'] > 0) $unseen++; }
    echo json_encode(['ok' => true, 'rows' => $rows, 'total' => count($rows), 'unseen' => $unseen,
        'filter' => $filter], JSON_UNESCAPED_UNICODE);
    exit;
}

/**
 * ارسال موارد انتخاب‌شده به پیام‌رسان‌ها.
 * kind=orders|chats و ids=فهرست شناسه‌های جداشده با کاما.
 * اگر ids خالی باشد، همهٔ موارد «اقدام‌نشده» فرستاده می‌شوند.
 */
if (isset($_GET['bsl_notify_selected'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $GLOBALS['_s4ManualNotifSend'] = true;
    $cn = loadConnections();
    $why = notifPrereq($cn);
    if ($why !== null) { echo json_encode(['ok' => false, 'error' => $why], JSON_UNESCAPED_UNICODE); exit; }
    $tk = (string)$cn['basalam']['token'];
    $vid = (int)$cn['basalam']['vendor_id'];
    $kind = (string)($_GET['kind'] ?? '');
    $idsRaw = trim((string)($_GET['ids'] ?? ''));
    $want = $idsRaw === '' ? [] : array_filter(array_map('intval', explode(',', $idsRaw)));
    $digest = !empty($_GET['digest']);   // یک پیام خلاصه به‌جای چند پیام جدا

    if ($kind === 'orders') {
        $shopsOrd = array_values(array_filter(bslAllShops($cn),
            fn($s) => trim((string)($s['token'] ?? '')) !== '' && (int)($s['vendor_id'] ?? 0) > 0));
        if (!$shopsOrd) $shopsOrd = [['token' => $tk, 'vendor_id' => $vid, 'shop_name' => '']];
        $netBsl = bslNetCfg($cn);
        $picked = [];
        $seenP = [];
        $okAny = false;
        $lastErr = '';
        foreach ($shopsOrd as $shO) {
            $r = bslFetchVendorParcels((string)$shO['token'], (int)$shO['vendor_id'], 30, [], $netBsl);
            if (empty($r['ok'])) {
                $lastErr = bslApiError($r, 'دریافت سفارش‌ها ناموفق', 'vendor-parcels', 'vendor.parcel.read');
                continue;
            }
            $okAny = true;
            $sNameO = trim((string)($shO['shop_name'] ?? ''));
            foreach (($r['body']['data'] ?? []) as $o) {
                if (!is_array($o)) continue;
                $n = bslNormalizeParcel($o, $sNameO, (int)$shO['vendor_id']);
                $pidO = (int)($n['parcel_id'] ?? 0);
                if ($pidO > 0 && isset($seenP[$pidO])) continue;
                if ($want ? in_array($pidO, $want, true) : $n['unsent']) {
                    if ($pidO > 0) $seenP[$pidO] = true;
                    $picked[] = $n;
                }
            }
        }
        if (!$okAny) { echo json_encode(['ok' => false, 'error' => $lastErr ?: 'دریافت سفارش‌ها ناموفق'], JSON_UNESCAPED_UNICODE); exit; }
    } elseif ($kind === 'chats') {
        $r = bslReq($tk, 'GET', 'chats?limit=50&order_by=updated_at');
        if (!$r['ok']) { echo json_encode(['ok' => false,
            'error' => bslApiError($r, 'دریافت گفتگوها ناموفق', 'chats', 'customer.chat.read')],
            JSON_UNESCAPED_UNICODE); exit; }
        $raw = $r['body']['data']['chats'] ?? ($r['body']['data'] ?? []);
        $picked = [];
        foreach ($raw as $c) {
            if (!is_array($c)) continue;
            $n = bslNormalizeChat($c);
            if ($want ? in_array($n['chat_id'], $want, true) : $n['unseen'] > 0) $picked[] = $n;
        }
    } else { echo json_encode(['ok' => false, 'error' => 'نوع نامعتبر'], JSON_UNESCAPED_UNICODE); exit; }

    if (!$picked) {
        echo json_encode(['ok' => true, 'sent' => 0, 'delivery' => [],
            'note' => 'موردی برای ارسال نبود'], JSON_UNESCAPED_UNICODE); exit;
    }

    $delivery = []; $sent = 0;
    if ($digest) {
        // یک پیام فشرده — برای وقتی موارد زیاد است و نمی‌خواهیم پیام‌رسان پر شود
        if ($kind === 'orders') {
            $lines = ['📦 سفارش‌های ارسال‌نشده (' . count($picked) . ' مورد)'];
            $sum = 0;
            foreach ($picked as $n) {
                $sum += $n['amount'];
                $lines[] = '• #' . ($n['order_id'] ?: $n['parcel_id']) . ' — ' . $n['customer']
                         . ' — ' . number_format($n['amount']) . ' تومان — ' . $n['status'];
            }
            $lines[] = '━━━━━━━━━━';
            $lines[] = 'جمع: ' . number_format($sum) . ' تومان';
        } else {
            $tot = 0;
            foreach ($picked as $n) { $tot += $n['unseen']; }
            $lines = ['💬 پیام‌های خوانده‌نشده (' . count($picked) . ' گفتگو · ' . $tot . ' پیام)'];
            foreach ($picked as $n) {
                $lines[] = '• ' . $n['who'] . ($n['unseen'] > 0 ? ' (' . $n['unseen'] . ')' : '')
                         . ' — ' . mb_substr($n['text'], 0, 60);
            }
        }
        $delivery = notifSend($cn, implode("\n", $lines), 'remind');
        $sent = 1;
    } else {
        foreach ($picked as $n) {
            if ($kind === 'orders') {
                $msg = bslParcelMsg($n, '📦 سفارش ارسال‌نشده');
            } else {
                // v8.33: متن کامل پیام‌های مشتری، نه فقط آخرین پیام
                $body = bslFetchChatMessages($tk, $n['chat_id'], max(1, min(10, $n['unseen'] ?: 1)));
                $msg = bslChatMsg($n, '💬 پیام خوانده‌نشده', $body);
                $_mediaSel = bslChatCollectMedia($n, $body);
                $delivery = notifSend($cn, $msg, 'remind', $_mediaSel);
                $sent++;
                if ($sent >= 20) break;
                continue;
            }
            $delivery = notifSend($cn, $msg, 'remind');
            $sent++;
            if ($sent >= 20) break;   // سقف ایمنی برای جلوگیری از هرزنامه
        }
    }
    echo json_encode(['ok' => true, 'sent' => $sent, 'picked' => count($picked),
        'delivery' => $delivery, 'digest' => $digest], JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v10.470: سامانهٔ یکپارچهٔ مدیریت سفارشات (باسلام چندغرفه + ووکامرس)
 * ===================================================================== */

function s4OrderMgrNotesLoad(): array {
    if (!is_file(ORDERS_MGR_NOTES_FILE)) return [];
    $lfp = @fopen(ORDERS_MGR_NOTES_FILE . '.lock', 'c');
    if ($lfp) @flock($lfp, LOCK_SH);
    $d = json_decode((string)@file_get_contents(ORDERS_MGR_NOTES_FILE), true);
    if ($lfp) { @flock($lfp, LOCK_UN); @fclose($lfp); }
    return is_array($d) ? $d : [];
}

function s4OrderMgrNotesSaveOne(string $key, array $patch): array {
    $lfp = @fopen(ORDERS_MGR_NOTES_FILE . '.lock', 'c');
    if ($lfp) @flock($lfp, LOCK_EX);
    $entry = [];
    try {
        $all = is_file(ORDERS_MGR_NOTES_FILE) ? json_decode((string)@file_get_contents(ORDERS_MGR_NOTES_FILE), true) : [];
        if (!is_array($all)) $all = [];
        $cur = is_array($all[$key] ?? null) ? $all[$key] : [];
        foreach ($patch as $k => $v) $cur[$k] = $v;
        $cur['updated_at'] = time();
        $all[$key] = $cur;
        if (count($all) > 5000) {
            uasort($all, fn($a, $b) => (int)($b['updated_at'] ?? 0) <=> (int)($a['updated_at'] ?? 0));
            $all = array_slice($all, 0, 5000, true);
        }
        @file_put_contents(ORDERS_MGR_NOTES_FILE, json_encode($all, JSON_UNESCAPED_UNICODE), LOCK_EX);
        $entry = $cur;
    } finally {
        if ($lfp) { @flock($lfp, LOCK_UN); @fclose($lfp); }
    }
    return $entry;
}

function s4OrderMgrWooStatuses(): array {
    return [
        'pending'    => 'در انتظار پرداخت',
        'processing' => 'در حال انجام (آماده ارسال)',
        'on-hold'    => 'در انتظار بررسی',
        'completed'  => 'تکمیل شده',
        'cancelled'  => 'لغو شده',
        'refunded'   => 'مسترد شده',
        'failed'     => 'ناموفق',
    ];
}

function s4OrderMgrRialToToman(int $val): int {
    if ($val <= 0) return 0;
    return ($val >= 10000 && ($val % 10) === 0) ? intdiv($val, 10) : $val;
}

function s4OrderMgrNormalizeBslFull(array $o, string $shopName = '', int $vendorId = 0, array $notesMap = []): array {
    $base = bslNormalizeParcel($o, $shopName, $vendorId);
    $pid = (int)($base['parcel_id'] ?? 0);
    $vid = (int)($base['vendor_id'] ?? $vendorId);
    $cust = is_array($o['order']['customer'] ?? null) ? $o['order']['customer'] : (is_array($o['customer'] ?? null) ? $o['customer'] : []);
    $rec  = is_array($cust['recipient'] ?? null) ? $cust['recipient'] : [];
    $usr  = is_array($cust['user'] ?? null) ? $cust['user'] : [];
    $cityObj = is_array($cust['city'] ?? null) ? $cust['city'] : (is_array($rec['city'] ?? null) ? $rec['city'] : []);
    $provObj = is_array($cityObj['parent'] ?? null) ? $cityObj['parent'] : (is_array($cust['province'] ?? null) ? $cust['province'] : []);

    $phone = '';
    foreach ([$rec['mobile'] ?? '', $rec['phone'] ?? '', $usr['mobile'] ?? '', $cust['mobile'] ?? '', $cust['phone'] ?? '', $o['recipient_mobile'] ?? ''] as $candPh) {
        if (is_scalar($candPh) && trim((string)$candPh) !== '') { $phone = trim((string)$candPh); break; }
    }
    $province = trim((string)($provObj['title'] ?? ($provObj['name'] ?? ($rec['province'] ?? ''))));
    $city     = trim((string)($cityObj['title'] ?? ($cityObj['name'] ?? ($rec['city_title'] ?? ''))));
    $address  = '';
    foreach ([$rec['postal_address'] ?? '', $rec['address'] ?? '', $cust['postal_address'] ?? '', $cust['address'] ?? '', $o['address'] ?? ''] as $candAdr) {
        if (is_scalar($candAdr) && trim((string)$candAdr) !== '') { $address = trim((string)$candAdr); break; }
    }
    $postalCode = '';
    foreach ([$rec['postal_code'] ?? '', $cust['postal_code'] ?? '', $o['postal_code'] ?? ''] as $candZip) {
        if (is_scalar($candZip) && trim((string)$candZip) !== '') { $postalCode = trim((string)$candZip); break; }
    }
    $shipMethod = '';
    foreach ([
        $o['shipping_method']['title'] ?? '',
        $o['post_type']['title'] ?? '',
        $o['delivery_method']['title'] ?? '',
        is_string($o['shipping_method'] ?? null) ? $o['shipping_method'] : '',
    ] as $candSh) {
        if (is_scalar($candSh) && trim((string)$candSh) !== '') { $shipMethod = trim((string)$candSh); break; }
    }
    $tracking = '';
    foreach ([
        $o['post_receipt']['tracking_code'] ?? '',
        $o['shipping']['tracking_code'] ?? '',
        $o['tracking_code'] ?? '',
        $o['barcode'] ?? '',
    ] as $candTr) {
        if (is_scalar($candTr) && trim((string)$candTr) !== '') { $tracking = trim((string)$candTr); break; }
    }
    $shipCostRaw = (int)($o['shipping_cost'] ?? ($o['send_price'] ?? 0));
    $shipCost = s4OrderMgrRialToToman($shipCostRaw);

    $richItems = [];
    foreach (($o['items'] ?? []) as $it) {
        if (!is_array($it)) continue;
        $qty = max(1, (int)($it['quantity'] ?? 1));
        $prd = is_array($it['product'] ?? null) ? $it['product'] : [];
        $itTitle = trim((string)($it['title'] ?? ($prd['title'] ?? ($prd['name'] ?? ''))));
        $itPriceRaw = (int)($it['price'] ?? 0);
        $unitToman = s4OrderMgrRialToToman($itPriceRaw);
        $img = '';
        foreach ([
            $prd['photo']['small'] ?? '',
            $prd['photo']['medium'] ?? '',
            $prd['photo']['original'] ?? '',
            $prd['photos'][0]['small'] ?? '',
            $it['photo']['small'] ?? '',
            is_string($prd['photo'] ?? null) ? $prd['photo'] : '',
        ] as $candImg) {
            if (is_string($candImg) && strncmp($candImg, 'http', 4) === 0) { $img = $candImg; break; }
        }
        $varTitle = '';
        if (is_array($it['variation'] ?? null)) {
            $vp = [];
            foreach (($it['variation']['properties'] ?? []) as $prp) {
                if (is_array($prp)) {
                    $pt = trim((string)($prp['property']['title'] ?? '') . ' ' . (string)($prp['value']['title'] ?? ($prp['value'] ?? '')));
                    if ($pt !== '') $vp[] = $pt;
                }
            }
            $varTitle = $vp ? implode(' · ', $vp) : trim((string)($it['variation']['title'] ?? ''));
        }
        $richItems[] = [
            'product_id' => (int)($prd['id'] ?? ($it['product_id'] ?? 0)),
            'title'      => $itTitle !== '' ? $itTitle : 'کالا',
            'variant'    => $varTitle,
            'sku'        => trim((string)($it['sku'] ?? ($prd['sku'] ?? ''))),
            'qty'        => $qty,
            'unit_price' => $unitToman,
            'total'      => $unitToman * $qty,
            'image'      => $img,
        ];
    }
    $noteKey = 'bsl:' . $vid . ':' . $pid;
    $localMeta = is_array($notesMap[$noteKey] ?? null) ? $notesMap[$noteKey] : [];
    if ($tracking === '' && !empty($localMeta['tracking_code'])) $tracking = (string)$localMeta['tracking_code'];

    return array_merge($base, [
        'channel'         => 'bsl',
        'uid'             => $noteKey,
        'display_number'  => (string)($base['order_id'] ?: $pid),
        'phone'           => $phone,
        'province'        => $province,
        'city'            => $city,
        'address'         => $address,
        'postal_code'     => $postalCode,
        'shipping_method' => $shipMethod,
        'shipping_cost'   => $shipCost,
        'tracking_code'   => $tracking,
        'carrier'         => (string)($localMeta['carrier'] ?? ''),
        'customer_note'   => trim((string)($o['description'] ?? ($o['note'] ?? ($cust['description'] ?? '')))),
        'admin_note'      => (string)($localMeta['admin_note'] ?? ''),
        'buyer_user_id'   => (int)($usr['id'] ?? 0),
        'items'           => $richItems ?: $base['items'],
        'items_count'     => count($richItems ?: $base['items']),
        'panel_url'       => $pid > 0 ? ('https://vendor.basalam.com/orders/' . $pid) : 'https://vendor.basalam.com/orders',
    ]);
}

function s4OrderMgrMoneyFromWoo($raw, string $currency): int {
    $num = (int)round((float)$raw);
    if ($num <= 0) return 0;
    $cur = strtoupper(trim($currency));
    if ($cur === 'IRR' || $cur === 'RIAL') return intdiv($num, 10);
    if ($cur === 'IRHT') return $num * 1000;
    return $num;
}

function s4OrderMgrNormalizeWoo(array $o, string $storeUrl = '', array $notesMap = []): array {
    $oid = (int)($o['id'] ?? 0);
    $stSlug = strtolower(trim((string)($o['status'] ?? 'pending')));
    if (strncmp($stSlug, 'wc-', 3) === 0) $stSlug = substr($stSlug, 3);
    $stMap = s4OrderMgrWooStatuses();
    $stLabel = $stMap[$stSlug] ?? $stSlug;
    $cur = (string)($o['currency'] ?? 'IRT');

    $bill = is_array($o['billing'] ?? null) ? $o['billing'] : [];
    $ship = is_array($o['shipping'] ?? null) ? $o['shipping'] : [];
    $custName = trim(trim((string)($bill['first_name'] ?? '')) . ' ' . trim((string)($bill['last_name'] ?? '')));
    if ($custName === '') $custName = trim(trim((string)($ship['first_name'] ?? '')) . ' ' . trim((string)($ship['last_name'] ?? '')));
    if ($custName === '') $custName = trim((string)($bill['company'] ?? '')) ?: 'مشتری مهمان';

    $phone = trim((string)($bill['phone'] ?? ($ship['phone'] ?? '')));
    $email = trim((string)($bill['email'] ?? ''));
    $prov  = trim((string)($ship['state'] ?? ($bill['state'] ?? '')));
    $city  = trim((string)($ship['city'] ?? ($bill['city'] ?? '')));
    $addr1 = trim((string)($ship['address_1'] ?? ($bill['address_1'] ?? '')));
    $addr2 = trim((string)($ship['address_2'] ?? ($bill['address_2'] ?? '')));
    $address = trim($addr1 . ($addr2 !== '' ? '، ' . $addr2 : ''));
    $postal  = trim((string)($ship['postcode'] ?? ($bill['postcode'] ?? '')));

    $shipMethod = '';
    if (!empty($o['shipping_lines']) && is_array($o['shipping_lines'])) {
        $smParts = [];
        foreach ($o['shipping_lines'] as $sl) {
            if (is_array($sl) && trim((string)($sl['method_title'] ?? '')) !== '') $smParts[] = trim((string)$sl['method_title']);
        }
        $shipMethod = implode(' + ', $smParts);
    }

    $tracking = '';
    $carrier = '';
    if (!empty($o['meta_data']) && is_array($o['meta_data'])) {
        foreach ($o['meta_data'] as $md) {
            if (!is_array($md)) continue;
            $mk = (string)($md['key'] ?? '');
            $mv = $md['value'] ?? '';
            if (in_array($mk, ['_tracking_number', '_shipping_tracking_code', 'tracking_code', '_post_barcode', 'post_tracking_code'], true) && is_scalar($mv) && trim((string)$mv) !== '') {
                $tracking = trim((string)$mv);
            } elseif ($mk === '_shipping_tracking_carrier' && is_scalar($mv) && trim((string)$mv) !== '') {
                $carrier = trim((string)$mv);
            } elseif ($mk === '_wc_shipment_tracking_items' && is_array($mv) && !empty($mv[0]['tracking_number'])) {
                $tracking = trim((string)$mv[0]['tracking_number']);
                if ($carrier === '' && !empty($mv[0]['tracking_provider'])) $carrier = trim((string)$mv[0]['tracking_provider']);
            }
        }
    }

    $items = [];
    foreach (($o['line_items'] ?? []) as $li) {
        if (!is_array($li)) continue;
        $qty = max(1, (int)($li['quantity'] ?? 1));
        $lineTotal = s4OrderMgrMoneyFromWoo($li['total'] ?? 0, $cur);
        $unitPrice = $qty > 0 ? intdiv($lineTotal, $qty) : s4OrderMgrMoneyFromWoo($li['price'] ?? 0, $cur);
        $img = '';
        if (is_array($li['image'] ?? null) && !empty($li['image']['src']) && strncmp((string)$li['image']['src'], 'http', 4) === 0) {
            $img = (string)$li['image']['src'];
        }
        $varParts = [];
        foreach (($li['meta_data'] ?? []) as $lmd) {
            if (!is_array($lmd)) continue;
            $lk = trim((string)($lmd['display_key'] ?? ($lmd['key'] ?? '')));
            $lv = is_scalar($lmd['display_value'] ?? ($lmd['value'] ?? null)) ? trim(strip_tags((string)($lmd['display_value'] ?? $lmd['value']))) : '';
            if ($lk !== '' && $lv !== '' && $lk[0] !== '_') $varParts[] = $lk . ': ' . $lv;
        }
        $items[] = [
            'product_id' => (int)($li['product_id'] ?? 0),
            'variation_id' => (int)($li['variation_id'] ?? 0),
            'title'      => trim((string)($li['name'] ?? 'کالا')),
            'variant'    => implode(' · ', array_slice($varParts, 0, 4)),
            'sku'        => trim((string)($li['sku'] ?? '')),
            'qty'        => $qty,
            'unit_price' => $unitPrice,
            'total'      => $lineTotal,
            'image'      => $img,
        ];
    }

    $noteKey = 'woo:' . $oid;
    $localMeta = is_array($notesMap[$noteKey] ?? null) ? $notesMap[$noteKey] : [];
    if ($tracking === '' && !empty($localMeta['tracking_code'])) $tracking = (string)$localMeta['tracking_code'];
    if ($carrier === '' && !empty($localMeta['carrier'])) $carrier = (string)$localMeta['carrier'];

    $createdAt = trim((string)($o['date_created'] ?? ($o['date_created_gmt'] ?? '')));
    $adminUrl = $storeUrl !== '' && $oid > 0 ? (rtrim($storeUrl, '/') . '/wp-admin/post.php?post=' . $oid . '&action=edit') : '';

    return [
        'channel'         => 'woo',
        'uid'             => $noteKey,
        'order_id'        => $oid,
        'parcel_id'       => 0,
        'display_number'  => trim((string)($o['number'] ?? (string)$oid)),
        'customer'        => $custName,
        'phone'           => $phone,
        'email'           => $email,
        'province'        => $prov,
        'city'            => $city,
        'address'         => $address,
        'postal_code'     => $postal,
        'amount'          => s4OrderMgrMoneyFromWoo($o['total'] ?? 0, $cur),
        'shipping_cost'   => s4OrderMgrMoneyFromWoo($o['shipping_total'] ?? 0, $cur),
        'discount_total'  => s4OrderMgrMoneyFromWoo($o['discount_total'] ?? 0, $cur),
        'currency_raw'    => $cur,
        'payment_method'  => trim((string)($o['payment_method_title'] ?? ($o['payment_method'] ?? ''))),
        'shipping_method' => $shipMethod,
        'tracking_code'   => $tracking,
        'carrier'         => $carrier,
        'status_id'       => $stSlug,
        'status'          => $stLabel,
        'unsent'          => in_array($stSlug, ['processing', 'on-hold'], true),
        'created_at'      => $createdAt,
        'send_before'     => '',
        'customer_note'   => trim((string)($o['customer_note'] ?? '')),
        'admin_note'      => (string)($localMeta['admin_note'] ?? ''),
        'items'           => $items,
        'items_count'     => count($items),
        'shop_name'       => 'ووکامرس',
        'vendor_id'       => 0,
        'panel_url'       => $adminUrl,
    ];
}

function s4OrderMgrFetchWooList(array $cn, int $page = 1, int $perPage = 20, string $status = 'any', string $search = '', array $notesMap = []): array {
    $w = is_array($cn['woocommerce'] ?? null) ? $cn['woocommerce'] : [];
    $storeUrl = rtrim(trim((string)($w['store_url'] ?? '')), '/');
    $ck = trim((string)($w['consumer_key'] ?? ''));
    $cs = trim((string)($w['consumer_secret'] ?? ''));
    $per = min(50, max(5, $perPage));
    $pg  = max(1, $page);
    $stClean = strtolower(trim($status));
    $validSt = array_keys(s4OrderMgrWooStatuses());
    if ($stClean === '' || $stClean === 'all') $stClean = 'any';
    elseif ($stClean === 'unsent') $stClean = 'processing,on-hold';
    elseif (!in_array($stClean, $validSt, true)) $stClean = 'any';

    if ($storeUrl !== '' && $ck !== '' && $cs !== '') {
        $qp = ['per_page=' . $per, 'page=' . $pg, 'orderby=date', 'order=desc'];
        if ($stClean !== 'any') $qp[] = 'status=' . rawurlencode($stClean);
        else $qp[] = 'status=any';
        if ($search !== '') $qp[] = 'search=' . rawurlencode($search);
        $r = wooReq($storeUrl, $ck, $cs, 'GET', 'orders?' . implode('&', $qp), null, 30);
        if (!empty($r['ok']) && is_array($r['body'])) {
            $rows = [];
            foreach ($r['body'] as $wo) {
                if (is_array($wo)) $rows[] = s4OrderMgrNormalizeWoo($wo, $storeUrl, $notesMap);
            }
            return ['ok' => true, 'via' => 'api', 'rows' => $rows, 'has_more' => count($rows) >= $per, 'page' => $pg];
        }
        $apiErr = 'خطای API ووکامرس (' . (int)($r['code'] ?? 0) . ')'
                . (!empty($r['body']['message']) ? ': ' . mb_substr((string)$r['body']['message'], 0, 140) : (!empty($r['error']) ? ': ' . $r['error'] : ''));
        if (!function_exists('wc_get_orders')) {
            return ['ok' => false, 'configured' => true, 'error' => $apiErr, 'rows' => []];
        }
    }

    if (function_exists('wc_get_orders')) {
        $args = ['limit' => $per, 'page' => $pg, 'orderby' => 'date', 'order' => 'DESC', 'type' => 'shop_order'];
        if ($stClean !== 'any') $args['status'] = explode(',', $stClean);
        if ($search !== '') $args['s'] = $search;
        $objs = @wc_get_orders($args);
        if (is_array($objs)) {
            $rows = [];
            foreach ($objs as $obj) {
                if (!is_object($obj) || !method_exists($obj, 'get_data')) continue;
                $d = $obj->get_data();
                $d['number'] = method_exists($obj, 'get_order_number') ? (string)$obj->get_order_number() : (string)($d['id'] ?? '');
                $d['date_created'] = isset($d['date_created']) && is_object($d['date_created']) && method_exists($d['date_created'], 'date')
                    ? $d['date_created']->date('c') : '';
                $d['line_items'] = [];
                if (method_exists($obj, 'get_items')) {
                    foreach ($obj->get_items() as $itemObj) {
                        if (!is_object($itemObj) || !method_exists($itemObj, 'get_data')) continue;
                        $idD = $itemObj->get_data();
                        $d['line_items'][] = [
                            'product_id'   => (int)($idD['product_id'] ?? 0),
                            'variation_id' => (int)($idD['variation_id'] ?? 0),
                            'name'         => (string)($idD['name'] ?? ''),
                            'quantity'     => (int)($idD['quantity'] ?? 1),
                            'total'        => (string)($idD['total'] ?? '0'),
                        ];
                    }
                }
                $rows[] = s4OrderMgrNormalizeWoo($d, $storeUrl, $notesMap);
            }
            return ['ok' => true, 'via' => 'direct', 'rows' => $rows, 'has_more' => count($rows) >= $per, 'page' => $pg];
        }
    }

    return ['ok' => false, 'configured' => false, 'error' => 'اتصال ووکامرس تنظیم نشده است (آدرس فروشگاه و کلیدهای Consumer Key/Secret را در بخش ووکامرس وارد کنید)', 'rows' => []];
}

function s4OrderMgrFetchBslDetail(string $tk, int $parcelId, string $shopName, int $vid, array $notesMap, ?array $net = null): array {
    if ($parcelId <= 0 || trim($tk) === '') return ['ok' => false, 'error' => 'پارامتر نامعتبر'];
    $ep = 'vendor-parcels/' . $parcelId;
    $r = bslReqRead($tk, $ep);
    if (empty($r['ok']) && in_array((int)($r['code'] ?? 0), [0, 403, 404, 500, 502, 503, 504], true)) {
        if ($net === null) $net = bslNetCfg();
        $fbUrl = 'https://order-processing.basalam.com/v3/' . $ep;
        foreach (bslNetModes($net) as $m) {
            $ch = curl_init();
            curl_setopt_array($ch, bslCurlOpts($fbUrl, $tk, 'GET', null, false, $net, $m));
            $raw = curl_exec($ch);
            $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
            $err = curl_error($ch);
            curl_close($ch);
            if ($code >= 200 && $code < 300) {
                $r = ['ok' => true, 'code' => $code, 'body' => json_decode((string)$raw, true), 'raw' => $raw, 'error' => ''];
                break;
            }
        }
    }
    if (!empty($r['ok']) && is_array($r['body'])) {
        $obj = is_array($r['body']['data'] ?? null) && isset($r['body']['data']['id']) ? $r['body']['data'] : $r['body'];
        if (isset($obj['id'])) {
            return ['ok' => true, 'order' => s4OrderMgrNormalizeBslFull($obj, $shopName, $vid, $notesMap)];
        }
    }
    $listR = bslFetchVendorParcels($tk, $vid, 30, [], $net);
    if (!empty($listR['ok'])) {
        foreach (($listR['body']['data'] ?? []) as $cand) {
            if (is_array($cand) && (int)($cand['id'] ?? 0) === $parcelId) {
                return ['ok' => true, 'order' => s4OrderMgrNormalizeBslFull($cand, $shopName, $vid, $notesMap)];
            }
        }
    }
    return ['ok' => false, 'error' => bslApiError($r, 'دریافت جزئیات مرسوله ناموفق', $ep, 'vendor.parcel.read')];
}

if (isset($_GET['orders_mgr_api']) || isset($_POST['orders_mgr_api'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $actOm = trim((string)($_POST['orders_mgr_api'] ?? $_GET['orders_mgr_api'] ?? 'list'));
    $cnOm = loadConnections();
    $notesMapOm = s4OrderMgrNotesLoad();
    $bslShopsOm = array_values(array_filter(bslAllShops($cnOm),
        fn($s) => trim((string)($s['token'] ?? '')) !== '' && (int)($s['vendor_id'] ?? 0) > 0));
    $wCfgOm = is_array($cnOm['woocommerce'] ?? null) ? $cnOm['woocommerce'] : [];
    $hasWooCfgOm = (trim((string)($wCfgOm['store_url'] ?? '')) !== '' && trim((string)($wCfgOm['consumer_key'] ?? '')) !== '' && trim((string)($wCfgOm['consumer_secret'] ?? '')) !== '')
                || function_exists('wc_get_orders');

    if ($actOm === 'list') {
        $chanOm   = strtolower(trim((string)($_GET['channel'] ?? 'all')));
        if (!in_array($chanOm, ['all', 'bsl', 'woo'], true)) $chanOm = 'all';
        $filterOm = trim((string)($_GET['status'] ?? 'all'));
        $searchOm = trim((string)($_GET['q'] ?? ''));
        $shopIdOm = (int)($_GET['shop_id'] ?? 0);
        $perOm    = min(30, max(5, (int)($_GET['per_page'] ?? 20)));
        $pageOm   = max(1, (int)($_GET['page'] ?? 1));
        $cursorOm = trim((string)($_GET['cursor'] ?? ''));

        $rowsOm = [];
        $errorsOm = [];
        $bslNextCurOm = '';
        $wooHasMoreOm = false;
        $bslCountOm = 0; $wooCountOm = 0; $bslUnsentOm = 0; $wooUnsentOm = 0;

        if (($chanOm === 'all' || $chanOm === 'bsl') && $bslShopsOm) {
            $qShops = $bslShopsOm;
            if ($shopIdOm > 0) {
                $qShops = array_values(array_filter($qShops, fn($s) => (int)($s['vendor_id'] ?? 0) === $shopIdOm));
            }
            $extraBsl = [];
            if ($filterOm === 'unsent') $extraBsl['statuses'] = bslUnsentStatuses();
            elseif (ctype_digit($filterOm) && (int)$filterOm > 0) $extraBsl['statuses'] = [(int)$filterOm];
            if ($cursorOm !== '') $extraBsl['cursor'] = $cursorOm;
            $netBslOm = bslNetCfg($cnOm);
            $seenPidOm = [];
            foreach ($qShops as $shOm) {
                $rB = bslFetchVendorParcels((string)$shOm['token'], (int)$shOm['vendor_id'], $perOm, $extraBsl, $netBslOm);
                if (empty($rB['ok'])) {
                    $errorsOm[] = ((string)$shOm['shop_name'] !== '' ? $shOm['shop_name'] . ': ' : 'باسلام: ')
                                . bslApiError($rB, 'دریافت سفارش‌ها ناموفق', 'vendor-parcels', 'vendor.parcel.read');
                    continue;
                }
                if (count($qShops) === 1) $bslNextCurOm = (string)($rB['body']['next_cursor'] ?? '');
                foreach (($rB['body']['data'] ?? []) as $rawP) {
                    if (!is_array($rawP)) continue;
                    $np = s4OrderMgrNormalizeBslFull($rawP, (string)($shOm['shop_name'] ?? ''), (int)$shOm['vendor_id'], $notesMapOm);
                    $pid = (int)($np['parcel_id'] ?? 0);
                    if ($pid > 0) {
                        if (isset($seenPidOm[$pid])) continue;
                        $seenPidOm[$pid] = true;
                    }
                    if ($filterOm === 'problem' && !in_array((int)$np['status_id'], [5017, 3572, 3740, 4633, 5075, 3233, 6440], true)) continue;
                    if ($searchOm !== '') {
                        $hay = implode(' ', [
                            (string)$np['parcel_id'], (string)$np['order_id'], (string)$np['customer'],
                            (string)$np['phone'], (string)$np['city'], (string)$np['shop_name'], (string)$np['tracking_code'],
                            implode(' ', array_map(fn($x) => (string)($x['title'] ?? ''), (array)$np['items'])),
                        ]);
                        if (mb_stripos($hay, $searchOm) === false) continue;
                    }
                    $bslCountOm++;
                    if (!empty($np['unsent'])) $bslUnsentOm++;
                    $rowsOm[] = $np;
                }
            }
        } elseif ($chanOm === 'bsl' && !$bslShopsOm) {
            $errorsOm[] = 'هیچ غرفهٔ متصلی در باسلام یافت نشد.';
        }

        if ($chanOm === 'all' || $chanOm === 'woo') {
            if ($hasWooCfgOm) {
                $wooFilter = $chanOm === 'all' && ctype_digit($filterOm) ? 'any' : $filterOm;
                $wRes = s4OrderMgrFetchWooList($cnOm, $pageOm, $perOm, $wooFilter, $searchOm, $notesMapOm);
                if (!empty($wRes['ok'])) {
                    $wooHasMoreOm = !empty($wRes['has_more']);
                    foreach ($wRes['rows'] as $wr) {
                        $wooCountOm++;
                        if (!empty($wr['unsent'])) $wooUnsentOm++;
                        $rowsOm[] = $wr;
                    }
                } else {
                    $errorsOm[] = (string)($wRes['error'] ?? 'دریافت سفارش‌های ووکامرس ناموفق');
                }
            } elseif ($chanOm === 'woo') {
                $errorsOm[] = 'اتصال ووکامرس تنظیم نشده است (آدرس سایت و کلیدهای API را در زیرمنوی ووکامرس وارد کنید).';
            }
        }

        if (count($rowsOm) > 1) {
            usort($rowsOm, function ($a, $b) {
                $ta = strtotime((string)($a['created_at'] ?? '')) ?: 0;
                $tb = strtotime((string)($b['created_at'] ?? '')) ?: 0;
                if ($ta !== $tb) return $tb <=> $ta;
                return strcmp((string)($b['display_number'] ?? ''), (string)($a['display_number'] ?? ''));
            });
        }

        $sumToman = 0;
        foreach ($rowsOm as $rw) $sumToman += (int)($rw['amount'] ?? 0);
        $shopsMeta = array_map(fn($s) => [
            'vendor_id' => (int)$s['vendor_id'],
            'shop_name' => (string)$s['shop_name'],
            'is_default' => !empty($s['is_default']),
        ], $bslShopsOm);

        echo json_encode([
            'ok'              => true,
            'channel'         => $chanOm,
            'rows'            => $rowsOm,
            'total'           => count($rowsOm),
            'unsent'          => $bslUnsentOm + $wooUnsentOm,
            'bsl_count'       => $bslCountOm,
            'woo_count'       => $wooCountOm,
            'bsl_unsent'      => $bslUnsentOm,
            'woo_unsent'      => $wooUnsentOm,
            'sum_toman'       => $sumToman,
            'bsl_shops'       => $shopsMeta,
            'woo_configured'  => $hasWooCfgOm,
            'bsl_next_cursor' => $bslNextCurOm,
            'woo_page'        => $pageOm,
            'woo_has_more'    => $wooHasMoreOm,
            'bsl_statuses'    => bslParcelStatuses(),
            'woo_statuses'    => s4OrderMgrWooStatuses(),
            'errors'          => $errorsOm,
        ], JSON_UNESCAPED_UNICODE);
        exit;
    }

    if ($actOm === 'detail') {
        $chDet = strtolower(trim((string)($_GET['channel'] ?? 'bsl')));
        if ($chDet === 'woo') {
            $oid = (int)($_GET['order_id'] ?? 0);
            if ($oid <= 0) { echo json_encode(['ok' => false, 'error' => 'شناسهٔ سفارش نامعتبر است'], JSON_UNESCAPED_UNICODE); exit; }
            $storeUrl = rtrim(trim((string)($wCfgOm['store_url'] ?? '')), '/');
            $ck = trim((string)($wCfgOm['consumer_key'] ?? ''));
            $cs = trim((string)($wCfgOm['consumer_secret'] ?? ''));
            if ($storeUrl !== '' && $ck !== '' && $cs !== '') {
                $rO = wooReq($storeUrl, $ck, $cs, 'GET', 'orders/' . $oid, null, 25);
                if (empty($rO['ok']) || !is_array($rO['body'])) {
                    echo json_encode(['ok' => false, 'error' => 'خطا در خواندن سفارش ووکامرس (' . (int)($rO['code'] ?? 0) . ')'], JSON_UNESCAPED_UNICODE); exit;
                }
                $ordNorm = s4OrderMgrNormalizeWoo($rO['body'], $storeUrl, $notesMapOm);
                $rNotes = wooReq($storeUrl, $ck, $cs, 'GET', 'orders/' . $oid . '/notes?per_page=20', null, 15);
                $notesArr = [];
                if (!empty($rNotes['ok']) && is_array($rNotes['body'])) {
                    foreach ($rNotes['body'] as $nt) {
                        if (!is_array($nt)) continue;
                        $notesArr[] = [
                            'id'            => (int)($nt['id'] ?? 0),
                            'note'          => trim(strip_tags((string)($nt['note'] ?? ''))),
                            'customer_note' => !empty($nt['customer_note']),
                            'author'        => trim((string)($nt['author'] ?? '')),
                            'date'          => (string)($nt['date_created'] ?? ''),
                        ];
                    }
                }
                $ordNorm['woo_notes'] = $notesArr;
                echo json_encode(['ok' => true, 'order' => $ordNorm], JSON_UNESCAPED_UNICODE); exit;
            }
            if (function_exists('wc_get_order')) {
                $obj = @wc_get_order($oid);
                if (is_object($obj) && method_exists($obj, 'get_data')) {
                    $d = $obj->get_data();
                    $d['number'] = method_exists($obj, 'get_order_number') ? (string)$obj->get_order_number() : (string)$oid;
                    $d['date_created'] = isset($d['date_created']) && is_object($d['date_created']) && method_exists($d['date_created'], 'date')
                        ? $d['date_created']->date('c') : '';
                    $d['line_items'] = [];
                    if (method_exists($obj, 'get_items')) {
                        foreach ($obj->get_items() as $itemObj) {
                            if (!is_object($itemObj) || !method_exists($itemObj, 'get_data')) continue;
                            $idD = $itemObj->get_data();
                            $d['line_items'][] = [
                                'product_id' => (int)($idD['product_id'] ?? 0),
                                'variation_id' => (int)($idD['variation_id'] ?? 0),
                                'name' => (string)($idD['name'] ?? ''),
                                'quantity' => (int)($idD['quantity'] ?? 1),
                                'total' => (string)($idD['total'] ?? '0'),
                            ];
                        }
                    }
                    $ordNorm = s4OrderMgrNormalizeWoo($d, $storeUrl, $notesMapOm);
                    $ordNorm['woo_notes'] = [];
                    echo json_encode(['ok' => true, 'order' => $ordNorm], JSON_UNESCAPED_UNICODE); exit;
                }
            }
            echo json_encode(['ok' => false, 'error' => 'اتصال ووکامرس در دسترس نیست'], JSON_UNESCAPED_UNICODE); exit;
        }

        $pid = (int)($_GET['parcel_id'] ?? 0);
        $vid = (int)($_GET['vendor_id'] ?? 0);
        $pickedShop = null;
        foreach ($bslShopsOm as $sh) {
            if ($vid > 0 && (int)$sh['vendor_id'] === $vid) { $pickedShop = $sh; break; }
        }
        if (!$pickedShop && $bslShopsOm) $pickedShop = $bslShopsOm[0];
        if (!$pickedShop) { echo json_encode(['ok' => false, 'error' => 'غرفهٔ باسلام یافت نشد'], JSON_UNESCAPED_UNICODE); exit; }
        $det = s4OrderMgrFetchBslDetail((string)$pickedShop['token'], $pid, (string)$pickedShop['shop_name'], (int)$pickedShop['vendor_id'], $notesMapOm, bslNetCfg($cnOm));
        echo json_encode($det, JSON_UNESCAPED_UNICODE);
        exit;
    }

    if ($actOm === 'woo_action') {
        $oid = (int)($_POST['order_id'] ?? 0);
        $subAct = trim((string)($_POST['sub_action'] ?? ''));
        if ($oid <= 0) { echo json_encode(['ok' => false, 'error' => 'شناسهٔ سفارش ووکامرس نامعتبر است'], JSON_UNESCAPED_UNICODE); exit; }
        $storeUrl = rtrim(trim((string)($wCfgOm['store_url'] ?? '')), '/');
        $ck = trim((string)($wCfgOm['consumer_key'] ?? ''));
        $cs = trim((string)($wCfgOm['consumer_secret'] ?? ''));
        $hasRest = ($storeUrl !== '' && $ck !== '' && $cs !== '');

        if ($subAct === 'update_status') {
            $newSt = strtolower(trim((string)($_POST['new_status'] ?? '')));
            if (!isset(s4OrderMgrWooStatuses()[$newSt])) {
                echo json_encode(['ok' => false, 'error' => 'وضعیت انتخابی نامعتبر است'], JSON_UNESCAPED_UNICODE); exit;
            }
            if ($hasRest) {
                $rUp = wooReq($storeUrl, $ck, $cs, 'PUT', 'orders/' . $oid, ['status' => $newSt], 25);
                if (!empty($rUp['ok']) && is_array($rUp['body'])) {
                    echo json_encode(['ok' => true, 'message' => 'وضعیت سفارش ووکامرس با موفقیت تغییر کرد', 'order' => s4OrderMgrNormalizeWoo($rUp['body'], $storeUrl, s4OrderMgrNotesLoad())], JSON_UNESCAPED_UNICODE); exit;
                }
                echo json_encode(['ok' => false, 'error' => 'خطا در تغییر وضعیت ووکامرس (' . (int)($rUp['code'] ?? 0) . ')'], JSON_UNESCAPED_UNICODE); exit;
            }
            if (function_exists('wc_get_order')) {
                $obj = @wc_get_order($oid);
                if (is_object($obj) && method_exists($obj, 'update_status')) {
                    $obj->update_status($newSt, 'تغییر وضعیت از پنل مدیریت سفارشات اسکرپر');
                    echo json_encode(['ok' => true, 'message' => 'وضعیت سفارش ووکامرس تغییر کرد'], JSON_UNESCAPED_UNICODE); exit;
                }
            }
            echo json_encode(['ok' => false, 'error' => 'اتصال ووکامرس تنظیم نشده است'], JSON_UNESCAPED_UNICODE); exit;
        }

        if ($subAct === 'save_tracking') {
            $trk = trim((string)($_POST['tracking_code'] ?? ''));
            $car = trim((string)($_POST['carrier'] ?? 'پست'));
            $adminNote = trim((string)($_POST['admin_note'] ?? ''));
            $notifyCust = !empty($_POST['notify_customer']);
            $markCompleted = !empty($_POST['mark_completed']);
            s4OrderMgrNotesSaveOne('woo:' . $oid, [
                'tracking_code' => $trk,
                'carrier'       => $car,
                'admin_note'    => $adminNote,
            ]);
            if ($hasRest) {
                $payloadUp = [
                    'meta_data' => [
                        ['key' => '_tracking_number', 'value' => $trk],
                        ['key' => '_shipping_tracking_code', 'value' => $trk],
                        ['key' => '_shipping_tracking_carrier', 'value' => $car],
                    ],
                ];
                if ($markCompleted) $payloadUp['status'] = 'completed';
                $rUp = wooReq($storeUrl, $ck, $cs, 'PUT', 'orders/' . $oid, $payloadUp, 25);
                if ($notifyCust && $trk !== '') {
                    $noteTxt = '📦 سفارش شما ارسال شد.' . "\n" . ($car !== '' ? 'روش ارسال: ' . $car . "\n" : '') . 'کد رهگیری مرسوله: ' . $trk;
                    wooReq($storeUrl, $ck, $cs, 'POST', 'orders/' . $oid . '/notes', ['note' => $noteTxt, 'customer_note' => true], 20);
                }
                echo json_encode(['ok' => true, 'api_synced' => !empty($rUp['ok']), 'message' => 'کد رهگیری و یادداشت با موفقیت ثبت شد'], JSON_UNESCAPED_UNICODE); exit;
            }
            if (function_exists('wc_get_order')) {
                $obj = @wc_get_order($oid);
                if (is_object($obj)) {
                    if (method_exists($obj, 'update_meta_data')) {
                        $obj->update_meta_data('_tracking_number', $trk);
                        $obj->update_meta_data('_shipping_tracking_code', $trk);
                        $obj->update_meta_data('_shipping_tracking_carrier', $car);
                    }
                    if ($markCompleted && method_exists($obj, 'set_status')) $obj->set_status('completed');
                    if (method_exists($obj, 'save')) $obj->save();
                    if ($notifyCust && $trk !== '' && method_exists($obj, 'add_order_note')) {
                        $obj->add_order_note('📦 کد رهگیری مرسوله: ' . $trk . ($car !== '' ? ' (' . $car . ')' : ''), 1);
                    }
                }
            }
            echo json_encode(['ok' => true, 'message' => 'کد رهگیری و یادداشت ذخیره شد'], JSON_UNESCAPED_UNICODE); exit;
        }

        if ($subAct === 'add_note') {
            $noteTxt = trim((string)($_POST['note'] ?? ''));
            $isCust = !empty($_POST['customer_note']);
            if ($noteTxt === '') { echo json_encode(['ok' => false, 'error' => 'متن یادداشت خالی است'], JSON_UNESCAPED_UNICODE); exit; }
            if ($hasRest) {
                $rNt = wooReq($storeUrl, $ck, $cs, 'POST', 'orders/' . $oid . '/notes', ['note' => $noteTxt, 'customer_note' => $isCust], 20);
                if (!empty($rNt['ok'])) {
                    echo json_encode(['ok' => true, 'message' => $isCust ? 'یادداشت برای مشتری ارسال و ثبت شد' : 'یادداشت خصوصی ثبت شد'], JSON_UNESCAPED_UNICODE); exit;
                }
                echo json_encode(['ok' => false, 'error' => 'ثبت یادداشت در ووکامرس ناموفق بود (' . (int)($rNt['code'] ?? 0) . ')'], JSON_UNESCAPED_UNICODE); exit;
            }
            if (function_exists('wc_get_order')) {
                $obj = @wc_get_order($oid);
                if (is_object($obj) && method_exists($obj, 'add_order_note')) {
                    $obj->add_order_note($noteTxt, $isCust ? 1 : 0);
                    echo json_encode(['ok' => true, 'message' => 'یادداشت ثبت شد'], JSON_UNESCAPED_UNICODE); exit;
                }
            }
            echo json_encode(['ok' => false, 'error' => 'اتصال ووکامرس تنظیم نشده است'], JSON_UNESCAPED_UNICODE); exit;
        }
        echo json_encode(['ok' => false, 'error' => 'عملیات ناشناخته'], JSON_UNESCAPED_UNICODE); exit;
    }

    if ($actOm === 'bsl_action') {
        $pid = (int)($_POST['parcel_id'] ?? 0);
        $vid = (int)($_POST['vendor_id'] ?? 0);
        $subAct = trim((string)($_POST['sub_action'] ?? ''));
        if ($pid <= 0) { echo json_encode(['ok' => false, 'error' => 'شناسهٔ مرسوله نامعتبر است'], JSON_UNESCAPED_UNICODE); exit; }
        $pickedShop = null;
        foreach ($bslShopsOm as $sh) {
            if ($vid > 0 && (int)$sh['vendor_id'] === $vid) { $pickedShop = $sh; break; }
        }
        if (!$pickedShop && $bslShopsOm) $pickedShop = $bslShopsOm[0];
        $vidActual = $pickedShop ? (int)$pickedShop['vendor_id'] : $vid;
        $tkActual  = $pickedShop ? (string)$pickedShop['token'] : '';

        if ($subAct === 'save_note') {
            $trk = trim((string)($_POST['tracking_code'] ?? ''));
            $car = trim((string)($_POST['carrier'] ?? ''));
            $adm = trim((string)($_POST['admin_note'] ?? ''));
            $saved = s4OrderMgrNotesSaveOne('bsl:' . $vidActual . ':' . $pid, [
                'tracking_code' => $trk,
                'carrier'       => $car,
                'admin_note'    => $adm,
            ]);
            echo json_encode(['ok' => true, 'message' => 'یادداشت و کد رهگیری در پروندهٔ مرسوله ذخیره شد', 'meta' => $saved], JSON_UNESCAPED_UNICODE); exit;
        }

        if ($subAct === 'set_preparation') {
            if ($tkActual === '') { echo json_encode(['ok' => false, 'error' => 'توکن غرفه یافت نشد'], JSON_UNESCAPED_UNICODE); exit; }
            $tried = [];
            foreach ([
                ['POST', 'vendor-parcels/' . $pid . '/set-preparation', []],
                ['POST', 'vendor-parcels/' . $pid . '/confirm', []],
                ['PATCH', 'vendor-parcels/' . $pid, ['status' => 3237]],
            ] as [$mth, $epTry, $bdTry]) {
                $rT = bslReq($tkActual, $mth, $epTry, $bdTry);
                $tried[] = $epTry . ':' . (int)($rT['code'] ?? 0);
                if (!empty($rT['ok'])) {
                    echo json_encode(['ok' => true, 'message' => 'مرسوله وارد وضعیت «در حال آماده‌سازی» شد'], JSON_UNESCAPED_UNICODE); exit;
                }
            }
            $lastErr = isset($rT) ? bslApiError($rT, 'تأیید آماده‌سازی ناموفق', 'vendor-parcels', 'vendor.parcel.write') : 'خطا در تغییر وضعیت';
            echo json_encode(['ok' => false, 'error' => $lastErr, 'tried' => $tried], JSON_UNESCAPED_UNICODE); exit;
        }

        if ($subAct === 'set_posted') {
            $trk = trim((string)($_POST['tracking_code'] ?? ''));
            $car = trim((string)($_POST['carrier'] ?? 'post'));
            $adm = trim((string)($_POST['admin_note'] ?? ''));
            if ($trk === '') { echo json_encode(['ok' => false, 'error' => 'کد رهگیری پستی الزامی است'], JSON_UNESCAPED_UNICODE); exit; }
            s4OrderMgrNotesSaveOne('bsl:' . $vidActual . ':' . $pid, [
                'tracking_code' => $trk,
                'carrier'       => $car,
                'admin_note'    => $adm,
            ]);
            if ($tkActual === '') {
                echo json_encode(['ok' => false, 'saved_locally' => true, 'error' => 'توکن غرفه یافت نشد (کد رهگیری محلی ذخیره شد)'], JSON_UNESCAPED_UNICODE); exit;
            }
            $shippingMethodMap = ['post' => 3197, 'pishtaz' => 3197, 'sefareshi' => 3198, 'tipax' => 3259, 'chapar' => 6102, 'courier' => 3258];
            $smCode = $shippingMethodMap[strtolower($car)] ?? 3197;
            $tried = [];
            foreach ([
                ['POST', 'vendor-parcels/' . $pid . '/set-posted', ['tracking_code' => $trk, 'shipping_method' => $smCode]],
                ['POST', 'vendor-parcels/' . $pid . '/post', ['tracking_code' => $trk, 'shipping_method' => $smCode]],
                ['PATCH', 'vendor-parcels/' . $pid, ['status' => 3238, 'tracking_code' => $trk]],
            ] as [$mth, $epTry, $bdTry]) {
                $rT = bslReq($tkActual, $mth, $epTry, $bdTry);
                $tried[] = $epTry . ':' . (int)($rT['code'] ?? 0);
                if (!empty($rT['ok'])) {
                    echo json_encode(['ok' => true, 'saved_locally' => true, 'message' => 'کد رهگیری در باسلام ثبت شد و مرسوله «ارسال‌شده» علامت خورد'], JSON_UNESCAPED_UNICODE); exit;
                }
            }
            $apiErr = isset($rT) ? bslApiError($rT, 'ثبت ارسال در API باسلام ناموفق', 'vendor-parcels/set-posted', 'vendor.parcel.write') : 'خطا';
            echo json_encode([
                'ok' => false,
                'saved_locally' => true,
                'error' => $apiErr . ' (کد رهگیری در پروندهٔ داخلی ذخیره شد؛ در صورت کمبود دسترسی vendor.parcel.write توکن، از پنل غرفه‌دار ثبت نهایی کنید)',
                'tried' => $tried,
            ], JSON_UNESCAPED_UNICODE);
            exit;
        }
        echo json_encode(['ok' => false, 'error' => 'عملیات ناشناخته'], JSON_UNESCAPED_UNICODE); exit;
    }

    if ($actOm === 'forward_msgr') {
        $GLOBALS['_s4ManualNotifSend'] = true;
        $hasMsgr = notifMessengerConfigured($cnOm, 'baleh')
                || notifMessengerConfigured($cnOm, 'rubika')
                || notifMessengerConfigured($cnOm, 'telegram');
        if (!$hasMsgr) {
            echo json_encode(['ok' => false, 'error' => 'هیچ پیام‌رسانی (تلگرام / بله / روبیکا) تنظیم نشده است'], JSON_UNESCAPED_UNICODE); exit;
        }
        $msgFw = trim((string)($_POST['message'] ?? ''));
        if ($msgFw === '') {
            echo json_encode(['ok' => false, 'error' => 'متن پیام خالی است'], JSON_UNESCAPED_UNICODE); exit;
        }
        $dlv = notifSend($cnOm, $msgFw, 'order');
        $anySent = in_array('sent', array_values($dlv), true);
        echo json_encode(['ok' => $anySent, 'delivery' => $dlv, 'error' => $anySent ? '' : 'ارسال به پیام‌رسان ناموفق بود'], JSON_UNESCAPED_UNICODE);
        exit;
    }

    echo json_encode(['ok' => false, 'error' => 'درخواست نامعتبر'], JSON_UNESCAPED_UNICODE);
    exit;
}

/** v10.79 (93): Resolve با DoH — همان رزولورِ موجودِ بخشِ هوش مصنوعی */
function msgrResolveDoH(string $host): array {
    $cn = loadConnections();
    $doh = trim((string)($cn['ai_net']['doh_url'] ?? '')) ?: 'https://cloudflare-dns.com/dns-query';
    return aiDohResolve($host, $doh, 5);   // v10.82 (96): با خطا — تا در تلاش‌ها ثبت شود
}
/** v10.79 (93): آدرسِ اتصالِ غیرمستقیمِ سایت — همان کشفِ Push
    (فیلدِ جداگانه ← عبورِ هوش مصنوعی ← مبدأ). '' اگر نباشد یا
    قالبِ قدیمیِ HTTP-proxy (user:pass@...) باشد. */
function msgrSiteProxy(): string {
    $rc = pushRouteCfg();
    $u = (string)($rc['proxy'] ?? '');
    if ($u === '' || stripos($u, '@') !== false) return '';
    return $u;
}
/** v10.82 (96): فهرستِ همهٔ مسیرهایِ غیرمستقیمِ موجود — مسیرِ Push،
    عبورِ هوش مصنوعی، عبورِ مبدأ (به‌ترتیب). هر کدام جدا امتحان می‌شود
    تا یک مسیرِ مرده (مثلِ Cloudflare 530) جلویِ مسیرِ زنده را نگیرد. */
function msgrSiteProxies(): array {
    $rc = pushRouteCfg();
    $cn = loadConnections();
    $list = [];
    foreach ([(string)($rc['proxy'] ?? ''),
              trim((string)($cn['ai_net']['worker_url'] ?? '')),
              trim((string)($cn['src_net']['worker_url'] ?? ''))] as $u) {
        $u = trim((string)$u);
        if ($u === '' || stripos($u, '@') !== false) continue;
        if (!in_array($u, $list, true)) $list[] = $u;
    }
    return $list;
}
/** v10.81 (95): لاگِ ارسال‌هایِ پیام‌رسان — حقیقتِ «چه چیزی از کدام
    مسیر رفت و چه پاسخی آمد» (برایِ تشخیصِ مشکلاتِ مسیرِ هاست). */
function msgrSendLog(string $host, array $entry): void {
    try {
        $f = __DIR__ . '/msgr_send_log.json';
        $d = json_decode((string)@file_get_contents($f), true) ?: [];
        $rows = is_array($d['rows'] ?? null) ? $d['rows'] : [];
        $rows[] = ['at' => time(), 'host' => $host] + $entry;
        @file_put_contents($f, json_encode(['rows' => array_slice($rows, -25)], JSON_UNESCAPED_UNICODE), LOCK_EX);
    } catch (Throwable $e) { /* لاگ نباید ارسال را قطع کند */ }
}
/** v10.81 (95): امضایِ «بدنهٔ خراب‌شده در راه» — وقتی بدنهٔ POST
    قابلِ پارسِ JSON نباشد (مثلاً خروجیِ هاست سربرگِ
    Content-Type: application/json را بیندازد یا بدنه را تغییر دهد)،
    Bot API به‌جایِ «JSON نامعتبر»، «message text is empty»
    برمی‌گرداند. یعنی متنِ خالیِ واقعی نبود — بدنه در راه خراب شده. */
function msgrBodyCorrupted(int $code, string $resp): bool {
    if ($code < 400) return false;
    return (stripos($resp, 'message text is empty') !== false
        || stripos($resp, "can't parse") !== false
        || stripos($resp, 'invalid json') !== false);
}
/** v10.79 (93): ارسالِ مشترکِ پیام‌رسان — زنجیره:
    مستقیم ← (اگر بدنه خراب شد) فرم ← (اگر DNS/اتصال شکست) DoH با
    IP ثابت ← (اگر هنوز نرسید) proxy.phpِ خودِ سایت.
    v10.81 (95): هر تلاش در لاگِ ارسال ثبت می‌شود و خطایِ نهایی
    فهرستِ تلاش‌ها را دارد. برمی‌گرداند {ok, code, error, via}. */
function msgrSend(string $url, string $postJson): array {
    try {
    $host = (string)(parse_url($url, PHP_URL_HOST) ?? '');
    $arr = json_decode($postJson, true);
    $postForm = (is_array($arr) && $arr) ? http_build_query($arr) : '';
    $do = function (string $u, ?string $pinIp, string $body, string $enc): array {
        $ch = curl_init($u);
        $opt = [CURLOPT_POST => true, CURLOPT_POSTFIELDS => $body,
            CURLOPT_HTTPHEADER => ['Content-Type: ' . ($enc === 'json' ? 'application/json' : 'application/x-www-form-urlencoded')],
            CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 15, CURLOPT_CONNECTTIMEOUT => 6,
            CURLOPT_SSL_VERIFYPEER => true];
        if ($pinIp !== null && $pinIp !== '') {
            $h = (string)(parse_url($u, PHP_URL_HOST) ?? '');
            if ($h !== '') $opt[CURLOPT_RESOLVE] = [$h . ':443:' . $pinIp];
        }
        curl_setopt_array($ch, $opt);
        $resp = (string)curl_exec($ch);
        $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
        $err = (string)curl_error($ch);
        curl_close($ch);
        return [$code, $resp, $err];
    };
    $short = function (string $r): string {
        $j = json_decode($r, true);
        $d = is_array($j) ? (string)($j['description'] ?? ($j['error'] ?? ($j['message'] ?? ''))) : '';
        return $d !== '' ? $d : mb_substr($r, 0, 90);
    };
    $attempts = [];
    $try = function (string $label, string $u, ?string $pinIp, string $body, string $enc) use ($do, $short, &$attempts): array {
        [$c, $r, $e] = $do($u, $pinIp, $body, $enc);
        $attempts[] = $label . ': ' . ($e !== '' ? 'خطای شبکه — ' . mb_substr($e, 0, 60)
                              : ($c === 0 ? 'پاسخی نیامد'
                                          : 'HTTP ' . $c . ' — ' . mb_substr($short((string)$r), 0, 90)));
        return [$c, $r, $e];
    };
    $via = 'مستقیم';
    [$code, $resp, $err] = $try('مستقیم', $url, null, $postJson, 'json');
    /* v10.81 (95): بدنه در راه خراب شده (با وجودِ متنِ سالم، پاسخی
       از نوعِ «text is empty» آمد) ← همان مسیر با بدنهٔ فرمی که
       تلگرام هم قبول می‌کند، دوباره. */
    if (!($code >= 200 && $code < 300) && $postForm !== '' && msgrBodyCorrupted($code, (string)$resp)) {
        [$c, $r, $e] = $try('مستقیم(فرم)', $url, null, $postForm, 'form');
        $code = $c; $resp = $r; $err = $e;
        if ($c >= 200 && $c < 300) $via = 'مستقیم (فرم)';
    }
    if ($code === 0 && $host !== '') {
        $dr = msgrResolveDoH($host);
        $ip = (!empty($dr['ok']) && !empty($dr['ip'])) ? (string)$dr['ip'] : '';
        if ($ip !== '') {
            [$c2, $r2, $e2] = $try('DoH', $url, $ip, $postJson, 'json');
            if ($c2 !== 0) {
                $code = $c2; $resp = $r2; $err = $e2; $via = 'DoH(' . $ip . ')';
                if ($postForm !== '' && msgrBodyCorrupted($c2, (string)$r2)) {
                    [$c2f, $r2f, $e2f] = $try('DoH(فرم)', $url, $ip, $postForm, 'form');
                    $code = $c2f; $resp = $r2f; $err = $e2f; $via = 'DoH(' . $ip . ') (فرم)';
                }
            }
        } else {
            /* v10.82 (96): شکستِ resolve در تلاش‌ها ثبت می‌شود (قبلاً خاموش بود) */
            $attempts[] = 'DoH: resolve نشد — ' . mb_substr((string)($dr['error'] ?? 'نامشخص'), 0, 80);
        }
    }
    /* v10.82 (96): مسیرهایِ غیرمستقیم — وقتی نرسیده‌ایم یا بدنه در راه
       خراب شده؛ هر مسیرِ موجود به‌ترتیب امتحان می‌شود تا اولِ زنده. */
    if ($host !== '' && ($code === 0 || msgrBodyCorrupted($code, (string)$resp))) {
        $proxies = msgrSiteProxies();
        for ($iP = 0; $iP < count($proxies); $iP++) {
            $proxy = $proxies[$iP];
            $pu = strpos($proxy, '{url}') !== false
                ? str_replace('{url}', rawurlencode($url), $proxy)
                : $proxy . (strpos($proxy, '?') !== false ? '&' : '?') . 'url=' . rawurlencode($url);
            [$c3, $r3, $e3] = $try('proxy.php#' . ($iP + 1), $pu, null, $postJson, 'json');
            if ($c3 >= 200 && $c3 < 300) { $code = $c3; $resp = $r3; $err = $e3; $via .= ' ← proxy.php'; break; }
            $code = $c3; $resp = $r3; $err = $e3;
        }
    }
    msgrSendLog($host, ['via' => $via, 'code' => $code, 'ok' => ($code >= 200 && $code < 300),
        'attempts' => implode(' | ', $attempts), 'resp' => mb_substr((string)$resp, 0, 300)]);
    if ($code >= 200 && $code < 300) {
        /* v10.85 (99): شناسهٔ پیام برای رجیستری webhook */
        $_jR85 = json_decode((string)$resp, true);
        $_mId85 = is_array($_jR85) ? (string)(($_jR85['result']['message_id'] ?? ($_jR85['message_id'] ?? ($_jR85['result']['id'] ?? '')))) : '';
        return ['ok' => true, 'code' => $code, 'error' => '', 'via' => $via, 'message_id' => $_mId85];
    }
    $j = json_decode($resp, true);
    $detail = '';
    if (is_array($j)) $detail = (string)($j['description'] ?? ($j['error'] ?? ($j['message'] ?? ($j['detail'] ?? ''))));
    if ($detail === '' && is_array($j) && isset($j['error_code'])) $detail = 'error_code=' . $j['error_code'];
    if ($detail === '') $detail = mb_substr($resp, 0, 200);
    $e = $err !== '' ? 'خطای شبکه: ' . $err : ($detail !== '' ? $detail : 'پاسخی نیامد');
    $tr = count($attempts) > 1 ? ' — تلاش‌ها: ' . mb_substr(implode(' | ', $attempts), 0, 400) : '';
    /* v10.82 (96): راهنمایِ خطای Cloudflare روی مسیرِ غیرمستقیم */
    $hint = ($code === 530 && strpos($via, 'proxy') !== false)
        ? ' — اتصالِ غیرمستقیمِ سایت در دسترس نیست (Cloudflare)؛ آدرسِ «مسیرِ Push» را بررسی کنید' : '';
    return ['ok' => false, 'code' => $code,
        'error' => ($via !== 'مستقیم' && $via !== 'مستقیم (فرم)' ? '[' . $via . '] ' : '') . $e . $tr . $hint, 'via' => $via];
    } catch (Throwable $__msge) {
        return ['ok' => false, 'code' => 0, 'error' => 'خطای داخلی: ' . $__msge->getMessage(), 'via' => ''];
    }
}
function bslSendToBaleh(string $token, string $chatId, string $text, bool $preview = false): array {
return msgrSend('https://tapi.bale.ai/bot' . $token . '/sendMessage', json_encode(['chat_id' => $chatId, 'text' => $text, 'disable_web_page_preview' => !$preview], JSON_UNESCAPED_UNICODE));
}
function bslSendToRubika(string $token, string $chatId, string $text): array {
return msgrSend('https://api.rubika.ir/v1/bot' . $token . '/sendMessage', json_encode(['chat_id' => $chatId, 'text' => $text], JSON_UNESCAPED_UNICODE));
}

function bslSendToTelegram(string $token, string $chatId, string $text, bool $preview = false): array {
return msgrSend('https://api.telegram.org/bot' . $token . '/sendMessage', json_encode(['chat_id' => $chatId, 'text' => $text, 'disable_web_page_preview' => !$preview], JSON_UNESCAPED_UNICODE));
}

/**
 * v10.109: ارسال رسانه به پیام‌رسان (عکس/ویدیو/گیف/فایل/لینک) با URL عمومی.
 * $item = ['kind'=>photo|video|animation|audio|document|link, 'url'=>, 'caption'=>, 'name'=>]
 */
function bslSendMediaToMessenger(string $msgr, string $token, string $chatId, array $item): array {
    $kind = strtolower(trim((string)($item['kind'] ?? 'document')));
    $url  = trim((string)($item['url'] ?? ''));
    $cap  = trim((string)($item['caption'] ?? ''));
    $name = trim((string)($item['name'] ?? ''));
    if ($url === '') return ['ok' => false, 'error' => 'empty url'];
    if ($kind === 'link') {
        $txt = $cap !== '' ? $cap : ('🔗 ' . $url);
        if (mb_strpos($txt, $url) === false) $txt .= "\n" . $url;
        return match ($msgr) {
            'baleh', 'bale' => bslSendToBaleh($token, $chatId, $txt, true),
            'telegram' => bslSendToTelegram($token, $chatId, $txt, true),
            default => bslSendToRubika($token, $chatId, $txt),
        };
    }
    // روبیکا: فقط متن با لینک فایل
    if ($msgr === 'rubika') {
        $label = match ($kind) {
            'photo' => '🖼 تصویر',
            'video' => '🎬 ویدیو',
            'animation' => '🎞 گیف',
            'audio' => '🎧 صوت',
            default => '📎 فایل',
        };
        $txt = $label . ($name !== '' ? ' (' . $name . ')' : '') . "\n" . $url;
        if ($cap !== '') $txt = mb_substr($cap, 0, 200) . "\n" . $txt;
        return bslSendToRubika($token, $chatId, $txt);
    }
    $base = ($msgr === 'telegram')
        ? ('https://api.telegram.org/bot' . $token . '/')
        : ('https://tapi.bale.ai/bot' . $token . '/');
    $method = 'sendDocument';
    $field  = 'document';
    if ($kind === 'photo') { $method = 'sendPhoto'; $field = 'photo'; }
    elseif ($kind === 'video') { $method = 'sendVideo'; $field = 'video'; }
    elseif ($kind === 'animation') { $method = 'sendAnimation'; $field = 'animation'; }
    elseif ($kind === 'audio') { $method = 'sendAudio'; $field = 'audio'; }
    $body = ['chat_id' => $chatId, $field => $url];
    if ($cap !== '') $body['caption'] = mb_substr($cap, 0, 1000);
    if ($kind === 'document' && $name !== '') $body['file_name'] = $name;
    $r = msgrSend($base . $method, json_encode($body, JSON_UNESCAPED_UNICODE));
    // اگر sendPhoto/Video با URL شکست خورد، لینک را متنی بفرست
    if (empty($r['ok'])) {
        $label = match ($kind) {
            'photo' => '🖼 تصویر', 'video' => '🎬 ویدیو', 'animation' => '🎞 گیف',
            'audio' => '🎧 صوت', default => '📎 فایل',
        };
        $txt = $label . "\n" . $url . ($cap !== '' ? ("\n" . mb_substr($cap, 0, 300)) : '');
        if ($msgr === 'telegram') return bslSendToTelegram($token, $chatId, $txt, true);
        return bslSendToBaleh($token, $chatId, $txt, true);
    }
    return $r;
}

/* v10.85 (99): registry message_id for webhook reply */
function msgrMsgRegistry(): string { return __DIR__ . '/msgr_msg_registry.json'; }
function msgrSaveMsg(string $msgr, string $msgId, int $chatId, int $shop, string $who = ''): void {
    if ($msgId === '' || $msgId === '0') return;
    $f = msgrMsgRegistry();
    $reg = is_file($f) ? (array)@json_decode((string)@file_get_contents($f), true) : [];
    $reg[$msgr . ':' . $msgId] = ['chat_id' => $chatId, 'shop' => $shop, 'who' => $who, 'ts' => time()];
    if (count($reg) > 500) {
        uasort($reg, fn($a, $b) => ($a['ts'] ?? 0) <=> ($b['ts'] ?? 0));
        $reg = array_slice($reg, -500, null, true);
    }
    @file_put_contents($f, json_encode($reg, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT));
}
function msgrHookProcess(string $msgr, array $cn): void {
    header('Content-Type: application/json');
    $body = (string)@file_get_contents('php://input');
    $data = json_decode($body, true);
    if (!is_array($data)) { echo json_encode(['ok' => false, 'error' => 'invalid json']); exit; }
    $f = msgrMsgRegistry(); $reg = is_file($f) ? (array)@json_decode((string)@file_get_contents($f), true) : [];
    $key = ''; $text = '';
    if ($msgr === 'telegram') {
        $upd = $data['message'] ?? $data['edited_message'] ?? null;
        if (!is_array($upd)) { echo json_encode(['ok' => true, 'skipped' => 'no message']); exit; }
        $rt = $upd['reply_to_message'] ?? null;
        if (!is_array($rt)) { echo json_encode(['ok' => true, 'skipped' => 'not a reply']); exit; }
        $key = 'telegram:' . (string)($rt['message_id'] ?? '');
        $text = trim((string)($upd['text'] ?? $upd['caption'] ?? ''));
    } elseif ($msgr === 'bale') {
        $upd = $data['message'] ?? null;
        if (!is_array($upd)) { echo json_encode(['ok' => true, 'skipped' => 'no message']); exit; }
        $rt = $upd['reply_to_message'] ?? null;
        if (!is_array($rt)) { echo json_encode(['ok' => true, 'skipped' => 'not a reply']); exit; }
        $key = 'bale:' . (string)($rt['message_id'] ?? '');
        $text = trim((string)($upd['text'] ?? ''));
    } elseif ($msgr === 'rubika') {
        $upd = $data['message'] ?? $data['update'] ?? null;
        if (!is_array($upd)) { echo json_encode(['ok' => true, 'skipped' => 'no message']); exit; }
        $rid = $upd['reply_to_message_id'] ?? ($upd['reply_to'] ?? null);
        if (!$rid) { echo json_encode(['ok' => true, 'skipped' => 'not a reply']); exit; }
        $key = 'rubika:' . (string)$rid;
        $text = trim((string)($upd['text'] ?? $upd['message_text'] ?? ''));
    } else { echo json_encode(['ok' => false, 'error' => 'unknown messenger']); exit; }
    if (!isset($reg[$key])) { echo json_encode(['ok' => true, 'skipped' => 'not our message']); exit; }
    $entry = $reg[$key]; $chatId = (int)($entry['chat_id'] ?? 0); $shop = (int)($entry['shop'] ?? 1);
    if ($chatId <= 0 || $text === '') { echo json_encode(['ok' => false, 'error' => 'empty']); exit; }
    $shops = bslAllShops($cn); $sh = null;
    foreach ($shops as $s) { if ((int)($s['shop'] ?? 0) === $shop) { $sh = $s; break; } }
    if (!$sh && $shops) $sh = $shops[0];
    if (!$sh) { echo json_encode(['ok' => false, 'error' => 'no shop']); exit; }
    $tk = trim((string)($sh['token'] ?? ''));
    if ($tk === '') { echo json_encode(['ok' => false, 'error' => 'no token']); exit; }
    $r = bslSendChatMessage($tk, $chatId, $text);
    echo json_encode(['ok' => $r['ok'], 'error' => $r['error'] ?? '']);
    exit;
}

/**
 * v10.443: تشخیص دقیق خطای دسته‌بندی باسلام (مانند HTTP 422 با
 * {"http_status":422,"messages":[{"code":0,"fields":["category"],"message":".دسته بندی انتخابی دارای فرزند می باشد"}]})
 * از خطاهای غیر دسته‌بندی (نام تکراری، تصویر، قیمت، احراز هویت، 429 و ...).
 */
function bslIsCategoryError(array $r): bool {
    if (!empty($r['ok'])) return false;
    $code = (int)($r['code'] ?? 0);
    if ($code === 429 || in_array($code, [0, 401, 403], true)) return false;
    if (function_exists('bslIsDuplicateName') && bslIsDuplicateName($r)) return false;
    $b = is_array($r['body'] ?? null) ? $r['body'] : [];
    $hasExplicitCatField = false;
    if (is_array($b['messages'] ?? null)) {
        foreach ($b['messages'] as $mItem) {
            if (!is_array($mItem)) continue;
            $fields = is_array($mItem['fields'] ?? null) ? $mItem['fields'] : [];
            $nonEmptyFields = false;
            foreach ($fields as $f) {
                $fl = strtolower(trim((string)$f));
                if ($fl !== '') $nonEmptyFields = true;
                if ($fl === 'category' || $fl === 'category_id') {
                    $hasExplicitCatField = true;
                    return true;
                }
            }
            /* v10.459: پیام‌هایی مثل «مدت زمان آماده سازی برای این دسته بندی باید بین صفر تا 4 روز باشد»
               دارای fields:["preparation_days"] هستند و صرفِ وجود عبارت «برای این دسته بندی» نباید
               آن‌ها را خطای دسته‌بندی جا بزند. */
            if ($nonEmptyFields) continue;
            $mTxt = (string)($mItem['message'] ?? '');
            if ($mTxt !== '' && (
                mb_strpos($mTxt, 'دارای فرزند') !== false ||
                mb_strpos($mTxt, 'دسته بندی') !== false ||
                mb_strpos($mTxt, 'دسته‌بندی') !== false ||
                mb_strpos($mTxt, 'دسته') !== false ||
                mb_strpos($mTxt, 'زیرمجموعه') !== false ||
                mb_strpos($mTxt, 'فرزند') !== false ||
                stripos($mTxt, 'category') !== false ||
                stripos($mTxt, 'leaf') !== false
            )) {
                if (function_exists('bslIsPreparationDaysError') && bslIsPreparationDaysError($r)) continue;
                return true;
            }
        }
    }
    if (is_array($b['errors'] ?? null)) {
        foreach ($b['errors'] as $fk => $fv) {
            $fkl = strtolower(trim((string)$fk));
            if ($fkl === 'category' || $fkl === 'category_id') return true;
        }
    }
    if (!$hasExplicitCatField && function_exists('bslIsPreparationDaysError') && bslIsPreparationDaysError($r)) {
        return false;
    }
    $hay = [];
    foreach (['message', 'error', 'error_description', 'detail'] as $k) {
        if (!empty($b[$k])) {
            $hay[] = is_array($b[$k]) ? (string)json_encode($b[$k], JSON_UNESCAPED_UNICODE) : (string)$b[$k];
        }
    }
    if (!empty($r['raw']) && is_string($r['raw'])) $hay[] = $r['raw'];
    $joined = implode(' ', $hay);
    if ($joined === '') return false;
    if (stripos($joined, '"category"') !== false || stripos($joined, 'category_id') !== false) return true;
    if (mb_strpos($joined, 'دارای فرزند') !== false || mb_strpos($joined, 'دسته بندی') !== false || mb_strpos($joined, 'دسته‌بندی') !== false) return true;
    if ($code === 422 && (mb_strpos($joined, 'دسته') !== false || mb_strpos($joined, 'زیرمجموعه') !== false || mb_strpos($joined, 'فرزند') !== false || stripos($joined, 'category') !== false)) {
        return true;
    }
    return false;
}

/**
 * v10.443: ساخت زنجیرهٔ مرتب و یکتای تمام دسته‌های دستی انتخاب‌شده توسط کاربر
 * (دستهٔ مستقیم ردیف/پروفایل -> دسته‌های جایگزین پروفایل به ترتیب انتخاب -> دسته‌های جایگزین ارسالی -> دستهٔ اصلی و جایگزین‌های تنظیمات باسلام).
 */
function bslCollectManualCategories(int $primaryCatId = 0, ?array $profile = null, array $fallbackCatIds = [], ?array $basalamCfg = null): array {
    $ordered = [];
    $seen = [];
    $push = static function ($cid) use (&$ordered, &$seen): void {
        $n = (int)$cid;
        if ($n > 0 && empty($seen[$n])) {
            $seen[$n] = true;
            $ordered[] = $n;
        }
    };
    if ($primaryCatId > 0) $push($primaryCatId);
    if (is_array($profile)) {
        $push((int)($profile['bslCategoryId'] ?? 0));
        foreach ((array)($profile['bslFallbackCatIds'] ?? []) as $fc) $push($fc);
    }
    foreach ($fallbackCatIds as $fc) $push($fc);
    if (is_array($basalamCfg)) {
        $push((int)($basalamCfg['category_id'] ?? 0));
        foreach ((array)($basalamCfg['fallback_cat_ids'] ?? []) as $fc) $push($fc);
    }
    return $ordered;
}

/**
 * v10.443: صف اختصاصی محصولاتی که همهٔ دسته‌های دستی انتخاب‌شده برایشان با خطای دسته‌بندی رد شده
 * و برای «تصحیح دسته‌بندی با هوش مصنوعی» کنار گذاشته شده‌اند.
 */
function bslAiCatPendingMutate(callable $fn) {
    $lf = @fopen(BSL_AI_CAT_QUEUE_LOCK, 'c+');
    if ($lf) @flock($lf, LOCK_EX);
    try {
        $cur = is_file(BSL_AI_CAT_QUEUE_FILE)
            ? json_decode((string)@file_get_contents(BSL_AI_CAT_QUEUE_FILE), true) : null;
        if (!is_array($cur)) $cur = ['version' => APP_VERSION, 'updated_at' => time(), 'items' => []];
        if (!is_array($cur['items'] ?? null)) $cur['items'] = [];
        $ret = $fn($cur);
        $cur['version'] = APP_VERSION;
        $cur['updated_at'] = time();
        if (count($cur['items']) > 5000) {
            $cur['items'] = array_slice($cur['items'], -5000, null, true);
        }
        $tmp = BSL_AI_CAT_QUEUE_FILE . '.tmp.' . getmypid();
        @file_put_contents($tmp, json_encode($cur, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), LOCK_EX);
        @rename($tmp, BSL_AI_CAT_QUEUE_FILE);
        return $ret;
    } finally {
        if ($lf) { @flock($lf, LOCK_UN); @fclose($lf); }
    }
}

function bslAiCatPendingLoad(?int $vendorId = null, bool $onlyPending = true): array {
    if (!is_file(BSL_AI_CAT_QUEUE_FILE)) return [];
    $d = json_decode((string)@file_get_contents(BSL_AI_CAT_QUEUE_FILE), true);
    $items = is_array($d['items'] ?? null) ? $d['items'] : [];
    $out = [];
    foreach ($items as $qid => $it) {
        if (!is_array($it)) continue;
        if ($onlyPending && (string)($it['status'] ?? 'pending') !== 'pending') continue;
        if ($vendorId !== null && $vendorId > 0 && (int)($it['vendor_id'] ?? 0) !== $vendorId) continue;
        $it['queue_id'] = (string)($it['queue_id'] ?? $qid);
        $out[] = $it;
    }
    return $out;
}

function bslAiCatPendingKey(int $vendorId, string $productKey, string $title): string {
    $normKey = trim($productKey);
    $normTitle = function_exists('normalizeTitle') ? normalizeTitle($title) : mb_strtolower(trim($title), 'UTF-8');
    $seed = $vendorId . '|' . ($normKey !== '' ? $normKey : $normTitle);
    return 'aicat_' . $vendorId . '_' . substr(md5($seed), 0, 12);
}

function bslQueueForAiCategoryFix(array $p, array $ctx = []): array {
    $vid = (int)($ctx['vendor_id'] ?? 0);
    $title = trim((string)($ctx['title'] ?? ($p['title'] ?? '')));
    $pKey = trim((string)($ctx['product_key'] ?? ($p['_key'] ?? ($p['link'] ?? $title))));
    $qid = bslAiCatPendingKey($vid, $pKey, $title);
    $cleanP = $p;
    foreach (['_bsl_forced_price', '_forced_price_toman'] as $tmpK) unset($cleanP[$tmpK]);
    $triedIn = [];
    foreach ((array)($ctx['tried_cat_ids'] ?? []) as $tc) {
        $tcInt = (int)$tc;
        if ($tcInt > 0 && !in_array($tcInt, $triedIn, true)) $triedIn[] = $tcInt;
    }
    return bslAiCatPendingMutate(static function (array &$q) use ($qid, $vid, $title, $pKey, $cleanP, $triedIn, $ctx): array {
        $prev = is_array($q['items'][$qid] ?? null) ? $q['items'][$qid] : [];
        $mergedTried = [];
        foreach (array_merge((array)($prev['tried_cat_ids'] ?? []), $triedIn) as $tc) {
            $tcInt = (int)$tc;
            if ($tcInt > 0 && !in_array($tcInt, $mergedTried, true)) $mergedTried[] = $tcInt;
        }
        $now = time();
        $row = [
            'queue_id'          => $qid,
            'status'            => 'pending',
            'vendor_id'         => $vid,
            'shop_name'         => (string)($ctx['shop_name'] ?? ($prev['shop_name'] ?? '')),
            'profile_key'       => (string)($ctx['profile_key'] ?? ($cleanP['_profile_key'] ?? ($prev['profile_key'] ?? ''))),
            'profile_name'      => (string)($ctx['profile_name'] ?? ($cleanP['_profile_name'] ?? ($prev['profile_name'] ?? ''))),
            'product_key'       => $pKey,
            'bare'              => (string)($ctx['bare'] ?? ($prev['bare'] ?? '')),
            'title'             => $title,
            'tried_cat_ids'     => $mergedTried,
            'forced_price_toman'=> isset($ctx['forced_price_toman']) ? (int)$ctx['forced_price_toman'] : (isset($prev['forced_price_toman']) ? (int)$prev['forced_price_toman'] : 0),
            'endpoint'          => (string)($ctx['endpoint'] ?? ('vendors/' . $vid . '/products')),
            'last_error_code'   => (int)($ctx['error_code'] ?? 422),
            'last_error'        => (string)($ctx['error'] ?? ''),
            'last_error_detail' => mb_substr((string)($ctx['error_detail'] ?? ''), 0, 1200, 'UTF-8'),
            'source_step'       => (string)($ctx['step'] ?? 'shop_create'),
            'queued_at'         => (int)($prev['queued_at'] ?? $now),
            'updated_at'        => $now,
            'attempts'          => (int)($prev['attempts'] ?? 0) + 1,
            'product'           => $cleanP,
        ];
        $q['items'][$qid] = $row;
        return $row;
    });
}

function bslClearAiCategoryFixPending(int $vendorId, string $productKey = '', string $title = '', ?array $fixedMeta = null): void {
    if (!is_file(BSL_AI_CAT_QUEUE_FILE)) return;
    $qidExact = ($productKey !== '' || $title !== '') ? bslAiCatPendingKey($vendorId, $productKey, $title) : '';
    $normTitle = ($title !== '' && function_exists('normalizeTitle')) ? normalizeTitle($title) : mb_strtolower(trim($title), 'UTF-8');
    bslAiCatPendingMutate(static function (array &$q) use ($vendorId, $productKey, $normTitle, $qidExact, $fixedMeta): void {
        foreach ($q['items'] as $k => &$it) {
            if (!is_array($it)) continue;
            if ($vendorId > 0 && (int)($it['vendor_id'] ?? 0) !== $vendorId) continue;
            $itTitleNorm = function_exists('normalizeTitle') ? normalizeTitle((string)($it['title'] ?? '')) : mb_strtolower(trim((string)($it['title'] ?? '')), 'UTF-8');
            $matched = ($qidExact !== '' && $k === $qidExact)
                || ($productKey !== '' && (string)($it['product_key'] ?? '') === $productKey)
                || ($normTitle !== '' && $itTitleNorm === $normTitle);
            if (!$matched) continue;
            if (is_array($fixedMeta)) {
                $it['status'] = 'fixed';
                $it['fixed_at'] = time();
                $it['fixed_cat_id'] = (int)($fixedMeta['cat_id'] ?? 0);
                $it['fixed_cat_name'] = (string)($fixedMeta['cat_name'] ?? '');
                $it['remote_id'] = (int)($fixedMeta['remote_id'] ?? 0);
                unset($it['product']);
            } else {
                unset($q['items'][$k]);
            }
        }
        unset($it);
    });
}

function bslSaveAiCategoryToProfile(string $profileKey, string $productKey, string $title, int $catId): bool {
    if ($catId <= 0 || $profileKey === '' || !function_exists('mutateProfile')) return false;
    $_aiProfs = function_exists('loadProfiles') ? loadProfiles() : [];
    $resolvedKey = function_exists('profileResolveKey') ? (profileResolveKey($profileKey, $_aiProfs) ?? $profileKey) : $profileKey;
    if ($resolvedKey === '') $resolvedKey = $profileKey;
    $normTitle = ($title !== '' && function_exists('normalizeTitle')) ? normalizeTitle($title) : mb_strtolower(trim($title), 'UTF-8');
    $saved = false;
    mutateProfile($resolvedKey, static function (array $prof) use ($productKey, $normTitle, $catId, &$saved): array {
        if (!is_array($prof['products'] ?? null)) return $prof;
        foreach ($prof['products'] as &$pair) {
            if (!is_array($pair) || count($pair) < 2 || !is_array($pair[1])) continue;
            $k = (string)($pair[0] ?? '');
            $pd = &$pair[1];
            $ptNorm = function_exists('normalizeTitle') ? normalizeTitle((string)($pd['title'] ?? '')) : mb_strtolower(trim((string)($pd['title'] ?? '')), 'UTF-8');
            if (($productKey !== '' && ($k === $productKey || (string)($pd['link'] ?? '') === $productKey))
                || ($normTitle !== '' && $ptNorm === $normTitle)) {
                $pd['bsl_category_id'] = $catId;
                $saved = true;
            }
            unset($pd);
        }
        unset($pair);
        return $prof;
    });
    return $saved;
}

function bslBuildFinalCategoryDeferredError(array $lastResp, int $vid, array $tried, array $aiQueued, string $step = 'shop_create'): array {
    $rawErr = trim((string)($lastResp['raw'] ?? ''));
    if ($rawErr === '' && is_array($lastResp['body'] ?? null) && !empty($lastResp['body'])) {
        $rawErr = (string)json_encode($lastResp['body'], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    }
    $baseMsg = bslErrText($lastResp);
    $triedClean = [];
    foreach ($tried as $tc) {
        $ti = (int)$tc;
        if ($ti > 0 && !in_array($ti, $triedClean, true)) $triedClean[] = $ti;
    }
    $triedLabel = $triedClean ? implode(' -> ', array_map(static fn($x) => '#' . $x, $triedClean)) : '—';
    $finalMsg = $baseMsg
        . ' | دسته‌های دستی امتحان‌شده (' . count($triedClean) . '): ' . $triedLabel
        . ' — کنار گذاشته شد برای تصحیح دسته‌بندی با هوش مصنوعی';
    $errInfo = bslSendErrorInfo($lastResp, $step, 'vendors/' . $vid . '/products');
    $errInfo['error']           = $finalMsg;
    $errInfo['reason_kind']     = 'category_ai_pending';
    $errInfo['ai_cat_queued']   = true;
    $errInfo['ai_cat_queue_id'] = (string)($aiQueued['queue_id'] ?? '');
    $errInfo['tried_cat_ids']   = $triedClean;
    if ($rawErr !== '') $errInfo['error_detail'] = mb_substr($rawErr, 0, 800, 'UTF-8');
    return array_merge(['ok' => false], $errInfo);
}

/**
 * v10.443: تلاش ترتیبی روی دسته‌های دستی انتخاب‌شده به همان ترتیب دقیق کاربر.
 * - دسته‌های دستی هرگز با children[0] دستکاری نمی‌شوند؛ دقیقاً همان شناسه‌های انتخابی یک‌به‌یک تست می‌شوند.
 * - با خواندن کامل body.messages[*]، خطای HTTP 422 دسته‌بندی («دارای فرزند می باشد») باعث ادامه به دستهٔ دستی بعدی می‌شود.
 * - اگر خطای غیر دسته‌بندی (مانند نام تکراری یا 429) رخ دهد بلافاصله متوقف می‌شود و اگر همهٔ دسته‌های دستی رد شوند،
 *   بدون حدس تصادفی کلمه‌کلیدی، نتیجه را با all_categories_rejected=true برمی‌گرداند تا محصول برای هوش مصنوعی کنار گذاشته شود.
 */
function bslTryCreateWithFallback(string $tk, int $vid, array $bp, array $fallbackCatIds, string $pTitle = '', bool $autoCat = false, array $bslFlatCats = [], array $cData = []): array {
    $tried = [];
    $initCat = (int)($bp['category_id'] ?? 0);
    if ($initCat > 0) $tried[] = $initCat;
    $lastResp = null;
    foreach ($fallbackCatIds as $fcRaw) {
        if (function_exists('bslStopRequestedForQueue') && bslStopRequestedForQueue()) {
            return ['ok' => false, 'stopped' => true, 'error' => 'متوقف توسط کاربر', 'tried' => $tried, 'last_response' => $lastResp];
        }
        $fc = (int)$fcRaw;
        if ($fc <= 0 || in_array($fc, $tried, true)) continue;
        $tried[] = $fc;
        $bp['category_id'] = $fc;
        $r = bslReq($tk, 'POST', 'vendors/' . $vid . '/products', $bp);
        $lastResp = $r;
        if (!empty($r['ok']) && !empty($r['body']['id'])) {
            return ['ok' => true, 'body' => $r['body'], 'used_cat_id' => $fc, 'tried' => $tried, 'last_response' => $r];
        }
        if ((int)($r['code'] ?? 0) === 429) {
            return ['ok' => false, 'rate_limited' => true, 'error' => bslErrText($r), 'tried' => $tried, 'last_response' => $r];
        }
        if (function_exists('bslIsDuplicateName') && bslIsDuplicateName($r)) {
            return ['ok' => false, 'duplicate_name' => true, 'error' => bslErrText($r), 'tried' => $tried, 'last_response' => $r];
        }
        if (!bslIsCategoryError($r)) {
            return ['ok' => false, 'all_categories_rejected' => false, 'error' => bslErrText($r), 'tried' => $tried, 'last_response' => $r];
        }
    }
    return [
        'ok'                      => false,
        'all_categories_rejected' => true,
        'error'                   => ($lastResp ? bslErrText($lastResp) : 'همهٔ دسته‌های دستی انتخاب‌شده رد شدند'),
        'tried'                   => $tried,
        'last_response'           => $lastResp,
    ];
}
