/* ══════════════════════════════════════════════════════════════════
 *  v10.11 (۲۴): فهرستِ یکپارچهٔ مدل‌ها برای همهٔ انتخاب‌گرها
 *
 *  تا ۱۰٫۱۰ انتخاب‌گرهای «ایجنت» و «اتوماسیون» فقط کاتالوگِ ثابتِ
 *  autoFreeToolModels() را نشان می‌دادند. مشکل: آن کاتالوگ فهرستِ
 *  «پیشنهادی»ست، نه مدل‌هایی که کاربر واقعاً اتصالشان را ثبت کرده.
 *  اگر کاربر مدلی خارج از کاتالوگ داشت اصلاً دیده نمی‌شد، و اگر
 *  اتصالی نداشت فهرستِ پر می‌دید که هیچ‌کدامش کار نمی‌کرد.
 *
 *  این اندپوینت هر دو منبع را یکجا می‌دهد:
 *    • مدل‌های ثبت‌شدهٔ کاربر (از ai_providers.json) با پرچمِ ready=true
 *    • مدل‌های کاتالوگ که اتصالشان نیست، با ready=false (پیشنهاد)
 *  و برای هر مدل سه قابلیت را مشخص می‌کند تا فیلترِ سه‌گانه کار کند:
 *    chat (همه‌چیزِ گفت‌وگویی) · tools (فراخوانیِ ابزار) · reasoning (استدلالی)
 * ══════════════════════════════════════════════════════════════════ */

/** سه قابلیتِ یک مدل را از روی ردیفِ اتصال و کاتالوگ تعیین می‌کند */
function aiModelCaps(string $modelId, array $row = [], array $catRow = []): array {
    $nonChat = aiNonChatModel($modelId, $row);
    $chat    = $nonChat === '';
    /* ابزار: تیکِ دستیِ کاربر مقدم است؛ بعد حضور در کاتالوگِ ابزارداران؛
       بعد الگویِ نامِ خانواده‌هایی که tools را قابل‌اعتماد پشتیبانی می‌کنند. */
    if (array_key_exists('toolCalling', $row)) {
        $tools = !empty($row['toolCalling']);
    } elseif ($catRow) {
        $tools = true;
    } else {
        $tools = false;
        $low = strtolower($modelId);
        foreach (['llama-3.3', 'llama-3.1', 'llama-4', 'mistral', 'ministral', 'devstral',
                  'magistral', 'leanstral', 'codestral', 'gpt-oss', 'gpt-4', 'gpt-5', 'o3', 'o4-',
                  'claude-', 'gemini-2', 'gemini-3', 'gemini-1.5', 'qwen', 'command-r', 'command-a',
                  'firefunction', 'hermes', 'nemotron', 'glm-4', 'glm-5', 'deepseek-v3', 'deepseek-v4',
                  'deepseek-chat', 'kimi-k2', 'kimi-k3', 'grok', 'bonsai', 'hy3', 'minimax-m', 'mimo'] as $kw) {
            if (strpos($low, $kw) !== false) { $tools = true; break; }
        }
    }
    if (!$chat) $tools = false;
    $reason = $chat && aiIsReasoningModel($row ?: null, $modelId);
    return ['chat' => $chat, 'tools' => $tools, 'reasoning' => $reason, 'why' => $nonChat];
}

/* ══ v10.11 (۲۴): اندپوینتِ چتِ زندهٔ تبِ «💬 چت» ══
   یک پیام (به‌همراه تاریخچهٔ گفت‌وگو) را به مدلِ انتخابی می‌فرستد.
   مدل با همان autoResolveModel به اتصالِ کاربر نگاشت می‌شود؛ اگر
   نگاشت نشد به مدلِ پیش‌فرضِ اتصالات می‌افتد تا چت هرگز بن‌بست نشود. */
if (($_POST['action'] ?? '') === 'ai_chat_send') {
    header('Content-Type: application/json; charset=UTF-8');
    $msg = trim((string)($_POST['message'] ?? ''));
    if ($msg === '') { echo json_encode(['ok'=>false,'error'=>'پیام خالی است'],JSON_UNESCAPED_UNICODE); exit; }
    $model = trim((string)($_POST['model'] ?? ''));
    $sys   = trim((string)($_POST['system'] ?? ''));
    $hist  = json_decode((string)($_POST['history'] ?? '[]'), true);
    if (!is_array($hist)) $hist = [];

    $messages = [];
    if ($sys !== '') $messages[] = ['role' => 'system', 'content' => $sys];
    /* فقط ۱۲ نوبتِ آخر می‌رود تا سقفِ توکنِ مدل‌های کوچک پر نشود */
    $hist = array_slice($hist, -12);
    foreach ($hist as $h) {
        if (!is_array($h)) continue;
        $role = ($h['role'] ?? '') === 'assistant' ? 'assistant' : 'user';
        $txt  = trim((string)($h['content'] ?? ''));
        if ($txt !== '') $messages[] = ['role' => $role, 'content' => mb_substr($txt, 0, 6000)];
    }
    $messages[] = ['role' => 'user', 'content' => mb_substr($msg, 0, 12000)];

    $pin  = $model !== '' ? autoResolveModel($model) : [];
    $isR  = aiIsReasoningModel(null, $model);
    $payload = ['messages' => $messages, 'temperature' => 0.7,
                'max_tokens' => aiReasoningBudget(1200, $isR)];

    $t0 = microtime(true);
    $r  = $pin ? aiProviderCall($pin['provider'], $pin['model'], $payload)
               : aiActiveChat($payload);
    $ms = (int)round((microtime(true) - $t0) * 1000);

    if (empty($r['ok'])) {
        echo json_encode(['ok' => false, 'took' => $ms,
            'error' => (string)($r['error'] ?? ('خطای HTTP ' . (int)($r['code'] ?? 0))),
            'code'  => (int)($r['code'] ?? 0)], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $body = $r['body'] ?? null;
    if (is_string($body)) { $d = json_decode($body, true); if (is_array($d)) $body = $d; }
    $text = aiStripReasoning(aiExtractText($body));
    if (trim($text) === '') {
        echo json_encode(['ok' => false, 'took' => $ms,
            'error' => 'مدل پاسخِ متنی برنگرداند (شاید مدلِ غیرچت است)'], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $used = $pin ? (string)$pin['model'] : '';
    if ($used === '') { $ac = aiActiveConfig(); $used = (string)($ac['model'] ?? ''); }
    echo json_encode(['ok' => true, 'reply' => $text, 'took' => $ms,
        'model' => $used, 'via' => $pin ? (string)$pin['via'] : 'default',
        'provider' => $pin ? (string)($pin['provider']['name'] ?? '') : ''],
        JSON_UNESCAPED_UNICODE);
    exit;
}

/** فهرستِ یکپارچهٔ مدل‌ها را می‌سازد (تا هم اندپوینت و هم آزمون از آن بخورند) */
function aiModelIndexRows(): array {
    $cat = [];
    foreach (autoFreeToolModels() as $cm) $cat[(string)$cm['id']] = $cm;
    $provInfo = autoProviderInfo();

    $out = [];      // شناسهٔ یکتا ⇒ ردیف
    $groups = [];   // شناسهٔ گروه ⇒ برچسبِ نمایشی

    /* ── ۱) مدل‌های واقعیِ کاربر ── */
    foreach (aiProvidersLoad() as $pid => $pr) {
        $pname = (string)($pr['name'] ?? $pid);
        $on    = ($pr['enabled'] ?? true) !== false;
        $gid   = 'conn:' . $pid;
        $groups[$gid] = $pname . ($on ? '' : ' (خاموش)');
        foreach ((array)($pr['models'] ?? []) as $m) {
            if (!is_array($m)) continue;
            $mid = (string)($m['id'] ?? '');
            if ($mid === '') continue;
            $caps = aiModelCaps($mid, $m, $cat[$mid] ?? []);
            $out[$gid . '|' . $mid] = [
                'id'        => $mid,
                'name'      => (string)($m['name'] ?? $mid),
                'group'     => $gid,
                'provider'  => $pname,
                'ready'     => $on,
                'chat'      => $caps['chat'],
                'tools'     => $caps['tools'],
                'reasoning' => $caps['reasoning'],
                'why'       => $caps['why'],
                'tested'    => !empty($m['tested']),
                'available' => !empty($m['available']),
                'note'      => isset($cat[$mid]) ? (string)$cat[$mid]['note'] : '',
                'context'   => isset($cat[$mid]) ? (int)$cat[$mid]['context'] : 0,
                'quality'   => isset($cat[$mid]) ? (int)$cat[$mid]['quality'] : 0,
                'tag'       => isset($cat[$mid]) ? (string)$cat[$mid]['tag'] : '',
            ];
        }
    }

    /* ── ۲) پیشنهادهای کاتالوگ که اتصالشان ثبت نشده ── */
    $haveIds = [];
    foreach ($out as $r) $haveIds[$r['id']] = true;
    foreach (autoFreeToolModels() as $cm) {
        $mid = (string)$cm['id'];
        if (isset($haveIds[$mid])) continue;
        $pv  = (string)$cm['provider'];
        $gid = 'cat:' . $pv;
        $groups[$gid] = 'پیشنهادی — ' . (string)(($provInfo[$pv]['name'] ?? $pv));
        $out[$gid . '|' . $mid] = [
            'id'        => $mid,
            'name'      => (string)$cm['name'],
            'group'     => $gid,
            'provider'  => (string)(($provInfo[$pv]['name'] ?? $pv)),
            'ready'     => false,
            'chat'      => true,
            'tools'     => true,
            'reasoning' => aiIsReasoningModel(null, $mid) || (string)$cm['tag'] === 'reasoning',
            'why'       => '',
            'tested'    => false,
            'available' => false,
            'note'      => (string)$cm['note'],
            'context'   => (int)$cm['context'],
            'quality'   => (int)$cm['quality'],
            'tag'       => (string)$cm['tag'],
        ];
    }

    $rows = array_values($out);
    $n = ['chat' => 0, 'tools' => 0, 'reasoning' => 0, 'ready' => 0];
    foreach ($rows as $r) {
        if ($r['chat'])      $n['chat']++;
        if ($r['tools'])     $n['tools']++;
        if ($r['reasoning']) $n['reasoning']++;
        if ($r['ready'])     $n['ready']++;
    }
    return ['models' => $rows, 'groups' => $groups, 'counts' => $n];
}

if (isset($_GET['ai_model_index'])) {
    /* بافرهای تمِ رنگ را می‌بندیم تا JSON با HTML آلوده نشود — همان الگویی
       که در ?ai_export_providers جواب داد. بدونِ این، روی بعضی هاست‌ها پاسخ
       پارس نمی‌شد و منویِ مدل‌ها بی‌هیچ پیامی خالی می‌ماند. */
    while (@ob_get_level()) @ob_end_clean();
    $r   = aiModelIndexRows();
    $out = json_encode(['ok' => true, 'models' => $r['models'], 'groups' => $r['groups'],
                        'counts' => $r['counts'], 'total' => count($r['models'])],
                       JSON_UNESCAPED_UNICODE);
    header('Content-Type: application/json; charset=UTF-8');
    header('X-Content-Type-Options: nosniff');
    header('Cache-Control: no-store');
    header('Content-Length: ' . strlen($out));
    echo $out;
    exit;
}

/* v9.95 (۹ب): برون‌ریزی (دانلود) فایل JSON تنظیمات ارائه‌دهنده‌ها.
   ?ai_export_providers=1        → با کلیدهای API
   ?ai_export_providers=1&keys=0 → بدون کلید (برای اشتراک‌گذاری امن)      */
if (isset($_GET['ai_export_providers'])) {
// v9.98: هر بایتی که پیش از هدرها چاپ شده باشد (اخطار PHP، BOM، فیلترِ تم)
// فایلِ دانلودی را خراب می‌کند و مرورگر به‌جای ذخیره، متن را نشان می‌دهد.
while (@ob_get_level()) @ob_end_clean();
$withKeys = (string)($_GET['keys'] ?? '1') !== '0';
$data = aiProvidersExportArray($withKeys);
// v9.98: وقتی هیچ ارائه‌دهنده‌ای نیست، json_encode آرایهٔ خالی را «[]»
// می‌نویسد و درون‌ریزیِ دوبارهٔ همان فایل بی‌معنا می‌شود. فقط همین حالت
// به «{}» تبدیل می‌شود — JSON_FORCE_OBJECT به کار نمی‌رود چون فهرستِ
// models را هم به آبجکتِ ایندکس‌دار («{"0":…}») تبدیل می‌کند.
$json = $data === []
      ? '{}'
      : json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT);
if ($json === false) $json = '{}';
$fname = 'ai-providers-' . date('Y-m-d-His') . ($withKeys ? '' : '-nokeys') . '.json';
header('Content-Type: application/json; charset=UTF-8');
header('Content-Disposition: attachment; filename="' . $fname . '"');
header('Content-Length: ' . strlen($json));
header('Cache-Control: no-store');
// v9.98: بدون این هدر، مرورگر ممکن است نوعِ فایل را حدس بزند و به‌جای
// دانلود آن را در تب باز کند.
header('X-Content-Type-Options: nosniff');
echo $json;
exit;
}
/* v9.95 (۹د): جزئیات کاملِ تستِ یک مدل (شاملِ پاسخ خام) برای مودالِ ردیف */
if (isset($_GET['ai_test_detail'])) {
header('Content-Type: application/json; charset=UTF-8');
$pid = trim((string)($_GET['provider'] ?? ''));
$mid = trim((string)($_GET['model'] ?? ''));
$providers = aiProvidersLoad();
$p = $providers[$pid] ?? null;
if (!$p) { echo json_encode(['ok'=>false,'error'=>'ارائه‌دهنده یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
$row = aiFindModelRow($p, $mid);
if (!$row) { echo json_encode(['ok'=>false,'error'=>'مدل یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
$d = is_array($row['testDetails'] ?? null) ? $row['testDetails'] : [];
$ep = aiProviderEndpoint($p, $mid);
// آخرین ردیفِ همین مدل در وضعیتِ تستِ گروهی (اگر باشد) — خطای کاملِ شبکه
$stItem = null;
$st = aiTestStateLoad();
foreach (array_reverse((array)($st['items'] ?? [])) as $it) {
    if (is_array($it) && ($it['provider'] ?? '') === $pid && ($it['model'] ?? '') === $mid) { $stItem = $it; break; }
}
echo json_encode(['ok'=>true,
    'provider'      => $pid,
    'providerName'  => (string)($p['name'] ?? $pid),
    'providerUrl'   => (string)($p['url'] ?? ''),
    'endpoint'      => (string)($ep['url'] ?? ''),
    'model'         => $mid,
    'modelName'     => (string)($row['name'] ?? $mid),
    'tested'        => !empty($row['tested']),
    'available'     => !empty($row['available']),
    'rateLimited'   => !empty($row['rateLimited']),
    'toolCalling'   => !empty($row['toolCalling']),
    'vision'        => !empty($row['vision']),
    'free'          => !empty($row['free']),
    'reasoning'     => aiIsReasoningModel($row, $mid),
    'maxInputTokens'=> (int)($row['maxInputTokens'] ?? 0),
    'maxOutputTokens'=>(int)($row['maxOutputTokens'] ?? 0),
    'status'        => (int)($d['status'] ?? 0),
    'latencyMs'     => (int)($d['latencyMs'] ?? 0),
    'testedAt'      => (string)($d['testedAt'] ?? ''),
    'testMsg'       => (string)($d['testMsg'] ?? ''),
    'testCat'       => (string)($d['testCat'] ?? ''),
    'response'      => (string)($d['response'] ?? ''),
    'catResponse'   => (string)($d['catResponse'] ?? ''),
    'error'         => (string)($d['error'] ?? ''),
    'raw'           => (string)($d['raw'] ?? ''),
    'via'           => (string)($d['via'] ?? ''),
    /* v9.96: پاسخ خامِ درخواستِ دسته‌بندی — درخواستِ دومی که هنگام تست به
       همان مدل زده می‌شود و نتیجه‌اش ستونِ «پاسخ دسته» را پر می‌کند. */
    'catRaw'        => (string)($d['catRaw'] ?? ''),
    'catStatus'     => (int)($d['catStatus'] ?? 0),
    'catVia'        => (string)($d['catVia'] ?? ''),
    'catAiText'     => (string)($d['catAiText'] ?? ''),
    /* v9.97: تأخیر و زمانِ آخرین تستِ دسته‌بندی (وقتی جدا از پیام تست اجرا شده) */
    'catLatencyMs'  => (int)($d['catLatencyMs'] ?? 0),
    'catTestedAt'   => (string)($d['catTestedAt'] ?? ''),
    'itemError'     => $stItem ? (string)($stItem['error'] ?? '') : '',
    'itemLabel'     => $stItem ? (string)($stItem['label'] ?? '') : '',
], JSON_UNESCAPED_UNICODE);
exit;
}
/* v9.95 (۹ج): افزودن ارائه‌دهندهٔ آمادهٔ Mistral با همهٔ مدل‌های متن‌به‌متن */
if (($_POST['action'] ?? '') === 'ai_add_mistral') {
header('Content-Type: application/json; charset=UTF-8');
$cat = aiMistralCatalog();
$key = trim((string)($_POST['api_key'] ?? ''));
$providers = aiProvidersLoad();
$old = $providers['mistral'] ?? null;
// کلیدِ قبلی حفظ می‌شود مگر کلیدِ تازه داده شده باشد
if ($key === '' && is_array($old)) $key = trim((string)($old['apiKey'] ?? ''));
$cat['apiKey'] = $key;
/* v10.01: اگر قبلاً چند کلید برای Mistral ثبت شده بود، حفظشان کن و کلیدِ
   تازه را — اگر تکراری نیست — به همان فهرست اضافه کن. بدون این، هر بار
   «افزودن مدل‌های Mistral» همهٔ کلیدهای پشتیبان را پاک می‌کرد. */
$catKeys = is_array($old) ? aiProviderKeys($old) : [];
if ($key !== '') {
    $dup = false;
    foreach ($catKeys as $ck) if ($ck['key'] === $key) { $dup = true; break; }
    if (!$dup) array_unshift($catKeys, ['key' => $key, 'label' => '', 'enabled' => true]);
}
if ($catKeys) $cat = aiProviderSetKeys($cat, $catKeys);
// نتایجِ تستِ قبلیِ همان مدل‌ها را از دست ندهیم
if (is_array($old)) {
    foreach ($cat['models'] as $i => $m) {
        $prev = aiFindModelRow($old, (string)$m['id']);
        if (!$prev) continue;
        foreach (['tested','available','rateLimited','testDetails'] as $k) {
            if (array_key_exists($k, $prev)) $cat['models'][$i][$k] = $prev[$k];
        }
    }
}
$providers['mistral'] = $cat;
$providers = aiNormalizeProviders($providers);
$ok = aiProvidersSave($providers);
$sel = aiSelected();
if ($sel['provider'] === '' || !isset($providers[$sel['provider']])) {
    aiSaveSelected('mistral', $providers['mistral']['models'][0]['id'] ?? '');
}
echo json_encode(['ok'=>$ok, 'models'=>count($cat['models']), 'has_key'=>$key !== '',
    'message'=>'Mistral با '.count($cat['models']).' مدل متن‌به‌متن اضافه شد'
        .($key === '' ? ' — کلید API را در فایل تنظیمات وارد کنید' : '')], JSON_UNESCAPED_UNICODE);
exit;
}
/* v10.444: تعمیر خودکار یک‌کلیکی همهٔ پروایدرها، آدرس‌ها، مدل‌ها و کلیدهای مسدودِ اشتباه */
if (($_POST['action'] ?? '') === 'ai_repair_providers') {
    header('Content-Type: application/json; charset=UTF-8');
    $providers = aiProvidersLoad();
    $stats = aiRepairProvidersConfig($providers, true);
    $providers = aiNormalizeProviders($providers);
    $ok = aiProvidersSave($providers);
    $msg = sprintf(
        'تعمیر انجام شد: %d آدرس اصلاح شد · %d شناسهٔ مدل استاندارد شد · %d ردیف خراب حذف شد · %d کلید مسدود آزاد شد',
        (int)$stats['urls_fixed'], (int)$stats['models_renamed'], (int)$stats['junk_removed'], (int)$stats['keys_unblocked']
    );
    echo json_encode(['ok' => $ok, 'stats' => $stats, 'message' => $msg], JSON_UNESCAPED_UNICODE);
    exit;
}
/* v10.444: افزودن یک‌کلیکی هر پروایدر استاندارد از کاتالوگ aiProviderPresets */
if (($_POST['action'] ?? '') === 'ai_add_preset') {
    header('Content-Type: application/json; charset=UTF-8');
    $presetId = strtolower(trim((string)($_POST['preset_id'] ?? '')));
    $apiKey   = trim((string)($_POST['api_key'] ?? ''));
    if ($presetId === 'mistral') {
        $preset = aiMistralCatalog();
    } else {
        $presets = aiProviderPresets();
        if (!isset($presets[$presetId])) {
            echo json_encode(['ok' => false, 'error' => 'پروایدر انتخابی در فهرست استاندارد نیست'], JSON_UNESCAPED_UNICODE);
            exit;
        }
        $preset = $presets[$presetId];
    }
    $providers = aiProvidersLoad();
    $old = $providers[$presetId] ?? null;
    if ($apiKey === '' && is_array($old)) $apiKey = trim((string)($old['apiKey'] ?? ''));
    $preset['apiKey'] = $apiKey;
    $preset['enabled'] = true;
    $pKeys = is_array($old) ? aiProviderKeys($old) : [];
    if ($apiKey !== '') {
        $dup = false;
        foreach ($pKeys as $ek) { if ((string)($ek['key'] ?? '') === $apiKey) { $dup = true; break; } }
        if (!$dup) array_unshift($pKeys, ['key' => $apiKey, 'label' => '', 'enabled' => true]);
    }
    if ($pKeys) $preset = aiProviderSetKeys($preset, $pKeys);
    if (is_array($old) && !empty($old['models'])) {
        $mergedModels = (array)$old['models'];
        foreach ((array)($preset['models'] ?? []) as $pm) {
            if (!aiFindModelRow($old, (string)($pm['id'] ?? ''))) $mergedModels[] = $pm;
        }
        $preset['models'] = $mergedModels;
    }
    $providers[$presetId] = $preset;
    $providers = aiNormalizeProviders($providers);
    $ok = aiProvidersSave($providers);
    $sel = aiSelected();
    if ($sel['provider'] === '' || !isset($providers[$sel['provider']])) {
        aiSaveSelected($presetId, (string)($providers[$presetId]['models'][0]['id'] ?? ''));
    }
    echo json_encode([
        'ok' => $ok,
        'provider_id' => $presetId,
        'models' => count($providers[$presetId]['models'] ?? []),
        'message' => 'پروایدر «' . ($preset['name'] ?? $presetId) . '» با تنظیمات استاندارد ذخیره شد',
    ], JSON_UNESCAPED_UNICODE);
    exit;
}
/* درون‌ریزی فایل JSON تنظیمات ارائه‌دهنده‌ها */
if (($_POST['action'] ?? '') === 'ai_import_providers') {
header('Content-Type: application/json; charset=UTF-8');
$jsonStr = trim((string)($_POST['providers_json'] ?? ''));
$parsed = json_decode($jsonStr, true);
if (!is_array($parsed)) { echo json_encode(['ok'=>false,'error'=>'JSON نامعتبر: '.json_last_error_msg()],JSON_UNESCAPED_UNICODE); exit; }
// اگر کل بدنه داخل کلید providers بود بازش کن
if (isset($parsed['providers']) && is_array($parsed['providers'])) $parsed = $parsed['providers'];
$providers = aiNormalizeProviders($parsed);
if (empty($providers)) { echo json_encode(['ok'=>false,'error'=>'در JSON هیچ ارائه‌دهندهٔ معتبری پیدا نشد'],JSON_UNESCAPED_UNICODE); exit; }
$totalModels = 0;
foreach ($providers as $p) $totalModels += count($p['models']);
// اگر فعلاً انتخابی نیست، اولین ارائه‌دهندهٔ روشن را فعال کن
$sel = aiSelected();
if ($sel['provider'] === '' || !isset($providers[$sel['provider']])) {
    $first = null;
    foreach ($providers as $id => $p) { if (($p['enabled'] ?? true) && !empty($p['models'])) { $first = $id; break; } }
    if ($first !== null) aiSaveSelected($first, $providers[$first]['models'][0]['id'] ?? '');
}
$ok = aiProvidersSave($providers);
echo json_encode(['ok'=>$ok, 'providers'=>count($providers), 'models'=>$totalModels,
    'message'=>count($providers).' ارائه‌دهنده با '.$totalModels.' مدل درون‌ریزی شد'], JSON_UNESCAPED_UNICODE);
exit;
}
/* انتخاب ارائه‌دهنده/مدل فعال */
if (($_POST['action'] ?? '') === 'ai_select') {
header('Content-Type: application/json; charset=UTF-8');
$pid = trim($_POST['provider_id'] ?? '');
$mid = trim($_POST['model_id'] ?? '');
$providers = aiProvidersLoad();
if (!isset($providers[$pid])) { echo json_encode(['ok'=>false,'error'=>'ارائه‌دهنده یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
if ($mid === '') $mid = $providers[$pid]['models'][0]['id'] ?? '';
aiSaveSelected($pid, $mid);
echo json_encode(['ok'=>true,'provider'=>$pid,'model'=>$mid], JSON_UNESCAPED_UNICODE);
exit;
}
/* v9.63: روشن/خاموش کردن انفرادیِ یک ارائه‌دهنده — ارائه‌دهندهٔ خاموش به‌همراهِ
   همهٔ مدل‌هایش از «تست مدل‌ها» خارج می‌شود (تست انبوه ارائه‌دهنده‌های خاموش
   را رد می‌کند) ولی داده‌ها و تنظیماتش باقی می‌ماند. */
if (($_POST['action'] ?? '') === 'ai_toggle_provider') {
header('Content-Type: application/json; charset=UTF-8');
$pid = trim($_POST['provider_id'] ?? '');
$providers = aiProvidersLoad();
if (!isset($providers[$pid])) { echo json_encode(['ok'=>false,'error'=>'ارائه‌دهنده یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
$on = !empty($_POST['enabled']);
$providers[$pid]['enabled'] = $on;
$ok = aiProvidersSave($providers);
// اگر این ارائه‌دهنده «فعال» (انتخاب اصلی اتوماسیون) بود و خاموش شد، فعال را عوض کن
if ($on === false && aiSelected()['provider'] === $pid) {
    $cfg = aiActiveConfig();
    $np = is_array($cfg['provider']) ? ($cfg['provider']['id'] ?? '') : '';
    $nm = $cfg['model'] ?? '';
    if ($np !== '' && $np !== $pid) aiSaveSelected($np, $nm);
}
echo json_encode(['ok'=>$ok,'provider'=>$pid,'enabled'=>$on], JSON_UNESCAPED_UNICODE);
exit;
}
/* =====================================================================
 *  v10.01 (۱۵): اندپوینت‌های مدیریتِ چند کلید API
 *    ai_keys_list   — فهرستِ کلیدهای یک ارائه‌دهنده با وضعیتِ سلامت
 *    ai_keys_add    — افزودنِ یک یا چند کلید (هر خط یک کلید)
 *    ai_keys_del    — حذفِ کلید
 *    ai_keys_toggle — روشن/خاموش کردنِ موقتِ کلید
 *    ai_keys_reset  — پاک‌کردنِ برچسبِ خطای کلید (سهمیه تازه شده)
 *  در همهٔ پاسخ‌ها فقط پیش‌نمایشِ ماسک‌شده برمی‌گردد، نه خودِ کلید.
 * ===================================================================== */
if (in_array(($_POST['action'] ?? ''), ['ai_keys_list','ai_keys_add','ai_keys_del',
                                        'ai_keys_toggle','ai_keys_reset'], true)) {
header('Content-Type: application/json; charset=UTF-8');
$act = (string)$_POST['action'];
$pid = trim($_POST['provider_id'] ?? '');
$providers = aiProvidersLoad();
if (!isset($providers[$pid])) { echo json_encode(['ok'=>false,'error'=>'ارائه‌دهنده یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
$p    = $providers[$pid];
$keys = aiProviderKeys($p);
$msg  = '';
$added = 0; $removed = 0; $cleared = 0; $dirty = false;

if ($act === 'ai_keys_add') {
    /* کاربر می‌تواند چند کلید را با هم (هر خط یکی، یا جداشده با کاما/فاصله)
       بچسباند — چون معمولاً چند حسابِ رایگان را یکجا کپی می‌کند. */
    $raw   = (string)($_POST['api_key'] ?? '');
    $label = trim((string)($_POST['label'] ?? ''));
    /* v10.16: شمارهٔ حسابِ اختصاصیِ کلید. برای کلادفلر «کلیدِ دیگر» عملاً
       یعنی «حسابِ دیگر»، چون سهمیه به حساب بسته است نه به توکن؛ پس توکن و
       شمارهٔ حساب باید جفتی ذخیره شوند. */
    $acct  = aiNormalizeAccountId((string)($_POST['account_id'] ?? ''));
    if ($acct === '' && aiProviderNeedsAccount($p)) {
        echo json_encode(['ok'=>false,'error'=>'برای Cloudflare باید شمارهٔ حساب (Account ID) را هم وارد کنید — سهمیه به حساب بسته است نه به توکن.'], JSON_UNESCAPED_UNICODE); exit;
    }
    $parts = preg_split('~[\r\n,;\s]+~u', $raw);
    $have  = [];
    foreach ($keys as $k) $have[$k['key']] = true;
    $dupe = 0;
    foreach ((array)$parts as $one) {
        $one = trim((string)$one);
        if ($one === '' || mb_strlen($one) < 8) continue;
        if (isset($have[$one])) { $dupe++; continue; }
        $have[$one] = true;
        $keys[] = ['id' => aiKeyId($one), 'key' => $one,
                   'label' => $label !== '' ? $label : ('کلید ' . (count($keys) + 1)),
                   'enabled' => true, 'acct' => $acct, 'addedAt' => time()];
        $added++;
    }
    if ($added === 0) {
        echo json_encode(['ok'=>false,'error'=> $dupe > 0
            ? 'این کلید از قبل ثبت شده است'
            : 'کلید معتبری وارد نشد (حداقل ۸ نویسه)'], JSON_UNESCAPED_UNICODE); exit;
    }
    $dirty = true;
    /* کلیدِ تازه سابقهٔ خطا ندارد: نتیجهٔ «اعتبار تمام شد»ِ مدل‌ها باید دور
       ریخته شود تا با کلیدِ جدید دوباره تست شوند. این دقیقاً همان چیزی است
       که نبودش باعث می‌شد کلیدِ نو هم «قرمز» به‌نظر برسد. */
    $p = aiResetKeyRelatedFailures($p);
    $cleared = aiKeyClearState($pid);
    $msg = aiFaNum($added) . ' کلید افزوده شد؛ مدل‌هایی که به‌خاطر اتمام اعتبار رد شده بودند دوباره تست می‌شوند.';
    if ($dupe > 0) $msg .= ' (' . aiFaNum($dupe) . ' کلید تکراری نادیده گرفته شد.)';

} elseif ($act === 'ai_keys_del') {
    $kid = trim($_POST['key_id'] ?? '');
    $keep = [];
    foreach ($keys as $k) { if ($k['id'] === $kid) { $removed++; continue; } $keep[] = $k; }
    if ($removed === 0) { echo json_encode(['ok'=>false,'error'=>'کلید یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
    $keys = $keep;
    $dirty = true;
    aiKeyClearState($pid, $kid);
    $msg = 'کلید حذف شد.';

} elseif ($act === 'ai_keys_toggle') {
    $kid = trim($_POST['key_id'] ?? '');
    $on  = !empty($_POST['enabled']);
    $hit = false;
    foreach ($keys as $i => $k) { if ($k['id'] === $kid) { $keys[$i]['enabled'] = $on; $hit = true; } }
    if (!$hit) { echo json_encode(['ok'=>false,'error'=>'کلید یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
    $dirty = true;
    $msg = $on ? 'کلید روشن شد.' : 'کلید خاموش شد.';

} elseif ($act === 'ai_keys_reset') {
    $kid = trim($_POST['key_id'] ?? '');
    $cleared = aiKeyClearState($pid, $kid);
    /* «سهمیه‌ام تازه شده» ⇒ مدل‌های ردشده به‌خاطر اعتبار هم دوباره تست شوند */
    $p = aiResetKeyRelatedFailures($p);
    $dirty = true;
    $msg = 'وضعیتِ خطای کلید پاک شد؛ در تستِ بعدی دوباره امتحان می‌شود.';
}

if ($dirty) {
    $p = aiProviderSetKeys($p, $keys);
    $providers[$pid] = $p;
    if (!aiProvidersSave($providers)) {
        echo json_encode(['ok'=>false,'error'=>'ذخیرهٔ تنظیمات ناموفق بود'],JSON_UNESCAPED_UNICODE); exit;
    }
}

$state = aiKeyStateLoad();
$rows = [];
foreach (aiProviderKeys($providers[$pid]) as $k) {
    $h = aiKeyHealth($pid, $k['id'], $state);
    $rows[] = ['id'=>$k['id'], 'label'=>$k['label'], 'preview'=>aiKeyPreview($k['key']),
               'enabled'=>$k['enabled'], 'blocked'=>$h['blocked'], 'kind'=>$h['kind'],
               'note'=>$h['label'], 'fails'=>$h['fails'], 'retryIn'=>$h['retryIn'], 'okAt'=>$h['okAt']];
}
echo json_encode(['ok'=>true, 'provider'=>$pid, 'keys'=>$rows, 'count'=>count($rows),
                  'healthy'=>aiHealthyKeyCount($providers[$pid], $pid),
                  'added'=>$added, 'removed'=>$removed, 'cleared'=>$cleared,
                  'msg'=>$msg], JSON_UNESCAPED_UNICODE);
exit;
}
/* v9.94: تیکِ دستیِ «این مدل استدلالی است».
   تشخیصِ خودکار از روی نامِ مدل کار می‌کند، ولی مدل‌های تازه/نام‌های
   غیرمتعارف را نمی‌شناسد؛ این اندپوینت به کاربر اجازه می‌دهد صریحاً
   تعیین کند. با روشن بودنِ آن، سقفِ توکن بزرگ می‌شود و بلوکِ «فکر کردن»
   از پاسخ حذف می‌شود تا دسته‌بندی و پاسخ به مشتری درست کار کند. */
if (($_POST['action'] ?? '') === 'ai_toggle_reasoning') {
header('Content-Type: application/json; charset=UTF-8');
$pid = trim($_POST['provider_id'] ?? '');
$mid = trim($_POST['model_id'] ?? '');
$providers = aiProvidersLoad();
if (!isset($providers[$pid])) { echo json_encode(['ok'=>false,'error'=>'ارائه‌دهنده یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
$on = !empty($_POST['reasoning']);
$found = false;
foreach ($providers[$pid]['models'] as $i => $m) {
    if (($m['id'] ?? '') === $mid) {
        $providers[$pid]['models'][$i]['reasoning'] = $on;
        $found = true;
        break;
    }
}
if (!$found) { echo json_encode(['ok'=>false,'error'=>'مدل یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
$ok = aiProvidersSave($providers);
echo json_encode(['ok'=>$ok,'provider'=>$pid,'model'=>$mid,'reasoning'=>$on,
                  'budget'=>aiReasoningBudget(20, $on)], JSON_UNESCAPED_UNICODE);
exit;
}
/* تست یک مدل و ذخیرهٔ نتیجه در همان مدل */
/* =====================================================================
 *  v10.16 (۲۹ج): تستِ یک کلیدِ مشخص — دکمهٔ «تست» کنارِ هر کلید.
 *
 *  چرا اندپوینتِ جدا: aiProviderCall عمداً «اولین کلیدِ سالم» را برمی‌دارد
 *  و روی خطا می‌چرخد. اینجا دقیقاً برعکسش را می‌خواهیم — همان کلیدی که
 *  کاربر رویش کلیک کرده باید امتحان شود، حتی اگر قبلاً سوخته علامت خورده
 *  باشد (کاربر معمولاً وقتی تست می‌زند که فکر می‌کند سهمیه‌اش تازه شده).
 *  پس مستقیم aiProviderCallOnce صدا زده می‌شود، با کلید و حسابِ خودِ ردیف.
 * ===================================================================== */
if (($_POST['action'] ?? '') === 'ai_keys_test') {
header('Content-Type: application/json; charset=UTF-8');
$pid = trim($_POST['provider_id'] ?? '');
$kid = trim($_POST['key_id'] ?? '');
$providers = aiProvidersLoad();
if (!isset($providers[$pid])) { echo json_encode(['ok'=>false,'error'=>'ارائه‌دهنده یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
$p = $providers[$pid];
$hit = null;
foreach (aiProviderKeys($p) as $k) { if ($k['id'] === $kid) { $hit = $k; break; } }
if ($hit === null) { echo json_encode(['ok'=>false,'error'=>'کلید یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }

/* مدلِ آزمون: مدلِ انتخاب‌شدهٔ همین ارائه‌دهنده، وگرنه اولین مدلش. */
$mid = trim((string)($_POST['model_id'] ?? ''));
if ($mid === '') {
    $sel = aiActiveConfig();
    $selPid = is_array($sel['provider'] ?? null) ? (string)($sel['provider']['id'] ?? '') : '';
    if ($selPid === $pid && (string)$sel['model'] !== '') $mid = (string)$sel['model'];
}
if ($mid === '') {
    foreach ((array)($p['models'] ?? []) as $m) {
        if (!empty($m['id'])) { $mid = (string)$m['id']; break; }
    }
}
if ($mid === '') { echo json_encode(['ok'=>false,'error'=>'این ارائه‌دهنده هیچ مدلی ندارد تا کلید با آن تست شود'],JSON_UNESCAPED_UNICODE); exit; }

/* فقط همین کلید، بدون چرخش. */
$pk = $p;
$pk['apiKey'] = (string)$hit['key'];
$pk = aiApplyKeyAccount($pk, $hit);
$t0 = microtime(true);
$r  = aiProviderCallOnce($pk, $mid, ['messages'=>[['role'=>'user','content'=>'سلام']],
                                     'temperature'=>0.3, 'max_tokens'=>300], aiNetCfg());
/* v10.469: اگر مدلِ پیش‌فرض/اول در سطح اشتراک رایگان نبود (مثلاً mistral-large-latest -> 403 tier_not_allowed
   یا مدل پولی OpenRouter -> 402 یا مدل منسوخ -> 400/404)، همین کلید را با یک مدل در دسترس/پایهٔ همان ارائه‌دهنده بسنج
   تا سلامتِ خودِ کلید دقیق مشخص شود. */
if (empty($r['ok']) && (int)($r['code'] ?? 0) !== 401) {
    $altMids = [];
    if ($pid === 'mistral' || aiDetectProviderDialect($p) === 'mistral') {
        $altMids = ['ministral-8b-latest', 'mistral-small-latest', 'ministral-14b-latest'];
    }
    foreach ((array)($p['models'] ?? []) as $_mRow) {
        if (!is_array($_mRow)) continue;
        $_cid = trim((string)($_mRow['id'] ?? ''));
        if ($_cid === '' || $_cid === $mid || aiNonChatModel($_cid, $_mRow) !== '') continue;
        if (!empty($_mRow['available']) || !empty($_mRow['free']) || stripos($_cid, ':free') !== false || stripos($_cid, '-free') !== false) {
            if (!in_array($_cid, $altMids, true)) $altMids[] = $_cid;
        }
    }
    foreach (array_slice($altMids, 0, 2) as $_altMid) {
        if ($_altMid === $mid) continue;
        $_tAlt = microtime(true);
        $_rAlt = aiProviderCallOnce($pk, $_altMid, ['messages'=>[['role'=>'user','content'=>'سلام']],
                                                    'temperature'=>0.3, 'max_tokens'=>300], aiNetCfg());
        if ((int)($_rAlt['code'] ?? 0) === 200 && !empty($_rAlt['ok'])) {
            $r = $_rAlt;
            $mid = $_altMid;
            $t0 = $_tAlt;
            break;
        }
    }
}
$latency = (int)round((microtime(true) - $t0) * 1000);
$code = (int)($r['code'] ?? 0);
$ok   = $code === 200 && !empty($r['ok']);
$body = $r['body'] ?? [];
$ans  = $ok ? aiExtractAnswer($body) : '';
/* کلادفلر پیامِ خطا را در errors[] می‌گذارد نه error.message؛ اگر آن را
   نخوانیم کاربر فقط یک «HTTP 402»ِ بی‌معنا می‌بیند و نمی‌فهمد باید حساب را
   شارژ کند یا توکن را عوض کند. */
$err  = '';
if (!$ok) {
    $cfe = is_array($body) ? aiCloudflareError($r) : '';
    $err = $cfe !== '' ? $cfe
         : ($body['error']['message'] ?? ($body['message'] ?? ($r['error'] ?? ('HTTP '.$code))));
}

/* نتیجه در همان دفترِ سلامتِ کلیدها ثبت می‌شود تا رنگِ ردیف بی‌درنگ
   درست شود — تستِ موفق یعنی «سهمیه‌اش برگشته». */
$kf = aiKeyFailureKind($r);
if ($ok) { aiKeyMarkOk($pid, $kid); $providers[$pid] = aiResetKeyRelatedFailures($p); aiProvidersSave($providers); }
elseif ($kf['kind'] !== '') aiKeyMarkFail($pid, $kid, $kf['kind'], $kf['label'], $kf['msg']);

echo json_encode(['ok'=>true, 'pass'=>$ok, 'code'=>$code, 'model'=>$mid,
    'latencyMs'=>$latency, 'answer'=>mb_substr((string)$ans, 0, 200),
    'error'=>mb_substr((string)$err, 0, 300),
    'kind'=>(string)$kf['kind'], 'note'=>(string)$kf['label'],
    'acct'=>(string)($hit['acct'] ?? ''),
    'preview'=>aiKeyPreview((string)$hit['key'])], JSON_UNESCAPED_UNICODE);
exit;
}
if (($_POST['action'] ?? '') === 'ai_test_one') {
header('Content-Type: application/json; charset=UTF-8');
$pid = trim($_POST['provider_id'] ?? '');
$mid = trim($_POST['model_id'] ?? '');
$providers = aiProvidersLoad();
if (!isset($providers[$pid])) { echo json_encode(['ok'=>false,'error'=>'ارائه‌دهنده یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
$found = false;
foreach ($providers[$pid]['models'] as $i => $m) {
    if (($m['id'] ?? '') === $mid) { $found = true; break; }
}
if (!$found) { echo json_encode(['ok'=>false,'error'=>'مدل یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
/* v10.17 (۳۰): اگر شناسهٔ کلید آمده، تست فقط با همان کلید انجام می‌شود
   (بدون چرخش) — دقیقاً همان ردیفی که کاربر در فهرست دیده. */
$kid  = trim((string)($_POST['key_id'] ?? ''));
$slot = $kid !== '' ? aiTestKeySlot($providers[$pid], $kid) : null;
if ($kid !== '' && $slot === null) { echo json_encode(['ok'=>false,'error'=>'کلید یافت نشد یا خاموش است'],JSON_UNESCAPED_UNICODE); exit; }
$ksfx = $slot ? (string)$slot['suffix'] : '';
$pRun = $kid !== '' ? aiPinProviderKey($providers[$pid], $kid) : $providers[$pid];
// v9.52: پیام تست و دستهٔ تستِ قابل‌تنظیم (پیش‌فرض «سلام» و «ادو پرفیوم»)
$testMsg = trim((string)($_POST['msg'] ?? 'سلام'));
if ($testMsg === '') $testMsg = 'سلام';
$testCat = trim((string)($_POST['cat'] ?? 'ادو پرفیوم'));
if ($testCat === '') $testCat = 'ادو پرفیوم';
/* v10.00 (۱۴ب): اول دسته‌بندی، بعد پیام — دقیقاً مثل مسیرِ تستِ گروهی.
   دلیل: ریت‌لیمیتِ دقیقه‌ایِ سرویس‌های رایگان معمولاً درخواستِ *دوم* را رد
   می‌کند و دسته‌بندی برای کاربر مهم‌تر از پیامِ نمونه است. */
$catMeta = null;
$catResponse = aiRunTestCategory($pRun, $mid, $testCat, aiTestCategoryData(), null, $catMeta);
$t0 = microtime(true);
// v9.57: سقف توکن برای تست بالاتر رفت (۳۰۰) — مدل‌های reasoning (مثل gpt-oss،
// qwen، nemotron و...) اول روی «فکر کردن» توکن می‌سوزانند و اگر سقف پایین باشد
// (۳۰) هیچ‌وقت به content نمی‌رسند و پاسخِ خالی برمی‌گردد.
$payload = ['messages'=>[['role'=>'user','content'=>$testMsg]], 'temperature'=>0.3, 'max_tokens'=>300];
$r = aiProviderCall($pRun, $mid, $payload, aiNetCfg());
$latency = (int)round((microtime(true) - $t0) * 1000);
/* v10.218: تستِ تکی هم دقیقاً با داور مشترک قضاوت می‌شود؛ HTTP 200 با
   پاسخِ بی‌معنی/خالی دیگر به‌اشتباه سبز نمی‌شود و متن خطای Worker خام هم
   نمایش داده می‌شود. */
$j = aiTestJudge($r, $mid, $pid);
$code = (int)$j['code'];
$ok = !empty($j['ok']);
$response = (string)$j['response'];
$err = $ok ? '' : (string)$j['error'];
$rateLimited = in_array($code, [429], true);
$catOkOne = aiModelHasProperCatAnswer(['catResponse' => (string)$catResponse, 'catStatus' => (int)($catMeta['status'] ?? 0)]);
$details = ['status'=>$code, 'error'=>mb_substr((string)$err,0,300), 'response'=>mb_substr((string)$response,0,300),
            'catResponse'=>(string)$catResponse, 'catOk'=>$catOkOne, 'testMsg'=>$testMsg, 'testCat'=>$testCat,
            'latencyMs'=>$latency, 'testedAt'=>gmdate('c'),
            // v9.95 (۹د): بدنهٔ خامِ پاسخِ سرویس برای مودالِ «جزئیات کامل»
            'raw'=>mb_substr((string)($r['raw'] ?? ''), 0, 4000), 'via'=>(string)($r['via'] ?? ''),
            // v9.96: پاسخ خامِ درخواستِ دسته‌بندی (درخواستِ دوم) جداگانه
            'catRaw'=>(string)($catMeta['raw'] ?? ''), 'catStatus'=>(int)($catMeta['status'] ?? 0),
            'catVia'=>(string)($catMeta['via'] ?? ''), 'catAiText'=>(string)($catMeta['aiText'] ?? ''),
            // v10.01: دستهٔ خطا و توضیحِ فارسیِ آن — مثل مسیرِ گروهی
            'kind'=>(string)$j['kind'], 'note'=>(string)$j['note'],
            // v10.17 (۳۰): این نتیجه با کدام کلید گرفته شد
            'keyId'=>$kid, 'keySuffix'=>$ksfx, 'keyLabel'=>$slot ? (string)$slot['label'] : '',
            'payloadRepair'=>(string)($r['payload_repair'] ?? '')];
foreach ($providers[$pid]['models'] as $i => $m) {
    if (($m['id'] ?? '') === $mid) {
        $prevStatsOne = aiModelNormalizeTestStats(is_array($m) ? $m : ['id' => $mid]);
        /* v10.17 (۳۰): نتیجهٔ همین کلید جدا ثبت می‌شود و «در دسترس بودن»ِ
           مدل «یا»ی همهٔ کلیدهاست — کلیدِ خرابِ دوم مدلِ سالم را قرمز نکند. */
        $anyOk = $ok;
        if ($kid !== '') {
            $kt = (array)($providers[$pid]['models'][$i]['keyTests'] ?? []);
            $kt[$kid] = ['tested'=>true, 'available'=>$ok, 'label'=>$slot ? (string)$slot['label'] : '',
                         'suffix'=>$ksfx, 'runEpoch'=>(int)($GLOBALS['_aiTestRunEpoch'] ?? time()), 'latencyMs'=>$latency, 'status'=>$code,
                         'kind'=>(string)$j['kind'], 'error'=>mb_substr((string)$err,0,200),
                         'billing'=>(string)$j['billing'], 'testedAt'=>gmdate('c')];
            $providers[$pid]['models'][$i]['keyTests'] = $kt;
            foreach ($kt as $kk2 => $kv2) { if ($kk2 !== $kid && !empty($kv2['available'])) { $anyOk = true; break; } }
        }
        $providers[$pid]['models'][$i]['tested'] = true;
        $providers[$pid]['models'][$i]['available'] = $anyOk;
        $providers[$pid]['models'][$i]['rateLimited'] = $rateLimited && !$anyOk;
        // v10.01: علتِ «اعتبار/اشتراک» اینجا هم ثبت می‌شود تا افزودنِ کلیدِ
        // تازه بتواند این مدل را برای تستِ دوباره آزاد کند.
        if ($j['billing'] !== '' && !$anyOk) $providers[$pid]['models'][$i]['billingIssue'] = $j['billing'];
        else                                 unset($providers[$pid]['models'][$i]['billingIssue']);
        $providers[$pid]['models'][$i]['testDetails'] = $details;
        $providers[$pid]['models'][$i]['testStats'] = aiModelUpdateTestStats(
            $prevStatsOne, $anyOk, $catOkOne, $latency, 0, $anyOk ? 200 : $code, $anyOk ? '' : (string)$j['kind'], time()
        );
        break;
    }
}
aiProvidersSave($providers);
echo json_encode(['ok'=>true, 'model'=>$mid, 'provider'=>$pid, 'available'=>$ok,
    // v10.17 (۳۰): پسوندِ کلیدی که این تست با آن انجام شد
    'keyId'=>$kid, 'keySuffix'=>$ksfx,
    'rateLimited'=>$rateLimited, 'latencyMs'=>$latency, 'code'=>$code, 'error'=>$err,
    'response'=>mb_substr($response,0,200), 'catResponse'=>(string)$catResponse,
    // v10.01: توضیحِ فارسیِ خطا و وضعیتِ چرخشِ کلید برای نمایشِ بی‌درنگ
    'kind'=>(string)$j['kind'], 'note'=>(string)$j['note'], 'billing'=>(string)$j['billing'],
    'keysExhausted'=>!empty($r['keysExhausted']), 'keyRotated'=>(int)($r['keyRotated'] ?? 0),
    'keyPreview'=>(string)($r['keyPreview'] ?? ''), 'payloadRepair'=>(string)($r['payload_repair'] ?? '')], JSON_UNESCAPED_UNICODE);
exit;
}
/* =====================================================================
 *  v9.97: تستِ دوبارهٔ «فقط دسته‌بندی» برای یک مدل.
 *
 *  در مودالِ «جزئیات کاملِ تستِ مدل» دکمهٔ «🔁 تست دوبارهٔ همین مدل» هر دو
 *  درخواست (پیام + دسته‌بندی) را از نو می‌زد. وقتی فقط می‌خواهید ببینید چرا
 *  دسته‌بندی خطا می‌دهد، تکرارِ درخواستِ پیام هم وقت می‌برد و هم بی‌جهت
 *  سهمیه/ریت‌لیمیت می‌سوزاند. این اندپوینت فقط درخواستِ دوم را می‌زند و
 *  تنها کلیدهای دسته‌بندیِ testDetails را به‌روز می‌کند — پاسخِ پیام تست،
 *  تأخیر، کد وضعیت و خامِ آن دست‌نخورده باقی می‌ماند.
 *
 *  توجه: available/tested مدل را عوض نمی‌کند، چون معیارِ «در دسترس بودن»
 *  همان درخواستِ پیام است؛ شکستِ دسته‌بندی می‌تواند فقط به‌خاطر نبودِ
 *  توکنِ باسلام یا بدفرمت‌بودنِ خروجیِ مدل باشد.
 * ===================================================================== */
if (($_POST['action'] ?? '') === 'ai_test_one_cat') {
header('Content-Type: application/json; charset=UTF-8');
$pid = trim($_POST['provider_id'] ?? '');
$mid = trim($_POST['model_id'] ?? '');
$providers = aiProvidersLoad();
if (!isset($providers[$pid])) { echo json_encode(['ok'=>false,'error'=>'ارائه‌دهنده یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
$idx = -1;
foreach ($providers[$pid]['models'] as $i => $m) { if (($m['id'] ?? '') === $mid) { $idx = $i; break; } }
if ($idx < 0) { echo json_encode(['ok'=>false,'error'=>'مدل یافت نشد'],JSON_UNESCAPED_UNICODE); exit; }
$testCat = trim((string)($_POST['cat'] ?? ''));
if ($testCat === '') $testCat = trim((string)($providers[$pid]['models'][$idx]['testDetails']['testCat'] ?? ''));
if ($testCat === '') $testCat = 'ادو پرفیوم';
$catData = aiTestCategoryData();
if (!$catData) {
    echo json_encode(['ok'=>false,'error'=>'دسته‌های باسلام در دسترس نیست — توکنِ باسلام را در تنظیمات ← اتصالات وارد کنید.'],JSON_UNESCAPED_UNICODE);
    exit;
}
$t0 = microtime(true);
$catMeta = null;
$catResponse = aiRunTestCategory($providers[$pid], $mid, $testCat, $catData, null, $catMeta);
$catLatency = (int)round((microtime(true) - $t0) * 1000);
/* فقط کلیدهای دسته‌بندی را روی جزئیاتِ موجود بنویس — بقیه دست‌نخورده */
$catOkOnly = aiModelHasProperCatAnswer(['catResponse' => (string)$catResponse, 'catStatus' => (int)($catMeta['status'] ?? 0)]);
$d = (array)($providers[$pid]['models'][$idx]['testDetails'] ?? []);
$d['catResponse']  = (string)$catResponse;
$d['catOk']        = $catOkOnly;
$d['testCat']      = $testCat;
$d['catRaw']       = (string)($catMeta['raw'] ?? '');
$d['catStatus']    = (int)($catMeta['status'] ?? 0);
$d['catVia']       = (string)($catMeta['via'] ?? '');
$d['catAiText']    = (string)($catMeta['aiText'] ?? '');
$d['catLatencyMs'] = $catLatency;
$d['catTestedAt']  = gmdate('c');
$providers[$pid]['models'][$idx]['testDetails'] = $d;
$stCat = aiModelNormalizeTestStats((array)$providers[$pid]['models'][$idx]);
$stCat['last_cat_ok'] = $catOkOnly;
if ($catOkOnly !== null) {
    $stCat['cat_runs'] = max(1, (int)($stCat['cat_runs'] ?? 0) + 1);
    if ($catOkOnly === true) $stCat['cat_ok_runs'] = max(0, (int)($stCat['cat_ok_runs'] ?? 0)) + 1;
}
$stCat['last_proper'] = aiModelIsProperInLatestTest((array)$providers[$pid]['models'][$idx], false) && ($catOkOnly !== false);
$providers[$pid]['models'][$idx]['testStats'] = $stCat;
aiProvidersSave($providers);
echo json_encode(['ok'=>true, 'provider'=>$pid, 'model'=>$mid, 'testCat'=>$testCat,
    'catResponse'=>(string)$catResponse, 'catStatus'=>(int)($catMeta['status'] ?? 0),
    'catVia'=>(string)($catMeta['via'] ?? ''), 'catLatencyMs'=>$catLatency], JSON_UNESCAPED_UNICODE);
exit;
}
/* تست همهٔ مدل‌های فعال (SSE) — با سقف به‌ازای هر ارائه‌دهنده */
/* =====================================================================
 *  v9.24: تست مدل‌ها به‌صورت کارِ پس‌زمینهٔ سمت سرور
 *
 *  ?ai_test_start=1  → شروع تست در پس‌زمینه (جدا از مرورگر) + پاسخ فوری
 *  ?ai_test_all=1    → نامِ سازگار (همان شروع) برای نسخه‌های قبلی
 *  ?ai_test_status=1 → وضعیت فعلی کار (poll شده توسط مرورگر)
 *  ?ai_test_stop=1   → سیگنال توقف صریح
 * ===================================================================== */
if (isset($_GET['ai_test_status'])) {
header('Content-Type: application/json; charset=UTF-8');
$st = aiTestStateLoad();
/* v9.45: نگهبانِ گیرکردن. اگر پردازهٔ پس‌زمینه مرده باشد (کشته شده)،
   running تا ابد true می‌ماند و مرورگر بی‌نهایت poll می‌کند. وقتی چند دقیقه
   است هیچ به‌روزرسانی‌ای (updated_at) نیامده، یعنی پردازه دیگر زنده نیست —
   آن را «متوقف شده» علامت بزن تا رابط کاربری رها شود. همین الگو در جای‌های
   دیگر (extractProgress و... ) هم هست. */
if (!empty($st['running']) && empty($st['done'])) {
    $stAt = (int)($st['updated_at'] ?? $st['started_at'] ?? 0);
    $idle = $stAt > 0 ? (time() - $stAt) : PHP_INT_MAX;
    $stall = max(120, (int)(loadConnections()['ai_test_stall_sec'] ?? 300));
    if ($idle > $stall && !aiTestLockHeld()) {
        $st['running'] = false;
        $st['done'] = true;
        $st['stopped'] = true;
        $st['stalled'] = true;
        /* v9.99: «رفعِ گیر» — کارِ نیمه‌تمام دور ریخته نمی‌شود. چون نتیجهٔ هر
           دور بلافاصله در ai_providers.json ذخیره شده، با only_untested
           می‌توان دقیقاً از همان‌جا ادامه داد. این پرچم را UI می‌بیند و دکمهٔ
           «ادامه» را نشان می‌دهد؛ اگر خودکار هم باشد، همان‌جا ازسرگیری می‌کند. */
        $st['resumable'] = true;
        $st['idle_sec'] = $idle;
        $st['summary'] = 'گیر کرد (پردازهٔ پس‌زمینه ' . $idle . ' ثانیه پاسخ نداد) — با «ادامه» از همان‌جا دنبال می‌شود';
        aiTestStateSave($st);
    }
}
echo json_encode($st, JSON_UNESCAPED_UNICODE);
exit;
}
/* =====================================================================
 *  v10.36 (۴۹د): آمارِ تفصیلیِ مدل‌ها — پشتِ کارت‌های زیرِ دکمه‌های تست
 *
 *  ?ai_stats=1
 *
 *  چرا از ai_providers.json و نه از فایلِ وضعیتِ تست: فایلِ وضعیت فقط
 *  «همین اجرا» را می‌شناسد و با هر اجرای تازه صفر می‌شود. ولی نتیجهٔ هر
 *  مدل بلافاصله در کاتالوگِ ارائه‌دهنده‌ها ذخیره می‌شود، پس آمارِ آنجا
 *  ماندگار و کامل است — حتی برای مدل‌هایی که ماه‌ها پیش آزموده شده‌اند.
 * ===================================================================== */
if (isset($_GET['ai_stats'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $provs = aiProvidersLoad();
    $tot = 0; $tested = 0; $okN = 0; $failN = 0; $rate = 0;
    $tool = 0; $reason = 0; $free = 0; $excludedInvalid = 0; $excludedNonchat=0;
    $latSum = 0; $latN = 0; $fastest = [];
    $byProv = []; $keyTotal = 0; $keyHealthy = 0;

    foreach ($provs as $pid => $p) {
        if (!is_array($p)||($p['enabled']??true)===false) continue;
        $pname = trim((string)($p['name'] ?? $pid));
        $models = is_array($p['models'] ?? null) ? $p['models'] : [];
        $pRow = ['id' => (string)$pid, 'name' => $pname !== '' ? $pname : (string)$pid,
                 'total' => 0, 'tested' => 0, 'ok' => 0, 'fail' => 0, 'lat' => 0];
        $pLatSum = 0; $pLatN = 0;
        foreach ((array)(aiTestKeySlots($p)) as $sl) { $keyTotal++; }
        foreach ($models as $m) {
            if (!is_array($m)) continue;
            if(!empty($m['feedbackExcluded'])){$excludedInvalid++;continue;}
            if(aiNonChatModel((string)($m['id']??''),$m)!==''){$excludedNonchat++;continue;}
            $tot++; $pRow['total']++;
            if (!empty($m['toolCalling'])) $tool++;
            if (function_exists('aiIsReasoningModel') && aiIsReasoningModel($m)) $reason++;
            if (!empty($m['free'])) $free++;
            $isT = !empty($m['tested']);
            $isA = !empty($m['available']);
            if (!empty($m['rateLimited'])) $rate++;
            if ($isT) {
                $tested++; $pRow['tested']++;
                if ($isA) { $okN++; $pRow['ok']++; } else { $failN++; $pRow['fail']++; }
            }
            $lat = (int)($m['testDetails']['latencyMs'] ?? 0);
            if ($isT && $isA && $lat > 0) {
                $latSum += $lat; $latN++; $pLatSum += $lat; $pLatN++;
                $fastest[] = ['model' => (string)($m['id'] ?? ''), 'provider' => $pRow['name'], 'lat' => $lat];
            }
        }
        if ($pLatN > 0) $pRow['lat'] = (int)round($pLatSum / $pLatN);
        if ($pRow['total'] > 0) $byProv[] = $pRow;
    }
    /* سالم‌ترین ارائه‌دهنده‌ها اول — معیار «تعدادِ مدلِ سالم» است نه درصد،
       چون ارائه‌دهنده‌ای با یک مدلِ سالم نباید بالاتر از یکی با ۴۰ بنشیند. */
    usort($byProv, fn($a, $b) => ($b['ok'] <=> $a['ok']) ?: ($a['lat'] <=> $b['lat']));
    usort($fastest, fn($a, $b) => $a['lat'] <=> $b['lat']);

    $st = aiTestStateLoad();
    echo json_encode([
        'ok' => true,
        'total' => $tot, 'tested' => $tested, 'untested' => max(0, $tot - $tested),
        'available' => $okN, 'failed' => $failN, 'rate_limited' => $rate,
        'tool_calling' => $tool, 'reasoning' => $reason, 'free' => $free, 'excluded_invalid'=>$excludedInvalid, 'excluded_nonchat'=>$excludedNonchat,
        'providers' => count($byProv), 'key_slots' => $keyTotal,
        'avg_latency' => $latN > 0 ? (int)round($latSum / $latN) : 0,
        'health_pct' => $tested > 0 ? (int)round($okN * 100 / $tested) : 0,
        'coverage_pct' => $tot > 0 ? (int)round($tested * 100 / $tot) : 0,
        'by_provider' => array_slice($byProv, 0, 12),
        'fastest' => array_slice($fastest, 0, 5),
        'last_run' => (int)($st['updated_at'] ?? $st['started_at'] ?? 0),
        'last_summary' => (string)($st['summary'] ?? ''),
        'running' => !empty($st['running']) && empty($st['done']),
    ], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['ai_test_stop'])) {
    /* v9.42: فایل توقف را مقاوم بنویس — writeJsonFile اول با قفل تلاش می‌کند
       و اگر قفل روی FUSE/ترموکس پشتیبانی نشد، بدون قفل می‌نویسد. قبلاً با
       LOCK_EX مستقیم اگر نوشتن بی‌صدا fail می‌شد، پردازهٔ پس‌زمینه هیچ‌وقت
       توقف را نمی‌دید. */
    writeJsonFile(AI_TEST_STOP_FILE, ['stop' => true, 'time' => time()]);
    $st = aiTestStateLoad();
    $st['stopping'] = true;
    aiTestStateSave($st);
    /* v9.45: اگر پردازهٔ پس‌زمینه دیگر زنده نباشد (کشته شده)، هیچ‌کس نمی‌آید
       running را false کند و رابط کاربری تا ابد «در حال اجراست» نشان می‌داد.
       اینجا حالت را مستقیم «متوقف شده» می‌کنیم تا poll مرورگر همان لحظه ببیند
       کار تمام شده. پردازهٔ زنده هم وقتی سیگنال توقف را می‌بیند خودش همان
       نتیجه را می‌نویسد (همان مقدار). */
    if (!empty($st['running']) && empty($st['done'])) {
        $st['running'] = false;
        $st['done'] = true;
        $st['stopped'] = true;
        $st['summary'] = 'توقف خواسته شد';
        aiTestStateSave($st);
    }
    header('Content-Type: application/json; charset=UTF-8');
    echo json_encode(['ok' => true, 'stopping' => true], JSON_UNESCAPED_UNICODE);
    exit;
}

/* v9.52: دادهٔ دسته‌بندی برای «تست دسته» — دسته‌های برگِ باسلام را یک‌بار
   می‌گیرد و برای همهٔ مدل‌ها به‌کار می‌برد تا در تستِ انبوه دوباره‌دوباره
   درخواستِ categories نرود. اگر توکن باسلام نباشد null برمی‌گردد. */
function aiTestCategoryData(): ?array {
    $cn = loadConnections(); $bs = $cn['basalam'] ?? [];
    $tk = trim((string)($bs['token'] ?? ''));
    if ($tk === '') return null;
    $cats = [];
    $cats = bslCatsAll($tk); /* v10.41 (۵۵): از کشِ مشترک */
    if (!$cats) return null;
    $leafCats = [];
    foreach ($cats as $c) { if (($c['level'] ?? 0) >= 2) $leafCats[] = $c; }
    if (!$leafCats) $leafCats = $cats;
    /* v10.40 (۵۴ب): ساختِ فهرست به هلپرِ مشترک سپرده شد. نسخهٔ قبلی
       دستیِ اینجا هم همان باگِ «بریدن با بایت» را داشت (۳۰۰۰ بایت روی
       متنِ فارسی ≈ ۶۹ دسته) و علاوه بر آن با array_slice(…,200) فقط
       ۲۰۰ دستهٔ اولِ درخت را نگه می‌داشت. */
    $catList = aiCatListBuild($leafCats, []);
    return ['cats' => $cats, 'leafCats' => $leafCats, 'catList' => $catList];
}

/* v9.52: اجرای تستِ دسته‌بندی برای یک مدل و خلاصه‌سازی نتیجه به رشتهٔ کوتاه.
   اگر catData نباشد یا عنوان خالی باشد null برمی‌گردد. */
/* v9.96: پارامترِ خروجیِ $meta پاسخِ خامِ درخواستِ دسته‌بندی را برمی‌گرداند
   (raw/status/via/ai_text) تا در مودالِ «جزئیات کاملِ تست» ذخیره و نشان داده شود. */
function aiRunTestCategory(array $p, string $mid, string $testCat, ?array $catData, ?array $net = null, ?array &$meta = null): ?string {
    $meta = ['raw' => '', 'status' => 0, 'via' => '', 'aiText' => ''];
    if ($testCat === '' || !$catData) return null;
    if ($net === null) $net = aiNetCfg();
    $res  = aiCandidateCategory($p, $mid, $testCat, $catData['cats'], $catData['leafCats'], $catData['catList'], $net);
    $meta = aiCatMeta($res);
    return aiCatSummary($res);
}

/* =====================================================================
 *  v9.99: اجرای موازیِ چرخشی (round-robin) با curl_multi
 *
 *  خواستهٔ کاربر: «اول مدلِ اولِ همهٔ ارائه‌دهنده‌ها، بعد مدلِ دومِ همه، و
 *  همین‌طور تا آخر» — تا هم کلِ لیست سریع‌تر تمام شود و هم ریت‌لیمیت نخوریم.
 *
 *  چرا این ترتیب دقیقاً ریت‌لیمیت را کم می‌کند: ریت‌لیمیت همیشه «به ازای هر
 *  ارائه‌دهنده» است. اگر ۵۰ مدلِ OpenRouter را پشت‌سرهم بزنیم، ۵۰ درخواست در
 *  چند ثانیه به یک ارائه‌دهنده می‌خورد و از RPM آن رد می‌شویم. ولی در حالتِ
 *  چرخشی، هر «دور» فقط یک درخواست به هر ارائه‌دهنده می‌فرستد و درخواست‌های
 *  هم‌زمان روی ارائه‌دهنده‌های *متفاوت* پخش می‌شوند. نتیجه: هم‌زمانیِ واقعی
 *  بالا می‌رود ولی نرخِ هر ارائه‌دهنده پایین می‌ماند.
 *
 *  aiTestBuildQueue(): صفِ چرخشی را می‌سازد (دور ۱ = مدلِ اولِ همه، …).
 *  aiParallelCalls():  یک دسته درخواست را با curl_multi هم‌زمان می‌فرستد.
 * ===================================================================== */
function aiTestBuildQueue(array $providers, int $per, bool $onlyUntested, bool $skipNonChat = true, array &$stats = []): array {
    $stats = ['skipped' => 0, 'nonchat' => 0, 'keys' => 0, 'multikey' => 0];
    // ۱) فهرستِ مدل‌های هر ارائه‌دهنده (با رعایتِ سقف و فیلترها)
    $byProv = [];
    foreach ($providers as $pid => $p) {
        if (($p['enabled'] ?? true) === false) continue;
        /* v10.17 (۳۰): هر کلیدِ فعال یک «اسلات» است. با دو کلید، هر مدل دو
           بار (یک‌بار با هر کلید) وارد صف می‌شود و ردیف‌ها با پسوند از هم
           جدا می‌مانند. سقفِ «مدل به‌ازای هر ارائه‌دهنده» همچنان روی *مدل*
           اعمال می‌شود نه روی ردیف — یعنی سقفِ ۵۰ با دو کلید ۱۰۰ ردیف
           می‌سازد، همان‌طور که کاربر انتظار دارد. */
        $slots = aiTestKeySlots($p);
        $stats['keys'] += count($slots);
        if (count($slots) > 1) $stats['multikey']++;
        $n = 0; $list = [];
        foreach ((array)($p['models'] ?? []) as $m) {
            $mid = (string)($m['id'] ?? '');
            if ($mid === '' || !empty($m['feedbackExcluded'])) continue;
            /* v9.99: مدل‌های غیرچت (امبدینگ/تصویر/صوت/rerank) اصلاً وارد صف
               نمی‌شوند — تستِ چت روی آن‌ها همیشه شکست می‌خورد. */
            if ($skipNonChat) {
                $why = aiNonChatModel($mid, is_array($m) ? $m : []);
                if ($why !== '') { $stats['nonchat']++; continue; }
            }
            /* v10.17: «فقط تست‌نشده» حالا برای هر کلید جداگانه سنجیده
               می‌شود؛ اگر مدل با کلیدِ اول تست شده ولی با کلیدِ دوم نه،
               فقط اسلاتِ کلیدِ دوم وارد صف می‌شود.
               v10.476: در ادامهٔ تست روزانهٔ ناتمام (_aiTestResumeEpoch)، فقط ردیف‌هایی
               رد می‌شوند که در همین چرخهٔ روزانه قبلاً تست شده‌اند. */
            $resumeEpoch = max(0, (int)($GLOBALS['_aiTestResumeEpoch'] ?? 0));
            $mSlots = [];
            foreach ($slots as $sl) {
                if ($onlyUntested) {
                    if ($resumeEpoch > 0) {
                        $slId = (string)$sl['id'];
                        $mArr = is_array($m) ? $m : [];
                        $keyTestRow = ($slId !== '' && is_array($mArr['keyTests'][$slId] ?? null)) ? $mArr['keyTests'][$slId] : [];
                        $rowEpoch = (int)($keyTestRow['runEpoch'] ?? (($slId === '') ? ($mArr['testDetails']['runEpoch'] ?? 0) : 0));
                        $rowAtStr = ($slId !== '' && isset($keyTestRow['testedAt']))
                            ? (string)$keyTestRow['testedAt']
                            : ((string)($mArr['testDetails']['keyId'] ?? '') === $slId || $slId === ''
                                ? (string)($mArr['testDetails']['testedAt'] ?? '') : '');
                        $rowAtTs = $rowAtStr !== '' ? max(0, (int)@strtotime($rowAtStr)) : 0;
                        if ($rowEpoch >= $resumeEpoch || $rowAtTs >= $resumeEpoch) continue;
                    } elseif (aiModelKeyTested(is_array($m) ? $m : [], (string)$sl['id'])) {
                        continue;
                    }
                }
                $mSlots[] = $sl;
            }
            if (!$mSlots) continue;
            if ($n >= $per) { $stats['skipped'] += count($mSlots); $n++; continue; }
            $n++;
            foreach ($mSlots as $sl) {
                $list[] = ['mid' => $mid, 'kid' => (string)$sl['id'],
                           'ksuffix' => (string)$sl['suffix'], 'klabel' => (string)$sl['label']];
            }
        }
        if ($list) $byProv[$pid] = $list;
    }
    // ۲) چرخش: دور i = ردیفِ i-امِ هر ارائه‌دهنده
    $queue = []; $round = 0; $max = 0;
    foreach ($byProv as $l) $max = max($max, count($l));
    for ($i = 0; $i < $max; $i++) {
        foreach ($byProv as $pid => $l) {
            if (!isset($l[$i])) continue;
            $it = $l[$i];
            $queue[] = ['pid' => $pid, 'mid' => $it['mid'], 'round' => $i,
                        /* v10.17: شناسهٔ کلیدِ پین‌شده + پسوندِ نمایشی. خودِ
                           کلید هرگز در صف/وضعیت ذخیره نمی‌شود. */
                        'kid' => $it['kid'], 'ksuffix' => $it['ksuffix'], 'klabel' => $it['klabel']];
        }
        $round++;
    }
    $stats['rounds'] = $round;
    $stats['providers'] = count($byProv);
    return $queue;
}

/**
 * چند فراخوانیِ مدل را هم‌زمان اجرا می‌کند (curl_multi).
 * $jobs: هر عضو ['p'=>provider, 'mid'=>string, 'payload'=>array]
 * خروجی: همان کلیدها با 'r' => نتیجهٔ استانداردِ aiHttp
 *
 * نکته: فقط مسیرِ OpenAI-compatible موازی می‌شود. Cloudflare native چند
 * درخواستِ زنجیره‌ای دارد (نام‌های مختلفِ org و دو نوع بدنه) و منطقش
 * ترتیبی است؛ آن‌ها به مسیرِ تکی برمی‌گردند تا رفتار عوض نشود.
 */
function aiParallelCalls(array $jobs, array $net, int $concurrency = 4): array {
    $out = [];
    $concurrency = max(1, min(16, $concurrency));
    $pending = [];
    foreach ($jobs as $k => $job) {
        $p = $job['p']; $mid = (string)$job['mid'];
        $payload = (array)$job['payload'];
        if (isset($payload['max_tokens'])) {
            $isR = aiIsReasoningModel(aiFindModelRow($p, $mid), $mid);
            $payload['max_tokens'] = aiReasoningBudget((int)$payload['max_tokens'], $isR);
        }
        $ep = aiProviderEndpoint($p, $mid);
        if ($ep['kind'] !== 'openai') {   // Cloudflare و مسیرهای خاص → ترتیبی
            $out[$k] = $job + ['r' => aiProviderCall($p, $mid, (array)$job['payload'], $net), 'seq' => true];
            continue;
        }
        /* v10.01: به‌جای apiKey ثابت، «اولین کلیدِ سالمِ» این ارائه‌دهنده. */
        $pick   = aiPickApiKey($p, (string)($p['id'] ?? ''));
        if (!empty($pick['acct'])) { $p = aiApplyKeyAccount($p, $pick); $ep = aiProviderEndpoint($p, $mid); }
        $apiKey = trim((string)($pick['key'] ?? ''));
        $headers = aiBuildProviderHeaders($p, $ep, $apiKey);
        $body = aiBuildOpenAiPayload($payload, (string)($ep['model'] ?? $mid), (string)($ep['dialect'] ?? ''), $p);
        $pending[$k] = ['job' => $job, 'url' => $ep['url'], 'headers' => $headers, 'body' => $body,
                        'apiKey' => $apiKey, 'keyId' => (string)($pick['id'] ?? '')];
    }
    $keys = array_keys($pending);
    $nk = count($keys);
    $idx = 0;
    while ($idx < $nk) {
        if (aiTestStopRequested()) break;
        $mh = curl_multi_init();
        $batch = [];
        /* یک دسته به اندازهٔ سقفِ هم‌زمانی بردار. کلیدِ $batch یک شمارندهٔ
           سادهٔ عددی است، نه خودِ هندل: در PHP 8 هندلِ curl یک شیء
           (CurlHandle) است و قابلِ تبدیل به int/کلیدِ آرایه نیست. */
        while (count($batch) < $concurrency && $idx < $nk) {
            $k = $keys[$idx++];
            $pd = $pending[$k];
            $h = aiHttpPrepare($pd['url'], $pd['headers'], $pd['body'], $net, $net['mode'] ?? 'direct');
            if (isset($h['err'])) { $out[$k] = $pd['job'] + ['r' => $h['err']]; continue; }
            $batch[] = ['k' => $k, 'h' => $h, 'pd' => $pd];
            curl_multi_add_handle($mh, $h['ch']);
        }
        if (!$batch) { curl_multi_close($mh); continue; }
        // اجرای هم‌زمانِ دسته
        $running = null;
        do {
            $st = curl_multi_exec($mh, $running);
            if ($running) curl_multi_select($mh, 0.5);
            if (aiTestStopRequested()) break;
        } while ($running > 0 && $st === CURLM_OK);
        foreach ($batch as $b) {
            $ch = $b['h']['ch'];
            $raw  = (string)curl_multi_getcontent($ch);
            $err  = (string)curl_error($ch);
            $code = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
            $eurl = (string)curl_getinfo($ch, CURLINFO_EFFECTIVE_URL);
            curl_multi_remove_handle($mh, $ch);
            curl_close($ch);
            $r = aiHttpFinish($b['h'], $raw, $err, $code, $eurl);
            /* v10.219: اگر مسیر موازی با ۴۰۰/۴۲۲ ناشی از شکل payload خورد،
               مسیر ترتیبیِ کامل را اجرا کن؛ آن مسیر بدنه‌های جایگزین
               max_completion_tokens/بدون temperature را هم امتحان می‌کند. */
            if (empty($r['ok']) && !aiTestStopRequested()
                && aiPayloadRepairVariants((array)$b['pd']['body'], $r, (string)$b['pd']['job']['mid'])) {
                $r2 = aiProviderCall($b['pd']['job']['p'], (string)$b['pd']['job']['mid'],
                                     (array)$b['pd']['job']['payload'], $net);
                $r2['retried_payload_seq'] = true;
                $r = $r2;
            }
            /* v10.444: اگر مسیر موازی به واسطهٔ خراب، حذف هدر در Worker (۴۰۱)،
               بلاک جغرافیایی Direct (۴۰۳) یا خطای شبکه خورد، مسیر ترتیبیِ کامل را اجرا کن. */
            $rMode = (string)($r['mode'] ?? '');
            $parAuthStripped = ((string)($b['pd']['apiKey'] ?? '') !== '' && in_array($rMode, ['worker', 'proxy'], true)
                && ((int)$r['code'] === 401 || ((int)$r['code'] === 400 && aiIsMissingAuthHeaderError($r))));
            $parGeoBlocked = (in_array($rMode, ['direct', 'doh', 'dns'], true) && aiIsGeoOrEdgeBlock($r, $rMode));
            if (empty($r['ok']) && !aiTestStopRequested()
                && (aiProxyLevelFailure($r, $rMode) || (int)$r['code'] === 0 || $parAuthStripped || $parGeoBlocked)) {
                $r2 = aiProviderCall($b['pd']['job']['p'], (string)$b['pd']['job']['mid'],
                                     (array)$b['pd']['job']['payload'], $net);
                $r2['retried_seq'] = true;
                $r = $r2;
            } elseif (!empty($r['ok']) && !aiTestStopRequested() && is_array($r['body'] ?? null)) {
                $ch0 = $r['body']['choices'][0] ?? null;
                $cTxt = is_array($ch0['message'] ?? null) && is_string($ch0['message']['content'] ?? null) ? trim($ch0['message']['content']) : '';
                $rTxt = is_array($ch0['message'] ?? null) ? trim((string)($ch0['message']['reasoning_content'] ?? ($ch0['message']['reasoning'] ?? ''))) : '';
                if (($ch0['finish_reason'] ?? '') === 'length' && $cTxt === '' && $rTxt !== '') {
                    $plMore = (array)$b['pd']['job']['payload'];
                    $plMore['max_tokens'] = max(2048, ((int)($plMore['max_tokens'] ?? 300)) * 4);
                    $r2 = aiProviderCall($b['pd']['job']['p'], (string)$b['pd']['job']['mid'], $plMore, $net);
                    if (!empty($r2['ok'])) { $r2['retried_seq'] = true; $r = $r2; }
                }
            }
            /* v10.01: نتیجهٔ کلیدی که در مسیرِ موازی استفاده شد را ثبت کن؛ اگر
               خطا از جنسِ کلید بود، کلید را بسوزان و همان مدل را یک بار از
               مسیرِ ترتیبی رد کن — آنجا خودکار سراغِ کلیدِ بعدی می‌رود. */
            $bKid = (string)($b['pd']['keyId'] ?? '');
            $bPid = (string)($b['pd']['job']['p']['id'] ?? '');
            if ($bKid !== '' && $bPid !== '' && empty($r['retried_seq'])) {
                $r['keyId'] = $bKid;
                if (!empty($r['ok'])) aiKeyMarkOk($bPid, $bKid);
                else {
                    $kf = aiKeyFailureKind($r);
                    if ($kf['kind'] !== '') {
                        aiKeyMarkFail($bPid, $bKid, $kf['kind'], $kf['label'], $kf['msg']);
                        if (!aiTestStopRequested()
                            && aiHealthyKeyCount($b['pd']['job']['p'], $bPid) > 0) {
                            $r2 = aiProviderCall($b['pd']['job']['p'], (string)$b['pd']['job']['mid'],
                                                 (array)$b['pd']['job']['payload'], $net);
                            $r2['retried_seq'] = true;
                            $r2['keyRotated']  = max(1, (int)($r2['keyRotated'] ?? 0));
                            $r = $r2;
                        }
                    }
                }
            }
            $out[$b['k']] = $b['pd']['job'] + ['r' => $r];
        }
        curl_multi_close($mh);
    }
    return $out;
}

/* =====================================================================
 *  v10.12 (۲۵): «اجماعِ مرحله‌ای» — وقتی چند مدل کاندید انتخاب شده،
 *  چطور سریع‌تر به بهترین دسته برسیم.
 *
 *  چهار سازوکار روی هم:
 *
 *  ۱) موازی‌سازی: همهٔ مدل‌های یک مرحله با curl_multi هم‌زمان پرسیده
 *     می‌شوند، نه یکی‌یکی. با ۵ مدل، زمان از «مجموعِ تأخیرها» به
 *     «کندترین تأخیر» می‌رسد.
 *
 *  ۲) توقفِ زودهنگام: اول فقط «حدِ نصاب» مدلِ برترِ جدول (پیش‌فرض ۲) را
 *     می‌پرسیم. اگر هم‌نظر بودند همان‌جا تمام است و بقیهٔ مدل‌ها اصلاً
 *     فراخوانی نمی‌شوند — هم سریع‌تر، هم مصرفِ سهمیهٔ کمتر. فقط وقتی
 *     اختلاف باشد مرحلهٔ دوم اجرا می‌شود.
 *
 *  ۳) رأیِ وزنی: در مرحلهٔ دوم رأی‌ها با سابقهٔ آماری هر مدل
 *     (aiScoreOf، همان جدولِ برد/باخت) وزن می‌گیرند؛ پس مدلی که در
 *     گذشته بیشتر درست گفته، در تساوی برنده می‌شود.
 *
 *  ۴) کشِ هم‌کلمه: نتیجهٔ هر عنوان با کلیدِ «چند کلمهٔ اول» کش می‌شود.
 *     در غرفه‌هایی که ده‌ها «شال نخی ...» دارند، فقط اولی از مدل‌ها
 *     می‌پرسد و بقیه رایگان و آنی جواب می‌گیرند.
 *
 *  خروجی: ['ok','category_id','category_name','agreement','votes','asked',
 *           'stages','from_cache','per_model','error']
 * ===================================================================== */
function aiCatConsensus(array $cands, array $providers, string $title, array $cats,
                        array $leafCats, array $exclude, ?array $net = null,
                        array $opts = []): array {
    $net    = $net ?? aiNetCfg();
    $quorum = max(1, min(8, (int)($opts['quorum'] ?? 2)));
    $conc   = max(1, min(16, (int)($opts['concurrency'] ?? 4)));
    $useCache = ($opts['cache'] ?? true) !== false;
    $triedInfo = (array)($opts['tried_info'] ?? []);
    $empty = ['ok' => false, 'category_id' => 0, 'category_name' => '', 'agreement' => 0,
              'votes' => [], 'asked' => 0, 'stages' => 0, 'from_cache' => false,
              'per_model' => [], 'error' => ''];
    if ($title === '' || !$cands) return array_merge($empty, ['error' => 'کاندید یا عنوان خالی']);

    /* ۴) کشِ هم‌کلمه — کلیدِ کش شاملِ فهرستِ ممنوعه است، چون با تغییرِ
       آن فضای انتخاب عوض می‌شود و جوابِ قبلی دیگر معتبر نیست. */
    /* v10.36 (۴۹ه): بافتِ پروفایل هم باید در کلیدِ کش باشد. دو محصولِ
       هم‌کلمه در دو پروفایلِ متفاوت جوابِ متفاوت می‌گیرند (همان مثالِ
       «ست ۳ تکه»)؛ بدونِ این، جوابِ پروفایلِ اول به دومی هم داده می‌شد و
       کلِ فایدهٔ بافت از بین می‌رفت. */
    $profileHint = (string)($opts['profile_hint'] ?? '');
    static $cache = [];
    $ck = catFirstWords($title, catLearnWordCount()) . '|' . implode(',', $exclude)
        . '|' . md5($profileHint);
    if ($useCache && $ck !== '|' && isset($cache[$ck])) {
        /* توجه: عملگرِ + کلیدِ موجود را بازنویسی نمی‌کند، پس
           from_cache باید صریح ست شود نه با آرایهٔ پیش‌فرض. */
        $hit = $cache[$ck];
        $hit['from_cache'] = true;
        return $hit;
    }

    /* v10.40 (۵۴ب): عنوان هم داده می‌شود تا مرتبط‌ترین دسته‌ها اولِ فهرست بیایند */
    $catList = aiCatListBuild($leafCats, $exclude, 24000, $title);
    if (trim($catList) === '') return array_merge($empty, ['error' => 'همهٔ دسته‌ها قبلاً امتحان شده‌اند']);
    $payload = aiCatPayload($title, $catList, $triedInfo, $profileHint);   // v10.36 (۴۹ه)

    // v10.476: مرتب‌سازی کاندیدها بر اساس امتیاز ترکیبی پایداری+کیفیت (و سپس رأی تاریخی)
    $v = aiVotesLoad();
    $evalRank = aiEvaluateAndRankModels($providers, $v)['by_key'] ?? [];
    $ranked = $cands;
    usort($ranked, function ($a, $b) use ($v, $evalRank) {
        $ra = $evalRank[$a['key'] ?? ''] ?? null;
        $rb = $evalRank[$b['key'] ?? ''] ?? null;
        $pa = ($ra && !empty($ra['proper_latest'])) ? 1 : 0;
        $pb = ($rb && !empty($rb['proper_latest'])) ? 1 : 0;
        if ($pa !== $pb) return $pb <=> $pa;
        $ca = $ra ? (float)$ra['composite_score'] : 0.0;
        $cb = $rb ? (float)$rb['composite_score'] : 0.0;
        if (abs($ca - $cb) > 0.01) return $cb <=> $ca;
        return aiScoreOf($v['scores'][$b['key']] ?? []) <=> aiScoreOf($v['scores'][$a['key']] ?? []);
    });

    $perModel = []; $votes = []; $asked = 0; $stages = 0;
    $run = function (array $group) use (&$perModel, &$votes, &$asked, $providers, $payload,
                                        $net, $conc, $title, $cats, $exclude) {
        $jobs = [];
        foreach ($group as $c) {
            $pp = $providers[$c['provider']] ?? null;
            if ($pp === null) continue;
            $jobs[$c['key']] = ['p' => $pp, 'mid' => $c['model'], 'payload' => $payload, 'cand' => $c];
        }
        if (!$jobs) return;
        $t0  = microtime(true);
        $res = aiParallelCalls($jobs, $net, $conc);
        $lat = (int)round((microtime(true) - $t0) * 1000);
        foreach ($res as $k => $row) {
            $asked++;
            $c   = $row['cand'];
            $par = aiCatParse((array)$row['r'], $title, $cats, (string)$c['model'], $lat, $exclude);
            $perModel[] = ['key' => $k, 'model' => $c['model'], 'provider' => $c['providerName'] ?? $c['provider'],
                           'ok' => !empty($par['ok']), 'category_id' => (int)$par['category_id'],
                           'category_name' => (string)$par['category_name'],
                           'repeat' => !empty($par['repeat']), 'error' => (string)$par['error'],
                           'latency' => (int)$par['latency']];
            if (!empty($par['ok']) && (int)$par['category_id'] > 0) {
                $cid = (string)$par['category_id'];
                if (!isset($votes[$cid])) $votes[$cid] = ['n' => 0, 'w' => 0.0, 'name' => '', 'keys' => []];
                $votes[$cid]['n']++;
                $votes[$cid]['name'] = (string)$par['category_name'];
                $votes[$cid]['keys'][] = $k;
            }
        }
    };

    // ── مرحلهٔ ۱: فقط بهترین‌ها ─────────────────────────────────────
    $stage1 = array_slice($ranked, 0, $quorum);
    $stages++; $run($stage1);

    $decide = function () use (&$votes, $v, $cands) {
        if (!$votes) return null;
        /* ۳) وزنِ هر دسته = مجموعِ امتیازِ تاریخیِ رأی‌دهنده‌ها (+۱ پایه
           تا مدلِ بی‌سابقه هم صفر نشود). تعدادِ رأی مقدم است، وزن
           فقط تساوی را می‌شکند. */
        foreach ($votes as $cid => &$row) {
            $w = 0.0;
            foreach ($row['keys'] as $k) $w += 1.0 + aiScoreOf($v['scores'][$k] ?? []);
            $row['w'] = round($w, 3);
        }
        unset($row);
        $bestId = 0; $bestN = -1; $bestW = -1.0;
        foreach ($votes as $cid => $row) {
            if ($row['n'] > $bestN || ($row['n'] === $bestN && $row['w'] > $bestW)) {
                $bestN = $row['n']; $bestW = $row['w']; $bestId = (int)$cid;
            }
        }
        return $bestId > 0 ? ['id' => $bestId, 'n' => $bestN] : null;
    };

    // ۲) توقفِ زودهنگام: اگر همهٔ پرسیده‌شده‌های مرحلهٔ ۱ یک چیز گفتند، تمام
    $d = $decide();
    $unanimous = ($d !== null && count($votes) === 1 && $d['n'] >= min($quorum, count($stage1)));
    if (!$unanimous && count($ranked) > count($stage1)) {
        $stages++; $run(array_slice($ranked, count($stage1)));
        $d = $decide();
    }

    if ($d === null) {
        $err = 'هیچ مدلی دستهٔ تازه‌ای نداد';
        foreach ($perModel as $pm) { if (!empty($pm['repeat'])) { $err = 'همهٔ پیشنهادها تکراری بودند'; break; } }
        return array_merge($empty, ['asked' => $asked, 'stages' => $stages,
                                    'per_model' => $perModel, 'error' => $err, 'votes' => $votes]);
    }
    $winner = (string)$d['id'];
    $out = ['ok' => true, 'category_id' => (int)$d['id'],
            'category_name' => (string)($votes[$winner]['name'] ?? bslCatNameById((int)$d['id'])),
            'agreement' => (int)$d['n'], 'votes' => $votes, 'asked' => $asked,
            'stages' => $stages, 'from_cache' => false, 'per_model' => $perModel,
            'winner_keys' => (array)($votes[$winner]['keys'] ?? []), 'error' => ''];
    if ($useCache && $ck !== '|') $cache[$ck] = $out;
    return $out;
}

/* v9.99: نتیجهٔ یک مدل را ارزیابی و برچسب‌گذاری می‌کند.
   یک نقطهٔ مشترک تا مسیرِ موازی و ترتیبی دقیقاً یکسان قضاوت کنند. */
function aiTestJudge(array $r, string $mid, string $pid = ''): array {
    $code = (int)($r['code'] ?? 0);
    $body = $r['body'] ?? [];
    $ok = $code === 200;
    $response = $ok ? aiExtractAnswer($body) : '';
    $err = '';
    if (!$ok) {
        $err = aiHttpErrorMessage($r);
        if ($err === '') $err = 'HTTP ' . $code;
        if (is_array($err)) $err = json_encode($err, JSON_UNESCAPED_UNICODE);
    }
    $diag = aiTestNetworkFailure($r);
    $kind = ''; $note = '';

    /* ۱) خطاهای اعتبار/اشتراک — طبقِ خواستهٔ صریحِ کاربر «رفع» نمی‌شوند،
          فقط درست برچسب می‌خورند تا با خطای فنی قاطی نشوند. */
    $bill = aiBillingFailure($r);
    if (!$ok && $bill['is']) {
        $kind = 'billing:' . $bill['kind'];
        $note = $bill['label'];
        $diag['cat'] = 'billing';
        $diag['label'] = $bill['label'];
        /* v10.01: اگر چند کلید داشتیم و همه امتحان شدند، این را صریح بگو —
           تفاوتِ «یک کلید تمام شد» با «هیچ کلیدِ سالمی نمانده» برای کاربر
           مهم است: در حالت دوم باید کلیدِ تازه اضافه کند. */
        if (!empty($r['keysExhausted'])) {
            $kt = aiFaNum((int)($r['keysTried'] ?? 0));
            $note .= ' — هر ' . $kt . ' کلیدِ این ارائه‌دهنده امتحان شد؛ یک کلید تازه اضافه کنید';
            $diag['label'] = $note;
            $diag['keysExhausted'] = true;
        } elseif (!empty($r['keyRotated'])) {
            $note .= ' (پس از چرخش روی ' . aiFaNum((int)$r['keyRotated']) . ' کلید)';
        }
    /* ۲) خطا از واسطه (Worker/پروکسی/CDN) است نه از سرویس */
    } elseif (!$ok && (!empty($r['proxy_blocked']) || aiProxyLevelFailure($r, (string)($r['mode'] ?? '')))) {
        $kind = 'proxy';
        $note = 'خطا از مسیرِ عبور (Worker/پروکسی/CDN) است نه از خودِ مدل — روش اتصال را عوض کنید';
        $diag['cat'] = 'proxy';
        $diag['label'] = 'مسیرِ عبور مسدود است (' . $code . ') — نه خطای مدل';
    /* ۲ب) v10.444: حذف هدر احراز هویت در Worker قدیمی یا بلاک جغرافیایی */
    } elseif (!$ok && !empty($r['auth_stripped_suspect'])) {
        $kind = 'proxy';
        $note = 'واسطهٔ Worker هدر Authorization را حذف کرده است — کد جدید Worker را از تب «🌐 اتصال» کپی و Deploy کنید';
        $diag['cat'] = 'proxy';
        $diag['label'] = 'حذف هدر در Worker (' . $code . ')';
    } elseif (!$ok && aiIsGeoOrEdgeBlock($r, (string)($r['mode'] ?? ''))) {
        $kind = 'proxy';
        $note = 'دسترسی مستقیم از IP هاست توسط سرویس مسدود است (' . $code . ') — Worker سالم را فعال کنید';
        $diag['cat'] = 'forbidden';
        $diag['label'] = 'مسدودیت جغرافیایی/IP (' . $code . ')';
    /* ۳) مدلی که در این سرویس وجود ندارد، بازنشسته شده (404/410) یا چت نیست */
    } elseif (!$ok && in_array($code, [400, 404, 410], true)) {
        $low = strtolower((string)$err . ' ' . (string)($r['raw'] ?? ''));
        if ($code === 410 || strpos($low, 'model_not_supported') !== false || strpos($low, 'invalid model') !== false
            || strpos($low, 'no route for that uri') !== false || strpos($low, 'not a chat model') !== false
            || strpos($low, 'no such model') !== false || strpos($low, 'model_not_found') !== false
            || strpos($low, 'model not found') !== false || strpos($low, 'does not exist') !== false
            || strpos($low, 'decommissioned') !== false || strpos($low, 'deprecated') !== false
            || strpos($low, 'no longer supported') !== false) {
            $kind = 'badmodel';
            $note = 'این مدل/اندپوینت منسوخ یا ناموجود است (' . $code . ') — با دکمهٔ «تعمیر خودکار» اصلاح کنید';
            $diag['cat'] = 'badmodel';
            $diag['label'] = 'مدل ناموجود/منسوخ (' . $code . ')';
        }
    }

    /* ۴) مثبتِ کاذب: HTTP 200 ولی پاسخ در عمل بی‌معنی/متعلق به مدلِ دیگر */
    $suspect = '';
    if ($ok) {
        $suspect = aiSuspectAnswer((string)$response, $mid);
        if ($suspect !== '') {
            $ok = false;
            $kind = 'bogus';
            $note = 'پاسخ معتبر نیست: ' . $suspect;
            $err = $note;
            $diag['cat'] = 'bogus';
            $diag['label'] = 'پاسخِ نامعتبر با کد ۲۰۰ — عملاً کار نمی‌کند';
        }
    }
    if ($ok) { $diag['cat'] = 'ok'; $diag['label'] = 'در دسترس'; }
    elseif (($diag['label'] ?? '') === '') $diag['label'] = 'HTTP ' . $code;
    $diag['ok'] = $ok;
    return ['ok' => $ok, 'code' => $code, 'response' => (string)$response, 'error' => (string)$err,
            'diag' => $diag, 'kind' => $kind, 'note' => $note, 'suspect' => $suspect,
            'billing' => $bill['is'] ? $bill['kind'] : ''];
}

/* =====================================================================
 *  v10.18 (۳۱ب): دورِ جبرانیِ پایانِ صف — تلاشِ مجدد با تایم‌اوتِ فزاینده
 *
 *  خواستهٔ کاربر: «بعد از اتمامِ صفِ تستِ مدل‌ها، خطاهای غیرمرتبط با اعتبار
 *  تا سه بار با تایم‌اوتِ فزاینده دوباره تلاش شوند.»
 *
 *  چرا لازم است: بخشِ بزرگی از قرمزهای یک اجرا موقتی‌اند — تایم‌اوت،
 *  قطعِ اتصال، ۵۰۰/۵۰۲/۵۰۳ سرویس و خطای DNS/پروکسی. از v10.218،
 *  ۴۲۹ ریت‌لیمیت مثل credit رفع‌پذیر کدی حساب نمی‌شود و فقط گزارش می‌شود.
 *  اینجا این‌ها همان‌قدر قرمز می‌ماندند که یک مدلِ واقعاً خراب، و کاربر
 *  مجبور بود کلِ تست را از نو بزند.
 *
 *  در مقابل، خطاهایی که تکرارشان بی‌فایده است رد می‌شوند:
 *    • اعتبار/اشتراک/سهمیهٔ تمام‌شده (billing) — خواستهٔ صریحِ کاربر
 *    • محدودیت نرخ/ریت‌لیمیت (429) — با کد رفع نمی‌شود؛ فقط گزارش می‌شود
 *    • مدلِ ناموجود/غیرچت (badmodel) و ۴۰۱/۴۰۳/۴۰۴ — با تکرار درست نمی‌شود
 *    • پاسخِ بی‌معنی (bogus) — مدل جواب داد، فقط جوابش بی‌ربط بود
 *
 *  خروجی: رشتهٔ خالی = تلاشِ دوباره نکن، وگرنه دلیلِ کوتاهِ فارسی.
 * ===================================================================== */
function aiTestRetryable(array $j): string {
    if (!empty($j['ok'])) return '';
    $kind = (string)($j['kind'] ?? '');
    $code = (int)($j['code'] ?? 0);
    /* اعتبار/اشتراک — طبقِ خواستهٔ کاربر هرگز دوباره تلاش نمی‌شود */
    if ((string)($j['billing'] ?? '') !== '' || strpos($kind, 'billing') === 0) return '';
    if ($kind === 'badmodel' || $kind === 'bogus') return '';
    if ($code === 429) return ''; // v10.218: rate-limit قابلِ رفعِ کدی نیست؛ در feedback فقط گزارش می‌شود
    if (in_array($code, [400, 401, 403, 404, 405, 422], true)) return '';
    $cat = (string)($j['diag']['cat'] ?? '');
    if ($code === 0) return 'خطای شبکه/اتصال';                   // تایم‌اوت، DNS، refused
    if ($code >= 500) return 'خطای موقتِ سرویس (' . $code . ')';
    if ($kind === 'proxy' || $cat === 'proxy') return 'خطای مسیرِ عبور';
    if (in_array($cat, ['dns','timeout','refused','connect','ssl','network'], true)) return 'خطای شبکه';
    return '';
}

/* v10.18 (۳۱ب): تایم‌اوتِ دورِ جبرانیِ n-ام.
   هر دور سخاوتمندانه‌تر از قبلی صبر می‌کند (۱٫۷۵×)، چون بخشِ زیادی از این
   شکست‌ها صرفاً «سرویس کُند بود» است. سقفِ ۱۲۰ ثانیه همان سقفِ aiNetCfg. */
function aiTestRetryTimeout(int $base, int $pass): int {
    $t = (int)round(max(5, $base) * pow(1.75, max(1, $pass)));
    return max(5, min(120, $t));
}

/* هستهٔ اجرای تست — یک تابع تا هم از مسیر پس‌زمینه و هم از مسیر هم‌زمان استفاده کند */
function aiRunTestBackground(int $per, bool $onlyUntested, string $testMsg = 'سلام', string $testCat = 'ادو پرفیوم', int $delayMs = 120, int $concurrency = 4, bool $skipNonChat = true, bool $doCat = true): array {
    @set_time_limit(0); @ignore_user_abort(true);
    @unlink(AI_TEST_STOP_FILE);
    $providers = aiProvidersLoad();
    $catData = $doCat ? aiTestCategoryData() : null;
    $delayMs = max(0, min(60000, (int)$delayMs));   // v9.56: تاخیر بین هر دور (جلوگیری از ریت‌لیمیت)
    $concurrency = max(1, min(16, (int)$concurrency));
    $net = aiNetCfg();
    $st = ['running'=>true,'done'=>false,'stopped'=>false,'started_at'=>time(),'updated_at'=>time(),
           'per_provider'=>$per,'only_untested'=>$onlyUntested,'delay_ms'=>$delayMs,
           'concurrency'=>$concurrency,'skip_nonchat'=>$skipNonChat,
           'total'=>0,'tested'=>0,'available'=>0,'failed'=>0,'skipped'=>0,'nonchat'=>0,
           'billing'=>0,'proxy'=>0,'bogus'=>0,'badmodel'=>0,'round'=>0,'rounds'=>0,
           'current'=>['provider'=>'','model'=>''],'items'=>[],'diag'=>[],'summary'=>''];

    $runEpoch = max(0, (int)($GLOBALS['_aiTestRunEpoch'] ?? 0));
    if ($runEpoch <= 0) $runEpoch = time();
    $isDailyAuto = !empty($GLOBALS['_aiDailyAutoRun']);

    /* v9.99: صفِ چرخشی — مدلِ اولِ همهٔ ارائه‌دهنده‌ها، بعد مدلِ دومِ همه، …
       تا درخواست‌هایِ هم‌زمان روی ارائه‌دهنده‌های متفاوت پخش شوند و ریت‌لیمیتِ
       هیچ ارائه‌دهنده‌ای پر نشود. */
    $qstats = [];
    $queue = aiTestBuildQueue($providers, $per, $onlyUntested, $skipNonChat, $qstats);
    /* If every eligible model is already marked tested, "only untested" used
       to create an empty queue and finish before visibly starting. Start a real
       refresh pass instead; an actually empty catalog still remains actionable. */
    if(!$queue&&$onlyUntested&&empty($GLOBALS['_aiTestResumeEpoch'])){
        $allStats=[];$allQueue=aiTestBuildQueue($providers,$per,false,$skipNonChat,$allStats);
        if($allQueue){$queue=$allQueue;$qstats=$allStats;$st['only_untested']=false;
            $st['only_untested_requested']=true;$st['fallback_all_tested']=true;}
    }
    /* v9.99: پارامترهای اجرا را نگه دار تا مکانیزمِ «رفعِ گیر» بتواند دقیقاً
       همین تست را از همان‌جا که مانده ادامه دهد (بدون تستِ دوبارهٔ مدل‌هایی
       که جواب داده‌اند). */
    $st['args'] = ['per'=>$per, 'msg'=>$testMsg, 'cat'=>$testCat, 'delay'=>$delayMs,
                   'conc'=>$concurrency, 'nonchat'=>$skipNonChat ? 1 : 0,
                   'run_epoch'=>$runEpoch, 'daily_auto'=>$isDailyAuto ? 1 : 0];
    $st['run_epoch'] = $runEpoch;
    $st['daily_auto'] = $isDailyAuto;
    $st['pid'] = function_exists('getmypid') ? (int)getmypid() : 0;
    $st['skipped'] = (int)($qstats['skipped'] ?? 0);
    $st['nonchat'] = (int)($qstats['nonchat'] ?? 0);
    $st['rounds']  = (int)($qstats['rounds'] ?? 0);
    $st['total']   = count($queue);
    /* v10.17 (۳۰): نگاشتِ «ارائه‌دهنده|کلید ⇒ پسوندِ نمایشی» تا در حلقهٔ
       نتیجه‌ها بدون دسترسی دوباره به کلیدها، برچسبِ ردیف ساخته شود. */
    $sfxByKey = [];
    foreach ($queue as $q0) {
        $k0 = (string)($q0['kid'] ?? '');
        if ($k0 === '') continue;
        $sfxByKey[$q0['pid'] . '|' . $k0] = ['suffix'=>(string)($q0['ksuffix'] ?? ''), 'label'=>(string)($q0['klabel'] ?? '')];
    }
    /* key_rows = تعدادِ کلِ ردیف‌های صف (مدل × کلید)، key_slots = تعدادِ
       کلیدهای فعالِ همهٔ ارائه‌دهنده‌ها، multi_key = چند ارائه‌دهنده بیش از
       یک کلید دارند. */
    $st['key_rows']  = count($queue);
    $st['key_slots'] = (int)($qstats['keys'] ?? 0);
    $st['multi_key'] = (int)($qstats['multikey'] ?? 0);
    aiTestStateSave($st);

    /* مدل‌های غیرچت را در همان provider علامت بزن تا کاربر ببیند چرا تست نشدند */
    if ($skipNonChat) {
        foreach ($providers as $pid2 => $p2) {
            foreach ((array)($p2['models'] ?? []) as $i2 => $m2) {
                $mid2 = (string)($m2['id'] ?? '');
                if ($mid2 === '') continue;
                $why = aiNonChatModel($mid2, is_array($m2) ? $m2 : []);
                if ($why !== '') {
                    $providers[$pid2]['models'][$i2]['nonChat'] = true;
                    $providers[$pid2]['models'][$i2]['nonChatReason'] = $why;
                } elseif (isset($providers[$pid2]['models'][$i2]['nonChat'])) {
                    unset($providers[$pid2]['models'][$i2]['nonChat'], $providers[$pid2]['models'][$i2]['nonChatReason']);
                }
            }
        }
    }

    /* صف را دور-به-دور (هر دور = یک مدل از هر ارائه‌دهنده) اجرا کن. داخل هر
       دور، درخواست‌ها با curl_multi هم‌زمان می‌روند. */
    $rounds = [];
    foreach ($queue as $q) { $rounds[(int)$q['round']][] = $q; }
    ksort($rounds);
    $payloadBase = ['messages'=>[['role'=>'user','content'=>$testMsg]], 'temperature'=>0.3, 'max_tokens'=>300];
    /* v10.00 (۱۴ب): بدنهٔ ثابتِ درخواستِ دسته‌بندی یک بار ساخته می‌شود؛ برای
       همهٔ مدل‌ها یکسان است (فقط نامِ مدل داخلِ aiParallelCalls عوض می‌شود). */
    $catPayload = ($doCat && $catData && $testCat !== '') ? aiCatPayload($testCat, (string)$catData['catList']) : null;

    /* v10.476: اسنپ‌شاتِ آمار پیش از این اجرا تا تلاش‌های چندکلیدی و دورهای جبرانی
       هرگز شمارندهٔ runs یک مدل را در یک چرخه دوبار افزایش ندهند. */
    $prevStatsByModel = [];
    foreach ($providers as $pidS => $pS) {
        if (!is_array($pS)) continue;
        foreach ((array)($pS['models'] ?? []) as $mS) {
            if (!is_array($mS)) continue;
            $midS = (string)($mS['id'] ?? '');
            if ($midS === '') continue;
            $prevStatsByModel[$pidS . '::' . $midS] = aiModelNormalizeTestStats($mS);
        }
    }
    $runModelAgg = [];

    $rowJudge = [];
        /* v10.18 (۳۱ب): ثبتِ نتیجهٔ یک ردیف در یک نقطه جمع شد.
           تا اینجا این منطق فقط داخلِ حلقهٔ دورها بود؛ چون «دورِ جبرانیِ»
           پایانِ صف باید دقیقاً همان کار را بکند (وگرنه خطرِ شمارشِ دوگانه
           و واگراییِ رفتار داریم)، به یک کلوژرِ مشترک تبدیل شد.
           خروجی: false یعنی توقف خواسته شده. */
        $recordResult = function (array $res, array $catByKey) use (&$st, &$providers, &$rowJudge,
                                  &$runModelAgg, $prevStatsByModel, $runEpoch,
                                  $sfxByKey, $net, $testMsg, $testCat): bool {
            $pid = (string)$res['pid']; $mid = (string)$res['mid'];
            /* v10.17 (۳۰): این نتیجه مالِ کدام کلید است؟ */
            $kid  = (string)($res['kid'] ?? '');
            $ksf  = $sfxByKey[$pid . '|' . $kid] ?? ['suffix'=>'', 'label'=>''];
            $ksfx = (string)$ksf['suffix'];
            $midLabel = $mid . $ksfx;      // نامِ نمایشیِ ردیف (با پسوندِ کلید)
            $p = $providers[$pid] ?? null;
            if (!$p) return true;
            $r = (array)$res['r'];
            $latency = (int)round((microtime(true) - (float)$res['t0']) * 1000);
            $j = aiTestJudge($r, $mid, $pid);
            $ok = $j['ok']; $code = $j['code']; $response = $j['response']; $err = $j['error'];
            $diag = $j['diag']; $diag['latencyMs'] = $latency;

            if (!isset($st['diag'][$pid])) $st['diag'][$pid] = ['reachable'=>true,'categories'=>[],'samples'=>0];
            $st['diag'][$pid]['samples']++;
            if (!$ok) {
                $st['diag'][$pid]['categories'][$diag['cat']] = ($st['diag'][$pid]['categories'][$diag['cat']] ?? 0) + 1;
                if (in_array($diag['cat'], ['dns','timeout','refused','connect','ssl','network'], true)) {
                    $st['diag'][$pid]['reachable'] = false;
                    $st['diag'][$pid]['first_error'] = $diag['error'];
                }
                if ($j['kind'] === 'proxy') {
                    $st['diag'][$pid]['net_issue'] = true;
                    $st['diag'][$pid]['mode'] = (string)($net['mode'] ?? 'direct');
                    $st['diag'][$pid]['net_hint'] = 'پاسخِ خطا از Worker/پروکسی آمده نه از سرویس — روش اتصال را «مستقیم» کنید یا Workerِ سالم بگذارید';
                }
            }
            $st['diag'][$pid]['last_label'] = $diag['label'];
            if ($j['billing'] !== '') $st['billing']++;
            if ($j['kind'] === 'proxy') $st['proxy']++;
            if ($j['kind'] === 'bogus') $st['bogus']++;
            if ($j['kind'] === 'badmodel') $st['badmodel']++;

            /* v10.00 (۱۴ب): نتیجهٔ دسته‌بندی همین دور از پیش (قبل از پیام)
               گرفته شده؛ اینجا فقط خوانده می‌شود و درخواستِ تازه‌ای نمی‌رود. */
            $cc = $catByKey[aiTestRowKey($pid, $mid, $kid)] ?? null;
            $catMeta     = $cc ? (array)$cc['meta'] : null;
            $catResponse = $cc ? (string)$cc['summary'] : null;
            $catLatency  = $cc ? (int)$cc['lat'] : 0;
            $catOkRow    = $cc ? (!empty($cc['res']['ok']) && (int)($cc['res']['category_id'] ?? 0) > 0) : null;

            $mKeyAgg = $pid . '::' . $mid;
            $prevAgg = $runModelAgg[$mKeyAgg] ?? ['chat_ok' => false, 'cat_ok' => null, 'lat' => 0, 'cat_lat' => 0, 'code' => 0, 'kind' => ''];
            if ($ok && (string)$j['kind'] === '') {
                $prevAgg['chat_ok'] = true;
                $prevAgg['kind'] = '';
                $prevAgg['code'] = 200;
                $prevAgg['lat'] = $latency;
                if ($catOkRow === true) $prevAgg['cat_ok'] = true;
                elseif ($prevAgg['cat_ok'] === null) $prevAgg['cat_ok'] = $catOkRow;
                if ($catLatency > 0) $prevAgg['cat_lat'] = $catLatency;
            } elseif (!$prevAgg['chat_ok']) {
                $prevAgg['code'] = $code;
                $prevAgg['kind'] = (string)$j['kind'];
                $prevAgg['lat'] = $latency;
                if ($prevAgg['cat_ok'] === null) $prevAgg['cat_ok'] = $catOkRow;
                if ($catLatency > 0) $prevAgg['cat_lat'] = $catLatency;
            }
            $runModelAgg[$mKeyAgg] = $prevAgg;

            if (isset($providers[$pid]['models'])) {
                foreach ($providers[$pid]['models'] as $i => $m) {
                    if (($m['id'] ?? '') === $mid) {
                        /* v10.17 (۳۰): در حالتِ چندکلیدی، نتیجهٔ هر کلید جدا
                           نگه داشته می‌شود و وضعیتِ کلیِ مدل «یا»ی آن‌هاست:
                           اگر با دستِ‌کم یک کلید جواب داد، مدل در دسترس است.
                           بدون این، کلیدِ خرابِ دوم مدلِ سالم را قرمز می‌کرد. */
                        if ($kid !== '') {
                            $kt = (array)($providers[$pid]['models'][$i]['keyTests'] ?? []);
                            $kt[$kid] = ['tested'=>true, 'available'=>$ok, 'label'=>(string)$ksf['label'],
                                         'suffix'=>$ksfx, 'runEpoch'=>$runEpoch, 'latencyMs'=>$latency, 'status'=>$code,
                                         'kind'=>(string)$j['kind'], 'error'=>mb_substr((string)$err,0,200),
                                         'billing'=>(string)$j['billing'], 'testedAt'=>gmdate('c')];
                            $providers[$pid]['models'][$i]['keyTests'] = $kt;
                            $anyOk = $ok;
                            foreach ($kt as $kk2 => $kv2) {
                                if ($kk2 === $kid) continue;
                                if (!empty($kv2['available'])) { $anyOk = true; break; }
                            }
                            $providers[$pid]['models'][$i]['available'] = $anyOk;
                            $providers[$pid]['models'][$i]['rateLimited'] = !$anyOk && in_array($code, [429], true);
                        } else {
                            $anyOk = $ok;
                            $providers[$pid]['models'][$i]['available'] = $ok;
                            $providers[$pid]['models'][$i]['rateLimited'] = in_array($code, [429], true);
                        }
                        $providers[$pid]['models'][$i]['tested'] = true;
                        /* v9.99: علتِ رفع‌نشدنی (اعتبار/اشتراک) جدا ثبت می‌شود
                           v10.17 (۳۰): اگر کلیدِ دیگری همین مدل را باز کرده،
                           مشکلِ اعتبارِ این کلید نباید کلِ مدل را قفل کند. */
                        if ($j['billing'] !== '' && !$anyOk) {
                            $providers[$pid]['models'][$i]['billingIssue'] = $j['billing'];
                        } else {
                            unset($providers[$pid]['models'][$i]['billingIssue']);
                        }
                        $providers[$pid]['models'][$i]['testDetails'] = ['status'=>$code, 'error'=>mb_substr((string)$err,0,300),
                            'response'=>mb_substr((string)$response,0,300), 'catResponse'=>(string)$catResponse,
                            'catOk'=>$prevAgg['cat_ok'], 'runEpoch'=>$runEpoch,
                            'testMsg'=>$testMsg, 'testCat'=>$testCat, 'latencyMs'=>$latency, 'testedAt'=>gmdate('c'),
                            'raw'=>mb_substr((string)($r['raw'] ?? ''), 0, 4000), 'via'=>(string)($r['via'] ?? ''),
                            'catRaw'=>(string)($catMeta['raw'] ?? ''), 'catStatus'=>(int)($catMeta['status'] ?? 0),
                            'catVia'=>(string)($catMeta['via'] ?? ''), 'catAiText'=>(string)($catMeta['aiText'] ?? ''),
                            // v10.00: تأخیر و زمانِ خودِ درخواستِ دسته‌بندی
                            'catLatencyMs'=>$catLatency, 'catTestedAt'=>$cc ? gmdate('c') : '',
                            // v10.00 (۱۴ب): پیام تست به‌خاطر خطای قطعیِ دسته‌بندی زده نشد
                            'msgSkipped'=>!empty($r['msg_skipped']),
                            // v9.99: دستهٔ خطا و توضیحِ فارسیِ آن
                            'kind'=>(string)$j['kind'], 'note'=>(string)$j['note'],
                            // v10.17 (۳۰): این جزئیات مالِ کدام کلید است
                            'keyId'=>$kid, 'keySuffix'=>$ksfx, 'keyLabel'=>(string)$ksf['label'],
                            'payloadRepair'=>(string)($r['payload_repair'] ?? ''),
                            'retriedPayloadSeq'=>!empty($r['retried_payload_seq']),
                            'retriedSeq'=>!empty($r['retried_seq'])];
                        $baseSnap = $prevStatsByModel[$mKeyAgg] ?? [];
                        if ((int)($baseSnap['last_run_epoch'] ?? 0) !== $runEpoch) {
                            $providers[$pid]['models'][$i]['testStats'] = aiModelUpdateTestStats(
                                $baseSnap,
                                !empty($prevAgg['chat_ok']),
                                $prevAgg['cat_ok'],
                                (int)$prevAgg['lat'],
                                (int)$prevAgg['cat_lat'],
                                (int)$prevAgg['code'],
                                (string)$prevAgg['kind'],
                                $runEpoch
                            );
                        }
                        break;
                    }
                }
            }
            $st['tested']++;
            if ($ok) $st['available']++; else $st['failed']++;
            $st['items'][] = ['provider'=>$pid, 'providerName'=>$p['name']??$pid, 'model'=>$midLabel,
                /* v10.17 (۳۰): نامِ خامِ مدل و مشخصاتِ کلید جدا نگه داشته
                   می‌شوند؛ ستونِ «مدل» پسوندِ کلید را نشان می‌دهد ولی کلیکِ
                   ردیف باید سراغِ همان مدلِ واقعی برود. */
                'baseModel'=>$mid, 'keyId'=>$kid, 'keySuffix'=>$ksfx, 'keyLabel'=>(string)$ksf['label'],
                'ok'=>$ok, 'latencyMs'=>$latency, 'error'=>mb_substr((string)$err,0,120),
                'cat'=>$diag['cat'], 'label'=>$diag['label'], 'kind'=>(string)$j['kind'],
                'round'=>$st['round'],
                'msgResponse'=>mb_substr($response,0,150), 'catResponse'=>mb_substr((string)$catResponse,0,150)];
            if (count($st['items']) > 1000) $st['items'] = array_slice($st['items'], -1000);
            /* v10.18 (۳۱ب): قضاوتِ این ردیف را نگه دار تا دورِ جبرانی بداند
               کدام شکست‌ها ارزشِ تلاشِ دوباره دارند. */
            $rowJudge[aiTestRowKey($pid, $mid, $kid)] = ['ok'=>$ok, 'code'=>$code,
                'kind'=>(string)$j['kind'], 'billing'=>(string)$j['billing'],
                'diag'=>['cat'=>(string)($diag['cat'] ?? '')]];
            return true;
        };

    foreach ($rounds as $rIdx => $items) {
        clearstatcache(true, AI_TEST_STOP_FILE);
        if (is_file(AI_TEST_STOP_FILE)) { $st['stopped'] = true; break; }
        $st['round'] = (int)$rIdx + 1;
        $st['current'] = ['provider'=>'دورِ ' . ($rIdx + 1), 'model'=>count($items) . ' مدل هم‌زمان'];
        aiTestStateSave($st);

        $t0r = microtime(true);

        /* =============================================================
         *  v10.00 (۱۴ب): گامِ ۱ — «تستِ دسته‌بندی» *اول* زده می‌شود.
         *
         *  چرا ترتیب عوض شد: هر مدل در این برنامه دو درخواست می‌گیرد
         *  (پیامِ نمونه + دسته‌بندیِ یک عنوانِ نمونه). خیلی از سرویس‌های
         *  رایگان ریت‌لیمیتِ *دقیقه‌ای* دارند؛ وقتی دو درخواست پشت‌سرهم
         *  می‌رود، معمولاً درخواستِ دوم است که ۴۲۹ می‌خورد. تا نسخهٔ ۹٫۹۹
         *  درخواستِ دوم «دسته‌بندی» بود و دقیقاً همان چیزی که برای کاربر
         *  مهم‌تر است (توانایی مدل در انتخابِ دستهٔ باسلام) قربانی می‌شد.
         *  حالا دسته‌بندی اول می‌رود و اگر سهمیه ته کشید، پیام رد می‌شود
         *  که کم‌اهمیت‌تر است.
         *
         *  ضمناً دسته‌بندی هم مثل پیام با curl_multi موازی می‌رود (قبلاً
         *  تک‌تک و ترتیبی بود) ⇒ کلِ تست سریع‌تر تمام می‌شود.
         * ============================================================= */
        $catByKey = [];
        if ($catPayload !== null) {
            $catJobs = [];
            foreach ($items as $q) {
                $p = $providers[$q['pid']] ?? null;
                if (!$p) continue;
                /* v10.17 (۳۰): اگر این ردیف به یک کلیدِ مشخص گره خورده، همان
                   کلید پین می‌شود تا نتیجه واقعاً «این مدل با این کلید» باشد. */
                $kid = (string)($q['kid'] ?? '');
                $catJobs[] = ['p'=>aiPinProviderKey($p, $kid), 'mid'=>$q['mid'], 'pid'=>$q['pid'],
                              'kid'=>$kid, 'payload'=>$catPayload, 't0'=>microtime(true)];
            }
            if ($catJobs) {
                $st['current'] = ['provider'=>'دورِ ' . ($rIdx + 1) . ' · تستِ دسته‌بندی', 'model'=>count($catJobs) . ' مدل هم‌زمان'];
                aiTestStateSave($st);
                foreach (aiParallelCalls($catJobs, $net, $concurrency) as $cr) {
                    $crr    = (array)$cr['r'];
                    $clat   = (int)round((microtime(true) - (float)$cr['t0']) * 1000);
                    $parsed = aiCatParse($crr, $testCat, (array)$catData['cats'], (string)$cr['mid'], $clat);
                    $catByKey[aiTestRowKey((string)$cr['pid'], (string)$cr['mid'], (string)($cr['kid'] ?? ''))] =
                        ['res'=>$parsed, 'r'=>$crr, 'summary'=>aiCatSummary($parsed), 'meta'=>aiCatMeta($parsed), 'lat'=>$clat];
                }
            }
            if (aiTestStopRequested()) { $st['stopped'] = true; break; }
            /* فاصلهٔ کوتاه بین دو موجِ درخواست به همان ارائه‌دهنده‌ها */
            if ($catByKey && $delayMs > 0) usleep($delayMs * 1000);
        }

        /* گامِ ۲ — تستِ پیام. اگر دسته‌بندی با خطای «قطعی» برگشته (اعتبار/
           اشتراک، مدلِ ناموجود، کلیدِ نامعتبر) درخواستِ دوم هم دقیقاً همان
           خطا را می‌گیرد ⇒ زده نمی‌شود و همان نتیجه بازاستفاده می‌شود.
           این هم سهمیه را نمی‌سوزاند و هم تست را کوتاه‌تر می‌کند. */
        $jobs = []; $reuse = [];
        $st['current'] = ['provider'=>'دورِ ' . ($rIdx + 1) . ' · تستِ پیام', 'model'=>count($items) . ' مدل هم‌زمان'];
        foreach ($items as $q) {
            $p = $providers[$q['pid']] ?? null;
            if (!$p) continue;
            $kid = (string)($q['kid'] ?? '');
            $pk  = aiPinProviderKey($p, $kid);   // v10.17 (۳۰): کلیدِ همین ردیف
            $cc = $catByKey[aiTestRowKey((string)$q['pid'], (string)$q['mid'], $kid)] ?? null;
            if ($cc !== null) {
                $cj    = aiTestJudge((array)$cc['r'], (string)$q['mid'], (string)$q['pid']);
                $ccode = (int)($cc['r']['code'] ?? 0);
                if ($cj['billing'] !== '' || $cj['kind'] === 'badmodel' || in_array($ccode, [401, 404], true)) {
                    $reuse[] = ['p'=>$pk, 'mid'=>$q['mid'], 'pid'=>$q['pid'], 'kid'=>$kid,
                                't0'=>microtime(true) - ((int)$cc['lat']) / 1000,
                                'r'=>((array)$cc['r']) + ['msg_skipped'=>true]];
                    continue;
                }
            }
            $jobs[] = ['p'=>$pk, 'mid'=>$q['mid'], 'pid'=>$q['pid'], 'kid'=>$kid,
                       'payload'=>$payloadBase, 't0'=>microtime(true)];
        }
        $results = [];
        if ($jobs) {
            aiTestStateSave($st);
            $results = array_values(aiParallelCalls($jobs, $net, $concurrency));
        }
        foreach ($reuse as $ru) $results[] = $ru;
        if (!$results) continue;
        if (aiTestStopRequested()) { $st['stopped'] = true; break; }
        $roundMs = (int)round((microtime(true) - $t0r) * 1000);

        foreach ($results as $res) {
            if (aiTestStopRequested()) { $st['stopped'] = true; break 2; }
            if (!$recordResult($res, $catByKey)) { $st['stopped'] = true; break 2; }
        }
        $st['current'] = ['provider'=>'', 'model'=>''];
        $st['last_round_ms'] = $roundMs;
        aiProvidersSave($providers);
        aiTestStateSave($st);
        /* تاخیر بینِ دورها (نه بینِ تک‌تکِ درخواست‌ها): چون هر دور فقط یک
           درخواست به هر ارائه‌دهنده می‌زند، همین فاصله برای رعایتِ RPM کافی است. */
        if ($delayMs > 0 && !aiTestStopRequested()) usleep($delayMs * 1000);
    }

    /* =================================================================
     *  v10.18 (۳۱ب): دورهای جبرانیِ پایانِ صف
     *
     *  صفِ اصلی تمام شد. حالا هر ردیفی که با خطای *غیرمرتبط با اعتبار*
     *  قرمز شده (تایم‌اوت، ۵۰۰/۵۰۲، ۴۲۹، قطعِ اتصال، خطای پروکسی) تا سه
     *  بار دوباره تست می‌شود و هر بار تایم‌اوتِ شبکه بزرگ‌تر می‌شود
     *  (۱٫۷۵× در هر دور، سقفِ ۱۲۰ ثانیه). ردیف‌های اعتباری/مدلِ نامعتبر
     *  اصلاً وارد این دورها نمی‌شوند — تکرارشان فقط سهمیه می‌سوزاند.
     *
     *  نتیجهٔ هر تلاش از همان $recordResult عبور می‌کند، پس شمارنده‌ها،
     *  keyTests و جزئیات دقیقاً مثل دورِ اصلی به‌روز می‌شوند؛ فقط تعدادِ
     *  «tested» را دستی برمی‌گردانیم تا یک ردیف چند بار شمرده نشود.
     * ================================================================= */
    $st['retry_passes'] = 0;
    $st['retry_fixed']  = 0;
    $st['retry_tried']  = 0;
    $baseTimeout = (int)($net['timeout'] ?? 25);
    for ($pass = 1; $pass <= AI_TEST_RETRY_PASSES; $pass++) {
        if ($st['stopped'] || aiTestStopRequested()) break;
        /* کدام ردیف‌ها هنوز قرمزند و ارزشِ تلاشِ دوباره دارند؟ */
        $todo = [];
        foreach ($queue as $q) {
            $rk = aiTestRowKey((string)$q['pid'], (string)$q['mid'], (string)($q['kid'] ?? ''));
            $j0 = $rowJudge[$rk] ?? null;
            if ($j0 === null || !empty($j0['ok'])) continue;
            $why = aiTestRetryable($j0);
            if ($why === '') continue;
            $todo[] = ['q'=>$q, 'why'=>$why];
        }
        if (!$todo) break;

        $retNet = $net;
        $retNet['timeout'] = aiTestRetryTimeout($baseTimeout, $pass);
        $st['retry_passes'] = $pass;
        $st['retry_tried'] += count($todo);
        $st['current'] = ['provider'=>'تلاشِ دوبارهٔ ' . aiFaNum($pass) . ' از ' . aiFaNum(AI_TEST_RETRY_PASSES),
                          'model'=>aiFaNum(count($todo)) . ' مدل · تایم‌اوت ' . aiFaNum($retNet['timeout']) . ' ثانیه'];
        aiTestStateSave($st);

        /* گامِ ۱ — دسته‌بندی (اگر روشن است) تا جزئیاتِ ردیف کامل بماند */
        $catByKey2 = [];
        if ($catPayload !== null) {
            $cj2 = [];
            foreach ($todo as $t) {
                $p = $providers[$t['q']['pid']] ?? null;
                if (!$p) continue;
                $kid = (string)($t['q']['kid'] ?? '');
                $cj2[] = ['p'=>aiPinProviderKey($p, $kid), 'mid'=>$t['q']['mid'], 'pid'=>$t['q']['pid'],
                          'kid'=>$kid, 'payload'=>$catPayload, 't0'=>microtime(true)];
            }
            if ($cj2) {
                foreach (aiParallelCalls($cj2, $retNet, $concurrency) as $cr) {
                    $crr    = (array)$cr['r'];
                    $clat   = (int)round((microtime(true) - (float)$cr['t0']) * 1000);
                    $parsed = aiCatParse($crr, $testCat, (array)$catData['cats'], (string)$cr['mid'], $clat);
                    $catByKey2[aiTestRowKey((string)$cr['pid'], (string)$cr['mid'], (string)($cr['kid'] ?? ''))] =
                        ['res'=>$parsed, 'r'=>$crr, 'summary'=>aiCatSummary($parsed), 'meta'=>aiCatMeta($parsed), 'lat'=>$clat];
                }
            }
            if (aiTestStopRequested()) { $st['stopped'] = true; break; }
            if ($delayMs > 0) usleep($delayMs * 1000);
        }

        /* گامِ ۲ — پیام */
        $jobs2 = [];
        foreach ($todo as $t) {
            $p = $providers[$t['q']['pid']] ?? null;
            if (!$p) continue;
            $kid = (string)($t['q']['kid'] ?? '');
            $jobs2[] = ['p'=>aiPinProviderKey($p, $kid), 'mid'=>$t['q']['mid'], 'pid'=>$t['q']['pid'],
                        'kid'=>$kid, 'payload'=>$payloadBase, 't0'=>microtime(true)];
        }
        if (!$jobs2) break;
        $res2 = array_values(aiParallelCalls($jobs2, $retNet, $concurrency));
        if (aiTestStopRequested()) { $st['stopped'] = true; break; }

        foreach ($res2 as $res) {
            if (aiTestStopRequested()) { $st['stopped'] = true; break 2; }
            $rk  = aiTestRowKey((string)$res['pid'], (string)$res['mid'], (string)($res['kid'] ?? ''));
            $was = $rowJudge[$rk] ?? null;
            /* ردیف قبلاً شمرده شده؛ شمارنده‌ها را عقب بکش تا ثبتِ تازه
               جای نتیجهٔ قبلی بنشیند نه اینکه رویش اضافه شود. */
            $st['tested'] = max(0, (int)$st['tested'] - 1);
            $st['failed'] = max(0, (int)$st['failed'] - 1);
            if ($was !== null && (string)$was['billing'] !== '') $st['billing'] = max(0, (int)$st['billing'] - 1);
            if ($was !== null && $was['kind'] === 'proxy')   $st['proxy']    = max(0, (int)$st['proxy'] - 1);
            if ($was !== null && $was['kind'] === 'bogus')   $st['bogus']    = max(0, (int)$st['bogus'] - 1);
            if ($was !== null && $was['kind'] === 'badmodel') $st['badmodel'] = max(0, (int)$st['badmodel'] - 1);
            $res['retry_pass'] = $pass;
            $recordResult($res, $catByKey2);
            if (!empty($rowJudge[$rk]['ok'])) $st['retry_fixed']++;
        }
        $st['current'] = ['provider'=>'', 'model'=>''];
        aiProvidersSave($providers);
        aiTestStateSave($st);
        if ($delayMs > 0 && !aiTestStopRequested()) usleep($delayMs * 1000);
    }

    aiProvidersSave($providers);
    $st['running'] = false;
    $st['done'] = true;
    $extra = '';
    if (!empty($st['fallback_all_tested'])) $extra .= ' · ↻ مدل تست‌نشده‌ای نبود؛ همهٔ مدل‌های واجد شرایط دوباره آزموده شدند';
    if ($st['nonchat'] > 0) $extra .= ' · ⏭ ' . $st['nonchat'] . ' غیرچت';
    if ($st['billing'] > 0) $extra .= ' · 💳 ' . $st['billing'] . ' اعتبار/اشتراک';
    if ($st['proxy'] > 0)   $extra .= ' · 🛰 ' . $st['proxy'] . ' مسیرِ عبور';
    if ($st['bogus'] > 0)   $extra .= ' · ⚠ ' . $st['bogus'] . ' پاسخِ نامعتبر';
    /* v10.18 (۳۱ب): نتیجهٔ دورهای جبرانی را صریح گزارش کن */
    if ((int)($st['retry_tried'] ?? 0) > 0)
        $extra .= ' · ↻ ' . (int)$st['retry_tried'] . ' تلاشِ دوباره در '
                . (int)($st['retry_passes'] ?? 0) . ' دور'
                . ((int)($st['retry_fixed'] ?? 0) > 0 ? ' (' . (int)$st['retry_fixed'] . ' مورد درست شد)' : '');
    /* v10.476: پس از پایان کامل تست، بر اساس آمار پایداری و کیفیت، بهترین مدلِ دارای پاسخ مناسب
       به عنوان مدل مستر و بقیهٔ مدل‌های برتر به ترتیب پایداری و کیفیت به عنوان پشتیبان‌های مستر انتخاب می‌شوند */
    if (!$st['stopped']) {
        $dCfgDone = aiDailyTestCfg();
        if (!empty($dCfgDone['auto_select_master']) || $isDailyAuto) {
            $markDailyDone = $isDailyAuto || empty($st['only_untested']);
            $autoSel = aiAutoSelectMasterAndFallbacks($providers, $isDailyAuto ? 'daily_cron' : 'test_complete', [
                'mark_daily_done' => $markDailyDone,
            ]);
            $st['auto_selection'] = $autoSel;
            if (!empty($autoSel['ok']) && !empty($autoSel['master'])) {
                $mLbl = (string)($autoSel['master']['providerName'] ?? '') . ' / ' . (string)($autoSel['master']['modelName'] ?? $autoSel['master']['model'] ?? '');
                $fbCnt = count((array)($autoSel['fallbacks'] ?? []));
                $extra .= ' · ⭐ مستر: ' . $mLbl . ($fbCnt > 0 ? (' (+' . $fbCnt . ' پشتیبان)') : '');
            }
        }
    }
    $st['summary'] = $st['stopped']
        ? 'توقف خواسته شد — '.$st['tested'].' تست انجام شد'
        : 'تمام شد — '.$st['tested'].' تست · 🟢 '.$st['available'].' · 🔴 '.$st['failed'].$extra;
    aiTestStateSave($st);
    @unlink(AI_TEST_STOP_FILE);
    return $st;
}

/* =====================================================================
 *  v9.99: «رفعِ گیر» برای تستِ مدل‌ها  →  ?ai_test_unstick=1
 *
 *  چرا لازم است: پردازهٔ پس‌زمینهٔ تست ممکن است وسطِ کار بمیرد (کشته‌شدن
 *  توسط هاست، ری‌استارتِ php-fpm، تایم‌اوتِ سخت). در آن حالت running در فایلِ
 *  وضعیت true می‌ماند، مرورگر بی‌نهایت poll می‌کند و کاربر فکر می‌کند تست
 *  ادامه دارد در حالی که هیچ‌کس کار نمی‌کند.
 *
 *  این اندپوینت همان الگوی «رفعِ گیر»ِ صفِ ارسال (bsl_queue) را برای تست
 *  پیاده می‌کند:
 *    ۱) وضعیتِ مرده را تشخیص می‌دهد (updated_at کهنه).
 *    ۲) قفلِ running و فایلِ توقف را آزاد می‌کند.
 *    ۳) کار را با only_untested=1 از سر می‌گیرد؛ چون نتیجهٔ هر دور بلافاصله
 *       ذخیره شده، مدل‌های تست‌شده دوباره تست نمی‌شوند و کار دقیقاً از همان
 *       نقطه ادامه پیدا می‌کند.
 * ===================================================================== */
if (isset($_GET['ai_test_unstick'])) {
header('Content-Type: application/json; charset=UTF-8');
$aiTestLockFp = aiTestLockOpen();
if (!$aiTestLockFp) {
    echo json_encode(['ok' => false, 'running' => true,
        'error' => 'تستِ مدل‌ها هنوز قفلِ فعال دارد — اجرای موازی ساخته نشد'], JSON_UNESCAPED_UNICODE);
    exit;
}
register_shutdown_function(function () use ($aiTestLockFp) { aiTestLockClose($aiTestLockFp); });
$st = aiTestStateLoad();
$stAt = (int)($st['updated_at'] ?? $st['started_at'] ?? 0);
$idle = $stAt > 0 ? (time() - $stAt) : PHP_INT_MAX;
$stall = max(60, (int)(loadConnections()['ai_test_stall_sec'] ?? 300));
$force = !empty($_GET['force']);

// اگر واقعاً زنده است و به‌تازگی به‌روز شده، دست نزن
if (!empty($st['running']) && empty($st['done']) && $idle < $stall && !$force) {
    echo json_encode(['ok'=>false, 'alive'=>true, 'idle_sec'=>$idle,
        'error'=>'تست زنده است و ' . $idle . ' ثانیه پیش به‌روز شده — گیر نکرده'], JSON_UNESCAPED_UNICODE);
    exit;
}

$args = (array)($st['args'] ?? []);
$per     = max(1, min(500, (int)($_GET['per_provider'] ?? ($args['per'] ?? 50))));
$testMsg = trim((string)($_GET['msg'] ?? ($args['msg'] ?? 'سلام')));
if ($testMsg === '') $testMsg = 'سلام';
$testCat = trim((string)($_GET['cat'] ?? ($args['cat'] ?? 'ادو پرفیوم')));
if ($testCat === '') $testCat = 'ادو پرفیوم';
$delayMs = max(0, min(60000, (int)($_GET['delay'] ?? ($args['delay'] ?? 120))));
$concurrency = max(1, min(16, (int)($_GET['conc'] ?? ($args['conc'] ?? 4))));
// اگر وضعیتِ قبلی این پارامتر را نداشت، همان پیش‌فرضِ شروعِ تست (روشن) بماند
$skipNonChat = isset($_GET['nonchat']) ? ($_GET['nonchat'] !== '0')
                                       : (array_key_exists('nonchat', $args) ? !empty($args['nonchat']) : true);
$prevRunEpoch = max(0, (int)($args['run_epoch'] ?? ($st['run_epoch'] ?? 0)));
$prevDailyAuto = !empty($args['daily_auto']) || !empty($st['daily_auto']);

// آزادسازی قفل‌ها
@unlink(AI_TEST_STOP_FILE);
$doneBefore = (int)($st['tested'] ?? 0);
$st['running'] = false; $st['done'] = true; $st['stalled'] = true;
aiTestStateSave($st);

/* از سر بگیر: فقط مدل‌های تست‌نشده — یعنی همان‌هایی که به آن‌ها نرسیده بودیم */
finishRequestNow(json_encode(['ok'=>true, 'unstuck'=>true, 'resumed'=>true,
    'idle_sec'=>$idle, 'done_before'=>$doneBefore,
    'note'=>'تستِ گیرکرده آزاد شد و از همان‌جا ادامه یافت — ' . $doneBefore . ' مدل قبلاً تست شده بود'],
    JSON_UNESCAPED_UNICODE));
if ($prevRunEpoch > 0) $GLOBALS['_aiTestResumeEpoch'] = $prevRunEpoch;
$GLOBALS['_aiTestRunEpoch'] = $prevRunEpoch > 0 ? $prevRunEpoch : time();
$GLOBALS['_aiDailyAutoRun'] = $prevDailyAuto;
aiRunTestBackground($per, true, $testMsg, $testCat, $delayMs, $concurrency, $skipNonChat);
exit;
}

if (isset($_GET['ai_test_start']) || isset($_GET['ai_test_all'])) {
header('Content-Type: application/json; charset=UTF-8');
$aiTestLockFp = aiTestLockOpen();
if (!$aiTestLockFp) {
    echo json_encode(['ok' => false, 'running' => true,
        'error' => 'تستِ مدل‌ها هنوز قفلِ فعال دارد — اجرای موازی ساخته نشد'], JSON_UNESCAPED_UNICODE);
    exit;
}
register_shutdown_function(function () use ($aiTestLockFp) { aiTestLockClose($aiTestLockFp); });
$per = max(1, min(500, (int)($_GET['per_provider'] ?? 50)));
$onlyUntested = !empty($_GET['only_untested']);
// v9.52: پیام تست و دستهٔ تستِ قابل‌تنظیم (پیش‌فرض «سلام» و «ادو پرفیوم»)
$testMsg = trim((string)($_GET['msg'] ?? 'سلام'));
if ($testMsg === '') $testMsg = 'سلام';
$testCat = trim((string)($_GET['cat'] ?? 'ادو پرفیوم'));
if ($testCat === '') $testCat = 'ادو پرفیوم';
// v9.56: تاخیر بین هر تست (میلی‌ثانیه) — برای جلوگیری از ریت‌لیمیت
$delayMs = max(0, min(60000, (int)($_GET['delay'] ?? 120)));
// v9.99: سقفِ درخواست‌های هم‌زمان و ردکردنِ مدل‌های غیرچت
$concurrency = max(1, min(16, (int)($_GET['conc'] ?? 4)));
$skipNonChat = ($_GET['nonchat'] ?? '1') !== '0';
$GLOBALS['_aiDailyAutoRun'] = !empty($_GET['daily_auto']);
$GLOBALS['_aiTestRunEpoch'] = max(0, (int)($_GET['run_epoch'] ?? 0)) ?: time();
// اگر کاری در حال اجراست، دوباره شروع نکن
$cur = aiTestStateLoad();
if (!empty($cur['running'])) {
    echo json_encode(['ok'=>false,'running'=>true,'error'=>'تست مدل‌ها در حال اجراست — برای شروع تازه اول متوقفش کنید (?)'], JSON_UNESCAPED_UNICODE);
    exit;
}
$detach = !isset($_GET['sync']);
finishRequestNow(json_encode(['ok'=>true,'started'=>true,'background'=>$detach,
    'note'=>'تست در پس‌زمینهٔ سرور ادامه دارد — می‌توانید صفحه را ببندید'], JSON_UNESCAPED_UNICODE));
if (!$detach) {
    // حالت هم‌زمان برای تست/عیب‌یابی
    aiRunTestBackground($per, $onlyUntested, $testMsg, $testCat, $delayMs, $concurrency, $skipNonChat);
    exit;
}
// پس از جدا شدن از مرورگر، اجرای واقعی ادامه می‌یابد
aiRunTestBackground($per, $onlyUntested, $testMsg, $testCat, $delayMs, $concurrency, $skipNonChat);
exit;
}

/* =====================================================================
 *  v10.476: اندپوینت‌های مدیریت و مشاهدهٔ تست خودکار روزانه و انتخاب مستر + پشتیبان‌ها
 * ===================================================================== */
if (isset($_GET['ai_daily_status'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $cn = loadConnections();
    $cfg = aiDailyTestCfg($cn);
    $providers = aiProvidersLoad();
    $v = aiVotesLoad();
    $dst = aiDailyStateLoad();
    if (!empty($cfg['auto_select_master']) && (empty($v['auto_master']) || empty($dst['master']))) {
        $eval0 = aiEvaluateAndRankModels($providers, $v);
        if (!empty($eval0['eligible'])) {
            aiAutoSelectMasterAndFallbacks($providers, 'status_bootstrap', ['mark_daily_done' => false]);
            $v = aiVotesLoad();
            $dst = aiDailyStateLoad();
        }
    }
    $eval = aiEvaluateAndRankModels($providers, $v);
    echo json_encode([
        'ok'              => true,
        'config'          => $cfg,
        'state'           => $dst,
        'master'          => aiMasterKey(),
        'auto_master'     => $v['auto_master'] ?? '',
        'pin'             => $v['pin'] ?? '',
        'manual_pin_lock' => !empty($v['manual_pin_lock']),
        'fallbacks'       => $v['fallbacks'] ?? [],
        'eligible_count'  => $eval['eligible_count'],
        'total_evaluated' => $eval['total_evaluated'],
        'top_ranked'      => array_slice($eval['eligible'], 0, max(5, (int)$cfg['max_fallbacks'] + 1)),
    ], JSON_UNESCAPED_UNICODE);
    exit;
}
if (($_POST['action'] ?? '') === 'ai_daily_config_save') {
    header('Content-Type: application/json; charset=UTF-8');
    $cn = loadConnections();
    $cur = aiDailyTestCfg($cn);
    if (isset($_POST['enabled']))            $cur['enabled'] = !empty($_POST['enabled']) && $_POST['enabled'] !== 'false' && $_POST['enabled'] !== '0';
    if (isset($_POST['auto_select_master'])) $cur['auto_select_master'] = !empty($_POST['auto_select_master']) && $_POST['auto_select_master'] !== 'false' && $_POST['auto_select_master'] !== '0';
    if (isset($_POST['interval_hours']))     $cur['interval_hours'] = max(1, min(168, (int)$_POST['interval_hours']));
    if (isset($_POST['per_provider']))       $cur['per_provider'] = max(1, min(500, (int)$_POST['per_provider']));
    if (isset($_POST['max_fallbacks']))      $cur['max_fallbacks'] = max(1, min(50, (int)$_POST['max_fallbacks']));
    if (isset($_POST['concurrency']))        $cur['concurrency'] = max(1, min(16, (int)$_POST['concurrency']));
    if (isset($_POST['delay_ms']))           $cur['delay_ms'] = max(0, min(60000, (int)$_POST['delay_ms']));
    if (isset($_POST['test_msg']) && trim((string)$_POST['test_msg']) !== '') $cur['test_msg'] = trim((string)$_POST['test_msg']);
    if (isset($_POST['test_cat']) && trim((string)$_POST['test_cat']) !== '') $cur['test_cat'] = trim((string)$_POST['test_cat']);
    $cn['ai_daily_test'] = $cur;
    $ok = saveConnections($cn);
    $rerank = null;
    if ($ok && !empty($cur['auto_select_master'])) {
        $rerank = aiAutoSelectMasterAndFallbacks(null, 'config_save', ['max_fallbacks' => $cur['max_fallbacks']]);
    }
    echo json_encode(['ok' => $ok, 'config' => $cur, 'rerank' => $rerank], JSON_UNESCAPED_UNICODE);
    exit;
}
if (isset($_GET['ai_rerank_master_now']) || (($_POST['action'] ?? '') === 'ai_rerank_master_now')) {
    header('Content-Type: application/json; charset=UTF-8');
    $runTest = !empty($_REQUEST['run_test']);
    if ($runTest) {
        $runRes = s4CronMaybeRunDailyAiTest('manual_trigger', true);
        echo json_encode(['ok' => !empty($runRes['ok']), 'mode' => 'daily_test_started', 'dispatch' => $runRes], JSON_UNESCAPED_UNICODE);
        exit;
    }
    $sel = aiAutoSelectMasterAndFallbacks(null, 'manual_rerank', ['force_auto' => !empty($_REQUEST['force_auto'])]);
    echo json_encode($sel, JSON_UNESCAPED_UNICODE);
    exit;
}

/* =====================================================================
 *  v9.38: مدل‌های کاندید + مدل مستر — مدیریت، آزمون چند-مدلی و رأی
 * ===================================================================== */
/* وضعیت کاندیدها + امتیازات + مستر */
if (isset($_GET['ai_candidates'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $providers = aiProvidersLoad();
    $v = aiVotesLoad();
    $dCfg = aiDailyTestCfg();
    if (!empty($dCfg['auto_select_master']) && empty($v['auto_master'])) {
        $evalBoot = aiEvaluateAndRankModels($providers, $v);
        if (!empty($evalBoot['eligible'])) {
            aiAutoSelectMasterAndFallbacks($providers, 'candidates_bootstrap', ['mark_daily_done' => false]);
            $v = aiVotesLoad();
        }
    }
    $cands = aiCandidates();
    $master = aiMasterKey();
    $eval = aiEvaluateAndRankModels($providers, $v);
    $rankMap = $eval['by_key'] ?? [];
    $items = [];
    foreach ($cands as $idxPos => $c) {
        $mn = $c['model'];
        if (isset($providers[$c['provider']])) {
            foreach ($providers[$c['provider']]['models'] as $mm) {
                if (($mm['id'] ?? '') === $c['model']) { $mn = $mm['name'] ?? $c['model']; break; }
            }
        }
        $s = $v['scores'][$c['key']] ?? ['wins' => 0, 'losses' => 0, 'votes' => 0];
        $rk = $rankMap[$c['key']] ?? null;
        $items[] = [
            'provider'        => $c['provider'],
            'model'           => $c['model'],
            'key'             => $c['key'],
            'providerName'    => $c['providerName'],
            'modelName'       => $mn,
            'wins'            => (int)($s['wins'] ?? 0),
            'losses'          => (int)($s['losses'] ?? 0),
            'votes'           => (int)($s['votes'] ?? 0),
            'score'           => aiScoreOf($s),
            'order_idx'       => $idxPos,
            'composite_score' => $rk ? (float)$rk['composite_score'] : 0.0,
            'stability_score' => $rk ? (float)$rk['stability_score'] : 0.0,
            'quality_score'   => $rk ? (float)$rk['quality_score'] : 0.0,
            'pass_rate'       => $rk ? (float)$rk['pass_rate'] : 0.0,
            'cat_rate'        => $rk ? $rk['cat_rate'] : null,
            'streak_ok'       => $rk ? (int)$rk['streak_ok'] : 0,
            'runs'            => $rk ? (int)$rk['runs'] : 0,
            'latency_ms'      => $rk ? (int)$rk['display_lat_ms'] : 0,
            'proper_latest'   => $rk ? !empty($rk['proper_latest']) : false,
            'available'       => $rk ? !empty($rk['available']) : false,
        ];
    }
    usort($items, function ($a, $b) use ($master) {
        $aM = ($a['key'] === $master) ? 1 : 0;
        $bM = ($b['key'] === $master) ? 1 : 0;
        if ($aM !== $bM) return $bM <=> $aM;
        $aP = !empty($a['proper_latest']) ? 1 : 0;
        $bP = !empty($b['proper_latest']) ? 1 : 0;
        if ($aP !== $bP) return $bP <=> $aP;
        if ($a['composite_score'] !== $b['composite_score']) return $b['composite_score'] <=> $a['composite_score'];
        if ($a['stability_score'] !== $b['stability_score']) return $b['stability_score'] <=> $a['stability_score'];
        return ($a['order_idx'] <=> $b['order_idx']);
    });
    $fbRank = 0;
    foreach ($items as &$itRef) {
        if ($itRef['key'] === $master) {
            $itRef['role'] = 'master';
            $itRef['fallback_rank'] = 0;
        } else {
            $fbRank++;
            $itRef['role'] = 'fallback';
            $itRef['fallback_rank'] = $fbRank;
        }
    }
    unset($itRef);
    echo json_encode([
        'ok'              => true,
        'candidates'      => $items,
        'master'          => $master,
        'auto_master'     => $v['auto_master'] ?? '',
        'pin'             => !empty($v['manual_pin_lock']) ? $v['pin'] : '',
        'manual_pin_lock' => !empty($v['manual_pin_lock']),
        'daily_test'      => ['config' => $dCfg, 'state' => aiDailyStateLoad()],
        'history'         => array_slice(array_reverse($v['history']), 0, 50),
    ], JSON_UNESCAPED_UNICODE);
    exit;
}
/* ذخیرهٔ کاندیدها + سنجاقِ مستر */
if (($_POST['action'] ?? '') === 'ai_candidates_save') {
    header('Content-Type: application/json; charset=UTF-8');
    $list = json_decode((string)($_POST['candidates'] ?? '[]'), true);
    $ok = is_array($list) && aiCandidatesSave($list);
    // سنجاقِ مستر فقط وقتی به‌روزرسانی شود که صریحاً همراه درخواست آمده باشد
    // (افزودن/حذف یک کاندید نباید سنجاقِ دستیِ مستر را پاک کند)
    $pinProvided = isset($_POST['pin']);
    $pin = $pinProvided ? trim((string)$_POST['pin']) : '';
    if ($ok && $pinProvided) {
        $v = aiVotesLoad();
        $valid = false;
        foreach (aiCandidates() as $c) { if ($c['key'] === $pin) { $valid = true; break; } }
        $v['pin'] = $valid ? $pin : '';
        $v['manual_pin_lock'] = ($valid && $pin !== '');
        if ($pin === '' && aiDailyTestCfg()['auto_select_master']) {
            aiVotesSave($v);
            aiAutoSelectMasterAndFallbacks(null, 'pin_auto', ['force_auto' => true]);
            $v = aiVotesLoad();
        } else {
            $v['master'] = aiMasterKey();
            aiVotesSave($v);
        }
    }
    echo json_encode(['ok' => $ok, 'error' => $ok ? '' : 'خطا در ذخیرهٔ کاندیدها'], JSON_UNESCAPED_UNICODE);
    exit;
}
/* ثبت رأی برای یک آزمون */
if (($_POST['action'] ?? '') === 'ai_vote') {
    header('Content-Type: application/json; charset=UTF-8');
    $task = in_array((string)($_POST['task'] ?? ''), ['category', 'autoreply'], true) ? $_POST['task'] : 'category';
    $input = (string)($_POST['input'] ?? '');
    $winner = trim((string)($_POST['winner'] ?? ''));
    $cands = json_decode((string)($_POST['candidates'] ?? '[]'), true);
    if ($winner === '' || !is_array($cands)) { echo json_encode(['ok' => false, 'error' => 'رأی نامعتبر'], JSON_UNESCAPED_UNICODE); exit; }
    $v = aiVoteRecord($task, $input, $winner, array_map('strval', $cands));
    // v9.49: اگر رأیِ دسته‌بندی است و دستهٔ برنده هم داده شد، همان را در
    // حافظهٔ یادگیری ثبت کن تا «اصلاح بقیه با مستر» و مسیرهای بعدی از آن
    // استفاده کنند. (برندهٔ واقعی جایی است که کاربر برگزیده؛ مستر فقط مرجع است.)
    if ($task === 'category' && $input !== '') {
        $catId = (int)($_POST['cat_id'] ?? 0);
        if ($catId > 0) {
            $v['learned'] = catLearnRecord($input, $catId, trim((string)($_POST['cat_name'] ?? '')));
            $v['learn_word'] = catFirstWord($input);
        }
    }
    echo json_encode(['ok' => true, 'master' => $v['master'], 'pin' => $v['pin'],
        'scores' => $v['scores'], 'learned' => $v['learned'] ?? false,
        'learn_word' => $v['learn_word'] ?? ''], JSON_UNESCAPED_UNICODE);
    exit;
}
/* آزمون دسته‌بندی با همهٔ کاندیدها — پاسخ هر مدل جدا می‌آید */
if (isset($_GET['ai_candidates_category'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(180);
    $title = trim((string)($_GET['title'] ?? ''));
    if ($title === '') { echo json_encode(['ok' => false, 'error' => 'عنوان محصول خالی'], JSON_UNESCAPED_UNICODE); exit; }
    $cands = aiCandidates();
    if (!$cands) { echo json_encode(['ok' => false, 'error' => 'هیچ مدل کاندیدی انتخاب نشده — اول در بخش 🤖 چند مدل کاندید اضافه کنید'], JSON_UNESCAPED_UNICODE); exit; }
    $cn = loadConnections(); $tk = (string)($cn['basalam']['token'] ?? '');
    $cats = [];
    if (!empty($tk)) {
        $cats = bslCatsAll($tk); /* v10.41 (۵۵): از کشِ مشترک */
    }
    if (!$cats) { echo json_encode(['ok' => false, 'error' => 'دسته‌بندی‌های باسلام در دسترس نیست'], JSON_UNESCAPED_UNICODE); exit; }
    $catList = ''; $leafCats = [];
    foreach ($cats as $c) { if (($c['level'] ?? 0) >= 2) { $catList .= $c['id'] . ': ' . $c['name'] . "\n"; $leafCats[] = $c; } }
    if (!$leafCats) { foreach ($cats as $c) { $catList .= $c['id'] . ': ' . $c['name'] . "\n"; $leafCats[] = $c; } }
    if (strlen($catList) > 3000) { $catList = ''; $leafCats = array_slice($leafCats, 0, 200); foreach ($leafCats as $c) { $catList .= $c['id'] . ': ' . $c['name'] . "\n"; } }
    $providers = aiProvidersLoad();
    $net = aiNetCfg();
    $items = [];
    foreach ($cands as $c) {
        $p = $providers[$c['provider']] ?? null;
        if (!$p) continue;
        $res = aiCandidateCategory($p, $c['model'], $title, $cats, $leafCats, $catList, $net);
        $res['key'] = $c['key'];
        $res['providerName'] = $c['providerName'];
        $items[] = $res;
    }
    echo json_encode(['ok' => true, 'title' => $title, 'master' => aiMasterKey(), 'items' => $items], JSON_UNESCAPED_UNICODE);
    exit;
}
/* آزمون پاسخ خودکار با همهٔ کاندیدها */
if (isset($_GET['ai_candidates_reply'])) {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(180);
    $msg = trim((string)($_GET['msg'] ?? ($_GET['text'] ?? '')));
    if ($msg === '') { echo json_encode(['ok' => false, 'error' => 'پیام خالی است'], JSON_UNESCAPED_UNICODE); exit; }

    $cands = aiCandidates();
    if (!$cands) { echo json_encode(['ok' => false, 'error' => 'هیچ مدل کاندیدی انتخاب نشده'], JSON_UNESCAPED_UNICODE); exit; }
    $providers = aiProvidersLoad();
    $items = [];
    foreach ($cands as $c) {
        $p = $providers[$c['provider']] ?? null;
        if (!$p) continue;
        $res = aiCandidateReply($p, $c['model'], $msg, 8);
        $res['key'] = $c['key'];
        $res['providerName'] = $c['providerName'];
        $items[] = $res;
    }
    echo json_encode(['ok' => true, 'master' => aiMasterKey(), 'items' => $items], JSON_UNESCAPED_UNICODE);
    exit;
}

/* v10.72: تولید خودکار توضیحات و دسته‌بندی با هوش مصنوعی (مستر و کاندیدها + وب) */
if (isset($_GET['ai_generate_product_content']) || ($_POST['action'] ?? '') === 'ai_generate_product_content') {
    header('Content-Type: application/json; charset=UTF-8');
    @set_time_limit(180);
    $title = trim((string)($_REQUEST['title'] ?? ''));
    if ($title === '') {
