/**
 * v8.58: نام دسته‌بندی‌های یک وظیفهٔ صف باسلام.
 *
 * تا اینجا مودال هر وظیفه فقط آمار و فهرست محصولات را نشان می‌داد و
 * معلوم نبود این وظیفه با کدام دسته ارسال شده. حالا دستهٔ اصلی، حالت
 * «دستهٔ خودکار» و دسته‌های جایگزین با نام برگردانده می‌شوند.
 *
 * درخت دسته‌ها یک بار گرفته و کنار فایل کش می‌شود؛ اگر شبکه در دسترس
 * نبود، همان شناسه‌ها بدون نام برمی‌گردند و مودال باز می‌ماند.
 */
function bslCatNameMapCached(): array {
    static $map = null;
    if ($map !== null) return $map;
    $map = [];
    $cacheFile = __DIR__ . '/bsl_cat_names.json';
    if (is_file($cacheFile) && (time() - (int)@filemtime($cacheFile)) < 86400) {
        $d = json_decode((string)@file_get_contents($cacheFile), true);
        if (is_array($d) && $d) { $map = $d; return $map; }
    }
    $cn = loadConnections();
    $tk = (string)($cn['basalam']['token'] ?? '');
    if ($tk === '') return $map;
    /* v10.41 (۵۵): از کشِ مشترک — نه یک واکشیِ مستقلِ دیگر */
    foreach (bslCatsAll($tk) as $c) {
        $id = (int)($c['id'] ?? 0);
        if ($id > 0) $map[$id] = (string)($c['name'] ?? '');
    }
    if ($map) @file_put_contents($cacheFile, json_encode($map, JSON_UNESCAPED_UNICODE), LOCK_EX);
    return $map;
}

function bslQueueCatInfo(array $cfg): array {
    $names   = bslCatNameMapCached();
    $mainId  = (int)($cfg['category_id'] ?? 0);
    $autoCat = !empty($cfg['auto_category']);
    $label   = function (int $id) use ($names) {
        $n = $names[$id] ?? '';
        return ['id' => $id, 'name' => $n !== '' ? $n : ('#' . $id)];
    };
    $fallback = [];
    foreach ((array)($cfg['fallback_cat_ids'] ?? []) as $fid) {
        $fid = (int)$fid;
        if ($fid > 0) $fallback[] = $label($fid);
    }
    return [
        'main'          => $mainId > 0 ? $label($mainId) : null,
        'auto_category' => $autoCat,
        'fallback'      => $fallback,
        'title_suffix'  => trim((string)($cfg['title_suffix'] ?? '')),
    ];
}

function bslReadQueue(): array {
clearstatcache(true,BSL_QUEUE_FILE);
if(!file_exists(BSL_QUEUE_FILE)) return ['entries'=>[]];
$d=@json_decode(@file_get_contents(BSL_QUEUE_FILE)?:'',true);
if(!is_array($d)||!isset($d['entries'])||!is_array($d['entries'])) return ['entries'=>[]];
$fixed=false;
foreach($d['entries'] as &$re){
if(!is_array($re))continue;
if((int)($re['total']??0)<=0&&in_array((string)($re['status']??''),['running','waiting','paused'],true)){
$pf=(string)($re['products_file']??'');
if($pf===''&&!empty($re['id']))$pf=__DIR__.'/bsl_queue_products_'.basename((string)$re['id']).'.json';
if($pf!==''&&is_file($pf)){
$arr=@json_decode(@file_get_contents($pf)?:'[]',true);
if(is_array($arr)&&count($arr)>0){$re['total']=count($arr);$re['products_file']=$pf;$fixed=true;}
}
}
}
unset($re);
if($fixed)bslWriteQueue($d);
return $d;
}
function bslWriteQueue(array $queue): void {
sendQueueAtomicWrite(BSL_QUEUE_FILE,$queue);
}

/**
 * v8.36: فایل محصولاتِ یک ورودی صف را برمی‌گرداند.
 *
 * چرا لازم است: تا نسخهٔ ۸.۳۵ همهٔ ارسال‌ها از یک فایل مشترک
 * (BSL_PRODUCTS_FILE) می‌خواندند، ولی آن فایل با شروع هر ارسال تازه
 * بازنویسی می‌شد. نتیجه این بود که اگر پروفایل دیگری ارسال می‌شد،
 * محصولات پروفایل قبلی فرستاده می‌شد. حالا هر صف فایل خودش را دارد.
 */
function bslQueueProductsFile(string $queueId): string {
    $queueId=trim($queueId);
    if($queueId!==''){
        // مسیر ثبت‌شده در خود صف مرجع اصلی است
        $q=bslReadQueue();
        foreach(($q['entries']??[]) as $e){
            if(($e['id']??'')===$queueId){
                $f=(string)($e['products_file']??'');
                if($f!==''&&is_file($f)) return $f;
                break;
            }
        }
        $guess=__DIR__.'/bsl_queue_products_'.basename($queueId).'.json';
        if(is_file($guess)) return $guess;
    }
    return BSL_PRODUCTS_FILE;   // سازگاری با مسیرهای قدیمی بدون queue_id
}

/** همان منطق برای ووکامرس */
function wooQueueProductsFile(string $queueId): string {
    $queueId=trim($queueId);
    $q=@json_decode((string)@file_get_contents(WOO_QUEUE_FILE),true);
    $entries=is_array($q['entries']??null)?$q['entries']:[];
    if($queueId!==''){
        foreach($entries as $e){
            if(($e['id']??'')===$queueId){
                $f=(string)($e['products_file']??'');
                if($f!==''&&is_file($f)) return $f;
                break;
            }
        }
        $guess=__DIR__.'/woo_queue_products_'.basename($queueId).'.json';
        if(is_file($guess)) return $guess;
    }
    // فراخوان‌های ووکامرس queue_id نمی‌فرستند؛ پس ردیف در حال اجرا را خودمان پیدا می‌کنیم
    foreach($entries as $e){
        if(($e['status']??'')==='running'){
            $f=(string)($e['products_file']??'');
            if($f!==''&&is_file($f)) return $f;
        }
    }
    return WOO_PRODUCTS_FILE;
}

/* ممیزی یک‌جای تمام مسیرهای ارسال دستی/همگام‌سازی؛ فقط تشخیصی و بدون افشای مسیر/توکن. */
if (isset($_GET['send_pipeline_audit'])) {
    header('Content-Type: application/json; charset=UTF-8');
    $scan = static function (string $dest, array $q): array {
        $issues = []; $notices = []; $statusCounts = []; $triggerCounts = []; $activeProfiles = []; $validFiles = 0;
        foreach ((array)($q['entries'] ?? []) as $e) {
            if (!is_array($e)) continue;
            $id = (string)($e['id'] ?? ''); $st = (string)($e['status'] ?? 'unknown');
            $profile = (string)($e['profile_key'] ?? ''); $trigger = (string)($e['trigger'] ?? 'legacy');
            $statusCounts[$st] = ($statusCounts[$st] ?? 0) + 1;
            $triggerCounts[$trigger] = ($triggerCounts[$trigger] ?? 0) + 1;
            if (in_array($st, ['waiting','running','paused'], true) && $profile !== '') $activeProfiles[$profile][] = $id;
            $file = (string)($e['products_file'] ?? '');
            if ($file === '' || !is_file($file)) {
                if (in_array($st, ['waiting','running','paused'], true)) $issues[] = ['key'=>'missing_products_file','queue_id'=>$id,'profile'=>$profile,'status'=>$st];
                continue;
            }
            $raw = (string)@file_get_contents($file); $products = json_decode($raw, true);
            if (!is_array($products)) $issues[] = ['key'=>'invalid_products_json','queue_id'=>$id,'profile'=>$profile,'status'=>$st];
            else {
                $validFiles++;
                $declared = (int)($e['total'] ?? 0);
                if ($declared !== count($products)) {
                    $item = ['key'=>'total_mismatch','queue_id'=>$id,'profile'=>$profile,'status'=>$st,'declared'=>$declared,'actual'=>count($products)];
                    if (in_array($st, ['waiting','running','paused'], true)) $issues[] = $item; else $notices[] = $item;
                }
            }
            if ((int)($e['current'] ?? 0) > (int)($e['total'] ?? 0)) $issues[] = ['key'=>'cursor_overflow','queue_id'=>$id,'profile'=>$profile];
            if ($st === 'running' && (int)($e['started_at'] ?? 0) > 0 && time() - (int)$e['started_at'] > 3600)
                $issues[] = ['key'=>'stale_running','queue_id'=>$id,'profile'=>$profile,'age_sec'=>time()-(int)$e['started_at']];
        }
        foreach ($activeProfiles as $profile => $ids) if (count($ids) > 1)
            $issues[] = ['key'=>'duplicate_active_profile','profile'=>$profile,'queue_ids'=>$ids];
        return ['destination'=>$dest,'entries'=>count((array)($q['entries']??[])),'status_counts'=>(object)$statusCounts,
            'trigger_counts'=>(object)$triggerCounts,'valid_product_files'=>$validFiles,'issues'=>$issues,'notices'=>$notices];
    };
    $wooAudit = $scan('woocommerce', wooReadQueue()); $bslAudit = $scan('basalam', bslReadQueue());
    $issues = array_merge($wooAudit['issues'], $bslAudit['issues']);
    $notices = array_merge($wooAudit['notices'], $bslAudit['notices']);
    echo json_encode(['ok'=>true,'version'=>APP_VERSION,'healthy'=>!$issues,'issue_count'=>count($issues),
        'notice_count'=>count($notices),'destinations'=>[$wooAudit,$bslAudit], 'fixes_present'=>[
            'canonical_profile_products'=>true,'atomic_queue_product_files'=>true,
            'running_profile_dedup'=>true,'destination_specific_woo_suffix'=>true,
            'basalam_422_repair'=>true,'multi_shop_fanout'=>true,
        ], 'solutions'=>[
            'missing_products_file'=>'ردیف فعال بدون فایل محصول باید ناموفق و از پروفایل دوباره صف شود',
            'duplicate_active_profile'=>'برای هر پروفایل و مقصد فقط یک ردیف فعال نگه داشته شود',
            'stale_running'=>'قفل worker بررسی و ردیف از checkpoint ادامه داده شود',
            'total_mismatch'=>'total از تعداد واقعی فایل محصولات بازسازی شود',
        ]], JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);
    exit;
}

