$bp=['name'=>mb_substr($pTitle,0,120),'brief'=>mb_substr($bsBrief,0,250),'description'=>$bsDesc,'primary_price'=>$pn,'stock'=>(int)($bs['stock']??10),'preparation_days'=>(int)($bs['preparation_days']??3),'weight'=>(int)$_wStreamNoImg['weight'],'package_weight'=>(int)$_wStreamNoImg['package_weight'],'is_wholesale'=>false,'category_id'=>$catId,'status'=>3790];
if(!empty($p['sku']))$bp['sku']=$p['sku'];
$r=bslReq($tk,'POST','vendors/'.$vid.'/products',$bp);
if($r['ok']&&!empty($r['body']['id'])){
$sent++;send_sse('send_ok',['key'=>$pKey,'remote_id'=>$r['body']['id'],'title'=>$pTitle,'note'=>'بدون تصویر (غیرفعال)']);
}else{
$em=$r['body']['error_description']??$r['body']['message']??$r['body']['error']??'';
if(is_array($em))$em=json_encode($em,JSON_UNESCAPED_UNICODE);

if(mb_stripos($em,'دسته')!==false||mb_stripos($em,'category')!==false||mb_stripos($em,'فرزند')!==false){
$fbResult=bslTryCreateWithFallback($tk,$vid,$bp,$bslFallbackCats,$pTitle,$autoCat,$bslFlatCats,$cData);
if(!empty($fbResult['ok'])){
$sent++;send_sse('send_ok',['key'=>$pKey,'remote_id'=>$fbResult['body']['id'],'title'=>$pTitle,'note'=>'بدون تصویر (اصلاح دسته: '.$fbResult['used_cat_id'].')']);
usleep($bslDelayMs*1000);continue;
}
}
$fail++;send_sse('send_fail',['key'=>$pKey,'error'=>'تصویر+ایجاد بدون تصویر ناموفق: '.mb_substr($em,0,150)]);
}
usleep($bslDelayMs*1000);continue;
}

$_builtStreamMain=bslBuildUnifiedDescription($p,$pTitle);
$bsBrief=$_builtStreamMain['brief']!==''?$_builtStreamMain['brief']:mb_substr(s4HtmlToPlainTextForBsl($pTitle),0,250,'UTF-8');
$bsDesc=$_builtStreamMain['description']!==''?$_builtStreamMain['description']:$bsBrief;

$__sseManualCats=bslCollectManualCategories((int)($p['bsl_category_id']??($p['category_id']??0)),null,(array)($bs['fallback_cat_ids']??[]),$bs);
$__sseRemManual=[];
if(!empty($__sseManualCats)){
$catId=(int)$__sseManualCats[0];
$__sseRemManual=array_slice($__sseManualCats,1);
}else{
$catId=0;
if($autoCat&&!empty($bslFlatCats)){$_ac=autoMatchBslCategory($pTitle,$bslFlatCats);if($_ac>0)$catId=$_ac;}
}

$_wStreamMain=bslResolveProductWeights($p,(int)($bs['weight']??500),(int)($bs['package_weight']??0));
$bp=['name'=>mb_substr($pTitle,0,120),'brief'=>mb_substr($bsBrief,0,250),'description'=>$bsDesc,'primary_price'=>$pn,'stock'=>(int)($bs['stock']??10),'preparation_days'=>(int)($bs['preparation_days']??3),'weight'=>(int)$_wStreamMain['weight'],'package_weight'=>(int)$_wStreamMain['package_weight'],'is_wholesale'=>false,'category_id'=>$catId,'photo'=>$pid,'photos'=>(!empty($galC)?$galC:[$pid]),'status'=>2976];
if(!empty($p['sku']))$bp['sku']=$p['sku'];

send_sse('send_info',['msg'=>'['.$n.'] ایجاد: '.mb_substr($pTitle,0,40)]);
$r=bslReq($tk,'POST','vendors/'.$vid.'/products',$bp);

if($r['ok']&&!empty($r['body']['id'])){
bslClearAiCategoryFixPending($vid,(string)$pKey,$pTitle);
$sent++;send_sse('send_ok',['key'=>$pKey,'title'=>$pTitle,'remote_id'=>$r['body']['id'],'edit_url'=>'']);
}else{
$dupName=bslIsDuplicateName($r);
if(!$dupName&&bslIsCategoryError($r)){
$fbSse=!empty($__sseRemManual)?bslTryCreateWithFallback($tk,$vid,$bp,$__sseRemManual,$pTitle,false,[],[]):['ok'=>false,'all_categories_rejected'=>true,'tried'=>$catId>0?[$catId]:[],'last_response'=>$r];
if(!empty($fbSse['ok'])&&!empty($fbSse['body']['id'])){
bslClearAiCategoryFixPending($vid,(string)$pKey,$pTitle);
$sent++;send_sse('send_ok',['key'=>$pKey,'title'=>$pTitle,'remote_id'=>$fbSse['body']['id'],'edit_url'=>'','used_cat_id'=>$fbSse['used_cat_id']]);
usleep($bslDelayMs*1000);continue;
}
if(!empty($fbSse['duplicate_name'])&&is_array($fbSse['last_response']??null)){
$r=$fbSse['last_response'];$dupName=true;
}elseif(!empty($fbSse['all_categories_rejected'])){
$__sseResp=is_array($fbSse['last_response']??null)?$fbSse['last_response']:$r;
$__sseTried=is_array($fbSse['tried']??null)&&!empty($fbSse['tried'])?$fbSse['tried']:($catId>0?[$catId]:[]);
$__sseAiQ=bslQueueForAiCategoryFix($p,['vendor_id'=>$vid,'product_key'=>(string)$pKey,'title'=>$pTitle,'tried_cat_ids'=>$__sseTried,'forced_price_toman'=>(int)round($pn/10),'endpoint'=>'vendors/'.$vid.'/products','error_code'=>(int)($__sseResp['code']??422),'error'=>bslErrText($__sseResp),'error_detail'=>(string)($__sseResp['raw']??json_encode($__sseResp['body']??[],JSON_UNESCAPED_UNICODE)),'step'=>'sse_create']);
$__sseFinal=bslBuildFinalCategoryDeferredError($__sseResp,$vid,$__sseTried,$__sseAiQ,'sse_create');
$fail++;send_sse('send_fail',['key'=>$pKey,'title'=>$pTitle,'error'=>$__sseFinal['error'],'tried_cat_ids'=>$__sseTried,'ai_cat_queued'=>true]);
usleep($bslDelayMs*1000);continue;
}elseif(is_array($fbSse['last_response']??null)){
$r=$fbSse['last_response'];
}
}
if($dupName){

$foundExisting=null;
foreach($bslExisting as $ebn=>$ebp){if(bslNormalizeTitle($ebn)===$nTitle){$foundExisting=$ebp;break;}}
if(!$foundExisting){foreach($bslExistingNorm as $enk=>$enp){if($enk===bslNormalizeTitle($pTitle)){$foundExisting=$enp;break;}}}
if($foundExisting){
$dupId=$foundExisting['id']??'?';
send_sse('send_info',['msg'=>'['.$n.'] نام تکراری → آپدیت ID#'.$dupId]);
$bu=['primary_price'=>$pn,'stock'=>(int)($bs['stock']??10),'status'=>2976,'category_id'=>$catId,'weight'=>(int)($bs['weight']??500),'package_weight'=>(int)($bs['package_weight']??((int)($bs['weight']??500)+100))];
bslApplyContent($bu,$p);
if($pid){$bu['photo']=$pid;$bu['photos']=(!empty($galC)?$galC:[$pid]);}
$r3=bslReq($tk,'PATCH','products/'.$dupId,$bu);
if($r3['code']===404){$r3=bslReq($tk,'PATCH','vendors/'.$vid.'/products/'.$dupId,$bu);}
if($r3['ok']){$updated++;send_sse('send_update',['key'=>$pKey,'title'=>$pTitle,'remote_id'=>$dupId,'old_price'=>0,'new_price'=>$pn,'edit_url'=>'']);}
else{$skipped++;send_sse('send_skip',['key'=>$pKey,'reason'=>'نام تکراری — آپدیت شکست']);}
}else{
/* v8.80: به‌جای رد کردن بی‌صدا، شناسه را پیدا کن و آپدیت بزن */
$buY=['primary_price'=>$pn,'stock'=>(int)($bs['stock']??10),'status'=>2976,'category_id'=>$catId,'weight'=>(int)($bs['weight']??500),'package_weight'=>(int)($bs['package_weight']??((int)($bs['weight']??500)+100))];
if($pid){$buY['photo']=$pid;$buY['photos']=(!empty($galC)?$galC:[$pid]);}
$fuY=bslForceUpdateOnDuplicate($tk,$vid,$pTitle,(string)$pKey,$buY,$p);
if(!empty($fuY['ok'])){$updated++;send_sse('send_update',['key'=>$pKey,'title'=>$pTitle,'remote_id'=>$fuY['id'],'old_price'=>0,'new_price'=>$pn,'edit_url'=>'']);}
else{$fail++;send_sse('send_fail',['key'=>$pKey,'title'=>$pTitle,'error'=>mb_substr((string)$fuY['error'],0,200)]);}
}
}else{
$fail++;
$em=bslErrText($r);
send_sse('send_fail',['key'=>$pKey,'error'=>mb_substr($em,0,240)]);
}
}
usleep($bslDelayMs*1000);
}

send_sse('send_complete',['sent'=>$sent,'updated'=>$updated,'skipped'=>$skipped,'failed'=>$fail,'total'=>$total]);
send_sse('done',[]);exit;
}
// v10.02 (۱۶): اندپوینتِ قدیمیِ ?woo_dedup_stream=1 حذف شد؛ جایگزینِ آن موتورِ dedup_* است (dedup_start/dedup_status/dedup_result).
/* =====================================================================
 *  v10.02 (۱۶): موتورِ حذفِ محصولاتِ تکراری — قابل تنظیم و سمتِ سرور
 *
 *  چرا بازنویسی شد؟
 *   ۱) معیارِ «کدام نسخه بماند» سفت‌وسخت بود: ووکامرس همیشه قدیمی‌ترین را
 *      حذف می‌کرد و باسلام هرچه فعال نبود. کاربر می‌خواهد خودش انتخاب کند
 *      (جدیدتر/قدیمی‌تر، ارزان‌تر/گران‌تر، موجودی بیشتر، وضعیت بهتر).
 *   ۲) الگویِ پسوندی که هنگام تشخیصِ هم‌نامی نادیده گرفته می‌شود ثابت و
 *      فقط «(کد:N)» بود. حالا کاربر می‌تواند «#N»، «(code:N)»، پسوندِ
 *      دلخواه یا حتی چند الگو را با هم فعال کند.
 *   ۳) این کار روی غرفه‌ای با چند هزار محصول چند دقیقه طول می‌کشد. تا امروز
 *      روی یک درخواستِ همزمانِ HTTP اجرا می‌شد و مرورگر/هاست وسطِ راه قطع
 *      می‌کرد ⇒ «خطای شبکه». حالا مثل «گزارش پسوند»، درخواست بی‌درنگ پاسخ
 *      می‌گیرد و کار در پس‌زمینه ادامه پیدا می‌کند؛ پیشرفت از فایل خوانده
 *      می‌شود و بستنِ مرورگر هیچ اثری ندارد.
 * ===================================================================== */

/** پیش‌فرضِ تنظیماتِ حذفِ تکراری (هم برای باسلام هم ووکامرس یکسان) */
function dedupDefaultCfg(): array {
    return [
        'keep'          => 'newest',   // newest|oldest|cheapest|expensive|most_stock|best_status
        'tie'           => 'newest',   // معیارِ دوم وقتی معیارِ اول مساوی شد
        'prefer_active' => true,       // پیش از هر معیار، نسخهٔ فعال/منتشرشده را نگه دار
        'strip_code'    => true,       // (کد:۱۲) و (code:12) و [کد ۱۲]
        'strip_hash'    => true,       // #12 در انتهای عنوان
        'strip_paren'   => false,      // (۱۲) خالی در انتها
        'strip_dash'    => false,      // - ۱۲ در انتهای عنوان
        'strip_custom'  => '',         // الگوی دلخواهِ کاربر (چند خطی)
        'ci'            => true,       // بی‌تفاوت به بزرگی/کوچکیِ حروف
        'norm_digits'   => true,       // ارقامِ فارسی/عربی ⇒ لاتین
        'norm_arabic'   => true,       // ي/ك عربی ⇒ ی/ک فارسی و حذف اعراب
        'min_len'       => 3,          // عنوانِ کوتاه‌تر از این نادیده گرفته شود
        /* v10.39 (۵۳) — هر دو فقط برای باسلام معنا دارند */
        'active_only'   => true,       // فقط محصولاتِ فعال (۲۹۷۶) مقایسه شوند
        'skip_multi'    => true,       // عنوانی که در چند غرفه هست، اصلاً دست نخورد
        'all_vendors'   => true,       // همهٔ غرفه‌ها اسکن شوند، نه فقط پیش‌فرض
        'use_cache'     => true,       // از فهرستِ آمادهٔ باسلام استفاده کن
    ];
}

/** تنظیماتِ ذخیره‌شده را با پیش‌فرض ادغام می‌کند */
function dedupCfg(?array $cn = null): array {
    if ($cn === null) $cn = loadConnections();
    $c = is_array($cn['dedup'] ?? null) ? $cn['dedup'] : [];
    $d = dedupDefaultCfg();
    $out = [];
    foreach ($d as $k => $v) {
        if (!array_key_exists($k, $c)) { $out[$k] = $v; continue; }
        if (is_bool($v))      $out[$k] = !empty($c[$k]) && $c[$k] !== 'false' && $c[$k] !== '0';
        elseif (is_int($v))   $out[$k] = (int)$c[$k];
        else                  $out[$k] = (string)$c[$k];
    }
    $valid = ['newest','oldest','cheapest','expensive','most_stock','best_status'];
    if (!in_array($out['keep'], $valid, true)) $out['keep'] = 'newest';
    if (!in_array($out['tie'],  $valid, true)) $out['tie']  = 'newest';
    $out['min_len'] = max(1, min(60, $out['min_len']));
    return $out;
}

/**
 * الگوهای regex ای که باید از انتهای عنوان برداشته شوند.
 * هر الگو یک regex کاملِ آمادهٔ preg_replace است.
 *
 * الگویِ دلخواهِ کاربر: هر خط یک الگو. اگر خط با / شروع و تمام شود، عیناً
 * به‌عنوان regex استفاده می‌شود؛ وگرنه به‌صورتِ متنِ ساده در نظر گرفته
 * می‌شود و «x» یا «X» یا «*» داخلش به معنیِ «یک عددِ چندرقمی» است. مثلاً
 * کاربر می‌نویسد «(کد:x)» یا «#x» یا «-کد x».
 */
function dedupPatterns(array $cfg): array {
    $D = '[0-9۰-۹٠-٩]';                 // رقمِ لاتین/فارسی/عربی
    $pats = [];
    if (!empty($cfg['strip_code'])) {
        // (کد:۱۲) · [code: 12] · (شناسه ۱۲) · (sku:12) — با یا بدون فاصله و دونقطه
        $pats[] = '/\s*[\(\[]\s*(?:کد|کُد|code|sku|شناسه|شناسه\s*کالا)\s*[:：\-]?\s*' . $D . '+\s*[\)\]]\s*$/iu';
        // بدونِ پرانتز: «... کد:۱۲» در انتها
        $pats[] = '/\s*(?:کد|code|sku|شناسه)\s*[:：]\s*' . $D . '+\s*$/iu';
    }
    if (!empty($cfg['strip_hash'])) {
        $pats[] = '/\s*[#＃]\s*' . $D . '+\s*$/u';
        $pats[] = '/\s*[\(\[]\s*[#＃]\s*' . $D . '+\s*[\)\]]\s*$/u';
    }
    if (!empty($cfg['strip_paren'])) {
        $pats[] = '/\s*[\(\[]\s*' . $D . '+\s*[\)\]]\s*$/u';
    }
    if (!empty($cfg['strip_dash'])) {
        $pats[] = '/\s*[\-–—_]\s*' . $D . '+\s*$/u';
    }
    $custom = trim((string)($cfg['strip_custom'] ?? ''));
    if ($custom !== '') {
        foreach (preg_split('/[\r\n]+/u', $custom) as $line) {
            $line = trim($line);
            if ($line === '') continue;
            if (strlen($line) > 2 && $line[0] === '/' && substr($line, -1) === '/') {
                // regex خام؛ فقط اگر معتبر باشد پذیرفته می‌شود
                $rx = $line . 'u';
                if (@preg_match($rx, '') !== false) $pats[] = $rx;
                continue;
            }
            // متنِ ساده ⇒ escape، سپس x/X/* ⇒ عدد، و فاصله‌ها انعطاف‌پذیر
            $q = preg_quote($line, '/');
            $q = str_replace(['x', 'X', '\*'], $D . '+', $q);
            $q = preg_replace('/(\\\\ )+/u', '\\s*', $q);
            $rx = '/\s*' . $q . '\s*$/iu';
            if (@preg_match($rx, '') !== false) $pats[] = $rx;
        }
    }
    return $pats;
}

/** یک الگوی نمونه را روی یک عنوان آزمایش می‌کند (برای پیش‌نمایشِ زندهٔ UI) */
function dedupNormalize(string $title, array $cfg, ?array $pats = null): string {
    if ($pats === null) $pats = dedupPatterns($cfg);
    $t = trim($title);
    if (!empty($cfg['norm_arabic'])) {
        $t = strtr($t, ['ي' => 'ی', 'ك' => 'ک', 'ٱ' => 'ا', 'أ' => 'ا', 'إ' => 'ا',
                        'ة' => 'ه', 'ۀ' => 'ه', 'ؤ' => 'و', 'ئ' => 'ی',
                        "\u{200c}" => ' ', "\u{200f}" => '', "\u{200e}" => '',
                        'ً' => '', 'ٌ' => '', 'ٍ' => '', 'َ' => '', 'ُ' => '',
                        'ِ' => '', 'ّ' => '', 'ْ' => '', 'ٰ' => '']);
    }
    if (!empty($cfg['norm_digits'])) {
        $t = strtr($t, ['۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5',
                        '۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9',
                        '٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5',
                        '٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9']);
    }
    if (!empty($cfg['ci']) && function_exists('mb_strtolower')) $t = mb_strtolower($t, 'UTF-8');
    $t = preg_replace('/\s+/u', ' ', $t);
    // الگوها ممکن است تودرتو باشند («… (کد:۳) #۷») ⇒ تا وقتی چیزی کم می‌شود تکرار کن
    for ($round = 0; $round < 4; $round++) {
        $before = $t;
        foreach ($pats as $rx) $t = (string)preg_replace($rx, ' ', $t);
        $t = trim(preg_replace('/\s{2,}/u', ' ', $t));
        if ($t === $before) break;
    }
    return trim($t);
}

/** برچسبِ فارسیِ معیارِ نگه‌داری */
function dedupKeepLabel(string $k): string {
    $m = ['newest' => 'جدیدترین', 'oldest' => 'قدیمی‌ترین', 'cheapest' => 'ارزان‌ترین',
          'expensive' => 'گران‌ترین', 'most_stock' => 'بیشترین موجودی',
          'best_status' => 'بهترین وضعیت'];
    return $m[$k] ?? $k;
}

/**
 * رتبهٔ وضعیت — هرچه بزرگ‌تر، «بهتر». برای هر دو مقصد یکدست است تا
 * منطقِ مرتب‌سازی مشترک بماند.
 *   باسلام: 2976 فعال · 3568 در انتظار · 3567 تأییدنشده · 3790 غیرفعال · 4184 بایگانی
 *   ووکامرس: publish · pending · draft · private · trash
 */
function dedupStatusRank(array $p): int {
    $bs = (int)($p['status'] ?? 0);
    if ($bs > 0) {
        $r = [2976 => 100, 3568 => 70, 3567 => 40, 3790 => 25, 4184 => 5];
        return $r[$bs] ?? 10;
    }
    $w = (string)($p['wstatus'] ?? '');
    $r = ['publish' => 100, 'pending' => 70, 'draft' => 40, 'private' => 25, 'trash' => 5];
    return $r[$w] ?? 10;
}

/** آیا این نسخه «فعال/منتشرشده» است؟ */
function dedupIsActive(array $p): bool {
    if ((int)($p['status'] ?? 0) > 0) return (int)$p['status'] === 2976;
    return (string)($p['wstatus'] ?? '') === 'publish';
}

/**
 * مقایسهٔ دو نسخه بر اساس یک معیار.
 * خروجی منفی ⇒ $a «بهتر» است (باید بماند).
 */
function dedupCmpBy(array $a, array $b, string $crit): int {
    switch ($crit) {
        case 'oldest':
            return dedupTs($a) <=> dedupTs($b);
        case 'newest':
            return dedupTs($b) <=> dedupTs($a);
        case 'cheapest':
            $pa = dedupPrice($a); $pb = dedupPrice($b);
            if ($pa <= 0 && $pb > 0) return 1;      // قیمتِ نامعلوم بازنده است
            if ($pb <= 0 && $pa > 0) return -1;
            return $pa <=> $pb;
        case 'expensive':
            return dedupPrice($b) <=> dedupPrice($a);
        case 'most_stock':
            return (int)($b['stock'] ?? 0) <=> (int)($a['stock'] ?? 0);
        case 'best_status':
            return dedupStatusRank($b) <=> dedupStatusRank($a);
    }
    return 0;
}

/** زمانِ ساختِ محصول به‌صورت عدد (۰ = نامعلوم ⇒ بازنده در «جدیدترین») */
function dedupTs(array $p): int {
    if (isset($p['ts']) && (int)$p['ts'] > 0) return (int)$p['ts'];
    $d = trim((string)($p['date_created'] ?? ''));
    if ($d !== '') { $t = strtotime($d); if ($t !== false) return $t; }
    // باسلام تاریخ نمی‌دهد؛ شناسهٔ بزرگ‌تر یعنی محصولِ تازه‌تر
    return (int)($p['id'] ?? 0);
}

/** قیمت به عدد (۰ = نامعلوم) */
function dedupPrice(array $p): int {
    $v = $p['price'] ?? 0;
    if (is_string($v)) { $v = preg_replace('/[^0-9.]/', '', $v); }
    return (int)round((float)$v);
}

/**
 * از یک گروهِ هم‌نام، تصمیم می‌گیرد کدام بماند و کدام‌ها بروند.
 * ترتیبِ تصمیم:
 *   ۱) اگر «ترجیحِ فعال» روشن است و دستِ‌کم یکی فعال است ⇒ فقط بینِ فعال‌ها رقابت
 *   ۲) معیارِ اصلی · ۳) معیارِ دوم (tie) · ۴) شناسهٔ کوچک‌تر (پایداریِ نتیجه)
 */
function dedupPickKeeper(array $items, array $cfg): array {
    $pool = $items;
    if (!empty($cfg['prefer_active'])) {
        $act = array_values(array_filter($items, 'dedupIsActive'));
        if ($act) $pool = $act;
    }
    $keep = $cfg['keep']; $tie = $cfg['tie'];
    usort($pool, function ($a, $b) use ($keep, $tie) {
        $c = dedupCmpBy($a, $b, $keep);
        if ($c !== 0) return $c;
        if ($tie !== $keep) { $c = dedupCmpBy($a, $b, $tie); if ($c !== 0) return $c; }
        return (int)($a['id'] ?? 0) <=> (int)($b['id'] ?? 0);
    });
    $keeper = $pool[0] ?? $items[0];
    $kid = (int)($keeper['id'] ?? 0);
    $drop = [];
    foreach ($items as $it) if ((int)($it['id'] ?? 0) !== $kid) $drop[] = $it;
    return ['keep' => $keeper, 'drop' => $drop];
}

/**
 * گروه‌بندیِ محصولات بر اساس عنوانِ نرمال‌شده.
 *
 * v10.39 (۵۳): اگر ردیف‌ها از چند غرفه آمده باشند (vendor_id دارند)، شناسهٔ
 * غرفه هم واردِ کلید می‌شود. یعنی دو محصولِ هم‌نام در دو غرفهٔ متفاوت هرگز
 * یک گروه نمی‌شوند و «تکراری» شمرده نمی‌شوند — دقیقاً همان چیزی که کاربر
 * خواست: حذف فقط *داخلِ* هر غرفه. جداکنندهٔ \x00 است تا با هیچ عنوانِ
 * واقعی‌ای اشتباه نشود.
 */
function dedupGroup(array $rows, array $cfg): array {
    $pats = dedupPatterns($cfg);
    $g = [];
    foreach ($rows as $r) {
        $name = (string)($r['name'] ?? ($r['title'] ?? ''));
        $n = dedupNormalize($name, $cfg, $pats);
        if ($n === '' || mb_strlen($n, 'UTF-8') < (int)$cfg['min_len']) continue;
        $vid = (int)($r['vendor_id'] ?? 0);
        $g[$vid > 0 ? $n . "\x00" . $vid : $n][] = $r;
    }
    return $g;
}

/** عنوانِ نمایشیِ گروه — پسوندِ غرفه از کلید برداشته می‌شود */
function dedupGroupNorm(string $key): string {
    $p = strpos($key, "\x00");
    return $p === false ? $key : substr($key, 0, $p);
}

/* --------------------- پیشرفتِ کارِ پس‌زمینه --------------------- */

function dedupProgress(array $patch): void {
    $cur = [];
    if (is_file(DEDUP_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(DEDUP_PROGRESS_FILE), true);
        if (is_array($d)) $cur = $d;
    }
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) $log[] = ['t' => time(), 'm' => (string)$l];
        if (count($log) > 400) $log = array_slice($log, -400);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log; $cur['ts'] = time();
    writeProgress(DEDUP_PROGRESS_FILE, $cur);
}

function dedupStopRequested(): bool { return is_file(DEDUP_STOP_FILE); }
function dedupClearStop(): void { @unlink(DEDUP_STOP_FILE); }

/* --------------------- گرفتنِ محصولات از مقصد --------------------- */

/* =====================================================================
 *  v10.18 (۳۱ج): تلاشِ مجددِ صفحه در برداشتِ «حذفِ تکراری»
 *
 *  گزارشِ کاربر: لاگ با «صفحهٔ 1/400: 100 محصول» شروع می‌شد و بلافاصله
 *  «⚠️ صفحهٔ 2 ناموفق (HTTP 500)» می‌آمد و کلِ عملیات با ۱۰۰ محصول از
 *  ۴۰۰ صفحه تمام می‌شد. علت: هر دو تابعِ برداشت در اولین خطای HTTP بی‌درنگ
 *  break می‌کردند — یک خطای گذرای ۵۰۰/۵۰۲/۴۲۹ که چند ثانیه بعد رفع می‌شود
 *  کلِ کار را می‌بست. (bslReq فقط خطای *شبکه* را دوباره می‌زند؛ وقتی سرور
 *  کدِ HTTP برگرداند آن را «پاسخِ گرفته‌شده» می‌داند و تکرار نمی‌کند.)
 *
 *  حالا هر صفحه تا DEDUP_PAGE_TRIES بار با مکثِ فزاینده تکرار می‌شود و
 *  فقط اگر همهٔ تلاش‌ها شکست خورد کار متوقف می‌شود.
 *
 *  $fetch: تابعی که یک بار درخواست را می‌زند و آرایهٔ پاسخ برمی‌گرداند.
 *  خروجی: همان پاسخ (موفق یا آخرین شکست) + کلیدِ tries.
 * ===================================================================== */
function dedupFetchPage(callable $fetch, int $page, string $who): array {
    $tries = max(1, (int)DEDUP_PAGE_TRIES);
    $r = ['ok' => false, 'code' => 0];
    for ($try = 1; $try <= $tries; $try++) {
        if ($try > 1 && dedupStopRequested()) break;
        $r = (array)$fetch();
        if (!empty($r['ok'])) {
            /* موفقیت بعد از شکست را صریح بگو تا کاربر بداند چه شد */
            if ($try > 1) dedupProgress(['log_add' => ['✅ ' . $who . ' صفحهٔ ' . $page
                . ' در تلاشِ ' . $try . 'ام موفق شد']]);
            $r['tries'] = $try;
            return $r;
        }
        if ($try < $tries) {
            /* مکثِ فزاینده: ۲، ۴، ۸ … ثانیه (سقفِ DEDUP_PAGE_WAIT_MAX) */
            $wait = min((int)DEDUP_PAGE_WAIT_MAX, (int)(DEDUP_PAGE_WAIT_BASE * pow(2, $try - 1)));
            dedupProgress(['log_add' => ['↻ ' . $who . ' صفحهٔ ' . $page . ' ناموفق (HTTP '
                . ($r['code'] ?? '?') . ') — تلاشِ ' . ($try + 1) . ' از ' . $tries
                . ' بعد از ' . $wait . ' ثانیه']]);
            sleep($wait);
        }
    }
    $r['tries'] = $tries;
    return $r;
}

/** همهٔ محصولاتِ باسلام برای حذفِ تکراری (با قیمت/موجودی/وضعیت)
 *
 *  v10.23 (۳۶ب): $partial با ارجاع پر می‌شود. قبلاً وقتی برداشت وسطِ کار
 *  می‌شکست (یا کاربر توقف می‌زد) تابع همان چیزی را که تا آن لحظه گرفته بود
 *  برمی‌گرداند و کسی نمی‌فهمید فهرست ناقص است — بعد گروه‌بندی روی نصفِ
 *  محصولات انجام می‌شد و «تکراری‌ها» ناقص گزارش می‌شدند. حالا این پرچم تا
 *  گزارشِ نهایی و رابط بالا می‌آید و در حالتِ حذف، از حذف جلوگیری می‌کند. */
function dedupCursorLoad(string $target, int $vid = 0): array {
    $f = DEDUP_FETCH_CURSOR_FILE;
    if (!is_file($f)) return ['rows' => [], 'page' => 0];
    $rows = []; $page = 0;
    foreach ((array)@file($f, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) as $line) {
        $d = json_decode($line, true);
        if (!is_array($d) || (string)($d['target'] ?? '') !== $target
            || (int)($d['vid'] ?? 0) !== $vid) continue;
        foreach ((array)($d['rows'] ?? []) as $r) if (is_array($r)) $rows[] = $r;
        $page = max($page, (int)($d['page'] ?? 0));
    }
    return ['rows' => $rows, 'page' => $page];
}

function dedupCursorAppend(string $target, int $vid, int $page, array $rows): void {
    if (!$rows) return;
    @file_put_contents(DEDUP_FETCH_CURSOR_FILE,
        json_encode(['target' => $target, 'vid' => $vid, 'page' => $page, 'rows' => $rows], JSON_UNESCAPED_UNICODE) . "\n",
        FILE_APPEND | LOCK_EX);
}

/** همهٔ محصولاتِ باسلام برای حذفِ تکراری (با قیمت/موجودی/وضعیت)
 *
 *  v10.23 (۳۶ب): $partial با ارجاع پر می‌شود. قبلاً وقتی برداشت وسطِ کار
 *  می‌شکست (یا کاربر توقف می‌زد) تابع همان چیزی را که تا آن لحظه گرفته بود
 *  برمی‌گرداند و کسی نمی‌فهمید فهرست ناقص است — بعد گروه‌بندی روی نصفِ
 *  محصولات انجام می‌شد و «تکراری‌ها» ناقص گزارش می‌شدند. حالا این پرچم تا
 *  گزارشِ نهایی و رابط بالا می‌آید و در حالتِ حذف، از حذف جلوگیری می‌کند. */
function dedupFetchBsl(string $tk, int $vid, int $maxPages = DEDUP_MAX_PAGES, ?array &$partial = null): array {
    $cursor = dedupCursorLoad('bsl', $vid);
    $rows = array_values(array_filter((array)($cursor['rows'] ?? []), 'is_array'));
    $firstPage = max(1, (int)($cursor['page'] ?? 0) + 1);
    $statuses = '&statuses=2976&statuses=3790&statuses=3567&statuses=3568&statuses=4184';
    for ($page = $firstPage; $page < $firstPage + $maxPages; $page++) {
        if (dedupStopRequested()) {
            dedupProgress(['log_add' => ['⏹ توقف در صفحهٔ ' . $page]]);
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'stopped', 'page' => $page];
            break;
        }
        /* v10.18 (۳۱ج): به‌جای توقفِ فوری، همین صفحه چند بار با مکثِ فزاینده
           دوباره خواسته می‌شود؛ خطای گذرای ۵۰۰ دیگر کلِ برداشت را نمی‌بندد. */
        $r = dedupFetchPage(function () use ($tk, $vid, $page, $statuses) {
            return bslReq($tk, 'GET', 'vendors/' . $vid . '/products?page=' . $page . '&per_page=100' . $statuses);
        }, $page, 'باسلام');
        if (empty($r['ok'])) {
            dedupProgress(['log_add' => ['⚠️ صفحهٔ ' . $page . ' بعد از ' . (int)($r['tries'] ?? 1)
                . ' تلاش ناموفق ماند (HTTP ' . ($r['code'] ?? '?') . ') — برداشت با '
                . count($rows) . ' محصول متوقف شد']]);
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'http',
                'page' => $page, 'code' => (int)($r['code'] ?? 0), 'tries' => (int)($r['tries'] ?? 1)];
            break;
        }
        /* v10.40 (۵۴الف): همان اصلاحِ bslCatalogBuild — ردیف‌ها با bslRowsOf
           (شکل‌های data/products/items) و total_page با bslMetaInt (زیرِ
           meta/pagination هم می‌گردد). با پیش‌فرضِ ۱، برداشت در پایانِ
           صفحهٔ یک می‌شکست بدونِ اینکه ناقص علامت بخورد. */
        $batch = bslRowsOf($r['body']);
        if (!$batch) break;
        $tp = bslMetaInt($r['body'], 'total_page', 0);
        $pageRows = [];
        foreach ($batch as $p) {
            if (!is_array($p)) continue;
            $rev  = $p['revision']['data'] ?? [];
            $name = trim((string)($p['title'] ?? ($p['name'] ?? ($rev['title'] ?? ''))));
            if ($name === '') continue;
            $st = $p['status'] ?? null;
            $pageRows[] = [
                'id'     => (int)($p['id'] ?? 0),
                'name'   => $name,
                'status' => (int)(is_array($st) ? ($st['value'] ?? 0) : $st),
                'price'  => (int)($rev['primary_price'] ?? ($p['price'] ?? 0)),
                'stock'  => (int)($rev['stock'] ?? ($p['stock'] ?? 0)),
                'ts'     => (int)($p['id'] ?? 0),
            ];
        }
        $rows = array_merge($rows, $pageRows);
        dedupCursorAppend('bsl', $vid, $page, $pageRows);
        dedupProgress(['fetched' => count($rows), 'page' => $page, 'pages' => $tp,
            'log_add' => ['📄 باسلام صفحهٔ ' . $page . '/' . ($tp > 0 ? $tp : '?') . ': ' . count($batch)
                . ' محصول (مجموع ' . count($rows) . ')']]);
        /* صفحهٔ ناقص قطعی‌ترین نشانهٔ پایان است؛ total_page فقط وقتی
           معتبر است که واقعاً آمده باشد. */
        if (count($batch) < 100) break;
        if ($tp > 0 && $page >= $tp) break;
        /* v10.23 (۳۶ب): رسیدن به سقفِ صفحات هم «برداشتِ ناقص» است */
        if ($page >= $firstPage + $maxPages - 1) {
            dedupProgress(['log_add' => ['⚠️ سقفِ ' . $maxPages . ' صفحه پر شد ولی فروشگاه '
                . ($tp > 0 ? $tp : 'بیش از این') . ' صفحه دارد — فهرست ناقص است']]);
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'max_pages',
                'page' => $page, 'pages' => $tp];
        }
        usleep(150000);
    }
    if ($page >= $firstPage + $maxPages && $partial !== null && empty($partial)) {
        $partial = ['partial' => true, 'reason' => 'max_pages', 'page' => $page - 1];
        dedupProgress(['log_add' => ['⚠️ سقفِ برداشتِ باسلام رسید — checkpoint صفحهٔ ' . ($page - 1) . ' حفظ شد']]);
    }
    return $rows;
}

/* =====================================================================
 *  v10.39 (۵۳): برداشتِ چندغرفه‌ایِ باسلام برای حذفِ تکراری
 *
 *  سه تغییرِ خواستهٔ کاربر، همه اینجا جمع‌اند:
 *
 *  ۱) «فقط در محصولات فعال جستجو کند» — تا ۱۰.۳۸ پنج وضعیت پرس‌وجو
 *     می‌شد (فعال، غیرفعال، تأییدنشده، در انتظار، بایگانی) و بعد همه با هم
 *     مقایسه می‌شدند. یعنی یک محصولِ فعال می‌توانست به بهانهٔ هم‌نامیِ یک
 *     نسخهٔ بایگانی حذف شود. حالا فیلترِ 2976 پیش از گروه‌بندی اعمال
 *     می‌شود.
 *
 *  ۲) «اگر محصول در دو یا چند غرفه باشد نادیده گرفته شود» — عنوانی که در
 *     بیش از یک غرفه دیده شود کلاً از گروه‌بندی کنار می‌رود. این عمداً
 *     محافظه‌کارانه است: چنین عنوانی معمولاً همان محصول است که به چند غرفه
 *     ارسال شده، نه یک تکراریِ اشتباهی. تکراریِ *داخلِ* یک غرفه همچنان
 *     حذف می‌شود (انتخابِ صریحِ کاربر).
 *
 *  ۳) «فهرستِ آماده» — به‌جای برداشتِ زنده از سرورِ باسلام، از کشِ
 *     کاتالوگ خوانده می‌شود که هر چند ساعت یک‌بار ساخته می‌شود.
 * ===================================================================== */
function dedupFetchBslAll(array $cn, array $cfg, ?array &$partial = null): array {
    $shops = bslAllShops($cn);
    if (empty($cfg['all_vendors'])) {
        /* فقط غرفهٔ پیش‌فرض — رفتارِ نسخه‌های قبل */
        $shops = array_values(array_filter($shops, function ($s) { return !empty($s['is_default']); }));
        if (!$shops) $shops = array_slice(bslAllShops($cn), 0, 1);
    }
    if (!$shops) return [];

    $useCache = !empty($cfg['use_cache']);
    $rows = []; $byTitleVendors = []; $anyPartial = false; $reason = '';
    /* الگوها یک‌بار ساخته می‌شوند؛ dedupNormalize بدونِ این آرگومان هر بار
       برای *هر ردیف* دوباره regexها را می‌سازد و روی چند هزار محصول
       به‌شدت کند می‌شود. */
    $pats = dedupPatterns($cfg);

    foreach ($shops as $sh) {
        if (dedupStopRequested()) {
            $anyPartial = true; $reason = 'stopped'; break;
        }
        $vid = (int)($sh['vendor_id'] ?? 0);
        $tk  = (string)($sh['token'] ?? '');
        if ($vid <= 0 || $tk === '') continue;
        $nm = (string)($sh['shop_name'] ?? ('غرفهٔ ' . $vid));

        if ($useCache) {
            $got  = bslCatalogRows($tk, $vid, true);
            $vr   = $got['rows'];
            if (!empty($got['partial'])) { $anyPartial = true; if ($reason === '') $reason = 'cache_partial'; }
            $age  = $got['at'] > 0 ? max(0, time() - (int)$got['at']) : 0;
            dedupProgress(['log_add' => ['🗂 ' . $nm . ': ' . count($vr) . ' محصول از '
                . ($got['from'] === 'network' ? 'فهرستِ تازه‌ساخته' : 'فهرستِ آماده')
                . ($got['from'] === 'cache' ? ' (' . dedupAgeFa($age) . ' پیش)' : '')]]);
        } else {
            $vp = [];
            $vr = dedupFetchBsl($tk, $vid, DEDUP_MAX_PAGES, $vp);
            if (!empty($vp['partial'])) {
                $anyPartial = true;
                if ($reason === '') $reason = (string)($vp['reason'] ?? 'http');
            }
        }

        foreach ($vr as $r) {
            if (!is_array($r)) continue;
            /* فیلترِ «فقط فعال» — پیش از هر مقایسه‌ای */
            if (!empty($cfg['active_only']) && (int)($r['status'] ?? 0) !== 2976) continue;
            $r['vendor_id']   = $vid;
            $r['vendor_name'] = $nm;
            $rows[] = $r;
            $n = dedupNormalize((string)($r['name'] ?? ''), $cfg, $pats);
            if ($n !== '') $byTitleVendors[$n][$vid] = true;
        }
    }

    /* گامِ «نادیده‌گرفتنِ محصولاتِ چندغرفه‌ای» */
    $skipped = 0; $skipTitles = 0;
    if (!empty($cfg['skip_multi'])) {
        $keep = [];
        foreach ($rows as $r) {
            $n = dedupNormalize((string)($r['name'] ?? ''), $cfg, $pats);
            if ($n !== '' && count($byTitleVendors[$n] ?? []) > 1) { $skipped++; continue; }
            $keep[] = $r;
        }
        foreach ($byTitleVendors as $vs) if (count($vs) > 1) $skipTitles++;
        $rows = $keep;
    }

    dedupProgress(['multi_skipped' => $skipped, 'multi_titles' => $skipTitles,
        'vendors' => count($shops), 'fetched' => count($rows),
        'log_add' => ['✅ مجموعاً ' . count($rows) . ' محصول'
            . (!empty($cfg['active_only']) ? ' (فقط فعال)' : '')
            . ' از ' . count($shops) . ' غرفه'
            . ($skipped > 0 ? ' — ' . $skipTitles . ' عنوان که در چند غرفه بود ('
                . $skipped . ' محصول) نادیده گرفته شد' : '')]]);

    if ($anyPartial && $partial !== null) $partial = ['partial' => true, 'reason' => $reason ?: 'http'];
    return $rows;
}

/** سنِ خوانا برای گزارشِ فهرستِ آماده */
function dedupAgeFa(int $sec): string {
    if ($sec < 60)   return 'کمتر از یک دقیقه';
    if ($sec < 3600) return (int)round($sec / 60) . ' دقیقه';
    return round($sec / 3600, 1) . ' ساعت';
}

/** همهٔ محصولاتِ ووکامرس برای حذفِ تکراری (v10.23 (۳۶ب): با پرچمِ ناقص‌بودن) */
function dedupFetchWoo(array $w, int $maxPages = DEDUP_MAX_PAGES, ?array &$partial = null): array {
    $cursor = dedupCursorLoad('woo', 0);
    $rows = array_values(array_filter((array)($cursor['rows'] ?? []), 'is_array'));
    $firstPage = max(1, (int)($cursor['page'] ?? 0) + 1);
    for ($page = $firstPage; $page < $firstPage + $maxPages; $page++) {
        if (dedupStopRequested()) {
            dedupProgress(['log_add' => ['⏹ توقف در صفحهٔ ' . $page]]);
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'stopped', 'page' => $page];
            break;
        }
        /* v10.18 (۳۱ج): همان تلاشِ مجددِ باسلام برای ووکامرس */
        $r = dedupFetchPage(function () use ($w, $page) {
            $rr = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'], 'GET',
                'products?per_page=100&status=any&orderby=id&order=asc&page=' . $page);
            if (!is_array($rr['body'] ?? null)) $rr['ok'] = false;
            return $rr;
        }, $page, 'ووکامرس');
        if (empty($r['ok']) || !is_array($r['body'])) {
            dedupProgress(['log_add' => ['⚠️ صفحهٔ ' . $page . ' بعد از ' . (int)($r['tries'] ?? 1)
                . ' تلاش ناموفق ماند (HTTP ' . ($r['code'] ?? '?') . ') — برداشت با '
                . count($rows) . ' محصول متوقف شد']]);
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'http',
                'page' => $page, 'code' => (int)($r['code'] ?? 0), 'tries' => (int)($r['tries'] ?? 1)];
            break;
        }
        $batch = $r['body'];
        if (!$batch) break;
        $pageRows = [];
        foreach ($batch as $p) {
            if (!is_array($p)) continue;
            $name = trim((string)($p['name'] ?? ''));
            if ($name === '') continue;
            $pr = $p['regular_price'] ?? '';
            if ($pr === '' || $pr === null) $pr = $p['price'] ?? '';
            $pageRows[] = [
                'id'      => (int)($p['id'] ?? 0),
                'name'    => $name,
                'wstatus' => (string)($p['status'] ?? ''),
                'price'   => $pr,
                'stock'   => (int)($p['stock_quantity'] ?? 0),
                'date_created' => (string)($p['date_created'] ?? ''),
                'sku'     => (string)($p['sku'] ?? ''),
            ];
        }
        $rows = array_merge($rows, $pageRows);
        dedupCursorAppend('woo', 0, $page, $pageRows);
        dedupProgress(['fetched' => count($rows), 'page' => $page,
            'log_add' => ['📄 ووکامرس صفحهٔ ' . $page . ': ' . count($batch)
                . ' محصول (مجموع ' . count($rows) . ')']]);
        if (count($batch) < 100) break;
        if ($page >= $firstPage + $maxPages - 1) {
            dedupProgress(['log_add' => ['⚠️ سقفِ ' . $maxPages . ' صفحه پر شد و صفحهٔ پُر هم آمد — فهرست ناقص است']]);
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'max_pages', 'page' => $page];
        }
        usleep(150000);
    }
    if ($page >= $firstPage + $maxPages && $partial !== null && empty($partial)) {
        $partial = ['partial' => true, 'reason' => 'max_pages', 'page' => $page - 1];
        dedupProgress(['log_add' => ['⚠️ سقفِ برداشتِ ووکامرس رسید — checkpoint صفحهٔ ' . ($page - 1) . ' حفظ شد']]);
    }
    return $rows;
}

/**
 * کارِ کاملِ حذفِ تکراری — این تابع می‌تواند چند دقیقه طول بکشد و فقط از
 * مسیرِ پس‌زمینه صدا زده می‌شود.
 *
 * $mode: 'scan' فقط گزارش · 'delete' واقعاً حذف/بایگانی کن
 */
function dedupRun(array $cn, string $target, array $cfg, string $mode, ?array $cp = null): array {
    $t0 = microtime(true);
    dedupProgress(['phase' => 'fetch', 'log_add' => ['🔍 دریافتِ فهرستِ محصولات...']]);

    /* v10.23 (۳۶ب): پرچمِ «برداشتِ ناقص» — با ارجاع پر می‌شود */
    $partial = [];
    if ($target === 'bsl') {
        $bs = $cn['basalam'] ?? [];
        if (empty($bs['token']) || empty($bs['vendor_id'])) return ['ok' => false, 'error' => 'تنظیمات باسلام ناقص است'];
        /* v10.39 (۵۳): چندغرفه‌ای + فقط فعال + از فهرستِ آماده */
        $rows = dedupFetchBslAll($cn, $cfg, $partial);
    } else {
        $w = $cn['woocommerce'] ?? [];
        if (empty($w['store_url'])) return ['ok' => false, 'error' => 'تنظیمات ووکامرس ناقص است'];
        $rows = dedupFetchWoo($w, DEDUP_MAX_PAGES, $partial);
    }
    $cpStartedAt = (is_array($cp) ? (int)($cp['started_at'] ?? 0) : 0);
    if (!$rows) {
        if (!empty($partial['partial'])) {
            $fetchCp = ['phase' => 'fetch', 'target' => $target, 'mode' => $mode,
                'done_ids' => (array)($cp['done_ids'] ?? []), 'deleted' => (int)($cp['deleted'] ?? 0),
                'failed' => (int)($cp['failed'] ?? 0), 'started_at' => $cpStartedAt > 0 ? $cpStartedAt : time()];
            dedupProgress(['running' => false, 'done' => true, 'partial' => true, 'stale' => true,
                'checkpoint' => $fetchCp, 'log_add' => ['⚠️ برداشت هنوز محصولی برنگردانده؛ checkpoint حفظ شد']]);
            return ['ok' => false, 'partial' => true, 'error' => 'برداشت محصول ناقص ماند؛ در اجرای بعدی ادامه می‌یابد'];
        }
        return ['ok' => false, 'error' => 'هیچ محصولی دریافت نشد'];
    }

    /* v10.23 (۳۶ب): اگر فهرست ناقص باشد، حذف بسیار خطرناک است — «تنها نسخهٔ
       باقی‌مانده» ممکن است در صفحه‌ای باشد که اصلاً دریافت نشده و آن‌وقت
       نسخه‌ای که اینجا «تکراری» دیده می‌شود در واقع تنها نسخهٔ موجود است.
       پس در حالتِ حذف فقط گزارش می‌دهیم و صریح می‌گوییم چرا. */
    $partialReason = [
        'stopped'   => 'کاربر وسطِ برداشت توقف زد',
        'http'      => 'یک صفحه بعد از چند تلاش هم نیامد',
        'max_pages' => 'سقفِ صفحاتِ برداشت پر شد',
    ];
    $isPartial = !empty($partial['partial']);
    if ($isPartial) {
        dedupProgress(['partial' => true,
            'partial_reason' => (string)($partial['reason'] ?? ''),
            'log_add' => ['⚠️ فهرست ناقص است ('
                . ($partialReason[(string)($partial['reason'] ?? '')] ?? 'نامعلوم')
                . ') — فقط ' . count($rows) . ' محصول دریافت شد'
                . ($mode === 'delete' ? '؛ برای ایمنی حذف انجام نمی‌شود' : '')]]);
        if ($mode === 'delete') $mode = 'scan';
        $fetchCp = ['phase' => 'fetch', 'target' => $target, 'mode' => $mode,
            'done_ids' => (array)($cp['done_ids'] ?? []), 'deleted' => (int)($cp['deleted'] ?? 0),
            'failed' => (int)($cp['failed'] ?? 0), 'started_at' => $cpStartedAt > 0 ? $cpStartedAt : time(),
            'fetch_page' => (int)($partial['page'] ?? 0), 'fetch_reason' => (string)($partial['reason'] ?? '')];
        dedupProgress(['checkpoint' => $fetchCp]);
    }

    /* v10.126: ادامهٔ واقعی — شناسه‌هایی که در اجرای قبلی حذف/بایگانی شده‌اند
       (done_ids) از فهرست کنار می‌روند تا دوباره پردازش نشوند. باسلام بایگانی
       را حذف نمی‌کند و همین شناسه‌ها در واکشیِ بعدی هم برمی‌گردند. */
    $cpDoneIds = [];
    if (is_array($cp)) {
        $cpDoneIds = array_values(array_filter(array_map('intval', (array)($cp['done_ids'] ?? [])), function ($x) { return $x > 0; }));
        if ($cpDoneIds) {
            $doneSet = array_fill_keys($cpDoneIds, true);
            $before = count($rows);
            $rows = array_values(array_filter($rows, function ($r) use ($doneSet) {
                return !isset($doneSet[(int)($r['id'] ?? 0)]);
            }));
            if (count($rows) !== $before) {
                dedupProgress(['log_add' => ['↻ ' . ($before - count($rows))
                    . ' موردِ ازقبل‌پردازش‌شده از چک‌پوینت رد شد']]);
            }
        }
    }

    dedupProgress(['phase' => 'group', 'total' => count($rows),
        'log_add' => ['🧮 ' . count($rows) . ' محصول دریافت شد؛ گروه‌بندی بر اساس عنوان...']]);

    $groups = dedupGroup($rows, $cfg);
    $dupGroups = []; $dupCount = 0;
    foreach ($groups as $norm => $items) {
        if (count($items) < 2) continue;
        $pick = dedupPickKeeper($items, $cfg);
        $dupCount += count($pick['drop']);
        $dupGroups[] = ['norm' => dedupGroupNorm((string)$norm), 'count' => count($items),
                        'vendor_id'   => (int)($items[0]['vendor_id'] ?? 0),
                        'vendor_name' => (string)($items[0]['vendor_name'] ?? ''),
                        'keep' => $pick['keep'], 'drop' => $pick['drop']];
    }
    usort($dupGroups, function ($a, $b) { return $b['count'] <=> $a['count']; });

    dedupProgress(['phase' => $mode === 'delete' ? 'delete' : 'done',
        'groups' => count($dupGroups), 'dups' => $dupCount,
        'log_add' => ['🔎 ' . count($dupGroups) . ' گروهِ هم‌نام با مجموعاً ' . $dupCount
            . ' نسخهٔ اضافی — معیارِ نگه‌داری: ' . dedupKeepLabel($cfg['keep'])]]);

    /* v10.126: شمارنده‌ها از چک‌پوینت شروع می‌شوند تا جمعِ کل (نه فقط این
       اجرا) دیده شود و امضای پیشرفتِ v10.125 هم یکنوا بالا برود. */
    $deleted = (int)($cp['deleted'] ?? 0);
    $failed  = (int)($cp['failed'] ?? 0);
    $errors  = [];
    $stopDuringDelete = false;
    if ($mode === 'delete' && $dupCount > 0) {
        $done = (int)($cp['done'] ?? 0);
        foreach ($dupGroups as $gi => $g) {
            if (dedupStopRequested()) { $stopDuringDelete = true; dedupProgress(['log_add' => ['⏹ حذف با درخواستِ کاربر متوقف شد']]); break; }
            foreach ($g['drop'] as $d) {
                if (dedupStopRequested()) { $stopDuringDelete = true; break; }
                $did = (int)($d['id'] ?? 0);
                if ($did <= 0) continue;
                /* v10.23 (۳۶ب): خودِ حذف/بایگانی هم تلاشِ مجدد دارد. تا اینجا
                   فقط *برداشتِ* صفحات retry داشت؛ خودِ عملیات یک‌باره بود و
                   یک ۵۰۰/۴۲۹ گذرا محصول را برای همیشه در ستونِ «ناموفق»
                   می‌نشاند. مکث فزاینده است تا ریت‌لیمیت هم فرصت بازیابی بگیرد. */
                $ok = false; $em = ''; $dTries = 0;
                for ($dt = 1; $dt <= (int)DEDUP_DEL_TRIES; $dt++) {
                    $dTries = $dt;
                    if ($dt > 1 && dedupStopRequested()) break;
                    if ($target === 'bsl') {
                        /* v10.39 (۵۳): با اسکنِ چندغرفه‌ای، محصول لزوماً مالِ
                           غرفهٔ پیش‌فرض نیست. توکن/شناسهٔ خودِ همان غرفه باید
                           استفاده شود وگرنه باسلام ۴۰۳ می‌دهد.
                           v10.42 (۵۶): همان منطق حالا در bslArchiveSmart جمع
                           شده تا این مسیر و مسیرِ dedup_delete_ids دقیقاً یک
                           رفتار داشته باشند (قبلاً فقط این یکی درست بود) و
                           متنِ خطا هم به‌جای «HTTP ?» گویا باشد. */
                        $dVid = (int)($d['vendor_id'] ?? ($g['vendor_id'] ?? 0));
                        $r  = bslArchiveSmart($cn, $did, $dVid);
                        $ok = !empty($r['ok']);
                        $em = (string)($r['msg'] ?? '');
                    } else {
                        $w = $cn['woocommerce'] ?? [];
                        $r = wooReq($w['store_url'], $w['consumer_key'], $w['consumer_secret'],
                            'DELETE', 'products/' . $did . '?force=true');
                        $ok = !empty($r['ok']);
                        $em = $r['body']['message'] ?? ('HTTP ' . ($r['code'] ?? '?'));
                    }
                    if ($ok) break;
                    /* ۴۰۴/۴۰۳ یعنی «دیگر نیست یا اجازه نداریم» — تکرارش بی‌فایده است */
                    $code = (int)($r['code'] ?? 0);
                    if (in_array($code, [400, 401, 403, 404], true)) break;
                    if ($dt < (int)DEDUP_DEL_TRIES) {
                        $wait = min((int)DEDUP_PAGE_WAIT_MAX, (int)(DEDUP_DEL_WAIT_BASE * pow(2, $dt - 1)));
                        dedupProgress(['log_add' => ['↻ #' . $did . ' ناموفق (HTTP ' . ($code ?: '?')
                            . ') — تلاشِ ' . ($dt + 1) . ' از ' . DEDUP_DEL_TRIES . ' بعد از ' . $wait . ' ثانیه']]);
                        sleep($wait);
                    }
                }
                $done++;
                if ($ok) {
                    $deleted++;
                    dedupProgress(['deleted' => $deleted, 'failed' => $failed, 'processed' => $done,
                        'log_add' => ['✅ ' . ($target === 'bsl' ? 'بایگانی' : 'حذف') . ' #' . $did
                            . ($dTries > 1 ? (' (تلاشِ ' . $dTries . 'ام)') : '')
                            . ' — ' . mb_substr((string)$d['name'], 0, 45, 'UTF-8')]]);
                } else {
                    $failed++;
                    if (count($errors) < 30) $errors[] = ['id' => $did, 'msg' => (string)$em];
                    dedupProgress(['deleted' => $deleted, 'failed' => $failed, 'processed' => $done,
                        'log_add' => ['❌ #' . $did . ' — ' . mb_substr((string)$em, 0, 70, 'UTF-8')]]);
                }
                /* v10.126: چک‌پوینت پس از هر مورد — اگر پردازه همین‌جا کشته
                   شود، ادامهٔ بعدی از این شناسه‌ها می‌گذرد و شمارنده‌ها حفظ
                   می‌شوند. */
                if ($ok) $cpDoneIds[] = $did;
                dedupProgress(['checkpoint' => [
                    'done_ids' => $cpDoneIds, 'deleted' => $deleted, 'failed' => $failed,
                    'done' => $done, 'started_at' => ($cpStartedAt > 0 ? $cpStartedAt : time())]]);
                usleep(250000);
            }
            if ($gi % 10 === 9) dedupProgress(['log_add' => ['— ' . ($gi + 1) . ' گروه پردازش شد —']]);
        }
    }

    // فقط بخشی از گروه‌ها را در نتیجه نگه می‌داریم تا فایل غول‌آسا نشود
    $out = [];
    foreach (array_slice($dupGroups, 0, DEDUP_MAX_GROUPS) as $g) {
        /* v10.42 (۵۶): vendor_id هر ردیف هم در گزارش می‌ماند. بدونِ آن،
           هندلرِ dedup_delete_ids (که فقط فهرستِ id می‌گیرد) نمی‌دانست هر
           محصول مالِ کدام غرفه است و همه را با توکنِ غرفهٔ پیش‌فرض بایگانی
           می‌کرد ⇒ ۴۰۳ برای هرچه مالِ غرفهٔ دیگری بود. */
        $mk = function (array $p) use ($g) {
            return ['id' => (int)($p['id'] ?? 0), 'name' => (string)($p['name'] ?? ''),
                    'price' => dedupPrice($p), 'stock' => (int)($p['stock'] ?? 0),
                    'status' => (int)($p['status'] ?? 0), 'wstatus' => (string)($p['wstatus'] ?? ''),
                    'vendor_id' => (int)($p['vendor_id'] ?? ($g['vendor_id'] ?? 0)),
                    'ts' => dedupTs($p), 'date_created' => (string)($p['date_created'] ?? '')];
        };
        /* v10.39 (۵۳): نامِ غرفه هم می‌رود تا در گزارشِ چندغرفه‌ای معلوم باشد
           هر گروه مالِ کدام غرفه است */
        $out[] = ['normalized' => $g['norm'], 'count' => $g['count'],
                  'vendor_id'   => (int)($g['vendor_id'] ?? 0),
                  'vendor_name' => (string)($g['vendor_name'] ?? ''),
                  'keep' => $mk($g['keep']), 'drop' => array_map($mk, $g['drop'])];
    }

    return ['ok' => true, 'target' => $target, 'mode' => $mode, 'cfg' => $cfg,
            'total' => count($rows), 'groups' => count($dupGroups), 'duplicates' => $dupCount,
            'deleted' => $deleted, 'failed' => $failed, 'errors' => $errors,
            'partial' => $isPartial || $stopDuringDelete,
            'stopped' => $stopDuringDelete,
            'partial_reason' => $isPartial ? (string)($partial['reason'] ?? '') : ($stopDuringDelete ? 'stopped' : ''),
            'partial_msg' => $isPartial
                ? ('فهرست ناقص دریافت شد — ' . ($partialReason[(string)($partial['reason'] ?? '')] ?? 'علتِ نامعلوم')
                   . '. گروه‌بندی روی همین ' . count($rows) . ' محصول انجام شد و برای ایمنی حذفی صورت نگرفت.')
                : '',
            'truncated' => count($dupGroups) > DEDUP_MAX_GROUPS,
            'took' => round(microtime(true) - $t0, 1), 'at' => time(),
            'duplicates_list' => $out];
}

/* =====================================================================
 *  v10.23 (۳۶د): «اصلاح دسته‌بندی محصولات باسلام» — موتورِ پس‌زمینه
 *
 *  چه چیزی عوض شد و چرا:
 *
 *  تا نسخهٔ ۱۰٫۲۲ هر سه مسیرِ این جریان (اصلاح با متنِ AIِ خودِ باسلام،
 *  اصلاح با مدلِ مستر، و اجماعِ چندمدلی) فقط «رویدادِ زنده» (SSE) بودند.
 *  یعنی کار در همان درخواستِ مرورگر می‌دوید. عوارضش دقیقاً همان چیزهایی
 *  بود که کاربر گزارش کرد:
 *
 *    • بستنِ تب یا رفتنِ گوشی به حالتِ خواب ⇒ کار وسطِ راه می‌مرد و
 *      محصولاتِ بعدی هیچ‌وقت اصلاح نمی‌شدند.
 *    • هیچ قفلی نبود ⇒ دو تبِ باز = دو اجرای موازی روی یک غرفه؛ هر دو
 *      همان محصول را PATCH می‌کردند و سهمیهٔ API دوبرابر می‌سوخت.
 *    • هیچ دکمهٔ توقفی وجود نداشت؛ تنها راه، بستنِ پنجره بود.
 *    • و مهم‌تر از همه: در «مدیر وظیفه» اصلاً دیده نمی‌شد. کاربر نمی‌دانست
 *      چنین کاری اصلاً در جریان است.
 *
 *  حالا عیناً همان الگویِ dedup/ایجنت را دارد: قفلِ انحصاری، پاسخِ زودهنگام
 *  و ادامهٔ کار در پس‌زمینهٔ سرور، فایلِ پیشرفت با لاگ و درصد، فایلِ نتیجه،
 *  فایلِ سیگنالِ توقف — و یک ردیف در رجیستریِ مدیر وظیفه.
 * ===================================================================== */

function catfixProgress(array $patch): void {
    $cur = [];
    if (is_file(CATFIX_PROGRESS_FILE)) {
        $d = json_decode((string)@file_get_contents(CATFIX_PROGRESS_FILE), true);
        if (is_array($d)) $cur = $d;
    }
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) $log[] = ['t' => time(), 'm' => (string)$l];
        if (count($log) > 400) $log = array_slice($log, -400);
        unset($patch['log_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log; $cur['ts'] = time();
    writeProgress(CATFIX_PROGRESS_FILE, $cur);
}

function catfixStopRequested(): bool { return is_file(CATFIX_STOP_FILE); }
function catfixClearStop(): void { @unlink(CATFIX_STOP_FILE); }

/** برچسبِ خوانای حالت‌های اجرا */
function catfixModeLabel(string $mode): string {
    /* v10.71 (85): روشِ چهارم — زنجیرهٔ پشتیبان */
    $m = ['ai_text' => 'متنِ بررسیِ باسلام', 'master' => 'مدلِ مستر', 'quorum' => 'اجماعِ چندمدلی',
          'fallback' => 'زنجیرهٔ پشتیبان (مستر ← کاندیدها)'];
    return $m[$mode] ?? $mode;
}

/** درختِ دسته‌بندیِ باسلام را تخت می‌کند — همان تابعِ درون‌خطیِ چهار اندپوینتِ قبلی */
function catfixFlatCats(string $tk): array {
    /* v10.41 (۵۵): از کشِ مشترک — دیگر هر بار از باسلام گرفته نمی‌شود */
    return bslCatsAll($tk);
}

/** فهرستِ محصولاتِ ردشده (وضعیت ۳۵۶۷) — با پرچمِ ناقص‌بودن، مثلِ dedup */
function catfixCursorLoad(int $vid): array {
    if (!is_file(CATFIX_FETCH_CURSOR_FILE)) return ['rows' => [], 'page' => 0];
    $sz = (int)@filesize(CATFIX_FETCH_CURSOR_FILE);
    if ($sz <= 0 || $sz > 10 * 1024 * 1024) {
        if ($sz > 10 * 1024 * 1024) @unlink(CATFIX_FETCH_CURSOR_FILE);
        return ['rows' => [], 'page' => 0];
    }
    $rows = []; $page = 0;
    $fp = @fopen(CATFIX_FETCH_CURSOR_FILE, 'rb');
    if (!is_resource($fp)) return ['rows' => [], 'page' => 0];
    $vidNeedle1 = '"vid":' . $vid . ',';
    $vidNeedle2 = '"vid": ' . $vid;
    while (($line = fgets($fp)) !== false) {
        if (strpos($line, $vidNeedle1) === false && strpos($line, $vidNeedle2) === false) {
            unset($line);
            continue;
        }
        $d = json_decode($line, true);
        unset($line);
        if (!is_array($d) || (int)($d['vid'] ?? 0) !== $vid) continue;
        foreach ((array)($d['rows'] ?? []) as $r) {
            if (is_array($r)) $rows[] = $r;
        }
        $page = max($page, (int)($d['page'] ?? 0));
    }
    @fclose($fp);
    return ['rows' => $rows, 'page' => $page];
}
function catfixCursorAppend(int $vid, int $page, array $rows): void {
    if (!$rows) return;
    $slimRows = [];
    foreach ($rows as $r) {
        if (!is_array($r)) continue;
        unset($r['vendor'], $r['category_list']);
        if (isset($r['revision']['data']['category_list'])) unset($r['revision']['data']['category_list']);
        $slimRows[] = $r;
    }
    @file_put_contents(CATFIX_FETCH_CURSOR_FILE,
        json_encode(['vid' => $vid, 'page' => $page, 'rows' => $slimRows], JSON_UNESCAPED_UNICODE) . "\n",
        FILE_APPEND | LOCK_EX);
}

/** فهرستِ محصولاتِ ردشده (وضعیت ۳۵۶۷) — با cursor صفحه‌ای و پرچمِ ناقص‌بودن */
function catfixFetchRejected(string $tk, int $vid, ?array &$partial = null, ?array &$meta = null): array {
    $meta = ['complete' => false, 'partial' => false, 'stopped' => false, 'reason' => '', 'page' => 0];
    $cursor = catfixCursorLoad($vid);
    $all = array_values(array_filter((array)($cursor['rows'] ?? []), 'is_array'));
    $firstPage = max(1, (int)($cursor['page'] ?? 0) + 1);
    for ($pg = $firstPage; $pg < $firstPage + CATFIX_MAX_PAGES; $pg++) {
        if (catfixStopRequested()) {
            $meta['partial'] = true; $meta['stopped'] = true; $meta['reason'] = 'stopped'; $meta['page'] = $pg;
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'stopped', 'page' => $pg];
            catfixProgress(['log_add' => ['⏹ توقف هنگام دریافتِ صفحهٔ ' . $pg . ' — checkpoint حفظ شد']]);
            break;
        }
        $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?page=' . $pg . '&per_page=100&statuses=3567');
        if (empty($r['ok'])) {
            $meta['partial'] = true; $meta['reason'] = 'http'; $meta['page'] = $pg;
            if ($partial !== null) $partial = ['partial' => true, 'reason' => 'http', 'page' => $pg, 'code' => (int)($r['code'] ?? 0)];
            catfixProgress(['log_add' => ['⚠️ صفحهٔ ' . $pg . ' نیامد (HTTP ' . ($r['code'] ?? '?') . ') — checkpoint حفظ شد']]);
            break;
        }
        $data = bslRowsOf($r['body']);
        if (!$data) { $meta['complete'] = true; $meta['page'] = max(0, $pg - 1); break; }
        $tp = bslMetaInt($r['body'], 'total_page', 0);
        $pageRows = [];
        foreach ($data as $item) {
            if (!is_array($item)) continue;
            unset($item['vendor'], $item['category_list']);
            if (isset($item['revision']['data']['category_list'])) unset($item['revision']['data']['category_list']);
            $pageRows[] = $item;
        }
        $all = array_merge($all, $pageRows);
        catfixCursorAppend($vid, $pg, $pageRows);
        $meta['page'] = $pg;
        catfixProgress(['fetched' => count($all), 'page' => $pg, 'pages' => $tp,
            'log_add' => ['📄 صفحهٔ ' . $pg . '/' . ($tp > 0 ? $tp : '?') . ' — مجموعاً ' . count($all) . ' محصولِ ردشده']]);
        if (count($data) < 100 || ($tp > 0 && $pg >= $tp)) { $meta['complete'] = true; break; }
        usleep(120000);
    }
    if (!$meta['complete'] && !$meta['partial']) {
        $meta['partial'] = true; $meta['reason'] = 'max_pages'; $meta['page'] = $firstPage + CATFIX_MAX_PAGES - 1;
        if ($partial !== null) $partial = ['partial' => true, 'reason' => 'max_pages', 'page' => $meta['page']];
        catfixProgress(['log_add' => ['⚠️ سقفِ برداشت رسید — checkpoint صفحهٔ ' . $meta['page'] . ' حفظ شد']]);
    }
    return $all;
}

/**
 * v10.467: واکشیِ برش‌محور (Streaming Slice) برای اجرای نامحدودِ اصلاحِ دسته بدون OOM در CloudLinux LVE.
 * به‌جای بارگذاریِ یک‌جای ۱,۰۰۰+ محصولِ ردشده در RAM پیش از اصلاحِ اولین محصول، هر نوبت حداکثر
 * $sliceSize محصولِ تازهٔ پردازش‌نشده و بایگانی‌نشده را با per_page=30 می‌خواند، بلافاصله اصلاح می‌کند،
 * و در صورت باقی‌ماندنِ صفحاتِ بعدی، از همان صفحهٔ دقیق زنجیرهٔ نوبتِ بعد را ادامه می‌دهد.
 */
function catfixFetchRejectedSlice(
    string $tk,
    int $vid,
    int $sliceSize = 20,
    int $startPage = 1,
    array $skipDoneSet = [],
    array $retired3567 = [],
    ?array &$sliceMeta = null
): array {
    $sliceSize = max(1, min(50, $sliceSize));
    $startPage = max(1, $startPage);
    $pp = 30;
    $out = [];
    $sliceMeta = [
        'ok'          => true,
        'stopped'     => false,
        'http_error'  => false,
        'code'        => 200,
        'has_more'    => false,
        'next_page'   => $startPage,
        'total_pages' => 0,
    ];
    for ($pg = $startPage; $pg < $startPage + 35; $pg++) {
        if (catfixStopRequested()) {
            $sliceMeta['stopped'] = true;
            $sliceMeta['has_more'] = true;
            $sliceMeta['next_page'] = $pg;
            break;
        }
        $r = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?page=' . $pg . '&per_page=' . $pp . '&statuses=3567');
        if (empty($r['ok'])) {
            $sliceMeta['ok'] = !empty($out);
            $sliceMeta['http_error'] = true;
            $sliceMeta['code'] = (int)($r['code'] ?? 0);
            $sliceMeta['has_more'] = true;
            $sliceMeta['next_page'] = $pg;
            break;
        }
        $data = bslRowsOf($r['body']);
        $tp = bslMetaInt($r['body'], 'total_page', 0);
        if ($tp > 0) $sliceMeta['total_pages'] = $tp;
        if (!$data) {
            $sliceMeta['has_more'] = false;
            $sliceMeta['next_page'] = $pg;
            break;
        }
        $leftoverOnPage = false;
        foreach ($data as $item) {
            if (!is_array($item)) continue;
            $rwId = (int)($item['id'] ?? 0);
            if ($rwId > 0) {
                if (isset($retired3567[$vid . ':' . $rwId]) || isset($skipDoneSet[(string)$rwId])) continue;
            }
            if (count($out) >= $sliceSize) {
                $leftoverOnPage = true;
                break;
            }
            unset($item['vendor'], $item['category_list']);
            if (isset($item['revision']['data']['category_list'])) unset($item['revision']['data']['category_list']);
            $out[] = $item;
        }
        $morePagesAfter = (count($data) >= $pp) && ($tp <= 0 || $pg < $tp);
        if (count($out) >= $sliceSize) {
            $sliceMeta['has_more'] = $leftoverOnPage || $morePagesAfter;
            $sliceMeta['next_page'] = $leftoverOnPage ? $pg : ($pg + 1);
            break;
        }
        if (!$morePagesAfter) {
            $sliceMeta['has_more'] = false;
            $sliceMeta['next_page'] = $pg;
            break;
        }
        $sliceMeta['next_page'] = $pg + 1;
        usleep(80000);
    }
    return $out;
}

/**
 * v10.466: دسته‌بندیِ دقیقِ دلایلِ عدم تأییدِ محصول در باسلام (وضعیت ۳۵۶۷).
 * دلایلِ مرتبط با رعایت شئونات اسلامی/پوشش در تصویر (کدهای ۶۴۵۶، ۵۰۳۱، ۶۴۱۹)
 * را صراحتاً با skip_modesty=true علامت می‌زند تا هرگز به‌صورت خودکار دستکاری یا
 * باز-ارسال نشوند؛ و تمامِ ۲۱ علتِ غیرشئوناتی را برای اصلاحِ مکانیزمی تفکیک می‌کند.
 */
function bslClassifyRejectionReasons(array $p, array $flatCats = []): array {
    $rev = is_array($p['revision'] ?? null) ? $p['revision'] : [];
    $revData = is_array($rev['data'] ?? null) ? $rev['data'] : [];
    $rrList = is_array($rev['rejection_reasons'] ?? null) ? $rev['rejection_reasons'] : [];
    $metaDesc = trim((string)($rev['metadata']['description'] ?? ''));
    $title = trim((string)($p['title'] ?? ($p['name'] ?? ($revData['title'] ?? ''))));
    $curCat = function_exists('bslProductCatId') ? bslProductCatId($p) : (int)($revData['category_id'] ?? 0);

    $codes = [];
    $texts = $metaDesc !== '' ? [$metaDesc] : [];
    foreach ($rrList as $rr) {
        if (!is_array($rr)) continue;
        $cid = (int)($rr['value'] ?? ($rr['id'] ?? ($rr['code'] ?? 0)));
        if ($cid > 0 && !in_array($cid, $codes, true)) $codes[] = $cid;
        $nm = trim((string)($rr['name'] ?? ($rr['title'] ?? '')));
        if ($nm !== '') $texts[] = $nm;
        $d = trim((string)($rr['description'] ?? ''));
        if ($d !== '') $texts[] = $d;
    }
    $joined = implode(' | ', $texts);

    // ۱) استثنای صریح: رعایت شئونات اسلامی در تصویر یا مشابه (۶۴۵۶، ۵۰۳۱، ۶۴۱۹)
    $modestyCodes = [6456, 5031, 6419];
    $hasModesty = false;
    foreach ($codes as $c) {
        if (in_array($c, $modestyCodes, true)) { $hasModesty = true; break; }
    }
    if (!$hasModesty && $joined !== '' && preg_match('/شئونات|پوشش\s+نامناسب|حجاب|مغایر\s+با\s+شئونات/u', $joined)) {
        $hasModesty = true;
    }

    // ۲) بررسیِ تضادِ معناییِ دستهٔ فعلی حتی وقتی تنها کدِ ثبت‌شده ۷۰۹۳ یا ۵۷۷۱ بوده است
    $semanticCatClash = false;
    if ($curCat > 0 && $title !== '' && !empty($flatCats)) {
        if (bslCategoryHasSemanticClash($title, $curCat, $flatCats)) {
            $semanticCatClash = true;
        } else {
            foreach ($flatCats as $fc) {
                if ((int)($fc['id'] ?? 0) === $curCat) {
                    $ft = trim((string)($fc['title'] ?? ($fc['name'] ?? '')));
                    if ($ft !== '' && bslIsBannedCategoryTitle($ft)) $semanticCatClash = true;
                    break;
                }
            }
        }
    }

    $catCodes = [6046, 6457, 7077];
    $needsCategory = $semanticCatClash;
    foreach ($codes as $c) {
        if (in_array($c, $catCodes, true)) { $needsCategory = true; break; }
    }
    if (!$needsCategory && $metaDesc !== '' && preg_match('/دسته[\x{200c}\s]*بندی|در\s+دسته\s+/u', $metaDesc)) {
        $needsCategory = true;
    }

    $textCodes = [5771, 5386, 6435, 6379, 5351, 5581, 6378, 7083, 6454, 6054];
    $needsText = false;
    foreach ($codes as $c) {
        if (in_array($c, $textCodes, true)) { $needsText = true; break; }
    }
    $descRaw = trim((string)($revData['description'] ?? ($p['description'] ?? '')));
    if (!$needsText && mb_strlen($descRaw, 'UTF-8') < 25) $needsText = true;

    $imgCodes = [5387, 5388, 5043, 6379];
    $needsImage = false;
    foreach ($codes as $c) {
        if (in_array($c, $imgCodes, true)) { $needsImage = true; break; }
    }

    $priceCodes = [6380, 6381, 5011];
    $needsPrice = false;
    foreach ($codes as $c) {
        if (in_array($c, $priceCodes, true)) { $needsPrice = true; break; }
    }

    return [
        'codes'               => $codes,
        'skip_modesty'        => $hasModesty,
        'needs_vendor_active' => in_array(7094, $codes, true),
        'needs_stock'         => in_array(7093, $codes, true),
        'needs_category'      => $needsCategory,
        'needs_text_or_title' => $needsText,
        'needs_image_refresh' => $needsImage,
        'needs_price_check'   => $needsPrice,
        'semantic_cat_clash'  => $semanticCatClash,
        'summary_text'        => mb_substr($joined, 0, 240, 'UTF-8'),
    ];
}

/**
 * v10.466: ایندکسِ حافظه‌ایِ محصولاتِ محلی (پروفایل‌ها + دفترچهٔ remote_map)
 * برای تطبیقِ سریعِ محصولاتِ ردشدهٔ باسلام با منبعِ اصلی (موجودی واقعی، تصاویر اصلی، مشخصات).
 */
function bslBuildLocalProductIndex(?array $profiles = null, ?array $targetProducts = null): array {
    if ($profiles === null) $profiles = function_exists('loadProfiles') ? loadProfiles() : [];
    $byRemote = [];
    $byNorm = [];
    $byBare = [];

    $wantRids = null;
    $wantNorms = null;
    $wantQTail = [];
    $wantSkus = [];
    if (is_array($targetProducts)) {
        $wantRids = [];
        $wantNorms = [];
        foreach ($targetProducts as $tp) {
            if (!is_array($tp)) continue;
            $tid = (int)($tp['id'] ?? 0);
            if ($tid > 0) $wantRids[$tid] = true;
            $tsku = trim((string)($tp['sku'] ?? ($tp['revision']['data']['sku'] ?? '')));
            if ($tsku !== '') {
                $tskuClean = strtolower(trim((string)(preg_replace('~^sku\s*:\s*~i', '', $tsku) ?? $tsku)));
                if ($tskuClean !== '') $wantSkus[$tskuClean] = true;
            }
            $tt = trim((string)($tp['title'] ?? ($tp['name'] ?? ($tp['revision']['data']['title'] ?? ''))));
            if ($tt !== '') {
                $tNorm = bslNormalizeTitle($tt);
                if ($tNorm !== '') $wantNorms[$tNorm] = true;
                $tBareRaw = stripProductCode($tt);
                $tBare = bslNormalizeTitle($tBareRaw);
                if ($tBare !== '') $wantNorms[$tBare] = true;
                $tClean = bslNormalizeTitle(bslSanitizeModerationTitle($tt, true));
                if ($tClean !== '') $wantNorms[$tClean] = true;
                if (strpos($tBareRaw, '?') === 0 && mb_strlen($tBareRaw, 'UTF-8') > 2) {
                    $qt = bslNormalizeTitle(mb_substr($tBareRaw, 1, null, 'UTF-8'));
                    if ($qt !== '') $wantQTail[$qt] = true;
                }
            }
        }
    }

    $rm = function_exists('remoteMapLoad') ? (array)(remoteMapLoad()['bsl'] ?? []) : [];
    $ledgerKeyByRid = [];
    $wantKeys = ($wantRids !== null) ? [] : null;
    foreach ($rm as $mk => $row) {
        if (!is_array($row)) continue;
        $rid = (int)($row['id'] ?? 0);
        if ($rid <= 0) continue;
        if ($wantRids !== null && !isset($wantRids[$rid])) continue;
        $rawPk = (strpos((string)$mk, '@') !== false) ? substr((string)$mk, 0, strpos((string)$mk, '@')) : (string)$mk;
        $ledgerKeyByRid[$rid] = ['product_key' => $rawPk, 'title' => trim((string)($row['title'] ?? ''))];
        if ($wantKeys !== null && $rawPk !== '') $wantKeys[$rawPk] = true;
        if ($wantNorms !== null && !empty($row['title'])) {
            $lNorm = bslNormalizeTitle((string)$row['title']);
            if ($lNorm !== '') $wantNorms[$lNorm] = true;
        }
    }
    unset($rm);

    $slimKeep = ['key','title','price','final_price','stock','in_stock','availability','status','weight','barcode','shenase_kala','gtin','ean','sku','image','images','link','bsl_category_id','category_id','short_desc','variations_text'];
    $byKey = [];
    $bySku = [];
    $byQTail = [];
    $hasWantSkus = !empty($wantSkus);
    $hasWantQTail = !empty($wantQTail);
    foreach ($profiles as $profKey => $prof) {
        if (!is_array($prof)) continue;
        $prods = is_array($prof['products'] ?? null) ? $prof['products'] : [];
        $profMeta = $prof;
        unset($profMeta['products'], $profMeta['logs'], $profMeta['history']);
        foreach ($prods as $pk => $pr) {
            if (!is_array($pr)) continue;
            $itemKey = trim((string)($pr['key'] ?? (is_string($pk) ? $pk : '')));
            $pt = trim((string)($pr['title'] ?? ''));
            if ($pt === '') continue;
            $nt = bslNormalizeTitle($pt);
            $bareRaw = stripProductCode($pt);
            $bare = ($bareRaw === $pt) ? $nt : bslNormalizeTitle($bareRaw);
            $psku = '';
            if ($hasWantSkus && !empty($pr['sku'])) {
                $rawS = trim((string)$pr['sku']);
                if (stripos($rawS, 'sku:') === 0) $rawS = trim(substr($rawS, 4));
                $psku = strtolower($rawS);
            }
            $qTail = '';
            if ($hasWantQTail && strlen($bare) > 3) {
                $b0 = ord($bare[0]);
                $skipB = (($b0 & 0xE0) === 0xC0) ? 2 : ((($b0 & 0xF0) === 0xE0) ? 3 : ((($b0 & 0xF8) === 0xF0) ? 4 : 1));
                $qTail = ltrim(substr($bare, $skipB));
            }
            if ($wantNorms !== null) {
                $matched = ($itemKey !== '' && isset($wantKeys[$itemKey]))
                    || ($psku !== '' && isset($wantSkus[$psku]))
                    || ($nt !== '' && isset($wantNorms[$nt]))
                    || ($bare !== '' && isset($wantNorms[$bare]))
                    || ($qTail !== '' && isset($wantQTail[$qTail]));
                if (!$matched) continue;
            }
            $slimPr = [];
            foreach ($slimKeep as $sk) {
                if (array_key_exists($sk, $pr)) $slimPr[$sk] = $pr[$sk];
            }
            if (!empty($pr['long_desc']) && is_string($pr['long_desc'])) {
                $slimPr['long_desc'] = mb_substr($pr['long_desc'], 0, 1800, 'UTF-8');
            }
            if (!empty($pr['specs']) && is_string($pr['specs'])) {
                $slimPr['specs'] = mb_substr($pr['specs'], 0, 1800, 'UTF-8');
            }
            $entry = ['product' => $slimPr, 'profile' => $profMeta, 'profile_key' => (string)$profKey, 'product_key' => $itemKey];
            if ($itemKey !== '' && !isset($byKey[$itemKey])) $byKey[$itemKey] = $entry;
            if ($psku !== '' && !isset($bySku[$psku])) $bySku[$psku] = $entry;
            if ($nt !== '' && !isset($byNorm[$nt])) $byNorm[$nt] = $entry;
            if ($bare !== '' && !isset($byBare[$bare])) $byBare[$bare] = $entry;
            if ($qTail !== '' && !isset($byQTail[$qTail])) $byQTail[$qTail] = $entry;
        }
    }
    foreach ($ledgerKeyByRid as $rid => $inf) {
        $pk0 = (string)($inf['product_key'] ?? '');
        if ($pk0 !== '' && isset($byKey[$pk0])) {
            $byRemote[$rid] = $byKey[$pk0];
        } elseif ($inf['title'] !== '') {
            $nt0 = bslNormalizeTitle($inf['title']);
            if ($nt0 !== '' && isset($byNorm[$nt0])) $byRemote[$rid] = $byNorm[$nt0];
        }
    }
    return ['by_remote' => $byRemote, 'by_sku' => $bySku, 'by_norm' => $byNorm, 'by_bare' => $byBare, 'by_qtail' => $byQTail];
}

function bslFindLocalSourceProduct(int $remoteId, string $title, array $idx, string $sku = ''): ?array {
    if ($remoteId > 0 && isset($idx['by_remote'][$remoteId])) return $idx['by_remote'][$remoteId];
    if ($sku !== '') {
        $skuClean = strtolower(trim((string)(preg_replace('~^sku\s*:\s*~i', '', $sku) ?? $sku)));
        if ($skuClean !== '' && isset($idx['by_sku'][$skuClean])) return $idx['by_sku'][$skuClean];
    }
    $nt = bslNormalizeTitle($title);
    if ($nt !== '' && isset($idx['by_norm'][$nt])) return $idx['by_norm'][$nt];
    $bareRaw = stripProductCode($title);
    $bare = bslNormalizeTitle($bareRaw);
    if ($bare !== '' && isset($idx['by_bare'][$bare])) return $idx['by_bare'][$bare];
    if (strpos($bareRaw, '?') === 0 && mb_strlen($bareRaw, 'UTF-8') > 2) {
        $qt = bslNormalizeTitle(mb_substr($bareRaw, 1, null, 'UTF-8'));
        if ($qt !== '' && isset($idx['by_qtail'][$qt])) return $idx['by_qtail'][$qt];
    }
    $cleanT = bslNormalizeTitle(bslSanitizeModerationTitle($title, true));
    if ($cleanT !== '' && isset($idx['by_bare'][$cleanT])) return $idx['by_bare'][$cleanT];
    return null;
}

function bslHealCorruptedLeadingQuestionTitle(string $title, ?array $localMatch = null): string {
    $t = trim($title);
    if ($t === '' || strpos($t, '?') !== 0) return $t;
    $localTitle = trim((string)($localMatch['product']['title'] ?? ''));
    if ($localTitle !== '' && strpos($localTitle, '?') !== 0) {
        $firstChar = mb_substr($localTitle, 0, 1, 'UTF-8');
        if ($firstChar !== '') return $firstChar . mb_substr($t, 1, null, 'UTF-8');
    }
    static $prefixMap = [
        '?ابه' => 'تابه', '?رویس' => 'سرویس', '?ماور' => 'سماور', '?رس ' => 'برس ',
        '?تری' => 'بطری', '?شقاب' => 'بشقاب', '?ندل' => 'صندل', '?ومیز' => 'شومیز',
        '?لوار' => 'شلوار', '?ال ' => 'شال ', '?امپو' => 'شامپو', '?ت ' => 'ست ',
        '?بد ' => 'سبد ', '?طل ' => 'سطل ', '?ینی' => 'سینی', '?فره' => 'سفره',
        '?بکش' => 'آبکش', '?بمیوه' => 'آبمیوه', '?ویز' => 'آویز', '?ینه' => 'آینه',
        '?ستکان' => 'استکان', '?ستند' => 'استند', '?سفنج' => 'اسفنج', '?سپری' => 'اسپری',
        '?دکلن' => 'ادکلن', '?بزار' => 'ابزار', '?تو ' => 'اتو ', '?جاق' => 'اجاق',
        '?رام پز' => 'آرام پز', '?رخ کن' => 'سرخ کن', '?نبر' => 'انبر', '?ردوخوری' => 'اردوخوری',
        '?الش' => 'بالش', '?اکس' => 'باکس', '?ند ' => 'بند ', '?لوز' => 'بلوز',
        '?اپ ' => 'تاپ ', '?یشرت' => 'تیشرت', '?ونیک' => 'تونیک', '?رمه' => 'ترمه',
        '?خته' => 'تخته', '?رازو' => 'ترازو', '?ارو' => 'جارو', '?اکلیدی' => 'جاکلیدی',
        '?امایع' => 'جامایع', '?ادستمالی' => 'جادستمالی', '?اقاشقی' => 'جاقاشقی', '?اصابونی' => 'جاصابونی',
        '?اکفشی' => 'جاکفشی', '?عبه' => 'جعبه', '?وراب' => 'جوراب', '?وله' => 'حوله',
        '?ردکن' => 'خردکن', '?امن' => 'دامن', '?ستکش' => 'دستکش', '?ستمال' => 'دستمال',
        '?یس ' => 'دیس ', '?یگ ' => 'دیگ ', '?نده' => 'رنده', '?ومیزی' => 'رومیزی',
        '?ودپز' => 'زودپز', '?اعت' => 'ساعت', '?اک ' => 'ساک ', '?اندویچ' => 'ساندویچ',
        '?شوار' => 'سشوار', '?وپ' => 'سوپ', '?ارژر' => 'شارژر', '?مع' => 'شمع',
        '?یرینی' => 'شیرینی', '?یشه' => 'شیشه', '?ابون' => 'صابون', '?افی' => 'صافی',
        '?رف ' => 'ظرف ', '?روف' => 'ظروف', '?طر ' => 'عطر ', '?ینک' => 'عینک',
    ];
    foreach ($prefixMap as $bad => $good) {
        if (mb_strpos($t, $bad, 0, 'UTF-8') === 0) {
            return $good . mb_substr($t, mb_strlen($bad, 'UTF-8'), null, 'UTF-8');
        }
    }
    return $t;
}

/**
 * v10.466: استخراجِ شناسه‌هایِ واقعیِ عکس از revision.data محصولِ ردشده.
 * در محصولاتِ ۳۵۶۷، فیلدِ سطحِ بالای photo تصویرِ placeholder ادمینِ باسلام است
 * و photos خالی است؛ شناسه‌های واقعی در revision.data.photos / revision.data.photo قرار دارند.
 */
function bslExtractRevisionPhotoIds(array $origP): array {
    $rev = is_array($origP['revision'] ?? null) ? $origP['revision'] : [];
    $revData = is_array($rev['data'] ?? null) ? $rev['data'] : [];
    $ids = [];
    $addObj = static function ($ph) use (&$ids): void {
        if (is_numeric($ph)) {
            $id = (int)$ph;
            if ($id > 0 && !in_array($id, $ids, true)) $ids[] = $id;
            return;
        }
        if (!is_array($ph)) return;
        $url = trim((string)($ph['original'] ?? ($ph['lg'] ?? ($ph['md'] ?? ($ph['url'] ?? '')))));
        if ($url !== '' && bslIsPlaceholderImageUrl($url)) return;
        $id = (int)($ph['id'] ?? ($ph['file_id'] ?? 0));
        if ($id > 0 && !in_array($id, $ids, true)) $ids[] = $id;
    };
    $addObj($revData['photo'] ?? null);
    foreach ((array)($revData['photos'] ?? []) as $ph) $addObj($ph);
    $addObj($origP['photo'] ?? null);
    foreach ((array)($origP['photos'] ?? []) as $ph) $addObj($ph);
    return ['main' => $ids[0] ?? 0, 'ids' => $ids];
}

function bslRetired3567Load(): array {
    $f = __DIR__ . '/bsl_retired_3567.json';
    if (!is_file($f)) return [];
    $d = json_decode((string)@file_get_contents($f), true);
    return is_array($d) ? $d : [];
}

function bslRetired3567Record(int $vid, int $pId, string $action, int $newId = 0): void {
    if ($vid <= 0 || $pId <= 0) return;
    $f = __DIR__ . '/bsl_retired_3567.json';
    $d = bslRetired3567Load();
    $d[$vid . ':' . $pId] = ['action' => $action, 'new_id' => $newId, 'at' => time()];
    if (count($d) > 25000) $d = array_slice($d, -20000, null, true);
    @file_put_contents($f, json_encode($d, JSON_UNESCAPED_UNICODE), LOCK_EX);
}

/**
 * v10.466: اعمالِ امنِ اصلاحِ دسته‌بندی + محتوا/تصویر/موجودی/قیمت روی محصولِ ردشده (۳۵۶۷).
 * - اگر محصول واقعاً ناموجود باشد یا قیمت زیر کفِ مجاز (۵,۰۰۰ تومان) داشته باشد، به‌جای
 *   ارسالِ مجدد و خوردنِ دوبارهٔ کد ۷۰۹۳/۵۰۱۱/۶۳۸۱، آن را بایگانی (۴۱۸۴) یا غیرفعال (۳۷۹۰) می‌کند.
 * - اگر allow_category_change فعال باشد یا دسته تغییر نکرده باشد، مستقیماً PATCH می‌زند.
 * - اگر باسلام تغییرِ دسته را قفل کرده باشد (HTTP 422: «فعلا قادر به تغییر دسته بندی محصول خود نمی باشید»)،
 *   محصولِ معیوبِ قبلی را تغییرِ نام و بایگانی (۴۱۸۴) کرده و محصولِ تمیزِ جایگزین را با شناسه‌هایِ واقعیِ عکس،
 *   عنوانِ استاندارد، توضیحاتِ غنی و دفترچهٔ به‌روز ثبت می‌کند.
 */
function bslApplyCategoryChangeOrRecreate(
    string $tk,
    int $vid,
    array $origP,
    int $newCatId,
    array $cn = [],
    ?array $localMatch = null,
    bool $forceFreshPhotos = false
): array {
    $pId = (int)($origP['id'] ?? 0);
    if ($pId <= 0) return ['ok' => false, 'error' => 'شناسهٔ محصول نامعتبر است'];
    $bs = is_array($cn['basalam'] ?? null) ? $cn['basalam'] : [];
    $retMap = bslRetired3567Load();
    $retEntry = $retMap[$vid . ':' . $pId] ?? null;
    if (is_array($retEntry) && (int)($retEntry['new_id'] ?? 0) > 0 && (int)$retEntry['new_id'] !== $pId) {
        return [
            'ok'            => true,
            'id'            => (int)$retEntry['new_id'],
            'replaced_from' => $pId,
            'action'        => 'already_replaced',
            'category_id'   => $newCatId,
            'msg'           => 'نسخهٔ جایگزین #' . (int)$retEntry['new_id'] . ' از قبل ثبت شده بود',
        ];
    }

    $fullP = $origP;
    if (!isset($fullP['revision']['data']) || !array_key_exists('allow_category_change', $fullP)) {
        $rg = bslReq($tk, 'GET', 'products/' . $pId);
        if (!empty($rg['ok']) && is_array($rg['body'] ?? null)) $fullP = $rg['body'];
    }
    $rev = is_array($fullP['revision'] ?? null) ? $fullP['revision'] : [];
    $revData = is_array($rev['data'] ?? null) ? $rev['data'] : [];
    $curCatId = function_exists('bslProductCatId') ? bslProductCatId($fullP) : (int)($revData['category_id'] ?? 0);
    if ($newCatId <= 0) $newCatId = $curCatId;
    if ($newCatId <= 0) return ['ok' => false, 'error' => 'دستهٔ مقصد نامعتبر است'];

    $localProd = is_array($localMatch['product'] ?? null) ? $localMatch['product'] : [];
    $localProf = is_array($localMatch['profile'] ?? null) ? $localMatch['profile'] : null;

    $rawOrigTitle = trim((string)($fullP['title'] ?? ($fullP['name'] ?? ($revData['title'] ?? ''))));
    $rawOrigTitle = trim((string)(preg_replace('/\s*\[بایگانی\s+\d+\]\s*$/u', '', $rawOrigTitle) ?? $rawOrigTitle));
    $rawOrigTitle = bslHealCorruptedLeadingQuestionTitle($rawOrigTitle, $localMatch);
    if ($rawOrigTitle === '' && !empty($localProd['title'])) $rawOrigTitle = trim((string)$localProd['title']);
    if ($rawOrigTitle === '') return ['ok' => false, 'error' => 'عنوانِ محصول خالی است'];

    $barcode = !empty($localProd) ? bslExtractValidBarcode($localProd) : '';
    if ($barcode === '') {
        $candBc = preg_replace('/\D+/', '', (string)($revData['barcode'] ?? ($fullP['barcode'] ?? '')));
        if (in_array(strlen($candBc), [8, 12, 13, 14], true) && !preg_match('/^0+$/', $candBc)) $barcode = $candBc;
    }
    $cleanTitle = bslSanitizeModerationTitle($rawOrigTitle, $barcode !== '');
    if ($cleanTitle === '') $cleanTitle = mb_substr($rawOrigTitle, 0, 120, 'UTF-8');

    // محاسبهٔ موجودی و قیمتِ واقعی
    $origStock = (int)($revData['inventory'] ?? ($revData['stock'] ?? ($fullP['inventory'] ?? ($fullP['stock'] ?? 0))));
    if (!empty($localProd)) {
        $finalStock = effectiveStock($localProd, max(1, (int)($bs['stock'] ?? 10)));
    } else {
        $finalStock = $origStock;
    }

    $origPriceRial = (int)($revData['primary_price'] ?? ($fullP['primary_price'] ?? ($fullP['price'] ?? 0)));
    $finalPriceRial = $origPriceRial;
    if (!bslIsRealisticPriceRial($finalPriceRial) && !empty($localProd)) {
        $srcToman = (int)($localProd['final_price'] ?? ($localProd['price'] ?? 0));
        if ($srcToman > 0) {
            $targetShop = ['vendor_id' => $vid, 'token' => $tk];
            if (function_exists('bslAllShops')) {
                foreach (bslAllShops($cn) as $sh0) {
                    if ((int)($sh0['vendor_id'] ?? 0) === $vid) { $targetShop = $sh0; break; }
                }
            }
            $adjToman = function_exists('destAdjustedPrice')
                ? destAdjustedPrice($srcToman, $localProf, 'basalam', (int)($bs['price_round'] ?? 0), $targetShop)
                : $srcToman;
            if ($adjToman > 0) $finalPriceRial = $adjToman * 10;
        }
    }

    // اگر محصول ناموجود است یا قیمتش غیرواقعی (< ۵,۰۰۰ تومان) است، به‌جای ایجاد خطای ۷۰۹۳/۵۰۱۱ بایگانی کن
    if ($finalStock <= 0 || !bslIsRealisticPriceRial($finalPriceRial)) {
        $archReason = $finalStock <= 0
            ? 'محصول ناموجود بود (کد ۷۰۹۳) — بایگانی شد تا خطای عدم تأیید تکرار نشود'
            : 'قیمت محصول زیر کف مجاز باسلام بود (کد ۵۰۱۱/۶۳۸۱) — بایگانی شد';
        $archRes = function_exists('bslSetProductStatus')
            ? bslSetProductStatus($tk, $vid, $pId, 4184, 'auto')
            : bslReq($tk, 'PATCH', 'products/' . $pId, ['status' => 3790, 'stock' => 0]);
        if (empty($archRes['ok'])) {
            $archRes = bslReq($tk, 'PATCH', 'products/' . $pId, ['status' => 3790, 'stock' => 0]);
        }
        if (!empty($archRes['ok'])) {
            bslRetired3567Record($vid, $pId, 'archived', 0);
            return ['ok' => true, 'id' => $pId, 'action' => 'archived', 'category_id' => $curCatId, 'msg' => $archReason];
        }
        return ['ok' => false, 'error' => 'محصول ناموجود/کم‌قیمت بود ولی بایگانی هم ناموفق ماند: ' . bslErrText($archRes)];
    }

    // آماده‌سازیِ توضیحاتِ غنی و وزن
    if (!empty($localProd)) {
        $built = bslBuildUnifiedDescription($localProd, $cleanTitle);
        $cleanBrief = $built['brief'] !== '' ? $built['brief'] : mb_substr(s4HtmlToPlainTextForBsl($cleanTitle), 0, 250, 'UTF-8');
        $cleanDesc = bslEnsureRichCompliantDescription($built['description'], $cleanTitle, $localProd, $barcode !== '');
    } else {
        $rawBrief = trim((string)($revData['brief'] ?? ($fullP['brief'] ?? '')));
        $rawDesc  = trim((string)($revData['description'] ?? ($fullP['description'] ?? '')));
        $cleanBrief = bslSanitizeModerationText($rawBrief !== '' ? $rawBrief : $cleanTitle, $barcode !== '');
        if (mb_strlen($cleanBrief, 'UTF-8') < 10) $cleanBrief = mb_substr($cleanTitle, 0, 250, 'UTF-8');
        $cleanBrief = mb_substr($cleanBrief, 0, 250, 'UTF-8');
        $cleanDesc = bslEnsureRichCompliantDescription($rawDesc, $cleanTitle, [], $barcode !== '');
    }

    $origW = (int)($revData['net_weight'] ?? ($revData['weight'] ?? ($fullP['net_weight'] ?? ($fullP['weight'] ?? 0))));
    if ($origW <= 0) $origW = (int)($bs['weight'] ?? 500);
    $origPW = (int)($revData['packaged_weight'] ?? ($revData['package_weight'] ?? ($fullP['packaged_weight'] ?? ($fullP['package_weight'] ?? 0))));
    if ($origPW <= $origW) $origPW = $origW + 100;
    $wInfo = bslResolveProductWeights($localProd, $origW, $origPW);
    $finalW = max(50, (int)($wInfo['weight'] ?? $origW));
    $finalPW = max($finalW + 50, (int)($wInfo['package_weight'] ?? $origPW));
    $prepDays = max(1, (int)($revData['preparation_day'] ?? ($revData['preparation_days'] ?? ($bs['preparation_days'] ?? 3))));

    // آماده‌سازیِ عکس‌ها (بازآپلودِ استاندارد در صورت خطای کیفی/کادر/واترمارک یا نبودنِ عکس در revision)
    $revPhotos = bslExtractRevisionPhotoIds($fullP);
    $photoMain = (int)($revPhotos['main'] ?? 0);
    $photoIds  = (array)($revPhotos['ids'] ?? []);
    $uploadedFresh = false;
    if (($forceFreshPhotos || $photoMain <= 0) && !empty($localProd)) {
        $srcImgs = productImageList($localProd);
        if (!empty($srcImgs)) {
            $um = bslUploadMany($tk, $srcImgs, (int)($bs['max_photos'] ?? 10));
            if (!empty($um['ok']) && (int)($um['main'] ?? 0) > 0) {
                $photoMain = (int)$um['main'];
                $photoIds  = !empty($um['ids']) ? $um['ids'] : [$photoMain];
                $uploadedFresh = true;
            }
        }
    }

    $sameCategory = ($curCatId > 0 && $newCatId === $curCatId);
    $canPatchCat  = !empty($fullP['allow_category_change']);

    // مسیر الف: همان دسته است یا باسلام اجازهٔ تغییر مستقیم دسته را داده است → PATCH مستقیم
    if ($sameCategory || $canPatchCat) {
        $bu = [
            'name'             => mb_substr($cleanTitle, 0, 120, 'UTF-8'),
            'brief'            => $cleanBrief,
            'description'      => $cleanDesc,
            'primary_price'    => $finalPriceRial,
            'stock'            => $finalStock,
            'weight'           => $finalW,
            'package_weight'   => $finalPW,
            'preparation_days' => $prepDays,
            'is_wholesale'     => false,
            'status'           => 2976,
        ];
        if (!$sameCategory && $canPatchCat) $bu['category_id'] = $newCatId;
        if ($barcode !== '') $bu['barcode'] = $barcode;
        if ($uploadedFresh && $photoMain > 0) {
            $bu['photo']  = $photoMain;
            $bu['photos'] = !empty($photoIds) ? $photoIds : [$photoMain];
        }
        $rPatch = bslReq($tk, 'PATCH', 'products/' . $pId, $bu);
        if (empty($rPatch['ok']) && bslIsDuplicateName($rPatch)) {
            $bu['name'] = mb_substr($cleanTitle, 0, 108, 'UTF-8') . ' کد ' . ($pId % 10000);
            $rPatch = bslReq($tk, 'PATCH', 'products/' . $pId, $bu);
        }
        if (!empty($rPatch['ok']) && !empty($rPatch['body']['id'])) {
            if (function_exists('bslCatalogNote')) bslCatalogNote($vid, (string)$bu['name'], (int)$rPatch['body']['id']);
            return [
                'ok'          => true,
                'id'          => (int)$rPatch['body']['id'],
                'action'      => 'patched',
                'category_id' => $sameCategory ? $curCatId : $newCatId,
                'msg'         => $sameCategory
                    ? 'محتوا، موجودی و استانداردهای محصول اصلاح و برای بررسی مجدد ارسال شد'
                    : 'دسته و محتوای محصول مستقیماً اصلاح شد',
            ];
        }
        if ($sameCategory) {
            return ['ok' => false, 'error' => 'PATCH ناموفق: ' . bslErrText($rPatch), 'last_response' => $rPatch];
        }
    }

    // مسیر ب: باسلام تغییر دسته روی محصولِ موجود را قفل کرده (HTTP 422) → آزادسازی نام/SKU، ایجادِ جایگزینِ تمیز و سپس بایگانیِ قدیمی
    if ($photoMain <= 0) {
        return ['ok' => false, 'error' => 'شناسهٔ تصویر معتبر برای بازسازی محصول یافت نشد'];
    }
    $origSku = trim((string)($localProd['sku'] ?? ($revData['sku'] ?? ($fullP['sku'] ?? ''))));
    if (strpos($origSku, 'ret-') === 0) $origSku = '';

    // اگر نسخهٔ سالمِ همین عنوان از قبل در دستهٔ جدید (یا وضعیت غیر ۳۵۶۷) فعال است، دوباره نساز و فقط این نسخهٔ ردشده را بایگانی کن
    if (function_exists('bslFindExistingQuick')) {
        $exRowQuick = bslFindExistingQuick($tk, $vid, $cleanTitle);
        $existingReplId = is_array($exRowQuick) ? (int)($exRowQuick['id'] ?? 0) : 0;
        if ($existingReplId > 0 && $existingReplId !== $pId) {
            $rExRepl = bslReq($tk, 'GET', 'products/' . $existingReplId);
            $exBody = is_array($rExRepl['body'] ?? null) ? $rExRepl['body'] : [];
            $exCat = (int)($exBody['category']['id'] ?? ($exBody['category_id'] ?? 0));
            $exSt = is_array($exBody['status'] ?? null) ? (int)($exBody['status']['value'] ?? 0) : (int)($exBody['status'] ?? 0);
            if ($exCat === $newCatId || ($exSt > 0 && $exSt !== 3567 && $exSt !== 4184 && $exSt !== 3790)) {
                if (function_exists('bslSetProductStatus')) {
                    bslSetProductStatus($tk, $vid, $pId, 4184, 'auto');
                }
                bslRetired3567Record($vid, $pId, 'already_replaced', $existingReplId);
                if (!empty($localProd)) {
                    bslShopMapRecord($localProd, ['vendor_id' => $vid, 'token' => $tk], $existingReplId, $cleanTitle, $finalPriceRial, $finalStock, $finalW);
                }
                return [
                    'ok'            => true,
                    'id'            => $existingReplId,
                    'replaced_from' => $pId,
                    'action'        => 'already_replaced',
                    'category_id'   => $exCat > 0 ? $exCat : $newCatId,
                    'msg'           => 'نسخهٔ سالم #' . $existingReplId . ' از قبل فعال بود؛ نسخهٔ ردشده #' . $pId . ' بایگانی شد',
                ];
            }
        }
    }

    $retiredName = mb_substr($rawOrigTitle, 0, 92, 'UTF-8') . ' [بایگانی ' . $pId . ']';
    $retirePatch = [
        'name'   => $retiredName,
        'stock'  => 0,
        'status' => 3790,
        'sku'    => 'ret-' . $pId,
    ];
    bslReq($tk, 'PATCH', 'products/' . $pId, $retirePatch);

    $bp = [
        'name'             => mb_substr($cleanTitle, 0, 120, 'UTF-8'),
        'brief'            => $cleanBrief,
        'description'      => $cleanDesc,
        'primary_price'    => $finalPriceRial,
        'stock'            => $finalStock,
        'preparation_days' => $prepDays,
        'weight'           => $finalW,
        'package_weight'   => $finalPW,
        'is_wholesale'     => false,
        'category_id'      => $newCatId,
        'photo'            => $photoMain,
        'photos'           => !empty($photoIds) ? $photoIds : [$photoMain],
        'status'           => 2976,
    ];
    if ($barcode !== '') $bp['barcode'] = $barcode;
    if ($origSku !== '') $bp['sku'] = mb_substr($origSku, 0, 60, 'UTF-8');

    $rCreate = bslReq($tk, 'POST', 'vendors/' . $vid . '/products', $bp);
    for ($createAtt = 0; $createAtt < 4 && empty($rCreate['ok']); $createAtt++) {
        $retriedThisRound = false;
        $errCreateTxt = bslErrText($rCreate);
        if (isset($bp['sku']) && (stripos($errCreateTxt, 'sku') !== false || isset($rCreate['body']['messages']['sku']))) {
            unset($bp['sku']);
            $retriedThisRound = true;
        }
        if (bslIsDuplicateName($rCreate)) {
            $suf1 = ' کد ' . ($pId % 10000);
            $suf2 = ' کد ' . $pId;
            if (strpos((string)$bp['name'], $suf1) === false && strpos((string)$bp['name'], $suf2) === false) {
                $bp['name'] = mb_substr($cleanTitle, 0, 108, 'UTF-8') . $suf1;
                $retriedThisRound = true;
            } elseif (strpos((string)$bp['name'], $suf2) === false) {
                $bp['name'] = mb_substr($cleanTitle, 0, 102, 'UTF-8') . $suf2;
                $retriedThisRound = true;
            }
        }
        if (((function_exists('bslIsPreparationDaysError') && bslIsPreparationDaysError($rCreate))
             || stripos($errCreateTxt, 'preparation_days') !== false)
            && (int)$bp['preparation_days'] > 1
        ) {
            $bp['preparation_days'] = max(1, (int)$bp['preparation_days'] - 1);
            $retriedThisRound = true;
        }
        if (!$retriedThisRound) break;
        $rCreate = bslReq($tk, 'POST', 'vendors/' . $vid . '/products', $bp);
    }
    if (!empty($rCreate['ok']) && !empty($rCreate['body']['id'])) {
        $newId = (int)$rCreate['body']['id'];
        if (function_exists('bslSetProductStatus')) {
            bslSetProductStatus($tk, $vid, $pId, 4184, 'auto');
        }
        bslRetired3567Record($vid, $pId, 'recreated', $newId);
        if (!empty($localProd)) {
            bslShopMapRecord($localProd, ['vendor_id' => $vid, 'token' => $tk], $newId, (string)$bp['name'], $finalPriceRial, $finalStock, $finalW);
        }
        bslCatalogNote($vid, (string)$bp['name'], $newId);
        if (!empty($localMatch['profile_key'])) {
            bslSaveAiCategoryToProfile((string)$localMatch['profile_key'], (string)($localMatch['product_key'] ?? ''), $cleanTitle, $newCatId);
        }
        return [
            'ok'            => true,
            'id'            => $newId,
            'replaced_from' => $pId,
            'action'        => 'recreated',
            'category_id'   => $newCatId,
            'msg'           => 'دسته قفل بود؛ محصولِ معیوب #' . $pId . ' بایگانی و محصولِ تمیز #' . $newId . ' ثبت شد',
        ];
    }
    // در صورت شکست ایجاد، نام اصلی روی محصول قدیمی برگردانده شود
    $rollbackPatch = ['name' => mb_substr($rawOrigTitle, 0, 120, 'UTF-8')];
    if ($origSku !== '') $rollbackPatch['sku'] = mb_substr($origSku, 0, 60, 'UTF-8');
    bslReq($tk, 'PATCH', 'products/' . $pId, $rollbackPatch);
    return [
        'ok'            => false,
        'error'         => 'بازسازی محصول با دستهٔ جدید ناموفق: ' . bslErrText($rCreate),
        'last_response' => $rCreate,
    ];
}

/**
 * اجرای کاملِ اصلاحِ دسته — می‌تواند چند دقیقه طول بکشد و فقط از مسیرِ
 * پس‌زمینه صدا زده می‌شود.
 *
 * $mode: 'ai_text' متنِ بررسیِ خودِ باسلام · 'master' فقط مدلِ مستر ·
 *        'quorum' اجماعِ چند مدلِ کاندید
 * $opts: ['quorum'=>int, 'product_id'=>int (فقط همین یک محصول)]
 */
function catfixRun(array $cn, string $mode, array $opts = [], ?array $cp = null): array {
    @ini_set('memory_limit', '512M');
    $t0 = microtime(true);
    $bs = $cn['basalam'] ?? [];
    if (empty($bs['token']) || empty($bs['vendor_id']))
        return ['ok' => false, 'error' => 'تنظیمات باسلام ناقص است'];
    $tk = (string)$bs['token']; $vid = (int)$bs['vendor_id'];
    /* v10.107: چندغرفه + اولویت یادگیری */
    $useLearn = !isset($opts['use_learn']) || !empty($opts['use_learn']);
    $learnFirst = !empty($opts['learn_first']) || !empty($opts['periodic']);
    $allVendors = !empty($opts['all_vendors']);
    $onlyVid = (int)($opts['vendor_id'] ?? 0);
    $learnedHits = 0;

    if ($allVendors && empty($opts['product_id'])) {
        $shops = function_exists('bslAllShops') ? bslAllShops($cn) : [];
        if (count($shops) > 1) {
            /* v10.129: checkpointِ چندغرفه‌ای یک‌جا برای همهٔ غرفه‌ها نیست.
               هر غرفه وضعیتِ مستقلِ خود (done_ids و شمارنده‌ها) دارد؛ بنابراین
               قطع وسطِ غرفهٔ دوم نه غرفهٔ اول را دوباره PATCH می‌کند و نه باعث
               می‌شود غرفهٔ دوم از اولِ فهرست شروع شود. */
            $seedAgg = is_array($cp['aggregate'] ?? null) ? $cp['aggregate'] : [];
            $agg = array_merge(['ok' => true, 'mode' => $mode, 'total' => 0, 'fixed' => 0, 'failed' => 0,
                    'no_ai' => 0, 'no_cat' => 0, 'skip_same' => 0, 'skip_tried' => 0,
                    'asked' => 0, 'cache_hits' => 0, 'learned_hits' => 0, 'items' => [],
                    'shops' => [], 'took' => 0, 'at' => time()], $seedAgg);
            $vendorState = is_array($cp['vendors'] ?? null) ? $cp['vendors'] : [];
            $addVendor = function (array $one, array $sh) use (&$agg): void {
                $vid0 = (int)($sh['vendor_id'] ?? 0);
                $nm0 = (string)($sh['shop_name'] ?? ('غرفهٔ ' . $vid0));
                $agg['shops'][] = ['vendor_id' => $vid0, 'shop_name' => $nm0,
                    'ok' => !empty($one['ok']), 'fixed' => (int)($one['fixed'] ?? 0),
                    'total' => (int)($one['total'] ?? 0), 'failed' => (int)($one['failed'] ?? 0),
                    'learned_hits' => (int)($one['learned_hits'] ?? 0)];
                foreach (['total','fixed','failed','no_ai','no_cat','skip_same','skip_tried','asked','cache_hits','learned_hits'] as $k)
                    $agg[$k] += (int)($one[$k] ?? 0);
                foreach ((array)($one['items'] ?? []) as $it) {
                    if (count($agg['items']) >= 500) break;
                    $it['shop_name'] = $nm0; $it['vendor_id'] = $vid0; $agg['items'][] = $it;
                }
                if (empty($one['ok']) && empty($agg['error'])) $agg['error'] = (string)($one['error'] ?? '');
            };
            $currentCp = is_array($cp) && (int)($cp['vendor_id'] ?? 0) > 0 ? $cp : null;
            foreach ($shops as $shopIndex => $sh) {
                if (!is_array($sh)) continue;
                $vid0 = (int)($sh['vendor_id'] ?? 0);
                $tok0 = trim((string)($sh['token'] ?? ''));
                if ($vid0 <= 0 || $tok0 === '') continue;
                $state0 = is_array($vendorState[(string)$vid0] ?? null) ? $vendorState[(string)$vid0] : [];
                if (!empty($state0['done'])) continue; // already included in aggregate
                $vendorCp = is_array($state0['checkpoint'] ?? null) ? $state0['checkpoint'] : null;
                if ($vendorCp === null && $currentCp !== null && (int)($currentCp['vendor_id'] ?? 0) === $vid0)
                    $vendorCp = $currentCp;
                $ov = $opts;
                $ov['all_vendors'] = false; $ov['vendor_id'] = $vid0;
                $ov['_shop_token'] = $tok0; $ov['_shop_name'] = (string)($sh['shop_name'] ?? '');
                $ov['_vendor_index'] = (int)$shopIndex;
                $ov['_parent_vendors'] = $vendorState;
                $ov['_parent_aggregate'] = $agg;
                catfixProgress(['log_add' => ['——— ' . ($sh['shop_name'] ?? ('غرفهٔ ' . $vid0)) . ' (#' . $vid0 . ') ———']]);
                $cn2 = $cn;
                $cn2['basalam'] = is_array($cn['basalam'] ?? null) ? $cn['basalam'] : [];
                $cn2['basalam']['token'] = $tok0; $cn2['basalam']['vendor_id'] = $vid0;
                $one = catfixRun($cn2, $mode, $ov, $vendorCp);
                $isDone = !empty($one['ok']) && empty($one['stopped']) && empty($one['partial']);
                if ($isDone) {
                    $addVendor($one, $sh);
                    $vendorState[(string)$vid0] = ['done' => true, 'checkpoint' => null,
                        'summary' => ['ok' => !empty($one['ok']), 'total' => (int)($one['total'] ?? 0),
                            'fixed' => (int)($one['fixed'] ?? 0), 'failed' => (int)($one['failed'] ?? 0),
                            'learned_hits' => (int)($one['learned_hits'] ?? 0)]];
                } else {
                    /* فرزند آخرین checkpoint خود را در فایل نوشته است؛ همان را
                       زیرِ شناسهٔ غرفه نگه می‌داریم تا resume دقیقاً همان‌جا باشد. */
                    $curCat = json_decode((string)@file_get_contents(CATFIX_PROGRESS_FILE), true);
                    $childCp = is_array($curCat['checkpoint'] ?? null) ? $curCat['checkpoint'] : null;
                    $vendorState[(string)$vid0] = ['done' => false, 'checkpoint' => $childCp,
                        'summary' => ['total' => (int)($one['total'] ?? 0), 'fixed' => (int)($one['fixed'] ?? 0),
                            'failed' => (int)($one['failed'] ?? 0)]];
                    $agg['partial'] = true;
                    $agg['has_more_slices'] = !empty($one['has_more_slices']);
                    $agg['stopped'] = !empty($one['stopped']);
                    break;
                }
                $parentCp = ['phase' => 'vendors', 'vendor_id' => 0, 'vendor_index' => $shopIndex + 1,
                    'vendors' => $vendorState, 'aggregate' => $agg, 'started_at' => (int)($cp['started_at'] ?? time())];
                catfixProgress(['checkpoint' => $parentCp]);
            }
            $agg['took'] = round(microtime(true) - $t0, 1);
            $agg['msg'] = 'اصلاح چندغرفه: ' . (int)$agg['fixed'] . ' از ' . (int)$agg['total']
                . ' · یادگیری ' . (int)$agg['learned_hits'];
            return $agg;
        }
    }
    if ($onlyVid > 0 && !empty($opts['_shop_token'])) {
        $tk = (string)$opts['_shop_token'];
        $vid = $onlyVid;
    } elseif ($onlyVid > 0 && function_exists('bslAllShops')) {
        foreach (bslAllShops($cn) as $sh) {
            if ((int)$sh['vendor_id'] === $onlyVid) {
                $tk = (string)$sh['token']; $vid = $onlyVid; break;
            }
        }
    }

    $vActiveChk = bslCheckVendorActiveStatus($tk, $vid);
    if (empty($vActiveChk['active'])) {
        $inactMsg = (string)($vActiveChk['reason'] ?? ('غرفه #' . $vid . ' غیرفعال است'));
        catfixProgress(['log_add' => ['⏸ ' . $inactMsg . ' — عبور سریع از این غرفه (پیشگیری از کد ۷۰۹۴)']]);
        return ['ok' => true, 'skipped_inactive_vendor' => true, 'mode' => $mode, 'total' => 0,
                'fixed' => (int)($cp['fixed'] ?? 0), 'failed' => (int)($cp['failed'] ?? 0),
                'no_ai' => (int)($cp['no_ai'] ?? 0), 'no_cat' => (int)($cp['no_cat'] ?? 0),
                'skip_same' => (int)($cp['skip_same'] ?? 0), 'skip_tried' => (int)($cp['skip_tried'] ?? 0),
                'asked' => (int)($cp['asked'] ?? 0), 'cache_hits' => (int)($cp['cache_hits'] ?? 0),
                'learned_hits' => (int)($cp['learned_hits'] ?? 0),
                'items' => is_array($cp['items'] ?? null) ? $cp['items'] : [],
                'took' => round(microtime(true) - $t0, 1), 'at' => time(), 'msg' => $inactMsg];
    }

    catfixProgress(['phase' => 'cats', 'log_add' => ['📂 دریافتِ درختِ دسته‌بندی‌های باسلام...']]);
    $cats = catfixFlatCats($tk);
    if (!$cats) return ['ok' => false, 'error' => 'دسته‌بندی‌ها بارگذاری نشد'];
    bslSetCatNameMap($cats);
    $leafCats = bslCatsTrueLeaves($cats);
    if (!$leafCats) {
        foreach ($cats as $c) if ((int)($c['level'] ?? 0) >= 2) $leafCats[] = $c;
    }
    if (!$leafCats) $leafCats = $cats;
    $trueLeafSet = [];
    foreach ($leafCats as $lc) {
        $lcid = (int)($lc['id'] ?? 0);
        if ($lcid > 0) $trueLeafSet[$lcid] = true;
    }
    catfixProgress(['log_add' => [count($cats) . ' دسته دریافت شد (' . count($leafCats) . ' دستهٔ برگِ واقعی بدون فرزند)']]);

    $onlyId = (int)($opts['product_id'] ?? 0);
    $pendingAiItems = ($onlyId > 0) ? [] : bslAiCatPendingLoad($onlyVid > 0 ? $vid : null, true);

    /* --- آماده‌سازیِ مدل‌ها در حالت‌های هوش مصنوعی (یا وقتی محصول کنارگذاشته‌شدهٔ ارسال داریم) --- */
    $cands = []; $providers = []; $master = null; $mp = null; $masterKey = ''; $net = []; $candKeys = [];
    $quorum = 2;
    $wantModels = in_array($mode, ['master', 'quorum', 'fallback'], true) || !empty($pendingAiItems);
    if ($wantModels) {
        $cands = aiCandidates();
        if (!$cands && in_array($mode, ['master', 'quorum', 'fallback'], true)) {
            return ['ok' => false, 'error' => 'هیچ مدل کاندیدی انتخاب نشده — اول در بخش 🤖 چند مدل کاندید اضافه کنید'];
        }
        if ($cands) {
            $providers = aiProvidersLoad();
            $masterKey = aiMasterKey();
            foreach ($cands as $c) if ($c['key'] === $masterKey) { $master = $c; break; }
            if ($master === null) $master = $cands[0];
            $mp = $providers[$master['provider']] ?? null;
            if ($mp === null && in_array($mode, ['master', 'quorum', 'fallback'], true)) {
                return ['ok' => false, 'error' => 'ارائه‌دهندهٔ مدل مستر یافت نشد'];
            }
            $net = aiNetCfg();
            $net['timeout'] = min(14, max(8, (int)($net['timeout'] ?? 12)));
            $candKeys = array_map(function ($c) { return $c['key']; }, $cands);
            $quorum = max(1, min(count($cands), (int)($opts['quorum'] ?? 2)));
            if (in_array($mode, ['master', 'quorum', 'fallback'], true)) {
                catfixProgress(['log_add' => ['🧠 مستر: ' . $master['providerName'] . ' / ' . $master['model']
                    . ($mode === 'quorum'
                       ? (' · اجماع با ' . aiFaNum(count($cands)) . ' مدل، حدنصابِ مرحلهٔ اول: ' . aiFaNum($quorum))
                       : ($mode === 'fallback'
                          ? (' · زنجیرهٔ پشتیبان — اگر مستر نداد، ' . aiFaNum(max(0, count($cands) - 1)) . ' کاندید به‌ترتیب')
                          : ' · حالتِ تک‌مدلی'))]]);
                if ($mode === 'quorum' && count($cands) < 2) {
                    $mode = 'master';
                    catfixProgress(['log_add' => ['ℹ️ فقط یک کاندید هست — به حالتِ تک‌مدلی برگشت']]);
                }
                if ($mode === 'fallback' && count($cands) < 2) {
                    catfixProgress(['log_add' => ['ℹ️ فقط یک کاندید هست — زنجیرهٔ پشتیبان عملاً حالتِ مستر است']]);
                }
            }
        }
    }

    /* v10.126: شناسه‌هایِ ازقبل‌پردازش‌شده برای رد شدن در واکشی/حلقه + ثبتِ چک‌پوینت */
    $cpDoneIds = [];
    if (is_array($cp)) {
        foreach ((array)($cp['done_ids'] ?? []) as $dx) {
            $dxs = trim((string)$dx);
            if ($dxs !== '' && $dxs !== '0') $cpDoneIds[] = is_numeric($dxs) ? (int)$dxs : $dxs;
        }
    }
    $cpDoneSet = [];
    foreach ($cpDoneIds as $dx) $cpDoneSet[(string)$dx] = true;

    /* --- فهرستِ محصولات --- */
    $partial = []; $fetchMeta = [];
    $hasMoreSlices = false;
    $startScanPage = max(1, (int)($cp['scan_page'] ?? 1));
    $curScanPageForCp = $startScanPage;
    $nextScanPage = $startScanPage;
    $maxLimit = max(0, (int)($opts['limit'] ?? 0));
    if ($onlyId > 0) {
        catfixProgress(['phase' => 'fetch', 'log_add' => ['🔎 دریافتِ محصول #' . $onlyId]]);
        $rg = bslReq($tk, 'GET', 'products/' . $onlyId);
        if (empty($rg['ok'])) $rg = bslReq($tk, 'GET', 'vendors/' . $vid . '/products/' . $onlyId);
        if (empty($rg['ok'])) return ['ok' => false, 'error' => 'محصول یافت نشد (HTTP ' . ($rg['code'] ?? '?') . ')'];
        $products = [(array)($rg['body'] ?? [])];
    } elseif ($maxLimit > 0 && $maxLimit <= 100) {
        $ppLim = min(100, max(50, $maxLimit));
        $retired3567 = function_exists('bslRetired3567Load') ? bslRetired3567Load() : [];
        catfixProgress(['phase' => 'fetch', 'log_add' => ['🔎 دریافتِ سریعِ ' . aiFaNum($maxLimit) . ' محصولِ ردشدهٔ تازه (وضعیت ۳۵۶۷)...']]);
        $products = [];
        for ($pgLim = 1; $pgLim <= 10 && count($products) < $maxLimit; $pgLim++) {
            $rLim = bslReq($tk, 'GET', 'vendors/' . $vid . '/products?page=' . $pgLim . '&per_page=' . $ppLim . '&statuses=3567');
            if (empty($rLim['ok'])) {
                if ($pgLim === 1) return ['ok' => false, 'error' => 'دریافت فهرست ردشده ناموفق (HTTP ' . ($rLim['code'] ?? '?') . ')'];
                break;
            }
            $rowsLim = array_values(array_filter(bslRowsOf($rLim['body']), 'is_array'));
            if (!$rowsLim) break;
            foreach ($rowsLim as $rwL) {
                $rwId = (int)($rwL['id'] ?? 0);
                if ($rwId > 0 && (isset($retired3567[$vid . ':' . $rwId]) || isset($cpDoneSet[(string)$rwId]))) continue;
                unset($rwL['vendor'], $rwL['category_list']);
                $products[] = $rwL;
                if (count($products) >= $maxLimit) break;
            }
            if (count($rowsLim) < $ppLim) break;
        }
        $fetchMeta = ['complete' => true, 'partial' => false, 'stopped' => false, 'page' => 1];
    } else {
        /* v10.467: واکشیِ برش‌محورِ ۲۰تایی (Streaming Slice) برای جلوگیری کامل از OOM در اجرای نامحدود */
        $retired3567 = function_exists('bslRetired3567Load') ? bslRetired3567Load() : [];
        $sliceSize = ($maxLimit > 100) ? min(30, $maxLimit) : 20;
        catfixProgress(['phase' => 'fetch', 'log_add' => ['🔎 دریافتِ برشِ جاریِ محصولاتِ ردشده (از صفحهٔ ' . aiFaNum($startScanPage) . ')...']]);
        $sliceMeta = [];
        $products = catfixFetchRejectedSlice($tk, $vid, $sliceSize, $startScanPage, $cpDoneSet, $retired3567, $sliceMeta);
        if (empty($products) && $startScanPage > 1 && empty($sliceMeta['stopped']) && empty($sliceMeta['http_error'])) {
            $startScanPage = 1;
            $curScanPageForCp = 1;
            $products = catfixFetchRejectedSlice($tk, $vid, $sliceSize, 1, $cpDoneSet, $retired3567, $sliceMeta);
        }
        $hasMoreSlices = !empty($sliceMeta['has_more']);
        $nextScanPage = max(1, (int)($sliceMeta['next_page'] ?? $startScanPage));
        if (!empty($sliceMeta['stopped'])) {
            $partial = ['partial' => true, 'reason' => 'stopped', 'page' => $nextScanPage];
            $fetchMeta = ['complete' => false, 'partial' => true, 'stopped' => true, 'page' => $nextScanPage];
        } elseif (!empty($sliceMeta['http_error']) && empty($products)) {
            $partial = ['partial' => true, 'reason' => 'http', 'page' => $nextScanPage, 'code' => (int)($sliceMeta['code'] ?? 0)];
            $fetchMeta = ['complete' => false, 'partial' => true, 'stopped' => false, 'reason' => 'http', 'page' => $nextScanPage];
        } else {
            $fetchMeta = ['complete' => true, 'partial' => false, 'stopped' => false, 'page' => $nextScanPage];
        }
        if (!empty($pendingAiItems) && !$hasMoreSlices) {
            $addedPending = 0;
            foreach ($pendingAiItems as $pq) {
                if (!is_array($pq)) continue;
                $qTok = trim((string)($pq['queue_id'] ?? ''));
                if ($qTok !== '' && isset($cpDoneSet[$qTok])) continue;
                if ($addedPending >= 20) { $hasMoreSlices = true; break; }
                $products[] = [
                    'id'                  => 0,
                    '_pending_ai_create'  => true,
                    '_queue_id'           => $qTok,
                    '_vendor_id'          => (int)($pq['vendor_id'] ?? $vid),
                    '_shop_name'          => (string)($pq['shop_name'] ?? ''),
                    'title'               => (string)($pq['title'] ?? ''),
                    'tried_cat_ids'       => array_values(array_map('intval', (array)($pq['tried_cat_ids'] ?? []))),
                    'profile_key'         => (string)($pq['profile_key'] ?? ''),
                    'profile_name'        => (string)($pq['profile_name'] ?? ''),
                    'product_key'         => (string)($pq['product_key'] ?? ''),
                    'bare'                => (string)($pq['bare'] ?? ''),
                    'forced_price_toman'  => (int)($pq['forced_price_toman'] ?? 0),
                    'product'             => is_array($pq['product'] ?? null) ? $pq['product'] : [],
                ];
                $addedPending++;
            }
            if ($addedPending > 0) {
                catfixProgress(['log_add' => ['🤖 ' . aiFaNum($addedPending) . ' محصول کنارگذاشته‌شده از ارسال (پس از رد دسته‌های دستی) برای تصحیح دسته و ایجاد با هوش مصنوعی اضافه شد']]);
            }
        }
        if ($maxLimit > 0 && count($products) > $maxLimit) {
            $products = array_slice($products, 0, $maxLimit);
            $hasMoreSlices = false;
        }
    }
    if (!empty($partial['partial']) || (!empty($fetchMeta) && empty($fetchMeta['complete']))) {
        $fetchCp = ['phase' => 'fetch', 'vendor_id' => $vid, 'scan_page' => $nextScanPage,
            'fetch_page' => (int)($fetchMeta['page'] ?? ($partial['page'] ?? 0)),
            'fetch_reason' => (string)($fetchMeta['reason'] ?? ($partial['reason'] ?? 'http')),
            'done_ids' => $cpDoneIds, 'fixed' => (int)($cp['fixed'] ?? 0),
            'failed' => (int)($cp['failed'] ?? 0), 'no_ai' => (int)($cp['no_ai'] ?? 0),
            'no_cat' => (int)($cp['no_cat'] ?? 0), 'skip_same' => (int)($cp['skip_same'] ?? 0),
            'skip_tried' => (int)($cp['skip_tried'] ?? 0), 'asked' => (int)($cp['asked'] ?? 0),
            'cache_hits' => (int)($cp['cache_hits'] ?? 0), 'learned_hits' => (int)($cp['learned_hits'] ?? 0),
            'idx' => (int)($cp['idx'] ?? 0), 'items' => is_array($cp['items'] ?? null) ? $cp['items'] : [],
            'started_at' => (int)($cp['started_at'] ?? time()),
            'vendor_index' => (int)($opts['_vendor_index'] ?? 0),
            'vendors' => is_array($opts['_parent_vendors'] ?? null) ? $opts['_parent_vendors'] : [],
            'aggregate' => is_array($opts['_parent_aggregate'] ?? null) ? $opts['_parent_aggregate'] : null];
        catfixProgress(['running' => false, 'done' => true, 'stale' => true, 'partial' => true,
            'phase' => 'fetch', 'checkpoint' => $fetchCp,
            'log_add' => ['⏸ فهرستِ محصولات کامل نشد — هیچ PATCHای انجام نشد و checkpoint حفظ شد']]);
        return ['ok' => false, 'partial' => true, 'stopped' => !empty($fetchMeta['stopped']),
            'error' => !empty($fetchMeta['stopped']) ? 'اصلاح با درخواست کاربر متوقف شد' : 'فهرست محصولات کامل دریافت نشد',
            'mode' => $mode, 'total' => count($products), 'fixed' => (int)($cp['fixed'] ?? 0),
            'failed' => (int)($cp['failed'] ?? 0), 'items' => is_array($cp['items'] ?? null) ? $cp['items'] : []];
    }
    $priorIdx = (int)($cp['idx'] ?? 0);
    $sliceCount = count($products);
    if ($sliceCount === 0) {
        /* v10.126: در ادامهٔ چک‌پوینت، جمعِ قبلی حفظ می‌شود (نه صفر) */
        return ['ok' => true, 'mode' => $mode, 'total' => $priorIdx,
                'fixed' => (int)($cp['fixed'] ?? 0), 'failed' => (int)($cp['failed'] ?? 0),
                'no_ai' => (int)($cp['no_ai'] ?? 0), 'no_cat' => (int)($cp['no_cat'] ?? 0),
                'skip_same' => (int)($cp['skip_same'] ?? 0), 'skip_tried' => (int)($cp['skip_tried'] ?? 0),
                'asked' => (int)($cp['asked'] ?? 0), 'cache_hits' => (int)($cp['cache_hits'] ?? 0),
                'learned_hits' => (int)($cp['learned_hits'] ?? 0),
                'items' => is_array($cp['items'] ?? null) ? $cp['items'] : [],
                'partial' => false,
                'took' => round(microtime(true) - $t0, 1), 'at' => time(),
                'msg' => $priorIdx > 0 ? ('همهٔ برش‌های این غرفه کامل شد (' . $priorIdx . ' مورد)') : 'هیچ محصولِ ردشده‌ای پیدا نشد'];
    }
    $total = $priorIdx + $sliceCount;
    catfixProgress(['phase' => 'run', 'total' => $total, 'current' => $priorIdx,
        'log_add' => ['🚀 شروعِ اصلاحِ برشِ جاری — ' . aiFaNum($sliceCount) . ' محصول'
            . ($priorIdx > 0 ? (' (انجام‌شدهٔ قبلی: ' . aiFaNum($priorIdx) . ')') : '')
            . ($hasMoreSlices ? ' · ادامه‌دار در برش‌های بعدی' : '')
            . ' · روش: ' . catfixModeLabel($mode)]]);

    /* v10.126: ادامهٔ واقعی — شمارنده‌ها و اقلامِ گزارش از چک‌پوینت می‌آیند */
    $fixed = (int)($cp['fixed'] ?? 0);
    $failed = (int)($cp['failed'] ?? 0);
    $noAi = (int)($cp['no_ai'] ?? 0);
    $noCat = (int)($cp['no_cat'] ?? 0);
    $skipSame = (int)($cp['skip_same'] ?? 0);
    $skipTried = (int)($cp['skip_tried'] ?? 0);
    $asked = (int)($cp['asked'] ?? 0);
    $cacheHits = (int)($cp['cache_hits'] ?? 0);
    $idx = $priorIdx;
    $items = is_array($cp['items'] ?? null) ? $cp['items'] : [];
    $learnedHits = (int)($cp['learned_hits'] ?? 0);
    $stopped = false;
    $fbRescued = 0;   // v10.71 (85): چند محصول با زنجیرهٔ پشتیبان نجات یافت
    $cpStartedAt = (is_array($cp) ? (int)($cp['started_at'] ?? 0) : 0);
    $allKnownShops = function_exists('bslAllShops') ? bslAllShops($cn) : [];
    $rawLoadedProfiles = function_exists('loadProfiles') ? loadProfiles() : [];
    /* v10.468: بازیافتِ همان بارگذاریِ واحدِ پروفایل‌ها برای catProfileResolver و ایندکس محلی (حذف ۳ بار json_decode سنگین در RAM) */
    $profOf = catProfileResolver('bsl', $rawLoadedProfiles);
    $profHits = (int)($cp['prof_hits'] ?? 0);
    $allLoadedProfiles = [];
    foreach ($rawLoadedProfiles as $_pkM => $_prM) {
        if (!is_array($_prM)) continue;
        $_metaOnly = $_prM;
        unset($_metaOnly['products'], $_metaOnly['logs'], $_metaOnly['history']);
        $allLoadedProfiles[$_pkM] = $_metaOnly;
    }
    $localIndex = bslBuildLocalProductIndex($rawLoadedProfiles, $products);
    unset($rawLoadedProfiles);
    if (function_exists('gc_collect_cycles')) gc_collect_cycles();
    $deadProviders401 = [];
    $sliceWallStart = microtime(true);
    $processedInSlice = 0;
    $cpSave = function () use (&$cpDoneIds, &$fixed, &$failed, &$noAi, &$noCat,
        &$skipSame, &$skipTried, &$asked, &$cacheHits, &$learnedHits, &$profHits,
        &$idx, &$items, $cpStartedAt, $opts, &$curScanPageForCp) {
        if (count($cpDoneIds) > 4000) $cpDoneIds = array_slice($cpDoneIds, -3000);
        catfixProgress(['checkpoint' => [
            'done_ids' => $cpDoneIds, 'scan_page' => $curScanPageForCp,
            'fixed' => $fixed, 'failed' => $failed,
            'no_ai' => $noAi, 'no_cat' => $noCat, 'skip_same' => $skipSame,
            'skip_tried' => $skipTried, 'asked' => $asked, 'cache_hits' => $cacheHits,
            'learned_hits' => $learnedHits, 'prof_hits' => $profHits, 'idx' => $idx,
            'items' => $items, 'started_at' => ($cpStartedAt > 0 ? $cpStartedAt : time()),
            'vendor_id' => (int)($opts['vendor_id'] ?? 0),
            'vendor_index' => (int)($opts['_vendor_index'] ?? 0),
            'vendors' => is_array($opts['_parent_vendors'] ?? null) ? $opts['_parent_vendors'] : [],
            'aggregate' => is_array($opts['_parent_aggregate'] ?? null) ? $opts['_parent_aggregate'] : null]]);
    };

    foreach ($products as $p) {
        if ($processedInSlice >= 1 && (microtime(true) - $sliceWallStart) >= 34.0) {
            $hasMoreSlices = true;
            $nextScanPage = $curScanPageForCp;
            catfixProgress(['log_add' => ['⏱ بودجهٔ زمانی برش جاری کامل شد (' . aiFaNum($processedInSlice) . ' محصول در این برش) — ادامهٔ خودکار در برش بعدی...']]);
            break;
        }
        $idx++;
        if (catfixStopRequested()) {
            $stopped = true;
            catfixProgress(['log_add' => ['⏹ توقف با درخواستِ کاربر — ' . aiFaNum($idx - 1) . ' محصول پردازش شده بود']]);
            break;
        }
        $isPendingCreate = !empty($p['_pending_ai_create']);
        $pId   = (int)($p['id'] ?? 0);
        $doneToken = $isPendingCreate ? trim((string)($p['_queue_id'] ?? '')) : ($pId > 0 ? (string)$pId : '');
        if ($doneToken !== '' && isset($cpDoneSet[$doneToken])) continue;
        $processedInSlice++;
        $pName = trim((string)($p['title'] ?? ($p['name'] ?? '')));
        $rev   = $p['revision'] ?? [];
        $pSku  = trim((string)($p['sku'] ?? ($rev['data']['sku'] ?? '')));
        $localMatch = $isPendingCreate ? null : bslFindLocalSourceProduct($pId, $pName, $localIndex, $pSku);
        if (!$isPendingCreate) {
            $healedPName = bslHealCorruptedLeadingQuestionTitle($pName, $localMatch);
            if ($healedPName !== $pName) {
                $pName = $healedPName;
                $p['title'] = $healedPName;
                $p['name'] = $healedPName;
            }
        }
        $curCat = $isPendingCreate ? 0 : bslProductCatId($p);
        $pendingTried = $isPendingCreate
            ? array_values(array_filter(array_map('intval', (array)($p['tried_cat_ids'] ?? [])), static fn($x) => $x > 0))
            : [];
        $push = function (string $status, string $msg, int $catId = 0, string $catName = '', int $overrideId = 0) use (&$items, $pId, $pName) {
            if (count($items) < 500)
                $items[] = ['id' => ($overrideId > 0 ? $overrideId : $pId), 'title' => $pName, 'status' => $status,
                            'cat_id' => $catId, 'cat_name' => $catName, 'msg' => $msg];
        };
        $cpMark = function () use (&$cpDoneIds, &$cpDoneSet, $doneToken, $isPendingCreate, $pId, &$cpSave): void {
            if ($doneToken !== '' && !isset($cpDoneSet[$doneToken])) {
                $cpDoneIds[] = $isPendingCreate ? $doneToken : $pId;
                $cpDoneSet[$doneToken] = true;
            }
            $cpSave();
        };
        catfixProgress(['current' => $idx, 'last_title' => mb_substr($pName, 0, 50, 'UTF-8'),
            'fixed' => $fixed, 'failed' => $failed, 'no_ai' => $noAi, 'no_cat' => $noCat,
            'skip_same' => $skipSame, 'skip_tried' => $skipTried, 'asked' => $asked,
            'learned_hits' => $learnedHits]);

        $cls = $isPendingCreate ? ['skip_modesty' => false, 'needs_category' => true, 'needs_image_refresh' => false] : bslClassifyRejectionReasons($p, $cats);

        if (!$isPendingCreate) {
            // ۱) استثنای صریحِ قوانین شئونات اسلامی در تصویر (۶۴۵۶، ۵۰۳۱، ۶۴۱۹): عبور بدون هیچ دستکاری
            if (!empty($cls['skip_modesty'])) {
                $skipSame++;
                $push('skipped', 'ردشده به‌دلیل قوانین شئونات تصویری — عبور بدون دستکاری', $curCat, bslCatNameById($curCat));
                catfixProgress(['log_add' => ['⏭️ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — شئونات تصویری (بدون دستکاری)']]);
                $cpMark();
                continue;
            }

            // ۲) اگر محصول ناموجود است (کد ۷۰۹۳ و در منبع هم ناموجود است)، بدون سوزاندن سهمیهٔ AI فوراً بایگانی شود
            $revDataQuick = is_array($rev['data'] ?? null) ? $rev['data'] : [];
            $origInvQuick = (int)($revDataQuick['inventory'] ?? ($revDataQuick['stock'] ?? ($p['inventory'] ?? 0)));
            $realInvQuick = (!empty($localMatch['product']) && is_array($localMatch['product']))
                ? effectiveStock($localMatch['product'], max(1, (int)($bs['stock'] ?? 10)))
                : $origInvQuick;
            if ($realInvQuick <= 0) {
                $archQuick = bslApplyCategoryChangeOrRecreate($tk, $vid, $p, max(1, $curCat), $cn, $localMatch, false);
                if (!empty($archQuick['ok'])) {
                    $fixed++;
                    $push('fixed', (string)($archQuick['msg'] ?? 'محصول ناموجود بایگانی شد'), $curCat, bslCatNameById($curCat));
                    catfixProgress(['log_add' => ['📦 [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — ناموجود بود؛ بایگانی شد (رفع کد ۷۰۹۳)']]);
                    $cpMark();
                } else {
                    $failed++;
                    $push('failed', (string)($archQuick['error'] ?? 'بایگانی کالای ناموجود ناموفق'), $curCat, bslCatNameById($curCat));
                    $cpSave();
                }
                usleep(250000);
                continue;
            }

            // ۳) اگر دستهٔ فعلی سالم و بدون تضاد است و علتِ رد متن/عنوان/بارکد/قیمت/کیفیتِ عکس/موجودی بوده → اصلاحِ مستقیم بدون نیاز به AI
            if (empty($cls['needs_category']) && $curCat > 0) {
                $curCatName0 = bslCatNameById($curCat);
                $healRes = bslApplyCategoryChangeOrRecreate($tk, $vid, $p, $curCat, $cn, $localMatch, !empty($cls['needs_image_refresh']));
                if (!empty($healRes['ok'])) {
                    $fixed++;
                    $push('fixed', (string)($healRes['msg'] ?? 'اصلاح محتوا/موجودی/تصویر و ارسال مجدد'), $curCat, $curCatName0, (int)($healRes['id'] ?? $pId));
                    catfixProgress(['log_add' => ['✅🛠️ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8')
                        . ' — ' . (string)($healRes['msg'] ?? 'اصلاح محتوا/استاندارد') . ' (کدها: ' . implode(',', (array)($cls['codes'] ?? [])) . ')']]);
                    $cpMark();
                } else {
                    $failed++;
                    $errHeal = (string)($healRes['error'] ?? 'اصلاح ناموفق');
                    $push('failed', $errHeal, $curCat, $curCatName0);
                    catfixProgress(['log_add' => ['❌ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — ' . mb_substr($errHeal, 0, 80, 'UTF-8')]]);
                    $cpSave();
                }
                usleep(350000);
                continue;
            }
        }

        $itemMode = ($isPendingCreate && $mode === 'ai_text') ? ($mp !== null ? 'fallback' : 'ai_text') : $mode;

        if ($pName === '' && $itemMode !== 'ai_text') {
            $failed++; $push('failed', 'عنوانِ محصول خالی است');
            catfixProgress(['log_add' => ['❌ [' . $idx . '/' . $total . '] عنوانِ خالی — #' . $pId]]);
            $cpSave();
            continue;
        }

        $catId = 0; $catName = ''; $winKeys = []; $askedItemKeys = [];

        /* v10.107 + v10.466: اول حافظهٔ یادگیری (فقط اگر برگ واقعی باشد، رد نشده باشد و تضاد معنایی نداشته باشد) */
        if ($useLearn && $pName !== '' && function_exists('catLearnLookup')) {
            $lid = (int)catLearnLookup($pName);
            if ($lid > 0 && $lid !== $curCat && isset($trueLeafSet[$lid])
                && !in_array($lid, $pendingTried, true)
                && !bslCategoryHasSemanticClash($pName, $lid, $cats)) {
                $lname = '';
                if (function_exists('bslCatName')) $lname = (string)bslCatName($lid);
                if ($lname === '' && !empty($cats)) {
                    foreach ($cats as $c) {
                        if ((int)($c['id'] ?? 0) === $lid) { $lname = (string)($c['title'] ?? $c['name'] ?? ''); break; }
                    }
                }
                if ($lname === '' || !bslIsBannedCategoryTitle($lname)) {
                    $catId = $lid;
                    $catName = $lname !== '' ? $lname : ('#' . $lid);
                    $learnedHits++;
                    if ($learnFirst || $mode === 'learned') {
                        goto CATFIX_AFTER_AI_PICK;
                    }
                }
            }
        }

        if ($itemMode === 'ai_text') {
            if ($isPendingCreate) {
                $detId = autoMatchBslCategory($pName, $cats);
                if ($detId > 0 && isset($trueLeafSet[$detId]) && !in_array($detId, $pendingTried, true)) {
                    $catId = $detId;
                    $catName = bslCatNameById($catId);
                    goto CATFIX_AFTER_AI_PICK;
                }
                $noAi++; $push('no_ai', 'محصول هنوز در باسلام ساخته نشده؛ برای تصحیح دسته یک مدل هوش مصنوعی در بخش 🤖 فعال کنید');
                catfixProgress(['log_add' => ['⚠️ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — برای محصولِ کنارگذاشته‌شده مدل AI فعال نیست']]);
                $cpSave();
                continue;
            }
            $aiText = trim((string)($rev['metadata']['description'] ?? ''));
            foreach ((array)($rev['rejection_reasons'] ?? []) as $rr) {
                $d = trim((string)($rr['description'] ?? ''));
                if ($d !== '' && mb_strlen($d, 'UTF-8') > 5) $aiText .= ($aiText ? ' ' : '') . $d;
            }
            $pickedFromText = 0;
            if ($aiText !== '') {
                $res = extractAiCategoryFromTextEx($aiText, $cats);
                $pickedFromText = (int)($res['catId'] ?? 0);
                if ($pickedFromText > 0) $pickedFromText = findLeafCategory($pickedFromText, $cats);
                if ($pickedFromText > 0 && ($pickedFromText === $curCat || bslCategoryHasSemanticClash($pName, $pickedFromText, $cats))) {
                    $pickedFromText = 0;
                }
            }
            if ($pickedFromText <= 0) {
                // v10.466: وقتی کارشناس دستهٔ پیشنهادی ننوشته (مثلاً فقط کد ۶۰۴۶ یا دستهٔ ممنوع ۵۵۴/۲۳۱ بوده)، از تطبیقگر برگِ معنایی استفاده کن
                $detLeaf = autoMatchBslCategory($pName, $cats);
                if ($detLeaf > 0 && $detLeaf !== $curCat && isset($trueLeafSet[$detLeaf]) && !catTriedHas($pId, $detLeaf)) {
                    $pickedFromText = $detLeaf;
                }
            }
            if ($pickedFromText <= 0) {
                $noCat++; $push('no_cat', 'از متنِ بررسی یا تطبیقگرِ برگ دسته‌ای استخراج نشد');
                catfixProgress(['log_add' => ['⚠️ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — دستهٔ جایگزین درنیامد']]);
                $cpSave();
                continue;
            }
            $catId = $pickedFromText;
            $catName = bslCatNameById($catId);
        } else {
            $exclude = $isPendingCreate ? $pendingTried : catTriedExclude($pId, $curCat);
            $triedInfo = [];
            if ($isPendingCreate) {
                foreach ($pendingTried as $tcid) {
                    $triedInfo[] = ['id' => (int)$tcid, 'name' => bslCatNameById((int)$tcid)];
                }
            } else {
                $trRow = catTriedRow($pId);
                foreach ((array)($trRow['tried'] ?? []) as $tcid => $tinfo)
                    $triedInfo[] = ['id' => (int)$tcid, 'name' => (string)($tinfo['name'] ?? '')];
            }
            // اگر یادداشتِ کارشناسِ باسلام خودش دستهٔ دقیق را گفته، قبل از مصرف توکن AI بررسی شود
            if (!$isPendingCreate) {
                $modNote = trim((string)($rev['metadata']['description'] ?? ''));
                if ($modNote !== '') {
                    $modEx = extractAiCategoryFromTextEx($modNote, $cats);
                    $modCid = (int)($modEx['catId'] ?? 0);
                    if ($modCid > 0) $modCid = findLeafCategory($modCid, $cats);
                    if ($modCid > 0 && $modCid !== $curCat && isset($trueLeafSet[$modCid])
                        && !in_array($modCid, $exclude, true) && !bslCategoryHasSemanticClash($pName, $modCid, $cats)) {
                        $catId = $modCid;
                        $catName = bslCatNameById($catId);
                        catfixProgress(['log_add' => ['📌 [' . $idx . '/' . $total . '] دستهٔ پیشنهادیِ کارشناسِ باسلام: ' . $catName . ' (#' . $catId . ')']]);
                        goto CATFIX_AFTER_AI_PICK;
                    }
                }
            }
            $pProf = $isPendingCreate && trim((string)($p['profile_name'] ?? '')) !== ''
                ? trim((string)$p['profile_name'])
                : $profOf($pId, $pName);
            $pHint = aiCatProfileHint($pProf);
            if ($pProf !== '') $profHits++;
            $ok = false; $err = '';
            if ($itemMode === 'quorum') {
                $liveCands = array_values(array_filter($cands, static function ($c0) use (&$deadProviders401) {
                    return empty($deadProviders401[(string)($c0['provider'] ?? '')]);
                }));
                if ($liveCands) {
                    $con = aiCatConsensus($liveCands, $providers, $pName, $cats, $leafCats, $exclude, $net,
                        ['quorum' => min($quorum, count($liveCands)), 'tried_info' => $triedInfo, 'profile_hint' => $pHint]);
                    $asked += (int)($con['asked'] ?? 0);
                    if (!empty($con['from_cache'])) $cacheHits++;
                    $catId   = (int)($con['category_id'] ?? 0);
                    $catName = (string)($con['category_name'] ?? '');
                    $ok      = !empty($con['ok']);
                    $err     = (string)($con['error'] ?? '');
                    $winKeys = (array)($con['winner_keys'] ?? []);
                    foreach ((array)($con['per_model'] ?? []) as $_pmIt) {
                        $_pmKey = trim((string)($_pmIt['key'] ?? ''));
                        if ($_pmKey !== '' && !in_array($_pmKey, $askedItemKeys, true)) $askedItemKeys[] = $_pmKey;
                    }
                    if ($ok) catfixProgress(['log_add' => ['🗳️ [' . $idx . '/' . $total . '] اجماع: ' . $catName
                        . ' (' . $catId . ') — ' . aiFaNum((int)($con['agreement'] ?? 0)) . ' رأی از '
                        . aiFaNum((int)($con['asked'] ?? 0)) . ' مدل' . (!empty($con['from_cache']) ? ' · از کش ⚡' : '')
                        . ($pProf !== '' ? ' · بافت: ' . $pProf : '')]]);
                }
            } elseif ($itemMode === 'fallback' || $itemMode === 'master') {
                $catListPrompt = aiCatListBuild($leafCats, $exclude, 24000, $pName);
                $masterProvId = (string)($master['provider'] ?? '');
                if ($mp !== null && empty($deadProviders401[$masterProvId])) {
                    catfixProgress([]);
                    $res = aiCandidateCategory($mp, $master['model'], $pName, $cats, $leafCats,
                        $catListPrompt, $net, $exclude, $triedInfo, $pHint);
                    $asked++;
                    if ($masterKey !== '' && !in_array($masterKey, $askedItemKeys, true)) $askedItemKeys[] = $masterKey;
                    $catId   = (int)($res['category_id'] ?? 0);
                    $catName = (string)($res['category_name'] ?? '');
                    $ok      = !empty($res['ok']);
                    $err     = (string)($res['error'] ?? '');
                    $winKeys = [$masterKey];
                    if (!$ok && !in_array($masterProvId, ['openrouter', 'opencode'], true)
                        && preg_match('/401|402|Unauthorized|invalid_api_key|insufficient_quota|insufficient credits|depleted/i', $err)) {
                        $deadProviders401[$masterProvId] = true;
                        catfixProgress(['log_add' => ['⚡ کلیدِ ارائه‌دهندهٔ «' . ($master['providerName'] ?? $masterProvId) . '» خطای احراز هویت داد — سوئیچ خودکار به کاندیدهای دیگر']]);
                    }
                } else {
                    $err = 'ارائه‌دهندهٔ مستر غیرفعال (۴۰۱)';
                }
                if ((!$ok || $catId <= 0) && count($cands) > 1) {
                    $fbChain = '🛟 زنجیرهٔ پشتیبان — مستر: ' . ($err !== '' ? $err : 'دستهٔ معتبر نداد');
                    $fbTries = 0;
                    $maxFbTries = 8;
                    $skipProvThisItem = [];
                    foreach ($cands as $fc) {
                        if (catfixStopRequested() || $fbTries >= $maxFbTries) break;
                        if ($fbTries >= 1 && (microtime(true) - $sliceWallStart) >= 42.0) break;
                        $fcProv = (string)($fc['provider'] ?? '');
                        if (($fc['key'] ?? '') === $masterKey || !empty($deadProviders401[$fcProv]) || !empty($skipProvThisItem[$fcProv])) continue;
                        $fcp = $providers[$fcProv] ?? null;
                        if ($fcp === null) continue;
                        $fbTries++;
                        catfixProgress([]);
                        $fres = aiCandidateCategory($fcp, $fc['model'], $pName, $cats, $leafCats,
                            $catListPrompt, $net, $exclude, $triedInfo, $pHint);
                        $asked++;
                        $fcKey = trim((string)($fc['key'] ?? ''));
                        if ($fcKey !== '' && !in_array($fcKey, $askedItemKeys, true)) $askedItemKeys[] = $fcKey;
                        $fErr = (string)($fres['error'] ?? '');
                        if (empty($fres['ok'])) {
                            if (!in_array($fcProv, ['openrouter', 'opencode'], true)
                                && preg_match('/401|402|Unauthorized|invalid_api_key|insufficient_quota|insufficient credits|depleted/i', $fErr)) {
                                $deadProviders401[$fcProv] = true;
                            } elseif (preg_match('/429|rate|quota|timeout|timed out|502|503|504|connect/i', $fErr)) {
                                $skipProvThisItem[$fcProv] = true;
                            }
                        }
                        if (!empty($fres['ok']) && (int)($fres['category_id'] ?? 0) > 0) {
                            $catId   = (int)$fres['category_id'];
                            $catName = (string)($fres['category_name'] ?? '');
                            $ok      = true;
                            $err     = '';
                            $winKeys = [$fcKey];
                            $fbChain .= ' → ' . ($fc['providerName'] ?? $fcProv) . '/' . $fc['model'] . ' ✓';
                            $fbRescued++;
                            break;
                        }
                        $fbChain .= ' → ' . ($fc['providerName'] ?? $fcProv) . '/' . $fc['model'] . ' ✗';
                    }
                    catfixProgress(['log_add' => [$fbChain]]);
                }
            }
            // اگر AI به‌خاطر خطای کلید/سهمیه پاسخ نداد، تطبیقگرِ برگِ معنایی را امتحان کن
            if (!$ok || $catId <= 0 || bslCategoryHasSemanticClash($pName, $catId, $cats)) {
                $detFallback = autoMatchBslCategory($pName, $cats);
                if ($detFallback > 0 && $detFallback !== $curCat && isset($trueLeafSet[$detFallback]) && !in_array($detFallback, $exclude, true)) {
                    $catId   = $detFallback;
                    $catName = bslCatNameById($catId);
                    $ok      = true;
                    $winKeys = [];
                    catfixProgress(['log_add' => ['🧭 [' . $idx . '/' . $total . '] انتخاب با تطبیقگرِ برگِ معنایی: ' . $catName . ' (#' . $catId . ')']]);
                }
            }
            if (!$ok || $catId <= 0) {
                $noCat++;
                $m = ($itemMode === 'quorum' ? 'اجماع به دستهٔ تازه‌ای نرسید'
                    : ($itemMode === 'fallback' ? 'زنجیرهٔ پشتیبان به دستهٔ تازه‌ای نرسید' : 'مستر دستهٔ معتبری نداد'))
                     . ($err !== '' ? ' — ' . $err : '');
                $push('no_cat', $m);
                catfixProgress(['log_add' => ['⚠️ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — ' . $m]]);
                $cpSave();
                continue;
            }
        }

        CATFIX_AFTER_AI_PICK:

        if ($isPendingCreate) {
            if (in_array($catId, $pendingTried, true)) {
                $skipTried++;
                $push('skipped', '«' . $catName . '» قبلاً رد شده بود', $catId, $catName);
                catfixProgress(['log_add' => ['⏭️ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — دستهٔ #' . $catId . ' قبلاً رد شده']]);
                $cpSave();
                continue;
            }
            $targetVid = (int)($p['_vendor_id'] ?? $vid);
            if ($targetVid <= 0) $targetVid = $vid;
            $targetShop = null;
            foreach ($allKnownShops as $shX) {
                if ((int)($shX['vendor_id'] ?? 0) === $targetVid) { $targetShop = $shX; break; }
            }
            if (!$targetShop) {
                $targetShop = ['vendor_id' => $targetVid, 'token' => $tk, 'shop_name' => (string)($p['_shop_name'] ?? ('غرفهٔ ' . $targetVid))];
            }
            $profKeyCreate = trim((string)($p['profile_key'] ?? ''));
            $profCreate = ($profKeyCreate !== '' && isset($allLoadedProfiles[$profKeyCreate])) ? $allLoadedProfiles[$profKeyCreate] : null;
            $prodPayload = is_array($p['product'] ?? null) ? $p['product'] : [];
            if (empty($prodPayload['title'])) $prodPayload['title'] = $pName;
            $prodPayload['bsl_category_id'] = $catId;
            if ($profKeyCreate !== '') {
                bslSaveAiCategoryToProfile($profKeyCreate, (string)($p['product_key'] ?? ''), $pName, $catId);
            }
            $bsCfg = is_array($cn['basalam'] ?? null) ? $cn['basalam'] : [];
            $upOpts = [
                'profile'            => $profCreate,
                'profile_key'        => $profKeyCreate,
                'basalam_cfg'        => $bsCfg,
                'round'              => (int)($bsCfg['price_round'] ?? 0),
                'stock'              => (int)($bsCfg['stock'] ?? 10),
                'preparation_days'   => (int)($bsCfg['preparation_days'] ?? 3),
                'weight'             => (int)($bsCfg['weight'] ?? 500),
                'package_weight'     => (int)($bsCfg['package_weight'] ?? 0),
                'category_id'        => $catId,
                'ai_cat_direct'      => true,
                'find_deep_scan'     => false,
                'forced_price_toman' => max(0, (int)($p['forced_price_toman'] ?? 0)),
            ];
            $upRes = bslUpsertToShop($prodPayload, $targetShop, $upOpts);
            if (!empty($upRes['ok']) && (int)($upRes['id'] ?? 0) > 0) {
                $createdId = (int)$upRes['id'];
                $fixed++;
                if (count($askedItemKeys) >= 2 && !empty($winKeys)) {
                    foreach (array_unique($winKeys) as $wk) {
                        if ($wk !== '') aiVoteRecord('category', $pName, $wk, $askedItemKeys);
                    }
                }
                catLearnRecord($pName, $catId, $catName);
                bslClearAiCategoryFixPending($targetVid, (string)($p['product_key'] ?? ''), $pName, [
                    'cat_id'    => $catId,
                    'cat_name'  => $catName,
                    'remote_id' => $createdId,
                ]);
                $bareKey = trim((string)($p['bare'] ?? ''));
                if ($bareKey !== '' && function_exists('matrixResultPatchRow')) {
                    matrixResultPatchRow($bareKey, [
                        'fix_pending'      => '',
                        'fix_pending_kind' => '',
                        'shops'            => [$targetVid => [
                            'id'        => $createdId,
                            'tone'      => 'ok',
                            'shop_name' => (string)($targetShop['shop_name'] ?? ''),
                            'title'     => $pName,
                        ]],
                    ]);
                }
                $push('fixed', 'دسته با AI تصحیح و محصول در غرفه #' . $targetVid . ' ثبت شد (#' . $createdId . ')', $catId, $catName, $createdId);
                catfixProgress(['log_add' => ['✅🤖 [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8')
                    . ' → ' . $catName . ' (#' . $catId . ') · ثبت شد #' . $createdId]]);
                $cpMark();
            } else {
                $failed++;
                $errUp = (string)($upRes['error'] ?? 'ایجاد محصول ناموفق');
                if (is_array($upRes['last_response'] ?? null) && bslIsCategoryError($upRes['last_response'])) {
                    bslQueueForAiCategoryFix($prodPayload, [
                        'vendor_id'         => $targetVid,
                        'shop_name'         => (string)($targetShop['shop_name'] ?? ''),
                        'profile_key'       => $profKeyCreate,
                        'profile_name'      => (string)($p['profile_name'] ?? ''),
                        'product_key'       => (string)($p['product_key'] ?? ''),
                        'bare'              => (string)($p['bare'] ?? ''),
                        'title'             => $pName,
                        'tried_cat_ids'     => array_merge($pendingTried, [$catId]),
                        'forced_price_toman'=> (int)($p['forced_price_toman'] ?? 0),
                        'error'             => $errUp,
                        'step'              => 'ai_cat_create',
                    ]);
                }
                $push('failed', 'ایجاد پس از انتخاب دسته ناموفق: ' . $errUp, $catId, $catName);
                catfixProgress(['log_add' => ['❌🤖 [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8')
                    . ' — ' . mb_substr($errUp, 0, 90, 'UTF-8')]]);
                $cpSave();
            }
            usleep(500000);
            continue;
        }

        if ($curCat > 0 && $catId === $curCat) {
            $skipSame++;
            catTriedRecord($pId, $catId, $catName, $mode, 'skipped', $pName, $curCat);
            $push('skipped', 'پیشنهاد همان دستهٔ فعلی است («' . $catName . '»)', $catId, $catName);
            catfixProgress(['log_add' => ['⏭️ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — همان دستهٔ فعلی']]);
            $cpMark();
            continue;
        }
        if (catTriedHas($pId, $catId)) {
            $skipTried++;
            catTriedRecord($pId, $catId, $catName, $mode, 'skipped', $pName, $curCat);
            $push('skipped', '«' . $catName . '» قبلاً برای این محصول امتحان و رد شده', $catId, $catName);
            catfixProgress(['log_add' => ['⏭️ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8') . ' — «' . $catName . '» قبلاً امتحان شده']]);
            $cpMark();
            continue;
        }

        /* --- v10.466: اعمالِ تغییر دسته + محتوا (PATCH در صورت مجاز بودن، یا بایگانی + ایجادِ جایگزینِ تمیز در صورت قفلِ ۴۲۲) --- */
        $r2 = bslApplyCategoryChangeOrRecreate($tk, $vid, $p, $catId, $cn, $localMatch, !empty($cls['needs_image_refresh']));
        if (!empty($r2['ok'])) {
            $fixed++;
            $appliedId = (int)($r2['id'] ?? $pId);
            if ($mode !== 'ai_text' && count($askedItemKeys) >= 2 && !empty($winKeys)) {
                foreach (array_unique($winKeys) as $wk) {
                    if ($wk !== '') aiVoteRecord('category', $pName, $wk, $askedItemKeys);
                }
            }
            if (($r2['action'] ?? '') !== 'archived') {
                catLearnRecord($pName, $catId, $catName);
            }
            catTriedRecord($pId, $catId, $catName, $mode, 'applied', $pName, $curCat);
            $actNote = (string)($r2['msg'] ?? 'اصلاح شد و به بررسیِ مجدد رفت');
            $push('fixed', $actNote, $catId, $catName, $appliedId);
            catfixProgress(['log_add' => ['✅ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8')
                . ' → ' . $catName . ' (#' . $catId . ')'
                . (($r2['action'] ?? '') === 'recreated' ? (' · جایگزین #' . $appliedId) : '')]]);
            $cpMark();
        } else {
            $failed++;
            $err = (string)($r2['error'] ?? 'اصلاح ناموفق');
            $push('failed', $err, $catId, $catName);
            catfixProgress(['log_add' => ['❌ [' . $idx . '/' . $total . '] ' . mb_substr($pName, 0, 40, 'UTF-8')
                . ' — ' . mb_substr($err, 0, 90, 'UTF-8')]]);
            $cpSave();
        }
        usleep(450000);
    }

    if (!$stopped && $hasMoreSlices) {
        $curScanPageForCp = $nextScanPage;
        $cpSave();
    }

    $savedMsg = '';
    if ($mode === 'quorum' && $total > 0 && $cands) {
        $maxCalls = $total * count($cands);
        $saved = $maxCalls - $asked;
        if ($saved > 0) $savedMsg = ' | صرفه‌جویی: ' . aiFaNum($saved) . ' فراخوانی از ' . aiFaNum($maxCalls);
        if ($cacheHits > 0) $savedMsg .= ' | از کش: ' . aiFaNum($cacheHits);
    }
    // v10.36 (۴۹ه): سهمِ بافتِ پروفایل هم در خلاصه دیده شود
    if ($mode !== 'ai_text' && $profHits > 0)
        $savedMsg .= ' | با بافتِ پروفایل: ' . aiFaNum($profHits);
    $msg = '✅ اصلاح: ' . $fixed . ' | دسته نیافت: ' . $noCat
         . ($mode === 'ai_text' ? (' | بدون متنِ AI: ' . $noAi) : '')
         . ' | تکراری/همان دسته: ' . ($skipSame + $skipTried)
         . ' | ناموفق: ' . $failed . ' (از ' . $total . ')' . $savedMsg
         . (($mode === 'fallback' && $fbRescued > 0) ? (' | نجات‌یافته با زنجیره: ' . $fbRescued) : '');

    return ['ok' => true, 'mode' => $mode, 'total' => $total, 'processed' => $idx,
            'fixed' => $fixed, 'failed' => $failed, 'no_ai' => $noAi, 'no_cat' => $noCat,
            'skip_same' => $skipSame, 'skip_tried' => $skipTried,
            'skipped' => $skipSame + $skipTried, 'asked' => $asked, 'cache_hits' => $cacheHits, 'learned_hits' => $learnedHits,
            'stopped' => $stopped, 'partial' => (!empty($partial['partial']) || (!$stopped && $hasMoreSlices)),
            'has_more_slices' => (!$stopped && $hasMoreSlices),
            /* v10.36 (۴۹ه): چند محصول توانستند بافتِ پروفایل بگیرند — اگر
               این عدد صفر باشد یعنی نه دفترچه شناسه‌ای دارد نه پسوندی
               تعریف شده، و کاربر باید بداند چرا بافت اثری نداشته. */
            'profile_hints' => $profHits,
            'items' => $items, 'took' => round(microtime(true) - $t0, 1), 'at' => time(),
            'msg' => $msg];
}

/* =====================================================================
 *  v10.03 (۱۷): محیطِ آزمایشیِ «ایجنتِ مدیریت محصولات»
 *
 *  ایده: به‌جای اینکه برای هر کار یک دکمه و یک تابعِ جدا بنویسیم، به مدل
 *  یک جعبه‌ابزار می‌دهیم و می‌گذاریم خودش تصمیم بگیرد کدام ابزار را با چه
 *  ورودی صدا بزند. این همان «فراخوانیِ ابزار» (tool calling) است که
 *  مدل‌های Mistral / Gemini / Groq / GPT-OSS و... پشتیبانی می‌کنند.
 *
 *  چرخهٔ کار:
 *    ۱) پیامِ کاربر + فهرستِ ابزارها (JSON Schema) به مدل فرستاده می‌شود.
 *    ۲) مدل به‌جای متن، یک یا چند tool_call برمی‌گرداند.
 *    ۳) ما ابزار را واقعاً اجرا می‌کنیم و نتیجه را با نقشِ "tool" و
 *       همان tool_call_id به مدل پس می‌دهیم.
 *    ۴) تکرار تا وقتی مدل «تمام شد» بگوید یا به سقفِ گام‌ها برسیم.
 *
 *  سه حالتِ اجرا (مهم‌ترین بخشِ «آزمایشی بودن»):
 *    sim  — هیچ تماسِ شبکه‌ای؛ دادهٔ نمونهٔ داخلی. برای دیدنِ رفتارِ مدل.
 *    dry  — دادهٔ واقعی خوانده می‌شود، ولی هیچ نوشتنی انجام نمی‌شود.
 *    live — واقعی؛ قیمت و موجودی واقعاً در باسلام/ووکامرس نوشته می‌شود.
 *
 *  پیش‌فرض همیشه dry است تا یک اشتباهِ مدل به فروشگاه آسیب نزند.
 * ===================================================================== */

/** پیشرفتِ زندهٔ ایجنت (همان الگوی dedupProgress) */
function agentProgress(array $patch): void {
    $cur = localTaskStateRead(AGENT_PROGRESS_FILE, []);
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) $log[] = ['t' => time(), 'm' => (string)$l];
        if (count($log) > 500) $log = array_slice($log, -500);
        unset($patch['log_add']);
    }
    $steps = is_array($cur['steps'] ?? null) ? $cur['steps'] : [];
    if (isset($patch['step_add'])) {
        foreach ((array)$patch['step_add'] as $s) $steps[] = $s;
        if (count($steps) > 300) $steps = array_slice($steps, -300);
        unset($patch['step_add']);
    }
    /* v10.26 (۳۹ب): جریانِ «گفتگو». تا اینجا فقط یک لاگِ خلاصه داشتیم
       («گامِ ۳ — پرسش از مدل…») که نمی‌گفت مدل واقعاً چه گفت و ابزار چه
       برگرداند. حالا خودِ پیام‌ها هم ذخیره می‌شوند تا کاربر بتواند زنده
       ببیند چه در جریان است — به‌ویژه در اجراهای چنددقیقه‌ای. */
    $convo = is_array($cur['convo'] ?? null) ? $cur['convo'] : [];
    if (isset($patch['convo_add'])) {
        foreach ((array)$patch['convo_add'] as $c) {
            if (!is_array($c)) continue;
            $c['t'] = time();
            $convo[] = $c;
        }
        if (count($convo) > 240) $convo = array_slice($convo, -240);
        unset($patch['convo_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log; $cur['steps'] = $steps; $cur['convo'] = $convo; $cur['ts'] = time();
    writeProgress(AGENT_PROGRESS_FILE, $cur);
}

/* =====================================================================
 *  v10.26 (۳۹ب): ابزارهای مشترکِ «گفتگوی زنده»
 *  ---------------------------------------------------------------------
 *  هر دو ایجنت (مدیریتِ محصولات و کشفِ سلکتور) و کارهای اتوماسیون از
 *  همین دو تابع استفاده می‌کنند تا شکلِ پیام‌ها یکی باشد و فرانت فقط یک
 *  رندرکننده لازم داشته باشد.
 *
 *  ساختارِ هر پیام:
 *    ['role' => system|user|assistant|tool, 'text' => '…',
 *     'calls' => [ ['name'=>..,'args'=>'json'], … ],   (فقط assistant)
 *     'name'  => 'نامِ ابزار', 'ok' => true|false]     (فقط tool)
 * ===================================================================== */

/** متنِ بلند را برای ذخیره در فایلِ پیشرفت کوتاه می‌کند.
 *  بدونِ این، یک پاسخِ ۴۰ کیلوبایتی مدل فایلِ JSON را باد می‌کند و هر
 *  نظرسنجیِ ۱٫۲ ثانیه‌ای همان حجم را روی شبکه می‌فرستد. */
function agentConvoTrim(string $s, int $max = 1400): string {
    $s = trim($s);
    if ($s === '') return '';
    if (mb_strlen($s) <= $max) return $s;
    return mb_substr($s, 0, $max) . ' … [' . aiFaNum(mb_strlen($s) - $max) . ' نویسهٔ دیگر بریده شد]';
}

/** پیامِ assistant را از متن و فهرستِ tool_call ها می‌سازد. */
function agentConvoAssistant(string $text, array $tcs): array {
    $calls = [];
    foreach ($tcs as $c) {
        $calls[] = ['name' => (string)($c['name'] ?? '?'),
                    'args' => agentConvoTrim(json_encode($c['args'] ?? [], JSON_UNESCAPED_UNICODE) ?: '{}', 600)];
    }
    return ['role' => 'assistant', 'text' => agentConvoTrim($text), 'calls' => $calls];
}

/** پیامِ نتیجهٔ یک ابزار. */
function agentConvoTool(string $name, array $res): array {
    return ['role' => 'tool', 'name' => $name, 'ok' => !empty($res['ok']),
            'text' => agentConvoTrim(json_encode($res, JSON_UNESCAPED_UNICODE) ?: '', 800)];
}
function agentStopRequested(): bool { return is_file(AGENT_STOP_FILE); }
function agentClearStop(): void { @unlink(AGENT_STOP_FILE); }

/** برچسبِ فارسیِ حالتِ اجرا */
function agentModeLabel(string $m): string {
    if ($m === 'live') return 'اجرای واقعی';
    if ($m === 'sim')  return 'شبیه‌سازیِ کامل';
    return 'آزمایشی (بدون نوشتن)';
}

/* ---------------------------------------------------------------------
 *  استخراجِ tool_call از پاسخِ مدل
 * ------------------------------------------------------------------- */

/**
 * tool_call ها را از پاسخِ سازگارِ OpenAI بیرون می‌کشد.
 * خروجی: [ ['id'=>..,'name'=>..,'args'=>[..]] , ... ]
 */
function aiExtractToolCalls($body): array {
    if (!is_array($body)) return [];
    $out = [];
    $raw = [];
    // OpenAI / Mistral / Groq / Together / OpenRouter
    foreach (($body['choices'] ?? []) as $ch) {
        if (!is_array($ch)) continue;
        $tc = $ch['message']['tool_calls'] ?? ($ch['delta']['tool_calls'] ?? null);
        if (is_array($tc)) foreach ($tc as $t) $raw[] = $t;
        // فرمتِ قدیمیِ function_call (تک‌تایی)
        $fc = $ch['message']['function_call'] ?? null;
        if (is_array($fc) && ($fc['name'] ?? '') !== '') {
            $raw[] = ['id' => 'call_legacy_' . count($raw), 'function' => $fc];
        }
    }
    // پاسخ‌های Responses-style: output[] با type=function_call
    foreach (($body['output'] ?? []) as $it) {
        if (!is_array($it)) continue;
        if (($it['type'] ?? '') === 'function_call' || isset($it['arguments'])) {
            $raw[] = ['id' => (string)($it['call_id'] ?? ($it['id'] ?? '')),
                      'function' => ['name' => (string)($it['name'] ?? ''),
                                     'arguments' => $it['arguments'] ?? '{}']];
        }
    }
    // v10.444: Anthropic نیتیو content[] با type=tool_use و Gemini نیتیو candidates[].content.parts[].functionCall
    foreach (($body['content'] ?? []) as $blk) {
        if (is_array($blk) && ($blk['type'] ?? '') === 'tool_use' && !empty($blk['name'])) {
            $raw[] = ['id' => (string)($blk['id'] ?? ''), 'name' => (string)$blk['name'], 'input' => $blk['input'] ?? []];
        }
    }
    foreach (($body['candidates'] ?? []) as $cand) {
        foreach (($cand['content']['parts'] ?? []) as $pt) {
            if (is_array($pt) && isset($pt['functionCall']['name'])) {
                $raw[] = ['id' => '', 'name' => (string)$pt['functionCall']['name'], 'input' => $pt['functionCall']['args'] ?? []];
            }
        }
    }
    foreach ($raw as $i => $t) {
        if (!is_array($t)) continue;
        $fn = $t['function'] ?? $t;
        $name = trim((string)($fn['name'] ?? ''));
        if ($name === '') continue;
        $a = $fn['arguments'] ?? ($t['input'] ?? []);
        if (is_string($a)) {
            $dec = json_decode($a, true);
            $a = is_array($dec) ? $dec : [];
        }
        if (!is_array($a)) $a = [];
        $id = trim((string)($t['id'] ?? ''));
        if ($id === '') $id = 'call_' . $i . '_' . substr(md5($name . $i), 0, 8);
        $out[] = ['id' => $id, 'name' => $name, 'args' => $a];
    }
    return $out;
}

/**
 * پشتیبانِ متنی: مدل‌هایی که tool calling بومی ندارند معمولاً بلوکِ JSON
 * برمی‌گردانند. اگر متن دقیقاً شکلِ {"tool":"...","args":{...}} داشت،
 * همان را به‌عنوان فراخوانیِ ابزار می‌پذیریم تا این محیط با مدل‌های
 * بیشتری کار کند.
 */
function agentParseTextCall(string $text): array {
    $t = trim($text);
    if ($t === '') return [];
    if (preg_match('~```(?:json)?\s*(.+?)\s*```~s', $t, $m)) $t = trim($m[1]);
    $s = strpos($t, '{');
    $e = strrpos($t, '}');
    if ($s === false || $e === false || $e <= $s) return [];
    $d = json_decode(substr($t, $s, $e - $s + 1), true);
    if (!is_array($d)) return [];
    $name = trim((string)($d['tool'] ?? ($d['name'] ?? ($d['function'] ?? ''))));
    if ($name === '') return [];
    $args = $d['args'] ?? ($d['arguments'] ?? ($d['parameters'] ?? []));
    if (is_string($args)) { $dd = json_decode($args, true); $args = is_array($dd) ? $dd : []; }
    if (!is_array($args)) $args = [];
    return [['id' => 'call_text_' . substr(md5($name . $t), 0, 8), 'name' => $name, 'args' => $args]];
}

/** پیامِ خامِ assistant (با tool_calls) را از پاسخ بیرون می‌کشد */
function aiAssistantMessage($body): ?array {
    if (!is_array($body)) return null;
    foreach (($body['choices'] ?? []) as $ch) {
        if (is_array($ch) && is_array($ch['message'] ?? null)) return $ch['message'];
    }
    return null;
}

