/** آیا عنوان با کلیدواژه‌های query جور است؟ */
function agentTitleMatches(string $name, string $query): bool {
    $query = trim($query);
    if ($query === '') return true;
    foreach (preg_split('~[|،,]+~u', $query) as $kw) {
        $kw = trim($kw);
        if ($kw !== '' && mb_stripos($name, $kw) !== false) return true;
    }
    return false;
}

/** ابزارِ ۱: فهرستِ محصولات */
function agentToolListProducts(array $ctx, array $a): array {
    $src   = ((string)($a['source'] ?? 'woo')) === 'bsl' ? 'bsl' : 'woo';
    $query = (string)($a['query'] ?? '');
    $limit = max(1, min(100, (int)($a['limit'] ?? 20)));

    if ($ctx['mode'] === 'sim') {
        $rows = agentSimData()[$src];
    } elseif ($src === 'bsl') {
        $bs = $ctx['cn']['basalam'] ?? [];
        if (empty($bs['token']) || empty($bs['vendor_id']))
            return ['ok' => false, 'error' => 'اتصالِ باسلام تنظیم نشده است'];
        $rows = dedupFetchBsl((string)$bs['token'], (int)$bs['vendor_id'], 5);
    } else {
        $w = $ctx['cn']['woocommerce'] ?? [];
        if (empty($w['store_url']))
            return ['ok' => false, 'error' => 'اتصالِ ووکامرس تنظیم نشده است'];
        $rows = dedupFetchWoo($w, 5);
    }

    $out = [];
    foreach ($rows as $r) {
        $name = (string)($r['name'] ?? '');
        if (!agentTitleMatches($name, $query)) continue;
        $out[] = ['id' => (int)($r['id'] ?? 0), 'title' => $name,
                  'price' => (int)round((float)($r['price'] ?? 0)),
                  'stock' => (int)($r['stock'] ?? 0)];
        if (count($out) >= $limit) break;
    }
    return ['ok' => true, 'source' => $src, 'count' => count($out), 'products' => $out];
}

/**
 * ابزارِ ۲: جست‌وجو در snappshop.ir
 * سایت را می‌گیریم و قیمت را از JSON-LD یا __NEXT_DATA__ یا الگوی متنی درمی‌آوریم.
 */
function agentSnappParse(string $html): array {
    $items = [];
    // ۱) JSON-LD (مطمئن‌ترین راه اگر سایت آن را بدهد)
    if (preg_match_all('~<script[^>]+application/ld\+json[^>]*>(.*?)</script>~si', $html, $m)) {
        foreach ($m[1] as $blk) {
            $d = json_decode(trim($blk), true);
            if (!is_array($d)) continue;
            $list = isset($d['itemListElement']) ? $d['itemListElement'] : [$d];
            foreach ((array)$list as $it) {
                if (!is_array($it)) continue;
                $node = $it['item'] ?? $it;
                if (!is_array($node)) continue;
                $nm = trim((string)($node['name'] ?? ''));
                $of = $node['offers'] ?? [];
                if (isset($of[0])) $of = $of[0];
                $pr = (float)($of['price'] ?? ($node['price'] ?? 0));
                $av = (string)($of['availability'] ?? '');
                if ($nm === '') continue;
                $items[] = ['title' => $nm, 'price' => (int)round($pr),
                            'available' => $av === '' ? ($pr > 0) : (stripos($av, 'InStock') !== false)];
            }
        }
    }
    // ۲) __NEXT_DATA__ / داده‌های تزریق‌شده
    if (!$items && preg_match('~__NEXT_DATA__[^>]*>(.*?)</script>~s', $html, $m)) {
        $d = json_decode(trim($m[1]), true);
        if (is_array($d)) {
            $walk = function ($n) use (&$walk, &$items) {
                if (!is_array($n)) return;
                $t = $n['title'] ?? ($n['name'] ?? null);
                $p = $n['price'] ?? ($n['min_price'] ?? ($n['final_price'] ?? null));
                if (is_string($t) && trim($t) !== '' && (is_int($p) || is_float($p) || (is_string($p) && $p !== ''))) {
                    $pv = (int)round((float)preg_replace('~[^0-9.]~', '', (string)$p));
                    if ($pv > 0) $items[] = ['title' => trim($t), 'price' => $pv, 'available' => true];
                }
                foreach ($n as $v) if (is_array($v)) $walk($v);
            };
            $walk($d);
        }
    }
    // ۳) آخرین راه: الگوی متنیِ «عنوان ... قیمت»
    if (!$items && preg_match_all('~"(?:title|name)"\s*:\s*"([^"]{6,120})"[^}]{0,400}?"(?:price|final_price|min_price)"\s*:\s*"?([0-9,\.]+)~su', $html, $m, PREG_SET_ORDER)) {
        foreach ($m as $one) {
            $pv = (int)round((float)str_replace(',', '', $one[2]));
            if ($pv > 0) $items[] = ['title' => $one[1], 'price' => $pv, 'available' => true];
        }
    }
    // یکتاسازی
    $seen = []; $uniq = [];
    foreach ($items as $it) {
        $k = mb_strtolower($it['title']);
        if (isset($seen[$k])) continue;
        $seen[$k] = 1; $uniq[] = $it;
        if (count($uniq) >= 20) break;
    }
    return $uniq;
}

/** امتیازِ شباهتِ دو عنوان (۰ تا ۱) بر پایهٔ کلمه‌های مشترک */
function agentTitleScore(string $a, string $b): float {
    $norm = function ($s) {
        $s = mb_strtolower(persianToEnglish($s));
        $s = preg_replace('~[^\p{L}\p{N}]+~u', ' ', $s);
        return array_values(array_filter(explode(' ', trim((string)$s)), fn($w) => mb_strlen($w) > 1));
    };
    $wa = $norm($a); $wb = $norm($b);
    if (!$wa || !$wb) return 0.0;
    $hit = count(array_intersect($wa, $wb));
    return $hit / max(1, min(count($wa), count($wb)));
}

function agentToolSearchSnappshop(array $ctx, array $a): array {
    $title = trim((string)($a['title'] ?? ''));
    if ($title === '') return ['ok' => false, 'error' => 'عنوان خالی است'];

    if ($ctx['mode'] === 'sim') {
        $tbl = agentSimData()['snapp'];
        $best = null; $bs = 0.0;
        foreach ($tbl as $k => $v) {
            $s = agentTitleScore($title, $k);
            if ($s > $bs) { $bs = $s; $best = $v; }
        }
        if (!$best || $bs < 0.4) return ['ok' => true, 'found' => false, 'query' => $title,
                                         'note' => 'در snappshop چیزی پیدا نشد'];
        return ['ok' => true, 'found' => true, 'query' => $title, 'match' => $best['title'],
                'price' => $best['price'], 'available' => $best['available'], 'score' => round($bs, 2)];
    }

    $url = 'https://snappshop.ir/search?q=' . rawurlencode($title);
    $r = fetch_html($url, 25);
    if (empty($r['ok']))
        return ['ok' => false, 'error' => 'دسترسی به snappshop ممکن نشد: ' . (string)($r['error'] ?? ('HTTP ' . ($r['code'] ?? '?')))];
    $items = agentSnappParse((string)($r['html'] ?? ''));
    if (!$items) return ['ok' => true, 'found' => false, 'query' => $title,
                         'note' => 'صفحه گرفته شد ولی محصولی استخراج نشد'];
    $best = null; $bs = 0.0;
    foreach ($items as $it) {
        $s = agentTitleScore($title, $it['title']);
        if ($s > $bs) { $bs = $s; $best = $it; }
    }
    if (!$best || $bs < 0.3) return ['ok' => true, 'found' => false, 'query' => $title,
                                     'note' => 'نتیجهٔ به‌اندازهٔ کافی نزدیک پیدا نشد',
                                     'candidates' => array_slice(array_column($items, 'title'), 0, 5)];
    return ['ok' => true, 'found' => true, 'query' => $title, 'match' => $best['title'],
            'price' => $best['price'], 'available' => !empty($best['available']),
            'score' => round($bs, 2), 'url' => $url];
}

/** ابزارِ ۳: به‌روزرسانیِ قیمت/موجودی */
function agentToolUpdateProduct(array $ctx, array $a): array {
    $target = ((string)($a['target'] ?? '')) === 'bsl' ? 'bsl' : 'woo';
    $id     = (int)($a['id'] ?? 0);
    $hasP   = array_key_exists('price', $a) && $a['price'] !== null && $a['price'] !== '';
    $hasS   = array_key_exists('stock', $a) && $a['stock'] !== null && $a['stock'] !== '';
    $price  = $hasP ? (int)round((float)$a['price']) : null;
    $stock  = $hasS ? (int)$a['stock'] : null;
    $reason = trim((string)($a['reason'] ?? ''));
    if ($id <= 0)          return ['ok' => false, 'error' => 'شناسهٔ محصول نامعتبر است'];
    if (!$hasP && !$hasS)  return ['ok' => false, 'error' => 'نه قیمت داده شده نه موجودی؛ چیزی برای تغییر نیست'];
    if ($price !== null && $price <= 0) return ['ok' => false, 'error' => 'قیمت باید بزرگ‌تر از صفر باشد'];
    if ($stock !== null && $stock < 0)  return ['ok' => false, 'error' => 'موجودی نمی‌تواند منفی باشد'];

    $rec = ['target' => $target, 'id' => $id, 'price' => $price, 'stock' => $stock, 'reason' => $reason];

    // در sim و dry هیچ‌چیز واقعاً نوشته نمی‌شود
    if ($ctx['mode'] !== 'live') {
        return ['ok' => true, 'applied' => false, 'simulated' => true,
                'message' => 'حالتِ ' . agentModeLabel($ctx['mode']) . ' — تغییر ثبت شد ولی روی فروشگاه نوشته نشد',
                'change' => $rec];
    }

    if ($target === 'bsl') {
        $bs = $ctx['cn']['basalam'] ?? [];
        if (empty($bs['token']) || empty($bs['vendor_id']))
            return ['ok' => false, 'error' => 'اتصالِ باسلام تنظیم نشده است'];
        $f = [];
        if ($price !== null) $f['primary_price'] = $price;
        if ($stock !== null) $f['stock'] = $stock;
        $r = bslEditProduct((string)$bs['token'], (int)$bs['vendor_id'], $id, $f);
    } else {
        $w = $ctx['cn']['woocommerce'] ?? [];
        if (empty($w['store_url']))
            return ['ok' => false, 'error' => 'اتصالِ ووکامرس تنظیم نشده است'];
        $f = [];
        if ($price !== null) { $f['regular_price'] = (string)$price; }
        if ($stock !== null) {
            $f['manage_stock']   = true;
            $f['stock_quantity'] = $stock;
            $f['stock_status']   = $stock > 0 ? 'instock' : 'outofstock';
        }
        $r = wooEditProduct($w, $id, $f);
    }
    if (empty($r['ok']))
        return ['ok' => false, 'error' => 'ناموفق (HTTP ' . (int)($r['code'] ?? 0) . ')', 'change' => $rec];
    return ['ok' => true, 'applied' => true, 'change' => $rec];
}

/** اجرای یک ابزار و برگرداندنِ نتیجه به‌صورت آرایه */
function agentExecTool(array $ctx, string $name, array $args): array {
    switch ($name) {
        case 'list_products':     return agentToolListProducts($ctx, $args);
        case 'search_snappshop':  return agentToolSearchSnappshop($ctx, $args);
        case 'update_product':    return agentToolUpdateProduct($ctx, $args);
        case 'finish':            return ['ok' => true, 'finished' => true,
                                          'summary' => (string)($args['summary'] ?? '')];
    }
    return ['ok' => false, 'error' => 'ابزارِ ناشناخته: ' . $name];
}

/** خلاصهٔ یک‌خطیِ فارسی از یک فراخوانیِ ابزار — برای لاگِ زنده */
function agentCallLabel(string $name, array $args): string {
    if ($name === 'list_products')
        return '📋 فهرستِ محصولات ' . ((($args['source'] ?? '') === 'bsl') ? 'باسلام' : 'ووکامرس')
             . (($args['query'] ?? '') !== '' ? (' · جست‌وجو: ' . $args['query']) : '');
    if ($name === 'search_snappshop')
        return '🔎 اسنپ‌شاپ: ' . (string)($args['title'] ?? '');
    if ($name === 'update_product') {
        $p = [];
        if (isset($args['price'])) $p[] = 'قیمت ' . aiFaNum((int)$args['price']);
        if (isset($args['stock'])) $p[] = 'موجودی ' . aiFaNum((int)$args['stock']);
        return '✏️ به‌روزرسانی ' . ((($args['target'] ?? '') === 'bsl') ? 'باسلام' : 'ووکامرس')
             . ' #' . aiFaNum((int)($args['id'] ?? 0)) . ($p ? (' → ' . implode('، ', $p)) : '');
    }
    if ($name === 'finish') return '🏁 پایانِ کار';
    return '🔧 ' . $name;
}

/** پیامِ سیستمیِ ایجنت */
function agentSystemPrompt(string $mode): string {
    $s  = "تو یک دستیارِ مدیریتِ فروشگاهِ اینترنتی هستی و به چند ابزارِ واقعی دسترسی داری.\n";
    $s .= "قواعد:\n";
    $s .= "۱) برای هر کاری حتماً ابزارِ مناسب را صدا بزن؛ چیزی را از خودت حدس نزن.\n";
    $s .= "۲) اول با list_products محصولات را پیدا کن، بعد برای هر عنوان search_snappshop را صدا بزن، و در پایان با update_product قیمت و موجودی را اصلاح کن.\n";
    $s .= "۳) اگر snappshop محصولی را پیدا نکرد، آن محصول را دست‌نخورده رها کن.\n";
    $s .= "۴) اگر در snappshop ناموجود بود، موجودی را صفر کن.\n";
    $s .= "۵) هر بار حداکثر چند ابزار را صدا بزن و منتظرِ نتیجه بمان.\n";
    $s .= "۶) وقتی کار تمام شد، ابزارِ finish را با خلاصهٔ فارسی صدا بزن.\n";
    $s .= "حالتِ فعلیِ اجرا: " . agentModeLabel($mode) . ".\n";
    if ($mode !== 'live') $s .= "در این حالت هیچ تغییری واقعاً روی فروشگاه نوشته نمی‌شود، ولی تو کارَت را کامل انجام بده.\n";
    $s .= "همیشه فارسی بنویس.";
    return $s;
}

/* ---------------------------------------------------------------------
 *  حلقهٔ اصلیِ ایجنت
 * ------------------------------------------------------------------- */

/**
 * ایجنت را اجرا می‌کند.
 * $mode: sim | dry | live
 * خروجی: گزارشِ کامل برای AGENT_RESULT_FILE
 */
function agentRun(array $cn, string $task, string $mode, string $model = '', ?array $checkpoint = null): array {
    $t0  = microtime(true);
    $ctx = ['cn' => $cn, 'mode' => $mode];
    $tools = agentToolSpecs();
    $resumeCp = is_array($checkpoint) && is_array($checkpoint['messages'] ?? null)
        && count($checkpoint['messages']) >= 2 ? $checkpoint : null;
    /* v10.08: اگر کار مدلِ دلخواه دارد و آن مدل در اتصال‌های کاربر پیدا
       شد، همهٔ گام‌های همین اجرا با همان مدل زده می‌شوند. پیدا نشد ⇒
       بی‌صدا به مدلِ فعالِ پیش‌فرض برمی‌گردیم تا کار زمین نماند. */
    $pin = $model !== '' ? autoResolveModel($model) : [];
    if ($model !== '' && !$pin) {
        agentProgress(['log_add' => ['⚠️ مدلِ «' . $model . '» در اتصال‌ها پیدا نشد؛ مدلِ پیش‌فرض استفاده می‌شود']]);
    }

    $messages = $resumeCp !== null ? array_values($resumeCp['messages']) : [
        ['role' => 'system', 'content' => agentSystemPrompt($mode)],
        ['role' => 'user',   'content' => $task],
    ];
    $calls = $resumeCp !== null ? (int)($resumeCp['calls'] ?? 0) : 0;
    $changes = $resumeCp !== null && is_array($resumeCp['changes'] ?? null) ? $resumeCp['changes'] : [];
    $finalText = $resumeCp !== null ? (string)($resumeCp['final_text'] ?? '') : '';
    $stoppedBy = '';
    $usedTools = $resumeCp !== null && is_array($resumeCp['used_tools'] ?? null) ? $resumeCp['used_tools'] : [];
    $nativeTools = $resumeCp !== null && array_key_exists('native_tools', $resumeCp) ? $resumeCp['native_tools'] : null;
    $startStep = $resumeCp !== null ? max(1, (int)($resumeCp['next_step'] ?? 1)) : 1;
    $startedAt = (int)($resumeCp['started_at'] ?? time());
    /* v10.26 (۳۹ب): اجرای تازه پیام‌های آغازین را به جریان گفتگو اضافه می‌کند؛
       در resume همان گفتگو از checkpoint خوانده می‌شود تا پیام‌ها دوباره تکرار نشوند. */
    if ($resumeCp === null) {
        agentProgress(['convo_add' => [
            ['role' => 'system', 'text' => agentConvoTrim(agentSystemPrompt($mode), 700)],
            ['role' => 'user',   'text' => agentConvoTrim($task)],
        ]]);
    }
    $saveCp = function (int $nextStep) use (&$messages, &$calls, &$changes, &$usedTools,
        &$nativeTools, &$finalText, $startedAt): void {
        agentProgress(['checkpoint' => [
            'messages' => $messages, 'calls' => $calls, 'changes' => $changes,
            'used_tools' => $usedTools, 'native_tools' => $nativeTools,
            'final_text' => $finalText, 'next_step' => $nextStep,
            'last_step' => max(0, $nextStep), 'started_at' => (int)($startedAt ?: time())]]);
    };
    /* v10.130: حتی اگر نخستین تماس مدل با خطای شبکه/timeout قطع شود،
       تاریخچهٔ system/user از قبل در checkpoint هست و کران بعدی می‌تواند
       همان کار را resume کند؛ بدون این ذخیره، خطای اولین تماس قابل‌ادامه نبود. */
    if ($resumeCp === null) $saveCp(1);

    for ($step = $startStep; $step <= AGENT_MAX_STEPS; $step++) {
        if (agentStopRequested()) { $stoppedBy = 'کاربر'; break; }
        agentProgress(['step' => $step, 'phase' => 'think',
            'checkpoint' => ['messages' => $messages, 'calls' => $calls, 'changes' => $changes,
                'used_tools' => $usedTools, 'native_tools' => $nativeTools, 'final_text' => $finalText,
                'next_step' => $step, 'last_step' => $step, 'started_at' => $startedAt],
            'log_add' => ['🤔 گامِ ' . aiFaNum($step) . ' — پرسش از مدل...']]);

        $payload = ['messages' => $messages, 'tools' => $tools, 'tool_choice' => 'auto',
                    'temperature' => 0.1, 'max_tokens' => 1200];
        $r = $pin ? aiProviderCall($pin['provider'], $pin['model'], $payload) : aiActiveChat($payload);

        if (empty($r['ok'])) {
            $err = (string)($r['error'] ?? ('HTTP ' . (int)($r['code'] ?? 0)));
            // بعضی سرویس‌ها اصلاً فیلدِ tools را قبول نمی‌کنند ⇒ بدونِ آن دوباره امتحان کن
            if ((int)($r['code'] ?? 0) === 400 && $nativeTools !== false) {
                $nativeTools = false;
                agentProgress(['log_add' => ['⚠️ مدل فیلدِ tools را نپذیرفت؛ حالتِ متنی امتحان می‌شود']]);
                $messages[0]['content'] = agentSystemPrompt($mode) . "\n\n"
                    . "این مدل فراخوانیِ ابزارِ بومی ندارد. برای صدا زدنِ ابزار فقط و فقط یک بلوکِ JSON بنویس:\n"
                    . '{"tool":"نامِ ابزار","args":{...}}' . "\n"
                    . 'ابزارها: ' . json_encode(array_map(fn($t) => [
                          'name' => $t['function']['name'],
                          'params' => array_keys($t['function']['parameters']['properties'] ?? []),
                      ], $tools), JSON_UNESCAPED_UNICODE);
                continue;
            }
            agentProgress(['log_add' => ['❌ خطای مدل: ' . $err]]);
            return ['ok' => false, 'error' => $err, 'mode' => $mode, 'task' => $task,
                    'steps' => $step, 'calls' => $calls, 'changes' => $changes,
                    'took' => round(microtime(true) - $t0, 1)];
        }

        $body = $r['body'];
        $tcs  = aiExtractToolCalls($body);
        $text = aiExtractText($body);
        if (!$tcs) {
            $tcs = agentParseTextCall($text);
            if ($tcs) agentProgress(['log_add' => ['🧩 فراخوانیِ ابزار از متنِ مدل استخراج شد']]);
        } elseif ($nativeTools === null) {
            $nativeTools = true;
            agentProgress(['native_tools' => true, 'log_add' => ['✅ مدل فراخوانیِ ابزارِ بومی دارد']]);
        }

        if (!$tcs) {
            $finalText = trim($text);
            agentProgress(['convo_add' => [['role' => 'assistant', 'text' => agentConvoTrim($finalText), 'calls' => []]],
                'log_add' => ['💬 مدل بدونِ ابزار پاسخِ متنی داد؛ پایان']]);
            break;
        }
        agentProgress(['convo_add' => [agentConvoAssistant($text, $tcs)]]);

        // پیامِ assistant را عیناً به تاریخچه اضافه کن (لازمهٔ پروتکل)
        $asst = aiAssistantMessage($body);
        if (is_array($asst) && isset($asst['tool_calls'])) {
            $messages[] = $asst;
        } else {
            $messages[] = ['role' => 'assistant', 'content' => $text !== '' ? $text : null,
                'tool_calls' => array_map(fn($c) => [
                    'id' => $c['id'], 'type' => 'function',
                    'function' => ['name' => $c['name'],
                                   'arguments' => json_encode($c['args'], JSON_UNESCAPED_UNICODE)],
                ], $tcs)];
        }
        /* پاسخِ assistant پیش از اجرای ابزارها ذخیره می‌شود؛ اگر پردازه در
           تماسِ یک ابزار قطع شد، resume همان نوبت را با تاریخچهٔ معتبر ادامه
           می‌دهد و فقط همان ابزارِ درحال‌انجام ممکن است یک بار تکرار شود. */
        $saveCp($step);

        $finished = false;
        foreach ($tcs as $c) {
            if (agentStopRequested()) { $stoppedBy = 'کاربر'; break; }
            if ($calls >= AGENT_MAX_CALLS) { $stoppedBy = 'سقفِ فراخوانی'; break; }
            $calls++;
            $usedTools[$c['name']] = ($usedTools[$c['name']] ?? 0) + 1;
            agentProgress(['phase' => 'tool', 'calls' => $calls,
                'log_add' => [agentCallLabel($c['name'], $c['args'])]]);

            $res = agentExecTool($ctx, $c['name'], $c['args']);

            if ($c['name'] === 'update_product' && !empty($res['ok']) && isset($res['change'])) {
                $ch = $res['change'];
                $ch['applied'] = !empty($res['applied']);
                $changes[] = $ch;
                agentProgress(['changes' => count($changes)]);
            }
            if (!empty($res['ok'])) {
                if ($c['name'] === 'list_products')
                    agentProgress(['log_add' => ['   ↳ ' . aiFaNum((int)($res['count'] ?? 0)) . ' محصول']]);
                elseif ($c['name'] === 'search_snappshop')
                    agentProgress(['log_add' => ['   ↳ ' . (empty($res['found'])
                        ? 'پیدا نشد'
                        : ('قیمت ' . aiFaNum((int)($res['price'] ?? 0)) . ' · '
                           . (!empty($res['available']) ? 'موجود' : 'ناموجود')))]]);
                elseif ($c['name'] === 'update_product')
                    agentProgress(['log_add' => ['   ↳ ' . (!empty($res['applied'])
                        ? 'روی فروشگاه نوشته شد' : 'شبیه‌سازی شد (بدون نوشتن)')]]);
            } else {
                agentProgress(['log_add' => ['   ↳ ⚠️ ' . (string)($res['error'] ?? 'ناموفق')]]);
            }

            agentProgress(['step_add' => [['step' => $step, 'tool' => $c['name'],
                'args' => $c['args'], 'ok' => !empty($res['ok'])]]]);

            $messages[] = ['role' => 'tool', 'tool_call_id' => $c['id'], 'name' => $c['name'],
                           'content' => json_encode($res, JSON_UNESCAPED_UNICODE)];
            agentProgress(['convo_add' => [agentConvoTool($c['name'], $res)]]);
            $saveCp($step);

            if ($c['name'] === 'finish') {
                $finalText = (string)($res['summary'] ?? '');
                $finished = true;
                break;
            }
        }
        if ($finished || $stoppedBy !== '') break;
    }

    if ($finalText === '' && $stoppedBy === '') $stoppedBy = 'سقفِ گام‌ها';

    $applied = 0;
    foreach ($changes as $c) if (!empty($c['applied'])) $applied++;

    return ['ok' => true, 'mode' => $mode, 'task' => $task, 'summary' => $finalText,
            'stopped_by' => $stoppedBy, 'calls' => $calls, 'tools_used' => $usedTools,
            'changes' => $changes, 'applied' => $applied,
            'simulated' => count($changes) - $applied,
            'native_tools' => $nativeTools, 'took' => round(microtime(true) - $t0, 1)];
}

/* =====================================================================
 *  v10.25 (۳۸ج): ایجنتِ کشفِ سلکتور
 *  ---------------------------------------------------------------------
 *  تا نسخهٔ ۱۰٫۲۴ دکمهٔ «💡 پیشنهاد» فقط یک فهرستِ ثابت از الگوهای
 *  ووکامرس را روی صفحه امتحان می‌کرد. روی هر سایتی که قالبِ ووکامرسیِ
 *  استاندارد نداشت (اکثرِ فروشگاه‌های ایرانی) خروجی یا خالی بود یا
 *  سلکتوری می‌داد که موقعِ استخراج رشتهٔ خالی برمی‌گرداند.
 *
 *  حالا یک ایجنتِ واقعی این کار را می‌کند:
 *    ۱) صفحه را می‌گیرد و یک «نقشهٔ فشرده» از DOM می‌سازد (نه خودِ HTML —
 *       یک صفحهٔ فروشگاهی ۸۰۰ کیلوبایت است و در هیچ کانتکستی جا نمی‌شود).
 *    ۲) مدل با ابزارها روی همان DOM کاوش می‌کند: probe_selector می‌زند،
 *       نمونهٔ واقعی می‌بیند، اشتباهش را می‌فهمد و سلکتورِ بعدی را امتحان
 *       می‌کند.
 *    ۳) هر سلکتوری که مدل نهایی می‌کند، پیش از پذیرش *دوباره روی همان
 *       صفحه اعتبارسنجی می‌شود*. مدل نمی‌تواند سلکتورِ خیالی تحویل بدهد.
 *
 *  همهٔ گام‌ها با selagentProgress ثبت می‌شوند تا هم‌زمان در «مدیر وظیفه»
 *  و در تبِ «🤖 ایجنت» دیده شوند (بندِ ۳۸د).
 * ================================================================== */

/** ثبتِ پیشرفت — دقیقاً همان قراردادِ agentProgress، روی فایلِ خودِ این ایجنت. */
function selagentProgress(array $patch): void {
    $cur = localTaskStateRead(SELAGENT_PROGRESS_FILE, []);
    $log = is_array($cur['log'] ?? null) ? $cur['log'] : [];
    if (isset($patch['log_add'])) {
        foreach ((array)$patch['log_add'] as $l) $log[] = ['t' => time(), 'm' => (string)$l];
        if (count($log) > 400) $log = array_slice($log, -400);
        unset($patch['log_add']);
    }
    $steps = is_array($cur['steps'] ?? null) ? $cur['steps'] : [];
    if (isset($patch['step_add'])) {
        foreach ((array)$patch['step_add'] as $s) $steps[] = $s;
        if (count($steps) > 200) $steps = array_slice($steps, -200);
        unset($patch['step_add']);
    }
    /* v10.26 (۳۹ب): همان جریانِ گفتگوی agentProgress، اینجا هم. */
    $convo = is_array($cur['convo'] ?? null) ? $cur['convo'] : [];
    if (isset($patch['convo_add'])) {
        foreach ((array)$patch['convo_add'] as $c) {
            if (!is_array($c)) continue;
            $c['t'] = time();
            $convo[] = $c;
        }
        if (count($convo) > 240) $convo = array_slice($convo, -240);
        unset($patch['convo_add']);
    }
    $cur = array_merge($cur, $patch);
    if (!empty($patch['running']) && empty($patch['done'])) {
        foreach (['stale', 'stopped', 'cancelled', 'stalled', 'partial', 'incomplete', 'error', 'result_ok'] as $k) unset($cur[$k]);
    }
    $cur['log'] = $log; $cur['steps'] = $steps; $cur['convo'] = $convo; $cur['ts'] = time();
    writeProgress(SELAGENT_PROGRESS_FILE, $cur);
}
function selagentStopRequested(): bool { return is_file(SELAGENT_STOP_FILE); }
function selagentClearStop(): void { @unlink(SELAGENT_STOP_FILE); }

/** فیلدهای هر حالت — همان کلیدهایی که فرمِ تبِ سلکتور می‌شناسد. */
function selagentFields(string $kind): array {
    if ($kind === 'detail') {
        return ['price' => 'قیمت', 'shortDesc' => 'توضیحاتِ کوتاه', 'longDesc' => 'توضیحاتِ بلند',
                'sku' => 'کدِ کالا (SKU)', 'category' => 'دسته‌بندی', 'tags' => 'برچسب‌ها',
                'weight' => 'وزن', 'stock' => 'موجودی', 'brand' => 'برند'];
    }
    return ['container' => 'ظرفِ هر محصول', 'title' => 'عنوان', 'price' => 'قیمت',
            'link' => 'لینکِ صفحهٔ محصول', 'image' => 'عکس'];
}

/**
 * نقشهٔ فشردهٔ DOM برای مدل.
 *
 * ایدهٔ کلیدی: مدل به خودِ HTML نیاز ندارد، به «کدام کلاس‌ها چند بار
 * تکرار شده‌اند و داخلشان چه هست» نیاز دارد. برای صفحهٔ فهرست، ظرفِ
 * محصول همیشه یک کلاسِ پرتکرار است؛ برای صفحهٔ جزئیات، فیلدها کلاس‌های
 * یکتای معنادار دارند. پس یک هیستوگرامِ کلاس + چند نمونه‌متن می‌سازیم.
 */
function selagentDomMap(DOMXPath $xp, string $kind, int $budget = 12000): string {
    $out = [];

    /* هیستوگرامِ کلاس‌ها: کلاس ⇒ [تعداد، تگِ غالب، آیا لینک دارد، آیا عکس دارد، آیا عدد دارد] */
    $hist = [];
    $nodes = @$xp->query('//*[@class]');
    $seen = 0;
    if ($nodes) foreach ($nodes as $n) {
        if (++$seen > 6000) break;
        if (!($n instanceof DOMElement)) continue;
        $tag = strtolower($n->tagName);
        if (in_array($tag, ['script', 'style', 'noscript', 'svg', 'path'], true)) continue;
        $txt = trim(preg_replace('/\s+/u', ' ', (string)$n->textContent));
        foreach (preg_split('/\s+/', trim((string)$n->getAttribute('class')), -1, PREG_SPLIT_NO_EMPTY) as $c) {
            if (mb_strlen($c) > 40 || mb_strlen($c) < 2) continue;
            // کلاس‌های هش‌شدهٔ ابزارهای بیلد (مثل css-1a2b3c) برای انسان و مدل بی‌معنی‌اند
            if (preg_match('/^(css|sc|jsx|_)-?[0-9a-f]{5,}$/i', $c)) continue;
            $k = $tag . '.' . $c;
            if (!isset($hist[$k])) $hist[$k] = ['n' => 0, 'a' => 0, 'img' => 0, 'num' => 0, 'len' => 0, 'ex' => ''];
            $hist[$k]['n']++;
            if (strpos($n->textContent, '') !== false) { /* no-op */ }
            $a = @$xp->query('.//a[@href]', $n);   if ($a && $a->length) $hist[$k]['a']++;
            $i = @$xp->query('.//img', $n);        if ($i && $i->length) $hist[$k]['img']++;
            if (preg_match('/[0-9۰-۹٠-٩]{3,}/u', $txt)) $hist[$k]['num']++;
            $hist[$k]['len'] += mb_strlen($txt);
            if ($hist[$k]['ex'] === '' && $txt !== '') $hist[$k]['ex'] = mb_substr($txt, 0, 60);
        }
    }

    if ($kind === 'list') {
        /* برای فهرست: کلاس‌هایی که چند بار تکرار شده‌اند کاندیدِ ظرف‌اند. */
        $rep = array_filter($hist, fn($v) => $v['n'] >= 2 && $v['n'] <= 200);
        uasort($rep, function ($a, $b) {
            // امتیاز: تکرارِ زیاد + داشتنِ لینک و عکس در بیشترِ نمونه‌ها
            $sa = $a['n'] + ($a['a'] * 2) + ($a['img'] * 2);
            $sb = $b['n'] + ($b['a'] * 2) + ($b['img'] * 2);
            return $sb <=> $sa;
        });
        $out[] = 'کلاس‌های تکرارشونده (کاندیدِ ظرفِ محصول) — قالب: سلکتور | تکرار | چندتا لینک دارند | چندتا عکس دارند | نمونهٔ متن:';
        $c = 0;
        foreach ($rep as $k => $v) {
            if (++$c > 60) break;
            $out[] = $k . ' | ' . $v['n'] . ' | ' . $v['a'] . ' | ' . $v['img'] . ' | ' . $v['ex'];
        }
    } else {
        /* برای جزئیات: کلاس‌های کم‌تکرار (یکتا) معنادارند. */
        $uniq = array_filter($hist, fn($v) => $v['n'] <= 6 && $v['ex'] !== '');
        uasort($uniq, fn($a, $b) => $b['len'] <=> $a['len']);
        $out[] = 'عناصرِ معنادارِ صفحه — قالب: سلکتور | تکرار | نمونهٔ متن:';
        $c = 0;
        foreach ($uniq as $k => $v) {
            if (++$c > 80) break;
            $out[] = $k . ' | ' . $v['n'] . ' | ' . $v['ex'];
        }
        /* عنوانِ صفحه و متاها اغلب مستقیماً به فیلدها می‌خورند */
        $h1 = @$xp->query('//h1');
        if ($h1 && $h1->length) $out[] = 'h1 | 1 | ' . mb_substr(trim(preg_replace('/\s+/u', ' ', $h1->item(0)->textContent)), 0, 60);
    }

    /* =================================================================
     *  v10.30 (۴۳الف): بخشِ «عناصرِ نشان‌دار».
     *
     *  تا ۱۰.۲۹ نقشه فقط //*[@class] را می‌خواند و کلاس‌های هش‌شده را هم
     *  دور می‌ریخت. روی صفحه‌ای مثل snappshop.ir/product/... که تمامِ
     *  کلاس‌هایش css-xxxxxx است، نتیجه یک نقشهٔ عملاً خالی می‌شد و مدل
     *  چیزی برای شروع نداشت. ولی همان صفحه پر است از data-testid و
     *  itemprop و id — که سلکتورِ ساخته‌شده از رویشان از کلاس هم پایدارتر
     *  است. پس یک بخشِ جدا برایشان می‌گذاریم.
     * ================================================================= */
    $attrRows = [];
    $attrList = selagentStableAttrs();
    $q = [];
    foreach ($attrList as $at) $q[] = '//*[@' . $at . ']';
    $q[] = '//*[@id]';
    $marked = @$xp->query(implode(' | ', $q));
    $seenSel = [];
    if ($marked) foreach ($marked as $n) {
        if (count($attrRows) >= 45) break;
        if (!($n instanceof DOMElement)) continue;
        $tag = strtolower($n->tagName);
        if (in_array($tag, ['script', 'style', 'noscript', 'svg', 'path', 'html', 'head', 'body'], true)) continue;
        $sel = selagentSelectorFor($n)[0];
        if ($sel === $tag) continue;                 // چیزی برای گفتن ندارد
        if (isset($seenSel[$sel])) continue;
        $seenSel[$sel] = 1;
        $cnt = 0;
        $x = cssToXpath($sel);
        if ($x !== '') { $qq = @$xp->query($x); $cnt = $qq ? $qq->length : 0; }
        $txt = trim(preg_replace('/\s+/u', ' ', (string)$n->textContent));
        $extra = '';
        if ($tag === 'img') $extra = ' [عکس]';
        elseif ($tag === 'a') $extra = ' [لینک]';
        $attrRows[] = $sel . ' | ' . ($cnt ?: 1) . $extra . ' | ' . ($txt === '' ? '—' : mb_substr($txt, 0, 55));
    }
    if ($attrRows) {
        $out[] = '';
        $out[] = 'عناصرِ نشان‌دار (data-testid / itemprop / id / role) — قالب: سلکتور | تکرار | نمونهٔ متن:';
        foreach ($attrRows as $r) $out[] = $r;
    }

    /* اگر صفحه تقریباً هیچ کلاسِ معناداری نداشت، صریح به مدل بگو از کجا
       شروع کند؛ وگرنه شروع می‌کند به حدس زدنِ کلاس‌هایی که وجود ندارند. */
    if (count($out) < 6) {
        $out[] = '';
        $out[] = '⚠️ این صفحه کلاسِ معنادارِ کمی دارد (احتمالاً SPA با کلاس‌های هش‌شده).'
               . ' حدس نزن: اول page_data را بزن تا مقدارِ درستِ فیلدها را ببینی،'
               . ' بعد با find_text همان مقدار را در صفحه پیدا کن، و با list_children ساختار را باز کن.';
    }

    $s = implode("\n", $out);
    if (mb_strlen($s) > $budget) $s = mb_substr($s, 0, $budget) . "\n… (فهرست بریده شد)";
    return $s;
}

/**
 * یک سلکتور را روی صفحه امتحان می‌کند و می‌گوید *واقعاً* چه چیزی برمی‌دارد.
 *
 * این قلبِ ایجنت است: مدل حدس می‌زند، این تابع حقیقت را برمی‌گرداند.
 * $scope: اگر داده شود، جست‌وجو داخلِ اولین تطبیقِ آن انجام می‌شود
 * (برای فیلدهای داخلِ ظرفِ محصول).
 */
function selagentProbe(DOMXPath $xp, string $selector, string $field, string $baseUrl, string $scope = ''): array {
    $selector = trim($selector);
    if ($selector === '') return ['ok' => false, 'error' => 'سلکتور خالی است'];
    $xpath = cssToXpath($selector);
    /* v10.30 (۴۳الف): پیامِ قبلی می‌گفت «فقط تگ، کلاس، #id و > مجازند» و
       همین مدل را از [data-testid=...] و :nth-child می‌ترساند — دقیقاً دو
       چیزی که روی صفحاتِ SPA تنها راهِ نجات‌اند و cssToXpath از v9.85
       پشتیبانی‌شان می‌کند. حالا دقیقاً می‌گوییم چه چیزی کار نمی‌کند. */
    if ($xpath === '') return ['ok' => false,
        'error' => 'این سلکتورِ CSS قابلِ ترجمه نیست.',
        'supported' => 'تگ، .کلاس، #شناسه، [ویژگی]، [ویژگی="مقدار"]، [ویژگی^=]، [ویژگی*=]، [ویژگی$=]، :nth-child(n)، :first-child، :last-child، فاصله، > و کاما',
        'not_supported' => '+ و ~ و :not() و شبه‌کلاس‌های حالت مثل :hover',
        'hint' => 'اگر به کلاسِ هش‌شده گیر کرده‌ای، به‌جایش از [data-testid="..."] یا [itemprop="..."] استفاده کن؛ با find_text می‌توانی پیدایشان کنی.'];

    $roots = [null];
    if ($scope !== '') {
        $sx = cssToXpath($scope);
        if ($sx === '') return ['ok' => false, 'error' => 'سلکتورِ ظرف قابلِ ترجمه نیست'];
        $sn = @$xp->query($sx);
        if (!$sn || !$sn->length) return ['ok' => false, 'error' => 'ظرفِ داده‌شده روی صفحه پیدا نشد'];
        $roots = [];
        foreach ($sn as $i => $one) { if ($i >= 5) break; $roots[] = $one; }
    }

    $samples = []; $hit = 0; $rootsWith = 0;
    foreach ($roots as $root) {
        $q = $root === null ? $xpath : ('.' . $xpath);
        $nodes = $root === null ? @$xp->query($q) : @$xp->query($q, $root);
        if (!$nodes || !$nodes->length) continue;
        $rootsWith++;
        $hit += $nodes->length;
        $lim = $root === null ? 3 : 1;
        foreach ($nodes as $i => $n) {
            if ($i >= $lim) break;
            $samples[] = selagentValueOf($xp, $n, $field, $baseUrl);
        }
        if (count($samples) >= 5) break;
    }

    if (!$hit) return ['ok' => false, 'found' => 0,
        'error' => 'هیچ عنصری با این سلکتور پیدا نشد' . ($scope !== '' ? ' (داخلِ ظرف)' : '')];

    $nonEmpty = 0;
    foreach ($samples as $s) if (trim((string)$s) !== '') $nonEmpty++;

    $r = ['ok' => true, 'found' => $hit, 'samples' => $samples,
          'non_empty' => $nonEmpty, 'empty' => count($samples) - $nonEmpty];
    if ($scope !== '') $r['containers_matched'] = $rootsWith . ' از ' . count($roots) . ' ظرفِ نمونه';
    if ($nonEmpty === 0) $r['warning'] = 'سلکتور تطبیق می‌خورد ولی مقدارِ استخراج‌شده خالی است — این به دردِ استخراج نمی‌خورد';
    return $r;
}

/** مقدارِ واقعیِ یک گره برای یک فیلد — همان منطقِ ?test_selector، فشرده. */
function selagentValueOf(DOMXPath $xp, DOMNode $node, string $field, string $baseUrl): string {
    if ($field === 'price') {
        $v = extractPrice($node->textContent);
        return $v !== '' ? $v : '';
    }
    if ($field === 'link') {
        $link = '';
        if ($node instanceof DOMElement) {
            if (strtolower($node->tagName) === 'a') $link = (string)$node->getAttribute('href');
            if ($link === '') {
                $a = @$xp->query('.//a[@href]', $node);
                if ($a && $a->length) $link = (string)$a->item(0)->getAttribute('href');
            }
            if ($link === '') {
                $p = $node->parentNode;
                for ($i = 0; $i < 5 && $p instanceof DOMElement; $i++) {
                    if (strtolower($p->tagName) === 'a' && $p->getAttribute('href')) { $link = (string)$p->getAttribute('href'); break; }
                    $p = $p->parentNode;
                }
            }
        }
        return $link === '' ? '' : make_absolute_url($link, $baseUrl);
    }
    if ($field === 'image') {
        $img = '';
        $cand = null;
        if ($node instanceof DOMElement && strtolower($node->tagName) === 'img') $cand = $node;
        else { $in = @$xp->query('.//img', $node); if ($in && $in->length) $cand = $in->item(0); }
        if ($cand instanceof DOMElement) {
            foreach (['data-src', 'data-lazy-src', 'data-original', 'srcset', 'src'] as $at) {
                $v = trim((string)$cand->getAttribute($at));
                if ($at === 'srcset' && $v !== '') $v = trim(explode(' ', explode(',', $v)[0])[0]);
                if ($v !== '' && url_is_image($v)) { $img = $v; break; }
            }
        }
        return $img === '' ? '' : make_absolute_url($img, $baseUrl);
    }
    if ($field === 'container') {
        /* برای ظرف، «مقدار» یعنی خلاصه‌ای از آنچه داخلش هست تا مدل بفهمد
           ظرفِ درستی گرفته یا مثلاً کلِ صفحه را. */
        $t = @$xp->query('.//h1|.//h2|.//h3|.//h4|.//a[@title]', $node);
        $a = @$xp->query('.//a[@href]', $node);
        $i = @$xp->query('.//img', $node);
        $head = ($t && $t->length) ? mb_substr(normalize_text($t->item(0)->textContent), 0, 45) : '—';
        return 'عنوان: ' . $head . ' · لینک: ' . (($a && $a->length) ? 'دارد' : 'ندارد')
             . ' · عکس: ' . (($i && $i->length) ? 'دارد' : 'ندارد');
    }
    return mb_substr(normalize_text($node->textContent), 0, 120);
}

/* =====================================================================
 *  v10.30 (۴۳الف): چرا ایجنت روی صفحه‌ای مثل
 *  https://snappshop.ir/product/snp-1540201588 گیر می‌کرد.
 *
 *  تا ۱۰.۲۹ ایجنت سه چشم داشت: «نقشهٔ کلاس‌ها»، probe_selector، و
 *  inspect_html. روی یک صفحهٔ محصولِ Next.js هیچ‌کدام کار نمی‌کرد:
 *
 *   ۱) کلاس‌ها هش‌شده‌اند (css-1a2b3c) و خودِ selagentDomMap عمداً
 *      دورشان می‌ریخت ⇒ نقشه تقریباً خالی درمی‌آمد.
 *   ۲) عنصرهای معنادارِ این صفحات کلاس ندارند؛ data-testid / itemprop /
 *      id دارند. ولی نقشه فقط //*[@class] را می‌خواند ⇒ نامرئی بودند.
 *   ۳) پرامپت صریح می‌گفت «از [attr] و :nth-child استفاده نکن» — در حالی
 *      که cssToXpath از v9.85 کاملاً [attr]، [attr^=]، [attr*=]، [attr$=]
 *      و :nth-child/:first-child/:last-child را ترجمه می‌کند. یعنی ایجنت
 *      از تنها ابزاری که روی این صفحه جواب می‌داد منع شده بود.
 *   ۴) قیمت و SKU و برندِ چنین صفحاتی اصلاً در HTMLِ سرور نیستند؛ در
 *      JSON-LD و __NEXT_DATA__ نشسته‌اند و مدل هیچ راهی به آن‌ها نداشت.
 *   ۵) «پارامترِ اندازهٔ کاراکترِ ۲۰۰۰»: inspect_html همیشه از کاراکترِ صفرِ
 *      همان گره شروع می‌کرد و سقفش ۴۰۰۰ بود. در یک SPA، دو هزار کاراکترِ
 *      اولِ body فقط <div id="__next"> و چند wrapper است؛ راهی برای رفتن
 *      به کاراکترِ ۲۰۰۱ به بعد نبود ⇒ مدل همان تکهٔ بی‌فایده را بارها
 *      می‌گرفت تا سقفِ گام‌ها تمام شود.
 *
 *  پاسخِ ۱۰.۳۰: سه ابزارِ تازه (page_data، find_text، list_children)،
 *  inspect_html با offset و سقفِ ۱۲۰۰۰، نقشهٔ DOM که ویژگی‌ها را هم
 *  می‌بیند، سقفِ گام/فراخوانیِ بالاتر، و پرامپتی که دیگر دروغ نمی‌گوید.
 * ===================================================================== */

/** کلاس‌های «انسانی» یک گره — هش‌شده‌ها و کلاس‌های یک‌بارمصرف کنار گذاشته می‌شوند. */
function selagentNiceClasses(DOMElement $n): array {
    $out = [];
    foreach (preg_split('/\s+/', trim((string)$n->getAttribute('class')), -1, PREG_SPLIT_NO_EMPTY) as $c) {
        if (mb_strlen($c) > 40 || mb_strlen($c) < 2) continue;
        if (preg_match('/^(css|sc|jsx|_)-?[0-9a-f]{5,}$/i', $c)) continue;
        if (preg_match('/^[a-z]{1,4}[-_]?[0-9a-f]{6,}$/i', $c)) continue;
        $out[] = $c;
    }
    return $out;
}

/** ویژگی‌هایی که سلکتورِ ساخته‌شده از رویشان با تغییرِ استایلِ سایت نمی‌شکند. */
function selagentStableAttrs(): array {
    return ['data-testid', 'data-test', 'data-test-id', 'data-cy', 'data-qa',
            'itemprop', 'data-role', 'data-field', 'data-name', 'role', 'name'];
}

/**
 * v10.30 (۴۳الف): چند سلکتورِ کاندید برای یک گره، از پایدار به شکننده.
 *
 * ترتیب عمدی است: #id ← [data-testid] ← .کلاسِ معنادار ← تگِ خالی.
 * روی صفحاتِ هش‌شده تنها گزینهٔ زنده همان [data-testid] است، و تا ۱۰.۲۹
 * ایجنت اصلاً به آن فکر نمی‌کرد چون نه در نقشه می‌دیدش نه پرامپت اجازه
 * می‌داد.
 */
function selagentSelectorFor(DOMElement $n): array {
    $tag = strtolower($n->tagName);
    $c = [];
    $id = trim((string)$n->getAttribute('id'));
    if ($id !== '' && preg_match('~^[A-Za-z][\w:-]*$~', $id) && !preg_match('/[0-9a-f]{8,}/i', $id))
        $c[] = '#' . $id;
    foreach (selagentStableAttrs() as $at) {
        $v = trim((string)$n->getAttribute($at));
        if ($v === '' || mb_strlen($v) > 40) continue;
        if (preg_match('~["\'\]\[]~', $v)) continue;
        $c[] = $tag . '[' . $at . '="' . $v . '"]';
    }
    foreach (selagentNiceClasses($n) as $cl) $c[] = $tag . '.' . $cl;
    $c[] = $tag;
    return array_values(array_unique($c));
}

/**
 * v10.30 (۴۳الف) — ابزارِ find_text.
 *
 * مهم‌ترین ابزارِ تازه. کاربر روی صفحه یک قیمت یا یک عنوان *می‌بیند*؛
 * مسئلهٔ ایجنت این است که «کدام سلکتور همان را برمی‌دارد». تا ۱۰.۲۹ راهی
 * جز حدس‌زدنِ کلاس نبود. حالا مدل خودِ متن را می‌دهد و ما عمیق‌ترین گرهی
 * که آن را دربر دارد پیدا می‌کنیم و سلکتورهای کاندید را با تعدادِ تطبیقِ
 * واقعی برمی‌گردانیم.
 */
function selagentFindText(DOMXPath $xp, string $needle, int $limit = 6): array {
    $needle = trim(preg_replace('/\s+/u', ' ', $needle));
    if (mb_strlen($needle) < 2)
        return ['ok' => false, 'error' => 'متنِ جست‌وجو خیلی کوتاه است (حداقل ۲ کاراکتر)'];
    $limit = max(1, min(12, $limit));
    $nd = mb_strtolower(persianToEnglish($needle));

    $nodes = @$xp->query('//body//*');
    if (!$nodes || !$nodes->length) $nodes = @$xp->query('//*');
    $hits = []; $seen = 0;
    if ($nodes) foreach ($nodes as $n) {
        if (++$seen > 14000) break;
        if (!($n instanceof DOMElement)) continue;
        $tag = strtolower($n->tagName);
        if (in_array($tag, ['script', 'style', 'noscript', 'svg', 'path', 'head', 'html'], true)) continue;
        $txt = trim(preg_replace('/\s+/u', ' ', (string)$n->textContent));
        if ($txt === '' || mb_strlen($txt) > 4000) continue;
        if (mb_strpos(mb_strtolower(persianToEnglish($txt)), $nd) === false) continue;
        /* فقط عمیق‌ترین گره؛ وگرنه body و همهٔ والدها هم «تطبیق» می‌شوند. */
        $deepest = true;
        foreach ($n->childNodes as $ch) {
            if (!($ch instanceof DOMElement)) continue;
            $ct = trim(preg_replace('/\s+/u', ' ', (string)$ch->textContent));
            if ($ct !== '' && mb_strpos(mb_strtolower(persianToEnglish($ct)), $nd) !== false) { $deepest = false; break; }
        }
        if (!$deepest) continue;
        $hits[] = $n;
        if (count($hits) >= $limit) break;
    }

    if (!$hits) return ['ok' => false, 'found' => 0,
        'error' => 'این متن در HTMLِ صفحه نیست',
        'hint' => 'شاید با جاوااسکریپت ساخته می‌شود. ابزارِ page_data را صدا بزن؛ چنین مقادیری معمولاً در JSON-LD یا __NEXT_DATA__ هستند.'];

    $res = [];
    foreach ($hits as $n) {
        $row = ['tag' => strtolower($n->tagName),
                'text' => mb_substr(normalize_text($n->textContent), 0, 90),
                'candidates' => []];
        foreach (selagentSelectorFor($n) as $cand) {
            $x = cssToXpath($cand);
            if ($x === '') continue;
            $q = @$xp->query($x);
            if (!$q || !$q->length) continue;
            $row['candidates'][] = ['selector' => $cand, 'matches' => $q->length];
            if (count($row['candidates']) >= 4) break;
        }
        /* زنجیرهٔ والدها: وقتی خودِ گره سلکتورِ یکتا ندارد، «والد > فرزند»
           می‌سازد. همان کاری که یک انسان در وب‌تولز می‌کند. */
        $chain = []; $p = $n->parentNode;
        for ($i = 0; $i < 4 && $p instanceof DOMElement; $i++) {
            $cs = selagentSelectorFor($p);
            $chain[] = $cs[0];
            $p = $p->parentNode;
        }
        $row['ancestors'] = $chain;
        $res[] = $row;
    }
    return ['ok' => true, 'found' => count($res), 'hits' => $res,
            'hint' => 'هر کاندید را با probe_selector بسنج. اگر matches خیلی زیاد بود، سلکتورِ والد را با فاصله جلویش بگذار (مثل: div[data-testid="pdp"] span.price).'];
}

/**
 * v10.30 (۴۳الف) — ابزارِ list_children.
 *
 * برای وقتی که مدل ظرف را پیدا کرده ولی نمی‌داند داخلش چه هست. به‌جای
 * ریختنِ HTMLِ خام (که توکن می‌سوزاند و مدل‌های کوچک را گم می‌کند)، یک
 * جدولِ تمیز از فرزندان با سلکتورِ پیشنهادی و نمونهٔ متن می‌دهد.
 */
function selagentListChildren(DOMXPath $xp, string $selector, int $depth = 1, int $limit = 40): array {
    $selector = trim($selector);
    $depth = max(1, min(3, $depth));
    $limit = max(5, min(80, $limit));
    if ($selector === '') {
        $b = @$xp->query('//body');
        $root = ($b && $b->length) ? $b->item(0) : null;
    } else {
        $x = cssToXpath($selector);
        if ($x === '') return ['ok' => false, 'error' => 'سلکتور قابلِ ترجمه نیست'];
        $q = @$xp->query($x);
        if (!$q || !$q->length) return ['ok' => false, 'error' => 'عنصری با این سلکتور نیست'];
        $root = $q->item(0);
    }
    if (!($root instanceof DOMElement)) return ['ok' => false, 'error' => 'ریشه پیدا نشد'];

    $rows = [];
    $walk = function (DOMElement $el, int $d, string $pre) use (&$walk, &$rows, $depth, $limit, $xp) {
        foreach ($el->childNodes as $ch) {
            if (count($rows) >= $limit) return;
            if (!($ch instanceof DOMElement)) continue;
            $tag = strtolower($ch->tagName);
            if (in_array($tag, ['script', 'style', 'noscript', 'svg', 'path'], true)) continue;
            $sel = selagentSelectorFor($ch)[0];
            $txt = trim(preg_replace('/\s+/u', ' ', (string)$ch->textContent));
            $atts = [];
            foreach (selagentStableAttrs() as $at) {
                $v = trim((string)$ch->getAttribute($at));
                if ($v !== '' && mb_strlen($v) <= 40) $atts[] = $at . '=' . $v;
            }
            if ($tag === 'img') {
                foreach (['src', 'data-src', 'srcset'] as $at) {
                    $v = trim((string)$ch->getAttribute($at));
                    if ($v !== '') { $atts[] = $at . '=' . mb_substr($v, 0, 60); break; }
                }
            }
            if ($tag === 'a') {
                $v = trim((string)$ch->getAttribute('href'));
                if ($v !== '') $atts[] = 'href=' . mb_substr($v, 0, 60);
            }
            $rows[] = $pre . $sel
                    . ($atts ? (' | ' . implode(' ', array_slice($atts, 0, 3))) : '')
                    . ' | ' . ($txt === '' ? '—' : mb_substr($txt, 0, 60));
            if ($d < $depth) $walk($ch, $d + 1, $pre . '  ');
        }
    };
    $walk($root, 1, '');
    if (!$rows) return ['ok' => true, 'children' => 0,
        'note' => 'این عنصر فرزندِ عنصری ندارد (فقط متن). با inspect_html نگاهش کن.'];
    return ['ok' => true, 'children' => count($rows),
            'format' => 'سلکتورِ پیشنهادی | ویژگی‌ها | نمونهٔ متن',
            'rows' => $rows];
}

/** یک JSON را به خطوطِ «مسیر = مقدار» صاف می‌کند تا مدل بتواند بخواندش. */
function selagentJsonFlatten($node, string $prefix, array &$out, int $cap = 500, int $depth = 0): void {
    if (count($out) >= $cap || $depth > 14 || !is_array($node)) return;
    foreach ($node as $k => $v) {
        if (count($out) >= $cap) return;
        $p = ($prefix === '') ? (string)$k : ($prefix . '.' . $k);
        if (is_array($v)) { selagentJsonFlatten($v, $p, $out, $cap, $depth + 1); continue; }
        if (is_bool($v)) $v = $v ? 'true' : 'false';
        if ($v === null) continue;
        $s = trim(preg_replace('/\s+/u', ' ', (string)$v));
        if ($s === '') continue;
        $out[] = $p . ' = ' . mb_substr($s, 0, 160);
    }
}

/**
 * v10.30 (۴۳الف) — ابزارِ page_data: دادهٔ ساخت‌یافتهٔ صفحه.
 *
 * این همان چیزی است که نبودش ایجنت را روی صفحاتِ SPA زمین می‌زد. قیمت،
 * SKU، برند و توضیحاتِ چنین صفحاتی در HTMLِ رندرشده نیستند؛ در
 * application/ld+json یا __NEXT_DATA__ یا __NUXT__ یا متاتگ‌ها هستند.
 * وقتی مدل این‌ها را ببیند، دستِ‌کم می‌فهمد قیمتِ درست چند است و بعد با
 * find_text دنبالِ همان عدد در DOM می‌گردد.
 */
function selagentPageData(string $html, string $want = '', int $max = 3500): array {
    $max = max(600, min(9000, $max ?: 3500));
    $want = trim(mb_strtolower(persianToEnglish($want)));
    $sec = [];

    /* ۱) متاتگ‌ها — ارزان‌ترین و مطمئن‌ترین منبعِ عنوان/عکس/توضیح */
    $meta = [];
    if (preg_match_all('~<meta\b[^>]*>~i', $html, $mm)) {
        foreach ($mm[0] as $tag) {
            if (!preg_match('~(?:property|name|itemprop)\s*=\s*["\']([^"\']+)["\']~i', $tag, $k)) continue;
            if (!preg_match('~content\s*=\s*["\']([^"\']*)["\']~i', $tag, $v)) continue;
            $key = trim($k[1]); $val = trim(preg_replace('/\s+/u', ' ', html_entity_decode($v[1], ENT_QUOTES, 'UTF-8')));
            if ($val === '' || mb_strlen($key) > 50) continue;
            if (!preg_match('~^(og:|twitter:|product:|description$|keywords$|author$|price|sku|brand)~i', $key)) continue;
            $meta[] = $key . ' = ' . mb_substr($val, 0, 150);
            if (count($meta) >= 30) break;
        }
    }
    if ($meta) $sec['meta'] = $meta;

    /* ۲) JSON-LD */
    $ld = [];
    if (preg_match_all('~<script[^>]+application/ld\+json[^>]*>(.*?)</script>~si', $html, $m)) {
        foreach ($m[1] as $blk) {
            $d = json_decode(trim($blk), true);
            if (!is_array($d)) continue;
            selagentJsonFlatten($d, '', $ld, 220);
            if (count($ld) >= 220) break;
        }
    }
    if ($ld) $sec['json_ld'] = $ld;

    /* ۳) __NEXT_DATA__ / __NUXT__ / هر <script type="application/json"> */
    $emb = [];
    $blobs = [];
    if (preg_match('~<script[^>]*id=["\']__NEXT_DATA__["\'][^>]*>(.*?)</script>~si', $html, $m)) $blobs[] = $m[1];
    if (preg_match('~window\.__NUXT__\s*=\s*(\{.*?\});?\s*</script>~si', $html, $m)) $blobs[] = $m[1];
    if (preg_match_all('~<script[^>]+type=["\']application/json["\'][^>]*>(.*?)</script>~si', $html, $m)) {
        foreach ($m[1] as $b) { $blobs[] = $b; if (count($blobs) >= 6) break; }
    }
    /* __NEXT_DATA__ هم id دارد هم type="application/json"، پس با هر دو الگو
       گرفته می‌شود و بدونِ این dedupe هر خط دو بار به مدل می‌رسید. */
    $seenBlob = [];
    foreach ($blobs as $b) {
        $b = trim($b);
        $sig = md5($b);
        if (isset($seenBlob[$sig])) continue;
        $seenBlob[$sig] = 1;
        $d = json_decode($b, true);
        if (!is_array($d)) continue;
        selagentJsonFlatten($d, '', $emb, 900);
        if (count($emb) >= 900) break;
    }
    /* Next.js با App Router داده را تکه‌تکه در self.__next_f.push می‌ریزد؛
       آن‌جا JSON معتبرِ یکپارچه نداریم، پس جفتِ «کلید»:«مقدار» را برمی‌داریم. */
    if (!$emb && strpos($html, '__next_f') !== false) {
        if (preg_match_all('~"(title|name|price|final_price|min_price|sku|brand|category|stock|availability|description)"\s*:\s*("(?:[^"\\\\]|\\\\.){0,160}"|[0-9.]+)~i', $html, $m, PREG_SET_ORDER)) {
            foreach ($m as $one) {
                $emb[] = $one[1] . ' = ' . mb_substr(trim($one[2], '"'), 0, 160);
                if (count($emb) >= 200) break;
            }
        }
    }
    if ($emb) {
        /* این بخش می‌تواند هزاران خط باشد؛ فقط کلیدهای به‌دردبخور را نگه می‌داریم. */
        $keep = [];
        foreach ($emb as $line) {
            if (preg_match('~(^|\.)(title|name|price|final_price|min_price|max_price|discount|sku|code|barcode|brand|category|categories|stock|quantity|available|availability|description|summary|image|images|url|slug|weight|tag|tags)([0-9]*)\s*=~i', $line))
                $keep[] = $line;
            if (count($keep) >= 160) break;
        }
        $sec['embedded_json'] = $keep ?: array_slice($emb, 0, 60);
    }

    if (!$sec) return ['ok' => false,
        'error' => 'این صفحه هیچ دادهٔ ساخت‌یافته‌ای (JSON-LD، __NEXT_DATA__، متاتگ) ندارد',
        'hint' => 'پس داده در خودِ HTML است؛ با find_text و list_children جلو برو.'];

    /* فیلترِ اختیاری: مدل می‌تواند بگوید فقط دنبالِ «price» می‌گردم. */
    if ($want !== '') {
        foreach ($sec as $k => $lines) {
            $f = [];
            foreach ($lines as $l) if (mb_strpos(mb_strtolower(persianToEnglish($l)), $want) !== false) $f[] = $l;
            if ($f) $sec[$k] = $f; else unset($sec[$k]);
        }
        if (!$sec) return ['ok' => false, 'error' => 'در دادهٔ ساخت‌یافتهٔ صفحه چیزی شاملِ «' . $want . '» نبود'];
    }

    $txt = '';
    foreach ($sec as $k => $lines) {
        $txt .= '── ' . $k . " ──\n" . implode("\n", $lines) . "\n";
    }
    $trunc = false;
    if (mb_strlen($txt) > $max) { $txt = mb_substr($txt, 0, $max); $trunc = true; }
    return ['ok' => true, 'sections' => array_keys($sec), 'data' => $txt,
            'truncated' => $trunc,
            'hint' => $trunc ? 'بریده شد — با پارامترِ want (مثلاً want="price") فیلتر کن.' : ''];
}

/** مشخصاتِ ابزارها — با شرحِ فارسی، چون مدل‌ها با شرحِ دقیق بهتر ابزار می‌زنند. */
function selagentToolSpecs(string $kind): array {
    $fields = implode('، ', array_keys(selagentFields($kind)));
    $probeProps = [
        'field'    => ['type' => 'string', 'description' => 'فیلدی که این سلکتور برایش است. یکی از: ' . $fields],
        /* v10.30 (۴۳الف): شرحِ قبلی غلط بود و می‌گفت [attr] و :nth-child
           پشتیبانی نمی‌شوند. cssToXpath از v9.85 هر دو را ترجمه می‌کند و
           روی صفحاتِ با کلاسِ هش‌شده تنها گزینهٔ جواب‌ده همان [attr] است. */
        'selector' => ['type' => 'string', 'description' => 'سلکتورِ CSS. پشتیبانی می‌شود: تگ، .کلاس، #شناسه، [ویژگی]، [ویژگی="مقدار"]، [ویژگی^="شروع"]، [ویژگی*="شامل"]، [ویژگی$="پایان"]، :nth-child(n)، :first-child، :last-child، فاصله، > و کاما. پشتیبانی نمی‌شود: + و ~ و :not() و :hover.'],
    ];
    if ($kind === 'list') {
        $probeProps['scope'] = ['type' => 'string', 'description' => 'سلکتورِ ظرفِ محصول. برای همهٔ فیلدها به‌جز container حتماً این را بده تا سلکتور *داخلِ* ظرف سنجیده شود.'];
    }
    return [
        ['type' => 'function', 'function' => [
            'name' => 'probe_selector',
            'description' => 'یک سلکتورِ CSS را روی همین صفحه امتحان می‌کند و می‌گوید چند عنصر گرفت و *واقعاً* چه مقداری استخراج می‌شود. پیش از نهایی‌کردنِ هر فیلد حتماً این را صدا بزن؛ حدس زدن ممنوع است.',
            'parameters' => ['type' => 'object', 'properties' => $probeProps, 'required' => ['field', 'selector']],
        ]],
        ['type' => 'function', 'function' => [
            'name' => 'inspect_html',
            'description' => 'تکه‌ای از HTMLِ خامِ صفحه را نشان می‌دهد تا ساختارِ دقیقِ تگ‌ها را ببینی. وقتی نقشهٔ کلاس‌ها کافی نبود از این استفاده کن. اگر خروجی بریده شد (truncated=true) دوباره با offset برابرِ next_offset صدا بزن تا تکهٔ بعدی را ببینی.',
            'parameters' => ['type' => 'object', 'properties' => [
                'selector' => ['type' => 'string', 'description' => 'سلکتورِ عنصری که می‌خواهی HTMLش را ببینی؛ خالی یعنی ابتدای صفحه'],
                'max_chars' => ['type' => 'integer', 'description' => 'حداکثر کاراکتر (پیش‌فرض ۲۵۰۰، سقف ۱۲۰۰۰)'],
                'offset' => ['type' => 'integer', 'description' => 'از کاراکترِ چندم شروع شود (پیش‌فرض ۰). برای دیدنِ ادامهٔ یک تکهٔ بریده‌شده، این را برابرِ next_offset بگذار.'],
            ], 'required' => []],
        ]],
        /* v10.30 (۴۳الف): سه ابزارِ تازه — بدونِ این‌ها ایجنت روی صفحاتِ
           SPA (کلاسِ هش‌شده، دادهٔ داخلِ JSON) هیچ راهی نداشت. */
        ['type' => 'function', 'function' => [
            'name' => 'find_text',
            'description' => 'کارآمدترین ابزار: یک متنی را که روی صفحه می‌بینی (مثلاً قیمت «۲٬۴۵۰٬۰۰۰» یا بخشی از عنوانِ محصول) می‌دهی و این ابزار می‌گوید کدام عنصر آن را دربر دارد و چه سلکتورهایی به آن می‌رسند. وقتی کلاس‌های صفحه هش‌شده و بی‌معنی‌اند، از این شروع کن نه از حدس زدنِ کلاس.',
            'parameters' => ['type' => 'object', 'properties' => [
                'text'  => ['type' => 'string',  'description' => 'متنی که دنبالش می‌گردی؛ بخشی از آن هم کافی است'],
                'limit' => ['type' => 'integer', 'description' => 'حداکثر چند عنصر برگردد (پیش‌فرض ۶، سقف ۱۲)'],
            ], 'required' => ['text']],
        ]],
        ['type' => 'function', 'function' => [
            'name' => 'list_children',
            'description' => 'فرزندانِ یک عنصر را به‌صورتِ فهرستِ تمیز نشان می‌دهد: سلکتورِ پیشنهادیِ هرکدام، ویژگی‌های پایدارش و نمونهٔ متنش. وقتی ظرف را پیدا کرده‌ای و می‌خواهی بدانی داخلش چه چیزی هست، این را به‌جای inspect_html بزن؛ خیلی خواناتر است.',
            'parameters' => ['type' => 'object', 'properties' => [
                'selector' => ['type' => 'string',  'description' => 'سلکتورِ عنصرِ والد؛ خالی یعنی body'],
                'depth'    => ['type' => 'integer', 'description' => 'تا چند لایه پایین برود (پیش‌فرض ۱، سقف ۳)'],
                'limit'    => ['type' => 'integer', 'description' => 'حداکثر چند سطر (پیش‌فرض ۴۰، سقف ۸۰)'],
            ], 'required' => []],
        ]],
        ['type' => 'function', 'function' => [
            'name' => 'page_data',
            'description' => 'دادهٔ ساخت‌یافتهٔ صفحه را می‌خواند: متاتگ‌های og/product، JSON-LD و دادهٔ تزریق‌شدهٔ فریم‌ورک (__NEXT_DATA__ و مانندش). در سایت‌های مدرن قیمت و SKU و برند اغلب فقط این‌جا هستند و در HTMLِ دیده‌شده نیستند. اول این را بزن تا بدانی مقدارِ درست چیست، بعد با find_text دنبالِ همان مقدار در صفحه بگرد.',
            'parameters' => ['type' => 'object', 'properties' => [
                'want'      => ['type' => 'string',  'description' => 'فیلترِ اختیاری، مثلاً price یا sku یا brand — فقط خطوطی که این واژه در آن‌هاست برمی‌گردد'],
                'max_chars' => ['type' => 'integer', 'description' => 'حداکثر کاراکتر (پیش‌فرض ۳۵۰۰، سقف ۹۰۰۰)'],
            ], 'required' => []],
        ]],
        ['type' => 'function', 'function' => [
            'name' => 'submit_selectors',
            'description' => 'وقتی همهٔ سلکتورها را با probe_selector تأیید کردی، نتیجهٔ نهایی را با این ابزار تحویل بده. فیلدی که سلکتورِ مطمئنی برایش پیدا نکردی را اصلاً نفرست؛ سلکتورِ اشتباه از نبودِ سلکتور بدتر است.',
            'parameters' => ['type' => 'object', 'properties' => [
                'selectors' => ['type' => 'object', 'description' => 'نگاشتِ فیلد به سلکتور، مثلاً {"container":"li.product","title":"h2 a"}. کلیدهای مجاز: ' . $fields],
                'note' => ['type' => 'string', 'description' => 'توضیحِ کوتاهِ فارسی دربارهٔ ساختارِ صفحه و اینکه چه فیلدی پیدا نشد و چرا'],
            ], 'required' => ['selectors']],
        ]],
    ];
}

/** برچسبِ فارسیِ یک فراخوانی برای لاگِ زنده */
function selagentCallLabel(string $name, array $args): string {
    if ($name === 'probe_selector')
        return '🔬 آزمایشِ «' . (string)($args['selector'] ?? '') . '» برای ' . (string)($args['field'] ?? '?')
             . (trim((string)($args['scope'] ?? '')) !== '' ? (' داخلِ ' . $args['scope']) : '');
    if ($name === 'inspect_html')
        return '🔎 نگاه به HTMLِ ' . (trim((string)($args['selector'] ?? '')) === '' ? 'ابتدای صفحه' : $args['selector'])
             . (((int)($args['offset'] ?? 0)) > 0 ? (' از کاراکترِ ' . aiFaNum((int)$args['offset'])) : '');
    /* v10.30 (۴۳الف) */
    if ($name === 'find_text')
        return '🔤 جست‌وجوی متنِ «' . mb_substr((string)($args['text'] ?? ''), 0, 40) . '» در صفحه';
    if ($name === 'list_children')
        return '🌳 فرزندانِ ' . (trim((string)($args['selector'] ?? '')) === '' ? 'body' : $args['selector']);
    if ($name === 'page_data')
        return '🗄 خواندنِ دادهٔ ساخت‌یافتهٔ صفحه'
             . (trim((string)($args['want'] ?? '')) !== '' ? (' — فیلتر: ' . $args['want']) : '');
    if ($name === 'submit_selectors')
        return '📨 تحویلِ ' . aiFaNum(count((array)($args['selectors'] ?? []))) . ' سلکتور';
    return '🔧 ' . $name;
}

/** پیامِ سیستمی — قواعد را صریح و شماره‌دار می‌دهیم چون مدل‌های کوچک‌تر با شرحِ کلی گم می‌شوند. */
/* =====================================================================
 *  v10.27 (۴۰الف): دریافتِ صفحه برای ایجنت — «اول iframeِ پروکسی، بعد
 *  مستقیم با قابلیت‌های وب‌تولز».
 *
 *  چرا لازم شد: تا ۱۰.۲۶ هر دو ایجنت مستقیماً fetch_html($url, 25) را
 *  صدا می‌زدند. این یعنی سه چیز از مسیرِ جاافتادهٔ «بارگذاری صفحه» در تبِ
 *  سلکتور جا می‌افتاد:
 *    ۱) تنظیمِ «اتصالِ غیرمستقیمِ همین پروفایل» اصلاً اعمال نمی‌شد؛
 *    ۲) مهلت ثابتِ ۲۵ ثانیه بود، نه مهلتِ تنظیماتِ کاربر (پیش‌فرض ۴۵)؛
 *    ۳) هیچ تلاشِ دومی برای کندی نبود.
 *  نتیجه‌اش این می‌شد که صفحه‌ای که در iframeِ انتخابگر عالی باز می‌شد،
 *  زیرِ دستِ ایجنت «دریافتِ صفحه ناموفق بود» می‌گرفت.
 *
 *  حالا دقیقاً همان دو پلهٔ ?visual_proxy طی می‌شود، و اگر باز هم نشد،
 *  پلهٔ سومی اضافه شده که معادلِ «🌐 بارگذاری مستقیم / 🔍 بازرسی تمام
 *  صفحه» است: بدونِ پروکسی و بدونِ iframe، همان‌طور که وب‌تولزِ مرورگر
 *  صفحه را می‌گیرد. روی سایت‌هایی که فقط پروکسی/Worker را می‌بندند این
 *  پله جواب می‌دهد.
 *
 *  خروجی: همان آرایهٔ fetch_html به‌علاوهٔ کلیدِ via = proxy|direct|none
 * ===================================================================== */
function selagentFetchPage(string $url, string $pk = '', string $label = 'صفحه'): array {
    $cn = function_exists('loadConnections') ? loadConnections() : [];
    $t = (int)($cn['proxy_timeout_sec'] ?? 0);
    if ($t <= 0) $t = 45;
    $t = max(10, min(180, $t));

    /* پلهٔ ۱ — همان مسیرِ iframeِ پروکسی: اتصالِ پروفایل + مهلتِ تنظیمات */
    selagentProgress(['log_add' => ['🖼 آزمایشِ باز شدنِ ' . $label . ' از راهِ iframeِ پروکسی…']]);
    srcNetSetProfileIndirect($pk);
    $res = fetch_html($url, $t);
    if (empty($res['ok']) && selagentSlowError((string)($res['error'] ?? ''))) {
        selagentProgress(['log_add' => ['   ↳ کند بود؛ تلاشِ دوم با مهلتِ '
            . aiFaNum(min(180, $t * 2)) . ' ثانیه…']]);
        $res = fetch_html($url, min(180, $t * 2));
    }
    if (!empty($res['ok'])) {
        $res['via'] = 'proxy';
        selagentProgress(['fetch_via' => 'proxy',
            'log_add' => ['   ↳ ✅ ' . $label . ' از راهِ پروکسی باز شد']]);
        return $res;
    }
    $proxyErr = (string)($res['error'] ?? 'ناموفق');

    /* پلهٔ ۲ — «وب‌تولز»: مستقیم، بدونِ پروکسی و بدونِ iframe */
    selagentProgress(['log_add' => ['   ↳ ⚠️ از راهِ پروکسی باز نشد ('
        . mb_substr($proxyErr, 0, 60) . ') — تلاشِ مستقیم با قابلیت‌های وب‌تولز…']]);
    $GLOBALS['_srcNetProfileIndirect'] = false;      // اجبار به اتصالِ مستقیم
    $res2 = fetch_html($url, max(30, $t));
    if (empty($res2['ok']) && selagentSlowError((string)($res2['error'] ?? ''))) {
        $res2 = fetch_html($url, min(180, max(60, $t * 2)));
    }
    if (!empty($res2['ok'])) {
        $res2['via'] = 'direct';
        selagentProgress(['fetch_via' => 'direct',
            'log_add' => ['   ↳ ✅ ' . $label . ' به‌صورتِ مستقیم (وب‌تولز) باز شد']]);
        return $res2;   // اتصالِ مستقیم را نگه می‌داریم؛ بقیهٔ درخواست‌ها هم از همین راه
    }
    srcNetSetProfileIndirect($pk);                   // برگرداندنِ حالتِ پروفایل
    $directErr = (string)($res2['error'] ?? 'ناموفق');
    selagentProgress(['fetch_via' => 'none',
        'log_add' => ['   ↳ ❌ نه پروکسی نه مستقیم — ' . mb_substr($directErr, 0, 60)]]);
    return ['ok' => false, 'via' => 'none',
            'error' => 'پروکسی: ' . $proxyErr . ' · مستقیم: ' . $directErr,
            'proxy_error' => $proxyErr, 'direct_error' => $directErr,
            'code' => (int)($res2['code'] ?? 0), 'url' => $url, 'html' => ''];
}

/** آیا این خطا از جنسِ «کند بود» است؟ فقط برای این‌ها تلاشِ دوم می‌ارزد. */
function selagentSlowError(string $e): bool {
    return stripos($e, 'timed out') !== false || stripos($e, 'timeout') !== false
        || stripos($e, 'Empty') !== false || trim($e) === '';
}

/* =====================================================================
 *  v10.27 (۴۰ب): «ایجنتِ جزئیات وقتی هیچ محصولی نیست».
 *
 *  تا ۱۰.۲۶ اگر کاربر روی «🤖 پیشنهاد (ایجنت)»ِ زیرتبِ جزئیات می‌زد و
 *  هنوز محصولی استخراج نشده بود، فقط یک توستِ «ابتدا محصولات را استخراج
 *  کنید» می‌گرفت و کار همان‌جا می‌ایستاد. ولی همهٔ چیزهایی که برای برداشتنِ
 *  آن قدم لازم است همین‌جا موجود است: آدرسِ صفحهٔ فهرست، ایجنتِ کشفِ
 *  سلکتورِ فهرست، و parse_with_selectors. پس خودِ ایجنت زنجیره را کامل
 *  می‌کند: سلکتورِ فهرست ← چند محصول ← صفحهٔ نمونه ← سلکتورهای جزئیات.
 *
 *  ترتیبِ عمداً محافظه‌کارانه (ارزان به گران):
 *    ۱) محصولاتِ ذخیره‌شدهٔ همین پروفایل روی دیسک
 *    ۲) سلکتورِ فهرستِ ذخیره‌شدهٔ همین پروفایل روی صفحهٔ فهرست
 *    ۳) اجرای کاملِ ایجنتِ کشفِ سلکتورِ فهرست، بعد استخراج
 *
 *  چرا selagentRun مستقیم صدا زده می‌شود و نه اندپوینتِ ?selagent_start:
 *  آن اندپوینت SELAGENT_LOCK_FILE را می‌گیرد و ما همین حالا داخلِ همان
 *  قفل هستیم؛ صدا زدنش قطعاً «یک کشف در جریان است» می‌گرفت.
 * ===================================================================== */
function selagentSeedProducts(string $listUrl, string $pk, string $model = '', int $want = 12): array {
    $out = ['ok' => false, 'products' => [], 'list_selectors' => [], 'from' => '', 'error' => ''];
    $listUrl = trim($listUrl);
    if ($pk === '' && $listUrl !== '') $pk = profileKey($listUrl);

    /* ۱) محصولاتِ روی دیسک */
    $profiles = loadProfiles();
    $prof = is_array($profiles[$pk] ?? null) ? $profiles[$pk] : [];
    $stored = [];
    foreach (profileProductsMap($prof) as $k => $p) {
        if (is_array($p) && trim((string)($p['link'] ?? '')) !== '') {
            $p['key'] = (string)$k;
            $stored[] = [(string)$k, $p];
            if (count($stored) >= $want) break;
        }
    }
    if ($stored) {
        selagentProgress(['log_add' => ['📦 ' . aiFaNum(count($stored))
            . ' محصولِ ذخیره‌شدهٔ این پروفایل پیدا شد — نیازی به استخراجِ تازه نیست']]);
        return ['ok' => true, 'products' => $stored, 'list_selectors' => (array)($prof['selectors'] ?? []),
                'from' => 'stored', 'error' => ''];
    }

    $listUrl = s4NormalizeInputUrl($listUrl);
    if ($listUrl === '' || !filter_var($listUrl, FILTER_VALIDATE_URL)) {
        $out['error'] = 'برای ساختنِ محصولِ نمونه، آدرسِ صفحهٔ فهرست لازم است';
        return $out;
    }

    /* ۲) سلکتورِ فهرستِ ذخیره‌شده */
    $sel = (array)($prof['selectors'] ?? []);
    $from = 'profile_selectors';
    if (trim((string)($sel['container'] ?? '')) === '') {
        /* ۳) هیچ سلکتوری نیست ⇒ ایجنتِ فهرست را همین‌جا اجرا کن */
        selagentProgress(['phase' => 'chain', 'log_add' => [
            '🔗 هیچ محصولی در نتایج و در پروفایل نیست — اول ایجنتِ کشفِ سلکتورِ فهرست اجرا می‌شود',
        ], 'convo_add' => [['role' => 'system',
            'text' => 'برای صفحهٔ جزئیات هیچ محصولی موجود نیست؛ ابتدا ایجنتِ فهرست روی ' . $listUrl . ' اجرا می‌شود.']]]);
        $sub = selagentRun($listUrl, 'list', $model, $pk);
        if (empty($sub['ok'])) {
            $out['error'] = 'ایجنتِ فهرست موفق نشد: ' . (string)($sub['error'] ?? '');
            return $out;
        }
        $sel = (array)($sub['selectors'] ?? []);
        $from = 'agent';
        if (trim((string)($sel['container'] ?? '')) === '') {
            $out['error'] = 'ایجنتِ فهرست سلکتورِ ظرفِ محصول پیدا نکرد';
            $out['list_selectors'] = $sel;
            return $out;
        }
        selagentProgress(['log_add' => ['   ↳ ✅ سلکتورِ فهرست کشف شد: ' . (string)$sel['container']]]);
    } else {
        selagentProgress(['log_add' => ['🔗 سلکتورِ فهرستِ ذخیره‌شدهٔ پروفایل استفاده می‌شود: '
            . (string)$sel['container']]]);
    }

    /* حالا صفحهٔ فهرست را بگیر و چند محصول بیرون بکش */
    selagentProgress(['phase' => 'chain', 'log_add' => ['🧺 استخراجِ چند محصول از صفحهٔ فهرست…']]);
    $lres = selagentFetchPage($listUrl, $pk, 'صفحهٔ فهرست');
    if (empty($lres['ok'])) {
        $out['error'] = 'صفحهٔ فهرست باز نشد — ' . (string)($lres['error'] ?? '');
        $out['list_selectors'] = $sel;
        return $out;
    }
    $rows = parse_with_selectors((string)$lres['html'], (string)($lres['url'] ?? $listUrl), $sel);
    $pairs = [];
    foreach ($rows as $k => $p) {
        if (!is_array($p) || trim((string)($p['link'] ?? '')) === '') continue;
        $p['key'] = (string)$k;
        $pairs[] = [(string)$k, $p];
        if (count($pairs) >= $want) break;
    }
    if (!$pairs) {
        $out['error'] = 'از صفحهٔ فهرست هیچ محصولِ دارای لینکی استخراج نشد';
        $out['list_selectors'] = $sel;
        return $out;
    }
    selagentProgress(['log_add' => ['   ↳ ✅ ' . aiFaNum(count($pairs)) . ' محصول استخراج شد']]);

    /* در پروفایل هم بنشانیم تا دفعهٔ بعد این زنجیره لازم نشود */
    $profiles = loadProfiles();
    if (empty($GLOBALS['_profilesCorrupt'])) {
        if (!is_array($profiles[$pk] ?? null)) $profiles[$pk] = ['url' => $listUrl, 'created' => time()];
        if (trim((string)($profiles[$pk]['url'] ?? '')) === '') $profiles[$pk]['url'] = $listUrl;
        if (trim((string)(((array)($profiles[$pk]['selectors'] ?? []))['container'] ?? '')) === '')
            $profiles[$pk]['selectors'] = $sel;
        if (!profileProductsMap($profiles[$pk])) $profiles[$pk]['products'] = $pairs;
        $profiles[$pk]['updated'] = time();
        @saveProfiles($profiles);
    }

    return ['ok' => true, 'products' => $pairs, 'list_selectors' => $sel, 'from' => $from, 'error' => ''];
}

/* =====================================================================
 *  v10.30 (۴۳ب): پرامپتِ سفارشیِ ایجنتِ کشفِ سلکتور.
 *
 *  چرا: پرامپتِ پیش‌فرض عمومی است، ولی کاربر سایت‌های خودش را می‌شناسد
 *  («در این فروشگاه قیمتِ درست همیشه دومی است»، «برچسبِ تخفیف را نگیر»).
 *  تا ۱۰.۲۹ هیچ راهی برای گفتنِ این‌ها به ایجنت نبود.
 *
 *  طراحی عمداً محافظه‌کارانه است:
 *   • دو حالت — «افزودن» (پیش‌فرض؛ متنِ کاربر ته پرامپتِ استاندارد
 *     می‌چسبد) و «جایگزینی» (کاربر کلِ پرامپت را خودش می‌نویسد).
 *   • جایگزینی خطرناک است، چون اگر کاربر یادش برود بگوید «در پایان
 *     submit_selectors را صدا بزن» ایجنت هیچ‌وقت نتیجه نمی‌دهد. پس
 *     در هر دو حالت یک «حداقلِ ضروری» ته متن اضافه می‌شود.
 *   • برای هر kind (فهرست/جزئیات) یک متنِ جدا نگه داشته می‌شود.
 *   • جانگهدارها: {{url}} {{kind}} {{fields}} {{default}}
 * ===================================================================== */

/** پرامپت‌های سفارشیِ ذخیره‌شده. ساختار: [list=>[mode,text], detail=>[...]] */
function selagentLoadPrompts(): array {
    $d = [];
    if (is_file(SELAGENT_PROMPT_FILE)) {
        $j = json_decode((string)@file_get_contents(SELAGENT_PROMPT_FILE), true);
        if (is_array($j)) $d = $j;
    }
    $out = [];
    foreach (['list', 'detail'] as $k) {
        $row = is_array($d[$k] ?? null) ? $d[$k] : [];
        $mode = (string)($row['mode'] ?? 'append');
        if (!in_array($mode, ['append', 'replace', 'off'], true)) $mode = 'append';
        $out[$k] = ['mode' => $mode, 'text' => (string)($row['text'] ?? '')];
    }
    $out['updated'] = (int)($d['updated'] ?? 0);
    return $out;
}

function selagentSavePrompts(array $p): bool {
    $out = ['updated' => time()];
    foreach (['list', 'detail'] as $k) {
        $row = is_array($p[$k] ?? null) ? $p[$k] : [];
        $mode = (string)($row['mode'] ?? 'append');
        if (!in_array($mode, ['append', 'replace', 'off'], true)) $mode = 'append';
        /* سقف تا یک پرامپتِ اشتباهاً چسبانده‌شده (مثلاً کلِ یک صفحهٔ HTML)
           هر بار کلِ پنجرهٔ متنِ مدل را نخورد. */
        $out[$k] = ['mode' => $mode, 'text' => mb_substr(trim((string)($row['text'] ?? '')), 0, 8000)];
    }
    return (bool)@file_put_contents(SELAGENT_PROMPT_FILE,
        json_encode($out, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT), LOCK_EX);
}

/** markupِ ویرایشگرِ پرامپت؛ چون برای هر دو زیرتب یکسان است یک‌جا ساخته می‌شود. */
function selagentPromptEditorHtml(string $kind): string {
    $k   = ($kind === 'detail') ? 'detail' : 'list';
    $cfg = selagentLoadPrompts()[$k];
    $fa  = ($k === 'detail') ? 'جزئیاتِ محصول' : 'فهرستِ محصولات';
    $md  = $cfg['mode'];
    $on  = ($cfg['text'] !== '' && $md !== 'off');
    $r   = function ($v) use ($md) { return $md === $v ? ' checked' : ''; };
    $h  = '<details class="sprompt" id="sprompt-' . $k . '">';
    $h .= '<summary>🧠 پرامپتِ ایجنتِ کشفِ سلکتورِ ' . $fa
        . ' <span class="sprompt-badge" id="spromptBadge-' . $k . '">'
        . ($on ? ($md === 'replace' ? 'جایگزینِ سفارشی' : 'افزودهٔ سفارشی') : 'پیش‌فرض')
        . '</span></summary>';
    $h .= '<div class="sprompt-bd">';
    $h .= '<div class="sprompt-note">دستورالعملِ اختصاصیِ خودت را برای این ایجنت بنویس؛ مثلاً «قیمتِ نهایی همیشه عنصرِ دوم است، اولی قیمتِ خط‌خورده است» یا «برچسبِ تخفیف را به‌عنوانِ قیمت انتخاب نکن».</div>';
    $h .= '<div class="sprompt-modes">'
        . '<label><input type="radio" name="spmode-' . $k . '" value="append" onchange="spromptDirty(\'' . $k . '\')"' . $r('append') . '> افزودن به پرامپتِ استاندارد (امن)</label>'
        . '<label><input type="radio" name="spmode-' . $k . '" value="replace" onchange="spromptDirty(\'' . $k . '\')"' . $r('replace') . '> جایگزینیِ کاملِ پرامپت</label>'
        . '<label><input type="radio" name="spmode-' . $k . '" value="off" onchange="spromptDirty(\'' . $k . '\')"' . $r('off') . '> غیرفعال (فقط پیش‌فرض)</label>'
        . '</div>';
    $h .= '<textarea id="spromptText-' . $k . '" oninput="spromptDirty(\'' . $k . '\')" placeholder="مثال: در این سایت عنوانِ محصول داخلِ h1 با ویژگیِ data-testid است. قیمت را از عنصری بگیر که کلمهٔ «تومان» کنارش باشد.">'
        . htmlspecialchars($cfg['text'], ENT_QUOTES, 'UTF-8') . '</textarea>';
    $h .= '<div class="sprompt-ph">جانگهدارها (کلیک = درج): '
        . '<code onclick="spromptIns(\'' . $k . '\',\'{{url}}\')">{{url}}</code> '
        . '<code onclick="spromptIns(\'' . $k . '\',\'{{kind}}\')">{{kind}}</code> '
        . '<code onclick="spromptIns(\'' . $k . '\',\'{{fields}}\')">{{fields}}</code> '
        . '<code onclick="spromptIns(\'' . $k . '\',\'{{default}}\')">{{default}}</code>'
        . ' — <b>{{default}}</b> کلِ پرامپتِ استاندارد را همان‌جا می‌گذارد (به‌دردِ حالتِ جایگزینی می‌خورد).</div>';
    $h .= '<div style="display:flex;gap:8px;flex-wrap:wrap">'
        . '<button class="btn" style="font-size:11.5px;padding:6px 12px" onclick="spromptSave(\'' . $k . '\')">💾 ذخیرهٔ پرامپت</button>'
        . '<button class="btn btn-secondary" style="font-size:11.5px;padding:6px 12px" onclick="spromptPreview(\'' . $k . '\')">👁 پیش‌نمایشِ پرامپتِ نهایی</button>'
        . '<button class="btn btn-secondary" style="font-size:11.5px;padding:6px 12px" onclick="spromptShowDefault(\'' . $k . '\')">📄 دیدنِ پرامپتِ پیش‌فرض</button>'
        . '<button class="btn btn-secondary" style="font-size:11.5px;padding:6px 12px" onclick="spromptReset(\'' . $k . '\')">↩️ خالی‌کردن</button>'
        . '<span id="spromptMsg-' . $k . '" style="font-size:11px;color:#94a3b8;align-self:center"></span>'
        . '</div>';
    $h .= '<div class="sprompt-out hidden" id="spromptOut-' . $k . '"></div>';
    $h .= '<div class="sprompt-note">⚠️ در حالتِ «جایگزینی» هم چند قاعدهٔ فنیِ ضروری (تأیید با probe_selector، صدا زدنِ submit_selectors، نحوِ سلکتورهای مجاز) به‌صورتِ خودکار ته پرامپت اضافه می‌شوند تا ایجنت خراب نشود.</div>';
    $h .= '</div></details>';
    return $h;
}

/** قواعدی که بدونشان ایجنت اصلاً کار نمی‌کند — حتی در حالتِ «جایگزینی» می‌مانند. */
function selagentPromptFloor(string $kind): string {
    return "\n\n[قواعدِ فنیِ ثابت — این‌ها را نمی‌شود تغییر داد]\n"
         . "• هرگز سلکتوری را تحویل نده که با probe_selector تأیید نکرده‌ای.\n"
         . "• در پایان حتماً ابزارِ submit_selectors را صدا بزن؛ بدونِ آن هیچ نتیجه‌ای ثبت نمی‌شود.\n"
         . "• سلکتورهای پشتیبانی‌شده: تگ، .کلاس، #شناسه، [ویژگی]، [ویژگی=\"مقدار\"]، [ویژگی^=]، [ویژگی*=]، [ویژگی\$=]، :nth-child(n)، :first-child، :last-child، فاصله، > و کاما."
         . " پشتیبانی نمی‌شوند: + و ~ و :not() و شبه‌کلاس‌های حالت.\n"
         . "• کلیدهای مجازِ خروجی: " . implode('، ', array_keys(selagentFields($kind))) . "\n";
}

/** متنِ پیش‌فرضِ کارخانه — همان چیزی که تا ۱۰.۲۹ ثابت بود. */
function selagentDefaultPrompt(string $kind, string $url): string {
    $s  = "تو یک متخصصِ استخراجِ داده از صفحاتِ وب هستی. وظیفه‌ات پیدا کردنِ سلکتورهای CSSِ درست برای یک صفحهٔ مشخص است.\n";
    $s .= "آدرسِ صفحه: " . $url . "\n\n";
    if ($kind === 'list') {
        $s .= "این صفحه یک «فهرستِ محصولات» است. باید این فیلدها را پیدا کنی:\n";
        $s .= "- container: سلکتورِ ظرفی که *هر محصول* را دربر می‌گیرد. مهم‌ترین فیلد است؛ اگر این غلط باشد بقیه بی‌فایده‌اند. ظرفِ درست معمولاً بین ۵ تا ۱۰۰ بار در صفحه تکرار شده و داخلِ هرکدام هم لینک هست هم عنوان.\n";
        $s .= "- title: عنوانِ محصول، *داخلِ* ظرف\n- price: قیمت، داخلِ ظرف\n- link: لینکِ صفحهٔ محصول، داخلِ ظرف\n- image: عکسِ محصول، داخلِ ظرف\n\n";
        $s .= "روشِ کار:\n";
        $s .= "۱) اول container را با probe_selector پیدا و تأیید کن. تعدادِ تطبیق باید منطقی باشد (نه ۱، نه ۵۰۰) و نمونه‌ها باید هم عنوان هم لینک داشته باشند.\n";
        $s .= "۲) بعد برای هر فیلدِ دیگر probe_selector را با پارامترِ scope برابرِ همان container صدا بزن. سلکتورِ فیلد باید *نسبی* باشد (مثل h2 a) نه مطلق.\n";
        $s .= "۳) اگر نتیجه empty بود یا warning داشت، آن سلکتور را نپذیر و سلکتورِ دیگری امتحان کن.\n";
    } else {
        $s .= "این صفحه یک «صفحهٔ جزئیاتِ یک محصول» است. باید سلکتورهای این فیلدها را پیدا کنی:\n";
        foreach (selagentFields('detail') as $k => $fa) $s .= "- $k: $fa\n";
        $s .= "\nروشِ کار:\n";
        $s .= "۱) برای هر فیلد یک سلکتور حدس بزن و با probe_selector تأییدش کن.\n";
        $s .= "۲) نمونه‌ای که برمی‌گردد را بخوان: اگر متنِ برگشتی به آن فیلد نمی‌خورد (مثلاً برای «وزن» یک پاراگرافِ توضیحات آمده) آن را نپذیر.\n";
        $s .= "۳) فیلدی که واقعاً روی این صفحه وجود ندارد را رها کن؛ لازم نیست همهٔ فیلدها پر شوند.\n";
    }

    /* v10.30 (۴۳الف): بخشِ تازه — دستورالعملِ صفحاتِ SPA.
       بدونِ این، مدل روی صفحه‌ای با کلاس‌های هش‌شده فقط کلاس حدس می‌زند و
       بعد از چند گام به سقف می‌خورد. حالا مسیرِ درست را صریح می‌گوییم. */
    $s .= "\nابزارهایی که داری و ترتیبِ درستِ استفاده‌شان:\n";
    $s .= "• page_data — دادهٔ ساخت‌یافتهٔ صفحه (متاتگ‌ها، JSON-LD، __NEXT_DATA__). قیمت و SKU و برندِ درست معمولاً این‌جاست.\n";
    $s .= "• find_text — متنی را که می‌دانی روی صفحه هست می‌دهی و سلکتورهای رسیدن به آن را می‌گیری.\n";
    $s .= "• list_children — فرزندانِ یک عنصر را خوانا فهرست می‌کند (به‌جای HTMLِ خام).\n";
    $s .= "• inspect_html — HTMLِ خام؛ اگر بریده شد با offset=next_offset ادامه‌اش را بگیر.\n";
    $s .= "• probe_selector — سنجشِ واقعیِ یک سلکتور روی همین صفحه.\n";
    $s .= "• submit_selectors — تحویلِ نتیجهٔ نهایی.\n\n";
    $s .= "اگر کلاس‌های صفحه هش‌شده و بی‌معنی بودند (مثل css-1a2b3c) این مسیر را برو:\n";
    $s .= "الف) page_data را بزن تا مقدارِ درستِ فیلدها (مثلاً عددِ قیمت) را ببینی.\n";
    $s .= "ب) همان مقدار را به find_text بده تا بفهمی کدام عنصر آن را نشان می‌دهد.\n";
    $s .= "پ) از کاندیدهای برگشتی، آن‌که ویژگیِ پایدار دارد ([data-testid]، [itemprop]، #id) را انتخاب کن نه کلاسِ هش‌شده را.\n";
    $s .= "ت) با probe_selector تأییدش کن.\n";

    $s .= "\nقواعدِ عمومی:\n";
    $s .= "۴) هرگز سلکتوری را تحویل نده که با probe_selector تأیید نکرده‌ای.\n";
    $s .= "۵) سلکتور را تا جای ممکن ساده نگه دار، ولی [ویژگی=\"مقدار\"] و :nth-child مجازند و روی سایت‌های مدرن اغلب تنها راه‌اند. فقط + و ~ و :not() کار نمی‌کنند.\n";
    $s .= "۶) کلاس‌های هش‌شده و تصادفی (مثل .css-1x2y3z) را انتخاب نکن؛ با تغییرِ سایت می‌شکنند. کلاسِ معنادار یا ویژگیِ پایدار را ترجیح بده.\n";
    $s .= "۷) اگر یک ابزار دو بار پشتِ سرِ هم همان نتیجه را داد، تکرارش نکن؛ ابزارِ دیگری را امتحان کن.\n";
    $s .= "۸) در پایان حتماً submit_selectors را صدا بزن.\n";
    $s .= "همیشه فارسی توضیح بده.";
    return $s;
}

/**
 * پرامپتِ نهایی = پیش‌فرض (یا متنِ کاربر) + قواعدِ فنیِ ثابت.
 *
 * $override برای «پیش‌نمایش» در UI است تا کاربر بدونِ ذخیره‌کردن ببیند
 * متنش چه شکلی درمی‌آید.
 */
function selagentSystemPrompt(string $kind, string $url, ?array $override = null): string {
    $kind = ($kind === 'detail') ? 'detail' : 'list';
    $def = selagentDefaultPrompt($kind, $url);

    $cfg = $override ?? (selagentLoadPrompts()[$kind] ?? ['mode' => 'append', 'text' => '']);
    $mode = (string)($cfg['mode'] ?? 'append');
    $txt  = trim((string)($cfg['text'] ?? ''));

    if ($txt === '' || $mode === 'off') return $def;

    /* جانگهدارها — تا کاربر بتواند متنِ پیش‌فرض را داخلِ متنِ خودش جا بدهد */
    $txt = strtr($txt, [
        '{{url}}'     => $url,
        '{{kind}}'    => ($kind === 'detail' ? 'صفحهٔ جزئیاتِ محصول' : 'صفحهٔ فهرستِ محصولات'),
        '{{fields}}'  => implode('، ', array_keys(selagentFields($kind))),
        '{{default}}' => $def,
    ]);

    if ($mode === 'replace') return $txt . selagentPromptFloor($kind);
    return $def . "\n\n[دستورالعملِ اختصاصیِ کاربر — بر قواعدِ بالا اولویت دارد، مگر قواعدِ فنیِ ثابت]\n" . $txt;
}

/**
 * حلقهٔ ایجنتِ کشفِ سلکتور.
 *
 * ساختارش عمداً آینهٔ agentRun است (همان fallbackِ حالتِ متنی برای مدل‌هایی
 * که tools ندارند، همان سقف‌ها، همان الگوی ثبتِ پیشرفت) تا نگهداری‌اش یک
 * چیز باشد نه دو چیز.
 */
function selagentRun(string $url, string $kind, string $model = '', string $pk = '', string $listUrl = '', ?array $checkpoint = null): array {
    $t0 = microtime(true);
    $kind = ($kind === 'detail') ? 'detail' : 'list';
    $url = trim($url); $listUrl = trim($listUrl);
    if ($pk === '') $pk = profileKey($url !== '' ? $url : $listUrl);
    $resumeCp = is_array($checkpoint) && is_array($checkpoint['messages'] ?? null)
        && count($checkpoint['messages']) >= 2 ? $checkpoint : null;
    if ($resumeCp !== null && filter_var((string)($resumeCp['effective_url'] ?? ''), FILTER_VALIDATE_URL))
        $url = (string)$resumeCp['effective_url'];
    $seeded = $resumeCp !== null && is_array($resumeCp['seeded'] ?? null) ? $resumeCp['seeded'] : null;

    /* v10.27 (۴۰ب): ایجنتِ جزئیات بدونِ هیچ محصولی هم باید بتواند شروع کند.
       آدرسِ صفحهٔ نمونه خالی است ⇒ خودمان می‌سازیمش: سلکتورِ فهرست (از
       پروفایل یا با اجرای ایجنتِ فهرست) ← استخراجِ چند محصول ← لینکِ اولی. */
    if ($resumeCp === null && $kind === 'detail' && ($url === '' || !filter_var($url, FILTER_VALIDATE_URL))) {
        $seed = selagentSeedProducts($listUrl, $pk, $model);
        if (empty($seed['ok'])) {
            $err = 'برای کشفِ سلکتورهای جزئیات صفحهٔ محصولی در دست نبود و ساختنش هم نشد — '
                 . (string)($seed['error'] ?? '');
            selagentProgress(['log_add' => ['❌ ' . $err]]);
            return ['ok' => false, 'error' => $err, 'url' => $url, 'kind' => $kind,
                    'seeded' => $seed, 'took' => round(microtime(true) - $t0, 1)];
        }
        $seeded = $seed;
        $url = (string)($seed['products'][0][1]['link'] ?? '');
        selagentProgress(['phase' => 'fetch', 'log_add' => [
            '🎯 صفحهٔ نمونه از محصولِ «'
            . mb_substr((string)($seed['products'][0][1]['title'] ?? '—'), 0, 40) . '» انتخاب شد',
        ], 'convo_add' => [['role' => 'system',
            'text' => aiFaNum(count($seed['products'])) . ' محصول آماده شد؛ صفحهٔ نمونه: ' . $url]]]);
    }

    selagentProgress(['phase' => 'fetch', 'log_add' => ['🌐 دریافتِ صفحه…']]);
    $res = selagentFetchPage($url, $pk, $kind === 'detail' ? 'صفحهٔ محصول' : 'صفحهٔ فهرست');
    if (empty($res['ok'])) {
        $err = 'دریافتِ صفحه ناموفق بود: ' . (string)($res['error'] ?? '')
             . ' — این صفحه نه از راهِ iframeِ پروکسی باز شد نه به‌صورتِ مستقیم.'
             . ' می‌توانید در تبِ سلکتور «🌐 بارگذاری مستقیم» یا «🔍 بازرسی تمام صفحه» را بزنید،'
             . ' یا با «📋 اسکریپت بازرسی» سلکتور را دستی بردارید.';
        selagentProgress(['log_add' => ['❌ ' . $err]]);
        return ['ok' => false, 'error' => $err, 'url' => $url, 'kind' => $kind,
                'via' => (string)($res['via'] ?? 'none'), 'seeded' => $seeded,
                'took' => round(microtime(true) - $t0, 1)];
    }
    $fetchVia = (string)($res['via'] ?? 'proxy');
    selagentProgress(['convo_add' => [['role' => 'system',
        'text' => 'صفحه ' . ($fetchVia === 'direct'
            ? 'از راهِ iframeِ پروکسی باز نشد؛ به‌صورتِ مستقیم (قابلیت‌های وب‌تولز) گرفته شد.'
            : 'از راهِ iframeِ پروکسی گرفته شد.')]]]);
    $html = (string)$res['html'];
    $baseUrl = (string)($res['url'] ?? $url);

    libxml_use_internal_errors(true);
    $dom = new DOMDocument('1.0', 'UTF-8');
    @$dom->loadHTML('<?xml encoding="UTF-8"><meta charset="UTF-8">' . $html, LIBXML_NOERROR);
    $xp = new DOMXPath($dom);
    libxml_clear_errors();

    selagentProgress(['phase' => 'map', 'html_bytes' => strlen($html),
        'log_add' => ['📄 صفحه گرفته شد (' . aiFaNum((int)round(strlen($html) / 1024)) . ' کیلوبایت) — ساختِ نقشهٔ ساختار…']]);
    $map = selagentDomMap($xp, $kind);

    $pin = $model !== '' ? autoResolveModel($model) : [];
    if ($model !== '' && !$pin) {
        selagentProgress(['log_add' => ['⚠️ مدلِ «' . $model . '» پیدا نشد؛ مدلِ پیش‌فرض استفاده می‌شود']]);
    }

    $tools = selagentToolSpecs($kind);
    $messages = $resumeCp !== null ? array_values($resumeCp['messages']) : [
        ['role' => 'system', 'content' => selagentSystemPrompt($kind, $url)],
        ['role' => 'user',   'content' => "نقشهٔ ساختارِ این صفحه:\n\n" . $map
            . "\n\nحالا سلکتورها را پیدا کن. هر حدس را با probe_selector بسنج و در پایان submit_selectors را صدا بزن."],
    ];
    /* v10.26 (۳۹ب): نقشهٔ DOM می‌تواند ده‌ها کیلوبایت باشد؛ فقط سرش را
       در اجرای تازه در گفتگو نشان می‌دهیم. resume تاریخچهٔ واقعی را نگه می‌دارد. */
    if ($resumeCp === null) selagentProgress(['convo_add' => [
        ['role' => 'system', 'text' => agentConvoTrim(selagentSystemPrompt($kind, $url), 700)],
        ['role' => 'user',   'text' => agentConvoTrim("نقشهٔ ساختارِ این صفحه:\n\n" . $map, 900)],
    ]]);

    $calls = $resumeCp !== null ? (int)($resumeCp['calls'] ?? 0) : 0;
    $probes = $resumeCp !== null ? (int)($resumeCp['probes'] ?? 0) : 0;
    $confirmed = $resumeCp !== null && is_array($resumeCp['confirmed'] ?? null) ? $resumeCp['confirmed'] : [];
    $submitted = $resumeCp !== null && is_array($resumeCp['submitted'] ?? null) ? $resumeCp['submitted'] : null;
    $note = $resumeCp !== null ? (string)($resumeCp['note'] ?? '') : '';
    $stoppedBy = ''; $nativeTools = $resumeCp !== null && array_key_exists('native_tools', $resumeCp) ? $resumeCp['native_tools'] : null;
    $finalText = $resumeCp !== null ? (string)($resumeCp['final_text'] ?? '') : '';
    $startStep = $resumeCp !== null ? max(1, (int)($resumeCp['next_step'] ?? 1)) : 1;
    $startedAt = (int)($resumeCp['started_at'] ?? time());
    $saveCp = function (int $nextStep) use (&$messages, &$calls, &$probes, &$confirmed,
        &$submitted, &$note, &$nativeTools, &$finalText, $url, $kind, $pk, $listUrl, $seeded, $startedAt): void {
        selagentProgress(['checkpoint' => [
            'messages' => $messages, 'calls' => $calls, 'probes' => $probes,
            'confirmed' => $confirmed, 'submitted' => $submitted, 'note' => $note,
            'native_tools' => $nativeTools, 'final_text' => $finalText,
            'next_step' => $nextStep, 'last_step' => $nextStep, 'effective_url' => $url,
            'kind' => $kind, 'pk' => $pk, 'list_url' => $listUrl, 'seeded' => $seeded,
            'started_at' => $startedAt]]);
    };

    for ($step = $startStep; $step <= SELAGENT_MAX_STEPS; $step++) {
        if (selagentStopRequested()) { $stoppedBy = 'کاربر'; break; }
        $saveCp($step);
        selagentProgress(['step' => $step, 'phase' => 'think',
            'log_add' => ['🤔 گامِ ' . aiFaNum($step) . ' — پرسش از مدل…']]);

        $payload = ['messages' => $messages, 'tools' => $tools, 'tool_choice' => 'auto',
                    'temperature' => 0.1, 'max_tokens' => 1200];
        $r = $pin ? aiProviderCall($pin['provider'], $pin['model'], $payload) : aiActiveChat($payload);

        if (empty($r['ok'])) {
            $err = (string)($r['error'] ?? ('HTTP ' . (int)($r['code'] ?? 0)));
            if ((int)($r['code'] ?? 0) === 400 && $nativeTools !== false) {
                $nativeTools = false;
                selagentProgress(['log_add' => ['⚠️ مدل فیلدِ tools را نپذیرفت؛ حالتِ متنی امتحان می‌شود']]);
                $messages[0]['content'] = selagentSystemPrompt($kind, $url) . "\n\n"
                    . "این مدل فراخوانیِ ابزارِ بومی ندارد. برای صدا زدنِ ابزار فقط و فقط یک بلوکِ JSON بنویس:\n"
                    . '{"tool":"نامِ ابزار","args":{...}}' . "\n"
                    . 'ابزارها: ' . json_encode(array_map(fn($t) => [
                          'name' => $t['function']['name'],
                          'params' => array_keys($t['function']['parameters']['properties'] ?? []),
                      ], $tools), JSON_UNESCAPED_UNICODE);
                continue;
            }
            selagentProgress(['log_add' => ['❌ خطای مدل: ' . $err]]);
            return ['ok' => false, 'error' => $err, 'url' => $url, 'kind' => $kind,
                    'steps' => $step, 'calls' => $calls, 'confirmed' => $confirmed,
                    'via' => $fetchVia, 'seeded' => $seeded,
                    'took' => round(microtime(true) - $t0, 1)];
        }

        $body = $r['body'];
        $tcs  = aiExtractToolCalls($body);
        $text = aiExtractText($body);
        if (!$tcs) {
            $tcs = agentParseTextCall($text);
            if ($tcs) selagentProgress(['log_add' => ['🧩 فراخوانیِ ابزار از متنِ مدل استخراج شد']]);
        } elseif ($nativeTools === null) {
            $nativeTools = true;
            selagentProgress(['native_tools' => true, 'log_add' => ['✅ مدل فراخوانیِ ابزارِ بومی دارد']]);
        }

        if (!$tcs) {
            $finalText = trim($text);
            selagentProgress(['convo_add' => [['role' => 'assistant', 'text' => agentConvoTrim($finalText), 'calls' => []]],
                'log_add' => ['💬 مدل بدونِ ابزار پاسخ داد؛ پایانِ حلقه']]);
            break;
        }
        selagentProgress(['convo_add' => [agentConvoAssistant($text, $tcs)]]);

        $asst = aiAssistantMessage($body);
        if (is_array($asst) && isset($asst['tool_calls'])) {
            $messages[] = $asst;
        } else {
            $messages[] = ['role' => 'assistant', 'content' => $text !== '' ? $text : null,
                'tool_calls' => array_map(fn($c) => [
                    'id' => $c['id'], 'type' => 'function',
                    'function' => ['name' => $c['name'],
                                   'arguments' => json_encode($c['args'], JSON_UNESCAPED_UNICODE)],
                ], $tcs)];
        }
        /* checkpoint پیش از اجرای ابزارها؛ در صورت قطع، گفتگوی مدل از همین
           نوبت ادامه پیدا می‌کند و صفحه دوباره فقط برای اجرای ابزار در حافظه ساخته شده است. */
        $saveCp($step);

        $finished = false;
        foreach ($tcs as $c) {
            if (selagentStopRequested()) { $stoppedBy = 'کاربر'; break; }
            if ($calls >= SELAGENT_MAX_CALLS) { $stoppedBy = 'سقفِ فراخوانی'; break; }
            $calls++;
            selagentProgress(['phase' => 'tool', 'calls' => $calls,
                'log_add' => [selagentCallLabel($c['name'], $c['args'])]]);

            $out = ['ok' => false, 'error' => 'ابزارِ ناشناخته'];
            if ($c['name'] === 'probe_selector') {
                $probes++;
                $f = (string)($c['args']['field'] ?? '');
                $sc = (string)($c['args']['scope'] ?? '');
                if ($kind === 'list' && $f !== 'container' && $sc === '' && isset($confirmed['container']))
                    $sc = $confirmed['container'];   // مدل گاهی scope را جا می‌اندازد؛ خودمان پرش می‌کنیم
                $out = selagentProbe($xp, (string)($c['args']['selector'] ?? ''), $f, $baseUrl, $sc);
                if (!empty($out['ok']) && (int)($out['non_empty'] ?? 0) > 0) {
                    /* سلکتورِ سالم را همین‌جا نگه می‌داریم؛ اگر مدل در پایان
                       submit را خراب کرد یا اصلاً نزد، باز هم دستِ کاربر پر است. */
                    $confirmed[$f] = (string)$c['args']['selector'];
                }
                $lbl = !empty($out['ok'])
                    ? ('✔ ' . aiFaNum((int)$out['found']) . ' تطبیق'
                       . (isset($out['samples'][0]) && trim((string)$out['samples'][0]) !== ''
                          ? (' · نمونه: ' . mb_substr((string)$out['samples'][0], 0, 50)) : '')
                       . (isset($out['warning']) ? ' ⚠' : ''))
                    : ('✘ ' . (string)($out['error'] ?? 'ناموفق'));
                selagentProgress(['probes' => $probes, 'confirmed' => count($confirmed),
                    'log_add' => ['   ↳ ' . $lbl]]);
            } elseif ($c['name'] === 'inspect_html') {
                $out = selagentInspect($dom, $xp, (string)($c['args']['selector'] ?? ''),
                                       (int)($c['args']['max_chars'] ?? 2500),
                                       (int)($c['args']['offset'] ?? 0));
                selagentProgress(['log_add' => ['   ↳ ' . (!empty($out['ok'])
                    ? (aiFaNum(mb_strlen((string)$out['html'])) . ' کاراکتر HTML'
                       . (!empty($out['truncated']) ? (' · ادامه از ' . aiFaNum((int)$out['next_offset'])) : ''))
                    : ('⚠️ ' . (string)($out['error'] ?? '')))]]);
            /* v10.30 (۴۳الف): سه ابزارِ تازهٔ کاوشِ صفحه */
            } elseif ($c['name'] === 'find_text') {
                $out = selagentFindText($xp, (string)($c['args']['text'] ?? ''),
                                        (int)($c['args']['limit'] ?? 6));
                selagentProgress(['log_add' => ['   ↳ ' . (!empty($out['ok'])
                    ? (aiFaNum((int)$out['found']) . ' عنصر شاملِ این متن'
                       . (isset($out['hits'][0]['candidates'][0]['selector'])
                          ? (' · بهترین کاندید: ' . $out['hits'][0]['candidates'][0]['selector']) : ''))
                    : ('⚠️ ' . (string)($out['error'] ?? '')))]]);
            } elseif ($c['name'] === 'list_children') {
                $out = selagentListChildren($xp, (string)($c['args']['selector'] ?? ''),
                                            (int)($c['args']['depth'] ?? 1),
                                            (int)($c['args']['limit'] ?? 40));
                selagentProgress(['log_add' => ['   ↳ ' . (!empty($out['ok'])
                    ? (aiFaNum((int)($out['children'] ?? 0)) . ' فرزند')
                    : ('⚠️ ' . (string)($out['error'] ?? '')))]]);
            } elseif ($c['name'] === 'page_data') {
                $out = selagentPageData($html, (string)($c['args']['want'] ?? ''),
                                        (int)($c['args']['max_chars'] ?? 3500));
                selagentProgress(['log_add' => ['   ↳ ' . (!empty($out['ok'])
                    ? ('منابع: ' . implode('، ', (array)($out['sections'] ?? []))
                       . ' · ' . aiFaNum(mb_strlen((string)$out['data'])) . ' کاراکتر')
                    : ('⚠️ ' . (string)($out['error'] ?? '')))]]);
            } elseif ($c['name'] === 'submit_selectors') {
                $sel = (array)($c['args']['selectors'] ?? []);
                $note = trim((string)($c['args']['note'] ?? ''));
                $verify = selagentVerifyAll($xp, $sel, $kind, $baseUrl);
                $submitted = $verify['accepted'];
                foreach ($verify['accepted'] as $k => $v) $confirmed[$k] = $v;
                $out = ['ok' => true, 'accepted' => $verify['accepted'], 'rejected' => $verify['rejected']];
                selagentProgress(['log_add' => ['   ↳ پذیرفته: ' . aiFaNum(count($verify['accepted']))
                    . ' · ردشده: ' . aiFaNum(count($verify['rejected']))]]);
                if (!$verify['rejected']) { $finished = true; }
                else {
                    /* رد شد؟ به مدل بگو چرا و بگذار دوباره تلاش کند — همین
                       حلقهٔ اصلاح است که کیفیت را از «الگوی ثابت» بالاتر می‌برد. */
                    $out['hint'] = 'سلکتورهای ردشده روی صفحه مقدارِ معتبری ندادند. آن‌ها را با probe_selector اصلاح کن و دوباره submit_selectors بزن.';
                }
            }

            selagentProgress(['step_add' => [['step' => $step, 'tool' => $c['name'],
                'args' => $c['args'], 'ok' => !empty($out['ok'])]]]);
            $messages[] = ['role' => 'tool', 'tool_call_id' => $c['id'], 'name' => $c['name'],
                           'content' => json_encode($out, JSON_UNESCAPED_UNICODE)];
            selagentProgress(['convo_add' => [agentConvoTool($c['name'], $out)]]);
            $saveCp($step);
            if ($finished) break;
        }
        if ($finished || $stoppedBy !== '') break;
    }

    if ($submitted === null && $confirmed) {
        /* مدل نرسید submit بزند ولی چند سلکتورِ تأییدشده داریم — دور نریزیم. */
        $v = selagentVerifyAll($xp, $confirmed, $kind, $baseUrl);
        $submitted = $v['accepted'];
        $note = $note !== '' ? $note : 'مدل نتیجه را رسماً تحویل نداد؛ سلکتورهای تأییدشده در میانهٔ کار نگه داشته شدند.';
        if ($stoppedBy === '') $stoppedBy = 'سقفِ گام‌ها';
    }
    $final = is_array($submitted) ? $submitted : [];

    /* پیش‌نمایشِ نهایی: همان چیزی که کاربر در فرم خواهد دید */
    $preview = [];
    $scope = ($kind === 'list' && isset($final['container'])) ? $final['container'] : '';
    foreach ($final as $f => $s) {
        $p = selagentProbe($xp, $s, $f, $baseUrl, ($f === 'container' ? '' : $scope));
        $preview[$f] = ['selector' => $s, 'found' => (int)($p['found'] ?? 0),
                        'sample' => (string)($p['samples'][0] ?? '')];
    }

    return ['ok' => true, 'url' => $url, 'kind' => $kind, 'selectors' => $final,
            'preview' => $preview, 'note' => $note, 'summary' => $finalText,
            'calls' => $calls, 'probes' => $probes, 'stopped_by' => $stoppedBy,
            'native_tools' => $nativeTools, 'via' => $fetchVia, 'seeded' => $seeded,
            'took' => round(microtime(true) - $t0, 1)];
}

/**
 * تکه‌ای از HTML برای مدل (پاک‌سازی‌شده از script/style که فقط توکن می‌سوزانند)
 *
 * v10.30 (۴۳الف): دو تغییرِ کلیدی.
 *  ۱) offset اضافه شد. تا ۱۰.۲۹ همیشه از کاراکترِ صفر شروع می‌شد، پس روی
 *     یک صفحهٔ SPA مدل هرچقدر هم دوباره صدا می‌زد باز همان
 *     <div id="__next"><div class="css-1a2b3c"> را می‌گرفت و هیچ‌وقت به
 *     محتوای واقعی نمی‌رسید — دقیقاً همان بن‌بستِ «۲۰۰۰ کاراکتر».
 *  ۲) سقف از ۴۰۰۰ به ۱۲۰۰۰ رفت و اندازهٔ کل و next_offset برگردانده
 *     می‌شود تا مدل بداند چقدر باقی مانده و از کجا ادامه بدهد.
 */
function selagentInspect(DOMDocument $dom, DOMXPath $xp, string $selector, int $max, int $offset = 0): array {
    $max = max(300, min(12000, $max ?: 2500));
    $offset = max(0, $offset);
    $node = null;
    if (trim($selector) !== '') {
        $x = cssToXpath(trim($selector));
        if ($x === '') return ['ok' => false, 'error' => 'سلکتور قابلِ ترجمه نیست'];
        $n = @$xp->query($x);
        if (!$n || !$n->length) return ['ok' => false, 'error' => 'عنصری با این سلکتور نیست'];
        $node = $n->item(0);
    } else {
        $b = @$xp->query('//body');
        $node = ($b && $b->length) ? $b->item(0) : $dom->documentElement;
    }
    if (!$node) return ['ok' => false, 'error' => 'صفحه خالی است'];
    $h = (string)@$dom->saveHTML($node);
    $h = preg_replace('~<(script|style|noscript)\b[^>]*>.*?</\1>~is', '', $h);
    $h = preg_replace('/\s+/u', ' ', $h);
    $total = mb_strlen($h);
    if ($offset >= $total && $total > 0)
        return ['ok' => false, 'total_chars' => $total,
                'error' => 'offset از اندازهٔ این عنصر (' . $total . ' کاراکتر) بیشتر است'];
    $chunk = mb_substr($h, $offset, $max);
    $end = $offset + mb_strlen($chunk);
    $r = ['ok' => true, 'html' => $chunk, 'offset' => $offset,
          'total_chars' => $total, 'truncated' => $end < $total];
    if ($end < $total) {
        $r['next_offset'] = $end;
        $r['hint'] = 'این عنصر ' . $total . ' کاراکتر است و فقط تا ' . $end
                   . ' را دیدی. برای ادامه دوباره inspect_html را با offset=' . $end . ' صدا بزن،'
                   . ' یا بهتر: به‌جای خواندنِ HTMLِ خام از list_children و find_text استفاده کن.';
    }
    return $r;
}

/**
 * دروازهٔ نهایی: هر سلکتوری که مدل تحویل داده دوباره روی همان صفحه سنجیده
 * می‌شود. این تنها چیزی است که بین «ایجنتِ قابل‌اعتماد» و «ایجنتی که
 * سلکتورِ خیالی می‌سازد» فرق می‌گذارد.
 */
function selagentVerifyAll(DOMXPath $xp, array $sel, string $kind, string $baseUrl): array {
    $allowed = array_keys(selagentFields($kind));
    $accepted = []; $rejected = [];

    /* ظرف باید اول تأیید شود چون scopeِ بقیه است */
    $order = $allowed;
    $scope = '';
    if ($kind === 'list' && isset($sel['container'])) {
        $p = selagentProbe($xp, (string)$sel['container'], 'container', $baseUrl, '');
        if (!empty($p['ok']) && (int)$p['found'] >= 2) { $accepted['container'] = trim((string)$sel['container']); $scope = $accepted['container']; }
        else $rejected['container'] = (string)($p['error'] ?? 'ظرف باید حداقل ۲ بار در صفحه تکرار شود');
    }
    foreach ($order as $f) {
        if ($f === 'container' || !isset($sel[$f])) continue;
        $s = trim((string)$sel[$f]);
        if ($s === '') continue;
        $p = selagentProbe($xp, $s, $f, $baseUrl, $scope);
        if (!empty($p['ok']) && (int)($p['non_empty'] ?? 0) > 0) $accepted[$f] = $s;
        else $rejected[$f] = (string)($p['warning'] ?? $p['error'] ?? 'مقدارِ معتبری نداد');
    }
    foreach ($sel as $f => $s) {
        if (!in_array($f, $allowed, true)) $rejected[(string)$f] = 'فیلدِ ناشناخته';
    }
    return ['accepted' => $accepted, 'rejected' => $rejected];
}

function normalizeTitle(string $title): string {
$t=mb_strtolower(trim($title),'UTF-8');
$t=preg_replace("/\s+/u",' ',$t);
/* v9.51: محافظه‌کارانه شد تا محصولِ واقعاً متفاوت را «تکراری» نسازد.
   نسخهٔ قبلی هر چیزی را از اولین پرانتز/خط‌تیره/اسلش و از اولین کلمهٔ صفت
   (رنگ/سایز/مدل/مشکی/...) به بعد حذف می‌کرد؛ برای همین «کارتریج اچ پی رنگ
   مشکی HP 131A» و «HP 128A» هر دو به «کارتریج اچ پی» می‌رسیدند و با هم
   تکراری حساب شده و حذف می‌شدند.
   حالا فقط پسوندِ کدِ افزوده‌شده توسط خودِ اسکرپر (مثل «(کد:۱)»، «(کد: ۱۲۳)»)
   که در انتهای عنوان می‌نشیند برداشته می‌شود؛ بقیهٔ عنوان — برند، شمارهٔ مدل
   (HP 131A)، رنگ، سایز و شناسه‌ها — دست‌نخورده می‌ماند. پس فقط همان نامِ
   یکسان واقعی (با همان کد) با هم تکراری می‌شوند. */
$t=preg_replace("/\s*[\(\[]\s*(?:کد|کُد|code|sku|شناسه)\s*[:：]?\s*[0-9۰-۹٠-٩]+\s*[\)\]]\s*$/iu",' ',$t);
$t=preg_replace("/\s{2,}/u",' ',$t);
return trim($t);
}

