.bsl-modal-pager{flex:0 0 auto;position:relative;z-index:3;flex-wrap:wrap;padding-bottom:max(8px,env(safe-area-inset-bottom))}
@media(max-height:700px),(max-width:620px){.bsl-modal-overlay{padding:4px;align-items:center}.bsl-modal{max-height:calc(100vh - 8px);max-height:calc(100dvh - 8px);border-radius:10px}.bsl-modal-head{padding:7px 9px}.bsl-modal-pager{padding:6px 8px;padding-bottom:max(6px,env(safe-area-inset-bottom))}}
.bsl-tabs{display:flex;gap:2px;padding:0 12px;background:#1e293b;border-bottom:1px solid #334155;flex-wrap:wrap;direction:rtl}.bsl-tab{padding:6px 12px;font-size:11px;color:#94a3b8;cursor:pointer;border-bottom:2px solid transparent;transition:all .2s;white-space:nowrap;border-radius:6px 6px 0 0}.bsl-tab:hover{color:#e2e8f0;background:#334155}.bsl-tab.active{color:#67e8f9;border-bottom-color:#67e8f9;background:#0f172a;font-weight:700}.bsl-tab .tab-count{font-size:9px;color:#64748b;margin-right:2px}.hamburger-btn{position:fixed;top:10px;left:10px;z-index:10001;width:44px;height:44px;border-radius:12px;background:#1e293b;border:1px solid #475569;color:#e2e8f0;font-size:22px;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 12px rgba(0,0,0,.4);transition:background .2s}.hamburger-btn:hover{background:#334155}
/* v9.61: دکمهٔ «تمام‌عرض کردن منو» کنار همبرگر — پنل تنظیمات را به‌جای
   ۴۰۰ پیکسل، تمام عرض صفحه می‌کند تا همهٔ محتوا/بخش‌ها در یک نگاه باز شوند. */
.fullwidth-btn{position:fixed;top:10px;left:60px;z-index:10001;width:44px;height:44px;border-radius:12px;background:#1e293b;border:1px solid #475569;color:#e2e8f0;font-size:18px;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 12px rgba(0,0,0,.4);transition:background .2s}.fullwidth-btn:hover{background:#334155}.fullwidth-btn.active{background:#7c3aed;color:#fff}.settings-panel.full{width:100vw;max-width:100vw}.settings-panel.full:not(.open){left:-100vw!important;right:auto}.settings-panel.full.open{left:0!important;right:0}.settings-panel.full .smenu-body.open{max-height:none;overflow:visible}body.spanel-full .settings-overlay.open{background:rgba(0,0,0,.55)}
/* v10.273: کنترل تمام‌عرض داخل خود منوی بازشده است، نه نوار اصلی. */
.settings-panel-actions{display:flex;align-items:center;gap:7px;flex:0 0 auto;margin-inline-start:auto}.panel-fullwidth-btn{height:31px;padding:0 10px;border-radius:8px;border:1px solid #6d28d9;background:#2e1065;color:#ddd6fe;display:inline-flex;align-items:center;justify-content:center;gap:6px;font-family:inherit;font-size:11px;font-weight:800;cursor:pointer;transition:background .2s,border-color .2s,transform .2s}.panel-fullwidth-btn:hover{background:#4c1d95;border-color:#a78bfa;transform:translateY(-1px)}.panel-fullwidth-btn.active{background:#7c3aed;border-color:#c4b5fd;color:#fff;box-shadow:0 0 0 3px #7c3aed30}.settings-panel.full .panel-fullwidth-btn span:last-child::after{content:' را بستن'}
/* چراغ وضعیت محیط اجرا: پاسخ endpoint=سبز، timeout/شبکه=قرمز، بررسی=کهربایی. */
.runtime-pulse{position:static;flex:0 0 52px;width:52px;height:44px;margin:0;border-radius:0;border:1px solid #475569;border-right-width:0;background:#0b1220;color:#94a3b8;display:grid;grid-template-columns:16px 14px;align-items:center;justify-content:center;gap:2px;cursor:pointer;overflow:visible}.runtime-pulse-core{grid-area:1/1;width:11px;height:11px;justify-self:center;border-radius:50%;background:#f59e0b;box-shadow:0 0 8px #f59e0b;position:relative;z-index:2;transition:background .25s,box-shadow .25s}.runtime-pulse-ring{grid-area:1/1;justify-self:center;width:11px;height:11px;border-radius:50%;background:#f59e0b80;animation:runtimePulse 1.7s ease-out infinite}.runtime-pulse-tag{grid-area:1/2;font-size:8px;font-weight:900;letter-spacing:.2px;color:#fcd34d;min-width:12px;text-align:center}.runtime-pulse.online .runtime-pulse-core{background:#22c55e;box-shadow:0 0 5px #22c55e,0 0 13px #22c55e}.runtime-pulse.online .runtime-pulse-ring{background:#22c55e99}.runtime-pulse.online .runtime-pulse-tag{color:#86efac}.runtime-pulse.offline .runtime-pulse-core{background:#ef4444;box-shadow:0 0 6px #ef4444,0 0 14px #ef4444}.runtime-pulse.offline .runtime-pulse-ring{background:#ef444499;animation-duration:1s}.runtime-pulse.offline .runtime-pulse-tag{color:#fca5a5}.runtime-pulse:hover{background:#162033}.runtime-pulse:focus-visible{outline:2px solid #67e8f9;outline-offset:-2px}@keyframes runtimePulse{0%{transform:scale(.8);opacity:.9}75%,100%{transform:scale(2.7);opacity:0}}@media(max-width:430px){.runtime-pulse{flex-basis:44px;width:44px}.runtime-pulse-tag{display:none}.panel-fullwidth-btn span:last-child{display:none}.panel-fullwidth-btn{width:34px;padding:0}}
/* v10.400: cron arrivals briefly override the health color, then restore it. */
.runtime-pulse.cron-pulse-internal{border-color:#38bdf8!important;background:#082f49!important}
.runtime-pulse.cron-pulse-internal .runtime-pulse-core{background:#38bdf8!important;box-shadow:0 0 5px #38bdf8,0 0 14px #38bdf8!important}
.runtime-pulse.cron-pulse-internal .runtime-pulse-ring{background:#38bdf880!important;animation-duration:.85s!important}
.runtime-pulse.cron-pulse-internal .runtime-pulse-tag{color:#7dd3fc!important}
.runtime-pulse.cron-pulse-external{border-color:#a78bfa!important;background:#2e1065!important}
.runtime-pulse.cron-pulse-external .runtime-pulse-core{background:#a78bfa!important;box-shadow:0 0 5px #a78bfa,0 0 14px #a78bfa!important}
.runtime-pulse.cron-pulse-external .runtime-pulse-ring{background:#a78bfa80!important;animation-duration:.85s!important}
.runtime-pulse.cron-pulse-external .runtime-pulse-tag{color:#ddd6fe!important}
/* v10.19 (۳۲): دکمهٔ مدیر وظیفه — سومین دکمهٔ شناورِ هدر، کنارِ ☰ و ⛶ */
.tasks-btn{position:fixed;top:10px;left:110px;z-index:10001;width:44px;height:44px;border-radius:12px;background:#1e293b;border:1px solid #475569;color:#e2e8f0;font-size:19px;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 12px rgba(0,0,0,.4);transition:background .2s}
/* v10.82 (96): دکمهٔ چت باسلام در نوارِ هدر — کنارِ مدیرِ وظیفه */
.chat-hdr-btn{position:fixed;top:10px;left:110px;z-index:10001;height:44px;padding:0 12px;border-radius:12px;background:#1e293b;border:1px solid #475569;color:#e2e8f0;font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:6px;box-shadow:0 2px 12px rgba(0,0,0,.4);transition:background .2s;direction:rtl}.chat-hdr-btn:hover{background:#334155}.chat-hdr-lbl{font-size:11px;white-space:nowrap}.hdr-tools .chat-hdr-btn{position:static;flex:0 0 auto;z-index:10050}body.modal-open .chat-hdr-btn{z-index:10}body.spanel-open .chat-hdr-btn{box-shadow:0 2px 20px rgba(0,0,0,.7)}@media(max-width:400px){.chat-hdr-lbl{display:none}}
/* v10.84 (98): تب‌هایِ فرعیِ تبِ ارسال (ووکامرس / باسلام) */
.send-subtabs{display:flex;gap:6px;margin-bottom:12px;direction:ltr}.ssb{flex:0 0 auto;font-size:12px;font-weight:700;padding:6px 18px;border-radius:8px 8px 0 0;border:1px solid #334155;border-bottom:none;background:#0f172a;color:#94a3b8;cursor:pointer;transition:all .15s;direction:rtl}.ssb:hover{color:#67e8f9}.ssb.on{color:#67e8f9;background:linear-gradient(90deg,#164e63,#0f172a);border-color:#0e7490}
/* v10.84 (98): اتاقِ چتِ تک‌صفحهٔ تمام‌عرضِ تمام‌ارتفاع + لیستِ کشویی */
#mrDrawerBtn{display:none}
#mrModal{padding:0}
#mrModal .bsl-modal{width:100vw;max-width:100vw;height:100vh;max-height:100vh;border-radius:0}
#mrModalHost{padding:0!important;height:100%}
#mrModalHost #mrBody{max-height:none!important;flex:1;display:flex;flex-direction:column;padding:0 12px 12px!important}
#mrModalHost #mrRow{flex:1;min-height:0;position:relative;flex-wrap:nowrap}
#mrModalHost #mrDrawerBtn{display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;flex:0 0 auto;z-index:7;background:#16233d;border:1px solid #334155;border-radius:8px;color:#e2e8f0;font-size:15px;cursor:pointer}
#mrModalHost #mrDrawerBtn:hover{background:#1e293b}
#mrModalHost #mrListWrap{position:absolute;top:0;bottom:0;right:0;left:auto;width:min(330px,85%);min-width:0;z-index:6;background:#0f172a;border-left:1px solid #334155;box-shadow:0 0 30px rgba(0,0,0,.5);transform:translateX(105%);transition:transform .25s ease;overflow-y:auto;display:flex;flex-direction:column}
#mrModalHost #mrRow.mr-drawer-open #mrListWrap{transform:translateX(0)}
#mrModalHost #mrList{max-height:none;flex:1;border-radius:0;border:none}
#mrModalHost #mrThread{min-width:0;display:flex;flex-direction:column}
#mrModalHost #mrMsgs{height:auto;flex:1;font-size:13px}
.tasks-btn:hover{background:#334155}
.tasks-btn.active{background:#0891b2;color:#fff}
/* ==================================================================
   v10.20 (۳۳ج): سه دکمهٔ هدر در یک نوارِ واقعی می‌نشینند.

   قبلاً هر سه جداگانه position:fixed با left ثابت (۱۰/۶۰/۱۱۰) بودند.
   نتیجه: بینشان ۶ پیکسل فاصلهٔ نامنظم می‌افتاد، در موبایل دکمهٔ 🗂 به
   گوشهٔ مخالفِ صفحه پرت می‌شد، و مدیر وظیفه فقط یک آیکونِ 🗂 بی‌برچسب
   بود که معلوم نبود چیست.

   حالا یک نوارِ فلکسِ چسبان (.hdr-tools) هر سه را نگه می‌دارد؛ دکمه‌ها
   داخلش با position:static می‌نشینند و کاملاً به هم چسبیده‌اند. دکمهٔ
   مدیر وظیفه تمام‌عرضِ باقی‌ماندهٔ نوار را می‌گیرد و برچسبِ متنی دارد.
   ================================================================== */
.hdr-tools{position:fixed;top:10px;left:10px;right:10px;z-index:10050;display:flex;align-items:stretch;gap:0;height:44px;border-radius:12px;box-shadow:0 2px 12px rgba(0,0,0,.4);overflow:hidden;direction:ltr}
/* دکمه‌ها داخلِ نوار دیگر شناور نیستند؛ کنار هم و بدون فاصله می‌نشینند */
.hdr-tools .hamburger-btn,.hdr-tools .fullwidth-btn,.hdr-tools .tasks-btn{position:static;top:auto;left:auto;right:auto;bottom:auto;flex:0 0 auto;height:44px;margin:0;border-radius:0;box-shadow:none;border-right-width:0}
.hdr-tools .tasks-btn{flex:1 1 auto;width:auto;min-width:0;justify-content:flex-start;gap:8px;padding:0 12px;border-right-width:1px;font-size:17px;overflow:hidden;direction:rtl}
/* v10.229: انتخاب سریع پروفایل داخل همان نوارِ چسبانِ بالای صفحه */
.hdr-profile-select{position:static;flex:0 1 240px;min-width:150px;height:44px;margin:0;border:1px solid #475569;border-right-width:0;border-radius:0;background:#0f172a;color:#e2e8f0;font-size:11px;font-weight:700;padding:0 10px;outline:none;box-shadow:none;direction:rtl;cursor:pointer}
.hdr-profile-select:hover{background:#1e293b}
.hdr-profile-select:focus{border-color:#22d3ee;box-shadow:inset 0 0 0 1px #22d3ee}
body.modal-open .hdr-profile-select{z-index:10}
@media(max-width:720px){.hdr-profile-select{flex:0 1 160px;min-width:105px;font-size:10px;padding:0 6px}.hdr-profile-select option{font-size:11px}}
@media(max-width:400px){.hdr-profile-select{flex:1 1 90px;min-width:78px}.hdr-profile-select{font-size:9.5px}}
/* برچسبِ متنی — «گویاتر» یعنی متن هم داشته باشد، نه فقط یک تصویرکِ مبهم */
.tasks-lbl{font-size:12px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:.2px}
.tasks-sub{font-size:10px;color:#94a3b8;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-weight:400;flex:1 1 auto;min-width:0}
.tasks-btn.busy .tasks-sub{color:#86efac}
.tasks-btn.warn .tasks-sub{color:#fcd34d}
/* نشانگرِ عددی داخلِ نوار جای شناور ندارد؛ کنارِ متن می‌نشیند */
.hdr-tools .tasks-badge{position:static;top:auto;right:auto;box-shadow:none;flex:0 0 auto}
/* وقتی کاری در حال اجراست دکمه نفس می‌کشد — تنها راهی که کاربر بدونِ
   باز کردنِ چیزی بفهمد پس‌زمینه مشغول است */
.tasks-btn.busy{border-color:#22c55e;background:#14321f;color:#86efac;animation:tmPulse 1.8s ease-in-out infinite}
@keyframes tmPulse{0%,100%{box-shadow:0 2px 12px rgba(0,0,0,.4),0 0 0 0 rgba(34,197,94,.55)}50%{box-shadow:0 2px 12px rgba(0,0,0,.4),0 0 0 7px rgba(34,197,94,0)}}
.tasks-badge{position:absolute;top:-5px;right:-5px;min-width:18px;height:18px;padding:0 4px;border-radius:9px;background:#22c55e;color:#04210f;font-size:10px;font-weight:800;display:none;align-items:center;justify-content:center;box-shadow:0 1px 5px rgba(0,0,0,.5)}
.tasks-btn.busy .tasks-badge{display:flex}
.tasks-btn.warn{border-color:#f59e0b;background:#3a2a0c;color:#fcd34d;animation:none}
.tasks-btn.warn .tasks-badge{display:flex;background:#f59e0b;color:#3a2a0c}
.tmc{border:1px solid #334155;border-radius:10px;background:#111c31;padding:9px 11px;margin-bottom:8px;transition:border-color .2s,background .2s}
/* v10.37 (۵۰ب): کارتِ کشویی — سربرگ همیشه، جزئیات فقط وقتی باز است */
.tmc.open{background:#132038;border-color:#3b5578}
.tmc-body{margin-top:2px;animation:tmFold .16s ease-out}
@keyframes tmFold{from{opacity:0;transform:translateY(-3px)}to{opacity:1;transform:none}}
.tmchev{color:#67e8f9;font-size:10px;width:11px;display:inline-block;text-align:center;flex:0 0 auto}
.tmc-sum{font-size:10px;color:#94a3b8;margin-top:5px;padding-right:17px;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tmbar.mini{height:3px;margin-top:5px}
.tmc:hover{border-color:#475569}
.tmc.run{border-color:#22c55e55;background:#0f2419}
.tmc.stale{border-color:#f59e0b66;background:#2a1f08}
.tmc.done{border-color:#33415588}
.tmc.idle{opacity:.62}
.tmc-head{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.tmc-t{font-weight:700;color:#e2e8f0;font-size:12.5px}
.tmc-tab{font-size:9px;color:#64748b;background:#0f172a;border:1px solid #263449;border-radius:5px;padding:1px 6px}
.tmc-badge{font-size:9.5px;font-weight:700;border-radius:5px;padding:2px 7px}
/* v10.24 (۳۷الف): ستونِ اولویتِ کارهای پس‌زمینه */
.tmord{display:flex;flex-direction:column;gap:1px}
.tmord button{background:#16233a;border:1px solid #263449;color:#94a3b8;border-radius:4px;
  font-size:8px;line-height:1;padding:2px 5px;cursor:pointer}
.tmord button:hover:not(:disabled){background:#1e3a5f;color:#67e8f9;border-color:#3b6ea5}
.tmord button:disabled{opacity:.28;cursor:default}
.tmrank{font-size:9.5px;font-weight:800;color:#67e8f9;background:#0f172a;border:1px solid #263449;
  border-radius:5px;min-width:17px;text-align:center;padding:2px 4px}
.tmrank:hover{background:#1e3a5f;border-color:#3b6ea5}
.tmb-run{background:#14532d;color:#86efac}.tmb-stale{background:#78350f;color:#fcd34d}
.tmb-done{background:#1e3a5f;color:#93c5fd}.tmb-idle{background:#1e293b;color:#64748b}
/* نوارِ پیشرفت؛ حالتِ نامعین برای کارهایی که «کل» را نمی‌دانند */
.tmbar{height:6px;border-radius:4px;background:#0b1220;overflow:hidden;margin-top:7px;border:1px solid #1e293b}
.tmbar>i{display:block;height:100%;background:linear-gradient(90deg,#22c55e,#67e8f9);transition:width .4s ease}
.tmbar.ind>i{width:35%;background:linear-gradient(90deg,transparent,#22c55e,transparent);animation:tmSlide 1.4s linear infinite}
@keyframes tmSlide{0%{transform:translateX(-120%)}100%{transform:translateX(340%)}}
.tmstat{display:flex;gap:6px;flex-wrap:wrap;margin-top:7px}
.tmstat span{font-size:9.5px;color:#94a3b8;background:#0f172a;border:1px solid #263449;border-radius:5px;padding:2px 7px}
.tmstat b{color:#67e8f9;font-weight:700}
.tmlog{margin-top:7px;background:#0a1120;border:1px solid #1e293b;border-radius:7px;padding:6px 8px;max-height:96px;overflow:auto;font-size:10px;color:#94a3b8;line-height:1.75;white-space:pre-wrap}
.tmrow{display:flex;align-items:center;gap:7px;padding:7px 9px;border:1px solid #334155;border-radius:9px;background:#111c31;margin-bottom:6px}
.tmrow.off{opacity:.5}
.tmord{display:flex;flex-direction:column;gap:2px}
.tmord button{width:22px;height:15px;line-height:1;padding:0;font-size:9px;border-radius:4px;background:#1e293b;border:1px solid #334155;color:#94a3b8;cursor:pointer}
.tmord button:hover:not(:disabled){background:#334155;color:#e2e8f0}
.tmord button:disabled{opacity:.28;cursor:default}
.tmrank{min-width:22px;height:22px;border-radius:6px;background:#0891b2;color:#04212b;font-size:10px;font-weight:800;display:flex;align-items:center;justify-content:center}
/* قواعدِ همزیستی با ☰ و ⛶ — جداگانه نوشته شده‌اند تا رشته‌های اصلیِ
   آن دو دست‌نخورده بمانند (selftest عیناً همان‌ها را چک می‌کند) */
.tasks-btn{z-index:10050}
body.spanel-open .tasks-btn{box-shadow:0 2px 14px rgba(0,0,0,.65)}
body.modal-open .tasks-btn{z-index:10}
/* v10.20 (۳۳ج): حالا z-index روی خودِ نوار است، نه تک‌تکِ دکمه‌ها */
body.spanel-open .hdr-tools{box-shadow:0 2px 14px rgba(0,0,0,.65)}
body.modal-open .hdr-tools{z-index:10}
.hdr-tools .tasks-btn,.hdr-tools .hamburger-btn,.hdr-tools .fullwidth-btn{z-index:auto}
html[data-fx="on"] .tasks-btn{transition:background-color .2s,transform .25s var(--fx-ease),box-shadow .25s var(--fx-ease);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}
html[data-fx="on"] .tasks-btn:hover{transform:translateY(-2px) scale(1.06);box-shadow:0 8px 24px rgba(0,0,0,.7)}
/* v10.20 (۳۳ج): در موبایل هم دکمه در همان نوار می‌ماند — قبلاً به گوشهٔ
   پایین-راست پرت می‌شد و از بقیهٔ دکمه‌ها جدا می‌افتاد. فقط زیرنویس حذف
   می‌شود تا جا کم نیاید. */
@media(max-width:620px){.hdr-tools .tasks-btn{padding:0 9px;gap:6px}.tasks-sub{display:none}html[data-fx="on"] .tasks-btn{backdrop-filter:none;-webkit-backdrop-filter:none}}
@media(max-width:400px){.tasks-lbl{display:none}.hdr-tools .tasks-btn{flex:0 0 auto;width:44px;justify-content:center;padding:0}}
/* v9.94 (۸الف): دکمه‌های ☰ و ⛶ همیشه بالای پنل تنظیمات بمانند.
   قبلاً z-index:10001 بود ولی پنل (z-index:9999) با پس‌زمینهٔ مات و
   عرضِ 100vw در حالت «تمام‌عرض» روی آن‌ها می‌افتاد و کلیک را می‌بلعید. */
.hamburger-btn,.fullwidth-btn{z-index:10050}
body.spanel-open .hamburger-btn,body.spanel-open .fullwidth-btn{box-shadow:0 2px 14px rgba(0,0,0,.65)}
/* v10.00 (۱۴الف): وقتی یک مودالِ تمام‌صفحه باز است، دکمه‌های شناورِ ☰ و ⛶
   باید *زیرِ* آن بروند. قبلاً مودالِ «نتایج زندهٔ تستِ مدل‌ها» با z-index:10000
   ساخته می‌شد و این دو دکمه (10050) روی آن می‌افتادند و هم دیده می‌شدند هم
   کلیک را می‌دزدیدند. راهِ درست همین است، نه بالا بردنِ z-index مودال:
   دکمه‌ها باید بالای *پنلِ تنظیمات* (9999) بمانند ولی زیرِ *مودال‌ها*. */
body.modal-open .hamburger-btn,body.modal-open .fullwidth-btn{z-index:10}
.hamburger-btn.active{background:#3b82f6;color:#000}.settings-overlay{position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.5);z-index:9998;display:none;opacity:0;transition:opacity .3s}.settings-overlay.open{display:block;opacity:1}.settings-panel{position:fixed;top:0;left:-420px;width:400px;max-width:90vw;height:100vh;background:#0f172a;border-right:1px solid #334155;z-index:9999;overflow-y:auto;transition:left .3s ease;padding:0}.settings-panel.open{left:0}.settings-panel-head{position:sticky;top:0;z-index:6;background:#1e293b;padding:12px 14px;display:flex;align-items:center;justify-content:space-between;gap:8px;border-bottom:1px solid #334155;flex-wrap:nowrap}.settings-panel-head h2{margin:0;font-size:16px;color:#e2e8f0;flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.settings-panel-body{padding:16px 20px}.settings-panel .cc{margin-bottom:12px}.settings-panel .ccb{padding:10px}.smenu{border-bottom:1px solid #1e293b}
.smenu-hdr{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;cursor:pointer;transition:background .15s}.smenu-hdr:hover{background:#1e293b}
/* v9.94 (۸ب): سربخشِ هر آیتمِ منو به بالای پنل می‌چسبد.
   بخش‌های بلند (هوش مصنوعی، سلکتورها، …) چند هزار پیکسل ارتفاع دارند و
   بعد از کمی اسکرول معلوم نبود داخل کدام بخش هستید. حالا عنوان بالا می‌ماند.
   --spanel-head-h ارتفاع واقعیِ سربرگِ پنل است (با JS اندازه گرفته می‌شود)
   تا سربخش دقیقاً زیرِ آن بنشیند و رویش نیفتد. */
.settings-panel .smenu-hdr{position:sticky;top:var(--spanel-head-h,58px);z-index:5;background:#0f172a;box-shadow:0 1px 0 #1e293b}
.settings-panel .smenu-hdr.open{background:#111c31;box-shadow:0 2px 8px rgba(0,0,0,.45)}
.settings-panel .smenu-hdr:hover{background:#1e293b}
/* سربخشِ تودرتو زیرِ سربخشِ والدش می‌چسبد تا هر دو دیده شوند */
.settings-panel .smenu-body .smenu-hdr{top:calc(var(--spanel-head-h,58px) + var(--smenu-hdr-h,46px));z-index:4}
.settings-panel .smenu-body .smenu-body .smenu-hdr{top:calc(var(--spanel-head-h,58px) + (var(--smenu-hdr-h,46px) * 2));z-index:3}
.settings-panel .smenu-body .smenu-body .smenu-body .smenu-hdr{top:calc(var(--spanel-head-h,58px) + (var(--smenu-hdr-h,46px) * 3));z-index:2}.smenu-hdr h3{margin:0;font-size:14px;display:flex;align-items:center;gap:8px}.smenu-hdr .arrow{font-size:12px;color:#64748b;transition:transform .2s}.smenu-hdr.open .arrow{transform:rotate(180deg)}.smenu-body{max-height:0;overflow:hidden;transition:max-height .3s ease;padding:0 16px}.smenu-body.open{max-height:2000px;padding:0 16px 16px}
/* v10.73 (87): تب‌های بخشِ اعلان‌ها */
.ntab{flex:0 0 auto;font-size:11px;font-weight:700;padding:5px 10px;border-radius:6px;border:1px solid #334155;background:#0f172a;color:#94a3b8;cursor:pointer;transition:all .15s}.ntab:hover{border-color:#67e8f9;color:#67e8f9}.ntab.active{background:linear-gradient(90deg,#164e63,#0f172a);border-color:#0e7490;color:#67e8f9}.ntabpane{animation:ntabIn .18s ease}
@keyframes ntabIn{from{opacity:0;transform:translateY(3px)}to{opacity:1;transform:none}}
/* v9.94 (۸ب): بعد از پایانِ انیمیشنِ باز شدن، سقفِ ارتفاع برداشته می‌شود.
   دو سود دارد: (۱) بخش‌های بلندتر از ۲۰۰۰px دیگر بریده نمی‌شوند،
   (۲) overflow:visible باعث می‌شود سربخش‌های تودرتو هم واقعاً بچسبند
   (سربخشِ داخلِ جعبهٔ overflow:hidden به‌جای پنل، به همان جعبه می‌چسبد). */
.smenu-body.open.smenu-done{max-height:none;overflow:visible}/* v9.78: آکاردئون‌های تب سلکتورها بزرگ‌ترند (شامل پیش‌نمایش iframe) */
.smenu-body.open.sel-open{max-height:12000px}.smenu-body .crow{margin-bottom:8px}.smenu-body .cact{margin-top:10px}.live-cnt{display:grid;grid-template-columns:repeat(6,1fr);gap:6px;margin:8px 0}.live-cnt .lc{background:#0f172a;border:1px solid #334155;border-radius:8px;padding:7px 4px;text-align:center;cursor:pointer;transition:.15s;display:flex;flex-direction:column;gap:1px}
/* v9.78: توضیحاتِ داخلِ بخش‌های تب سلکتورها هم کشویی شدند */
.hint-collapse summary{cursor:pointer;font-size:12px;font-weight:700;list-style:none;display:flex;align-items:center;gap:6px;padding:4px 0}
.hint-collapse summary::-webkit-details-marker{display:none}
.hint-collapse summary::before{content:"▼";font-size:9px;color:#64748b;transition:transform .2s;display:inline-block}
.hint-collapse[open] summary::before{transform:rotate(180deg)}
.hint-collapse .hint-body{padding-top:6px}
/* v10.26 (۳۹الف): واریانتِ «راهنمای ریز» — همان رفتارِ کشویی، ولی با ظاهرِ
   همان توضیح‌های کم‌رنگِ زیرِ فیلدها (نه باکسِ آبیِ alert). هرجا قبلاً یک
   <div> توضیحیِ ثابت بود که فضای پنل را می‌گرفت، به این تبدیل شده تا
   پیش‌فرض بسته باشد و با یک کلیک باز شود. */
.hint-mini{display:block;margin:0 0 6px}
.hint-mini>summary{cursor:pointer;font-size:10px;font-weight:700;color:#64748b;list-style:none;display:flex;align-items:center;gap:5px;padding:3px 0}
.hint-mini>summary::-webkit-details-marker{display:none}
.hint-mini>summary::before{content:"▼";font-size:8px;color:#475569;transition:transform .2s;display:inline-block}
.hint-mini[open]>summary::before{transform:rotate(180deg)}
.hint-mini>summary:hover{color:#94a3b8}
.hint-mini .hint-body{padding-top:4px}
/* v10.26 (۳۹ب): باکسِ کشویی «گفتگوی زنده» — همان استایل برای هر سه جا
   (ایجنتِ محصولات، ایجنتِ کشفِ سلکتور، مودالِ لاگِ اتوماسیون). */
.cvo{margin-top:8px;background:#0b1120;border:1px solid #1e293b;border-radius:8px;overflow:hidden}
.cvo>summary{cursor:pointer;list-style:none;display:flex;align-items:center;gap:7px;padding:7px 9px;font-size:11px;font-weight:700;color:#a5b4fc;background:#111c31}
.cvo>summary::-webkit-details-marker{display:none}
.cvo>summary::before{content:"▼";font-size:8px;color:#64748b;transition:transform .2s;display:inline-block}
.cvo[open]>summary::before{transform:rotate(180deg)}
.cvo>summary:hover{background:#16233c}
.cvo-live{font-size:9px;color:#0b1120;background:#4ade80;border-radius:4px;padding:1px 5px;font-weight:700}
.cvo-n{margin-right:auto;font-size:9.5px;color:#64748b;font-weight:400}
.cvo-bd{padding:8px;max-height:320px;overflow:auto;direction:rtl}
.cvo-msg{border-radius:7px;padding:6px 8px;margin-bottom:5px;font-size:10.5px;line-height:1.9;border:1px solid transparent}
.cvo-msg .cvo-who{display:block;font-size:9.5px;font-weight:700;margin-bottom:2px;opacity:.85}
.cvo-msg .cvo-t{float:left;font-style:normal;font-weight:400;color:#475569;font-family:ui-monospace,monospace;font-size:9px}
.cvo-msg .cvo-tx{color:#cbd5e1;white-space:pre-wrap;word-break:break-word}
.cvo-system{background:#0f172a;border-color:#1e293b}   .cvo-system .cvo-who{color:#64748b}
.cvo-user{background:#12233b;border-color:#1e3a5f}      .cvo-user .cvo-who{color:#60a5fa}
.cvo-assistant{background:#1c1233;border-color:#4c1d95} .cvo-assistant .cvo-who{color:#c084fc}
.cvo-tool{background:#0d1f1a;border-color:#14532d}      .cvo-tool .cvo-who{color:#34d399}
.cvo-tool.bad{background:#1f1214;border-color:#7f1d1d}  .cvo-tool.bad .cvo-who{color:#f87171}
.cvo-call{margin-top:4px;background:#0b1120;border:1px dashed #4c1d95;border-radius:6px;padding:4px 6px;font-size:10px;color:#ddd6fe;direction:ltr;text-align:left;word-break:break-all}
.cvo-call b{color:#f0abfc}
.cvo-empty{color:#64748b;font-size:10.5px;text-align:center;padding:10px}
