<script>
(function(){
window._jsOk=true;
window.onerror=function(m,u,l,c,e){
try{
console.error('JS Error:',m,'Line:',l);
var d=document.getElementById('_dbg');
if(!d){d=document.createElement('div');d.id='_dbg';
d.style.cssText='position:fixed;bottom:0;left:0;right:0;max-height:40vh;overflow:auto;background:#1a0000;border:3px solid #f00;padding:10px;z-index:9999998;font:12px monospace;color:#fca5a5;direction:ltr';
document.body.appendChild(d);
var b=document.createElement('button');b.textContent='X';b.style.cssText='position:absolute;top:5px;right:5px;background:#f00;color:#fff;border:none;padding:2px 8px;cursor:pointer;font:bold 14px monospace';
b.onclick=function(){d.style.display='none';};d.appendChild(b);}
d.insertAdjacentHTML('beforeend','<div style="border-bottom:1px solid #7f1d1d;padding:4px 0">JS Error: '+m+' <b>Line:'+l+'</b></div>');
}catch(ex){}
return false;
};
window.addEventListener('unhandledrejection',function(e){
try{var d=document.getElementById('_dbg');if(d)d.insertAdjacentHTML('beforeend','<div style="color:#fbbf24;border-bottom:1px solid #7f1d1d;padding:4px 0">Promise: '+String(e.reason)+'</div>');}catch(ex){}
});
})();
</script>
<script>
const $=id=>document.getElementById(id);
let es=null,detailEs=null,products=new Map(),order=[],pages=0,details=0,running=false,detailRunning=false,mode='auto',extractSpeedStartMs=0;
// v8.77: نگهبانِ توقفِ استخراج تفصیلی
let detailWatch=null, detailLastBeat=0;
let sel={container:'',title:'',price:'',link:'',image:''};
const DETAIL_FIELDS = [
    /* v10.15: قیمت از صفحهٔ خودِ محصول.
       چرا لازم بود: تا اینجا قیمت فقط از صفحهٔ فهرست برداشته می‌شد. خیلی از
       فروشگاه‌ها در فهرست یا قیمت نمی‌گذارند، یا بازه («از ۱۲۰٬۰۰۰») یا قیمتِ
       پیش از تخفیف نشان می‌دهند و عددِ درست فقط داخلِ صفحهٔ محصول است.
       هر دو استخراج‌کنندهٔ بک‌اند از قدیم شاخهٔ price داشتند (extractPrice روی
       متنِ گره) ولی مثل image در v8.66 هیچ‌جا در رابط کاربری قابل تنظیم نبود،
       پس عملاً مرده بود. */
    {key:'price',     label:'قیمت',            icon:'💰'},
    {key:'shortDesc', label:'توضیحات کوتاه', icon:'📝'},
    {key:'longDesc',  label:'توضیحات بلند',   icon:'📄'},
    {key:'specs',     label:'مشخصات فنی (جدول)', icon:'📋'},
    {key:'sku',       label:'SKU',             icon:'🏷️'},
    {key:'category',  label:'دسته‌بندی',      icon:'📂'},
    {key:'tags',      label:'برچسب‌ها',        icon:'🔖'},
    {key:'weight',    label:'وزن',             icon:'⚖️'},
    {key:'stock',     label:'موجودی',          icon:'📦'},
    {key:'brand',     label:'برند',            icon:'🏭'},
    // v8.66: هر دو استخراج‌کننده (بک‌اند و SSE) از قدیم فیلد image را
    // پشتیبانی می‌کردند ولی هیچ‌جا در رابط کاربری قابل تنظیم نبود، پس عملاً
    // مرده بود. برای صفحاتی که عکس اصلی فقط در صفحهٔ محصول است لازم است.
    {key:'image',     label:'عکس اصلی',        icon:'🌆'},
    // v8.68: تنوع‌ها (variations) — مثل رنگ و سایز. یک سلکتور به ظرفی
    // می‌دهید که گزینه‌ها داخلش هستند (select، رادیو، یا فهرست دکمه‌ای)
    // و همهٔ مقادیر برداشته می‌شوند.
    {key:'variations',label:'تنوع‌ها (گالری عکس رنگ/سایز)', icon:'🎨', multi:true, asGallery:true},
];
let detailSel = {};
DETAIL_FIELDS.forEach(f => detailSel[f.key] = {enabled:false, selector:''});

// ========== Import State ==========
let importProducts = [];
