let urlChangeTimer = null;
let testTimers = {};

const toFa=n=>String(n).replace(/[0-9]/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d]);
const toEn=s=>(s||'').replace(/[۰-۹]/g,d=>'0123456789'['۰۱۲۳۴۵۶۷۸۹'.indexOf(d)]).replace(/[٠-٩]/g,d=>'0123456789'['٠١٢٣٤٥٦٧٨٩'.indexOf(d)]);

function showToast(msg, isError=false) {
    const t = $('toast');
    t.textContent = msg;
    t.className = 'toast show' + (isError ? ' error' : '');
    setTimeout(() => t.className = 'toast' + (isError ? ' error' : ''), 2500);
}

const START_PRODUCT_METRICS = [
  ['total','📦','کل محصولات','#38bdf8','مجموع ردیف‌های محصول در همهٔ پروفایل‌ها'],
  ['priced','💰','دارای قیمت','#22c55e','محصولاتی که قیمت عددی معتبر دارند'],
  ['no_price','⚠️','بدون قیمت','#f97316','محصولاتی که برای ارسال نیازمند قیمت هستند'],
  ['in_stock','✅','موجود صریح','#10b981','محصولات دارای موجودی مثبت یا وضعیت instock'],
  ['out_stock','⛔','ناموجود صریح','#ef4444','محصولات با موجودی صفر یا وضعیت outofstock'],
  ['stock_unknown','❔','موجودی نامشخص','#eab308','محصولاتی که فیلد موجودی صریح ندارند'],
  ['with_image','🖼️','دارای تصویر','#8b5cf6','محصولات دارای حداقل یک تصویر'],
  ['no_image','🌫️','بدون تصویر','#f43f5e','محصولاتی که تصویر قابل استفاده ندارند'],
  ['gallery','🎞️','دارای گالری','#a855f7','محصولات دارای بیش از یک تصویر'],
  ['variations','🎨','دارای تنوع','#ec4899','محصولات دارای رنگ، سایز یا گزینه‌های تنوع'],
  ['linked','🔗','دارای لینک','#06b6d4','محصولات دارای لینک صفحهٔ جزئیات'],
  ['sku','🏷️','دارای SKU','#6366f1','محصولات دارای شناسه یا SKU'],
  ['description','📝','دارای توضیحات','#14b8a6','محصولات دارای توضیح کوتاه یا بلند'],
  ['category','📂','دارای دسته','#84cc16','محصولات دارای دسته‌بندی استخراج‌شده'],
  ['brand','🏭','دارای برند','#f59e0b','محصولات دارای نام برند'],
  ['ready','🚀','آمادهٔ پایهٔ ارسال','#4ade80','محصولاتی که هم‌زمان قیمت، تصویر و لینک دارند']
];
let startProductOverviewData=null,startProductOverviewBusy=false,startBreakdownRefreshTimer=null;
function scheduleStartBreakdownRefresh(){clearTimeout(startBreakdownRefreshTimer);startBreakdownRefreshTimer=setTimeout(()=>loadStartProductOverview(true),1800)}
function spoNum(n){try{return Number(n||0).toLocaleString('fa-IR')}catch(e){return toFa(n||0)}}
function renderStartProfileBreakdown(d){
  const body=$('startProfileBreakdownBody'),foot=$('startProfileBreakdownFoot'),head=$('startProfileBreakdownHead'),meta=$('startProfileBreakdownMeta');if(!body||!foot||!head)return;
  const rows=Array.isArray(d&&d.by_profile)?d.by_profile:[],mx=(d&&d.matrix)||{},dests=Array.isArray(mx.destinations)?mx.destinations:[],cols=5+dests.length;
  head.innerHTML='<th>پروفایل</th><th>کل محصولات</th>'+dests.map(x=>'<th title="بر اساس آخرین نتیجهٔ کامل جدول مغایرت">'+(x.type==='woo'?'🛒 ':'🏪 ')+esc(x.label||x.key||'مقصد')+(x.type==='bsl'?'<small class="spb-uncoded">متفرقه بدون کد: '+spoNum(x.uncoded||0)+'</small>':'')+'</th>').join('')+'<th>سلکتور جزئیات</th><th>مرحلهٔ دوم</th><th>دارای جزئیات</th>';
  if(meta){const at=parseInt(mx.generated_at||0);meta.textContent=dests.length?('تعداد محصولات ذخیره‌شده و موجودی مقصدها بر اساس جدول مغایرت '+(at?new Date(at*1000).toLocaleString('fa-IR'):'')+'؛ به‌همراه پوشش مرحلهٔ دوم.'):'تعداد محصولات ذخیره‌شده؛ هنوز مقصدی در نتیجهٔ جدول مغایرت موجود نیست.';}
  if(!rows.length){body.innerHTML='<tr><td colspan="'+cols+'" class="spb-empty">هیچ پروفایل ذخیره‌شده‌ای وجود ندارد.</td></tr>';foot.innerHTML='';return;}
  let all=0,detailed=0,enabled=0;const destTotals={};dests.forEach(x=>destTotals[x.key]=0);
  const profileHtml=rows.map(row=>{const counts=row.counts||{},det=row.detail||{},dc=row.destinations||{},pm=row.price_mismatches||{},total=parseInt(counts.total||det.total||0),done=Math.min(total,parseInt(det.detailed||0)),on=!!det.enabled,nsel=parseInt(det.selector_count||0),pct=total?Math.round(done*100/total):0;all+=total;detailed+=done;if(on)enabled++;
    const destCells=dests.map(x=>{const n=parseInt(dc[x.key]||0),mis=parseInt(pm[x.key]||0),dp=total?Math.round(n*100/total):0,pending=startDestinationEqualizePending.has(String(row.key||'')+'|'+String(x.key||''));destTotals[x.key]=(destTotals[x.key]||0)+n;return '<td><span class="spb-dest-num">'+spoNum(n)+'</span><small class="spb-dest-pct">'+spoNum(dp)+'٪ از پروفایل</small><small class="spb-price-mismatch" title="بر پایهٔ قیمت مورد انتظار پس از اعمال ضرایب تعدیل کلی">⚠ مغایرت قیمت: '+spoNum(mis)+'</small><button type="button" class="spb-equalize" data-profile="'+esc(row.key||'')+'" data-destination="'+esc(x.key||'')+'" onclick="equalizeStartDestination(this)" '+(pending?'disabled':'')+'>'+(pending?'⏳ صف مستقیم فعال…':'⚖️ برابر‌سازی')+'</button></td>';}).join('');
    return '<tr data-profile-key="'+esc(row.key||'')+'"><td><span class="spb-profile"><i></i><b title="'+esc(row.name||row.key||'')+'">'+esc(row.name||row.key||'—')+'</b><button type="button" class="spb-dup-btn" data-dup-profile="'+esc(row.key||'')+'" data-dup-name="'+esc(row.name||row.key||'')+'" data-dup-count="'+esc(String(total))+'" onclick="duplicateStartBreakdownProfile(this)" title="داپلیکیت (کپی) از این پروفایل">📋</button><button type="button" class="spb-del-btn" data-del-profile="'+esc(row.key||'')+'" data-del-name="'+esc(row.name||row.key||'')+'" onclick="deleteStartBreakdownProfile(this)" title="حذف کامل این پروفایل">🗑</button></span></td>'+
      '<td><span class="spb-num">'+spoNum(total)+'</span></td>'+destCells+
      '<td><span class="spb-badge '+(on?'on':'off')+'">'+(on?('✓ فعال · '+spoNum(nsel)+' سلکتور'):'✕ غیرفعال')+'</span></td>'+
      '<td><span class="spb-badge '+(on?'on':'off')+'">'+(on?'▶ اجرا می‌شود':'— اجرا نمی‌شود')+'</span></td>'+
      '<td><div class="spb-coverage"><div class="spb-coverage-top"><b>'+spoNum(done)+' از '+spoNum(total)+'</b><span>'+spoNum(pct)+'٪</span></div><span class="spb-bar"><i style="width:'+pct+'%"></i></span></div></td></tr>';
  }).join('');
  const miscMap=mx.uncoded_products||{},miscTotal=dests.reduce((n,x)=>n+(x.type==='bsl'?(Array.isArray(miscMap[x.key])?miscMap[x.key].length:parseInt(x.uncoded||0)):0),0);
  const miscCells=dests.map(x=>{const n=x.type==='bsl'?(Array.isArray(miscMap[x.key])?miscMap[x.key].length:parseInt(x.uncoded||0)):0;return '<td class="spb-misc-cell" data-misc-destination="'+esc(x.key||'')+'"><span class="spb-dest-num">'+spoNum(n)+'</span><small class="spb-dest-pct">'+(x.type==='bsl'?'نمایش محصولات':'موردی ندارد')+'</small></td>';}).join('');
  const miscHtml='<tr class="spb-misc-row" tabindex="0" role="button" data-misc-destination="all"><td><span class="spb-profile"><i></i><b>متفرقه‌های بدون کد</b></span></td><td class="spb-misc-cell"><span class="spb-num">'+spoNum(miscTotal)+'</span><small class="spb-dest-pct">جمع همهٔ غرفه‌ها</small></td>'+miscCells+'<td class="spb-misc-na">—</td><td class="spb-misc-na">—</td><td class="spb-misc-na">برای مشاهده کلیک کنید</td></tr>';
  body.innerHTML=profileHtml+miscHtml;
  body.onclick=e=>{const cell=e.target.closest('[data-misc-destination]');if(cell&&body.contains(cell))openStartMiscProducts(cell.dataset.miscDestination||'all')};
  body.onkeydown=e=>{if(e.key!=='Enter'&&e.key!==' ')return;const row=e.target.closest('.spb-misc-row');if(row){e.preventDefault();openStartMiscProducts('all')}};
  const pct=all?Math.round(detailed*100/all):0,mismatchTotals=mx.price_mismatch_totals||{},destFoot=dests.map(x=>'<td><b class="spb-dest-num">'+spoNum(destTotals[x.key]||0)+'</b><small class="spb-dest-pct">موجود کددارِ پروفایل‌ها</small><small class="spb-price-mismatch" title="بر پایهٔ ضرایب تعدیل کلی">⚠ مغایرت قیمت: '+spoNum(mismatchTotals[x.key]||0)+'</small>'+(x.type==='bsl'?'<small class="spb-uncoded">متفرقه بدون کد: '+spoNum(x.uncoded||0)+'</small>':'')+'</td>').join('');
  foot.innerHTML='<tr><td>جمع '+spoNum(rows.length)+' پروفایل</td><td>'+spoNum(all)+'</td>'+destFoot+'<td>'+spoNum(enabled)+' پروفایل فعال</td><td>'+(enabled?'مرحلهٔ دوم فعال است':'مرحلهٔ دوم غیرفعال است')+'</td><td>'+spoNum(detailed)+' از '+spoNum(all)+' · '+spoNum(pct)+'٪</td></tr>';
}
let startMiscModalItems=[],startMiscSelected=new Set(),startMiscDrafts={},startMiscEditing=false,startMiscBusy=false,startMiscLabel='';
function openStartOverviewModal(){
  const m=$('startProductOverviewModal');if(!m)return;
  /* Portal to body: transformed/overflow ancestors can otherwise trap a fixed
     dialog inside the Start pane's stacking context. */
  if(m.parentNode!==document.body)document.body.appendChild(m);
  m.classList.add('open');document.body.style.overflow='hidden';
}
function openStartMiscProducts(destination){
  const d=startProductOverviewData,mx=(d&&d.matrix)||{},map=mx.uncoded_products||{},dests=Array.isArray(mx.destinations)?mx.destinations:[];if(!d)return;
  let items=[],label='همهٔ غرفه‌ها';
  if(destination==='all'){dests.forEach(x=>{if(Array.isArray(map[x.key]))items=items.concat(map[x.key])});}
  else{items=Array.isArray(map[destination])?map[destination]:[];const md=dests.find(x=>x.key===destination);if(md)label=md.label||md.key||label;}
  startMiscModalItems=items.map(p=>Object.assign({},p,{_key:String(p.destination||destination)+'|'+String(p.id||0)}));
  startMiscSelected=new Set();startMiscDrafts={};startMiscEditing=false;startMiscBusy=false;startMiscLabel=label;
  $('spoDetailTitle').textContent='🧩 محصولات متفرقهٔ بدون کد';renderStartMiscProducts();openStartOverviewModal();
}
function renderStartMiscProducts(){
  $('spoDetailSub').textContent=spoNum(startMiscModalItems.length)+' محصول · '+startMiscLabel+' · انتخاب تکی یا همه';
  const selected=startMiscSelected.size,all=startMiscModalItems.length>0&&selected===startMiscModalItems.length;
  let h='<div class="spb-misc-toolbar"><label><input type="checkbox" '+(all?'checked':'')+' '+(startMiscBusy?'disabled':'')+' onchange="startMiscSelectAll(this.checked)"> انتخاب همه</label>'+
    '<button type="button" class="btn btn-red" onclick="startMiscArchiveSelected()" '+(!selected||startMiscBusy?'disabled':'')+'>🗑 حذف / بایگانی انتخابی</button>'+
    '<button type="button" class="btn btn-blue" onclick="startMiscEditSelected()" '+(!selected||startMiscBusy?'disabled':'')+'>'+(startMiscEditing?'💾 ذخیرهٔ عنوان‌ها':'✏️ تغییر عنوان انتخابی')+'</button>'+
    '<span class="spb-misc-selected">'+spoNum(selected)+' انتخاب‌شده</span><div class="spb-misc-progress" id="startMiscProgress">'+(startMiscBusy?'در حال اجرای عملیات…':'')+'</div></div>'+
    '<div class="spb-misc-modal-scroll"><table class="spb-misc-table"><thead><tr><th>انتخاب</th><th>#</th><th>غرفه</th><th>شناسه</th><th>عنوان محصول</th><th>قیمت</th><th>موجودی / وضعیت</th><th>لینک</th></tr></thead><tbody>';
  if(!startMiscModalItems.length)h+='<tr><td colspan="8" class="spb-empty">محصول متفرقهٔ بدون کدی در این مقصد نیست.</td></tr>';
  startMiscModalItems.forEach((p,i)=>{const sel=startMiscSelected.has(p._key),editing=startMiscEditing&&sel,draft=startMiscDrafts[p._key]!==undefined?startMiscDrafts[p._key]:String(p.title||'');
    const title=editing?'<input class="spb-misc-title-input" data-misc-key="'+esc(p._key)+'" value="'+esc(draft)+'" maxlength="120" oninput="startMiscDrafts[this.dataset.miscKey]=this.value">':'<b>'+esc(p.title||'بدون عنوان')+'</b>';
    h+='<tr class="'+(sel?'is-selected ':'')+(p._failed?'is-failed':'')+'"><td><input type="checkbox" '+(sel?'checked':'')+' '+(startMiscBusy?'disabled':'')+' onchange="startMiscToggle(\''+esc(p._key)+'\',this.checked)"></td><td>'+spoNum(i+1)+'</td><td>'+esc(p.shop||'—')+'</td><td><code>'+spoNum(p.id||0)+'</code></td><td>'+title+(p._result?'<small class="spb-misc-result '+(p._failed?'err':'')+'">'+esc(p._result)+'</small>':'')+'</td><td>'+((parseInt(p.price)||0)>0?spoNum(p.price):'—')+'</td><td>'+spoNum(p.stock||0)+' / '+esc(String(p.status||'—'))+'</td><td>'+(p.url?'<a href="'+esc(p.url)+'" target="_blank" rel="noopener">مشاهده ↗</a>':'—')+'</td></tr>';});
  h+='</tbody></table></div>';$('spoDetailBody').innerHTML=h;
}
function startMiscSelectAll(on){startMiscSelected=new Set(on?startMiscModalItems.map(p=>p._key):[]);if(!on)startMiscEditing=false;else if(startMiscEditing)startMiscModalItems.forEach(p=>{if(startMiscDrafts[p._key]===undefined)startMiscDrafts[p._key]=String(p.title||'')});renderStartMiscProducts()}
function startMiscToggle(key,on){if(on){startMiscSelected.add(key);if(startMiscEditing&&startMiscDrafts[key]===undefined){const p=startMiscModalItems.find(x=>x._key===key);startMiscDrafts[key]=String((p&&p.title)||'')}}else{startMiscSelected.delete(key);delete startMiscDrafts[key]}if(!startMiscSelected.size)startMiscEditing=false;renderStartMiscProducts()}
function startMiscEditSelected(){
  if(startMiscBusy||!startMiscSelected.size)return;
  if(!startMiscEditing){startMiscEditing=true;startMiscModalItems.forEach(p=>{if(startMiscSelected.has(p._key))startMiscDrafts[p._key]=String(p.title||'')});renderStartMiscProducts();return;}
  const chosen=startMiscModalItems.filter(p=>startMiscSelected.has(p._key)&&String(startMiscDrafts[p._key]||'').trim()!==String(p.title||'').trim());
  if(!chosen.length){showToast('عنوانی تغییر نکرده است',true);return;}
  startMiscRunActions('rename',chosen);
}
function startMiscArchiveSelected(){
  if(startMiscBusy||!startMiscSelected.size)return;const chosen=startMiscModalItems.filter(p=>startMiscSelected.has(p._key));
  if(!confirm('حذف همیشگی در API باسلام وجود ندارد. '+chosen.length.toLocaleString('fa-IR')+' محصول انتخابی حذف/بایگانی شود؟'))return;
  startMiscRunActions('archive',chosen);
}
async function startMiscRunActions(action,chosen){
  startMiscBusy=true;renderStartMiscProducts();let cursor=0,done=0,ok=0,failed=0;
  const progress=()=>{const el=$('startMiscProgress');if(el)el.textContent='انجام‌شده '+spoNum(done)+' از '+spoNum(chosen.length)+' · موفق '+spoNum(ok)+' · خطا '+spoNum(failed)};progress();
  async function worker(){while(true){const i=cursor++;if(i>=chosen.length)return;const p=chosen[i],fd=new FormData();fd.append('start_misc_product_action','1');fd.append('misc_action',action);fd.append('destination',String(p.destination||''));fd.append('product_id',String(p.id||0));if(action==='rename')fd.append('title',String(startMiscDrafts[p._key]||'').trim());
      try{const r=await fetch(location.pathname,{method:'POST',body:fd,cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'عملیات ناموفق بود');ok++;p._result=d.msg||'انجام شد';p._failed=false;
        const map=((startProductOverviewData||{}).matrix||{}).uncoded_products||{},arr=Array.isArray(map[p.destination])?map[p.destination]:[],idx=arr.findIndex(x=>parseInt(x.id||0)===parseInt(p.id||0));
        if(action==='archive'){if(idx>=0)arr.splice(idx,1);startMiscSelected.delete(p._key);}
        else{const nt=String(startMiscDrafts[p._key]||'').trim();p.title=nt;if(idx>=0)arr[idx].title=nt;startMiscSelected.delete(p._key);}
      }catch(e){failed++;p._failed=true;p._result=e.message||String(e)}finally{done++;progress()}}
  }
  await Promise.all(Array.from({length:Math.min(3,chosen.length)},worker));
  if(action==='archive')startMiscModalItems=startMiscModalItems.filter(p=>!(!p._failed&&chosen.includes(p)));
  startMiscEditing=false;startMiscBusy=false;renderStartProfileBreakdown(startProductOverviewData);renderStartMiscProducts();
  showToast('عملیات پایان یافت: '+ok.toLocaleString('fa-IR')+' موفق، '+failed.toLocaleString('fa-IR')+' خطا',failed>0);
}
const startDestinationEqualizePending=new Set();
function equalizeStartDestination(btn){
  const pk=String((btn&&btn.dataset.profile)||''),dest=String((btn&&btn.dataset.destination)||''),sig=pk+'|'+dest;if(!pk||!dest||startDestinationEqualizePending.has(sig))return;
  startDestinationEqualizePending.add(sig);btn.disabled=true;btn.textContent='⏳ ساخت صف مستقیم…';
  const fd=new FormData();fd.append('start_profile_destination_equalize','1');fd.append('profile_key',pk);fd.append('destination',dest);
  fetch(location.pathname,{method:'POST',body:fd,cache:'no-store'}).then(async r=>{const text=await r.text();let d={};try{d=JSON.parse(text)}catch(e){d={ok:false,error:text.trim()||('HTTP '+r.status)}}return{r,d}}).then(({r,d})=>{
    if(!r.ok||!d.ok){const logs=d&&d.send&&Array.isArray(d.send.log)?d.send.log.join(' · '):'';throw new Error((d&&d.error)||logs||'صف‌کردن عملیات ناموفق بود')}
    btn.textContent='✓ در صف ارسال';showToast(d.message||'صف برابر‌سازی مستقیم ساخته شد؛ شمارش جدول شرط اجرا نیست');
    setTimeout(()=>loadStartProductOverview(true),12000);
    setTimeout(()=>{startDestinationEqualizePending.delete(sig);if(document.body.contains(btn)){btn.disabled=false;btn.textContent='⚖️ برابر‌سازی'}},60000);
  }).catch(e=>{startDestinationEqualizePending.delete(sig);btn.disabled=false;btn.textContent='⚖️ برابر‌سازی';showToast(e.message||String(e),true)});
}
function loadStartProductOverview(force){
  const grid=$('startProductOverviewGrid'),meta=$('startProductOverviewMeta');if(!grid||startProductOverviewBusy)return;
  startProductOverviewBusy=true;if(force)meta.textContent='در حال محاسبهٔ دوباره…';
  fetch('?start_product_stats=1&_='+Date.now(),{cache:'no-store'}).then(r=>r.json()).then(d=>{
    if(!d||!d.ok)throw new Error((d&&d.error)||'پاسخ نامعتبر');startProductOverviewData=d;renderStartProfileBreakdown(d);
    const total=parseInt((d.totals||{}).total||0),prof=parseInt(d.profiles||0);
    meta.textContent=spoNum(total)+' محصول در '+spoNum(prof)+' پروفایل · آخرین محاسبه: '+new Date((d.generated_at||0)*1000).toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'});
    grid.innerHTML=START_PRODUCT_METRICS.map(m=>{const n=parseInt((d.totals||{})[m[0]]||0),pct=total?Math.round(n*100/total):0;
      return '<button class="spo-card" style="--spo-color:'+m[3]+'" onclick="openStartProductOverviewDetail(\''+m[0]+'\')" title="'+esc(m[4])+'"><span class="spo-icon">'+m[1]+'</span><b class="spo-value">'+spoNum(n)+'</b><span class="spo-label">'+esc(m[2])+'</span><span class="spo-foot"><span>'+esc(m[4])+'</span><b class="spo-pct">'+spoNum(pct)+'٪</b></span></button>';
    }).join('');
  }).catch(e=>{grid.innerHTML='<div class="spo-error">آمار کل محصولات خوانده نشد: '+esc(e.message||String(e))+'</div>';meta.textContent='برای تلاش دوباره دکمهٔ تازه‌سازی را بزنید.';const b=$('startProfileBreakdownBody'),f=$('startProfileBreakdownFoot');if(b)b.innerHTML='<tr><td colspan="99" class="spb-empty">جدول پروفایل‌ها خوانده نشد؛ دوباره تلاش کنید.</td></tr>';if(f)f.innerHTML='';}).finally(()=>{startProductOverviewBusy=false;});
}
function openStartProductOverviewDetail(metric){
  const d=startProductOverviewData;if(!d)return;const def=START_PRODUCT_METRICS.find(x=>x[0]===metric);if(!def)return;
  const total=parseInt((d.totals||{}).total||0),value=parseInt((d.totals||{})[metric]||0),rows=(d.by_profile||[]).filter(x=>parseInt(((x.counts||{})[metric])||0)>0);
  $('spoDetailTitle').textContent=def[1]+' '+def[2];$('spoDetailSub').textContent=spoNum(value)+' از '+spoNum(total)+' محصول · '+def[4];
  const max=Math.max(1,...rows.map(x=>parseInt((x.counts||{})[metric]||0)));
  let h=rows.length?'<div>': '<div class="spo-empty">موردی برای این شاخص وجود ندارد.</div>';
  rows.forEach(x=>{const n=parseInt((x.counts||{})[metric]||0),all=parseInt((x.counts||{}).total||0),pct=all?Math.round(n*100/all):0;
    h+='<div class="spo-profile-row"><span title="'+esc(x.name||x.key||'')+'">'+esc(x.name||x.key||'—')+'</span><b>'+spoNum(n)+' <small style="color:#64748b">('+spoNum(pct)+'٪)</small></b><span class="spo-profile-bar"><i style="width:'+Math.round(n*100/max)+'%"></i></span></div>';
  });if(rows.length)h+='</div>';
  const samples=((d.samples||{})[metric]||[]);if(samples.length){h+='<h4 style="font-size:11px;color:#cbd5e1;margin:15px 0 7px">نمونه محصولات</h4><div class="spo-samples">';samples.forEach(s=>{h+='<div class="spo-sample"><b>'+esc(s.title||'بدون عنوان')+'</b><span>'+esc(s.profile||'')+'</span><br><span>قیمت: '+(s.price?spoNum(s.price):'—')+' · تصاویر: '+spoNum(s.images||0)+'</span>'+(s.link?'<br><a href="'+esc(s.link)+'" target="_blank" rel="noopener" style="color:#7dd3fc">باز کردن محصول ↗</a>':'')+'</div>';});h+='</div>';}
  $('spoDetailBody').innerHTML=h;openStartOverviewModal();
}
function closeStartProductOverviewDetail(){const m=$('startProductOverviewModal');if(m)m.classList.remove('open');document.body.style.overflow='';}
setTimeout(()=>loadStartProductOverview(false),700);
setInterval(()=>{const pane=$('pane-start');if(document.visibilityState==='visible'&&pane&&pane.classList.contains('active'))loadStartProductOverview(false)},60000);

function markDirty() {
    isDirty = true;
    const s = $('profileStatus');
    s.textContent = 'تغییرات';
    s.className = 'profile-indicator unsaved';
}

function markClean(key) {
    isDirty = false;
    currentProfileKey = key;
    const s = $('profileStatus');
    s.textContent = 'ذخیره';
    s.className = 'profile-indicator saved';
}

function scheduleSave() {
    if (!$('url').value.trim()) return;
    markDirty();
    clearTimeout(saveTimer);
    saveTimer = setTimeout(saveProfileSilent, 500);
    // v7.66: Update auto-extract button based on selector state
    if(sel.container && sel.title){
        $('startBtn').textContent='▶ استخراج اتوماتیک ✓ ('+sel.container+')';
        $('startBtn').style.background='#22c55e';
        $('startBtn').style.color='#fff';
    }else{
        $('startBtn').textContent='▶ استخراج اتوماتیک';
        $('startBtn').style.background='';
        $('startBtn').style.color='';
    }
}

/* =====================================================================
 *  v9.91: آخرین تبِ باز بعد از رفرش برمی‌گردد
 *
 *  تا اینجا با هر رفرش، تب «شروع» باز می‌شد (یا اگر پروفایلی بازیابی
 *  می‌شد، تب «نتایج»). آدرسِ هش (#results) نوشته می‌شد ولی دو چیز آن را
 *  بی‌اثر می‌کرد: ۱) اگر کاربر هیچ تبی را دستی کلیک نکرده بود هشی وجود
 *  نداشت، ۲) بازیابیِ خودکارِ آخرین پروفایل بعد از آن اجرا می‌شد و
 *  زورکی به «نتایج» می‌پرید. حالا نامِ تب در همین مرورگر ذخیره می‌شود و
 *  بازیابیِ پروفایل دیگر تب را عوض نمی‌کند. */
const MAIN_TABS = ['start','settings','selectors','results','send','import'];
const LAST_TAB_KEY = 'scraper_last_main_tab';
/* v10.488: each footer tab owns its own document vertical scroll position. */
const MAIN_TAB_SCROLL_POS = Object.create(null);
function rememberMainTab(name){
    try { if (MAIN_TABS.includes(name)) localStorage.setItem(LAST_TAB_KEY, name); } catch(e) {}
}
function lastMainTab(){
    try { const v = localStorage.getItem(LAST_TAB_KEY) || ''; return MAIN_TABS.includes(v) ? v : ''; }
    catch(e) { return ''; }
}

function switchMainTab(name) {
    const target=document.getElementById('pane-'+name);
    const currentPane=document.querySelector('.tab-pane.active');
    const currentName=currentPane&&currentPane.id.startsWith('pane-')?currentPane.id.slice(5):'';
    if(target&&currentName&&currentName!==name){
        MAIN_TAB_SCROLL_POS[currentName]=Math.max(0,window.scrollY||document.documentElement.scrollTop||0);
    }
    document.querySelectorAll('.main-tab').forEach(t => t.classList.toggle('active', t.dataset.tab === name));
    // v9.65: اگر پنلِ درخواست‌شده وجود نداشته باشد (مثلاً نامِ اشتباه)، هیچ پنلی را
    // خالی نکن. قبلاً switchMainTab('profiles') همهٔ پنل‌ها را deactivate می‌کرد
    // چون پنلی به نام pane-profiles وجود ندارد → کل محتوای تب‌ها خالی دیده می‌شد.
    if(target){
        document.querySelectorAll('.tab-pane').forEach(p => p.classList.toggle('active', p === target));
        const restoreY=Math.max(0,Number(MAIN_TAB_SCROLL_POS[name]||0));
        requestAnimationFrame(()=>window.scrollTo(0,restoreY));
    }
    try { history.replaceState(null, '', '#' + name); } catch(e) {}
    rememberMainTab(name);   // v9.91: تا رفرشِ بعدی همین‌جا باز شود
    /* v10.31 (۴۴): نتایج تا لحظهٔ دیده‌شدن ساخته نمی‌شوند. ورود به تب
       همان لحظه است — پس اگر نمای جاری کهنه است، همین‌جا ساختش. */
    if (name === 'results' && typeof rvEnsure === 'function') rvEnsure(rvCurView);
    if (name === 'start' && typeof loadStartProductOverview === 'function') loadStartProductOverview(false);
    /* Refresh both send queues on entry so queued profiles are visible immediately. */
    if (name === 'send') {
        try { if (typeof checkWooQueue === 'function') checkWooQueue(); } catch(e) {}
        try { if (typeof checkBslQueue === 'function') checkBslQueue(); } catch(e) {}
    }
}
// v8.17: Settings panel toggle
function toggleSettingsPanel(){
  const p=document.getElementById('settingsPanel');
  const o=document.getElementById('settingsOverlay');
  const b=document.getElementById('hamburgerBtn');
  const fb=document.getElementById('fullBtn');
  const hfb=document.getElementById('hdrFullBtn');
  if(!p)return;
  if(p.classList.contains('open')){
    p.classList.remove('open');
    if(o)o.classList.remove('open');
    if(b)b.classList.remove('active');
    document.body.classList.remove('spanel-open');
  }else{
    p.classList.add('open');
    if(o)o.classList.add('open');
    if(b)b.classList.add('active');
    document.body.classList.add('spanel-open');
    try{
      if(localStorage.getItem('amphp_spanel_full')==='1'){
        p.classList.add('full');
        if(fb)fb.classList.add('active');
        if(hfb)hfb.classList.add('active');
      }
    }catch(e){}
    syncSmenuStickyOffsets();
  }
  document.body.classList.toggle('spanel-full', p.classList.contains('full') && p.classList.contains('open'));
}
/* v9.94 (۸ب): ارتفاعِ واقعیِ سربرگِ پنل و یک سربخشِ نمونه را اندازه می‌گیریم و
   داخل متغیرهای CSS می‌گذاریم. با این کار سربخش‌های چسبان دقیقاً زیرِ سربرگ
   می‌نشینند، حتی اگر فونتِ انتخابیِ کاربر ارتفاع‌ها را عوض کرده باشد. */
function syncSmenuStickyOffsets(){
  const p=document.getElementById('settingsPanel');if(!p)return;
  const head=p.querySelector('.settings-panel-head');
  const hdr=p.querySelector('.smenu-hdr');
  const hh=head?Math.round(head.getBoundingClientRect().height):0;
  const sh=hdr?Math.round(hdr.getBoundingClientRect().height):0;
  if(hh>0)p.style.setProperty('--spanel-head-h',hh+'px');
  if(sh>0)p.style.setProperty('--smenu-hdr-h',sh+'px');
}
// v9.61: تمام‌عرض کردن پنل تنظیمات (منو و محتویاتش). اگر منو بسته باشد اول باز
// می‌شود؛ کلاس .full روی پنل عرض را به 100vw و سقف‌های .smenu-body را بی‌سقف می‌کند
// تا هیچ بخشی گیر و بریده نماند.
function toggleFullSettings(){
  const p=document.getElementById('settingsPanel');
  const b=document.getElementById('fullBtn');
  const hfb=document.getElementById('hdrFullBtn');
  if(!p)return;
  if(!p.classList.contains('open')){
    toggleSettingsPanel();
  }
  const full=p.classList.toggle('full');
  if(b)b.classList.toggle('active', full);
  if(hfb)hfb.classList.toggle('active', full);
  document.body.classList.toggle('spanel-full', full && p.classList.contains('open'));
  try{ localStorage.setItem('amphp_spanel_full', full ? '1' : '0'); }catch(e){}
  syncSmenuStickyOffsets();
}
(function(){
  try{
    if(localStorage.getItem('amphp_spanel_full')==='1'){
      const p=document.getElementById('settingsPanel');
      const b=document.getElementById('fullBtn');
      const hfb=document.getElementById('hdrFullBtn');
      if(p)p.classList.add('full');
      if(b)b.classList.add('active');
      if(hfb)hfb.classList.add('active');
    }
  }catch(e){}
  /* Escape می‌بندد؛ overlay از قبل onclick="toggleSettingsPanel()" دارد */
  document.addEventListener('keydown', function(ev){
    if(ev.key!=='Escape')return;
    const p=document.getElementById('settingsPanel');
    if(p && p.classList.contains('open')) toggleSettingsPanel();
  });
})();
/* v9.94 (۸ب): بعد از پایانِ ترنزیشنِ باز شدن، کلاس smenu-done می‌گیرد تا سقفِ
   max-height برداشته و overflow باز شود؛ موقعِ بستن اول برمی‌گردد به حالتِ
   سقف‌دار وگرنه انیمیشنِ بسته‌شدن اصلاً دیده نمی‌شود. */
function toggleSmenu(hdr){
  const isOpen=hdr.classList.contains('open');
  hdr.classList.toggle('open');
  const body=hdr.nextElementSibling;
  if(body){
    if(isOpen){
      body.classList.remove('smenu-done');
      void body.offsetHeight;          /* فورس رفلو تا ترنزیشن از ارتفاع واقعی شروع شود */
      body.classList.remove('open');
    }else{
      body.classList.add('open');
      clearTimeout(body.__smenuT);
      body.__smenuT=setTimeout(function(){if(body.classList.contains('open'))body.classList.add('smenu-done');},320);
    }
  }
  syncSmenuStickyOffsets();
}
