/* v10.20 (۳۳الف): تیکِ «ارسال همزمان به همهٔ غرفه‌ها».

   دو ایرادِ قدیمی که باعث می‌شد کاربر فکر کند تیک کار نمی‌کند:
   ۱) تیک هیچ‌جا ذخیره نمی‌شد — با هر بار رفرش خاموش می‌شد و کاربر بدون
      اینکه بفهمد دوباره تک‌غرفه‌ای می‌فرستاد.
   ۲) هیچ بازخوردی نبود؛ اگر هیچ غرفهٔ اضافیِ فعالی تعریف نشده بود، تیک
      روشن می‌ماند و در عمل هیچ اتفاقی نمی‌افتاد.
   حالا هم ذخیره می‌شود و هم تعدادِ غرفه‌های فعال کنارش نوشته می‌شود. */
// v10.88: shop picker state — array of selected vendor_ids (null = not initialised yet)
let bslSelectedShopVids = null; // null means "all" (default)

function bslAllShopEntries() {
    const shops = [];
    const defVid = parseInt(($('bsVid')||{}).value)||0;
    const defTok = ($('bsTk')||{}).value||'';
    if(defVid>0 && defTok.trim()!=='')
        shops.push({vid:defVid, name:'\u063a\u0631\u0641\u0647\u0654 \u067e\u06cc\u0634\u200c\u0641\u0631\u0636', isDefault:true, token:defTok});
    (Array.isArray(bslExtraVendors)?bslExtraVendors:[]).forEach(function(v){
        const vid=parseInt(v&&v.vendor_id)||0, tok=String(v&&v.token||'').trim();
        if(vid>0&&tok!=='')
            shops.push({vid:vid, name:v.shop_name||v.name||('\u063a\u0631\u0641\u0647 '+vid), isDefault:false, token:tok,
                price_mode:v.price_mode||'none', price_val:parseFloat(v.price_val||0)});
    });
    return shops;
}
function bslActiveShopCount(){return bslAllShopEntries().length;}

// Build dropdown HTML and wire events
function bslBuildShopDrop(){
    const list=$('bsShopDropList'); if(!list)return;
    const shops=bslAllShopEntries();
    if(shops.length===0){list.innerHTML='<div style="padding:8px 12px;font-size:11px;color:#64748b">\u063a\u0631\u0641\u0647\u0627\u06cc \u0641\u0639\u0627\u0644 \u06cc\u0627\u0641\u062a \u0646\u0634\u062f. \u0627\u0628\u062a\u062f\u0627 \u062f\u0631 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u063a\u0631\u0641\u0647 \u0627\u0636\u0627\u0641\u0647 \u06a9\u0646\u06cc\u062f.</div>';return;}
    // Init selection: null = all selected
    if(bslSelectedShopVids===null) bslSelectedShopVids=shops.map(s=>s.vid);
    const profMode=($('priceMode')||{}).value||'none';
    const profVal=parseFloat(($('priceVal')||{}).value)||0;
    const profRound=parseInt(($('roundPrice')||{}).value)||0;
    const bsCfg=typeof liveDestCfg==='function'?liveDestCfg('bs'):{price_mode:($('bsPMode')||{}).value||'none',price_val:parseFloat(($('bsPVal')||{}).value)||0,price_round:parseInt(($('bsPRound')||{}).value)||0};
    let h='';
    shops.forEach(function(s){
        const checked=bslSelectedShopVids.includes(s.vid);
        const vMode=s.isDefault?'none':(s.price_mode||'none');
        const vVal=s.isDefault?0:(parseFloat(s.price_val)||0);
        let priceBadge='';
        try{
            const prev=bslShopThreeLayerPreview(100000,profMode,profVal,profRound,bsCfg.price_mode||'none',parseFloat(bsCfg.price_val)||0,parseInt(bsCfg.price_round)||0,vMode,vVal);
            if(prev.pct!==0||(bsCfg.price_mode&&bsCfg.price_mode!=='none')||vMode!=='none'){
                const pct=prev.pct; const col=pct>0?'#4ade80':(pct<0?'#f87171':'#94a3b8');
                priceBadge='<span style="font-size:9px;color:'+col+';margin-right:4px" title="پروفایل '+toFa(prev.profPct)+'٪ · کلی باسلام '+toFa(prev.globalPct)+'٪'+(s.isDefault?'':(' · غرفه '+toFa(prev.shopPct)+'٪'))+'">'+(pct>=0?'+':'')+toFa(pct)+'%</span>';
            }
        }catch(e){}
        h+='<label style="display:flex;align-items:center;gap:8px;padding:6px 12px;cursor:pointer;user-select:none" '
          +'onmouseover="this.style.background=\'#273549\'" onmouseout="this.style.background=\'\'">'
          +'<input type="checkbox" '+(checked?'checked':'')
          +' onchange="bslShopPickToggle('+s.vid+',this.checked)" style="width:14px;height:14px;flex-shrink:0">'
          +'<span style="flex:1;font-size:11px;color:#e2e8f0">'+esc(s.name)
          +(s.isDefault?'<span style="font-size:8.5px;color:#0f172a;background:#67e8f9;border-radius:3px;padding:0 4px;margin-right:4px"> \u067e\u06cc\u0634\u200c\u0641\u0631\u0636</span>':'')
          +'</span>'
          +priceBadge
          +'<span style="font-size:9px;color:#475569">#'+toFa(s.vid)+'</span>'
          +'</label>';
    });
    list.innerHTML=h;
}
function bslPositionShopDrop(){
    const btn=$('bsShopDropBtn'), menu=$('bsShopDropMenu'); if(!btn||!menu)return;
    const r=btn.getBoundingClientRect();
    const menuH=menu.offsetHeight||300;
    const spaceBelow=window.innerHeight-r.bottom;
    const spaceAbove=r.top;
    // prefer below; flip above if not enough room
    if(spaceBelow>=menuH+8||spaceBelow>=spaceAbove){
        menu.style.top=(r.bottom+4)+'px';
    } else {
        menu.style.top=Math.max(4,(r.top-menuH-4))+'px';
    }
    // align right edge with button right edge; clamp to viewport
    const menuW=Math.max(240,Math.min(320,window.innerWidth-16));
    menu.style.width=menuW+'px';
    let left=r.right-menuW;
    if(left<8)left=8;
    if(left+menuW>window.innerWidth-8)left=window.innerWidth-menuW-8;
    menu.style.left=left+'px';
}
function bslToggleShopDrop(){
    const menu=$('bsShopDropMenu'); if(!menu)return;
    if(menu.style.display==='none'||!menu.style.display){
        // v10.88 fix2: portal — move to <body> so no ancestor clips it
        if(menu.parentElement!==document.body)document.body.appendChild(menu);
        bslBuildShopDrop();
        menu.style.display='block';
        bslPositionShopDrop();
        // close on outside click or scroll
        setTimeout(function(){
            function outsideClick(e){if(!$('bsShopDropWrap')?.contains(e.target)&&!menu.contains(e.target)){bslCloseShopDrop();document.removeEventListener('click',outsideClick);window.removeEventListener('scroll',outsideClick,true);}}
            document.addEventListener('click',outsideClick);
            window.addEventListener('scroll',outsideClick,true);
        },10);
    } else { bslCloseShopDrop(); }
}
function bslCloseShopDrop(){
    const menu=$('bsShopDropMenu'); if(menu)menu.style.display='none';
    bslUpdateShopDropLabel();
}
function bslShopPickToggle(vid,checked){
    const shops=bslAllShopEntries();
    if(bslSelectedShopVids===null) bslSelectedShopVids=shops.map(s=>s.vid);
    if(checked){ if(!bslSelectedShopVids.includes(vid))bslSelectedShopVids.push(vid); }
    else { bslSelectedShopVids=bslSelectedShopVids.filter(v=>v!==vid); }
    bslSelectedShopVids=Array.from(new Set(bslSelectedShopVids.map(Number))).filter(v=>shops.some(s=>s.vid===v));
    bslUpdateShopDropLabel();
    bslRenderShopsHint();

    /* The dropdown is excluded from delegated autosave, so persist this change explicitly. */
    try{if(typeof scheduleConnSave==='function')scheduleConnSave();}catch(e){}

}
function bslShopPickAll(select){
    const shops=bslAllShopEntries();
    bslSelectedShopVids=select?shops.map(s=>s.vid):[];
    bslBuildShopDrop(); // re-render checkboxes
    bslUpdateShopDropLabel();
    bslRenderShopsHint();

    try{if(typeof scheduleConnSave==='function')scheduleConnSave();}catch(e){}

}
function bslUpdateShopDropLabel(){
    const lbl=$('bsShopDropLabel'); if(!lbl)return;
    const shops=bslAllShopEntries(); const total=shops.length;
    if(total===0){lbl.textContent='\u063a\u0631\u0641\u0647\u0627\u06cc \u0641\u0639\u0627\u0644 \u06cc\u0627\u0641\u062a \u0646\u0634\u062f';return;}
    const sel=(bslSelectedShopVids===null)?total:bslSelectedShopVids.length;
    if(sel===0) lbl.textContent='\u0647\u06cc\u0686 \u063a\u0631\u0641\u0647\u0627\u06cc \u0627\u0646\u062a\u062e\u0627\u0628 \u0646\u0634\u062f\u0647';
    else if(sel===total) lbl.textContent='\U0001f3ea \u0647\u0645\u0647\u0654 \u063a\u0631\u0641\u0647\u200c\u0647\u0627 ('+toFa(total)+')';
    else {
        const names=shops.filter(s=>bslSelectedShopVids.includes(s.vid)).map(s=>s.name.slice(0,8));
        lbl.textContent='\U0001f3ea '+names.join('، ')+(sel>2?'...':'');
    }
}
function bslGetShopSendMode(){
    const el=$('bsShopSendMode');
    return (el&&el.value==='parallel')?'parallel':'serial';
}
function bslOnShopSendModeChange(){
    const m=bslGetShopSendMode();
    if(cn&&cn.basalam)cn.basalam.shop_send_mode=m;
    bslRenderShopsHint();
    try{if(typeof scheduleConnSave==='function')scheduleConnSave();else saveConn();}catch(e){}
}
function bslRenderShopsHint(){
    const el=$('bsShopsHint'); if(!el)return;
    const shops=bslAllShopEntries(); const total=shops.length;
    const sel=(bslSelectedShopVids===null)?total:(bslSelectedShopVids||[]).length;
    const modeWrap=$('bsShopModeWrap');
    if(modeWrap)modeWrap.style.opacity=(sel>1?'1':'0.6');
    if(total===0){el.style.color='#fbbf24';el.textContent='⚠ غرفه‌ای فعال یافت نشد';return;}
    if(sel===0){el.style.color='#f87171';el.textContent='❌ هیچ غرفه‌ای انتخاب نشده';return;}
    if(sel===1){el.style.color='#4ade80';el.textContent='✓ ۱ غرفه انتخاب شده — ارسال مستقیم';return;}
    const isPar=(bslGetShopSendMode()==='parallel');
    const modeTxt=isPar?'⚡ موازی (همزمان به همهٔ غرفه‌ها)':'📋 سری (نوبتی، هر غرفه جداگانه در صف)';
    if(sel===total){el.style.color=isPar?'#67e8f9':'#c4b5fd';el.textContent='✓ همهٔ '+toFa(total)+' غرفه — '+modeTxt;}
    else{el.style.color=isPar?'#38bdf8':'#a78bfa';el.textContent='✓ '+toFa(sel)+' از '+toFa(total)+' غرفه — '+modeTxt;}
}
function bslToggleAllShops(){bslRenderShopsHint();try{saveConn();}catch(e){}}
// initialise hint after applyCn populates bslExtraVendors

function bslInitShopPicker(){
    const saved=(cn&&cn.basalam&&cn.basalam.send_shop_ids);
    if(Array.isArray(saved)){
        const allowed=new Set(bslAllShopEntries().map(s=>s.vid));
        bslSelectedShopVids=Array.from(new Set(saved.map(v=>parseInt(v)||0).filter(v=>v>0&&allowed.has(v))));
    }else{
        bslSelectedShopVids=null; // old configs and null mean all active shops
    }
    bslUpdateShopDropLabel();
    bslRenderShopsHint();
}

// Get selected vids for send action — null = all
function bslGetSelectedVids(){
    const shops=bslAllShopEntries();
    if(bslSelectedShopVids===null||bslSelectedShopVids.length===shops.length) return null;
    return bslSelectedShopVids.slice();
}

/* ═══════════════════════════════════════════════════════════════════
 *  v10.35 (۴۷ب): کشِ کاتالوگِ غرفه — وضعیت، بازسازی، پاک‌کردن
 *
 *  بازسازی می‌تواند دقایقی طول بکشد (هر ۱۰۰ محصول یک درخواست)، پس دکمه
 *  قفل می‌شود و پیام صریح می‌دهد؛ وگرنه کاربر چند بار می‌زند و چند
 *  پیمایشِ همزمان راه می‌افتد.
 * ═══════════════════════════════════════════════════════════════════ */
function bcRender(d){
  const box=$('bcBox'); if(!box)return;
  const rows=(d&&d.vendors)||[];
  if(!rows.length){
    box.innerHTML='<div style="color:#fbbf24">غرفهٔ فعالی پیدا نشد — توکن و شمارهٔ غرفه را تنظیم کنید.</div>';
    return;
  }
  let h='';
  rows.forEach(v=>{
    const col=v.fresh?'#4ade80':(v.count>0?'#fbbf24':'#64748b');
    const st=v.count<=0?'ساخته نشده':(v.fresh?'تازه':'کهنه — در ارسالِ بعدی از نو ساخته می‌شود');
    h+='<div style="border-top:1px solid #1e293b;padding:3px 0;display:flex;gap:6px;flex-wrap:wrap;align-items:center">'
      +'<span style="color:#cbd5e1;flex:1">🏪 '+esc(v.shop_name||('#'+v.vendor_id))+' <span style="color:#64748b">#'+v.vendor_id+'</span></span>'
      +'<span style="color:'+col+'">'+toFa(v.count||0)+' عنوان</span>'
      +'<span style="color:#64748b">'+esc(v.at_h||'—')+'</span>'
      +'<span style="color:'+col+'">'+esc(st)+'</span>'
      +(v.source?'<span style="color:#93c5fd">'+esc(v.source)+'</span>':'')
      +(v.status_scope?'<span style="color:#a78bfa">'+esc(v.status_scope)+'</span>':'')
      +(v.partial?'<span style="color:#f87171" title="کش ناقص است — «نبودنِ» محصول در آن قطعی شمرده نمی‌شود">⚠ ناقص</span>':'')
      +'</div>';
  });
  h+='<div style="color:#64748b;margin-top:5px">مدتِ اعتبار: '+toFa(Math.round((d.ttl||0)/3600))+' ساعت</div>';
  if(d.progress&&Array.isArray(d.progress.log)&&d.progress.log.length){
    const pp=d.progress;
    h+='<div style="margin-top:6px;background:#020617;border:1px solid #1e293b;border-radius:7px;padding:6px;color:#cbd5e1;max-height:150px;overflow:auto">'
      +'<div style="color:#93c5fd;margin-bottom:3px">جزئیات آخرین واکشی: '+esc(pp.phase||'')+' '+(pp.pct?toFa(pp.pct)+'٪':'')+'</div>'
      +pp.log.slice(-12).map(x=>'<div style="font-size:10.5px;border-top:1px solid #111827;padding:2px 0">'+esc((x&&x.m)?x.m:String(x))+'</div>').join('')+'</div>';
  }
  box.innerHTML=h;
}

/* v10.90 (۱۰۳): safeFetchJson — اگر پاسخ سرور HTML بود خطای خوانا می‌دهد */
function safeFetchJson(url, opts){
    return fetch(url, opts||undefined).then(function(r){
        var ct=r.headers.get('content-type')||'';
        if(!r.ok||!ct.includes('json')){
            return r.text().then(function(t){
                throw new Error('سرور پاسخ JSON نداد (HTTP '+r.status+'): '+t.slice(0,120));
            });
        }
        return r.json();
    });
}
function bcLoad(){
  const box=$('bcBox'); if(box)box.innerHTML='<div style="color:#93c5fd">⏳ در حال خواندن…</div>';
  safeFetchJson('?bsl_catalog=1').then(d=>{
    if(!d.ok){if(box)box.innerHTML='<div style="color:#f87171">✗ '+esc(d.error||'خطا')+'</div>';return;}
    bcRender(d);
  }).catch(()=>{if(box)box.innerHTML='<div style="color:#f87171">✗ خطا در ارتباط</div>';});
}
function bcRebuild(){
  if(!confirm('فهرستِ همهٔ غرفه‌ها از نو گرفته شود؟\n\n'
     +'بسته به تعدادِ محصولات ممکن است یکی‌دو دقیقه طول بکشد. '
     +'در این مدت صفحه را نبندید.'))return;
  const box=$('bcBox');
  if(box)box.innerHTML='<div style="color:#93c5fd">🏗 در حال گرفتنِ فهرستِ غرفه‌ها… (چند دقیقه)</div>';
  safeFetchJson('?bsl_catalog=1&rebuild=1').then(d=>{
    if(!d.ok){if(box)box.innerHTML='<div style="color:#f87171">✗ '+esc(d.error||'خطا')+'</div>';return;}
    bcRender(d);
    showToast('✓ کشِ کاتالوگ بازسازی شد');
  }).catch(()=>{if(box)box.innerHTML='<div style="color:#f87171">✗ خطا یا مهلت تمام شد — «وضعیت» را بزنید</div>';});
}
function bcClear(){
  if(!confirm('کشِ کاتالوگ پاک شود؟ دفعهٔ بعد از نو ساخته می‌شود (کندتر، ولی بی‌خطر).'))return;
  safeFetchJson('?bsl_catalog=1&clear=1').then(()=>{
    const box=$('bcBox'); if(box)box.innerHTML='<div style="color:#4ade80">✓ پاک شد</div>';
  }).catch(()=>showToast('✗ خطا شبکه',1));
