// v10.87: flush DOM → bslExtraVendors[] before save (prevents price-reset)
function bslFlushVendors(){
    (bslExtraVendors||[]).forEach((v,i)=>{
        const sel=$('bslVPMode_'+i), inp=$('bslVPV_'+i);
        if(sel) v.price_mode=sel.value||'none';
