// v10.87 / v10.440: ارسال مجدد همه محصولات فقط به یک غرفه (با تطبیق دقیق شناسهٔ غرفه)
function bslResendShop(idx){
    const v=bslExtraVendors[idx]; if(!v)return;
    const shopName=v.shop_name||v.name||('غرفه '+(idx+1));
    if(!confirm('آیا می‌خواهید همهٔ محصولات را دوباره به غرفه ' + shopName + ' ارسال کنید؟'))return;
    bslFlushVendors();
    Promise.resolve(saveConn()).finally(()=>{
        const fd=new FormData();
        fd.append('action','resend_shop_bsl');
        fd.append('vendor_idx',String(idx));
        fd.append('vendor_id',String(parseInt(v.vendor_id)||0));
        fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(j=>{
            const msg=j.queued?('✅ '+toFa(j.queued)+' ردیف ارسال در صف شد'):('⚠️ خطا: '+(j.error||''));
            alert(msg);
            if(j.queued>0)openTab('tabSend');
        }).catch(e=>alert('⚠️ '+e));
    });
}
// v9.68: محاسبهٔ قیمتِ نمونه/درصدِ مؤثر «دولایه» برای یک غرفه (معادل سمت سرور).
// لایهٔ ۱ = تعدیلِ خودِ پروفایل، لایهٔ ۲ = تعدیلِ این غرفه. eff_pct نسبت به پایهٔ خام است.
function bslCombinedPreview(base,profMode,profVal,shopMode,shopVal){
    base=parseInt(base)||0; profVal=parseFloat(profVal)||0; shopVal=parseFloat(shopVal)||0;
    if(base<=0)return{price:0,pct:0,profPct:0,shopPct:0};
    // v9.71: جمعِ ساده — درصدِ پروفایل + درصدِ این غرفه (مثل ۳۰+۵=۳۵)
    let ppct=0;
    if(profMode==='percent'){ppct=profVal;}
    else if(profMode==='multiplier'){ppct=profVal>0?Math.round((profVal-1)*100*10)/10:0;}
    let spct=0;
    if(shopMode==='percent'){spct=shopVal;}
    else if(shopMode==='multiplier'){spct=shopVal>0?Math.round((shopVal-1)*100*10)/10:0;}
    const eff=Math.round((ppct+spct)*10)/10;
    let out=base*(1+eff/100);
    out=Math.round(out); if(out<=0)out=base;
    return{price:out,pct:eff,profPct:Math.round(ppct*10)/10,shopPct:Math.round(spct*10)/10};
}
/* v10.440: معادل دقیق سمت سرور (bslShopPriceFor + bslShopPriceForProfile):
   لایهٔ ۱: پروفایل (همراه با گردکردن پروفایل) → قیمت پروفایل
   لایهٔ ۲: ضریب تعدیل کلی باسلام (روی همهٔ غرفه‌ها، پیش‌فرض و غیرپیش‌فرض)
   لایهٔ ۳: ضریب اختصاصی همان غرفهٔ غیرپیش‌فرض + گردکردن باسلام */
function bslShopFinalPrice(profilePrice,gMode,gVal,vMode,vVal,round){
    profilePrice=parseInt(profilePrice)||0;
    if(!(profilePrice>0))return 0;
    gMode=String(gMode||'none'); gVal=parseFloat(gVal)||0;
    vMode=String(vMode||'none'); vVal=parseFloat(vVal)||0;
    round=parseInt(round)||0;
    const gpct=gMode==='percent'?gVal:(gMode==='multiplier'&&gVal>0?(gVal-1)*100:0);
    const vpct=vMode==='percent'?vVal:(vMode==='multiplier'&&vVal>0?(vVal-1)*100:0);
    const spct=gpct+vpct;
    if(vMode==='none')return destAdjustPreviewNum(profilePrice,gMode,gVal,round);
    if(gMode==='none')return destAdjustPreviewNum(profilePrice,vMode,vVal,round);
    let out=Math.round(profilePrice*(1+(spct/100)));
    if(round>0)out=Math.round(out/round)*round;
    return out>0?out:profilePrice;
}
function bslShopThreeLayerPreview(raw,profMode,profVal,profRound,gMode,gVal,gRound,vMode,vVal){
    raw=parseInt(raw)||0; profVal=parseFloat(profVal)||0; profRound=parseInt(profRound)||0;
    gMode=String(gMode||'none'); gVal=parseFloat(gVal)||0; gRound=parseInt(gRound)||0;
    vMode=String(vMode||'none'); vVal=parseFloat(vVal)||0;
    if(!(raw>0))return{price:0,profilePrice:0,pct:0,profPct:0,globalPct:0,shopPct:0,destPct:0};
    let profPrice=raw;
    if(profMode==='percent')profPrice=raw*(1+(profVal/100));
    else if(profMode==='multiplier'&&profVal>0)profPrice=raw*profVal;
    profPrice=Math.round(profPrice);
    if(profRound>0)profPrice=Math.round(profPrice/profRound)*profRound;
    if(!(profPrice>0))profPrice=raw;
    const ppct=profMode==='percent'?profVal:(profMode==='multiplier'&&profVal>0?(profVal-1)*100:0);
    const gpct=gMode==='percent'?gVal:(gMode==='multiplier'&&gVal>0?(gVal-1)*100:0);
    const vpct=vMode==='percent'?vVal:(vMode==='multiplier'&&vVal>0?(vVal-1)*100:0);
    const finalP=bslShopFinalPrice(profPrice,gMode,gVal,vMode,vVal,gRound);
    const effPct=Math.round(((finalP-raw)/raw)*1000)/10;
    return{price:finalP,profilePrice:profPrice,pct:effPct,profPct:Math.round(ppct*10)/10,globalPct:Math.round(gpct*10)/10,shopPct:Math.round(vpct*10)/10,destPct:Math.round((gpct+vpct)*10)/10};
}
// v8.17: Per-profile BaSalam category dropdown
let bslProfileSelectedCatId=0;
/* v10.393: fixed positioning escapes settings-card/smenu overflow and z-index contexts. */
function bslPlaceCategoryPopup(input,list){if(!input||!list)return;/* portal to body also escapes transformed settings-panel ancestors */if(list.parentElement!==document.body)document.body.appendChild(list);const r=input.getBoundingClientRect();const below=Math.max(100,window.innerHeight-r.bottom-12),above=Math.max(100,r.top-12);const useAbove=below<170&&above>below;list.style.position='fixed';list.style.left=Math.max(8,r.left)+'px';list.style.width=Math.max(220,r.width)+'px';list.style.right='auto';list.style.top=useAbove?'auto':(r.bottom+2)+'px';list.style.bottom=useAbove?(window.innerHeight-r.top+2)+'px':'auto';list.style.maxHeight=Math.min(300,useAbove?above:below)+'px';list.style.zIndex='2147483647';}
/* One source of truth in the browser: profile settings and Send always mirror. */
function syncBslCategoryPair(catId,origin,persist){catId=parseInt(catId)||0;const c=(bslAllCats||[]).find(x=>x.id===catId);const name=c?c.name:'';bslProfileSelectedCatId=catId;if($('bslProfileCatId'))$('bslProfileCatId').value=String(catId);if($('bslProfileCatSearch'))$('bslProfileCatSearch').value=catId?(name||('#'+catId)):'';bslSelectedCatId=catId;bslSelectedCatName=name;if($('bsCat'))$('bsCat').value=String(catId);if($('bsCatSearch'))$('bsCatSearch').value=catId?(name?(name+' ('+catId+')'):('#'+catId)):'';if(persist!==false&&typeof scheduleSave==='function')scheduleSave();}
function renderBslProfileCatDropdown(cats,selectedId){const si=$('bslProfileCatSearch');const list=$('bslProfileCatList');if(!si||!list)return;/* v8.43: اگر بدون شناسه صدا زده شود (مثلاً دکمهٔ 🔄)، انتخاب فعلی نباید پاک شود */if(selectedId===undefined||selectedId===null)selectedId=bslProfileSelectedCatId||parseInt($('bslProfileCatId').value)||0;syncBslCategoryPair(selectedId,'load',false);si.onfocus=function(){bslPlaceCategoryPopup(si,list);list.style.display='block';};si.onblur=function(){setTimeout(()=>{list.style.display='none';},200);};si.oninput=function(){bslPlaceCategoryPopup(si,list);list.style.display='block';const q=si.value.toLowerCase().trim();renderBslProfileCatList(cats,q);};renderBslProfileCatList(cats,'');}
function renderBslProfileCatList(cats,q){const list=$('bslProfileCatList');if(!list)return;list.innerHTML='';cats.filter(c=>!q||c.name.toLowerCase().includes(q)).slice(0,100).forEach(c=>{const d=document.createElement('div');d.style.cssText='padding:6px 10px;cursor:pointer;font-size:12px;color:#e2e8f0;border-bottom:1px solid #334155;background:#1e293b';d.textContent=c.name+' ('+c.id+')';d.onmousedown=function(e){e.preventDefault();syncBslCategoryPair(c.id,'profile',true);list.style.display='none';};list.appendChild(d);});}
