(function(){
    /* v9.91: اول هشِ آدرس (اگر کاربر لینکِ مستقیم باز کرده)، وگرنه آخرین
       تبی که در همین مرورگر باز بود. قبلاً فقط هش خوانده می‌شد و چون در
       بازِ کردنِ ساده هشی وجود ندارد، همیشه «شروع» می‌آمد. */
    const hash = window.location.hash.replace('#','');
    const want = MAIN_TABS.includes(hash) ? hash : lastMainTab();
    /* v10.31 (۴۴): نمای نتایج را از حافظه برگردان — ولی هرگز روی «کارت»،
       چون رفرش باید سبک بماند. rvSavedView خودش کارت را به جدول می‌برد. */
    if (typeof switchView === 'function') {
        setTimeout(() => switchView(rvSavedView()), 20);
    }
    if (want) {
        setTimeout(() => switchMainTab(want), 50);
    }
})();

function extractNumber(str) {
    if (!str) return 0;
    let en = toEn(str);
    en = en.replace(/[^0-9]/g, '');
    return parseInt(en, 10) || 0;
}

function getOriginalPrice(str) {
    const base = extractNumber(str);
    if (base === 0) return '0';
    return base.toLocaleString('en-US');
}

function getFinalPriceNum(str) {
    let base = extractNumber(str);
    if (base === 0) return 0;

    let mode = $('priceMode') ? $('priceMode').value : 'none';
    let val = parseFloat($('priceVal') ? $('priceVal').value : 0) || 0;

    let finalNum = base;
    if (mode === 'percent') {
        finalNum = base * (1 + (val / 100));
    } else if (mode === 'multiplier') {
        finalNum = base * val;
    }

    finalNum = Math.round(finalNum);

    const roundMode = $('roundPrice') ? $('roundPrice').value : '0';
    if (roundMode !== '0') {
        const factor = parseInt(roundMode, 10);
        if (factor > 0) {
            finalNum = Math.round(finalNum / factor) * factor;
        }
    }

    return finalNum;
}

function getFinalPrice(str) {
    const num = getFinalPriceNum(str);
    return num === 0 ? '0' : num.toLocaleString('en-US');
}

function getFinalTitle(title) {
    let suffix = $('titleSuffix') ? $('titleSuffix').value.trim() : '';
    return (title || '') + (suffix ? ' ' + suffix : '');
}

function isCustomColEnabled() {
    return $('useCustomCol') && $('useCustomCol').checked;
}

function getCustomColName() {
    return $('customColName') ? ($('customColName').value.trim() || 'Custom') : 'Custom';
}

function getCustomColVal() {
    return $('customColVal') ? $('customColVal').value : '';
}

function getMinPrice() {
    return parseInt($('minPrice') ? $('minPrice').value : 10000) || 10000;
}

function stripHtml(html) {
    if (!html) return '';
    const tmp = document.createElement('div');
    tmp.innerHTML = html;
    return (tmp.textContent || tmp.innerText || '').trim();
}

function shortText(s, len=80) {
    if (!s) return '';
    return s.length > len ? s.substring(0, len) + '...' : s;
}

function getEnabledDetailFields() {
    return DETAIL_FIELDS.filter(f => detailSel[f.key] && detailSel[f.key].enabled && detailSel[f.key].selector);
}

/* v10.15: ستون‌های جزئیات برای جدول/خروجی — بدونِ «قیمت».
   قیمتِ جزئیات فیلدِ تازه‌ای نمی‌سازد؛ همان p.price را دقیق‌تر می‌کند و
   جدول از قبل «قیمت اولیه/قیمت نهایی» را از همان p.price می‌سازد. اگر
   این‌جا فیلتر نشود، کاربر یک ستونِ «قیمت» سومِ تکراری کنارِ آن دو می‌بیند
   و در CSV/اکسل هم یک ستونِ اضافه ظاهر می‌شود. استخراج و صف‌بندی همچنان
   از getEnabledDetailFields استفاده می‌کنند، فقط نمایش/خروجی فرق دارد. */
function getDetailColumns() {
    return getEnabledDetailFields().filter(f => f.key !== 'price');
}

/* =====================================================================
 *  v10.29 (۴۲): ورودِ دستیِ سلکتورهای «جزئیات»
 *
 *  زیرتبِ «لیست» از v7.81 تیکِ «✏️ وارد کردن دستی سلکتور» داشت، ولی
 *  زیرتبِ «📄 استخراج جزئیات محصولات» نداشت. آن‌جا ورودی‌ها ظاهراً باز
 *  بودند اما عملاً تایپ‌کردنی نبودند، چون updateDetailSelector روی هر
 *  کاراکتر کلِ فهرست را innerHTML می‌کرد: ورودی دور ریخته می‌شد، تمرکز
 *  می‌پرید و مکان‌نما به آخرِ خط برمی‌گشت. نتیجه این بود که تنها راهِ
 *  پرکردنِ این فیلدها کلیک روی صفحهٔ نمونه بود؛ و اگر صفحهٔ نمونه در
 *  iframe باز نمی‌شد (X-Frame-Options، جاوااسکریپتِ سنگین، لاگین)،
 *  کاربر هیچ راهی نداشت.
 *
 *  حالا: تیک ورودی‌ها را از readonly درمی‌آورد، تایپ بدونِ بازسازیِ
 *  DOM ذخیره می‌شود، و کنارِ هر فیلد یک «👁 تست» هست که همان اندپوینتِ
 *  ?test_selector را روی صفحهٔ نمونهٔ محصول می‌زند.
 * ===================================================================== */

/** آیا حالتِ دستیِ جزئیات روشن است؟ */
function dmanOn() {
    const c = $('manualDetailSelMode');
    return !!(c && c.checked);
}

/** تیکِ حالتِ دستی — قرینهٔ toggleManualSelMode()ِ زیرتبِ لیست */
function toggleManualDetailSelMode() {
    try { localStorage.setItem('manualDetailSelMode', dmanOn() ? '1' : '0'); } catch (e) {}
    renderDetailFieldsList();
    if (dmanOn()) showToast('✏️ حالت دستی جزئیات فعال — سلکتورها را مستقیم تایپ کنید');
}

/** v10.29 (۴۲): وضعیتِ تیک بعد از رفرش برمی‌گردد — مثل زیرتبِ فعال
    (selSubRestore). کسی که سایتش در iframe باز نمی‌شود هر بار مجبور
    نباشد دوباره تیک بزند. */
function manualDetailSelRestore() {
    const c = $('manualDetailSelMode');
    if (!c) return;
    let v = '0';
    try { v = localStorage.getItem('manualDetailSelMode') || '0'; } catch (e) {}
    if (v === '1') { c.checked = true; renderDetailFieldsList(); }
}

/** v10.29 (۴۲): روشن کردنِ حالتِ دستی از بیرون (وقتی صفحهٔ نمونه باز نشد) */
function manualDetailSelOn() {
    const c = $('manualDetailSelMode');
    if (!c || c.checked) return;
    c.checked = true;
    toggleManualDetailSelMode();
}

/* هر فیلد تایمرِ دیبانسِ خودش را دارد؛ مثل testTimersِ زیرتبِ لیست */
let dTestTimers = {};

function renderDetailFieldsList() {
    // v8.77: نوار نمونه هم همین‌جا تازه شود تا قبل از باز کردن پیش‌نمایش
    // هم معلوم باشد کدام محصول نمونه است
    try { renderSampleBar(); } catch (e) {}
    const container = $('detailFieldsList');
    if (!container) return;
    const manual = dmanOn();
    let html = '';
    DETAIL_FIELDS.forEach(f => {
        const cfg = detailSel[f.key] || {enabled:false, selector:''};
        html += `
            <div class="detail-field ${cfg.enabled ? 'enabled' : ''} ${manual ? 'dman' : ''}" data-f="${f.key}">
                <div class="detail-field-row">
                    <span class="fname">${f.icon} ${f.label}</span>
                    <label class="switch ftoggle">
                        <input type="checkbox" ${cfg.enabled ? 'checked' : ''} onchange="toggleDetailField('${f.key}', this.checked)">
                        <span class="slider"></span>
                    </label>
                    <input class="fselector" id="dsel-${f.key}" type="text" ${manual ? '' : 'readonly'}
                           value="${esc(cfg.selector||'')}"
                           placeholder="${manual ? 'سلکتور CSS را تایپ کنید…' : 'با کلیک روی صفحهٔ نمونه پر می‌شود'}"
                           oninput="updateDetailSelector('${f.key}', this.value)">
                    ${manual ? `<button class="btn btn-indigo ftest" onclick="testDetailSel('${f.key}')" title="سلکتور را روی صفحهٔ نمونهٔ محصول بسنج">👁 تست</button>` : ''}
                </div>
                ${manual ? `<div class="dtest wait" id="dprev-${f.key}">در انتظار تست…</div>` : ''}
            </div>
        `;
    });
    container.innerHTML = html;
}

function toggleDetailField(key, enabled) {
    if (!detailSel[key]) detailSel[key] = {enabled:false, selector:''};
    detailSel[key].enabled = enabled;
    renderDetailFieldsList();
    refreshViews();
    scheduleSave();
}

/* v10.29 (۴۲): دیگر موقعِ تایپ کلِ فهرست بازسازی نمی‌شود.
   فقط وضعیتِ همان کارت (کلاسِ enabled و تیکِ کنارش) دستی به‌روز می‌شود،
   تا مکان‌نما سرِ جایش بماند و بشود سلکتورِ بلند را تا آخر تایپ کرد. */
function updateDetailSelector(key, val) {
    if (!detailSel[key]) detailSel[key] = {enabled:false, selector:''};
    const had = detailSel[key].enabled;
    detailSel[key].selector = val.trim();
    if (val.trim()) detailSel[key].enabled = true;

    const card = document.querySelector('.detail-field[data-f="' + key + '"]');
    if (card) {
        card.classList.toggle('enabled', !!detailSel[key].enabled);
        const cb = card.querySelector('.ftoggle input');
        if (cb) cb.checked = !!detailSel[key].enabled;
    } else {
        renderDetailFieldsList();
    }
    // اگر فیلدی تازه فعال شد، ستون‌های خروجی عوض می‌شوند
    if (!had && detailSel[key].enabled) refreshViews();
    scheduleSave();
}

/** v10.29 (۴۲): سنجشِ یک سلکتورِ جزئیات روی صفحهٔ نمونهٔ محصول.
    از همان اندپوینتِ ?test_selector استفاده می‌کند که زیرتبِ لیست هم
    می‌زند، فقط URLش صفحهٔ محصول است نه صفحهٔ فهرست. */
function testDetailSel(key) {
    const out = $('dprev-' + key);
    const inp = $('dsel-' + key);
    if (!out || !inp) return;
    const selector = (inp.value || '').trim();
    if (!selector) { out.className = 'dtest bad'; out.textContent = '❌ اول سلکتور را بنویسید'; return; }

    const url = detailSampleUrl();
    if (!url) { out.className = 'dtest bad'; out.textContent = '❌ صفحهٔ نمونه‌ای نیست — اول فهرست را استخراج کنید'; return; }

    out.className = 'dtest wait';
    out.textContent = '⏳ در حال تست روی صفحهٔ نمونه…';

    if (dTestTimers[key]) clearTimeout(dTestTimers[key]);
    dTestTimers[key] = setTimeout(() => {
        // image و price در بک‌اند شاخهٔ اختصاصی دارند؛ بقیه متنِ گره‌اند
        const t = (key === 'image') ? 'image' : (key === 'price' ? 'price' : 'text');
        const params = new URLSearchParams({test_selector: url, type: t, selector: selector});
        fetch('?' + params.toString())
            .then(r => r.json())
            .then(d => {
                if (!d.ok) { out.className = 'dtest bad'; out.textContent = '❌ ' + (d.error || 'خطا'); return; }
                const many = d.count > 1 ? ' (' + toFa(d.count) + ' مورد)' : '';
                const v = (d.value || '').trim();
                if (!v) { out.className = 'dtest bad'; out.textContent = '⚠️ پیدا شد ولی خالی بود' + many; return; }
                out.className = 'dtest';
                out.textContent = '✓ ' + (v.length > 180 ? v.slice(0, 180) + '…' : v) + many;
            })
            .catch(() => { out.className = 'dtest bad'; out.textContent = '❌ خطا در ارتباط'; });
    }, 300);
}

/* =====================================================================
 *  v8.64: گالری چندعکسی — رابط کاربری
 * ===================================================================== */

/** تنظیمات گالری را از فرم می‌خواند */
function galCollect() {
    const g = id => $(id) || {};
    const editMode = (g('galImgEditMode').value === 'crop') ? 'crop' : 'white_square';
    const cornerRaw = (g('galSquareCorner').value || 'bottom_right');
    const corner = ['bottom_right', 'bottom_left', 'top_right', 'top_left'].includes(cornerRaw) ? cornerRaw : 'bottom_right';
    return {
        mode:            (g('galMode').value || 'off'),
        box:             (g('galBox').value || '').trim(),
        selectors:       (g('galSelectors').value || '').trim(),
        pattern:         (g('galPattern').value || '').trim(),
        from:            parseInt(g('galFrom').value || '1') || 1,
        to:              parseInt(g('galTo').value || '10') || 10,
        max:             parseInt(g('galMax').value || '10') || 10,
        skip_first:      !!g('galSkipFirst').checked,
        edit_mode:       editMode,
        square_corner:   corner,
        square_pct:      Math.max(0, Math.min(48, parseInt(g('galSquarePct').value || '0') || 0)),
        square_px:       Math.max(0, Math.min(600, parseInt(g('galSquarePx').value || '0') || 0)),
        crop_bottom_pct: Math.max(0, Math.min(45, parseInt(g('galCropBottomPct').value || '0') || 0)),
        crop_bottom_px:  Math.max(0, Math.min(600, parseInt(g('galCropBottomPx').value || '0') || 0))
    };
}

function s4InferImgEditModeJs(cfg) {
    cfg = cfg || {};
    if (cfg.edit_mode === 'crop' || cfg.edit_mode === 'white_square') return cfg.edit_mode;
    const cp = parseInt(cfg.crop_bottom_pct || 0) || 0;
    const cx = parseInt(cfg.crop_bottom_px || 0) || 0;
    const sp = parseInt(cfg.square_pct || 0) || 0;
    const sx = parseInt(cfg.square_px || 0) || 0;
    if ((cp > 0 || cx > 0) && sp <= 0 && sx <= 0) return 'crop';
    return 'white_square';
}

function s4CornerLabelFa(corner) {
    const map = {bottom_right: 'پایین راست', bottom_left: 'پایین چپ', top_right: 'بالا راست', top_left: 'بالا چپ'};
    return map[corner] || 'پایین راست';
}

function s4BuildImgEditPreviewQuery(cfg) {
    cfg = cfg || {};
    const m = (cfg.edit_mode === 'crop') ? 'crop' : 'white_square';
    if (m === 'crop') {
        return '&edit_mode=crop&crop_bottom_pct=' + (parseInt(cfg.crop_bottom_pct || 0) || 0)
            + '&crop_bottom_px=' + (parseInt(cfg.crop_bottom_px || 0) || 0);
    }
    return '&edit_mode=white_square&square_corner=' + encodeURIComponent(cfg.square_corner || 'bottom_right')
        + '&square_pct=' + (parseInt(cfg.square_pct || 0) || 0)
        + '&square_px=' + (parseInt(cfg.square_px || 0) || 0);
}

function s4RenderBeforeAfterPreview(box, sampleImg, cfg) {
    if (!box) return;
    if (!sampleImg) {
        box.innerHTML = '<div style="font-size:11px;color:#fbbf24">ابتدا یک‌بار «👁 تست» سلکتور عکس یا استخراج انجام دهید تا نمونه تصویر پیدا شود.</div>';
        return;
    }
    const ts = Date.now();
    const origSrc = '?image_proxy=' + encodeURIComponent(sampleImg) + '&no_crop=1&_t=' + ts;
    const editSrc = '?image_proxy=' + encodeURIComponent(sampleImg) + s4BuildImgEditPreviewQuery(cfg) + '&_t=' + ts;
    let afterLabel = '';
    if ((cfg.edit_mode || 'white_square') === 'crop') {
        const sz = (cfg.crop_bottom_px > 0) ? (cfg.crop_bottom_px + 'px') : (cfg.crop_bottom_pct + '%');
        afterLabel = 'پس از برش پایین (' + sz + ')';
    } else {
        const sz = (cfg.square_px > 0) ? (cfg.square_px + 'px') : (cfg.square_pct + '%');
        afterLabel = 'مربع سفید · ' + s4CornerLabelFa(cfg.square_corner) + ' (' + sz + ')';
    }
    box.innerHTML = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;background:#0f172a;padding:8px;border-radius:10px;border:1px solid #334155">'
        + '<div style="text-align:center"><div style="font-size:10px;color:#94a3b8;margin-bottom:4px">اصلی</div><img src="' + origSrc + '" style="max-width:100%;max-height:170px;object-fit:contain;background:#cbd5e1;border-radius:6px"></div>'
        + '<div style="text-align:center"><div style="font-size:10px;color:#4ade80;margin-bottom:4px">' + esc(afterLabel) + '</div><img src="' + editSrc + '" style="max-width:100%;max-height:170px;object-fit:contain;background:#cbd5e1;border-radius:6px"></div>'
        + '</div>';
}

function listImgEditCollect() {
    const g = id => $(id) || {};
    const editMode = (g('listImgEditMode').value === 'crop') ? 'crop' : 'white_square';
    const cornerRaw = (g('listImgSquareCorner').value || 'bottom_right');
    const corner = ['bottom_right', 'bottom_left', 'top_right', 'top_left'].includes(cornerRaw) ? cornerRaw : 'bottom_right';
    return {
        edit_mode:       editMode,
        square_corner:   corner,
        square_pct:      Math.max(0, Math.min(48, parseInt(g('listImgSquarePct').value || '0') || 0)),
        square_px:       Math.max(0, Math.min(600, parseInt(g('listImgSquarePx').value || '0') || 0)),
        crop_bottom_pct: Math.max(0, Math.min(45, parseInt(g('listImgCropBottomPct').value || '0') || 0)),
        crop_bottom_px:  Math.max(0, Math.min(600, parseInt(g('listImgCropBottomPx').value || '0') || 0))
    };
}

function listImgEditModeChanged(silent) {
    const m = (($('listImgEditMode') || {}).value === 'crop') ? 'crop' : 'white_square';
    if ($('listImgSquareBox')) $('listImgSquareBox').classList.toggle('hidden', m !== 'white_square');
    if ($('listImgCropBox'))   $('listImgCropBox').classList.toggle('hidden', m !== 'crop');
    if (!silent) listImgEditChanged();
}

function listImgEditChanged() { markDirty(); scheduleSave(); }

function listImgEditApply(cfg) {
    cfg = cfg || {};
    const set = (id, v) => { const e = $(id); if (e) e.value = v; };
    set('listImgEditMode', s4InferImgEditModeJs(cfg));
    set('listImgSquareCorner', ['bottom_right', 'bottom_left', 'top_right', 'top_left'].includes(cfg.square_corner) ? cfg.square_corner : 'bottom_right');
    set('listImgSquarePct', cfg.square_pct !== undefined ? cfg.square_pct : 0);
    set('listImgSquarePx', cfg.square_px !== undefined ? cfg.square_px : 0);
    set('listImgCropBottomPct', cfg.crop_bottom_pct !== undefined ? cfg.crop_bottom_pct : 0);
    set('listImgCropBottomPx', cfg.crop_bottom_px !== undefined ? cfg.crop_bottom_px : 0);
    if ($('listImgEditPreview')) $('listImgEditPreview').innerHTML = '';
    listImgEditModeChanged(true);
}

function previewListImageEdit() {
    const box = $('listImgEditPreview');
    if (!box) return;
    let sampleImg = (window._lastListTestedImageUrl && /^https?:\/\//i.test(window._lastListTestedImageUrl)) ? window._lastListTestedImageUrl : '';
    if (!sampleImg) {
        for (const [, p] of products) {
            if (p && p.image && /^https?:\/\//i.test(p.image)) { sampleImg = p.image; break; }
        }
    }
    s4RenderBeforeAfterPreview(box, sampleImg, listImgEditCollect());
}

/** تنظیمات ذخیره‌شده را در فرم می‌نشاند */
function galApply(cfg) {
    cfg = cfg || {};
    const set = (id, v) => { const e = $(id); if (e) e.value = v; };
    let effMode = cfg.mode || 'off';
    const curUrl = (($('targetUrl') || {}).value || '').trim();
    if (effMode === 'off' && /snappshop\.ir/i.test(curUrl)) {
        if (String(cfg.box || '').trim() !== '') effMode = 'auto';
        else if (String(cfg.selectors || '').trim() !== '') effMode = 'manual';
        else if (String(cfg.pattern || '').includes('{n}')) effMode = 'number';
    }
    set('galMode', effMode);
    set('galBox', cfg.box || '');
    set('galSelectors', cfg.selectors || '');
    set('galPattern', cfg.pattern || '');
    set('galFrom', cfg.from !== undefined ? cfg.from : 1);
    set('galTo', cfg.to !== undefined ? cfg.to : 10);
    set('galMax', cfg.max !== undefined ? cfg.max : 10);
    set('galImgEditMode', s4InferImgEditModeJs(cfg));
    set('galSquareCorner', ['bottom_right', 'bottom_left', 'top_right', 'top_left'].includes(cfg.square_corner) ? cfg.square_corner : 'bottom_right');
    set('galSquarePct', cfg.square_pct !== undefined ? cfg.square_pct : 0);
    set('galSquarePx', cfg.square_px !== undefined ? cfg.square_px : 0);
    set('galCropBottomPct', cfg.crop_bottom_pct !== undefined ? cfg.crop_bottom_pct : 0);
    set('galCropBottomPx', cfg.crop_bottom_px !== undefined ? cfg.crop_bottom_px : 0);
    if ($('galSkipFirst')) $('galSkipFirst').checked = !!cfg.skip_first;
    if ($('galCropPreview')) $('galCropPreview').innerHTML = '';
    galImgEditModeChanged(true);
    galModeChanged(true);
}

function galImgEditModeChanged(silent) {
    const m = (($('galImgEditMode') || {}).value === 'crop') ? 'crop' : 'white_square';
    if ($('galSquareBox')) $('galSquareBox').classList.toggle('hidden', m !== 'white_square');
    if ($('galCropBox'))   $('galCropBox').classList.toggle('hidden', m !== 'crop');
    if (!silent) galChanged();
}

function previewImageBottomCrop() {
    const box = $('galCropPreview');
    if (!box) return;
    let sampleImg = (window._lastGalleryTestedImageUrl && /^https?:\/\//i.test(window._lastGalleryTestedImageUrl)) ? window._lastGalleryTestedImageUrl : '';
    if (!sampleImg) {
        for (const [, p] of products) {
            if (p && Array.isArray(p.images) && p.images.length > 1 && /^https?:\/\//i.test(p.images[1])) { sampleImg = p.images[1]; break; }
            if (p && Array.isArray(p.images) && p.images.length > 0 && /^https?:\/\//i.test(p.images[0])) { sampleImg = p.images[0]; break; }
            if (p && p.image && /^https?:\/\//i.test(p.image)) { sampleImg = p.image; break; }
        }
    }
    s4RenderBeforeAfterPreview(box, sampleImg, galCollect());
}

/** با تغییر روش، فقط جعبهٔ همان روش نشان داده می‌شود */
function galModeChanged(silent) {
    const m = ($('galMode') || {}).value || 'off';
    const show = (id, on) => { const e = $(id); if (e) e.classList.toggle('hidden', !on); };
    show('galAutoBox',   m === 'auto');
    show('galManualBox', m === 'manual');
    show('galNumberBox', m === 'number');
    show('galCommon',    m !== 'off');
    if (!silent) galChanged();
}

function galChanged() { markDirty(); scheduleSave(); if (typeof rvRebuildVisible === 'function') rvRebuildVisible(); }

/** آدرس یک محصول نمونه از نتایج فعلی */
function galSampleUrl() { return detailSampleUrl(); }

/** پیشنهاد سلکتور «باکس عکس‌ها» از روی یک صفحهٔ محصول واقعی */
function gallerySuggest() {
    const url = galSampleUrl();
    const box = $('galSuggest');
    if (!url) return;
    if (box) box.innerHTML = '<div style="color:#93c5fd;font-size:11px;padding:4px 0">⏳ بررسی صفحهٔ محصول...</div>';
    fetch('?gallery_suggest=' + encodeURIComponent(url))
        .then(r => r.json())
        .then(d => {
            if (!box) return;
            if (!d.ok) { box.innerHTML = '<div style="color:#fca5a5;font-size:11px">✗ ' + esc(d.error || 'خطا') + '</div>'; return; }
            const rows = d.suggestions || [];
            if (!rows.length) {
                box.innerHTML = '<div style="color:#fbbf24;font-size:11px;line-height:1.8">'
                    + 'گالری شناخته‌شده‌ای پیدا نشد. با «باز کردن نمونه» ظرف عکس‌ها را دستی انتخاب کنید '
                    + 'یا از روش سلکتور دستی استفاده کنید.</div>';
                return;
            }
            let h = '<div style="font-size:10.5px;color:#94a3b8;margin:6px 0">روی هرکدام بزنید تا انتخاب شود:</div>';
            rows.forEach(s => {
                h += '<div class="suggest-item" onclick="galPick(\'' + esc(s.selector).replace(/'/g, "\\'") + '\')" '
                   + 'style="display:flex;justify-content:space-between;gap:8px;align-items:center;direction:ltr">'
                   + '<span style="color:#f9a8d4">' + esc(s.selector) + '</span>'
                   + '<span style="color:#86efac;flex:0 0 auto">' + toFa(s.count) + ' عکس</span></div>';
            });
            box.innerHTML = '<div class="suggest-list">' + h + '</div>';
        })
        .catch(e => { if (box) box.innerHTML = '<div style="color:#f87171;font-size:11px">✗ ' + esc(e.message) + '</div>'; });
}

function galPick(sel) {
    if ($('galMode') && $('galMode').value === 'off') {
        $('galMode').value = 'auto';
        galModeChanged(true);
    }
    if ($('galBox')) $('galBox').value = sel;
    const b = $('galSuggest'); if (b) b.innerHTML = '';
    galChanged();
    showToast('✓ باکس انتخاب شد — حالا آزمایش کنید');
}

/** آزمایش تنظیمات فعلی روی یک صفحهٔ محصول واقعی */
function galleryTest() {
    const url = galSampleUrl();
    const box = $('galTestR');
    if (!url) return;
    const cfg = galCollect();
    if (cfg.mode === 'off') { showToast('اول یک روش انتخاب کنید', true); return; }
    if (box) box.innerHTML = '<div style="color:#93c5fd;font-size:11px">⏳ آزمایش روی: ' + esc(url.substring(0, 60)) + '</div>';
    fetch('?gallery_test=' + encodeURIComponent(url) + '&gallery=' + encodeURIComponent(JSON.stringify(cfg)))
        .then(r => r.json())
        .then(d => {
            if (!box) return;
            if (!d.ok) { box.innerHTML = '<div style="color:#fca5a5;font-size:11px;background:#7f1d1d20;padding:6px 8px;border-radius:6px">✗ ' + esc(d.error || 'خطا') + '</div>'; return; }
            let h = '<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px">';
            h += '<div style="color:' + (d.count > 0 ? '#4ade80' : '#fbbf24') + ';font-weight:700;margin-bottom:4px">'
               + (d.count > 0 ? '✅ ' + toFa(d.count) + ' عکس پیدا شد' : '⚠️ هیچ عکسی پیدا نشد') + '</div>';
            h += '<div style="color:#94a3b8;font-size:10px;margin-bottom:6px">' + esc(d.note || '') + '</div>';
            if (d.images && d.images.length) {
                window._lastGalleryTestedImageUrl = d.images[0];
                const editQs = s4BuildImgEditPreviewQuery(cfg);
                h += '<div style="display:flex;gap:5px;flex-wrap:wrap">';
                d.images.slice(0, 12).forEach((u, i) => {
                    h += '<div style="position:relative"><img src="?image_proxy=' + encodeURIComponent(u) + editQs + '" '
                       + 'style="width:62px;height:62px;object-fit:cover;border-radius:6px;border:1px solid '
                       + (i === 0 ? '#22c55e' : '#334155') + '" title="' + esc(u) + '">'
                       + '<span style="position:absolute;bottom:1px;right:2px;background:#000a;color:#fff;font-size:9px;padding:0 3px;border-radius:3px">'
                       + toFa(i + 1) + '</span></div>';
                });
                h += '</div>';
                if (d.count > 12) h += '<div style="color:#64748b;font-size:10px;margin-top:4px">و ' + toFa(d.count - 12) + ' عکس دیگر</div>';
                h += '<div style="color:#86efac;font-size:10px;margin-top:5px">🟢 قاب سبز = عکس شاخص محصول</div>';
            }
            h += '</div>';
            box.innerHTML = h;
        })
        .catch(e => { if (box) box.innerHTML = '<div style="color:#f87171;font-size:11px">✗ ' + esc(e.message) + '</div>'; });
}

function clearDetailSel() {
    if (!confirm('پاک کردن همه سلکتورهای صفحه جزئیات؟')) return;
    DETAIL_FIELDS.forEach(f => detailSel[f.key] = {enabled:false, selector:''});
    renderDetailFieldsList();
    $('detailFrameWrap').classList.add('hidden');
    $('detailFrame').src = 'about:blank';
    refreshViews();
    scheduleSave();
}

/**
 * v8.66: یک نقطهٔ واحد برای پیدا کردن آدرس نمونه.
 * قبلاً سه جا همین حلقه تکرار شده بود و پیامشان هم گمراه‌کننده بود:
 * وقتی محصول بود ولی هیچ‌کدام «لینک» نداشتند، باز هم می‌گفت «استخراج کنید».
 */
/* v8.77: کدام محصول به‌عنوان نمونه باز شود.
   قبلاً همیشه «اولین محصولِ دارای لینک» بود. مشکلش این بود که آن یکی
   ممکن است اصلاً تنوع یا گالری نداشته باشد، و آن‌وقت نمی‌شد سلکتورِ
   تنوع/گالری را انتخاب کرد. حالا کاربر می‌تواند نمونه را عوض کند. */
let detailSampleKey = null;

/** فهرست محصولاتی که لینک دارند — برای انتخاب نمونه */
function detailSampleList() {
    const out = [];
    for (const k of order) {
        const p = products.get(k);
        if (p && p.link) out.push([k, p]);
    }
    // اگر order هنوز پر نشده، از خود نقشه بخوان
    if (!out.length) for (const [k, p] of products) if (p && p.link) out.push([k, p]);
    return out;
}

function detailSampleUrl(silent) {
    // اگر کاربر نمونه‌ای انتخاب کرده و هنوز معتبر است، همان
    if (detailSampleKey) {
        const p = products.get(detailSampleKey);
        if (p && p.link) return p.link;
        detailSampleKey = null;
    }
    const list = detailSampleList();
    if (list.length) return list[0][1].link;
    if (!silent) {
        if (products.size === 0) showToast('ابتدا محصولات را استخراج کنید', true);
        else showToast('هیچ محصولی لینک ندارد — سلکتور «🔗 لینک» را تنظیم و دوباره استخراج کنید', true);
    }
    return null;
}

/** برچسب نمونهٔ فعلی، برای نشان دادن در پنل */
function detailSampleLabel() {
    const list = detailSampleList();
    if (!list.length) return '';
    let idx = list.findIndex(([k]) => k === detailSampleKey);
    if (idx < 0) idx = 0;
    const p = list[idx][1];
    return (idx + 1) + '/' + list.length + ' — ' + String(p.title || p.link || '').substring(0, 45);
}

/** نمونهٔ بعدی/قبلی — برای وقتی این یکی تنوع یا گالری ندارد */
function detailSampleStep(step) {
    const list = detailSampleList();
    if (list.length < 2) { showToast('محصول دیگری با لینک وجود ندارد', true); return; }
    let idx = list.findIndex(([k]) => k === detailSampleKey);
    if (idx < 0) idx = 0;
    idx = ((idx + step) % list.length + list.length) % list.length;
    detailSampleKey = list[idx][0];
    renderSampleBar();
    openDetailProxy(true);
}

/* v8.77: «همین محصول را نمونه کن» از روی کارت نتایج.
   این همان چیزی است که نبودش آزار می‌داد: نمونه همیشه اولین محصول بود و
   اگر آن یکی تنوع یا گالری نداشت، راهی برای عوض کردنش نبود. */
function useAsDetailSample(k) {
    const p = products.get(k);
    if (!p || !p.link) { showToast('این محصول لینک ندارد', true); return; }
    detailSampleKey = k;
    showToast('🎯 نمونه عوض شد — ' + String(p.title || '').substring(0, 30));
    openDetailProxy();
}

/** نوار کوچک «نمونهٔ فعلی» بالای پیش‌نمایش جزئیات */
function renderSampleBar() {
    const b = $('detailSampleBar');
    if (!b) return;
    const list = detailSampleList();
    if (!list.length) { b.innerHTML = ''; return; }
    b.innerHTML = '<span style="color:#94a3b8">🎯 نمونه:</span> '
      + '<b style="color:#f9a8d4">' + esc(detailSampleLabel()) + '</b>'
      + ' <button class="btn btn-gray" onclick="detailSampleStep(-1)" style="font-size:10px;padding:2px 7px">قبلی</button>'
      + ' <button class="btn btn-gray" onclick="detailSampleStep(1)" style="font-size:10px;padding:2px 7px">بعدی ⏭</button>'
      + '<div style="color:#64748b;font-size:10px;margin-top:3px">اگر این محصول تنوع یا گالری ندارد، با «بعدی» یکی دیگر را باز کنید.</div>';
}

function openDetailProxy(keepScroll) {
    /* v8.77: اگر در پیش‌نمایش بالا روی یک محصول کلیک کرده‌اید، همان
       باز می‌شود. قبلاً همیشه اولین محصول فهرست باز می‌شد، حتی وقتی
       شما محصول دیگری را در نظر داشتید. */
    const sampleUrl = detailSampleUrl();
    if (!sampleUrl) return;
    renderSampleBar();
    $('detailFrameWrap').classList.remove('hidden');
    // v8.68: پنل کنترل بیرونی هم باز شود
    const pp = $('pickerPanel'); if (pp) pp.classList.remove('hidden');
    // v9.90: نوار تیک‌های نمایش هم با پنل باز می‌شود، بعد وضعیت ذخیره‌شده اعمال می‌شود
    const pcb = $('pkCtlBar'); if (pcb) pcb.classList.remove('hidden');
    try{ selCtlApply('pkPanel', !$('ctlPkPanel')||$('ctlPkPanel').checked);
         selCtlApply('pkHint',  !$('ctlPkHint') ||$('ctlPkHint').checked); }catch(_e){}
    // ارتفاع پیش‌فرض را به اندازهٔ پنجره بزرگ کن تا فضای کلیک کم نباشد
    setDetailIframeHeight(Math.max(500, window.innerHeight - 160));
    // v9.75: کلید پروفایلِ فعلی را بفرست تا اتصالِ صفحه مطابق «اتصال غیرمستقیم»ِ
    // همین پروفایل باشد (خاموش = مستقیم). پروفایلِ فعلی = انتخابِ منو یا URL.
    const _pk = profileKey(($('profileSelect')&&$('profileSelect').value)||($('url')&&$('url').value.trim())||'');
    $('detailFrame').src = '?detail_proxy=' + encodeURIComponent(sampleUrl) + '&pk=' + encodeURIComponent(_pk) + selectorWaitParam();
    $('detailStatus').textContent = '⏳ در حال باز کردن صفحهٔ نمونه...';
    switchMainTab('selectors');
    // v8.66: اگر پروکسی خطا بدهد، iframe سفید می‌ماند و کاربر نمی‌فهمد چه شد
    const fr = $('detailFrame');
    fr.onload = () => {
        $('detailStatus').textContent = '✓ نوع فیلد را از پنل بالا انتخاب کنید، بعد روی صفحه کلیک کنید';
        pkSetMode(($('pkMode') || {}).value || 'shortDesc');
    };
    /* v10.29 (۴۲): اگر صفحهٔ نمونه باز نشد، کاربر بن‌بست نمی‌ماند —
       حالتِ دستی خودکار روشن می‌شود تا سلکتورها را تایپ کند. همان
       رفتاری که loadDirect() از v7.81 برای زیرتبِ لیست دارد. */
    fr.onerror = () => {
        $('detailStatus').textContent = '✗ صفحهٔ نمونه باز نشد — حالتِ دستی روشن شد؛ سلکتورها را تایپ کنید';
        try { manualDetailSelOn(); } catch (_e) {}
    };
    // v8.77: موقع عوض کردن نمونه، صفحه را دوباره بالا نپران
    if (!keepScroll)
        setTimeout(() => { const p = $('pickerPanel') || $('detailFrameWrap');
                           softScrollIntoView(p, {behavior:'smooth',block:'start'}); }, 200);
}

function suggestDetailSelectors() {
    const sampleUrl = detailSampleUrl();
    if (!sampleUrl) return;
    $('detailStatus').textContent = 'در حال تحلیل صفحه جزئیات...';
    fetch('?suggest_detail_selectors=' + encodeURIComponent(sampleUrl))
        .then(r => r.json())
        .then(d => {
            if (!d.ok) {
                showToast('خطا: ' + d.error, true);
                return;
            }
            let applied = 0;
            for (const field of Object.keys(d.suggestions)) {
                if (d.suggestions[field].length > 0 && (!detailSel[field].selector || !detailSel[field].enabled)) {
                    detailSel[field].selector = d.suggestions[field][0].selector;
                    detailSel[field].enabled = true;
                    applied++;
                }
            }
            renderDetailFieldsList();
            refreshViews();
            scheduleSave();
            $('detailStatus').textContent = applied > 0 ? `✓ ${applied} فیلد تنظیم شد` : 'هیچ فیلد جدیدی یافت نشد';
            showToast(applied > 0 ? `✓ ${applied} فیلد شناسایی شد` : 'پیشنهادی یافت نشد');
        })
        .catch(() => showToast('خطا در ارتباط', true));
}

// Test selector - fetch sample value
function testSel(type) {
    const url = $('url').value.trim();
    const selector = sel[type];
    const prevEl = $('prev-' + type);

    if (!url) { showToast('URL وارد کنید', true); return; }
    if (!selector) { showToast('ابتدا سلکتور را انتخاب کنید', true); return; }

    prevEl.textContent = '⏳ در حال تست...';
    prevEl.className = prevEl.className.replace(/empty|__preview-\w+/g, '').trim();

    // Debounce
    if (testTimers[type]) clearTimeout(testTimers[type]);
    testTimers[type] = setTimeout(() => {
        const params = new URLSearchParams({
            test_selector: url,
            type: type,
            selector: selector
        });
        fetch('?' + params.toString())
            .then(r => r.json())
            .then(d => {
                if (!d.ok) {
                    prevEl.textContent = '❌ ' + (d.error || 'خطا');
                    prevEl.classList.add('empty');
                    return;
                }

                let display = d.value || '(خالی)';
                let extra = d.count > 1 ? ` (${toFa(d.count)} مورد یافت شد)` : '';

                if (type === 'container') {
                    display = `✓ ${toFa(d.count)} کانتینر مشابه یافت شد`;
                    prevEl.className = 'sel-preview' + (d.count >= 2 ? '' : ' empty');
                } else if (type === 'title') {
                    prevEl.className = 'sel-preview' + (d.value ? '' : ' empty');
                } else if (type === 'price') {
                    display = d.value ? d.value + ' تومان' : '(قیمت یافت نشد)';
                    prevEl.className = 'sel-preview price-prev' + (d.value ? '' : ' empty');
                } else if (type === 'link') {
                    display = d.value || '(لینک یافت نشد)';
                    prevEl.className = 'sel-preview link-prev' + (d.value ? '' : ' empty');
                } else if (type === 'image') {
                    if (d.value && /^https?:\/\//i.test(d.value)) window._lastListTestedImageUrl = d.value;
                    display = d.value || '(تصویر یافت نشد)';
                    prevEl.className = 'sel-preview img-prev' + (d.value ? '' : ' empty');
                }

                prevEl.textContent = display + extra;
            })
            .catch(e => {
                prevEl.textContent = '❌ خطا در ارتباط';
                prevEl.classList.add('empty');
            });
    }, 300);
}

function updatePagUI(){
    const t = $('pagType').value;
    const v = $('pagVal');
    const row = $('pagValRow');
    if(t === 'query_page') {
        row.style.display = 'none';
        v.value = '';
    } else {
        row.style.display = 'flex';
        if(t === 'query_custom') {
            v.placeholder = 'نام پارامتر (مثال: paged)';
            if(!v.value) v.value = 'paged';
        } else if(t === 'path_pattern') {
            v.placeholder = 'الگوی مسیر (/page/{page}/ یا ~page~{page})';
            if(!v.value) v.value = '/page/{page}/';
        } else if(t === 'full_pattern') {
            v.placeholder = 'الگوی کامل URL';
        } else if(t === 'next_selector') {
            v.placeholder = 'سلکتور CSS (a.next)';
            if(!v.value) v.value = 'a.next';
        }
    }
}
updatePagUI();

/* v10.177: آزمایش صفحه‌بندی — همان پیکربندیِ فعلیِ فرم را روی سرور با خودِ
   مسیرِ واقعیِ واکشی امتحان می‌کند و علتِ توقف را فارسی می‌گوید. */
function pagProbe(){
    const wrap=$('pagValRow');
    let box=$('pagProbeOut');
    if(!box){
        box=document.createElement('div');
        box.id='pagProbeOut';
        box.style.cssText='width:100%;font-size:12px;line-height:1.9;white-space:pre-wrap;word-break:break-all;background:var(--bg-2,var(--bg));border:1px solid var(--border);border-radius:8px;padding:8px;margin-top:6px;';
        wrap.appendChild(box);
    }
    const url=$('url').value.trim();
    if(!url){box.textContent='اول آدرس فروشگاه را وارد کنید.';return;}
    box.textContent='⏳ در حال آزمایش: صفحهٔ ۱ و صفحهٔ ۲ از خودِ سرور واکشی می‌شوند…';
    let sel='{}';
    try{ if(typeof collectProfileData==='function'){const d=collectProfileData(); if(d&&d.selectors)sel=JSON.stringify(d.selectors);} }catch(e){}
    fetch('?pag_probe=1'
        +'&url='+encodeURIComponent(url)
        +'&pagType='+encodeURIComponent($('pagType').value)
        +'&pagVal='+encodeURIComponent($('pagVal').value)
        +'&extractionEngine='+encodeURIComponent(s4EngineValue())
        +'&selectors='+encodeURIComponent(sel))
    .then(r=>r.json())
    .then(d=>{
        let t=(d.ok?'✓ ':'✗ ')+(d.diagnosis||'');
        t+='\n— موتور آزمون: '+(d.engine||s4EngineValue());
        t+='\n— نشانیِ ساخته‌شدهٔ صفحهٔ ۲: '+(d.built_url||'—');
        if(d.final_url) t+='\n— نشانیِ نهایی بعد از ریدایرکت: '+d.final_url;
        if(typeof d.new_in_page2!=='undefined') t+='\n— محصول تازه در صفحهٔ ۲: '+d.new_in_page2;
        if(d.title_page1||d.title_page2) t+='\n— عنوان سند: ص۱ «'+(d.title_page1||'?')+'» | ص۲ «'+(d.title_page2||'?')+'»';
        if(d.samples_page1&&d.samples_page1.length) t+='\n— نمونهٔ کارتِ ص۱: '+d.samples_page1.join(' ، ');
        if(d.samples_page2&&d.samples_page2.length) t+='\n— نمونهٔ کارتِ ص۲: '+d.samples_page2.join(' ، ');
        box.textContent=t;
        if(d.ok)showToast('✓ الگوی صفحه‌بندی سالم است');
    })
    .catch(()=>{box.textContent='❌ خطا در ارتباط با رابطِ آزمایش';});
}


function comprehensiveTestStart(){
    const box=$('comprehensiveTestBox'); const btn=$('comprehensiveTestBtn');
    if(!box)return;
    box.style.display='block';
    box.innerHTML='<div style="padding:12px;background:#0f172a;border:1px solid #f59e0b;border-radius:10px;color:#fde68a;font-size:12px;line-height:1.9">⏳ تست جامع شروع شد؛ همهٔ پروفایل‌ها با پیش‌فرض ۵ صفحه آزمایش می‌شوند و نمونه کارت محصول ساخته می‌شود. چیزی ارسال یا ذخیره نمی‌شود.</div>';
    if(btn){btn.disabled=true;btn.textContent='⏳ در حال تست جامع...';}
    const fd=new FormData(); fd.append('pages','5');
    fetch('?s4_comprehensive_test=1',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d.ok)throw Error(d.error||'پاسخ نامعتبر');
        comprehensiveReport=d;
        renderComprehensiveTest(d);
        showToast('✓ تست جامع کامل شد: '+toFa((d.profiles||[]).length)+' پروفایل');
    }).catch(e=>{
        box.innerHTML='<div class="alert alert-danger">❌ خطای تست جامع: '+esc(e.message||e)+'</div>';
    }).finally(()=>{if(btn){btn.disabled=false;btn.textContent='🧪 تست جامع همهٔ پروفایل‌ها (۵ صفحه)';}});
}
function compMoney(n){n=parseInt(n)||0;return n?toFa(n.toLocaleString('en-US'))+' تومان':'—';}
function renderComprehensiveTest(rep){
    const box=$('comprehensiveTestBox'); if(!box)return;
    const rows=rep.profiles||[];
    let ok=rows.filter(r=>r.ok).length;
    let h='<div style="background:linear-gradient(135deg,#0f172a,#42200655);border:1px solid #f59e0b;border-radius:12px;padding:12px;color:#e2e8f0">';
    h+='<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:10px">';
    h+='<b style="color:#fde68a;font-size:14px">🧪 نتیجهٔ تست جامع همهٔ پروفایل‌ها</b>';
    h+='<span style="font-size:10px;color:#94a3b8">نسخه '+esc(rep.version||'')+' · '+toFa(rows.length)+' پروفایل · '+toFa(ok)+' موفق · '+toFa(rep.took_ms||0)+'ms</span></div>';
    h+='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">';
    rows.forEach((r,pi)=>{
        const color=r.ok?'#22c55e':'#f87171';
        h+='<div style="background:#0f172a;border:1px solid '+(r.ok?'#14532d':'#7f1d1d')+';border-radius:12px;padding:10px;min-width:0">';
        h+='<div style="display:flex;justify-content:space-between;gap:8px;align-items:start"><b style="color:#e2e8f0;font-size:12px;line-height:1.6">'+esc(r.name||r.key)+'</b><span style="color:'+color+';font-size:11px;white-space:nowrap">'+(r.ok?'✓':'✗')+'</span></div>';
        h+='<div style="font-size:10px;color:#64748b;direction:ltr;text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+esc(r.url||r.source||'')+'</div>';
        h+='<div style="display:flex;gap:5px;flex-wrap:wrap;margin:7px 0;font-size:10px">';
        h+='<span style="background:#1e293b;border:1px solid #334155;border-radius:99px;padding:2px 7px">منبع: '+(r.source==='github'?'GitHub':'مستقیم')+'</span>';
        h+='<span style="background:#1e293b;border:1px solid #334155;border-radius:99px;padding:2px 7px">محصول: '+toFa(r.products_unique||0)+'</span>';
        h+='<span style="background:#1e293b;border:1px solid #334155;border-radius:99px;padding:2px 7px">سرعت: '+toFa(r.products_per_minute||0)+'/دقیقه</span>';
        h+='</div>';
        if(r.errors&&r.errors.length)h+='<div style="font-size:10px;color:#fca5a5;line-height:1.6;max-height:44px;overflow:auto">'+esc(r.errors.join(' | '))+'</div>';
        const samples=r.samples||[];
        if(samples.length){
            h+='<div style="display:grid;gap:7px;margin-top:8px">';
            samples.forEach((p,si)=>{h+=compProductCard(p,pi,si);});
            h+='</div>';
        }else h+='<div style="font-size:11px;color:#64748b;padding:10px;text-align:center;border:1px dashed #334155;border-radius:8px;margin-top:8px">نمونه محصولی برنگشت</div>';
        if(r.pages&&r.pages.length){
            h+='<details style="margin-top:8px"><summary style="cursor:pointer;color:#93c5fd;font-size:11px">جزئیات صفحه‌ها</summary><div style="font-size:10px;color:#cbd5e1;line-height:1.8;white-space:pre-wrap">';
            h+=esc((r.pages||[]).map(p=>'ص'+p.page+': '+(p.ok?'HTTP '+p.code:'خطا')+' · '+(p.products||0)+' کارت · '+(p.bytes||0)+' بایت · '+(p.used_engine||'')+(p.error?' · '+p.error:'')).join('\n'));
            h+='</div></details>';
        }
        h+='</div>';
    });
    h+='</div><div style="font-size:10px;color:#94a3b8;margin-top:10px;line-height:1.8">کلیک روی هر کارت محصول، مودال کامل قیمت‌ها، تعدیل پروفایل/غرفه، قیمت نهایی ارسال، تصاویر، توضیحات، تنوع‌ها و سایر جزئیات استخراج‌شده را باز می‌کند.</div></div>';
    box.innerHTML=h;
}
function compProductCard(p,pi,si){
    const pr=p._pricing||{}; const img=(Array.isArray(p.images)&&p.images.length?p.images[0]:p.image)||'';
    let h='<button type="button" onclick="compOpenProduct('+pi+','+si+')" style="display:flex;gap:8px;text-align:right;background:#111c31;border:1px solid #334155;border-radius:10px;padding:8px;color:#e2e8f0;cursor:pointer;width:100%">';
    if(img)h+='<img src="?image_proxy='+encodeURIComponent(img)+'" onerror="this.style.display=\'none\'" style="width:54px;height:54px;object-fit:cover;border-radius:8px;border:1px solid #334155;flex:0 0 auto">';
    else h+='<span style="width:54px;height:54px;border-radius:8px;background:#0f172a;border:1px solid #334155;display:flex;align-items:center;justify-content:center;flex:0 0 auto">📦</span>';
    h+='<span style="min-width:0;flex:1"><b style="display:block;font-size:11px;color:#e2e8f0;line-height:1.6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+esc(p.title||p.link||'بدون عنوان')+'</b>';
    h+='<span style="display:block;color:#fbbf24;font-size:10px">پایه: '+compMoney(pr.raw||extractNumber(p.price||''))+'</span>';
    h+='<span style="display:block;color:#67e8f9;font-size:10px">ارسال: '+compMoney(pr.woocommerce_price||pr.basalam_price||pr.profile_price)+'</span></span></button>';
    return h;
}
function compOpenProduct(pi,si){
    if(!comprehensiveReport)return;
    const prof=(comprehensiveReport.profiles||[])[pi]; if(!prof)return;
    const p=(prof.samples||[])[si]; if(!p)return;
    const pr=p._pricing||{};
    let m=$('compProductModal');
    if(!m){m=document.createElement('div');m.id='compProductModal';m.className='bsl-modal-overlay';m.onclick=function(e){if(e.target===m)compCloseProduct();};document.body.appendChild(m);}
    const imgs=[]; if(p.image)imgs.push(p.image); if(Array.isArray(p.images))p.images.forEach(u=>{if(u&&!imgs.includes(u))imgs.push(u);});
    let h='<div class="bsl-modal" style="width:980px;max-width:96vw"><div class="bsl-modal-head"><h2>📦 '+esc(p.title||'جزئیات محصول')+'</h2><button class="btn btn-gray" onclick="compCloseProduct()">✕</button></div>';
    h+='<div class="bsl-modal-body" style="padding:14px;max-height:78vh;overflow:auto">';
    h+='<div style="display:grid;grid-template-columns:minmax(220px,320px) 1fr;gap:14px">';
    h+='<div>';
    if(imgs.length){h+='<div style="display:flex;flex-wrap:wrap;gap:6px">';imgs.slice(0,12).forEach((u,i)=>{h+='<a href="'+esc(u)+'" target="_blank" title="'+esc(u)+'"><img src="?image_proxy='+encodeURIComponent(u)+'" style="width:'+(i?72:150)+'px;height:'+(i?72:150)+'px;object-fit:cover;border-radius:10px;border:1px solid '+(i?'#334155':'#22c55e')+'"></a>';});h+='</div>';}else h+='<div style="height:160px;border:1px dashed #334155;border-radius:12px;display:flex;align-items:center;justify-content:center;color:#64748b">بدون تصویر</div>';
    h+='</div><div>';
    h+='<table class="bsl-modal-table" style="white-space:normal"><tbody>';
    const row=(k,v,c)=>'<tr><th style="width:190px;text-align:right">'+k+'</th><td style="white-space:normal;color:'+(c||'#e2e8f0')+'">'+v+'</td></tr>';
    h+=row('پروفایل',esc(prof.name||''));
    h+=row('لینک',p.link?('<a href="'+esc(p.link)+'" target="_blank" style="color:#93c5fd;direction:ltr;display:block">'+esc(p.link)+'</a>'):'—');
    h+=row('SKU',esc(p.sku||'—'));
    h+=row('قیمت پایه سایت',compMoney(pr.raw||extractNumber(p.price||''))+' <span style="color:#64748b">('+esc(pr.raw_text||p.price||'')+')</span>','#fbbf24');
    h+=row('تعدیل همین پروفایل',esc((pr.profile_mode||'none')+' '+(pr.profile_val||0)+' · گرد کردن '+(pr.round||0))+' → <b>'+compMoney(pr.profile_price)+'</b>','#86efac');
    h+=row('قیمت نهایی ارسال ووکامرس',compMoney(pr.woocommerce_price),'#a78bfa');
    h+=row('قیمت نهایی ارسال باسلام',compMoney(pr.basalam_price),'#67e8f9');
    if(pr.shops&&pr.shops.length){
        let sh='<table style="width:100%;border-collapse:collapse;font-size:11px"><tr><th>غرفه</th><th>تعدیل کل</th><th>کلی باسلام</th><th>تعدیل غرفه</th><th>قیمت ارسال</th></tr>';
        pr.shops.forEach(s=>{sh+='<tr><td>'+esc(s.name||s.vendor_id||'—')+(s.is_default?' <span style="color:#22c55e">پیش‌فرض</span>':'')+'</td><td>'+toFa(s.eff_pct||0)+'٪</td><td>'+toFa(s.global_pct||0)+'٪</td><td>'+(s.is_default?'—':(toFa(s.vendor_pct||0)+'٪'))+'</td><td style="color:#fbbf24">'+compMoney(s.price)+'</td></tr>';});
        sh+='</table>'; h+=row('غرفه‌ها / تعدیل اضافه',sh);
    }
    h+='</tbody></table></div></div>';
    h+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px">';
    h+='<div style="background:#0f172a;border:1px solid #334155;border-radius:10px;padding:10px"><b style="color:#c4b5fd">📝 توضیحات</b><div style="font-size:12px;color:#cbd5e1;line-height:1.9;margin-top:6px;white-space:pre-wrap">'+esc(p.longDesc||p.shortDesc||p.description||'—')+'</div></div>';
    h+='<div style="background:#0f172a;border:1px solid #334155;border-radius:10px;padding:10px"><b style="color:#f9a8d4">🎨 تنوع‌ها و سایر جزئیات</b><div style="font-size:11px;color:#cbd5e1;line-height:1.9;margin-top:6px;white-space:pre-wrap;direction:ltr;text-align:left">'+esc(JSON.stringify({variations:p.variations||null,stock:p.stock||null,brand:p.brand||null,category:p.category||null,tags:p.tags||null,extra:p.extra||null},null,2))+'</div></div>';
    h+='</div></div></div>';
    m.innerHTML=h;m.style.display='flex';document.body.classList.add('modal-open');
}
function compCloseProduct(){const m=$('compProductModal');if(m)m.style.display='none';document.body.classList.remove('modal-open');}

function engineBenchmarkStart(){
    const box=$('engineBenchmarkBox');
    const btn=$('engineBenchmarkBtn');
    if(!box)return;
    let d={};
    try{d=collectProfileData();}catch(e){box.style.display='block';box.innerHTML='<div class="alert alert-danger">خطا در خواندن فرم: '+esc(e.message||e)+'</div>';return;}
    if(!d.url){showToast('ابتدا آدرس پروفایل را وارد کنید',1);return;}
    box.style.display='block';
    box.innerHTML='<div style="padding:10px;background:#0f172a;border:1px solid #f59e0b;border-radius:10px;color:#fde68a;font-size:12px">⏳ تست سه‌صفحه‌ای موتورها شروع شد… هر موتور فقط سه صفحهٔ اول را می‌خواند و چیزی ذخیره نمی‌کند.</div>';
    if(btn){btn.disabled=true;btn.textContent='⏳ در حال تست موتورها…';}
    const fd=new FormData();
    fd.append('url',d.url||'');
    fd.append('pages','3');
    fd.append('pagType',d.pagType||'query_page');
    fd.append('pagVal',d.pagVal||'');
    fd.append('selectors',JSON.stringify(d.selectors||{}));
    fetch('?engine_benchmark=1',{method:'POST',body:fd})
      .then(r=>r.json()).then(rep=>{
        if(!rep||!rep.ok){throw Error((rep&&rep.error)||'پاسخ نامعتبر');}
        renderEngineBenchmark(rep);
        if(rep.fastest)showToast('🏁 سریع‌ترین موتور: '+rep.fastest.engine+' — '+toFa(rep.fastest.products_per_minute)+' محصول/دقیقه');
      }).catch(e=>{
        box.innerHTML='<div class="alert alert-danger">❌ خطای تست موتورها: '+esc(e.message||e)+'</div>';
      }).finally(()=>{if(btn){btn.disabled=false;btn.textContent='🏁 تست سه‌صفحه‌ای همهٔ موتورها';}});
}
function renderEngineBenchmark(rep){
    const box=$('engineBenchmarkBox'); if(!box)return;
    const rows=rep.results||[];
    const fast=rep.fastest&&rep.fastest.engine;
    let h='<div style="background:linear-gradient(135deg,#0f172a,#42200655);border:1px solid #f59e0b;border-radius:12px;padding:12px;color:#e2e8f0">';
    h+='<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px">';
    h+='<b style="color:#fde68a;font-size:13px">🏁 نتیجهٔ تست سه‌صفحه‌ای موتورهای استخراج</b>';
    h+='<span style="font-size:10px;color:#94a3b8">صفحات هدف: '+toFa(rep.pages_target||3)+' · زمان کل: '+toFa(rep.took_ms||0)+'ms</span></div>';
    if(rep.fastest){
        h+='<div style="margin-bottom:8px;padding:8px 10px;background:#14532d55;border:1px solid #22c55e66;border-radius:8px;font-size:11px;color:#bbf7d0">';
        h+='✅ سریع‌ترین موتورِ دارای محصول: <b>'+esc(rep.fastest.label||rep.fastest.engine)+'</b> — '+toFa(rep.fastest.products_per_minute||0)+' محصول/دقیقه · '+toFa(rep.fastest.products_unique||0)+' محصول یکتا';
        h+='</div>';
    }
    h+='<div style="overflow:auto"><table style="width:100%;border-collapse:collapse;font-size:11px;min-width:900px">';
    h+='<thead><tr style="background:#1e293b;color:#cbd5e1"><th style="padding:7px;border:1px solid #334155">موتور</th><th style="padding:7px;border:1px solid #334155">وضعیت</th><th style="padding:7px;border:1px solid #334155">صفحات</th><th style="padding:7px;border:1px solid #334155">کل کارت‌ها</th><th style="padding:7px;border:1px solid #334155">محصول یکتا</th><th style="padding:7px;border:1px solid #334155">تکراری</th><th style="padding:7px;border:1px solid #334155">سرعت میانگین</th><th style="padding:7px;border:1px solid #334155">زمان</th><th style="padding:7px;border:1px solid #334155">لایه/خطا</th><th style="padding:7px;border:1px solid #334155">جزئیات صفحه‌ها</th></tr></thead><tbody>';
    rows.forEach(r=>{
        const ok=(r.products_unique||0)>0;
        const isFast=fast&&fast===r.engine;
        const status=ok?(isFast?'🏆 سریع‌ترین':'✓ محصول دارد'):'✗ بی‌نتیجه';
        const errs=(r.errors||[]).join(' | ');
        const layers=(r.used_layers||[]).join('، ');
        const pg=(r.pages||[]).map(p=>{
          const sam=(p.sample||[]).map(s=>((s.title||'').slice(0,80))+(s.price?(' — '+s.price):'')+(s.link?(' — '+s.link):'')).join(' | ');
          return 'ص'+p.page+': '+(p.ok?'HTTP '+p.code:'خطا')+' · '+(p.products||0)+' کارت · '+(p.new||0)+' تازه · fetch '+(p.fetch_ms||0)+'ms · parse '+(p.parse_ms||0)+'ms'+(p.final_url&&p.final_url!==p.url?' · نهایی: '+p.final_url:'' )+(p.used_engine?' · موتور: '+p.used_engine:'')+(sam?'\nنمونه‌ها: '+sam:'')+(p.error?' · '+p.error:'');
        });
        h+='<tr style="background:'+(isFast?'#14532d33':'#0f172a')+'">';
        h+='<td style="padding:7px;border:1px solid #334155;color:#fde68a"><b>'+esc(r.label||r.engine)+'</b><br><span dir="ltr" style="color:#94a3b8">'+esc(r.engine)+'</span></td>';
        h+='<td style="padding:7px;border:1px solid #334155;color:'+(ok?'#86efac':'#fca5a5')+'">'+status+'</td>';
        h+='<td style="padding:7px;border:1px solid #334155;text-align:center">'+toFa(r.pages_scanned||0)+'</td>';
        h+='<td style="padding:7px;border:1px solid #334155;text-align:center">'+toFa(r.products_total||0)+'</td>';
        h+='<td style="padding:7px;border:1px solid #334155;text-align:center;font-weight:800">'+toFa(r.products_unique||0)+'</td>';
        h+='<td style="padding:7px;border:1px solid #334155;text-align:center;color:#fbbf24">'+toFa(r.products_duplicate||0)+'</td>';
        h+='<td style="padding:7px;border:1px solid #334155;text-align:center;color:#67e8f9;font-weight:800">'+toFa(r.products_per_minute||0)+' / دقیقه</td>';
        h+='<td style="padding:7px;border:1px solid #334155;text-align:center">'+toFa(r.elapsed_ms||0)+'ms</td>';
        h+='<td style="padding:7px;border:1px solid #334155;max-width:220px">'+(layers?('لایه: '+esc(layers)+'<br>'):'')+(errs?('<span style="color:#fca5a5">'+esc(errs)+'</span>'):('<span style="color:#94a3b8">'+esc(r.hint||'—')+'</span>'))+'</td>';
        h+='<td style="padding:7px;border:1px solid #334155"><details><summary style="cursor:pointer;color:#93c5fd">نمایش</summary><div style="direction:rtl;white-space:pre-wrap;color:#cbd5e1;line-height:1.8">'+esc(pg.join('\n')||'—')+'</div></details></td>';
        h+='</tr>';
    });
    h+='</tbody></table></div>';
    h+='<div style="font-size:10px;color:#94a3b8;margin-top:8px;line-height:1.8">این تست فقط فهرست سه صفحهٔ اول را می‌خواند؛ گالری/جزئیات محصول و ارسال به مقصد انجام نمی‌شود. معیار سرعت = محصول یکتای یافت‌شده ÷ زمان کل موتور.</div>';
    h+='</div>';
    box.innerHTML=h;
}

function findProfileEntryJs(ref) {
    if (!ref || !Array.isArray(profiles)) return null;
    const s = String(ref).trim();
    if (!s) return null;
    return profiles.find(p => p && p.key === s)
        || profiles.find(p => p && p.url === s)
        || null;
}

function updateUrlTargetProfileHint() {
    const el = $('urlTargetProfileHint');
    if (!el) return;
    const active = currentProfileKey ? findProfileEntryJs(currentProfileKey) : null;
    if (active) {
        const curUrl = (($('url') || {}).value || '').trim();
        const urlChanged = !!(curUrl && active.url && curUrl !== active.url);
        el.style.color = urlChanged ? '#fbbf24' : '#86efac';
        el.innerHTML = '📌 پروفایل فعال: <b style="color:#f8fafc">' + esc(active.name || active.key) + '</b> — '
            + (urlChanged
                ? 'آدرس جدید مستقیماً روی <b>همین پروفایل</b> ذخیره می‌شود (پروفایل جدید ساخته نمی‌شود).'
                : 'تغییر آدرس بالا مستقیماً روی همین پروفایل ذخیره می‌شود (برای ساخت پروفایل مجزا از «📋 کپی» یا «➕ جدید» استفاده کنید).');
    } else {
        el.style.color = '#94a3b8';
        el.textContent = 'حالت پروفایل جدید فعال است — با زدن 💾 پروفایل جدید ساخته می‌شود.';
    }
}

function maybeAutoSelectDigikalaEngine(urlStr) {
    if (!urlStr || !/(?:^https?:\/\/)(?:[^\/?#]+\.)?digikala\.com(?:[\/:?#]|$)/i.test(urlStr)) return;
    const engEl = $('extractionEngine');
    const contEl = $('selContainer');
    if (engEl && engEl.value === 'selectors' && (!contEl || !contEl.value.trim())) {
        syncExtractionEngine('digikala_api', '');
    }
}

function onUrlChange() {
    clearTimeout(saveTimer);
    clearTimeout(urlChangeTimer);
    maybeAutoSelectDigikalaEngine(($('url') && $('url').value || '').trim());
    const active = currentProfileKey ? findProfileEntryJs(currentProfileKey) : null;
    if (active) {
        /* v10.462: وقتی پروفایل فعالی باز است، تغییر لینک آدرس نباید currentProfileKey یا نام پروفایل را پاک کند
           یا پروفایل خالی جدید بسازد؛ بلکه تغییر روی همان پروفایل فعال ذخیره می‌شود. */
        if (!profileFormReady) {
            window._pendingEditedUrlForSeq = { seq: profileLoadSeq, url: (($('url') && $('url').value) || '').trim() };
        }
        markDirty();
        updateUrlTargetProfileHint();
        urlChangeTimer = setTimeout(() => {
            const url = ($('url') && $('url').value || '').trim();
            if (/^https?:\/\/[^\s/$.?#].[^\s]*$/i.test(url) && profileFormReady) {
                scheduleSave();
            }
        }, 600);
        return;
    }
    profileLoadSeq++;profileFormReady=false;
    urlChangeTimer = setTimeout(() => {
        const url = $('url').value.trim();
        if (!url) { updateUrlTargetProfileHint(); return; }
        const matches = Array.isArray(profiles) ? profiles.filter(p => p && p.url === url) : [];
        if (matches.length === 1) {
            loadProfileFromServer(matches[0].key || url);
        } else {
            currentProfileKey = null;
            const s = $('profileStatus');
            if (s) {
                s.textContent = 'جدید';
                s.className = 'profile-indicator unsaved';
            }
            $('profileName').value = '';
            setProfileSelectValue('');
            updateUrlTargetProfileHint();
        }
    }, 500);
}

function setProfileSelectValue(url) {
    let resolved = url || '';
    if (resolved && Array.isArray(profiles)) {
        if (!profiles.some(p => p && p.key === resolved)) {
            const byActive = currentProfileKey ? profiles.find(p => p && p.key === currentProfileKey && p.url === resolved) : null;
            const byUrl = byActive || profiles.find(p => p && p.url === resolved);
            if (byUrl && byUrl.key) resolved = byUrl.key;
        }
    }
    ['profileSelect','hdrProfileSelect'].forEach(id => { const el=$(id); if(el) el.value = resolved || ''; });
    updateUrlTargetProfileHint();
}

function renderProfileDropdown() {
    // v9.65: اگر profiles.json خراب/غیر-آرایه باشد، کل اسکریپت هنگام راه‌اندازی
    // با «profiles.forEach is not a function» می‌ایستد و محتوای تب‌ها خالی می‌ماند.
    if(!Array.isArray(profiles)) profiles=[];
    const fill = (el, label) => {
        if(!el) return;
        el.innerHTML = '';
        const first = document.createElement('option');
        first.value = '';
        first.textContent = label;
        el.appendChild(first);
        profiles.forEach(p => {
            if (!p) return;
            const opt = document.createElement('option');
            opt.value = p.key || p.url || '';
            if (p.url) opt.dataset.url = p.url;
            opt.textContent = p.name || p.url || p.key;
            opt.title = (p.name ? (p.name + ' — ') : '') + (p.url || p.key || '');
            el.appendChild(opt);
        });
    };
    fill($('profileSelect'), '-- انتخاب سایت (' + profiles.length + ') --');
    fill($('hdrProfileSelect'), 'پروفایل (' + profiles.length + ')');
    if (currentProfileKey && profiles.some(p => p && p.key === currentProfileKey)) {
        setProfileSelectValue(currentProfileKey);
    } else {
        const cur = (($('url')||{}).value || '').trim();
        if (cur && profiles.some(p => p && p.url === cur)) setProfileSelectValue(cur);
    }
    // v8.62: همان فهرست برای «عکس‌دار کردن» — آنجا کلید پروفایل لازم است نه URL
    const ph = $('photoProfile');
    if (ph) {
        let h = '<option value="">همهٔ پروفایل‌ها</option>';
        profiles.forEach(p => { if (p) h += '<option value="' + esc(p.key) + '">' + esc(p.name) + '</option>'; });
        ph.innerHTML = h;
    }
}
renderProfileDropdown();

/* =====================================================================
 *  v8.68: آخرین پروفایل باز، پیش‌فرض دفعهٔ بعد
 *
 *  تا اینجا هر بار صفحه رفرش می‌شد، فهرست خالی بود و باید دوباره
 *  پروفایل را از کشویی انتخاب می‌کردید. آدرس آخرین پروفایل در همین
 *  مرورگر ذخیره می‌شود (نه روی سرور، چون به کاربر و دستگاه مربوط است)
 *  و موقع باز شدن دوباره بارگذاری می‌شود.
 * ===================================================================== */
const LAST_PROFILE_KEY = 'scraper_last_profile_url';
const LAST_PROFILE_ID_KEY = 'scraper_last_profile_key';
const EXTRACTION_ENGINE_DEFAULT = 'selectors';
function s4EngineValue(){
    return ($('extractionEngine')&&$('extractionEngine').value) || ($('extractionEngine2')&&$('extractionEngine2').value) || EXTRACTION_ENGINE_DEFAULT;
}
function syncExtractionEngine(v, src){
    v = v || EXTRACTION_ENGINE_DEFAULT;
    const ref=$('extractionEngine')||$('extractionEngine2');
    if(ref && !Array.from(ref.options).some(o=>o.value===v)) v=EXTRACTION_ENGINE_DEFAULT;
    ['extractionEngine','extractionEngine2'].forEach(id=>{ const el=$(id); if(el) el.value=v; });
}

function rememberProfile(url, key) {
    try {
        if (url) localStorage.setItem(LAST_PROFILE_KEY, url);
        const found=key || ((profiles.find(p=>p.url===url)||{}).key) || '';
        if(found)localStorage.setItem(LAST_PROFILE_ID_KEY, found);
    } catch (e) {}
}
function forgetProfile() {
    try { localStorage.removeItem(LAST_PROFILE_KEY); localStorage.removeItem(LAST_PROFILE_ID_KEY); } catch (e) {}
}
function lastProfileUrl() {
    try { return localStorage.getItem(LAST_PROFILE_KEY) || ''; } catch (e) { return ''; }
}

/** موقع باز شدن صفحه، آخرین پروفایل را با key پایدار (و سپس URL) برگردان */
function restoreLastProfile() {
    let url = lastProfileUrl();
    let key='';try{key=localStorage.getItem(LAST_PROFILE_ID_KEY)||'';}catch(e){}
    const found=(key&&profiles.find(p=>p&&p.key===key)) || (url&&profiles.find(p=>p&&p.url===url));
    if (!found) { if(url||key)forgetProfile(); updateUrlTargetProfileHint(); return; }
    url=found.url||url;if(!url)return;
    const targetRef = found.key || key || url;
    currentProfileKey = found.key || key || null;
    rememberProfile(url,found.key||key);
    setProfileSelectValue(targetRef);
    $('url').value = url;
    loadProfileFromServer(targetRef, true);
}

function newBlankProfile(silentToast) {
    clearTimeout(saveTimer);
    clearTimeout(urlChangeTimer);
    profileLoadSeq++;
    profileFormReady = false;
    isDirty = false;
    window._userClearedProducts = false;
    currentProfileKey = null;
    currentProfileUrl = '';
    currentProfileUpdatedAt = 0;
    if ($('url')) $('url').value = '';
    if ($('profileName')) $('profileName').value = '';
    resetResultFilter();
    products.clear();
    order = [];
    try { listImgEditApply({}); galApply({}); } catch (e) {}
    try { refreshViews(); update(); } catch (e) {}
    setProfileSelectValue('');
    const s = $('profileStatus');
    if (s) {
        s.textContent = 'جدید';
        s.className = 'profile-indicator unsaved';
    }
    updateUrlTargetProfileHint();
    if (!silentToast) {
        showToast('➕ فرم پروفایل جدید آماده شد — نام و آدرس را وارد کرده و 💾 بزنید');
        if ($('profileName')) $('profileName').focus();
    }
}

function selectProfile(url) {
    if (!url) { newBlankProfile(true); return; }
    clearTimeout(saveTimer); profileFormReady=false; profileLoadSeq++;
    const hit = findProfileEntryJs(url);
    const resolvedKey = (hit && hit.key) ? hit.key : (String(url).indexOf('://') === -1 ? url : '');
    const resolvedUrl = (hit && hit.url) ? hit.url : (String(url).indexOf('://') !== -1 ? url : '');
    if (resolvedKey) currentProfileKey = resolvedKey;
    setProfileSelectValue(resolvedKey || url);
    if (resolvedUrl && $('url')) $('url').value = resolvedUrl;
    if (hit && hit.name && $('profileName')) $('profileName').value = hit.name;
    rememberProfile(resolvedUrl || url, resolvedKey);
    loadProfileFromServer(resolvedKey || url);
}
function selectHeaderProfile(url) {
    if (!url) { newBlankProfile(true); return; }
    selectProfile(url);
}

function pagesInputChanged(commit){
    const input=$('pages');if(!input)return;
    if(commit&&(input.value===''||parseInt(input.value)<0))input.value='0';
    scheduleSave();
}

function ghRepoValue(){
    const custom=$('ghRepoCustom');
    if(custom&&custom.style.display!=='none'&&custom.value.trim())return custom.value.trim();
    return (($('ghRepoSelect')||{}).value)||S4_GH_DEFAULT_REPO;
}
function ghBranchValue(){return (($('ghBranchSelect')||{}).value)||S4_GH_DEFAULT_BRANCH;}
function ghFileValue(){return (($('ghFileSelect')||{}).value)||'';}
function getProductSourceConfig(){
    const mode=(($('profileProductSource')||{}).value)||'direct';
    if(mode!=='github')return{mode:'direct'};
    return{mode:'github',repo:ghRepoValue(),branch:ghBranchValue(),path:ghFileValue()};
}
function applyProductSourceConfig(ps, triggerLoad){
    ps=ps||{mode:'direct'};
    const mode=ps.mode==='github'?'github':'direct';
    if($('profileProductSource'))$('profileProductSource').value=mode;
    if(mode==='github'){
        if($('ghRepoSelect')){
            const repo=ps.repo||S4_GH_DEFAULT_REPO;
            if(!Array.from($('ghRepoSelect').options).some(o=>o.value===repo))$('ghRepoSelect').insertAdjacentHTML('beforeend','<option value="'+esc(repo)+'">'+esc(repo)+'</option>');
            $('ghRepoSelect').value=repo;
        }
        if($('ghBranchSelect')){
            const br=ps.branch||S4_GH_DEFAULT_BRANCH;
            if(!Array.from($('ghBranchSelect').options).some(o=>o.value===br))$('ghBranchSelect').insertAdjacentHTML('beforeend','<option value="'+esc(br)+'">'+esc(br)+'</option>');
            $('ghBranchSelect').value=br;
        }
        if($('ghFileSelect')&&ps.path){
            if(!Array.from($('ghFileSelect').options).some(o=>o.value===ps.path))$('ghFileSelect').insertAdjacentHTML('beforeend','<option value="'+esc(ps.path)+'">'+esc(ps.path)+'</option>');
            $('ghFileSelect').value=ps.path;
        }
    }
    productSourceChanged(false);
    if(mode==='github'&&triggerLoad!==false)ghSourceRefresh();
}
function productSourceChanged(save){
    const mode=(($('profileProductSource')||{}).value)||'direct';
    const gh=$('sourceGithubFields'), hint=$('sourceDirectHint');
    if(gh)gh.classList.toggle('hidden',mode!=='github');
    if(hint)hint.classList.toggle('hidden',mode==='github');
    const directHidden=(mode==='github');
    ['directExtractFieldsCard'].forEach(id=>{const el=$(id);if(el)el.style.display=directHidden?'none':'';});
    const status=$('ghSourceStatus');
    if(mode==='github'){
        if(status&&!ghSourceState.loaded)status.textContent='در حال آماده‌سازی فهرست GitHub...';
        if(!ghSourceState.loaded)ghSourceRefresh();
        if($('profileSyncNoExtract')){$('profileSyncNoExtract').checked=true;syncToggleNoExtractBox();updateSyncStatusText();}
    }
    if(save)scheduleSave();
}
function ghSourceToggleCustomRepo(){
    const c=$('ghRepoCustom'), s=$('ghRepoSelect'); if(!c||!s)return;
    const show=c.style.display==='none';
    c.style.display=show?'':'none';
    s.style.display=show?'none':'';
    if(show)c.value=s.value||S4_GH_DEFAULT_REPO;
    ghSourceRefresh();
}
function ghSourceRepoCustomChanged(){clearTimeout(window._ghRepoT);window._ghRepoT=setTimeout(()=>ghSourceRefresh(),600);}
function ghSourceRepoChanged(){ghSourceRefresh();}
function ghSetStatus(msg,isErr){const el=$('ghSourceStatus');if(el){el.textContent=msg;el.style.color=isErr?'#fca5a5':'#94a3b8';}}
function ghSourceRefresh(){
    const repo=ghRepoValue();
    ghSetStatus('⏳ خواندن branch و فایل‌های CSV/Excel از '+repo+' ...');
    const br=ghBranchValue();
    fetch('?github_product_files=1&repo='+encodeURIComponent(repo)+'&branch='+encodeURIComponent(br))
      .then(r=>r.json()).then(d=>{
        if(!d.ok)throw Error(d.error||'GitHub error');
        ghSourceState.loaded=true;ghSourceState.files=d.files||[];ghSourceState.branches=d.branches||[];
        const bsel=$('ghBranchSelect');
        if(bsel){
            const want=bsel.value||d.branch||S4_GH_DEFAULT_BRANCH;
            bsel.innerHTML='';
            (d.branches||[want]).forEach(b=>{const o=document.createElement('option');o.value=b;o.textContent=b;bsel.appendChild(o);});
            if(Array.from(bsel.options).some(o=>o.value===want))bsel.value=want;
        }
        renderGhFiles(d.files||[]);
        ghSetStatus('✓ '+toFa((d.files||[]).length)+' فایل CSV/Excel پیدا شد'+((d.files||[]).some(f=>f.source==='local')?' (fallback محلی)':''));
      }).catch(e=>{ghSetStatus('❌ '+(e.message||e),true);});
}
function ghSourceLoadFiles(){
    const repo=ghRepoValue(), br=ghBranchValue();
    ghSetStatus('⏳ خواندن فایل‌های '+br+' ...');
    fetch('?github_product_files=1&repo='+encodeURIComponent(repo)+'&branch='+encodeURIComponent(br))
      .then(r=>r.json()).then(d=>{if(!d.ok)throw Error(d.error||'GitHub error');ghSourceState.files=d.files||[];renderGhFiles(d.files||[]);ghSetStatus('✓ '+toFa((d.files||[]).length)+' فایل پیدا شد');productSourceChanged(true);})
      .catch(e=>ghSetStatus('❌ '+(e.message||e),true));
}
function renderGhFiles(files){
    const fs=$('ghFileSelect'); if(!fs)return;
    const prev=fs.value;
    fs.innerHTML='<option value="">— فایل CSV/Excel —</option>';
    (files||[]).forEach(f=>{
        const o=document.createElement('option');
        o.value=f.path;o.textContent=f.path+(f.size?(' — '+Math.round(f.size/1024)+'KB'):'')+(f.source==='local'?' [local]':'');
        fs.appendChild(o);
    });
    if(prev&&Array.from(fs.options).some(o=>o.value===prev))fs.value=prev;
}
function ghImportProducts(){
    if(!ghFileValue()){showToast('ابتدا فایل CSV/Excel را انتخاب کنید',true);return;}
    const url=($('url')&&$('url').value.trim())||(($('profileSelect')||{}).value)||'';
    if(!url){showToast('برای ثبت در پروفایل، ابتدا پروفایل/URL را انتخاب کنید',true);return;}
    const btn=$('ghImportBtn'); if(btn){btn.disabled=true;btn.textContent='⏳ در حال دریافت...';}
    ghSetStatus('⏳ دریافت فایل و تبدیل به محصولات داخلی...');
    const fd=new FormData();
    fd.append('action','github_import_products');fd.append('repo',ghRepoValue());fd.append('branch',ghBranchValue());fd.append('path',ghFileValue());fd.append('profile_url',url);fd.append('save_to_profile','1');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d.ok)throw Error(d.error||'import failed');
        products.clear(); order=[];
        (d.products||[]).forEach(p=>{const k=p.key||((p.link||'')+'|'+(p.title||''));p.key=k;products.set(k,p);order.push(k);});
        importProducts=d.products||[];
        if($('profileSyncNoExtract')){$('profileSyncNoExtract').checked=true;syncToggleNoExtractBox();updateSyncStatusText();}
        refreshViews(); update();
        markClean(d.profile_key||currentProfileKey||profileKey(url));
        ghSetStatus('✓ '+toFa(d.count||0)+' محصول از '+d.path+' دریافت و برای همین پروفایل ثبت شد');
        showToast('✓ محصولات GitHub مثل خروجی استخراج در پروفایل نشستند');
        renderProfileDropdown();
        if(typeof switchMainTab==='function')switchMainTab('results');
    }).catch(e=>{ghSetStatus('❌ '+(e.message||e),true);showToast('خطا در دریافت GitHub: '+(e.message||e),true);})
      .finally(()=>{if(btn){btn.disabled=false;btn.textContent='📥 دریافت و ثبت محصولات برای همین پروفایل';}});
}

function loadProfileFromServer(url, silent) {
    const seq=++profileLoadSeq;
    clearTimeout(saveTimer); profileFormReady=false;
    window._pendingEditedUrlForSeq = null;
    const isUrlRef = String(url || '').indexOf('://') !== -1;
    fetch('?load_profile=' + encodeURIComponent(url))
        .then(r => r.json())
        .then(d => {
            /* پاسخ دیررس پروفایل قبلی نباید انتخاب تازه‌تر را برگرداند. */
            if(seq!==profileLoadSeq || (isUrlRef && !window._pendingEditedUrlForSeq && $('url').value.trim()!==url))return;
            if (d.ok && d.profile) {
                const pendingEdited = (window._pendingEditedUrlForSeq && window._pendingEditedUrlForSeq.seq === seq)
                    ? window._pendingEditedUrlForSeq.url : '';
                window._pendingEditedUrlForSeq = null;
                window._applyingProfileKey = d.key || (isUrlRef ? '' : String(url || ''));
                /* v9.91: در بازیابیِ خودکارِ بعد از رفرش (silent) نباید تبِ کاربر
                   عوض شود. قبلاً applyProfile در پایانش به «نتایج» می‌پرید و
                   همان علتِ اصلیِ «هر رفرش، تبِ من عوض می‌شود» بود. */
                try {
                    applyProfile(d.profile, !!silent);
                } finally {
                    window._applyingProfileKey = '';
                }
                currentProfileKey=d.key||currentProfileKey;
                currentProfileUrl=d.profile.url||url;
                currentProfileUpdatedAt=parseInt(d.profile.updatedAt||0)||0;
                profileFormReady=true;
                setProfileSelectValue(currentProfileKey || currentProfileUrl);
                rememberProfile(currentProfileUrl,currentProfileKey);
                if (pendingEdited && pendingEdited !== currentProfileUrl) {
                    if ($('url')) $('url').value = pendingEdited;
                    markDirty();
                    updateUrlTargetProfileHint();
                    if (/^https?:\/\/[^\s/$.?#].[^\s]*$/i.test(pendingEdited)) scheduleSave();
                } else {
                    updateUrlTargetProfileHint();
                }
                if (silent) showToast('↩ آخرین پروفایل بازیابی شد: ' + (d.profile.name || url));
            } else if (!silent) {
                showToast('پروفایل یافت نشد', true);
            } else {
                forgetProfile();                 // پروفایل دیگر نیست
            }
        })
        .catch(() => { if(seq===profileLoadSeq&&!silent) showToast('خطا در بارگذاری', true); });
}

function applyProfile(p, keepTab) {
    $('url').value = p.url || '';
    $('profileName').value = p.name || '';
    $('pages').value = (p.pages===0||p.pages==='0') ? 0 : Math.max(1,parseInt(p.pages)||10);
    syncExtractionEngine(p.extractionEngine || EXTRACTION_ENGINE_DEFAULT, 'load');
    $('pagType').value = p.pagType || 'query_page';
    $('pagVal').value = p.pagVal || '';
    $('titleSuffix').value = p.titleSuffix || '';
    $('priceMode').value = p.priceMode || 'none';
    $('priceVal').value = p.priceVal || 0;
    $('roundPrice').value = p.roundPrice || '0';
    $('minPrice').value = p.minPrice || 10000;
    $('useCustomCol').checked = !!p.useCustomCol;
    if($('fullMode'))$('fullMode').checked=!!p.fullMode;
    $('customColName').value = p.customColName || 'وضعیت';
    $('customColVal').value = p.customColVal || 'موجود';
    // Restore iframe height slider
    if(p.iframeHeight){$('iframeSizeSlider').value=p.iframeHeight;setIframeHeight(p.iframeHeight);}

    if (p.selectors) {
        sel = {...sel, ...p.selectors};
        ['container','title','price','link','image'].forEach(k=>{
            $('sel'+k.charAt(0).toUpperCase()+k.slice(1)).value = sel[k] || '';
            $('s-'+k).classList.toggle('has', !!sel[k]);
            // Auto-test each selector
            if (sel[k]) {
                setTimeout(() => testSel(k), 300);
            }
        });
    }
    // v7.66: Show auto-extract status on start button
    if(sel.container && sel.title){
        $('startBtn').textContent='▶ استخراج اتوماتیک ✓ ('+sel.container+')';
        $('startBtn').style.background='#22c55e';
        $('startBtn').style.color='#fff';
    }else{
        $('startBtn').textContent='▶ استخراج اتوماتیک';
        $('startBtn').style.background='';
        $('startBtn').style.color='';
    }

    if (p.detailSelectors) {
        DETAIL_FIELDS.forEach(f => {
            if (p.detailSelectors[f.key]) {
                detailSel[f.key] = {
                    enabled: !!p.detailSelectors[f.key].enabled,
                    selector: p.detailSelectors[f.key].selector || ''
                };
            } else {
                detailSel[f.key] = {enabled:false, selector:''};
            }
        });
        renderDetailFieldsList();
    }
    window._lastListTestedImageUrl = '';
    window._lastGalleryTestedImageUrl = '';
    listImgEditApply(p.listImageEdit || {}); // v10.445
    galApply(p.gallery || {});           // v8.64

    updatePagUI();
    applyProductSourceConfig(p.productSource || {mode:'direct'}, false);

    // Restore saved products from profile
    if (p.products && Array.isArray(p.products) && p.products.length > 0) {
        resetResultFilter();
        products.clear();
        order = p.productsOrder || p.products.map(e => e[0]);
        p.products.forEach(entry => {
            if (Array.isArray(entry) && entry.length === 2) {
                if(entry[1]&&typeof entry[1]==='object'&&!entry[1].key)entry[1].key=entry[0];
                products.set(entry[0], entry[1]);
            }
        });
        refreshViews();
        /* v9.91: در بازیابیِ خودکار، تبِ فعلیِ کاربر حفظ می‌شود.
           v10.31 (۴۴): حالا در هیچ حالتی تب عوض نمی‌شود. پریدن به «نتایج»
           یعنی رندرِ فوریِ کلِ محصولات، و روی پروفایل‌های بزرگ همان چیزی
           است که بارگذاری را کند می‌کرد. اگر کاربر نتایج بخواهد، خودش
           روی تب می‌زند و همان لحظه ساخته می‌شود. پارامترِ keepTab برای
           سازگاریِ امضای تابع می‌ماند. */
        void keepTab;
        window._userClearedProducts = false;
        showToast('✓ پروفایل "' + (p.name || '') + '" بارگذاری شد (' + toFa(products.size) + ' محصول)');
    } else {
        resetResultFilter();
        products.clear();
        order = [];
        window._userClearedProducts = false;
        refreshViews();
        try { update(); } catch (e) {}
        showToast('✓ پروفایل "' + (p.name || '') + '" بارگذاری شد');
    }

    if (window._applyingProfileKey) {
        currentProfileKey = window._applyingProfileKey;
    } else {
        try {
            const u = new URL(p.url);
            let path = u.pathname.replace(/\/$/, '');
            path = path.replace(/\/page\/\d+\/?$/i, '');
            path = path.replace(/\.(html|htm|php)$/i, '');
            let key = u.host.toLowerCase() + (path ? '_' + path.replace(/[^a-z0-9]+/gi, '_').replace(/^_|_$/g, '') : '');
            currentProfileKey = key;
        } catch(e) {
            currentProfileKey = null;
        }
    }

    markClean(currentProfileKey);
    setProfileSelectValue(currentProfileKey || p.url || '');
    // v8.06: Restore per-profile BaSalam category
    if(p.bslCategoryId && p.bslCategoryId>0){
        bslSelectedCatId=p.bslCategoryId;
        $('bsCat').value=String(p.bslCategoryId);
        if(bslAllCats.length>0){
            renderBslCatDropdown(bslAllCats,p.bslCategoryId);
            bslSelectCat(p.bslCategoryId);
        }else{
            // Load cats first, then select
            loadBslCats();
            setTimeout(()=>{bslSelectCat(p.bslCategoryId);},2000);
        }
    }else{
        bslSelectedCatId=0;
        $('bsCat').value='0';
        if($('bsCatSearch'))$('bsCatSearch').value='';
    }
    // v8.17: Restore per-profile category and fallback
    if(p.bslCategoryId && p.bslCategoryId>0){
        bslProfileSelectedCatId=p.bslCategoryId;
        if($('bslProfileCatId'))$('bslProfileCatId').value=String(p.bslCategoryId);
        if(bslAllCats.length>0){
            renderBslProfileCatDropdown(bslAllCats,p.bslCategoryId);
        }else{
            // v8.43: دسته‌ها هنوز نرسیده‌اند. قبلاً هیچ کاری نمی‌شد و کادر
            // خالی می‌ماند، بعد ذخیرهٔ خودکار همان خالی را ذخیره می‌کرد.
            // حالا شناسه را نشان می‌دهیم و پس از رسیدن دسته‌ها نام را می‌گذاریم.
            if($('bslProfileCatSearch'))$('bslProfileCatSearch').value='#'+p.bslCategoryId;
            const _wantCat=p.bslCategoryId;
            loadBslCats();
            let _tries=0;
            const _t=setInterval(()=>{
                _tries++;
                if(bslAllCats&&bslAllCats.length>0){
                    clearInterval(_t);
                    renderBslProfileCatDropdown(bslAllCats,_wantCat);
                }else if(_tries>20){clearInterval(_t);}
            },400);
        }
    }else{
        bslProfileSelectedCatId=0;
        if($('bslProfileCatId'))$('bslProfileCatId').value='0';
        if($('bslProfileCatSearch'))$('bslProfileCatSearch').value='';
    }
    if(p.bslFallbackCatIds && Array.isArray(p.bslFallbackCatIds)){
        renderBslProfileFallbackCats(p.bslFallbackCatIds);
    }else{
        bslProfileFallbackCats=[];
        renderBslProfileFallbackCats([]);
    }
    // v8.56: دستهٔ ووکامرس این پروفایل
    wooProfileCatId=parseInt(p.wooCategoryId||0)||0;
    renderWooProfileCats(wooProfileCatId);
    if(wooProfileCatId>0&&wooAllCats.length===0)loadCats();
    // v8.59: همان دسته‌ها را در کادر بالای «ارسال باسلام» هم نشان بده
    syncBslSendBoxCats(p.bslCategoryId||0,p.bslFallbackCatIds||[]);
    if($('detailExtractMode')){
        $('detailExtractMode').value = normalizeDetailExtractModeJs(p.detailExtractMode || loadDetailExtractModePref());
    }
    if($('backendExtractWithDetail')){
        $('backendExtractWithDetail').checked = p.backendExtractWithDetail !== undefined ? !!p.backendExtractWithDetail : loadBackendExtractWithDetailPref();
    }
    syncDetailExtractModeUi(true);
    syncBackendExtractDetailUi(true);
}

function normalizeDetailExtractModeJs(v){
    return String(v||'').trim().toLowerCase()==='inline' ? 'inline' : 'two_stage';
}
function loadDetailExtractModePref(){
    try{ return normalizeDetailExtractModeJs(localStorage.getItem('s4_detail_extract_mode')||'two_stage'); }catch(e){ return 'two_stage'; }
}
function loadBackendExtractWithDetailPref(){
    try{
        const raw=localStorage.getItem('s4_backend_extract_with_detail');
        return raw===null ? true : raw==='1';
    }catch(e){ return true; }
}
function syncDetailExtractModeUi(skipPrefWrite){
    const selEl=$('detailExtractMode'), hint=$('detailExtractModeHint'), lbl=$('backendExtractWithDetailLbl');
    const mode=normalizeDetailExtractModeJs(selEl?selEl.value:loadDetailExtractModePref());
    if(selEl && selEl.value!==mode) selEl.value=mode;
    if(!skipPrefWrite){ try{ localStorage.setItem('s4_detail_extract_mode', mode); }catch(e){} }
    if(hint){
        hint.textContent = mode==='inline'
            ? 'در حین استخراج هر صفحهٔ لیست، جزئیات هر محصول همان لحظه به‌صورت درجا استخراج و ذخیره می‌شود.'
            : 'اول کل لیست محصولات استخراج و در پروفایل و تب نتایج ذخیره می‌شود؛ سپس خودکار به سراغ مرحلهٔ دوم (استخراج جزئیات) می‌رود.';
    }
    if(lbl){
        lbl.textContent = mode==='inline'
            ? '🔍 استخراج جزئیات درجا هم‌زمان با پیمایش لیست انجام شود'
            : '🔍 پس از استخراج لیست و ذخیره در تب نتایج، مرحلهٔ دوم (استخراج جزئیات) هم اجرا شود';
    }
    syncBackendExtractDetailUi(true);
}
function syncBackendExtractDetailUi(skipPrefWrite){
    const cb=$('backendExtractWithDetail'),btn=$('startBackendBtn');
    const on=!!(cb&&cb.checked);
    const mode=normalizeDetailExtractModeJs($('detailExtractMode')?$('detailExtractMode').value:loadDetailExtractModePref());
    if(!skipPrefWrite){ try{ localStorage.setItem('s4_backend_extract_with_detail', on?'1':'0'); }catch(e){} }
    if(btn){
        btn.textContent = on
            ? (mode==='inline' ? '⚡ استخراج بک‌اند (لیست + جزئیات درجا)' : '⚡ استخراج بک‌اند (دو مرحله‌ای: لیست ← جزئیات)')
            : '⚡ استخراج بک‌اند (فقط لیست)';
    }
}
setTimeout(()=>{syncDetailExtractModeUi(true);syncBackendExtractDetailUi(true);},50);

function collectProfileData() {
    // Serialize current products Map and order array
    const prodsArr = [];
    products.forEach((v, k) => prodsArr.push([k, v]));
    return {
        url: $('url').value.trim(),
        name: $('profileName').value.trim(),
        pages: Math.max(0,parseInt($('pages').value)||0),
        extractionEngine: s4EngineValue(),
        pagType: $('pagType').value,
        pagVal: $('pagVal').value,
        selectors: {...sel},
        detailSelectors: JSON.parse(JSON.stringify(detailSel)),
        listImageEdit: listImgEditCollect(),         // v10.445
        gallery: galCollect(),                       // v8.64
        titleSuffix: $('titleSuffix').value,
        priceMode: $('priceMode').value,
        priceVal: parseFloat($('priceVal').value) || 0,
        roundPrice: $('roundPrice').value,
        minPrice: parseInt($('minPrice').value) || 10000,
        useCustomCol: $('useCustomCol').checked,
        fullMode: $('fullMode')?$('fullMode').checked:false,
        backendExtractWithDetail: $('backendExtractWithDetail') ? !!$('backendExtractWithDetail').checked : true,
        detailExtractMode: $('detailExtractMode') ? normalizeDetailExtractModeJs($('detailExtractMode').value) : loadDetailExtractModePref(),
        customColName: $('customColName').value,
        customColVal: $('customColVal').value,
        iframeHeight: parseInt($('iframeSizeSlider').value) || 600,
        products: prodsArr,
        productsOrder: [...order],
        // v8.06: Per-profile BaSalam category
        // v8.43: اگر متغیرها هنوز مقدار نگرفته‌اند، از فیلد مخفی بخوان تا
        // ذخیرهٔ خودکار انتخاب قبلی را با صفر جایگزین نکند.
        bslCategoryId: bslProfileSelectedCatId
            || parseInt(($('bslProfileCatId')||{}).value||'0')
            || bslSelectedCatId
            || parseInt(($('bsCat')||{}).value||'0')
            || 0,
        // v8.17: Per-profile fallback categories
        bslFallbackCatIds: Array.isArray(bslProfileFallbackCats)?bslProfileFallbackCats:[],
        // v8.56: دستهٔ ووکامرس مخصوص همین پروفایل
        wooCategoryId: parseInt(($('wooProfileCatId')||{}).value||'0')||wooProfileCatId||0,
        // v9.67: اتصال غیرمستقیمِ فقط همین پروفایل (پیش‌فرض: خاموش = مستقیم)
        // v9.76: به‌جای boolean، '1'/'0' بفرست — FormData مقدار false را به رشتهٔ
        // "false" تبدیل می‌کرد و سرور !empty("false") را true حساب می‌کرد؛ یعنی
        // خاموش‌کردن هیچ‌وقت ذخیره نمی‌شد و بعد از رفرش برمی‌گشت.
        net_indirect: (($('profileNetIndirect') && $('profileNetIndirect').checked) ? '1' : '0'),
        productSource: getProductSourceConfig()
    };
}

function saveProfileSilent() {
    const data = collectProfileData();
    const hasActiveKey = !!(currentProfileKey && Array.isArray(profiles) && profiles.some(p => p && p.key === currentProfileKey));
    const validHttpUrl = /^https?:\/\/[^\s/$.?#].[^\s]*$/i.test(String(data.url || '').trim());
    /* فرمِ بین دو profile، پاسخ دیررس، یا snapshot بی‌نسخه هرگز autosave نشود. */
    if (!data.url || !validHttpUrl || !profileFormReady || (!hasActiveKey && data.url!==currentProfileUrl) || currentProfileUpdatedAt<=0)
        return Promise.resolve({ok:false,error:'profile_form_not_ready'});

    const fd = new FormData();
    fd.append('action', 'save_profile');
    fd.append('autosave','1');
    fd.append('loaded_updated_at',String(currentProfileUpdatedAt));
    if (hasActiveKey) fd.append('target_key', currentProfileKey);
    if (window._userClearedProducts) fd.append('allow_empty_products', '1');
    if (window._userPrunedProducts) fd.append('allow_shrink_products', '1');
    for (const k in data) {
        // v7.66: syncConfig must also be JSON.stringify'd — otherwise FormData converts object to "[object Object]"
        if (k === 'selectors' || k === 'detailSelectors' || k === 'products' || k === 'productsOrder' || k === 'syncConfig' || k === 'bslFallbackCatIds' || k === 'gallery' || k === 'listImageEdit' || k === 'productSource') {
            fd.append(k, JSON.stringify(data[k]));
        } else {
            fd.append(k, typeof data[k]==='boolean' ? (data[k]?'1':'0') : data[k]);
        }
    }

    return fetch('', {method:'POST', body:fd})
        .then(r => r.json())
        .then(d => {
            if (d.ok) {
                markClean(d.key);
                window._userClearedProducts = false;
                window._userPrunedProducts = false;
                currentProfileUpdatedAt=parseInt(d.updated_at||0)||Math.floor(Date.now()/1000);
                currentProfileUrl=data.url;profileFormReady=true;
                rememberProfile(data.url, d.key);
                if(d.matrix_repriced&&d.matrix_repriced.changed)try{syncMatrixLoad(window._smPage||1,true)}catch(e){}
                const existingIdx = profiles.findIndex(p => p && (p.key === d.key || (!hasActiveKey && p.url === data.url)));
                const oldEntry=existingIdx>=0?profiles[existingIdx]:{};
                const pCount = (typeof d.product_count === 'number') ? d.product_count : (oldEntry.productCount || products.size || 0);
                const entry = {key: d.key, name: oldEntry.name || data.name || parseUrlHost(data.url), url: data.url, updatedAt: currentProfileUpdatedAt, productCount: pCount};
                if (existingIdx >= 0) {
                    profiles[existingIdx] = entry;
                } else {
                    profiles.unshift(entry);
                }
                renderProfileDropdown();
                setProfileSelectValue(d.key);
                scheduleStartBreakdownRefresh();
            } else if(d.error==='stale_profile') {
                profileFormReady=false;
                clearTimeout(saveTimer);
                showToast('پروفایل در سرور تغییر کرده؛ برای جلوگیری از بازنویسی، ذخیرهٔ خودکار متوقف شد.',true);
            }
            return d;
        })
        .catch(e => ({ok:false,error:(e&&e.message)||'network_error'}));
}

function parseUrlHost(url) {
    try { return new URL(url).host; } catch(e) { return url; }
}

function saveProfile() {
    const data = collectProfileData();
    if (!data.url) {
        showToast('URL وارد کنید', true);
        return;
    }

    const activeEntry = (currentProfileKey && Array.isArray(profiles)) ? profiles.find(p => p && p.key === currentProfileKey) : null;
    const hasActiveKey = !!activeEntry;

    if (!data.name) {
        data.name = (activeEntry && activeEntry.name) ? activeEntry.name : parseUrlHost(data.url);
        $('profileName').value = data.name;
    }

    const fd = new FormData();
    fd.append('action', 'save_profile');
    if (hasActiveKey) {
        fd.append('target_key', currentProfileKey);
        if (!profileFormReady) {
            fd.append('partial_meta_only', '1');
        }
    }
    if (window._userClearedProducts) {
        fd.append('allow_empty_products', '1');
    }
    if (window._userPrunedProducts) {
        fd.append('allow_shrink_products', '1');
    }
    for (const k in data) {
        // v7.66: syncConfig must also be JSON.stringify'd — otherwise "[object Object]"
        if (k === 'selectors' || k === 'detailSelectors' || k === 'products' || k === 'productsOrder' || k === 'syncConfig' || k === 'bslFallbackCatIds' || k === 'gallery' || k === 'listImageEdit' || k === 'productSource') {
            fd.append(k, JSON.stringify(data[k]));
        } else {
            fd.append(k, typeof data[k]==='boolean' ? (data[k]?'1':'0') : data[k]);
        }
    }

    fetch('', {method:'POST', body:fd})
        .then(r => r.json())
        .then(d => {
            if (d.ok) {
                const wasPartialOnly = hasActiveKey && !profileFormReady;
                markClean(d.key);
                window._userClearedProducts = false;
                window._userPrunedProducts = false;
                currentProfileUrl=data.url;
                currentProfileUpdatedAt=parseInt(d.updated_at||0)||Math.floor(Date.now()/1000);
                if (!wasPartialOnly) profileFormReady=true;
                rememberProfile(data.url,d.key);
                if(d.matrix_repriced&&d.matrix_repriced.changed)try{syncMatrixLoad(window._smPage||1,true)}catch(e){}
                const existingIdx = profiles.findIndex(p => p && (p.key === d.key || (!hasActiveKey && p.url === data.url)));
                const oldP = existingIdx >= 0 ? profiles[existingIdx] : {};
                const pCount = (typeof d.product_count === 'number') ? d.product_count : (oldP.productCount || products.size || 0);
                const entry = {key: d.key, name: d.name || data.name, url: data.url, updatedAt: currentProfileUpdatedAt, productCount: pCount};
                if (existingIdx >= 0) {
                    profiles[existingIdx] = entry;
                } else {
                    profiles.unshift(entry);
                }
                renderProfileDropdown();
                setProfileSelectValue(d.key);
                scheduleStartBreakdownRefresh();
                if (wasPartialOnly) {
                    loadProfileFromServer(d.key, true);
                }
                // v7.66: Show selector status after save
                if(d.has_selectors || (data.selectors && data.selectors.container)){
                    showToast('✓ روی همین پروفایل ذخیره شد — سلکتورها فعال ✓');
                }else{
                    showToast('✓ روی پروفایل ذخیره شد');
                }
                fxOkFlash('profileName');     // v10.07: تأییدِ دیداریِ ذخیره
            } else {
                showToast('خطا: ' + (d.error || ''), true);
                fxErrFlash('profileName');    // v10.07
            }
        })
        .catch(() => showToast('خطا در ارتباط', true));
}

let _dupSourceProfileKey = '';
function suggestDuplicateProfileNameJs(srcName) {
    const clean = String(srcName || 'پروفایل').replace(/\s*\(کپی(?:\s*[^\)]*)?\)\s*$/u, '').trim() || 'پروفایل';
    const existing = new Set((Array.isArray(profiles) ? profiles : []).map(p => String((p && p.name) || '').trim()).filter(Boolean));
    let cand = clean + ' (کپی)';
    let n = 2;
    while (existing.has(cand) && n < 200) {
        cand = clean + ' (کپی ' + toFa(n) + ')';
        n++;
    }
    return cand;
}

function openDuplicateProfileModal(explicitKey, selectAfterDefault) {
    const selVal = (($('profileSelect') || {}).value || '').trim();
    const targetRef = explicitKey || currentProfileKey || selVal || (($('url') || {}).value || '').trim();
    const src = findProfileEntryJs(targetRef);
    if (!src || !src.key) {
        showToast('⚠️ ابتدا یک پروفایل ذخیره‌شده را انتخاب کنید تا از آن کپی ساخته شود', true);
        return;
    }
    _dupSourceProfileKey = src.key;
    const modal = $('dupProfileModal');
    if (!modal) return;
    let pCount = parseInt(src.productCount || 0) || 0;
    if (!pCount && currentProfileKey === src.key && products && products.size > 0) pCount = products.size;
    if (!pCount && startProductOverviewData && Array.isArray(startProductOverviewData.by_profile)) {
        const ovRow = startProductOverviewData.by_profile.find(r => r && r.key === src.key);
        if (ovRow && ovRow.counts) pCount = parseInt(ovRow.counts.total || 0) || 0;
    }
    const badge = $('dupProfileSourceBadge');
    if (badge) {
        badge.innerHTML = 'پروفایل مبدأ: <b style="color:#fff">' + esc(src.name || src.key) + '</b>'
            + (src.url ? ' <span dir="ltr" style="color:#94a3b8;font-size:10px">(' + esc(src.url) + ')</span>' : '');
    }
    const nameEl = $('dupProfileName');
    const urlEl = $('dupProfileUrl');
    const incEl = $('dupIncludeProducts');
    const cntHint = $('dupProductsCountHint');
    const selAfterEl = $('dupSelectAfterCreate');
    if (nameEl) nameEl.value = suggestDuplicateProfileNameJs(src.name || src.key);
    if (urlEl) urlEl.value = src.url || '';
    if (incEl) incEl.checked = true;
    if (cntHint) cntHint.textContent = pCount > 0 ? ('(' + toFa(pCount) + ' محصول فعلی)') : '(بدون محصول ذخیره‌شده)';
    if (selAfterEl) selAfterEl.checked = (selectAfterDefault === undefined ? true : !!selectAfterDefault);
    modal.style.display = 'flex';
    setTimeout(() => { if (nameEl) { nameEl.focus(); nameEl.select(); } }, 40);
}

function closeDuplicateProfileModal() {
    const modal = $('dupProfileModal');
    if (modal) modal.style.display = 'none';
}

function duplicateStartBreakdownProfile(btn) {
    const key = String((btn && btn.dataset.dupProfile) || '').trim();
    if (!key) return;
    openDuplicateProfileModal(key, true);
}

function confirmDuplicateProfile() {
    if (!_dupSourceProfileKey) { closeDuplicateProfileModal(); return; }
    const btn = $('dupConfirmBtn');
    const newName = (($('dupProfileName') || {}).value || '').trim();
    const newUrl = (($('dupProfileUrl') || {}).value || '').trim();
    const incProds = !($('dupIncludeProducts')) || !!$('dupIncludeProducts').checked;
    const selectAfter = !($('dupSelectAfterCreate')) || !!$('dupSelectAfterCreate').checked;
    if (newUrl && !/^https?:\/\/[^\s/$.?#].[^\s]*$/i.test(newUrl)) {
        showToast('⚠️ لینک آدرس واردشده معتبر نیست (با http:// یا https:// شروع شود)', true);
        return;
    }
    const executeDup = () => {
        if (btn) { btn.disabled = true; btn.textContent = '⏳ در حال ساخت کپی…'; }
        const fd = new FormData();
        fd.append('action', 'duplicate_profile');
        fd.append('source_key', _dupSourceProfileKey);
        if (newName) fd.append('name', newName);
        if (newUrl) fd.append('new_url', newUrl);
        fd.append('include_products', incProds ? '1' : '0');
        fd.append('return_full', selectAfter ? '1' : '0');
        fetch('', { method: 'POST', body: fd, cache: 'no-store' })
            .then(r => r.json())
            .then(d => {
                if (!d || !d.ok || !d.key) {
                    showToast('خطا در داپلیکیت پروفایل: ' + ((d && d.error) || 'نامشخص'), true);
                    return;
                }
                const sum = d.profile_summary || {};
                const entry = {
                    key: d.key,
                    name: sum.name || newName || d.key,
                    url: sum.url || newUrl || '',
                    updatedAt: parseInt(sum.updatedAt || 0) || Math.floor(Date.now() / 1000),
                    productCount: parseInt(sum.productCount || 0) || 0,
                };
                const idx = profiles.findIndex(p => p && p.key === d.key);
                if (idx >= 0) profiles[idx] = entry;
                else profiles.unshift(entry);
                closeDuplicateProfileModal();
                renderProfileDropdown();
                if (selectAfter) {
                    if (d.profile) {
                        clearTimeout(saveTimer);
                        profileLoadSeq++;
                        window._applyingProfileKey = d.key;
                        try {
                            applyProfile(d.profile, true);
                        } finally {
                            window._applyingProfileKey = '';
                        }
                        currentProfileKey = d.key;
                        currentProfileUrl = d.profile.url || entry.url || '';
                        currentProfileUpdatedAt = parseInt(d.profile.updatedAt || entry.updatedAt || 0) || Math.floor(Date.now() / 1000);
                        profileFormReady = true;
                        setProfileSelectValue(d.key);
                        rememberProfile(currentProfileUrl, d.key);
                        updateUrlTargetProfileHint();
                    } else {
                        selectProfile(d.key);
                    }
                }
                clearTimeout(startBreakdownRefreshTimer);
                startProductOverviewBusy = false;
                loadStartProductOverview(true);
                showToast('✓ کپی پروفایل «' + entry.name + '» با موفقیت ساخته شد');
            })
            .catch(() => showToast('خطا در ارتباط هنگام ساخت کپی پروفایل', true))
            .finally(() => {
                if (btn) { btn.disabled = false; btn.textContent = '📋 ایجاد کپی پروفایل'; }
            });
    };
    if (isDirty && currentProfileKey === _dupSourceProfileKey && typeof saveProfileSilent === 'function' && profileFormReady) {
        clearTimeout(saveTimer);
        saveProfileSilent().finally(executeDup);
    } else {
        executeDup();
    }
}

document.addEventListener('keydown', e => {
    if (e.key === 'Escape') {
        const m = $('dupProfileModal');
        if (m && m.style.display !== 'none') closeDuplicateProfileModal();
    }
});

function purgeDeletedProfileClientState(deletedKey, deletedUrl) {
    clearTimeout(saveTimer);
    profiles = profiles.filter(p => {
        if (!p) return false;
        if (deletedKey) return p.key !== deletedKey;
        if (deletedUrl && p.url === deletedUrl) return false;
        return true;
    });
    const curUrl = (($('url')||{}).value || '').trim();
    const isActiveProfile = deletedKey
        ? (currentProfileKey === deletedKey)
        : !!(deletedUrl && (curUrl === deletedUrl || currentProfileUrl === deletedUrl));
    if (isActiveProfile) {
        profileFormReady = false;
        isDirty = false;
        currentProfileKey = null;
        currentProfileUrl = '';
        currentProfileUpdatedAt = 0;
        if ($('url')) $('url').value = '';
        if ($('profileName')) $('profileName').value = '';
        try { listImgEditApply({}); galApply({}); } catch (e) {}
        products.clear();
        order = [];
        try { refreshViews(); update(); } catch (e) {}
        setProfileSelectValue('');
        const s = $('profileStatus');
        if (s) { s.textContent = 'جدید'; s.className = 'profile-indicator unsaved'; }
        updateUrlTargetProfileHint();
    }
    const stillHasUrl = deletedUrl && profiles.some(p => p && p.url === deletedUrl);
    if ((!stillHasUrl && deletedUrl && lastProfileUrl() === deletedUrl) || isActiveProfile) forgetProfile();
    renderProfileDropdown();
    if (startProductOverviewData && Array.isArray(startProductOverviewData.by_profile)) {
        startProductOverviewData.by_profile = startProductOverviewData.by_profile.filter(r => r && r.key !== deletedKey);
        startProductOverviewData.profiles = startProductOverviewData.by_profile.length;
        renderStartProfileBreakdown(startProductOverviewData);
    }
    clearTimeout(startBreakdownRefreshTimer);
    startProductOverviewBusy = false;
    loadStartProductOverview(true);
}

function deleteStartBreakdownProfile(btn) {
    const key = String((btn && btn.dataset.delProfile) || '').trim();
    const name = String((btn && btn.dataset.delName) || key).trim();
    if (!key) return;
    if (!confirm('پروفایل «' + name + '» و آمار آن به‌طور کامل حذف شود؟')) return;
    btn.disabled = true;
    const found = profiles.find(p => p && p.key === key) || {};
    const fd = new FormData();
    fd.append('action', 'delete_profile');
    fd.append('key', key);
    if (found.url) fd.append('url', found.url);
    fetch('', {method:'POST', body:fd, cache:'no-store'})
        .then(r => r.json())
        .then(d => {
            if (d && d.ok) {
                purgeDeletedProfileClientState(d.key || key, d.url || found.url || '');
                showToast('✓ پروفایل «' + name + '» حذف شد');
            } else {
                btn.disabled = false;
                showToast('خطا: ' + ((d && d.error) || ''), true);
            }
        })
        .catch(() => { btn.disabled = false; showToast('خطا در حذف پروفایل', true); });
}

function deleteProfile() {
    const url = $('url').value.trim();
    const matched = (currentProfileKey && profiles.find(p => p.key === currentProfileKey))
        || (url && profiles.find(p => p.url === url))
        || null;
    const key = (matched && matched.key) || currentProfileKey || '';
    if (!url && !key) {
        showToast('URL وارد کنید', true);
        return;
    }
    if (!confirm('حذف این پروفایل؟')) return;
    clearTimeout(saveTimer);
    profileFormReady = false;

    const fd = new FormData();
    fd.append('action', 'delete_profile');
    if (url) fd.append('url', url);
    if (key) fd.append('key', key);

    fetch('', {method:'POST', body:fd, cache:'no-store'})
        .then(r => r.json())
        .then(d => {
            if (d.ok) {
                purgeDeletedProfileClientState(d.key || key, d.url || url);
                showToast('✓ حذف شد');
            } else {
                showToast('خطا: ' + (d.error || ''), true);
            }
        })
        .catch(() => showToast('خطا', true));
}

function setMode(m){
  mode=m;
  document.querySelectorAll('.mode-tab').forEach((t,i)=>t.classList.toggle('active',(i===0&&m==='auto')||(i===1&&m==='visual')));
  $('autoCtrl').classList.toggle('hidden',m!=='auto');
  $('visualCtrl').classList.toggle('hidden',m!=='visual');

  if (m === 'visual') {
      switchMainTab('selectors');
  }
}

function setDetailIframeHeight(h){const w=$('detailFrameWrap');if(!w)return;h=Math.max(300,parseInt(h)||600);w.style.height=h+'px';$('detailIframeSizeVal').textContent=toFa(h);const s=$('detailIframeSlider');if(s&&String(s.value)!==String(h))s.value=h;}

/* =====================================================================
 *  v8.68: کنترل‌های انتخابگر، بیرون از پنجرهٔ پیش‌نمایش
 *
 *  نوار قبلی داخل خودِ iframe بود و با padding-top حدود ۱۳۰ پیکسل از
 *  ارتفاع صفحهٔ محصول را می‌خورد. حالا کنترل‌ها در پنل والد هستند و از
 *  طریق postMessage با صفحه حرف می‌زنند.
 * ===================================================================== */
function pkFrame(){ const f=$('detailFrame'); return f&&f.contentWindow?f.contentWindow:null; }
function pkSend(type,extra){ const w=pkFrame(); if(w)try{w.postMessage(Object.assign({type},extra||{}),'*');}catch(e){} }

/* v8.76: راهنما و دکمهٔ گالری از فرستادن فرمان جدا شدند، چون وقتی خودِ
   صفحه فیلد را عوض کرده باشد فقط باید متن به‌روز شود، نه فرمان دوباره. */
function pkModeHint(m){
  const hints={
    galleryBox:'🖼 روی ظرفی کلیک کنید که همهٔ عکس‌ها داخلش هستند (نه خود عکس). با ⬆ والد بزرگ‌ترش کنید تا همهٔ عکس‌ها صورتی شوند.',
    galleryOne:'➕ روی هر عکسی که می‌خواهید کلیک کنید — چند بار. هر کدام به فهرست اضافه می‌شود.',
    variations:'🎨 روی ظرفی کلیک کنید که گزینه‌های رنگ یا سایز داخلش هستند (select، دکمه‌ها یا فهرست).',
    image:'🌆 روی عکس اصلی محصول کلیک کنید.',
    price:'💰 روی قیمتِ نهایی محصول کلیک کنید (اگر تخفیف دارد، روی عددِ پس از تخفیف). قیمتِ صفحهٔ محصول جای قیمتِ صفحهٔ فهرست را می‌گیرد.'
  };
  const h=$('pkHint');
  if(h)h.innerHTML=(hints[m]||'روی هر بخش از صفحهٔ زیر کلیک کنید.')
    +' <span style="color:#c4b5fd">همهٔ کنترل‌ها بالای همان المان هستند — '
    +'<b>↑</b> والد، <b>↓</b> فرزند، <b>→ ←</b> کناری‌ها، <b>Tab</b> فیلد بعدی، '
    +'<b>Space</b> ثبت و بعدی، <b>Esc</b> پاک کردن، <b>Enter</b> اتمام.</span>';
  const cg=$('pkClearGal'); if(cg)cg.style.display=(m==='galleryOne')?'':'none';
}
function pkSetMode(m){
  pkSend('picker_mode',{mode:m});
  pkModeHint(m);
}
function pkGo(dir){ pkSend('picker_go',{dir}); }
function pkClearGal(){ pkSend('picker_clear_gal',{}); }

/* v8.75: رفتن به فیلد بعدیِ پرنشده — تا لازم نباشد هر بار سراغ فهرست بروید */
function pkNextField(){
  const sel=$('pkMode'); if(!sel)return;
  const opts=[...sel.options].map(o=>o.value);
  const filled=new Set(Object.keys(pkFilled||{}));
  const cur=opts.indexOf(sel.value);
  for(let i=1;i<=opts.length;i++){
    const v=opts[(cur+i)%opts.length];
    if(!filled.has(v)){ sel.value=v; pkSetMode(v); return; }
  }
  showToast('همهٔ فیلدها انتخاب شده‌اند ✓');
}

/* v8.75: نشان دادن اینکه چه چیزهایی تا حالا انتخاب شده */
var pkFilled={};
function pkRenderChips(){
  const box=$('pkChips'); if(!box)return;
  const sel=$('pkMode'); if(!sel)return;
  let h='';
  [...sel.options].forEach(o=>{
    const on=!!pkFilled[o.value];
    const label=o.textContent.replace(/^[^\s]+\s/,'');
    h+='<span onclick="$(\'pkMode\').value=\''+o.value+'\';pkSetMode(\''+o.value+'\')" '
      +'style="cursor:pointer;font-size:10px;padding:2px 7px;border-radius:10px;'
      +'border:1px solid '+(on?'#22c55e':'#475569')+';color:'+(on?'#86efac':'#64748b')+';'
      +'background:'+(on?'#14532d40':'transparent')+'">'+(on?'✓ ':'')+esc(label)+'</span>';
  });
  box.innerHTML=h;
}
function pkDone(){ pkSend('picker_done',{}); }
function pkClose(){
  $('detailFrameWrap').classList.add('hidden');
  $('detailFrame').src='about:blank';
  const p=$('pickerPanel'); if(p)p.classList.add('hidden');
  const cb=$('pkCtlBar');    if(cb)cb.classList.add('hidden');   // v9.90
}

/** وضعیتی که iframe گزارش می‌دهد را روی پنل می‌نشاند */
function pkApplyState(st){
  const set=(id,v)=>{const e=$(id);if(e)e.textContent=v;};
  set('pkSel', st.sel||'—');
  set('pkTag', st.tag||'-');
  /* v8.85: برای تنوع‌ها، به‌جای یک خط متن، همان خروجی نهایی را
     گزینه‌به‌گزینه نشان بده — این دقیقاً همان چیزی است که ذخیره و به
     ووکامرس/باسلام فرستاده می‌شود. */
  const c=$('pkPrev2');
  if(st.mode==='variations'&&Array.isArray(st.vars)){
    if(st.vars.length){
      const ni=parseInt(st.varImgs||st.imgs||0,10)||0;
      let vh='<div style="color:#c4b5fd;font-size:10px;margin-bottom:3px">'
        +'✅ خروجی نهایی — '+toFa(st.vars.length)+' گزینه'
        +(ni?(' · 🖼 '+toFa(ni)+' عکس → گالری'):'')
        +' <span style="color:#64748b">(مقادیر + تصاویر سواچ ذخیره می‌شوند)</span></div>'
        +'<div style="display:flex;gap:3px;flex-wrap:wrap">';
      st.vars.forEach(v=>{
        vh+='<span style="background:#1e1b4b;border:1px solid #6d28d9;color:#e9d5ff;'
          +'border-radius:10px;padding:1px 7px;font-size:10px">'+esc(v)+'</span>';
      });
      vh+='</div><div style="margin-top:4px;font-size:9.5px;color:#64748b;direction:ltr;'
        +'text-align:left;word-break:break-all">'+esc(st.vars.join('، '))+'</div>';
      if(c){c.innerHTML=vh;c.style.color='';}
    }else if(c){
      c.textContent='⚠ هیچ گزینه‌ای پیدا نشد — ظرف دیگری را امتحان کنید (⬆ والد)';
      c.style.color='#fbbf24';
    }
  }else{
    set('pkPrev2', st.preview||'(خالی)');
    if(c)c.style.color=st.preview?'#86efac':'#fbbf24';
  }
  let cnt='';
  if(st.mode==='galleryBox')      cnt='🖼 '+toFa(st.imgs||0)+' عکس'+((st.matches||0)>1?(' · '+toFa(st.matches)+' ظرف'):'');
  else if(st.mode==='galleryOne') cnt='➕ '+toFa(st.imgs||0)+' عکس · '+toFa((st.gal||[]).length)+' سلکتور';
  else if(st.mode==='variations') cnt=(st.vars&&st.vars.length? (toFa(st.vars.length)+' گزینه') :'')+((st.varImgs||st.imgs)?(' · 🖼 '+toFa(st.varImgs||st.imgs)+' → گالری'):'');
  else if((st.matches||0)>1)      cnt='⚠ '+toFa(st.matches)+' تطبیق';
  set('pkCnt', cnt);
  const nav=st.nav||{};
  /* v9.90: دکمه‌های هم‌سطح برگشتند. صفحه از قبل prev/next را گزارش می‌کرد
     ولی پنل نادیده‌شان می‌گرفت (v8.77 آن‌ها را حذف کرده بود). */
  [['pkUp','up'],['pkDown','down'],['pkPrev','prev'],['pkNext','next']].forEach(([id,k])=>{
    const b=$(id); if(b)b.disabled=!nav[k];
  });
  // v8.75: کدام فیلدها تا حالا پر شده‌اند
  pkFilled={};
  const all=st.all||{};
  for(const k in all){ if(String(all[k]||'').trim()!=='')pkFilled[k]=1; }
  pkRenderChips();
  const n=Object.keys(pkFilled).length;
  const pb=$('pkProgress');
  if(pb)pb.textContent=n?('✓ '+toFa(n)+' فیلد انتخاب شده'):'';
}
function setIframeHeight(h){const w=$('iframeWrap');if(!w)return;w.style.height=h+'px';$('iframeSizeVal').textContent=h;scheduleSave();}

/* =====================================================================
 *  v8.77: کنترل‌های بیرونی پیش‌نمایش فهرست محصولات.
 *  سلکتور جزئیات از ۸.۶۸ پنل بیرونی داشت ولی این یکی نداشت و همهٔ
 *  کارها فقط از نوار داخل صفحه انجام می‌شد. پروتکل پیام همان است.
 * ===================================================================== */
const VP_FIELDS=[['container','کانتینر'],['title','عنوان'],['price','قیمت'],
                 ['link','لینک'],['image','تصویر']];
function vpFrame(){ const f=$('vFrame'); return f&&f.contentWindow?f.contentWindow:null; }
function vpSend(type,extra){ const w=vpFrame(); if(w)try{w.postMessage(Object.assign({type},extra||{}),'*');}catch(e){} }
function vpSetMode(m){ vpSend('vp_mode',{mode:m}); }
function vpGo(dir){ vpSend('vp_go',{dir}); }

/* =====================================================================
 *  v9.90: نمایش/پنهان‌کردن دسته‌های کنترلِ سلکتور.
 *  سه دستهٔ کنترل (پنل بیرونی، نوار شناور کنار المان، نوار بالای صفحه)
 *  با هم ارتفاع زیادی می‌گرفتند و روی نمایشگر کوچک چیزی از خودِ صفحه
 *  باقی نمی‌ماند. هرکدام حالا یک تیک دارد. دسته‌هایی که داخل iframe
 *  هستند با postMessage خبردار می‌شوند، بقیه مستقیم کلاس hidden می‌گیرند.
 *  انتخاب کاربر در localStorage می‌ماند تا هر بار تکرار نشود.
 * ===================================================================== */
const SEL_CTL_KEY='scraper_selctl';
function selCtlLoad(){
  try{ return JSON.parse(localStorage.getItem(SEL_CTL_KEY)||'{}')||{}; }catch(e){ return {}; }
}
function selCtlSave(st){
  try{ localStorage.setItem(SEL_CTL_KEY,JSON.stringify(st)); }catch(e){}
}
/** یک دسته را روشن/خاموش کن (بدون ذخیره — برای اعمال اولیه هم استفاده می‌شود) */
function selCtlApply(key,on){
  const box=id=>{ const n=$(id); if(n)n.classList.toggle('hidden',!on); };
  if(key==='vpPanel')      box('vpPanel');
  else if(key==='pkPanel') box('pickerPanel');
  else if(key==='pkHint'){ box('pkHint'); box('pkChips'); box('pkProgress'); }
  else if(key==='vpPop')   vpSend('vp_popbar',{on:!!on});
  else if(key==='vpTop')   vpSend('vp_topbar',{on:!!on});
  else if(key==='pkPop')   pkSend('picker_popbar',{on:!!on});
}
function selCtlToggle(key,on){
  const st=selCtlLoad(); st[key]=!!on; selCtlSave(st);
  selCtlApply(key,!!on);
}
/** وضعیت ذخیره‌شده را روی تیک‌ها و خود کنترل‌ها بنشان */
function selCtlInit(){
  const st=selCtlLoad();
  [['vpPanel','ctlVpPanel'],['vpPop','ctlVpPop'],['vpTop','ctlVpTop'],
   ['pkPanel','ctlPkPanel'],['pkPop','ctlPkPop'],['pkHint','ctlPkHint']]
  .forEach(([key,boxId])=>{
    const on = (st[key]===undefined) ? true : !!st[key];   // پیش‌فرض: روشن
    const cb=$(boxId); if(cb)cb.checked=on;
    selCtlApply(key,on);
  });
}
/** بعد از آمادهٔ‌شدن هر iframe دوباره اعمال کن — پیام قبل از ready گم می‌شود */
function selCtlSyncFrame(which){
  const st=selCtlLoad(), get=k=>(st[k]===undefined?true:!!st[k]);
  if(which==='vp'){ selCtlApply('vpPop',get('vpPop')); selCtlApply('vpTop',get('vpTop')); }
  else            { selCtlApply('pkPop',get('pkPop')); }
}

var vpFilled={};
function vpNextField(){
  const sel=$('vpMode'); if(!sel)return;
  const opts=[...sel.options].map(o=>o.value);
  const cur=opts.indexOf(sel.value);
  for(let i=1;i<=opts.length;i++){
    const v=opts[(cur+i)%opts.length];
    if(!vpFilled[v]){ sel.value=v; vpSetMode(v); return; }
  }
  showToast('همهٔ سلکتورها انتخاب شده‌اند ✓');
}
function vpRenderChips(){
  const box=$('vpChips'); if(!box)return;
  let h='';
  VP_FIELDS.forEach(([k,label])=>{
    const on=!!vpFilled[k];
    h+='<span onclick="$(\'vpMode\').value=\''+k+'\';vpSetMode(\''+k+'\')" '
      +'style="cursor:pointer;font-size:10px;padding:2px 7px;border-radius:10px;'
      +'border:1px solid '+(on?'#22c55e':'#475569')+';color:'+(on?'#86efac':'#64748b')+';'
      +'background:'+(on?'#14532d40':'transparent')+'">'+(on?'✓ ':'')+esc(label)+'</span>';
  });
  box.innerHTML=h;
}
/** وضعیتی که iframe فهرست گزارش می‌دهد را روی پنل می‌نشاند */
function vpApplyState(st){
  const set=(id,v)=>{const e=$(id);if(e)e.textContent=v;};
  set('vpSel', st.sel||'—');
  set('vpTag', st.tag||'-');
  set('vpPv',  st.preview||'(خالی)');
  const c=$('vpPv'); if(c)c.style.color=st.preview?'#86efac':'#fbbf24';
  set('vpCnt', (st.matches||0)>1?('🔢 '+toFa(st.matches)+' مشابه'):'');
  const nav=st.nav||{};
  // v9.90: قبلی/بعدی هم به فهرست اضافه شدند
  [['vpUp','up'],['vpDown','down'],['vpPrev','prev'],['vpNext','next']].forEach(([id,k])=>{
    const b=$(id); if(b)b.disabled=!nav[k];
  });
  vpFilled={};
  const all=st.all||{};
  for(const k in all){ if(String(all[k]||'').trim()!=='')vpFilled[k]=1; }
  vpRenderChips();
  const ms=$('vpMode'); if(ms&&st.mode&&ms.value!==st.mode)ms.value=st.mode;
}

let selectorFsPaused=false;
function selectorFsPauseType(){return selectorFsState&&selectorFsState.kind==='detail'?'picker_pause':'vp_pause';}
function selectorFsFrameWin(){const fr=$('selectorFsFrame');return fr&&fr.contentWindow?fr.contentWindow:null;}
function selectorFsSendPause(){const w=selectorFsFrameWin();if(w)try{w.postMessage({type:selectorFsPauseType(),on:selectorFsPaused},'*');}catch(e){}}
function selectorFsUpdatePauseBtn(){const b=$('selectorFsPauseBtn');if(!b)return;b.classList.toggle('__on',selectorFsPaused);b.innerHTML=(selectorFsPaused?'▶ <span class="txt">فعال‌سازی انتخاب</span>':'⏸ <span class="txt">توقف انتخاب</span>');}
function selectorFsTogglePause(){selectorFsPaused=!selectorFsPaused;selectorFsUpdatePauseBtn();selectorFsSendPause();showToast(selectorFsPaused?'انتخاب موقتاً متوقف شد — حالا با صفحه تعامل کنید':'انتخاب دوباره فعال شد');}
function selectorSyncWait(v){const ms=String(Math.max(0,Math.min(30000,parseInt(v)||0)));['selectorWaitMs','selectorFsWait'].forEach(id=>{const el=$(id);if(el&&el.value!==ms)el.value=ms;});}
function selectorWaitValue(){const modal=$('selectorFsModal'),fs=$('selectorFsWait'),main=$('selectorWaitMs');let el=(modal&&modal.style.display!=='none'&&fs)?fs:main;if(!el&&fs)el=fs;const ms=Math.max(0,Math.min(30000,parseInt(el&&el.value)||0));selectorSyncWait(ms);return ms;}
function selectorWaitParam(){const ms=selectorWaitValue();return ms>0?'&wait_ms='+ms:'';}
function selectorFsBuildSrc(kind){
    if(kind==='detail'){
        const sampleUrl=detailSampleUrl(); if(!sampleUrl)return'';
        const _pk=profileKey(($('profileSelect')&&$('profileSelect').value)||($('url')&&$('url').value.trim())||'');
        return '?detail_proxy='+encodeURIComponent(sampleUrl)+'&pk='+encodeURIComponent(_pk)+selectorWaitParam();
    }
    const url=$('url').value.trim(); if(!url){showToast('URL وارد کنید',true);return'';}
    const full=$('fullMode')&&$('fullMode').checked?'&full=1':'';
    const _pk=profileKey(url);
    return '?visual_proxy='+encodeURIComponent(url)+full+'&pk='+encodeURIComponent(_pk)+selectorWaitParam();
}
function selectorFsOpen(kind){
    selectorSyncWait(selectorWaitValue());
    const src=selectorFsBuildSrc(kind||'list'); if(!src)return;
    selectorFsState={kind:kind||'list',src:src,inline:false};
    selectorFsPaused=false; selectorFsUpdatePauseBtn();
    const m=$('selectorFsModal'), fr=$('selectorFsFrame'), title=$('selectorFsTitle'), hint=$('selectorFsHint');
    if(title)title.textContent=(kind==='detail'?'📄 نمونه جزئیات':'🧾 لیست محصولات');
    if(hint){hint.innerHTML='';hint.style.display='none';}
    if(fr){fr.src='about:blank';setTimeout(()=>{fr.src=src;},30);}
    if(m){m.style.display='flex';document.body.classList.add('modal-open');}
    if(kind==='detail'){
        renderSampleBar();
        const pp=$('pickerPanel'); if(pp)pp.classList.remove('hidden');
    }else{
        const d=$('directLoadBanner'); if(d)d.classList.add('hidden');
    }
}
function selectorFsClose(){const m=$('selectorFsModal');if(m)m.style.display='none';const fr=$('selectorFsFrame');if(fr)fr.src='about:blank';document.body.classList.remove('modal-open');}
function selectorFsReload(){const fr=$('selectorFsFrame');if(fr&&selectorFsState.src){selectorFsPaused=false;selectorFsUpdatePauseBtn();fr.src='about:blank';setTimeout(()=>{fr.src=selectorFsState.src;},30);}}
function selectorFsUseInline(){
    if(selectorFsState.kind==='detail'){
        const fr=$('detailFrame'); if(fr){$('detailFrameWrap').classList.remove('hidden');fr.src=selectorFsState.src;}
    }else{
        const fr=$('vFrame'); if(fr)fr.src=selectorFsState.src;
    }
    showToast('صفحه در پنل داخلی هم نمایش داده شد');
}
function selectorFsOpenNewTab(){if(selectorFsState.src){const w=window.open(selectorFsState.src,'_blank');if(!w)showToast('پاپ‌آپ مسدود شد',true);}}

function loadVisual(){
  const url=$('url').value.trim();
  if(!url){showToast('URL وارد کنید',true);return;}
  $('status').textContent='در حال بارگذاری...';
  $('directLoadBanner').classList.add('hidden');
  const full=$('fullMode')&&$('fullMode').checked?'&full=1':'';
  // v9.75: اتصالِ این صفحه را مطابق «اتصال غیرمستقیم»ِ پروفایلِ فعلی بگذار (خاموش = مستقیم)
  const _pk=profileKey(url);
  $('vFrame').src='?visual_proxy='+encodeURIComponent(url)+full+'&pk='+encodeURIComponent(_pk)+selectorWaitParam();
  $('vFrame').onload=()=>{
      if($('fullMode')&&$('fullMode').checked){
          $('status').textContent='⏳ رندر JS... صبر کنید';
          setTimeout(()=>{$('status').textContent='✓ آماده | ⬆ اسکرول بیشتر | 🔄 اسکرول خودکار';showToast('از ⬆🔄 برای بارگذاری بیشتر استفاده کنید');},3000);
      } else {
          $('status').textContent='✓ روی المان‌ها کلیک کنید';
          showToast('صفحه آماده');
      }
  };
}

function suggestSelectors(){
  const url=$('url').value.trim();
  if(!url){showToast('URL وارد کنید',true);return;}
  $('status').textContent='در حال تحلیل...';

  fetch('?suggest_selectors='+encodeURIComponent(url))
    .then(r=>r.json())
    .then(d=>{
      if(!d.ok){$('status').textContent='خطا: '+d.error;return;}
      $('suggestions').classList.remove('hidden');
      let html='';

      if(d.suggestions.container.length){
        html+='<div style="font-size:11px;color:#67e8f9;padding:6px 8px">📦 کانتینر:</div>';
        d.suggestions.container.forEach(s=>{
          html+=`<div class="suggest-item" onclick="setSel('container','${s.selector}')">${s.selector} <span style="color:#64748b">(${s.count})</span></div>`;
        });
      }

      html+='<div style="font-size:11px;color:#67e8f9;padding:6px 8px;border-top:1px solid #334155">📝 عنوان:</div>';
      d.suggestions.title.slice(0,5).forEach(s=>{
        html+=`<div class="suggest-item" onclick="setSel('title','${s.selector}')">${s.selector}</div>`;
      });

      html+='<div style="font-size:11px;color:#67e8f9;padding:6px 8px;border-top:1px solid #334155">💰 قیمت:</div>';
      d.suggestions.price.slice(0,4).forEach(s=>{
        html+=`<div class="suggest-item" onclick="setSel('price','${s.selector}')">${s.selector}</div>`;
      });

      $('suggestList').innerHTML=html;
      $('status').textContent='✓ پیشنهادها آماده';
      showToast('پیشنهادها در پنل کناری');
    })
    .catch(e=>{$('status').textContent='خطا';showToast('خطا در دریافت',true);});
}

/* ═══════════════════════════════════════════════════════════════════
 *  v10.25 (۳۸ب+۳۸ج): زیرتب‌های تبِ سلکتور + ایجنتِ کشفِ خودکارِ سلکتور
 *
 *  چرا این‌طور نوشته شد:
 *
 *  ۱) زیرتب‌ها — پیش از این، پنج آکاردئونِ تبِ سلکتور پشتِ سرِ هم بودند
 *     و «لیست» و «جزئیات» درهم می‌رفتند. حالا دو پنلِ selsub-list و
 *     selsub-detail داریم و انتخابِ کاربر در localStorage می‌ماند تا با
 *     هر رفرش به زیرتبِ پیش‌فرض برنگردد.
 *
 *  ۲) ایجنت — دکمهٔ «💡 پیشنهاد» قدیمی یک heuristicِ سرور‌سمتی بود که
 *     فقط چند الگوی ثابت (`.product`, `.price`, …) را امتحان می‌کرد.
 *     نسخهٔ ایجنتی به‌جای حدس زدن، صفحه را واقعاً می‌گیرد، نقشهٔ فشردهٔ
 *     DOM را به مدل می‌دهد و مدل با ابزارِ probe_selector هر حدسش را
 *     روی همان صفحه می‌آزماید. بنابراین چیزی که تحویل می‌دهد از قبل
 *     تست‌شده است — نه یک لیستِ آرزویی.
 *
 *  ۳) چرا نظرسنجیِ مشترک: خواستهٔ کاربر این بود که پیشرفت هم در تبِ
 *     سلکتور، هم در تبِ «🤖 ایجنت» و هم در «مدیر وظیفه» دیده شود. اگر
 *     هر نما جداگانه poll می‌زد، سه تایمرِ ناهماهنگ داشتیم و سرور سه
 *     برابر بار می‌گرفت. پس یک تایمرِ واحد (selagTimer) داریم که وضعیت
 *     را می‌گیرد و آن را در هر سه جا رندر می‌کند.
 * ═══════════════════════════════════════════════════════════════════ */

/** زیرتبِ فعالِ تبِ سلکتور: 'list' یا 'detail'. */
let selSubView = 'list';

function selSub(v) {
    if (v !== 'list' && v !== 'detail') v = 'list';
    selSubView = v;
    ['list', 'detail'].forEach(function (k) {
        const pane = $('selsub-' + k);
        if (pane) pane.classList.toggle('hidden', k !== v);
        const btn = $('selsubBtn-' + k);
        if (btn) btn.classList.toggle('active', k === v);
    });
    try { localStorage.setItem('selSubView', v); } catch (e) {}
    /* پنلِ ایجنت باید بعد از سوییچ دوباره کشیده شود، وگرنه اگر کاربر
       وسطِ اجرا زیرتب عوض کند پنلِ مقصد خالی می‌ماند تا تیکِ بعدی. */
    selagRender();
}

function selSubRestore() {
    let v = 'list';
    try { v = localStorage.getItem('selSubView') || 'list'; } catch (e) {}
    selSub(v);
}

/* ── حالتِ ایجنتِ سلکتور ─────────────────────────────────────────── */
let selagState = null;   // آخرین پاسخِ ?selagent_status
let selagLines = [];     // خطوطِ لاگ که تا حالا گرفته‌ایم
let selagTimer = null;   // شناسهٔ setInterval نظرسنجی
let selagKind  = 'list'; // آخرین نوعِ اجرا
let selagLast  = null;   // آخرین نتیجهٔ کامل (?selagent_result)
let selagConvo = [];     // v10.26 (۳۹ب): پیام‌های ردوبدل‌شده با مدل
let selagCSince = 0;     // v10.26 (۳۹ب): چند پیام را تا حالا گرفته‌ایم

/** نشانیِ صفحهٔ فهرست — همان چیزی که در کادرِ بالای صفحه است. */
function selagListUrl() {
    return ($('url') && $('url').value || '').trim();
}

/**
 * نشانیِ صفحه‌ای که باید کاوش شود، بسته به نوعِ کار.
 *
 * v10.27 (۴۰ب): برای «جزئیات» دیگر نبودِ محصول بن‌بست نیست. تا ۱۰.۲۶
 * detailSampleUrl() یک توستِ «ابتدا محصولات را استخراج کنید» می‌داد و
 * کار می‌ایستاد. حالا اگر محصولی نیست ولی آدرسِ صفحهٔ فهرست را داریم،
 * رشتهٔ خالی برمی‌گردانیم و به سرور می‌گوییم خودش زنجیره را کامل کند:
 * ایجنتِ فهرست ← استخراجِ چند محصول ← صفحهٔ نمونه ← سلکتورهای جزئیات.
 */
function selagUrlFor(kind) {
    if (kind === 'detail') {
        const u = detailSampleUrl(true);
        if (u) return u;
        if (selagListUrl()) {
            showToast('هیچ محصولی نیست — ایجنت اول فهرست را استخراج می‌کند');
            return '';   // '' یعنی «بساز»، برخلافِ null که یعنی «نشد»
        }
        detailSampleUrl();   // پیامِ راهنمای همیشگی
        return null;
    }
    const u = selagListUrl();
    if (!u) { showToast('اول آدرسِ صفحهٔ فهرست را وارد کنید', true); return null; }
    return u;
}

/* ====================================================================
 *  v10.30 (۴۳ب): ویرایشگرِ پرامپتِ ایجنتِ کشفِ سلکتور.
 *  حالتِ ذخیره‌شده سمتِ سرور در selagent_prompt.json می‌نشیند، پس این‌جا
 *  فقط فرم را می‌خوانیم/می‌فرستیم و چیزی در localStorage نگه نمی‌داریم.
 * ==================================================================== */
function spromptEl(kind, part) { return document.getElementById('sprompt' + part + '-' + kind); }
/* آدرسِ نمونه برای پیش‌نمایش. عمداً selagUrlFor را صدا نمی‌زنیم چون آن
   وقتی آدرس نیست toastِ خطا می‌دهد، و پیش‌نمایشِ پرامپت اصلاً به آدرسِ
   واقعی نیاز ندارد — فقط جایِ {{url}} را پر می‌کند. */
function spromptUrl(kind) {
    try {
        if (kind === 'detail') { const d = detailSampleUrl(true); if (d) return d; }
        const l = selagListUrl();
        if (l) return l;
    } catch (e) {}
    return '';
}
function spromptMode(kind) {
    const r = document.querySelector('input[name="spmode-' + kind + '"]:checked');
    return r ? r.value : 'append';
}
function spromptMsg(kind, txt, bad) {
    const m = spromptEl(kind, 'Msg');
    if (!m) return;
    m.textContent = txt || '';
    m.style.color = bad ? '#fca5a5' : '#86efac';
}
/** بعد از هر تغییر، برچسبِ بالای پنل را با وضعیتِ ذخیره‌نشده هماهنگ کن. */
function spromptDirty(kind) {
    const b = spromptEl(kind, 'Badge');
    if (b) { b.textContent = 'ذخیره‌نشده'; b.style.borderColor = '#f59e0b'; b.style.color = '#fcd34d'; }
    spromptMsg(kind, '');
}
function spromptIns(kind, token) {
    const t = spromptEl(kind, 'Text');
    if (!t) return;
    const a = t.selectionStart || 0, b = t.selectionEnd || 0;
    t.value = t.value.slice(0, a) + token + t.value.slice(b);
    t.focus();
    t.selectionStart = t.selectionEnd = a + token.length;
    spromptDirty(kind);
}
function spromptOut(kind, txt) {
    const o = spromptEl(kind, 'Out');
    if (!o) return;
    o.textContent = txt;
    o.classList.remove('hidden');
}
function spromptSave(kind) {
    const t = spromptEl(kind, 'Text');
    if (!t) return;
    const fd = new FormData();
    fd.append('kind', kind);
    fd.append('mode', spromptMode(kind));
    fd.append('text', t.value);
    spromptMsg(kind, 'در حالِ ذخیره…');
    fetch('?selagent_prompt_save=1', { method: 'POST', body: fd })
        .then(r => r.json())
        .then(j => {
            if (!j || !j.ok) { spromptMsg(kind, '⚠️ ' + ((j && j.error) || 'ذخیره نشد'), true); return; }
            const md = (j.saved && j.saved.mode) || 'append';
            const on = !!(j.saved && j.saved.text && md !== 'off');
            const b = spromptEl(kind, 'Badge');
            if (b) {
                b.textContent = on ? (md === 'replace' ? 'جایگزینِ سفارشی' : 'افزودهٔ سفارشی') : 'پیش‌فرض';
                b.style.borderColor = ''; b.style.color = '';
            }
            spromptMsg(kind, '✓ ذخیره شد — از اجرای بعدیِ ایجنت اعمال می‌شود');
            if (typeof showToast === 'function') showToast('پرامپتِ ایجنت ذخیره شد');
        })
        .catch(e => spromptMsg(kind, '⚠️ ' + e, true));
}
function spromptPreview(kind) {
    const t = spromptEl(kind, 'Text');
    if (!t) return;
    const fd = new FormData();
    fd.append('kind', kind);
    fd.append('mode', spromptMode(kind));
    fd.append('text', t.value);
    fd.append('url', spromptUrl(kind));
    spromptMsg(kind, 'در حالِ ساختِ پیش‌نمایش…');
    fetch('?selagent_prompt_preview=1', { method: 'POST', body: fd })
        .then(r => r.json())
        .then(j => {
            if (!j || !j.ok) { spromptMsg(kind, '⚠️ پیش‌نمایش ناموفق', true); return; }
            spromptOut(kind, j.prompt);
            spromptMsg(kind, 'پرامپتِ نهایی: ' + j.chars + ' کاراکتر');
        })
        .catch(e => spromptMsg(kind, '⚠️ ' + e, true));
}
function spromptShowDefault(kind) {
    fetch('?selagent_prompt=1&kind=' + kind + '&url=' + encodeURIComponent(spromptUrl(kind)))
        .then(r => r.json())
        .then(j => {
            if (!j || !j.ok) { spromptMsg(kind, '⚠️ خواندن ناموفق', true); return; }
            spromptOut(kind, j['default']);
            spromptMsg(kind, 'این متنِ پیش‌فرضِ کارخانه است (فقط برای دیدن؛ چیزی تغییر نکرد)');
        })
        .catch(e => spromptMsg(kind, '⚠️ ' + e, true));
}
function spromptReset(kind) {
    const t = spromptEl(kind, 'Text');
    if (!t) return;
    if (t.value.trim() !== '' && !confirm('متنِ پرامپتِ سفارشی پاک شود؟')) return;
    t.value = '';
    const r = document.querySelector('input[name="spmode-' + kind + '"][value="append"]');
    if (r) r.checked = true;
    const o = spromptEl(kind, 'Out');
    if (o) o.classList.add('hidden');
    spromptDirty(kind);
    spromptMsg(kind, 'خالی شد — برای اعمال «ذخیرهٔ پرامپت» را بزنید');
}

/** شروعِ ایجنت. عمداً مدل را نمی‌فرستیم تا سرور از «مدلِ فعالِ اتصالات»
 *  استفاده کند — همان مدلی که کاربر در تبِ هوش مصنوعی انتخاب کرده. */
function selagStart(kind) {
    kind = (kind === 'detail') ? 'detail' : 'list';
    const url = selagUrlFor(kind);
    if (url === null || url === undefined) return;
    const listUrl = selagListUrl();
    if (!url && !listUrl) return;
    if (selagState && selagState.running) { showToast('یک کشف همین حالا در جریان است', true); return; }

    selagKind = kind;
    selagLines = [];
    selagLast = null;
    selagConvo = []; selagCSince = 0;   // v10.26 (۳۹ب)
    selagState = { running: true, kind: kind, url: url, phase: 'start', step: 0, calls: 0, probes: 0, confirmed: 0 };
    selagRender();

    /* v10.27 (۴۰الف): pk را می‌فرستیم تا سرور دقیقاً همان اتصالی را
       به کار ببرد که iframeِ ?visual_proxy می‌برد (تنظیمِ «اتصالِ
       غیرمستقیمِ این پروفایل»). بدونِ آن، ایجنت روی سایتی که در
       انتخابگر عالی باز می‌شود «دریافتِ صفحه ناموفق» می‌گرفت. */
    const body = new URLSearchParams({ kind: kind, url: url || '',
        pk: profileKey(listUrl || url), list_url: listUrl });
    fetch('?selagent_start=1', { method: 'POST', body: body })
        .then(function (r) { return r.json(); })
        .then(function (d) {
            if (!d.ok) {
                selagState = { running: false, done: true, error: d.error || 'شروع نشد', kind: kind, url: url };
                selagRender();
                showToast(d.error || 'شروع نشد', true);
                return;
            }
            showToast('🧲 ایجنتِ کشفِ سلکتور شروع شد');
            selagPollStart();
        })
        .catch(function () {
            selagState = { running: false, done: true, error: 'ارتباط با سرور برقرار نشد', kind: kind, url: url };
            selagRender();
            showToast('خطا در ارتباط', true);
        });
}

function selagStop() {
    fetch('?selagent_stop=1').then(function () { showToast('⏹ درخواستِ توقف ثبت شد'); });
}

function selagPollStart() {
    if (selagTimer) clearInterval(selagTimer);
    selagTick();
    selagTimer = setInterval(selagTick, 1400);
}

function selagPollStop() {
    if (selagTimer) { clearInterval(selagTimer); selagTimer = null; }
}

function selagTick() {
    fetch('?selagent_status=1&since=' + selagLines.length + '&csince=' + selagCSince)
        .then(function (r) { return r.json(); })
        .then(function (p) {
            if (!p || !p.ok) return;
            (p.log || []).forEach(function (l) { selagLines.push(l && l.m ? l.m : String(l)); });
            /* v10.26 (۳۹ب): پیام‌های تازهٔ گفتگو */
            if (p.convo && p.convo.length) {
                p.convo.forEach(function (m) { selagConvo.push(m); });
                selagCSince = p.convo_total || selagConvo.length;
            } else if (typeof p.convo_total === 'number') {
                selagCSince = p.convo_total;
            }
            selagState = p;
            selagRender();
            if (p.done || p.running === false) {
                selagPollStop();
                if (p.result_ok) selagFetchResult();
                else if (p.error) showToast('❌ ' + p.error, true);
            }
        })
        .catch(function () {});
}

function selagFetchResult() {
    fetch('?selagent_result=1')
        .then(function (r) { return r.json(); })
        .then(function (d) {
            selagLast = d;
            selagAdoptSeeded(d);       // v10.27 (۴۰ب)
            selagRender();
            const n = d && d.selectors ? Object.keys(d.selectors).length : 0;
            showToast(n > 0 ? ('✓ ' + toFa(n) + ' سلکتور کشف شد — برای اعمال دکمه را بزنید')
                            : 'ایجنت سلکتوری پیدا نکرد');
        })
        .catch(function () {});
}

/**
 * v10.27 (۴۰ب): محصولاتی که ایجنتِ جزئیات برای ساختنِ صفحهٔ نمونه استخراج
 * کرده، باید در همین تب هم دیده شوند.
 *
 * چرا صرفاً «سرور ذخیره کرده» کافی نیست: تبِ باز هنوز نقشهٔ محصولاتِ خالیِ
 * خودش را دارد و اولین ذخیرهٔ خودکار همان خالی را روی دیسک می‌نویسد —
 * دقیقاً همان باگی که در ۸.۸۳ سرِ گالری‌ها آمد. پس همین‌جا نتیجه را در
 * حافظهٔ تب می‌نشانیم و بعد ذخیره را زمان‌بندی می‌کنیم.
 *
 * ادغام محافظه‌کارانه است: محصولِ موجود هرگز بازنویسی نمی‌شود.
 */
function selagAdoptSeeded(d) {
    const sd = d && d.seeded;
    if (!sd || !sd.ok || !Array.isArray(sd.products) || !sd.products.length) return 0;
    let added = 0;
    sd.products.forEach(function (e) {
        if (!Array.isArray(e) || e.length < 2) return;
        const k = String(e[0] || ''), p = e[1];
        if (!k || !p || typeof p !== 'object') return;
        if (products.has(k)) return;
        products.set(k, p);
        order.push(k);
        added++;
    });
    if (!added) return 0;
    /* سلکتورهای فهرستی که ایجنت در همین زنجیره کشف کرده هم حیف است */
    const ls = sd.list_selectors || {};
    if (ls.container && !sel.container && typeof setSel === 'function') {
        ['container', 'title', 'price', 'link', 'image'].forEach(function (f) {
            if (ls[f] && !sel[f]) setSel(f, ls[f]);
        });
    }
    if (!detailSampleKey) {
        const first = detailSampleList()[0];
        if (first) detailSampleKey = first[0];
    }
    refreshViews();
    update();
    scheduleSave();
    showToast('🧺 ' + toFa(added) + ' محصول توسط ایجنت استخراج و به نتایج اضافه شد');
    return added;
}

/** برچسبِ فارسیِ فازِ جاری. */
function selagPhaseLabel(ph) {
    const m = { start: 'آماده‌سازی', fetch: 'دریافتِ صفحه', map: 'نقشه‌برداری از ساختار',
                think: 'تحلیل توسط مدل', tool: 'اجرای ابزار', verify: 'اعتبارسنجیِ نهایی',
                chain: 'ساختِ محصولِ نمونه (اجرای ایجنتِ فهرست)' };
    return m[ph] || ph || '—';
}

/** درصدِ تقریبیِ پیشرفت. مبنا نسبتِ گامِ جاری به سقفِ گام‌هاست؛ وقتی
 *  کار تمام شده صریحاً ۱۰۰ می‌دهیم تا نوار نیمه‌کاره نماند. */
function selagPct(p) {
    if (!p) return 0;
    if (p.done) return 100;
    const st = +(p.step || 0), mx = 16;
    return Math.max(3, Math.min(97, Math.round(st / mx * 100)));
}

let selagConvoOpen = false;   // v10.26 (۳۹ب): باکسِ گفتگو باز است یا نه

/** رندرِ یکسانِ پنل در هر سه جا (زیرتبِ لیست، زیرتبِ جزئیات، تبِ ایجنت). */
function selagRender() {
    const html = selagPanelHtml();
    ['list', 'detail', 'ai'].forEach(function (slot) {
        const box = $('selagBody-' + slot);
        if (!box) return;
        /* در زیرتب‌ها فقط پنلِ همان نوع را نشان بده؛ در تبِ ایجنت همیشه. */
        const show = (slot === 'ai') || (selagState && selagState.kind === slot) ||
                     (!selagState && false);
        box.innerHTML = show ? html : '';
    });
    const idle = $('selagIdleAi');
    if (idle) idle.classList.toggle('hidden', !!(selagState && html));
    /* دکمه‌ها هنگام اجرا قفل می‌شوند تا کاربر دو اجرا روی هم نیندازد. */
    ['list', 'detail'].forEach(function (k) {
        const b = $('selagBtn-' + k);
        if (b) b.disabled = !!(selagState && selagState.running);
    });
}

function selagPanelHtml() {
    const p = selagState;
    if (!p) return '';
    const kindFa = (p.kind === 'detail') ? 'صفحهٔ جزئیات' : 'صفحهٔ فهرست';
    const pct = selagPct(p);
    let h = '';

    h += '<div class="selag-hd">';
    h += '<span>🧲 ایجنتِ کشفِ سلکتور — ' + esc(kindFa) + '</span>';
    if (p.running) h += '<span class="selag-chip">⏳ ' + esc(selagPhaseLabel(p.phase)) + '</span>';
    else if (p.error) h += '<span class="selag-chip" style="color:#fca5a5;border-color:#7f1d1d">❌ ناموفق</span>';
    else if (p.done) h += '<span class="selag-chip" style="color:#86efac;border-color:#166534">✓ پایان‌یافته</span>';
    h += '<span style="flex:1"></span>';
    if (p.running) h += '<button class="btn btn-red" onclick="selagStop()" style="font-size:10px;padding:3px 10px">⏹ توقف</button>';
    else h += '<button class="btn btn-gray" onclick="selagDismiss()" style="font-size:10px;padding:3px 10px">✕ بستن</button>';
    h += '</div><div class="selag-bd">';

    if (p.url) h += '<div style="font-size:10px;color:#64748b;direction:ltr;text-align:left;word-break:break-all;margin-bottom:5px">' + esc(p.url) + '</div>';
    h += '<div class="selag-bar"><i style="width:' + pct + '%"></i></div>';
    h += '<div style="display:flex;gap:6px;flex-wrap:wrap;font-size:10.5px;color:#94a3b8;margin-bottom:6px">';
    h += '<span class="selag-chip">گام ' + toFa(+(p.step || 0)) + '</span>';
    h += '<span class="selag-chip">فراخوانِ مدل ' + toFa(+(p.calls || 0)) + '</span>';
    h += '<span class="selag-chip">آزمایشِ سلکتور ' + toFa(+(p.probes || 0)) + '</span>';
    h += '<span class="selag-chip">تأییدشده ' + toFa(+(p.confirmed || 0)) + '</span>';
    h += '</div>';

    /* v10.27 (۴۰الف): از کدام راه صفحه گرفته شد. وقتی «مستقیم» است یعنی
       iframeِ پروکسی این سایت را باز نمی‌کند — دانستنش برای کاربر مهم است
       چون انتخابگر عالی هم روی همین سایت خالی می‌ماند. */
    const _via = p.fetch_via || (selagLast && selagLast.via) || '';
    if (_via === 'proxy') h += '<div style="font-size:10.5px;color:#86efac;margin-bottom:6px">🖼 صفحه از راهِ iframeِ پروکسی باز شد</div>';
    else if (_via === 'direct') h += '<div style="font-size:10.5px;color:#fbbf24;margin-bottom:6px">🌐 iframeِ پروکسی این صفحه را باز نکرد — مستقیم با قابلیت‌های وب‌تولز گرفته شد</div>';

    if (p.error) h += '<div class="alert alert-danger" style="font-size:11px;margin:0 0 7px">❌ ' + esc(p.error) + '</div>';

    if (selagLines.length) {
        h += '<div class="selag-log" id="selagLogBox">';
        selagLines.slice(-120).forEach(function (l) { h += '<div>' + esc(l) + '</div>'; });
        h += '</div>';
    }

    /* v10.26 (۳۹ب): گفتگوی زنده. چون selagRender کلِ پنل را دوباره
       می‌سازد، وضعیتِ باز/بستهٔ details را در selagConvoOpen نگه می‌داریم
       تا با هر نوسازیِ ۱٫۴ ثانیه‌ای زیرِ دستِ کاربر بسته نشود. */
    if (selagConvo.length) {
        h += '<details class="cvo"' + (selagConvoOpen ? ' open' : '')
           + ' ontoggle="selagConvoOpen=this.open">'
           + '<summary><span>💬 گفتگوی زنده با مدل</span>'
           + (p.running ? '<span class="cvo-live">در جریان</span>' : '')
           + '<span class="cvo-n">' + toFa(selagConvo.length) + ' پیام</span></summary>'
           + '<div class="cvo-bd">';
        selagConvo.forEach(function (m) { h += cvoMsgHtml(m); });
        h += '</div></details>';
    }

    h += selagResultHtml();
    h += '</div>';
    return h;
}

function selagResultHtml() {
    const d = selagLast;
    if (!d || !d.ok) return '';
    const sels = d.selectors || {};
    const keys = Object.keys(sels);
    if (!keys.length) return '<div style="margin-top:8px;font-size:11px;color:#fbbf24">ایجنت هیچ سلکتورِ قابلِ اعتمادی پیدا نکرد.</div>';

    let h = '<div class="selag-res">';
    if (d.note) h += '<div style="font-size:10.5px;color:#a5b4fc;line-height:1.9">📝 ' + esc(d.note) + '</div>';
    keys.forEach(function (f) {
        const pv = (d.preview && d.preview[f]) || {};
        const found = +(pv.found || 0);
        h += '<div class="selag-row">';
        h += '<b style="color:#e2e8f0;min-width:64px">' + esc(selagFieldFa(f)) + '</b>';
        h += '<code>' + esc(sels[f]) + '</code>';
        h += '<span class="' + (found > 0 ? 'ok' : 'no') + '">' + (found > 0 ? ('✓ ' + toFa(found) + ' مورد') : '✗ بی‌نتیجه') + '</span>';
        if (pv.sample) h += '<span style="color:#64748b;font-size:10px">« ' + esc(String(pv.sample).slice(0, 60)) + ' »</span>';
        h += '</div>';
    });
    h += '</div>';
    h += '<div class="row" style="margin-top:9px">';
    h += '<button class="btn btn-green" onclick="selagApply()" style="flex:1;font-size:11px">✅ اعمالِ همهٔ سلکتورها</button>';
    h += '<button class="btn btn-blue" onclick="selagStart(\'' + esc(d.kind || 'list') + '\')" style="font-size:11px">🔁 اجرای دوباره</button>';
    h += '</div>';
    return h;
}

function selagFieldFa(f) {
    const m = { container: 'کانتینر', title: 'عنوان', price: 'قیمت', link: 'لینک', image: 'تصویر',
                shortDesc: 'توضیحِ کوتاه', longDesc: 'توضیحِ بلند', sku: 'کدِ کالا', category: 'دسته',
                tags: 'برچسب‌ها', weight: 'وزن', stock: 'موجودی', brand: 'برند' };
    return m[f] || f;
}

/** اعمالِ نتیجه روی همان فرم‌هایی که تا امروز دستی پر می‌شدند. عمداً از
 *  setSel و detailSel استفاده می‌کنیم تا مسیرِ ذخیره/تست دقیقاً همان
 *  مسیرِ همیشگی باشد و رفتارِ تازه‌ای وارد نشود. */
function selagApply() {
    const d = selagLast;
    if (!d || !d.ok || !d.selectors) { showToast('نتیجه‌ای برای اعمال نیست', true); return; }
    const sels = d.selectors;
    let n = 0;
    if ((d.kind || 'list') === 'detail') {
        Object.keys(sels).forEach(function (f) {
            if (typeof detailSel === 'undefined' || !detailSel[f]) return;
            detailSel[f].selector = sels[f];
            detailSel[f].enabled = true;
            n++;
        });
        if (typeof renderDetailFieldsList === 'function') renderDetailFieldsList();
        if (typeof refreshViews === 'function') refreshViews();
        scheduleSave();
    } else {
        ['container', 'title', 'price', 'link', 'image'].forEach(function (f) {
            if (!sels[f]) return;
            setSel(f, sels[f]);
            n++;
        });
    }
    showToast(n > 0 ? ('✅ ' + toFa(n) + ' سلکتور اعمال شد') : 'چیزی برای اعمال نبود');
}

function selagDismiss() {
    selagState = null; selagLast = null; selagLines = [];
    selagConvo = []; selagCSince = 0;    // v10.26 (۳۹ب)
    selagRender();
}

/** بازیابیِ اجرای در جریان بعد از رفرشِ صفحه — همان کاری که مدیر وظیفه
 *  برای بقیهٔ کارها می‌کند. بدون این، اگر کاربر وسطِ کار F5 بزند فکر
 *  می‌کند اجرا مرده است. */
function selagResume() {
    fetch('?selagent_status=1&since=0&csince=0')
        .then(function (r) { return r.json(); })
        .then(function (p) {
            if (!p || !p.ok || !p.started_at) return;
            selagLines = (p.log || []).map(function (l) { return l && l.m ? l.m : String(l); });
            selagConvo = p.convo || [];                         // v10.26 (۳۹ب)
            selagCSince = p.convo_total || selagConvo.length;
            selagState = p;
            if (p.running) { selagRender(); selagPollStart(); }
            else if (p.result_ok) { selagRender(); selagFetchResult(); }
        })
        .catch(function () {});
}

/** ورودیِ «مدیر وظیفه» برای این کار: کاربر را به زیرتبِ درست می‌برد. */
function selAgentOpenLast() {
    switchMainTab('selectors');
    const k = (selagState && selagState.kind === 'detail') ? 'detail' : 'list';
    selSub(k);
    selagRender();
    const el = $('selagPanel-' + k);
    if (el && typeof softScrollIntoView === 'function') softScrollIntoView(el);
}

function setSel(type,val){
  sel[type]=val;
  $('sel'+type.charAt(0).toUpperCase()+type.slice(1)).value=val;
  $('s-'+type).classList.toggle('has',!!val);
  updateStartVisBtn();
  scheduleSave();

  // Auto-test the selector
  if (val) {
      setTimeout(() => testSel(type), 200);
  }
}

function updateStartVisBtn() {
    const btn = $('startVisBtn');
    if (!btn) return;
    if (sel.container) {
        btn.disabled = false;
        btn.textContent = '▶ شروع اسکرپ';
    } else {
        btn.disabled = true;
        btn.textContent = '▶ نیاز به کانتینر';
    }
}

window.addEventListener('message',e=>{
  if(e.data && e.data.type==='selectors'){
    sel=e.data.data;
    ['container','title','price','link','image'].forEach(k=>{
      $('sel'+k.charAt(0).toUpperCase()+k.slice(1)).value=sel[k]||'';
      $('s-'+k).classList.toggle('has',!!sel[k]);
      // Auto-test
      if (sel[k]) {
          setTimeout(() => testSel(k), 300);
      }
    });
    $('status').textContent='✓ سلکتورها ذخیره شدند';
    updateStartVisBtn();
    scheduleSave();
    showToast('✓ سلکتورها دریافت شد');
  } else if(e.data && e.data.type==='picker_ready'){
    // v8.68: صفحهٔ نمونه آماده شد — حالت فعلی پنل را به آن بگو
    pkSetMode(($('pkMode')||{}).value||'shortDesc');
    selCtlSyncFrame('pk');   // v9.90: تیک‌های نمایش را روی صفحهٔ تازه‌لودشده اعمال کن
    if(selectorFsState&&selectorFsState.kind==='detail')selectorFsSendPause();
  } else if(e.data && e.data.type==='picker_state'){
    pkApplyState(e.data);
  } else if(e.data && e.data.type==='picker_field'){
    // v8.76: فیلد از داخل خود صفحه عوض شد — منوی پنل را هم‌تراز کن.
    // pkSetMode را صدا نمی‌زنیم چون خودِ iframe همین حالا عوضش کرده و
    // فرستادن دوبارهٔ فرمان باعث رفت‌وبرگشت بی‌جا می‌شود.
    const ms=$('pkMode'); if(ms)ms.value=e.data.mode||'shortDesc';
    pkModeHint(e.data.mode||'shortDesc');
  } else if(e.data && e.data.type==='picker_hint'){
    if(e.data.msg){const h=$('pkHint');if(h)h.textContent=e.data.msg;}
    else pkSetMode(($('pkMode')||{}).value||'shortDesc');
  } else if(e.data && e.data.type==='detail_selectors'){
    const data = e.data.data || {};
    let applied = 0, galMsg = '';
    for (const k of Object.keys(data)) {
        if (data[k] && DETAIL_FIELDS.some(f => f.key === k)) {
            detailSel[k] = {enabled: true, selector: data[k]};
            applied++;
        }
    }
    // v8.68: تنوع‌ها یک فیلد عادی جزئیات است و در حلقهٔ بالا ذخیره می‌شود
    // v8.66: انتخاب‌های گالری به تنظیمات گالری می‌روند، نه به فیلدهای جزئیات
    if (data.galleryBox) {
        galApply(Object.assign(galCollect(), {mode:'auto', box:data.galleryBox}));
        galMsg = ' · باکس گالری تنظیم شد';
        applied++;
    } else if (data.galleryOne) {
        const n = data.galleryOne.split('\n').filter(x=>x.trim()).length;
        galApply(Object.assign(galCollect(), {mode:'manual', selectors:data.galleryOne}));
        galMsg = ' · ' + toFa(n) + ' عکس گالری';
        applied++;
    }
    if (data.image) {
        // عکس اصلی جزو سلکتورهای فهرست است، نه صفحهٔ جزئیات
        sel.image = data.image;
        if ($('selImage')) $('selImage').value = data.image;
        applied++;
    }
    renderDetailFieldsList();
    refreshViews();
    scheduleSave();
    showToast(`✓ ${applied} مورد انتخاب شد` + galMsg);
    $('detailStatus').textContent = `✓ ${applied} مورد دریافت شد` + galMsg;
    if (galMsg) setTimeout(()=>{ const b=$('galTestR'); if(b) galleryTest(); }, 300);
  } else if(e.data && e.data.type==='vp_state'){
    // v8.77: وضعیت پیش‌نمایش فهرست روی پنل بیرونی
    vpApplyState(e.data);
  } else if(e.data && e.data.type==='vp_ready'){
    vpSetMode(($('vpMode')||{}).value||'container');
    selCtlSyncFrame('vp');   // v9.90: تیک‌های نمایش را روی صفحهٔ تازه‌لودشده اعمال کن
    if(selectorFsState&&selectorFsState.kind!=='detail')selectorFsSendPause();
  } else if(e.data && (e.data.type==='picker_pause_state'||e.data.type==='vp_pause_state')){
    selectorFsPaused=!!e.data.on; selectorFsUpdatePauseBtn();
  } else if(e.data && e.data.type==='cancel'){
    $('vFrame').src='about:blank';
  } else if(e.data && e.data.type==='cancel_detail'){
    pkClose();
  }
});

// v7.81: Toggle manual selector input mode
function toggleManualSelMode(){
    const manual=$('manualSelMode').checked;
    ['container','title','price','link','image'].forEach(k=>{
        const inp=$('sel'+k.charAt(0).toUpperCase()+k.slice(1));
        if(manual){inp.removeAttribute('readonly');inp.style.background='#1e293b';inp.style.borderColor='#f59e0b';inp.style.cursor='text';}
        else{inp.setAttribute('readonly','readonly');inp.style.background='';inp.style.borderColor='';inp.style.cursor='';}
    });
    if(manual) showToast('✏️ حالت دستی فعال — سلکتورها را مستقیم تایپ کنید');
}
// v7.81: Handle manual selector input
function onManualSelInput(key){
    const inp=$('sel'+key.charAt(0).toUpperCase()+key.slice(1));
    sel[key]=inp.value.trim();
    if(sel[key])$('s-'+key).classList.add('has');
    else $('s-'+key).classList.remove('has');
    updateStartVisBtn();scheduleSave();
}
// v7.81: Direct load — load site directly in iframe without proxy
function loadDirect(){
    const url=$('url').value.trim();
    if(!url){showToast('URL وارد کنید',true);return;}
    $('status').textContent='🌐 بارگذاری مستقیم...';
    $('directLoadBanner').classList.remove('hidden');
    if($('manualSelMode')&&!$('manualSelMode').checked){$('manualSelMode').checked=true;toggleManualSelMode();}
    $('vFrame').src=url;
    $('vFrame').onload=()=>{$('status').textContent='✅ سایت بارگذاری شد — از 🔍 بازرسی تمام صفحه یا 📋 اسکریپت بازرسی استفاده کنید';showToast('✅ سایت مستقیم بارگذاری شد');};
}
// v7.81: Full Page Inspector — opens the page in a new tab with proxy + inspector
function openFullPageInspector(){
    const url=$('url').value.trim();
    if(!url){showToast('URL وارد کنید',true);return;}
    const full=$('fullMode')&&$('fullMode').checked?'&full=1':'';
    // v9.75: اتصالِ این صفحه را مطابق «اتصال غیرمستقیم»ِ پروفایلِ فعلی بگذار (خاموش = مستقیم)
    const _pk=profileKey(url);
    const w=window.open('?visual_proxy='+encodeURIComponent(url)+'&fullpage_inspect=1'+full+'&pk='+encodeURIComponent(_pk),'_blank');
    if(!w){showToast('⚠️ پاپ‌آپ مسدود شد — لطفاً پاپ‌آپ را فعال کنید',true);return;}
    showToast('🔍 صفحه بازرسی در تب جدید باز شد — المان‌ها را انتخاب کنید');
    $('status').textContent='🔍 صفحه بازرسی در تب جدید باز شد';
}
