function clearSel(){
  if(!confirm('پاک کردن همه سلکتورها؟')) return;
  sel={container:'',title:'',price:'',link:'',image:''};
  ['container','title','price','link','image'].forEach(k=>{
    $('sel'+k.charAt(0).toUpperCase()+k.slice(1)).value='';
    $('s-'+k).classList.remove('has');
    const prev = $('prev-' + k);
    if (prev) {
        prev.textContent = 'در انتظار...';
        prev.classList.add('empty');
    }
  });
  $('vFrame').src='about:blank';
  $('suggestions').classList.add('hidden');
  updateStartVisBtn();
  scheduleSave();
}

/* v7.41: Start extraction from selectors tab
   v8.92: این دکمه هم مثل «استخراج اتوماتیک» به موتور بک‌اند وصل شد.
   وگرنه همان استخراج ناقصِ بدون گالری و بدون تنوع را اجرا می‌کرد و
   نتیجه‌اش به این بستگی داشت که کاربر کدام دکمه را زده — که دلیلی
   ندارد فرق کند. */
function startFromSelectors(){
  if(!sel.container){showToast('ابتدا کانتینر را انتخاب کنید!',true);return;}
  if(!sel.title){showToast('ابتدا سلکتور عنوان را انتخاب کنید!',true);return;}
  if(!$('url').value.trim()){showToast('ابتدا آدرس سایت را وارد کنید!',true);return;}
  switchMainTab('start');
  startAutoExtract();
}

function startVisual(){
  if(!sel.container){showToast('کانتینر انتخاب کنید',true);return;}
  if(!$('url').value.trim()){showToast('ابتدا آدرس سایت را وارد کنید!',true);return;}
  switchMainTab('start');
  startAutoExtract();
}

function log(m,t='info'){
  const logs = $('logs');
  logs.innerHTML += `<div class="log log-${t}">${new Date().toLocaleTimeString('fa-IR')} ${m}</div>`;
  logs.scrollTop = logs.scrollHeight;
}

function updateSpeedCard(count, startedAtSec){
  const el=$('numSpeed'); if(!el)return;
  let startedMs=startedAtSec?startedAtSec*1000:extractSpeedStartMs;
  let ppm=0;
  if(startedMs&&count>0){
    const mins=Math.max((Date.now()-startedMs)/60000, 1/60);
    ppm=Math.max(0, Math.round(count/mins));
  }
  fxSetNum('numSpeed', toFa(ppm));
  el.title=ppm?('میانگین از شروع اجرا: '+ppm+' محصول/دقیقه'):'در انتظار استخراج';
}

function update(){
  /* v10.06: fxSetNum فقط وقتی می‌نویسد که عدد واقعاً عوض شده باشد و همان‌جا
     تپشِ کوتاهِ fx-bump را می‌زند — هم DOM کمتر دست می‌خورد، هم تغییرِ عدد
     در وسطِ یک استخراجِ شلوغ از چشم نمی‌افتد. */
  fxSetNum('numP',  toFa(products.size));
  fxSetNum('numPg', toFa(pages));
  fxSetNum('numD',  toFa(details));
  fxSetNum('resultProfileCount',toFa(products.size));
  const rpn=$('resultProfileName'),ps=$('profileSelect');if(rpn)rpn.textContent=(ps&&ps.options&&ps.selectedIndex>=0?(ps.options[ps.selectedIndex].text||ps.value):'—')||'—';
  if(extractSpeedStartMs) updateSpeedCard(products.size, 0);

  const badge = $('resultsBadge');
  const _bPrev = badge.textContent;
  if (products.size > 0) {
      badge.classList.remove('hidden');
      badge.textContent = products.size > 99 ? '99+' : products.size;
      badge.className = 'badge ok';          // v10.06: className پاک می‌شود…
      if (badge.textContent !== _bPrev) fxBump(badge);   // …پس تپش بعدش می‌آید
  } else {
      badge.classList.add('hidden');
  }

  const empty = $('emptyState');
  if (empty) {
      empty.style.display = products.size > 0 ? 'none' : 'block';
  }
}

// v8.06: Safe scroll — only scrolls the element if it's visible and has overflow (prevents mobile auto-scroll)
function scrollElBottom(el){if(!el)return;try{if(el.scrollHeight>el.clientHeight&&el.scrollHeight>0){const nearBottom=el.scrollHeight-el.scrollTop-el.clientHeight<80;if(nearBottom)el.scrollTop=el.scrollHeight;}}catch(e){}}
/* =====================================================================
 *  v8.88: جلوگیری از پرش‌های خودکار صفحه روی موبایل.
 *
 *  چند جای برنامه صفحه را خودکار جابه‌جا می‌کردند: عوض کردن تب صفحه را
 *  به بالا می‌پراند، باز کردن نمونهٔ سلکتور صفحه را پایین می‌کشید، و
 *  حرکت در درخت المان‌ها هر بار صفحه را وسط‌چین می‌کرد. روی دسکتاپ
 *  تحمل‌پذیر است ولی روی موبایل — که صفحه کوچک است و کاربر با انگشت
 *  جای خودش را نگه داشته — آزاردهنده است و کار را از دست کاربر می‌گیرد.
 *
 *  اینجا یک نقطهٔ واحد گذاشته شده تا همهٔ آن جاها از یک قاعده پیروی کنند
 *  و بشود با یک تنظیم خاموش/روشنش کرد.
 * ===================================================================== */
function isMobileView(){
  try{
    if(window.matchMedia&&window.matchMedia('(max-width: 820px)').matches)return true;
    return (window.innerWidth||document.documentElement.clientWidth||0)<=820;
  }catch(e){ return false; }
}
/** آیا اجازهٔ پرش خودکار صفحه هست؟ پیش‌فرض روی موبایل: نه */
function autoScrollAllowed(){
  try{
    const v=localStorage.getItem('scraper_autoscroll');
    if(v==='1')return true;      // کاربر صریحاً روشن کرده
    if(v==='0')return false;     // کاربر صریحاً خاموش کرده
  }catch(e){}
  return !isMobileView();
}
/** جای گذاشتنِ scrollIntoView — روی موبایل بی‌صدا کاری نمی‌کند */
function softScrollIntoView(el,opts){
  if(!el||!autoScrollAllowed())return false;
  try{ el.scrollIntoView(opts||{block:'center'}); return true; }catch(e){ return false; }
}
/** جای گذاشتنِ window.scrollTo */
function softScrollTo(opts){
  if(!autoScrollAllowed())return false;
  try{ window.scrollTo(opts); return true; }catch(e){ return false; }
}
function setAutoScrollPref(on){
  try{ localStorage.setItem('scraper_autoscroll', on?'1':'0'); }catch(e){}
  showToast(on?'پرش خودکار صفحه روشن شد':'پرش خودکار صفحه خاموش شد');
}
/** تیک را با وضعیت فعلی هم‌تراز کن (پیش‌فرض موبایل: خاموش) */
function initAutoScrollPref(){
  const el=document.getElementById('autoScrollOn');
  if(el)el.checked=autoScrollAllowed();
}

/* ==================================================================
 *  v9.93: فونتِ کل برنامه
 *
 *  موتورش (appFontApply/appFontCurrent) در همان اولین اسکریپتِ <head>
 *  تعریف شده تا صفحه از لحظهٔ اول با فونت درست رندر شود. این‌جا فقط
 *  کشویی پنل تنظیمات به آن وصل می‌شود.
 * ================================================================== */
function setAppFont(key){
  if(typeof window.appFontApply!=='function')return;
  const k=window.appFontApply(key,true);
  /* v10.106: فونت سرور = منبع حقیقت سراسری برای همهٔ دستگاه‌ها */
  try{ window.APP_FONT_SERVER = k; }catch(e){}
  const f=(window.APP_FONTS||{})[k];
  syncAppFontPreview(k);
  showToast('فونت برنامه: '+((f&&f.label)||k)+' — در حال ذخیره برای همه…');
  try{
    const fd=new FormData();
    fd.append('font', k);
    fetch('?action=save_ui_font',{method:'POST',body:fd,credentials:'same-origin'})
      .then(r=>r.json()).then(d=>{
        if(d&&d.ok){
          showToast('✓ فونت «'+((f&&f.label)||k)+'» برای همهٔ بازدیدکننده‌ها ذخیره شد', true);
        }else{
          showToast('⚠️ فونت محلی اعمال شد ولی ذخیرهٔ سرور ناموفق: '+(d&&d.error?d.error:''), true);
        }
      }).catch(()=>{ showToast('⚠️ ذخیرهٔ سرور فونت ناموفق — فقط همین مرورگر', true); });
  }catch(e){}
}
/** جعبهٔ نمونهٔ زیر کشویی را با فونت انتخابی نشان بده */
function syncAppFontPreview(k){
  const box=document.getElementById('appFontPreview');
  const f=(window.APP_FONTS||{})[k];
  if(box&&f)box.style.fontFamily=f.stack;
}
/** کشویی را با فونتِ ذخیره‌شده هم‌تراز کن */
function initAppFontPref(){
  const k=(typeof window.appFontCurrent==='function')?window.appFontCurrent()
    :(window.APP_FONT_SERVER||'vazirmatn');
  const sel=document.getElementById('appFontSel');
  if(sel)sel.value=k;
  syncAppFontPreview(k);
}

/* ==================================================================
 *  v9.94: رنگ‌بندی (تم) کل برنامه
 *
 *  رنگ‌ها سمتِ سرور در خروجی جاسازی می‌شوند (app_theme_filter)، پس
 *  عوض کردن تم یعنی: ذخیره در localStorage + نوشتن کوکی + یک رفرش.
 *  موتورش (appThemeApply/appThemeCurrent) در <head> تعریف شده است.
 * ================================================================== */
function setAppTheme(key){
  if(typeof window.appThemeApply!=='function')return;
  const cur=(typeof window.appThemeCurrent==='function')?window.appThemeCurrent():'';
  const k=window.appThemeApply(key,true);
  syncAppThemeUI(k);
  if(k===cur)return;                       /* همان تم — رفرشِ بی‌مورد نکن */
  const t=(window.APP_THEMES||{})[k];
  showToast('رنگ‌بندی: '+((t&&t.label)||k)+' — در حال اعمال…');
  try{ sessionStorage.removeItem('__thm_reload'); }catch(e){}
  setTimeout(function(){location.reload();},220);
}
/** کشویی و کارت‌های نمونه را با تمِ جاری هم‌تراز کن */
function syncAppThemeUI(k){
  const sel=document.getElementById('appThemeSel');
  if(sel)sel.value=k;
  const cards=document.querySelectorAll('[data-theme-card]');
  for(let i=0;i<cards.length;i++){
    const on=cards[i].getAttribute('data-theme-card')===k;
    cards[i].style.borderColor=on?'#4ade80':'#334155';
    cards[i].style.boxShadow=on?'0 0 0 1px #4ade80':'none';
  }
}
function initAppThemePref(){
  const k=(typeof window.appThemeCurrent==='function')?window.appThemeCurrent():'ocean';
  syncAppThemeUI(k);
}
/* =====================================================================
 *  v10.06 (۲۰): لایهٔ «جلوه‌های بصری»
 *
 *  کلِ ظاهرِ جلوه‌ها CSS است و پشتِ html[data-fx="on"] قفل شده؛ این چند
 *  تابع فقط سه کارِ کوچک می‌کنند که از CSS برنمی‌آید:
 *    ۱) تپشِ شمارنده وقتی عددش واقعاً عوض شده (نه در هر رندر)،
 *    ۲) ورودِ آبشاریِ کارتِ محصول وقتی وارد دید می‌شود،
 *    ۳) فلاشِ لمس روی دکمه‌ها (چون موبایل :hover ندارد).
 *  هر سه با کلاس کار می‌کنند و اگر جلوه‌ها خاموش باشد اصلاً اجرا نمی‌شوند.
 * ================================================================== */
function fxOn(){
  try{ return document.documentElement.getAttribute('data-fx')==='on'; }catch(e){ return false; }
}
function setAppFx(on){
  if(typeof window.appFxApply!=='function')return;
  const v=window.appFxApply(on?'on':'off',true);
  syncAppFxUI(v);
  if(v==='on')fxInitRuntime();
  showToast(v==='on'?'✨ جلوه‌های بصری روشن شد':'جلوه‌های بصری خاموش شد');
}
function syncAppFxUI(v){
  const on=(v!=='off');
  const c=document.getElementById('appFxChk');
  if(c)c.checked=on;
  const s=document.getElementById('appFxState');
  if(s)s.textContent=on?'روشن':'خاموش';
}
function initAppFxPref(){
  const v=(typeof window.appFxCurrent==='function')?window.appFxCurrent():'on';
  syncAppFxUI(v);
  fxInitRuntime();
}
/** انیمیشنِ یک‌باره را از نو راه می‌اندازد (بدون reflow دوباره نمی‌پرد) */
function fxReplay(el,cls,ms){
  if(!el||!fxOn())return;
  el.classList.remove(cls);
  void el.offsetWidth;
  el.classList.add(cls);
  setTimeout(function(){ try{ el.classList.remove(cls); }catch(e){} },ms);
}
function fxBump(el){ fxReplay(el,'fx-bump',620); }
function fxPulse(el){ fxReplay(el,'fx-pulse',3400); }
/** حالتِ «در حال کار» — نوارِ نورِ عبوری روی یک عنصر */
function fxBusy(el,on){
  if(!el)return;
  if(on&&fxOn())el.classList.add('fx-busy'); else el.classList.remove('fx-busy');
}
/** عدد را فقط وقتی می‌نویسد که عوض شده باشد، و همان‌جا یک تپش می‌زند */
function fxSetNum(id,txt){
  const el=$(id);
  if(!el)return;
  const s=String(txt);
  if(el.textContent===s)return;
  el.textContent=s;
  fxBump(el);
}
/* ورودِ کارتِ محصول: fx-pop یک «انیمیشن» است نه «حالتِ پنهان»؛ اگر ناظر
   هرگز شلیک نکند هیچ محصولی نامرئی نمی‌ماند. */
let fxPopObs;
function fxPopObserver(){
  if(fxPopObs!==undefined)return fxPopObs;
  if(typeof IntersectionObserver!=='function'){ fxPopObs=null; return null; }
  fxPopObs=new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(!e.isIntersecting)return;
      fxPopObs.unobserve(e.target);
      if(fxOn())e.target.classList.add('fx-pop');
    });
  },{rootMargin:'80px'});
  return fxPopObs;
}
function fxWatchCard(el){
  if(!el||!fxOn())return;
  const o=fxPopObserver();
  if(o)o.observe(el); else el.classList.add('fx-pop');
}
function fxInitRuntime(){
  if(window.__fxRuntime)return;
  window.__fxRuntime=true;
  /* فلاشِ لمس: در فازِ capture می‌نشیند تا stopPropagation هندلرهای
     موجود آن را نخورد، و هیچ‌وقت جلوی کلیک را نمی‌گیرد. */
  document.addEventListener('pointerdown',function(e){
    if(!fxOn())return;
    const t=e&&e.target;
    const b=(t&&t.closest)?t.closest('.btn'):null;
    if(!b||b.disabled)return;
    fxReplay(b,'fx-tap',500);
  },true);
  /* v10.07: ردیابِ نشانگر برای هالهٔ دنبال‌کنندهٔ کارت‌ها */
  try{ document.addEventListener('pointermove',fxTrackPointer,{passive:true}); }catch(e){}
}
/* ══════════════════════════════════════════════════════════════════
 *  v10.07 (۲۱): لایهٔ دومِ جلوه‌ها — «جنس» و «واکنش»
 *
 *  همه‌چیز روی زیرساختِ v10.06 سوار است: fxOn() برای گیت و fxReplay()
 *  برای زدن و برداشتنِ کلاس. هیچ‌کدام اجباری نیستند — اگر عنصر نباشد
 *  یا جلوه‌ها خاموش باشد، بی‌صدا برمی‌گردند.
 * ================================================================== */

/* ردیابِ نشانگر: مختصاتِ نسبیِ ماوس داخلِ کارت را در دو متغیرِ CSS
   می‌گذارد تا هالهٔ ::after دنبالش بیاید. روی document شنیده می‌شود
   (نه تک‌تکِ کارت‌ها) تا با کارت‌هایی که بعداً ساخته می‌شوند هم کار
   کند و هزارتا listener روی صفحه نماند. */
function fxTrackPointer(e){
  if(!fxOn())return;
  const c=(e&&e.target&&e.target.closest)?e.target.closest('.card'):null;
  if(!c)return;
  const r=c.getBoundingClientRect();
  if(!r.width||!r.height)return;
  c.style.setProperty('--fx-mx',((e.clientX-r.left)/r.width*100).toFixed(1)+'%');
  c.style.setProperty('--fx-my',((e.clientY-r.top)/r.height*100).toFixed(1)+'%');
}

/* نوارِ باریکِ بالای صفحه برای کارهای طولانی.
   شمارنده است نه سوییچ: اگر دو کارِ هم‌زمان شروع شوند، نوار تا پایانِ
   آخرینشان می‌ماند. هرگز زیرِ صفر نمی‌رود. */
let fxTopN=0;
function fxTopBar(on){
  fxTopN=Math.max(0,fxTopN+(on?1:-1));
  let el=document.getElementById('fxTop');
  if(fxTopN>0&&fxOn()){
    if(!el){el=document.createElement('div');el.id='fxTop';document.body.appendChild(el);}
    el.style.opacity='1';
  }else if(el){
    el.style.opacity='0';
    setTimeout(function(){ try{ if(fxTopN===0&&el.parentNode)el.parentNode.removeChild(el); }catch(e){} },320);
  }
}

/* دو حالتِ معنایی روی همان fxReplayِ لایهٔ قبل */
function fxOkFlash(el){ if(typeof el==='string')el=$(el); fxReplay(el,'fx-ok',720); }
function fxErrFlash(el){ if(typeof el==='string')el=$(el); fxReplay(el,'fx-err',540); }

/* اسکلتِ بارگذاری: چند نوارِ موج‌دار به‌جای ظرفِ خالی و مرده.
   اگر جلوه‌ها خاموش باشد ظرف را فقط خالی می‌کند. */
function fxSkeleton(el,n){
  if(typeof el==='string')el=$(el);
  if(!el)return;
  if(!fxOn()){el.innerHTML='';return;}
  let h='';
  for(let i=0;i<(n||3);i++)
    h+='<div class="fx-skel" style="height:'+(14+(i%2)*8)+'px;margin-bottom:8px;opacity:'+(1-i*0.18).toFixed(2)+'"></div>';
  el.innerHTML=h;
}
function esc(s){const d=document.createElement('div');d.textContent=s||'';return d.innerHTML;}
/**
 * v8.84: مقدار امن برای گذاشتن داخل رشتهٔ تک‌کوتیشنیِ یک ویژگی onclick.
 *
 * esc() از textContent/innerHTML استفاده می‌کند و «کوتیشن دوتایی» را
 * فرار نمی‌دهد؛ چون در متن عادی مشکلی ندارد. ولی داخل onclick="..."
 * همان یک کوتیشنِ فرارنداده، ویژگی را زودتر می‌بندد و مرورگر هندلر را
 * نصفه می‌خواند — همان خطای «Unexpected end of input».
 * اینجا هر چیزی که می‌تواند از ویژگی یا از رشته بیرون بزند خنثی می‌شود.
 */
function jsAttr(s){
  return String(s==null?'':s)
    .replace(/\\/g,'\\\\')      // اول بک‌اسلش، وگرنه فرارهای بعدی خراب می‌شوند
    .replace(/'/g,"\\'")        // رشتهٔ تک‌کوتیشنی را نبند
    .replace(/"/g,'&quot;')     // ویژگیِ دوکوتیشنی را نبند
    .replace(/&(?!quot;)/g,'&amp;')
    .replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/[\r\n]+/g,' ');   // خط جدید داخل ویژگی، هندلر را می‌شکند
}

/**
 * v8.42: کلید محصول را مطمئن می‌کند.
 *
 * محصولات ذخیره‌شده در پروفایل به شکل [کلید, محصول] نگه داشته می‌شوند،
 * یعنی خودِ شیء محصول فیلد key ندارد. هنگام بارگذاری پروفایل، p.key
 * برابر undefined می‌شد و چون جست‌وجو با [data-k="undefined"] انجام
 * می‌شد، همهٔ محصولات روی یک کارت بازنویسی می‌شدند و فقط یکی دیده می‌شد.
 */
function ensureKey(p,fallback){
  if(!p||typeof p!=='object')return '';
  if(p.key===undefined||p.key===null||p.key===''){
    if(fallback!==undefined&&fallback!==null&&fallback!=='')p.key=fallback;
  }
  return p.key||'';
}

/* v10.31 (۴۴): بدنهٔ کارت جدا شد تا رندرِ انبوه بتواند بدون جست‌وجوی DOM
   و بدون appendChildِ تک‌تک، رشته بسازد. renderCard خودش دست‌نخورده
   می‌ماند و همان رفتار قبلی را دارد. */
function s4ImgCfgIsActiveJs(cfg){
  if(!cfg||typeof cfg!=='object')return false;
  const m=s4InferImgEditModeJs(cfg);
  if(m==='crop')return (parseInt(cfg.crop_bottom_pct||0)||0)>0||(parseInt(cfg.crop_bottom_px||0)||0)>0;
  return (parseInt(cfg.square_pct||0)||0)>0||(parseInt(cfg.square_px||0)||0)>0;
}
function resultEditedImgUrl(imgUrl,p,role){
  if(!imgUrl)return '';
  const r=(role==='gallery')?'gallery':'list';
  let lc=(typeof listImgEditCollect==='function')?listImgEditCollect():{};
  let gc=(typeof galCollect==='function')?galCollect():{};
  const prof=(typeof findProfileEntryJs==='function'&&currentProfileKey)?findProfileEntryJs(currentProfileKey):((typeof profiles!=='undefined'&&currentProfileKey&&profiles[currentProfileKey])?profiles[currentProfileKey]:null);
  if(!s4ImgCfgIsActiveJs(lc)&&prof&&prof.listImageEdit&&s4ImgCfgIsActiveJs(prof.listImageEdit))lc=prof.listImageEdit;
  if(!s4ImgCfgIsActiveJs(gc)&&prof&&prof.gallery&&s4ImgCfgIsActiveJs(prof.gallery))gc=prof.gallery;
  const lcOn=s4ImgCfgIsActiveJs(lc),gcOn=s4ImgCfgIsActiveJs(gc);
  const chosen=(r==='gallery')?(gcOn?gc:(lcOn?lc:null)):(lcOn?lc:(gcOn?gc:null));
  const prodUrl=(p&&p.link)||currentProfileUrl||'';
  let url='?image_proxy='+encodeURIComponent(imgUrl)+'&img_role='+encodeURIComponent(r);
  if(prodUrl)url+='&product_url='+encodeURIComponent(prodUrl);
  if(chosen){url+=s4BuildImgEditPreviewQuery(chosen);}
  return url;
}
function sanitizeResultRichHtml(raw){
  if(!raw)return '';
  const s=String(raw).trim();
  if(!s)return '';
  if(!s.includes('<'))return '<div style="white-space:pre-wrap;line-height:1.9">'+esc(s)+'</div>';
  const doc=new DOMParser().parseFromString(s,'text/html');
  const allowed=new Set(['TABLE','THEAD','TBODY','TFOOT','TR','TH','TD','P','BR','UL','OL','LI','STRONG','B','EM','I','H3','H4','H5','DIV','SPAN']);
  const cleanNode=(node)=>{
    Array.from(node.childNodes).forEach(ch=>{
      if(ch.nodeType===1){
        const tag=ch.tagName.toUpperCase();
        if(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','FORM','INPUT','BUTTON','SVG'].includes(tag)){ch.remove();return;}
        if(!allowed.has(tag)){
          while(ch.firstChild)node.insertBefore(ch.firstChild,ch);
          ch.remove();return;
        }
        Array.from(ch.attributes).forEach(at=>{
          const an=at.name.toLowerCase();
          if(an!=='colspan'&&an!=='rowspan'&&an!=='dir')ch.removeAttribute(at.name);
        });
        if(tag==='TABLE'){ch.style.cssText='width:100%;border-collapse:collapse;margin:8px 0;font-size:12px;background:#0b1220;border:1px solid #334155;border-radius:8px;overflow:hidden';}
        else if(tag==='TH'){ch.style.cssText='border:1px solid #334155;padding:7px 10px;background:#1e293b;color:#93c5fd;text-align:right;width:34%;font-weight:700';}
        else if(tag==='TD'){ch.style.cssText='border:1px solid #334155;padding:7px 10px;color:#e2e8f0;text-align:right';}
        cleanNode(ch);
      }
    });
  };
  cleanNode(doc.body);
  return doc.body.innerHTML;
}
function extractSpecsPairsJs(raw){
  if(!raw)return [];
  const pairs=[];
  const pushPair=(k,v)=>{k=String(k||'').replace(/[:：]+$/,'').trim();v=String(v||'').trim();if(k&&v&&k.length<=120)pairs.push([k,v]);};
  if(Array.isArray(raw)){
    raw.forEach(r=>{if(r&&typeof r==='object')pushPair(r.k||r.title||r.name||r[0],r.v||r.value||r[1]);});
    return pairs;
  }
  if(typeof raw==='object'){
    Object.entries(raw).forEach(([k,v])=>pushPair(k,typeof v==='object'?JSON.stringify(v):v));
    return pairs;
  }
  const str=String(raw).trim();
  if(!str)return [];
  if(str.includes('<')){
    const doc=new DOMParser().parseFromString(str,'text/html');
    doc.querySelectorAll('tr').forEach(tr=>{
      const cells=Array.from(tr.querySelectorAll('th,td'));
      if(cells.length>=2)pushPair(cells[0].textContent,cells.slice(1).map(c=>c.textContent.trim()).filter(Boolean).join(' ، '));
    });
    if(pairs.length)return pairs;
    doc.querySelectorAll('dl dt').forEach(dt=>{
      const dd=dt.nextElementSibling;
      if(dd&&dd.tagName==='DD')pushPair(dt.textContent,dd.textContent);
    });
    if(pairs.length)return pairs;
    doc.querySelectorAll('li').forEach(li=>{
      const m=li.textContent.trim().match(/^([^:：]{1,70})\s*[:：]\s*(.+)$/);
      if(m)pushPair(m[1],m[2]);
    });
    if(pairs.length)return pairs;
  }
  str.replace(/<[^>]+>/g,'\n').split(/\r?\n+/).forEach(ln=>{
    const m=ln.trim().match(/^([^:：\t|]{1,70})\s*(?:[:：]|\t|\s+\|\s+)\s*(.+)$/);
    if(m)pushPair(m[1],m[2]);
  });
  return pairs;
}
function renderResultSpecsTableHtml(p){
  const raw=p&&(p.specs||p.specifications||p.attributes_table||'');
  const pairs=extractSpecsPairsJs(raw);
  if(!pairs.length)return '';
  let h='<table style="width:100%;border-collapse:collapse;font-size:12px;background:#111827;border:1px solid #334155;border-radius:10px;overflow:hidden"><tbody>';
  pairs.forEach(([k,v])=>{h+='<tr><th style="border:1px solid #334155;padding:7px 10px;background:#1e293b;color:#93c5fd;text-align:right;width:34%">'+esc(k)+'</th><td style="border:1px solid #334155;padding:7px 10px;color:#e2e8f0">'+esc(v)+'</td></tr>';});
  return h+'</tbody></table>';
}
function renderResultVariationsTableHtml(p){
  if(!p)return '';
  const combs=Array.isArray(p.variation_combinations)?p.variation_combinations:[];
  const groups=Array.isArray(p.variation_groups)?p.variation_groups:[];
  const prices=(p.variation_prices&&typeof p.variation_prices==='object')?p.variation_prices:{};
  if(combs.length){
    let h='<table style="width:100%;border-collapse:collapse;font-size:11.5px;background:#111827;border:1px solid #334155;border-radius:10px;overflow:hidden"><thead><tr style="background:#1e293b;color:#f9a8d4"><th style="padding:7px;border:1px solid #334155;text-align:right">ترکیب تنوع</th><th style="padding:7px;border:1px solid #334155;text-align:right">قیمت مبدأ</th><th style="padding:7px;border:1px solid #334155;text-align:right">وضعیت</th></tr></thead><tbody>';
    combs.slice(0,30).forEach(c=>{
      const lbl=Object.entries(c.attributes||{}).map(([ak,av])=>(ak?ak+': ':'')+av).join(' · ');
      const st=(c.in_stock===false)?'<span style="color:#f87171">ناموجود</span>':'<span style="color:#4ade80">موجود</span>';
      h+='<tr><td style="padding:6px 9px;border:1px solid #334155">'+esc(lbl)+'</td><td style="padding:6px 9px;border:1px solid #334155;color:#86efac">'+resultMoney(c.price)+'</td><td style="padding:6px 9px;border:1px solid #334155">'+st+'</td></tr>';
    });
    return h+'</tbody></table>';
  }
  if(groups.length){
    let h='<table style="width:100%;border-collapse:collapse;font-size:11.5px;background:#111827;border:1px solid #334155;border-radius:10px;overflow:hidden"><tbody>';
    groups.forEach(g=>{
      const vals=(g.values||[]).map(v=>{const pv=prices[v];return esc(v)+(pv?' ('+resultMoney(pv)+')':'');}).join(' ، ');
      h+='<tr><th style="border:1px solid #334155;padding:7px 10px;background:#1e293b;color:#f9a8d4;text-align:right;width:30%">'+esc(g.name||'تنوع')+'</th><td style="border:1px solid #334155;padding:7px 10px">'+vals+'</td></tr>';
    });
    return h+'</tbody></table>';
  }
  return '';
}

function cardHtml(p,_k){
  let title = getFinalTitle(p.title);
  const origPrice = getOriginalPrice(p&&p.price);
  const price = getFinalPrice(p&&p.price);
  let origDiffers = origPrice !== '0' && origPrice !== price;
  let shortDesc = '';
  if (detailSel.shortDesc && detailSel.shortDesc.enabled && p.shortDesc) {
      shortDesc = stripHtml(p.shortDesc);
  }
  const _st=prodStatus(p);
  const _nImg=(p.images&&p.images.length)||0;
  const _galBadge=_nImg>1?`<span style="position:absolute;bottom:4px;left:4px;background:#000b;color:#f9a8d4;font-size:9px;font-weight:700;padding:1px 6px;border-radius:10px">🖼 ${toFa(_nImg)}</span>`:'';
  const _qb=resultPriceBreakdown(p);
  const _destMini=(_qb&&Array.isArray(_qb.dests)&&_qb.dests.some(d=>d.price>0&&d.price!==_qb.profilePrice))
    ?`<div style="margin-top:4px;display:flex;flex-wrap:wrap;gap:3px">${_qb.dests.filter(d=>d.price>0).map(d=>`<span style="font-size:9px;background:#0f172a;border:1px solid #334155;border-radius:5px;padding:1px 5px;color:#86efac" title="${esc(d.label||'')}">${esc(d.name)}: ${resultMoney(d.price)}</span>`).join('')}</div>`:'';
  const _mainImgSrc=p.image?resultEditedImgUrl(p.image,p,'list'):'';
  return `<div class="thumb" style="position:relative;cursor:pointer" onclick="resultProductOpen('${resultKeyArg(_k)}')">${_mainImgSrc?`<img class="lazy-img" data-src="${esc(_mainImgSrc)}" loading="lazy">`:'<div class="noimg">بدون تصویر</div>'}${_galBadge}</div>
  <div class="pbody"><div class="ptitle" style="cursor:pointer" onclick="resultProductOpen('${resultKeyArg(_k)}')">${statusBadge(_st)}${esc(title||'بدون عنوان')}</div>
  ${shortDesc ? `<div class="pdetail-short">${esc(shortDesc)}</div>` : ''}
  ${origDiffers ? `<span class="price-orig">${esc(origPrice)}</span>` : ''}
  <div class="price ${price!=='0'?'':'no-price'}">${price!=='0'?esc(price):'؟'}</div>${_destMini}
  ${p.link?`<a class="plink" href="${esc(p.link)}" target="_blank">مشاهده</a>
  <button class="btn btn-pink" onclick="useAsDetailSample('${_k}')" style="font-size:9.5px;padding:3px 7px;margin-top:4px;width:100%" title="همین محصول را در سلکتور جزئیات باز کن">🎯 نمونهٔ سلکتور</button>`:''}</div>`;
}

function renderCard(p,k){
  const _k=ensureKey(p,k);
  if(!_k)return;                       // بدون کلید نمی‌توان کارت ساخت
  const el=$('vGrid').querySelector(`[data-k="${_k}"]`);
  const html=cardHtml(p,_k);
  // v8.41: محصول تازه هرگز نباید به‌خاطر فیلترِ اجرای قبلی پنهان شود
  if(resultFilter!=='all'&&Object.keys(prodStatusMap).length===0)resetResultFilter();
  const _st=prodStatus(p);
  const _cls='product'+(_st==='new'?' is-new':_st==='changed'?' is-chg':'');
  // v10.06: className یک‌جا بازنویسی می‌شود؛ اگر کارت قبلاً جلوهٔ ورود را
  // گرفته بود باید نگهش داریم وگرنه با هر به‌روزرسانی دوباره می‌پرد.
  if(el){const _pop=el.classList.contains('fx-pop')?' fx-pop':'';
         el.innerHTML=html;el.className=_cls+_pop;el.style.display=matchFilter(_st)?'':'none';}
  else{
    if(typeof rvCanAppend==='function'&&!rvCanAppend('grid')){if(typeof rvDirty!=='undefined')rvDirty.grid=true;return;}
    const d=document.createElement('div');d.className=_cls;d.dataset.k=_k;d.innerHTML=html;
    d.style.display=matchFilter(_st)?'':'none';$('vGrid').appendChild(d);fxWatchCard(d);
  }
}

/* v10.291 / v10.440: شکست کامل قیمت سه‌لایه برای جدول/مودال/کارت نتایج؛ دقیقاً مطابق قواعد ارسال سرور. */
function resultAdjLabel(mode,val,round){
  mode=String(mode||'none');val=parseFloat(val)||0;round=parseInt(round)||0;
  let base='بدون تعدیل';
  if(mode==='percent')base=(val>=0?'+':'')+toFa(val)+'٪';
  else if(mode==='multiplier')base='×'+toFa(val);
  if(round>0&&base!=='بدون تعدیل')return base+' · گرد '+toFa(round.toLocaleString('en-US'));
  if(round>0)return 'گرد '+toFa(round.toLocaleString('en-US'));
  return base;
}
function liveDestCfg(pre){
  const key=pre==='wc'?'woocommerce':'basalam';
  const saved=(cn&&cn[key])||{};
  const mEl=$(pre+'PMode'),vEl=$(pre+'PVal'),rEl=$(pre+'PRound');
  const domMode=mEl?String(mEl.value||'none'):'';
  const domVal=(vEl&&vEl.value!=='')?parseFloat(vEl.value):NaN;
  const domRound=(rEl&&rEl.value!=='')?parseInt(rEl.value):NaN;
  const hydrated=!!window._connHydrated;
  const domEdited=(domMode!==''&&domMode!=='none')||(!isNaN(domVal)&&domVal!==0)||(!isNaN(domRound)&&domRound!==0);
  if(hydrated||domEdited){
    return Object.assign({},saved,{
      price_mode:mEl?(domMode||'none'):(saved.price_mode||'none'),
      price_val:!isNaN(domVal)?domVal:(parseFloat(saved.price_val)||0),
      price_round:!isNaN(domRound)?domRound:(parseInt(saved.price_round)||0)
    });
  }
  return Object.assign({},saved,{
    price_mode:saved.price_mode||'none',
    price_val:parseFloat(saved.price_val)||0,
    price_round:parseInt(saved.price_round)||0
  });
}
function bslShopAdjSummaryLabel(gMode,gVal,vMode,vVal,round,isDefault){
  gMode=String(gMode||'none');gVal=parseFloat(gVal)||0;
  vMode=isDefault?'none':String(vMode||'none');vVal=isDefault?0:(parseFloat(vVal)||0);
  round=parseInt(round)||0;
  const gActive=gMode!=='none'&&((gMode==='percent'&&gVal!==0)||(gMode==='multiplier'&&gVal>0&&gVal!==1));
  const vActive=!isDefault&&vMode!=='none'&&((vMode==='percent'&&vVal!==0)||(vMode==='multiplier'&&vVal>0&&vVal!==1));
  if(isDefault)return resultAdjLabel(gMode,gVal,round);
  if(gActive&&vActive){
    const gpct=gMode==='percent'?gVal:(gVal-1)*100;
    const vpct=vMode==='percent'?vVal:(vVal-1)*100;
    const tot=Math.round((gpct+vpct)*10)/10;
    let s=(tot>=0?'+':'')+toFa(tot)+'٪ (کلی '+resultAdjLabel(gMode,gVal)+' + غرفه '+resultAdjLabel(vMode,vVal)+')';
    if(round>0)s+=' · گرد '+toFa(round.toLocaleString('en-US'));
    return s;
  }
  if(gActive){
    let s=resultAdjLabel(gMode,gVal)+' (کلی باسلام)';
    if(round>0)s+=' · گرد '+toFa(round.toLocaleString('en-US'));
    return s;
  }
  if(vActive){
    let s=resultAdjLabel(vMode,vVal)+' (اختصاصی غرفه)';
    if(round>0)s+=' · گرد '+toFa(round.toLocaleString('en-US'));
    return s;
  }
  return resultAdjLabel('none',0,round);
}
function resultRoundPrice(n,round){n=Math.round(parseFloat(n)||0);round=parseInt(round)||0;return round>0?Math.round(n/round)*round:n;}
function resultPriceBreakdown(p){
  const raw=extractNumber(p&&p.price);const pm=($('priceMode')||{}).value||'none';const pv=parseFloat(($('priceVal')||{}).value)||0;
  const prRound=parseInt(($('roundPrice')||{}).value)||0;
  const profilePrice=getFinalPriceNum(p&&p.price);const out={raw:raw,profileMode:pm,profileVal:pv,profileRound:prRound,profilePrice:profilePrice,dests:[]};
  const w=liveDestCfg('wc');
  const wRound=parseInt(w.price_round)||0;
  const wFinal=destAdjustPreviewNum(profilePrice,w.price_mode||'none',parseFloat(w.price_val)||0,wRound);
  out.dests.push({key:'woo',name:'ووکامرس',mode:w.price_mode||'none',val:parseFloat(w.price_val)||0,round:wRound,label:resultAdjLabel(w.price_mode||'none',parseFloat(w.price_val)||0,wRound),price:wFinal});
  const b=liveDestCfg('bs');
  const br=parseInt(b.price_round)||0;
  const gMode=b.price_mode||'none',gVal=parseFloat(b.price_val)||0;
  if((parseInt(b.vendor_id)||0)>0||b.token||gMode!=='none'||br>0){
    const defFinal=bslShopFinalPrice(profilePrice,gMode,gVal,'none',0,br);
    out.dests.push({key:'bsl:'+String(parseInt(b.vendor_id)||0),name:b.shop_name||'غرفهٔ پیش‌فرض',mode:gMode,val:gVal,round:br,label:bslShopAdjSummaryLabel(gMode,gVal,'none',0,br,true),price:defFinal});
  }
  const liveVendors=Array.isArray(bslExtraVendors)&&bslExtraVendors.length?bslExtraVendors:(Array.isArray(b.vendors)?b.vendors:[]);
  liveVendors.forEach((v,idx)=>{
    if(!v)return;
    const sel=$('bslVPMode_'+idx),inp=$('bslVPV_'+idx);
    const vMode=sel?(sel.value||'none'):(v.price_mode||'none');
    const vVal=inp?(parseFloat(inp.value)||0):(parseFloat(v.price_val)||0);
    const shopFinal=bslShopFinalPrice(profilePrice,gMode,gVal,vMode,vVal,br);
    out.dests.push({key:'bsl:'+String(parseInt(v.vendor_id)||idx),name:v.shop_name||v.name||('غرفه '+toFa(idx+1)),mode:vMode!=='none'?vMode:gMode,val:vMode!=='none'?vVal:gVal,globalMode:gMode,globalVal:gVal,shopMode:vMode,shopVal:vVal,round:br,label:bslShopAdjSummaryLabel(gMode,gVal,vMode,vVal,br,false),price:shopFinal});
  });
  return out;
}
function resultMoney(n){n=parseInt(n)||0;return n>0?toFa(n.toLocaleString('en-US')):'—';}
function resultPricingCells(p){
  const q=resultPriceBreakdown(p);let h='<td class="td-orig">'+resultMoney(q.raw)+'</td><td>'+esc(resultAdjLabel(q.profileMode,q.profileVal,q.profileRound))+'</td><td>'+resultMoney(q.profilePrice)+'</td>';
  q.dests.forEach(d=>{h+='<td title="'+esc(d.name+' · '+(d.label||resultAdjLabel(d.mode,d.val)))+'">'+esc(d.label||resultAdjLabel(d.mode,d.val))+'</td><td style="color:#86efac;font-weight:800">'+resultMoney(d.price)+'</td>';});
  return h;
}
function resultPricingHeaders(){
  const q=resultPriceBreakdown({price:'100000'});let h='<th>قیمت مبدأ</th><th>ضریب تعدیل پروفایل</th><th>قیمت پروفایل</th>';
  q.dests.forEach(d=>{h+='<th>تعدیل '+esc(d.name)+'</th><th>قیمت نهایی '+esc(d.name)+'</th>';});return h;
}
function resultKeyArg(k){return encodeURIComponent(String(k||'')).replace(/'/g,'%27');}
function resultProductClose(){const m=document.getElementById('resultProductModal');if(m)m.style.display='none';}
function resultProductOpen(encodedKey){
  const k=decodeURIComponent(String(encodedKey||'')),p=products.get(k);if(!p)return;
  let m=document.getElementById('resultProductModal');if(!m){m=document.createElement('div');m.id='resultProductModal';m.onclick=e=>{if(e.target===m)resultProductClose();};document.body.appendChild(m);}
  m.style.cssText='position:fixed;inset:0;z-index:100050;background:rgba(2,6,23,.86);display:flex;align-items:center;justify-content:center;padding:12px;direction:rtl';
  const q=resultPriceBreakdown(p),imgs=Array.from(new Set([p.image].concat(Array.isArray(p.images)?p.images:[]).filter(Boolean)));
  const image=imgs[0]||'';
  const short=stripHtml(p.shortDesc||p.short_desc||p.brief||'');
  const rawLong=String(p.longDesc||p.long_desc||p.description||'');
  const richLongHtml=sanitizeResultRichHtml(rawLong);
  const specsTableHtml=renderResultSpecsTableHtml(p);
  const showSeparateSpecs=specsTableHtml&&(!richLongHtml.toLowerCase().includes('<table'));
  const varsTableHtml=renderResultVariationsTableHtml(p);
  let pricing='<table style="width:100%;border-collapse:collapse;font-size:11px"><thead><tr><th style="padding:7px">مرحله/مقصد</th><th>تعدیل</th><th>قیمت نهایی</th></tr></thead><tbody>';
  pricing+='<tr><td style="padding:7px">مبدأ</td><td>—</td><td>'+resultMoney(q.raw)+'</td></tr><tr><td style="padding:7px">پروفایل</td><td>'+esc(resultAdjLabel(q.profileMode,q.profileVal,q.profileRound))+'</td><td>'+resultMoney(q.profilePrice)+'</td></tr>';
  q.dests.forEach(d=>{pricing+='<tr><td style="padding:7px">'+esc(d.name)+'</td><td>'+esc(d.label||resultAdjLabel(d.mode,d.val))+'</td><td style="color:#86efac;font-weight:900">'+resultMoney(d.price)+'</td></tr>';});pricing+='</tbody></table>';
  const known=['title','price','link','image','images','shortDesc','short_desc','brief','longDesc','long_desc','description','specs','specifications','attributes_table','variation_combinations','variation_groups','variation_prices','variations','key'];let fields='';
  Object.keys(p).filter(x=>!known.includes(x)&&!x.startsWith('_')&&p[x]!==''&&p[x]!=null).forEach(x=>{let v=p[x];if(typeof v==='object')v=JSON.stringify(v);fields+='<div style="padding:7px;border:1px solid #334155;border-radius:7px"><b style="color:#93c5fd">'+esc(x)+'</b><div style="margin-top:3px;white-space:pre-wrap;word-break:break-word">'+esc(String(v))+'</div></div>';});
  const mainEditedSrc=image?resultEditedImgUrl(image,p,'list'):'';
  const gallery=imgs.map((u,idx)=>{const esrc=resultEditedImgUrl(u,p,idx===0?'list':'gallery');return '<img src="'+esc(esrc)+'" onclick="const mi=document.getElementById(\'resultModalMainImg\');if(mi)mi.src=this.src;" loading="lazy" style="width:74px;height:74px;object-fit:cover;border-radius:8px;border:1px solid #475569;cursor:pointer" title="کلیک برای بزرگ‌نمایی تصویر ویرایش‌شده">';}).join('');
  m.innerHTML='<article style="width:min(1050px,97vw);max-height:calc(100dvh - 24px);overflow:auto;overscroll-behavior:contain;background:#0f172a;border:1px solid #475569;border-radius:14px;color:#e2e8f0;box-shadow:0 20px 70px #000;padding:14px">'
    +'<header style="display:flex;justify-content:space-between;gap:10px;align-items:start"><div><div style="font-size:16px;font-weight:900">'+esc(getFinalTitle(p.title)||'بدون عنوان')+'</div><div style="color:#86efac;font-size:18px;font-weight:900;margin-top:5px">'+resultMoney(q.profilePrice)+'</div></div><button class="btn btn-gray" onclick="resultProductClose()">✕</button></header>'
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px;margin-top:12px"><div>'+(mainEditedSrc?'<img id="resultModalMainImg" src="'+esc(mainEditedSrc)+'" style="width:100%;max-height:320px;object-fit:contain;background:#fff;border-radius:10px">':'<div style="padding:60px 10px;text-align:center;background:#1e293b;border-radius:10px">بدون تصویر</div>')+'<div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:7px">'+gallery+'</div></div>'
    +'<div><div style="background:#111827;border:1px solid #334155;border-radius:10px;overflow:auto">'+pricing+'</div>'+(varsTableHtml?'<h4 style="color:#f9a8d4;margin:12px 0 6px">🎨 تنوع‌های محصول</h4>'+varsTableHtml:'')+(short?'<h4 style="color:#fbbf24;margin:12px 0 6px">توضیح کوتاه</h4><p style="line-height:1.9">'+esc(short)+'</p>':'')+(richLongHtml?'<h4 style="color:#fbbf24;margin:12px 0 6px">توضیحات محصول</h4><div style="line-height:1.9">'+richLongHtml+'</div>':'')+(showSeparateSpecs?'<h4 style="color:#38bdf8;margin:12px 0 6px">📋 جدول مشخصات فنی</h4>'+specsTableHtml:'')+(p.link?'<div style="margin-top:10px"><a href="'+esc(p.link)+'" target="_blank" class="btn btn-blue" onclick="event.stopPropagation()">مشاهده صفحه مبدأ</a></div>':'')+'</div></div>'
    +(fields?'<h4 style="color:#c4b5fd">همهٔ فیلدهای محصول</h4><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:7px">'+fields+'</div>':'')+'</article>';
}

/* v10.31 (۴۴): همان تفکیک برای ردیفِ جدول. */
function rowHtml(p,i){
  let title = getFinalTitle(p.title);
  let customTd = isCustomColEnabled() ? `<td>${esc(getCustomColVal())}</td>` : '';
  let detailTds = '';
  const enabledFields = getDetailColumns();
  enabledFields.forEach(f => {
      const val = p[f.key] || '';
      let display = val;
      if (f.key === 'shortDesc' || f.key === 'longDesc' || f.key === 'specs') {
          display = shortText(stripHtml(val), 60);
      }
      detailTds += `<td class="td-detail" title="${esc(stripHtml(val))}">${esc(display) || '-'}</td>`;
  });
  const _st=prodStatus(p);
  const _imgs=Array.isArray(p.images)?p.images.filter(Boolean):[];
  const _n=_imgs.length;
  let galTd;
  if(_n>1){
      const thumbs=_imgs.slice(0,4).map((u,idx)=>
          `<img src="${esc(resultEditedImgUrl(u,p,idx===0?'list':'gallery'))}" loading="lazy" `
        + `style="width:22px;height:22px;object-fit:cover;border-radius:3px;border:1px solid #334155">`).join('');
      galTd=`<td class="td-gal" title="${esc(_imgs.join('\n'))}">`
          + `<div style="display:flex;gap:2px;align-items:center">`
          + `<b style="color:#f9a8d4;font-size:10px">🖼 ${toFa(_n)}</b>${thumbs}`
          + (_n>4?`<span style="color:#64748b;font-size:9px">+${toFa(_n-4)}</span>`:'')
          + `</div></td>`;
  }else{
      galTd=`<td class="td-gal" style="color:#64748b;font-size:10px">${_n===1?'۱ عکس':'—'}</td>`;
  }
  const _mainThumbTd=p.image
      ?`<td title="${esc(p.image)}"><div style="display:flex;align-items:center;gap:5px"><img src="${esc(resultEditedImgUrl(p.image,p,'list'))}" loading="lazy" style="width:28px;height:28px;object-fit:cover;border-radius:4px;border:1px solid #334155;background:#fff"><span style="direction:ltr;font-size:9px;max-width:90px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(p.image)}</span></div></td>`
      :`<td style="color:#64748b;font-size:10px">-</td>`;
  return `<td>${toFa(i)}</td><td>${statusBadge(_st)}${esc(title)}</td>${resultPricingCells(p)}
  <td>${p.link?`<a href="${esc(p.link)}" target="_blank" onclick="event.stopPropagation()">لینک</a>`:'-'}</td>${_mainThumbTd}${galTd}${detailTds}${customTd}`;
}

function renderRow(p,i,k){
  const _k=ensureKey(p,k);if(!_k)return;
  const tb=$('tBody'),el=tb&&tb.querySelector(`[data-k="${_k}"]`),st=prodStatus(p),html=rowHtml(p,i);
  if(el){el.innerHTML=html;el.style.display=matchFilter(st)?'':'none';el.onclick=()=>resultProductOpen(resultKeyArg(_k));}
  else if(tb){
    if(typeof rvCanAppend==='function'&&!rvCanAppend('table')){if(typeof rvDirty!=='undefined')rvDirty.table=true;return;}
    const tr=document.createElement('tr');tr.dataset.k=_k;tr.innerHTML=html;tr.style.cursor='pointer';tr.title='مشاهده صفحه کامل محصول';tr.onclick=()=>resultProductOpen(resultKeyArg(_k));tr.style.display=matchFilter(st)?'':'none';tb.appendChild(tr);
  }
}

function updateTableHeaders() {
    let thead = $('tBody').parentElement.querySelector('thead tr');
    if(!thead) return;
    // v8.84: ستون گالری بعد از «تصویر» می‌آید — همان ترتیبی که renderRow می‌سازد
    let baseHeaders = '<th>#</th><th>عنوان</th>'+resultPricingHeaders()+'<th>لینک</th><th>تصویر</th><th>🖼 گالری</th>';
    const enabledFields = getDetailColumns();   // v10.15: قیمت ستونِ جدا نمی‌گیرد
    enabledFields.forEach(f => {
        baseHeaders += `<th>${f.icon} ${esc(f.label)}</th>`;
    });
    if (isCustomColEnabled()) {
        baseHeaders += `<th>${esc(getCustomColName())}</th>`;
    }
    thead.innerHTML = baseHeaders;
}

/* =====================================================================
 *  v10.31 (۴۴): رندرِ تنبلِ نتایج
 *
 *  مشکل: refreshViews() هر بار هر سه نما را برای همهٔ محصولات می‌ساخت —
 *  کارت + ردیفِ جدول + متنِ کامل — حتی وقتی تبِ نتایج اصلاً باز نبود.
 *  با یک پروفایلِ چندهزار محصولی، بارگذاری پروفایل یا رفرشِ صفحه یعنی
 *  ده‌ها هزار گرهِ DOM و به‌ازای هر محصول دو querySelector روی سند.
 *  نتیجه: چند ثانیه فریزِ کامل، آن هم برای چیزی که کاربر نمی‌بیند.
 *
 *  حالا:
 *    ۱) اگر تبِ نتایج باز نیست، هیچ نمایی ساخته نمی‌شود؛ فقط علامت
 *       «کثیف» می‌خورد و لحظهٔ ورود به تب ساخته می‌شود.
 *    ۲) نمای پیش‌فرضِ تبِ نتایج «جدول» است، نه «کارت» — جدول بدونِ
 *       تصویر و بدونِ IntersectionObserver است و بسیار سبک‌تر.
 *    ۳) هر نما فقط وقتی ساخته می‌شود که واقعاً دیده شود، و همان‌جا هم
 *       کش می‌شود تا سوییچِ بعدی رایگان باشد.
 *    ۴) هر نما یک پنجرهٔ محدود DOM دارد؛ صفحه‌های بعد/قبل نزدیک sentinel
 *       بار می‌شوند و صفحه‌های دور حذف می‌گردند تا DOM هرگز نامحدود نشود.
 * ===================================================================== */
const RV_CHUNK = 120;          // compatibility: old chunk test/name
const RV_HEAVY = 400;
const RV_PAGE_SIZE = 80;       // DOM rows/cards loaded per scroll page
const RV_MAX_DOM = 240;        // keep at most three pages; older pages can reload upward
const RV_TEXT_PAGE_SIZE = 200;
let rvDirty = {grid:true, table:true, text:true};
let rvChunkTimer = null;       // compatibility; eager all-product timer removed
let rvCurView = 'table';
let rvPageState = {grid:null,table:null,text:null};
let rvMoreObserver = {grid:null,table:null,text:null};

function resultsVisible(){
  const p=document.getElementById('pane-results');
  return !!(p&&p.classList.contains('active'));
}
function rvMarkDirty(){
  rvDirty.grid=true;rvDirty.table=true;rvDirty.text=true;
  rvPageState={grid:null,table:null,text:null};rvCancelChunks();
}
function rvCancelChunks(){
  if(rvChunkTimer){clearTimeout(rvChunkTimer);rvChunkTimer=null;}
  Object.keys(rvMoreObserver).forEach(v=>{if(rvMoreObserver[v]){try{rvMoreObserver[v].disconnect();}catch(e){}rvMoreObserver[v]=null;}});
}
function rvHint(msg){return '<div class="rv-hint">'+msg+'</div>';}
function rvFilteredItems(){
  const out=[];order.forEach((k,i)=>{const p=products.get(k);if(!p)return;const _k=ensureKey(p,k);if(!_k)return;
    if(matchFilter(prodStatus(p)))out.push({k:_k,p:p,n:i+1});});return out;
}
function rvMoreText(st){
  const shown=Math.min(st.cursor,st.items.length),left=Math.max(0,st.items.length-shown);
  return 'نمایش '+toFa(shown)+' از '+toFa(st.items.length)+(left?' · '+toFa(left)+' مورد با اسکرول بارگذاری می‌شود':'');
}
function rvWatchMore(view,els){
  if(rvMoreObserver[view]){try{rvMoreObserver[view].disconnect();}catch(e){}}
  const targets=Array.from(els?(els.length===undefined?[els]:els):[]).filter(Boolean);
  if(!targets.length||typeof IntersectionObserver!=='function')return;
  const io=new IntersectionObserver(es=>{const hit=es.find(x=>x.isIntersecting);if(!hit)return;
    io.disconnect();rvMoreObserver[view]=null;const dir=(hit.target.dataset&&hit.target.dataset.rvDir)||'next';
    if(view==='grid')rvAppendGrid(dir);else if(view==='table')rvAppendTable(dir);else rvAppendText(dir);},
    {root:null,rootMargin:'500px 0px',threshold:0});
  rvMoreObserver[view]=io;targets.forEach(el=>io.observe(el));
}
function rvWindowText(st){
  return 'نمایش '+toFa(st.start+1)+' تا '+toFa(st.cursor)+' از '+toFa(st.items.length)+' · فقط '+toFa(RV_MAX_DOM)+' مورد در صفحه نگه داشته می‌شود';
}
function rvTableMore(st){
  const tb=$('tBody');if(!tb)return;tb.querySelectorAll('.rv-page-sentinel').forEach(x=>x.remove());
  const cols=Math.max(1,document.querySelectorAll('#vTable thead th').length),sentinels=[];
  const add=(dir,label)=>{const tr=document.createElement('tr');tr.className='rv-page-sentinel';tr.id=dir==='next'?'rvTableMore':'rvTablePrev';tr.dataset.rvDir=dir;
    tr.innerHTML='<td colspan="'+cols+'" style="text-align:center;padding:12px;color:#7dd3fc;background:#0f172a">'+rvWindowText(st)
      +'<br><button class="btn btn-blue" style="margin-top:7px" onclick="rvAppendTable(\''+dir+'\')">'+label+'</button></td>';
    if(dir==='prev')tb.insertBefore(tr,tb.firstChild);else tb.appendChild(tr);sentinels.push(tr);};
  if(st.start>0)add('prev','نمایش موارد قبلی');if(st.cursor<st.items.length)add('next','نمایش موارد بعدی');rvWatchMore('table',sentinels);
}
function rvAppendTable(dir='next'){
  const st=rvPageState.table,tb=$('tBody');if(!st||!tb)return;if(rvMoreObserver.table)rvMoreObserver.table.disconnect();
  tb.querySelectorAll('.rv-page-sentinel').forEach(x=>x.remove());const anchor=tb.querySelector('tr[data-k]'),oldTop=anchor?anchor.getBoundingClientRect().top:0;
  const buf=[];if(dir==='prev'){
    const from=Math.max(0,st.start-RV_PAGE_SIZE);for(let i=from;i<st.start;i++){const x=st.items[i];buf.push('<tr data-k="'+esc(x.k)+'" title="مشاهده صفحه کامل محصول" style="cursor:pointer" onclick="resultProductOpen(\''+resultKeyArg(x.k)+'\')">'+rowHtml(x.p,x.n)+'</tr>');}
    tb.insertAdjacentHTML('afterbegin',buf.join(''));st.start=from;
  }else{
    const end=Math.min(st.cursor+RV_PAGE_SIZE,st.items.length);for(let i=st.cursor;i<end;i++){const x=st.items[i];buf.push('<tr data-k="'+esc(x.k)+'" title="مشاهده صفحه کامل محصول" style="cursor:pointer" onclick="resultProductOpen(\''+resultKeyArg(x.k)+'\')">'+rowHtml(x.p,x.n)+'</tr>');}
    tb.insertAdjacentHTML('beforeend',buf.join(''));st.cursor=end;
  }
  let rows=Array.from(tb.querySelectorAll('tr[data-k]')),excess=Math.max(0,rows.length-RV_MAX_DOM);
  if(excess&&dir==='prev'){for(let i=0;i<excess;i++)rows[rows.length-1-i].remove();st.cursor-=excess;}
  else if(excess){const h0=document.documentElement.scrollHeight;for(let i=0;i<excess;i++)rows[i].remove();st.start+=excess;const dh=document.documentElement.scrollHeight-h0;if(dh)window.scrollBy(0,dh);}
  if(dir==='prev'&&anchor){const dy=anchor.getBoundingClientRect().top-oldTop;if(dy)window.scrollBy(0,dy);}
  rvTableMore(st);
}
function rvBuildTable(){
  updateTableHeaders();const tb=$('tBody');if(!tb)return;rvCancelChunks();tb.innerHTML='';
  const items=rvFilteredItems();rvPageState.table={items:items,start:0,cursor:0};rvDirty.table=false;if(items.length)rvAppendTable();
}
function rvGridMore(st){
  const g=$('vGrid');if(!g)return;g.querySelectorAll('.rv-page-sentinel').forEach(x=>x.remove());const sentinels=[];
  const add=(dir,label)=>{const more=document.createElement('div');more.id=dir==='next'?'rvGridMore':'rvGridPrev';more.className='rv-hint rv-page-sentinel';more.style.gridColumn='1/-1';more.dataset.rvDir=dir;
    more.innerHTML=rvWindowText(st)+'<br><button class="btn btn-blue" style="margin-top:7px" onclick="rvAppendGrid(\''+dir+'\')">'+label+'</button>';
    if(dir==='prev')g.insertBefore(more,g.firstChild);else g.appendChild(more);sentinels.push(more);};
  if(st.start>0)add('prev','نمایش موارد قبلی');if(st.cursor<st.items.length)add('next','نمایش موارد بعدی');rvWatchMore('grid',sentinels);
}
function rvAppendGrid(dir='next'){
  const st=rvPageState.grid,g=$('vGrid');if(!st||!g)return;if(rvMoreObserver.grid)rvMoreObserver.grid.disconnect();
  g.querySelectorAll('.rv-page-sentinel').forEach(x=>x.remove());const anchor=g.querySelector('.product'),oldTop=anchor?anchor.getBoundingClientRect().top:0,buf=[];
  const html=x=>{const stt=prodStatus(x.p);return '<div class="product'+(stt==='new'?' is-new':stt==='changed'?' is-chg':'')+'" data-k="'+esc(x.k)+'">'+cardHtml(x.p,x.k)+'</div>';};
  if(dir==='prev'){const from=Math.max(0,st.start-RV_PAGE_SIZE);for(let i=from;i<st.start;i++)buf.push(html(st.items[i]));g.insertAdjacentHTML('afterbegin',buf.join(''));st.start=from;}
  else{const end=Math.min(st.cursor+RV_PAGE_SIZE,st.items.length);for(let i=st.cursor;i<end;i++)buf.push(html(st.items[i]));g.insertAdjacentHTML('beforeend',buf.join(''));st.cursor=end;}
  let cards=Array.from(g.querySelectorAll('.product')),excess=Math.max(0,cards.length-RV_MAX_DOM);
  if(excess&&dir==='prev'){for(let i=0;i<excess;i++)cards[cards.length-1-i].remove();st.cursor-=excess;}
  else if(excess){const h0=document.documentElement.scrollHeight;for(let i=0;i<excess;i++)cards[i].remove();st.start+=excess;const dh=document.documentElement.scrollHeight-h0;if(dh)window.scrollBy(0,dh);}
  if(dir==='prev'&&anchor){const dy=anchor.getBoundingClientRect().top-oldTop;if(dy)window.scrollBy(0,dy);}
  if(typeof window.rvAfterGrid==='function')window.rvAfterGrid();rvGridMore(st);
}
function rvBuildGrid(){
  rvCancelChunks();const g=$('vGrid');if(!g)return;g.innerHTML='';const items=rvFilteredItems();
  rvPageState.grid={items:items,start:0,cursor:0};rvDirty.grid=false;
  if(!items.length){g.innerHTML='<div class="empty-state" id="emptyState"><div class="icon">📭</div><p>محصولی برای نمایش نیست.</p></div>';return;}rvAppendGrid();
}
function rvRenderTextWindow(st,anchorIndex=-1,oldTop=0){
  const t=$('txtContent');if(!t)return;t.textContent='';t.appendChild(document.createTextNode(resultTextHeader()));const sentinels=[];
  const sentinel=(dir,label)=>{const more=document.createElement('span');more.className='rv-page-sentinel';more.id=dir==='next'?'rvTextMore':'rvTextPrev';more.dataset.rvDir=dir;more.style.cssText='display:block;padding:12px;text-align:center;color:#7dd3fc;white-space:normal';
    more.innerHTML='نمایش '+toFa(st.start+1)+' تا '+toFa(st.cursor)+' از '+toFa(st.items.length)+'<br><button class="btn btn-blue" style="margin-top:7px" onclick="rvAppendText(\''+dir+'\')">'+label+'</button>';sentinels.push(more);return more;};
  if(st.start>0)t.appendChild(sentinel('prev','نمایش موارد قبلی'));
  for(let i=st.start;i<st.cursor;i++){const x=st.items[i],line=document.createElement('span');line.className='rv-text-row';line.dataset.i=String(i);line.style.display='block';line.textContent=resultTextRow(x.p,x.n);t.appendChild(line);}
  if(st.cursor<st.items.length)t.appendChild(sentinel('next','نمایش موارد بعدی'));
  if(anchorIndex>=0){const anchor=t.querySelector('.rv-text-row[data-i="'+anchorIndex+'"]');if(anchor){const dy=anchor.getBoundingClientRect().top-oldTop;if(dy)window.scrollBy(0,dy);}}
  rvWatchMore('text',sentinels);
}
function rvAppendText(dir='next'){
  const st=rvPageState.text,t=$('txtContent');if(!st||!t)return;const anchor=t.querySelector('.rv-text-row'),anchorIndex=anchor?parseInt(anchor.dataset.i):-1,oldTop=anchor?anchor.getBoundingClientRect().top:0;
  if(dir==='prev'){st.start=Math.max(0,st.start-RV_TEXT_PAGE_SIZE);st.cursor=Math.min(st.items.length,Math.max(st.cursor,st.start+RV_TEXT_PAGE_SIZE*3));}
  else{st.cursor=Math.min(st.items.length,st.cursor+RV_TEXT_PAGE_SIZE);st.start=Math.max(0,st.cursor-RV_TEXT_PAGE_SIZE*3);}
  rvRenderTextWindow(st,anchorIndex,oldTop);
}
function rvBuildText(){
  rvCancelChunks();const t=$('txtContent');if(!t)return;t.textContent='';const items=rvFilteredItems();
  rvPageState.text={items:items,start:0,cursor:Math.min(RV_TEXT_PAGE_SIZE,items.length)};rvDirty.text=false;rvRenderTextWindow(rvPageState.text);
}
function rvEnsure(v){
  if(v==='table'&&rvDirty.table)rvBuildTable();else if(v==='grid'&&rvDirty.grid)rvBuildGrid();else if(v==='text'&&rvDirty.text)rvBuildText();
  else if(v==='table')rvWatchMore('table',document.querySelectorAll('#tBody .rv-page-sentinel'));
  else if(v==='grid')rvWatchMore('grid',document.querySelectorAll('#vGrid .rv-page-sentinel'));
  else if(v==='text')rvWatchMore('text',document.querySelectorAll('#txtContent .rv-page-sentinel'));
}
function rvRebuildVisible(){rvMarkDirty();if(resultsVisible())rvEnsure(rvCurView);}
function rvCanAppend(view){
  const host=view==='grid'?$('vGrid'):$('tBody');if(!host)return false;
  return host.querySelectorAll(view==='grid'?'.product':'tr[data-k]').length<RV_PAGE_SIZE;
}
function refreshViews(){
  rvMarkDirty();
  try{if(typeof bslRefreshVendorPreviews==='function')bslRefreshVendorPreviews();if(typeof bslBuildShopDrop==='function')bslBuildShopDrop();}catch(e){}
  if(products.size===0){rvBuildGrid();rvBuildTable();}else if(resultsVisible())rvEnsure(rvCurView);update();
}

function removeNoPrice() {
    let keysToDelete = [];
    products.forEach((p, k) => {
        if (getFinalPriceNum(p.price) === 0) {
            keysToDelete.push(k);
        }
    });
    if (keysToDelete.length === 0) {
        showToast('محصول بدون قیمت یافت نشد', true);
        return;
    }
    if (!confirm(`حذف ${keysToDelete.length} محصول بدون قیمت؟`)) return;

    keysToDelete.forEach(k => {
        products.delete(k);
        order = order.filter(x => x !== k);
    });
    window._userPrunedProducts = true;

    refreshViews();
    log(`✓ ${keysToDelete.length} محصول بدون قیمت حذف شد`, 'ok');
    showToast(`${keysToDelete.length} محصول حذف شد`);
}

function removeBelowMinPrice() {
    const minPrice = getMinPrice();
    let keysToDelete = [];
    products.forEach((p, k) => {
        const finalNum = getFinalPriceNum(p.price);
        if (finalNum > 0 && finalNum < minPrice) {
            keysToDelete.push(k);
        }
    });
    if (keysToDelete.length === 0) {
        showToast(`هیچ محصولی زیر ${toFa(minPrice.toLocaleString('en-US'))} یافت نشد`, true);
        return;
    }
    if (!confirm(`حذف ${keysToDelete.length} محصول با قیمت زیر ${minPrice.toLocaleString('en-US')}؟`)) return;

    keysToDelete.forEach(k => {
        products.delete(k);
        order = order.filter(x => x !== k);
    });
    window._userPrunedProducts = true;

    refreshViews();
    log(`✓ ${keysToDelete.length} محصول زیر حداقل قیمت حذف شد`, 'ok');
    showToast(`${keysToDelete.length} محصول حذف شد`);
}

function resultTextHeader(){
  let headers='# | Title | Original | Final | URL | Image | Gallery';
  getDetailColumns().forEach(f=>headers+=` | ${f.label}`);
  if(isCustomColEnabled())headers+=` | ${getCustomColName()}`;
  return headers+'\n'+'-'.repeat(140)+'\n';
}
function resultTextRow(p,i){
  const _gn=Array.isArray(p.images)?p.images.filter(Boolean).length:0;
  let row=`${i} | ${(getFinalTitle(p.title)||'').substring(0,25)} | ${getOriginalPrice(p.price)} | ${getFinalPrice(p.price)} | ${p.link||'-'} | ${p.image||'-'} | ${_gn>1?(_gn+' imgs'):(_gn===1?'1':'-')}`;
  getDetailColumns().forEach(f=>{let val=p[f.key]||'';if(f.key==='shortDesc'||f.key==='longDesc')val=shortText(stripHtml(val),40);row+=` | ${val}`;});
  if(isCustomColEnabled())row+=` | ${getCustomColVal()}`;
  return row;
}
function genTxt(){
  let t=resultTextHeader();order.forEach((k,i)=>{const p=products.get(k);if(p)t+=resultTextRow(p,i+1)+'\n';});return t;
}

/* v10.31 (۴۴): نما فقط لحظهٔ انتخاب ساخته می‌شود.
   نمای کارتی روی پروفایل‌های بزرگ اول یک پیامِ کوتاه نشان می‌دهد و بعد
   تکه‌تکه پر می‌شود، تا کلیک روی «کارت» صفحه را قفل نکند. */
const RV_VIEW_KEY = 'scraper_results_view';
function rvRememberView(v){
  try{ if(v==='grid'||v==='table'||v==='text')localStorage.setItem(RV_VIEW_KEY,v); }catch(e){}
}
/** نمای ذخیره‌شده — ولی «کارت» عمداً بازیابی نمی‌شود تا رفرش سبک بماند */
function rvSavedView(){
  try{
    const v=localStorage.getItem(RV_VIEW_KEY)||'';
    return (v==='table'||v==='text')?v:'table';
  }catch(e){ return 'table'; }
}

function switchView(v){
  document.querySelectorAll('.sub-tab').forEach(t=>t.classList.toggle('active',t.dataset.v===v));
  $('vGrid').classList.toggle('hidden',v!=='grid');
  $('vTable').classList.toggle('hidden',v!=='table');
  $('vText').classList.toggle('hidden',v!=='text');
  rvCurView=v;
  rvRememberView(v);
  /* ساخت نخستین صفحهٔ کارت را یک تیک عقب می‌اندازیم تا خودِ تب فوراً
     عوض شود؛ فقط پنجرهٔ محدود ساخته می‌شود، نه همهٔ محصولات. */
  if(v==='grid'&&rvDirty.grid&&products.size>=RV_HEAVY){
    $('vGrid').innerHTML=rvHint('⏳ در حال آماده‌سازی نخستین صفحه از '+toFa(products.size)+' محصول…');
    setTimeout(()=>{ if(rvCurView==='grid')rvBuildGrid(); },30);
    return;
  }
  rvEnsure(v);
}

// v7.66: Auto extract — uses saved selectors from profile, no need to re-select
// v7.81: Backend Extract — server-side scraping from source supplier website
// NOT sending to BaSalam/WooCommerce — only extracting products and saving to profile
// Triggers ?action=backend_extract endpoint which does PHP-side scraping
/**
 * v8.92: تنها راه شروع یک استخراج از مرورگر.
 *
 * سه دکمه («استخراج اتوماتیک»، «استخراج بک‌اند»، «اجرای الان») همگی از
 * همین‌جا رد می‌شوند تا رفتارشان نتواند از هم جدا بیفتد. قبلاً هرکدام
 * کد خودش را داشت و دو تای‌شان اصلاً به موتور اصلی نمی‌رسیدند.
 */
function backendExtractFor(url,panelTitle,phase){
    if(!url){showToast('URL وارد کنید',1);return;}
    /* Persist the current page limit/selectors first. In particular, numeric
       zero is a real auto-until-last-page value and must not race an older 10. */
    if(!window._extractAfterSave&&profileFormReady&&(url===currentProfileUrl||url===currentProfileKey)){
        saveProfileSilent().then(d=>{if(!d||!d.ok){showToast('تنظیمات پروفایل ذخیره نشد؛ استخراج شروع نشد',1);return;}window._extractAfterSave=true;try{backendExtractFor(d.key||currentProfileKey||url,panelTitle,phase);}finally{window._extractAfterSave=false;}});return;
    }
    // سلکتورها از روی نسخهٔ ذخیره‌شده بررسی می‌شوند، چون موتور بک‌اند
    // هم دقیقاً همان را می‌خواند — نه چیزی که در فرم باز است.
    const _loadTarget=(currentProfileKey&&(url===currentProfileKey||(currentProfileUrl&&url===currentProfileUrl)))?currentProfileKey:url;
    fetch('?load_profile='+encodeURIComponent(_loadTarget)).then(r=>r.json()).then(d=>{
        if(!d.ok||!d.profile){showToast('خطا: پروفایل یافت نشد — اول ذخیره کنید',1);return;}
        const prof=d.profile||{};
        const sels=prof.selectors||{};
        const profEngine=prof.extractionEngine||'selectors';
        if(profEngine==='selectors'&&(!sels.container||sels.container==='')){
            showToast('⚠️ سلکتورها ذخیره نشده — برای موتور CSS selector لازم است؛ یا Auto/Heuristic/Playwright/Selenium را انتخاب و ذخیره کنید',1);
            switchMainTab('selectors');
            return;
        }
        /* v9.07: فاز جزئیات روی محصولاتی کار می‌کند که «روی دیسک» هستند.
           اگر پروفایل ذخیره‌شده هنوز محصولی ندارد، گام جزئیات چیزی برای
           باز کردن پیدا نمی‌کند و کاربر یک اجرای بی‌صدا می‌بیند. */
        const ph=phase||'list';
        if(ph==='detail'&&!(prof.products&&prof.products.length)){
            showToast('⚠️ هنوز محصولی روی سرور ذخیره نشده — اول «استخراج بک‌اند» را بزنید',1);
            return;
        }
        openExtractPanel(panelTitle||'⚡ استخراج سریع فهرست — پیشرفت زنده');
        const galObj=prof.gallery||{};
        const isSnappUrl=/snappshop\.ir/i.test(String(prof.url||url||''));
        const galOn=(galObj.mode||'off')!=='off'||isSnappUrl||!!(galObj.box||'').trim()||!!(galObj.selectors||'').trim();
        const nDet=Object.entries(prof.detailSelectors||{}).filter(([,v])=>v&&(typeof v==='string'?v.trim()!=='':(v.enabled&&String(v.selector||'').trim()!==''))).length;
        const detailMode=normalizeDetailExtractModeJs(($('detailExtractMode')&&$('detailExtractMode').value)||prof.detailExtractMode||'two_stage');
        if(ph==='detail'){
            showToast('🔍 استخراج تفصیلی روی سرور شروع شد — گالری '+(galOn?'روشن':'خاموش')
                +(nDet?(' · '+toFa(nDet)+' فیلد'):''));
        }else if(ph==='list'){
            showToast('⚡ استخراج سریع فهرست — همان مسیر تست سه‌صفحه‌ای، بدون باز کردن صفحهٔ تک‌محصول');
        }else{
            if(!nDet){
                showToast('⚠️ سلکتور جزئیاتی در این پروفایل فعال نیست؛ فاز ۱ اجرا می‌شود (برای فاز ۲ ابتدا سلکتورهای جزئیات را فعال کنید)',1);
            }else if(detailMode==='inline'){
                showToast('⚡ استخراج درجا شروع شد — در حین پیمایش لیست، جزئیات ('+toFa(nDet)+' فیلد'+(galOn?' + گالری':'')+') هم‌زمان استخراج می‌شود');
            }else{
                showToast('⚡ استخراج دو مرحله‌ای شروع شد — اول لیست ← ذخیره در تب نتایج ← مرحلهٔ دوم ('+toFa(nDet)+' فیلد جزئیات'+(galOn?' + گالری':'')+')');
            }
        }
        // Trigger backend extract endpoint
        const serverProfileKey = (d.key || prof.key || profileKey(prof.url || url) || profileKey(url));
        const pageTarget=(prof.pages===0||prof.pages==='0')?0:Math.max(1,parseInt(prof.pages)||10);
        showToast(pageTarget===0?'📄 هدف تأییدشده: تشخیص خودکار آخرین صفحه':'📄 هدف تأییدشدهٔ این اجرا: '+toFa(pageTarget)+' صفحه');
        fetch('?action=backend_extract&phase='+encodeURIComponent(ph)
              +'&detail_mode='+encodeURIComponent(detailMode)
              +'&profile_key='+encodeURIComponent(serverProfileKey)
              +'&pages='+encodeURIComponent(pageTarget),{method:'GET'})
            .then(r=>r.json()).then(exResp=>{
                if(exResp&&exResp.ok===false&&exResp.error){
                    showToast('⚠️ '+exResp.error,1);
                }
            }).catch(()=>{});
        watchExtractProgress();
    }).catch(()=>{showToast('خطا شبکه',1);});
}

function startDetailExtractionServer(){
    const url=($('url')&&$('url').value.trim())
              ||($('profileSelect')&&$('profileSelect').value.trim())||'';
    if(!url){
        showToast('⚠️ ابتدا پروفایل را انتخاب یا ذخیره کنید',1);
        switchMainTab('profiles');
        return;
    }
    const go=()=>{
        window._extractAfterSave=true;
        try{backendExtractFor(url,'🔍 استخراج تفصیلی (سرور) — پیشرفت زنده','detail');}
        finally{window._extractAfterSave=false;}
    };
    /* v10.458: فقط اگر فرم واقعاً تغییر ذخیره نشده دارد (isDirty) یا پروفایل تازه در مرورگر است،
       ذخیره کن؛ وگرنه آپلود تکراری ۵ مگابایتی هزاران محصول مانع شروع فوری استخراج می‌شد. */
    const profMeta=(typeof findProfileEntryJs==='function'&&currentProfileKey)?findProfileEntryJs(currentProfileKey):((typeof profiles!=='undefined'&&currentProfileKey&&profiles[currentProfileKey])?profiles[currentProfileKey]:null);
    const serverHasProducts=!!(profMeta&&(profMeta.productCount>0||(Array.isArray(profMeta.products)&&profMeta.products.length>0)));
    const needSave=(typeof isDirty!=='undefined'&&isDirty)
                   ||(!serverHasProducts&&typeof products!=='undefined'&&products.size>0);
    if(needSave&&typeof saveProfileSilent==='function'){
        if(typeof saveTimer!=='undefined')clearTimeout(saveTimer);
        showToast('💾 ذخیره روی سرور — پس از تأیید، استخراج تفصیلی شروع می‌شود…');
        saveProfileSilent().then(d=>{
            if(!d||!d.ok){showToast('⛔ ذخیره انجام نشد؛ استخراج تفصیلی شروع نشد',1);return;}
            go();
        });
        return;
    }
    go();
}

function startBackendSync(){
    /* v8.93: آدرس از فیلد URL خوانده می‌شود و اگر خالی بود از منوی
       پروفایل. قبلاً فقط منوی پروفایل بود، برای همین «استخراج اتوماتیک»
       نمی‌توانست مستقیم همین را صدا بزند و مجبور شده بودم منطق موازی
       بنویسم. */
    const url=($('url')&&$('url').value.trim())
              ||($('profileSelect')&&$('profileSelect').value.trim())||'';
    if(!url){
        showToast('⚠️ ابتدا پروفایل با سلکتورها ذخیره شده انتخاب کنید',1);
        switchMainTab('profiles');
        return;
    }
    const wantDetail=!!($('backendExtractWithDetail')&&$('backendExtractWithDetail').checked);
    const detailMode=normalizeDetailExtractModeJs($('detailExtractMode')?$('detailExtractMode').value:loadDetailExtractModePref());
    const runPh=wantDetail?'all':'list';
    const runTitle=wantDetail
        ?(detailMode==='inline'?'⚡ استخراج بک‌اند (لیست + جزئیات درجا) — پیشرفت زنده':'⚡ استخراج بک‌اند دو مرحله‌ای (لیست ← تب نتایج ← جزئیات) — پیشرفت زنده')
        :undefined;
    /* موتور بک‌اند سلکتورها را از فایل پروفایل می‌خواند، نه از فرم باز.
       پس تغییر ذخیره‌نشده باید اول روی دیسک بنشیند وگرنه استخراج با
       سلکتورهای قدیمی اجرا می‌شود. */
    /* Never guess that 900ms was enough for a large profile JSON write.
       Await the confirmed save, then enqueue with the exact saved page target. */
    if(typeof saveProfileSilent==='function'){
        if(typeof saveTimer!=='undefined')clearTimeout(saveTimer);
        showToast('💾 ذخیرهٔ تنظیمات و تأیید تعداد صفحات…');
        saveProfileSilent().then(d=>{
            if(!d||!d.ok){
                if(d&&d.error==='profile_form_not_ready'){backendExtractFor(url,runTitle,runPh);return;}
                showToast('⛔ تنظیمات ذخیره نشد؛ استخراج با مقدار قدیمی شروع نشد',1);return;
            }
            backendExtractFor(url,runTitle,runPh);
        });
        return;
    }
    backendExtractFor(url,runTitle,runPh);
}

/* ═══════════════════════════════════════════════════════════════════
 *  v10.35 (۴۷ه): همگام‌سازیِ دستی
 *
 *  دکمه فقط یک درخواستِ «شلیک کن و فراموش کن» می‌فرستد و بعد فایلِ
 *  پیشرفت را رصد می‌کند. این عمدی است: کلِ زنجیره ممکن است چند دقیقه
 *  طول بکشد و اگر منتظرِ پاسخ می‌ماندیم، بستنِ تب یا خوابِ گوشی کار را
 *  «به نظر» شکست‌خورده نشان می‌داد — دقیقاً همان اشتباهی که در v9.07
 *  برای استخراجِ تفصیلی رفع شد.
 * ═══════════════════════════════════════════════════════════════════ */
let msTimer=null;

function msSetState(txt,cls){
  const el=$('msState');
  if(el){el.textContent=txt;el.className='cst '+(cls||'off');}
}

let syncPipeRows=[];const syncPipeExpanded=new Set();
function syncPipelineToggle(key){if(syncPipeExpanded.has(key))syncPipeExpanded.delete(key);else syncPipeExpanded.add(key);syncPipelineRender();}
function syncPipelineControl(key,action){
  const label=action==='stop'?'توقف این همگام‌سازی':'ادامهٔ این همگام‌سازی';
  if(!confirm(label+'؟'))return;const fd=new FormData();fd.append('profile_key',key);fd.append('control',action);
  fetch('?sync_pipeline_control=1',{method:'POST',body:fd,cache:'no-store'}).then(r=>r.json()).then(d=>{if(!d.ok){showToast(d.error||'عملیات ناموفق بود',1);return;}showToast(action==='stop'?'⏹ متوقف شد':'▶ ادامه در صف اجرا قرار گرفت');syncPipelineRender();}).catch(()=>showToast('خطا در کنترل همگام‌سازی',1));
}
function syncPipelineClearDone(){
  if(!confirm('همهٔ همگام‌سازی‌های تمام‌شده، خطادار و متوقف پاک شوند؟ کارهای فعال باقی می‌مانند.'))return;
  fetch('?sync_pipeline_clear_done=1',{cache:'no-store'}).then(r=>r.json()).then(d=>{
    if(!d.ok){showToast(d.error||'پاک‌سازی انجام نشد',1);return;}
    showToast('🧹 '+toFa(d.removed||0)+' همگام‌سازی تمام‌شده پاک شد');syncPipelineRender();
  }).catch(()=>showToast('خطا در پاک‌سازی همگام‌سازی‌ها',1));
}
const syncCountLabels={extracted:'استخراج',new:'جدید',updated:'آپدیت',removed:'حذف/رفته',unchanged:'بدون تغییر',price_up:'گران',price_down:'ارزان',products:'محصول',queued:'صف‌شده',sent:'ارسال',failed:'خطا',skipped:'ردشده'};
function syncPipelineRender(){
  const host=$('syncPipelineCards');if(!host)return;
  fetch('?sync_pipeline_status=1').then(r=>r.json()).then(d=>{
    syncPipeRows=Array.isArray(d.rows)?d.rows.slice(0,8):[];const rows=syncPipeRows;
    if(!rows.length){host.innerHTML='';return;}
    const stages=[['extract','⚡','استخراج بک‌اند سریع'],['pricing','٪','ذخیره و اعمال ضرایب'],['send','↑','ساخت صف و ارسال'],['done','✓','پایان و گزارش']];
    const idx={queued:0,extract:0,pricing:1,send:2,done:3};
    host.innerHTML=rows.map((row,ri)=>{
      const bad=row.stage==='error'||row.stage==='stopped';
      const cur=idx[bad?(row.failed_stage||'extract'):row.stage]??0,terminal=row.stage==='done';
      const details=row.stage_details||{};
      const steps=stages.map((s,i)=>{
        const complete=terminal||i<cur,active=!terminal&&i===cur,failed=bad&&active,det=details[s[0]]||{};
        const cls=failed?'failed':active?'active':complete?'done':'';
        const state=failed?(row.stage==='stopped'?'متوقف':'خطا'):active?'در حال انجام':complete?'انجام شد':'در انتظار';
        let pct=complete?100:0;if(active){pct=Math.max(6,Math.min(99,parseInt(row.stage_progress)||42));if(s[0]==='send'&&det.counts&&!row.stage_progress){const q=parseInt(det.counts.queued)||0,done=(parseInt(det.counts.sent)||0)+(parseInt(det.counts.updated)||0)+(parseInt(det.counts.failed)||0);if(q>0)pct=Math.max(8,Math.min(96,Math.round(done*100/q)));}}
        const counts=det.counts&&typeof det.counts==='object'?Object.entries(det.counts).filter(x=>parseInt(x[1])||['extracted','products','queued'].includes(x[0])).slice(0,7):[];
        const minis=counts.length?'<span class="sync-pipe-mini">'+counts.map(([k,v])=>'<button type="button" class="sync-pipe-count" onclick="event.stopPropagation();syncDetailOpen('+ri+',\''+s[0]+'\',\''+k+'\')"><b>'+toFa(parseInt(v)||0)+'</b>'+esc(syncCountLabels[k]||k)+'</button>').join('')+'</span>':'';
        return '<div class="sync-pipe-step '+cls+'" style="--pipe-progress:'+pct+'%" onclick="syncDetailOpen('+ri+',\''+s[0]+'\')"><span class="sync-pipe-dot">'+(complete?'✓':failed?'!':s[1])+'</span>'
          +'<span class="sync-pipe-name">'+s[2]+'</span><span class="sync-pipe-state">'+state+' · '+toFa(pct)+'٪<b style="display:block;color:#7dd3fc;margin-top:2px">مشاهده جزئیات ›</b></span>'+minis+'</div>';
      }).join('');
      const key=String(row.profile_key||''),ek=encodeURIComponent(key),expanded=syncPipeExpanded.has(key),activePct=terminal?100:(bad?Math.max(0,cur*25):Math.min(99,Math.round(cur*25+(parseInt(row.stage_progress)||42)/4)));
      const canStop=!terminal&&!bad,canContinue=row.stage==='stopped'||row.stage==='error';
      return '<article class="sync-pipe-card '+(expanded?'':'collapsed')+'"><header class="sync-pipe-head" onclick="syncPipelineToggle(decodeURIComponent(\''+ek+'\'))"><span class="sync-pipe-title">'+esc(row.profile_name||key||'—')+'</span><span class="sync-pipe-overall-label">'+toFa(activePct)+'٪</span></header>'
        +'<div style="display:flex;align-items:center;gap:7px"><div class="sync-pipe-overall" style="flex:1"><i style="width:'+activePct+'%"></i></div></div>'
        +'<div class="sync-pipe-controls"><button class="btn btn-red" '+(canStop?'':'disabled')+' onclick="event.stopPropagation();syncPipelineControl(decodeURIComponent(\''+ek+'\'),\'stop\')">⏹ توقف</button><button class="btn btn-green" '+(canContinue?'':'disabled')+' onclick="event.stopPropagation();syncPipelineControl(decodeURIComponent(\''+ek+'\'),\'continue\')">▶ ادامه</button></div>'
        +'<div class="sync-pipe-detail"><div class="sync-pipe-track">'+steps+'</div>'
        +(row.message?'<div class="sync-pipe-msg" style="color:'+(bad?'#fca5a5':'#94a3b8')+'">'+esc(row.message)+'</div>':'')+'</div></article>';
    }).join('');
  }).catch(()=>{});
}
function syncDetailOpen(rowIndex,stage,filterKey){
  const row=syncPipeRows[rowIndex]||{},det=((row.stage_details||{})[stage])||{};
  const labels={extract:'استخراج بک‌اند',pricing:'ذخیره و اعمال ضرایب',send:'صف و ارسال',done:'گزارش پایان'};
  const title=$('syncDetailTitle'),body=$('syncDetailBody'),modal=$('syncDetailModal');if(!body||!modal)return;
  /* fixed داخل پنل‌های transform/overflow بعضی تم‌ها محبوس می‌شود؛ مودال را
     هنگام اولین کلیک مستقیماً زیر body می‌بریم تا همیشه واقعاً دیده شود. */
  if(modal.parentNode!==document.body)document.body.appendChild(modal);
  if(title)title.textContent=(labels[stage]||stage)+' — '+(row.profile_name||row.profile_key||'');
  const counts=det.counts&&typeof det.counts==='object'?det.counts:{};
  let html='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(90px,1fr));gap:7px">'+Object.entries(counts).map(([k,v])=>'<div class="sync-pipe-count" style="cursor:default"><b>'+toFa(parseInt(v)||0)+'</b>'+esc(syncCountLabels[k]||k)+'</div>').join('')+'</div>';
  if(det.report)html+='<div class="sync-detail-product" style="border-color:#2563eb;color:#bfdbfe">'+esc(String(det.report))+'</div>';
  let lists=det.lists&&typeof det.lists==='object'?det.lists:{};
  let keys=filterKey&&Array.isArray(lists[filterKey])?[filterKey]:Object.keys(lists);
  const listNames={new:'محصولات جدید',updated:'محصولات آپدیت‌شده',removed:'محصولات حذف‌شده/رفته'};
  keys.forEach(k=>{const arr=Array.isArray(lists[k])?lists[k]:[];if(!arr.length)return;html+='<h4 style="color:#e2e8f0;margin:7px 0 0">'+esc(listNames[k]||k)+' · '+toFa(arr.length)+'</h4>'+arr.map(p=>'<div class="sync-detail-product"><b style="color:#f8fafc">'+esc(p.title||'—')+'</b>'+(p.price?'<div>قیمت: '+esc(p.price)+'</div>':'')+(p.link?'<a href="'+esc(p.link)+'" target="_blank" rel="noopener">مشاهده محصول ↗</a>':'')+'</div>').join('');});
  if(filterKey&&(!lists[filterKey]||!lists[filterKey].length))html+='<div class="sync-detail-product">برای این شمارنده فهرست محصول جداگانه‌ای ثبت نشده است؛ گزارش و شمارندهٔ کامل مرحله در بالا دیده می‌شود.</div>';
  const data=det.data&&typeof det.data==='object'?det.data:{};
  if(Array.isArray(data.destinations)&&data.destinations.length)html+='<h4 style="color:#e2e8f0;margin:7px 0 0">صف‌های مقصد</h4>'+data.destinations.map(x=>'<div class="sync-detail-product"><b>'+(x.destination==='bsl'?'باسلام':'ووکامرس')+'</b> · '+esc(x.status||'')+'<div>'+toFa(x.current||0)+' از '+toFa(x.total||0)+' · خطا '+toFa(x.failed||0)+'</div></div>').join('');
  const simple=Object.entries(data).filter(x=>['string','number','boolean'].includes(typeof x[1])).slice(0,20);
  if(simple.length)html+='<details class="sync-detail-product"><summary style="cursor:pointer;color:#93c5fd">داده‌های فنی مرحله</summary><div style="margin-top:7px">'+simple.map(([k,v])=>'<div><span style="color:#64748b">'+esc(k)+':</span> '+esc(String(v))+'</div>').join('')+'</div></details>';
  body.innerHTML=html||'<div class="sync-detail-product">این مرحله هنوز شروع نشده و جزئیاتی ثبت نشده است.</div>';modal.classList.add('open');document.body.style.overflow='hidden';
}
function syncDetailClose(){const m=$('syncDetailModal');if(m)m.classList.remove('open');document.body.style.overflow='';}
document.addEventListener('keydown',e=>{if(e.key==='Escape')syncDetailClose();});
setInterval(syncPipelineRender,3000);setTimeout(syncPipelineRender,500);

function startManualSync(){
  const url=($('url')&&$('url').value.trim())
            ||($('profileSelect')&&$('profileSelect').value.trim())||'';
  if(!url){
    showToast('⚠️ ابتدا یک پروفایل انتخاب یا ذخیره کنید',1);
    switchMainTab('profiles');
    return;
  }
  if(!confirm('کلِ فرآیندِ همین پروفایل همین حالا اجرا شود؟\n\n'
     +'استخراج بک‌اند سریع ← اعمال ضرایب ← صف‌سازی و ارسال ← گزارش\n\n'
     +'بسته به تعدادِ محصولات ممکن است چند دقیقه طول بکشد؛ بستنِ صفحه کار را قطع نمی‌کند.'))return;
  /* v10.79: کلید واقعی پروفایل (از آرایهٔ profiles / currentProfileKey)
     — نه فقط profileKey(url) که گاهی با کلید روی دیسک یکی نیست
     و فیلتر only در سرور هیچ پروفایلی پیدا نمی‌کند → صف خالی می‌ماند. */
  const resolveManualKey=()=>{
    try{
      if(typeof currentProfileKey==='string'&&currentProfileKey.trim()){
        if(Array.isArray(profiles)&&profiles.some(p=>p&&p.key===currentProfileKey))return currentProfileKey.trim();
      }
    }catch(e){}
    try{
      if(Array.isArray(profiles)){
        const hit=profiles.find(p=>p&&(p.url===url||p.key===url||(p.url&&profileKey(p.url)===profileKey(url))));
        if(hit&&hit.key)return String(hit.key);
        if(hit&&hit.url)return profileKey(hit.url)||String(hit.key||'');
      }
    }catch(e){}
    return profileKey(url)||url;
  };
  const go=()=>msFire(resolveManualKey());
  /* موتورِ سرور پروفایل را از دیسک می‌خواند، پس تغییرِ ذخیره‌نشده اول
     باید بنشیند وگرنه با سلکتور/ضریبِ قدیمی اجرا می‌شود. */
  if(typeof isDirty!=='undefined'&&isDirty&&typeof saveProfileSilent==='function'){
    saveProfileSilent();
    showToast('💾 ذخیره شد — شروع همگام‌سازی...');
    setTimeout(go,900);
    return;
  }
  go();
}

function msFire(pkey){
  const btn=$('manualSyncBtn'); if(btn)btn.disabled=true;
  const box=$('manualSyncProgress'); if(box)box.style.display='block';
  const sb=$('manualSyncStopBtn'); if(sb)sb.classList.remove('hidden');
  const rep=$('msReport'); if(rep)rep.innerHTML='';
  msSetState('در حال اجرا','on');
  if($('msPhase'))$('msPhase').textContent='⏳ در حال شروع…';
  if($('msLog'))$('msLog').innerHTML='';
  try{ if(typeof switchMainTab==='function') switchMainTab('start'); }catch(e){}
  /* v10.81: مثل استخراج بک‌اند — پنل پیشرفت استخراج + صف را همان لحظه باز کن */
  try{ if(typeof openExtractPanel==='function') openExtractPanel('🔄 همگام‌سازی دستی — استخراج بک‌اند'); }catch(e){}
  try{ if(typeof watchExtractProgress==='function') watchExtractProgress(); }catch(e){}
  try{ if(typeof refreshExtractQueue==='function') refreshExtractQueue(); }catch(e){}
  fetch('?manual_sync=1&profile='+encodeURIComponent(pkey)+'&force=1')
    .then(r=>r.text()).then(t=>{
      /* v10.61 (۷۵): پاسخ ndjson است — خطِ اول «شروع شد» و هر خطِ بعدی
         یک ضربانِ زنده تا پایانِ کار. نتیجهٔ واقعی را همان‌طور از فایلِ
         پیشرفت می‌گیریم (msPoll)؛ تنها اگر خطِ آخر خطا/رد باشد همین‌جا
         متوقف می‌شویم. */
      let last=null;
      const lines=String(t).trim().split('\n');
      for(let i=lines.length-1;i>=0;i--){try{last=JSON.parse(lines[i]);break;}catch(e){}}
      if(last&&last.ok===false){
        msFinish(false,(last.error||'شروع نشد'));
        return;
      }
      try{ if(typeof refreshExtractQueue==='function') refreshExtractQueue(); }catch(e){}
    }).catch(()=>{/* خطای شبکه — وضعیت را از پویینگِ دستی می‌پرسیم */});
  showToast('🔄 همگام‌سازی شروع شد — پیشرفت و صف استخراج را همین‌جا ببینید');
  msWatch();
  setTimeout(()=>{ try{ refreshExtractQueue(); }catch(e){} }, 800);
  setTimeout(()=>{ try{ refreshExtractQueue(); }catch(e){} }, 2500);
}

function msWatch(){
  if(msTimer)clearInterval(msTimer);
  msTimer=setInterval(msPoll,2000);
  setTimeout(msPoll,600);
}

function msPoll(){
  fetch('?manual_sync_status=1').then(r=>r.json()).then(d=>{
    const p=(d&&d.progress)||{};
    const tot=parseInt(p.total)||3, cur=Math.min(tot,parseInt(p.current)||0);
    const bar=$('msBar'); if(bar)bar.style.width=Math.round(cur*100/Math.max(1,tot))+'%';
    const ph=$('msPhase');
    if(ph)ph.textContent=(p.phase?('▸ '+p.phase):'')+(p.profile_name?(' — '+p.profile_name):'');
    const lg=$('msLog');
    if(lg&&Array.isArray(p.recent_log))
      lg.innerHTML=p.recent_log.slice(-20).map(l=>'<div>'+esc(String(l))+'</div>').join('');
    /* v10.79: صف استخراج را حین اجرا هم تازه کن تا کاربر ردیف را ببیند */
    try{ if(typeof refreshExtractQueue==='function') refreshExtractQueue(); }catch(e){}
    if(p.done){
      /* v10.58 (۷۲): اگر اجرا از دستِ هاست نیمه‌کاره مانده، سرور آن را با
         error بسته است — پیامش را نشان بده تا کاربر بداند و دوباره بزند. */
      msFinish(!p.cancelled && !p.error,
        p.cancelled?'با درخواستِ شما متوقف شد':(p.error||''), p.summary||'');
    }
  }).catch(()=>{});
}

function msFinish(ok,msg,summary){
  if(msTimer){clearInterval(msTimer);msTimer=null;}
  const btn=$('manualSyncBtn'); if(btn)btn.disabled=false;
  const sb=$('manualSyncStopBtn'); if(sb)sb.classList.add('hidden');
  msSetState(ok?'تمام شد':'متوقف','off');
  const bar=$('msBar'); if(bar&&ok)bar.style.width='100%';
  const rep=$('msReport');
  if(rep){
    if(summary){
      rep.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;'
        +'font-size:11px;color:#cbd5e1;white-space:pre-wrap;line-height:1.9">'+esc(summary)+'</div>';
    }else if(msg){
      rep.innerHTML='<div style="color:'+(ok?'#4ade80':'#fbbf24')+';font-size:11px">'+esc(msg)+'</div>';
    }
  }
  showToast(ok?'✅ همگام‌سازی تمام شد — گزارش ثبت و ارسال شد':('⏹ '+(msg||'متوقف شد')),!ok);
  try{refreshExtractQueue();}catch(e){}
  try{tmPulse();}catch(e){}
  if(ok)msKickSend(); /* v10.49 (۶۳): اگر چیزی صف شده، ارسال را با اتصالِ مرورگر بکوب */
}

/* v10.49 (۶۳): بعد از پایانِ همگام‌سازیِ دستی، اگر محصولی در صفِ ارسال
   منتظر است، پردازنده را با یک fetch مرورگری راه بیندازیم — روی هاستِ
   شما پردژهٔ ارسال فقط تا وقتی که یک کلاینت وصل است زنده می‌ماند، و
   مرورگرِ همین تب آن کلاینت است. بدون این، صف به حالِ خود رها می‌ماند
   و کران هر ۵ دقیقه فقط چند ثانیه جلویش می‌راند.
   v10.50 (۶۴): حالا کارگرِ دستی خودش ارسال را کاملاً سرورساید جلو می‌رساند،
   پس هشدارِ «تب را باز نگه دارید» لازم نیست؛ این کیک فقط شتاب‌دهندهٔ
   اختیاری و پشتیبانِ زمانی است که کارگرِ سرورساید زنده نیست (در آن
   حالت قفلِ flock جلوی تداخل را می‌گیرد). */
function msKickSend(){
  const box=$('msReport');
  const kick=(label,statusUrl,actionName)=>{
    fetch(statusUrl).then(r=>r.json()).then(q=>{
      const entries=Array.isArray(q.entries)?q.entries:[];
      const waiting=entries.filter(e=>e.status==='waiting'||e.status==='paused');
      const running=entries.filter(e=>e.status==='running');
      if(!waiting.length&&!running.length)return;
      const pend=entries.filter(e=>['waiting','running','paused'].includes(e.status))
        .reduce((a,e)=>a+Math.max(0,(parseInt(e.total)||0)-(parseInt(e.current)||0)),0);
      if(box)box.innerHTML+='<div style="margin-top:8px;background:#1e293b;border:1px solid #475569;border-radius:8px;padding:8px;font-size:11px;color:#cbd5e1;line-height:1.8">'
        +'📤 <b>'+toFa(pend)+'</b> product for <b>'+label+'</b> entered the send queue'
        +(waiting.length?' — starting send…':' — a send is in progress')
        +'. <b style="color:#34d399">Sending is handled fully server-side</b> — no need to keep this tab open; if the server-side worker is not running, this kick keeps the send alive with the browser connection.'
        +' <button class="btn btn-cyan" onclick="switchMainTab(\'send\')" style="font-size:9.5px;padding:2px 8px;margin-right:6px">📡 See sending</button></div>';
      if(waiting.length&&running.length===0){
        /* no live process ⇒ start it ourselves with a connection that stays open */
        fetch('?action='+actionName,{method:'GET'}).catch(()=>{});
      }
      try{ if(actionName==='bsl_backend'){bSend=true;pollBslProgress();}else{pollWooProgress();} }catch(e){}
    }).catch(()=>{});
  };
  kick('باسلام','?bsl_queue_status=1','bsl_backend');
  kick('ووکامرس','?woo_queue_status=1','woo_backend');
}

function stopManualSync(){
  if(!confirm('همگام‌سازیِ دستی متوقف شود؟ کارِ نیمه‌تمام در نوبتِ بعدی ادامه پیدا می‌کند.'))return;
  fetch('?manual_sync_stop=1').then(r=>r.json()).then(()=>{
    showToast('⏹ درخواستِ توقف ثبت شد — پس از پروفایلِ جاری می‌ایستد');
  }).catch(()=>showToast('✗ خطا شبکه',1));
}

/* v10.35 (۴۷د): گزارشِ همگام‌سازی‌های گذشته */
function srLoad(){
  const rep=$('msReport'); if(!rep)return;
  rep.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ در حال خواندن…</div>';
  fetch('?sync_report=1&limit=25').then(r=>r.json()).then(d=>{
    if(!d.ok){rep.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا</div>';return;}
    const items=d.items||[];
    if(!items.length){
      rep.innerHTML='<div style="color:#64748b;font-size:11px;background:#0f172a;padding:8px;border-radius:8px">'
        +'هنوز هیچ همگام‌سازی‌ای ثبت نشده.</div>';
      return;
    }
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px">'
      +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px">'
      +'<span style="font-size:11px;color:#34d399;font-weight:700;flex:1">📄 '+toFa(d.total)+' گزارشِ ثبت‌شده</span>'
      +'<button class="btn btn-gray" onclick="srClear()" style="font-size:9.5px;padding:2px 8px">🗑 پاک‌کردن</button></div>';
    items.forEach((r,i)=>{
      h+='<details style="border-top:1px solid #1e293b;padding:4px 0">'
        +'<summary style="cursor:pointer;color:#cbd5e1;font-size:11px">'
        +esc(r.at_h||'—')+' — '+esc(r.profile||'?')
        +(r.trigger==='manual'||r.trigger==='manual_sync'?' <span style="color:#34d399">دستی</span>':'') /* v10.53 (۶۷) */
        +'</summary>'
        +'<div style="white-space:pre-wrap;color:#94a3b8;font-size:10.5px;line-height:1.9;padding:4px 8px 2px">'
        +esc(r.text||'')+'</div></details>';
    });
    h+='</div>';
    rep.innerHTML=h;
  }).catch(()=>{rep.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا در ارتباط</div>';});
}

function srClear(){
  if(!confirm('کلِ گزارشِ همگام‌سازی‌ها پاک شود؟ خودِ محصولات دست نمی‌خورند.'))return;
  fetch('?sync_report_clear=1').then(r=>r.json()).then(()=>{
    const rep=$('msReport'); if(rep)rep.innerHTML='<div style="color:#4ade80;font-size:11px">✓ پاک شد</div>';
  }).catch(()=>{});
}

/**
 * v8.28: پنل پیشرفت استخراج — یک ظاهر واحد برای هر سه مسیر
 * (دکمهٔ استخراج بک‌اند، دکمهٔ اجرای حالا، و کران‌جاب). قبلاً هرکدام
 * پنل خودش را می‌ساخت و «اجرای حالا» نه شمارنده داشت نه دکمهٔ توقف و
 * نه اصلاً polling را شروع می‌کرد، برای همین به نظر می‌رسید کاری نمی‌کند.
 */
/* v10.180: جعبهٔ لاگِ استخراج — رندرِ یک‌باره و رنگی به‌جای «الحاقِ کور»
   قبلاً هر ۱/۵ ثانیه کلِ recent_log دوباره به انتهای جعبه چسبانده می‌شد و
   خطِ ⏳ شروع ناگهان ده‌ها بار تکرار می‌شد. حالا HTML ساخته‌شده فقط وقتی
   عوض می‌شود که محتوا واقعاً فرق کرده باشد — تکرار غیرممکن است. */
function ensureExtractLogStyles(){
    if($('exlStyle'))return;
    const st=document.createElement('style');st.id='exlStyle';
    st.textContent='.exl{padding:2px 6px;margin:1px 0;border-right:3px solid transparent;border-radius:4px;line-height:1.8;white-space:pre-wrap;word-break:break-word;direction:rtl;background:rgba(148,163,184,.05)}'
        +'.exl:hover{background:rgba(148,163,184,.11)}'
        +'.exl-btn{font-size:11px;line-height:1;padding:5px 10px;border-radius:6px;border:1px solid #47556966;background:#1e293b;color:#cbd5e1;cursor:pointer}'
        +'.exl-btn:hover{background:#334155}';
    document.head.appendChild(st);
}
function extractLogRow(m){
    const s=String(m);let c='#94a3b8';
    if(s.includes('✅')||s.includes('✓'))c='#4ade80';
    else if(s.includes('❌'))c='#f87171';
    else if(s.includes('🛡')||s.includes('⚠'))c='#fbbf24';
    else if(s.includes('🔍')||s.includes('🧪'))c='#67e8f9';
    else if(s.includes('📄'))c='#facc15';
    else if(s.includes('⛳')||s.includes('⏸')||s.includes('⏹'))c='#fb923c';
    else if(s.includes('⏯')||s.includes('⏭')||s.includes('🔄'))c='#c4b5fd';
    else if(s.includes('⏳'))c='#a78bfa';
    return '<div class="exl" style="color:'+c+';border-right-color:'+c+'">'+esc(s)+'</div>';
}
function extractLogCopy(){
    const d=$('extractLog');if(!d)return;
    navigator.clipboard.writeText(d.innerText).then(()=>showToast('📋 لاگ کپی شد'));
}
function extractLogClear(){
    const d=$('extractLog');if(!d)return;
    d.innerHTML='';d.__lastH='';
}

function openExtractPanel(title){
    switchMainTab('start');
    const panel=$('extractProgressPanel');
    if(panel){
        ensureExtractLogStyles();
        panel.style.display='block';
        panel.innerHTML='<div style="color:#a855f7;font-weight:bold;padding:8px;margin-bottom:4px;background:#2e106530;border-radius:6px">'+esc(title)+'</div>'
            +'<div id="liveCounters" class="live-cnt"></div>'
            +'<div style="display:flex;align-items:center;gap:6px;margin:8px 0 4px">'
            +'<span style="font-size:12px;color:#a5b4fc;font-weight:bold">📜 گزارش زندهٔ اجرا</span><span style="flex:1"></span>'
            +'<button type="button" class="exl-btn" onclick="extractLogCopy()" title="همهٔ خطوطِ لاگ به حافظه کپی می‌شود">📋 کپی لاگ</button>'
            +'<button type="button" class="exl-btn" onclick="extractLogClear()" title="فقط نمایشِ این جعبه پاک می‌شود؛ اجرا ادامه دارد">🧹 پاک‌کردن نمایش</button>'
            +'</div>'
            +'<div id="extractLog" style="max-height:400px;overflow-y:auto;font-size:11px;color:#e2e8f0;background:#0f172a80;border:1px solid #33415555;border-radius:8px;padding:6px 8px"></div>'
            +'<div id="extractStats" style="display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-top:10px"></div>'
            +'<div style="text-align:center;margin-top:8px"><button class="btn btn-red" onclick="stopBackendExtract()">⏹ توقف</button></div>';
    }
    if($('extractStatusText'))$('extractStatusText').textContent='⚡ در حال استخراج...';
    if($('extractProgressBar')){$('extractProgressBar').style.width='0%';$('extractProgressBar').style.background='linear-gradient(90deg,#7c3aed,#a855f7)';}
    if($('extractProgress'))$('extractProgress').classList.remove('hidden');
    refreshExtractQueue();
}

/** شروع (یا ازسرگیری) رصد پیشرفت — از چند بار اجرا شدن جلوگیری می‌کند */
function watchExtractProgress(){
    if(extractPollTimer)clearInterval(extractPollTimer);
    extractPollTimer=setInterval(pollExtractProgress,1500);
}
function stopBackendExtract(){
    // v8.91: پاسخ را بخوان و صف را بلافاصله تازه کن، تا اگر ردیف مرده
    // بسته شد کاربر همان لحظه ببیند و منتظر نماند.
    fetch('?extract_stop=1').then(r=>r.json()).then(()=>{
        refreshExtractQueue();
    }).catch(()=>{});
    if(extractPollTimer)clearInterval(extractPollTimer);
    $('extractStatusText').textContent='⏹ متوقف شد';
    $('extractProgress').classList.add('hidden');
    setTimeout(refreshExtractQueue,1000);
}
// v8.20: Extraction queue rendered in the same visual language as the
// Basalam/WooCommerce send queues (status badge, progress bar, counters,
// elapsed time, per-row actions).
/* v10.58 (۷۲): دکترِ همگام‌سازی — چرا کار نمی‌کند؟ */
function syncDiagnose(){
  const box=$('syncDiagnoseBox'); if(!box)return;
  box.style.display='block';
  box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ در حالِ معاینهٔ زنجیره…</div>';
  fetch('?sync_diagnose=1').then(r=>r.json()).then(d=>{
    if(!d.ok){box.innerHTML='<div style="color:#f87171;font-size:11px">✗ معاینه نشد</div>';return;}
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px">';
    h+='<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px">'
      +'<span style="font-size:11px;color:#34d399;font-weight:700;flex:1">🩺 معاینهٔ زنجیرهٔ همگام‌سازی</span>'
      +'<button class="btn btn-gray" onclick="syncDiagnose()" style="font-size:9.5px;padding:2px 8px">↺ تکرار</button></div>';
    (d.checks||[]).forEach(c=>{
      h+='<div style="font-size:10.5px;color:'+(c.ok?'#86efac':'#fca5a5')+';line-height:1.7;padding:2px 0">'
        +(c.ok?'✅ ':'⚠️ ')+esc(c.msg)+'</div>';
    });
    const bad=(d.profiles||[]).filter(p=>!p.ok);
    if((d.profiles||[]).length){
      h+='<div style="font-size:10px;color:#94a3b8;margin-top:6px;border-top:1px solid #1e293b;padding-top:4px"><b>پروفایل‌ها:</b></div>';
      (d.profiles||[]).forEach(p=>{
        h+='<div style="font-size:10px;color:'+(p.ok?'#86efac':'#fbbf24')+';padding:1px 0">'
          +(p.ok?'✅ ':'⚠️ ')+esc(p.name)
          +(p.issues.length?(' — '+p.issues.map(esc).join('، ')):' — آمادهٔ اجرا')+'</div>';
      });
    }
    /* v10.66 (۸۰): صفِ استخراج + آخرین همگام‌سازیِ دستی + تشخیص */
    if(d.queue){
      h+='<div style="font-size:10px;color:#94a3b8;margin-top:6px;border-top:1px solid #1e293b;padding-top:4px"><b>صفِ استخراج:</b></div>';
      h+='<div style="font-size:10px;color:#e2e8f0;padding:1px 0">ردیف‌ها: '+toFa(d.queue.count||0)+' · فعال: '+toFa(d.queue.active||0)+'</div>';
      (d.queue.rows||[]).forEach(r=>{
        const cc=(r.status==='running'||r.status==='waiting'||r.status==='paused')?'#fbbf24':(r.status==='done'?'#86efac':'#f87171');
        h+='<div style="font-size:10px;color:'+cc+';padding:1px 0">• '+esc(r.profile||'—')+' — '+esc(r.status)
          +(r.products?(' · '+toFa(r.products)+' محصول'):'')
          +(r.age>0?(' · '+toFa(r.age)+' ثانیه پیش'):'')
          +(r.error?(' · '+esc(r.error)):'')+'</div>';
      });
      if(d.queue.manual){
        const m=d.queue.manual;
        const mst=m.running?'🔄 در حال اجرا':(m.cancelled?'⏹ متوقف شد':(m.done?'✅ انجام شد':'—'));
        h+='<div style="font-size:10px;color:#e2e8f0;padding:2px 0">آخرین همگام‌سازیِ دستی: '+mst
          +(m.profile?(' — '+esc(m.profile)):'')
          +(m.phase?(' · '+esc(m.phase)):'')
          +(m.age>0?(' · '+toFa(m.age)+' ثانیه پیش'):'')
          +(m.error?('<div style="color:#f87171;font-size:10px">'+esc(m.error)+'</div>'):'')+'</div>';
        (m.log_tail||[]).forEach(l=>{h+='<div style="font-size:9.5px;color:#64748b;padding:0 0 0 10px">'+esc(l)+'</div>';});
      }
      if(d.queue.why){
        h+='<div style="font-size:10.5px;color:#fbbf24;padding:4px 0;line-height:1.7">💡 '+esc(d.queue.why)+'</div>';
      }
    }
    const problems=(d.checks||[]).filter(c=>!c.ok).length + bad.length;
    h+='<div style="margin-top:6px;font-size:11px;font-weight:700;color:'+(problems===0?'#4ade80':'#fbbf24')+'">'
      +(problems===0
        ?'✅ کلِ زنجیره باز است. اگر کارتی در صف نمی‌بینید، همین حالا «همگام‌سازیِ دستی» را بزنید و صف را نگاه کنید.'
        :'⚠️ '+toFa(problems)+' نکته نیاز به رسیدگی دارد — جزئیات را در بالا ببینید.')+'</div>';
    h+='</div>';
    box.innerHTML=h;
  }).catch(()=>{box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطای شبکه</div>';});
}

/* v10.70 (84): صفِ استخراج «زنده» — خودش تازه می‌شود.
   تا حالا پیشرفتِ ردیف‌ها فقط با کلیکِ 🔄 (یا شروع/توقف/پاک‌سازی) دیده می‌شد،
   پس کارِ پس‌زمینه (کران، نگهبان، ادامهٔ کارِ گیرکرده) را کاربر نمی‌دید مگر
   ریفرش می‌زد. حالا هر بارِ خواندن، نوبتِ بعد را خودش می‌چیند:
   ردیفِ فعال (در صف/در حال اجرا/متوقف) ⇒ هر ۳ ثانیه؛ وگرنه ⇒ هر ۱۵ ثانیه
   تا شروعِ کارِ بعدی هم آنی دیده شود. دکمهٔ 🔄 همان کارِ قبلی را می‌کند
   (و زمان‌سنج را هم از اول می‌شمارد). */
let exqInFlight=false, exqTimer=null;
function exqSchedule(ms){
  if(exqTimer)clearTimeout(exqTimer);
  exqTimer=setTimeout(refreshExtractQueue,ms);
}
function exqSetLive(active){
  try{
    const el=$('exqLive');
    if(!el)return;
    el.style.display='inline';
    el.style.color=active?'#4ade80':'#64748b';
    el.textContent=active?'● زنده':'● پایشِ آهسته';
  }catch(e){}
}
function refreshExtractQueue(){
  if(exqInFlight)return;
  exqInFlight=true;
  fetch('?extract_queue_status=1').then(r=>r.json()).then(d=>{
    if(!d.ok)return;
    renderExtractQueue(d.entries||[], d.progress||{});
    const entries=d.entries||[];
    const active=entries.some(e=>e.status==='waiting'||e.status==='running'||e.status==='paused');
    exqSetLive(active);
    exqSchedule(active?3000:15000);
  }).catch(()=>exqSchedule(5000)).then(()=>{exqInFlight=false;});
}

function renderExtractQueue(entries, progress){
    const list=$('extractQueueList');
    if(!list)return;
    if(!entries.length){
        list.innerHTML='<span style="color:#64748b">صف خالی — برای افزودن، دکمه «⚡ استخراج بک‌اند» را کلیک کنید</span>';
        return;
    }
    const statusLabels={waiting:'⏳ در صف',running:'🔄 در حال استخراج',paused:'⏹ متوقف شد',done:'✅ انجام شد',failed:'❌ خطا',superseded:'↪ checkpoint جایگزین شد'};
    const statusColors={waiting:'#fbbf24',running:'#a855f7',paused:'#f97316',done:'#4ade80',failed:'#f87171',superseded:'#94a3b8'};
    const statusBg={waiting:'#42200630',running:'#7c3aed20',paused:'#c2410c20',done:'#14532d20',failed:'#7f1d1d20',superseded:'#33415540'};

    let html='';
    entries.slice().reverse().forEach(e=>{
        const st=statusLabels[e.status]?e.status:'failed';
        // Shared progress belongs to one queue ID; never paint it onto a parallel row.
        const runningCount=entries.filter(x=>x&&x.status==='running').length;
        const progressOwns=progress&&((String(progress.queue_id||'')===String(e.id||''))
            ||(!progress.queue_id&&runningCount===1));
        const live=(st==='running'&&progress&&progress.running&&progressOwns)?progress:null;
        const total=(live&&live.total)||e.total||0;
        const current=(live&&live.current)||e.current||0;
        const products=e.products_count||(live&&live.extracted)||0;
        const newC=(live&&live.new)||e.new||0;
        const chgC=(live&&live.price_changed)||e.price_changed||0;
        const remC=(live&&live.removed)||e.removed||0;
        const unchC=(live&&live.unchanged)||e.unchanged||0;
        /* v8.90: شمارندهٔ تصاویر — هم برای ردیف در حال اجرا (از progress)
           و هم برای ردیف تمام‌شده (از خود ردیف صف). */
        const galImgs=(live&&live.gallery_images)||e.gallery_images||0;
        const galProds=(live&&live.gallery_products)||e.gallery_products||0;
        const dOk=(live&&live.detail_ok)||e.detail_ok||0;
        const dFail=(live&&live.detail_fail)||e.detail_fail||0;
        const dFields=(live&&live.detail_fields)||e.detail_fields||0;
        const varProds=(live&&live.variation_products)||e.variation_products||0;
        const detCur=(live&&live.detail_current)||0;
        const detTot=(live&&live.detail_total)||0;

        let progText='', progPercent=0;
        if(st==='running'){
            if(total>0){
                progPercent=Math.min(100,Math.round(current/total*100));
                progText=toFa(current)+'/'+toFa(total)+' ('+toFa(progPercent)+'٪)';
            }else{
                progText='در حال آماده‌سازی...';
            }
            if(products>0)progText+=' | '+toFa(products)+'📦 '+toFa(newC)+'🆕 '+toFa(chgC)+'💰 '+toFa(remC)+'❌';
            // v8.90: وقتی فاز جزئیات در جریان است، پیشرفت همان را نشان بده
            if(live&&live.phase==='detail'&&detTot>0){
                progText='🔍 جزئیات '+toFa(detCur)+'/'+toFa(detTot);
                if(galImgs>0)progText+=' | 🖼 '+toFa(galImgs)+' تصویر';
                if(dFail>0)progText+=' | ❌ '+toFa(dFail);
            }else if(galImgs>0){
                progText+=' | 🖼 '+toFa(galImgs);
            }
        }else if(st==='paused'){
            progPercent=total>0?Math.round(current/total*100):0;
            progText=(total>0?(toFa(current)+'/'+toFa(total)+' — '):'')
                    +(e.stopped_by_user?'با دکمهٔ توقف متوقف شد':'متوقف');
            if(products>0)progText+=' | '+toFa(products)+' محصول تا این لحظه';
            if(e.resume_page) progText+=' · ▶️ ادامه از ص '+toFa(e.resume_page);
            e.resumable = true;
        }else if(st==='done'){
            progPercent=100;
            progText='✓ '+toFa(products)+' محصول | '+toFa(newC)+' جدید | '+toFa(chgC)+' تغییر قیمت | '
                    +toFa(remC)+' حذف‌شده | '+toFa(unchC)+' بدون تغییر';
            // v8.90: تصاویر استخراج‌شده هم در خلاصهٔ ردیف تمام‌شده
            if(galImgs>0)progText+=' | 🖼 '+toFa(galImgs)+' تصویر'
                +(galProds>0?(' از '+toFa(galProds)+' محصول'):'');
        }else if(st==='waiting'){
            progText=total>0?(toFa(total)+' محصول — منتظر شروع'):'منتظر شروع';
        }else if(st==='failed'){
            progText=e.error?esc(e.error):'استخراج ناتمام ماند';
            if(e.resumable||e.resume_page){
                progText+=' · ▶️ قابل ادامه'+(e.resume_page?(' از ص '+toFa(e.resume_page)):'');
            }
        }else if(st==='superseded'){
            progText='checkpoint تکراری بود؛ ادامه از ردیف '+esc(e.superseded_by||'تازه‌تر')+' انجام می‌شود';
        }
        if(e.stop_requested)progText='⏳ درخواست توقف ثبت شد؛ در حال آزادکردن قفل worker — checkpoint محفوظ است';
        /* v9.11: ردیف گزارشیِ استخراج دوره‌ای — متن خودش را دارد و
           شمارنده‌های محصول برایش بی‌معناست. */
        if(e.note_only){
            progText='<b style="color:#f9a8d4">'+esc(e.note_title||'')+'</b>'
                +(Array.isArray(e.note_lines)&&e.note_lines.length
                    ?('<br>'+e.note_lines.map(l=>esc(l)).join('<br>')):'');
            progPercent=0;
        }

        html+='<div onclick="showExtractLogModal(\''+esc(e.id)+'\')" style="cursor:pointer;padding:8px 10px;border:1px solid #334155;border-radius:8px;margin:4px 0;background:'+statusBg[st]+';transition:background 0.2s" onmouseover="this.style.borderColor=\'#a855f7\'" onmouseout="this.style.borderColor=\'#334155\'">';

        // ردیف ۱: وضعیت + نام پروفایل + دکمه‌ها
        html+='<div style="display:flex;justify-content:space-between;align-items:center">';
        html+='<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">';
        const statusLabel=e.stop_requested?'⏳ در حال توقف':statusLabels[st];
        const statusColor=e.stop_requested?'#fb923c':statusColors[st];
        html+='<span style="color:'+statusColor+';font-weight:700;font-size:12px">'+statusLabel+'</span>';
        // v10.284: منشأ همهٔ ردیف‌ها، از جمله worker و resume، صریحاً دستی یا دوره‌ای باشد
        const exManual=['manual','manual_sync','manual_resume','worker','worker_child'].includes(e.trigger);
        const exPeriodic=['periodic_sync','auto','cron','watchdog_resume','auto_resume'].includes(e.trigger);
        if(exManual){
            const isSync=e.trigger==='manual_sync';
            html+='<span style="color:#34d399;font-size:10px;background:#064e3b40;padding:1px 6px;border-radius:4px">'+(isSync?'🤝 استخراج همگام‌سازی · دستی':'👤 استخراج دستی')+'</span>';
        }else if(exPeriodic){
            const isSync=e.trigger==='periodic_sync';
            html+='<span style="color:#22d3ee;font-size:10px;background:#0e749020;padding:1px 6px;border-radius:4px">'+(isSync?'🔄 استخراج همگام‌سازی · دوره‌ای':'⏱ استخراج دوره‌ای')+'</span>';
        }else{
            html+='<span style="color:#cbd5e1;font-size:10px;background:#334155;padding:1px 6px;border-radius:4px">👤 استخراج دستی</span>';
        }
        /* v9.04: کدام مرحله؟ بدون این، ردیف «فهرست» با شمارندهٔ صفرِ
           جزئیات شبیه یک اجرای ناموفق به نظر می‌رسید. */
        if(e.phase==='list'){
            html+='<span style="color:#fbbf24;font-size:10px;background:#42200630;padding:1px 6px;border-radius:4px">📄 مرحله ۱: فهرست</span>';
        }else if(e.phase==='detail'){
            html+='<span style="color:#f9a8d4;font-size:10px;background:#50072430;padding:1px 6px;border-radius:4px">🔍 مرحله ۲: جزئیات</span>';
        }
        if(e.profile_name)html+='<span style="color:#94a3b8;font-size:10px">'+esc(e.profile_name)+'</span>';
        if(products>0)html+='<span style="color:#e2e8f0;font-weight:600;font-size:12px">'+toFa(products)+' محصول</span>';
        html+='</div>';
        html+='<div style="display:flex;gap:4px">';
        if(st==='running'||st==='waiting'||e.stop_requested){
            const stopLabel=e.stop_requested?'⏳ توقف در جریان':(st==='waiting'?'✖ لغو از صف':'⏹ توقف');
            html+='<button class="btn" style="font-size:10px;padding:3px 8px;background:#f97316;color:#fff;border:none;border-radius:4px" onclick="event.stopPropagation();stopExtractQueue(\''+esc(e.id)+'\')">'+stopLabel+'</button>';
        }else{
            if((st==='failed'||st==='paused') && e.profile_key){
                const rp=e.resume_page||0;
                html+='<button class="btn" style="font-size:10px;padding:3px 8px;background:#059669;color:#fff;border:none;border-radius:4px" onclick="event.stopPropagation();resumeExtractQueue(\''+esc(e.profile_key)+'\',\''+esc(e.id)+'\','+(rp||0)+')" title="ادامه از یک صفحه قبل از محل گیر">▶ ادامه'+(rp?(' از '+toFa(rp)):'')+'</button>';
            }
            const archivedRow=st==='done'||st==='superseded';
            html+='<button class="btn" style="font-size:10px;padding:3px 8px;background:'+(archivedRow?'#334155':'#dc2626')+';color:'+(archivedRow?'#94a3b8':'#fff')+';border:none;border-radius:4px" onclick="event.stopPropagation();deleteExtractQueue(\''+esc(e.id)+'\')">🗑️ حذف</button>';
        }
        html+='</div></div>';

        // ردیف ۲: نوار پیشرفت
        if(!e.note_only&&(progPercent>0||st==='running'||st==='paused'||st==='done')){
            html+='<div style="margin-top:4px"><div style="height:4px;background:#1e293b;border-radius:2px;overflow:hidden"><div style="height:100%;background:'+statusColors[st]+';width:'+progPercent+'%;border-radius:2px;transition:width 0.5s"></div></div></div>';
        }

        // ردیف ۳: متن پیشرفت
        if(progText)html+='<div style="color:#94a3b8;font-size:10px;margin-top:3px">'+progText+'</div>';
        if(e.sync_stage&&e.note_title){
            html+='<div style="color:'+(e.sync_skipped?'#fbbf24':'#7dd3fc')+';font-size:9.5px;margin-top:3px">'+(e.sync_skipped?'↪ ':'🔗 ')+esc(e.note_title)+'</div>';
        }

        /* v8.90: نشان‌های شمارشی — تصاویر، فیلدها، تنوع‌ها و شکست‌ها.
           تا حالا فقط تعداد محصول دیده می‌شد و معلوم نبود از دل جزئیات چه
           چیزی واقعاً بیرون آمده. */
        if(!e.note_only&&(galImgs>0||dFields>0||varProds>0||dFail>0)){
            const badge=(bg,fg,txt)=>'<span style="background:'+bg+';color:'+fg
                +';font-size:9.5px;padding:1px 6px;border-radius:9px;white-space:nowrap">'+txt+'</span>';
            html+='<div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:4px">';
            if(galImgs>0)  html+=badge('#500724','#f9a8d4','🖼 '+toFa(galImgs)+' تصویر'
                                 +(galProds>0?(' / '+toFa(galProds)+' محصول'):''));
            if(dFields>0)  html+=badge('#1e1b4b','#c4b5fd','🏷 '+toFa(dFields)+' فیلد');
            if(varProds>0) html+=badge('#164e63','#67e8f9','🎨 '+toFa(varProds)+' تنوع‌دار');
            if(dOk>0)      html+=badge('#14532d','#86efac','✅ '+toFa(dOk)+' صفحه');
            if(dFail>0)    html+=badge('#7f1d1d','#fca5a5','❌ '+toFa(dFail)+' باز نشد');
            html+='</div>';
        }

        // ردیف ۴: زمان سپری‌شده یا زمان پایان
        if(st==='running'&&e.started_at>0){
            const el=Math.floor(Date.now()/1000-e.started_at);
            const es=el>=60?(Math.floor(el/60)+' دقیقه '+(el%60)+' ثانیه'):(el+' ثانیه');
            html+='<div style="color:#64748b;font-size:9px;margin-top:2px">⏱ '+es+'</div>';
        }else if(e.started_at>0){
            html+='<div style="color:#64748b;font-size:9px;margin-top:2px">⏱ '+new Date(e.started_at*1000).toLocaleString('fa-IR')+'</div>';
        }

        html+='<div style="color:#475569;font-size:9px;margin-top:1px">کلیک برای گزارش تفصیلی →</div>';
        html+='</div>';
    });
    list.innerHTML=html;
}

function deleteExtractQueue(qid){
    if(!confirm('این ردیف از صف حذف شود؟'))return;
    fetch('?extract_queue_delete=1&queue_id='+encodeURIComponent(qid)).then(r=>r.json()).then(d=>{
        if(d.ok){showToast('🗑️ حذف شد');refreshExtractQueue();}
        else showToast(d.message||d.error||'خطا در حذف',1);
    }).catch(()=>showToast('خطا شبکه',1));
}

function clearExtractQueueDone(){
    fetch('?extract_queue_clear_done=1').then(r=>r.json()).then(d=>{
        if(d.ok){showToast('🧹 '+toFa(d.removed||0)+' ردیف پاک شد');refreshExtractQueue();}
        else showToast(d.error||'خطا',1);
    }).catch(()=>showToast('خطا شبکه',1));
}

function resumeExtractQueue(profileKey, qid, resumePage, autoResume){
    resumePage = resumePage||0;
    const msg = resumePage>0
      ? ('ادامهٔ استخراج از صفحه '+resumePage+'؟\n(یک صفحه قبل از جایی که گیر کرده — از اول شروع نمی‌شود)')
      : 'ادامهٔ استخراج این پروفایل از آخرین نقطه؟';
    if(!autoResume&&!confirm(msg))return;
    showToast((autoResume?'♻️ ادامهٔ خودکار از ':'▶️ در حال ادامه از ')+(resumePage?('صفحه '+resumePage):'نقطهٔ ذخیره')+'…');
    const fd=new FormData();
    fd.append('action','extract_resume');
    fd.append('profile_key', profileKey||'');
    if(qid) fd.append('queue_id', qid);
    if(typeof extractPollTimer!=='undefined' && extractPollTimer) clearInterval(extractPollTimer);
    // Do not poll the previous completed snapshot while the resume request is
    // pending; it would replay the old completion toast before a new run starts.
    fetch('?extract_resume=1&profile_key='+encodeURIComponent(profileKey||'')
        +'&queue_id='+encodeURIComponent(qid||''), {method:'POST', body:fd})
      .then(r=>r.json()).then(d=>{
        if(!d||!d.ok){ showToast((d&&d.error)||'ادامه ناموفق',1); return; }
        const resumedPhase=d.phase||'list';
        showToast(resumedPhase==='detail'?'▶️ ادامهٔ جزئیات از checkpoint شروع شد':('▶️ ادامهٔ صفحه‌ای از صفحه '+(d.start_page||resumePage||'?')+' شروع شد'));
        try{
          if($('extractProgress'))$('extractProgress').classList.remove('hidden');
          if($('extractStatusText'))$('extractStatusText').textContent='▶️ ادامه از صفحه '+(d.start_page||'…');
        }catch(e){}
        if(typeof extractPollTimer!=='undefined' && extractPollTimer) clearInterval(extractPollTimer);
        if(typeof pollExtractProgress==='function'){
          extractPollTimer=setInterval(pollExtractProgress,1500);
          pollExtractProgress();
        }
        refreshExtractQueue();
        setTimeout(refreshExtractQueue,2000);
        if(d.browser_held&&d.result&&d.result.resume_needed){
          const r=d.result||{};
          const sig=[r.extracted||0,r.detail_done||0,d.start_page||0,d.phase||''].join('|');
          if(window._extractAutoResumeSig!==sig){window._extractAutoResumeSig=sig;window._extractAutoResumeCount=0;}
          window._extractAutoResumeCount=(window._extractAutoResumeCount||0)+1;
          if(window._extractAutoResumeCount<=15)setTimeout(()=>resumeExtractQueue(profileKey,(r.queue_id||qid),d.start_page||resumePage,true),2000);
        }else window._extractAutoResumeCount=0;
      }).catch(e=>{
        showToast('اتصال ادامه قطع شد؛ تلاش خودکار دوباره…',1);
        window._extractAutoResumeCount=(window._extractAutoResumeCount||0)+1;
        if(window._extractAutoResumeCount<=15)setTimeout(()=>resumeExtractQueue(profileKey,qid,resumePage,true),5000);
      });
}
function stopExtractQueue(qid){
    if(!confirm('این استخراج/کارِ در صف لغو شود؟ ردیف و checkpoint برای ادامه حفظ می‌شوند.'))return;
    /* The queue ID lets the server signal/cancel only this row's worker. */
    fetch('?extract_stop=1&queue_id='+encodeURIComponent(qid||'')).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){showToast((d&&d.error)||'درخواست توقف ناموفق بود',1);return;}
        const n=(d.stopped&&d.stopped.length)||0;
        const pending=(d.stop_pending&&d.stop_pending.length)||0;
        showToast(pending>0?'⏳ درخواست توقف ارسال شد؛ worker در حال آزادکردن قفل است و checkpoint حفظ می‌شود'
            :(n>0?'⏹ متوقف شد؛ ردیف و checkpoint حفظ شدند':'⏹ درخواست توقف ثبت شد'));
        refreshExtractQueue();
        setTimeout(refreshExtractQueue,1200);
        setTimeout(refreshExtractQueue,3500);
    }).catch(()=>showToast('خطا شبکه',1));
}
// v7.81: Show extract log modal for a specific queue entry
function showExtractLogModal(queueId){
    // Create modal
    let modal=$('extractLogModal');
    if(!modal){
        modal=document.createElement('div');
        modal.id='extractLogModal';
        modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;z-index:99999;background:rgba(0,0,0,.7);display:flex;align-items:center;justify-content:center';
        document.body.appendChild(modal);
    }
    modal.style.display='flex';
    modal.innerHTML='<div style="background:#1e293b;border:1px solid #475569;border-radius:12px;padding:16px;width:90%;max-width:700px;max-height:85vh;overflow-y:auto;color:#e2e8f0">'
        +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">'
        +'<span style="font-weight:700;font-size:14px;color:#a855f7">📋 گزارش استخراج بک‌اند</span>'
        +'<button class="btn btn-gray" onclick="closeExtractLogModal()" style="font-size:10px;padding:4px 8px">✕</button>'
        +'</div>'
        +'<div id="extractModalCounters" class="live-cnt"></div>'
        +'<div id="extractModalPhase2"></div>'
        +'<div id="extractModalLog" style="font-size:11px;max-height:45vh;overflow-y:auto;margin-top:10px">بارگذاری...</div>'
        +'</div>';
    // v8.25: شمارنده‌های قابل کلیک این اجرا را بارگذاری کن
    loadExtractModalCounters(queueId);
    renderPhase2Report(queueId);
    pollExtractLogModal();
}

/**
 * v9.04: گزارش صریح مرحلهٔ ۲ (استخراج تفصیلی).
 *
 * تا حالا معلوم نبود این مرحله اصلاً اجرا شده یا نه — کاربر فقط می‌دید
 * گالری نیامده و نمی‌توانست بفهمد کجای کار ایراد دارد. حالا همان
 * عددهایی که موتور ثبت کرده مستقیم نشان داده می‌شوند.
 */
function renderPhase2Report(queueId){
    const box=$('extractModalPhase2');
    if(!box)return;
    fetch('?extract_queue_status=1').then(r=>r.json()).then(d=>{
        const rows=(d&&d.entries)||[];
        const e=rows.find(x=>x.id===queueId);
        if(!e){box.innerHTML='';return;}
        /* v9.11: ردیف گزارشیِ استخراج دوره‌ای — متن آماده دارد و
           شمارنده‌های فاز ۲ برایش معنا ندارد. */
        if(e.note_only){
            let nh='<div style="margin-top:10px;padding:10px 12px;background:#0f172a;border:1px solid #334155;border-radius:10px">';
            nh+='<div style="font-weight:700;font-size:12px;color:#f9a8d4;margin-bottom:6px">'+esc(e.note_title||'')+'</div>';
            nh+='<div style="font-size:11px;color:#cbd5e1;line-height:2">'
              +((e.note_lines||[]).map(l=>esc(l)).join('<br>'))+'</div>';
            nh+='<div style="font-size:10px;color:#64748b;margin-top:8px">'
              +'این ردیف گزارشِ «استخراج دوره‌ای جزئیات» است. ردیف‌های «🔍 مرحله ۲: جزئیات» '
              +'کار واقعی استخراج را نشان می‌دهند.</div>';
            nh+='</div>';
            box.innerHTML=nh;
            return;
        }
        const runningCount=rows.filter(x=>x&&x.status==='running').length;
        const progressOwns=String(d.progress&&d.progress.queue_id||'')===String(e.id||'')
            ||(!(d.progress&&d.progress.queue_id)&&runningCount===1);
        const live=(e.status==='running'&&d.progress&&d.progress.running&&progressOwns)?d.progress:null;
        const pages=(live&&live.detail_ok)||e.detail_ok||0;
        const fail =(live&&live.detail_fail)||e.detail_fail||0;
        const flds =(live&&live.detail_fields)||e.detail_fields||0;
        const imgs =(live&&live.gallery_images)||e.gallery_images||0;
        const gprd =(live&&live.gallery_products)||e.gallery_products||0;
        const vars =(live&&live.variation_products)||e.variation_products||0;
        const tot  =(live&&live.detail_total)||e.detail_total||0;

        const phaseLbl = e.phase==='list' ? '📄 مرحله ۱ — استخراج فهرست'
                       : (e.phase==='detail' ? '🔍 مرحله ۲ — استخراج تفصیلی'
                                             : '⚡ استخراج کامل (فهرست + جزئیات)');
        let h='<div style="margin-top:10px;padding:10px 12px;background:#0f172a;border:1px solid #334155;border-radius:10px">';
        h+='<div style="font-weight:700;font-size:12px;color:#f9a8d4;margin-bottom:6px">'+phaseLbl+'</div>';

        if(e.phase==='list'){
            h+='<div style="font-size:11px;color:#94a3b8;line-height:1.9">'
             +'این ردیف فقط صفحهٔ فهرست را گرفته — گرفتن گالری و فیلدها کار مرحلهٔ ۲ است.<br>'
             +'ردیف «🔍 مرحله ۲» را در همین صف ببینید.</div>';
        }else if(pages===0&&fail===0&&tot===0){
            /* v9.05: قبلاً همیشه می‌گفت «همه از قبل کامل بودند» — که وقتی
               گالری اصلاً نیامده دروغ است. حالا علت واقعی گفته می‌شود. */
            const why=e.detail_skip_why||'';
            const noLink=e.detail_no_link||0, already=e.detail_already||0;
            let msg='', color='#fbbf24';
            if(why==='no_config'){
                color='#f87171';
                msg='⛔ نه سلکتور جزئیات تنظیم شده و نه گالری روشن است.<br>'
                   +'برای همین این مرحله کاری نداشت. در تب سلکتورها،'
                   +' «سلکتورهای صفحهٔ جزئیات» یا «🖼 گالری» را تنظیم کنید.';
            }else if(why==='no_link'){
                color='#f87171';
                msg='⛔ هیچ‌کدام از '+toFa(noLink)+' محصول «لینک» ندارند.<br>'
                   +'بدون لینک نمی‌شود صفحهٔ محصول را باز کرد، پس گالری و جزئیات'
                   +' هرگز استخراج نمی‌شوند.<br>'
                   +'<b>راه‌حل:</b> در تب سلکتورها سلکتور «🔗 لینک» را تنظیم کنید'
                   +' و یک بار استخراج فهرست را دوباره بزنید.';
            }else if(why==='already_done'){
                msg='⏭ هر '+toFa(already)+' محصول از قبل گالری و همهٔ فیلدهای'
                   +' خواسته‌شده را داشتند، پس دوباره باز نشدند.<br>'
                   +'اگر گالری‌ها را نمی‌بینید، یعنی داده روی دیسک هست ولی جای'
                   +' دیگری گم می‌شود — گزارش را بفرستید.';
            }else if(why==='nothing_selected'){
                color='#f87171';
                msg='⛔ محصولی برای باز کردن انتخاب نشد'
                   +(noLink>0?(' ('+toFa(noLink)+' محصول بدون لینک)'):'')
                   +(already>0?(' · '+toFa(already)+' محصول از قبل کامل'):'')+'.';
            }else if(why==='no_products'){
                color='#f87171';
                msg='⛔ روی سرور هیچ محصولی ذخیره نشده بود، پس مرحلهٔ جزئیات'
                   +' چیزی برای باز کردن نداشت.<br>'
                   +'<b>راه‌حل:</b> اول «⚡ استخراج بک‌اند» را بزنید تا فهرست'
                   +' روی سرور بنشیند، بعد استخراج تفصیلی.';
            }else{
                /* v9.09: این پیام عمومی یعنی موتور علتی ثبت نکرده — که
                   خودش یک نشانه است، نه یک وضعیت عادی. */
                msg='⏭ این مرحله چیزی برای انجام نداشت.'
                   +(noLink>0?('<br>⚠️ '+toFa(noLink)+' محصول لینک ندارند.'):'')
                   +(already>0?('<br>'+toFa(already)+' محصول از قبل کامل بودند.'):'')
                   +'<br><span style="color:#64748b">اگر گالری نیامده، این ردیف مالِ'
                   +' مرحلهٔ فهرست است؛ ردیف «🔍 مرحله ۲» را ببینید.</span>';
            }
            h+='<div style="font-size:11px;color:'+color+';line-height:1.9">'+msg+'</div>';
        }else{
            const cell=(bg,fg,big,lbl)=>'<div style="background:'+bg+';border-radius:8px;padding:7px;text-align:center">'
                +'<b style="color:'+fg+';font-size:15px">'+toFa(big)+'</b>'
                +'<br><span style="color:#94a3b8;font-size:9.5px">'+lbl+'</span></div>';
            h+='<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:6px">';
            h+=cell('#14532d20','#4ade80',pages,'✅ صفحه باز شد');
            h+=cell(fail>0?'#7f1d1d20':'#1e293b',fail>0?'#f87171':'#475569',fail,'❌ باز نشد');
            h+=cell('#1e1b4b','#c4b5fd',flds,'🏷 فیلد');
            h+=cell('#50072430','#f9a8d4',imgs,'🖼 تصویر');
            h+=cell('#164e6320','#67e8f9',vars,'🎨 تنوع‌دار');
            h+='</div>';
            h+='<div style="font-size:10.5px;color:#94a3b8;margin-top:7px;line-height:1.9">';
            if(tot>0)h+='از '+toFa(tot)+' محصولی که لازم بود باز شود، '+toFa(pages)+' موفق بود.<br>';
            if(gprd>0)h+='🖼 '+toFa(imgs)+' تصویر از '+toFa(gprd)+' محصول جمع شد.<br>';
            /* v9.09: وقتی صفحه‌ها باز شده‌اند ولی عکسی نیامده، علت تقریباً
               همیشه سلکتور کادر گالری است — پس خودش را نشان بده. */
            if(imgs===0&&pages>0&&e.gallery_enabled===false){
                h+='<span style="color:#94a3b8">ℹ️ استخراج گالری در این اجرا غیرفعال بود (روش گالری روی «خاموش» بود).</span><br>';
            }else if(imgs===0&&pages>0){
                h+='<span style="color:#f87171">⛔ '+toFa(pages)+' صفحهٔ محصول باز شد ولی'
                 +' هیچ تصویر گالری‌ای پیدا نشد.</span><br>';
                h+='<span style="color:#fbbf24">کادر گالری: <code style="direction:ltr;display:inline-block">'
                 +esc(e.gallery_box||'(تنظیم نشده)')+'</code></span><br>';
                h+='<span style="color:#94a3b8">یعنی این سلکتور با ساختار صفحهٔ محصول نمی‌خواند،'
                 +' یا عکس‌ها با جاوااسکریپت تزریق می‌شوند و در HTML خام نیستند.'
                 +' یک صفحهٔ محصول را در تب سلکتورها باز کنید و کادر گالری را دوباره انتخاب کنید.</span><br>';
            }else if(imgs===0&&e.gallery_enabled!==false){
                h+='<span style="color:#fbbf24">⚠️ هیچ تصویر گالری‌ای جمع نشد — سلکتور «باکس گالری» یا دسترسی سرور به صفحهٔ محصول را بررسی کنید.</span><br>';
            }
            if(fail>0)h+='<span style="color:#f87171">⛔ '+toFa(fail)+' صفحه باز نشد — اگر ۴۰۳/۴۲۹ بود یعنی IP سرور بلاک شده.</span>';
            h+='</div>';
        }
        h+='</div>';
        box.innerHTML=h;
    }).catch(()=>{});
}

/**
 * v8.25: شمارنده‌های جدید/تغییر قیمت/حذف‌شده را برای یک اجرای مشخص
 * می‌آورد. با کلیک روی هرکدام، فهرست محصولات همان دسته باز می‌شود.
 */
function loadExtractModalCounters(queueId){
    const box=$('extractModalCounters');
    if(box)box.innerHTML='<div style="grid-column:1/-1;color:#64748b;font-size:11px;padding:6px">در حال بارگذاری شمارنده‌ها...</div>';
    fetch('?extract_report=1&queue_id='+encodeURIComponent(queueId)).then(r=>r.json()).then(d=>{
        if(!box)return;
        if(!d.ok){
            box.innerHTML='<div style="grid-column:1/-1;color:#64748b;font-size:11px;padding:6px">'+esc(d.error||'گزارشی موجود نیست')+'</div>';
            return;
        }
        const rp=d.report||{};
        // همان داده‌ای که مودال جزئیات از آن می‌خواند
        extractReportData={
            newItems:rp.new_items||[], changedItems:rp.changed_items||[],
            removedItems:rp.removed_items||[], unchangedCount:rp.unchanged||0,
            totalOld:0
        };
        buildStatusMap();refreshResultBadges();
        // شمارنده‌ها از خودِ گزارش خوانده می‌شوند نه از طول لیست،
        // چون لیست‌ها سقف ۳۰۰ تایی دارند ولی شمارش باید دقیق باشد.
        const nNew=rp.new!=null?rp.new:(rp.new_items||[]).length;
        const nChg=rp.price_changed!=null?rp.price_changed:(rp.changed_items||[]).length;
        const nRem=rp.removed!=null?rp.removed:(rp.removed_items||[]).length;
        const nUnc=rp.unchanged||0;
        const up=rp.price_up||0, down=rp.price_down||0;
        const gone=rp.gone_from_site||0, noPrice=rp.no_price||0;
        const ppm=extractAvgPpm(rp);

        const cell=(icon,label,val,color,type,extra)=>
            '<div class="lc" style="border-color:'+color+'33" onclick="showExtractReport(\''+type+'\')" title="کلیک برای دیدن فهرست">'
            +'<b style="color:'+color+'">'+toFa(val)+'</b><span>'+icon+' '+label+'</span>'
            +(extra?'<i style="color:#64748b">'+extra+'</i>':'')+'</div>';

        box.innerHTML=
            '<div class="lc" style="border-color:#67e8f933"><b style="color:#67e8f9">'+toFa(rp.extracted||0)+'</b><span>📦 کل</span></div>'
            +cell('🆕','جدید',nNew,'#4ade80','new')
            +cell('💰','تغییر قیمت',nChg,'#facc15','changed',nChg?('▲'+toFa(up)+' ▼'+toFa(down)):'')
            +cell('❌','حذف/ناموجود',nRem,'#f87171','removed',noPrice?('🚫'+toFa(noPrice)+' بی‌قیمت'):'')
            +cell('⏭','بدون تغییر',nUnc,'#94a3b8','unchanged')
            +cell('⚡','سرعت میانگین',ppm,'#a78bfa','none','محصول/دقیقه');
    }).catch(()=>{
        if(box)box.innerHTML='<div style="grid-column:1/-1;color:#f87171;font-size:11px;padding:6px">خطا در دریافت گزارش</div>';
    });
}
function closeExtractLogModal(){
    const modal=$('extractLogModal');
    if(modal)modal.style.display='none';
    if(extractModalTimer)clearInterval(extractModalTimer);
}
function pollExtractLogModal(){
    if(extractModalTimer)clearInterval(extractModalTimer);
    extractModalTimer=setInterval(()=>{
        fetch('?poll_extract=1').then(r=>r.json()).then(d=>{
            if(!d)return;
            const logDiv=$('extractModalLog');
            if(!logDiv)return;
            const logs=d.recent_log||[];
            const running=d.running||false;
            const done=d.done||false;
            const extracted=d.extracted||0;
            const newC=d.new||0;const changedC=d.price_changed||0;const removedC=d.removed||0;
            let html='';
            if(done){
                html+='<div style="color:#4ade80;font-weight:700;margin-bottom:8px">✅ تکمیل: '+toFa(extracted)+' محصول</div>';
                if(newC>0)html+='<div style="color:#4ade80;font-size:11px">🆕 '+toFa(newC)+' جدید</div>';
                if(changedC>0)html+='<div style="color:#facc15;font-size:11px">💰 '+toFa(changedC)+' تغییر قیمت</div>';
                if(removedC>0)html+='<div style="color:#f87171;font-size:11px">❌ '+toFa(removedC)+' حذف شده</div>';
                clearInterval(extractModalTimer);
            }else if(running){
                html+='<div style="color:#a855f7;font-weight:700;margin-bottom:8px">⏳ در حال اجرا — '+toFa(extracted)+' محصول</div>';
            }
            if(logs.length>0){
                logs.forEach(m=>{
                    let cls='color:#94a3b8';
                    if(m.includes('✅')||m.includes('✓'))cls='color:#4ade80';
                    if(m.includes('❌'))cls='color:#f87171';
                    if(m.includes('📄'))cls='color:#facc15';
                    if(m.includes('🔍'))cls='color:#67e8f9';
                    html+='<div style="'+cls+';padding:2px 4px">'+esc(m)+'</div>';
                });
            }
            logDiv.innerHTML=html;
        }).catch(()=>{});
    },2000);
}
// v10.195: میانگین سرعت استخراج برای شمارندهٔ ششمِ زنده و گزارش نهایی.
function extractAvgPpm(d){
    const count=Number((d&&d.extracted)||0);
    if(!count)return 0;
    let started=Number((d&&d.started_at)||0);
    let finished=Number((d&&d.finished_at)||0);
    if(started>0){
        const endMs=finished>0?finished*1000:Date.now();
        const mins=Math.max((endMs-started*1000)/60000,1/60);
        return Math.max(0,Math.round(count/mins));
    }
    return Number((d&&d.avg_ppm)||0)||0;
}

// v8.22: clickable live counters shown while the extraction runs
function renderLiveCounters(d){
    const box=$('liveCounters');
    if(!box)return;
    const nNew=d.new||0, nChg=d.price_changed||0, nRem=d.removed||0, nUnc=d.unchanged||0;
    const up=d.price_up||0, down=d.price_down||0;

    // نگه داشتن داده برای باز کردن لیست‌ها بدون انتظار برای پایان کار
    extractReportData={
        newItems:d.new_items||[], changedItems:d.changed_items||[],
        removedItems:d.removed_items||[], unchangedCount:nUnc,
        totalOld:nNew+nChg+nRem+nUnc
    };
    buildStatusMap();refreshResultBadges();

    const cell=(icon,label,val,color,type,extra)=>
        '<div class="lc" style="border-color:'+color+'33" onclick="showExtractReport(\''+type+'\')" title="کلیک برای دیدن لیست">'
        +'<b style="color:'+color+'">'+toFa(val)+'</b>'
        +'<span>'+icon+' '+label+'</span>'
        +(extra?'<i style="color:#64748b">'+extra+'</i>':'')
        +'</div>';

    let extra='';
    if(nChg>0)extra='▲'+toFa(up)+' ▼'+toFa(down);
    const noPrice=d.no_price||0;   // v8.26: چند تا از حذف‌شده‌ها بی‌قیمت‌اند
    const ppm=extractAvgPpm(d);

    box.innerHTML=
        cell('📦','کل','','#67e8f9','none').replace('<b style="color:#67e8f9"></b>','<b style="color:#67e8f9">'+toFa(d.extracted||0)+'</b>')
        +cell('🆕','جدید',nNew,'#4ade80','new')
        +cell('💰','تغییر قیمت',nChg,'#facc15','changed',extra)
        +cell('❌','حذف/ناموجود',nRem,'#f87171','removed',noPrice?('🚫'+toFa(noPrice)+' بی‌قیمت'):'')
        +cell('⏭','بدون تغییر',nUnc,'#94a3b8','unchanged')
        +cell('⚡','سرعت میانگین',ppm,'#a78bfa','none','محصول/دقیقه');
}

function extractCompletionToastKey(d){
    d=d||{};
    const id=String(d.queue_id||d.profile_key||'legacy');
    const end=Number(d.finished_at||d.last_progress_ts||d.done_at||0);
    const start=Number(d.started_at||0);
    return [id,end,start,Number(d.extracted||0),Number(d.new||0),Number(d.price_changed||0),Number(d.removed||0)].join('|');
}
function rememberExtractCompletionToast(d){
    const key=extractCompletionToastKey(d);
    try{
        const stored=JSON.parse(localStorage.getItem('extract_completion_toasts_v1')||'{}');
        const seen=stored&&typeof stored==='object'?stored:{};
        if(Object.prototype.hasOwnProperty.call(seen,key))return false;
        seen[key]=Date.now();
        const recent=Object.entries(seen).sort((a,b)=>Number(b[1])-Number(a[1])).slice(0,40);
        localStorage.setItem('extract_completion_toasts_v1',JSON.stringify(Object.fromEntries(recent)));
    }catch(e){
        window._extractCompletionToastKeys=window._extractCompletionToastKeys||new Set();
        if(window._extractCompletionToastKeys.has(key))return false;
        window._extractCompletionToastKeys.add(key);
    }
    return true;
}
function rememberBslCompletionToast(d){
    d=d||{};
    const key=[String(d.queue_id||'legacy'),Number(d.finished_at||d.last_progress_ts||0),Number(d.started_at||0),Number(d.sent||0),Number(d.updated||0),Number(d.skipped||0),Number(d.failed||0)].join('|');
    try{
        const stored=JSON.parse(localStorage.getItem('bsl_completion_toasts_v1')||'{}');
        const seen=stored&&typeof stored==='object'?stored:{};
        if(Object.prototype.hasOwnProperty.call(seen,key))return false;
        seen[key]=Date.now();
        localStorage.setItem('bsl_completion_toasts_v1',JSON.stringify(Object.fromEntries(Object.entries(seen).sort((a,b)=>Number(b[1])-Number(a[1])).slice(0,40))));
    }catch(e){
        window._bslCompletionToastKeys=window._bslCompletionToastKeys||new Set();
        if(window._bslCompletionToastKeys.has(key))return false;
        window._bslCompletionToastKeys.add(key);
    }
    return true;
}

function rememberStageOneExtractSync(d){
    d=d||{};
    if(!d.list_saved_for_results||!d.profile_key||!(Number(d.list_saved_count||d.extracted||0)>0))return false;
    const key=[String(d.queue_id||d.profile_key||'legacy'),Number(d.list_saved_at||d.started_at||0)].join('|');
    try{
        const stored=JSON.parse(localStorage.getItem('extract_stage1_results_v1')||'{}');
        const seen=stored&&typeof stored==='object'?stored:{};
        if(Object.prototype.hasOwnProperty.call(seen,key))return false;
        seen[key]=Date.now();
        const recent=Object.entries(seen).sort((a,b)=>Number(b[1])-Number(a[1])).slice(0,40);
        localStorage.setItem('extract_stage1_results_v1',JSON.stringify(Object.fromEntries(recent)));
    }catch(e){
        window._extractStageOneSyncKeys=window._extractStageOneSyncKeys||new Set();
        if(window._extractStageOneSyncKeys.has(key))return false;
        window._extractStageOneSyncKeys.add(key);
    }
    return true;
}

function pollExtractProgress(){
    // v8.20: keep the queue list live while a run is in progress, the same
    // way the Basalam queue refreshes itself during a send.
    window._extractPollCount=(window._extractPollCount||0)+1;
    if(window._extractPollCount%3===0)refreshExtractQueue();

    fetch('?poll_extract=1').then(r=>r.json()).then(d=>{
        if(!d)return;
        renderLiveCounters(d);   // v8.22
        const running=!!(d.running||d.worker_continuing||d.auto_resuming);
        const done=!!d.done && !d.worker_continuing && !d.auto_resuming;
        const completionKey=done?extractCompletionToastKey(d):'';
        const firstDonePoll=done&&window._extractFinalizedCompletionKey!==completionKey;
        if(firstDonePoll)window._extractFinalizedCompletionKey=completionKey;
        const cancelled=d.cancelled||false;
        const extracted=d.extracted||0;
        const logs=d.recent_log||[];
        const phase=d.phase||'list';
        const detailMode=normalizeDetailExtractModeJs(d.detail_extract_mode||'two_stage');
        const current=d.current||0;
        const total=d.total||0;
        const newCount=d.new||0;
        const priceChanged=d.price_changed||0;
        const removed=d.removed||0;
        const unchanged=d.unchanged||0;
        const page=d.page||0;
        updateSpeedCard(extracted, d.started_at||0);

        // v10.442: روی هاست‌های بدون exec/worker نیز در صورت دریافت auto_resume_browser
        // مرورگر به‌صورت خودکار و بدون دیالوگ، ادامه از checkpoint (فاز ۱ یا فاز ۲) را اجرا می‌کند.
        if(!cancelled && d.auto_resume_browser && d.auto_resume_browser.profile_key){
            const nowMs=Date.now();
            if(!window._lastBrowserAutoResumeAt || (nowMs-window._lastBrowserAutoResumeAt)>6000){
                window._lastBrowserAutoResumeAt=nowMs;
                const br=d.auto_resume_browser;
                setTimeout(()=>resumeExtractQueue(br.profile_key, br.queue_id||'', br.resume_page||0, true), 800);
            }
        }

        // v10.441: در حالت دو مرحله‌ای (پیش‌فرض)، بلافاصله پس از پایان مرحلهٔ ۱ (لیست)
        // محصولات استخراج‌شده در تب نتایج نیز بارگذاری و ذخیره می‌شوند و سپس مرحلهٔ ۲ اجرا می‌گردد.
        if(!cancelled && !done && d.list_saved_for_results && d.profile_key && rememberStageOneExtractSync(d)){
            loadBackendExtractResults(d.profile_key, {stageOne:true, skipSaveBack:true});
        }

        // Update progress bar
        $('extractProgressBar').style.width=(total>0?Math.min(current/total*100,100):0)+'%';

        // Update status text
        let statusText='';
        if(running&&!done){
            if(d.auto_resuming && (d.paused || d.stalled || d.ran_out)){
                statusText='♻️ ادامهٔ خودکار از نقطهٔ توقف ('+(phase==='detail'?'فاز ۲: جزئیات':('فاز ۱: صفحه '+toFa(d.resume_page||page||1)))+') — '+toFa(extracted)+' محصول حفظ شده';
            }else if(phase==='list_done'){
                statusText='✅ مرحلهٔ ۱ تمام شد ('+toFa(extracted)+' محصول در تب نتایج ذخیره شد) — ورود به مرحلهٔ ۲ (استخراج جزئیات)...';
            }else if(phase==='detail'){
                statusText='🔍 مرحلهٔ ۲ (استخراج جزئیات) '+toFa(d.detail_current||0)+'/'+toFa(d.detail_total||0)+' — لیست ('+toFa(extracted)+' محصول) در تب نتایج ذخیره شده';
            }else if(phase==='list_detail'||detailMode==='inline'){
                statusText='⚡ استخراج درجا — صفحه '+toFa(page)+(d.inline_detail_current?(' · جزئیات: '+toFa(d.inline_detail_current)):'')+' · '+toFa(extracted)+' محصول';
            }else{
                statusText='📄 مرحلهٔ ۱ (استخراج لیست) — صفحه '+toFa(page)+' · '+toFa(extracted)+' محصول استخراج شده';
            }
        }else if(done){
            if(cancelled){
                statusText=d.products_saved===false ? '⏹ متوقف شد — نتایج قبلی دست‌نخورده ماند' : '⏹ متوقف شد';
            }else if(d.products_saved===false){
                statusText='⏸ ناتمام پیش از آخرین صفحه — نتایج قبلی دست‌نخورده حفظ شد';
            }else{
                statusText='✅ '+toFa(extracted)+' محصول — 🆕'+toFa(newCount)+' 💰'+toFa(priceChanged)+' ❌'+toFa(removed)+' ⏭'+toFa(unchanged);
            }
        }else if(d.error){
            statusText='❌ '+d.error;
        }
        $('extractStatusText').textContent=statusText;

        // Show logs — v10.180: رندرِ idempotent؛ اگر محتوا همان است هیچ‌کاری
        // نکن. دیگر هیچ خطی هر ۱/۵ ثانیه به انتها اضافه نمی‌شود.
        const logDiv=$('extractLog');
        if(logDiv){
            const html=logs.slice(-40).map(extractLogRow).join('');
            if(logDiv.__lastH!==html){
                const nearBottom=(logDiv.scrollHeight-logDiv.scrollTop-logDiv.clientHeight)<48;
                logDiv.innerHTML=html;logDiv.__lastH=html;
                if(nearBottom)scrollElBottom(logDiv);
            }
        }

        // Finalize once per run. poll_extract is also called by cron/UI refresh,
        // so a terminal progress file can otherwise replay this toast repeatedly.
        if(done){
            if(extractPollTimer)clearInterval(extractPollTimer);
            $('extractProgress').classList.add('hidden');
            if(firstDonePoll){
                refreshExtractQueue();
                scheduleStartBreakdownRefresh();
                if(d.products_saved!==false && (d.new_items||d.changed_items||d.removed_items)){
                    extractReportData={newItems:d.new_items||[],changedItems:d.changed_items||[],removedItems:d.removed_items||[],unchangedCount:d.unchanged||0,totalOld:(d.new_items||[]).length+(d.changed_items||[]).length+(d.removed_items||[]).length+(d.unchanged||0)};
                    buildStatusMap();refreshResultBadges();
                }
                if(!cancelled&&extracted>0&&d.products_saved!==false){
                    loadBackendExtractResults(d.profile_key||'', {skipSaveBack:true});
                    showLiveComparison();
                    const statsDiv=$('extractStats');
                    if(statsDiv){
                        const ppm=extractAvgPpm(d);
                        statsDiv.innerHTML='<div style="background:#0f172a;border-radius:8px;padding:8px;text-align:center;cursor:pointer" onclick="showExtractReport(\'new\')"><b style="color:#4ade80;font-size:16px">'+toFa(newCount)+'</b><br><span style="color:#94a3b8;font-size:10px">🆕 جدید</span></div><div style="background:#0f172a;border-radius:8px;padding:8px;text-align:center;cursor:pointer" onclick="showExtractReport(\'changed\')"><b style="color:#facc15;font-size:16px">'+toFa(priceChanged)+'</b><br><span style="color:#94a3b8;font-size:10px">💰 تغییر قیمت</span></div><div style="background:#0f172a;border-radius:8px;padding:8px;text-align:center;cursor:pointer" onclick="showExtractReport(\'removed\')"><b style="color:#f87171;font-size:16px">'+toFa(removed)+'</b><br><span style="color:#94a3b8;font-size:10px">❌ حذف شده</span></div><div style="background:#0f172a;border-radius:8px;padding:8px;text-align:center;cursor:pointer" onclick="showExtractReport(\'unchanged\')"><b style="color:#94a3b8;font-size:16px">'+toFa(unchanged)+'</b><br><span style="color:#94a3b8;font-size:10px">⏭ بدون تغییر</span></div><div style="background:#0f172a;border-radius:8px;padding:8px;text-align:center"><b style="color:#60a5fa;font-size:16px">'+toFa(extracted)+'</b><br><span style="color:#94a3b8;font-size:10px">📊 کل</span></div><div style="background:#0f172a;border-radius:8px;padding:8px;text-align:center"><b style="color:#a78bfa;font-size:16px">'+toFa(ppm)+'</b><br><span style="color:#94a3b8;font-size:10px">⚡ محصول/دقیقه</span></div>';
                    }
                    if(rememberExtractCompletionToast(d))showToast('✅ '+extracted+' محصول استخراج شد — 🆕'+newCount+' 💰'+priceChanged+' ❌'+removed);
                }else if(d.products_saved===false && !d.auto_resume_browser){
                    if(rememberExtractCompletionToast(d)){
                        showToast(cancelled
                            ? '⏹ استخراج پیش از پایان آخرین صفحه متوقف شد — محصولات قبلی در تب نتایج دست‌نخورده ماند'
                            : '⏸ استخراج پیش از پایان آخرین صفحه متوقف شد — محصولات قبلی دست‌نخورده باقی ماند', true);
                    }
                }
            }
        }
    }).catch(()=>{});
}
function loadBackendExtractResults(key, opts){
    opts = opts || {};
    // Load the profile that was just updated by backend extract
    fetch('?load_profile='+encodeURIComponent(key)).then(r=>r.json()).then(d=>{
        if(!d.ok||!d.profile)return;
        const prof=d.profile||{};
        const prods=prof.products||[];
        const prodOrder=prof.productsOrder||[];
        /* v8.89: قبلاً همین‌جا فهرست پاک می‌شد و بعد اگر productsOrder خالی
           بود، تابع برمی‌گشت — یعنی تب نتایج کاملاً خالی می‌ماند در حالی که
           محصولات (و گالری‌هایشان) روی دیسک سالم بودند. حالا اول داده را
           می‌سنجیم و ترتیب را در نبودش از خود محصولات می‌سازیم. */
        // Convert products: could be [[key,data],...] or {key:data,...}
        let prodMap={};
        if(Array.isArray(prods)&&prods.length>0){
            const first=prods[0];
            if(Array.isArray(first)&&first.length>=2&&typeof first[0]=='string'){
                // [[key,data],...] format
                prods.forEach(e=>{if(Array.isArray(e)&&e.length>=2)prodMap[e[0]]=e[1];});
            }else{
                // [{title:...,price:...},...] flat array — keyed by prodOrder
                prodOrder.forEach((k,i)=>{if(prods[i])prodMap[k]=prods[i];});
            }
        }else if(typeof prods==='object'&&prods!==null){
            // {key:data,...} object format
            prodMap=prods;
        }
        // v8.89: ترتیب نبود؟ از خود محصولات بسازش، نه اینکه همه را دور بریزی
        let keys=prodOrder.filter(k=>prodMap[k]);
        if(!keys.length)keys=Object.keys(prodMap);
        // چیزی برای نشان دادن نیست: دست به فهرست فعلی نزن
        if(!keys.length)return;
        resetResultFilter();
        products.clear();order=[];
        keys.forEach(k=>{
            const p=prodMap[k];
            if(p){
                // v8.42: کلید را روی خود شیء بنشان — پروفایل آن را جدا نگه می‌دارد
                if(typeof p==='object'&&!p.key)p.key=k;
                products.set(k,p);
                order.push(k);
            }
        });
        /* Data stays complete in memory; the Results DOM receives only the
           first scroll page and appends later pages near the viewport. */
        refreshViews();
        const activeUrl=($('url')&&$('url').value.trim())||'';
        if(prof.url && (!activeUrl || activeUrl===prof.url || profileKey(activeUrl)===(d.key||key))){
            currentProfileUpdatedAt=parseInt(prof.updatedAt||0)||currentProfileUpdatedAt;
            markClean(d.key||key);
        }
        scheduleStartBreakdownRefresh();
        if(opts.stageOne){
            const resTab=document.querySelector('.main-tab[data-tab="results"]');
            if(resTab&&typeof fxPulse==='function')fxPulse(resTab);
            showToast('💾 مرحلهٔ ۱ تمام شد: '+toFa(products.size)+' محصول در تب نتایج ذخیره شد — شروع مرحلهٔ ۲ (استخراج جزئیات)...');
        }
        // Only save back from client if explicitly needed (never overwrite an active Stage 2 worker!)
        if(!opts.skipSaveBack && $('url').value.trim()&&products.size>0)saveProfileSilent();
    }).catch(()=>{});
}
// Helper: profileKey from URL — mirrors PHP profileKey()
function profileKey(url){
    if(url && String(url).indexOf('://')===-1 && Array.isArray(profiles) && profiles.some(p=>p&&p.key===String(url).trim())){
        return String(url).trim();
    }
    // v10.67 (81): فرمولِ سمتِ سرور (PHP) مسیرِ URL را «بدونِ دیکُدِ percent»
    // می‌خواند، ولی new URL(url).pathname کاراکترهای %XX را دیکُد می‌کند؛
    // برای لینک‌های دارایِ کاراکترِ فارسی/percent-encoded کلیدِ مرورگر با
    // کلیدِ سرور یکی نبود و مثلاً همگام‌سازیِ دستی فیلترِ only هیچ
    // پروفایلی نمی‌یافت. حالا مسیر را عینِ تایپ‌شده می‌گیریم تا دقیقاً
    // هم‌زمانِ سرور بماند.
    try{
        const src=String(url).replace(/[^\x21-\x7E]/g,ch=>encodeURIComponent(ch));
        const m=src.match(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/[^/?#]*/);
        let host='',rawPath='';
        if(m){
            host=m[0].replace(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//,'').replace(/:\d+$/,'').toLowerCase();
            rawPath=src.slice(m[0].length).split(/[?#]/)[0];
        }else{
            const u=new URL(src);
            host=u.hostname.toLowerCase();
            rawPath=u.pathname;
        }
        let path=rawPath.replace(/^\/|\/$/g,'');
        // Remove /page/N suffix
        path=path.replace(/\/page\/\d+\/?$/i,'');
        // Remove .html/.htm/.php suffix
        path=path.replace(/\.(html|htm|php)$/i,'');
        // Replace non-alpha-numeric with underscore
        path=path.replace(/[^a-z0-9]+/gi,'_');
        return host+(path?'_'+path:'');
    }catch(e){return '';}
}
/**
 * v8.93: «استخراج اتوماتیک» همان دکمهٔ «⚡ استخراج بک‌اند» را می‌زند. تمام.
 *
 * در ۸.۹۲ این کار انجام شد ولی با منطق موازیِ خودش: بررسی سلکتور از روی
 * فرم، شاخهٔ جداگانه برای ذخیرهٔ نشده، عنوان پنل متفاوت. یعنی باز هم دو
 * کد بود که می‌توانستند از هم جدا بیفتند — همان اشتباهی که قرار بود حل شود.
 * حالا واقعاً همان تابع صدا زده می‌شود، بدون هیچ شرط اضافه.
 */
function startAutoExtract(){
    startBackendSync();
}

function start(useSel=false){
  if(running)return;
  const url=$('url').value.trim();
  if(!url){showToast('URL وارد کنید',true);return;}

  if (isDirty) saveProfileSilent();

  /* v10.471: تا رسیدن به انتهای آخرین صفحه (رویداد complete)، محصولات قبلی در تب نتایج
     به هیچ عنوان پاک یا جایگزین نمی‌شوند؛ محصولات استریم در بافر موقت جمع می‌شوند. */
  const stagedStreamProducts = new Map();
  const stagedStreamOrder = [];
  let streamCompleted = false;
  pages=0;details=0;running=true;extractSpeedStartMs=Date.now();
  log('▶ شروع (بدون تغییر نتایج قبلی تا پایان آخرین صفحه): '+url,'info');

  $('startBtn').classList.add('hidden');$('startManualBtn').classList.add('hidden');$('stopBtn').classList.remove('hidden');
  $('progress').classList.remove('hidden');$('progressBar').style.width='0%';
  $('status').textContent='⏳ استخراج در حافظهٔ مرحله‌ای...';
  fxBusy($('status'),true);          // v10.06: نوارِ نورِ «در حال کار»

  let sUrl=`?stream=1&url=${encodeURIComponent(url)}&pages=${$('pages').value}&pagType=${encodeURIComponent($('pagType').value)}&pagVal=${encodeURIComponent($('pagVal').value)}&extractionEngine=${encodeURIComponent(s4EngineValue())}`;
  if(currentProfileKey) sUrl+='&profile_key='+encodeURIComponent(currentProfileKey);
  if(useSel&&sel.container){
    sUrl+='&selectors='+encodeURIComponent(JSON.stringify(sel));
    log('🎯 سلکتور: '+sel.container,'info');
  }

  es=new EventSource(sUrl);

  es.addEventListener('page',e=>{const d=JSON.parse(e.data);pages=d.page;log(`📄 صفحه ${d.page}: ${d.ok?'✓':'✗'}`,d.ok?'ok':'err');$('status').textContent=`📄 صفحه ${toFa(d.page)} · ${toFa(stagedStreamProducts.size)} محصول مرحله‌ای`;updateSpeedCard(stagedStreamProducts.size,extractSpeedStartMs);});
  es.addEventListener('product',e=>{const p=JSON.parse(e.data);if(!stagedStreamProducts.has(p.key)){stagedStreamProducts.set(p.key,p);stagedStreamOrder.push(p.key);$('status').textContent=`📄 صفحه ${toFa(pages||1)} · ${toFa(stagedStreamProducts.size)} محصول مرحله‌ای`;updateSpeedCard(stagedStreamProducts.size,extractSpeedStartMs);}});
  es.addEventListener('page_done',e=>{const d=JSON.parse(e.data);log(`✓ صفحه ${d.page}: +${d.new} جدید، کل مرحله‌ای: ${d.total}`,'ok');});
  es.addEventListener('missing_start',e=>{const d=JSON.parse(e.data);$('status').textContent=`دریافت جزئیات ${toFa(d.current)}/${toFa(d.total)}`;$('progressBar').style.width=(d.current/d.total*100)+'%';});
  es.addEventListener('fetch_info',e=>{const d=JSON.parse(e.data);if(d.msg)$('status').textContent=d.msg;log(d.msg,'info');});
  es.addEventListener('missing_done',e=>{const d=JSON.parse(e.data);details++;const p=stagedStreamProducts.get(d.key);if(p){if(d.image)p.image=d.image;if(d.price)p.price=d.price;if(d.image_cached){p._imgCached=true;p._imgValid=true;}else if(d.image_valid){p._imgValid=true;}stagedStreamProducts.set(d.key,p);}});
  es.addEventListener('complete',e=>{
      const d=JSON.parse(e.data);
      if(stagedStreamProducts.size===0){
          log('⚠️ هیچ محصولی استخراج نشد — نتایج قبلی دست‌نخورده حفظ شد','err');
          showToast('⚠️ هیچ محصولی استخراج نشد — نتایج قبلی حفظ شد',true);
          return;
      }
      const prevClientSize=products.size;
      const clientLoss=prevClientSize-stagedStreamProducts.size;
      const clientCollapseLimit=prevClientSize>=200?Math.min(80,Math.ceil(prevClientSize*0.18)):Math.max(6,Math.ceil(prevClientSize*0.18));
      if(d.shrinkage_blocked || (prevClientSize>=8 && clientLoss>=clientCollapseLimit)){
          log(`🛡 گارد حفاظت نتایج: خروجی جدید (${stagedStreamProducts.size}) کمتر از نتایج قبلی (${prevClientSize}) بود — نتایج قبلی ثابت نگه داشته شد`,'err');
          showToast(`🛡 نتایج قبلی (${toFa(prevClientSize)} محصول) حفظ شد`,true);
          return;
      }
      streamCompleted=true;
      const keepDetailKeys=['images','images_count','variations','variationPrices','specs','longDesc','shortDesc','weight','package_weight','brand','category','bslCategoryId'];
      stagedStreamOrder.forEach(k=>{
          const cur=stagedStreamProducts.get(k);
          const prev=products.get(k);
          if(cur && prev){
              keepDetailKeys.forEach(fk=>{
                  if((cur[fk]===undefined||cur[fk]===''||(Array.isArray(cur[fk])&&cur[fk].length===0)) && prev[fk]!==undefined && prev[fk]!==''){
                      cur[fk]=prev[fk];
                  }
              });
          }
      });
      rvCancelChunks();
      resetResultFilter();
      products.clear();order=[];
      stagedStreamOrder.forEach(k=>{const p=stagedStreamProducts.get(k);if(p){products.set(k,p);order.push(k);}});
      refreshViews();
      log(`✅ تکمیل تا پایان آخرین صفحه: ${d.total} محصول ثبت نهایی شد`,'ok');
      $('status').textContent=`✓ ${toFa(d.total)} محصول`;
      $('progressBar').style.width='100%';
      showToast(`✓ ${d.total} محصول استخراج شد`);
      switchMainTab('results');
      fxPulse(document.querySelector('.main-tab[data-tab="results"]'));   // v10.06
      // Auto-save profile with products after scrape completes
      if($('url').value.trim() && products.size > 0) saveProfileSilent();
  });
  es.addEventListener('error',e=>{
      if(e.data){
          try{const er=JSON.parse(e.data);log('❌ '+(er.message||'خطا'),'err');if(er.interrupted)showToast('⏸ '+er.message,true);}catch(_){}
      }
  });
  es.addEventListener('done',()=>{
      if(!streamCompleted){
          $('status').textContent=products.size>0?`🛡 نتایج قبلی حفظ شد (${toFa(products.size)} محصول)`:'آماده';
      }
      finish();
  });
  es.onerror=()=>{
      if(running){
          if(!streamCompleted){
              log('⏸ اتصال پیش از پایان آخرین صفحه قطع شد — نتایج قبلی در تب نتایج دست‌نخورده ماند','err');
              showToast('⏸ استخراج پیش از آخرین صفحه قطع شد — نتایج قبلی دست‌نخورده ماند',true);
          }
          finish();
      }
  };
}

function stop(){if(es)es.close();log('⏹ متوقف شد — نتایج قبلی دست‌نخورده باقی ماند','err');showToast('⏹ استخراج متوقف شد — نتایج قبلی دست‌نخورده ماند');finish();}
function finish(){updateSpeedCard(products.size,0);extractSpeedStartMs=0;running=false;if(es){es.close();es=null;}$('startBtn').classList.remove('hidden');$('startManualBtn').classList.remove('hidden');$('stopBtn').classList.add('hidden');rvRebuildVisible();showLiveComparison();fxBusy($('status'),false);}

function startDetailExtraction(){
    if(detailRunning)return;
    const enabledFields = getEnabledDetailFields();
    // v8.64: گالری هم به تنهایی دلیل کافی برای باز کردن صفحهٔ محصول است
    const galCfg = galCollect();
    const galOn = galCfg.mode !== 'off';
    if (enabledFields.length === 0 && !galOn) {
        showToast('ابتدا فیلدهای مورد نظر یا گالری را فعال کنید', true);
        switchMainTab('selectors');
        return;
    }
    if (products.size === 0) {
        showToast('ابتدا محصولات را استخراج کنید', true);
        return;
    }

    const keys = order.filter(k => {
        const p = products.get(k);
        if (!p.link) return false;
        // با گالری روشن، محصولی که هنوز چند عکس ندارد باید بررسی شود
        if (galOn && !(p.images && p.images.length > 1)) return true;
        /* v10.15: قیمت استثناست. بقیهٔ فیلدها «یک‌بار پر می‌شوند و تمام»،
           ولی p.price تقریباً همیشه از فازِ فهرست پر است؛ با قاعدهٔ «فقط
           خالی‌ها» هیچ محصولی صف نمی‌شد و کاربری که فقط «قیمت» را فعال
           کرده بود پیام «همه از قبل استخراج شده‌اند» می‌گرفت. از آن‌طرف
           قیمت همان چیزی است که مدام عوض می‌شود، پس وقتی کاربر عمداً
           سلکتورش را داده یعنی می‌خواهد از صفحهٔ محصول تازه‌اش کند. */
        return enabledFields.some(f => f.key === 'price' ? true : !p[f.key]);
    });

    if (keys.length === 0) {
        showToast('همه فیلدها از قبل استخراج شده‌اند', true);
        return;
    }

    const urlMap = {};
    keys.forEach(k => urlMap[k] = products.get(k).link);

    detailRunning = true;
    $('btnExtractDetail').classList.add('hidden');
    $('btnStopDetail').classList.remove('hidden');
    $('detailProgress').classList.remove('hidden');
    $('detailProgressBar').style.width = '0%';
    $('detailStatus').textContent = `در حال استخراج ${toFa(keys.length)} محصول...`;

    log(`🔍 شروع استخراج تفصیلی ${keys.length} محصول`, 'detail');

    const params = new URLSearchParams({
        detail_stream: '1',
        keys: keys.join(','),
        detailSelectors: JSON.stringify(detailSel)
    });

    const fd = new FormData();
    fd.append('urlMap', JSON.stringify(urlMap));
    fd.append('gallery', JSON.stringify(galCfg));      // v8.64

    /* v8.77: نگهبان توقف. تا حالا اگر اتصال وسط کار می‌مُرد (هاست،
       پروکسی، یا صفحه‌ای که جواب نمی‌داد) نوار پیشرفت همان‌جا می‌ماند و
       معلوم نبود کار تمام شده یا گیر کرده. حالا اگر ۹۰ ثانیه هیچ بایتی
       نیاید، خودش اعلام می‌کند و می‌گوید از کجا ادامه بدهید. */
    detailLastBeat = Date.now();
    clearInterval(detailWatch);
    detailWatch = setInterval(() => {
        if (!detailRunning) { clearInterval(detailWatch); return; }
        const idle = Math.round((Date.now() - detailLastBeat) / 1000);
        if (idle >= 90) {
            clearInterval(detailWatch);
            log('⏱ ارتباط قطع شد — ' + idle + ' ثانیه هیچ پاسخی نیامد', 'err');
            $('detailStatus').textContent = '⚠ ارتباط قطع شد. دوباره «استخراج تفصیلی» را بزنید — '
                + 'محصولات استخراج‌شده حفظ شده‌اند و از همان‌جا ادامه می‌دهد.';
            showToast('ارتباط قطع شد — دوباره بزنید تا ادامه دهد', true);
            finishDetailExtraction();
        } else if (idle >= 25) {
            $('detailStatus').textContent = '⏳ ' + toFa(idle) + ' ثانیه منتظر پاسخ سرور... '
                + '(صفحهٔ محصول کند است یا جواب نمی‌دهد)';
        }
    }, 5000);

    fetch('?detail_stream=1&' + params.toString(), {method:'POST', body:fd})
        .then(response => {
            const reader = response.body.getReader();
            const decoder = new TextDecoder();
            let buffer = '';

            function read() {
                reader.read().then(({done, value}) => {
                    detailLastBeat = Date.now();   // v8.77
                    if (done) {
                        finishDetailExtraction();
                        return;
                    }
                    buffer += decoder.decode(value, {stream:true});
                    const events = buffer.split('\n\n');
                    buffer = events.pop();
                    events.forEach(ev => parseSSEEvent(ev));
                    read();
                }).catch(err => {
                    log('❌ خطا در استخراج: ' + err.message, 'err');
                    finishDetailExtraction();
                });
            }
            read();
        })
        .catch(err => {
            log('❌ خطا: ' + err.message, 'err');
            finishDetailExtraction();
        });
}

function parseSSEEvent(ev) {
    if (!ev.trim()) return;
    let type = '', data = '';
    ev.split('\n').forEach(line => {
        if (line.startsWith('event:')) type = line.substring(6).trim();
        else if (line.startsWith('data:')) data = line.substring(5).trim();
    });
    if (!type || !data) return;

    try {
        const d = JSON.parse(data);
        if (type === 'detail_progress') {
            $('detailStatus').textContent = `استخراج ${toFa(d.current)} از ${toFa(d.total)}...`;
            $('detailProgressBar').style.width = (d.current/d.total*100) + '%';
        } else if (type === 'detail_extracted') {
            const p = products.get(d.key);
            if (p) {
                let added = 0;
                DETAIL_FIELDS.forEach(f => {
                    if (d[f.key] !== undefined && d[f.key] !== null) {
                        /* v10.15: قیمتِ خالی نباید قیمتِ موجود را پاک کند.
                           بقیهٔ فیلدها تا حالا فقط وقتی می‌آمدند که چیزی
                           پیدا شده بود، ولی p.price از فازِ فهرست پر است و
                           بازنویسی‌اش با '' یعنی از دست رفتنِ داده. */
                        if (f.key === 'price' && !d[f.key] && p[f.key]) return;
                        p[f.key] = d[f.key];
                        added++;
                    }
                });
                if (d.package_weight) p.package_weight = d.package_weight;
                // v8.64: گالری
                if (Array.isArray(d.images) && d.images.length) {
                    p.images = d.images;
                    p.images_count = d.images.length;
                    if (d.image) p.image = d.image;
                    added++;
                }
                products.set(d.key, p);
                if (added > 0) {
                    renderCard(p, d.key);
                    renderRow(p, order.indexOf(d.key) + 1, d.key);
                }
            }
        } else if (type === 'detail_complete') {
            log(`✅ استخراج تفصیلی تکمیل: ${d.total} محصول`, 'ok');
            showToast(`✓ استخراج تفصیلی ${d.total} محصول تکمیل شد`);
            $('detailStatus').textContent = `✓ استخراج ${toFa(d.total)} محصول تکمیل شد`;
            rvRebuildVisible();
        } else if (type === 'error') {
            log('❌ ' + d.message, 'err');
        } else if (type === 'done') {
            finishDetailExtraction();
        }
    } catch(e) {}
}

function stopDetailExtraction(){
    if (detailEs) { detailEs.close(); detailEs = null; }
    detailRunning = false;
    log('⏹ استخراج تفصیلی متوقف شد', 'err');
    finishDetailExtraction();
}

function finishDetailExtraction(){
    detailRunning = false;
    clearInterval(detailWatch); detailWatch = null;   // v8.77
    $('btnExtractDetail').classList.remove('hidden');
    $('btnStopDetail').classList.add('hidden');
    // v7.81: Show comparison report after extraction
    showComparisonReport();
}

// v7.81: Clear results only (keep selectors, URL, profile settings)
function clearResults(){
  if(!confirm('پاک کردن همه نتایج؟ (تنظیمات و سلکتورها حفظ می‌شوند)')) return;
  resetResultFilter();
  window._userClearedProducts = true;
  products.clear();order=[];pages=0;details=0;extractSpeedStartMs=0;updateSpeedCard(0,0);
  $('vGrid').innerHTML='<div class="empty-state" id="emptyState"><div class="icon">📭</div><p>هنوز محصولی اسکرپ نشده است.</p></div>';
  $('tBody').innerHTML='';$('txtContent').textContent='';
  $('emptyState')||0;
  $('numP').textContent='۰';$('numPg').textContent='۰';$('numD').textContent='۰';
  $('resultsBadge').classList.add('hidden');$('resultsBadge').textContent='0';
  $('detailProgress').classList.add('hidden');$('detailStatus').textContent='';
  $('detailProgressBar').style.width='0%';
  $('logs').innerHTML='<div class="log log-info">نتایج پاک شدند</div>';
  refreshViews();
  scheduleSave();
  showToast('✅ نتایج پاک شدند');
}

function reset(){
  stop();$('url').value='<?=h(DEFAULT_URL)?>';resetResultFilter();products.clear();order=[];pages=0;details=0;
  $('vGrid').innerHTML='<div class="empty-state" id="emptyState"><div class="icon">📭</div><p>هنوز محصولی اسکرپ نشده است.</p></div>';
  $('tBody').innerHTML='';$('txtContent').textContent='';
  $('logs').innerHTML='<div class="log log-info">ریست شد</div>';
  /* v10.31 (۴۴): ریست هم به نمای سبکِ جدول برمی‌گردد، نه کارت */
  $('progress').classList.add('hidden');$('status').textContent='آماده';update();rvMarkDirty();switchView('table');
  clearSel();
  clearDetailSel();
  currentProfileKey = null;
  isDirty = false;
  const s = $('profileStatus');
  s.textContent = 'جدید';
  s.className = 'profile-indicator unsaved';
  switchMainTab('start');
  showToast('✓ ریست شد');
}

function getCSV(){
  let headers = ['"#"', '"Title"', '"Original Price"', '"Final Price"', '"URL"', '"Image"'];
  const enabledFields = getDetailColumns();   // v10.15: قیمت ستونِ جدا نمی‌گیرد
  enabledFields.forEach(f => headers.push(`"${f.label}"`));
  if (isCustomColEnabled()) headers.push(`"${getCustomColName()}"`);
  let c = headers.join(',') + '\n';

  order.forEach((k,i)=>{
      const p=products.get(k);
      const e=v=>'"'+(v||'').replace(/"/g,'""')+'"';
      let row = [i+1, e(getFinalTitle(p.title)), e(getOriginalPrice(p.price)), e(getFinalPrice(p.price)), e(p.link), e(p.image)];
      enabledFields.forEach(f => {
          let val = p[f.key] || '';
          if (f.key === 'shortDesc' || f.key === 'longDesc') val = stripHtml(val);
          row.push(e(val));
      });
      if (isCustomColEnabled()) row.push(e(getCustomColVal()));
      c += row.join(',') + '\n';
  });
  return c;
}

function copyCSV(){navigator.clipboard.writeText(getCSV()).then(()=>showToast('✓ کپی شد'));}
function copyTxt(){navigator.clipboard.writeText(genTxt()).then(()=>showToast('✓ کپی شد'));}

function dl(action){
    const f=document.createElement('form');
    f.method='POST';
    const enabledFields = getDetailColumns();   // v10.15: قیمت ستونِ جدا نمی‌گیرد
    f.innerHTML=`<input type="hidden" name="action" value="${action}">
                 <input type="hidden" name="products">
                 <input type="hidden" name="useCustom" value="${isCustomColEnabled() ? 1 : 0}">
                 <input type="hidden" name="customName" value="${esc(getCustomColName())}">
                 <input type="hidden" name="detailFields">`;

    let exportData = [];
    order.forEach(k => {
        let p = products.get(k);
        let row = {
            title: getFinalTitle(p.title),
            origPrice: getOriginalPrice(p.price),
            price: getFinalPrice(p.price),
            link: p.link,
            image: p.image
        };
        enabledFields.forEach(ff => {
            row[ff.key] = p[ff.key] || '';
        });
        if (isCustomColEnabled()) row.custom = getCustomColVal();
        exportData.push(row);
    });

    f.querySelector('[name="products"]').value=JSON.stringify(exportData);
    f.querySelector('[name="detailFields"]').value=JSON.stringify(enabledFields);
    document.body.appendChild(f);
    f.submit();
    f.remove();
}
function dlCSV(){dl('csv');}
function dlExcel(){dl('excel');}

renderDetailFieldsList();

/* ==================================================================
 *  بررسی نسخه و نصب از طریق deploy.php یا code_update احراز‌شده.
 *  بررسی نسخه فقط خواندنی است؛ نصب فقط با تأیید مدیر و مسیر امن انجام می‌شود.
 * ================================================================== */
let VC = null, vcSaveTimer = null, VC_BRANCHES = [], VC_FILES = [], VC_PENDING = false, VC_PENDING_BRANCH = '';
/* v10.268: اگر deploy.php یا code_update فایل را بیرون از همین tab عوض کرد،
   tab قدیمی نسخهٔ تازه را می‌بیند و بدون وابستگی به پاسخ updater رفرش می‌شود. */
const S4_LOADED_VERSION='<?=APP_VERSION?>';
const S4_LOADED_SHA='<?=s4DiskCodeMeta()['sha']?>';
window._s4CodeReloading=false;
window._vcInstalling=false;
function s4ReloadForNewCode(nextVersion, manualInstall){
  if(window._s4CodeReloading)return;
  if(!manualInstall){
    try{
      const key='s4_code_reload_guard';
      const prev=JSON.parse(sessionStorage.getItem(key)||'null')||{};
      const sig=String(S4_LOADED_VERSION)+':'+String(S4_LOADED_SHA||'');
      const now=Date.now();
      const sameTrap=(prev.from===sig&&String(prev.target||'')===String(nextVersion||'')&&(now-(prev.ts||0))<60000);
      const cnt=sameTrap?((prev.count||0)+1):1;
      sessionStorage.setItem(key,JSON.stringify({from:sig,target:String(nextVersion||''),ts:now,count:cnt}));
      if(cnt>=2)return;
    }catch(e){}
  }else{
    try{sessionStorage.removeItem('s4_code_reload_guard');}catch(e){}
  }
  window._s4CodeReloading=true;
  try{showToast('✅ کد '+String(nextVersion||'جدید')+' نصب شد — صفحه رفرش می‌شود');}catch(e){}
  setTimeout(()=>{const u=new URL(location.href);u.searchParams.set('_v',Date.now());location.replace(u.toString());},900);
}
function s4WatchInstalledCode(){
  if(window._s4CodeReloading||window._vcInstalling||document.visibilityState==='hidden')return;
  fetch('?code_auto_update=1&_watch='+Date.now(),{cache:'no-store',credentials:'same-origin'})
    .then(r=>r.ok?r.json():null).then(d=>{
      if(!d||!d.ok)return;
      if(d.disk_sha&&S4_LOADED_SHA){
        if(String(d.disk_sha)!==String(S4_LOADED_SHA))s4ReloadForNewCode(d.disk_version||d.to_version||d.version||'جدید',false);
        return;
      }
      const v=d.disk_version||(d.updated?d.to_version:'')||d.version||(d.state&&!d.state.manual_pending?d.state.to_version:'');
      if(v&&String(v)!==String(S4_LOADED_VERSION))s4ReloadForNewCode(v,false);
    }).catch(()=>{});
}
setTimeout(s4WatchInstalledCode,1500);
setInterval(s4WatchInstalledCode,30000);
window.addEventListener('focus',s4WatchInstalledCode);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')s4WatchInstalledCode();});

