/**
 * v8.29: تست استعلام باسلام — واقعاً درخواست می‌فرستد، نه شبیه‌سازی.
 * حالت تست وضعیت را ذخیره نمی‌کند تا اعلان واقعی بعدی از دست نرود.
 */
/* v10.46 (۶۰): یک خط از وضعیت اعلان‌ها — آخرین بررسی کِی بود، چه دیده،
   و اگر مشکلی هست همان‌جا می‌درخشد تا «چیزی نمی‌آید» دیگر قابل‌گمان نباشد. */
function renderNotifHealth(){
  const line=$('notifHealthLine'); if(!line)return;
  fetch('?notif_health=1').then(r=>r.json()).then(d=>{
    if(!line)return;
    if(!d||!d.ok){line.style.color='#f87171';line.textContent='⚠️ خواندن وضعیت اعلان‌ها ناموفق بود';return;}
    const bits=[];
    if(d.last_notif_run){
      bits.push('آخرین بررسی: '+(d.last_notif_run_fa||'—'));
      if(d.last_notif_seen){
        bits.push('دیده‌شده: '+toFa(d.last_notif_seen.chats||0)+' گفتگو'+(d.last_notif_pending>0?' ('+toFa(d.last_notif_pending)+' بی‌جواب)':'')+' · '+toFa(d.last_notif_seen.orders||0)+' سفارش · '+toFa(d.last_notif_seen.products||0)+' محصول');
      }
      const fN=(d.last_notif_found?(d.last_notif_found.chats||0)+(d.last_notif_found.orders||0)+(d.last_notif_found.products||0):0);
      if(fN>0)bits.push('اعلان: '+toFa(fN)+' مورد');
    }else{
      bits.push('هنوز دورِ بررسی‌ای ثبت نشده — منتظرِ اجرای بعدیِ کران‌جاب');
    }
    if(d.healthy){
      line.style.color='#4ade80';
      line.innerHTML='🩺 <b>همه چیز درست است</b> — '+esc(bits.join(' · '));
    }else{
      line.style.color='#fbbf24';
      line.innerHTML='⚠️ <b>'+esc((d.problems||[]).slice(0,2).join('؛ '))+'</b>'
        +(bits.length?' — '+esc(bits.join(' · ')):'' )
        +'<span style="color:#64748b"> · جزئیات: <code>?notif_health=1</code></span>';
    }
  }).catch(()=>{if(line)line.textContent='';});
}

function notifTest(kind){
  const labels={orders:'🛒 سفارش‌ها',chats:'💬 پیام‌ها',products:'📋 محصولات',source:'💰 تغییرات مبدأ',ping:'📡 پینگ کران'};
  const box=$('notifTestR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ در حال استعلام '+esc(labels[kind]||kind)+' از باسلام...</div>';
  fetch('?notif_test=1&kind='+encodeURIComponent(kind)).then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){
      box.innerHTML='<div style="color:#f87171;font-size:11px;background:#7f1d1d20;padding:6px 8px;border-radius:6px">✗ '+esc(d.error||'خطا')+'</div>';
      showToast(d.error||'تست ناموفق',1);
      return;
    }
    const sent=d.sent||{};
    const nmMap={baleh:'بله',rubika:'روبیکا',telegram:'تلگرام',none:'پیام‌رسان'};
    const chips=Object.keys(sent).filter(k=>nmMap[k]).map(k=>{
      const okv=sent[k]==='sent';
      const nm=nmMap[k];
      return '<span style="font-size:10px;padding:1px 7px;border-radius:4px;margin-left:4px;background:'
        +(okv?'#14532d':'#7f1d1d')+';color:'+(okv?'#86efac':'#fca5a5')+'">'
        +(okv?'✓ ':'✗ ')+esc(nm)+'</span>';
    }).join('');
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px">';
    h+='<div style="color:#4ade80;margin-bottom:4px">✓ ارتباط با باسلام برقرار است</div>';
    h+='<div style="color:#94a3b8">بررسی‌شده: '+toFa(d.total_seen||0)+' مورد · یافت‌شده: '+toFa(d.found||0)+'</div>';
    /* v10.45: گزارشِ غرفه‌به‌غرفه — کدام وصل است، کدام نه، و چرا */
    if(Array.isArray(d.shops)&&d.shops.length){
      h+='<div style="margin-top:4px">';
      d.shops.forEach(s=>{
        h+='<div style="font-size:10px;color:'+(s.ok?'#94a3b8':'#fca5a5')+';margin-top:2px">'
          +(s.ok?'✓ ':'✗ ')+esc(s.shop_name||('غرفه '+s.vendor_id))
          +(s.ok?(' — '+toFa(s.seen||0)+' مورد اخیر · '+toFa(s.found||0)+' قابل اعلان'):(esc(s.error||'')))
          +(s.new_shop?' (اولین بررسی — بدون اعلان)':'')
          +'</div>';
      });
      h+='</div>';
    }
    let errLines='';
    Object.keys(sent).forEach(k=>{if(/_err$/.test(k)&&sent[k])errLines+='<div style="font-size:9.5px;color:#fca5a5;margin-top:2px">'+esc(nmMap[k.replace(/_err$/,'')]||k)+': '+esc(sent[k])+'</div>';});
    if(chips||errLines)h+='<div style="margin-top:4px">'+(chips?'ارسال: '+chips:'')+errLines+'</div>';
    if(d.sample)h+='<div style="margin-top:6px;color:#cbd5e1;background:#1e293b;padding:6px;border-radius:6px;white-space:pre-wrap;font-size:10.5px">'+esc(d.sample)+'</div>';
    h+='</div>';
    box.innerHTML=h;
    showToast('✓ تست '+(labels[kind]||kind)+' انجام شد');
    renderNotifHealth(); /* v10.46 (۶۰): خطِ وضعیت را تازه کن */
  }).catch(()=>{
    if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا در ارتباط</div>';
    showToast('خطا شبکه',1);
  });
}

/** v8.37: پینگ آزمایشی — همان پیامی که کران‌جاب می‌فرستد */
function testPing(){notifTest('ping');}
/** v10.79 (93): لاگِ پینگ‌هایِ اخیر — کجای زنجیره گیر است را نشان می‌دهد */
function showPingLog(){
  const box=$('pingLogR');if(!box)return;
  box.innerHTML='<div>⏳ بارگذاری...</div>';
  fetch('?ping_log=1').then(r=>r.json()).then(d=>{
    const L=(d&&d.log)||[];
    if(!L.length){box.innerHTML='<div>هنوز تلاشی ثبت نشده است.</div>';return;}
    const nm={baleh:'بله',rubika:'روبیکا',telegram:'تلگرام',none:'پیام‌رسان'};
    let h='';
    L.slice(0,6).forEach(e=>{
      const dv=e.delivery||{};
      let chips='';
      chips=Object.keys(dv).filter(k=>nm[k]).map(k=>'<span style="color:'+(dv[k]==='sent'?'#4ade80':'#f87171')+'">'+nm[k]+(dv[k]==='sent'?' ✓':' ✗')+'</span>').join(' · ');
      let errs='';
      Object.keys(dv).forEach(k=>{if(/_err$/.test(k)&&dv[k])errs+='<div style="color:#fca5a5;padding-left:12px">'+esc(k.replace(/_err$/,''))+': '+esc(dv[k])+'</div>';});
      h+='<div style="margin-top:3px">'+(e.ok?'✓':'✗')+' '+esc(e.time||'')+' — '+esc(e.src||'')
        +(e.skipped?' (رد شد: '+esc(e.skipped)+')':'')
        +(chips?' — '+chips:'')
        +((e.error&&!e.skipped)?' — '+esc(e.error):'')+'</div>'+errs;
    });
    box.innerHTML=h;
  }).catch(()=>{box.innerHTML='<div>✗ خطای شبکه</div>';});
}
/* v10.81 (95): لاگِ ارسال‌هایِ پیام‌رسان — حقیقتِ مسیر و پاسخ */
function showMsgrLog(){
  const box=$('msgrLogR');if(!box)return;
  box.innerHTML='<div>⏳ بارگذاری...</div>';
  fetch('?msgr_log=1').then(r=>r.json()).then(d=>{
    const R=(d&&d.rows)||[];
    if(!R.length){box.innerHTML='<div>هنوز ارسالِ ثبت‌شده‌ای نیست.</div>';return;}
    let h='';
    R.slice(-6).reverse().forEach(x=>{
      const t=new Date(x.at*1000).toLocaleString('fa-IR',{hour:'2-digit',minute:'2-digit',day:'numeric',month:'numeric'});
      h+='<div style="margin-top:3px">'+(x.ok?'<span style="color:#4ade80">✓</span>':'<span style="color:#f87171">✗</span>')
        +' <b>'+esc(x.host||'؟')+'</b> <span style="color:#64748b">'+t+' — '+esc(x.via||'')+' (HTTP '+(x.code||0)+')</span>'
        +'<div style="color:#94a3b8;padding-left:12px;direction:ltr;text-align:right">'+esc((x.attempts||'').slice(0,300))+'</div></div>';
    });
    box.innerHTML=h;
  }).catch(()=>{box.innerHTML='<div>✗ خطای شبکه</div>';});
}

/* =====================================================================
 *  v8.47: مغایرت‌گیری — رابط کاربری
 * ===================================================================== */
var reconLast=null;

function reconLabel(t){return t==='woo'?'ووکامرس':'باسلام';}

/** گام ۱: فقط گزارش، بدون هیچ تغییری */
function reconScan(target){reconStart(target,false,'off',1);}
function reconScanAll(){
  // پشت‌سرهم ووکامرس بعد باسلام
  const box=$('reconR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ بررسی کامل: اول ووکامرس...</div>';
  reconStart('woo',false,'off',1);
  // باسلام را بعد از اتمام ووکامرس — کاربر می‌تواند جدا هم بزند
  setTimeout(function(){ if(!window.reconTimer) reconStart('bsl',false,'off',1); }, 2500);
}

function reconAutoBuildOnlyUi(buildOnly){
  const bo=!!buildOnly;
  if($('reconAutoBuildOnly'))$('reconAutoBuildOnly').checked=bo;
  if($('smPeriodicBuildOnly'))$('smPeriodicBuildOnly').checked=bo;
  if(bo){
    if($('reconAutoMatrix'))$('reconAutoMatrix').checked=true;
    if($('reconAutoMatrixFix')){$('reconAutoMatrixFix').checked=false;$('reconAutoMatrixFix').disabled=true;}
    if($('reconAutoApply')){$('reconAutoApply').checked=false;$('reconAutoApply').disabled=true;}
    if($('reconAutoEnqueue')){$('reconAutoEnqueue').checked=false;$('reconAutoEnqueue').disabled=true;}
  }else{
    if($('reconAutoMatrixFix'))$('reconAutoMatrixFix').disabled=false;
    if($('reconAutoApply'))$('reconAutoApply').disabled=false;
    if($('reconAutoEnqueue'))$('reconAutoEnqueue').disabled=false;
  }
}
function reconAutoBuildOnlyToggle(checked,fromToolbar){
  const bo=!!checked;
  if(bo&&fromToolbar&&$('reconAutoEn')&&!$('reconAutoEn').checked){
    $('reconAutoEn').checked=true;
  }
  reconAutoBuildOnlyUi(bo);
  reconAutoSave(bo?'✓ مغایرت‌گیری دوره‌ای روی حالت «فقط ساخت جدول» ذخیره شد':'✓ حالت ساخت جدول + اصلاح دوره‌ای ذخیره شد');
}
function reconAutoCollect(){
  const buildOnly=!!(($('reconAutoBuildOnly')&&$('reconAutoBuildOnly').checked)||($('smPeriodicBuildOnly')&&$('smPeriodicBuildOnly').checked));
  return {
    enabled: !!($('reconAutoEn')||{}).checked,
    build_only: buildOnly,
    woo: !!($('reconAutoWoo')||{}).checked,
    bsl: !!($('reconAutoBsl')||{}).checked,
    all_vendors: true,
    all_profiles: !!($('reconAllProfiles')||{}).checked,
    fix_price: !!($('reconAutoFixPrice')||{}).checked,
    apply: buildOnly ? false : !!($('reconAutoApply')||{}).checked,
    extra_mode: (($('reconAutoMode')||{}).value||'off'),
    interval_h: parseInt(($('reconAutoIv')||{}).value||'6')||6,
    notify: !!($('reconAutoNotify')||{}).checked,
    enqueue_missing: buildOnly ? false : !!($('reconAutoEnqueue')||{}).checked,
    build_matrix: buildOnly ? true : ($('reconAutoMatrix') ? !!$('reconAutoMatrix').checked : true),
    matrix_fix: buildOnly ? false : ($('reconAutoMatrixFix') ? !!$('reconAutoMatrixFix').checked : true),
    execution_mode: (($('reconExecMode')||{}).value||'cron_first'),
    execution_pause_ms: Math.max(0,Math.min(2000,parseInt(($('reconExecPause')||{}).value||'250')||0)),
    cron_lease_sec: Math.max(30,Math.min(900,parseInt(($('reconCronLease')||{}).value||'180')||180))
  };
}
function reconAutoSave(customToast){
  const cfg=reconAutoCollect();
  const fd=new FormData();
  fd.append('action','save_connections');
  fd.append('recon_auto', JSON.stringify(cfg));
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    const st=$('reconAutoStatus');
    const modeDesc=cfg.build_only?'فقط ساخت جدول (بدون اصلاح مغایرت‌ها)':(cfg.matrix_fix?'ساخت جدول + اصلاح مغایرت‌ها':'مسیر جدول');
    if(st) st.textContent = (d&&d.ok) ? ('✓ ذخیره شد · '+(cfg.enabled?('فعال هر '+(cfg.interval_h||6)+' ساعت · '+modeDesc):'غیرفعال')) : ('✗ '+(d&&d.error||'خطا'));
    reconAutoBadge();
    if(d&&d.ok) showToast(customToast||'تنظیمات مغایرت‌گیری دوره‌ای ذخیره و اعمال شد');
  }).catch(()=>{const st=$('reconAutoStatus'); if(st) st.textContent='✗ شبکه';});
}
function reconAutoApplyCfg(c){
  c=c||{};
  const chk=(id,v)=>{const e=$(id); if(e) e.checked=!!v;};
  const set=(id,v)=>{const e=$(id); if(e) e.value=v;};
  const buildOnly=!!c.build_only;
  chk('reconAutoEn', c.enabled);
  chk('reconAutoWoo', c.woo!==false);
  chk('reconAutoBsl', c.bsl!==false);
  chk('reconAutoFixPrice', c.fix_price!==false);
  chk('reconAutoApply', buildOnly?false:c.apply);
  chk('reconAutoNotify', c.notify!==false);
  chk('reconAutoEnqueue', buildOnly?false:c.enqueue_missing);
  chk('reconAutoMatrix', buildOnly?true:(c.build_matrix!==false));
  chk('reconAutoMatrixFix', buildOnly?false:(c.matrix_fix!==false));
  reconAutoBuildOnlyUi(buildOnly);
  set('reconAutoIv', c.interval_h||6);
  set('reconAutoMode', c.extra_mode||'off');
  set('reconExecMode',c.execution_mode||'cron_first');set('reconExecPause',c.execution_pause_ms===undefined?250:c.execution_pause_ms);set('reconCronLease',c.cron_lease_sec||180);
  reconExecUi();reconAutoBadge();
  const st=$('reconAutoStatus');
  if(st && c.enabled) st.textContent='فعال · هر '+(c.interval_h||6)+' ساعت · '+(buildOnly?'فقط ساخت جدول (بدون اصلاح مغایرت‌ها)':(c.matrix_fix!==false?'ساخت جدول + اصلاح مغایرت‌ها':'مسیر جدول'));
}
function reconExecUi(){
  const m=(($('reconExecMode')||{}).value)||'cron_first',p=$('reconExecPause');
  if(p)p.disabled=(m==='cron_only');
  const h=$('reconExecHint');if(h){const labels={cron_only:'با ضربان کران، عملیات پیوسته و بدون برش زمانی/وقفهٔ handoff جلو می‌رود؛ اگر گیر کند نگهبان کران child را از checkpoint بازیابی می‌کند.',delay_only:'worker مستقل از کران و با برش checkpointدار و وقفهٔ تنظیمی ادامه می‌دهد.',cron_first:'کران مسیر پیوسته و بدون برش است؛ با قطع ضربان، worker از checkpoint با روش fallback ادامه می‌دهد.',delay_first:'worker مسیر اصلی است و کران بیرونی worker مرده یا کار paused را نجات می‌دهد.'};h.innerHTML=esc(labels[m]||labels.cron_first)+' تغییر روش با ذخیره، همان لحظه روی عملیات فعال اعمال می‌شود. کران بیرونی: <code>?cron_run=1</code>. تأخیر ایمنی API باسلام و Retry-After حذف نمی‌شود.';}
}
function reconExecStatus(){
  const o=$('reconExecStatus');if(o)o.textContent='در حال بررسی…';
  fetch('?matrix_execution_status=1&_='+Date.now(),{cache:'no-store'}).then(r=>r.json()).then(d=>{if(!o)return;const p=d.pulse||{},age=p.at?Math.max(0,Math.floor(Date.now()/1000-p.at)):null;o.textContent=(d.execution&&d.execution.cron_fresh?'🟢':'🟠')+' '+(age===null?'هنوز ضربانی نیست':('آخرین ضربان '+toFa(age)+' ثانیه پیش'))+' · '+((d.execution||{}).mode||'');}).catch(()=>{if(o)o.textContent='خطای خواندن وضعیت';});
}
function reconAutoLoadLog(){
  const box=$('reconAutoLog'),meta=$('reconAutoLogMeta');if(box)box.innerHTML='<div class="ral-empty">⏳ در حال خواندن گزارش‌های تفصیلی…</div>';
  const dt=v=>v?new Date(v*1000).toLocaleString('fa-IR'):'—';
  const dur=(a,b)=>{if(!a)return'—';const n=Math.max(0,(b||Math.floor(Date.now()/1000))-a);return n<60?toFa(n)+' ثانیه':(n<3600?toFa(Math.floor(n/60))+' دقیقه':toFa(Math.floor(n/3600))+' ساعت و '+toFa(Math.floor((n%3600)/60))+' دقیقه');};
  const modeLabel=m=>({cron_only:'فقط کران',delay_only:'فقط worker',cron_first:'کران ← worker',delay_first:'worker ← کران'}[m]||m||'—');
  const statusInfo=(stage,event)=>{const r=(stage||{}).runtime||{},s=r.status||((stage||{}).skipped?'skipped':((stage||{}).status||''));
    if(event==='queue_failed'||s==='failed'||s==='cancelled'||r.error)return{key:'bad',txt:s==='cancelled'?'لغوشده':'ناموفق'};
    if(s==='done')return{key:'ok',txt:'تکمیل‌شده'};if(s==='running')return{key:'wait',txt:'در حال اجرا'};if(s==='pending')return{key:'wait',txt:'در صف'};if(s==='paused')return{key:'wait',txt:'منتظر ادامه'};if(s==='skipped')return{key:'',txt:'انجام نمی‌شود'};return{key:'wait',txt:'صف‌شده'};};
  const stageCard=(name,icon,stage,event)=>{stage=stage||{};const r=stage.runtime||{},si=statusInfo(stage,event),res=r.result||{},dest=(r.selected_destinations||[]).map(x=>x==='woo'?'ووکامرس':(String(x).startsWith('bsl:')?'غرفه '+String(x).slice(4):x));
    const err=r.error||stage.error||(!res.ok&&res.tail?res.tail:'');
    return '<div class="ral-stage"><div class="ral-stage-h"><span>'+icon+' '+name+'</span><span class="ral-badge '+si.key+'">'+esc(si.txt)+'</span></div>'+
      '<div class="ral-stage-grid"><div class="ral-kv"><small>شناسه job</small><b title="'+esc(stage.job_id||'')+'">'+esc(stage.job_id||'—')+'</b></div><div class="ral-kv"><small>تلاش‌ها</small><b>'+toFa(r.attempts||0)+'</b></div><div class="ral-kv"><small>شروع</small><b>'+esc(dt(r.started_at))+'</b></div><div class="ral-kv"><small>مدت</small><b>'+esc(dur(r.started_at,r.done_at))+'</b></div><div class="ral-kv"><small>segmentها</small><b>'+toFa(res.worker_segments||0)+'</b></div><div class="ral-kv"><small>مقصدها</small><b title="'+esc(dest.join('، '))+'">'+esc(dest.length?dest.join('، '):'—')+'</b></div></div>'+
      (err?'<div class="ral-err">⚠ '+esc(String(err).slice(0,700))+'</div>':'')+'</div>';};
  fetch('?recon_auto_log=1&_=' + Date.now(),{cache:'no-store'}).then(r=>r.json()).then(d=>{
    if(!box)return;const rows=(d.entries||[]).slice().reverse(),st=d.state||{},cfg=d.config||{};
    if(meta)meta.textContent=toFa(rows.length)+' اجرای ثبت‌شده · نسخه '+(d.version||'');
    let html='<div class="ral-overview"><div class="ral-stat"><b>'+(cfg.enabled?'🟢 فعال':'⚪ خاموش')+'</b><small>وضعیت اجرای دوره‌ای</small></div><div class="ral-stat"><b>هر '+toFa(cfg.interval_h||0)+' ساعت</b><small>فاصلهٔ اجرا</small></div><div class="ral-stat"><b>'+esc(modeLabel(cfg.execution_mode))+'</b><small>موتور اجرا</small></div><div class="ral-stat"><b>'+esc(dt(st.last_finish||st.last_start))+'</b><small>آخرین فعالیت</small></div></div>';
    if(!rows.length){box.innerHTML=html+'<div class="ral-empty">هنوز اجرای دوره‌ای ثبت نشده است.</div>';return;}
    rows.forEach((x,i)=>{const z=x.data||{},bs=statusInfo(z.build,x.event),fs=statusInfo(z.fix,x.event),bad=bs.key==='bad'||fs.key==='bad'||x.event==='queue_failed',done=bs.key==='ok'&&(fs.key==='ok'||(z.fix||{}).skipped),cls=bad?'bad':(done?'ok':'wait'),overall=bad?'دارای خطا':(done?'کامل':'در حال پیگیری'),ex=z.execution||{};
      html+='<article class="ral-card '+cls+'"><div class="ral-head"><div><div class="ral-title">اجرای دوره‌ای #'+toFa(rows.length-i)+'</div><div class="ral-sub">'+esc(dt(x.t))+' · نسخه '+esc(x.version||'—')+'</div></div><span class="ral-badge '+cls+'">'+overall+'</span></div>'+
        '<div class="ral-tags"><span class="ral-tag">'+(z.worker_ready===false?'🔴 worker خاموش':'🟢 worker آماده')+'</span><span class="ral-tag">دامنه: '+esc(z.scope||'all')+'</span><span class="ral-tag">روش: '+esc(modeLabel(ex.mode))+'</span><span class="ral-tag">'+(ex.cron_fresh?'⚡ کران تازه':'◷ کران غیرفعال')+'</span><span class="ral-tag">lease: '+toFa(ex.lease_sec||0)+' ثانیه</span></div>'+
        '<div class="ral-stages">'+stageCard('ساخت جدول','📊',z.build,x.event)+stageCard('اصلاح جدول','🔧',z.fix,x.event)+'</div>'+
        '<details class="ral-tech"><summary>دادهٔ فنی و پاسخ کامل این اجرا</summary><pre>'+esc(JSON.stringify(x,null,2))+'</pre></details></article>';
    });box.innerHTML=html;
  }).catch(e=>{if(box)box.innerHTML='<div class="ral-empty" style="color:#fca5a5">✗ خطا در خواندن گزارش: '+esc(e.message)+'</div>';});
}
function reconAutoBadge(){
  const b=$('reconAutoBadge'); if(!b) return;
  const on=!!($('reconAutoEn')||{}).checked;
  const bo=!!(($('reconAutoBuildOnly')&&$('reconAutoBuildOnly').checked)||($('smPeriodicBuildOnly')&&$('smPeriodicBuildOnly').checked));
  b.textContent=on?(bo?'دوره‌ای: فقط ساخت جدول':'دوره‌ای روشن'):'دوره‌ای';
  b.className='cst '+(on?'on':'off');
}

function catfixAutoCollect(){
  return {
    enabled: !!($('catfixAutoEn')||{}).checked,
    mode: (($('catfixAutoMode')||{}).value||'learned'),
    all_vendors: !!($('catfixAutoAllVendors')||{}).checked,
    use_learn: !!($('catfixAutoLearn')||{}).checked,
    interval_h: parseInt(($('catfixAutoIv')||{}).value||'12')||12,
    quorum: 2,
    notify: !!($('catfixAutoNotify')||{}).checked
  };
}
function catfixAutoSave(){
  const fd=new FormData();
  fd.append('action','save_connections');
  fd.append('catfix_auto', JSON.stringify(catfixAutoCollect()));
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    const st=$('catfixAutoStatus');
    if(st) st.textContent=(d&&d.ok)?'✓ ذخیره شد — از کران بعدی':'✗ خطا';
    if(d&&d.ok) showToast('اصلاح دوره‌ای دسته ذخیره شد');
  }).catch(()=>{});
}
function catfixAutoApplyCfg(c){
  c=c||{};
  const chk=(id,v)=>{const e=$(id); if(e) e.checked=!!v;};
  const set=(id,v)=>{const e=$(id); if(e) e.value=v;};
  chk('catfixAutoEn', c.enabled);
  chk('catfixAutoAllVendors', c.all_vendors!==false);
  chk('catfixAutoLearn', c.use_learn!==false);
  chk('catfixAutoNotify', c.notify);
  set('catfixAutoMode', c.mode||'learned');
  set('catfixAutoIv', c.interval_h||12);
  const st=$('catfixAutoStatus');
  if(st && c.enabled) st.textContent='فعال · هر '+(c.interval_h||12)+' ساعت · '+(c.mode||'learned');
}

/* v8.65: دفترچهٔ شناسهٔ مقصد */
function rmapShow(){
  const box=$('rmapR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ ...</div>';
  fetch('?remote_map=1').then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#fca5a5;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    const tot=(d.woo||0)+(d.bsl||0);
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px;line-height:1.9">';
    h+='<div style="color:#67e8f9;font-weight:700">📇 شناسه‌های ثبت‌شده</div>';
    h+='<div>🛒 ووکامرس: <b style="color:'+((d.woo||0)?'#4ade80':'#94a3b8')+'">'+toFa(d.woo||0)+'</b>'
      +' · 🏪 باسلام: <b style="color:'+((d.bsl||0)?'#4ade80':'#94a3b8')+'">'+toFa(d.bsl||0)+'</b></div>';
    if(!tot){
      h+='<div style="color:#fbbf24;font-size:10.5px;margin-top:4px">'
        +'هنوز چیزی ثبت نشده. با هر ارسال خودکار پر می‌شود، یا همین حالا «بازسازی» را بزنید.</div>';
    }
    ['woo','bsl'].forEach(t=>{
      const rows=(d.sample||{})[t]||[];
      rows.forEach(s=>{h+='<div style="color:#94a3b8;font-size:10px">'
        +(t==='woo'?'🛒':'🏪')+' #'+toFa(s.id)+' — '+esc(s.title||'')+'</div>';});
    });
    h+='</div>';
    box.innerHTML=h;
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

function rmapRebuild(target){
  const box=$('rmapR');
  const lbl=target==='woo'?'ووکامرس':'باسلام';
  if(!confirm('شناسهٔ محصولات '+lbl+' از روی عنوان‌های فعلی ثبت شود؟\n\n'
    +'این کار چیزی را تغییر نمی‌دهد؛ فقط یاد می‌گیرد کدام محصول مقصد مال کدام محصول پروفایل است.\n'
    +'بهتر است قبل از تغییر نام محصولات انجام شود.'))return;
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ خواندن محصولات '+esc(lbl)+'...</div>';
  safeFetchJson('?remote_map=1&rebuild='+encodeURIComponent(target)).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#fca5a5;font-size:11px;background:#7f1d1d20;padding:6px 8px;border-radius:6px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px;line-height:1.9">';
    h+='<div style="color:#4ade80;font-weight:700">✅ بازسازی '+esc(lbl)+'</div>';
    h+='<div>محصولات مقصد: <b>'+toFa(d.remote_seen||0)+'</b> · عنوان‌های پروفایل: <b>'+toFa(d.profile_titles||0)+'</b></div>';
    h+='<div>🔗 شناسهٔ ثبت‌شده: <b style="color:#4ade80">'+toFa(d.recorded||0)+'</b></div>';
    if(!(d.recorded||0))h+='<div style="color:#fbbf24;font-size:10.5px">هیچ عنوانی تطبیق نخورد — یعنی عنوان‌های مقصد با پروفایل فرق دارند.</div>';
    h+='</div>';
    box.innerHTML=h;
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

/** v8.49: شروع در پس‌زمینه و سپس دنبال کردن گزارش زنده */
function reconStart(target,apply,mode,fixPrice){
  const box=$('reconR');
  let q='?recon=1&target='+encodeURIComponent(target);
  // v8.64: همهٔ پروفایل‌ها یا فقط همگام‌شونده‌ها
  if(($('reconAllProfiles')||{}).checked)q+='&all_profiles=1';
  // v10.107: همهٔ غرفه‌های باسلام
  if(target==='bsl'&&($('reconAllVendors')||{}).checked)q+='&all_vendors=1';
  if(apply)q+='&apply=1&mode='+encodeURIComponent(mode||'off')+'&fix_price='+(fixPrice?1:0);
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ در حال شروع...</div>';
  fetch(q).then(r=>r.json()).then(d=>{
    if(!d.ok){
      if(box)box.innerHTML='<div style="color:#fca5a5;font-size:11px;background:#7f1d1d20;'
        +'padding:6px 8px;border-radius:6px">✗ '+esc(d.error||'خطا')
        +(d.running?'<div style="color:#94a3b8;margin-top:4px">اگر گیر کرده، تا ۳ دقیقه دیگر خودش آزاد می‌شود.</div>':'')
        +'</div>';
      return;
    }
    reconWatch(target);
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

var reconTimer=null, reconSeen=0;

function reconWatch(target){
  if(reconTimer)clearInterval(reconTimer);
  reconSeen=0;
  const box=$('reconR');
  if(box)box.innerHTML=
    '<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px">'
    +'<div id="reconHead" style="color:#93c5fd;margin-bottom:5px">⏳ در حال اجرا...</div>'
    +'<div id="reconCounts" style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:5px"></div>'
    +'<div id="reconLog" style="max-height:190px;overflow:auto;font-family:ui-monospace,monospace;'
    +'font-size:10.5px;line-height:1.8;direction:rtl;background:#111c31;border-radius:6px;padding:6px"></div>'
    +'</div>';
      const tick=()=>{
    fetch('?recon_status=1&since='+reconSeen).then(r=>r.json()).then(st=>{
      const logEl=$('reconLog');
      if(logEl&&st.log&&st.log.length){
        st.log.forEach(l=>{
          const d=document.createElement('div');
          // v8.64: رنگ سطر بر اساس محتوا، تا گزارش زنده خوانا باشد
          const m=l.m||'';
          d.style.color = /^⛔|❌|🛑|⚠️/.test(m) ? '#fca5a5'
                        : /^✅|^💰|^🗑/.test(m)  ? '#86efac'
                        : /^\s+[•✓⏭🗑💰]/.test(m) ? '#94a3b8'
                        : /^📊|^⚖️/.test(m)      ? '#93c5fd'
                        : '#cbd5e1';
          if(/^\s/.test(m))d.style.paddingRight='10px';
          d.textContent=m;
          logEl.appendChild(d);
        });
        logEl.scrollTop=logEl.scrollHeight;
      }
      reconSeen=st.log_total||reconSeen;
      const c=$('reconCounts');
      if(c){
        const cell=(lbl,v,col)=>v===undefined?'':
          '<span style="color:#94a3b8">'+lbl+': <b style="color:'+col+'">'+toFa(v)+'</b></span>';
        c.innerHTML=cell('پروفایل',st.expected,'#e2e8f0')+cell('مقصد',st.remote,'#e2e8f0')
          +cell('یکسان',st.matched,'#86efac')+cell('در مبدأ نیست',st.extra,'#fca5a5')
          +cell('مغایرت',st.diff,'#fbbf24')+cell('در مقصد نیست',st.missing,'#67e8f9')
          +(st.repriced?cell('اصلاح‌شده',st.repriced,'#4ade80'):'')
          +(st.deleted?cell('حذف‌شده',st.deleted,'#4ade80'):'')
          +(st.cur&&st.cur_total?'<span style="color:#93c5fd">'+toFa(st.cur)+'/'+toFa(st.cur_total)+'</span>':'');
      }
      const h=$('reconHead');
      if(st.done){
        clearInterval(reconTimer);reconTimer=null;
        if(h)h.innerHTML=st.result_ok===false
          ?'<span style="color:#fca5a5">✗ '+esc(st.error||'ناموفق')+'</span>'
          :'<span style="color:#4ade80">✅ پایان</span>';
        fetch('?recon_result=1').then(r=>r.json()).then(res=>{
          reconLast=res;
          if(!res.ok){
            // v8.64: وقتی نتیجه‌ای نیست، بگو چرا و چه کاری می‌شود کرد
            const b=$('reconR');
            if(b&&res.hint_all_profiles){
              b.insertAdjacentHTML('beforeend',
                '<div style="background:#78350f30;border:1px solid #f59e0b;border-radius:8px;'
                +'padding:8px;margin-top:6px;font-size:11px;color:#fcd34d;line-height:1.8">'
                +'💡 پروفایل‌هایی هست ولی «همگام‌سازی دوره‌ای» ندارند. تیک '
                +'<b>«همهٔ پروفایل‌ها»</b> را بزنید و دوباره بررسی کنید.</div>');
            }
            return;
          }
          res.applied=!!st.apply;
          const b=$('reconR');
          if(b)b.innerHTML=reconReport(res,target)
            +'<div style="margin-top:6px"><button class="btn btn-gray" onclick="reconWatch(\''+target+'\')" '
            +'style="font-size:10px;padding:3px 8px">📜 نمایش گزارش</button></div>';
        }).catch(()=>{});
      }else if(h){
        const ph={start:'شروع',profiles:'خواندن پروفایل‌ها',fetch:'دریافت از مقصد',
                  compare:'مقایسه',apply:'اعمال تغییرات'}[st.phase]||'در حال اجرا';
        // v8.64: جزئیات زندهٔ همان لحظه، نه فقط نام مرحله
        let extra='';
        if(st.phase==='fetch'&&st.fetched)extra=' — '+toFa(st.fetched)+' محصول از صفحهٔ '+toFa(st.page||1);
        else if(st.cur&&st.cur_total)extra=' — '+toFa(st.cur)+' از '+toFa(st.cur_total);
        const secs=st.started_at?Math.max(0,Math.floor(Date.now()/1000)-st.started_at):0;
        h.innerHTML='⏳ '+esc(ph)+esc(extra)
          +(secs?'<span style="color:#64748b;font-size:10px"> · '+toFa(secs)+' ثانیه</span>':'');
      }
    }).catch(()=>{});
  };
  tick();
  reconTimer=setInterval(tick,1200);
}

function reconReport(d,target){
  // v8.50: هر شمارنده قابل کلیک است و فهرست محصولاتش را باز می‌کند
  reconLast=d; reconLastTarget=target;
  const nExtra=d.extra_total||0, nDiff=d.price_diff_total||0;
  const nMiss=d.missing_total||((d.missing||[]).length)||0;
  const nMatch=d.matched||0, nExp=d.expected||0, nRem=d.remote||0;
  const cell=(icon,label,val,color,kind,enabled)=>
    '<div class="rc-cell'+(enabled?' rc-on':'')+'"'
    +(enabled?' onclick="reconList(\''+kind+'\')" title="کلیک برای دیدن فهرست"':'')
    +'><b style="color:'+color+'">'+toFa(val)+'</b><span>'+icon+' '+label+'</span></div>';
  let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px">';
  h+='<div class="rc-grid">'
   +cell('📋','در پروفایل‌ها',nExp,'#e2e8f0','',false)
   +cell('🏪','در '+reconLabel(target),nRem,'#e2e8f0','',false)
   +cell('✓','یکسان',nMatch,'#86efac','matched',nMatch>0)
   +cell('🗑','اضافی',nExtra,nExtra?'#fca5a5':'#64748b','extra',nExtra>0)
   +cell('💰','مغایرت قیمت',nDiff,nDiff?'#fbbf24':'#64748b','diff',nDiff>0)
    +cell('📤','در مقصد نیست',nMiss,nMiss?'#67e8f9':'#64748b','missing',nMiss>0)
   +'</div>';
  if(d.applied){
    h+='<div style="color:#4ade80;margin:6px 0">✅ اعمال شد — '
      +toFa(d.repriced||0)+' قیمت اصلاح، '+toFa(d.deleted||0)+' مورد اضافی'
      +((d.failed||0)?' · <span style="color:#fca5a5">'+toFa(d.failed)+' ناموفق</span>':'')+'</div>';
  }
  if(d.skipped_delete){
    h+='<div style="color:#fca5a5;background:#7f1d1d20;padding:5px 7px;border-radius:6px;margin:4px 0">'
      +'🛑 حذف انجام نشد: '+esc(d.skipped_delete)+'</div>';
  }
  // v8.64: شرح تفکیکی پروفایل‌ها و هشدار «هیچ‌چیز تطبیق نخورد»
  const ps=d.profile_stats||{};
  if(ps.profiles&&ps.profiles.length){
    h+='<details style="margin-top:6px"><summary style="cursor:pointer;color:#94a3b8;font-size:10.5px">'
      +'📋 '+toFa(ps.used||0)+' پروفایل استفاده شد'
      +((ps.skipped||0)?(' · '+toFa(ps.skipped)+' کنار گذاشته شد'):'')+'</summary>'
      +'<div style="padding:5px 8px 0;font-size:10px;line-height:1.9">';
    ps.profiles.forEach(p=>{
      h+='<div style="color:'+(p.n>0?'#cbd5e1':'#64748b')+'">'+(p.n>0?'✓ ':'⏭ ')+esc(p.name||'')
        +(p.n>0?(' — '+toFa(p.n)+' محصول'+(p.no_price?(' ('+toFa(p.no_price)+' بدون قیمت)'):'')):'')
        +(p.why?' <span style="color:#64748b">· '+esc(p.why)+'</span>':'')+'</div>';
    });
    h+='</div></details>';
  }
    if(d.shops&&d.shops.length){
    h+='<div style="margin:6px 0;padding:8px;background:#0b1220;border:1px solid #334155;border-radius:8px;font-size:10.5px;line-height:1.85">';
    h+='<div style="color:#67e8f9;font-weight:800;margin-bottom:4px">🏪 خلاصهٔ غرفه‌ها ('+toFa(d.shops.length)+')</div>';
    d.shops.forEach(function(s){
      h+='<div style="color:'+(s.ok?'#cbd5e1':'#fca5a5')+'">'+(s.ok?'✓':'✗')+' '+esc(s.shop_name||('#'+s.vendor_id))
        +' — مقصد '+toFa(s.remote||0)
        +' · در مبدأ نیست '+toFa(s.extra||0)
        +' · مغایرت '+toFa(s.diff||0)
        +' · در مقصد نیست '+toFa(s.missing||0)
        +(s.error?(' · '+esc(s.error)):'')+'</div>';
    });
    h+='</div>';
  }
  if(d.matched_by_id>0){
    h+='<div style="color:#86efac;font-size:10.5px;margin-top:4px">🔗 '+toFa(d.matched_by_id)
      +' محصول با شناسهٔ ثبت‌شده تطبیق خورد — عنوانشان در مقصد عوض شده بود</div>';
  }
  if(d.no_src_price>0){
    h+='<div style="color:#94a3b8;font-size:10.5px;margin-top:4px">ℹ️ '+toFa(d.no_src_price)
      +' محصول در مبدأ قیمت ندارد — قیمتشان مقایسه نشد</div>';
  }
  if(nExtra>0&&nRem>0&&nExtra===nRem){
    h+='<div style="background:#7f1d1d30;border:1px solid #ef4444;border-radius:8px;padding:7px;'
      +'margin-top:5px;font-size:10.5px;color:#fca5a5;line-height:1.8">'
      +'⚠️ <b>هیچ محصولی تطبیق نخورد.</b> یعنی عنوان‌های مقصد با پروفایل یکی نیستند '
      +'(پسوند پروفایل، تغییر نام دستی، یا پروفایل اشتباه). '
      +'قبل از هر اقدامی روی «اضافی» بزنید و فهرست را ببینید.</div>';
  }
  if(!nExtra&&!nDiff&&!nMiss)h+='<div style="color:#4ade80;margin-top:4px">✓ همه‌چیز هماهنگ است</div>';
  else if(nMiss)h+='<div style="color:#67e8f9;margin-top:4px">📤 '+toFa(nMiss)+' محصول در مبدأ هست ولی هنوز در مقصد نیست — از ارسال/سینک صف استفاده کنید</div>';
  if(nMiss>0 && !d.enqueued_done){
    h+='<div style="margin-top:8px;padding:10px;background:#082f49;border:1px solid #0ea5e9;border-radius:8px">';
    h+='<div style="color:#7dd3fc;font-weight:800;margin-bottom:6px">📤 سینک محصولات «در مقصد نیست»</div>';
    h+='<div style="color:#94a3b8;font-size:10.5px;line-height:1.7;margin-bottom:8px">'+toFa(nMiss)+' محصول در مبدأ/پروفایل هست ولی در '+(target==='woo'?'ووکامرس':'باسلام')+' نیست. با صف‌کردن، به صف ارسال می‌روند تا غرفه/فروشگاه پر شود.</div>';
    h+='<button class="btn btn-cyan" onclick="reconEnqueueMissing(\''+target+'\')" style="width:100%;font-size:11px">📤 صف‌کردن ' + toFa(nMiss) + ' محصول برای ارسال</button>';
    h+='<div id="reconEnqueueStatus" style="margin-top:6px;font-size:10.5px;color:#7dd3fc"></div>';
    h+='</div>';
  }
  if(!d.applied&&(nExtra||nDiff)){
    h+='<div style="margin-top:8px;padding-top:8px;border-top:1px solid #334155">';
    h+='<div style="color:#94a3b8;margin-bottom:5px">اقدام برای موارد اضافی:</div>';
    h+='<select id="reconMode" style="width:100%;margin-bottom:6px;padding:5px;font-size:11px">'
      +'<option value="off">کاری نکن (فقط قیمت‌ها اصلاح شود)</option>'
      +'<option value="draft">پیش‌نویس/غیرفعال کن</option>'
      +'<option value="outofstock">ناموجود کن</option>'
      +'<option value="delete">حذف کن (زباله‌دان)</option></select>';
    h+='<label style="display:flex;align-items:center;gap:6px;color:#cbd5e1;margin-bottom:6px;cursor:pointer">'
      +'<input type="checkbox" id="reconFixPrice" checked style="width:14px;height:14px">'
      +'<span>قیمت‌های مغایر اصلاح شوند ('+toFa(nDiff)+')</span></label>';
    h+='<button class="btn btn-green" onclick="reconApply(\''+target+'\')" style="width:100%;font-size:11px">'
      +'✅ اعمال تغییرات</button>';
    h+='</div>';
  }
  return h+'</div>';
}

var reconLastTarget='';

/** v8.50: فهرست محصولات یک شمارنده */
function reconList(kind){
  const d=reconLast||{};
  const map={
    extra:{rows:d.extra||[],total:d.extra_total||0,title:'🗑 در مبدأ نیست (اضافی مقصد)',color:'#fca5a5'},
    diff:{rows:d.price_diff||[],total:d.price_diff_total||0,title:'💰 مغایرت قیمت',color:'#fbbf24'},
    missing:{rows:d.missing||[],total:d.missing_total||0,title:'📤 در مقصد نیست (نیاز سینک)',color:'#67e8f9'},
    matched:{rows:d.matched_items||[],total:d.matched_items_total||d.matched||0,
             title:'✓ یکسان',color:'#86efac'}
  }[kind];
  if(!map){showToast('فهرستی نیست',1);return;}
  let h='<div class="bsl-modal-overlay" onclick="if(event.target===this)reconCloseList()">';
  h+='<div class="bsl-modal" style="max-width:760px">';
  h+='<div class="bsl-modal-head"><h2 style="color:'+map.color+'">'+map.title
    +' ('+toFa(map.total)+')</h2>'
    +'<button class="btn btn-gray" onclick="reconCloseList()">✕</button></div>';
  h+='<div style="padding:6px 12px;background:#111c31;border-bottom:1px solid #334155">'
    +'<input type="text" id="reconFilter" placeholder="جستجو در فهرست..." oninput="reconFilterRows()" '
    +'style="width:100%;padding:5px 8px;border:1px solid #475569;border-radius:6px;'
    +'background:#0f172a;color:#e2e8f0;font-size:11px;direction:rtl"></div>';
  h+='<div class="bsl-modal-body" style="max-height:60vh;overflow:auto">';
  if(!map.rows.length){
    h+='<div style="padding:24px;text-align:center;color:#64748b">موردی نیست</div>';
  }else{
    h+='<table class="bsl-modal-table"><thead><tr>'
      +'<th style="width:34px">#</th><th>عنوان</th>'
      +(kind==='diff'?'<th>فعلی</th><th>جدید</th>':'<th>قیمت</th>')
      +'<th style="width:52px">شناسه</th>'
      +(kind!=='matched'?'<th style="width:40px">وضعیت</th>':'')
      +'</tr></thead><tbody id="reconRows">';
    map.rows.forEach((it,n)=>{
      const money=v=>toFa(Number(v||0).toLocaleString('en-US'));
      h+='<tr class="rc-row" data-t="'+esc(String(it.title||'').toLowerCase())+'">'
        +'<td style="color:#64748b">'+toFa(n+1)+'</td>'
        +'<td>'+esc(String(it.title||''))+'</td>';
      h+=kind==='diff'
        ? '<td style="color:#94a3b8;white-space:nowrap">'+money(it.from)+'</td>'
          +'<td style="color:#e2e8f0;white-space:nowrap"><b>'+money(it.to)+'</b></td>'
        : '<td style="white-space:nowrap">'+money(it.price)+'</td>';
      h+='<td style="font-family:ui-monospace,monospace;color:#64748b">'+toFa(it.id||0)+'</td>';
      if(kind!=='matched'){
        h+='<td style="text-align:center">'+(it.done===true?'<span style="color:#4ade80">✓</span>'
          :(it.done===false?'<span style="color:#fca5a5">✗</span>':'<span style="color:#475569">—</span>'))+'</td>';
      }
      h+='</tr>';
    });
    h+='</tbody></table>';
    if(map.total>map.rows.length){
      h+='<div style="padding:8px;text-align:center;color:#64748b;font-size:10.5px">'
        +'نمایش '+toFa(map.rows.length)+' مورد از '+toFa(map.total)+'</div>';
    }
  }
  h+='</div></div></div>';
  const old=document.getElementById('reconListBox');if(old)old.remove();
  const div=document.createElement('div');div.id='reconListBox';div.innerHTML=h;
  document.body.appendChild(div);
}

function reconCloseList(){const m=document.getElementById('reconListBox');if(m)m.remove();}

function reconFilterRows(){
  const q=((document.getElementById('reconFilter')||{}).value||'').toLowerCase().trim();
  document.querySelectorAll('#reconRows .rc-row').forEach(tr=>{
    tr.style.display=(!q||(tr.dataset.t||'').includes(q))?'':'none';
  });
}

/** گام ۲: اعمال، با تأیید صریح — سمت سرور با گزارش زنده */
function reconApply(target){
  const mode=($('reconMode')||{}).value||'off';
  const fix=($('reconFixPrice')||{}).checked?1:0;
  const d=reconLast||{};
  const nExtra=d.extra_total||0, nDiff=d.price_diff_total||0;
  const modeTxt={off:'',draft:'پیش‌نویس',outofstock:'ناموجود',delete:'حذف'}[mode]||'';
  if(!fix&&mode==='off'){showToast('هیچ اقدامی انتخاب نشده',1);return;}
  let msg='تغییرات روی '+reconLabel(target)+':\n';
  if(fix&&nDiff)msg+='\n• اصلاح قیمت '+nDiff+' محصول';
  if(mode!=='off'&&nExtra)msg+='\n• '+modeTxt+' کردن '+nExtra+' محصول اضافی';
  msg+='\n\nادامه می‌دهید؟';
  if(!confirm(msg))return;
  reconStart(target,true,mode,fix);
}

/** v10.108: صف‌کردن «در مقصد نیست» از آخرین گزارش مغایرت */
function reconEnqueueMissing(target){
  const d=reconLast||{};
  const n=d.missing_total||((d.missing||[]).length)||0;
  if(!n){showToast('موردی برای صف نیست',1);return;}
  if(!confirm('«'+n+'» محصولِ در مقصد نیست به صف ارسال '+reconLabel(target)+' اضافه شود؟\n\nاین کار فقط صف می‌سازد؛ ارسال توسط ورکر/کران انجام می‌شود.'))return;
  const st=$('reconEnqueueStatus');
  if(st) st.textContent='⏳ در حال صف‌کردن...';
  const fd=new FormData();
  if(d.missing&&d.missing.length){
    fd.append('missing', JSON.stringify(d.missing));
  }
  fd.append('max','2000');
  fetch('?recon_enqueue=1&target='+encodeURIComponent(target),{method:'POST',body:fd})
    .then(r=>r.json()).then(function(res){
      if(!res||!res.ok){
        const err=(res&&(res.error||res.msg))||'ناموفق';
        if(st) st.innerHTML='<span style="color:#fca5a5">✗ '+esc(err)+'</span>';
        showToast(err,1);
        return;
      }
      const msg=(res.msg||('صف شد: '+(res.products||0)+' محصول'));
      if(st) st.innerHTML='<span style="color:#4ade80">✓ '+esc(msg)+'</span>';
      showToast('✓ '+msg);
      if(reconLast){ reconLast.enqueued_done=true; reconLast.enqueue=res; }
      // refresh report strip
      const box=$('reconR');
      if(box&&reconLast){
        const tip=document.createElement('div');
        tip.style.cssText='margin-top:6px;padding:8px;background:#052e16;border:1px solid #16a34a;border-radius:8px;font-size:11px;color:#86efac';
        tip.textContent='✓ ' + msg + ' — از تب ارسال، صف را دنبال کنید.';
        box.appendChild(tip);
      }
    }).catch(function(e){
      if(st) st.innerHTML='<span style="color:#f87171">✗ شبکه</span>';
      showToast('خطای شبکه',1);
    });
}

/* =====================================================================
 *  v8.64: پاسخ خودکار به پیام مشتریان — رابط کاربری
 * ===================================================================== */
var arRules=[], arLoaded=false;

const AR_MATCH={contains:'شامل کلمه',exact:'دقیقاً همین',starts:'شروع با',regex:'الگوی regex',always:'همیشه (پیش‌فرض)'};

function arCollectCfg(){
  const g=id=>$(id)||{};
  return {
    enabled:      !!g('arEnabled').checked,
    grace_min:    parseInt(g('arGrace').value||'10')||0,
    per_chat_min: parseInt(g('arPerChat').value||'180')||0,
    max_per_run:  parseInt(g('arMaxRun').value||'5')||5,
    scan_limit:   parseInt(g('arScan').value||'20')||20,
    only_offhours:!!g('arOffHours').checked,
    work_from:    parseInt(g('arFrom').value||'9')||0,
    work_to:      parseInt(g('arTo').value||'21')||0,
    sign:         (g('arSign').value||'').trim(),
    notify:       !!g('arNotify').checked,
    ai_system_mode:(g('arAiSysMode').value||'default'),
    ai_system_text:(g('arAiSysText').value||'').trim(),
    reply_order:(g('arOrder').value||'rules_first')
  };
}

function arApplyCfg(c){
  c=c||{};
  const set=(id,v)=>{const e=$(id);if(e)e.value=v;};
  const chk=(id,v)=>{const e=$(id);if(e)e.checked=!!v;};
  // ساعت‌ها یک بار پر می‌شوند
  ['arFrom','arTo'].forEach(id=>{
    const e=$(id); if(!e||e.options.length)return;
    let h=''; for(let i=0;i<24;i++)h+='<option value="'+i+'">'+toFa(String(i).padStart(2,'0'))+':۰۰</option>';
    e.innerHTML=h;
  });
  chk('arEnabled',c.enabled);
  set('arGrace',c.grace_min!==undefined?c.grace_min:10);
  set('arPerChat',c.per_chat_min!==undefined?c.per_chat_min:180);
  set('arMaxRun',c.max_per_run!==undefined?c.max_per_run:5);
  set('arScan',c.scan_limit!==undefined?c.scan_limit:20);
  chk('arOffHours',c.only_offhours);
  set('arFrom',String(c.work_from!==undefined?c.work_from:9));
  set('arTo',String(c.work_to!==undefined?c.work_to:21));
  set('arSign',c.sign||'');
  chk('arNotify',c.notify);
  set('arAiSysMode',c.ai_system_mode||'default');
  set('arAiSysText',c.ai_system_text||'');
  set('arOrder',c.reply_order||'rules_first');
  arAiSysToggle();
  arOrderHint();
  arToggleHours();
  arBadge();
}
function arAiSysToggle(){
  const v=($('arAiSysMode')||{}).value||'default';
  const tr=$('arAiSysTextRow');
  const dh=$('arAiSysDefaultHint');
  if(tr)tr.style.display=(v==='custom')?'':'none';
  if(dh)dh.style.display=(v==='default')?'':'none';
}
/* v9.38: شرح هر حالتِ ترتیب اولویت پاسخ‌دهی */
function arOrderHint(){
  const h=$('arOrderHint'); if(!h)return;
  const v=($('arOrder')||{}).value||'rules_first';
  const map={
    'rules_first':'⭐ پیشنهادی: «سلام» و سؤال‌های ساده را همان قواعدِ آماده جواب می‌دهند (سریع و مطمئن). فقط وقتی هیچ قاعده‌ای نخورد — مثلاً «سلام، وقتتون بخیر، این کالا موجوده؟» — هوش مصنوعی پاسخ می‌دهد.',
    'ai_first':'🤖 اول از هوش مصنوعی پاسخ گرفته می‌شود؛ اگر خطا یا پاسخ خالی بدهد، قواعدِ آماده امتحان می‌شوند.',
    'rules_only':'📋 فقط از قواعدِ آماده استفاده می‌شود؛ هوش مصنوعی اصلاً صدا زده نمی‌شود.',
    'ai_only':'🧠 فقط از هوش مصنوعی استفاده می‌شود؛ قواعدِ آماده نادیده گرفته می‌شوند.'
  };
  h.textContent=map[v]||'';
}

function arToggleHours(){
  const r=$('arHoursRow');
  if(r)r.classList.toggle('hidden',!($('arOffHours')||{}).checked);
}
/* v9.37: تغییر تب‌های بخش پاسخ خودکار */
function arTab(btn){
  if(!btn)return;
  const tab=btn.getAttribute('data-ar-tab');
  document.querySelectorAll('.ar-tab').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  document.querySelectorAll('.ar-pane').forEach(p=>{
    p.style.display=(p.getAttribute('data-ar-pane')===tab)?'':'none';
  });
}

function arBadge(){
  const b=$('arS'); if(!b)return;
  const on=($('arEnabled')||{}).checked;
  const nOn=arRules.filter(r=>r.on).length;
  b.textContent=on?('فعال · '+toFa(nOn)+' قاعده'):'خاموش';
  b.className='cst '+(on?'on':'off');
}

function arSaveCfg(){arBadge();saveConn();}

/** قواعد و تنظیمات را از سرور می‌گیرد */
function arLoad(force){
  if(arLoaded&&!force)return Promise.resolve();
  return fetch('?ar_rules=1').then(r=>r.json()).then(d=>{
    if(!d.ok)return;
    arRules=d.rules||[];
    arLoaded=true;
    arApplyCfg(d.cfg||{});
    arRenderRules();
  }).catch(()=>{});
}

/* v10.57 (۷۱): اتاقِ چتِ باسلام — چندغرفه‌ای، زنده (هر ۱ ثانیه)، موبایل‌محور،
   با تصویر. لیستِ مشتری‌ها در موبایل کشویی است؛ عددِ پرانتزی = شمارهٔ غرفه. */
let MR_CHAT=null;           // {id, shop, shop_name, who, _count, _lastId}
let MR_SHOP_FILTER=0;       // 0 = همهٔ غرفه‌ها
let MR_IMG=null;            // {dataURL, name, mime}
let MR_SHOPS=[];            // [{shop,name,ok,n}]
let MR_LAST_CHATS=[];
const MR_COLORS=['#60a5fa','#34d399','#fbbf24','#f472b6','#a78bfa','#fb923c','#4ade80','#e879f9'];
function mrShopColor(n){return MR_COLORS[(n-1)%MR_COLORS.length];}
function mrIsMobile(){return window.innerWidth<720;}
function mrMsg(t,c){const m=$('mrMsg'); if(m){m.innerHTML=t; m.className='msg on '+(c||'');}}
function mrBodyOpen(){const b=$('mrBody'); return !!(b&&b.classList.contains('open')&&b.offsetParent!==null);}
function mrRelTime(v){
  if(!v)return'';
  let t=Date.parse(String(v));
  if(isNaN(t))t=Date.parse(String(v).replace(' ','T'));
  if(isNaN(t))return'';
  const df=(Date.now()-t)/1000;
  if(df<60)return'همین حالا';
  if(df<3600)return toFa(Math.floor(df/60))+' دقیقه پیش';
  if(df<86400)return toFa(Math.floor(df/3600))+' ساعت پیش';
  return toFa(Math.floor(df/86400))+' روز پیش';
}
async function mrFetchChats(){
  const d=await fetch('?bsl_chats=1&limit=30&shop='+MR_SHOP_FILTER).then(r=>r.json()).catch(()=>null);
  return (d&&d.ok)?d:null;
}
async function mrPoll(){
  if(document.visibilityState!=='visible'||!mrBodyOpen())return;
  const d=await mrFetchChats();
  if(!d)return;
  MR_SHOPS=d.shops||[];
  mrRenderChips();
  mrRenderList(d.chats||[]);
  mrUnreadBadge(d.chats||[]); /* v10.84 (98) */
  const info=$('mrInfo');
  if(info){
    const n=(d.chats||[]).length;
    const bad=(d.shop_errors||[]).length;
    info.textContent='به‌روزرسانیِ خودکارِ هر ۱ ثانیه'+(n?' · '+toFa(n)+' گفتگو':'')+(bad?' · '+toFa(bad)+' غرفه خطا دارد':'');
  }
  if(MR_CHAT)mrPollThread(false);
}
function mrRenderChips(){
  const box=$('mrShopChips'); if(!box)return;
  box.innerHTML='<span class="mrchip'+(MR_SHOP_FILTER===0?' on':'')+'" onclick="mrFilterShop(0)">همه</span>'+
    MR_SHOPS.map(x=>'<span class="mrchip'+(MR_SHOP_FILTER===x.shop?' on':'')+'" onclick="mrFilterShop('+x.shop+')" title="'+esc(x.name)+'"><span style="color:'+mrShopColor(x.shop)+'">('+toFa(x.shop)+')</span> '+esc(x.name)+(x.ok===false?' ⚠️':'')+'</span>').join('');
}
function mrFilterShop(n){
  MR_SHOP_FILTER=n;
  mrRenderChips();
  mrRenderList(MR_LAST_CHATS.filter(c=>n===0||(c.shop||1)===n));
  mrPoll();
}
function mrRenderList(chats){
  const box=$('mrList'); if(!box)return;
  const badge=$('mrListBadge');
  const tot=chats.reduce((a,c)=>a+(c.unseen||0),0);
  if(badge)badge.innerHTML=tot>0?'<span style="background:#dc2626;color:#fff;border-radius:9px;font-size:9.5px;padding:0 6px">'+toFa(tot)+' جدید</span>':'<span style="color:#64748b;font-size:9.5px">'+toFa(chats.length)+' گفتگو</span>';
  if(!chats.length){box.innerHTML='<div class="empty" style="padding:16px 6px">گفتگویی پیدا نشد</div>';return;}
  box.innerHTML=chats.map(c=>{
    const col=mrShopColor(c.shop||1);
    const active=MR_CHAT&&MR_CHAT.id===c.chat_id;
    return '<div onclick="mrOpenChat('+c.chat_id+','+(c.shop||1)+')" style="padding:7px 9px;border-bottom:1px solid #1e293b;cursor:pointer;border-radius:6px'+(active?';background:#16233d':'')+'">'+
      '<div style="display:flex;justify-content:space-between;align-items:center;gap:6px">'+
      '<b style="font-size:11.5px;color:#e2e8f0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(c.who)+'</b>'+
      '<span style="display:flex;gap:4px;align-items:center;flex:0 0 auto">'+
      '<span style="color:'+col+';font-size:9.5px;border:1px solid '+col+'66;border-radius:8px;padding:0 5px" title="'+esc(c.shop_name||'')+'">('+toFa(c.shop||1)+')</span>'+
      (c.unseen>0?'<span style="background:#dc2626;color:#fff;border-radius:9px;font-size:9.5px;padding:0 6px">'+toFa(c.unseen)+'</span>':'')+
      '</span></div>'+
      '<div style="display:flex;align-items:center;gap:5px;margin-top:2px">'+
      (c.last_img?'<img src="'+esc(c.last_img)+'" alt="تصویر" onclick="event.stopPropagation();mrLightbox(this.src)" style="width:27px;height:27px;object-fit:cover;border-radius:6px;flex:0 0 auto;cursor:zoom-in;border:1px solid #334155" title="نمایش تصویر"/>':'')+
      '<span style="font-size:10.5px;color:#94a3b8;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1">'+
      (c.last_is_mine?'<span style="color:#60a5fa">شما:</span> ':'')+esc(c.text||'—')+'</span></div>'+
      '<div style="font-size:9px;color:#475569;margin-top:1px">'+mrRelTime(c.updated_at)+'</div>'+
      '</div>';
  }).join('');
}
async function mrOpenChat(id,shop){
  shop=shop||1;
  mrCloseDrawer(); /* v10.84 (98): با انتخابِ گفتگو، لیستِ کشویی بسته شود */
  const c=MR_LAST_CHATS.find(x=>x.chat_id===id)||null;
  MR_CHAT={id:id, shop:shop, shop_name:c?(c.shop_name||''):'', who:c?(c.who||'مشتری'):'مشتری'};
  mrRenderList(MR_LAST_CHATS);
  const hdr=$('mrThrHdr'); if(hdr)hdr.style.display='flex';
  const w=$('mrWho'); if(w)w.textContent=MR_CHAT.who;
  const tag=$('mrShopTag');
  if(tag){tag.textContent='('+toFa(shop)+') '+(MR_CHAT.shop_name||''); tag.style.color=mrShopColor(shop);}
  if(mrIsMobile()){
    $('mrList').classList.add('mr-collapsed');
    const a=$('mrListArrow'); if(a)a.textContent='▲';
    $('mrBackBtn').style.display='inline-block';
    const t=$('mrThread'); if(t)t.scrollIntoView({behavior:'smooth',block:'nearest'});
  }
  $('mrMsgs').innerHTML='<div class="empty" style="padding:14px 6px">در حالِ بارگذاری…</div>';
  await mrPollThread(true);
}
async function mrPollThread(force){
  if(!MR_CHAT)return;
  const d=await fetch('?bsl_chat_messages=1&chat_id='+MR_CHAT.id+'&shop='+MR_CHAT.shop+'&limit=40').then(r=>r.json()).catch(()=>null);
  if(!d||!d.ok)return;
  const msgs=d.messages||[];
  if(d.shop)MR_CHAT.shop=d.shop;
  const box=$('mrMsgs'); if(!box)return;
  const atBottom=box.scrollHeight-box.scrollTop-box.clientHeight<80;
  const changed=force||MR_CHAT._lastId===undefined||msgs.length!==MR_CHAT._count||msgs.length>0&&msgs[msgs.length-1].id!==MR_CHAT._lastId;
  if(changed){
    box.innerHTML=msgs.length?msgs.map(mrMsgHtml).join(''):'<div class="empty" style="padding:20px 6px">پیامی در این گفتگو نیست</div>';
  }
  MR_CHAT._count=msgs.length;
  MR_CHAT._lastId=msgs.length?msgs[msgs.length-1].id:null;
  if(force||atBottom)box.scrollTop=box.scrollHeight;
}
function mrMsgHtml(m){
  let inner='';
  if(m.img)inner+='<div style="margin-top:4px"><img src="'+esc(m.img)+'" alt="تصویر" style="max-width:180px;max-height:180px;border-radius:6px;display:block;cursor:zoom-in" title="برای بزرگ‌نمایی کلیک کنید" onclick="event.stopPropagation();mrLightbox(this.src)"></div>';
  if(m.text)inner+='<div>'+esc(m.text)+'</div>';
  else if(!m.img&&m.type&&m.type!=='text')inner+='<span style="color:#64748b">['+esc(m.type)+']</span>';
  const mine=!!m.mine;
  return '<div style="margin-bottom:9px">'+
    '<div style="font-size:9.5px;color:#64748b;margin-bottom:2px">'+esc(m.sender||(mine?'شما':'مشتری'))+(m.at?' · '+mrRelTime(m.at):'')+'</div>'+
    '<div style="display:inline-block;max-width:88%;background:'+(mine?'#173254':'#1e293b')+';border-radius:7px;padding:6px 9px;color:#e2e8f0;word-break:break-word">'+inner+'</div></div>';
}
function mrCloseChat(){
  MR_CHAT=null;
  const hdr=$('mrThrHdr'); if(hdr)hdr.style.display='none';
  const b=$('mrBackBtn'); if(b)b.style.display='none';
  const m=$('mrMsgs'); if(m)m.innerHTML='<div class="empty" style="padding:20px 6px">یک گفتگو را انتخاب کنید</div>';
  const L=$('mrList'); if(L)L.classList.remove('mr-collapsed');
  const a=$('mrListArrow'); if(a)a.textContent='▼';
  mrRenderList(MR_LAST_CHATS);
}
function mrToggleList(){
  const L=$('mrList'); if(!L)return;
  L.classList.toggle('mr-collapsed');
  const a=$('mrListArrow'); if(a)a.textContent=L.classList.contains('mr-collapsed')?'▲':'▼';
}
function mrFileClick(){const f=$('mrFile'); if(f)f.click();}
function mrPickImage(inp){
  const f=inp.files&&inp.files[0]; inp.value='';
  if(!f)return;
  if(f.size>7500000){mrMsg('✗ تصویر خیلی بزرگ است (حداکثر حدود ۷ مگابایت)','m-err');return;}
  const rd=new FileReader();
  rd.onload=()=>{
    MR_IMG={dataURL:rd.result,name:f.name,mime:f.type||'image/jpeg'};
    const p=$('mrImgPrev');
    p.style.display='flex';
    p.innerHTML='<img src="'+rd.result+'" style="width:44px;height:44px;object-fit:cover;border-radius:6px;border:1px solid #334155;display:block"><span style="font-size:10.5px;color:#94a3b8;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(f.name)+'</span><button type="button" class="btn btn-gray" style="flex:0 0 auto;padding:2px 9px;font-size:10px" onclick="mrClearImage()">✕ حذف</button>';
  };
  rd.onerror=()=>mrMsg('✗ خواندنِ فایل ناموفق بود','m-err');
  rd.readAsDataURL(f);
}
function mrClearImage(){MR_IMG=null;const p=$('mrImgPrev'); if(p){p.style.display='none';p.innerHTML='';}}
function mrQuick(t){const el=$('mrText'); if(el){el.value=(el.value?el.value+' ':'')+t; el.focus();}}
function mrKeydown(e){
  /* v10.85 (99): Ctrl+Enter = ارسال، Enter = خط جدید */
  if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();mrSend();}
}
async function mrLoadChats(){
  mrMsg('در حالِ بررسیِ گفتگوها…','');
  mrPoll();
  setTimeout(()=>{const m=$('mrMsg'); if(m&&!m.classList.contains('m-err'))mrMsg('✓ به‌روز شد','m-ok');},1200);
}
async function mrSend(){
  if(!MR_CHAT)return;
  const t=$('mrText').value.trim();
  if(!t&&!MR_IMG)return;
  const btn=$('mrSendBtn'); if(btn)btn.disabled=true;
  const fd=new FormData();
  fd.append('chat_id',MR_CHAT.id);
  fd.append('shop',MR_CHAT.shop);
  fd.append('text',t);
  if(MR_IMG){
    fd.append('image_b64',MR_IMG.dataURL);
    fd.append('image_name',MR_IMG.name);
    fd.append('image_mime',MR_IMG.mime);
  }
  mrMsg(MR_IMG?'📤 آپلودِ تصویر و ارسال…':'در حالِ ارسال…','');
  const d=await fetch('?bsl_chat_reply=1',{method:'POST',body:fd}).then(r=>r.json()).catch(()=>({ok:false,error:'خطای شبکه'}));
  if(btn)btn.disabled=false;
  if(!d.ok)return mrMsg('✗ '+esc(d.error||'ارسال ناموفق'),'m-err');
  mrMsg('✓ '+(MR_IMG?'تصویر ارسال شد':'پاسخ ارسال شد'),'m-ok');
  $('mrText').value='';
  if(MR_IMG)mrClearImage();
  mrPollThread(true);
  setTimeout(mrPoll,300);
}
/* v10.57 (۷۱): ضربانِ سراسریِ ۱ ثانیه‌ای — فقط وقتی اتاقِ چت باز است و تب
   دیده می‌شود درخواست می‌فرستد (وگرنه بلافاصله برمی‌گردد). */
setInterval(mrPoll,1000);

/* v10.83 (97): اتاقِ چت درِ مودال — گرهٔ زندهٔ #mrBody جابه‌جا می‌شود
   (نه کپی): همهٔ JSِ موجود (پُلیینگ، ارسال، تصویر) بدونِ تغییر کار می‌کند. */
// =========================================================================
// STORE ONLINE HUMAN SUPPORT DESK JAVASCRIPT
// =========================================================================
let MR_STORE_THREADS = [];
let MR_SELECTED_THREAD = null;
let MR_ACTIVE_CHANNEL = 'store'; // 'store' or 'bsl'

function mrSwitchChannel(chan) {
    MR_ACTIVE_CHANNEL = chan;
    const tabStore = document.getElementById('mrTabStore');
    const tabBsl = document.getElementById('mrTabBsl');
    const paneStore = document.getElementById('mrStoreDeskPane');
    const paneBsl = document.getElementById('mrBslPane');

    if (chan === 'store') {
        if (tabStore) tabStore.className = 'btn btn-blue';
        if (tabBsl) tabBsl.className = 'btn btn-gray';
        if (paneStore) paneStore.style.display = 'block';
        if (paneBsl) paneBsl.style.display = 'none';
        mrFetchStoreThreads();
    } else {
        if (tabStore) tabStore.className = 'btn btn-gray';
        if (tabBsl) tabBsl.className = 'btn btn-blue';
        if (paneStore) paneStore.style.display = 'none';
        if (paneBsl) paneBsl.style.display = 'block';
        mrLoadChats();
  mrFetchStoreThreads();
    }
}

async function mrFetchStoreThreads() {
    try {
        const res = await fetch('?store_chat_api=get_threads').then(r => r.json());
        if (res && res.ok) {
            MR_STORE_THREADS = res.threads || [];
            mrRenderStoreThreads();

            // Update badge
            const badge = document.getElementById('mrStoreUnreadBadge');
            const hdrBadge = document.getElementById('chatUnreadB');
            if (badge) {
                if (res.unread_total > 0) {
                    badge.textContent = res.unread_total;
                    badge.style.display = 'inline-block';
                } else {
                    badge.style.display = 'none';
                }
            }
            if (hdrBadge && res.unread_total > 0) {
                hdrBadge.textContent = res.unread_total;
                hdrBadge.style.display = 'flex';
            }
        }
    } catch(e){}
}

function mrFilterStoreThreads() {
    mrRenderStoreThreads();
}

function mrRenderStoreThreads() {
    const listEl = document.getElementById('storeThreadsList');
    if (!listEl) return;

    const q = (document.getElementById('storeThreadSearch')?.value || '').trim().toLowerCase();
    const filtered = MR_STORE_THREADS.filter(t => {
        if (!q) return true;
        const name = (t.name || '').toLowerCase();
        const phone = (t.phone || '').toLowerCase();
        const lastMsg = ((t.messages && t.messages.length) ? t.messages[t.messages.length - 1].text : '').toLowerCase();
        return name.includes(q) || phone.includes(q) || lastMsg.includes(q);
    });

    if (filtered.length === 0) {
        listEl.innerHTML = '<div style="text-align:center;color:#64748b;font-size:11px;padding:24px 10px;">هیچ گفتگویی یافت نشد.</div>';
        return;
    }

    let html = '';
    filtered.forEach(t => {
        const isSelected = MR_SELECTED_THREAD && (MR_SELECTED_THREAD.id === t.id);
        const lastMsg = (t.messages && t.messages.length) ? t.messages[t.messages.length - 1] : { text: '', time: '' };
        const unread = t.unread_admin ? '<span style="width:8px;height:8px;background:#ef4444;border-radius:50%;display:inline-block;"></span>' : '';
        const statusBadge = t.status === 'pending'
            ? '<span style="background:#fee2e2;color:#dc2626;font-size:9px;padding:1px 5px;border-radius:4px;font-weight:700;">در انتظار</span>'
            : '<span style="background:#ecfdf5;color:#059669;font-size:9px;padding:1px 5px;border-radius:4px;font-weight:700;">پاسخ‌داده</span>';

        html += `
        <div onclick="mrSelectStoreThread('${t.id}')" style="background:${isSelected ? '#1e293b' : '#111c31'};border:1px solid ${isSelected ? '#3b82f6' : '#1e293b'};border-radius:8px;padding:8px 10px;cursor:pointer;transition:all 0.15s;">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">
                <div style="display:flex;align-items:center;gap:6px;">
                    ${unread}
                    <strong style="font-size:11.5px;color:#fff;">${t.name || 'کاربر مهمان'}</strong>
                </div>
                <span style="font-size:9.5px;color:#64748b;">${lastMsg.time || ''}</span>
            </div>
            <div style="font-size:10.5px;color:#94a3b8;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-bottom:4px;">
                ${lastMsg.text || 'شروع مکالمه'}
            </div>
            <div style="display:flex;justify-content:space-between;align-items:center;font-size:9.5px;color:#64748b;">
                <span>${t.phone ? '📞 ' + t.phone : 'بدون شماره'}</span>
                ${statusBadge}
            </div>
        </div>
        `;
    });

    listEl.innerHTML = html;

    // Keep active thread refreshed
    if (MR_SELECTED_THREAD) {
        const found = MR_STORE_THREADS.find(t => t.id === MR_SELECTED_THREAD.id);
        if (found) {
            MR_SELECTED_THREAD = found;
            mrRenderStoreMessages();
        }
    } else if (filtered.length > 0) {
        mrSelectStoreThread(filtered[0].id);
    }
}

function mrSelectStoreThread(id) {
    const thread = MR_STORE_THREADS.find(t => t.id === id);
    if (!thread) return;
    MR_SELECTED_THREAD = thread;
    mrRenderStoreMessages();
    mrRenderStoreThreads();
}

function mrRenderStoreMessages() {
    if (!MR_SELECTED_THREAD) return;
    const t = MR_SELECTED_THREAD;

    const nameEl = document.getElementById('storeActiveName');
    const metaEl = document.getElementById('storeActiveMeta');
    const badgeEl = document.getElementById('storeActiveBadge');
    const msgsWrap = document.getElementById('storeMsgsWrap');

    if (nameEl) nameEl.textContent = t.name || 'کاربر مهمان';
    if (metaEl) metaEl.textContent = (t.phone ? 'شماره تماس: ' + t.phone : 'بدون شماره') + (t.email ? ' | ' + t.email : '');
    if (badgeEl) {
        badgeEl.innerHTML = t.status === 'pending'
            ? '<span style="background:#fee2e2;color:#dc2626;font-size:10px;padding:3px 8px;border-radius:6px;font-weight:800;">⏳ نیازمند پاسخ</span>'
            : '<span style="background:#ecfdf5;color:#059669;font-size:10px;padding:3px 8px;border-radius:6px;font-weight:800;">✅ پاسخ داده شده</span>';
    }

    if (!msgsWrap) return;
    const msgs = t.messages || [];
    if (msgs.length === 0) {
        msgsWrap.innerHTML = '<div style="text-align:center;color:#64748b;font-size:11px;padding:20px;">هیچ پیامی در این گفتگو ثبت نشده است.</div>';
        return;
    }

    let html = '';
    msgs.forEach(m => {
        const isCustomer = m.sender === 'customer';
        html += `
        <div style="display:flex;justify-content:${isCustomer ? 'flex-start' : 'flex-end'};margin-bottom:4px;">
            <div style="max-width:82%;background:${isCustomer ? '#1e293b' : '#2563eb'};color:#fff;border-radius:12px;padding:8px 12px;font-size:11.5px;line-height:1.6;box-shadow:0 2px 6px rgba(0,0,0,0.2);">
                <div style="font-size:9.5px;color:${isCustomer ? '#94a3b8' : '#bfdbfe'};font-weight:700;margin-bottom:3px;display:flex;justify-content:space-between;gap:8px;">
                    <span>${m.sender_name || (isCustomer ? 'مشتری' : 'ادمین')}</span>
                    <span>${m.time || ''}</span>
                </div>
                <div style="white-space:pre-wrap;">${m.text || ''}</div>
            </div>
        </div>
        `;
    });

    msgsWrap.innerHTML = html;
    msgsWrap.scrollTop = msgsWrap.scrollHeight;
}

function mrInsertStoreQuick(text) {
    const area = document.getElementById('storeReplyText');
    if (!area) return;
    area.value = text;
    area.focus();
}

async function mrSendStoreReply() {
    if (!MR_SELECTED_THREAD) {
        alert('لطفاً ابتدا یک گفتگو را انتخاب نمایید.');
        return;
    }
    const area = document.getElementById('storeReplyText');
    const text = (area?.value || '').trim();
    if (!text) {
        alert('لطفاً متن پاسخ را بنویسید.');
        return;
    }

    const btn = document.getElementById('btnSendStoreReply');
    const status = document.getElementById('storeReplyStatus');
    if (btn) btn.disabled = true;
    if (status) { status.style.color = '#38bdf8'; status.textContent = 'در حال ارسال پاسخ به مشتری و پیام‌رسان‌ها...'; }

    try {
        const fd = new FormData();
        fd.append('store_chat_api', 'send_reply');
        fd.append('thread_id', MR_SELECTED_THREAD.id);
        fd.append('reply_text', text);

        const res = await fetch('', { method: 'POST', body: fd }).then(r => r.json());
        if (res && res.ok) {
            if (area) area.value = '';
            if (status) { status.style.color = '#4ade80'; status.textContent = '✓ پاسخ با موفقیت به مشتری و پیام‌رسان‌ها ارسال شد.'; setTimeout(() => status.textContent = '', 4000); }
            if (res.thread) {
                MR_SELECTED_THREAD = res.thread;
                const idx = MR_STORE_THREADS.findIndex(t => t.id === res.thread.id);
                if (idx !== -1) MR_STORE_THREADS[idx] = res.thread;
                mrRenderStoreMessages();
                mrRenderStoreThreads();
            }
        } else {
            alert('خطا در ارسال پاسخ: ' + (res.error || 'خطای سرور'));
            if (status) { status.style.color = '#f87171'; status.textContent = 'خطا در ارسال پاسخ'; }
        }
    } catch(err) {
        alert('خطای اتصال به سرور');
        if (status) { status.style.color = '#f87171'; status.textContent = 'خطای اتصال'; }
    } finally {
        if (btn) btn.disabled = false;
    }
}

// Auto-poll store threads when visible
setInterval(() => {
    if (document.visibilityState === 'visible' && MR_ACTIVE_CHANNEL === 'store') {
        mrFetchStoreThreads();
    }
}, 5000);


function mrOpenModal(){
  const modal=$('mrModal'),body=$('mrBody');
  if(!modal||!body)return;
  if(body.parentNode.id!=='mrModalHost'){
    if(!body.__mrPh){
      const ph=document.createElement('div');
      ph.id='mrBodyPh';
      ph.innerHTML='<div style="font-size:10.5px;color:#64748b;padding:8px;line-height:1.8">این بخش الان به‌صورتِ مودال باز است (دکمهٔ 💬 بالایِ صفحه) — برایِ دیدنِ آنِجایی، مودال را ببندید.</div>';
      body.parentNode.insertBefore(ph,body);
      body.__mrPh=ph;
    }
    const h=$('mrModalHost'); if(h)h.appendChild(body);
  }
  body.classList.add('open');
  clearTimeout(body.__smenuT);
  setTimeout(()=>{if(body.classList.contains('open'))body.classList.add('smenu-done');},320);
  modal.style.display='flex';
  mrCloseDrawer(); /* v10.84 (98): مودال تازه باز شد — لیستِ کشویی بسته باشد */
  mrLoadChats();
  mrFetchStoreThreads();
  if (typeof mrSwitchChannel === 'function') mrSwitchChannel('store');
}
function mrCloseModal(){
  const modal=$('mrModal'),body=$('mrBody');
  if(!modal||!body)return;
  modal.style.display='none';
  if(body.parentNode.id==='mrModalHost'){
    const ph=body.__mrPh;
    if(ph&&ph.parentNode)ph.parentNode.insertBefore(body,ph);
    if(ph)ph.innerHTML='';
    const hdr=body.previousElementSibling;
    if(hdr&&!hdr.classList.contains('open'))body.classList.remove('open','smenu-done');
  }
}
/* v10.84 (98): تعدادِ خوانده‌نشده روی دکمهٔ «پاسخ دستی» */
function mrUnreadBadge(chats){
  const b=$('chatUnreadB'); if(!b||!chats)return;
  let n=0;
  for(let i=0;i<chats.length;i++){ const u=chats[i].unseen; if(u>0)n+=u; }
  if(n>0){ b.textContent=toFa(n); b.style.display='flex'; } else { b.style.display='none'; }
}
/* v10.84 (98): لیستِ چت‌ها به‌صورتِ کشویی درِ حالتِ تمام‌صفحه */
function mrToggleDrawer(){
  const row=$('mrRow'); if(!row)return;
  row.classList.toggle('mr-drawer-open');
  const b=$('mrDrawerBtn'); if(b)b.textContent=row.classList.contains('mr-drawer-open')?'✕':'👥';
}
function mrCloseDrawer(){
  const row=$('mrRow'); if(!row)return;
  row.classList.remove('mr-drawer-open');
  const b=$('mrDrawerBtn'); if(b)b.textContent='👥';
}
/* v10.84 (98): تب‌هایِ فرعیِ تبِ ارسال — ووکامرس / باسلام */
function sendSubTab(w){
  try{localStorage.setItem('send_subtab',w);}catch(e){}
  const woo=$('sendPaneWoo'),bsl=$('sendPaneBsl'),sync=$('sendPaneSync');
  if(woo)woo.style.display=(w==='woo')?'':'none';
  if(bsl)bsl.style.display=(w==='bsl')?'':'none';
  if(sync)sync.style.display=(w==='sync')?'':'none';
  const a=$('ssbWoo'),b=$('ssbBsl'),c=$('ssbSync');
  if(a)a.classList.toggle('on',w==='woo');
  if(b)b.classList.toggle('on',w==='bsl');
  if(c)c.classList.toggle('on',w==='sync');
  /* Refresh the selected queue on load/tab change so its profile summary is never stale. */
  if(w==='woo'){try{if(typeof checkWooQueue==='function')checkWooQueue();}catch(e){}}
  else if(w==='bsl'){try{if(typeof checkBslQueue==='function')checkBslQueue();}catch(e){}}
}

/* =====================================================================
   v10.60 (۷۴): نوتیفیکیشنِ زندهٔ پیام‌های تازهٔ مشتری
   ---------------------------------------------------------------------
   با رسیدنِ هر پیامِ جدیدِ مشتری (از هر غرفه) یک کارتِ شیک بالا می‌آید:
     • سوایپِ چپ   ⇒ بسته می‌شود
     • سوایپِ راست ⇒ اتاقِ چت روی همان گفتگو باز می‌شود و تکست‌باکسِ
       پاسخ فوکوس می‌شود — آمادهٔ تایپ (دکمه‌های ✕ / 💬 هم هستن).
   کشف: هر ۵ ثانیه (و بی‌وابستگی به باز بودنِ اتاقِ چت) فهرستِ گفتگوها
   خوانده می‌شود (کشِ ۲ ثانیه‌ایِ سرور، ارزان) و «شناسهٔ آخرین پیامِ
   مشتری» هر گفتگو با دفعهٔ قبل (localStorage) مقایسه می‌شود. اولین
   بار بی‌صدا seed می‌شود تا پیام‌های قدیمی نوتیف نکنند؛ پیام‌های تازهٔ
   زمانِ نبودِ کاربر در نوبتِ اولِ بازگشت می‌آیند. اگر کاربر خودش آن
   گفتگو را باز داشته باشد، نوتیف نمی‌آید ولی «دیده‌شده» به‌روز می‌شود
   تا بعد از بستنِ اتاق، بارِ نوتیفِ قدیمی نداند.
   ===================================================================== */
let MR_NOTIFS=[];
let MR_SEEN={};
let MR_NOTIF_BOOTED=false;
const MR_NOTIF_TTL=30000;
/* v10.66 (۸۰): تنظیماتِ اعلانِ زنده — درِ localStorage، اثرِ آنی، بدونِ دکمهٔ ذخیره */
function mrLiveCfg(){
  try{
    return {
      on: localStorage.getItem('mr_live_cards')!=='0',
      sys: (localStorage.getItem('mr_sys_notif')==='1' && typeof Notification!=='undefined' && Notification.permission==='granted'),
      poll: Math.max(3, parseInt(localStorage.getItem('mr_live_poll')||'5',10)||5),
      ttl: Math.max(5, parseInt(localStorage.getItem('mr_live_ttl')||'30',10)||30),
      sound: localStorage.getItem('mr_live_sound')!=='0'
    };
  }catch(e){ return {on:true,sys:false,poll:5,ttl:30,sound:true}; }
}
function mrNotifTtlMs(){ return mrLiveCfg().ttl*1000; }
function mrNotifLoad(){try{return JSON.parse(localStorage.getItem('mr_notif_seen')||'{}')||{};}catch(e){return{};}}
function mrNotifSave(){try{localStorage.setItem('mr_notif_seen',JSON.stringify(MR_SEEN));}catch(e){}}
function mrNotifDing(){
  try{
    if(mrLiveCfg().sound===false)return; /* v10.66 (۸۰): صدایِ خاموش */
    const AC=window.AudioContext||window.webkitAudioContext; if(!AC)return;
    const C=new AC(); const t=C.currentTime;
    const o=C.createOscillator(),g=C.createGain();
    o.type='sine';
    o.frequency.setValueAtTime(740,t);
    o.frequency.exponentialRampToValueAtTime(1180,t+0.08);
    g.gain.setValueAtTime(0.0001,t);
    g.gain.exponentialRampToValueAtTime(0.10,t+0.02);
    g.gain.exponentialRampToValueAtTime(0.0001,t+0.45);
    o.connect(g);g.connect(C.destination);o.start(t);o.stop(t+0.5);
    setTimeout(()=>{try{C.close();}catch(e){}},800);
  }catch(e){}
}
function mrNotifLabel(t){
  return ({picture:'🖼 تصویر',gallery:'🖼 تصاویر',voice:'🎤 پیامِ صوتی',video:'🎬 ویدیو',
    location:'📍 موقعیت',sticker:'😀 استیکر',file:'📄 فایل',voice_call_phone:'📞 تماس',
    agreement:'📝 توافق‌نامه'})[t]||null;
}
function mrNotifText(c){
  const t=String(c.text||'').trim();
  if(!t)return'—';
  const m=t.match(/^\[([a-z_]+)\]$/);
  if(m)return mrNotifLabel(m[1])||t;
  return t;
}
function mrNotifHost(){
  let h=$('mrNotifHost');
  if(!h){
    h=document.createElement('div');h.id='mrNotifHost';
    h.style.cssText='position:fixed;top:66px;left:14px;z-index:9500;display:flex;flex-direction:column;gap:10px;width:322px;max-width:calc(100vw - 28px)';
    document.body.appendChild(h);
  }
  return h;
}
function mrNotifInitial(who){
  const w=String(who||'م').replace(/[«»"\s]/g,'').trim();
  return w?w.slice(0,1):'م';
}
function mrNotifClose(el){
  const i=MR_NOTIFS.findIndex(x=>x.el===el); if(i<0)return;
  const n=MR_NOTIFS[i]; MR_NOTIFS.splice(i,1);
  if(n.timer)clearTimeout(n.timer);
  if(el){
    el.style.transition='transform .3s ease,opacity .3s ease';
    el.style.transform='translateX(-130%) rotate(-5deg)';
    el.style.opacity='0';
    setTimeout(()=>{el.remove();},320);
  }
}
function mrNotifReply(n){
  const i=MR_NOTIFS.findIndex(x=>x.chat_id===n.chat_id);
  if(i>=0){
    const el=MR_NOTIFS[i].el; MR_NOTIFS.splice(i,1);
    if(n.timer)clearTimeout(n.timer);
    if(el){
      el.style.transition='transform .3s ease,opacity .3s ease';
      el.style.transform='translateX(130%) rotate(5deg)';
      el.style.opacity='0';
      setTimeout(()=>{el.remove();},320);
    }
  }
  /* v10.83 (97): اگر اتاقِ چت جابه‌جا شده باشد (مودال)، ازِ مودال باز شود */
  if(typeof mrOpenModal==='function'){ mrOpenModal(); }
  else {
    const body=$('mrBody');
    const hdr=body?body.previousElementSibling:null;
    if(hdr&&!hdr.classList.contains('open'))toggleSmenu(hdr);
  }
  mrOpenChat(n.chat_id,n.shop||1);
  setTimeout(()=>{const t=$('mrText');if(t){t.focus();t.scrollIntoView({block:'nearest'});}},500);
}
/* v10.62 (۷۶): بزرگ‌نماییِ تصویر (Lightbox) — کلیک روی تصاویر */
function mrLightbox(url){
  if(!url)return;
  let ov=$('mrLightbox');
  if(!ov){
    ov=document.createElement('div');
    ov.id='mrLightbox';
    ov.style.cssText='position:fixed;inset:0;z-index:99990;background:rgba(2,6,23,.93);display:flex;align-items:center;justify-content:center;cursor:zoom-out;animation:mrZoomIn .18s ease';
    document.body.appendChild(ov);
  }
  ov.innerHTML='<img src="'+esc(url)+'" alt="تصویر" style="max-width:94%;max-height:94%;border-radius:8px;box-shadow:0 20px 60px rgba(0,0,0,.6)"/>'+
    '<div style="position:absolute;bottom:14px;left:0;right:0;text-align:center;color:#94a3b8;font-size:10px">کلیک یا Escape برای بستن</div>';
  const closeOv=()=>{ov.remove();document.removeEventListener('keydown',ov._kd);};
  ov.onclick=closeOv;
  ov._kd=e=>{if(e.key==='Escape')closeOv();};
  document.removeEventListener('keydown',ov._kd);
  document.addEventListener('keydown',ov._kd);
}
/* v10.62 (۷۶): باز کردنِ پاسخِ درِجای درونِ کارت (سوایپِ راست / دکمهٔ 💬) */
/* v10.65 (۷۹): وقتی کاربر در حال پاسخ‌دهی است، کارت خودکار نبندد */
function mrNotifHold(card,n){
  if(n){if(n.timer){clearTimeout(n.timer);n.timer=null;}n.hold=true;}
  const bar=card.querySelector('.mrnbar'); if(bar)bar.style.animationPlayState='paused';
  card.style.maxHeight='calc(100vh - 90px)';
}
function mrNotifOpenReply(n){
  const card=n.el;
  card.style.transform='';card.style.opacity='';
  const rep=card.querySelector('.mrnreply'); if(rep)rep.style.display='block';
  mrNotifHold(card,n);
  const ta=card.querySelector('.mrnta');
  if(ta)setTimeout(()=>{ta.focus();},90);
}
/* v10.63 (۷۷): اعلانِ سطحِ سیستم‌عامل — با متنِ کاملِ پیام و دکمهٔ پاسخ */
function mrSysOn(){
  try{
    return localStorage.getItem('mr_sys_notif')==='1'
      && typeof Notification!=='undefined'
      && Notification.permission==='granted';
  }catch(e){return false;}
}
function mrSysIcon(){
  try{
    if(window._mrSysIconC)return window._mrSysIconC;
    const cv=document.createElement('canvas');cv.width=cv.height=96;
    const cx=cv.getContext('2d');
    cx.fillStyle='#1d4ed8';
    if(cx.roundRect){cx.beginPath();cx.roundRect(2,2,92,92,22);cx.fill();}
    else{cx.fillRect(0,0,96,96);}
    cx.font='50px serif';cx.textAlign='center';cx.textBaseline='middle';
    cx.fillText('\u{1F4AC}',48,50);
    window._mrSysIconC=cv.toDataURL('image/png');
    return window._mrSysIconC;
  }catch(e){return'';}
}
function mrSysNotif(c){
  try{
    if(!mrSysOn())return;
    const who=String(c.who||'مشتری');
    const shopNm=String(c.shop_name||('غرفهٔ '+toFa(c.shop||1)));
    let body=String(mrNotifText(c));
    if(body==='—')body='(بدونِ متن)';
    if(body.length>500)body=body.slice(0,500)+'…';
    const ic=mrSysIcon();
    const nt=new Notification('💬 '+who+' — '+shopNm,{
      body:body,
      tag:'mrchat_'+(c.shop||1)+'_'+c.chat_id,
      requireInteraction:true,
      icon:ic||undefined,
      badge:ic||undefined,
      actions:[{action:'mr-reply',title:'💬 پاسخ'}]
    });
    const act=ev=>{
      try{ev.preventDefault();}catch(err){}
      try{window.focus();}catch(err){}
      try{nt.close();}catch(err){}
      const isReply=!!(ev&&ev.action==='mr-reply');
      const f=MR_NOTIFS.find(x=>x.chat_id===c.chat_id&&(x.shop||1)===(c.shop||1));
      if(f&&isReply){
        /* پاسخِ درِجایِ روی همان کارتِ نوتیف */
        mrNotifOpenReply(f);
        return;
      }
      /* کلیکِ عادی یا پاسخِ بدونِ کارتِ موجود — گفتگو باز شود و فوکوس */
      mrOpenChat(c.chat_id,c.shop||1);
      setTimeout(()=>{const t=$('mrText');if(t){t.focus();t.scrollIntoView({block:'nearest'});}},500);
    };
    nt.onclick=act;
  }catch(e){}
}
function mrNotifPush(c){
