/* v8.70: بررسی امنیت نصب — آیا فایل‌های داده از وب خوانده می‌شوند؟ */
function secCheck(){
  const box=$('genR')||$('watchdogR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ بررسی دسترسی به فایل‌های داده...</div>';
  fetch('?sec_check=1').then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#fca5a5;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    const bad=(d.exposed||0)>0;
    let h='<div style="background:#0f172a;border:1px solid '+(bad?'#ef4444':'#22c55e')
      +';border-radius:8px;padding:9px;font-size:11px;line-height:1.9">';
    h+='<div style="color:'+(bad?'#fca5a5':'#4ade80')+';font-weight:700">'
      +(bad?('🔴 '+toFa(d.exposed)+' فایل داده از اینترنت قابل خواندن است'):'🟢 فایل‌های داده محافظت شده‌اند')+'</div>';
    (d.checks||[]).forEach(c=>{
      const ico=c.state==='open'?'🔴':(c.state==='protected'?'🟢':'⚪');
      const txt=c.state==='open'?'قابل خواندن از وب!':(c.state==='protected'?'محافظت‌شده':'وجود ندارد');
      h+='<div style="color:'+(c.state==='open'?'#fca5a5':'#94a3b8')+'">'+ico+' '+esc(c.file)+' — '+txt+'</div>';
    });
    h+='<div style="color:#94a3b8;margin-top:5px">'+esc(d.advice||'')+'</div>';
    if(bad){
      h+='<div style="color:#fbbf24;font-size:10.5px;margin-top:5px;line-height:1.8">'
        +'⚠️ <b>connections.json</b> شامل توکن باسلام و کلید ووکامرس شماست. '
        +'فایل <code>htaccess-sample.txt</code> را از مخزن بردارید، نامش را به <code>.htaccess</code> '
        +'تغییر دهید و کنار همین فایل آپلود کنید.</div>';
    }
    h+='<div style="color:#475569;font-size:10px;margin-top:4px">htaccess موجود: '+(d.htaccess?'بله':'خیر')+'</div>';
    h+='</div>';
    box.innerHTML=h;
  }).catch(e=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ '+esc(e.message)+'</div>';});
}

function genQueueStatus(){
  const box=$('genR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ ...</div>';
  fetch('?queues_overview=1').then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا</div>';return;}
    const nm={extract:'استخراج',bsl:'باسلام',woo:'ووکامرس'};
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px">';
    ['extract','bsl','woo'].forEach(k=>{
      const q=d.queues[k]||{};
      h+='<div style="border-top:1px solid #1e293b;padding:4px 0">'
        +'<b style="color:#e2e8f0">'+nm[k]+'</b> '
        +'<span style="color:#94a3b8">فعال: '+toFa(q.active||0)+' · کل: '+toFa(q.total||0)+'</span>';
      (q.profiles||[]).forEach(p=>{
        h+='<div style="color:#cbd5e1;padding-right:10px">• '+esc(p.name||p.key||'—')
          +' <span style="color:#64748b">('+esc(p.status)+')</span></div>';
      });
      h+='</div>';
    });
    h+='</div>';
    box.innerHTML=h;
  }).catch(()=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا</div>';});
}

/* v8.48: رابط حافظهٔ یادگیری دسته‌بندی */
/* ============ v8.62: ویرایشگر محصولات مقصد ============ */
let edTarget='woo', edPage=1, edRows=[], edSel=new Set(), edTimer=null;

function editorOpen(target){
  edTarget=target; edPage=1; edSel=new Set(); edRows=[];
  let m=document.getElementById('edModal');
  if(!m){
    m=document.createElement('div');
    m.id='edModal';
    m.className='bsl-modal-overlay';
    m.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.72);z-index:100000;display:flex;align-items:center;justify-content:center;padding:12px';
    m.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:12px;width:min(1000px,96vw);max-height:92vh;display:flex;flex-direction:column;overflow:hidden">'
      +'<div style="padding:12px 16px;background:#1e293b;border-bottom:1px solid #334155;display:flex;justify-content:space-between;align-items:center">'
      +'<h2 id="edTitle" style="margin:0;font-size:15px;color:#e2e8f0">✏️ ویرایش محصولات</h2>'
      +'<button class="btn btn-gray" onclick="editorClose()" style="padding:4px 10px">✕</button></div>'
      +'<div id="edBody" style="padding:12px 16px;overflow-y:auto;flex:1"></div></div>';
    document.body.appendChild(m);
  }
  m.style.display='flex';
  $('edTitle').textContent=target==='woo'?'✏️ ویرایش محصولات ووکامرس':'✏️ ویرایش محصولات باسلام';
  editorRender();
  editorLoad();
}
function editorClose(){
  const m=document.getElementById('edModal');if(m)m.style.display='none';
  if(edTimer){clearInterval(edTimer);edTimer=null;}
}
function editorRender(){
  const b=$('edBody');if(!b)return;
  const isBsl=edTarget==='bsl';
  b.innerHTML=
   '<div class="row" style="align-items:center;gap:6px">'
   +'<input type="text" id="edQ" placeholder="جستجوی عنوان..." style="flex:1" onkeydown="if(event.key===\'Enter\'){edPage=1;editorLoad();}">'
   +'<button class="btn btn-blue" onclick="edPage=1;editorLoad()">🔍 جستجو</button>'
   +'<button class="btn btn-gray" onclick="editorPage(-1)">‹</button>'
   +'<span id="edPageN" style="color:#94a3b8;font-size:12px">۱</span>'
   +'<button class="btn btn-gray" onclick="editorPage(1)">›</button></div>'
   +'<div id="edList" style="max-height:38vh;overflow-y:auto;border:1px solid #334155;border-radius:8px;padding:6px;background:#111c31;margin-bottom:10px">در حال بارگذاری...</div>'
   +'<div style="display:flex;gap:8px;align-items:center;margin-bottom:8px;flex-wrap:wrap">'
   +'<button class="btn btn-gray" onclick="editorSelAll(1)" style="font-size:11px;padding:4px 10px">انتخاب همه</button>'
   +'<button class="btn btn-gray" onclick="editorSelAll(0)" style="font-size:11px;padding:4px 10px">لغو انتخاب</button>'
   +'<span id="edSelN" style="color:#67e8f9;font-size:12px;font-weight:700">۰ انتخاب‌شده</span></div>'
   +'<div style="border-top:1px solid #334155;padding-top:10px">'
   +'<div style="color:#fbbf24;font-weight:700;font-size:12px;margin-bottom:8px">تغییرات روی انتخاب‌شده‌ها</div>'
   +'<div class="row" style="align-items:center"><label style="min-width:70px">💰 قیمت:</label>'
   +'<select id="edPriceOp" style="flex:0;min-width:130px"><option value="">بدون تغییر</option>'
   +'<option value="set">مقدار ثابت</option><option value="inc">افزایش</option><option value="dec">کاهش</option></select>'
   +'<input type="text" id="edPriceVal" placeholder="مثلاً 10% یا 5000" dir="ltr" style="flex:1"></div>'
   +'<div class="row" style="align-items:center"><label style="min-width:70px">📦 موجودی:</label>'
   +'<input type="number" id="edStock" placeholder="خالی = بدون تغییر" dir="ltr" style="flex:1"></div>'
   +'<div class="row" style="align-items:center"><label style="min-width:70px">🏷 وضعیت:</label>'
   +'<select id="edStatus" style="flex:1"><option value="">بدون تغییر</option>'
   +(isBsl
      ?'<option value="2976">فعال</option><option value="3790">غیرفعال</option><option value="4184">بایگانی</option>'
      :'<option value="publish">منتشر</option><option value="draft">پیش‌نویس</option><option value="private">خصوصی</option>')
   +'</select></div>'
   +'<div class="row" style="align-items:center"><label style="min-width:70px">📝 توضیح کوتاه:</label>'
   +'<input type="text" id="edShort" placeholder="خالی = بدون تغییر" style="flex:1"></div>'
   +'<div class="row" style="align-items:flex-start"><label style="min-width:70px">📄 توضیحات:</label>'
   +'<textarea id="edDesc" placeholder="خالی = بدون تغییر" style="flex:1;height:60px"></textarea></div>'
   +'<div class="row" style="align-items:center"><label style="min-width:70px">🔤 عنوان:</label>'
   +'<input type="text" id="edPrefix" placeholder="پیشوند" style="flex:1">'
   +'<input type="text" id="edSuffix" placeholder="پسوند" style="flex:1"></div>'
   +'<div style="border-top:1px solid #7f1d1d;margin-top:8px;padding-top:8px">'
   +'<label style="display:flex;align-items:center;gap:6px;font-size:12px;color:#fca5a5;cursor:pointer">'
   +'<input type="checkbox" id="edDelete" onchange="editorDelToggle()" style="width:16px;height:16px">'
   +(isBsl?'🗄 بایگانی کردن (باسلام حذف همیشگی ندارد)':'🗑 حذف محصولات')+'</label>'
   +(isBsl?'':'<label id="edForceWrap" style="display:none;align-items:center;gap:6px;font-size:11px;color:#f87171;margin-top:4px;cursor:pointer">'
      +'<input type="checkbox" id="edForce" style="width:14px;height:14px"> حذف همیشگی (برگشت‌ناپذیر)</label>')
   +'</div>'
   +'<label style="display:flex;align-items:center;gap:6px;font-size:11px;color:#cbd5e1;margin-top:8px;cursor:pointer">'
   +'<input type="checkbox" id="edNotify" style="width:14px;height:14px"> ارسال گزارش به پیام‌رسان</label>'
   +'<div class="cact" style="margin-top:10px">'
   +'<button class="btn btn-gray" onclick="editorRun(1)" style="flex:1">👁 پیش‌نمایش</button>'
   +'<button class="btn btn-green" onclick="editorRun(0)" style="flex:1">✓ اعمال</button></div>'
   +'<div id="edResult" style="margin-top:10px"></div></div>';
}
function editorDelToggle(){
  const w=$('edForceWrap');
  if(w)w.style.display=($('edDelete')&&$('edDelete').checked)?'flex':'none';
}
function editorPage(d){
  const n=edPage+d; if(n<1)return; edPage=n; editorLoad();
}
function editorLoad(){
  const l=$('edList');if(!l)return;
  l.innerHTML='در حال بارگذاری...';
  const q=new URLSearchParams({dest_list:'1',target:edTarget,page:String(edPage)});
  const s=($('edQ')||{}).value||''; if(s.trim())q.set('q',s.trim());
  fetch('?'+q.toString()).then(r=>r.json()).then(d=>{
    if(!d.ok){l.innerHTML='<div style="color:#fca5a5">✗ '+esc(d.error||'خطا')+'</div>';return;}
    edRows=d.products||[];
    if($('edPageN'))$('edPageN').textContent=toFa(edPage);
    if(!edRows.length){l.innerHTML='<div style="color:#64748b">محصولی نیست</div>';return;}
    let h='';
    edRows.forEach(p=>{
      const on=edSel.has(p.id);
      h+='<label style="display:flex;align-items:center;gap:8px;padding:5px 6px;border-bottom:1px solid #1e293b;cursor:pointer;font-size:11.5px">'
        +'<input type="checkbox" '+(on?'checked':'')+' onchange="editorPick('+p.id+',this.checked)" style="width:15px;height:15px">'
        +'<span style="flex:1;color:#e2e8f0">'+esc(p.title||'')+'</span>'
        +'<span style="color:#fbbf24;font-family:ui-monospace,monospace">'+toFa(Number(p.price||0).toLocaleString('en-US'))+'</span>'
        +'<span style="color:#94a3b8;min-width:46px;text-align:center">'+(p.stock===null||p.stock===undefined?'—':toFa(p.stock))+'</span>'
        +'<span style="color:#64748b;min-width:60px">'+esc(String(p.status||''))+'</span>'
        +(p.has_image?'':'<span title="بدون تصویر">🖼️❌</span>')
        +'</label>';
    });
    l.innerHTML=h;
    editorCount();
  }).catch(()=>{l.innerHTML='<div style="color:#fca5a5">✗ خطا شبکه</div>';});
}
function editorPick(id,on){ if(on)edSel.add(id); else edSel.delete(id); editorCount(); }
function editorSelAll(on){
  edRows.forEach(p=>{ if(on)edSel.add(p.id); else edSel.delete(p.id); });
  editorLoad();
}
function editorCount(){ if($('edSelN'))$('edSelN').textContent=toFa(edSel.size)+' انتخاب‌شده'; }
function editorRun(dry){
  if(edSel.size===0){showToast('محصولی انتخاب نشده',1);return;}
  const ops={};
  const po=($('edPriceOp')||{}).value||'';
  const pv=(($('edPriceVal')||{}).value||'').trim();
  if(po&&pv)ops.price={op:po,val:pv};
  const st=(($('edStock')||{}).value||'').trim();
  if(st!=='')ops.stock=parseInt(st)||0;
  const su=($('edStatus')||{}).value||''; if(su)ops.status=su;
  const sd=(($('edShort')||{}).value||'').trim(); if(sd)ops.short_desc=sd;
  const dd=(($('edDesc')||{}).value||'').trim(); if(dd)ops.desc=dd;
  const pf=(($('edPrefix')||{}).value||'').trim(); if(pf)ops.title_prefix=pf+' ';
  const sf=(($('edSuffix')||{}).value||'').trim(); if(sf)ops.title_suffix=' '+sf;
  const del=$('edDelete')&&$('edDelete').checked;
  if(del){ops.delete=true; if($('edForce')&&$('edForce').checked)ops.force=true;}
  if(!del&&Object.keys(ops).length===0){showToast('هیچ تغییری تعیین نشده',1);return;}
  if(!dry){
    const what=del?(edTarget==='bsl'?'بایگانی':'حذف'):'ویرایش';
    if(!confirm(what+' '+edSel.size+' محصول؟ این کار روی مقصد اعمال می‌شود.'))return;
  }
  const fd=new FormData();
  fd.append('target',edTarget);
  fd.append('ids',JSON.stringify(Array.from(edSel)));
  fd.append('ops',JSON.stringify(ops));
  if(dry)fd.append('dry','1');
  if(!dry&&$('edNotify')&&$('edNotify').checked)fd.append('notify','1');
  $('edResult').innerHTML='<div class="alert alert-info" style="padding:8px;font-size:11px">در حال اجرا...</div>';
  fetch('?bulk_edit=1',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    if(!d.ok){$('edResult').innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    if(edTimer)clearInterval(edTimer);
    edTimer=setInterval(editorPoll,1500);
    editorPoll();
  }).catch(()=>{$('edResult').innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا شبکه</div>';});
}
function editorPoll(){
  fetch('?bulk_status=1').then(r=>r.json()).then(d=>{
    const st=d.status||{},box=$('edResult');if(!box)return;
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px;font-size:11px;line-height:1.9">';
    h+='<div style="color:#67e8f9;font-weight:700">'+(st.running?'⏳ در حال اجرا':'✅ پایان')+(st.dry?' (پیش‌نمایش)':'')+'</div>';
    h+='<div>'+toFa(st.current||0)+'/'+toFa(st.total||0)
      +' · ویرایش: <b style="color:#4ade80">'+toFa(st.changed||0)+'</b>'
      +' · حذف/بایگانی: <b style="color:#fb923c">'+toFa(st.deleted||0)+'</b>'
      +' · بدون تغییر: '+toFa(st.skipped||0)
      +(st.failed?' · خطا: <b style="color:#f87171">'+toFa(st.failed)+'</b>':'')+'</div>';
    (st.log||[]).slice(-4).forEach(l=>{h+='<div style="color:#94a3b8;font-size:10px">'+esc(l.m||'')+'</div>';});
    h+='</div>';
    box.innerHTML=h;
    if(!st.running){
      if(edTimer){clearInterval(edTimer);edTimer=null;}
      fetch('?bulk_result=1').then(r=>r.json()).then(rr=>{
        const res=rr.result;if(!res||!res.items)return;
        let t='<div style="margin-top:6px;max-height:220px;overflow-y:auto;border:1px solid #334155;border-radius:8px;padding:6px;background:#111c31">';
        res.items.slice(0,120).forEach(i=>{
          const bad=i.error?'#fca5a5':'#cbd5e1';
          t+='<div style="font-size:10.5px;color:'+bad+'">• #'+i.id+' '+esc(i.title||'')
            +(i.new_price!==undefined?(' — '+toFa(Number(i.old_price).toLocaleString('en-US'))+'→'+toFa(Number(i.new_price).toLocaleString('en-US'))+' ('+(i.pct>=0?'+':'')+i.pct+'٪)'):'')
            +(i.action?(' — '+esc(i.action)):'')+(i.error?(' — '+esc(i.error)):'')+'</div>';
        });
        t+='</div>';
        box.innerHTML+=t;
        if(!res.dry)editorLoad();
      }).catch(()=>{});
    }
  }).catch(()=>{});
}

/* ============ v8.62: پشتیبان‌گیری آموخته‌ها ============ */
function catLearnExport(){
  const r=$('catLearnR');
  r.innerHTML='<div class="alert alert-info" style="padding:8px;font-size:11px">در حال آماده‌سازی...</div>';
  fetch('?catlearn=1&export=1').then(x=>x.json()).then(d=>{
    if(!d.ok){r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    const txt=JSON.stringify(d.data);
    r.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px">'
      +'<div style="color:#67e8f9;font-weight:700;font-size:11px;margin-bottom:6px">💾 پشتیبان '+toFa(d.count)+' کلمه</div>'
      +'<textarea id="catLearnBak" readonly style="width:100%;height:120px;font-family:ui-monospace,monospace;font-size:10px;direction:ltr;text-align:left;background:#111c31;color:#e2e8f0;border:1px solid #334155;border-radius:6px;padding:8px"></textarea>'
      +'<div style="font-size:10px;color:#64748b;margin-top:6px">این متن را جایی نگه دارید. بعد از نصب با نام جدید، با «⬆️ بازیابی» برگردانید.</div>'
      +'<button class="btn btn-cyan" style="margin-top:6px;font-size:11px;padding:5px 10px" onclick="catLearnCopyBak()">📋 کپی</button></div>';
    $('catLearnBak').value=txt;
  }).catch(()=>{r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا شبکه</div>';});
}
function catLearnCopyBak(){
  const t=$('catLearnBak');if(!t)return;t.select();
  try{document.execCommand('copy');showToast('✓ کپی شد');}
  catch(e){if(navigator.clipboard){navigator.clipboard.writeText(t.value);showToast('✓ کپی شد');}}
}
function catLearnImportPrompt(){
  const r=$('catLearnR');
  r.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px">'
    +'<div style="color:#4ade80;font-weight:700;font-size:11px;margin-bottom:6px">⬆️ بازیابی آموخته‌ها</div>'
    +'<textarea id="catLearnIn" placeholder=\'{"کفش":{...}}\' style="width:100%;height:110px;font-family:ui-monospace,monospace;font-size:10px;direction:ltr;text-align:left;background:#111c31;color:#e2e8f0;border:1px solid #334155;border-radius:6px;padding:8px"></textarea>'
    +'<label style="display:flex;align-items:center;gap:6px;font-size:11px;color:#cbd5e1;margin:6px 0;cursor:pointer">'
    +'<input type="checkbox" id="catLearnReplace" style="width:14px;height:14px"> جایگزینی کامل (به‌جای ادغام)</label>'
    +'<button class="btn btn-green" style="font-size:11px;padding:5px 10px" onclick="catLearnImport()">✓ بازیابی</button></div>';
}
function catLearnImport(){
  const t=$('catLearnIn');if(!t||!t.value.trim()){showToast('چیزی وارد نشده',1);return;}
  let parsed;try{parsed=JSON.parse(t.value.trim());}catch(e){showToast('JSON نامعتبر',1);return;}
  const fd=new FormData();
  fd.append('action','catlearn_import');
  fd.append('data',JSON.stringify(parsed));
  if($('catLearnReplace')&&$('catLearnReplace').checked)fd.append('replace','1');
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    if(d.ok){showToast('✓ '+toFa(d.added)+' تازه، '+toFa(d.merged)+' ادغام — کل '+toFa(d.total));catLearnShow();}
    else showToast('خطا: '+(d.error||''),1);
  }).catch(()=>showToast('خطا شبکه',1));
}

/* ============ v8.62: عکس‌دار کردن محصولات ووکامرس ============ */
let photoTimer=null;
function photoRun(dry){
  const r=$('photoR');
  const q=new URLSearchParams({photo_fix:'1'});
  if(dry)q.set('dry','1');
  const pf=($('photoProfile')||{}).value||'';
  if(pf)q.set('profile',pf);
  if(!dry&&$('photoNotify')&&$('photoNotify').checked)q.set('notify','1');
  if(!dry&&!confirm('تصویر محصولات بی‌عکس ووکامرس از روی پروفایل‌ها تکمیل شود؟'))return;
  r.innerHTML='<div class="alert alert-info" style="padding:8px;font-size:11px">🖼 شروع شد — پیشرفت زنده...</div>';
  fetch('?'+q.toString()).then(x=>x.json()).then(d=>{
    if(!d.ok){r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    if(photoTimer)clearInterval(photoTimer);
    photoTimer=setInterval(photoPoll,2000);
    photoPoll();
  }).catch(()=>{r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا شبکه</div>';});
}
function photoPoll(){
  fetch('?photo_status=1').then(x=>x.json()).then(d=>{
    const st=d.status||{},res=d.result||null,r=$('photoR');
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px;font-size:11px;line-height:1.9">';
    h+='<div style="color:#67e8f9;font-weight:700">🖼 '+(st.running?'در حال اجرا...':'پایان')+(st.dry?' (پیش‌نمایش)':'')+'</div>';
    h+='<div>بررسی‌شده: <b>'+toFa(st.scanned||0)+'</b> · بی‌تصویر: <b style="color:#fbbf24">'+toFa(st.missing||0)+'</b>'
      +' · عکس‌دار شد: <b style="color:#4ade80">'+toFa(st.fixed||0)+'</b>'
      +(st.unmatched?' · بی‌تطبیق: <b style="color:#94a3b8">'+toFa(st.unmatched)+'</b>':'')
      +(st.failed?' · خطا: <b style="color:#f87171">'+toFa(st.failed)+'</b>':'')+'</div>';
    (st.log||[]).slice(-6).forEach(l=>{h+='<div style="color:#94a3b8;font-size:10px">'+esc(l.m||'')+'</div>';});
    if(res&&res.items&&res.items.length){
      h+='<div style="margin-top:6px;max-height:200px;overflow-y:auto;border-top:1px solid #334155;padding-top:6px">';
      res.items.slice(0,60).forEach(i=>{h+='<div style="font-size:10px;color:#cbd5e1">• '+esc(i.title||'')+' — <span style="color:#94a3b8">'+esc(i.status||'')+'</span></div>';});
      h+='</div>';
    }
    h+='</div>';
    r.innerHTML=h;
    if($('photoS')){$('photoS').textContent=st.running?'در حال اجرا':(st.fixed?toFa(st.fixed)+' عکس‌دار':'—');
      $('photoS').className='cst '+(st.running?'tg':(st.fixed?'on':'off'));}
    if(!st.running&&photoTimer){clearInterval(photoTimer);photoTimer=null;}
  }).catch(()=>{});
}

/* ============ v8.62: گزارش شبانه ============ */
function updateDigestBadge(){
  const el=$('digestS'),en=$('digestEnabled'),h=$('digestHour');
  if(!el||!en)return;
  el.textContent=en.checked?('ساعت '+toFa((h&&h.value)||23)):'خاموش';
  el.className='cst '+(en.checked?'on':'off');
}
function digestPreview(){
  const r=$('digestR');
  r.innerHTML='<div class="alert alert-info" style="padding:8px;font-size:11px">در حال ساخت گزارش...</div>';
  fetch('?digest=1').then(x=>x.json()).then(d=>{
    if(!d.ok){r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا</div>';return;}
    r.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px">'
      +'<div style="color:#67e8f9;font-weight:700;font-size:11px;margin-bottom:6px">👁 پیش‌نمایش گزارش</div>'
      +'<pre style="white-space:pre-wrap;font-size:10.5px;color:#e2e8f0;max-height:320px;overflow-y:auto;margin:0">'+esc(d.message||'')+'</pre>'
      +(d.state&&d.state.last_date?'<div style="font-size:10px;color:#64748b;margin-top:6px">آخرین ارسال: '+esc(d.state.last_date)+'</div>':'')
      +'</div>';
  }).catch(()=>{r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا شبکه</div>';});
}
function digestSendNow(){
  if(!confirm('گزارش همین حالا به پیام‌رسان‌ها فرستاده شود؟'))return;
  const r=$('digestR');
  r.innerHTML='<div class="alert alert-info" style="padding:8px;font-size:11px">در حال ارسال...</div>';
  fetch('?digest=1&send=1').then(x=>x.json()).then(d=>{
    if(d.sent){r.innerHTML='<div class="alert alert-success" style="padding:8px;font-size:11px">✓ گزارش فرستاده شد</div>';showToast('✓ ارسال شد');}
    else r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'ارسال نشد')+'</div>';
  }).catch(()=>{r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطا شبکه</div>';});
}

function catLearnShow(){
  const box=$('catLearnR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ ...</div>';
  fetch('?catlearn=1').then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا</div>';return;}
    if(!d.count){box.innerHTML='<div style="color:#64748b;font-size:11px">هنوز چیزی آموخته نشده — '
      +'یک دسته را دستی اصلاح کنید.</div>';return;}
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px">';
    h+='<div style="display:flex;align-items:center;margin-bottom:5px">'
      +'<span style="color:#93c5fd">🧠 '+toFa(d.count)+' کلمه آموخته شده</span>'
      +'<span style="flex:1"></span>'
      +'<button class="btn btn-red" onclick="catLearnClear()" style="font-size:10px;padding:3px 8px">پاک کردن همه</button></div>';
    d.rows.slice(0,40).forEach(r=>{
      h+='<div style="display:flex;gap:6px;align-items:center;border-top:1px solid #1e293b;padding:3px 0">'
        +'<b style="color:#e2e8f0;min-width:70px">'+esc(r.word)+'</b>'
        +'<span style="color:#94a3b8;flex:1">→ '+esc(r.cat_name||('#'+r.cat_id))+'</span>'
        +'<span style="color:#64748b;font-size:10px">'+toFa(r.times)+'×</span>'
        +(r.variants>1?'<span style="color:#fbbf24;font-size:10px" title="چند دستهٔ مختلف">⚠'+toFa(r.variants)+'</span>':'')
        +'<button class="btn btn-gray" onclick="catLearnForget(\''+encodeURIComponent(r.word)+'\')" '
        +'style="font-size:9px;padding:2px 6px">✕</button></div>';
    });
    if(d.count>40)h+='<div style="color:#64748b;padding-top:4px">… و '+toFa(d.count-40)+' مورد دیگر</div>';
    box.innerHTML=h+'</div>';
  }).catch(()=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا</div>';});
}
function catLearnForget(w){
  fetch('?catlearn=1&forget='+w).then(r=>r.json()).then(()=>{showToast('فراموش شد');catLearnShow();});
}
function catLearnClear(){
  if(!confirm('همهٔ آموخته‌ها پاک شوند؟'))return;
  fetch('?catlearn=1&clear=1').then(r=>r.json()).then(()=>{showToast('پاک شد');catLearnShow();});
}
function catLearnTest(){
  const t=prompt('عنوان محصول را بنویسید:');
  if(!t)return;
  const box=$('catLearnR');
  fetch('?catlearn=1&test='+encodeURIComponent(t)).then(r=>r.json()).then(d=>{
    if(!box)return;
    box.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px">'
      +'<div style="color:#cbd5e1">عنوان: '+esc(d.title||'')+'</div>'
      +'<div style="color:#93c5fd">کلمهٔ اول: <b>'+esc(d.first_word||'—')+'</b></div>'
      +'<div style="color:'+(d.learned_cat?'#4ade80':'#64748b')+'">'
      +(d.learned_cat?('✓ دستهٔ آموخته‌شده: #'+d.learned_cat):'— هنوز برای این کلمه چیزی آموخته نشده')
      +'</div></div>';
  }).catch(()=>{});
}

/** v8.36: نشانگر کنار عنوان بخش «محصولات رفته از مبدأ» */
function updateRetireBadge(){
  const el=$('retireS'),sel=$('retireMode');
  if(!el||!sel)return;
  const lbl={off:'خاموش',draft:'پیش‌نویس',outofstock:'ناموجود',delete:'حذف'}[sel.value]||'خاموش';
  /* v10.34 (۴۸الف): تیکِ «افزودن/آپدیت» خودش بازنشستگی را روشن می‌کند، پس
     نشانگر نباید «خاموش» بگوید در حالی که هر شب چیزی حذف/بایگانی می‌شود. */
  const auOn=(($('profileSyncWooAddUpdate')&&$('profileSyncWooAddUpdate').checked)
           ||($('profileSyncBslAddUpdate')&&$('profileSyncBslAddUpdate').checked));
  if(sel.value==='off'&&auOn){
    const wl={delete:'حذف',delete_force:'حذف همیشگی',draft:'پیش‌نویس',outofstock:'ناموجود'}
             [$('retireWooAction')?$('retireWooAction').value:'delete']||'حذف';
    const bl={delete:'بایگانی',draft:'غیرفعال',outofstock:'ناموجود'}
             [$('retireBslAction')?$('retireBslAction').value:'delete']||'بایگانی';
    el.textContent='➕🔄 '+wl+'/'+bl;
    el.className='cst on';
    return;
  }
  el.textContent=lbl;
  el.className='cst '+(sel.value==='off'?'off':'on');
}

/** v8.36: نشانگر کنار عنوان بخش «نگهبان صف» */
function updateStallBadge(){
  const el=$('stallS'),cb=$('stallWatchdog');
  if(!el||!cb)return;
  el.textContent=cb.checked?'فعال':'خاموش';
  el.className='cst '+(cb.checked?'on':'off');
}

/**
 * v8.34: پیش‌نمایش بازنشستگی — هیچ تغییری اعمال نمی‌کند، فقط نشان می‌دهد
 * چه محصولاتی روی مقصد پیدا می‌شوند و چه بلایی سرشان می‌آید.
 */
function retirePreview(){
  const box=$('retireR');
  /* v10.38 (۵۱الف): مقدارِ کشویی URL است؛ سرور کلیدِ پروفایل می‌خواهد.
     تبدیل نکردن همان باگی بود که همیشه «پروفایل نامعتبر» می‌داد. */
  const _pv=$('profileSelect')?$('profileSelect').value:'';
  const key=_pv&&_pv.indexOf('://')>=0?(profileKey(_pv)||_pv):_pv;
  if(!key){if(box)box.innerHTML='<div style="color:#fca5a5;font-size:11px">اول یک پروفایل انتخاب کنید</div>';return;}
  const mode=$('retireMode')?$('retireMode').value:'draft';
  if(mode==='off'){if(box)box.innerHTML='<div style="color:#94a3b8;font-size:11px">اقدام روی «کاری نکن» است</div>';return;}
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ در حال بررسی...</div>';
  fetch('?retire_run=1&dry=1&profile='+encodeURIComponent(key)+'&mode='+encodeURIComponent(mode))
   .then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#f87171;font-size:11px;background:#7f1d1d20;padding:6px 8px;border-radius:6px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    if(d.skipped){
      const blocked=d.guard&&d.guard.blocked;
      box.innerHTML='<div style="color:'+(blocked?'#fca5a5':'#94a3b8')+';font-size:11px;background:'+(blocked?'#7f1d1d20':'#0f172a')+';padding:6px 8px;border-radius:6px">'
        +(blocked?'🛑 ':'ℹ️ ')+esc(d.skipped)+'</div>';return;
    }
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px">';
    h+='<div style="color:#fbbf24;margin-bottom:4px">پیش‌نمایش — هیچ تغییری اعمال نشد</div>';
    h+='<div style="color:#94a3b8">بررسی‌شده: '+toFa(d.checked||0)+' · یافت‌نشده: '+toFa(d.not_found||0)
      +(d.not_owned?(' · <span style="color:#fbbf24">مالِ پروفایلِ دیگر: '+toFa(d.not_owned)+'</span>'):'')
      +'</div>';
    (d.items||[]).slice(0,12).forEach(it=>{
      h+='<div style="border-top:1px solid #1e293b;padding:3px 0;color:#cbd5e1">• '+esc(it.title||'')
        +' <span style="color:#64748b">'+esc(it.reason||'')+'</span>'
        +(it.woo?' <span style="color:#67e8f9">woo: '+esc(it.woo)+'</span>':'')
        +(it.bsl?' <span style="color:#c4b5fd">bsl: '+esc(it.bsl)+'</span>':'')+'</div>';
    });
    /* v10.35 (۴۷ج): اجرای واقعی از همین‌جا، با تأییدِ همین فهرست.
       تا حالا کاربر پیش‌نمایش می‌گرفت و بعد راهی نداشت جز اینکه منتظرِ
       اجرای خودکارِ بعدی بماند — یعنی «پیش‌نمایش» عملاً به هیچ عملی
       وصل نبود. توکن یک‌بارمصرف است و به همین فهرست گره خورده. */
    if(d.confirm_token&&d.ready>0){
      h+='<div style="margin-top:8px;padding:7px 8px;background:#7f1d1d20;border:1px solid #7f1d1d;border-radius:6px">'
        +'<div style="color:#fca5a5;margin-bottom:6px">'+toFa(d.ready)+' مورد آمادهٔ اجراست. '
        +'فقط محصولاتی که <b>خودِ همین پروفایل</b> فرستاده باشد دست می‌خورند.</div>'
        +'<button class="btn btn-red" style="font-size:11px;padding:4px 10px" '
        +'onclick="retireApply(\''+esc(d.confirm_token)+'\','+d.ready+')">✔ تأیید و اجرا</button></div>';
    }else{
      h+='<div style="margin-top:6px;color:#94a3b8">موردِ آماده‌ای برای اجرا نیست.</div>';
    }
    h+='</div>';
    box.innerHTML=h;
  }).catch(()=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا در ارتباط</div>';});
}

/* v10.35 (۴۷ج): اجرای واقعیِ بازنشستگی — فقط با توکنِ همان پیش‌نمایش */
function retireApply(token,n){
  const box=$('retireR');
  /* v10.38 (۵۱الف): مقدارِ کشویی URL است؛ سرور کلیدِ پروفایل می‌خواهد.
     تبدیل نکردن همان باگی بود که همیشه «پروفایل نامعتبر» می‌داد. */
  const _pv=$('profileSelect')?$('profileSelect').value:'';
  const key=_pv&&_pv.indexOf('://')>=0?(profileKey(_pv)||_pv):_pv;
  if(!key||!token)return;
  if(!confirm('اجرای واقعی روی '+toFa(n)+' محصول؟\n\n'
     +'اقدامی که در بالا انتخاب کرده‌اید اعمال می‌شود. '
     +'«زباله‌دان» و «پیش‌نویس» و «ناموجود» برگشت‌پذیرند؛ «حذف همیشگی» نیست.'))return;
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ در حال اجرا…</div>';
  const mode=$('retireMode')?$('retireMode').value:'draft';
  fetch('?retire_run=1&dry=0&confirm='+encodeURIComponent(token)
        +'&profile='+encodeURIComponent(key)+'&mode='+encodeURIComponent(mode))
   .then(r=>r.json()).then(d=>{
    if(!box)return;
    if(!d.ok){
      box.innerHTML='<div style="color:#f87171;font-size:11px;background:#7f1d1d20;padding:6px 8px;border-radius:6px">✗ '
        +esc(d.error||'خطا')+'</div>';
      return;
    }
    box.innerHTML='<div style="background:#064e3b30;border:1px solid #065f46;border-radius:8px;padding:8px;font-size:11px">'
      +'<div style="color:#4ade80;margin-bottom:4px">✓ اجرا شد</div>'
      +'<div style="color:#94a3b8">انجام‌شده: '+toFa(d.retired||0)
      +' · یافت‌نشده: '+toFa(d.not_found||0)
      +' · ناموفق: '+toFa(d.failed||0)
      +(d.not_owned?(' · مالِ پروفایلِ دیگر: '+toFa(d.not_owned)):'')+'</div>'
      +'<div style="color:#64748b;margin-top:4px">جزئیات در «گزارشِ بایگانی‌شده‌ها» پایین ثبت شد.</div></div>';
    try{rlLoad();}catch(e){}
  }).catch(()=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا در ارتباط</div>';});
}

/* ---------------------------------------------------------------------
 *  v10.32 (۴۵ه): گزارشِ بایگانی‌شده‌ها
 *  یک بار از سرور می‌گیریم و در rlData نگه می‌داریم؛ جست‌وجو محلی است تا
 *  با هر حرفِ تایپ‌شده یک درخواست به سرور نرود.
 * ------------------------------------------------------------------- */
let rlData=null;
function rlLoad(){
  const box=$('rlBox');
  if(box)box.innerHTML='<div style="color:#93c5fd">⏳ در حال خواندن…</div>';
  fetch('?retire_log=1&limit=300').then(r=>r.json()).then(d=>{
    if(!d.ok){if(box)box.innerHTML='<div style="color:#f87171">✗ خطا</div>';return;}
    rlData=d;
    const c=$('rlCount'); if(c)c.textContent=d.total?('('+toFa(d.total)+' مورد)'):'';
    rlRender();
  }).catch(()=>{if(box)box.innerHTML='<div style="color:#f87171">✗ خطا در ارتباط</div>';});
}
function rlRender(){
  const box=$('rlBox'); if(!box)return;
  if(!rlData){box.innerHTML='برای دیدن، «نمایش» را بزنید.';return;}
  const q=($('rlSearch')?$('rlSearch').value:'').trim().toLowerCase();
  let items=rlData.items||[];
  if(q)items=items.filter(it=>((it.title||'')+' '+(it.profile||'')).toLowerCase().indexOf(q)>=0);
  if(!items.length){
    box.innerHTML='<div style="color:#94a3b8;background:#0f172a;padding:8px;border-radius:8px">'
      +(rlData.total?'چیزی با این جست‌وجو پیدا نشد.':'هنوز چیزی بایگانی نشده است.')+'</div>';
    return;
  }
  const cl={draft:'#fbbf24',outofstock:'#67e8f9',delete:'#f87171'};
  let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px">';
  /* خلاصهٔ بالای فهرست: تفکیکِ اقدام و پرتکرارترین پروفایل‌ها */
  const bm=rlData.by_mode||{}; let sum=[];
  Object.keys(bm).forEach(k=>{sum.push('<span style="color:'+(cl[k]||'#94a3b8')+'">'
    +esc({draft:'پیش‌نویس',outofstock:'ناموجود',delete:'حذف'}[k]||k)+': '+toFa(bm[k])+'</span>');});
  if(sum.length)h+='<div style="margin-bottom:5px;font-size:10.5px">'+sum.join(' · ')+'</div>';
  const bp=rlData.by_profile||{}; const pk=Object.keys(bp);
  if(pk.length)h+='<div style="color:#64748b;font-size:10px;margin-bottom:5px">پروفایل‌ها: '
    +pk.map(k=>esc(k)+' ('+toFa(bp[k])+')').join(' · ')+'</div>';
  items.forEach(it=>{
    h+='<div style="border-top:1px solid #1e293b;padding:4px 0">'
      +'<div style="color:#cbd5e1">• '+esc(it.title||'—')+'</div>'
      +'<div style="color:#64748b;font-size:10px;padding-right:10px">'
      +'<span style="color:'+(cl[it.mode]||'#94a3b8')+'">'+esc(it.mode_label||it.mode||'')+'</span>'
      +' · '+esc(it.at_h||'—')
      +(it.profile?' · '+esc(it.profile):'')
      +(it.reason?' · '+esc(it.reason):'')
      +(it.woo?' · <span style="color:#67e8f9">woo</span>':'')
      +(it.bsl?' · <span style="color:#c4b5fd">bsl</span>':'')
      +'</div></div>';
  });
  if(rlData.total>items.length&&!q)
    h+='<div style="color:#64748b;font-size:10px;margin-top:5px">'+toFa(rlData.total-items.length)+' مورد قدیمی‌تر نمایش داده نشد.</div>';
  h+='</div>';
  box.innerHTML=h;
}
function rlClear(){
  if(!confirm('کلِ گزارشِ بایگانی پاک شود؟ خودِ محصولات دست نمی‌خورند.'))return;
  fetch('?retire_log_clear=1').then(r=>r.json()).then(()=>{
    rlData=null; const c=$('rlCount'); if(c)c.textContent='';
    const box=$('rlBox'); if(box)box.innerHTML='<div style="color:#4ade80">✓ پاک شد</div>';
  }).catch(()=>{});
}

/* ═══ v10.39 (۵۳): فهرستِ آمادهٔ محصولاتِ باسلام ═══ */

/** جدولِ وضعیتِ فهرستِ هر غرفه را می‌سازد */
function bslCatRender(d){
  const box=$('bslCatBox'); if(!box)return;
  if(!d||!d.ok){box.innerHTML='<div style="color:#f87171">✗ '+esc((d&&d.error)||'خطا')+'</div>';return;}
  const rows=d.vendors||[];
  if(!rows.length){box.innerHTML='<div style="color:#64748b">هنوز هیچ غرفه‌ای تنظیم نشده.</div>';return;}
  let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:7px;line-height:1.9">';
  rows.forEach(v=>{
    const ok=!!v.fresh;
    h+='<div style="display:flex;gap:6px;align-items:center;border-bottom:1px solid #1e293b;padding:2px 0">'
      +'<span style="flex:1;color:#e2e8f0">'+esc(v.shop_name||('غرفه '+v.vendor_id))+'</span>'
      +'<span style="color:'+(ok?'#4ade80':'#fbbf24')+'">'+(ok?'✓ تازه':'⏳ کهنه')+'</span>'
      +'<span style="color:#94a3b8">'+toFa(v.count||0)+' عنوان</span>'
      +(v.rows_count?'<span style="color:#64748b">· '+toFa(v.rows_count)+' ردیف</span>':'')
      +(v.source?'<span style="color:#93c5fd">· '+esc(v.source)+'</span>':'')
      +(v.status_scope?'<span style="color:#a78bfa">· '+esc(v.status_scope)+'</span>':'')
      +(v.partial?'<span style="color:#f87171">· ناقص</span>':'')
      +'<span style="color:#64748b">'+esc(v.age_fa||'—')+'</span>'
      +'</div>';
  });
  h+='<div style="margin-top:4px;color:#64748b">تازه‌سازی هر '+toFa(Math.round(((d.ttl||21600)/3600)*100)/100)+' ساعت · کاتالوگ اگر جدول مغایرت موجود باشد از همان داده ساخته می‌شود.</div>';
  if(d.progress&&Array.isArray(d.progress.log)&&d.progress.log.length){
    const pp=d.progress;
    h+='<div style="margin-top:6px;background:#020617;border:1px solid #1e293b;border-radius:7px;padding:6px;color:#cbd5e1;max-height:150px;overflow:auto">'
      +'<div style="color:#93c5fd;margin-bottom:3px">جزئیات واکشی: '+esc(pp.phase||'')+' '+(pp.pct?toFa(pp.pct)+'٪':'')+'</div>'
      +pp.log.slice(-12).map(x=>'<div style="font-size:10.5px;border-top:1px solid #111827;padding:2px 0">'+esc((x&&x.m)?x.m:String(x))+'</div>').join('')+'</div>';
  }
  h+='</div>';
  box.innerHTML=h;
}

/** وضعیتِ فعلی را می‌خواند (بدون هیچ درخواستی به باسلام) */
function bslCatStatus(){
  const box=$('bslCatBox');
  if(box)box.innerHTML='<div style="color:#93c5fd">⏳ در حال خواندن…</div>';
  fetch('?bsl_catalog=1').then(r=>r.json()).then(bslCatRender)
    .catch(()=>{if(box)box.innerHTML='<div style="color:#f87171">✗ خطای شبکه</div>';});
}

/** بازسازیِ فوری — ممکن است چند ده ثانیه طول بکشد */
function bslCatRebuild(){
  if(!confirm('فهرستِ همهٔ غرفه‌ها دوباره از باسلام گرفته شود؟ بسته به تعدادِ محصولات ممکن است کمی طول بکشد.'))return;
  const box=$('bslCatBox');
  if(box)box.innerHTML='<div style="color:#93c5fd">⏳ در حال گرفتن از باسلام… صبر کنید.</div>';
  safeFetchJson('?bsl_catalog=1&rebuild=1').then(d=>{
    bslCatRender(d);
    showToast(d&&d.ok?'✓ فهرست به‌روز شد':'خطا',!(d&&d.ok));
  }).catch(()=>{if(box)box.innerHTML='<div style="color:#f87171">✗ خطای شبکه</div>';});
}

/** v8.34: بررسی دستی وضعیت گیر کردن صف */
function watchdogCheck(){
  const box=$('watchdogR');
  if(box)box.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ در حال بررسی...</div>';
  const after=$('stallAfter')?$('stallAfter').value:300;
  safeFetchJson('?queue_watchdog=1&dry=1&after='+encodeURIComponent(after)).then(d=>{
    if(!box)return;
    if(!d.ok){box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا</div>';return;}
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:8px;font-size:11px">';
    (d.checks||[]).forEach(c=>{
      const nm=c.which==='bsl'?'باسلام':'ووکامرس';
      if(c.stalled){
        h+='<div style="color:#fca5a5">⚠️ '+esc(nm)+' گیر کرده — '+toFa(c.idle||0)+' ثانیه بی‌حرکت'
          +' ('+toFa(c.current||0)+'/'+toFa(c.total||0)+')</div>';
      }else{
        h+='<div style="color:#86efac">✓ '+esc(nm)+' — '+esc(c.reason||'سالم')+'</div>';
      }
    });
    h+='<div style="margin-top:4px;color:#64748b">در اجرای خودکار بعدی، موارد گیرکرده ادامه داده می‌شوند.</div>';
    h+='</div>';
    box.innerHTML=h;
  }).catch(()=>{if(box)box.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا در ارتباط</div>';});
}

/* =====================================================================
 *  v8.32: مودال‌های استعلام — سفارش‌ها و گفتگوها
 *  اول لیست را نشان می‌دهد، بعد کاربر انتخاب می‌کند چه چیزی
 *  به پیام‌رسان‌ها فرستاده شود. هر دو مودال از یک اسکلت مشترک می‌آیند.
 * ===================================================================== */
let inqState={kind:'',filter:'',rows:[],sel:{},loading:false};

function inqClose(){
  const m=document.getElementById('inqModalContainer');
  if(m)m.remove();
  inqState={kind:'',filter:'',rows:[],sel:{},loading:false};
}

/** تاریخ ISO را به شکل خوانا و کوتاه فارسی درمی‌آورد */
function inqDate(s){
  if(!s)return '—';
  const d=new Date(s);
  if(isNaN(d))return '—';
  try{
    return new Intl.DateTimeFormat('fa-IR',{month:'short',day:'numeric',
      hour:'2-digit',minute:'2-digit'}).format(d);
  }catch(e){return d.toLocaleString();}
}

function inqMoney(n){return toFa(Number(n||0).toLocaleString('en-US'))+' تومان';}

/** کلید یکتای هر ردیف بسته به نوع */
function inqId(r){return inqState.kind==='orders'?r.parcel_id:r.chat_id;}

/** ردیف‌هایی که به‌طور پیش‌فرض «اقدام‌نشده» شمرده می‌شوند */
function inqIsPending(r){return inqState.kind==='orders'?!!r.unsent:(r.unseen>0);}

function inqSelectedIds(){
  return Object.keys(inqState.sel).filter(k=>inqState.sel[k]);
}

function inqToggle(id){
  inqState.sel[id]=!inqState.sel[id];
  inqRenderFoot();
  const cb=document.getElementById('inqCb_'+id);
  if(cb)cb.checked=!!inqState.sel[id];
  const tr=document.getElementById('inqRow_'+id);
  if(tr)tr.style.background=inqState.sel[id]?'#1e3a5f':'';
}

function inqSelectAll(on){
  inqState.rows.forEach(r=>{inqState.sel[inqId(r)]=on;});
  inqRenderBody();inqRenderFoot();
}

/** فقط موارد اقدام‌نشده را تیک می‌زند */
function inqSelectPending(){
  inqState.rows.forEach(r=>{inqState.sel[inqId(r)]=inqIsPending(r);});
  inqRenderBody();inqRenderFoot();
}

function openOrdersModal(filter){inqOpen('orders',filter||'all');}
function openChatsModal(filter){inqOpen('chats',filter||'all');}

function inqOpen(kind,filter){
  inqState.kind=kind;inqState.filter=filter;inqState.sel={};inqState.loading=true;
  const isOrd=kind==='orders';
  const title=isOrd?'🛒 سفارش‌های باسلام':'💬 گفتگوهای باسلام';
  let html='<div class="bsl-modal-overlay" onclick="if(event.target===this)inqClose()">';
  html+='<div class="bsl-modal" style="max-width:920px">';
  html+='<div class="bsl-modal-head"><h2 id="inqTitle">'+title+'</h2>'
      +'<button class="btn btn-gray" onclick="inqClose()">✕</button></div>';
  // نوار فیلتر — v9.96 (۱۰الف): یک ردیفِ افقی با اسکرول به‌جای wrap تا سربرگ کوتاه بماند
  html+='<div class="mbar" style="gap:6px;padding:7px 12px;background:#111c31;border-bottom:1px solid #334155">';
  if(isOrd){
    html+='<button class="btn btn-gray" id="inqF_all" onclick="inqSetFilter(\'all\')" style="font-size:11px;padding:5px 10px">همه</button>';
    html+='<button class="btn btn-gray" id="inqF_unsent" onclick="inqSetFilter(\'unsent\')" style="font-size:11px;padding:5px 10px">📦 ارسال‌نشده</button>';
  }else{
    html+='<button class="btn btn-gray" id="inqF_all" onclick="inqSetFilter(\'all\')" style="font-size:11px;padding:5px 10px">همه</button>';
    html+='<button class="btn btn-gray" id="inqF_unseen" onclick="inqSetFilter(\'unseen\')" style="font-size:11px;padding:5px 10px">💬 خوانده‌نشده</button>';
  }
  html+='<span class="mb-sp"></span>';
  html+='<span id="inqSummary" style="font-size:11px;color:#94a3b8"></span>';
  html+='<button class="btn btn-gray" onclick="inqReload()" style="font-size:11px;padding:5px 10px">🔄 تازه‌سازی</button>';
  html+='</div>';
  html+='<div class="bsl-modal-body" id="inqBody" style="min-height:180px"></div>';
  html+='<div class="bsl-modal-pager" id="inqFoot" style="justify-content:space-between;flex-wrap:wrap;gap:6px"></div>';
  html+='</div></div>';
  const old=document.getElementById('inqModalContainer');if(old)old.remove();
  const div=document.createElement('div');div.id='inqModalContainer';div.innerHTML=html;
  document.body.appendChild(div);
  inqReload();
}

function inqSetFilter(f){inqState.filter=f;inqState.sel={};inqReload();}

function inqReload(){
  const body=document.getElementById('inqBody');
  if(body)body.innerHTML='<div style="padding:26px;text-align:center;color:#93c5fd;font-size:12px">⏳ در حال استعلام از باسلام...</div>';
  inqRenderFoot();
  const isOrd=inqState.kind==='orders';
  const url=isOrd
    ?('?bsl_orders_list=1&per_page=30&filter='+encodeURIComponent(inqState.filter))
    :('?bsl_chats_list=1&limit=50&filter='+encodeURIComponent(inqState.filter));
  fetch(url).then(r=>r.json()).then(d=>{
    inqState.loading=false;
    if(!d||!d.ok){
      if(body)body.innerHTML='<div style="padding:20px;color:#fca5a5;font-size:12px;background:#7f1d1d20;border-radius:8px;margin:8px">✗ '+esc(d&&d.error?d.error:'خطا در دریافت')+'</div>';
      inqRenderFoot();return;
    }
    inqState.rows=d.rows||[];
    // پیش‌فرض: موارد اقدام‌نشده تیک خورده باشند تا کار کاربر کم شود
    inqState.rows.forEach(r=>{if(inqState.sel[inqId(r)]===undefined)inqState.sel[inqId(r)]=inqIsPending(r);});
    const sm=document.getElementById('inqSummary');
    if(sm){
      sm.innerHTML=isOrd
        ?(toFa(d.total||0)+' سفارش · <b style="color:#fbbf24">'+toFa(d.unsent||0)+'</b> ارسال‌نشده'
          +((d.shops_ok&&d.shops_ok>1)?' · <span style="color:#67e8f9">'+toFa(d.shops_ok)+' غرفه</span>':''))
        :(toFa(d.total||0)+' گفتگو · <b style="color:#fbbf24">'+toFa(d.unseen||0)+'</b> خوانده‌نشده');
    }
    ['all','unsent','unseen'].forEach(f=>{
      const b=document.getElementById('inqF_'+f);
      if(b){b.className='btn '+(inqState.filter===f?'btn-cyan':'btn-gray');}
    });
    inqRenderBody();inqRenderFoot();
  }).catch(e=>{
    inqState.loading=false;
    if(body)body.innerHTML='<div style="padding:20px;color:#fca5a5;font-size:12px">✗ خطا در ارتباط: '+esc(e.message)+'</div>';
    inqRenderFoot();
  });
}

function inqRenderBody(){
  const body=document.getElementById('inqBody');
  if(!body)return;
  const rows=inqState.rows;
  if(!rows.length){
    body.innerHTML='<div style="padding:30px;text-align:center;color:#64748b;font-size:12px">موردی یافت نشد</div>';
    return;
  }
  const isOrd=inqState.kind==='orders';
  let h='<table class="bsl-modal-table"><thead><tr>'
    +'<th style="width:34px"><input type="checkbox" onclick="inqSelectAll(this.checked)" style="width:15px;height:15px;cursor:pointer"></th>';
  h+=isOrd
    ?'<th>شماره</th><th>مشتری</th><th>مبلغ</th><th>وضعیت</th><th>تاریخ</th>'
    :'<th>مشتری</th><th>آخرین پیام</th><th>خوانده‌نشده</th><th>زمان</th>';
  h+='</tr></thead><tbody>';
  rows.forEach(r=>{
    const id=inqId(r);
    const pend=inqIsPending(r);
    const on=!!inqState.sel[id];
    h+='<tr id="inqRow_'+id+'" style="border-bottom:1px solid #1e293b;'+(on?'background:#1e3a5f':'')+'">';
    h+='<td style="text-align:center"><input type="checkbox" id="inqCb_'+id+'" '+(on?'checked':'')
      +' onclick="inqToggle('+id+')" style="width:15px;height:15px;cursor:pointer"></td>';
    if(isOrd){
      const it0=(r.items&&r.items[0]&&r.items[0].title)?String(r.items[0].title):'';
      h+='<td style="font-family:ui-monospace,monospace;direction:ltr;text-align:right">#'+toFa(r.order_id||r.parcel_id)
        +(r.shop_name?'<div style="font-family:inherit;direction:rtl;font-size:9.5px;color:#38bdf8;margin-top:2px">'+esc(r.shop_name)+'</div>':'')+'</td>';
      h+='<td>'+esc(r.customer||'—')+(r.items_count>0?'<div style="font-size:9.5px;color:#64748b">'+toFa(r.items_count)+' قلم'+(it0?' · '+esc(it0.slice(0,38)):'')+'</div>':'')+'</td>';
      h+='<td style="white-space:nowrap">'+inqMoney(r.amount)+'</td>';
      h+='<td><span style="font-size:10px;padding:2px 7px;border-radius:4px;background:'
        +(pend?'#7c2d12':'#14532d')+';color:'+(pend?'#fdba74':'#86efac')+'">'+esc(r.status||'—')+'</span></td>';
      h+='<td style="font-size:10px;color:#94a3b8;white-space:nowrap">'+esc(inqDate(r.created_at))+'</td>';
    }else{
      h+='<td>'+esc(r.who||'—')+'</td>';
      h+='<td style="max-width:340px;color:#cbd5e1">'+esc((r.text||'').slice(0,90))+'</td>';
      h+='<td style="text-align:center">'+(r.unseen>0
        ?'<span style="font-size:10px;padding:2px 7px;border-radius:10px;background:#7f1d1d;color:#fca5a5">'+toFa(r.unseen)+'</span>'
        :'<span style="color:#475569">—</span>')+'</td>';
      h+='<td style="font-size:10px;color:#94a3b8;white-space:nowrap">'+esc(inqDate(r.updated_at))+'</td>';
    }
    h+='</tr>';
  });
  h+='</tbody></table>';
  body.innerHTML=h;
}

function inqRenderFoot(){
  const foot=document.getElementById('inqFoot');
  if(!foot)return;
  const n=inqSelectedIds().length;
  const isOrd=inqState.kind==='orders';
  const lbl=isOrd?'سفارش':'گفتگو';
  let h='<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">';
  h+='<button class="btn btn-gray" onclick="inqSelectPending()" style="font-size:11px;padding:5px 10px">'
    +(isOrd?'انتخاب ارسال‌نشده‌ها':'انتخاب خوانده‌نشده‌ها')+'</button>';
  h+='<button class="btn btn-gray" onclick="inqSelectAll(false)" style="font-size:11px;padding:5px 10px">هیچ‌کدام</button>';
  h+='<span style="font-size:11px;color:'+(n?'#4ade80':'#64748b')+'">'+toFa(n)+' '+lbl+' انتخاب شده</span>';
  h+='</div>';
  h+='<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">';
  h+='<button class="btn btn-purple" id="inqSendDigest" '+(n?'':'disabled')
    +' onclick="inqSend(1)" style="font-size:11px;padding:6px 11px">📋 ارسال خلاصه (یک پیام)</button>';
  h+='<button class="btn btn-green" id="inqSendEach" '+(n?'':'disabled')
    +' onclick="inqSend(0)" style="font-size:11px;padding:6px 11px">📨 ارسال جداگانه</button>';
  h+='</div>';
  foot.innerHTML=h;
}

function inqSend(digest){
  const ids=inqSelectedIds();
  if(!ids.length){showToast('موردی انتخاب نشده',1);return;}
  if(!digest&&ids.length>5&&!confirm('می‌خواهید '+ids.length+' پیام جداگانه فرستاده شود؟\nبرای شلوغ نشدن پیام‌رسان، «ارسال خلاصه» بهتر است.'))return;
  ['inqSendDigest','inqSendEach'].forEach(k=>{const b=document.getElementById(k);if(b){b.disabled=true;}});
  const b2=document.getElementById(digest?'inqSendDigest':'inqSendEach');
  const oldTxt=b2?b2.textContent:'';
  if(b2)b2.textContent='⏳ در حال ارسال...';
  fetch('?bsl_notify_selected=1&kind='+encodeURIComponent(inqState.kind)
    +'&digest='+(digest?1:0)+'&ids='+encodeURIComponent(ids.join(',')))
    .then(r=>r.json()).then(d=>{
      if(b2)b2.textContent=oldTxt;
      inqRenderFoot();
      if(!d||!d.ok){showToast((d&&d.error)?d.error:'ارسال ناموفق',1);return;}
      if(d.note){showToast(d.note,1);return;}
      const dl=d.delivery||{};
      const bad=Object.keys(dl).filter(k=>dl[k]!=='sent');
      if(bad.length)showToast('⚠ ارسال به '+bad.join('، ')+' ناموفق بود',1);
      else showToast('✓ '+toFa(d.sent||0)+' پیام فرستاده شد');
    }).catch(()=>{
      if(b2)b2.textContent=oldTxt;
      inqRenderFoot();showToast('خطا شبکه',1);
    });
}

/* ===== v10.470: سامانهٔ جامع مدیریت سفارشات (باسلام + ووکامرس) ===== */
const omState={
  inited:false,
  loading:false,
  channel:'all',
  page:1,
  cursor:'',
  cursorStack:[],
  rows:[],
  bslShops:[],
  wooConfigured:false,
  bslStatuses:{},
  wooStatuses:{},
  activeUid:'',
  activeOrder:null
};

function omEnsureLoaded(){
  const root=document.getElementById('omSmenuRoot');
  if(!root)return;
  const body=root.querySelector('.smenu-body');
  if(body&&!body.classList.contains('open'))return;
  if(!omState.inited){
    omState.inited=true;
    omRebuildStatusOptions();
    omReload(true);
  }
}

function omMoney(v){
  const n=Math.max(0,parseInt(v||0,10)||0);
  return n>0?(toFa(n.toLocaleString('en-US'))+' تومان'):'—';
}

function omFmtDate(iso){
  if(!iso)return '—';
  const d=new Date(iso);
  if(isNaN(d.getTime()))return String(iso).slice(0,16);
  try{
    return d.toLocaleDateString('fa-IR',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
  }catch(_){return String(iso).slice(0,16);}
}

function omStatusClass(r){
  if(r.unsent)return 'pend';
  const st=String(r.status_id||'');
  if(['2979','3238','completed'].includes(st))return 'ok';
  if(['3067','3573','4633','5075','5017','3572','cancelled','failed','refunded'].includes(st))return 'bad';
  return 'muted';
}

function omRebuildStatusOptions(){
  const sel=document.getElementById('omStatusSel');
  if(!sel)return;
  const prev=sel.value||'all';
  let h='<option value="all">همهٔ وضعیت‌ها</option>';
  h+='<option value="unsent">⏳ در انتظار ارسال / اقدام</option>';
  if(omState.channel==='bsl'){
    h+='<option value="problem">⚠️ مشکل‌دار / تأخیر / انصراف</option>';
    const bs=omState.bslStatuses||{3739:'جدید (در انتظار تأیید)',3237:'در حال آماده‌سازی',3238:'ارسال شده',2979:'تحویل شده',3067:'لغو شده'};
    Object.keys(bs).forEach(k=>{h+='<option value="'+esc(k)+'">باسلام: '+esc(bs[k])+'</option>';});
  }else if(omState.channel==='woo'){
    const ws=omState.wooStatuses||{processing:'در حال انجام (آماده ارسال)','on-hold':'در انتظار بررسی',pending:'در انتظار پرداخت',completed:'تکمیل شده',cancelled:'لغو شده',refunded:'مسترد شده',failed:'ناموفق'};
    Object.keys(ws).forEach(k=>{h+='<option value="'+esc(k)+'">ووکامرس: '+esc(ws[k])+'</option>';});
  }
  sel.innerHTML=h;
  if([...sel.options].some(o=>o.value===prev))sel.value=prev;
  const shopSel=document.getElementById('omShopSel');
  if(shopSel){
    shopSel.style.display=(omState.channel==='woo')?'none':'';
  }
}

function omPopulateShops(shops){
  const sel=document.getElementById('omShopSel');
  if(!sel||!Array.isArray(shops))return;
  const prev=sel.value||'0';
  let h='<option value="0">همهٔ غرفه‌های باسلام ('+toFa(shops.length)+')</option>';
  shops.forEach(s=>{
    h+='<option value="'+esc(String(s.vendor_id))+'">🛍 '+esc(s.shop_name||('غرفه '+s.vendor_id))+'</option>';
  });
  sel.innerHTML=h;
  if([...sel.options].some(o=>o.value===prev))sel.value=prev;
}

function omSwitchChannel(ch){
  if(!['all','bsl','woo'].includes(ch))ch='all';
  omState.channel=ch;
  omState.page=1;
  omState.cursor='';
  omState.cursorStack=[];
  ['all','bsl','woo'].forEach(k=>{
    const b=document.getElementById('omTab_'+k);
    if(b)b.classList.toggle('active',k===ch);
  });
  omRebuildStatusOptions();
  omCloseDetail();
  omReload(true);
}

function omReload(resetPage){
  if(resetPage){
    omState.page=1;
    omState.cursor='';
    omState.cursorStack=[];
  }
  const listEl=document.getElementById('omListWrap');
  const warnEl=document.getElementById('omWarnBar');
  if(listEl)listEl.innerHTML='<div style="padding:26px;text-align:center;color:#93c5fd;font-size:12px">⏳ در حال دریافت سفارشات...</div>';
  if(warnEl)warnEl.classList.add('hidden');
  omState.loading=true;

  const q=(document.getElementById('omSearchInp')||{}).value||'';
  const st=(document.getElementById('omStatusSel')||{}).value||'all';
  const sh=(document.getElementById('omShopSel')||{}).value||'0';
  const url='?orders_mgr_api=list'
    +'&channel='+encodeURIComponent(omState.channel)
    +'&status='+encodeURIComponent(st)
    +'&shop_id='+encodeURIComponent(sh)
    +'&q='+encodeURIComponent(q.trim())
    +'&page='+encodeURIComponent(String(omState.page))
    +'&cursor='+encodeURIComponent(omState.cursor)
    +'&per_page=20';

  fetch(url).then(r=>r.json()).then(d=>{
    omState.loading=false;
    if(!d||!d.ok){
      if(listEl)listEl.innerHTML='<div style="padding:18px;color:#fca5a5;background:#7f1d1d22;border:1px solid #991b1b;border-radius:9px;font-size:11.5px">✗ '+esc((d&&d.error)?d.error:'خطا در دریافت سفارشات')+'</div>';
      return;
    }
    omState.rows=Array.isArray(d.rows)?d.rows:[];
    omState.bslShops=Array.isArray(d.bsl_shops)?d.bsl_shops:[];
    omState.wooConfigured=!!d.woo_configured;
    if(d.bsl_statuses)omState.bslStatuses=d.bsl_statuses;
    if(d.woo_statuses)omState.wooStatuses=d.woo_statuses;
    omPopulateShops(omState.bslShops);

    const kTot=document.getElementById('omKpiTotal');
    const kUns=document.getElementById('omKpiUnsent');
    const kSpl=document.getElementById('omKpiSplit');
    const kSum=document.getElementById('omKpiSum');
    if(kTot)kTot.textContent=toFa(d.total||0);
    if(kUns)kUns.textContent=toFa(d.unsent||0);
    if(kSpl)kSpl.textContent=toFa(d.bsl_count||0)+' / '+toFa(d.woo_count||0);
    if(kSum)kSum.textContent=d.sum_toman?toFa(Number(d.sum_toman).toLocaleString('en-US')):'۰';

    if(omState.channel==='all'){
      const ca=document.getElementById('omCnt_all');if(ca)ca.textContent=toFa(d.total||0);
      const cb=document.getElementById('omCnt_bsl');if(cb)cb.textContent=toFa(d.bsl_count||0);
      const cw=document.getElementById('omCnt_woo');if(cw)cw.textContent=toFa(d.woo_count||0);
    }else if(omState.channel==='bsl'){
      const cb=document.getElementById('omCnt_bsl');if(cb)cb.textContent=toFa(d.bsl_count||0);
    }else if(omState.channel==='woo'){
      const cw=document.getElementById('omCnt_woo');if(cw)cw.textContent=toFa(d.woo_count||0);
    }

    const hdrB=document.getElementById('omHdrBadge');
    if(hdrB){
      const u=parseInt(d.unsent||0,10)||0;
      hdrB.textContent=u>0?(toFa(u)+' منتظر ارسال'):(toFa(d.total||0)+' سفارش');
      hdrB.className='cst '+(u>0?'warn':'on');
    }

    if(warnEl){
      const errs=Array.isArray(d.errors)?d.errors:[];
      if(errs.length){
        warnEl.innerHTML='⚠️ '+errs.map(e=>esc(e)).join('<br>⚠️ ');
        warnEl.classList.remove('hidden');
      }else{
        warnEl.classList.add('hidden');
      }
    }

    omRenderList();
    omRenderPager(d);
  }).catch(e=>{
    omState.loading=false;
    if(listEl)listEl.innerHTML='<div style="padding:18px;color:#fca5a5;font-size:11.5px">✗ خطای شبکه: '+esc(e.message||'')+'</div>';
  });
}

function omRenderList(){
  const listEl=document.getElementById('omListWrap');
  if(!listEl)return;
  const rows=omState.rows||[];
  if(!rows.length){
    let emptyMsg='هیچ سفارشی با فیلتر فعلی یافت نشد.';
    if(omState.channel==='woo'&&!omState.wooConfigured){
      emptyMsg='اتصال ووکامرس هنوز تنظیم نشده است. از زیرمنوی «🟣 ووکامرس» در همین منو، آدرس فروشگاه و کلیدهای Consumer Key / Secret را ثبت کنید.';
    }
    listEl.innerHTML='<div style="padding:26px 14px;text-align:center;color:#94a3b8;background:#0f172a;border:1px dashed #334155;border-radius:10px;font-size:11.5px;line-height:1.8">'+esc(emptyMsg)+'</div>';
    return;
  }
  let h='';
  rows.forEach((r,idx)=>{
    const isBsl=r.channel==='bsl';
    const stCls=omStatusClass(r);
    const items=Array.isArray(r.items)?r.items:[];
    const firstTitle=items[0]&&items[0].title?String(items[0].title):'';
    const moreCnt=items.length>1?(' و '+toFa(items.length-1)+' قلم دیگر'):'';
    const loc=[r.province,r.city].filter(Boolean).join(' · ');
    const cardCls='om-card'+(r.unsent?' unsent':(stCls==='ok'?' done-ord':''));
    h+='<div class="'+cardCls+'" id="omCard_'+idx+'">';
    h+='<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:5px">';
    h+='<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">';
    if(isBsl){
      h+='<span class="om-ch-bsl">🛍 باسلام'+(r.shop_name?' · '+esc(r.shop_name):'')+'</span>';
    }else{
      h+='<span class="om-ch-woo">🟣 ووکامرس</span>';
    }
    h+='<b style="font-family:ui-monospace,monospace;font-size:12px;color:#f8fafc;direction:ltr">#'+esc(String(r.display_number||r.order_id||r.parcel_id||''))+'</b>';
    h+='<span class="om-st '+stCls+'">'+esc(r.status||'—')+'</span>';
    h+='</div>';
    h+='<div style="font-size:11.5px;font-weight:800;color:#4ade80">'+omMoney(r.amount)+'</div>';
    h+='</div>';

    h+='<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;font-size:11px;color:#cbd5e1;margin-bottom:5px">';
    h+='<div>👤 <b>'+esc(r.customer||'—')+'</b>'
      +(loc?' <span style="color:#94a3b8;font-size:10px">('+esc(loc)+')</span>':'')
      +(r.phone?' · <span style="font-family:ui-monospace,monospace;direction:ltr;display:inline-block;color:#67e8f9;cursor:pointer" title="کلیک برای کپی موبایل" onclick="omCopyText(\''+esc(String(r.phone))+'\')">📞 '+esc(String(r.phone))+'</span>':'')
      +'</div>';
    h+='<div style="font-size:10px;color:#94a3b8">🕒 '+esc(omFmtDate(r.created_at))
      +(r.send_before?' · <span style="color:#fbbf24">مهلت: '+esc(omFmtDate(r.send_before))+'</span>':'')
      +'</div>';
    h+='</div>';

    if(firstTitle){
      h+='<div style="font-size:10.5px;color:#94a3b8;background:#0b1220;border:1px solid #1e293b;border-radius:7px;padding:4px 8px;margin-bottom:6px;display:flex;justify-content:space-between;align-items:center;gap:6px;flex-wrap:wrap">';
      h+='<span>📦 '+esc(firstTitle.slice(0,65))+(items[0]&&items[0].qty>1?' ×'+toFa(items[0].qty):'')+esc(moreCnt)+'</span>';
      if(r.tracking_code){
        h+='<span style="font-family:ui-monospace,monospace;font-size:10px;color:#86efac;background:#064e3b66;padding:1px 6px;border-radius:5px;cursor:pointer" onclick="omCopyText(\''+esc(String(r.tracking_code))+'\')" title="کپی کد رهگیری">📮 '+esc(String(r.tracking_code))+'</span>';
      }
      h+='</div>';
    }

    h+='<div style="display:flex;gap:5px;flex-wrap:wrap;align-items:center">';
    h+='<button type="button" class="btn btn-cyan" style="font-size:10.5px;padding:4px 9px" onclick="omOpenDetail('+idx+')">🔍 جزئیات و مدیریت</button>';
    h+='<button type="button" class="btn btn-gray" style="font-size:10.5px;padding:4px 8px" onclick="omPrintByIdx('+idx+')">🖨 برچسب پستی</button>';
    h+='<button type="button" class="btn btn-gray" style="font-size:10.5px;padding:4px 8px" onclick="omForwardIdx('+idx+')">📤 پیام‌رسان</button>';
    if(r.panel_url){
      h+='<a href="'+esc(r.panel_url)+'" target="_blank" rel="noopener" class="btn btn-gray" style="font-size:10px;padding:4px 8px;text-decoration:none">↗ پنل اصلی</a>';
    }
    h+='</div>';
    h+='</div>';
  });
  listEl.innerHTML=h;
}

function omRenderPager(d){
  const pgEl=document.getElementById('omPagerWrap');
  if(!pgEl)return;
  let h='<div style="font-size:10px;color:#64748b">نمایش '+toFa((d.rows||[]).length)+' سفارش</div>';
  h+='<div style="display:flex;gap:5px;align-items:center">';
  if(omState.channel==='woo'||omState.channel==='all'){
    if(omState.page>1){
      h+='<button type="button" class="btn btn-gray" style="font-size:10px;padding:4px 9px" onclick="omState.page--;omReload(false)">→ صفحه قبل</button>';
    }
    if(d.woo_has_more){
      h+='<button type="button" class="btn btn-gray" style="font-size:10px;padding:4px 9px" onclick="omState.page++;omReload(false)">صفحه بعد ('+toFa(omState.page+1)+') ←</button>';
    }
  }
  if(omState.channel==='bsl'){
    if(omState.cursorStack.length>0){
      h+='<button type="button" class="btn btn-gray" style="font-size:10px;padding:4px 9px" onclick="omState.cursor=omState.cursorStack.pop()||\'\';omReload(false)">→ صفحه قبل باسلام</button>';
    }
    if(d.bsl_next_cursor){
      h+='<button type="button" class="btn btn-gray" style="font-size:10px;padding:4px 9px" onclick="omState.cursorStack.push(omState.cursor);omState.cursor=\''+esc(String(d.bsl_next_cursor))+'\';omReload(false)">مرسوله‌های بعدی ←</button>';
    }
  }
  h+='</div>';
  pgEl.innerHTML=h;
}

function omCopyText(txt){
  if(!txt)return;
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(txt).then(()=>showToast('✓ کپی شد: '+txt)).catch(()=>showToast(txt));
  }else{
    showToast(txt);
  }
}

function omCloseDetail(){
  omState.activeUid='';
  omState.activeOrder=null;
  const w=document.getElementById('omDetailWrap');
  if(w){w.classList.add('hidden');w.innerHTML='';}
}

function omOpenDetail(idx){
  const base=omState.rows[idx];
  if(!base)return;
  omState.activeUid=base.uid||'';
  omState.activeOrder=base;
  omRenderDetail(base,true);
  const w=document.getElementById('omDetailWrap');
  if(w)w.scrollIntoView({behavior:'smooth',block:'nearest'});

  const detUrl=base.channel==='woo'
    ?('?orders_mgr_api=detail&channel=woo&order_id='+encodeURIComponent(String(base.order_id)))
    :('?orders_mgr_api=detail&channel=bsl&parcel_id='+encodeURIComponent(String(base.parcel_id))+'&vendor_id='+encodeURIComponent(String(base.vendor_id||0)));
  fetch(detUrl).then(r=>r.json()).then(d=>{
    if(d&&d.ok&&d.order&&omState.activeUid===(base.uid||'')){
      omState.activeOrder=d.order;
      omState.rows[idx]=d.order;
      omRenderDetail(d.order,false);
      omRenderList();
    }else if(omState.activeUid===(base.uid||'')){
      omRenderDetail(base,false);
    }
  }).catch(()=>{
    if(omState.activeUid===(base.uid||''))omRenderDetail(base,false);
  });
}

function omRenderDetail(o,fetchingMore){
  const w=document.getElementById('omDetailWrap');
  if(!w||!o)return;
  w.classList.remove('hidden');
  const isBsl=o.channel==='bsl';
  const items=Array.isArray(o.items)?o.items:[];
  const fullAddr=[o.province,o.city,o.address].filter(Boolean).join(' — ');

  let h='<div class="om-det-box">';
  h+='<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;border-bottom:1px solid #1e293b;padding-bottom:8px;margin-bottom:8px">';
  h+='<div style="display:flex;align-items:center;gap:7px;flex-wrap:wrap">';
  h+=isBsl
    ?('<span class="om-ch-bsl">🛍 مرسوله باسلام'+(o.shop_name?' · '+esc(o.shop_name):'')+'</span>')
    :'<span class="om-ch-woo">🟣 سفارش ووکامرس</span>';
  h+='<b style="font-size:13px;color:#fff;direction:ltr">#'+esc(String(o.display_number||o.order_id||o.parcel_id))+'</b>';
  h+='<span class="om-st '+omStatusClass(o)+'">'+esc(o.status||'—')+'</span>';
  if(fetchingMore)h+='<span style="font-size:10px;color:#38bdf8">⏳ تکمیل اطلاعات...</span>';
  h+='</div>';
  h+='<div style="display:flex;gap:5px;align-items:center">';
  h+='<button type="button" class="btn btn-gray" style="font-size:10.5px;padding:4px 8px" onclick="omPrintOrder(omState.activeOrder)">🖨 چاپ برگه ارسال</button>';
  h+='<button type="button" class="btn btn-gray" style="font-size:11px;padding:3px 9px" onclick="omCloseDetail()">✕ بستن</button>';
  h+='</div></div>';

  /* مشخصات گیرنده و پرداخت */
  h+='<div class="om-field-grid">';
  h+='<div class="om-fcell"><small>👤 خریدار / گیرنده</small><b>'+esc(o.customer||'—')+'</b>'
    +(o.phone?'<div style="margin-top:2px"><span style="color:#67e8f9;direction:ltr;display:inline-block;cursor:pointer" onclick="omCopyText(\''+esc(String(o.phone))+'\')">📞 '+esc(String(o.phone))+' 📋</span></div>':'')
    +(o.email?'<div style="font-size:10px;color:#94a3b8;direction:ltr">'+esc(o.email)+'</div>':'')
    +'</div>';
  h+='<div class="om-fcell"><small>💳 مبلغ کل و ارسال</small><b style="color:#4ade80">'+omMoney(o.amount)+'</b>'
    +'<div style="font-size:10px;color:#94a3b8">هزینه ارسال: '+omMoney(o.shipping_cost)+(o.payment_method?' · '+esc(o.payment_method):'')+'</div>'
    +(o.shipping_method?'<div style="font-size:10px;color:#cbd5e1">روش ارسال: '+esc(o.shipping_method)+'</div>':'')
    +'</div>';
  h+='<div class="om-fcell" style="grid-column:1/-1"><small>📍 نشانی و کدپستی گیرنده '
    +(fullAddr?'<button type="button" class="btn btn-gray" style="font-size:9px;padding:1px 6px;margin-right:5px" onclick="omCopyText(\''+esc(fullAddr+(o.postal_code?' - کدپستی: '+o.postal_code:''))+'\')">کپی آدرس کامل</button>':'')
    +'</small>'
    +'<div style="color:#e2e8f0">'+(fullAddr?esc(fullAddr):'<span style="color:#64748b">آدرسی در پاسخ ثبت نشده است</span>')+'</div>'
    +(o.postal_code?'<div style="font-size:10px;color:#93c5fd;margin-top:2px;cursor:pointer" onclick="omCopyText(\''+esc(String(o.postal_code))+'\')">کدپستی: <b style="font-family:ui-monospace,monospace;direction:ltr">'+esc(String(o.postal_code))+'</b> 📋</div>':'')
    +(o.customer_note?'<div style="margin-top:4px;padding:4px 7px;background:#42200666;border:1px solid #b45309;border-radius:6px;color:#fde68a;font-size:10px">📝 توضیح مشتری: '+esc(o.customer_note)+'</div>':'')
    +'</div>';
  h+='</div>';

  /* اقلام سفارش */
  h+='<div style="background:#0f172a;border:1px solid #1e293b;border-radius:9px;margin:8px 0;overflow:hidden">';
  h+='<div style="padding:5px 9px;background:#111c31;font-size:10.5px;font-weight:700;color:#93c5fd;border-bottom:1px solid #1e293b">📦 اقلام سفارش ('+toFa(items.length)+' ردیف)</div>';
  items.forEach(it=>{
    h+='<div class="om-it-row">';
    if(it.image){
      h+='<img src="'+esc(it.image)+'" class="om-it-img" loading="lazy" alt="">';
    }else{
      h+='<div class="om-it-img" style="display:flex;align-items:center;justify-content:center;font-size:15px">📦</div>';
    }
    h+='<div style="flex:1 1 auto;min-width:0">';
    h+='<div style="font-weight:700;color:#f1f5f9;word-break:break-word">'+esc(it.title||'کالا')+'</div>';
    const metaBits=[];
    if(it.variant)metaBits.push(it.variant);
    if(it.sku)metaBits.push('SKU: '+it.sku);
    if(it.product_id)metaBits.push('#'+it.product_id);
    if(metaBits.length)h+='<div style="font-size:9.5px;color:#94a3b8">'+esc(metaBits.join(' · '))+'</div>';
    h+='</div>';
    h+='<div style="text-align:left;white-space:nowrap;font-size:10.5px">';
    h+='<span style="background:#1e293b;color:#67e8f9;padding:1px 7px;border-radius:999px;font-weight:700">×'+toFa(it.qty||1)+'</span>';
    if(it.total>0)h+='<div style="color:#4ade80;font-weight:700;margin-top:2px">'+omMoney(it.total)+'</div>';
    h+='</div></div>';
  });
  h+='</div>';

  /* پنل مدیریت اختصاصی کانال */
  if(isBsl){
    h+='<div style="background:#0f172a;border:1px solid #1e3a5f;border-radius:9px;padding:9px;margin-top:8px">';
    h+='<div style="font-size:11px;font-weight:700;color:#6ee7b7;margin-bottom:7px">⚙️ عملیات مرسوله باسلام</div>';
    h+='<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:7px">';
    if(parseInt(o.status_id||0,10)===3739){
      h+='<button type="button" class="btn btn-green" style="font-size:10.5px;padding:5px 10px" onclick="omBslAction(\'set_preparation\')">✅ تأیید و شروع آماده‌سازی</button>';
    }
    h+='<select id="omDetCarrier" style="background:#0b1220;border:1px solid #334155;color:#e2e8f0;border-radius:7px;padding:5px 8px;font-size:10.5px">'
      +'<option value="pishtaz" '+(o.carrier==='pishtaz'?'selected':'')+'>پست پیشتاز</option>'
      +'<option value="sefareshi" '+(o.carrier==='sefareshi'?'selected':'')+'>پست سفارشی</option>'
      +'<option value="tipax" '+(o.carrier==='tipax'?'selected':'')+'>تیپاکس</option>'
      +'<option value="chapar" '+(o.carrier==='chapar'?'selected':'')+'>چاپار</option>'
      +'<option value="courier" '+(o.carrier==='courier'?'selected':'')+'>پیک / باربری</option>'
      +'</select>';
    h+='<input type="text" id="omDetTracking" value="'+esc(o.tracking_code||'')+'" placeholder="کد رهگیری ۲۴ رقمی پست / بارکد..." style="flex:1 1 170px;background:#0b1220;border:1px solid #334155;color:#e2e8f0;border-radius:7px;padding:5px 8px;font-size:11px;direction:ltr">';
    h+='<button type="button" class="btn btn-cyan" style="font-size:10.5px;padding:5px 10px" onclick="omBslAction(\'set_posted\')">📮 ثبت ارسال در باسلام</button>';
    h+='</div>';
    h+='<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">';
    h+='<input type="text" id="omDetAdminNote" value="'+esc(o.admin_note||'')+'" placeholder="یادداشت داخلی فروشنده برای این مرسوله..." style="flex:1 1 200px;background:#0b1220;border:1px solid #334155;color:#e2e8f0;border-radius:7px;padding:5px 8px;font-size:10.5px">';
    h+='<button type="button" class="btn btn-gray" style="font-size:10.5px;padding:5px 10px" onclick="omBslAction(\'save_note\')">💾 ذخیره یادداشت / رهگیری</button>';
    h+='</div></div>';
  }else{
    const ws=omState.wooStatuses||{pending:'در انتظار پرداخت',processing:'در حال انجام (آماده ارسال)','on-hold':'در انتظار بررسی',completed:'تکمیل شده',cancelled:'لغو شده',refunded:'مسترد شده',failed:'ناموفق'};
    h+='<div style="background:#0f172a;border:1px solid #581c87;border-radius:9px;padding:9px;margin-top:8px">';
    h+='<div style="font-size:11px;font-weight:700;color:#d8b4fe;margin-bottom:7px">⚙️ مدیریت سفارش ووکامرس</div>';
    h+='<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-bottom:8px">';
    h+='<select id="omWooNewStatus" style="background:#0b1220;border:1px solid #334155;color:#e2e8f0;border-radius:7px;padding:5px 8px;font-size:11px">';
    Object.keys(ws).forEach(k=>{
      h+='<option value="'+esc(k)+'" '+(String(o.status_id)===k?'selected':'')+'>'+esc(ws[k])+'</option>';
    });
    h+='</select>';
    h+='<button type="button" class="btn btn-cyan" style="font-size:10.5px;padding:5px 10px" onclick="omWooUpdateStatus()">🔄 تغییر وضعیت سفارش</button>';
    h+='</div>';

    h+='<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-bottom:6px">';
    h+='<input type="text" id="omDetCarrier" value="'+esc(o.carrier||'پست پیشتاز')+'" placeholder="شرکت حمل (پست/تیپاکس)" style="width:115px;background:#0b1220;border:1px solid #334155;color:#e2e8f0;border-radius:7px;padding:5px 8px;font-size:10.5px">';
    h+='<input type="text" id="omDetTracking" value="'+esc(o.tracking_code||'')+'" placeholder="کد رهگیری مرسوله..." style="flex:1 1 160px;background:#0b1220;border:1px solid #334155;color:#e2e8f0;border-radius:7px;padding:5px 8px;font-size:11px;direction:ltr">';
    h+='<button type="button" class="btn btn-green" style="font-size:10.5px;padding:5px 10px" onclick="omWooSaveTracking()">📮 ثبت رهگیری</button>';
    h+='</div>';
    h+='<div style="display:flex;gap:12px;flex-wrap:wrap;font-size:10px;color:#cbd5e1;margin-bottom:8px">';
    h+='<label style="display:flex;align-items:center;gap:4px;cursor:pointer"><input type="checkbox" id="omWooNotifyCust" checked> ارسال یادداشت کد رهگیری برای مشتری</label>';
    h+='<label style="display:flex;align-items:center;gap:4px;cursor:pointer"><input type="checkbox" id="omWooMarkComp" '+(o.status_id!=='completed'?'checked':'')+'> تغییر وضعیت به «تکمیل‌شده»</label>';
    h+='</div>';
    h+='<input type="text" id="omDetAdminNote" value="'+esc(o.admin_note||'')+'" placeholder="یادداشت داخلی..." style="width:100%;background:#0b1220;border:1px solid #334155;color:#e2e8f0;border-radius:7px;padding:5px 8px;font-size:10.5px;margin-bottom:8px">';

    /* افزودن یادداشت رسمی ووکامرس + تاریخچه یادداشت‌ها */
    h+='<div style="border-top:1px solid #1e293b;padding-top:7px;margin-top:4px">';
    h+='<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">';
    h+='<input type="text" id="omWooNoteTxt" placeholder="افزودن یادداشت جدید در پرونده سفارش ووکامرس..." style="flex:1 1 190px;background:#0b1220;border:1px solid #334155;color:#e2e8f0;border-radius:7px;padding:5px 8px;font-size:10.5px">';
    h+='<label style="font-size:10px;color:#cbd5e1;display:flex;align-items:center;gap:4px;cursor:pointer"><input type="checkbox" id="omWooNoteCust"> قابل مشاهده برای مشتری</label>';
    h+='<button type="button" class="btn btn-gray" style="font-size:10.5px;padding:5px 9px" onclick="omWooAddNote()">📝 ثبت یادداشت</button>';
    h+='</div>';
    if(Array.isArray(o.woo_notes)&&o.woo_notes.length){
      h+='<div style="max-height:110px;overflow-y:auto;margin-top:6px;padding:5px;background:#0b1220;border-radius:7px;font-size:10px;color:#94a3b8">';
      o.woo_notes.forEach(n=>{
        h+='<div style="padding:3px 4px;border-bottom:1px solid #1e293b">'
          +(n.customer_note?'<span style="color:#38bdf8">[مشتری]</span> ':'<span style="color:#a78bfa">[خصوصی]</span> ')
          +esc(n.note||'')+' <span style="color:#64748b">('+esc(omFmtDate(n.date))+')</span></div>';
      });
      h+='</div>';
    }
    h+='</div></div>';
  }
  h+='</div>';
  w.innerHTML=h;
}

function omPostAction(params,cb){
  const fd=new URLSearchParams();
  Object.keys(params).forEach(k=>fd.append(k,params[k]==null?'':String(params[k])));
  fetch('',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8'},body:fd.toString()})
    .then(r=>r.json()).then(d=>cb(null,d)).catch(e=>cb(e,null));
}

function omBslAction(sub){
  const o=omState.activeOrder;
  if(!o)return;
  const trk=(document.getElementById('omDetTracking')||{}).value||'';
  const car=(document.getElementById('omDetCarrier')||{}).value||'pishtaz';
  const adm=(document.getElementById('omDetAdminNote')||{}).value||'';
  omPostAction({
    orders_mgr_api:'bsl_action',
    sub_action:sub,
    parcel_id:o.parcel_id,
    vendor_id:o.vendor_id||0,
    tracking_code:trk.trim(),
    carrier:car,
    admin_note:adm.trim()
  },(err,d)=>{
    if(err||!d){showToast('خطا در ارتباط با سرور',1);return;}
    if(!d.ok){
      showToast(d.error||'عملیات ناموفق بود',1);
      if(d.saved_locally){o.tracking_code=trk.trim();o.admin_note=adm.trim();omRenderList();}
      return;
    }
    showToast('✓ '+(d.message||'انجام شد'));
    omReload(false);
  });
}

function omWooUpdateStatus(){
  const o=omState.activeOrder;
  if(!o)return;
  const ns=(document.getElementById('omWooNewStatus')||{}).value||'';
  omPostAction({orders_mgr_api:'woo_action',sub_action:'update_status',order_id:o.order_id,new_status:ns},(err,d)=>{
    if(err||!d||!d.ok){showToast((d&&d.error)?d.error:'خطا در تغییر وضعیت',1);return;}
    showToast('✓ '+(d.message||'وضعیت بروزرسانی شد'));
    if(d.order){omState.activeOrder=d.order;omRenderDetail(d.order,false);}
    omReload(false);
  });
}

function omWooSaveTracking(){
  const o=omState.activeOrder;
  if(!o)return;
  const trk=(document.getElementById('omDetTracking')||{}).value||'';
  const car=(document.getElementById('omDetCarrier')||{}).value||'';
  const adm=(document.getElementById('omDetAdminNote')||{}).value||'';
  const nc=(document.getElementById('omWooNotifyCust')||{}).checked?1:0;
  const mc=(document.getElementById('omWooMarkComp')||{}).checked?1:0;
  omPostAction({
    orders_mgr_api:'woo_action',
    sub_action:'save_tracking',
    order_id:o.order_id,
    tracking_code:trk.trim(),
    carrier:car.trim(),
    admin_note:adm.trim(),
    notify_customer:nc,
    mark_completed:mc
  },(err,d)=>{
    if(err||!d||!d.ok){showToast((d&&d.error)?d.error:'خطا در ذخیره کد رهگیری',1);return;}
    showToast('✓ '+(d.message||'کد رهگیری ثبت شد'));
    o.tracking_code=trk.trim();o.carrier=car.trim();o.admin_note=adm.trim();
    omReload(false);
  });
}

function omWooAddNote(){
  const o=omState.activeOrder;
  if(!o)return;
  const inp=document.getElementById('omWooNoteTxt');
  const txt=inp?inp.value.trim():'';
  if(!txt){showToast('متن یادداشت را بنویسید',1);return;}
  const isCust=(document.getElementById('omWooNoteCust')||{}).checked?1:0;
  omPostAction({orders_mgr_api:'woo_action',sub_action:'add_note',order_id:o.order_id,note:txt,customer_note:isCust},(err,d)=>{
    if(err||!d||!d.ok){showToast((d&&d.error)?d.error:'ثبت یادداشت ناموفق بود',1);return;}
    if(inp)inp.value='';
    showToast('✓ '+(d.message||'یادداشت ثبت شد'));
    const idx=omState.rows.findIndex(x=>x.uid===o.uid);
    if(idx>=0)omOpenDetail(idx);
  });
}

function omBuildForwardMessage(o){
  const chTitle=o.channel==='bsl'?('🛍 سفارش باسلام'+(o.shop_name?' ('+o.shop_name+')':'')):'🟣 سفارش ووکامرس';
  const lines=[chTitle+' — #'+String(o.display_number||o.order_id||o.parcel_id)];
  lines.push('وضعیت: '+(o.status||'—'));
  lines.push('مشتری: '+(o.customer||'—')+(o.phone?' · '+o.phone:''));
  const addr=[o.province,o.city,o.address].filter(Boolean).join('، ');
  if(addr)lines.push('آدرس: '+addr+(o.postal_code?' (کدپستی: '+o.postal_code+')':''));
  if(Array.isArray(o.items)&&o.items.length){
    lines.push('اقلام:');
    o.items.slice(0,10).forEach(it=>{
      lines.push('• '+(it.title||'کالا')+(it.variant?' ['+it.variant+']':'')+' × '+(it.qty||1));
    });
  }
  lines.push('مبلغ کل: '+omMoney(o.amount));
  if(o.tracking_code)lines.push('کد رهگیری: '+o.tracking_code);
  return lines.join('\n');
}

function omForwardIdx(idx){
  const o=omState.rows[idx];
  if(!o)return;
  omPostAction({orders_mgr_api:'forward_msgr',message:omBuildForwardMessage(o)},(err,d)=>{
    if(err||!d||!d.ok){showToast((d&&d.error)?d.error:'ارسال به پیام‌رسان ناموفق بود',1);return;}
    showToast('✓ کارت سفارش به پیام‌رسان ارسال شد');
  });
}

function omPrintByIdx(idx){
  const o=omState.rows[idx];
  if(o)omPrintOrder(o);
}

function omPrintOrder(o){
  if(!o)return;
  const win=window.open('','_blank','width=780,height=680');
  if(!win){showToast('مرورگر پنجره چاپ را مسدود کرد',1);return;}
  const chName=o.channel==='bsl'?('باسلام'+(o.shop_name?' — '+o.shop_name:'')):'فروشگاه ووکامرس';
  const addr=[o.province,o.city,o.address].filter(Boolean).join('، ');
  const items=Array.isArray(o.items)?o.items:[];
  let rowsHtml='';
  items.forEach((it,i)=>{
    rowsHtml+='<tr><td>'+toFa(i+1)+'</td><td>'+esc(it.title||'کالا')+(it.variant?'<div style="font-size:11px;color:#555">'+esc(it.variant)+'</div>':'')+'</td>'
      +'<td style="text-align:center">'+toFa(it.qty||1)+'</td>'
      +'<td>'+omMoney(it.total||0)+'</td></tr>';
  });
  const doc='<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>برگه ارسال #'+esc(String(o.display_number||''))+'</title>'
    +'<style>body{font-family:Tahoma,Arial,sans-serif;padding:18px;color:#111;line-height:1.7}'
    +'.box{border:2px solid #111;border-radius:10px;padding:14px;margin-bottom:14px}'
    +'table{width:100%;border-collapse:collapse;margin-top:10px}th,td{border:1px solid #333;padding:7px 9px;font-size:13px;text-align:right}'
    +'th{background:#f1f5f9}@media print{.noprint{display:none}}</style></head><body>'
    +'<div class="noprint" style="margin-bottom:12px"><button onclick="window.print()" style="padding:8px 18px;font-weight:bold;cursor:pointer">🖨 چاپ برچسب و فاکتور</button></div>'
    +'<div class="box"><div style="display:flex;justify-content:space-between;border-bottom:1px dashed #666;padding-bottom:8px;margin-bottom:8px">'
    +'<div><b>کانال فروش:</b> '+esc(chName)+'</div>'
    +'<div><b>شماره سفارش:</b> <span dir="ltr">#'+esc(String(o.display_number||o.order_id||o.parcel_id))+'</span></div>'
    +'<div><b>تاریخ:</b> '+esc(omFmtDate(o.created_at))+'</div></div>'
    +'<div style="font-size:15px"><b>گیرنده:</b> '+esc(o.customer||'—')+(o.phone?' &nbsp;|&nbsp; <b>تلفن:</b> <span dir="ltr">'+esc(String(o.phone))+'</span>':'')+'</div>'
    +'<div style="margin-top:6px;font-size:14px"><b>نشانی گیرنده:</b> '+esc(addr||'—')+'</div>'
    +(o.postal_code?'<div style="margin-top:4px"><b>کدپستی:</b> <span dir="ltr" style="font-size:15px;font-weight:bold">'+esc(String(o.postal_code))+'</span></div>':'')
    +(o.shipping_method?'<div><b>روش ارسال:</b> '+esc(o.shipping_method)+'</div>':'')
    +(o.tracking_code?'<div><b>کد رهگیری:</b> <span dir="ltr">'+esc(String(o.tracking_code))+'</span></div>':'')
    +(o.customer_note?'<div style="margin-top:6px;background:#fef9c3;padding:6px;border:1px solid #ca8a04"><b>توضیح مشتری:</b> '+esc(o.customer_note)+'</div>':'')
    +'</div>'
    +'<table><thead><tr><th style="width:38px">#</th><th>شرح کالا</th><th style="width:65px;text-align:center">تعداد</th><th style="width:130px">مبلغ</th></tr></thead><tbody>'+rowsHtml+'</tbody></table>'
    +'<div style="margin-top:10px;text-align:left;font-size:14px"><b>جمع کل سفارش: '+omMoney(o.amount)+'</b></div>'
    +'</body></html>';
  win.document.open();win.document.write(doc);win.document.close();
}

/* ===== v9.16: بکاپ و بازیابی ===== */
function bkSet(msg,color){const s=$('bkStatus');if(s){s.innerHTML=msg;s.style.color=color||'#94a3b8';}}
function bkRefresh(){
    fetch('?backup_status=1').then(r=>r.json()).then(d=>{
        if(!d||!d.ok)return;
        const c=d.cfg||{};
        /* v9.18: مقادیر ارث‌بری‌شده از «منبع و نصب‌کننده» */
        const vc=c.vc||{};
        if($('bkVcRepo'))$('bkVcRepo').textContent=vc.repo||'— تنظیم نشده';
        if($('bkVcBranch'))$('bkVcBranch').textContent=vc.branch||'main';
        if($('bkVcToken')){
            $('bkVcToken').innerHTML=vc.has_token
                ?'<span style="color:#4ade80">ذخیره شده ✓</span>'
                :'<span style="color:#fbbf24">تنظیم نشده — برای مخزن خصوصی لازم است</span>';
        }
        if($('bkOwnRepo'))$('bkOwnRepo').checked=!!c.own_repo;
        bkToggleOwn();
        if($('bkRepo')&&!$('bkRepo').value&&c.own_repo)$('bkRepo').value=c.repo||'';
        if($('bkBranch')&&!$('bkBranch').value&&c.own_repo)$('bkBranch').value=c.branch||'main';
        if($('bkPath')&&!$('bkPath').value)$('bkPath').value=c.path||'backups';
        if($('bkToken'))$('bkToken').placeholder=(c.own_repo&&c.token)?('ذخیره شده '+c.token):'ghp_...';
        if($('bkIncData'))$('bkIncData').checked=!!c.include_data;
        if($('bkIncCode'))$('bkIncCode').checked=!!c.include_code;
        if($('bkAuto'))$('bkAuto').checked=!!c.auto;
        if($('bkEvery'))$('bkEvery').value=c.auto_every_h||24;
        if($('bkKeep'))$('bkKeep').value=c.keep||20;
        const b=$('bkBadge');
        if(b){
            const has=(d.local||[]).length;
            b.textContent=has?(toFa(has)+' نسخه'):'بدون بکاپ';
            b.className='cst '+(has?'on':'off');
        }
        // فهرست بکاپ‌های محلی
        let h='';
        (d.local||[]).forEach(f=>{
            h+='<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;'
              +'background:#0f172a;border:1px solid #334155;border-radius:7px;padding:6px 8px;margin-bottom:4px">'
              +'<div><code style="direction:ltr;font-size:10px">'+esc(f.name)+'</code>'
              +'<br><span style="color:#64748b;font-size:9.5px">'+esc(f.at_h)+' · '+toFa(Math.round(f.size/1024))+'KB</span></div>'
              +'<div style="display:flex;gap:4px">'
              +'<button class="btn" style="font-size:9.5px;padding:3px 7px;background:#334155;color:#cbd5e1;border:none;border-radius:4px" onclick="bkPeek(\''+esc(f.name)+'\')">👁</button>'
              +'<button class="btn" style="font-size:9.5px;padding:3px 7px;background:#0e7490;color:#fff;border:none;border-radius:4px" onclick="bkDownload(\''+esc(f.name)+'\')">⬇</button>'
              +'<button class="btn" style="font-size:9.5px;padding:3px 7px;background:#c2410c;color:#fff;border:none;border-radius:4px" onclick="bkRestore(\'local\',\''+esc(f.name)+'\')">♻️</button>'
              +'</div></div>';
        });
        if($('bkList'))$('bkList').innerHTML=h||'<span style="color:#64748b">هنوز بکاپی گرفته نشده</span>';
        // گزارش
        let lg='';
        (d.log||[]).forEach(l=>{
            const okc=l.ok?'#4ade80':'#f87171';
            lg+='<div style="border-right:2px solid '+okc+';padding:2px 8px;margin-bottom:4px">'
              +'<span style="color:'+okc+'">'+(l.ok?'✅':'❌')+'</span> '
              +'<span style="color:#64748b">'+esc(l.at_h||'')+'</span> '
              +(l.files!==undefined?('<span style="color:#94a3b8">'+toFa(l.files)+' فایل</span> '):'')
              +(l.github?('<span style="color:#67e8f9">گیت‌هاب: '+esc(l.github)+'</span>'):'')
              +(l.restore?('<span style="color:#fbbf24">بازیابی '+toFa((l.restore||[]).length)+' فایل</span>'):'')
              +(l.error?('<br><span style="color:#f87171;font-size:10px">'+esc(l.error)+'</span>'):'')
              +'</div>';
        });
        if($('bkLog'))$('bkLog').innerHTML=lg||'<span style="color:#64748b">—</span>';
    }).catch(()=>{});
}
/* v9.18: فیلدهای مخزن فقط وقتی معنا دارند که «مخزن جدا» روشن باشد */
function bkToggleOwn(){
    const on=!!(($('bkOwnRepo')||{}).checked);
    const box=$('bkOwnBox'), inh=$('bkInherit');
    if(box)box.style.display=on?'block':'none';
    if(inh)inh.style.opacity=on?'0.45':'1';
}
function bkSaveCfg(){
    const fd=new FormData();
    fd.append('action','backup_save_cfg');
    const own=!!(($('bkOwnRepo')||{}).checked);
    if(own){
        fd.append('own_repo','1');
        fd.append('repo',($('bkRepo')||{}).value||'');
        fd.append('branch',($('bkBranch')||{}).value||'main');
        const t=($('bkToken')||{}).value||'';
        if(t)fd.append('token',t);
    }
    fd.append('path',($('bkPath')||{}).value||'backups');
    if(($('bkIncData')||{}).checked)fd.append('include_data','1');
    if(($('bkIncCode')||{}).checked)fd.append('include_code','1');
    if(($('bkAuto')||{}).checked)fd.append('auto','1');
    fd.append('auto_every_h',($('bkEvery')||{}).value||24);
    fd.append('keep',($('bkKeep')||{}).value||20);
    bkSet('در حال ذخیره...','#67e8f9');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(d&&d.ok){bkSet('✅ ذخیره شد','#4ade80');if($('bkToken'))$('bkToken').value='';bkRefresh();}
        else bkSet('❌ ذخیره نشد','#f87171');
    }).catch(()=>bkSet('❌ خطای شبکه','#f87171'));
}
function bkRunNow(){
    bkSet('⏳ در حال گرفتن بکاپ...','#67e8f9');
    fetch('?backup_run=1').then(r=>r.json()).then(d=>{
        if(!d){bkSet('❌ پاسخ نامعتبر','#f87171');return;}
        let m=(d.ok?'✅':'⚠️')+' '+toFa(d.files||0)+' فایل ('+toFa(Math.round((d.bytes||0)/1024))+'KB)';
        if(d.github)m+=' · گیت‌هاب: '+esc(d.github);
        if(d.error)m+='<br><span style="color:#f87171">'+esc(d.error)+'</span>';
        bkSet(m,d.ok?'#4ade80':'#fbbf24');
        bkRefresh();
    }).catch(()=>bkSet('❌ خطای شبکه','#f87171'));
}
function bkDownload(n){window.open('?backup_download='+encodeURIComponent(n),'_blank');}
function bkPeek(n){
    fetch('?backup_peek='+encodeURIComponent(n)).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){showToast('خوانده نشد',1);return;}
        let m='📦 '+n+'\n'+(d.created_at_h||'')+' · v'+(d.version||'')+'\n\n';
        (d.files||[]).forEach(f=>{
            m+='• '+f.name+' ('+Math.round(f.size/1024)+'KB)';
            if(f.profiles!==undefined)m+=' — '+f.profiles+' پروفایل: '+(f.names||[]).join('، ');
            m+='\n';
        });
        alert(m);
    }).catch(()=>showToast('خطا',1));
}
function bkRemoteList(){
    bkSet('⏳ خواندن از گیت‌هاب...','#67e8f9');
    fetch('?backup_remote_list=1').then(r=>r.json()).then(d=>{
        if(!d||!d.ok){bkSet('❌ '+esc((d&&d.error)||'خطا'),'#f87171');return;}
        let h='<div style="color:#67e8f9;font-size:10.5px;margin-bottom:5px">☁️ روی گیت‌هاب:</div>';
        (d.items||[]).forEach(f=>{
            h+='<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;'
              +'background:#0f172a;border:1px solid #334155;border-radius:7px;padding:6px 8px;margin-bottom:4px">'
              +'<code style="direction:ltr;font-size:10px">'+esc(f.name)+'</code>'
              +'<button class="btn" style="font-size:9.5px;padding:3px 7px;background:#c2410c;color:#fff;border:none;border-radius:4px" onclick="bkRestore(\'github\',\''+esc(f.name)+'\')">♻️ بازیابی</button>'
              +'</div>';
        });
        if($('bkList'))$('bkList').innerHTML=h||'<span style="color:#64748b">روی گیت‌هاب بکاپی نیست</span>';
        bkSet('✅ '+toFa((d.items||[]).length)+' بکاپ روی گیت‌هاب','#4ade80');
    }).catch(()=>bkSet('❌ خطای شبکه','#f87171'));
}
/* v10.13 (۲۶): متنِ «چه چیزی بازیابی می‌شود» برای تأییدِ بازیابی؛
   از همان انتخابگرِ مشترکِ بالای منوی تنظیمات خوانده می‌شود. */
function bkSecSuffix(){
    if(typeof sxSel!=='function')return '';
    const sel=(typeof SX_SECS!=='undefined'&&SX_SECS.length)?sxSel():'';
    return sel?('\n\nفقط بخش‌های انتخاب‌شده در «💾 ذخیره و بازیابی همهٔ تنظیمات» ('+toFa(sxSecCount())+' بخش) برگردانده می‌شوند.'):'';
}
function bkSecAppend(fd){
    if(typeof sxSel!=='function')return;
    const sel=(typeof SX_SECS!=='undefined'&&SX_SECS.length)?sxSel():'';
    if(sel)fd.append('sections',sel);
}
function bkRestore(src,name){
    if(!confirm('بازیابی از «'+name+'»؟\nفایل‌های فعلی جایگزین می‌شوند (یک کپی .before-restore کنارشان می‌ماند).'+bkSecSuffix()))return;
    const fd=new FormData();
    fd.append('action','backup_restore');
    fd.append('source',src);
    fd.append('name',name);
    bkSecAppend(fd);
    bkSet('⏳ در حال بازیابی...','#67e8f9');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){bkSet('❌ '+esc((d&&d.error)||'بازیابی نشد'),'#f87171');return;}
        bkSet('✅ '+toFa((d.restored||[]).length)+' فایل برگردانده شد — صفحه را تازه کنید','#4ade80');
        showToast('✅ بازیابی شد — صفحه را رفرش کنید');
        bkRefresh();
    }).catch(()=>bkSet('❌ خطای شبکه','#f87171'));
}
function bkRestoreUpload(){
    const f=($('bkFile')||{}).files;
    if(!f||!f.length){showToast('اول فایل را انتخاب کنید',1);return;}
    if(!confirm('بازیابی از فایل انتخاب‌شده؟'+bkSecSuffix()))return;
    const fd=new FormData();
    fd.append('action','backup_restore');
    fd.append('source','upload');
    fd.append('file',f[0]);
    bkSecAppend(fd);
    bkSet('⏳ در حال بازیابی...','#67e8f9');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){bkSet('❌ '+esc((d&&d.error)||'بازیابی نشد'),'#f87171');return;}
        bkSet('✅ '+toFa((d.restored||[]).length)+' فایل برگردانده شد — صفحه را تازه کنید','#4ade80');
        bkRefresh();
    }).catch(()=>bkSet('❌ خطای شبکه','#f87171'));
}

/* =====================================================================
 * v10.13 (۲۶): انتخابگرِ بخش/زیربخش.
 * یک وضعیتِ مشترک برای هر دو جهت: چیزی که تیک دارد هم دانلود می‌شود و
 * هم بازیابی. فهرستِ بخش‌ها از سرور می‌آید (?backup_sections=1) تا هیچ
 * نامِ فایلی در جاوااسکریپت تکرار نشود و از PHP عقب نیفتد.
 * ===================================================================== */
let SX_SECS=[], SX_ON={}, SX_MODE='local';   // local = دادهٔ همین نصب، bundle = فایلِ آپلودشده
function sxSecCount(){let n=0;for(const k in SX_ON)if(SX_ON[k])n++;return n;}
/** v10.14: آیا زیربخشِ توکن‌داری تیک خورده؟ */
function sxSecretOn(){
    let y=false;SX_SECS.forEach(s=>(s.subs||[]).forEach(x=>{if(x.secret&&SX_ON[x.id])y=true;}));
    return y;
}
function sxSecTotal(){let n=0;SX_SECS.forEach(s=>n+=(s.subs||[]).length);return n;}
/** فهرستِ زیربخش‌های تیک‌خورده؛ اگر دقیقاً همان پیش‌فرض باشد رشتهٔ خالی
 *  v10.14: قبلاً «همه تیک ⇒ خالی» بود. حالا که خالی سمتِ سرور یعنی
 *  «پیش‌فرض‌ها»، اگر با تیکِ همه رشتهٔ خالی می‌فرستادیم، همان فایل‌های
 *  سیستمی که کاربر عمداً تیک زده بود بی‌صدا از بسته می‌افتادند. */
function sxSel(){
    const on=[],def=[];
    SX_SECS.forEach(s=>(s.subs||[]).forEach(x=>{
        if(SX_ON[x.id])on.push(x.id);
        if(!x.off)def.push(x.id);
    }));
    const same=on.length===def.length&&def.every(id=>SX_ON[id]);
    return same?'':on.join(',');
}
function sxPickBtnSync(){
    const b=$('sxPickBtn');if(!b)return;
    const n=sxSecCount(),t=sxSecTotal();
    b.textContent='🧩 انتخابِ بخش‌ها — '+(t===0?'…':(n===t?'همهٔ بخش‌ها':(n===0?'هیچ بخشی انتخاب نشده':toFa(n)+' از '+toFa(t)+' بخش')))
        +(sxSecretOn()?' 🔑':'');
    b.className='btn '+(n===0?'btn-red':(n===t?'btn-teal':'btn-yellow'));
}
function sxTogglePicker(){
    const p=$('sxPicker');if(!p)return;
    p.classList.toggle('hidden');
    if(!p.classList.contains('hidden')&&!SX_SECS.length)sxLoadSections();
}
function sxLoadSections(){
    fetch('?backup_sections=1').then(r=>r.json()).then(d=>{
        if(!d||!d.ok)return;
        SX_SECS=d.sections||[];SX_MODE='local';
        /* v10.14: زیربخش‌های نشان‌دارِ off (توکنِ گیت‌هاب، گزارشِ بکاپ)
           پیش‌فرض تیک نمی‌خورند — کاربر باید آگاهانه انتخابشان کند. */
        SX_SECS.forEach(s=>(s.subs||[]).forEach(x=>{if(SX_ON[x.id]===undefined)SX_ON[x.id]=!x.off;}));
        sxRenderSections();
    }).catch(()=>{const e=$('sxSecList');if(e)e.textContent='فهرست بخش‌ها بارگذاری نشد';});
}
function sxHuman(b){
    b=+b||0;
    if(b<1024)return toFa(b)+' بایت';
    if(b<1048576)return toFa(Math.round(b/1024))+' کیلوبایت';
    return toFa((b/1048576).toFixed(1))+' مگابایت';
}
function sxRenderSections(){
    const box=$('sxSecList');if(!box)return;
    if(!SX_SECS.length){box.textContent='بخشی پیدا نشد';return;}
    const srcNote=SX_MODE==='bundle'
        ?'<div style="font-size:10px;color:#fbbf24;margin-bottom:8px;line-height:1.7">📄 اعداد زیر از <b>فایلِ انتخاب‌شده</b> است، نه از این نصب. بخش‌هایی که داخلِ فایل نیستند غیرفعال شده‌اند.</div>'
        :'<div style="font-size:10px;color:#64748b;margin-bottom:8px;line-height:1.7">📊 اعداد زیر دادهٔ <b>همین نصب</b> است.</div>';
    const secretNote=sxSecretOn()
        ?'<div style="font-size:10px;color:#fca5a5;background:#3f1d1d;border:1px solid #7f1d1d;border-radius:6px;padding:6px 8px;margin-bottom:8px;line-height:1.7">🔑 بخشی که تیک زده‌اید <b>توکنِ گیت‌هاب</b> دارد. فایلِ خروجی را جای امن نگه دارید و برای عیب‌یابی به کسی ندهید.</div>'
        :'';
    box.innerHTML=srcNote+secretNote+SX_SECS.map(sec=>{
        const subs=sec.subs||[];
        const on=subs.filter(x=>SX_ON[x.id]).length;
        const rows=subs.map(x=>{
            const dis=(SX_MODE==='bundle'&&!x.exists);
            const meta=x.exists
                ?('<span style="color:#4ade80">'+toFa(x.count)+' مورد · '+sxHuman(x.bytes)+'</span>')
                :'<span style="color:#64748b">'+(SX_MODE==='bundle'?'در این فایل نیست':'خالی')+'</span>';
            const key=x.secret?'<span title="حاوی توکن" style="color:#fbbf24">🔑 </span>':'';
            return '<label style="display:flex;gap:6px;align-items:flex-start;padding:5px 6px;border-radius:6px;'
                +(dis?'opacity:.45;':'cursor:pointer;')+'">'
                +'<input type="checkbox" data-sxsub="'+esc(x.id)+'" '+(SX_ON[x.id]&&!dis?'checked':'')+(dis?' disabled':'')
                +' onchange="sxToggleSub(this)" style="margin-top:2px">'
                +'<span style="flex:1">'+key+'<span style="color:#e2e8f0">'+esc(x.title)+'</span> '+meta
                +'<br><span style="font-size:9.5px;color:#64748b">'+esc(x.desc||'')+'</span></span></label>';
        }).join('');
        return '<div style="border:1px solid #334155;border-radius:8px;padding:6px 8px;margin-bottom:6px;background:#111827">'
            +'<div style="display:flex;gap:6px;align-items:center;margin-bottom:4px">'
            +'<input type="checkbox" data-sxsec="'+esc(sec.id)+'" '+(on===subs.length?'checked':'')
            +' onchange="sxToggleSec(this)">'
            +'<b style="color:#5eead4;font-size:11.5px">'+esc(sec.title)+'</b>'
            +'<span style="font-size:9.5px;color:#64748b">'+esc(sec.desc||'')+'</span></div>'
            +rows+'</div>';
    }).join('');
    sxPickBtnSync();
}
function sxToggleSub(el){SX_ON[el.getAttribute('data-sxsub')]=el.checked;sxRenderSections();}
function sxToggleSec(el){
    const id=el.getAttribute('data-sxsec'),v=el.checked;
    const sec=SX_SECS.find(s=>s.id===id);if(!sec)return;
    (sec.subs||[]).forEach(x=>{if(!(SX_MODE==='bundle'&&!x.exists))SX_ON[x.id]=v;});
    sxRenderSections();
}
function sxPickAll(v){
    SX_SECS.forEach(s=>(s.subs||[]).forEach(x=>{if(!(SX_MODE==='bundle'&&!x.exists))SX_ON[x.id]=v;}));
    sxRenderSections();
}
function sxPickOnlyPresent(){
    SX_SECS.forEach(s=>(s.subs||[]).forEach(x=>{SX_ON[x.id]=!!x.exists;}));
    sxRenderSections();
}
/* فایلی که کاربر انتخاب می‌کند را می‌کاود تا تیک‌ها با محتوای واقعیِ
   همان بسته هم‌راستا شوند — نه با دادهٔ این نصب. */
function sxInspectFile(){
    const f=($('sxFile')||{}).files;
    if(!f||!f.length){SX_MODE='local';sxLoadSections();return;}
    const fd=new FormData();
    fd.append('action','backup_inspect');
    fd.append('file',f[0]);
    sxSet('⏳ در حال خواندنِ فایل...','#67e8f9');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){sxSet('❌ '+esc((d&&d.error)||'فایل خوانده نشد'),'#f87171');return;}
        SX_SECS=d.sections||[];SX_MODE='bundle';
        SX_SECS.forEach(s=>(s.subs||[]).forEach(x=>{SX_ON[x.id]=!!x.exists;}));
        sxRenderSections();
        const p=$('sxPicker');if(p)p.classList.remove('hidden');
        const when=d.created_at_h?(' — ساختِ '+esc(d.created_at_h)):'';
        sxSet('📄 فایل خوانده شد: '+toFa(sxSecCount())+' بخش داخلش هست'+when+' — تیک‌ها را بررسی کنید','#67e8f9');
    }).catch(()=>sxSet('❌ خطای شبکه هنگام خواندنِ فایل','#f87171'));
}

/* v9.59: «دانلود همهٔ تنظیمات و پروفایل‌ها» از بالای منوی تنظیمات
   v10.13 (۲۶): بخش‌های انتخاب‌شده به سرور فرستاده می‌شود */
function sxDownloadAll(){
    if(SX_SECS.length&&sxSecCount()===0){showToast('هیچ بخشی انتخاب نشده',1);return;}
    const sel=SX_SECS.length?sxSel():'';
    sxSet('⏳ در حال بسته‌بندی داده‌ها...','#67e8f9');
    fetch('?backup_export=1'+(sel?'&sections='+encodeURIComponent(sel):'')).then(r=>{
        if(!r.ok)return r.json().then(d=>{throw new Error((d&&d.error)||('HTTP '+r.status));});
        const cd=r.headers.get('Content-Disposition')||'';
        const m=cd.match(/filename="?([^";]+)"?/);
        const name=(m&&m[1])?m[1]:('settings_'+Date.now()+'.json');
        return r.blob().then(b=>{return {blob:b,name:name};});
    }).then(({blob,name})=>{
        const url=URL.createObjectURL(blob);
        const a=document.createElement('a');
        a.href=url;a.download=name;
        document.body.appendChild(a);a.click();
        document.body.removeChild(a);URL.revokeObjectURL(url);
        const partial=(SX_SECS.length&&sxSecCount()<sxSecTotal())?(' ('+toFa(sxSecCount())+' بخشِ منتخب)'):'';
        sxSet('✅ دانلود شد: <code style="direction:ltr">'+esc(name)+'</code>'+partial+' — آن را امن نگه دارید','#4ade80');
        showToast('✅ فایل تنظیمات دانلود شد');
    }).catch(e=>sxSet('❌ '+esc(e.message||'خطا'),'#f87171'));
}
/* v9.59: «بارگذاری و بازیابی» از بالای منوی تنظیمات
   v10.13 (۲۶): فقط بخش‌های تیک‌خورده نوشته می‌شوند و متنِ تأیید دقیقاً
   می‌گوید چه چیزی جایگزین می‌شود — «همه‌چیز» یک تأییدِ ترسناک است که
   کاربر بی‌فکر می‌زند؛ فهرستِ صریح این‌طور نیست. */
function sxRestoreAll(){
    const f=($('sxFile')||{}).files;
    if(!f||!f.length){showToast('اول فایل تنظیمات را انتخاب کنید',1);return;}
    if(SX_SECS.length&&sxSecCount()===0){showToast('هیچ بخشی برای بازیابی انتخاب نشده',1);return;}
    const sel=SX_SECS.length?sxSel():'';
    let what='همهٔ تنظیمات و پروفایل‌ها';
    if(sel){
        const names=[];
        SX_SECS.forEach(s=>(s.subs||[]).forEach(x=>{if(SX_ON[x.id])names.push('• '+x.title);}));
        what='این بخش‌ها:\n'+names.join('\n');
    }
    if(!confirm(what+'\n\nاز این فایل بارگذاری و جایگزین شوند؟\nبخش‌های تیک‌نخورده دست‌نخورده می‌مانند و از هر فایلِ عوض‌شده یک کپی .before-restore کنارش می‌ماند.'))return;
    const fd=new FormData();
    fd.append('action','backup_restore');
    fd.append('source','upload');
    fd.append('file',f[0]);
    if(sel)fd.append('sections',sel);
    sxSet('⏳ در حال بارگذاری و بازیابی...','#67e8f9');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){sxSet('❌ '+esc((d&&d.error)||'بازیابی نشد'),'#f87171');return;}
        const mg=(d.merged||[]).length?(' ('+toFa((d.merged||[]).length)+' فایل ادغام شد تا بقیهٔ داده‌ها نپرد)'):'';
        sxSet('✅ '+toFa((d.restored||[]).length)+' فایل بارگذاری شد'+mg+' — صفحه را رفرش کنید','#4ade80');
        showToast('✅ تنظیمات بازیابی شد — صفحه را رفرش کنید');
        setTimeout(()=>location.reload(),1600);
    }).catch(()=>sxSet('❌ خطای شبکه','#f87171'));
}
function sxSet(m,color){const e=$('sxStatus');if(e)e.innerHTML=m&&color?('<span style="color:'+color+'">'+m+'</span>'):m;}

function renderChangelog(){
  const box=$('changelogBox');
  if(!box)return;
  const cur='<?=APP_VERSION?>';
  const date='<?=APP_VERSION_DATE?>';
  const head='<div style="margin:0 0 12px;padding:10px 12px;border-radius:10px;background:#0f172a;border:1px solid #334155">'
    +'<div style="font-size:13px;font-weight:800;color:#e2e8f0">📋 گزارش تغییرات · نسخهٔ فعلی <span style="color:#4ade80;font-family:ui-monospace,monospace">v'+esc(cur)+'</span></div>'
    +'<div style="font-size:10.5px;color:#94a3b8;margin-top:4px">تاریخ نسخه: '+esc(date)+' · '+CHANGELOG.length+' ورودی ثبت‌شده · جدیدترین بالا</div>'
    +'</div>';
  box.style.maxHeight='min(70vh,520px)';
  box.innerHTML=head+CHANGELOG.map(c=>{
    const isCur=c.v===cur;
    return '<div style="border-right:3px solid '+(isCur?'#4ade80':'#334155')+';padding:0 10px 12px;margin-bottom:10px;background:'+(isCur?'rgba(74,222,128,.06)':'transparent')+';border-radius:0 8px 8px 0">'
      +'<div style="display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:4px">'
      +'<b style="color:'+(isCur?'#4ade80':'#94a3b8')+';font-size:12.5px;font-family:ui-monospace,monospace">v'+esc(c.v)+'</b>'
      +(isCur?'<span style="font-size:9px;color:#4ade80;background:#14532d;padding:2px 7px;border-radius:4px;font-weight:800">فعلی</span>':'')
      +'<span style="font-size:11.5px;color:#e2e8f0;font-weight:700">'+esc(c.t)+'</span></div>'
      +'<ul style="margin:0;padding-right:16px;color:#94a3b8;font-size:11px;line-height:1.85">'
      +(c.items||[]).map(i=>'<li>'+esc(i)+'</li>').join('')+'</ul></div>';
  }).join('');
}

/** آیا عملیات سنگینی در جریان است؟ */
/**
 * v8.46: فقط گزارش می‌دهد چه کاری در جریان است — دیگر جلوی نصب را نمی‌گیرد.
 *
 * چرا امن است: deploy.php فایل را اتمیک جایگزین می‌کند (نوشتن در فایل
 * موقت، بررسی هش، سپس rename). پردازه‌های در حال اجرا نسخهٔ قبلی را
 * کامل در حافظه دارند و تا پایان با همان ادامه می‌دهند. اسکریپت هم
 * تک‌فایل است و هیچ require زمان‌اجرا ندارد، پس نیمی از کد قدیم و نیمی
 * از کد جدید اجرا نمی‌شود. صف هم روی فایل ذخیره می‌شود و از نصب
 * جان سالم به در می‌برد.
 */
function vcBusy() {
    try {
        if (typeof running !== 'undefined' && running) return 'اسکرپ';
        if (typeof detailRunning !== 'undefined' && detailRunning) return 'استخراج تفصیلی';
        if (typeof bslClientRunning !== 'undefined' && bslClientRunning) return 'ارسال به باسلام';
        if (typeof wSend !== 'undefined' && wSend) return 'ارسال به ووکامرس';
        if (typeof bSend !== 'undefined' && bSend) return 'ارسال به باسلام';
        if (typeof fetchMissingRunning !== 'undefined' && fetchMissingRunning) return 'تکمیل اطلاعات';
        if (typeof ddIsRun !== 'undefined' && ddIsRun) return 'حذف تکراری‌ها';
    } catch (e) {}
    return '';
}

function vcStat(msg, color) {
    const el = $('vcStatus');
    if (el) { el.innerHTML = msg; el.style.color = color || '#4ade80'; }
}
function vcBadge(t, cls) {
    const b = $('vcBadge');
    if (b) { b.textContent = t; b.className = 'cst ' + (cls || 'off'); }
}
function vcDirty() {
    clearTimeout(vcSaveTimer);
    vcSaveTimer = setTimeout(() => vcSave(), 900);
}
function vcFmtSize(b) {
    if (!b) return '';
    if (b < 1024) return b + ' B';
    if (b < 1048576) return (b / 1024).toFixed(0) + ' KB';
    return (b / 1048576).toFixed(1) + ' MB';
}
function vcCloseDrops() {
    ['vcBranchDrop', 'vcPathDrop'].forEach(id => { const e = $(id); if (e) e.classList.remove('open'); });
}

function vcLoad(then) {
    fetch('?vc_settings=1').then(r => r.json()).then(d => {
        if (!d.ok) return;
        VC = d.settings;
        if ($('vcOnLoad'))     $('vcOnLoad').checked   = !!VC.check_on_load;
        if ($('vcRepo'))       $('vcRepo').value       = VC.repo || '';
        if (!Array.isArray(VC.branches)) VC.branches=VC.branch?[VC.branch]:[];
        if ($('vcBranch'))     $('vcBranch').value     = '';
        vcRenderBranches();
        if ($('vcPath'))       $('vcPath').value       = VC.path || '';
        if ($('vcDeployFile')) $('vcDeployFile').value = VC.deploy_file || 'deploy.php';
        if ($('vcGhState'))    $('vcGhState').textContent  = VC.has_gh_token ? 'تنظیم شده' : 'تنظیم نشده';
        if ($('vcDepState'))   $('vcDepState').textContent = VC.has_dep_token ? 'تنظیم شده' : 'تنظیم نشده';
        if ($('vcLocalInfo')) {
            $('vcLocalInfo').innerHTML = esc(VC.self_name) + '<br>' +
                '<span style="color:#64748b">' + esc(VC.local_id) + ' · ' +
                toFa((VC.local_size / 1024).toFixed(0)) + ' KB</span>';
        }
        vcBadge(VC.check_on_load ? 'خودکار' : 'دستی', VC.check_on_load ? 'on' : 'off');
        vcStat('برای بررسی نسخهٔ جدید دکمه را بزنید', '#64748b');
        if (typeof then === 'function') then();
    }).catch(() => {});
}

function vcRenderBranches(){
    const host=$('vcBranchList');if(!host)return;const rows=VC&&Array.isArray(VC.branches)?VC.branches:[];
    const pinned=(VC&&VC.pinned_branch)?String(VC.pinned_branch):'';
    host.innerHTML=rows.length?rows.map(b=>{const eb=encodeURIComponent(b);const isPin=(pinned&&pinned===b);return '<div style="display:flex;align-items:center;gap:6px;padding:7px 8px;border:1px solid '+(isPin?'#22c55e':'#334155')+';border-radius:8px;background:#0f172a"><code dir="ltr" style="flex:1;color:#bae6fd;overflow:hidden;text-overflow:ellipsis">'+esc(b)+'</code>'+(isPin?'<span style="font-size:9px;color:#4ade80;background:#14532d;padding:2px 6px;border-radius:4px">📌 فعال</span>':'')+'<button class="btn btn-green" type="button" style="font-size:9px;padding:4px 7px" onclick="vcUpdate(false,decodeURIComponent(\''+eb+'\'))">⬇ آپدیت از این برنچ</button><button class="btn btn-red" type="button" style="font-size:9px;padding:4px 7px" onclick="vcRemoveBranch(decodeURIComponent(\''+eb+'\'))">حذف</button></div>'}).join(''):'<div style="color:#fca5a5;font-size:10px">هنوز برنچی اضافه نشده است.</div>';
}
function vcAddBranch(){const el=$('vcBranch'),b=el?el.value.trim():'';if(!b)return showToast('نام برنچ را وارد کنید',1);if(!VC)VC={branches:[]};if(!Array.isArray(VC.branches))VC.branches=[];if(!VC.branches.includes(b))VC.branches.push(b);VC.branch=b;if(el)el.value='';vcRenderBranches();vcSave(true);}
function vcRemoveBranch(b){if(!VC||!Array.isArray(VC.branches))return;if(!confirm('برنچ «'+b+'» حذف شود؟'))return;VC.branches=VC.branches.filter(x=>x!==b);if(VC.branch===b)VC.branch=VC.branches[0]||'';vcRenderBranches();vcSave(true);}

function vcSave(showMsg) {
    const fd = new FormData();
    fd.append('check_on_load', $('vcOnLoad').checked ? '1' : '');
    fd.append('repo',        $('vcRepo').value.trim());
    const configured=VC&&Array.isArray(VC.branches)?VC.branches:[];
    fd.append('branches',JSON.stringify(configured));
    fd.append('branch',(VC&&VC.branch)||configured[0]||'');
    fd.append('path',        $('vcPath').value.trim());
    fd.append('deploy_file', $('vcDeployFile').value.trim() || 'deploy.php');
    if ($('vcGhToken').value)  fd.append('github_token', $('vcGhToken').value);
    if ($('vcDepToken').value) fd.append('deploy_token', $('vcDepToken').value);

    fetch('?vc_settings=1', { method: 'POST', body: fd }).then(r => r.json()).then(d => {
        if (!d.ok) { showToast(d.error || 'ذخیره ناموفق', true); return; }
        VC = d.settings;
        $('vcGhToken').value = ''; $('vcDepToken').value = '';
        if ($('vcGhState'))  $('vcGhState').textContent  = VC.has_gh_token ? 'تنظیم شده' : 'تنظیم نشده';
        if ($('vcDepState')) $('vcDepState').textContent = VC.has_dep_token ? 'تنظیم شده' : 'تنظیم نشده';
        vcBadge(VC.check_on_load ? 'خودکار' : 'دستی', VC.check_on_load ? 'on' : 'off');
        if (showMsg) showToast('✓ ذخیره شد');
    }).catch(() => showToast('خطا در ذخیره', true));
}

/**
 * v8.23: پنل بکاپ ورک‌اسپیس را باز می‌کند.
 * خودِ اسکریپر چیزی آپلود نمی‌کند؛ کار به deploy.php واگذار می‌شود تا
 * این فایل ساده و دور از الگوهای مشکوک برای اسکنر هاست بماند.
 */
function vcOpenBackup() {
    fetch('?vc_deploy_info=1').then(r => r.json()).then(d => {
        if (!d.ok) {
            showToast(d.error || 'نصب‌کننده در دسترس نیست', true);
            vcStat('✗ ' + esc(d.error || ''), '#f87171');
            return;
        }
        window.open(d.file + '#wbackup', '_blank');
        showToast('پنل بکاپ در تب جدید باز شد');
    }).catch(() => showToast('خطا در ارتباط', true));
}

/** حذف توکن گیت‌هاب — رفع سریع خطای ۴۰۱ روی ریپوی عمومی */
function vcClearToken() {
    const fd = new FormData();
    fd.append('github_token', '__CLEAR__');
    fetch('?vc_settings=1', { method: 'POST', body: fd }).then(r => r.json()).then(d => {
        if (!d.ok) { showToast(d.error || 'حذف ناموفق', true); return; }
        VC = d.settings;
        if ($('vcGhState')) $('vcGhState').textContent = 'تنظیم نشده';
        showToast('✓ توکن حذف شد — دوباره تلاش کنید');
        vcStat('توکن حذف شد — دکمهٔ بررسی را بزنید', '#4ade80');
    }).catch(() => showToast('خطا در ارتباط', true));
}

/** مقایسهٔ نسخه. manual=true یعنی کاربر دکمه زده. */
function vcCheck(manual) {
    if (!manual && (!VC || !VC.check_on_load)) return;
    const btn = $('vcBtnCheck');
    if (manual && btn) { btn.disabled = true; btn.textContent = '⏳ در حال بررسی...'; }
    if (manual) vcStat('<span style="opacity:.7">در حال مقایسه با گیت‌هاب...</span>', '#93c5fd');

    fetch('?vc_check=1' + (manual ? '&force=1' : '')).then(r => r.json()).then(d => {
        const reset = () => { if (btn) { btn.disabled = false; btn.textContent = '🔍 بررسی و نصب نسخهٔ جدید'; } };
        if (d.skipped) { reset(); return; }
        if (!d.ok) {
            if (d.bad_token) {
                // رایج‌ترین علت ۴۰۱: توکنی که لازم نیست و نامعتبر است
                vcStat('✗ ' + esc(d.error) +
                    ' <button class="btn" style="font-size:10px;padding:2px 8px;background:#dc2626;color:#fff;border:none;border-radius:4px;margin-right:6px" onclick="vcClearToken()">حذف توکن</button>',
                    '#f87171');
            } else {
                vcStat('✗ ' + esc(d.error || 'خطا'), '#f87171');
            }
            if (manual) showToast(d.error || 'خطا', true);
            reset(); return;
        }
        VC_PENDING_BRANCH=d.branch||'';if(VC&&VC_PENDING_BRANCH)VC.branch=VC_PENDING_BRANCH;
        if (!d.update) {
            VC_PENDING = false;
            $('vcBtnUpdate').classList.add('hidden');
            vcStat('✓ نسخهٔ شما به‌روز است — <code>' + esc(d.local_id) + '</code>', '#4ade80');
            vcBadge('به‌روز', 'on');
            const av = $('appVer');
            if (av) { av.classList.remove('upd'); av.title = 'نسخهٔ کد — به‌روز است'; }
            if (manual) showToast('✓ نسخهٔ شما به‌روز است');
            reset(); return;
        }

        // نسخهٔ جدید موجود است
        VC_PENDING = true;
        vcBadge('جدید', 'tg');
        $('vcBtnUpdate').classList.remove('hidden');
        const av = $('appVer');
        if (av) { av.classList.add('upd'); av.title = 'نسخهٔ جدید موجود است — کلیک کنید'; }
        vcStat('⬆ نسخهٔ جدید: <code>' + esc(d.remote_id) + '</code> · ' +
               toFa((d.remote_size / 1024).toFixed(0)) + ' KB · '+esc(d.branch||''), '#fbbf24');
        reset();

        if (!d.deploy_ready) {
            vcStat('⬆ نسخهٔ جدید موجود است — اما رمز نصب‌کننده تنظیم نشده', '#fbbf24');
            if (manual) showToast('رمز نصب‌کننده را در «منبع و نصب‌کننده» وارد کنید', true);
            return;
        }

        // v8.46: کاری در جریان باشد یا نه، نصب انجام می‌شود. جایگزینی
        // اتمیک است و اجرای فعلی با نسخهٔ قبلی تمام می‌شود.
    const busy = vcBusy();
        if (busy) showToast('«' + busy + '» در جریان است — نصب بدون وقفه انجام می‌شود');

        // دکمهٔ دستی = کاربر خودش خواسته، پس همان‌جا نصب و رفرش می‌کنیم
        if (manual) { vcUpdate(true); return; }
        vcBanner(d);
    }).catch(() => {
        vcStat('✗ خطا در ارتباط', '#f87171');
        if (btn) { btn.disabled = false; btn.textContent = '🔍 بررسی و نصب نسخهٔ جدید'; }
    });
}

function vcBanner(d) {
    if (document.getElementById('vcBar')) return;
    const b = document.createElement('div');
    b.id = 'vcBar';
    b.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:99999;background:linear-gradient(135deg,#f59e0b,#f97316);' +
        'color:#1c1207;padding:11px 16px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;' +
        'font-family:var(--app-font,Tahoma,sans-serif);font-size:13px;font-weight:700;box-shadow:0 3px 14px rgba(0,0,0,.4);direction:rtl';
    b.innerHTML = '<span style="flex:1;min-width:200px">⬆ نسخهٔ جدیدی از کد روی گیت‌هاب موجود است' +
        ' <span style="opacity:.75;font-weight:400">(' + esc(d.remote_id) + ')</span></span>' +
        '<button id="vcGo" style="background:#0f172a;color:#fde68a;border:none;padding:8px 15px;border-radius:7px;' +
        'font-weight:700;cursor:pointer;font-family:inherit;font-size:12px">نصب کن</button>' +
        '<button id="vcNo" style="background:transparent;color:#1c1207;border:1px solid rgba(0,0,0,.35);' +
        'padding:8px 13px;border-radius:7px;cursor:pointer;font-family:inherit;font-size:12px">بعداً</button>';
    document.body.appendChild(b);
    document.body.style.paddingTop = (b.offsetHeight + 6) + 'px';
    document.getElementById('vcGo').onclick = () => { vcCloseBar(); vcUpdate(true); };
    document.getElementById('vcNo').onclick = vcCloseBar;
}
function vcCloseBar() {
    const b = document.getElementById('vcBar');
    if (b) b.remove();
    document.body.style.paddingTop = '';
}

/**
 * نصب: این تابع خودش چیزی نمی‌نویسد. یک فرم به deploy.php ارسال می‌کند
 * که فایلی مستقل است و کار نصب را با همان زنجیرهٔ ایمنی انجام می‌دهد.
 */
function vcUpdate(skipConfirm, requestedBranch) {
    const isExplicitBranch = !!(requestedBranch && String(requestedBranch).trim());
    const installBranch = (isExplicitBranch ? String(requestedBranch).trim() : '')
        || VC_PENDING_BRANCH || (VC && VC.branch) || ((VC && VC.branches && VC.branches[0]) || '');
    const busy = vcBusy();
    if (busy && !skipConfirm) {
        if (!confirm('«' + busy + '» در جریان است.\n\n'
            + 'نصب بدون توقف آن انجام می‌شود و کار جاری با نسخهٔ فعلی تمام می‌گردد.\n'
            + 'ادامه می‌دهید؟')) return;
    }

    const btn = $('vcBtnUpdate');
    const lock = () => { window._vcInstalling = true; if (btn) { btn.disabled = true; btn.textContent = '⏳ در حال نصب...'; } };
    const unlock = () => { window._vcInstalling = false; if (btn) { btn.disabled = false; btn.textContent = '⬇ نصب نسخهٔ جدید'; } };

    fetch('?vc_deploy_info=1').then(r => r.json()).then(d => {
        const useSelfUpdate = (!d.ok && d.can_self_update);
        if (!d.ok && !useSelfUpdate) {
            showToast(d.error || 'نصب‌کننده در دسترس نیست', true);
            vcStat('✗ ' + esc(d.error || ''), '#f87171');
            return;
        }
        if (!d.token && !d.nonce) {
            showToast('ابتدا رمز نصب‌کننده را در تنظیمات وارد کنید', true);
            vcStat('✗ رمز نصب‌کننده تنظیم نشده — بخش «منبع و نصب‌کننده»', '#fbbf24');
            return;
        }
        const installerLabel = useSelfUpdate ? 'نصب‌کنندهٔ داخلی (code_update)' : d.file;
        if (!skipConfirm && !confirm((isExplicitBranch ? ('نصب از برنچ «' + installBranch + '» انجام شود؟') : 'نسخهٔ جدید نصب شود؟')
            + '\n\nنصب توسط ' + installerLabel + ' انجام می‌شود و از نسخهٔ فعلی بکاپ گرفته خواهد شد.')) return;

        lock();
        vcCloseBar();
        showToast('⏳ در حال نصب از ' + (installBranch || 'گیت‌هاب') + '...');
        vcStat('<span style="opacity:.7">' + esc(installerLabel) + ' در حال نصب...</span>', '#93c5fd');

        /* v10.446: پیش از جایگزینی فایل، برنچ دستی را قفل و وضعیت auto-update را پاک کن
           تا پس از رفرش، حتی روی برنچ‌های قدیمی‌تر، حلقهٔ رفرش بی‌نهایت رخ ندهد. */
        const prepFd = new FormData();
        if (isExplicitBranch) {
            prepFd.append('pin_only', '1');
            prepFd.append('pin_branch', installBranch);
        } else {
            prepFd.append('unpin_only', '1');
        }
        return fetch('?vc_settings=1', { method: 'POST', body: prepFd, cache: 'no-store' })
            .catch(() => null)
            .then(() => {
                if (useSelfUpdate) {
                    const ufd = new FormData();
                    ufd.append('action', 'code_update');
                    if (d.token) ufd.append('token', d.token);
                    if (d.nonce) ufd.append('_wpnonce', d.nonce);
                    if (installBranch) ufd.append('branch', installBranch);
                    if (isExplicitBranch) ufd.append('allow_downgrade', '1');
                    return fetch('?code_update=1', { method: 'POST', body: ufd, cache: 'no-store' })
                        .then(r => r.json().catch(() => ({ ok: false, error: 'پاسخ نامعتبر از نصب‌کنندهٔ داخلی' })));
                }
                const fd = new FormData();
                fd.append('action',    'deploy');
                fd.append('api_token', d.token);
                fd.append('repo',      $('vcRepo').value.trim());
                fd.append('branch',    installBranch);
                fd.append('source',    $('vcPath').value.trim());
                fd.append('dest',      VC ? VC.self_name : '');
                fd.append('folder',    '');
                fd.append('check_php', '1');
                fd.append('backup',    '1');
                return fetch(d.file, { method: 'POST', body: fd, cache: 'no-store' })
                    .then(r => r.json().catch(() => ({ ok: false, error: 'پاسخ نامعتبر از نصب‌کننده' })));
            })
            .then(res => {
                if (!res || !res.ok) {
                    const errMsg = (res && res.error) ? res.error : 'نصب ناموفق';
                    vcStat('✗ ' + esc(errMsg), '#f87171');
                    showToast(errMsg, true);
                    fetch('?code_update_sync_state=1', { method: 'POST', cache: 'no-store' }).catch(() => {});
                    unlock();
                    return;
                }
                const syncFd = new FormData();
                if (installBranch) syncFd.append('branch', installBranch);
                return fetch('?code_update_sync_state=1', { method: 'POST', body: syncFd, cache: 'no-store' })
                    .then(r => r.ok ? r.json() : null).catch(() => null)
                    .then(syncRes => {
                        if (VC) {
                            VC.pinned_branch = isExplicitBranch ? installBranch : '';
                            if (installBranch) VC.branch = installBranch;
                            vcRenderBranches();
                        }
                        if (res.same || res.changed === false) {
                            vcStat('✓ این برنچ از قبل نصب و فعال بود', '#4ade80');
                            showToast('✓ این برنچ از قبل نصب بود');
                            $('vcBtnUpdate').classList.add('hidden');
                            unlock();
                            return;
                        }
                        const nextVer = (syncRes && syncRes.version) || res.to_version || res.version || 'جدید';
                        vcStat('✓ نصب شد' + (res.backup ? ' · بکاپ: <code>' + esc(res.backup) + '</code>' : '') +
                               ' — بارگذاری مجدد...', '#4ade80');
                        showToast('✓ به‌روزرسانی انجام شد — صفحه رفرش می‌شود');
                        s4ReloadForNewCode(nextVer, true);
                    });
            });
    }).catch(() => {
        showToast('خطا در ارتباط با نصب‌کننده', true);
        vcStat('✗ خطا در ارتباط', '#f87171');
        unlock();
    });
}

/* ---------- دراپ‌داون‌های جستجودار ---------- */
function vcLoadBranches(manual) {
    const repo = $('vcRepo').value.trim();
    if (!repo) { if (manual) showToast('ابتدا نام ریپو را وارد کنید', true); return Promise.resolve(); }
    const btn = $('vcBtnRepo');
    if (btn) { btn.disabled = true; btn.textContent = '⏳'; }
    return fetch('?vc_branches=1&repo=' + encodeURIComponent(repo)).then(r => r.json()).then(d => {
        if (!d.ok) { VC_BRANCHES = []; if (manual) showToast(d.error || 'ناموفق', true); return; }
        VC_BRANCHES = d.branches || [];
        if (manual) showToast('✓ ' + toFa(VC_BRANCHES.length) + ' برنچ');
        $('vcBranch').placeholder = 'کلیک یا تایپ کنید';
        return vcLoadFiles(false);
    }).catch(() => { if (manual) showToast('خطا در ارتباط', true); })
      .finally(() => { if (btn) { btn.disabled = false; btn.textContent = '🔄'; } });
}

function vcLoadFiles(manual) {
    const repo = $('vcRepo').value.trim(), branch = $('vcBranch').value.trim();
    if (!repo || !branch) return Promise.resolve();
    $('vcFileCount').textContent = 'در حال دریافت فهرست...';
    return fetch('?vc_files=1&repo=' + encodeURIComponent(repo) + '&branch=' + encodeURIComponent(branch))
        .then(r => r.json()).then(d => {
            if (!d.ok) { VC_FILES = []; $('vcFileCount').textContent = ''; if (manual) showToast(d.error || 'ناموفق', true); return; }
            VC_FILES = d.files || [];
            $('vcFileCount').textContent = toFa(VC_FILES.length) + ' فایل PHP';
            $('vcPath').placeholder = 'کلیک یا تایپ کنید';
        }).catch(() => { $('vcFileCount').textContent = ''; });
}

function vcRenderDrop(dropId, items, onPick, emptyMsg) {
    const box = $(dropId);
    if (!box) return;
    if (!items.length) {
        box.innerHTML = '<div class="vc-none">' + esc(emptyMsg || 'موردی یافت نشد') + '</div>';
        box.classList.add('open'); return;
    }
    box.innerHTML = items.map((it, i) =>
        '<div class="vc-opt" data-i="' + i + '"><span>' + esc(it.label) + '</span>' +
        '<span class="vc-meta">' + esc(it.meta || '') + '</span></div>').join('');
    box.querySelectorAll('.vc-opt').forEach(el => {
        el.onmousedown = e => { e.preventDefault(); onPick(items[+el.dataset.i]); };
    });
    box.classList.add('open');
}

function vcFilterBranch() {
    const q = $('vcBranch').value.trim().toLowerCase();
    if (!VC_BRANCHES.length) { vcRenderDrop('vcBranchDrop', [], () => {}, 'ابتدا دکمهٔ 🔄 را بزنید'); return; }
    const cur = VC ? VC.branch : '';
    const items = VC_BRANCHES.filter(b => b.name.toLowerCase().includes(q)).slice(0, 60)
        .map(b => ({ label: b.name, meta: (b.name === cur ? '● فعلی  ' : '') + b.sha, value: b.name }));
    vcRenderDrop('vcBranchDrop', items, it => {
        $('vcBranch').value = it.value;
        vcCloseDrops(); vcDirty(); VC_FILES = [];
