/* v8.87: پیش‌نمایش زندهٔ تعدیل قیمت مقصد.
   روی یک قیمت نمونه نشان می‌دهد نتیجه چه می‌شود، تا قبل از ذخیره معلوم
   باشد درصد درست وارد شده یا نه (مثلاً ۲۰- به‌جای ۲۰). */
function destAdjustPreviewNum(base,mode,val,round){
  if(!(base>0))return 0;
  let out=base;
  if(mode==='percent')out=base*(1+(val/100));
  else if(mode==='multiplier')out=val>0?base*val:base;
  out=Math.round(out);
  if(round>0)out=Math.round(out/round)*round;
  return out>0?out:base;
}
function syncWcPriceUi(from){
  /* v10.112: همگام فیلدهای تعدیل WC در همبرگر و تب تنظیمات */
  const pairs=[['wcPMode','wcPModeHb'],['wcPVal','wcPValHb'],['wcPRound','wcPRoundHb']];
  pairs.forEach(function(pr){
    const a=$(pr[0]), b=$(pr[1]);
    if(!a||!b)return;
    if(from==='hb'){ a.value=b.value; }
    else { b.value=a.value; }
  });
}
function destPricePreview(pre){
  if(pre==='wc'){
    /* اگر از همبرگر پر شده، اول همگام کن */
    try{ if($('wcPModeHb')&&$('wcPMode')) syncWcPriceUi(document.activeElement&&(document.activeElement.id||'').indexOf('Hb')>=0?'hb':'main'); }catch(e){}
  }
  const mEl=$(pre+'PMode'),vEl=$(pre+'PVal'),rEl=$(pre+'PRound'),out=$(pre+'PPrev');
  const outHb = pre==='wc' ? $('wcPPrevHb') : null;
  if(!mEl)return;
  const mode=mEl.value,val=parseFloat(vEl&&vEl.value)||0,round=parseInt(rEl&&rEl.value)||0;
  function paint(el){
    if(!el)return;
    if(mode==='none'){el.textContent='بدون تغییر — همان قیمت پروفایل به مقصد می‌رود';el.style.color='#94a3b8';return;}
    const sample=250000;
    const res=destAdjustPreviewNum(sample,mode,val,round);
    const diff=res-sample;
    const pct=sample>0?Math.round(diff/sample*1000)/10:0;
    el.style.color=diff>0?'#4ade80':(diff<0?'#fbbf24':'#94a3b8');
    el.textContent='نمونه پروفایل: '+toFa(sample.toLocaleString('en-US'))+' → مقصد: '
      +toFa(res.toLocaleString('en-US'))
      +'  ('+(diff>=0?'+':'')+toFa(pct)+'٪)';
  }
  paint(out); paint(outHb);
}
/* v10.420: destination pricing must update Results from the live controls,
   then persist through save_connections. Previously these handlers only
   painted the tiny preview; cn and the Results table retained old values. */
function destPricingChanged(pre){
  window._connHydrated=true;
  if(pre==='wc'){
    const fromHb=!!(document.activeElement&&(document.activeElement.id||'').indexOf('Hb')>=0);
    syncWcPriceUi(fromHb?'hb':'main');
  }
  const mode=(($(pre+'PMode')||{}).value||'none');
  const val=parseFloat(($(pre+'PVal')||{}).value)||0;
  const round=parseInt(($(pre+'PRound')||{}).value)||0;
  const key=pre==='wc'?'woocommerce':'basalam';
  if(!cn[key])cn[key]={};
  cn[key].price_mode=mode;cn[key].price_val=val;cn[key].price_round=round;
  destPricePreview(pre);
  try{if(typeof bslRefreshVendorPreviews==='function')bslRefreshVendorPreviews();}catch(e){}
  try{refreshViews();}catch(e){}
  scheduleConnSave();
}


/* v10.113: جدول مقایسه — سرورساید + progress + فقط خواندن صفحه */
window._smPage = 1;
window._smPoll = null;
window._smPollGeneration=0;window._smPollLastResponseAt=0;window._smPollWakeTimer=null;
window._smUserMoveEpoch=0;window._smRestoringViewport=false;
['wheel','touchstart','pointerdown','keydown'].forEach(ev=>window.addEventListener(ev,()=>{if(!window._smRestoringViewport)window._smUserMoveEpoch++;},{passive:true}));
function smCaptureViewport(){
  const el=$('smTableWrap');if(!el)return null;const r=el.getBoundingClientRect(),vh=window.innerHeight||document.documentElement.clientHeight||0;
  if(r.bottom<=0||r.top>=vh)return null;
  return {el:el,top:r.top,y:window.scrollY||window.pageYOffset||0,epoch:window._smUserMoveEpoch,left:el.scrollLeft,innerTop:el.scrollTop};
}
function smRestoreViewport(g){
  if(!g||!g.el||!g.el.isConnected)return;
  requestAnimationFrame(()=>{if(g.epoch!==window._smUserMoveEpoch)return;const now=g.el.getBoundingClientRect().top,dy=now-g.top;
    window._smRestoringViewport=true;if(Math.abs(dy)>.5)window.scrollBy(0,dy);g.el.scrollLeft=g.left;g.el.scrollTop=g.innerTop;
    requestAnimationFrame(()=>{window._smRestoringViewport=false;});
  });
}
function smFa(n){ try{ return toFa(String(n)); }catch(e){ return String(n); } }
function smMoney(n){
  n=parseInt(n)||0; if(n<=0) return '—';
  try{ return toFa(n.toLocaleString('en-US')); }catch(e){ return String(n); }
}
function smToneBg(t){
  return ({ok:'#14532d',price_high:'#3730a3',price_low:'#9a5b08',price_missing:'#991b1b',warn:'#713f12',bad:'#7f1d1d',missing_dst:'#1e3a8a',extra:'#334155',no_src:'#3f3f46',na:'#0f172a'})[t]||'#0f172a';
}
function smToneFg(t){
  return ({ok:'#dcfce7',price_high:'#e0e7ff',price_low:'#fff7d6',price_missing:'#fee2e2',warn:'#fef3c7',bad:'#fee2e2',missing_dst:'#dbeafe',extra:'#f1f5f9',no_src:'#e2e8f0',na:'#f1f5f9'})[t]||'#e2e8f0';
}
/* رنگ جهت قیمت فقط برای خانهٔ مقصد است: برابر سبز، بالاتر آبی، پایین‌تر نارنجی، ناموجود قرمز. */
function smDestinationPriceTone(actual, expected, exists){
  actual=parseInt(actual)||0; expected=parseInt(expected)||0;
  if(!exists) return 'price_missing';
  if(expected<=0||actual<=0) return 'no_src';
  if(actual===expected) return 'ok';
  return actual>expected?'price_high':'price_low';
}
function smDestinationCell(actual, expected, id, extra){
  const tone=smDestinationPriceTone(actual,expected,true);
  return smCell('<div style="font-weight:900">موجود</div><div>قیمت: '+smMoney(actual)+'</div>'
    +'<div style="font-size:9px;opacity:.82">قیمت مورد انتظار: '+smMoney(expected)+(id?' · #'+smFa(id):'')+'</div>'+(extra||''),tone);
}
function smCell(html, tone){
  const bg=smToneBg(tone), fg=smToneFg(tone);
  return '<td style="padding:7px 8px;border-bottom:1px solid #1e293b;background:'+bg+';color:'+fg+';vertical-align:top;line-height:1.55;overflow-wrap:anywhere">'+html+'</td>';
}
window._smSort='';window._smSortDir='asc';window._smColWidths={};window._smFilterData={destinations:[],profiles:[]};window._smFilterRules=[];
try{window._smSort=localStorage.getItem('s4_matrix_sort')||'';window._smSortDir=localStorage.getItem('s4_matrix_sort_dir')||'asc';window._smColWidths=JSON.parse(localStorage.getItem('s4_matrix_col_widths')||'{}')||{};window._smFilterRules=JSON.parse(localStorage.getItem('s4_matrix_filters')||'[]')||[];if($('smFilterJoin'))$('smFilterJoin').value=localStorage.getItem('s4_matrix_filter_join')==='or'?'or':'and';}catch(e){window._smFilterRules=[];}
function smFilterStaticOptions(type){
  const m={
    status:[['ok','یکسان'],['mismatch','مغایرت قیمت'],['missing','ناقص/ناموجود'],['only_profile','فقط مبدأ'],['only_dest','فقط مقصد'],['partial','نیمه‌کامل']],
    duplicate:[['any','هر نوع تکراری'],['profile','تکراری در پروفایل'],['woo','تکراری ووکامرس'],['bsl','تکراری باسلام']],
    presence:[['only_profile','فقط در مبدأ'],['only_dest','فقط در مقصد'],['in_all','موجود در همهٔ مقصدها'],['missing_any','حداقل در یک مقصد ناموجود']],
    price:[['has_price','دارای قیمت پروفایل'],['no_price','بدون قیمت پروفایل'],['woo_higher','قیمت واقعی WC بیشتر از انتظار'],['woo_lower','قیمت واقعی WC کمتر از انتظار']],
    code_suffix:[['has_code','دارای پسوند (کد:ایکس)'],['no_code','بدون پسوند (کد:ایکس)']]
  };return m[type]||[];
}
function smFilterOptions(type){if(type==='profile')return window._smFilterData.profiles||[];if(['present_dest','missing_dest','mismatch_dest'].includes(type))return window._smFilterData.destinations||[];return smFilterStaticOptions(type).map(x=>({value:x[0],label:x[1]}));}
function smRenderFilterValues(preferred){
  const type=($('smFilterType')||{}).value||'',sel=$('smFilterValue');if(!sel)return;const opts=smFilterOptions(type);
  const wanted=preferred!=null?String(preferred):String(sel.value||'');
  sel.innerHTML='<option value="">'+(type?'انتخاب نام فیلتر…':'نام فیلتر')+'</option>'+opts.map(o=>'<option value="'+esc(o.value)+'">'+esc(o.label)+'</option>').join('');
  sel.disabled=!type;if(opts.some(o=>String(o.value)===wanted))sel.value=wanted;
}
