function smPaintProgress(p){
  p=p||{};
  smShowJob(true);
  const ph=String(p.phase||''),wp=parseInt(p.woo_page||0)||0,wf=parseInt(p.woo_fetched||0)||0,bp=parseInt(p.page||0)||0;
  let pct=Math.max(0,Math.min(100,parseInt(p.pct)||0));
  /* v10.339: phaseهای destination عمداً pct ثابت داشتند و با وجود صد صفحه
     پیشرفت، UI روی ۳۲٪ به‌نظر یخ‌زده می‌ماند. */
  if((ph==='woo_fetch'||ph==='yielded')&&wp>0)pct=Math.max(pct,Math.min(47,32+Math.floor(wp/10)));
  if(ph.indexOf('bsl')>=0&&bp>0)pct=Math.max(pct,Math.min(80,50+Math.floor(bp/5)));
  if($('smJobPct')) $('smJobPct').textContent=smFa(pct)+'٪';
  if($('smJobFill')) $('smJobFill').style.width=pct+'%';
  if($('smJobLabel')){
    let detail='';if(wp>0&&(ph==='woo_fetch'||ph==='yielded'))detail=' · ووکامرس صفحه '+smFa(wp)+(wf?' · '+smFa(wf)+' محصول':'');else if(bp>0&&ph.indexOf('bsl')>=0)detail=' · باسلام صفحه '+smFa(bp);
    $('smJobLabel').textContent = p.running ? ('⏳ '+(ph||'در حال ساخت')+detail+'…') : (p.yielded?('↻ ادامهٔ خودکار'+detail+'…'):(p.done ? (p.error?'❌ خطا':'✅ تمام') : '—'));
  }
  if($('smJobLog') && Array.isArray(p.log)){
    const lines=p.log.slice(-80).map(x=> (x&&x.m)?x.m:String(x)),el=$('smJobLog'),sig=JSON.stringify(lines);
    if(el.dataset.logSig!==sig){
      const nearBottom=(el.scrollHeight-el.scrollTop-el.clientHeight)<28,oldTop=el.scrollTop;
      el.innerHTML=lines.map(l=>'<div style="border-bottom:1px solid #1e293b;padding:2px 0">'+esc(l)+'</div>').join('');el.dataset.logSig=sig;
      try{el.scrollTop=nearBottom?el.scrollHeight:oldTop;}catch(e){}
    }
  }
  const buildStop=$('smBuildStopBtn'), buildResume=$('smBuildResumeBtn'), buildStart=$('smBuildStartBtn');
  const isFix=(p.job==='fix'||String(p.phase||'').indexOf('fix')>=0||p.ok_n!=null);
  const isBuild=!!p.running&&!isFix;
  if(buildStop) buildStop.style.display=isBuild?'':'none';
  if(buildResume) buildResume.style.display=(!isFix&&!p.running && (!!p.stopped || !!p.partial || !!p.checkpoint))?'':'none';
  if(buildStart) buildStart.disabled=!!p.running;
  if(!p.running && p.stopped && $('smJobLabel')) $('smJobLabel').textContent='⏹ متوقف شد — ادامه از checkpoint آماده است';
  const stopBtn=$('smFixStopBtn');
  if(stopBtn) stopBtn.style.display = (p.running && (p.job==='fix' || p.phase==='woo_fix' || p.phase==='bsl_fix' || p.phase==='queued' || (p.ok_n!=null))) ? '' : (p.running && p.job==='fix' ? '' : stopBtn.style.display);
  if(stopBtn && p.running && (String(p.phase||'').indexOf('fix')>=0 || p.job==='fix' || p.ok_n!=null || p.phase==='woo_fix' || p.phase==='bsl_fix' || p.phase==='queued')){
    stopBtn.style.display='';
  }
  if(stopBtn && !p.running) stopBtn.style.display='none';
  const ban=$('smFixBanner');
  if(ban && (p.ok_n!=null || p.job==='fix' || String(p.phase||'').indexOf('fix')>=0 || String(p.phase||'').indexOf('send')>=0 || String(p.phase||'').indexOf('del')>=0 || p.phase==='queued' || p.phase==='start')){
    ban.style.display='block';
    ban.innerHTML = (p.running?'⏳ در حال مغایرت‌گیری… ':'')
      +'✅ '+smFa(p.ok_n||0)+' · ❌ '+smFa(p.fail_n||0)
      +' · '+smFa(p.cur||0)+'/'+smFa(p.total||0)
      +' · 💰'+smFa(p.price_n||0)+' · 📤'+smFa(p.sent_n||0)+' · 🗑'+smFa(p.del_n||0)
      +(p.phase?(' · '+esc(String(p.phase))):'');
  }
  if(isFix) smPaintFixCounterCards(p);
}
