  let destinations='';
  if(window._smVisibleIncludeWoo){const w=r.woo||null;destinations+=smRowDetailCard('🛒 ووکامرس',line('شناسه',w&&w.id?smFa(w.id):'ناموجود')+line('قیمت مورد انتظار',money(r.woo_expect))+line('قیمت واقعی',w?money(w.price):'ناموجود','#67e8f9')+line('اختلاف',w?smRowDelta(w.price,r.woo_expect):'—')+line('وضعیت محصول',esc(w&&w.status||'—'))+line('تکراری',w&&w.dup?'بله':'خیر'),w?'#7c3aed':'#b91c1c');}
  shops.forEach(sh=>{const c=r.shops&&(r.shops[sh.vendor_id]||r.shops[String(sh.vendor_id)]),exp=Number(c&&c.expect||r.bsl_expect)||0;destinations+=smRowDetailCard('🏪 '+esc(sh.name||('#'+sh.vendor_id)),line('شناسه غرفه',smFa(sh.vendor_id||0))+line('شناسه محصول',c&&c.id?smFa(c.id):'ناموجود')+line('قیمت مورد انتظار',money(exp))+line('قیمت واقعی',c?money(c.price):'ناموجود','#67e8f9')+line('اختلاف',c?smRowDelta(c.price,exp):'—')+line('موجودی',c&&c.stock!=null?smFa(c.stock):'—')+line('وضعیت',c&&c.status!=null?smFa(c.status):'—')+line('تکراری',c&&c.dup?'بله':'خیر'),c?'#0891b2':'#b91c1c');});
  const flags=(r.flags||[]).length?'<div style="color:#c4b5fd">'+(r.flags||[]).map(esc).join(' · ')+'</div>':'<div style="color:#94a3b8">بدون پرچم اضافی</div>';
  const ops='<ol style="margin:0;padding-right:22px;color:#fde68a">'+operations.map(x=>'<li style="padding:3px 0">'+esc(x)+'</li>').join('')+'</ol>';
  modal.innerHTML='<div style="width:min(1050px,98vw);max-height:calc(100dvh - 20px);min-height:0;background:#0f172a;border:1px solid #64748b;border-radius:14px;overflow:hidden;display:flex;flex-direction:column;direction:rtl"><header style="padding:11px 14px;background:linear-gradient(90deg,#312e81,#1e293b);display:flex;flex:0 0 auto;justify-content:space-between;align-items:center;gap:10px"><div><b style="color:#fff">🔧 جزئیات تفصیلی مغایرت</b><div style="font-size:10px;color:#c7d2fe;margin-top:3px">'+esc(r.title||r.bare||'—')+'</div></div><button class="btn btn-gray" type="button" onclick="document.getElementById(\'smRowDiscrepancyModal\').style.display=\'none\'">✕</button></header><div style="padding:11px;overflow:auto;min-height:0;flex:1 1 auto;overscroll-behavior:contain;display:grid;gap:10px"><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:10px">'+smRowDetailCard('📋 مشخصات و مبنای مقایسه',overview,'#6366f1')+smRowDetailCard('🧭 اقدام اصلاحی مورد انتظار',ops,'#d97706')+'</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:10px">'+destinations+'</div>'+smRowDetailCard('🏷 پرچم‌ها و تشخیص تکمیلی',flags,'#7c3aed')+'<div style="font-size:10px;color:#94a3b8;padding:2px 3px">این جزئیات از همان snapshot و ضرایب فعلی جدول ساخته شده است.</div><div id="smRowFixDebug" style="display:none;background:#020617;border:1px solid #475569;border-radius:9px;padding:9px;font-size:10px;overflow:auto"></div></div><footer style="flex:0 0 auto;padding:9px 12px;padding-bottom:max(9px,env(safe-area-inset-bottom));background:#1e293b;border-top:1px solid #475569;display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap"><button class="btn btn-gray" type="button" onclick="document.getElementById(\'smRowDiscrepancyModal\').style.display=\'none\'">بستن</button><button id="smRowFixRunBtn" class="btn btn-green" type="button" onclick="smRunRowFix('+index+')" style="font-weight:900">⚡ اجرای واقعی اصلاح همین ردیف</button></footer></div>';modal.style.display='flex';
}
function smRunRowFix(index){
  const r=(window._smVisibleRows||[])[Number(index)],btn=document.getElementById('smRowFixRunBtn'),box=document.getElementById('smRowFixDebug');if(!r||!box)return;
  const selected=smSelectedDestinations();if(!selected.length){showToast('حداقل یک مقصد را انتخاب کنید',1);return;}
  if(!confirm('اصلاح واقعی فقط همین ردیف انجام شود؟\n'+String(r.title||r.bare||'')))return;
  const request={action:'sync_matrix_fix_row',bare:String(r.bare||''),scope:'all',selected_destinations:selected,duplicate_keep:(($('smDuplicateKeep')||{}).value||'newest'),prefer_coded_duplicate:(($('smPreferCodedDuplicate')||{}).checked?'1':'')};
  box.style.display='block';box.innerHTML='<div style="color:#fde68a;font-weight:900;margin-bottom:6px">⏳ در حال اجرای واقعی…</div><div style="color:#93c5fd;font-size:10px">REQUEST</div><pre style="direction:ltr;text-align:left;white-space:pre-wrap;word-break:break-word">'+esc(JSON.stringify(request,null,2))+'</pre>';
  if(btn){btn.disabled=true;btn.textContent='⏳ در حال اصلاح…';}
  const fd=new FormData();Object.keys(request).forEach(k=>fd.append(k,Array.isArray(request[k])?JSON.stringify(request[k]):String(request[k])));
  fetch('',{method:'POST',body:fd}).then(async resp=>{let d=null,raw='';try{raw=await resp.text();d=JSON.parse(raw);}catch(e){d={ok:false,error:'پاسخ JSON معتبر نیست',http_status:resp.status,raw:raw};}return {status:resp.status,data:d};}).then(x=>{
    const d=x.data||{};box.innerHTML='<div style="color:'+(d.ok?'#86efac':'#fca5a5')+';font-weight:900;margin-bottom:6px">'+(d.ok?'✅ اصلاح واقعی انجام شد':'❌ اصلاح انجام نشد')+' · HTTP '+smFa(x.status)+'</div><div style="color:#93c5fd;font-size:10px">REQUEST</div><pre style="direction:ltr;text-align:left;white-space:pre-wrap;word-break:break-word">'+esc(JSON.stringify(request,null,2))+'</pre><div style="color:#c4b5fd;font-size:10px;margin-top:8px">RESPONSE / TRACE</div><pre style="direction:ltr;text-align:left;white-space:pre-wrap;word-break:break-word;max-height:330px;overflow:auto">'+esc(JSON.stringify(d,null,2))+'</pre>';
    if(d.ok){showToast('اصلاح همین ردیف با موفقیت انجام شد');setTimeout(()=>syncMatrixLoad(window._smPage||1,true),500);}else showToast(d.error||'اصلاح ردیف ناموفق بود',1);
  }).catch(e=>{box.innerHTML+='<div style="color:#fca5a5">NETWORK ERROR: '+esc(String(e))+'</div>';showToast('خطای شبکه در اصلاح ردیف',1);}).finally(()=>{if(btn){btn.disabled=false;btn.textContent='⚡ اجرای واقعی اصلاح همین ردیف';}});
}
function syncMatrixLoad(page, silent){
  page = page || 1; window._smPage = page;
  silent = !!silent;
  const body = $('smBody'), sum=$('smSummary'), meta=$('smMeta'), pager=$('smPager'), head=$('smHead');
  const viewport=silent?smCaptureViewport():null,requestId=(window._smLoadIssued=(window._smLoadIssued||0)+1);
  if(body && !silent) body.innerHTML='<tr><td style="padding:16px;text-align:center;color:#67e8f9">📖 خواندن صفحه از فایل سرور…</td></tr>';
  const fd = new FormData();
  fd.append('action','sync_matrix');
  fd.append('page', String(page));
  fd.append('per_page', String(($('smPer')||{}).value||50));
  fd.append('q', ($('smQ')||{}).value||'');
  fd.append('filters_json',JSON.stringify(window._smFilterRules||[]));
  fd.append('filter_join',($('smFilterJoin')||{}).value||'and');
  if(window._smSort){fd.append('sort',window._smSort);fd.append('sort_dir',window._smSortDir||'asc');}
  if(($('smLiveFill')||{}).checked) fd.append('live_fill','1');
  if(($('smOnlyProblem')||{}).checked) fd.append('only_problem','1');
  if(($('smOnlyMis')||{}).checked) fd.append('only_mismatch','1');
  if(($('smOnlyMiss')||{}).checked) fd.append('only_missing','1');
  if(($('smOnlyDup')||{}).checked) fd.append('only_dup','1');
  return fetch('', {method:'POST', body:fd}).then(r=>r.json()).then(d=>{
    if(requestId<(window._smLoadIssued||0))return;
    if(d && d.progress) smPaintProgress(d.progress);
    if(d && d.running && !silent){ syncMatrixPoll(); }
    if(!d || !d.ok){
      /* A background poll must never collapse a healthy table into one error row. */
      if(silent)return;
      if(d && d.need_build){
        if(body) body.innerHTML='<tr><td style="padding:16px;text-align:center;color:#fbbf24">هنوز جدولی روی سرور نیست. «🚀 ساخت روی سرور» را بزنید'
          +(d.running?' (در حال ساخت…)':'')+'</td></tr>';
        if(d.running) syncMatrixPoll();
        return;
      }
      if(body) body.innerHTML='<tr><td style="padding:12px;color:#f87171">خطا: '+(d&&d.error?d.error:'ناموفق')+'</td></tr>';
      return;
    }
    const renderSig=JSON.stringify([d.page,d.pages,d.per_page,d.total,d.row_count_all,d.generated_at,d.source,d.live_partial,d.selected_destinations,d.shops,d.summary,d.filtered_status_counts,d.filter_options,d.rows,d.woo_count,d.woo_error,d.bsl_error,d.sort,d.sort_dir]);
    if(silent&&window._smRenderSig===renderSig)return;
    window._smRenderSig=renderSig;window._smLoadApplied=requestId;
    if(d.done || (d.progress&&d.progress.done)) smShowJob(!!(d.progress&&d.progress.running));
    window._smFilteredTotal=parseInt(d.actionable_total!=null?d.actionable_total:d.total)||0;
    window._smFilteredOnlyDest=parseInt((d.filtered_status_counts||{}).only_dest)||0;
    if(d.filter_options){window._smFilterData=d.filter_options;smRenderFilterValues(($('smFilterValue')||{}).value||'');smRenderFilterRules();}
    const shops = d.shops||[],resultDests=Array.isArray(d.selected_destinations)?d.selected_destinations:[],includeWoo=!resultDests.length||resultDests.includes('woo');
    if(typeof d.sort==='string'){window._smSort=d.sort;window._smSortDir=d.sort_dir||'asc';}
    const colKeys=['select','n','action','title','profile','src_price','profile_price'];if(includeWoo)colKeys.push('woo_expect','woo_actual');
    let h = '<th data-col="select" style="padding:8px;text-align:center;border-bottom:1px solid #475569"><input type="checkbox" id="smSelectAllHead" title="انتخاب همهٔ ردیف‌های فیلترشده" onchange="smToggleSelectAllFiltered(this.checked)" style="width:17px;height:17px"></th>'+smTh('#','n',false)+smTh('اصلاح مغایرت','action',false)+smTh('عنوان تطبیقی (پروفایل یا مقصد)','title',true)+smTh('پروفایل','profile',true)
      +smTh('مبدأ','src_price',true)+smTh('قیمت پروفایل','profile_price',true);
    if(includeWoo)h+=smTh('WC انتظار','woo_expect',true)+smTh('WC واقعی','woo_actual',true);
    shops.forEach(s=>{
      const sk='shop:'+String(s.vendor_id||0);colKeys.push(sk);
      h += smTh('🏪 '+(s.name||('#'+s.vendor_id)),sk,true);
    });
    colKeys.push('status');h += smTh('وضعیت','status',true);
    if(head) head.innerHTML = h;
    smRenderCols(colKeys);

    const s = d.summary||{};
    if(sum){
      const chip=(lab,val,bg)=>'<span style="background:'+bg+';color:#fff;padding:4px 8px;border-radius:8px;font-weight:800">'+lab+': '+smFa(val||0)+'</span>';
      sum.innerHTML = chip('کل فایل',d.row_count_all||s.total,'#4c1d95')+chip('این فیلتر',d.total,'#5b21b6')+chip('یکسان',s.ok,'#166534')+chip('مغایرت',s.price_mismatch,'#b91c1c')
        +(includeWoo?chip('نیست در WC',s.missing_woo,'#1d4ed8'):'')+chip('نیست در غرفه',s.missing_bsl,'#0369a1')
        +chip('فقط مقصد',s.only_dest,'#475569')+chip('تکراری پروفایل',s.dup_profile,'#7c3aed');
    }
    const wc = d.woo_cfg||{}, bc=d.bsl_cfg||{};
    const when = d.generated_at ? new Date(d.generated_at*1000).toLocaleString('fa-IR') : '—';
    window._smLastPages = d.pages||1;
    if(meta){
      meta.innerHTML = (d.live_partial?'🟢 نمایش زندهٔ بسته‌های دریافت‌شده · ':'📖 از فایل سرور · ')+when+' · منبع '+(d.source||'—')
        +' · صفحه '+smFa(d.page)+'/'+smFa(d.pages)+' · نمایش '+smFa(d.total)+' ردیف فیلترشده'
        +' · همهٔ محصولات پروفایل‌ها و مقصدهای انتخابی (ردیف «فقط مقصد» عمداً برای شناسایی محصول اضافی نمایش داده می‌شود)'
        +((d.filters||[]).length?' · 🔎 '+smFa(d.filters.length)+' فیلتر ('+(d.filter_join==='or'?'OR':'AND')+')':'')
        +(includeWoo?(' · WC: '+smFa(d.woo_count||0)+' · dest WC: '+(wc.mode||'none')+(wc.mode&&wc.mode!=='none'?(' '+wc.val):'')+(d.woo_error?(' · ⚠️ WC: '+d.woo_error):'')):' · WC خارج از شمول')
        +(d.bsl_error?(' · ⚠️ BSL: '+d.bsl_error):'');
    }
    try{ smPaintReports(d); }catch(e){}
    const rows = d.rows||[];
    window._smCurrentRows=rows;
    const selSig=JSON.stringify({q:($('smQ')||{}).value||'',rules:window._smFilterRules||[],join:($('smFilterJoin')||{}).value||'and',problem:!!(($('smOnlyProblem')||{}).checked),mis:!!(($('smOnlyMis')||{}).checked),miss:!!(($('smOnlyMiss')||{}).checked),dup:!!(($('smOnlyDup')||{}).checked)});if(window._smSelectionFilterSig&&window._smSelectionFilterSig!==selSig)smClearSelection();window._smSelectionFilterSig=selSig;
    window._smVisibleRows=rows;
    window._smVisibleShops=shops;
    window._smVisibleIncludeWoo=includeWoo;
    if(!rows.length){
      if(body) body.innerHTML='<tr><td colspan="20" style="padding:16px;text-align:center;color:#94a3b8">ردیفی در این فیلتر/صفحه نیست</td></tr>';
    } else if(body){
      const start = ((d.page||1)-1)*(d.per_page||50);
      body.innerHTML = rows.map((r,i)=>{
        if(r && (r.is_report || (r.bare||'').indexOf('__report_')===0)){
          const lines=(r.report_lines||[]).map(x=>'<div style="padding:2px 0;border-bottom:1px solid #33415544">'+esc(String(x))+'</div>').join('');
          const bg = (r.report_type==='work') ? '#1e3a5f' : '#14532d';
          let tr='<tr style="background:'+bg+'">';
          tr += smCell('','na');
          tr += smCell(smFa(start+i+1),'na');
          tr += '<td colspan="'+ Math.max(1,colKeys.length-2) +'" style="padding:10px 12px;border-bottom:1px solid #334155;color:#e2e8f0;vertical-align:top">';
          tr += '<div style="font-weight:900;font-size:12px;margin-bottom:6px;color:#fde68a">'+esc(r.title||'گزارش')+'</div>';
          tr += '<div style="font-size:11px;color:#bbf7d0;margin-bottom:6px">'+esc(r.report_text||'')+'</div>';
          tr += '<div style="font-size:10.5px;line-height:1.7;max-height:160px;overflow:auto">'+lines+'</div>';
          tr += '</td></tr>';
          return tr;
        }
        const stMap={ok:['✅ یکسان','ok'],mismatch:['❌ مغایرت','bad'],missing:['📤 ناقص','missing_dst'],only_profile:['📘 فقط مبدأ','missing_dst'],only_dest:['📦 فقط مقصد؛ در پروفایل نیست','extra'],partial:['➖ ناقص','warn'],removed:['🗑 حذف‌شد','extra'],only_dest_removed:['🗑 حذف‌شد','extra'],report:['📋 گزارش','na']};
        const st=stMap[r.status]||['?','na'];
        let flags='';
        (r.flags||[]).forEach(f=>{
          if(String(f).indexOf('dup')===0) flags+=' <span style="background:#6d28d9;color:#fff;border-radius:4px;padding:0 5px;font-size:10px">تکراری</span>';
        });
        if((r.profile_duplicate_hits||0)>0) flags+=' <span style="color:#e9d5ff;font-size:10px">'+smFa((r.profile_duplicate_hits||0)+1)+' عنوان دقیقاً یکسان در پروفایل</span>';
        let tr = '<tr>';
        tr += smCell('<input type="checkbox" class="sm-row-check" data-bare="'+esc(r.bare||'')+'" '+(smRowIsSelected(r.bare)?'checked':'')+' onchange="smToggleRowSelection(this.dataset.bare,this.checked)" onclick="event.stopPropagation()" style="width:17px;height:17px">','na');
        tr += smCell(smFa(start+i+1),'na');
        tr += smCell('<button type="button" class="btn btn-purple" onclick="smOpenRowDiscrepancy('+i+')" style="font-size:10px;padding:7px 10px;white-space:nowrap;width:100%;font-weight:900;box-shadow:0 3px 10px #4c1d9588">🔧 اصلاح مغایرت</button>','na');
        const onlyDest=r.status==='only_dest'||!(r.profile_hits||0);
        const originBadge=onlyDest?'<div style="margin-top:3px"><span style="background:#475569;color:#f8fafc;border-radius:4px;padding:1px 6px;font-size:9px">عنوان از مقصد؛ در پروفایل ذخیره‌شده نیست</span></div>':'';
        tr += smCell('<div style="font-weight:700;max-width:220px">'+esc(r.title||r.bare||'')+'</div>'+originBadge+'<div style="font-size:9px;opacity:.7;direction:ltr">'+esc(r.bare||'')+'</div>','na');
        tr += smCell(onlyDest?'<b style="color:#fca5a5">وجود ندارد</b>':(esc(r.profile||'—')+(r.profile_key?' <span style="opacity:.6">('+esc(r.profile_key)+')</span>':'')),onlyDest?'extra':'na');
        tr += smCell(smMoney(r.src_price), r.src_price>0?'na':'no_src');
        tr += smCell(smMoney(r.profile_price), r.profile_price>0?'na':'no_src');
        if(includeWoo){
          tr += smCell(smMoney(r.woo_expect), r.woo_expect>0?'na':'no_src');
          if(r.woo)tr += smDestinationCell(r.woo.price,r.woo_expect,r.woo.id,'<div style="font-size:9px;opacity:.75">'+esc(r.woo.status||'')+'</div>');
          else tr += smCell('<b>ناموجود</b>','price_missing');
        }
        shops.forEach(s=>{
          const cell = (r.shops&&r.shops[s.vendor_id]) ? r.shops[s.vendor_id] : null;
          if(cell){
            const exp = cell.expect||r.bsl_expect||0;
            tr += smDestinationCell(cell.price,exp,cell.id,cell.dup?' <b>تکراری</b>':'');
          } else {
            tr += smCell('<b>ناموجود</b>','price_missing');
          }
        });
        const rowErr=String(r.fix_error||'').trim(),rowPending=String(r.fix_pending||'').trim();
        tr += smCell(rowErr?('<b>❌ '+esc(rowErr)+'</b><div style="font-size:9px;opacity:.75;margin-top:3px">در عبور بعدی موقتاً رد می‌شود</div>'):(rowPending?('<b>🧵 '+esc(rowPending)+'</b><div style="font-size:9px;opacity:.75;margin-top:3px">اصلاح اصلی بدون توقف ادامه دارد</div>'):(st[0]+flags)), rowErr?'bad':(rowPending?'warn':st[1]));
        tr += '</tr>';
        return tr;
      }).join('');
      smUpdateSelectionUi();
    }
    if(pager){
      let pg='';
      const mk=(lab,p,dis)=>'<button class="btn '+(p===d.page?'btn-purple':'btn-gray')+'" '+(dis?'disabled':'')+' onclick="syncMatrixLoad('+p+')" style="font-size:11px;padding:5px 10px">'+lab+'</button>';
      pg += mk('«', Math.max(1,d.page-1), d.page<=1);
      const a=Math.max(1,d.page-2), b=Math.min(d.pages,d.page+2);
      for(let p=a;p<=b;p++) pg += mk(smFa(p), p, false);
      pg += mk('»', Math.min(d.pages,d.page+1), d.page>=d.pages);
      pager.innerHTML = pg;
    }
    if(silent)smRestoreViewport(viewport);
  }).catch(e=>{
    /* Keep the previous matrix intact when an automatic refresh transiently fails. */
    if(!silent && body) body.innerHTML='<tr><td style="padding:12px;color:#f87171">خطای شبکه: '+esc(String(e))+'</td></tr>';
  });
}
/* مرحلهٔ پایانی بارگذاری: نتیجهٔ کش‌شده فوراً و سبک خوانده می‌شود و فقط
   اگر مقصدها/ضرایب عوض شده یا نتیجه قدیمی است، rebuild به worker سپرده می‌شود. */
function syncMatrixAutoLate(){
  try{
    const selected=smSelectedDestinations();if(!selected.length)return;
    const fd=new FormData();fd.append('action','sync_matrix_status');fd.append('selected_destinations',JSON.stringify(selected));
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
      if(!d||!d.ok)return;
      if(d.has_result)syncMatrixLoad(1,true);
      if(d.running){smPaintProgress(d.progress||{});syncMatrixPoll();return;}
      const have=(d.result_destinations||[]).map(String).sort(),want=selected.map(String).sort();
      const scopeChanged=JSON.stringify(have)!==JSON.stringify(want);
      const stale=!d.has_result||scopeChanged||!!d.result_pricing_stale||Number(d.result_age_sec||0)>1800;
      if(stale)syncMatrixStart(false,true);
    }).catch(()=>{});
  }catch(e){}
}
function syncMatrixPollingBootstrap(){
  syncMatrixPollingWake('bootstrap');
  /* Destinations/settings may finish hydrating just after DOMContentLoaded. */
  setTimeout(syncMatrixAutoLate,900);
  setTimeout(()=>syncMatrixPollingWake('bootstrap-settled'),2500);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',syncMatrixPollingBootstrap,{once:true});
else syncMatrixPollingBootstrap();
window.addEventListener('load',()=>setTimeout(syncMatrixAutoLate,6000));

