/* v10.83: تیک همیشه-فعال تولید خودکار توضیح/دسته */
function aiContentAutoSave(){
  try{ if(typeof scheduleConnSave==='function') scheduleConnSave();
       else if(typeof saveConn==='function'){ window._connSaveNoToast=true; saveConn(); }
  }catch(e){}
  aiContentAutoRefreshStat();
}
function aiContentAutoRefreshStat(){
  const el=$('aiContentAutoStat'); if(!el)return;
  fetch('?ai_content_auto_status=1').then(r=>r.json()).then(d=>{
    if(!d||!d.ok){el.textContent='';return;}
    const on=d.cfg&&d.cfg.enabled;
    el.innerHTML=(on?'<span style="color:#34d399">● فعال</span>':'<span style="color:#64748b">○ خاموش</span>')
      +' · نیاز به محتوا: <b style="color:#fbbf24">'+toFa(d.products_need||0)+'</b> از '+toFa(d.products_total||0);
  }).catch(()=>{});
}
function aiContentAutoRunNow(){
  const el=$('aiContentAutoStat');
  if(el)el.textContent='⏳ شروع پس‌زمینه…';
  const lim=parseInt(($('aiContentAutoPerRun')||{}).value)||8;
  fetch('?aicontent_start=1&limit='+encodeURIComponent(lim)).then(r=>r.json()).then(d=>{
    if(!d){showToast('پاسخ خالی',1);return;}
    if(d.running&&d.error){showToast(d.error,1);if(el)el.textContent=d.error;return;}
    if(d.ok||d.started){
      showToast('📝 توضیح‌ساز در پس‌زمینه شروع شد — مدیر وظیفه را ببینید');
      if(el)el.textContent='در حال اجرا در سرور…';
      aicontentWatch(true);
      try{ if(typeof tmOpen==='function' && typeof tmPulse==='function'){ tmPulse(); } }catch(e){}
    }else showToast('خطا: '+(d.error||'?'),1);
    aiContentAutoRefreshStat();
  }).catch(()=>{showToast('خطا شبکه',1);if(el)el.textContent='';});
}
let _aicWatch=null,_aicLogSince=0;
function aicontentOpen(){
  try{
    if(typeof switchMainTab==='function') switchMainTab('settings');
    if(typeof toggleSmenu==='function'){
      /* ensure AI smenu open */
      document.querySelectorAll('.smenu-hdr').forEach(h=>{
        if((h.textContent||'').indexOf('هوش مصنوعی')>=0){
          const b=h.parentElement&&h.parentElement.querySelector('.smenu-body');
          if(b&&getComputedStyle(b).display==='none') h.click();
        }
      });
    }
    if(typeof aiTab==='function') aiTab('content_gen');
  }catch(e){}
  const box=$('aiContentJobBox');
  if(box){ box.scrollIntoView({behavior:'smooth',block:'nearest'}); box.style.boxShadow='0 0 0 2px #34d399'; setTimeout(()=>{box.style.boxShadow='';},1600); }
  aicontentRefreshLog();
  aicontentWatch(true);
}
function aicontentStop(){
  fetch('?aicontent_stop=1').then(r=>r.json()).then(d=>{
    showToast(d&&d.ok?'⏹ توقف ثبت شد':('خطا'), !(d&&d.ok));
    aicontentWatch(true);
  }).catch(()=>showToast('خطا شبکه',1));
}
function aicontentWatch(force){
  if(_aicWatch) clearInterval(_aicWatch);
  const tick=()=>{
    fetch('?aicontent_status=1&since=0').then(r=>r.json()).then(d=>{
      if(!d)return;
      const badge=$('aicontentJobBadge');
      const line=$('aicontentProgLine');
      const barW=$('aicontentBarWrap');
      const bar=$('aicontentBar');
      const run=!!d.running && !d.done;
      if(badge){
        badge.innerHTML=run
          ? '<span style="color:#4ade80">● در حال اجرا</span>'
          : (d.done?'<span style="color:#94a3b8">✓ تمام</span>':'<span style="color:#64748b">○ بی‌کار</span>');
      }
      if(line){
        const bits=[];
        if(d.phase) bits.push(esc(d.phase));
        if(d.total>0) bits.push(toFa(d.current||0)+' از '+toFa(d.total));
        if(d.filled) bits.push('پرشد '+toFa(d.filled));
        if(d.failed) bits.push('ناموفق '+toFa(d.failed));
        if(d.last_title) bits.push('↳ '+esc(d.last_title));
        line.textContent=bits.join(' · ');
      }
      if(barW&&bar){
        if(run||d.done){
          barW.style.display='block';
          const pct=d.total>0?Math.min(100,Math.round(100*(d.current||0)/d.total)):(run?15:100);
          bar.style.width=pct+'%';
        }else barW.style.display='none';
      }
      if(!run){ aicontentRefreshLog(); if(_aicWatch){clearInterval(_aicWatch);_aicWatch=null;} }
    }).catch(()=>{});
  };
  tick();
  if(force!==false) _aicWatch=setInterval(tick, 2500);
}
function aicontentRefreshLog(){
  fetch('?aicontent_items=1&limit=60').then(r=>r.json()).then(d=>{
    const box=$('aicontentCards'); if(!box)return;
    const items=(d&&d.items)||[];
    if(!items.length){ box.innerHTML='<div style="grid-column:1/-1;color:#64748b;font-size:11px;padding:12px;text-align:center">هنوز کارتی نیست — یک نوبت اجرا کنید.</div>'; return; }
    box.innerHTML=items.map(it=>{
      const st=it.status||'';
      const col=st==='ok'?'#065f46':(st==='fail'?'#7f1d1d':(st==='skip'?'#334155':'#1e3a5f'));
      const bdr=st==='ok'?'#34d399':(st==='fail'?'#f87171':'#475569');
      const cid=it.bsl_category_id?('#'+it.bsl_category_id):'';
      return '<button type="button" class="aic-card" data-id="'+esc(it.id||'')+'" onclick="aicontentShowItem(\''+jsAttr(it.id||'')+'\')" '
        +'style="text-align:right;background:#0f172a;border:1px solid '+bdr+';border-radius:10px;padding:8px 9px;cursor:pointer;color:#e2e8f0">'
        +'<div style="font-size:11px;font-weight:800;line-height:1.45;max-height:2.8em;overflow:hidden">'+esc(it.title||'—')+'</div>'
        +'<div style="font-size:9.5px;color:#94a3b8;margin-top:4px">'+esc(it.profile_name||it.profile_key||'')+'</div>'
        +'<div style="display:flex;justify-content:space-between;align-items:center;margin-top:6px;gap:4px">'
        +'<span style="font-size:9px;background:'+col+';color:#fff;padding:1px 6px;border-radius:6px">'+esc(st||'—')+'</span>'
        +'<span style="font-size:9.5px;color:#a7f3d0">'+esc(cid|| (it.category||'').slice(0,18))+'</span>'
        +'</div>'
        +(it.variations_text?('<div style="font-size:9px;color:#fbbf24;margin-top:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">🎛 '+esc(String(it.variations_text).slice(0,48))+'</div>'):'')
        +'</button>';
    }).join('');
  }).catch(()=>{});
}
function aicontentShowItem(id){
  if(!id)return;
  fetch('?aicontent_items=1&id='+encodeURIComponent(id)).then(r=>r.json()).then(d=>{
    if(!d||!d.ok||!d.item){showToast('مورد یافت نشد',1);return;}
    const it=d.item;
    const m=$('aicontentModal'), body=$('aicontentModalBody'), tit=$('aicontentModalTitle');
    if(tit) tit.textContent=it.title||'جزئیات';
    if(body){
      body.innerHTML=
        '<div style="margin-bottom:10px;font-size:11px;color:#94a3b8">'
        +esc(it.profile_name||'')+' · وضعیت: <b style="color:#e2e8f0">'+esc(it.status||'')+'</b>'
        +(it.model?(' · مدل: '+esc(it.model)):'')
        +'</div>'
        +(it.error?('<div style="background:#450a0a;border:1px solid #7f1d1d;border-radius:8px;padding:8px;margin-bottom:10px;color:#fecaca">'+esc(it.error)+'</div>'):'')
        +'<div style="margin-bottom:8px"><b style="color:#67e8f9">دسته:</b> '+esc(it.category||'—')
        +(it.bsl_category_id?(' <span style="color:#a7f3d0">· باسلام #'+it.bsl_category_id+(it.bsl_category_name?(' — '+esc(it.bsl_category_name)):'' )+'</span>'):'')
        +'</div>'
        +'<div style="margin-bottom:8px"><b style="color:#fbbf24">تنوع‌ها</b><div style="background:#111c31;border-radius:8px;padding:8px;margin-top:4px;white-space:pre-wrap;color:#e2e8f0">'
        +(function(){
          if(it.variations_text) return esc(it.variations_text);
          const gs=it.variation_groups||[];
          if(gs.length) return gs.map(g=>esc((g.name||'گزینه')+': '+((g.values||[]).join('، ')))).join('\n');
          if((it.variations||[]).length) return esc((it.variations||[]).join('، '));
          return '—';
        })()
        +'</div></div>'
        +'<div style="margin-bottom:8px"><b style="color:#94a3b8">معرفی کوتاه</b><div style="background:#111c31;border-radius:8px;padding:8px;margin-top:4px;white-space:pre-wrap">'+esc(it.short_description||'—')+'</div></div>'
        +'<div><b style="color:#94a3b8">توضیحات HTML</b>'
        +'<div style="background:#fff;color:#0f172a;border-radius:8px;padding:12px;margin-top:4px;max-height:280px;overflow:auto;font-size:12px;line-height:1.8">'+(it.description_html||'<span style="color:#94a3b8">—</span>')+'</div></div>';
    }
    if(m){ m.style.display='flex'; m.style.alignItems='center'; m.style.justifyContent='center';
      m.style.position='fixed'; m.style.inset='0'; m.style.background='rgba(0,0,0,.55)';
      document.body.classList.add('modal-open');
    }
  }).catch(()=>showToast('خطا شبکه',1));
}
function aicontentCloseModal(){
  const m=$('aicontentModal'); if(m) m.style.display='none';
  document.body.classList.remove('modal-open');
}


function aiRunContentGen(){
  const inp = $('aiGenProdTitle');
  const title = (inp ? inp.value : '').trim();
  if(!title){
    if(inp){ inp.focus(); inp.style.borderColor = '#ef4444'; setTimeout(()=>inp.style.borderColor='#3b82f6', 600); }
    showToast('لطفاً عنوان محصول را وارد کنید', 1);
    return;
  }

  const webSearch = $('aiGenWebSearch') ? $('aiGenWebSearch').checked : true;
  const btn = $('btnAiRunGen');
  const statusBox = $('aiGenStatusBox');
  const resultsCard = $('aiGenResultsCard');

  if(btn) { btn.disabled = true; btn.innerHTML = '<span>⏳</span> در حال پردازش و استعلام هوش مصنوعی...'; }
  if(resultsCard) resultsCard.style.display = 'none';
  if(statusBox){
    statusBox.style.display = 'block';
    statusBox.innerHTML = '<div style="color:#38bdf8">🔄 گام ۱: جستجو در وب برای یافتن مشخصات و توضیحات کالا...</div>'
      + '<div style="color:#64748b;margin-top:4px">گام ۲: ارسال اطلاعات به مدل مستر جهت نگارش و تعیین دسته...</div>';
  }

  const fd = new FormData();
  fd.append('action', 'ai_generate_product_content');
  fd.append('title', title);
  fd.append('web_search', webSearch ? '1' : '0');

  fetch('?ai_generate_product_content=1', {
    method: 'POST',
    body: fd
  })
  .then(r => r.json())
  .then(d => {
    if(btn) { btn.disabled = false; btn.innerHTML = '<span>🚀</span> جستجو در وب و ساخت هوشمند توضیحات و دسته‌بندی'; }
    if(!d || !d.ok){
      if(statusBox){
        statusBox.style.display = 'block';
        statusBox.innerHTML = '<div style="color:#f87171">❌ خطا: ' + esc((d && d.error) || 'عدم دریافت پاسخ معتبر از هوش مصنوعی') + '</div>';
      }
      showToast('خطا در تولید توضیحات', 1);
      return;
    }

    if(statusBox){
      statusBox.style.display = 'block';
      statusBox.innerHTML = '<div style="color:#34d399;font-weight:700">✅ تولید با موفقیت تکمیل شد!</div>'
        + '<div style="color:#94a3b8;font-size:10.5px;margin-top:3px">مدل استفاده‌شده: ' + esc(d.model_used) + ' | وضعیت جستجو: ' + (d.web_search_found ? ('یافت شد (' + esc(d.web_source) + ')') : 'عدم مشاهده در وب، نگارش مستقیم توسط هوش مصنوعی') + '</div>';
    }

    if(resultsCard){
      resultsCard.style.display = 'block';
      const mBadge = $('aiGenModelBadge');
      if(mBadge) mBadge.textContent = 'مدل: ' + (d.model_used || 'هوش مصنوعی');
      const wBadge = $('aiGenWebBadge');
      if(wBadge) wBadge.textContent = d.web_search_found ? ('منبع وب: ' + (d.web_source || 'وب')) : 'نگارش مستقیم هوش مصنوعی';

      const catInp = $('aiGenResCat');
      if(catInp) catInp.value = d.category || 'کالای عمومی';
      const bslEl = $('aiGenResBsl');
      if(bslEl){
        if(d.bsl_category_id){
          bslEl.style.display='block';
          bslEl.textContent='🟢 باسلام: #'+d.bsl_category_id+(d.bsl_category_name?(' — '+d.bsl_category_name):'')+(d.bsl_category_via?(' ('+d.bsl_category_via+')'):'');
        }else{
          bslEl.style.display='block';
          bslEl.textContent='⚠️ شناسهٔ باسلام نگاشت نشد — نام دسته ذخیره شد؛ auto_category هنگام ارسال کمک می‌کند';
        }
      }

      const shortBox = $('aiGenResShort');
      if(shortBox) shortBox.value = d.short_description || '';
      let varEl = $('aiGenResVars');
      if(!varEl){
        const catWrap = $('aiGenResCat') && $('aiGenResCat').parentElement;
        if(catWrap){
          varEl = document.createElement('div');
          varEl.id = 'aiGenResVars';
          varEl.style.cssText = 'margin-top:8px;font-size:11px;color:#fbbf24;display:none';
          catWrap.appendChild(varEl);
        }
      }
      if(varEl){
        const vt = d.variations_text || (Array.isArray(d.variation_groups)?d.variation_groups.map(g=>(g.name||'')+': '+((g.values||[]).join('، '))).join(' | '):'') || (Array.isArray(d.variations)?d.variations.join('، '):'');
        if(vt){ varEl.style.display='block'; varEl.textContent='🎛 تنوع‌ها: '+vt; }
        else { varEl.style.display='none'; varEl.textContent=''; }
      }

      const pBox = $('aiGenPreviewBox');
      if(pBox) pBox.innerHTML = d.description_html || '';

      const hBox = $('aiGenHtmlBox');
      if(hBox) hBox.value = d.description_html || '';

      aiSwitchGenTab('preview');
      resultsCard.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  })
  .catch(err => {
    if(btn) { btn.disabled = false; btn.innerHTML = '<span>🚀</span> جستجو در وب و ساخت هوشمند توضیحات و دسته‌بندی'; }
    if(statusBox){
      statusBox.style.display = 'block';
      statusBox.innerHTML = '<div style="color:#f87171">❌ خطای ارتباط با سرور یا شبکه.</div>';
    }
    showToast('خطای ارتباط با سرور', 1);
  });
}

function aiCandReplyRun(){
  const inp=$('aiCandReplyInput');const t=(inp?inp.value:'').trim();if(!t){if(inp)inp.focus();return;}
  const body=$('aiCandReplyBody'); if(!body)return;
  body.innerHTML='<div style="color:#93c5fd;font-size:11px">⏳ در حال پرسیدن از همهٔ کاندیدها...</div>';
  fetch('?ai_candidates_reply=1&msg='+encodeURIComponent(t)).then(r=>r.json()).then(d=>{
    if(!body)return;
    if(!d.ok){body.innerHTML='<div style="color:#fca5a5;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>';return;}
    const items=d.items||[];
    aiCandCtx={task:'autoreply',input:t,keys:items.map(x=>x.key),items:items};
    let h='<div style="font-size:11px;color:#67e8f9;font-weight:700;margin-bottom:8px">💬 «'+esc(t)+'» — پاسخ '+toFa(items.length)+' کاندید (مستر ⭐ مرجعِ مقایسه)</div>';
    items.forEach((it,idx)=>{
      const isM=(it.key===d.master);
      h+='<div style="border:1px solid '+(isM?'#fbbf24':'#334155')+';border-radius:8px;padding:8px;margin-bottom:8px;background:#111c31">'
        +'<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;flex-wrap:wrap">'
        +'<span style="color:'+(isM?'#fbbf24':'#e2e8f0')+';font-weight:700">'+esc(it.providerName)+(isM?' <span style="font-size:9px;color:#fbbf24">⭐ مستر</span>':'')+'</span>'
        +'<span style="color:#64748b;font-size:9px" dir="ltr">'+esc(it.model||'')+' · '+toFa(it.latency||0)+'ms</span></div>'
        +'<div style="margin-top:5px;color:'+(it.ok?'#e9d5ff':'#f87171')+';white-space:pre-wrap;font-size:12px">'+esc(it.ok?it.text:(it.error||'پاسخی نیامد'))+'</div>'
        +'<button class="btn btn-green" style="margin-top:6px;font-size:10px;padding:3px 10px" onclick="aiCandVote(\'autoreply\','+idx+')">✓ این بهتر بود (رای)</button>'
        +'</div>';
    });
    body.innerHTML=h;
  }).catch(()=>{if(body)body.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا شبکه</div>';});
}
function aiCandLeaderboard(){
  aiCandLoad(d=>{
    const r=$('aiCandR'); if(!r)return;
    const c=d.candidates||[];
    let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;font-size:11px;line-height:1.8">'
      +'<div style="color:#67e8f9;font-weight:700">📊 جدول امتیازات مدل‌های کاندید</div>';
    if(!c.length){h+='<div style="color:#64748b;padding:8px 0">کاندیدی نیست.</div>';}
    else{
      h+='<table style="width:100%;border-collapse:collapse;margin-top:6px;font-size:11px">'
        +'<tr style="background:#1e293b;color:#94a3b8"><th style="padding:5px;text-align:right">مدل</th><th>برد</th><th>شرکت</th><th>درصد برد</th><th>مستر</th></tr>';
      c.forEach(x=>{
        const pct=x.votes?Math.round(x.score*100)+'٪':'—';
        h+='<tr style="border-bottom:1px solid #1e293b"><td style="padding:5px;color:#e2e8f0">'+esc(x.providerName)+' · <span dir="ltr">'+esc(x.modelName||x.model)+'</span></td>'
          +'<td style="padding:5px;text-align:center;color:#4ade80">'+toFa(x.wins)+'</td>'
          +'<td style="padding:5px;text-align:center;color:#94a3b8">'+toFa(x.votes)+'</td>'
          +'<td style="padding:5px;text-align:center;color:#fbbf24">'+pct+'</td>'
          +'<td style="padding:5px;text-align:center">'+(x.key===d.master?'⭐':'')+'</td></tr>';
      });
      h+='</table>';
    }
    h+='<div style="color:#94a3b8;font-size:10px;margin-top:6px">آخرین رأی‌ها:</div>';
    (d.history||[]).slice(0,10).forEach(hi=>{
      h+='<div style="color:#64748b;font-size:10px;border-top:1px solid #1e293b;padding-top:3px;margin-top:3px">'
        +(hi.task==='category'?'🏷️':'💬')+' «'+esc(hi.input)+'» → برنده: <span dir="ltr">'+esc(hi.winner)+'</span></div>';
    });
    h+='</div>';
    r.innerHTML=h;
  });
}
function aiRenderProviders(){
    const sel=$('aiProviderSel');if(!sel)return;
    const cur=sel.value||aiProvData.selected.provider||'';
    sel.innerHTML='<option value="">— انتخاب —</option>';
    (aiProvData.providers||[]).forEach(p=>{
        const ok=p.enabled?'':' ⛔';
        sel.add(new Option(esc(p.name)+ok+' ('+(p.models||[]).length+' مدل)',esc(p.id)));
    });
    let target=cur;
    if(!target||![...(sel.options)].some(o=>o.value===target))target=aiProvData.selected.provider||'';
    if(target)sel.value=target;
    aiRenderModels();
    aiCandFillSel();
    aiRenderProviderToggles();
    aiKeyRender();   // v10.01: فهرستِ کلیدهای ارائه‌دهندهٔ انتخاب‌شده
}
// v9.63: فهرست ارائه‌دهنده‌ها با تیکِ روشن/خاموش انفرادی. خاموش کردن یعنی
// ارائه‌دهنده و همهٔ مدل‌هایش از «تست مدل‌ها» کنار می‌روند (تست انبوه فقط
// ارائه‌دهنده‌های روشن را می‌شمارد) ولی داده‌ها و کلیدها حفظ می‌شوند.
function aiRenderProviderToggles(){
    const list=document.getElementById('aiProviderToggleList');if(!list)return;
    const provs=aiProvData.providers||[];
    if(!provs.length){list.innerHTML='<div style="padding:8px;color:#64748b;font-size:11px">ارائه‌دهنده‌ای درون‌ریزی نشده.</div>';const c=document.getElementById('aiProvOnCount');if(c)c.textContent='';return;}
    let html='';
    let onCount=0;
    provs.forEach(p=>{
        const on=p.enabled!==false;
        if(on)onCount++;
        const mc=(p.models||[]).length;
        html+='<label style="display:flex;align-items:center;gap:8px;padding:7px 10px;border-bottom:1px solid #1e293b;cursor:pointer;'+(on?'':'opacity:.55')+'" title="خاموش: ارائه‌دهنده و مدل‌هایش در تست مدل‌ها شرکت نمی‌کنند">'
           +'<input type="checkbox" style="width:15px;height:15px;flex:0 0 auto" '+(on?'checked':'')+' onchange="aiToggleProvider(\''+jsAttr(p.id)+'\',this.checked)">'
           +'<span style="flex:1;min-width:0">'+esc(p.name||p.id)+'</span>'
           +'<span style="color:#94a3b8;font-size:10px;white-space:nowrap" dir="ltr">'+toFa(mc)+' مدل</span>'
           +'<span style="font-size:10px;'+(on?'color:#4ade80':'color:#f87171')+'" id="aiProvStat-'+esc(p.id)+'">'+(on?'✓ روشن':'✕ خاموش')+'</span>'
           +'</label>';
    });
    list.innerHTML=html||'<div style="padding:8px;color:#64748b;font-size:11px">ارائه‌دهنده‌ای نیست.</div>';
    const c=document.getElementById('aiProvOnCount');
    if(c)c.textContent=onCount+' روشن از '+provs.length;
}
/* ── v10.01 (۱۵): رابطِ مدیریتِ چند کلید API ─────────────────────────
   داده از aiProvData می‌آید (aiProvidersSummary سمتِ PHP). خودِ کلید هرگز
   به مرورگر نمی‌آید — فقط پیش‌نمایشِ ماسک‌شده و شناسهٔ هش‌شده. */
function aiKeyRender(){
    const list=document.getElementById('aiKeyList');if(!list)return;
    const cnt=document.getElementById('aiKeyCount');
    const p=aiCurrentProvider();
    /* v10.16: کادرِ «شمارهٔ حساب» فقط برای ارائه‌دهنده‌هایی که واقعاً لازمش
       دارند (کلادفلر) دیده می‌شود — بقیه شلوغ نشوند. */
    const needAcct=!!(p&&p.needs_acct);
    ['aiKeyAcctRow','aiKeyAcctHint'].forEach(function(id){
        const el=document.getElementById(id);
        if(el)el.classList.toggle('hidden',!needAcct);
    });
    const _kn=document.getElementById('aiKeyNew');
    if(_kn)_kn.placeholder=needAcct
        ?'توکنِ API همین حساب — برای Cloudflare هر کلید یک حسابِ جداست'
        :'کلید API تازه — می‌توانید چند کلید را هر خط یکی بچسبانید';
    if(!p){
        list.innerHTML='<div style="padding:8px;color:#64748b;font-size:11px">ابتدا یک ارائه‌دهنده انتخاب کنید.</div>';
        if(cnt)cnt.textContent='';return;
    }
    const keys=p.keys||[];
    if(!keys.length){
        list.innerHTML='<div style="padding:9px;color:#fbbf24;font-size:11px">⚠ هنوز هیچ کلیدی برای «'+esc(p.name||p.id)+'» ثبت نشده. کلید را در کادرِ پایین بگذارید.</div>';
        if(cnt)cnt.textContent='بدون کلید';return;
    }
    let html='';
    keys.forEach((k,i)=>{
        const off=k.enabled===false;
        let badge,color,tip;
        if(off){badge='✕ خاموش';color='#64748b';tip='این کلید موقتاً کنار گذاشته شده';}
        else if(k.kind==='billing'){badge='💳 اعتبار تمام';color='#f87171';tip=k.note||'اعتبار/سهمیهٔ این کلید تمام شده';}
        else if(k.kind==='auth'){badge='🚫 نامعتبر';color='#f87171';tip=k.note||'کلید پذیرفته نشد (۴۰۱)';}
        else if(k.kind==='rate'&&k.blocked){badge='⏳ '+toFa(k.retryIn)+'s';color='#fbbf24';tip=k.note||'محدودیت نرخ — به‌زودی دوباره امتحان می‌شود';}
        else{badge='✓ سالم';color='#4ade80';tip=k.okAt?'آخرین استفاده موفق بوده':'هنوز خطایی نداشته';}
        const active=(!off&&!k.blocked);
        html+='<div style="display:flex;align-items:center;gap:6px;padding:7px 9px;border-bottom:1px solid #1e293b;'+(off?'opacity:.55':'')+'" title="'+esc(tip)+'">'
           +'<span style="color:#64748b;font-size:10px;width:14px;flex:0 0 auto">'+toFa(i+1)+'</span>'
           +'<input type="checkbox" style="width:14px;height:14px;flex:0 0 auto" '+(off?'':'checked')+' onchange="aiKeyToggle(\''+jsAttr(k.id)+'\',this.checked)" title="روشن/خاموش">'
           +'<span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'
             +'<span dir="ltr" style="font-family:ui-monospace,monospace;font-size:10.5px;color:#e2e8f0">'+esc(k.preview||'')+'</span>'
             +(k.label?' <span style="color:#94a3b8;font-size:10px">· '+esc(k.label)+'</span>':'')
             /* v10.16: شمارهٔ حسابِ اختصاصیِ کلید — برای کلادفلر مهم است چون
                هر کلید در واقع «یک حسابِ دیگر» است. */
             +(k.acct?' <span dir="ltr" style="color:#a78bfa;font-size:9.5px" title="شمارهٔ حساب این کلید: '+esc(k.acct)+'">🏷 '+esc(String(k.acct).slice(0,8))+'…</span>':'')
           +'</span>'
           +'<span id="aiKeyT_'+esc(k.id)+'" style="font-size:9.5px;white-space:nowrap"></span>'
           +(active&&i===0?'<span style="font-size:9.5px;color:#67e8f9;white-space:nowrap">در حال استفاده</span>':'')
           +(k.fails?'<span style="font-size:9.5px;color:#64748b;white-space:nowrap" title="تعداد خطاهای ثبت‌شده">'+toFa(k.fails)+' خطا</span>':'')
           +'<span style="font-size:10px;color:'+color+';white-space:nowrap">'+badge+'</span>'
           /* v10.16 (۲۹ج): تستِ همین کلید — بدون چرخش، تا معلوم شود دقیقاً
              این حساب زنده است یا نه. */
           +'<button class="btn btn-blue" id="aiKeyTB_'+esc(k.id)+'" style="padding:2px 6px;font-size:10px" onclick="aiKeyTest(\''+jsAttr(k.id)+'\')" title="یک پیامِ «سلام» فقط با همین کلید فرستاده می‌شود">🧪 تست</button>'
           +(k.kind?'<button class="btn btn-cyan" style="padding:2px 6px;font-size:10px" onclick="aiKeyReset(\''+jsAttr(k.id)+'\')" title="سهمیه‌ام تازه شده — برچسبِ خطا را پاک کن">↺</button>':'')
           +'<button class="btn btn-red" style="padding:2px 6px;font-size:10px" onclick="aiKeyDel(\''+jsAttr(k.id)+'\')" title="حذف این کلید">🗑</button>'
           +'</div>';
    });
    /* اگر همهٔ کلیدها سوخته‌اند، صریح هشدار بده — این همان حالتی است که
       کاربر باید کلیدِ تازه اضافه کند. */
    const healthy=(typeof p.key_healthy==='number')?p.key_healthy:keys.filter(k=>k.enabled!==false&&!k.blocked).length;
    if(!healthy){
        html+='<div style="padding:8px;background:#3b1111;color:#fca5a5;font-size:10.5px">⚠ هیچ کلیدِ سالمی باقی نمانده — یک کلید تازه اضافه کنید یا با ↺ وضعیت را پاک کنید.</div>';
    }
    list.innerHTML=html;
    if(cnt)cnt.textContent=toFa(healthy)+' سالم از '+toFa(keys.length);
}
function aiKeyShow(){
    const el=document.getElementById('aiKeyNew');if(!el)return;
    el.type=(el.type==='password')?'text':'password';
    el.focus();
}
function aiKeyPost(fd,okMsg){
    const p=aiCurrentProvider();
    if(!p){showToast('ابتدا یک ارائه‌دهنده انتخاب کنید',1);return;}
    fd.append('provider_id',p.id);
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){showToast('❌ '+((d&&d.error)||'خطا'),1);return;}
        showToast('✓ '+(d.msg||okMsg||'انجام شد'));
        aiLoadProviders();
    }).catch(()=>{showToast('❌ خطای شبکه',1);});
}
function aiKeyAdd(){
    const inp=document.getElementById('aiKeyNew');
    const lab=document.getElementById('aiKeyLabel');
    const acc=document.getElementById('aiKeyAcct');
    const v=inp?inp.value.trim():'';
    if(!v){showToast('کلید را وارد کنید',1);return;}
    /* v10.16: برای کلادفلر «کلیدِ دیگر» یعنی «حسابِ دیگر» — سهمیه به حساب
       بسته است نه به توکن — پس شمارهٔ حساب هم اجباری است. */
    const p=aiCurrentProvider();
    const av=acc?acc.value.trim():'';
    if(p&&p.needs_acct&&!av){
        showToast('برای Cloudflare شمارهٔ حساب (Account ID) هم لازم است',1);
        if(acc)acc.focus();
        return;
    }
    const fd=new FormData();
    fd.append('action','ai_keys_add');
    fd.append('api_key',v);
    fd.append('label',lab?lab.value.trim():'');
    fd.append('account_id',av);
    if(inp)inp.value='';
    if(lab)lab.value='';
    if(acc)acc.value='';
    aiKeyPost(fd,'کلید افزوده شد');
}
/* v10.16 (۲۹ج): تستِ یک کلیدِ مشخص. نتیجه کنارِ خودِ ردیف می‌نشیند تا
   کاربر بفهمد کدام حساب زنده است — نه یک توستِ کلی. */
function aiKeyTest(kid){
    const p=aiCurrentProvider();
    if(!p){showToast('ابتدا یک ارائه‌دهنده انتخاب کنید',1);return;}
    const out=document.getElementById('aiKeyT_'+kid);
    const btn=document.getElementById('aiKeyTB_'+kid);
    if(out){out.style.color='#fbbf24';out.textContent='⏳ …';}
    if(btn)btn.disabled=true;
    const fd=new FormData();
    fd.append('action','ai_keys_test');
    fd.append('provider_id',p.id);
    fd.append('key_id',kid);
    const msel=document.getElementById('aiModelSel');
    if(msel&&msel.value)fd.append('model_id',msel.value);
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(btn)btn.disabled=false;
        if(!d||!d.ok){
            if(out){out.style.color='#f87171';out.textContent='✕ '+((d&&d.error)||'خطا');}
            showToast('❌ '+((d&&d.error)||'خطا'),1);return;
        }
        if(d.pass){
            if(out){out.style.color='#4ade80';out.textContent='✓ '+toFa(d.latencyMs||0)+'ms';
                    out.title=(d.answer||'')?('پاسخ: '+d.answer):'';}
            showToast('✓ این کلید سالم است — پاسخ در '+toFa(d.latencyMs||0)+' میلی‌ثانیه');
        }else{
            /* توست زودگذر است؛ دلیلِ خرابی باید کنارِ خودِ کلید هم بماند تا
               کاربر بین چند حساب بتواند مقایسه کند کدام شارژ می‌خواهد. */
            const why=d.note||d.error||('کد '+toFa(d.code||0));
            if(out){out.style.color='#f87171';out.textContent='✕ '+toFa(d.code||0);out.title=why;}
            showToast('❌ '+why,1);
        }
        /* وضعیتِ سلامت روی دیسک عوض شده ⇒ فهرست را تازه کن */
        setTimeout(aiLoadProviders,900);
    }).catch(()=>{
        if(btn)btn.disabled=false;
        if(out){out.style.color='#f87171';out.textContent='✕ شبکه';}
        showToast('❌ خطای شبکه',1);
    });
}
function aiKeyDel(kid){
