        else{showToast(on?('🧠 «'+mid+'» استدلالی شد — سقف توکن '+toFa(d.budget||0)):('«'+mid+'» غیراستدلالی شد'));}
        aiLoadProviders();
    }).catch(()=>{showToast('❌ خطا شبکه',1);});
}

