    const noKey=(pid==='pollinations'||pid==='ollama');
    const key=noKey?'':prompt('کلید API برای «'+pid+'» را وارد کنید (اختیاری — می‌توانید خالی بگذارید و بعداً وارد کنید):','');
    if(key===null)return;
    const fd=new FormData();
