/* v9.95 (۹د): مودالِ «اطلاعات کاملِ یک مدل + پاسخ خام» — با کلیک روی ردیفِ
   جدولِ نتایجِ تست باز می‌شود. داده‌ها از ?ai_test_detail=1 خوانده می‌شوند
   چون در state.items فقط نسخهٔ کوتاه‌شده (۱۵۰/۱۲۰ کاراکتری) ذخیره است. */
function aiCloseRowDetail(){const m=document.getElementById('aiRowDetail');if(m)m.remove();}
function aiRowDetailRow(label,val,mono){
    if(val===''||val===null||val===undefined)return '';
    return '<tr><td style="padding:5px 8px;color:#94a3b8;white-space:nowrap;vertical-align:top;border-bottom:1px solid #1e293b">'+esc(label)+'</td>'
      +'<td style="padding:5px 8px;color:#e2e8f0;border-bottom:1px solid #1e293b'+(mono?';font-family:ui-monospace,monospace;direction:ltr;text-align:left;word-break:break-all':'')+'">'+esc(String(val))+'</td></tr>';
}
var aiRowDetailKey={provider:'',model:''};
/* v9.95: «تست دوبارهٔ همین مدل» از داخلِ مودالِ جزئیات */
function aiRetestFromDetail(){
    const pid=aiRowDetailKey.provider, mid=aiRowDetailKey.model;
    if(!pid||!mid)return;
    const b=document.getElementById('aiRowDetailBody');
    if(b)b.innerHTML='<div style="color:#67e8f9">⏳ در حال تست دوبارهٔ <b dir="ltr">'+esc(mid)+'</b> ...</div>';
    const fd=new FormData();
    fd.append('action','ai_test_one');fd.append('provider_id',pid);fd.append('model_id',mid);
    fd.append('msg',($('aiTestMsg')&&$('aiTestMsg').value.trim())||'سلام');
    fd.append('cat',($('aiTestCat')&&$('aiTestCat').value.trim())||'ادو پرفیوم');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(()=>{aiOpenRowDetail(pid,mid);aiLoadProviders();})
      .catch(()=>{if(b)b.innerHTML='<div style="color:#fca5a5">✗ خطا در تست دوباره</div>';});
}
/* v9.97: «تست دوبارهٔ دسته‌بندی» — قرینهٔ aiRetestFromDetail ولی فقط درخواستِ
   دومی که ستونِ «پاسخ دسته» را می‌سازد. پاسخِ پیام تست و خامِ آن دست نمی‌خورد،
   پس می‌شود چند بار پشت‌سرهم زد بی‌آنکه سهمیه‌ی پیام هم مصرف شود. */
function aiRetestCatFromDetail(){
    const pid=aiRowDetailKey.provider, mid=aiRowDetailKey.model;
    if(!pid||!mid)return;
    const b=document.getElementById('aiRowDetailBody');
    if(b)b.innerHTML='<div style="color:#a78bfa">⏳ در حال تستِ دوبارهٔ دسته‌بندی برای <b dir="ltr">'+esc(mid)+'</b> ...</div>';
    const fd=new FormData();
    fd.append('action','ai_test_one_cat');fd.append('provider_id',pid);fd.append('model_id',mid);
    fd.append('cat',($('aiTestCat')&&$('aiTestCat').value.trim())||'');
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(d&&d.ok===false){
            if(b)b.innerHTML='<div style="color:#fca5a5;line-height:1.9">✗ '+esc(d.error||'خطا در تستِ دسته‌بندی')
              +'<div style="margin-top:8px"><button class="btn btn-gray" style="font-size:11px" onclick="aiOpenRowDetail('
              +JSON.stringify(pid)+','+JSON.stringify(mid)+')">↩ بازگشت به جزئیات</button></div></div>';
            return;
        }
        showToast('🏷️ دسته‌بندی دوباره تست شد',0);
        aiOpenRowDetail(pid,mid);aiLoadProviders();
    }).catch(()=>{if(b)b.innerHTML='<div style="color:#fca5a5">✗ خطا در تستِ دوبارهٔ دسته‌بندی</div>';});
}
function aiOpenRowDetail(pid,mid){
    if(!pid||!mid)return;
    aiRowDetailKey={provider:pid,model:mid};
    aiCloseRowDetail();
    const m=document.createElement('div');
    m.id='aiRowDetail';
    m.style.cssText='position:fixed;inset:0;background:rgba(2,6,23,.8);z-index:10090;display:flex;align-items:center;justify-content:center;padding:20px';
    m.innerHTML='<div style="background:#0f172a;border:1px solid #334155;border-radius:12px;width:min(900px,96vw);max-height:92vh;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.6)">'
      +'<div class="mhead" style="padding:10px 14px;border-bottom:1px solid #334155;flex:0 0 auto">'
      +'<b class="mh-t" style="color:#67e8f9;font-size:13px">🔎 جزئیات کاملِ تستِ مدل</b>'
      +'<span class="mh-act"><button class="btn btn-gray" onclick="aiCloseRowDetail()" style="font-size:11px;padding:4px 10px">✕ بستن</button></span></div>'
      +'<div id="aiRowDetailBody" style="flex:1;overflow:auto;padding:12px 16px;font-size:11.5px;color:#94a3b8">⏳ در حال خواندن...</div></div>';
    m.addEventListener('click',function(e){if(e.target===m)aiCloseRowDetail();});
    document.body.appendChild(m);
    fetch('?ai_test_detail=1&provider='+encodeURIComponent(pid)+'&model='+encodeURIComponent(mid))
      .then(r=>r.json()).then(d=>{
        const b=document.getElementById('aiRowDetailBody');if(!b)return;
        if(!d||!d.ok){b.innerHTML='<div style="color:#fca5a5">✗ '+esc((d&&d.error)||'خطا در خواندن جزئیات')+'</div>';return;}
        const badge=(txt,color)=>'<span style="display:inline-block;padding:2px 7px;border-radius:20px;font-size:10.5px;background:'+color+'22;color:'+color+';border:1px solid '+color+'66;margin-inline-end:5px;margin-left:5px">'+esc(txt)+'</span>';
        let flags='';
        flags+=d.available?badge('🟢 در دسترس','#4ade80'):badge('🔴 ناموفق','#f87171');
        if(d.rateLimited)flags+=badge('⏱ ریت‌لیمیت','#fbbf24');
        if(d.reasoning)flags+=badge('🧠 استدلالی','#a78bfa');
        if(d.toolCalling)flags+=badge('🔧 tool calling','#60a5fa');
        if(d.vision)flags+=badge('👁 تصویری','#f472b6');
        if(d.free)flags+=badge('🆓 رایگان','#34d399');
        if(!d.tested)flags+=badge('هنوز تست نشده','#94a3b8');
        let h='<div style="margin-bottom:8px">'+flags+'</div>';
        h+='<table style="width:100%;border-collapse:collapse;font-size:11.5px">';
        h+=aiRowDetailRow('ارائه‌دهنده',(d.providerName||'')+' ('+(d.provider||'')+')');
        h+=aiRowDetailRow('مدل',d.model,true);
        if(d.modelName&&d.modelName!==d.model)h+=aiRowDetailRow('نام مدل',d.modelName);
        h+=aiRowDetailRow('اندپوینت',d.endpoint,true);
        if(d.via)h+=aiRowDetailRow('روش اتصال',d.via,true);
        if(d.status)h+=aiRowDetailRow('کد وضعیت HTTP',d.status,true);
        if(d.latencyMs)h+=aiRowDetailRow('تأخیر',toFa(d.latencyMs)+' میلی‌ثانیه');
        if(d.testedAt)h+=aiRowDetailRow('زمان تست (UTC)',d.testedAt,true);
        if(d.maxInputTokens)h+=aiRowDetailRow('سقف توکن ورودی',toFa(d.maxInputTokens));
        if(d.maxOutputTokens)h+=aiRowDetailRow('سقف توکن خروجی',toFa(d.maxOutputTokens));
        if(d.testMsg)h+=aiRowDetailRow('پیام تست',d.testMsg);
        if(d.testCat)h+=aiRowDetailRow('عنوان دسته‌بندی',d.testCat);
        /* v9.97: اگر دسته‌بندی جدا از پیام تست اجرا شده، زمان/تأخیرِ خودش را دارد */
        if(d.catLatencyMs)h+=aiRowDetailRow('تأخیر دسته‌بندی',toFa(d.catLatencyMs)+' میلی‌ثانیه');
        if(d.catTestedAt)h+=aiRowDetailRow('زمان تستِ دسته‌بندی (UTC)',d.catTestedAt,true);
        h+='</table>';
        const block=(title,txt,color)=>txt?('<div style="margin-top:10px"><div style="color:'+color+';font-weight:700;margin-bottom:4px">'+esc(title)+'</div>'
            +'<div style="background:#0b1425;border:1px solid #1e293b;border-radius:6px;padding:8px;white-space:pre-wrap;word-break:break-word;color:#e2e8f0;max-height:240px;overflow:auto">'+esc(txt)+'</div></div>'):'';
        h+=block('💬 پاسخ مدل به پیام تست',d.response,'#4ade80');
        h+=block('🏷️ پاسخ دسته‌بندی',d.catResponse,'#a78bfa');
        h+=block('⚠️ خطا',d.error||d.itemError,'#f87171');
        /* v9.96: هر دو پاسخِ خام — درخواستِ «پیام تست» و درخواستِ «دسته‌بندی» */
        const rawBlock=(title,txt,color,note)=>{
            let pretty=txt;
            try{pretty=JSON.stringify(JSON.parse(txt),null,2);}catch(e){}
            return '<div style="margin-top:10px"><div style="color:'+color+';font-weight:700;margin-bottom:4px">'+esc(title)
              +(note?'<span style="color:#64748b;font-weight:400;font-size:10px"> — '+esc(note)+'</span>':'')+'</div>'
              +'<pre dir="ltr" style="background:#0b1425;border:1px solid #1e293b;border-radius:6px;padding:8px;white-space:pre-wrap;word-break:break-all;color:#cbd5e1;max-height:320px;overflow:auto;font-family:ui-monospace,monospace;font-size:10.5px;text-align:left;margin:0">'+esc(pretty)+'</pre></div>';
        };
        if(d.raw){
            h+=rawBlock('🧾 پاسخ خامِ درخواستِ پیام تست (JSON)',d.raw,'#67e8f9',
                'درخواست اول: پیامِ «'+(d.testMsg||'سلام')+'»');
        }else{
            h+='<div style="margin-top:10px;color:#64748b">🧾 پاسخ خامِ پیام تست ذخیره نشده — یک بار دیگر تستش کنید تا ذخیره شود.</div>';
        }
        if(d.catRaw){
            let note='درخواست دوم: دسته‌بندیِ «'+(d.testCat||'')+'»';
            if(d.catStatus)note+=' · HTTP '+d.catStatus;
            if(d.catVia)note+=' · '+d.catVia;
            h+=rawBlock('🏷️ پاسخ خامِ درخواستِ دسته‌بندی (JSON)',d.catRaw,'#a78bfa',note);
            if(d.catAiText)h+='<div style="margin-top:4px;color:#94a3b8;font-size:10.5px">متنِ خروجیِ مدل پیش از تبدیل به شناسهٔ دسته: <b style="color:#c4b5fd;direction:ltr;display:inline-block">'+esc(d.catAiText)+'</b></div>';
        }else{
            h+='<div style="margin-top:10px;color:#64748b">🏷️ پاسخ خامِ دسته‌بندی ذخیره نشده — برای ذخیره‌شدن باید توکنِ باسلام تنظیم باشد (فهرست دسته‌ها از آنجا خوانده می‌شود) و مدل دوباره تست شود.</div>';
        }
        /* v9.97: دو دکمهٔ تستِ دوباره — کاملِ مدل (پیام + دسته) و فقط دسته‌بندی */
        h+='<div class="cact" style="margin-top:12px">'
          +'<button class="btn btn-cyan" style="flex:1;font-size:11px" onclick="aiRetestFromDetail()" title="هر دو درخواست را از نو می‌زند: پیام تست و سپس دسته‌بندی">🔁 تست دوبارهٔ همین مدل</button>'
          +'<button class="btn btn-purple" style="flex:1;font-size:11px" onclick="aiRetestCatFromDetail()" title="فقط درخواستِ دسته‌بندی را دوباره می‌زند — پاسخِ پیام تست و خامِ آن دست‌نخورده می‌ماند">🏷️ تست دوبارهٔ دسته‌بندی</button>'
          +'<button class="btn btn-gray" style="flex:0;font-size:11px" onclick="aiCloseRowDetail()">بستن</button></div>';
        b.innerHTML=h;
      }).catch(()=>{const b=document.getElementById('aiRowDetailBody');if(b)b.innerHTML='<div style="color:#fca5a5">✗ خطا در ارتباط</div>';});
}
function aiTestOne(pid,mid,kid){
    // v9.52: پیام و دستهٔ تست را از فیلدهای جاری می‌گیرد (مودال یا بخش بیرونی)
    const msg=($('aiTestMsg')&&$('aiTestMsg').value.trim())||'سلام';
    const cat=($('aiTestCat')&&$('aiTestCat').value.trim())||'ادو پرفیوم';
    const fd=new FormData();fd.append('action','ai_test_one');fd.append('provider_id',pid);fd.append('model_id',mid);
    // v10.17 (۳۰): اگر ردیف به کلیدِ خاصی گره خورده، تست فقط با همان کلید
    if(kid)fd.append('key_id',kid);
    fd.append('msg',msg);fd.append('cat',cat);
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        const r=$('aiTR');if(r){
            const ok=d&&d.available;
            r.innerHTML='<div style="background:'+(ok?'#14532d':'#7f1d1d')+';color:'+(ok?'#86efac':'#fca5a5')+';padding:8px;font-size:11px">'
              +(ok?'✓':'✗')+' <b dir="ltr">'+esc(mid)+esc((d&&d.keySuffix)||'')+'</b> — '+(ok?('پاسخ پیام: '+esc(d.response||'')):esc(d.error||'خطا'))
              +(d.catResponse?'<div style="margin-top:3px;color:#c4b5fd">🏷️ دسته: '+esc(d.catResponse)+'</div>':'')
              +' <span style="color:#94a3b8">('+toFa(d.latencyMs||0)+'ms)</span></div>';
        }
        aiLoadProviders();
    }).catch(()=>{});
}
/* v9.23: مودال جدولِ زندهٔ «تست همهٔ مدل‌ها» — با ارسال پیام «سلام».
   هر ردیف = یک مدل؛ ستون‌ها: وضعیت، ارائه‌دهنده، مدل، تأخیر، پاسخ/خطا. */
function aiOpenTestModal(){
    let m=document.getElementById('aiTestModal');if(m)m.remove();
    m=document.createElement('div');
    m.id='aiTestModal';
    m.style.cssText='position:fixed;inset:0;background:rgba(2,6,23,.72);z-index:10080;display:flex;align-items:center;justify-content:center;padding:20px';
    // v10.00 (۱۴الف): تا وقتی این مودال باز است، دکمه‌های شناورِ ☰ و ⛶ زیر آن بروند
    document.body.classList.add('modal-open');
    aiDiagOpen=false; aiDiagSig='';   // v10.20 (۳۳ب): «مشکلات مدل‌ها» هر بار بسته باز شود
    m.innerHTML='<style>'
      // v9.64: سوییچِ اسلایدری «فقط سبزها» — نمایش فقط مدل‌های دارای چراغ سبز
      +'.ai-switch{width:34px;height:20px;border-radius:20px;background:#334155;position:relative;display:inline-block;transition:background .2s;flex:0 0 auto;vertical-align:middle}'
      +'.ai-switch::after{content:"";position:absolute;top:2px;left:2px;width:16px;height:16px;border-radius:50%;background:#e2e8f0;transition:transform .2s}'
      +'.ai-switch-wrap input:checked + .ai-switch{background:#22c55e}'
      +'.ai-switch-wrap input:checked + .ai-switch::after{transform:translateX(14px)}'
      +'</style>'
      +'<div style="background:#0f172a;border:1px solid #334155;border-radius:12px;width:min(1100px,96vw);max-height:92vh;display:flex;flex-direction:column;box-shadow:0 20px 60px rgba(0,0,0,.5)">'
      /* v9.96 (۱۰الف): سربرگِ مودال فشرده شد.
         پیش‌تر عنوان، متنِ زردِ «در حال تست…»، شمارنده‌ها و نوارِ فقط‌خواندنی
         سه ردیفِ جدا بودند و در موبایل با wrap شدن به ۵–۶ سطر می‌رسیدند و
         نیمی از ارتفاعِ مودال را می‌خوردند. حالا دو ردیفِ nowrap داریم:
         ۱) عنوان + چیپِ وضعیتِ زنده (aiTestCur) + دکمه‌ها
         ۲) شمارنده‌ها + مقادیرِ فقط‌خواندنی + سوییچِ «فقط سبزها» (با اسکرولِ افقی) */
      +'<div class="mhead" style="padding:9px 14px;border-bottom:1px solid #334155;flex:0 0 auto">'
      +'<b class="mh-t" style="color:#67e8f9;font-size:13px">🧪 نتایج زندهٔ تست همهٔ مدل‌ها</b>'
      +'<span id="aiTestCur" class="mstat"></span>'
      +'<span class="mh-act">'
      +'<button class="btn btn-red" onclick="aiTestStop()" style="font-size:11px;padding:4px 10px">⏹ توقف</button>'
      +'<button class="btn btn-gray" onclick="aiCloseTestModal()" style="font-size:11px;padding:4px 10px">✕ بستن</button></span></div>'
      /* v9.95 (۹الف): سه فیلدِ «پیام تست»، «دستهٔ تست» و «تاخیر» از داخلِ مودال
         برداشته شدند — همان‌ها در تبِ «🧪 تست مدل‌ها» هستند و داشتنِ نسخهٔ دوم
         با شناسه‌های تکراری (aiTestMsg/aiTestCat/aiTestDelay) باعث می‌شد
         document.getElementById همیشه نسخهٔ بیرونی را بگیرد. اینجا فقط
         مقادیرِ به‌کاررفته را «فقط‌خواندنی» نشان می‌دهیم.
         v9.96: این نوار با نوارِ شمارنده‌ها ادغام شد تا یک ردیفِ کامل صرفه‌جویی شود. */
      +'<div class="mbar" style="padding:6px 14px;border-bottom:1px solid #1e293b;flex:0 0 auto;font-size:11px;color:#94a3b8" title="برای تغییرِ پیام/دسته/تأخیر به تبِ «🧪 تست مدل‌ها» بروید · روی هر ردیف کلیک کنید تا جزئیات کامل را ببینید">'
      +'<span>کل: <b id="aiTestTot" style="color:#e2e8f0">۰</b></span>'
      +'<span>🟢 <b id="aiTestOk" style="color:#4ade80">۰</b></span>'
      +'<span>🔴 <b id="aiTestFail" style="color:#f87171">۰</b></span>'
      +'<span>⏳ <b id="aiTestWait" style="color:#fbbf24">۰</b></span>'
      +'<span style="color:#334155">|</span>'
      +'<span class="mb-el" style="color:#64748b">پیام: <b style="color:#cbd5e1">'+esc(aiTestMsgVal||'سلام')+'</b></span>'
      +'<span class="mb-el" style="color:#64748b">دسته: <b style="color:#cbd5e1">'+esc(aiTestCatVal||'ادو پرفیوم')+'</b></span>'
      +'<span style="color:#64748b">تأخیر: <b style="color:#cbd5e1">'+toFa(aiTestDelayVal||120)+'</b> ms</span>'
      +'<span class="mb-sp"></span>'
      // v9.64: سوییچِ اسلایدریِ «فقط سبزها»
      +'<label class="ai-switch-wrap" style="display:flex;align-items:center;gap:7px;cursor:pointer">'
      +'<span style="font-size:11px;color:#94a3b8">فقط سبزها</span>'
      +'<input type="checkbox" id="aiTestOnlyGreen" onchange="aiTestToggleOnlyGreen(this.checked)" style="display:none">'
      +'<span class=\"ai-switch\"></span></label></div>'
      /* ═══════════════════════════════════════════════════════════════
         v10.37 (۵۰الف): جدولِ منظم با سربرگ‌های مرتب‌کننده.

         عرضِ ستون‌ها با colgroup تعیین می‌شود (سهمِ بزرگ برای نامِ مدل) و
         چون table-layout ثابت است، یک نامِ خیلی بلند دیگر نمی‌تواند بقیهٔ
         ستون‌ها را له کند.

         هر سربرگِ مرتب‌کننده onclick دارد و جهتِ فعلی را با ▲/▼ نشان
         می‌دهد. مرتب‌سازی سمتِ مرورگر است و روی همان ردیف‌هایی که تا این
         لحظه آمده‌اند اعمال می‌شود — بدونِ هیچ درخواستی به سرور و بدونِ
         قطعِ تستِ در حال اجرا.
         ═══════════════════════════════════════════════════════════════ */
      +'<div style="flex:1;overflow:auto;padding:0">'
      +'<table class="aiTestTable">'
      +'<colgroup>'
      +'<col style="width:38px"><col style="width:52px">'
      +'<col style="width:14%"><col style="width:30%">'
      +'<col style="width:72px">'
      +'<col style="width:19%"><col style="width:19%">'
      +'</colgroup>'
      +'<thead><tr>'
      +'<th class="srt" data-sk="idx"  onclick="aiTestSort(\'idx\')"  style="text-align:center" title="ترتیبِ ورود">#<span class="sarw"></span></th>'
      +'<th class="srt" data-sk="st"   onclick="aiTestSort(\'st\')"   style="text-align:center" title="مرتب‌سازی بر اساسِ وضعیت (سالم اول)">وضعیت<span class="sarw"></span></th>'
      +'<th class="srt" data-sk="prov" onclick="aiTestSort(\'prov\')" style="text-align:right"  title="مرتب‌سازی الفبایی بر اساسِ ارائه‌دهنده">ارائه‌دهنده<span class="sarw"></span></th>'
      +'<th class="srt" data-sk="model" onclick="aiTestSort(\'model\')" style="text-align:left;direction:ltr" title="مرتب‌سازی الفبایی بر اساسِ نامِ مدل">مدل<span class="sarw"></span></th>'
      +'<th class="srt" data-sk="lat"  onclick="aiTestSort(\'lat\')"  style="text-align:center" title="مرتب‌سازی بر اساسِ سرعتِ پاسخ">تأخیر<span class="sarw"></span></th>'
      +'<th style="text-align:right">پاسخ پیام</th>'
      +'<th style="text-align:right">پاسخ دسته</th>'
      +'</tr></thead><tbody id="aiTestTbody"></tbody></table></div>'
      /* v10.20 (۳۳ب): «مشکلات مدل‌ها» حالا کشویی است و بسته باز می‌شود.
         قبلاً این باکسِ نارنجی/قرمز باز و کامل چاپ می‌شد و با چند ارائه‌دهندهٔ
         مشکل‌دار، چند سطر متن پایینِ مودال را می‌خورد و جدول را می‌فشرد.
         حالا فقط یک نوارِ جمع‌وجور با تعدادِ مشکل دیده می‌شود؛ باز کردنش
         با کاربر است و انتخابش تا پایانِ همان جلسه یادش می‌ماند. */
      +'<div id="aiTestDiag" style="flex:0 0 auto;padding:0 16px 10px"></div>'
      +'</div>';
    m.addEventListener('click',function(e){if(e.target===m)aiCloseTestModal();});
    document.body.appendChild(m);
}
function aiCloseTestModal(){
    // فقط poll را قطع می‌کنیم؛ کارِ سرور به‌صورت پس‌زمینه ادامه دارد
    if(window._aiPollTimer){clearInterval(window._aiPollTimer);window._aiPollTimer=null;}
    const m=document.getElementById('aiTestModal');if(m)m.remove();
    document.body.classList.remove('modal-open');   // v10.00 (۱۴الف): دکمه‌های شناور برگردند
    aiLoadProviders();
}
function aiTestStop(){
    fetch('?ai_test_stop=1').then(r=>r.json()).then(()=>{
        if($('aiTestCur'))$('aiTestCur').textContent='⏹ در حال توقف...';
    }).catch(()=>{});
}
/* v9.24: وضعیت کارِ پس‌زمینه را poll می‌کند و جدول را به‌روز می‌کند */
function aiPollTest(){
    if(window._aiPollTimer)return;
    window._aiPollTimer=setInterval(()=>{
        fetch('?ai_test_status=1').then(r=>r.json()).then(st=>{
            aiRenderTestState(st);
            if(!st.running&&st.done){
                if(window._aiPollTimer){clearInterval(window._aiPollTimer);window._aiPollTimer=null;}
                aiLoadProviders();
                /* v10.36 (۴۹د): تستِ تازه تمام شد ⇒ کارت‌های آمار هم باید
                   عددِ تازه نشان بدهند، وگرنه کاربر بعد از یک اجرای کامل
                   همان آمارِ قدیمی را می‌بیند و فکر می‌کند کار نکرده. */
                try{ aiStatsLoad(); }catch(e){}
            }
        }).catch(()=>{});
    },1200);
}
let aiTestRows={},aiTestTotCount=0,aiTestOkCount=0,aiTestFailCount=0,aiTestWaitCount=0;
let aiTestMsgVal='سلام',aiTestCatVal='ادو پرفیوم',aiTestDelayVal=120;
// v9.99: سقفِ درخواستِ هم‌زمان و ردکردنِ مدل‌های غیرچت
let aiTestConcVal=4,aiTestSkipNonChatVal=true;
function aiTestReadOpts(){
    aiTestConcVal=Math.max(1,Math.min(16,parseInt(($('aiTestConc')&&$('aiTestConc').value)||'4',10)||4));
    aiTestSkipNonChatVal=$('aiTestSkipNonChat')?!!$('aiTestSkipNonChat').checked:true;
    return '&conc='+aiTestConcVal+'&nonchat='+(aiTestSkipNonChatVal?'1':'0');
}
// v9.64: فیلترِ «فقط سبزها» در جدولِ نتایجِ تست مدل‌ها
let aiTestOnlyGreen=false;
function aiTestRenderCounters(){
    if($('aiTestTot'))$('aiTestTot').textContent=toFa(aiTestTotCount);
    if($('aiTestOk'))$('aiTestOk').textContent=toFa(aiTestOkCount);
    if($('aiTestFail'))$('aiTestFail').textContent=toFa(aiTestFailCount);
    if($('aiTestWait'))$('aiTestWait').textContent=toFa(aiTestWaitCount);
}
/* v9.64: سوییچِ «فقط سبزها» — فقط ردیف‌های دارای چراغ سبز (موفق) را نشان بده */
function aiTestToggleOnlyGreen(on){
    aiTestOnlyGreen=!!on;
    aiTestApplyGreenFilter();
}
function aiTestApplyGreenFilter(){
    if(!aiTestOnlyGreen){ Object.values(aiTestRows).forEach(r=>{ if(r&&r.tr)r.tr.style.display=''; }); return; }
    Object.values(aiTestRows).forEach(r=>{
        if(!r||!r.tr)return;
        const st=r.tr.querySelector('.aiSt');
        const txt=st?st.textContent:'';
        r.tr.style.display=(txt==='🟢')?'':'none';
    });
}
/* ═══════════════════════════════════════════════════════════════════════
   v10.37 (۵۰الف): مرتب‌سازیِ جدولِ نتایجِ تست از روی سربرگ‌ها.

   کلیک روی هر سربرگ: بارِ اول صعودی، بارِ دوم نزولی، بارِ سوم برگشت به
   ترتیبِ طبیعیِ ورود (idx صعودی). این «چرخهٔ سه‌حالته» عمدی است — کاربر
   بدونِ رفرش می‌تواند به نمای اولیه برگردد.

   نکتهٔ سازگاری: فیلترِ «فقط سبزها» با tr.style.display کار می‌کند. چون ما
   فقط ترتیبِ گره‌ها را عوض می‌کنیم و display را دست نمی‌زنیم، هر دو با هم
   کار می‌کنند. ردیف‌های پنهان هم مرتب می‌شوند تا اگر فیلتر برداشته شد،
   جدول همچنان مرتب باشد. ═══════════════════════════════════════════════ */
let aiTestSortKey='';    // '' یعنی ترتیبِ طبیعیِ ورود
let aiTestSortDir=1;     // ۱ صعودی، ‎-۱ نزولی

function aiTestSortVal(tr,k){
    const ds=tr.dataset||{};
    if(k==='idx')  return parseInt(ds.aiIdx||'0',10)||0;
    if(k==='st')   return parseInt(ds.aiStV||'2',10);
    if(k==='lat'){
        // مدل‌هایی که هنوز عددی ندارند همیشه ته صف می‌مانند — چه صعودی
        // چه نزولی — وگرنه در حالتِ صعودی «بی‌پاسخ»ها بالای سریع‌ترین‌ها
        // می‌نشستند و ستون بی‌معنی می‌شد.
        const v=parseInt(ds.aiLatV||'',10);
        return isNaN(v)?null:v;
    }
    if(k==='prov') return (ds.aiProvName||'').toLowerCase();
    if(k==='model')return (ds.aiModel||'').toLowerCase();
    return 0;
}

function aiTestSortApply(){
    const tbody=$('aiTestTbody'); if(!tbody)return;
    const rows=Array.prototype.slice.call(tbody.children);
    if(!rows.length)return;
    const k=aiTestSortKey||'idx', dir=aiTestSortKey?aiTestSortDir:1;
    rows.sort(function(a,b){
        const va=aiTestSortVal(a,k), vb=aiTestSortVal(b,k);
        // null (بی‌مقدار) همیشه پایین، مستقل از جهت
        if(va===null&&vb===null){}
        else if(va===null)return 1;
        else if(vb===null)return -1;
        else if(typeof va==='string'||typeof vb==='string'){
            const c=String(va).localeCompare(String(vb),'en');
            if(c)return c*dir;
        }
        else if(va!==vb) return (va<vb?-1:1)*dir;
        // گره‌گشا: ترتیبِ ورود، تا مرتب‌سازی پایدار و قابلِ پیش‌بینی بماند
        return aiTestSortVal(a,'idx')-aiTestSortVal(b,'idx');
    });
    const frag=document.createDocumentFragment();
    rows.forEach(function(tr){frag.appendChild(tr);});
    tbody.appendChild(frag);
    aiTestSortMarkHeads();
}

/* نشانهٔ ▲/▼ روی سربرگِ فعال */
function aiTestSortMarkHeads(){
    const tb=$('aiTestTbody'); if(!tb)return;
    const tbl=tb.parentNode; if(!tbl)return;
    const ths=tbl.querySelectorAll('thead th.srt');
    Array.prototype.forEach.call(ths,function(th){
        const on=(th.dataset.sk===aiTestSortKey);
        th.classList.toggle('on',on);
        const ar=th.querySelector('.sarw');
        if(ar)ar.textContent=on?(aiTestSortDir>0?'▲':'▼'):'';
        if(on)th.setAttribute('aria-sort',aiTestSortDir>0?'ascending':'descending');
        else  th.removeAttribute('aria-sort');
    });
}

function aiTestSort(k){
    if(aiTestSortKey!==k){ aiTestSortKey=k; aiTestSortDir=1; }
    else if(aiTestSortDir===1){ aiTestSortDir=-1; }
    else { aiTestSortKey=''; aiTestSortDir=1; }   // چرخه: صعودی ← نزولی ← طبیعی
    aiTestSortApply();
}

function aiEnsureTestRow(d){
    const tbody=$('aiTestTbody');if(!tbody)return null;
    /* v10.17 (۳۰): با چند کلید، یک مدل چند ردیف دارد؛ شناسهٔ ردیف باید
       شاملِ کلید باشد وگرنه ردیف‌ها روی هم می‌افتند. */
    const key=(d.provider||'')+'::'+(d.model||'')+'::'+(d.keyId||'');
    if(aiTestRows[key])return aiTestRows[key];
    aiTestTotCount++;aiTestWaitCount++;
    const tr=document.createElement('tr');
    tr.style.borderBottom='1px solid #1e293b';
    /* v9.95 (۹د): کلیک روی ردیف → مودالِ «اطلاعات کامل + پاسخ خامِ مدل» */
    tr.style.cursor='pointer';
    tr.title='برای دیدنِ اطلاعات کامل و پاسخ خامِ مدل کلیک کنید';
    tr.dataset.aiProvider=d.provider||'';
    // v10.17 (۳۰): مودالِ جزئیات با نامِ *خامِ* مدل کار می‌کند، نه نامِ باپسوند
    tr.dataset.aiModel=d.baseModel||d.model||'';
    tr.dataset.aiKey=d.keyId||'';
    tr.addEventListener('mouseenter',function(){tr.style.background='#16233c';});
    tr.addEventListener('mouseleave',function(){tr.style.background='';});
    tr.addEventListener('click',function(){aiOpenRowDetail(tr.dataset.aiProvider,tr.dataset.aiModel);});
    /* v10.37 (۵۰الف): کلیدهای مرتب‌سازی روی خودِ ردیف ذخیره می‌شوند تا
       aiTestSort مجبور نباشد هر بار متنِ سلول‌ها را دوباره پارس کند.
       aiIdx ترتیبِ ورود است — همان چیزی که «#» نشان می‌دهد و حالتِ
       پیش‌فرضِ جدول به آن برمی‌گردد. aiLatV با هر پاسخ به‌روز می‌شود و
       aiStV وضعیت را عددی می‌کند (۰=سالم، ۱=خطا، ۲=هنوز منتظر). */
    tr.dataset.aiIdx=String(aiTestTotCount);
    tr.dataset.aiLatV='';
    tr.dataset.aiStV='2';
    tr.dataset.aiProvName=(d.providerName||d.provider||'');
    /* v10.37 (۵۰الف): سلول‌ها دوباره <td>ی ساده‌اند و «دو خطی شدن» روی یک
       div داخلشان است. در v10.36 خودِ td حالتِ webkit-box گرفته بود و
       چون آن حالت با table-cell ناسازگار است، ستون‌ها از colgroup پیروی
       نمی‌کردند و کلِ جدول به‌هم می‌ریخت. */
    const pn=esc(d.providerName||d.provider||'');
    const mn=esc(d.baseModel||d.model||'');
    tr.innerHTML='<td style="text-align:center;color:#64748b" class="aiIdxCell">'+toFa(aiTestTotCount)+'</td>'
      +'<td style="text-align:center"><span class="aiSt">⏳</span></td>'
      +'<td style="text-align:right;color:#94a3b8" title="'+pn+'"><div class="c2">'+pn+'</div></td>'
      +'<td style="color:#e2e8f0;font-weight:600" class="aiModelCell" title="'+mn+'"><div class="c2">'+mn
      +(d.keySuffix?'<span style="color:#fbbf24" title="'+esc('کلید: '+(d.keyLabel||d.keySuffix))+'">'+esc(d.keySuffix)+'</span>':'')
      +'</div></td>'
      +'<td style="text-align:center;color:#64748b" class="aiLat">—</td>'
      +'<td style="text-align:right;color:#94a3b8" class="aiMsgRes"><div class="c2">…</div></td>'
      +'<td style="text-align:right;color:#94a3b8" class="aiCatRes"><div class="c2">…</div></td>';
    tbody.appendChild(tr);
    aiTestRenderCounters();
    /* اگر کاربر ستونی را برای مرتب‌سازی انتخاب کرده، ردیفِ تازه هم باید
       سرِ جای درستش بنشیند نه ته جدول. */
    if(aiTestSortKey) aiTestSortApply();
    return aiTestRows[key]={tr:tr};
}
function aiSetTestRow(d){
    const r=aiEnsureTestRow(d);
    if(!r)return;
    if(d.ok!==undefined){ if(aiTestWaitCount>0)aiTestWaitCount--; if(d.ok)aiTestOkCount++; else aiTestFailCount++; }
    r.tr.querySelector('.aiSt').textContent=d.ok?'🟢':'🔴';
    r.tr.querySelector('.aiSt').style.color=d.ok?'#4ade80':'#f87171';
    // v10.37 (۵۰الف): کلیدهای مرتب‌سازی همراهِ نتیجه به‌روز می‌شوند
    if(d.ok!==undefined) r.tr.dataset.aiStV=d.ok?'0':'1';
    r.tr.dataset.aiLatV=(d.latencyMs>0)?String(d.latencyMs):'';
    const lat=r.tr.querySelector('.aiLat');if(lat)lat.textContent=(d.latencyMs>0)?(toFa(d.latencyMs)+'ms'):'—';
    // v9.52: پاسخِ پیام و پاسخِ دستهٔ هر مدل در دو ستونِ جدا
    // v10.37 (۵۰الف): محتوا داخلِ پوششِ .c2 می‌رود، نه مستقیم داخلِ td
    const mr=r.tr.querySelector('.aiMsgRes .c2')||r.tr.querySelector('.aiMsgRes');
    if(mr){
        if(d.ok){
            // v9.57: اگر پاسخِ متن خالی بود (مدل ۲۰۰ داد ولی content نداشت)،
            // به‌جای «✓ پاسخ گرفت» بی‌محتوا، هشدارِ «بدون پاسخ» نشان بده.
            if((d.msgResponse||'').trim())
                mr.innerHTML='<span style="color:#4ade80" title="'+esc(d.msgResponse)+'">'+esc(d.msgResponse)+'</span>';
            else
                mr.innerHTML='<span style="color:#fbbf24" title="اتصال برقرار بود ولی مدل محتوایی برنگرداند (معمولاً مدل reasoning و سقفِ توکن)">⚠️ بدون پاسخ</span>';
        }
        else mr.innerHTML='<span style="color:#f87171" title="'+esc(d.label||'')+'">'+esc(d.error||d.label||'خطا')+'</span>';
    }
    const cr=r.tr.querySelector('.aiCatRes .c2')||r.tr.querySelector('.aiCatRes');
    if(cr){
        if(d.catResponse)cr.innerHTML='<span style="color:#a78bfa">'+esc(d.catResponse)+'</span>';
        else cr.innerHTML='<span style="color:#64748b">—</span>';
    }
    aiTestRenderCounters();
    aiTestApplyGreenFilter();   // v9.64: با فعال بودن «فقط سبزها»، وضعیتِ این ردیف را هم اعمال کن
}
function aiRenderTestState(st){
    if(!st)return;
    if(st.current&&st.current.model&&$('aiTestCur'))$('aiTestCur').textContent='در حال تست: '+esc(st.current.model);
    else if(st.done&&$('aiTestCur'))$('aiTestCur').textContent='🏁 '+esc(st.summary||'تمام شد');
    else if(st.stopping&&$('aiTestCur'))$('aiTestCur').textContent='⏹ در حال توقف...';
    // اگر هنوز ردیفی ساخته نشده و آیتم‌هایی هست، ابتدا کل ردیف‌ها را از روی total بساز
    if(aiTestTotCount===0&&st.total>0){
        const tbody=$('aiTestTbody');if(tbody)tbody.innerHTML='';
        aiTestTotCount=0;aiTestWaitCount=0;aiTestOkCount=0;aiTestFailCount=0;aiTestRows={};
        if(st.total>0)aiTestWaitCount=st.total;
        aiTestRenderCounters();
    }
    (st.items||[]).forEach(it=>aiSetTestRow(it));
    if(st.done){ if($('aiTestCur'))$('aiTestCur').textContent='🏁 '+esc(st.summary||'تمام شد'); }
    // خلاصهٔ عیب‌یابی (قابل‌دسترس‌نبودن اندپوینت‌ها / مشکل روش اتصال)
    const db=$('aiTestDiag');
    if(db&&st.diag){
        const netIssues=Object.entries(st.diag).filter(([,d])=>d&&d.net_issue===true);
        const unreach=Object.entries(st.diag).filter(([,d])=>d&&d.reachable===false&&d.net_issue!==true);
        if(netIssues.length){
            aiRenderDiagBox(db,'net',netIssues.length,
              '<b>⚠️ روش اتصال فعلی روی این شبکه کار نمی‌کند:</b><br>'
              +netIssues.map(([id,d])=>'• <b dir="ltr">'+esc(id)+'</b>: '+esc(d.net_hint||d.first_error||'')).join('<br>')
              +'<br><span style="color:#fbbf24">خودِ هاست به اندپوینت دسترسی دارد (مستقیم جواب می‌دهد). روش اتصال را روی «مستقیم» بگذارید، یا یک Worker/پروکسی سالم اضافه کنید.</span>');
        } else if(unreach.length){
            aiRenderDiagBox(db,'unreach',unreach.length,
              '<b>⚠️ هاست به این ارائه‌دهنده‌ها دسترسی ندارد:</b><br>'
              +unreach.map(([id,d])=>'• <b dir="ltr">'+esc(id)+'</b>: '+esc(d.first_error||d.last_label||'')).join('<br>')
              +'<br><span style="color:#fbbf24">این معمولاً DNS بسته/مسموم، تایم‌اوت یا بلاک IP هاست است. روش اتصال (DoH/پروکسی/Worker) را عوض کنید.</span>');
        } else {
            db.innerHTML='';
        }
    }
}
/* ==================================================================
 *  v10.20 (۳۳ب): باکسِ «مشکلات مدل‌ها» — کشویی و پیش‌فرض بسته
 *
 *  این باکس در پایینِ مودالِ تستِ مدل‌ها همیشه باز بود و با چند
 *  ارائه‌دهندهٔ مشکل‌دار چند سطر می‌شد؛ جدولِ نتایج را می‌فشرد و در
 *  موبایل عملاً نیمی از پنجره را می‌گرفت. حالا فقط یک نوارِ یک‌خطی
 *  با تعدادِ مشکل دیده می‌شود و جزئیات با کلیک باز می‌شود.
 *
 *  دو نکتهٔ ریز که رعایت شده:
 *   • حالتِ باز/بسته در aiDiagOpen نگه داشته می‌شود تا پولینگِ هر
 *     دو ثانیه‌ای، باکسی را که کاربر تازه باز کرده دوباره نبندد.
 *   • فقط وقتی محتوا واقعاً عوض شود دوباره رسم می‌شود، وگرنه هر
 *     رفرش انتخابِ متنِ کاربر را می‌پراند.
 * ================================================================== */
let aiDiagOpen=false, aiDiagSig='';
function aiRenderDiagBox(db,kind,count,innerHtml){
    const sig=kind+'|'+count+'|'+innerHtml.length;
    if(db.dataset.sig===sig&&db.dataset.open===(aiDiagOpen?'1':'0'))return;   // بدون تغییر، دست نزن
    db.dataset.sig=sig; db.dataset.open=aiDiagOpen?'1':'0';
    const warm = kind==='net';
    const bg   = warm?'#422006':'#3b1e1e';
    const bd   = warm?'#f59e0b':'#ef4444';
    const fg   = warm?'#fcd34d':'#fca5a5';
    const ttl  = warm?'مشکلِ روشِ اتصال':'ارائه‌دهنده‌های خارج از دسترس';
    db.innerHTML='<div style="margin-top:8px;background:'+bg+';border:1px solid '+bd+';border-radius:6px;overflow:hidden">'
      +'<div onclick="aiToggleDiag()" style="display:flex;align-items:center;gap:7px;padding:7px 9px;cursor:pointer;font-size:11px;color:'+fg+';user-select:none">'
      +'<span id="aiDiagCaret" style="display:inline-block;transition:transform .18s;transform:rotate('+(aiDiagOpen?'90':'0')+'deg)">◀</span>'
      +'<b>⚠️ مشکلات مدل‌ها</b>'
      +'<span style="background:'+bd+';color:'+bg+';border-radius:9px;padding:0 7px;font-size:10px;font-weight:800">'+toFa(count)+'</span>'
      +'<span style="color:'+fg+';opacity:.75;font-size:10px">'+esc(ttl)+'</span>'
      +'<span style="flex:1"></span>'
      +'<span id="aiDiagLbl" style="font-size:10px;opacity:.7">'+(aiDiagOpen?'بستن':'نمایش جزئیات')+'</span></div>'
      +'<div id="aiDiagBody" style="display:'+(aiDiagOpen?'block':'none')+';padding:0 9px 9px;font-size:11px;color:'+fg+';line-height:1.85">'
      +innerHtml+'</div></div>';
}
function aiToggleDiag(){
    aiDiagOpen=!aiDiagOpen;
    const b=$('aiDiagBody'), c=$('aiDiagCaret'), db=$('aiTestDiag');
    if(b)b.style.display=aiDiagOpen?'block':'none';
    if(c)c.style.transform='rotate('+(aiDiagOpen?'90':'0')+'deg)';
    const l=$('aiDiagLbl'); if(l)l.textContent=aiDiagOpen?'بستن':'نمایش جزئیات';
    if(db)db.dataset.open=aiDiagOpen?'1':'0';
}
function aiTestAll(){
    const per=$('aiTestPerProvider')?parseInt($('aiTestPerProvider').value)||50:50;
    const only=$('aiTestOnlyUntested')&&$('aiTestOnlyUntested').checked?1:0;
    // v9.52: پیام و دستهٔ تستِ قابل‌تنظیم — برای نمایش در مودال هم نگه می‌داریم
    aiTestMsgVal=($('aiTestMsg')&&$('aiTestMsg').value.trim())||'سلام';
    aiTestCatVal=($('aiTestCat')&&$('aiTestCat').value.trim())||'ادو پرفیوم';
    // v9.56: تاخیر بین تست‌ها (میلی‌ثانیه)
    aiTestDelayVal=Math.max(0,parseInt(($('aiTestDelay')&&$('aiTestDelay').value)||'120',10)||120);
    aiOpenTestModal();
    const tbody=$('aiTestTbody');if(!tbody)return;
    tbody.innerHTML='';
    aiTestTotCount=0;aiTestOkCount=0;aiTestFailCount=0;aiTestWaitCount=0;aiTestRows={};
    fetch('?ai_test_start=1&per_provider='+per+'&only_untested='+only
        +'&msg='+encodeURIComponent(aiTestMsgVal)+'&cat='+encodeURIComponent(aiTestCatVal)
        +'&delay='+aiTestDelayVal+aiTestReadOpts()).then(r=>r.json()).then(d=>{
        if(d&&d.running&&!d.ok){ if($('aiTestCur'))$('aiTestCur').textContent='در حال اجراست — ادامهٔ آن را نشان می‌دهم'; }
        else if($('aiTestCur'))$('aiTestCur').textContent='شروع تست در پس‌زمینهٔ سرور...';
        aiPollTest();
    }).catch(()=>{ if($('aiTestCur'))$('aiTestCur').textContent='خطا در شروع تست'; });
}
/* v9.58: «نمایش جدول» — مودالِ نتایج را باز می‌کند و نتایجِ ذخیره‌شدهٔ آخر را
   نشان می‌دهد، بدون شروعِ تستِ تازه. اگر تستی در حال اجراست، همان‌جا ادامه را
   پایش می‌کند. */
function aiShowTestTable(){
    aiOpenTestModal();
    // مقادیرِ جاری را از فیلدها تازه کن (در صورت تغییر)
    aiTestMsgVal=($('aiTestMsg')&&$('aiTestMsg').value.trim())||'سلام';
    aiTestCatVal=($('aiTestCat')&&$('aiTestCat').value.trim())||'ادو پرفیوم';
    aiTestDelayVal=Math.max(0,parseInt(($('aiTestDelay')&&$('aiTestDelay').value)||'120',10)||120);
    fetch('?ai_test_status=1').then(r=>r.json()).then(st=>{
        // نتایجِ ذخیره‌شده را (اگر هست) رندر کن
        if(st){
            if(st.items&&st.items.length){
                const tbody=$('aiTestTbody'); if(tbody)tbody.innerHTML='';
                aiTestTotCount=0;aiTestOkCount=0;aiTestFailCount=0;aiTestWaitCount=0;aiTestRows={};
                aiRenderTestState(st);
            }
            if(st.running){
                if($('aiTestCur'))$('aiTestCur').textContent='در حال اجراست — نتایج زنده به‌روز می‌شوند';
                aiPollTest();
            }else if(st.done&&$('aiTestCur')){
                $('aiTestCur').textContent='🏁 '+esc(st.summary||'پایان تست');
            }else{
                if($('aiTestCur'))$('aiTestCur').textContent='هنوز تستی اجرا نشده — دکمهٔ «▶ شروع / ادامه» را بزنید';
            }
        }
    }).catch(()=>{ if($('aiTestCur'))$('aiTestCur').textContent='خطا در خواندن وضعیت'; });
}
/* v10.218: حلقهٔ فیدبک AI — خطای Worker/پورت را از endpoint واقعی می‌گیرد
   و فقط مدل‌های شکست‌خوردهٔ غیرِ credit/rate-limit را دوباره تست و ذخیره می‌کند. */
function aiFeedbackFix(){
    const box=$('aiFixTR')||$('aiTR');
    if(box)box.innerHTML='<div class="alert alert-info" style="padding:8px;font-size:11px">🧭 حلقهٔ فیدبک در حال اجراست: probe مسیرها + تست دوبارهٔ خطاهای قابل رفع...</div>';
    const n=getAiNet();
    const q=new URLSearchParams({ai_feedback_fix:'1',apply:'1',limit:'25',
        msg:(($('aiTestMsg')&&$('aiTestMsg').value.trim())||'سلام'),
        net_mode:n.mode,net_resolve_ip:n.resolve_ip,net_doh_url:n.doh_url,
        net_worker_url:n.worker_url,net_proxy:n.proxy,net_proxy_type:n.proxy_type,
        net_proxy_auth:n.proxy_auth,net_timeout:String(n.timeout),net_fallback:String(n.fallback)});
    fetch('?'+q.toString()).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){ if(box)box.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc((d&&d.error)||'خطا')+'</div>'; return; }
        if(d.net_after){ const nn=Object.assign({},d.net_after); if(nn.proxy_auth==='***')nn.proxy_auth=n.proxy_auth; applyAiNet(nn); }
        let h='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:10px;font-size:11px;line-height:1.9">';
        h+='<div style="color:#fbbf24;font-weight:800;margin-bottom:6px">🧭 نتیجهٔ فیدبک و رفع AI</div>';
        h+='<div style="color:#94a3b8">'+esc(d.summary||'')+'</div>';
        if(d.recommended)h+='<div>روش پیشنهادی: <b style="color:#67e8f9">'+esc(d.recommended.mode||'')+'</b> — <span style="color:#94a3b8">'+esc(d.recommended.why||'')+'</span></div>';
        if((d.changes||[]).length)h+='<div style="color:#4ade80">تغییرها: '+esc((d.changes||[]).join(' · '))+'</div>';
        h+='<div>کاندیدا: '+toFa(d.candidates||0)+' · رفع‌شده: <b style="color:#4ade80">'+toFa(d.fixed||0)+'</b> · هنوز ناموفق: <b style="color:#fca5a5">'+toFa(d.still_failed||0)+'</b> · credit/rate رد شد: '+toFa(((d.skipped&&((d.skipped.billing||0)+(d.skipped.ratelimit||0)))||0)+(d.excluded_after_retest||0))+'</div>';
        if(d.probe){
            h+='<div style="margin-top:6px;color:#67e8f9;font-weight:700">Probe مسیرها</div>';
            ['direct','doh','worker','proxy','dns'].forEach(k=>{const m=d.probe[k]; if(!m)return; h+='<div>'+(m.reached?'🟢':'🔴')+' '+esc(k)+' — HTTP '+toFa(m.http||0)+' · '+esc(m.label||m.error||'')+(m.worker_style?' · '+esc(m.worker_style):'')+'</div>';});
        }
        if((d.results||[]).length){
            h+='<details style="margin-top:6px"><summary style="cursor:pointer;color:#c4b5fd">جزئیات مدل‌های دوباره‌تست‌شده</summary><div style="max-height:180px;overflow:auto;margin-top:4px">';
            d.results.slice(0,40).forEach(x=>{h+='<div style="border-top:1px solid #1e293b;padding:3px 0">'+(x.ok?'✅':'❌')+' <span dir="ltr">'+esc(x.provider||'')+' / '+esc(x.model||'')+'</span> — HTTP '+toFa(x.code||0)+' · '+esc(x.kind||x.diag||'')+(x.payloadRepair?' · اصلاح: '+esc(x.payloadRepair):'')+' · '+esc(x.error||'')+'</div>';});
            h+='</div></details>';
        }
        h+='</div>';
        if(box)box.innerHTML=h;
        try{ aiStatsLoad(); }catch(e){}
    }).catch(()=>{ if(box)box.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ خطای شبکه در اجرای فیدبک</div>'; });
}

/* v9.99: «رفعِ گیر» — وقتی پردازهٔ پس‌زمینهٔ تست مرده ولی وضعیت روی «در حال
   اجرا» مانده، قفل را آزاد می‌کند و تست را از همان‌جا که مانده ادامه می‌دهد.
   چون نتیجهٔ هر دور بلافاصله ذخیره شده، مدل‌های تست‌شده دوباره تست نمی‌شوند. */
function aiTestUnstick(){
    aiOpenTestModal();
    aiTestMsgVal=($('aiTestMsg')&&$('aiTestMsg').value.trim())||'سلام';
    aiTestCatVal=($('aiTestCat')&&$('aiTestCat').value.trim())||'ادو پرفیوم';
    aiTestDelayVal=Math.max(0,parseInt(($('aiTestDelay')&&$('aiTestDelay').value)||'120',10)||120);
    if($('aiTestCur'))$('aiTestCur').textContent='🔧 در حال بررسی و رفعِ گیر...';
    fetch('?ai_test_unstick=1&msg='+encodeURIComponent(aiTestMsgVal)
        +'&cat='+encodeURIComponent(aiTestCatVal)
        +'&delay='+aiTestDelayVal+aiTestReadOpts()).then(r=>r.json()).then(d=>{
        if(d&&d.alive){
            if($('aiTestCur'))$('aiTestCur').textContent='✅ تست گیر نکرده — زنده است و ادامه دارد';
            aiPollTest();
            return;
        }
        if(d&&d.ok){
            if($('aiTestCur'))$('aiTestCur').textContent='🔧 قفل آزاد شد — ادامه از مدلِ '+toFa((d.done_before||0)+1)+' به بعد';
            aiPollTest();
        }else if($('aiTestCur')){
            $('aiTestCur').textContent='خطا در رفعِ گیر: '+esc((d&&d.error)||'نامشخص');
        }
    }).catch(()=>{ if($('aiTestCur'))$('aiTestCur').textContent='خطا در رفعِ گیر'; });
}
/* v9.24: بعد از ریفرش، اگر کاری در حال اجراست مودال را باز کن و ادامه بده */
function aiResumeTestModalOnLoad(){
    fetch('?ai_test_status=1').then(r=>r.json()).then(st=>{
        if(st&&st.running){ aiOpenTestModal(); aiPollTest(); }
    }).catch(()=>{});
}
/* v9.53: دکمهٔ «شروع / ادامه» — اگر تستی در حال اجراست آن را ادامه می‌دهد
   (مودالِ زنده را باز می‌کند و poll را ادامه می‌دهد، بدون شروعِ تازه)، و اگر
   نه، یک تستِ تازه با مقادیرِ جاریِ پیام/دسته شروع می‌کند. */
/* ═══════════════════════════════════════════════════════════════════
 *  v10.36 (۴۹د): کارت‌های شمارندهٔ تفصیلی و آماری مدل‌ها
 *
 *  سه لایه اطلاعات، از کلی به جزئی:
 *    ۱) کارت‌های بزرگ — عددهایی که یک نگاه باید جواب بدهند
 *    ۲) دو نوارِ پوشش و سلامت — نسبت‌ها بهتر از عددِ خام درک می‌شوند
 *    ۳) تفکیکِ ارائه‌دهنده و سریع‌ترین مدل‌ها — برای انتخابِ مدلِ مستر
 * ═══════════════════════════════════════════════════════════════════ */
function aiStatCard(icon,label,val,color,hint){
    return '<div class="ai-stat-card"'+(hint?(' title="'+esc(hint)+'"'):'')+'>'
      +'<div class="ai-stat-ico">'+icon+'</div>'
      +'<div class="ai-stat-val" style="color:'+color+'">'+val+'</div>'
      +'<div class="ai-stat-lbl">'+esc(label)+'</div></div>';
}
function aiStatBar(label,pct,color,note){
    const p=Math.max(0,Math.min(100,parseInt(pct)||0));
    return '<div style="margin-bottom:7px">'
      +'<div style="display:flex;align-items:center;gap:6px;font-size:10px;color:#94a3b8;margin-bottom:3px">'
      +'<span style="flex:1">'+esc(label)+'</span>'
      +'<b style="color:'+color+'">'+toFa(p)+'٪</b>'
      +(note?'<span style="color:#64748b">'+esc(note)+'</span>':'')+'</div>'
      +'<div style="height:6px;background:#1e293b;border-radius:3px;overflow:hidden">'
      +'<div style="height:100%;width:'+p+'%;background:'+color+';border-radius:3px;transition:width .5s"></div>'
      +'</div></div>';
}
function aiStatsRender(d){
    const box=$('aiStatCards'); if(!box)return;
    if(!d||!d.ok){box.innerHTML='<div style="grid-column:1/-1;color:#f87171;font-size:10.5px">✗ آمار خوانده نشد</div>';return;}
    if(!d.total){
        box.innerHTML='<div style="grid-column:1/-1;color:#64748b;font-size:10.5px;padding:6px 2px">'
          +'هنوز هیچ ارائه‌دهنده‌ای درون‌ریزی نشده — اول از تبِ «ارائه‌دهنده‌ها» فهرست مدل‌ها را بگیرید.</div>';
        const b0=$('aiStatBars'); if(b0)b0.innerHTML='';
        return;
    }
    let h='';
    h+=aiStatCard('🧠','کلِ مدل‌ها',toFa(d.total),'#e2e8f0','همهٔ مدل‌های درون‌ریزی‌شده از همهٔ ارائه‌دهنده‌ها');
    h+=aiStatCard('🟢','سالم',toFa(d.available),'#4ade80','تست شده و پاسخ داد');
    h+=aiStatCard('🔴','ناموفق',toFa(d.failed),'#f87171','تست شده ولی خطا داد');
    h+=aiStatCard('⏳','تست‌نشده',toFa(d.untested),'#fbbf24','هنوز یک بار هم آزموده نشده');
    h+=aiStatCard('⚡','میانگین تأخیر',d.avg_latency>0?(toFa(d.avg_latency)+'<span style="font-size:9px;color:#64748b">ms</span>'):'—','#67e8f9','میانگینِ زمانِ پاسخ در مدل‌های سالم');
    h+=aiStatCard('🏢','ارائه‌دهنده',toFa(d.providers),'#c4b5fd','ارائه‌دهنده‌هایی که دستِ‌کم یک مدل دارند');
    h+=aiStatCard('🔧','ابزارپذیر',toFa(d.tool_calling),'#a78bfa','مدل‌هایی که tool calling دارند — لازمِ ایجنت');
    h+=aiStatCard('🐢','ریت‌لیمیت',toFa(d.rate_limited),'#fb923c','سهمیه‌شان پر شده — بعداً دوباره تست کنید');
    box.innerHTML=h;

    const bars=$('aiStatBars');
    if(bars){
        let b='';
        b+=aiStatBar('پوششِ تست (چقدر از کاتالوگ آزموده شده)',d.coverage_pct,'#67e8f9',
              toFa(d.tested)+' از '+toFa(d.total));
        b+=aiStatBar('سلامت (از آزموده‌شده‌ها چقدر جواب داد)',d.health_pct,
              d.health_pct>=50?'#4ade80':(d.health_pct>=20?'#fbbf24':'#f87171'),
              toFa(d.available)+' از '+toFa(d.tested));
        if(Array.isArray(d.by_provider)&&d.by_provider.length){
            b+='<details style="margin-top:6px"><summary style="cursor:pointer;font-size:10.5px;color:#94a3b8">'
              +'🏢 تفکیکِ ارائه‌دهنده‌ها ('+toFa(d.by_provider.length)+')</summary>'
              +'<div style="margin-top:5px;background:#0b1220;border:1px solid #1e293b;border-radius:7px;padding:6px 8px">';
            d.by_provider.forEach(function(p,i){
                b+='<div style="display:flex;align-items:center;gap:6px;font-size:10px;padding:3px 0'
                  +(i>0?';border-top:1px dashed #1e293b':'')+'">'
                  +'<span style="color:#cbd5e1;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(p.name)+'</span>'
                  +'<span style="color:#4ade80">🟢'+toFa(p.ok)+'</span>'
                  +'<span style="color:#f87171">🔴'+toFa(p.fail)+'</span>'
                  +'<span style="color:#64748b">/'+toFa(p.total)+'</span>'
                  +(p.lat>0?'<span style="color:#67e8f9;font-family:ui-monospace,monospace">'+toFa(p.lat)+'ms</span>':'')
                  +'</div>';
            });
            b+='</div></details>';
        }
        if(Array.isArray(d.fastest)&&d.fastest.length){
            b+='<details style="margin-top:5px"><summary style="cursor:pointer;font-size:10.5px;color:#94a3b8">'
              +'🚀 سریع‌ترین مدل‌های سالم</summary>'
              +'<div style="margin-top:5px;background:#0b1220;border:1px solid #1e293b;border-radius:7px;padding:6px 8px">';
            d.fastest.forEach(function(f,i){
                b+='<div style="display:flex;align-items:center;gap:6px;font-size:10px;padding:3px 0'
                  +(i>0?';border-top:1px dashed #1e293b':'')+'">'
                  +'<span style="color:#64748b">'+toFa(i+1)+'.</span>'
                  +'<span style="color:#e2e8f0;flex:1;direction:ltr;text-align:left;font-family:ui-monospace,monospace;'
                  +'overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="'+esc(f.model)+'">'+esc(f.model)+'</span>'
                  +'<span style="color:#94a3b8">'+esc(f.provider)+'</span>'
                  +'<span style="color:#67e8f9;font-family:ui-monospace,monospace">'+toFa(f.lat)+'ms</span></div>';
            });
            b+='</div></details>';
        }
        bars.innerHTML=b;
    }
    const w=$('aiStatWhen');
    if(w){
        if(d.running)w.textContent='🔄 تست در حال اجراست';
        else if(d.last_run>0){
            const mins=Math.floor((Date.now()/1000-d.last_run)/60);
            w.textContent='آخرین تست: '+(mins<1?'همین حالا':(mins<60?(toFa(mins)+' دقیقه پیش'):(toFa(Math.floor(mins/60))+' ساعت پیش')));
        } else w.textContent='';
    }
}
function aiStatsLoad(){
    const box=$('aiStatCards');
    if(box&&!box.dataset.loaded)box.innerHTML='<div style="grid-column:1/-1;color:#93c5fd;font-size:10.5px;padding:6px 2px">⏳ در حال خواندن…</div>';
    fetch('?ai_stats=1').then(r=>r.json()).then(d=>{
        if(box)box.dataset.loaded='1';
        aiStatsRender(d);
    }).catch(()=>{
        if(box)box.innerHTML='<div style="grid-column:1/-1;color:#f87171;font-size:10.5px">✗ خطا در ارتباط</div>';
    });
}

function aiTestStartContinue(){
    const btn=document.getElementById('aiTestStartContinue');
    if(btn){btn.disabled=true;const t=btn.textContent;btn.textContent='⏳ ...';setTimeout(()=>{btn.disabled=false;btn.textContent=t;},1500);}
    fetch('?ai_test_status=1').then(r=>r.json()).then(st=>{
        if(st&&st.running){
            // در حال اجراست → ادامه بده
            aiOpenTestModal();
            aiPollTest();
            if($('aiTestCur'))$('aiTestCur').textContent='ادامهٔ تست در حال اجرا...';
        }else{
            // نه → شروعِ تازه
            aiTestAll();
        }
    }).catch(()=>{ aiTestAll(); });
}
// v8.06: Test AI category selection with a sample product title
function testAiCategory(){
  /* v9.38: اگر مدل کاندید داریم، همهٔ آن‌ها را با هم تست می‌کنیم تا بهترین را
     برگزینیم؛ وگرنه همان تست تک‌مدلیِ قدیمی انجام می‌شود. */
  aiCandLoad(d=>{
    if((d.candidates||[]).length>0){aiCandCategoryTest();return;}
    const r=$('aiTR');const title=prompt('عنوان محصول برای تست دسته‌بندی:','کفش ورزشی مردانه نایک');if(!title)return;
    r.innerHTML='<div style="color:#67e8f9;font-size:11px">🔄 در حال تحلیل «'+esc(title)+'» با AI...</div>';
    fetch('?ai_category=1&title='+encodeURIComponent(title)).then(rr=>rr.json()).then(dd=>{
      if(dd.ok){r.innerHTML='<div class="alert alert-success" style="padding:8px;font-size:11px">✓ دسته: <b>'+esc(dd.category_name)+'</b> ('+dd.category_id+') | مدل: '+esc(dd.ai_model||'')+' | پاسخ AI: '+esc(dd.ai_raw||'')+'</div>';}
      else{r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(dd.error||'خطا')+'</div>';}
    }).catch(()=>{r.innerHTML='<div style="color:#f87171;font-size:11px">✗ خطا شبکه</div>';});
  });
}

function testBsl(){const s=$('bsS'),r=$('bsTR');s.textContent='تست...';s.className='cst tg';r.innerHTML='';const fd=new FormData();fd.append('action','test_basalam');fd.append('token',$('bsTk').value.trim());if($('bsIndirect'))fd.append('net_indirect',$('bsIndirect').checked?'1':'0');fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
if(d.ok){s.textContent='✓';s.className='cst on';r.innerHTML='<div class="alert alert-success" style="padding:8px;font-size:11px">✓ '+esc(d.message)+' | '+esc(d.vendor_title||'')+'</div>';if(d.vendor_id&&!$('bsVid').value)$('bsVid').value=d.vendor_id;saveConn();
showBslVendorModal(d);
}else{s.textContent='✗';s.className='cst off';
let ext='';
if(d.http_code===0){
ext='<div style="margin-top:6px;background:#0f172a;padding:8px;border-radius:6px;font-size:10px;color:#94a3b8;line-height:1.7">';
if(d.curl_error)ext+='<div>جزئیات: <span dir="ltr" style="font-family:monospace">'+esc(d.curl_error)+'</span></div>';
if(d.mode)ext+='<div>روش اتصال: '+esc(d.mode)+'</div>';
ext+='<div style="margin-top:4px;color:#fbbf24">💡 اگر IP هاست توسط باسلام بلاک شده است، تیک «اتصال غیرمستقیم» را فعال کنید و در بخش «اتصال به سایت مبدأ» یک روش (پروکسی، Worker یا DoH) تنظیم و ذخیره کنید.</div>';
ext+='</div>';
}
r.innerHTML='<div style="background:#7f1d1d;color:#fca5a5;padding:8px;font-size:11px">✗ '+esc(d.error||'خطا')+'</div>'+ext;
if(d.http_code===403||d.http_code===401){showBslVendorModal(d);}
}
}).catch(()=>{s.textContent='✗';s.className='cst off';});}
function showBslVendorModal(d){
let html='<div class="bsl-modal-overlay" onclick="if(event.target===this)closeBslVendorModal()">';
html+='<div class="bsl-modal" style="max-width:600px">';
html+='<div class="bsl-modal-head"><h2 style="color:'+(d.ok?'#22c55e':'#f87171')+'">'+(d.ok?'\u2713 \u0627\u0637\u0644\u0627\u0639\u0627\u062a \u063a\u0631\u0641\u0647 \u0628\u0627\u0633\u0627\u0644\u0627\u0645':'\u2717 \u062e\u0637\u0627 \u0627\u062a\u0635\u0627\u0644 \u0628\u0627\u0633\u0627\u0644\u0627\u0645')+'</h2><button class="btn btn-gray" onclick="closeBslVendorModal()">\u2717</button></div>';
if(!d.ok){
html+='<div class="bsl-modal-body" style="padding:20px">';
html+='<div style="background:#7f1d1d;color:#fca5a5;padding:12px;border-radius:8px;margin-bottom:16px;font-size:13px"><b>\u2717 '+esc(d.error||'\u062e\u0637\u0627')+'</b></div>';
