// v7.48: Auto-detect running BSL process on page load (works across devices/refreshes)
// v7.51: Auto-detect running process on page load
(function checkBslRunningOnLoad(){
    // v7.56: On page load, check if there's a running server-side process and just POLL to display progress.
    // NEVER start client-driven sendNextQueueProduct — it conflicts with server-side processing!
    // If server process died, offer "resume from server" button.
    fetch('?poll_bsl=1').then(r=>r.json()).then(d=>{
        if(d&&d.running&&!d.done){
            window._currentBslQueueId=String(d.queue_id||'');
            console.log('Server-side BSL process running on load — resuming polling');
            bSend=true;
            $('bST').classList.remove('hidden');
            $('bP').classList.remove('hidden');$('bR').classList.remove('hidden');$('bSM').classList.remove('hidden');
            const sent=d.sent||0,updated=d.updated||0,skipped=d.skipped||0,failed=d.failed||0,total=d.total||0,current=d.current||0;
            $('bO').textContent=toFa(sent);$('bU').textContent=toFa(updated);$('bK').textContent=toFa(skipped);$('bF').textContent=toFa(failed);$('bX').textContent=toFa(d.retired||0);$('bT').textContent=toFa(total);
            $('bPB').style.width=(total>0?current/total*100:0)+'%';
            const logDiv=$('bR');
            const logs=d.recent_log||[];
            const totalLogCount=d.total_log_count||0;
            for(let i=0;i<logs.length;i++){
                const raw=logs[i];const m=Array.isArray(raw)?raw.map(String).filter(Boolean).join(' · '):String(raw??'');if(!m)continue;let cls='';
                if(m.includes('\u2713'))cls='color:#22c55e;background:#14532d20;padding:3px 8px;font-size:12px;border-radius:4px';
                else if(m.includes('\u2717'))cls='color:#ef4444;background:#7f1d1d20;padding:3px 8px;font-size:12px;border-radius:4px';
                else if(m.includes('\u26a1'))cls='color:#facc15;background:#42200620;padding:3px 8px;font-size:12px;border-radius:4px';
                else if(m.includes('\u23ed'))cls='color:#94a3b8;padding:2px 6px;font-size:11px';
                else cls='color:#64748b;padding:1px 8px;font-size:10px';
                logDiv.insertAdjacentHTML('beforeend','<div style="'+cls+';margin:1px 0">'+esc(m)+'</div>');
            }
            const logNodes=logDiv.children;if(logNodes.length>300){for(let j=0;j<logNodes.length-300;j++)logNodes[0].remove();}
            scrollElBottom(logDiv);
            bslLastLogCount=totalLogCount;bslLastUpdateTime=Date.now();
            if(d.sent_details)bslReportData.sent=d.sent_details;
            if(d.updated_details)bslReportData.updated=d.updated_details;
            if(d.skipped_details)bslReportData.skipped=d.skipped_details;
            if(d.failed_details)bslReportData.failed=d.failed_details;
            if(d.retired_details)bslReportData.retired=d.retired_details;
            let elapsedStr='';
            if(d.started_at>0){const elapsedSec=Math.floor(Date.now()/1000-d.started_at);elapsedStr=elapsedSec>=60?(Math.floor(elapsedSec/60)+' \u062f\u0631\u06cc\u0642\u0647 '+elapsedSec%60+' \u062b\u0627\u0646\u06cc\u0647'):(elapsedSec+' \u062b\u0627\u0646\u06cc\u0647');}
            const pc=parseInt(d.phase_current)||0,pt=parseInt(d.phase_total)||0;
            $('bSS').textContent=(d.phase_label&&pt?(String(d.phase_label)+' — '+toFa(pc)+'/'+toFa(pt)+' ('+Math.round(Number(d.phase_pct??pc*100/pt))+'٪)'):(toFa(current)+'/'+toFa(total)+' ('+(total?Math.round(current/total*100):0)+'٪)'))+(elapsedStr?' | '+elapsedStr:'');
            if(d.last_title)$('bSS').title='\u0645\u062d\u0635\u0648\u0644 \u0641\u0639\u0644\u06cc: '+d.last_title;
            pollBslProgress();
        }else{
            // v7.66: No running process — check for waiting/stuck entries, trigger bsl_backend
            fetch('?bsl_queue_status=1').then(r=>r.json()).then(q=>{
                const stuckEntry=q.entries?.find(e=>e.status==='running'&&e.current>0);
                const waitingEntry=q.entries?.find(e=>e.status==='waiting');
                if(stuckEntry||waitingEntry){
                    // Found waiting or stuck — trigger bsl_backend
                    $('bSS').textContent='\u26a0 \u0631\u0633\u0627\u0646 \u0633\u0631\u0648\u0631 \u0642\u0637\u0639 \u0634\u062f \u2014 \u06a9\u0644\u06cc\u06a9 \u0631\u0627 \u0628\u0631\u0627\u06cc \u0627\u062f\u0627\u0645\u0647';
                    checkBslQueue();
                }else{
                    $('bSS').textContent='';
                    checkBslQueue();
                }
            }).catch(()=>{checkBslQueue();});
        }
        checkBslQueue();
    }).catch(()=>{checkBslQueue();});
})();
// v7.48: Queue management functions
let bslQueuePollTimer=null;
function checkBslQueue(){
    fetch('?bsl_queue_status=1').then(r=>r.json()).then(q=>{
        renderBslQueue(q);
        // v7.66: NEVER start client-driven sendNextQueueProduct — bsl_backend does the work
        // If a 'running' entry is found and no polling is active, just start polling to display progress
        const running=q.entries?.find(e=>e.status==='running');
        if(running&&!bSend){
            console.log('[v7.81 checkBslQueue] Found running entry, starting pollBslProgress (server-side mode)');
            window._currentBslQueueId=String(running.id||'');
            bSend=true;$('bST').classList.remove('hidden');
            $('bP').classList.remove('hidden');$('bR').classList.remove('hidden');$('bSM').classList.remove('hidden');
            pollBslProgress();
        }
        const hasActive=q.entries?.some(e=>e.status==='running'||e.status==='waiting'||e.status==='paused');
        if(hasActive&&!bslQueuePollTimer)bslQueuePollTimer=setInterval(checkBslQueue,3000);
        else if(!hasActive&&bslQueuePollTimer){clearInterval(bslQueuePollTimer);bslQueuePollTimer=null;}
    }).catch(()=>{});
}
function bslRunSendFeedback(btn){
    if(btn){btn.disabled=true;btn.dataset.oldText=btn.textContent;btn.textContent='⏳ بررسی وضعیت…';}
    fetch('?bsl_send_feedback=1',{cache:'no-store'}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok)throw new Error((d&&d.error)||'پاسخ فیدبک نامعتبر است');
        const ident=d.site||{},q=d.queue||{},row=q.active_row||{},cron=d.cron||{},worker=cron.worker||{},book=q.resume_book||{},lockInfo=q.backend_lock||{};
        const notif=(d.notifications&&d.notifications.enabled)||{};
        const lockLabel=lockInfo.probe_ok?(lockInfo.held?'گرفته':'آزاد'):'نامشخص';
        const safe=(v)=>esc(v===undefined||v===null||v===''?'—':String(v));
        const badge=(name,on)=>'<span style="display:inline-block;margin:2px;padding:3px 7px;border-radius:5px;background:'+(on?'#14532d':'#334155')+';color:'+(on?'#86efac':'#cbd5e1')+'">'+safe(name)+': '+(on?'روشن':'خاموش')+'</span>';
        const idle=q.last_heartbeat_age_sec===null?'—':toFa(q.last_heartbeat_age_sec)+' ثانیه';
        let h='<div class="bsl-modal-overlay" id="bslSendFeedbackModal" onclick="if(event.target===this)this.remove()"><div class="bsl-modal" style="max-width:760px">';
        h+='<div class="bsl-modal-head"><h2 style="color:#67e8f9">🩺 عیب‌یابی باسلام، صف و کران</h2><button class="btn btn-gray" onclick="document.getElementById(\'bslSendFeedbackModal\').remove()">✕</button></div><div class="bsl-modal-body" style="padding:14px;max-height:75vh;overflow:auto">';
        h+='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;margin-bottom:10px"><b style="color:#a5f3fc">سایتِ صادرکننده</b><div style="font-size:11px;margin-top:5px">'+safe(ident.host_path||ident.label)+' · v'+safe(ident.version)+' · instance #'+safe(ident.instance_id)+'</div></div>';
        h+='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;margin-bottom:10px"><b style="color:#fbbf24">صفِ منتخب</b>';
        h+='<div style="font-size:11px;line-height:1.8;margin-top:5px">ردیف: '+safe(row.id)+' · وضعیت: '+safe(row.status)+' · پروفایل: '+safe(row.profile)+' · غرفه: '+safe(row.shop)+' (#'+safe(row.vendor_id)+')<br>';
        h+='پیشرفت: '+toFa(row.current||0)+'/'+toFa(row.total||0)+' · '+safe(row.phase_label||row.phase)+' · آخرین ضربان: '+idle+'<br>';
        h+='progress مالک همین ردیف است: '+(q.progress_belongs_to_active_row?'بله':'خیر/نامشخص')+' · قفل worker: '+lockLabel+' · stop فعال: '+(q.stop_signal&&q.stop_signal.active?'بله':'خیر')+'<br>';
        h+='نگهبان صف: '+(q.watchdog_enabled?'روشن':'خاموش')+' · resume خودکار: '+(q.auto_resume_enabled?'روشن':'خاموش')+' · آستانه: '+toFa(q.stall_after_sec||0)+' ثانیه<br>';
        h+='تلاش‌های resume: '+toFa(book.tries||0)+'/'+toFa(3)+' · وضعیت آخر: '+safe(book.status)+' · dispatch: '+safe(book.dispatch_mode)+' · PID: '+safe(book.dispatch_pid||'—')+'</div></div>';
        h+='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;margin-bottom:10px"><b style="color:#c4b5fd">کران و اعلان‌ها</b><div style="font-size:11px;line-height:1.8;margin-top:5px">آخرین کران: '+(cron.last_file_age_sec===null?'ثبت نشده':toFa(cron.last_file_age_sec)+' ثانیه پیش')+' · کران داخلی: '+(cron.internal_enabled?'روشن':'خاموش')+'<br>';
        h+='worker: '+(worker.active?'فعال':'غیرفعال')+' · heartbeat worker: '+(worker.heartbeat_age_sec===null?'—':toFa(worker.heartbeat_age_sec)+' ثانیه')+' · نسخه worker: '+safe(worker.version)+'<br>';
        h+=badge('پینگ کران',!!notif.cron_ping)+badge('خطای اجرا',!!notif.run_fail)+badge('گزارش همگام‌سازی',!!notif.sync_report)+badge('مغایرت‌گیری',!!notif.recon_auto_report)+badge('اصلاح دسته',!!notif.catfix_auto_report);
        h+='<div style="font-size:10px;color:#94a3b8;margin-top:5px">سایر تیک‌های رویداد:</div>';
        h+=badge('قیمت',!!notif.src_price)+badge('موجودی',!!notif.src_stock)+badge('بازنشستگی',!!notif.retire)+badge('سفارش تازه',!!notif.order_new)+badge('وضعیت سفارش',!!notif.order_status)+badge('پیام مشتری',!!notif.chat_msg)+badge('محصول تازه',!!notif.product_new)+badge('وضعیت محصول',!!notif.product_status)+badge('مرجوعی',!!notif.order_refund);
        h+='<details style="margin-top:6px;font-size:10px"><summary style="cursor:pointer;color:#cbd5e1">آخرین تصمیم‌های watchdog / send pump</summary><pre style="white-space:pre-wrap;direction:ltr;color:#94a3b8">'+safe(JSON.stringify({watchdog:cron.watchdog||[],send_pump:cron.send_pump||{}},null,2))+'</pre></details>';
        h+='<div style="color:#94a3b8;margin-top:5px">خاموش‌بودن پینگ کران فقط heartbeat را خاموش می‌کند؛ خطای صف، گزارش همگام‌سازی و رویدادهای دیگر تیک‌های جداگانه دارند.</div></div></div>';
        h+='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;margin-bottom:10px"><b style="color:#fca5a5">نشانه‌های تشخیص</b><ul style="margin:6px 18px 0 0;padding:0;font-size:11px;line-height:1.8">';
        (q.diagnosis||[]).forEach(x=>{h+='<li>'+safe(x)+'</li>';});h+='</ul></div>';
        if((d.groups||[]).length){h+='<div style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px;margin-bottom:10px"><b style="color:#f87171">خطاهای ذخیره‌شده</b>';
            d.groups.forEach(g=>{h+='<div style="font-size:11px;margin-top:5px">'+safe(g.title)+' × '+toFa(g.count)+' — '+safe(g.solution)+'</div>';});h+='</div>';}
        if((d.notifications&&d.notifications.last_ping_attempts||[]).length){h+='<details style="background:#0f172a;border:1px solid #334155;border-radius:8px;padding:9px"><summary style="cursor:pointer;color:#cbd5e1;font-size:11px">۵ تلاش آخرِ پینگ</summary>';
            d.notifications.last_ping_attempts.forEach(p=>{h+='<div style="font-size:10px;color:#94a3b8;margin-top:4px">'+safe(p.source)+' · '+(p.ok?'موفق':'ناموفق/ردشده')+' · '+safe(JSON.stringify(p.delivery||{}))+'</div>';});h+='</details>';}
        h+='<div style="text-align:center;margin-top:12px"><button class="btn btn-cyan" onclick="document.getElementById(\'bslSendFeedbackModal\').remove()">بستن</button></div></div></div>';
        const old=document.getElementById('bslSendFeedbackModal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',h);
    }).catch(e=>{showToast('فیدبک ارسال در دسترس نیست: '+(e.message||'خطای شبکه'),1);})
    .finally(()=>{if(btn){btn.disabled=false;btn.textContent=btn.dataset.oldText||'🩺 عیب‌یابی ارسال و کران';}});
}
/* v10.23 (۳۶ه): بلوکِ شمارنده‌های تفکیکیِ غرفه‌ها.
 *
 *  ورودی: آرایهٔ shop_stats که بک‌اند می‌سازد — هر عضو
 *  {vid,name,is_default,sent,updated,skipped,failed}. اگر فقط یک غرفه در
 *  کار باشد چیزی نشان داده نمی‌شود، چون ردیفِ جمعِ بالای کارت همان است و
 *  تکرارش فقط شلوغی است.
 *
 *  خطِ جداکننده: بین هر دو غرفه یک <div> با border-top کشیده می‌شود (نه
 *  border روی خودِ بلوک) تا بالای غرفهٔ اول و پایینِ غرفهٔ آخر خطِ اضافه
 *  نیفتد و مرزها دقیقاً «بینِ» غرفه‌ها دیده شوند.
 */
function bslShopStatsHtml(rows,compact){
    /* v10.36 (۴۹ب): شرطِ «کمتر از ۲ ردیف ⇒ چیزی نشان نده» برداشته شد.
       منطقش این بود که «با یک غرفه، ردیفِ جمعِ بالا همان است». ولی در عمل
       دقیقاً همان حالتی را پنهان می‌کرد که کاربر دنبالش بود: وقتی غرفهٔ
       دوم هنوز هیچ ردیفی نساخته (توکن غلط، شناسهٔ اشتباه) فقط یک ردیف
       ساخته می‌شد و کلِ بلوک ناپدید می‌شد — یعنی «تفکیک دیده نمی‌شود».
       حالا هر وقت دستِ‌کم یک ردیف باشد نشان داده می‌شود. */
    if(!Array.isArray(rows)||rows.length<1)return '';
    const cell=function(v,color,icon,label){
        return '<span style="display:inline-flex;align-items:center;gap:3px;color:'+color+'">'
              +icon+' <b>'+toFa(v||0)+'</b>'
              +(compact?'':'<span style="color:#64748b">'+label+'</span>')+'</span>';
    };
    let h='<div style="margin-top:6px;background:#0b1220;border:1px solid #1e293b;border-radius:8px;padding:6px 8px">'
      +'<div style="font-size:9.5px;color:#67e8f9;font-weight:700;margin-bottom:4px">🏪 تفکیکِ غرفه‌ها</div>';
    rows.forEach(function(s,i){
        h+='<div style="padding:5px 0'+(i>0?';border-top:1px dashed #334155':'')+'">'
          +'<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">'
          +'<span style="color:#e2e8f0;font-size:10.5px;font-weight:700">'+esc(s.name||('غرفهٔ '+s.vid))+'</span>'
          +(s.is_default?'<span style="font-size:8.5px;color:#0f172a;background:#67e8f9;border-radius:4px;padding:0 5px">پیش‌فرض</span>':'')
          +'<span style="color:#475569;font-size:9px;font-family:ui-monospace,monospace">#'+toFa(s.vid)+'</span>'
          +(()=>{/* v10.87 / v10.440: per-shop 3-layer price badge */
              const vd=s.is_default?null:((bslExtraVendors||[]).find(v=>v&&parseInt(v.vendor_id)===s.vid)||null);
              const vMode=vd?(vd.price_mode||'none'):'none'; const vVal=vd?parseFloat(vd.price_val||0):0;
              const pMode=($('priceMode')||{}).value||'none'; const pVal=parseFloat(($('priceVal')||{}).value)||0;
              const pRound=parseInt(($('roundPrice')||{}).value)||0;
              const bsCfg=typeof liveDestCfg==='function'?liveDestCfg('bs'):{price_mode:($('bsPMode')||{}).value||'none',price_val:parseFloat(($('bsPVal')||{}).value)||0,price_round:parseInt(($('bsPRound')||{}).value)||0};
              const prev=bslShopThreeLayerPreview(100000,pMode,pVal,pRound,bsCfg.price_mode||'none',parseFloat(bsCfg.price_val)||0,parseInt(bsCfg.price_round)||0,vMode,vVal);
              const pct=prev.pct; if(pct===0&&(bsCfg.price_mode||'none')==='none'&&vMode==='none')return '';
              const col=pct>0?'#4ade80':(pct<0?'#f87171':'#94a3b8');
              return '<span style="font-size:9px;color:'+col+';border:1px solid '+col+';border-radius:3px;padding:0 4px">'+(pct>=0?'+':'')+toFa(pct)+'%</span>';
          })()
          +'<span style="flex:1"></span>'
          +'<span style="display:flex;gap:9px;font-size:10px">'
          + cell(s.sent,'#4ade80','✅','جدید')
          + cell(s.updated,'#facc15','⚡','آپدیت')
          + cell(s.skipped,'#94a3b8','⏭','تکراری')
          + cell(s.failed,'#f87171','❌','خطا')
          +'</span></div></div>';
    });
    return h+'</div>';
}


/* v10.102: صف‌های ارسال تکی پیش‌فرض بسته و کشویی */
function toggleSendQueuePane(which){
    const body=$(which==='woo'?'wooQueueBody':'bslQueueBody');
    const arrow=$(which==='woo'?'wooQueueArrow':'bslQueueArrow');
    if(!body)return;
    const open=body.style.display==='none'||body.style.display==='';
    body.style.display=open?'block':'none';
    if(arrow)arrow.textContent=open?'▲':'▼';
    try{localStorage.setItem('amphp_qpane_'+which, open?'1':'0');}catch(e){}
}
function restoreSendQueuePanes(){
    ['woo','bsl'].forEach(function(which){
        let pref='0';
        try{pref=localStorage.getItem('amphp_qpane_'+which)||'0';}catch(e){}
        const body=$(which==='woo'?'wooQueueBody':'bslQueueBody');
        const arrow=$(which==='woo'?'wooQueueArrow':'bslQueueArrow');
        if(!body)return;
        if(pref==='1'){body.style.display='block';if(arrow)arrow.textContent='▲';}
        else{body.style.display='none';if(arrow)arrow.textContent='▼';}
    });
}
try{document.addEventListener('DOMContentLoaded',restoreSendQueuePanes);}catch(e){}
try{setTimeout(restoreSendQueuePanes,0);}catch(e){}

/* v10.127: جمعِ محصولاتِ حذف/بایگانی‌شده از ردیف‌هایِ بازنشستگیِ صفِ ارسال */
function sendQueueRetireAgg(entries){
    let retired=0,notFound=0,failed=0;
    (entries||[]).forEach(function(e){
        if(!e)return;
        if(!(e.retire_report||e.kind==='retire'||e.trigger==='retire'))return;
        retired+=Number(e.sent||0);
        notFound+=Number(e.skipped||0);
        failed+=Number(e.failed||0);
    });
    return {retired:retired,notFound:notFound,failed:failed};
}
function renderSendQueueProfileSummary(which,entries,activeSend){
    const badge=$(which==='woo'?'wooQueueProfilesBadge':'bslQueueProfilesBadge');
    if(!badge)return;
    const grouped=new Map();
    (Array.isArray(entries)?entries:[]).forEach(function(e){
        const state=String((e||{}).status||'');
        if(!['running','waiting','paused'].includes(state))return;
        const name=String(e.profile_name||'').trim();
        const key=String(e.profile_key||name||'__unknown__').trim()||'__unknown__';
        let g=grouped.get(key);
        if(!g){g={key:key,name:name,running:0,waiting:0,paused:0};grouped.set(key,g);}
        if(!g.name&&name)g.name=name;
        g[state]++;
    });
    const profiles=Array.from(grouped.values());
    const live=activeSend&&activeSend.queue_id?activeSend:null;
    const liveName=live?String(live.profile_name||live.profile_key||'پروفایل نامشخص'):'';
    const liveShop=live&&live.shop_name?' · 🏪 '+esc(live.shop_name):'';
    const liveProgress=live?' · '+toFa(live.current||0)+' از '+toFa(live.total||0):'';
    const liveHtml=live
      ?'<div style="display:flex;align-items:center;gap:8px;padding:8px 10px;margin-bottom:6px;border:1px solid #22c55e88;border-radius:10px;background:#052e164d;color:#dcfce7;box-shadow:0 0 0 2px #22c55e12"><span style="font-size:16px">🟢</span><span style="min-width:0"><b style="display:block;font-size:11px">در حال ارسال واقعی: '+esc(liveName)+'</b><small style="color:#86efac">'+(which==='bsl'?'باسلام':'ووکامرس')+liveShop+liveProgress+'</small></span></div>'
      :'<div style="padding:6px 9px;margin-bottom:6px;border:1px solid #475569;border-radius:9px;background:#0f172a;color:#94a3b8;font-size:10px">⚪ در حال حاضر worker زنده‌ای در حال ارسال نیست</div>';
    if(!profiles.length){badge.innerHTML=liveHtml+'<span style="color:#64748b">پروفایل دیگری در صف نیست</span>';return;}
    profiles.sort(function(a,b){
        const rank=function(x){return x.running?0:(x.waiting?1:2);};
        return rank(a)-rank(b)||String(a.name||a.key).localeCompare(String(b.name||b.key));
    });
    const chips=profiles.map(function(p){
        const name=p.name||(p.key==='__unknown__'?'پروفایل نامشخص':p.key);
        const states=[];
        if(p.running)states.push('🔄 '+toFa(p.running)+' وظیفه در حال ارسال');
        if(p.waiting)states.push('⏳ '+toFa(p.waiting)+' وظیفه در صف');
        if(p.paused)states.push('⏸ '+toFa(p.paused)+' وظیفه متوقف');
        return '<span style="display:inline-block;margin:2px 6px 0 0;padding:2px 7px;border:1px solid #334155;border-radius:999px;background:#0f172a;color:#e2e8f0;font-size:9px;max-width:100%;vertical-align:middle" title="'+esc(p.key||name)+'">👤 '+esc(name)+' <span style="color:#94a3b8">'+states.join(' · ')+'</span></span>';
    });
    badge.innerHTML=liveHtml+'<div><span style="color:#94a3b8;font-weight:600">پروفایل‌های صف:</span> '+chips.join('')+'</div>';
}
function sendQueueVisualCard(e,opt){
    opt=opt||{};const total=parseInt(e.total)||0,cur=Math.min(total,parseInt(e.current)||0);
    const phTotal=parseInt(e.phase_total)||0,phCur=Math.min(phTotal,parseInt(e.phase_current)||0),hasPhase=e.status==='running'&&phTotal>0&&e.phase_label&&e.phase!=='send';
    const done=e.status==='done',failed=e.status==='failed',shopDisabled=!!e.shop_disabled;
    const pct=shopDisabled?(total>0?Math.max(0,Math.min(100,Math.round(cur*100/total))):0):(done?100:(hasPhase?Math.max(0,Math.min(100,Math.round(Number(e.phase_pct??(phCur*100/phTotal))))):(total>0?Math.max(0,Math.min(100,Math.round(cur*100/total))):0)));
    const labels={waiting:'در انتظار شروع',running:'در حال پردازش',paused:'موقتاً متوقف',done:'تکمیل شده',failed:'نیازمند بررسی'};
    const colors={waiting:'#fbbf24',running:opt.accent||'#38bdf8',paused:'#fb923c',done:'#4ade80',failed:'#f87171'};
    const processed=shopDisabled?cur:(done?total:cur),remain=Math.max(0,total-processed);
    const staleRunning=e.status==='running'&&!e._worker_live,visualStatus=shopDisabled?'paused':(staleRunning?'paused':e.status);
    const status=shopDisabled?'غرفه غیرفعال — ارسال متوقف شد':(staleRunning?'worker متوقف — آمادهٔ ادامه':(labels[e.status]||e.status));
    const isRetire=!!(e.retire_report||e.kind==='retire'||e.trigger==='retire');
    const profileName=String(e.profile_name||'').trim();
    const profileKey=String(e.profile_key||'').trim();
    const profileLabel=profileName||profileKey||'پروفایل نامشخص';
    const retired=parseInt(e.retired??e.archived??e.deleted??(isRetire?e.sent:0))||0;
    const newSent=isRetire?0:(parseInt(e.sent)||0);
    let chips='<span class="sendq-chip" style="color:var(--sq);font-weight:800">'+esc(opt.destination||'مقصد فروش')+'</span>';
    if(e._worker_live)chips+='<span class="sendq-chip" style="color:#86efac;background:#14532d">🟢 ارسال واقعی فعلی</span>';
    else if(staleRunning)chips+='<span class="sendq-chip" style="color:#fdba74;background:#7c2d12">⚠ worker متوقف</span>';
    const _qMode=(e.shop_send_mode||(e.config&&e.config.shop_send_mode)||'');
    if(_qMode==='parallel')chips+='<span class="sendq-chip" style="color:#67e8f9;background:#083344">⚡ ارسال موازی غرفه‌ها</span>';
    else if(_qMode==='serial'||(e.batch_id&&e.shop_vendor_id))chips+='<span class="sendq-chip" style="color:#c4b5fd;background:#2e1065">📋 ارسال سری (نوبتی)</span>';
    if(e.trigger==='manual_sync')chips+='<span class="sendq-chip">👤 همگام‌سازی دستی</span>';if(e.auto_sync)chips+='<span class="sendq-chip">⏱ همگام‌سازی دوره‌ای</span>';if(e.shop_name)chips+='<span class="sendq-chip">🏪 '+esc(e.shop_name)+'</span>';if(e.batch_id)chips+='<span class="sendq-chip">بسته '+esc(String(e.batch_id).slice(-8))+'</span>';if(isRetire)chips+='<span class="sendq-chip">🗂 بازنشستگی</span>';
    const metric=(n,l,c,important)=>'<div class="sendq-metric'+(important?' sendq-metric-retired':'')+'"><b'+(c?' style="color:'+c+'"':'')+'>'+toFa(parseInt(n)||0)+'</b>'+l+'</div>';
    const reason=e.fail_reason||e.error||'';
    return '<article class="sendq-card is-'+esc(visualStatus||'waiting')+'" style="--sq:'+(opt.accent||'#38bdf8')+'" onclick="'+opt.detailFn+'(\''+e.id+'\')">'
      +'<div class="sendq-head"><div class="sendq-logo">'+(opt.icon||'📦')+'</div><div><div class="sendq-name" title="'+esc(profileKey||profileLabel)+'">👤 پروفایل ارسال: '+esc(profileLabel)+'</div><div class="sendq-context">'+chips+'<span class="sendq-chip">'+toFa(total)+' محصول</span></div></div><span class="sendq-status" style="color:'+colors[visualStatus]+';background:'+colors[visualStatus]+'18;border:1px solid '+colors[visualStatus]+'55">'+status+'</span></div>'
      +'<div class="sendq-progress-head"><b>'+(hasPhase?esc(e.phase_label):toFa(pct)+'٪ انجام شده')+'</b><span>'+(hasPhase?(toFa(phCur)+' از '+toFa(phTotal)+' · '+toFa(pct)+'٪'):(toFa(processed)+' از '+toFa(total)+' · '+toFa(remain)+' باقی‌مانده'))+'</span></div><div class="sendq-track"><div class="sendq-fill" style="width:'+pct+'%"></div></div>'
      +'<div class="sendq-metrics">'+metric(newSent,'جدید','#4ade80')+metric(e.updated,'آپدیت','#facc15')+metric(retired,opt.retireLabel||'حذف/بایگانی','#f472b6',true)+metric(e.skipped,isRetire?'یافت‌نشد':'ردشده','#94a3b8')+metric(e.failed,'خطا','#f87171')+metric(processed,'پردازش')+metric(remain,'باقی')+'</div>'
      +(reason?'<div class="sendq-reason">⚠ '+esc(reason)+'</div>':'')+(opt.extra||'')
      +'<div class="sendq-foot"><span class="sendq-hint">مشاهدهٔ گزارش و محصولات ›</span><span class="sendq-actions" onclick="event.stopPropagation()">'+(opt.actions||'')+'</span></div></article>';
}
/* v10.415: compact current-task card in the Send tab, immediately below
   Catalog Cache. It deliberately does not depend on the Task Manager modal or
   on opening the full queue accordion. */
function renderBslActiveSendTask(q){
    const box=$('bslActiveSendTask');if(!box)return;
    const entries=Array.isArray(q&&q.entries)?q.entries:[];
    let row=null;
    if(q&&q.active_send&&q.active_send.queue_id)
        row=entries.find(e=>e&&String(e.id||'')===String(q.active_send.queue_id||''))||q.active_send;
    if(!row){
        const rank={running:0,paused:1,waiting:2,failed:3};
        row=entries.filter(e=>e&&rank[e.status]!==undefined&&((parseInt(e.total)||0)<=0||(parseInt(e.current)||0)<(parseInt(e.total)||0)))
            .sort((a,b)=>rank[a.status]-rank[b.status]||Number(b.resume_requested_at||b.started_at||0)-Number(a.resume_requested_at||a.started_at||0))[0]||null;
    }
    if(!row){box.style.display='none';box.innerHTML='';return;}
    /* Queue rows created before total was known keep total=0; the live phase
       carries the real scope and must drive checkpoint, percentage and ETA. */
    const total=Math.max(0,parseInt(row.total)||0,parseInt(row.phase_total)||0);
    const current=Math.max(0,parseInt(row.current)||0,parseInt(row.phase_current)||0);
    const incomplete=row.status!=='done'&&(total<=0||current<total);
    const live=!!row._worker_live||!!(q&&q.active_send&&String(q.active_send.queue_id||'')===String(row.id||''));
    const canContinue=incomplete&&!live&&['running','paused','waiting','failed'].includes(String(row.status||''));
    const profile=String(row.profile_name||row.profile_key||'پروفایل نامشخص');
    const shop=String(row.shop_name||row.phase_shop_name||'غرفهٔ پیش‌فرض');
    const beat=parseInt(row.last_progress_ts||0),age=beat>0?Math.max(0,Math.floor(Date.now()/1000)-beat):null;
    const pct=total>0?Math.max(0,Math.min(100,Math.round(current*100/total))):0;
    const started=parseInt(row.started_at||0),elapsed=started>0?Math.max(1,Math.floor(Date.now()/1000)-started):0;
    const etaSec=live&&total>current&&current>0&&elapsed>0?Math.round((total-current)/(current/elapsed)):0;
    const etaHuman=etaSec>0?(etaSec>=3600?(Math.floor(etaSec/3600)+' ساعت و '+Math.max(1,Math.round((etaSec%3600)/60))+' دقیقه'):(etaSec>=60?(Math.ceil(etaSec/60)+' دقیقه'):(etaSec+' ثانیه'))):'';
    const etaLine=etaHuman?'⏱ زمان مورد انتظار تا اتمام: حدود '+toFa(etaHuman):'';
    const state=live?'🟢 در حال ارسال واقعی':(canContinue?'⚠ ارسال متوقف/گیرکرده':'⏳ در صف ارسال');
    box.style.display='block';
    box.innerHTML='<div style="padding:10px 12px;background:'+(live?'#052e164d':'#43140755')+';border:1px solid '+(live?'#22c55e88':'#f9731688')+';border-radius:10px">'
      +'<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><b style="color:'+(live?'#86efac':'#fdba74')+';font-size:12px">'+state+'</b><span style="flex:1"></span>'
      +(canContinue?'<button class="btn btn-green" style="font-size:11px;padding:5px 12px" onclick="resumeBslQueue(\''+jsAttr(String(row.id||''))+'\')">▶ ادامه از '+toFa(current+1)+'</button>':'')+'</div>'
      +'<div style="margin-top:6px;color:#e2e8f0;font-size:11px;font-weight:700">👤 پروفایل ارسال: '+esc(profile)+'</div>'
      +'<div style="margin-top:3px;color:#94a3b8;font-size:10px">🏪 '+esc(shop)+' · checkpoint: '+toFa(current)+' از '+toFa(total)
      +(age===null?'':' · آخرین محصول: '+toFa(age)+' ثانیه پیش')+'</div>'
      +(etaLine?'<div style="margin-top:4px;color:#67e8f9;font-size:10px;font-weight:700">'+etaLine+'</div>':'')
      +'<div style="height:5px;background:#0f172a;border-radius:99px;overflow:hidden;margin-top:7px"><i style="display:block;height:100%;width:'+pct+'%;background:'+(live?'#22c55e':'#f97316')+'"></i></div></div>';
}
function renderBslQueue(q){
    const section=$('bslQueueSection');
    const list=$('bslQueueList');
    if(!section||!list)return;
    const entries=q.entries||[];

    renderBslActiveSendTask(q);
    renderSendQueueProfileSummary('bsl',entries,q.active_send||null);

    try{const bd=$('bslQueueCountBadge');if(bd){const n=(entries||[]).length;const act=(entries||[]).filter(e=>e&&(e.status==='running'||e.status==='waiting'||e.status==='paused')).length;const rag=sendQueueRetireAgg(entries);bd.textContent=n?(toFa(n)+' وظیفه'+(act?' · '+toFa(act)+' فعال':'')+(rag.retired?' · 🗂 '+toFa(rag.retired)+' حذف/بایگانی':'')):'';}}catch(_e){}
    if(entries.length===0){list.innerHTML='<span style="color:#64748b">صف خالی — برای افزودن، دکمه «🚀 ارسال باسلام» را کلیک کنید</span>';return;}
    section.style.display='block';
    const statusLabels={waiting:'⏳ در صف',running:'🔄 در حال ارسال',paused:'⏸ متوقف',done:'✅ انجام شد',failed:'❌ خطا'};
    const statusColors={waiting:'#fbbf24',running:'#67e8f9',paused:'#f97316',done:'#4ade80',failed:'#f87171'};
    const statusBg={waiting:'#42200630',running:'#0e749020',paused:'#c2410c20',done:'#14532d20',failed:'#7f1d1d20'};
    let html='';
    /* v10.73 (87): نوارِ خلاصهٔ وضعیت — صف حالا وظایفِ متعدد (هر غرفه
       یک وظیفه) است و باید یک نگاه بگوید چندتایش کجاست. */
    const cnt={waiting:0,running:0,paused:0,done:0,failed:0};
    entries.forEach(e=>{if(cnt[e.status]!==undefined)cnt[e.status]++;});
    html+='<div style="display:flex;gap:8px;flex-wrap:wrap;font-size:10px;margin-bottom:8px;align-items:center">'
      +'<span style="color:#94a3b8;font-weight:700">'+toFa(entries.length)+' وظیفه</span>'
      +(cnt.running?'<span style="color:#67e8f9">🔄 '+toFa(cnt.running)+'</span>':'')
      +(cnt.waiting?'<span style="color:#fbbf24">⏳ '+toFa(cnt.waiting)+'</span>':'')
      +(cnt.paused?'<span style="color:#f97316">⏸ '+toFa(cnt.paused)+'</span>':'')
      +(cnt.done?'<span style="color:#4ade80">✅ '+toFa(cnt.done)+'</span>':'')
      +(cnt.failed?'<span style="color:#f87171">❌ '+toFa(cnt.failed)+'</span>':'')
      +'</div>';
    let __batch='';
    entries.forEach(e=>{
        /* v10.73 (87): سربرگِ دسته — ردیف‌های یک ارسالِ چندغرفه‌ای */
        if(e.batch_id&&e.batch_id!==__batch){
            __batch=e.batch_id;
            const __be=entries.filter(x=>x.batch_id===e.batch_id);
            const __bd=__be.filter(x=>x.status==='done').length;
            html+='<div style="display:flex;align-items:center;gap:6px;margin:6px 0 2px;padding:4px 8px;background:#0b1220;border:1px solid #1e293b;border-radius:6px;font-size:10px;color:#67e8f9;font-weight:700">'
              +'📦 چندغرفه‌ای — '+toFa(__bd)+' از '+toFa(__be.length)+' غرفه'+(e.profile_name?' · '+esc(e.profile_name):'')
              +'<span style="flex:1"></span>'
              +'<span style="color:#475569;font-weight:400">همهٔ وظایفِ همین ارسال</span></div>';
        }else if(!e.batch_id){__batch='';}
        let __acts='',__total=Math.max(0,parseInt(e.total)||0),__current=Math.max(0,parseInt(e.current)||0);
        const __incomplete=e.status!=='done'||(__total>0&&__current<__total);
        if(e.shop_disabled){
            __acts='<span style="font-size:10px;color:#fdba74">⏹ غرفه از انتخاب ارسال خارج شده</span>'
              +'<button class="btn btn-gray" onclick="deleteBslQueue(\''+e.id+'\')">🗑 پاک‌کردن کارت</button>';
        }else if(__incomplete){
            __acts='<button class="btn btn-green" onclick="resumeBslQueue(\''+e.id+'\')">▶ ادامه'+(__current>0?' از '+toFa(__current+1):'')+'</button>'
              +'<button class="btn btn-red" onclick="deleteBslQueue(\''+e.id+'\')">حذف</button>';
        }else __acts='<button class="btn btn-gray" onclick="deleteBslQueue(\''+e.id+'\')">🗑 پاک‌کردن کارت</button>';
        html+=sendQueueVisualCard(e,{accent:'#22d3ee',icon:'🛍️',destination:'باسلام',retireLabel:'بایگانی‌شده',detailFn:'showBslQueueDetail',actions:__acts,extra:(e.shop_vendor_id?'':bslShopStatsHtml(e.shop_stats))});
        return;
        let progText='';
        let progPercent=0;
