      +'<label style="display:flex;align-items:center;gap:6px;cursor:pointer;margin-bottom:6px"><input type="checkbox" id="'+pfx+'SkipMulti"> <span>محصولی که در <b style="color:#fbbf24">چند غرفه</b> هست نادیده گرفته شود <span style="color:#64748b">(دست‌نخورده می‌ماند؛ تکراریِ داخلِ هر غرفه حذف می‌شود)</span></span></label>'
      +'<label style="display:flex;align-items:center;gap:6px;cursor:pointer;margin-bottom:6px"><input type="checkbox" id="'+pfx+'AllVend"> <span>همهٔ غرفه‌ها اسکن شوند <span style="color:#64748b">(خاموش = فقط غرفهٔ پیش‌فرض)</span></span></label>'
      +'<label style="display:flex;align-items:center;gap:6px;cursor:pointer;margin-bottom:8px"><input type="checkbox" id="'+pfx+'UseCache"> <span>از <b style="color:#38bdf8">فهرستِ آماده</b> استفاده کن <span style="color:#64748b">(بسیار سریع‌تر؛ خاموش = برداشتِ زنده از باسلام)</span></span></label>'
      :'')
    +'<div style="border-top:1px solid #1e293b;padding-top:8px;margin-bottom:6px;color:#94a3b8">🧩 <b>پسوندهایی که هنگام مقایسه نادیده گرفته شوند</b> — «۱۲» یعنی هر عددِ چندرقمی</div>'
    +'<div style="display:flex;flex-wrap:wrap;gap:10px;margin-bottom:8px">'
    +'<label style="cursor:pointer"><input type="checkbox" id="'+pfx+'SCode"> <code>(کد:۱۲)</code></label>'
    +'<label style="cursor:pointer"><input type="checkbox" id="'+pfx+'SHash"> <code>#۱۲</code></label>'
    +'<label style="cursor:pointer"><input type="checkbox" id="'+pfx+'SParen"> <code>(۱۲)</code></label>'
    +'<label style="cursor:pointer"><input type="checkbox" id="'+pfx+'SDash"> <code>- ۱۲</code></label>'
    +'</div>'
    +'<label style="display:block;margin-bottom:8px">✏️ الگوی دلخواه <span style="color:#64748b">(هر خط یکی؛ <code>x</code> = عدد. مثال: <code>(کد:x)</code> یا <code>#x</code>)</span>'
    +'<textarea id="'+pfx+'SCustom" class="inp" rows="2" style="width:100%;margin-top:3px;font-family:monospace" placeholder="(کد:x)&#10;#x"></textarea></label>'
    +'<div style="display:flex;flex-wrap:wrap;gap:10px;margin-bottom:8px">'
    +'<label style="cursor:pointer"><input type="checkbox" id="'+pfx+'Ci"> بی‌تفاوت به بزرگی حروف</label>'
    +'<label style="cursor:pointer"><input type="checkbox" id="'+pfx+'ND"> ارقام فارسی=لاتین</label>'
    +'<label style="cursor:pointer"><input type="checkbox" id="'+pfx+'NA"> ي/ك عربی=ی/ک</label>'
    +'</div>'
    +'<div style="border-top:1px solid #1e293b;padding-top:8px">'
    +'<div style="color:#94a3b8;margin-bottom:4px">🔬 <b>آزمایشِ الگو</b> — چند عنوانِ نمونه بنویسید تا ببینید چه چیزی هم‌نام شمرده می‌شود</div>'
    +'<textarea id="'+pfx+'Test" class="inp" rows="3" style="width:100%;font-family:monospace" placeholder="گوشی سامسونگ A54 (کد:۱۲۳)&#10;گوشی سامسونگ A54 #45"></textarea>'
    +'<div style="display:flex;gap:6px;margin-top:6px">'
    +'<button class="btn btn-cyan" style="flex:1;font-size:11px;padding:5px" onclick="ddPreview()">🔬 آزمایش</button>'
    +'<button class="btn btn-green" style="flex:1;font-size:11px;padding:5px" onclick="ddSaveCfg(1)">💾 ذخیرهٔ تنظیمات</button>'
    +'</div>'
    +'<div id="'+pfx+'Prev" style="margin-top:6px"></div>'
    +'</div></div>';
}

function ddPfx(){return ddTarget==='bsl'?'bd':'dd';}

function ddFillCfg(c){
    const p=ddPfx(); const g=id=>document.getElementById(p+id);
    if(!g('Keep'))return;
    g('Keep').value=c.keep; g('Tie').value=c.tie;
    g('PrefAct').checked=!!c.prefer_active;
    g('SCode').checked=!!c.strip_code; g('SHash').checked=!!c.strip_hash;
    g('SParen').checked=!!c.strip_paren; g('SDash').checked=!!c.strip_dash;
    g('SCustom').value=c.strip_custom||'';
    g('Ci').checked=!!c.ci; g('ND').checked=!!c.norm_digits; g('NA').checked=!!c.norm_arabic;
    // v10.39 (۵۳): فقط در نسخهٔ باسلام رندر شده‌اند
    if(g('ActOnly'))g('ActOnly').checked=!!c.active_only;
    if(g('SkipMulti'))g('SkipMulti').checked=!!c.skip_multi;
    if(g('AllVend'))g('AllVend').checked=!!c.all_vendors;
    if(g('UseCache'))g('UseCache').checked=!!c.use_cache;
}

function ddReadCfg(){
    const p=ddPfx(); const g=id=>document.getElementById(p+id);
    if(!g('Keep'))return ddCfg||{};
    const b=id=>g(id)?(g(id).checked?'1':'0'):undefined;
    const extra={};
    // v10.39 (۵۳): اگر رندر نشده‌اند اصلاً فرستاده نمی‌شوند تا مقدارِ
    // ذخیره‌شده با یک ذخیرهٔ ووکامرس پاک نشود
    ['ActOnly:active_only','SkipMulti:skip_multi','AllVend:all_vendors','UseCache:use_cache']
      .forEach(function(pair){const s=pair.split(':');const v=b(s[0]);if(v!==undefined)extra[s[1]]=v;});
    return Object.assign({keep:g('Keep').value,tie:g('Tie').value,
        prefer_active:g('PrefAct').checked?'1':'0',
        strip_code:g('SCode').checked?'1':'0',strip_hash:g('SHash').checked?'1':'0',
        strip_paren:g('SParen').checked?'1':'0',strip_dash:g('SDash').checked?'1':'0',
        strip_custom:g('SCustom').value,
        ci:g('Ci').checked?'1':'0',norm_digits:g('ND').checked?'1':'0',
        norm_arabic:g('NA').checked?'1':'0'},extra);
}

function ddLoadCfg(target,hostId){
    ddTarget=target;
    const host=document.getElementById(hostId);
    if(host&&!document.getElementById(ddPfx()+'Keep'))host.innerHTML=ddCfgHtml(ddPfx());
    return fetch('?dedup_cfg=1').then(r=>r.json()).then(d=>{
        if(d&&d.ok){ddCfg=d.cfg;ddFillCfg(d.cfg);}
        return d;
    }).catch(()=>null);
}

function ddSaveCfg(toast){
    const fd=new FormData();fd.append('action','dedup_save_cfg');
    const c=ddReadCfg();for(const k in c)fd.append(k,c[k]);
    return fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(d&&d.ok){ddCfg=d.cfg;if(toast)showToast('✅ تنظیماتِ حذفِ تکراری ذخیره شد');}
        else if(toast)showToast('❌ ذخیره نشد',1);
        return d;
    }).catch(()=>{if(toast)showToast('❌ خطای شبکه هنگام ذخیره',1);});
}

function ddPreview(){
    const p=ddPfx();const out=document.getElementById(p+'Prev');const ta=document.getElementById(p+'Test');
    if(!out||!ta)return;
    if(!ta.value.trim()){out.innerHTML='<div style="color:#94a3b8;font-size:11px">چند عنوانِ نمونه بنویسید.</div>';return;}
    out.innerHTML='<div style="color:#67e8f9;font-size:11px">⏳ ...</div>';
    const fd=new FormData();fd.append('action','dedup_preview');fd.append('titles',ta.value);
    const c=ddReadCfg();for(const k in c)fd.append(k,c[k]);
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){out.innerHTML='<div class="no2">✗ آزمایش ناموفق</div>';return;}
        let h='<div style="font-size:11px;border:1px solid #334155;border-radius:6px;overflow:hidden">';
        h+='<table style="width:100%;border-collapse:collapse"><tr style="background:#1e293b;color:#94a3b8"><th style="padding:4px;text-align:right">عنوان</th><th style="padding:4px;text-align:right">پس از نرمال‌سازی</th></tr>';
        d.rows.forEach(r=>{
            h+='<tr style="border-top:1px solid #1e293b"><td style="padding:4px;color:#cbd5e1">'+esc(r.title)+'</td><td style="padding:4px;color:'+(r.changed?'#4ade80':'#94a3b8')+'">'+esc(r.norm)+(r.changed?' ✂️':'')+'</td></tr>';
        });
        h+='</table></div>';
        if(d.dups&&d.dups.length){
            h+='<div style="margin-top:5px;color:#fb923c;font-size:11px">🔴 '+toFa(d.dups.length)+' گروهِ هم‌نام: '+d.dups.map(x=>'«'+esc(x.norm)+'» ×'+toFa(x.idx.length)).join(' · ')+'</div>';
        }else{
            h+='<div style="margin-top:5px;color:#4ade80;font-size:11px">✓ هیچ دو عنوانی هم‌نام نشد ('+toFa(d.patterns)+' الگوی فعال)</div>';
        }
        out.innerHTML=h;
    }).catch(()=>{out.innerHTML='<div class="no2">✗ خطای شبکه</div>';});
}

// شروعِ کارِ پس‌زمینه: تنظیمات ذخیره می‌شود، سرور بی‌درنگ پاسخ می‌دهد و
// از آن به بعد فقط وضعیت را می‌خوانیم ⇒ دیگر خطای شبکه/تایم‌اوت نداریم.
function ddStart(target,mode){
    if(ddIsRun){showToast('⏳ یک عملیات در حال اجراست',1);return;}
    ddTarget=target;
    if(mode==='delete'&&!confirm('محصولاتِ تکراری واقعاً حذف می‌شوند'+(target==='bsl'?' (در باسلام: بایگانی)':'')+'.\nمعیار: '+(document.getElementById(ddPfx()+'Keep')||{value:''}).value+'\nادامه می‌دهید؟'))return;
    ddSaveCfg(0).then(()=>{
        ddIsRun=true;ddSeen=0;ddLastResult=null;ddDelWatch=false;   // v10.44 (۵۸)
        fxTopBar(true);                       // v10.07: نوارِ پیشرفتِ بالای صفحه
        const E=ddEl;
        if(E('Btn'))E('Btn').classList.add('hidden');
        if(E('DelBtn'))E('DelBtn').classList.add('hidden');
        if(E('Stop'))E('Stop').classList.remove('hidden');
        if(E('P'))E('P').classList.remove('hidden');
        if(E('PB'))E('PB').style.width='5%';
        if(E('Running')){E('Running').classList.remove('hidden');E('Running').innerHTML='';}
        if(E('SM'))E('SM').classList.add('hidden');
        if(E('Report'))E('Report').innerHTML='';
        if(E('SS'))E('SS').textContent='⏳ در حال شروع...';
        fetch('?dedup_start=1&target='+target+'&mode='+mode).then(r=>r.json()).then(d=>{
            if(!d||!d.ok){
                if(E('SS'))E('SS').textContent='✗ '+((d&&d.error)||'شروع نشد');
                ddFinish();return;
            }
            if(E('SS'))E('SS').textContent='🚀 اجرا در پس‌زمینهٔ سرور — می‌توانید صفحه را ببندید';
            ddWatch();
        }).catch(()=>{
            // حتی اگر پاسخِ شروع گم شود، کار روی سرور آغاز شده؛ فقط تماشا کن
            if(E('SS'))E('SS').textContent='… اتصال کند است، وضعیت را دنبال می‌کنیم';
            ddWatch();
        });
    });
}

function ddWatch(){
    clearInterval(ddTimer);
    ddTimer=setInterval(()=>{
        fetch('?dedup_status=1&since='+ddSeen).then(r=>r.json()).then(st=>{
            if(!st)return;
            ddApplyStatus(st);
            if(st.done){
                clearInterval(ddTimer);ddFinish();
                /* v10.44 (۵۸): پایانِ یک *حذف* گزارشِ اسکنِ قدیمی را بار
                   نمی‌کند — آن فهرست دیگر منسوخ است. به‌جایش یک اسکنِ تازه
                   می‌زنیم تا کاربر وضعیتِ واقعیِ بعد از حذف را ببیند. */
                if(ddDelWatch){
                    ddDelWatch=false;
                    const ok=!!st.del_ok,msg=st.del_msg||'';
                    if(msg)showToast(((st.failed||0)>0?'⚠️ ':(ok?'✅ ':'❌ '))+msg,(ok&&!(st.failed||0))?0:1);
                    setTimeout(()=>{if(!ddIsRun)ddStart(ddTarget,'scan');},600);
                }else{
                    ddFetchResult();
                }
            }
        }).catch(()=>{});
    },1200);
}

function ddApplyStatus(st){
    const E=ddEl;
    if(st.log&&st.log.length&&E('Running')){
        let h='';
        st.log.forEach(l=>{h+='<div style="padding:2px 8px;font-size:10px;color:#94a3b8;border-bottom:1px solid #1e293b">'+esc(l.m)+'</div>';});
        E('Running').innerHTML+=h;scrollElBottom(E('Running'));
    }
    if(typeof st.log_total==='number')ddSeen=st.log_total;
    if(E('Tot'))E('Tot').textContent=toFa(st.total||0);
    if(E('Grp'))E('Grp').textContent=toFa(st.groups||0);
    if(E('Dup'))E('Dup').textContent=toFa(st.dups||0);
    if(E('Del'))E('Del').textContent=toFa(st.deleted||0);
    if(E('SM'))E('SM').classList.remove('hidden');
    if(E('PB')){
        let pct=8;
        if(st.phase==='fetch')pct=Math.min(55,10+(st.page||0)*3);
        else if(st.phase==='group')pct=60;
        else if(st.phase==='delete')pct=60+Math.round(35*((st.processed||0)/Math.max(1,st.dups||1)));
        else if(st.done)pct=100;
        E('PB').style.width=pct+'%';
    }
    /* v10.42 (۵۶): در باسلام «حذف» وجود ندارد — کار بایگانی (۴۱۸۴) است.
       تا اینجا همین نوار وضعیت هم «حذف» می‌گفت و انتظارِ اشتباه می‌ساخت. */
    const VV=(ddTarget==='bsl')?'بایگانی':'حذف';
    if(E('SS')&&!st.done){
        if(st.phase==='fetch')E('SS').textContent='📄 دریافت محصولات... ('+toFa(st.fetched||0)+')';
        else if(st.phase==='group')E('SS').textContent='🧮 گروه‌بندی عنوان‌ها...';
        else if(st.phase==='delete')E('SS').textContent='🗑 '+VV+' '+toFa(st.processed||0)+' از '+toFa(st.dups||0);
    }
    if(st.done&&E('SS')){
        if(st.error)E('SS').textContent='✗ '+st.error;
        else if(st.stopped)E('SS').textContent='⏹ متوقف شد — '+VV+'شده: '+toFa(st.deleted||0);
        else if((st.deleted||0)>0)E('SS').textContent='✓ '+toFa(st.deleted)+' مورد '+VV+' شد'+((st.failed||0)?('، '+toFa(st.failed)+' ناموفق'):'');
        /* شکستِ کامل دیگر پشتِ «گزارش آماده است» پنهان نمی‌شود */
        else if((st.failed||0)>0)E('SS').textContent='✗ هیچ موردی '+VV+' نشد — '+toFa(st.failed)+' ناموفق (گزارش را باز کنید)';
        else E('SS').textContent='✓ گزارش آماده است — '+toFa(st.dups||0)+' نسخهٔ اضافی در '+toFa(st.groups||0)+' گروه';
    }
}

/* v10.23 (۳۶ب): هشدارِ «فهرست ناقص».
   تا اینجا اگر برداشت وسطِ کار می‌شکست، گزارش با همان چند صد محصول ساخته و
   بی‌هیچ نشانه‌ای «کامل» نشان داده می‌شد — و بدتر، حذف روی همان فهرستِ ناقص
   انجام می‌شد. حالا سرور صریح می‌گوید ناقص است و اینجا هم بالای گزارش
   می‌نشیند. */
function ddPartialHtml(d){
    if(!d||!d.partial)return '';
    return '<div class="alert alert-warn" style="font-size:11px;margin-bottom:6px">'
      +'⚠️ <b>فهرست ناقص دریافت شد.</b> '+esc(d.partial_msg||'')
      +' برای گرفتنِ گزارشِ کامل، دوباره «گزارشِ تکراری‌ها» را بزنید.</div>';
}

function ddStop(){
    fetch('?dedup_stop=1').then(()=>{showToast('⏹ درخواستِ توقف ثبت شد');}).catch(()=>{});
}

function ddFinish(){
    ddIsRun=false;clearInterval(ddTimer);
    fxTopBar(false);                          // v10.07
    const E=ddEl;
    if(E('Btn'))E('Btn').classList.remove('hidden');
    if(E('DelBtn'))E('DelBtn').classList.remove('hidden');
    if(E('Stop'))E('Stop').classList.add('hidden');
    if(E('PB'))E('PB').style.width='100%';
}

function ddFetchResult(){
    return fetch('?dedup_result=1').then(r=>r.json()).then(d=>{
        /* v10.43 (۵۷): شکست دیگر بی‌صدا نیست — قبلاً اینجا خاموش return
           می‌شد و ddLastResult خالی می‌ماند و دکمهٔ حذفِ همه مرده می‌شد. */
        if(!d||!d.ok){
            const E=ddEl;const ss=E&&E('SS');
            const m=(d&&d.error)||'گزارشی در دسترس نیست';
            if(ss)ss.textContent='✗ '+m;else showToast('✗ '+m,1);
            return null;
        }
        ddLastResult=d;ddRenderReport(d);return d;
    }).catch(e=>{showToast('✗ خطا در خواندنِ گزارش: '+(e&&e.message||e),1);return null;});
}

function ddStatusBadge(p){
    const M={2976:['فعال','#4ade80'],3790:['غیرفعال','#94a3b8'],3567:['تأییدنشده','#fbbf24'],3568:['در انتظار','#60a5fa'],4184:['بایگانی','#f87171'],
             'publish':['منتشر','#4ade80'],'draft':['پیش‌نویس','#94a3b8'],'pending':['در انتظار','#60a5fa'],'private':['خصوصی','#a78bfa'],'trash':['زباله','#f87171']};
    const k=p.status>0?p.status:(p.wstatus||'');
    const v=M[k]||['—','#64748b'];
    return '<span style="color:'+v[1]+';font-size:10px">'+v[0]+'</span>';
}

/* =====================================================================
 *  v10.26 (۳۹ب): رندرکنندهٔ مشترکِ «گفتگوی زنده»
 *  ---------------------------------------------------------------------
 *  هر سه مصرف‌کننده (ایجنتِ محصولات، ایجنتِ کشفِ سلکتور، مودالِ لاگِ
 *  اتوماسیون) همین توابع را صدا می‌زنند تا شکلِ پیام‌ها یکی باشد.
 * ================================================================== */

/** برچسبِ فارسیِ نقشِ هر پیام. */
function cvoWho(role) {
    if (role === 'user')      return '🧑 دستورِ کاربر';
    if (role === 'assistant') return '🤖 مدل';
    if (role === 'tool')      return '🔧 نتیجهٔ ابزار';
    return '⚙️ پیامِ سیستمی';
}

/** HTMLِ یک پیام. */
function cvoMsgHtml(m) {
    if (!m || !m.role) return '';
    var role = String(m.role);
    var cls  = 'cvo-msg cvo-' + (['system', 'user', 'assistant', 'tool'].indexOf(role) >= 0 ? role : 'system');
    if (role === 'tool' && m.ok === false) cls += ' bad';
    var who = cvoWho(role);
    if (role === 'tool' && m.name) who += ' — ' + esc(String(m.name)) + (m.ok === false ? ' ✗' : ' ✓');
    /* v10.26 (۳۹ب): ساعتِ پیام. در اجرایی که چند دقیقه طول می‌کشد، «آخرین
       پیام ۴ دقیقه پیش بوده» تفاوتِ «کُند است» با «گیر کرده» را می‌سازد. */
    if (m.t) {
        var dt = new Date(m.t * 1000);
        who += '<i class="cvo-t">' + toFa(('0' + dt.getHours()).slice(-2) + ':'
             + ('0' + dt.getMinutes()).slice(-2) + ':' + ('0' + dt.getSeconds()).slice(-2)) + '</i>';
    }
    var h = '<div class="' + cls + '"><span class="cvo-who">' + who + '</span>';
    if (m.text) h += '<span class="cvo-tx">' + esc(String(m.text)) + '</span>';
    (m.calls || []).forEach(function (c) {
        h += '<div class="cvo-call"><b>' + esc(String(c.name || '?')) + '</b>(' + esc(String(c.args || '')) + ')</div>';
    });
    return h + '</div>';
}

/** کلِ باکس را از روی آرایهٔ پیام‌ها می‌سازد.
 *  اگر کاربر خودش تا ته اسکرول کرده باشد، بعد از افزودنِ پیامِ تازه هم
 *  ته می‌ماند؛ وگرنه جای اسکرولش دست نمی‌خورد تا وسطِ خواندن نپرد. */
function cvoRender(boxId, msgs, running) {
    var det = $(boxId);
    if (!det) return;
    msgs = msgs || [];
    det.classList.toggle('hidden', msgs.length === 0);
    var cnt = $(boxId + 'N');
    if (cnt) cnt.textContent = toFa(msgs.length) + ' پیام';
    var lv = $(boxId + 'Live');
    if (lv) lv.classList.toggle('hidden', !running);
    var b = $(boxId + 'Body');
    if (!b) return;
    if (!msgs.length) { b.innerHTML = '<div class="cvo-empty">هنوز پیامی رد و بدل نشده است.</div>'; return; }
    var atEnd = (b.scrollHeight - b.scrollTop - b.clientHeight) < 40;
    var h = '';
    msgs.forEach(function (m) { h += cvoMsgHtml(m); });
    b.innerHTML = h;
    if (atEnd) b.scrollTop = b.scrollHeight;
}

/* ===== v10.03 — ایجنتِ مدیریت محصولات (tool calling) ===== */
var agTimer = null, agSince = 0, agBusy = false;
var agConvo = [], agCSince = 0;   // v10.26 (۳۹ب): جریانِ گفتگوی ایجنت

function agSetBusy(b) {
    agBusy = b;
    var r = $('agRunBtn'), s = $('agStopBtn');
    if (r) { r.disabled = b; r.style.opacity = b ? '0.5' : '1'; }
    if (s) s.classList.toggle('hidden', !b);
}

function agLog(msg) {
    var box = $('agLog');
    if (!box) return;
    box.classList.remove('hidden');
    var d = document.createElement('div');
    d.textContent = msg;
    if (msg.indexOf('❌') === 0) d.style.color = '#f87171';
    else if (msg.indexOf('✏️') === 0) d.style.color = '#facc15';
    else if (msg.indexOf('🔎') === 0) d.style.color = '#22d3ee';
    else if (msg.indexOf('📋') === 0) d.style.color = '#a78bfa';
    else if (msg.indexOf('🤔') === 0) d.style.color = '#64748b';
    else if (msg.indexOf('   ↳') === 0) d.style.color = '#94a3b8';
    else d.style.color = '#e2e8f0';
    box.appendChild(d);
    box.scrollTop = box.scrollHeight;
}

/* ══ v10.10 (۲۳): انتخابِ مدل برای اجرای دستیِ ایجنت ══
   تا ۱۰٫۰۹ فقط کارهای زمان‌بندی‌شده مدلِ اختصاصی داشتند و اجرای دستی همیشه
   با مدلِ پیش‌فرضِ اتصالات می‌رفت. حالا همان کاتالوگِ مدل‌های ابزاردار
   (?auto_catalog=1) اینجا هم نشان داده می‌شود و انتخاب تا agentRun می‌رود. */
var AG_MODEL_LS = 'ag_model_pick';

function agLoadCatalog(force) {
    /* v10.11 (۲۴): از بارگذارِ مشترک استفاده می‌کند تا خطاها دیده شوند.
       ایجنت ابزار صدا می‌زند ⇒ فقط مدل‌های ابزاردار را نشان می‌دهیم. */
    aiMdlRegister({err:'agModelErr', fill:agFillModelSelect});
    aiMdlLoad(!!force);
}

/** تغییرِ ارائه‌دهنده ⇒ فهرستِ مدل‌ها فیلتر می‌شود */
function agProvChange() { agFillModelSelect(); }

/** پر کردنِ منویِ مدلِ ایجنت — با فیلترِ ارائه‌دهنده و جست‌وجو */
function agFillModelSelect() {
    var sel = $('agModelSel');
    if (!sel) return;
    /* انتخابِ دفعهٔ قبلِ کاربر پیش از ساختِ منو برگردانده می‌شود */
    if (!sel.value) { try { sel.value = localStorage.getItem(AG_MODEL_LS) || ''; } catch (e) { } }
    aiMdlFillProv('agProvSel', 'tools');
    aiMdlFillModels({model:'agModelSel', prov:'agProvSel', search:'agModelSearch',
                     cap:'tools', blank:'🔗 مدلِ پیش‌فرضِ اتصالات', after:agModelHint});
    sel.onchange = agModelHint;
}

/** توضیحِ زیرِ منو + ذخیرهٔ انتخاب برای دفعهٔ بعد */
function agModelHint() {
    var sel = $('agModelSel'), hint = $('agModelHint');
    if (!sel || !hint) return;
    try { localStorage.setItem(AG_MODEL_LS, sel.value || ''); } catch (e) { }
    hint.innerHTML = aiMdlHintHtml(sel.value,
        'مدلِ پیش‌فرضِ اتصالات استفاده می‌شود — همان چیزی که بالا زیرِ «مدل فعال» می‌بینید.');
    if (!sel.value) return;
    var m = { id: sel.value };
    /* آیا این مدل واقعاً به یکی از اتصال‌های ثبت‌شده می‌خورد؟ */
    fetch('?agent_model_check&model=' + encodeURIComponent(m.id))
        .then(function (r) { return r.json(); }).then(function (d) {
            if (!d || !d.ok) return;
            if ($('agModelSel') && $('agModelSel').value !== m.id) return;
            hint.innerHTML += d.found
                ? '<br><span style="color:#4ade80">✅ به اتصالِ «' + esc(d.provider) + '» وصل می‌شود</span>'
                : '<br><span style="color:#f87171">⚠️ هیچ اتصالِ فعالی برای این مدل نیست — اجرا با مدلِ پیش‌فرض می‌رود</span>';
        }).catch(function () { });
}

/* ═══════════════════════════════════════════════════════════════════
 *  v10.11 (۲۴): تبِ «💬 چت با مدل‌ها»
 *
 *  گفت‌وگوی مستقیم با هر مدلِ ثبت‌شده، جدا از ایجنت و اتوماسیون.
 *  انتخابِ مدل سه فیلترِ خواسته‌شده دارد: فقط چت / ابزاردار / استدلالی.
 *  تاریخچه در حافظهٔ صفحه می‌ماند و با هر پیام به سرور می‌رود تا مدل
 *  بافتِ گفت‌وگو را داشته باشد؛ سقفِ ۱۲ نوبتِ آخر سمتِ PHP اعمال می‌شود.
 * ═══════════════════════════════════════════════════════════════════ */

var CH_MODEL_LS = 'ai_chat_model';
var chCap  = 'chat';   // فیلترِ فعال: chat | tools | reasoning
var chHist = [];       // [{role:'user'|'assistant', content:'…'}]
var chBusy = false;

function chLoadCatalog(force) {
    aiMdlRegister({err:'chModelErr', fill:chFillModelSelect});
    chRenderFilter();
    aiMdlLoad(!!force);
}

/** سه دکمهٔ فیلترِ نوعِ مدل، با شمارشِ زنده */
function chRenderFilter() {
    var f = $('chFilter');
    if (!f) return;
    var defs = [
        ['chat',      '💬 فقط چت',        'مدل‌هایی که پاسخِ متنی می‌دهند'],
        ['tools',     '🤖 دارای ابزار',   'مدل‌هایی که فراخوانیِ ابزار (function calling) دارند'],
        ['reasoning', '🧠 استدلالی',      'مدل‌هایی که پیش از پاسخ زنجیرهٔ استدلال می‌سازند']
    ];
    var c = (aiMdlData && aiMdlData.counts) || {};
    var h = '';
    defs.forEach(function (d) {
        var n = c[d[0]];
        h += '<span class="ai-chip' + (chCap === d[0] ? ' on' : '') + '" title="' + esc(d[2]) + '"'
          +  ' onclick="chSetCap(\'' + d[0] + '\')">' + d[1]
          +  (n === undefined ? '' : ' (' + toFa(n) + ')') + '</span>';
    });
    f.innerHTML = h;
}

/** تغییرِ فیلترِ نوعِ مدل */
function chSetCap(cap) {
    chCap = cap;
    chRenderFilter();
    chFillModelSelect();
}

function chProvChange() { chFillModelSelect(); }

function chFillModelSelect() {
    var sel = $('chModelSel');
    if (!sel) return;
    if (!sel.value) { try { sel.value = localStorage.getItem(CH_MODEL_LS) || ''; } catch (e) { } }
    chRenderFilter();
    aiMdlFillProv('chProvSel', chCap);
    aiMdlFillModels({model:'chModelSel', prov:'chProvSel', search:'chModelSearch',
                     cap:chCap, blank:'🔗 مدلِ پیش‌فرضِ اتصالات', after:chModelHint});
}

function chModelHint() {
    var sel = $('chModelSel'), hint = $('chModelHintBox');
    if (!sel || !hint) return;
    try { localStorage.setItem(CH_MODEL_LS, sel.value || ''); } catch (e) { }
    hint.innerHTML = aiMdlHintHtml(sel.value,
        'مدلِ پیش‌فرضِ اتصالات استفاده می‌شود. برای انتخابِ مدلِ مشخص، اول نوع و ارائه‌دهنده را تعیین کنید.');
}

/** یک حباب پیام به کادرِ گفت‌وگو اضافه می‌کند */
function chBubble(kind, text, meta) {
    var box = $('chBox');
    if (!box) return null;
    var em = $('chEmpty');
    if (em) em.remove();
    var d = document.createElement('div');
    d.className = 'ai-msg ' + kind;
    d.innerHTML = esc(text) + (meta ? '<span class="mt">' + esc(meta) + '</span>' : '');
    box.appendChild(d);
    box.scrollTop = box.scrollHeight;
    return d;
}

/** Ctrl+Enter ⇒ ارسال (Enterِ تنها برای خطِ جدید آزاد می‌ماند) */
function chKey(e) {
    if (e && e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); chSend(); }
}

function chSend() {
    if (chBusy) { showToast('صبر کنید، پاسخِ قبلی هنوز نیامده', true); return; }
    var inp = $('chInput');
    if (!inp) return;
    var msg = (inp.value || '').trim();
    if (!msg) { showToast('پیام خالی است', true); return; }

    var sel   = $('chModelSel');
    var model = sel ? sel.value : '';
    var m     = (aiMdlData && model)
              ? aiMdlData.models.filter(function (x) { return x.id === model; })[0] : null;
    if (m && !m.chat) {
        showToast('این مدل گفت‌وگویی نیست: ' + (m.why || 'پاسخِ متنی نمی‌دهد'), true);
        return;
    }

    chBubble('me', msg);
    inp.value = '';
    chBusy = true;
    var btn = $('chSendBtn');
    if (btn) { btn.disabled = true; btn.textContent = '⏳ …'; }
    var st = $('chStatus');
    if (st) st.textContent = 'در حالِ گرفتنِ پاسخ' + (m ? ' از ' + m.name : '') + '…';
    var wait = chBubble('bot', '⏳ در حالِ نوشتن…');

    var fd = new FormData();
    fd.append('action', 'ai_chat_send');
    fd.append('message', msg);
    fd.append('model', model);
    fd.append('system', ($('chSystem') || {value:''}).value || '');
    fd.append('history', JSON.stringify(chHist));

    var code = 0;
    fetch(location.pathname, {method:'POST', body:fd})
      .then(function (r) { code = r.status; return r.text(); })
      .then(function (txt) {
        var d;
        try { d = JSON.parse(txt); }
        catch (e) {
            throw new Error('پاسخ JSON نبود (HTTP ' + toFa(code) + '): '
                + txt.replace(/\s+/g, ' ').slice(0, 90));
        }
        if (!d.ok) throw new Error(d.error || ('HTTP ' + toFa(code)));
        if (wait) wait.remove();
        chBubble('bot', d.reply,
            (d.model || 'پیش‌فرض') + ' · ' + toFa(Math.round(d.took / 100) / 10) + ' ثانیه');
        /* تاریخچه فقط پس از پاسخِ موفق رشد می‌کند تا پیامِ شکست‌خورده
           در نوبتِ بعد دوباره به مدل فرستاده نشود. */
        chHist.push({role:'user', content:msg});
        chHist.push({role:'assistant', content:d.reply});
        if (st) st.textContent = '✅ پاسخ آمد — ' + toFa(chHist.length / 2) + ' نوبت گفت‌وگو';
      })
      .catch(function (e) {
        if (wait) wait.remove();
        chBubble('err', '⚠️ ' + ((e && e.message) || 'ارتباط با سرور برقرار نشد'));
        if (st) st.textContent = '❌ ارسال ناموفق بود';
      })
      .then(function () {
        chBusy = false;
        var b = $('chSendBtn');
        if (b) { b.disabled = false; b.textContent = '📨 ارسال'; }
      });
}

function chClear() {
    if (chHist.length && !confirm('کلِ گفت‌وگو پاک شود؟')) return;
    chHist = [];
    var box = $('chBox');
    if (box) box.innerHTML = '<div class="ai-chat-empty" id="chEmpty">هنوز پیامی رد و بدل نشده. پایین بنویسید و بفرستید.</div>';
    var st = $('chStatus');
    if (st) st.textContent = '—';
    showToast('گفت‌وگو پاک شد');
}

/** بازگشت به مدلِ پیش‌فرضِ اتصالات */
function agModelReset() {
    var sel = $('agModelSel');
    if (!sel) return;
    sel.value = '';
    agModelHint();
    showToast('به مدلِ پیش‌فرضِ اتصالات برگشت');
}

function agLoadTools() {
    var el = $('agModel');
    if (el) el.textContent = 'در حال بررسی…';
    fetch('?agent_tools').then(function (r) { return r.json(); }).then(function (j) {
        if (!el) return;
        if (j && j.ok && j.model) {
            el.textContent = j.model + (j.provider ? ' (' + j.provider + ')' : '')
                + ' — ' + toFa(j.tools.length) + ' ابزار';
            el.style.color = '#4ade80';
        } else {
            el.textContent = 'هیچ مدلی فعال نیست — از تب «هوش مصنوعی» یکی را انتخاب کنید';
            el.style.color = '#f87171';
        }
    }).catch(function () { if (el) { el.textContent = 'خطای ارتباط'; el.style.color = '#f87171'; } });
}

function agShowTools() {
    fetch('?agent_tools').then(function (r) { return r.json(); }).then(function (j) {
        if (!j || !j.ok) { showToast('خطا در خواندن ابزارها', true); return; }
        var h = '<div style="background:#0b1120;border:1px solid #334155;border-radius:8px;padding:10px;font-size:11px">'
              + '<div style="color:#c084fc;font-weight:700;margin-bottom:7px">🧰 ابزارهایی که در اختیار مدل است</div>';
        j.tools.forEach(function (t) {
            h += '<div style="margin-bottom:7px;padding-bottom:7px;border-bottom:1px solid #1e293b">'
               + '<code style="color:#4ade80;direction:ltr;display:inline-block">' + esc(t.name) + '</code>'
               + '<div style="color:#94a3b8;margin-top:2px">' + esc(t.desc) + '</div>'
               + '<div style="color:#64748b;font-size:10px;direction:ltr;text-align:right">'
               + esc(t.params.join(' · ')) + '</div></div>';
        });
        h += '</div>';
        var box = $('agReport');
        if (box) { box.innerHTML = h; box.classList.remove('hidden'); }
    });
}

function agStart() {
    if (agBusy) return;
    var task = ($('agTask') || {}).value || '';
    task = task.trim();
    if (!task) { showToast('لطفاً کارِ موردنظر را بنویسید', true); return; }
    var mode = ($('agMode') || {}).value || 'dry';
    if (mode === 'live' && !confirm('حالت «اجرای واقعی» انتخاب شده است.\n\nقیمت و موجودی محصولات در باسلام و ووکامرس واقعاً تغییر می‌کند و برگشت‌پذیر نیست.\n\nادامه می‌دهید؟')) return;

    agSince = 0;
    agConvo = []; agCSince = 0;          // v10.26 (۳۹ب)
    cvoRender('agConvo', [], true);
    var box = $('agLog'); if (box) { box.innerHTML = ''; box.classList.remove('hidden'); }
    var rp = $('agReport'); if (rp) { rp.innerHTML = ''; rp.classList.add('hidden'); }
    var sm = $('agSum'); if (sm) sm.classList.remove('hidden');
    ['agSteps', 'agCalls', 'agChanges'].forEach(function (i) { if ($(i)) $(i).textContent = '۰'; });
    agSetBusy(true);
    if ($('agStatus')) $('agStatus').textContent = 'در حال شروع…';

    var fd = new FormData();
    fd.append('task', task);
    fd.append('model', ($('agModelSel') || { value: '' }).value || '');
    fetch('?agent_start&mode=' + encodeURIComponent(mode), { method: 'POST', body: fd })
        .then(function (r) { return r.json(); })
        .then(function (j) {
            if (!j || !j.ok) {
                agSetBusy(false);
                if ($('agStatus')) $('agStatus').textContent = (j && j.error) || 'شروع نشد';
                showToast((j && j.error) || 'ایجنت شروع نشد', true);
                return;
            }
            agWatch();
        })
        .catch(function () { agSetBusy(false); showToast('خطای ارتباط با سرور', true); });
}

function agWatch() {
    if (agTimer) clearInterval(agTimer);
    agTimer = setInterval(agPoll, 1200);
    agPoll();
}

function agPoll() {
    fetch('?agent_status&since=' + agSince + '&csince=' + agCSince).then(function (r) { return r.json(); }).then(function (p) {
        if (!p) return;
        (p.log || []).forEach(function (l) { agLog(l.m || ''); });
        agSince = p.log_total || agSince;
        /* v10.26 (۳۹ب): پیام‌های تازهٔ گفتگو را به همان آرایه بچسبان و
           باکس را دوباره بکش. csince تضمین می‌کند تکراری نگیریم. */
        if (p.convo && p.convo.length) {
            p.convo.forEach(function (m) { agConvo.push(m); });
            agCSince = p.convo_total || agConvo.length;
        } else if (typeof p.convo_total === 'number') {
            agCSince = p.convo_total;
        }
        cvoRender('agConvo', agConvo, !p.done);
        if ($('agSteps')) $('agSteps').textContent = toFa(p.step || 0);
        if ($('agCalls')) $('agCalls').textContent = toFa(p.calls || 0);
        if ($('agChanges')) $('agChanges').textContent = toFa(p.changes || 0);
        if ($('agStatus')) {
            $('agStatus').textContent = p.done
                ? (p.error ? ('خطا: ' + p.error) : 'پایان یافت')
                : ('در حال اجرا — گامِ ' + toFa(p.step || 0));
        }
        if (p.done) {
            if (agTimer) { clearInterval(agTimer); agTimer = null; }
            agSetBusy(false);
            agFinish();
        }
    }).catch(function () { });
}

function agStop() {
    fetch('?agent_stop').then(function () { showToast('درخواست توقف ارسال شد'); });
}

/** v10.26 (۳۹ب): بازیابیِ اجرای در جریان بعد از رفرشِ صفحه.
 *  بدونِ این، اگر کاربر وسطِ یک اجرای چنددقیقه‌ای F5 بزند، پنل خالی
 *  می‌ماند و فکر می‌کند ایجنت مرده — دقیقاً همان بی‌خبری‌ای که بندِ ۳۹ب
 *  برای رفعش نوشته شد. */
function agResume() {
    fetch('?agent_status&since=0&csince=0').then(function (r) { return r.json(); }).then(function (p) {
        if (!p || !p.started_at) return;
        agSince  = p.log_total  || 0;
        agConvo  = p.convo || [];
        agCSince = p.convo_total || agConvo.length;
        (p.log || []).forEach(function (l) { agLog(l.m || ''); });
        cvoRender('agConvo', agConvo, !p.done);
        if ($('agSteps'))   $('agSteps').textContent   = toFa(p.step || 0);
        if ($('agCalls'))   $('agCalls').textContent   = toFa(p.calls || 0);
        if ($('agChanges')) $('agChanges').textContent = toFa(p.changes || 0);
        var sm = $('agSum'); if (sm && p.step) sm.classList.remove('hidden');
        if (!p.done && p.running) {
            agSetBusy(true);
            if ($('agStatus')) $('agStatus').textContent = 'در حال اجرا — گامِ ' + toFa(p.step || 0);
            agWatch();
        } else if ($('agStatus') && p.step) {
            $('agStatus').textContent = p.error ? ('خطا: ' + p.error) : 'پایان یافت';
        }
    }).catch(function () { });
}

function agFinish() {
    fetch('?agent_result').then(function (r) { return r.json(); }).then(function (rep) {
        if (!rep || !rep.ok) return;
        agRenderReport(rep);
    }).catch(function () { });
}

function agModeLabelJs(m) {
    if (m === 'live') return '🔥 اجرای واقعی';
    if (m === 'sim') return '🧪 شبیه‌سازی';
    return '🔍 آزمایشی (بدون نوشتن)';
}

function agRenderReport(rep) {
    var box = $('agReport');
    if (!box) return;
    var ch = rep.changes || [];
    var h = '<div style="background:#0b1120;border:1px solid #334155;border-radius:8px;padding:11px;font-size:12px">'
          + '<div style="color:#c084fc;font-weight:700;margin-bottom:6px">📄 گزارشِ ایجنت — ' + esc(agModeLabelJs(rep.mode)) + '</div>'
          + '<div style="color:#e2e8f0;line-height:1.9;margin-bottom:8px">' + esc(rep.summary || '') + '</div>'
          + '<div style="color:#64748b;font-size:11px;margin-bottom:8px">'
          + 'زمان: ' + toFa(rep.took || 0) + ' ثانیه · فراخوانیِ ابزار: ' + toFa(rep.calls || 0)
          + ' · واقعاً اعمال‌شده: ' + toFa(rep.applied || 0)
          + ' · شبیه‌سازی‌شده: ' + toFa(rep.simulated || 0)
          + (rep.native_tools ? ' · ابزارِ بومی' : ' · حالتِ متنی')
          + (rep.stopped_by ? ' · متوقف‌شده توسط ' + esc(rep.stopped_by) : '')
          + '</div>';
    if (ch.length) {
        h += '<table style="width:100%;border-collapse:collapse;font-size:11px">'
           + '<tr style="color:#94a3b8;text-align:right">'
           + '<th style="padding:4px;border-bottom:1px solid #334155">مقصد</th>'
           + '<th style="padding:4px;border-bottom:1px solid #334155">شناسه</th>'
           + '<th style="padding:4px;border-bottom:1px solid #334155">قیمت</th>'
           + '<th style="padding:4px;border-bottom:1px solid #334155">موجودی</th>'
           + '<th style="padding:4px;border-bottom:1px solid #334155">وضعیت</th></tr>';
        ch.forEach(function (c) {
            h += '<tr>'
               + '<td style="padding:4px;border-bottom:1px solid #1e293b">' + (c.target === 'woo' ? 'ووکامرس' : 'باسلام') + '</td>'
               + '<td style="padding:4px;border-bottom:1px solid #1e293b;direction:ltr;text-align:right">' + toFa(c.id) + '</td>'
               + '<td style="padding:4px;border-bottom:1px solid #1e293b">' + (c.price === null || c.price === undefined ? '—' : toFa(c.price)) + '</td>'
               + '<td style="padding:4px;border-bottom:1px solid #1e293b">' + (c.stock === null || c.stock === undefined ? '—' : toFa(c.stock)) + '</td>'
               + '<td style="padding:4px;border-bottom:1px solid #1e293b;color:' + (c.applied ? '#4ade80' : (c.error ? '#f87171' : '#facc15')) + '">'
               + (c.applied ? 'اعمال شد' : (c.error ? esc(c.error) : 'شبیه‌سازی')) + '</td></tr>';
        });
        h += '</table>';
    } else {
        h += '<div style="color:#64748b">هیچ تغییری پیشنهاد نشد.</div>';
    }
    h += '</div>';
    box.innerHTML = h;
    box.classList.remove('hidden');
}

function ddRenderReport(d){
    const E=ddEl;const host=E('Report');if(!host)return;
    /* v10.43 (۵۷): هرچه رندر می‌شود همان‌جا در state هم می‌نشیند.
       پیش‌تر ddLastResult فقط داخلِ ddFetchResult پر می‌شد و اگر گزارش از
       مسیرِ دیگری رندر می‌شد (بازکردنِ دوبارهٔ پنل، از دست رفتنِ polling،
       ddStart که آن را null می‌کرد و هرگز به done نمی‌رسید) کاربر فهرست را
       می‌دید ولی دکمهٔ «حذفِ همه» روی یک stateِ خالی می‌نشست و بی‌صدا
       return می‌کرد — «هیچ اتفاقی نمی‌افتد». */
    ddLastResult=d;
    const list=d.duplicates_list||[];
    if(!list.length){host.innerHTML=ddPartialHtml(d)+'<div style="color:#4ade80;font-size:12px;padding:8px">✓ هیچ محصولِ تکراری‌ای پیدا نشد.</div>';return;}
    let h=ddPartialHtml(d)
      +'<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:6px">'
      +'<div style="color:#fb923c;font-size:12px;font-weight:700">🔴 '+toFa(d.groups)+' گروه · '+toFa(d.duplicates)+' نسخهٔ اضافی</div>'
      +'<button class="btn btn-red" style="font-size:11px;padding:4px 10px" onclick="ddDeleteAllFromReport()">🗑 حذفِ همهٔ موارد نشان‌داده‌شده</button></div>';
    if(d.truncated)h+='<div class="alert alert-warn" style="font-size:11px;margin-bottom:6px">⚠️ فقط بخشی از گروه‌ها نمایش داده می‌شود.</div>';
    h+='<div style="max-height:340px;overflow-y:auto;border:1px solid #334155;border-radius:8px">';
    list.forEach((g,gi)=>{
        h+='<div style="border-bottom:1px solid #1e293b;padding:6px 8px">';
        h+='<div style="color:#e2e8f0;font-size:11px;font-weight:700;margin-bottom:3px">'+esc(g.normalized)+' <span style="color:#f97316">×'+toFa(g.count)+'</span>'+(g.vendor_name?' <span style="color:#38bdf8;font-weight:400">🏪 '+esc(g.vendor_name)+'</span>':'')+'</div>';
        h+='<div style="font-size:10px;color:#4ade80;padding:2px 6px">✅ می‌ماند: #'+toFa(g.keep.id)+' — '+esc(g.keep.name)+' · '+toFa(g.keep.price)+' · '+ddStatusBadge(g.keep)+'</div>';
        (g.drop||[]).forEach(p=>{
            h+='<div style="font-size:10px;color:#fca5a5;padding:2px 6px;display:flex;justify-content:space-between;align-items:center">'
              +'<span>🗑 #'+toFa(p.id)+' — '+esc(p.name)+' · '+toFa(p.price)+' · '+ddStatusBadge(p)+'</span>'
              +'<button class="btn btn-red" style="font-size:9px;padding:1px 6px" onclick="ddDeleteIds(['+p.id+'])">حذف</button></div>';
        });
        h+='</div>';
    });
    h+='</div>';
    host.innerHTML=h;
}

function ddDeleteAllFromReport(){
    /* v10.43 (۵۷): این تابع قبلاً با `if(!ddLastResult)return;` شروع می‌شد و
       این تنها مسیرِ کاملاً بی‌صدای دکمه بود: نه toast، نه لاگ، نه هیچ
       نشانه‌ای. حالا اگر state خالی بود، به‌جای مردن، گزارش را از سرور
       (?dedup_result=1) دوباره می‌گیریم و بعد ادامه می‌دهیم؛ اگر آن هم
       نبود، پیامِ روشن می‌دهیم. */
    if(ddLastResult){ddDelAllWith(ddLastResult);return;}
    showToast('⏳ گزارش را از سرور می‌گیرم…');
    fetch('?dedup_result=1').then(r=>r.json()).then(d=>{
        if(!d||!d.ok||!(d.duplicates_list||[]).length){
            showToast('❌ گزارشی در دسترس نیست — یک‌بار «گزارشِ تکراری‌ها» را بگیرید',1);return;
        }
        ddLastResult=d;ddRenderReport(d);ddDelAllWith(d);
    }).catch(e=>{showToast('❌ خطا در گرفتنِ گزارش: '+(e&&e.message||e),1);});
}

/* v10.43 (۵۷): بدنهٔ واقعیِ «حذفِ همه» — از state یا از گزارشِ تازه‌گرفته‌شده */
function ddDelAllWith(d){
    const ids=[];
    ((d&&d.duplicates_list)||[]).forEach(g=>((g&&g.drop)||[]).forEach(p=>{
        const id=parseInt(p&&p.id,10);if(id>0&&ids.indexOf(id)<0)ids.push(id);
    }));
    if(!ids.length){showToast('چیزی برای حذف نیست');return;}
    const V=(ddTarget==='bsl'?'بایگانی':'حذف');
    /* v10.44 (۵۸): چون عملیات دیگر مسدودکننده نیست (سرور پس‌زمینه‌ای کار
       می‌کند و پیشرفت زنده می‌آید)، سقف از ۲۰۰ به DEDUP_DEL_MAX رسید؛ باز
       هم اگر بیشتر بود کاربر باید بداند این دور فقط بخشی را می‌برد. */
    const CAP=DD_DEL_MAX,go=ids.slice(0,CAP),rest=ids.length-go.length;
    if(!confirm(toFa(go.length)+' محصول '+V+' می‌شود'
        +(rest>0?(' (از '+toFa(ids.length)+' مورد؛ '+toFa(rest)+' موردِ باقی‌مانده را با زدنِ دوبارهٔ همین دکمه ادامه دهید)'):'')
        +'. مطمئنید؟'))return;
    ddDeleteIds(go);
}

/**
 * v10.42 (۵۶): دو ایرادِ این تابع رفع شد.
 *  ۱) همیشه «حذف» می‌گفت، حتی برای باسلام که در آن حذف وجود ندارد و
 *     کار واقعاً «بایگانی» (وضعیت ۴۱۸۴) است.
 *  ۲) اگر سرور با failed>0 برمی‌گشت ولی ok=true بود، فقط پیامِ موفقیت
 *     دیده می‌شد. حالا شکستِ جزئی هشدار می‌دهد و شکستِ کامل خطای
 *     واقعیِ باسلام (۴۰۳/توکن/شبکه) را نشان می‌دهد، نه «حذف ناموفق».
 */
function ddDeleteIds(ids){
    if(!ids||!ids.length)return;
    if(ddIsRun){showToast('⏳ یک عملیات در حال اجراست',1);return;}
    const isB=(ddTarget==='bsl'), V=isB?'بایگانی':'حذف';
    const fd=new FormData();fd.append('action','dedup_delete_ids');
    fd.append('target',ddTarget);fd.append('ids',JSON.stringify(ids));
    /* v10.44 (۵۸): سرور حالا پس‌زمینه‌ای کار می‌کند و بی‌درنگ پاسخ می‌دهد؛
       پس به‌جای انتظار برای پاسخِ طولانی (که تایم‌اوت می‌شد و کاربر می‌دید
       «دکمه کار نمی‌کند»)، همان پنلِ گزارشِ زنده را باز می‌کنیم و پیشرفت را
       مورد‌به‌مورد نشان می‌دهیم — دقیقاً مثل خودِ اسکن. */
    ddIsRun=true;ddSeen=0;
    fxTopBar(true);
    const E=ddEl;
    if(E('Btn'))E('Btn').classList.add('hidden');
    if(E('DelBtn'))E('DelBtn').classList.add('hidden');
    if(E('Stop'))E('Stop').classList.remove('hidden');
    if(E('P'))E('P').classList.remove('hidden');
    if(E('PB'))E('PB').style.width='5%';
    if(E('SM'))E('SM').classList.remove('hidden');
    if(E('Running')){E('Running').classList.remove('hidden');E('Running').innerHTML='';}
    if(E('SS'))E('SS').textContent='⏳ در حال '+V+' '+toFa(ids.length)+' مورد...';
    showToast('⏳ در حال '+V+' '+toFa(ids.length)+' مورد...');
    ddDelWatch=true;
    fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
        if(!d||!d.ok){
            ddDelWatch=false;ddFinish();
            const m=(d&&(d.error||d.msg))||(V+' ناموفق');
            if(E('SS'))E('SS').textContent='✗ '+m;
            showToast('❌ '+m,1);return;
        }
        ddWatch();
    }).catch(()=>{
        /* پاسخِ شروع ممکن است گم شود ولی کار روی سرور آغاز شده — فقط تماشا کن */
        if(E('SS'))E('SS').textContent='… اتصال کند است، وضعیت را دنبال می‌کنیم';
        ddWatch();
    });
}

