    document.body.appendChild(modal);
    fetch('?bsl_status_overview=1').then(r=>r.json()).then(d=>{
        if(!d||!d.ok){modal.querySelector('.bsl-modal-body').innerHTML='<div style="color:#f87171">\u274C '+(d?.error||'\u062E\u0637\u0627')+'</div>';return;}
        const c=d.counts;
        const statusLabels=[
