// v10.02 (۱۶): حذفِ تکراریِ باسلام — دقیقاً همان موتور و همان تنظیماتِ ووکامرس
// پیش‌تر این بخش فقط یک گزارشِ یک‌جا بود: کلِ غرفه در یک درخواستِ HTTP خوانده
// می‌شد و روی غرفه‌های بزرگ به «خطای شبکه» می‌خورد، معیارِ نگه‌داری هم سفت
// بود (هرچه فعال نبود می‌رفت). حالا مثل ووکامرس در پس‌زمینهٔ سرور اجرا می‌شود.
function bslFindDuplicates(){
    let modal=document.getElementById('bslDupModal');if(modal)modal.remove();
    modal=document.createElement('div');modal.id='bslDupModal';
    modal.innerHTML='<div class="bsl-modal-overlay" onclick="if(event.target===this)bslCloseDup()">'
      +'<div class="bsl-modal" style="width:900px;max-width:95vw">'
      +'<div class="bsl-modal-head"><h2>\u{1F5C3} بایگانیِ محصولاتِ تکراری باسلام</h2>'
      +'<button class="btn btn-gray" onclick="bslCloseDup()">\u2715</button></div>'
      +'<div class="bsl-modal-body" style="padding:12px;max-height:80vh;overflow-y:auto">'
      +'<details class="alert alert-info hint-collapse" style="font-size:11px;margin-bottom:8px"><summary>💡 چرا «بایگانی» و نه «حذف»؟</summary><div class="hint-body">در باسلام «حذف» وجود ندارد؛ نسخه‌های اضافی <b>بایگانی</b> می‌شوند (وضعیت ۴۱۸۴) و از غرفه ناپدید. کار در <b>پس‌زمینهٔ سرور</b> اجرا می‌شود — می‌توانید این پنجره را ببندید.</div></details>'
      +'<div id="bdCfgHost"></div>'
      +'<div style="display:flex;gap:6px;margin-top:8px">'
      +'<button class="btn btn-orange" id="bdBtn" onclick="ddStart(\'bsl\',\'scan\')" style="flex:1">\u{1F50D} گزارشِ تکراری‌ها</button>'
      +'<button class="btn btn-red" id="bdDelBtn" onclick="ddStart(\'bsl\',\'delete\')" style="flex:1">\u{1F5D1} بایگانیِ تکراری‌ها</button>'
      +'<button class="btn btn-red hidden" id="bdStop" onclick="ddStop()" style="flex:0">\u23F9</button>'
      +'</div>'
      +'<div class="progress hidden" id="bdP" style="margin-top:8px"><div class="progress-bar" id="bdPB" style="background:linear-gradient(90deg,#0891b2,#22d3ee)"></div></div>'
      +'<div class="status" id="bdSS" style="color:#67e8f9"></div>'
      +'<div class="sres hidden" id="bdRunning" style="max-height:220px;overflow-y:auto"></div>'
      +'<div class="ssum hidden" id="bdSM">'
      +'<div class="si"><b id="bdTot" style="color:#60a5fa">\u06F0</b><span>کل محصولات</span></div>'
      +'<div class="si"><b id="bdGrp" style="color:#facc15">\u06F0</b><span>گروه تکراری</span></div>'
      +'<div class="si"><b id="bdDup" style="color:#f97316">\u06F0</b><span>تعداد تکراری</span></div>'
      +'<div class="si"><b id="bdDel" style="color:#f87171">\u06F0</b><span>بایگانی شده</span></div>'
      +'</div>'
      +'<div id="bdReport" style="margin-top:8px"></div>'
      +'</div></div></div>';
    document.body.appendChild(modal);
    ddLoadCfg('bsl','bdCfgHost').then(()=>{
        // اگر گزارشی از قبل هست، بدونِ اسکنِ دوباره نشانش بده
        fetch('?dedup_result=1').then(r=>r.json()).then(d=>{
            if(d&&d.ok&&d.target==='bsl'){ddTarget='bsl';ddLastResult=d;ddRenderReport(d);
                const e=document.getElementById('bdSS');
                if(e)e.textContent='ℹ️ گزارشِ قبلی نمایش داده شد — برای به‌روزرسانی دکمهٔ گزارش را بزنید';}
        }).catch(()=>{});
    });
}

function bslCloseDup(){
    // نظرسنجی را ببند ولی کارِ سرور ادامه دارد
    if(ddTarget==='bsl'){clearInterval(ddTimer);ddIsRun=false;}
    const m=document.getElementById('bslDupModal');if(m)m.remove();
}

// سازگاریِ عقب‌رو با فراخوان‌های قدیمی از دیگر بخش‌ها
function bslDeleteOne(productId){
    ddTarget='bsl';
    if(!confirm('این محصول بایگانی شود؟'))return;
    ddDeleteIds([parseInt(productId,10)]);
}
function bslDeleteDuplicates(ids,groupName){
    ddTarget='bsl';
    if(!ids||!ids.length)return;
    if(!confirm(toFa(ids.length)+' نسخهٔ تکراری از «'+(groupName||'')+'» بایگانی شود؟'))return;
    ddDeleteIds(ids.map(x=>parseInt(x,10)));
}

/**
 * v8.50: این تابع هرگز تعریف نشده بود.
 *
 * دکمهٔ «دستهٔ خودکار» در پنجرهٔ جزئیات محصول و همچنین
 * bslInlineFixCatManual هر دو صدایش می‌زدند و هر بار
 * ReferenceError می‌داد. همان کار bslFixCat را می‌کند تا یادگیری
 * دسته‌بندی هم ثبت شود.
 */
function bslInlineFixCat(productId,catId){
    if(!catId||catId<=0){showToast('ابتدا دسته‌بندی انتخاب کنید!',1);return;}
    if(typeof bslFixCat==='function'){bslFixCat(productId,catId,catId);return;}
    // مسیر پشتیبان، اگر مودال فاز ۲ بارگذاری نشده باشد
    fetch('?bsl_fix_cat=1&product_id='+productId+'&category_id='+catId)
      .then(r=>r.json()).then(d=>{
        showToast(d&&d.ok?'✓ دسته اصلاح شد':('❌ '+((d&&d.error)||'خطا')),!(d&&d.ok));
      }).catch(()=>showToast('❌ خطا شبکه',1));
}

function bslInlineFixCatManual(productId){
    const catId=bslInlineSelectedCat[productId]||0;
    if(catId<=0){showToast('&#x0627;&#x0628;&#x062a;&#x062f;&#x0627; &#x062f;&#x0633;&#x062a;&#x0647;&#x200c;&#x0628;&#x0646;&#x062f;&#x06cc; &#x0627;&#x0646;&#x062a;&#x062e;&#x0627;&#x0628; &#x06a9;&#x0646;&#x06cc;&#x062f;!',1);return;}
    bslInlineFixCat(productId,catId);
}
function bslInlineSelectCat(productId,catId){
    bslInlineSelectedCat[productId]=catId;
    const btn=document.getElementById('bslInlineBtn-'+productId);
    if(btn)btn.disabled=false;
    const search=document.getElementById('bslInlineSearch-'+productId);
    const cats=window._bslModalCats||bslAllCats||[];
    const c=cats.find(c=>c.id===catId);
    if(search&&c)search.value=c.name+' ('+c.id+')';
    const list=document.getElementById('bslInlineList-'+productId);
    if(list)list.style.display='none';
}
// v7.48: Render inline category search list
function bslInlineRenderList(productId,query){
    const list=document.getElementById('bslInlineList-'+productId);
    if(!list)return;
    const cats=window._bslModalCats||bslAllCats||[];
    const q=query.toLowerCase().trim();
    const selId=bslInlineSelectedCat[productId]||0;
    let html='';
    // Show selected first
    if(selId>0){const sc=cats.find(c=>c.id===selId);if(sc&&(!q||sc.name.toLowerCase().includes(q))){html+='<div style="padding:5px 8px;cursor:pointer;background:#0e4429;color:#4ade80;border-bottom:1px solid #334155;font-size:11px" onclick="bslInlineSelectCat('+productId+','+sc.id+')">&#x2713; '+esc(sc.name)+' ('+sc.id+')</div>';}}
    cats.forEach(c=>{
        if(selId===c.id)return;
        if(q&&!c.name.toLowerCase().includes(q))return;
        const prefix=c.level>0?'──'.repeat(c.level)+' ':'';
        html+='<div style="padding:5px 8px;cursor:pointer;border-bottom:1px solid #1e293b;font-size:11px;color:#e2e8f0" onclick="bslInlineSelectCat('+productId+','+c.id+')">'+esc(prefix+c.name)+' ('+c.id+')</div>';
    });
    if(!html)html='<div style="padding:8px;color:#64748b;font-size:11px;text-align:center">&#x0646;&#x062a;&#x06cc;&#x062c;&#x0647; &#x06cc;&#x0627;&#x0641;&#x062a; &#x0646;&#x0634;&#x062f;</div>';
    list.innerHTML=html;
}
// v7.48: Set up inline search event handlers after detail popup is rendered
function setupBslInlineSearch(productId){
    const si=document.getElementById('bslInlineSearch-'+productId);
    if(!si)return;
    si.addEventListener('focus',function(){bslInlineRenderList(productId,this.value);document.getElementById('bslInlineList-'+productId).style.display='block';});
    si.addEventListener('input',function(){bslInlineRenderList(productId,this.value);document.getElementById('bslInlineList-'+productId).style.display='block';});
    si.addEventListener('blur',function(){setTimeout(function(){document.getElementById('bslInlineList-'+productId).style.display='none';},200);});
    si.addEventListener('keydown',function(e){
        if(e.key==='Escape')document.getElementById('bslInlineList-'+productId).style.display='none';
        if(e.key==='Enter'){const cats=window._bslModalCats||bslAllCats||[];const q=this.value.toLowerCase().trim();const match=cats.find(c=>c.name.toLowerCase().includes(q)&&c.id!==bslInlineSelectedCat[productId]);if(match)bslInlineSelectCat(productId,match.id);}
    });
}
// v7.48: Call setupBslInlineSearch after detail popup is shown
// (We'll patch the existing showBslProductDetail to call it after DOM insertion)
// Override: After the div2 is appended, call setup
const origShowDetail=showBslProductDetail;
showBslProductDetail=function(idx){
    origShowDetail(idx);
    const p=window._bslModalProducts&&window._bslModalProducts[idx];
    if(p){const productId=p.id;const sv=p.status||(p.revision&&p.revision.data||{}).status;const ssv=(typeof sv==='object'&&sv!==null)?sv.value:sv;const revReject=(p.revision&&typeof p.revision==='object')?(p.revision.rejection_reasons||[]):[];if(String(ssv??'')==='3567'||revReject.some(rr=>(rr.value??0)==6046)){setupBslInlineSearch(productId);}}
};

// v7.38: Phase 2 — Auto check for category-rejected products after send
function bslPhase2Check(){
    fetch('?bsl_rejected_cats=1').then(r=>r.json()).then(d=>{
        if(!d||!d.ok){showToast('خطا در بررسی محصولات رد شده',1);return;}
        const rejected=d.rejected||[];
        const cats=d.categories||[];
        if(rejected.length===0){showToast('✓ هیچ محصول رد‌شده دسته‌بندی یافت نشد');return;}
        // Show Phase 2 modal with rejected products + category dropdown + retry buttons
        showPhase2Modal(rejected,cats);
    }).catch(e=>{showToast('خطا شبکه: '+e.message,1);});
}
function showPhase2Modal(rejected,cats){
    // v8.45: بازنویسی کامل. مشکل قبلی: در حلقه دو <div> باز می‌شد ولی بسته
    // نمی‌شد، پس هر محصول داخل محصول قبلی فرو می‌رفت و با چند محصول،
    // مودال کاملاً به‌هم می‌ریخت.
    window._phase2Cats=cats;
    window._phase2Rows=rejected;
    let auto=0;
    const rows=rejected.map(p=>{
        const autoCatId=autoMatchBslCategoryJS(p.title,cats);
        if(autoCatId>0)auto++;
        return {p:p,autoCatId:autoCatId};
    });
    let h='<div class="bsl-modal-overlay" onclick="if(event.target===this)closePhase2()">';
    h+='<div class="bsl-modal" style="max-width:860px">';
    h+='<div class="bsl-modal-head">'
      +'<h2>🔄 فاز ۲ — اصلاح دستهٔ محصولات رد شده</h2>'
      +'<button class="btn btn-gray" onclick="closePhase2()">✕</button></div>';
    // نوار خلاصه و عملیات گروهی
    /* v9.96 (۱۰الف): نوارِ خلاصه+عملیات از wrap به یک ردیفِ افقی با اسکرول
       تبدیل شد تا در موبایل به ۳ سطر نشکند و ارتفاعِ لیستِ محصولات حفظ شود. */
    h+='<div class="mbar" style="gap:8px;padding:7px 14px;'
      +'background:#111c31;border-bottom:1px solid #334155">'
      +'<span style="font-size:12px;color:#e2e8f0">'+toFa(rejected.length)+' محصول رد شده</span>'
      +'<span style="font-size:11px;color:#86efac">✅ '+toFa(auto)+' پیشنهاد خودکار</span>'
      +'<span style="font-size:11px;color:#fbbf24">✋ '+toFa(rejected.length-auto)+' نیازمند انتخاب دستی</span>'
      +'<span class="mb-sp"></span>'
      +'<span id="p2Done" style="font-size:11px;color:#4ade80"></span>'
      +(auto>0?'<button class="btn btn-green" onclick="bslPhase2FixAll()" id="p2AllBtn" '
        +'style="font-size:11px;padding:5px 10px">⚡ اصلاح همهٔ پیشنهادها ('+toFa(auto)+')</button>':'')
      +'<button class="btn btn-purple" onclick="p2ApplyLearned()" id="p2LearnBtn" '
      +'style="font-size:11px;padding:5px 10px" title="بر اساس دسته‌هایی که قبلاً دستی انتخاب کرده‌اید">'
      +'🧠 اعمال آموخته‌ها</button>'
      +'<button class="btn btn-cyan" onclick="p2AskAiAll()" id="p2AiAllBtn" '
      +'style="font-size:11px;padding:5px 10px">🤖 پیشنهاد AI برای همه</button>'
      +'<button class="btn btn-orange" onclick="bslMasterFixAll()" id="p2MasterBtn" '
      +'style="font-size:11px;padding:5px 10px" title="با مدل مستر (بهترین کاندید از نظر آمار) مشورت و بقیهٔ محصولاتِ ردشده را دسته‌بندی و اصلاح کن">'
      +'🎯 اصلاح بقیه با مستر</button>'
      /* v10.12 (۲۵): نشانگر و پاک‌کنندهٔ حافظهٔ «دسته‌های امتحان‌شده».
         بدون این دکمه، اگر حافظه پر شود کاربر راهی برای شروعِ دوباره ندارد. */
      +'<span id="p2TriedInfo" style="font-size:11px;color:#f0abfc" '
      +'title="دسته‌هایی که قبلاً برای این محصولات امتحان و رد شده‌اند و دیگر پیشنهاد نمی‌شوند"></span>'
      +'<button class="btn btn-gray" onclick="p2ClearTried()" id="p2ClrTriedBtn" '
      +'style="font-size:11px;padding:5px 10px" title="پاک‌کردن حافظهٔ دسته‌های امتحان‌شده تا همهٔ دسته‌ها دوباره کاندید شوند">'
      +'🧹 پاک‌کردن تلاش‌ها</button>'
      +'</div>';
    h+='<div class="bsl-modal-body" style="max-height:64vh;overflow:auto;padding:10px">';
    if(!rows.length){
        h+='<div style="padding:24px;text-align:center;color:#64748b">موردی نیست</div>';
    }
    rows.forEach(r=>{
        const p=r.p, autoCatId=r.autoCatId;
        const autoName=autoCatId>0?((cats.find(c=>c.id===autoCatId)||{}).name||('#'+autoCatId)):'';
        h+='<div class="p2-card" id="p2-'+p.id+'">';
        h+=  '<div class="p2-title">'+esc(p.title)+' <span class="p2-id">#'+p.id+'</span></div>';
        h+=  '<div class="p2-reason">⚠️ '+esc(p.cat_reject_msg||'دستهٔ نامعتبر')
           +  ' · دستهٔ فعلی: '+esc(p.current_cat_title||String(p.current_cat_id||'—'))+'</div>';
        h+=  '<div class="p2-actions">';
        if(autoCatId>0){
            h+='<button class="btn btn-green p2-auto" id="btn-'+p.id+'" '
             + 'onclick="bslFixCat('+p.id+','+autoCatId+','+autoCatId+')">'
             + '✅ '+esc(autoName)+'</button>';
        }else{
            h+='<span class="p2-hint">دسته را دستی انتخاب کنید</span>';
        }
        // v8.51: پیشنهاد هوش مصنوعی — درخواستش جداگانه و با کلیک کاربر
        h+='<button class="btn btn-cyan" id="p2ai-'+p.id+'" '
         + 'onclick="p2AskAi('+p.id+')" style="font-size:11px;padding:5px 9px">'
         + '🤖 پیشنهاد هوش مصنوعی</button>';
        // v9.49: پیشنهاد همهٔ کاندیدها — جواب دسته‌بندیِ هر مدل کاندید را کنار
        // هم می‌آورد تا بهترین را برگزینید (رأی مستر + یادگیری + اصلاح محصول)
        h+='<button class="btn btn-purple" id="p2cand-'+p.id+'" '
         + 'onclick="p2AskCandidates('+p.id+')" style="font-size:11px;padding:5px 9px" '
         + 'title="دسته‌بندی همهٔ کاندیدها برای این محصول">'
         + '🏷️ همهٔ کاندیدها</button>';
        /* v10.12 (۲۵): دیدنِ اینکه چه دسته‌هایی قبلاً برای همین محصول
           امتحان و رد شده‌اند — تا کاربر بفهمد چرا پیشنهادها عوض شده‌اند. */
        h+='<button class="btn btn-gray" id="p2trb-'+p.id+'" '
         + 'onclick="p2ShowTried('+p.id+')" style="font-size:11px;padding:5px 9px" '
         + 'title="دسته‌هایی که قبلاً برای این محصول امتحان شده‌اند">'
         + '🧠 تلاش‌های قبلی</button>';
        h+=  '<div class="p2-search">'
           + '<input type="hidden" id="cat-'+p.id+'" value="0">'
           + '<input type="text" id="catSearch-'+p.id+'" placeholder="جستجوی دسته..." autocomplete="off">'
           + '<div id="catList-'+p.id+'" class="p2-list"></div>'
           + '</div>';
        h+=  '<button class="btn btn-orange" data-pid="'+p.id+'" onclick="bslFixCatManual(this)" '
           + 'id="btn-'+p.id+'-m">🔄 ارسال</button>';
        h+=  '</div>';                     // p2-actions
        h+=  '<div class="p2-ai" id="p2aiBox-'+p.id+'"></div>';
        h+=  '<div class="p2-tried" id="p2tr-'+p.id+'" data-open="0" style="padding:2px 0"></div>';
        h+=  '<div class="p2-status" id="p2st-'+p.id+'"></div>';
        h+='</div>';                       // p2-card  ← این دو بسته‌شدن قبلاً نبود
    });
    h+='</div></div></div>';
    const old=document.getElementById('phase2Container');if(old)old.remove();
    const div=document.createElement('div');div.id='phase2Container';div.innerHTML=h;
    document.body.appendChild(div);
    rejected.forEach(p=>{setupPhase2CatSearch(p.id,cats);});
    p2RefreshTried();   // v10.12 (۲۵): آمارِ حافظهٔ تلاش‌ها
}

/* =====================================================================
 *  v8.51: پیشنهاد هوش مصنوعی و اعمال آموخته‌ها در مودال فاز ۲
 * ===================================================================== */

/**
 * v8.51: بعد از هر انتخاب دستی، موارد باقی‌مانده با همان کلمهٔ اول را
 * پیدا می‌کند و روی کارتشان دکمهٔ «اعمال همین دسته» می‌گذارد.
 */
function p2SuggestSameWord(word){
  const rows=(window._phase2Rows||[]).filter(p=>{
    const el=document.getElementById('p2-'+p.id);
    return el&&el.dataset.done!=='1';
  });
  if(!rows.length)return;
  const fd=new FormData();
  fd.append('titles',JSON.stringify(rows.map(p=>({id:p.id,title:p.title||''}))));
  fetch('?catlearn_bulk=1',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    const m=((d&&d.matches)||[]).filter(x=>x.word===word);
    if(!m.length)return;
    m.forEach(it=>{
      const box=document.getElementById('p2aiBox-'+it.id);
      if(!box||box.dataset.learned==='1')return;
      box.dataset.learned='1';
      box.innerHTML='<span style="color:#c4b5fd">🧠 مثل «'+esc(word)+'» → دستهٔ #'+it.cat_id+'</span>'
        +' <button class="btn btn-green" style="font-size:10px;padding:2px 8px;margin-right:6px" '
        +'onclick="bslFixCat('+it.id+','+it.cat_id+','+it.cat_id+')">✅ اعمال</button>';
    });
    const bar=document.getElementById('p2LearnBtn');
    if(bar)bar.textContent='🧠 اعمال آموخته‌ها ('+toFa(m.length)+')';
    showToast('🧠 '+toFa(m.length)+' محصول دیگر با «'+word+'» پیدا شد');
  }).catch(()=>{});
}

/** پیشنهاد هوش مصنوعی برای یک محصول */
function p2AskAi(pid){
  const row=(window._phase2Rows||[]).find(x=>String(x.id)===String(pid));
  if(!row){showToast('محصول یافت نشد',1);return;}
  const box=document.getElementById('p2aiBox-'+pid);
  const btn=document.getElementById('p2ai-'+pid);
  if(btn){btn.disabled=true;btn.textContent='⏳ ...';}
  if(box)box.innerHTML='<span style="color:#93c5fd">🤖 در حال پرسیدن...</span>';
  return fetch('?bsl_ai_category=1&title='+encodeURIComponent(row.title||''))
    .then(r=>r.json()).then(d=>{
      if(btn){btn.disabled=false;btn.textContent='🤖 پیشنهاد هوش مصنوعی';}
      if(!box)return d;
      if(!d||!d.ok||!d.category_id){
        box.innerHTML='<span style="color:#fca5a5">🤖 '+esc((d&&d.error)||'پیشنهادی نداد')+'</span>';
        return d;
      }
      const nm=d.category_name||('#'+d.category_id);
      box.innerHTML='<span style="color:#67e8f9">🤖 پیشنهاد: <b>'+esc(nm)+'</b></span>'
        +' <button class="btn btn-green" style="font-size:10px;padding:2px 8px;margin-right:6px" '
        +'onclick="bslFixCat('+pid+','+d.category_id+','+d.category_id+')">✅ اجرا و ثبت</button>';
      return d;
    }).catch(()=>{
      if(btn){btn.disabled=false;btn.textContent='🤖 پیشنهاد هوش مصنوعی';}
      if(box)box.innerHTML='<span style="color:#fca5a5">🤖 خطای شبکه</span>';
    });
}

/* =====================================================================
 *  v9.49: دسته‌بندیِ همهٔ کاندیدها برای هر محصولِ تأیید‌نشده + اصلاح بقیه با مستر
 * ===================================================================== */

/** v9.49: پیشنهاد دسته‌بندی همهٔ کاندیدها برای یک محصولِ تأیید‌نشده */
function p2AskCandidates(pid){
  const row=(window._phase2Rows||[]).find(x=>String(x.id)===String(pid));
  if(!row){showToast('محصول یافت نشد',1);return;}
  const box=document.getElementById('p2aiBox-'+pid);
  const btn=document.getElementById('p2cand-'+pid);
  if(btn){btn.disabled=true;btn.textContent='⏳ ...';}
  if(box)box.innerHTML='<span style="color:#93c5fd">🏷️ در حال پرسیدن از همهٔ کاندیدها...</span>';
  return fetch('?ai_candidates_category=1&title='+encodeURIComponent(row.title||''))
    .then(r=>r.json()).then(d=>{
      if(btn){btn.disabled=false;btn.textContent='🏷️ همهٔ کاندیدها';}
      if(!box)return d;
      if(!d||!d.ok){box.innerHTML='<span style="color:#fca5a5">🏷️ '+esc((d&&d.error)||'خطا')+'</span>';return d;}
      const items=d.items||[];
      aiCandCtx={task:'category',input:d.title||row.title||'',keys:items.map(x=>x.key),items:items};
      // v9.50: پاسخ همهٔ کاندیدها را برای همین محصول نگه می‌داریم تا وقتی کاربر
      // دستهٔ صحیح را تأیید کرد، رأیِ کاندید(هایی) که همان دسته را پیش‌بینی
      // کرده بودند ثبت شود و مدل مستر بر اساس همین آمارِ صحیح انتخاب شود.
      if(!window._phase2CandResults)window._phase2CandResults={};
      window._phase2CandResults[String(pid)]={title:d.title||row.title||'',keys:items.map(x=>x.key),items:items};
      let h='<div style="background:#1e1b4b;border:1px solid #4338ca;border-radius:8px;padding:7px;font-size:11px">'
        +'<div style="color:#c4b5fd;font-weight:700;margin-bottom:4px">🏷️ دسته‌بندی «'+esc(d.title)+'» توسط '+toFa(items.length)+' کاندید — بهترین را برگزینید:</div>';
      items.forEach((it,idx)=>{
        const isM=(it.key===d.master);
        h+='<div style="border:1px solid '+(isM?'#fbbf24':'#334155')+';border-radius:6px;padding:6px;margin-bottom:4px;background:#111c31">'
          +'<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;flex-wrap:wrap">'
          +'<span style="color:'+(isM?'#fbbf24':'#e2e8f0')+';font-weight:700">'+(idx+1)+'. '+esc(it.providerName)+(isM?' ⭐':'')+'</span>'
          +'<span style="color:#64748b;font-size:9px" dir="ltr">'+esc(it.model)+' · '+toFa(it.latency||0)+'ms</span></div>'
          +'<div style="margin-top:3px">'+((it.ok&&it.category_name)
            ? '✅ <b style="color:#4ade80">'+esc(it.category_name)+'</b> (#'+it.category_id+')'
            : '<span style="color:#f87171">✗ '+(it.error||'پاسخ نامعتبر')+'</span>')+'</div>'
          +'<button class="btn btn-green" style="margin-top:5px;font-size:10px;padding:2px 9px" onclick="p2CandPick('+pid+','+idx+')">✓ برگزیدن + اصلاح</button>'
          +'</div>';
      });
      h+='</div>';
      box.innerHTML=h;
      return d;
    }).catch(()=>{ if(btn){btn.disabled=false;btn.textContent='🏷️ همهٔ کاندیدها';} if(box)box.innerHTML='<span style="color:#fca5a5">🏷️ خطای شبکه</span>'; });
}

/* v9.50: برگزیدن پاسخ یک کاندید برای یک محصولِ تأیید‌نشده.
   رأیِ مستر اینجا جدا ثبت نمی‌شود؛ اصلاحِ محصول از bslFixCat می‌رود و همان‌جا
   (پس از موفقیت) p2RecordCandVote کاندید(هایی) را که این دستهٔ صحیح را
   پیش‌بینی کرده بودند می‌برد تا تکراری نشود. */
function p2CandPick(pid, idx){
  const it=(aiCandCtx.items||[])[idx];
  if(!it){showToast('نتیجهٔ کاندید یافت نشد',1);return;}
  if(!it.ok||!it.category_id){showToast('این کاندید دستهٔ معتبری نداد',1);return;}
  // اصلاح + یادگیریِ خودِ محصول (PATCH باسلام + catLearnRecord + رأیِ کاندیدِ درست)
  bslFixCat(pid, it.category_id, it.category_id);
  // بعد از یادگیری، بقیهٔ محصولات با همان کلمهٔ اول را هم پیشنهاد بده
  if(it.category_name)setTimeout(()=>p2SuggestSameWord(catFirstWordsJS((aiCandCtx.input||''),1)),700);
}

/* v9.50: بر اساس آمارِ دسته‌بندیِ صحیحِ تأییدشده در فاز ۲، رأیِ کاندیدهایی را
   که همان دسته را پیش‌بینی کرده بودند ثبت کن تا مدل مستر (بهترین از نظر
   درصدِ بردِ همین رأی‌ها) بر اساس همین آمار انتخاب شود. اگر کاندیدی آن دسته
   را پیش‌بینی نکرده باشد، رأیی ثبت نمی‌شود. */
function p2RecordCandVote(pid, catId, catName){
  const rec=window._phase2CandResults&&window._phase2CandResults[String(pid)];
  if(!rec||!rec.items||!rec.keys||!rec.keys.length)return;
  if(!catId)return;
  const input=rec.title||'';
  const matches=(rec.items||[]).filter(it=>it.ok&&String(it.category_id)===String(catId));
  if(!matches.length)return;
  matches.forEach(it=>{
    const fd=new FormData();
    fd.append('action','ai_vote');
    fd.append('task','category');
    fd.append('input',input);
    fd.append('winner',it.key);
    fd.append('candidates',JSON.stringify(rec.keys));
    fd.append('cat_id',String(catId));
    fd.append('cat_name',catName||it.category_name||'');
    fetch('',{method:'POST',body:fd}).catch(()=>{});
  });
  // آمارِ مستر و فهرست کاندیدها را تازه کن (پس از ثبت رأی‌ها)
  setTimeout(()=>{if(typeof aiCandRender==='function')aiCandRender();},400);
}


/** پیشنهاد هوش مصنوعی برای همهٔ موارد باقی‌مانده، یکی‌یکی */
/* v10.12 (۲۵): آمارِ حافظهٔ تلاش را می‌گیرد و در نوارِ فاز ۲ نشان می‌دهد. */
function p2RefreshTried(){
  const el=document.getElementById('p2TriedInfo');
  if(!el)return;
  const fd=new FormData();fd.append('action','cat_tried');fd.append('op','stats');
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(j=>{
    if(!j||!j.ok){el.textContent='';return;}
    const pr=+(j.products||0), at=+(j.attempts||0);
    el.textContent=pr>0?('🧠 '+toFa(pr)+' محصول / '+toFa(at)+' تلاش ثبت‌شده'):'';
  }).catch(()=>{el.textContent='';});
}
/* پاک‌کردن حافظهٔ تلاش‌ها — با تأیید، چون برگشت‌ناپذیر است. */
function p2ClearTried(){
  if(!confirm('حافظهٔ «دسته‌های امتحان‌شده» پاک شود؟\n\nبعد از پاک‌کردن، دسته‌هایی که قبلاً رد شده بودند دوباره می‌توانند پیشنهاد شوند.'))return;
  const btn=document.getElementById('p2ClrTriedBtn');
  if(btn){btn.disabled=true;btn.textContent='⏳ ...';}
  const fd=new FormData();fd.append('action','cat_tried');fd.append('op','clear');fd.append('pid','0');
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(j=>{
    showToast((j&&j.msg)?j.msg:'پاک شد',!(j&&j.ok));
    p2RefreshTried();
    document.querySelectorAll('.p2-tried').forEach(e=>{e.innerHTML='';});
  }).catch(e=>{showToast('خطا: '+e.message,1);})
   .finally(()=>{if(btn){btn.disabled=false;btn.textContent='🧹 پاک‌کردن تلاش‌ها';}});
}
/* نمایش/پنهان‌کردنِ تلاش‌های قبلیِ یک محصول زیر ردیفِ خودش. */
function p2ShowTried(pid){
  const box=document.getElementById('p2tr-'+pid);
  if(!box)return;
  if(box.dataset.open==='1'){box.dataset.open='0';box.innerHTML='';return;}
  box.dataset.open='1';
  box.innerHTML='<span style="color:#64748b;font-size:11px">در حال دریافت…</span>';
  const fd=new FormData();fd.append('action','cat_tried');fd.append('op','list');fd.append('pid',String(pid));
  fetch('',{method:'POST',body:fd}).then(r=>r.json()).then(j=>{
    if(!j||!j.ok){box.innerHTML='<span style="color:#f87171;font-size:11px">خطا</span>';return;}
    const t=j.tried||[];
    if(!t.length){box.innerHTML='<span style="color:#64748b;font-size:11px">هنوز هیچ دسته‌ای برای این محصول امتحان نشده</span>';return;}
    const lbl={applied:'اعمال شد',rejected:'رد شد',failed:'ناموفق',skipped:'تکراری'};
    const col={applied:'#4ade80',rejected:'#f87171',failed:'#fbbf24',skipped:'#94a3b8'};
    box.innerHTML='<div style="font-size:11px;color:#cbd5e1;margin-bottom:3px">'
      +'🧠 '+toFa(t.length)+' دستهٔ امتحان‌شده (دیگر پیشنهاد نمی‌شوند):</div>'
      +t.map(x=>'<span style="display:inline-block;margin:2px 3px;padding:2px 7px;border-radius:9px;'
        +'background:#1e293b;border:1px solid #334155;font-size:10.5px;color:'+(col[x.res]||'#cbd5e1')+'">'
        +esc(x.name||('#'+x.id))+' ('+toFa(x.id)+')'
        +(x.n>1?' ×'+toFa(x.n):'')
        +' — '+(lbl[x.res]||x.res)+'</span>').join('');
  }).catch(e=>{box.innerHTML='<span style="color:#f87171;font-size:11px">خطا: '+esc(e.message)+'</span>';});
}
