/**
 * v8.51: بقیه را بر اساس دسته‌هایی که قبلاً دستی انتخاب کرده‌اید اصلاح کن.
 * سرور فقط پیشنهاد می‌دهد؛ اعمال اینجا و با تأیید انجام می‌شود.
 */
function p2ApplyLearned(){
  const rows=(window._phase2Rows||[]).filter(p=>{
    const el=document.getElementById('p2-'+p.id);
    return el&&el.dataset.done!=='1';
  });
  if(!rows.length){showToast('موردی باقی نمانده',1);return;}
  const btn=document.getElementById('p2LearnBtn');
  if(btn){btn.disabled=true;btn.textContent='⏳ بررسی...';}
  const fd=new FormData();
  fd.append('titles',JSON.stringify(rows.map(p=>({id:p.id,title:p.title||''}))));
  fetch('?catlearn_bulk=1',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{
    if(btn){btn.disabled=false;btn.textContent='🧠 اعمال آموخته‌ها';}
    const m=(d&&d.matches)||[];
    if(!m.length){
      showToast('برای هیچ‌کدام دستهٔ آموخته‌ای نیست — چند مورد را دستی اصلاح کنید',1);
      return;
    }
    if(!confirm('بر اساس انتخاب‌های قبلی شما، '+m.length+' محصول قابل اصلاح است.\n\nادامه؟'))return;
    if(btn){btn.disabled=true;}
    let i=0;
    (function next(){
      if(i>=m.length){
        if(btn){btn.disabled=false;btn.textContent='🧠 اعمال آموخته‌ها';}
        showToast('✓ '+toFa(m.length)+' محصول بر اساس آموخته‌ها اصلاح شد');
        return;
      }
      const it=m[i++];
      if(btn)btn.textContent='⏳ '+toFa(i)+'/'+toFa(m.length);
      const st=document.getElementById('p2st-'+it.id);
      if(st)st.innerHTML='<span style="color:#93c5fd">🧠 از «'+esc(it.word)+'»</span>';
      bslFixCat(it.id,it.cat_id,it.cat_id);
      setTimeout(next,1100);
    })();
  }).catch(()=>{
    if(btn){btn.disabled=false;btn.textContent='🧠 اعمال آموخته‌ها';}
    showToast('خطا شبکه',1);
  });
}

/** v8.45: اصلاح دسته‌جمعیِ همهٔ پیشنهادهای خودکار، یکی‌یکی و با فاصله */
function bslPhase2FixAll(){
    const rows=(window._phase2Rows||[]);
    const cats=window._phase2Cats||[];
    const todo=[];
    rows.forEach(p=>{
        const el=document.getElementById('p2-'+p.id);
        if(!el||el.dataset.done==='1')return;
        const cid=autoMatchBslCategoryJS(p.title,cats);
        if(cid>0)todo.push([p.id,cid]);
    });
    if(!todo.length){showToast('پیشنهاد خودکاری باقی نمانده',1);return;}
    const btn=document.getElementById('p2AllBtn');
    if(btn){btn.disabled=true;btn.textContent='⏳ در حال اصلاح...';}
    let i=0;
    (function next(){
        if(i>=todo.length){
            if(btn){btn.disabled=false;btn.textContent='⚡ اصلاح همهٔ پیشنهادها';}
            showToast('✓ '+toFa(todo.length)+' محصول اصلاح شد');
            return;
        }
        const [pid,cid]=todo[i++];
        bslFixCat(pid,cid,cid);
        setTimeout(next,1200);      // فاصله تا باسلام محدودیت نرخ نگیرد
    })();
}
// v7.48: Improved autoMatchBslCategoryJS — word-boundary matching
/* v8.60: «چند کلمهٔ اول» عنوان — معادل catFirstWords در PHP */
let catLearnWordsCfg=1;
function catFirstWordsJS(title,n){
    n=Math.max(1,Math.min(5,parseInt(n)||1));
    const s=(title||'').toLowerCase()
        .replace(/[0-9!@#$%^&*()+=\[\]{}|\\:;"'<>,.?/_\-–—…·«»]/g,' ')
        .replace(/\s{2,}/g,' ').trim();
    if(!s)return '';
    const skip=['خرید','فروش','قیمت','ارسال','رایگان','تخفیف','ویژه','جدید','اصل','اصلی'];
    const out=[];
    for(const w of s.split(/\s+/)){
        if(w.length<2||skip.includes(w))continue;
        out.push(w);
        if(out.length>=n)break;
    }
    return out.join(' ');
}
/* v8.60: دوربه‌دور — اول ۱ کلمه، بعد ۲ کلمه، تا سقف تنظیم‌شده */
function autoMatchBslCategoryJS(title,cats,maxWords){
    const rounds=Math.max(1,Math.min(5,parseInt(maxWords)||catLearnWordsCfg||1));
    for(let r=1;r<=rounds;r++){
        const id=autoMatchBslCategoryRoundJS(title,cats,r);
        if(id>0)return id;
    }
    return 0;
}
function autoMatchBslCategoryRoundJS(title,cats,wordsN){
    const norm=(title||'').toLowerCase().replace(/[0-9!@#$%^&*()+=\[\]{}|\\:;"<>,.?/_\-–—…·«»]/g,' ').replace(/\u200c/g,' ').replace(/\s{2,}/g,' ');
    const stop=['و','با','از','برای','در','به','تا','بر','یک','این','آن','که','هم','است','بود','شد','کن','کرد','باید','دیگر','قیمت','فروش','ارسال','رایگان','تخفیف','ویژه','نو','جدید','ست','بسته','دار','تکه','عدد','پک','سایز','رنگ','کد','اصلی','مخصوص','تک','فرد','نوع','مدل','طرح','خط','سری','متفرقه','کرانه','تن','های','ها','ای'];
    const genderMods=['زنانه','مردانه','دخترانه','پسرانه','بچگانه','نوزادی'];
    const words=norm.split(/\s+/).filter(w=>w.length>=2&&!stop.includes(w));
    if(!words.length)return 0;
    const parentIds=new Set();
    let hasHier=false;
    (cats||[]).forEach(c=>{const pid=parseInt(c.parent_id||c.parent||0)||0;if(pid>0){parentIds.add(pid);hasHier=true;}});
    // v8.60: کلمات ابتدایی همین دور، وزن سه‌برابر می‌گیرند (مثل سمت PHP)
    const lead=catFirstWordsJS(title,wordsN||1).split(/\s+/).filter(Boolean);
    let best=0,bestId=0;
    (cats||[]).forEach(c=>{
        const cid=parseInt(c.id)||0;
        if(cid<=0||(hasHier&&parentIds.has(cid)))return;
        const catNorm=(c.name||c.title||'').toLowerCase().replace(/[0-9()]/g,' ').replace(/\u200c/g,' ').replace(/\s{2,}/g,' ').trim();
        if(/حیوانات خانگی|غذای گربه|غذای سگ|شمش طلا|شمش نقره|اکسسوری طلا/.test(catNorm))return;
        const cw=catNorm.split(/\s+/).filter(w=>w.length>=2&&!stop.includes(w));
        let score=0,nounMatched=false;
        words.forEach(pw=>{
            const isG=genderMods.includes(pw);
            const wMul=isG?0.15:(lead.includes(pw)?3:1);
            cw.forEach(ccw=>{
                if(pw===ccw){score+=3*wMul;if(!isG)nounMatched=true;return;}
                if(pw.length<ccw.length){
                    if(ccw.startsWith(pw)){
                        const nextChar=ccw[pw.length];
                        if(nextChar===' '||nextChar==='\u200c'){score+=2*wMul;if(!isG)nounMatched=true;return;}
                    }
                    if(ccw.endsWith(pw)){
                        const prevChar=ccw[ccw.length-pw.length-1];
                        if(prevChar===' '||prevChar==='\u200c'){score+=2*wMul;if(!isG)nounMatched=true;return;}
                    }
                }
                if(pw.length>ccw.length&&pw.includes(ccw)){
                    const pos=pw.indexOf(ccw);
                    const beforeOk=pos===0||pw[pos-1]===' ';
                    const afterOk=pos+ccw.length===pw.length||pw[pos+ccw.length]===' ';
                    if(beforeOk&&afterOk){score+=1.5*wMul;if(!isG)nounMatched=true;return;}
                }
            });
        });
        if(!nounMatched)return;
        score+=(c.level||0)*0.2;
        if(score>best){best=score;bestId=cid;}
    });
    return best>=2?bestId:0;
}
function bslFixCatManual(btn){
    const pid=parseInt(btn.dataset.pid)||0;
    const sel=document.getElementById('cat-'+pid);
    const catId=parseInt(sel?.value)||0;
    if(catId<=0){showToast('ابتدا دسته‌بندی انتخاب کنید!',1);return;}
    bslFixCat(pid,catId,0);
}
// v7.48: Setup searchable dropdown for Phase 2 category fix
function setupPhase2CatSearch(pid,cats){
    const si=document.getElementById('catSearch-'+pid);
    if(!si)return;
    si.addEventListener('focus',function(){
        renderPhase2CatList(pid,cats,this.value);
        const list=document.getElementById('catList-'+pid);
        if(list)list.style.display='block';
    });
    si.addEventListener('input',function(){
        renderPhase2CatList(pid,cats,this.value);
        const list=document.getElementById('catList-'+pid);
        if(list)list.style.display='block';
    });
    si.addEventListener('blur',function(){
        setTimeout(function(){const list=document.getElementById('catList-'+pid);if(list)list.style.display='none';},200);
    });
    si.addEventListener('keydown',function(e){
        if(e.key==='Escape'){const list=document.getElementById('catList-'+pid);if(list)list.style.display='none';}
        if(e.key==='Enter'){const q=this.value.toLowerCase().trim();const match=cats.find(c=>c.name.toLowerCase().includes(q));if(match)phase2SelectCat(pid,match.id,cats);}
    });
}
function renderPhase2CatList(pid,cats,query){
    const list=document.getElementById('catList-'+pid);
    if(!list)return;
    const q=query.toLowerCase().trim();
    const hid=document.getElementById('cat-'+pid);
    const selId=parseInt(hid?.value)||0;
    let html='';
    if(selId>0){const sc=cats.find(c=>c.id===selId);if(sc&&(!q||sc.name.toLowerCase().includes(q))){html+='<div style="padding:5px 8px;cursor:pointer;background:#0e4429;color:#4ade80;border-bottom:1px solid #334155;font-size:11px" onclick="phase2SelectCat('+pid+','+sc.id+',window._phase2Cats)">✓ '+esc(sc.name)+' ('+sc.id+')</div>';}}
    cats.forEach(c=>{
        if(selId===c.id)return;
        if(q&&!c.name.toLowerCase().includes(q))return;
        const prefix=c.level>0?'──'.repeat(c.level)+' ':'';
        html+='<div style="padding:5px 8px;cursor:pointer;border-bottom:1px solid #1e293b;font-size:11px;color:#e2e8f0" onclick="phase2SelectCat('+pid+','+c.id+',window._phase2Cats)">'+esc(prefix+c.name)+' ('+c.id+')</div>';
    });
    if(!html)html='<div style="padding:8px;color:#64748b;font-size:11px;text-align:center">نتیجه یافت نشد</div>';
    list.innerHTML=html;
}
function phase2SelectCat(pid,catId,cats){
    const hid=document.getElementById('cat-'+pid);
    if(hid)hid.value=String(catId);
    const sc=cats.find(c=>c.id===catId);
    const si=document.getElementById('catSearch-'+pid);
    if(si&&sc)si.value=sc.name+' ('+catId+')';
    const btn=document.getElementById('btn-'+pid+'-m');
    if(btn)btn.disabled=false;
    const list=document.getElementById('catList-'+pid);
    if(list)list.style.display='none';
}
function bslFixCat(productId,catId,autoCatId){
    if(catId<=0&&autoCatId<=0){showToast('ابتدا دسته‌بندی انتخاب کنید!',1);return;}
    const useCatId=autoCatId>0?autoCatId:catId;
    if(useCatId<=0){showToast('دسته‌بندی نامعتبر!',1);return;}
    const btn=document.getElementById('btn-'+productId);
    const btnM=document.getElementById('btn-'+productId+'-m');
    if(btn)btn.disabled=true;if(btnM)btnM.disabled=true;
    // v8.48: عنوان و نام دسته را هم بفرست تا سیستم یاد بگیرد
    let _t='',_cn='';
    try{
        const row=(window._phase2Rows||[]).find(x=>String(x.id)===String(productId));
        if(row)_t=row.title||'';
        const cats=window._phase2Cats||window._bslModalCats||bslAllCats||[];
        const c=cats.find(x=>x.id===useCatId); if(c)_cn=c.name||'';
    }catch(e){}
    fetch('?bsl_fix_cat=1&product_id='+productId+'&category_id='+useCatId
      +'&title='+encodeURIComponent(_t)+'&cat_name='+encodeURIComponent(_cn))
      .then(r=>r.json()).then(d=>{
        // v8.45: به‌جای innerHTML+= که کل کارت را بازسازی و رویدادها را
        // نابود می‌کرد، فقط نوار وضعیتِ همان کارت به‌روز می‌شود.
        const row=document.getElementById('p2-'+productId);
        // v8.52: این تابع از دو جا صدا زده می‌شود: مودال فاز ۲ و پنجرهٔ
        // جزئیات محصول. قبلاً فقط عناصر فاز ۲ را به‌روز می‌کرد، پس در
        // پنجرهٔ جزئیات هیچ بازخوردی دیده نمی‌شد و دکمهٔ نارنجی «کار
        // نمی‌کرد» به نظر می‌رسید — با اینکه درخواست واقعاً می‌رفت.
        const st=document.getElementById('p2st-'+productId)
              ||document.getElementById('bslInlineResult-'+productId);
        const inlineBtn=document.getElementById('bslInlineBtn-'+productId);
        if(d&&d.ok){
            showToast('✓ دسته اصلاح شد');
            if(row){row.classList.add('p2-ok');row.dataset.done='1';}
            if(inlineBtn){inlineBtn.disabled=true;inlineBtn.textContent='✅ ارسال شد';}
            if(st)st.innerHTML='<span class="p2-ok-txt">✅ اصلاح شد — دستهٔ #'+useCatId+'</span>'
                 +(d.learned?'<span style="color:#93c5fd;margin-right:6px">🧠 آموخته شد: «'+esc(d.learn_word||'')+'»</span>':'');
            const box=document.getElementById('p2Done');
            if(box){const n=(parseInt(box.dataset.n||'0')||0)+1;box.dataset.n=String(n);
                    box.textContent='✅ '+toFa(n)+' اصلاح شد';}
            // v8.51: همین الان که یک دسته دستی ثبت شد، ببین چند مورد دیگر
            // با همان کلمهٔ اول هست و پیشنهادشان را روی کارت نشان بده.
            if(d.learned&&d.learn_word)setTimeout(()=>p2SuggestSameWord(d.learn_word),300);
            // v9.50: این تأییدِ دسته‌بندیِ صحیح در فاز ۲ را به آمارِ کاندیدها
            // وصل کن تا مدل مستر بر اساس این آمارِ صحیح انتخاب شود.
            p2RecordCandVote(productId, useCatId, _cn);
        }else{
            const msg=(d&&d.error)?d.error:'خطای نامشخص';
            showToast('❌ '+msg,1);
            if(btn)btn.disabled=false;if(btnM)btnM.disabled=false;
            if(inlineBtn)inlineBtn.disabled=false;
            if(row)row.classList.add('p2-err');
            if(st)st.innerHTML='<span class="p2-err-txt">❌ '+esc(msg)+'</span>';
        }
    }).catch(e=>{showToast('❌ خطا شبکه',1);if(btn)btn.disabled=false;if(btnM)btnM.disabled=false;
        const ib=document.getElementById('bslInlineBtn-'+productId);if(ib)ib.disabled=false;
        const ir=document.getElementById('bslInlineResult-'+productId);
        if(ir)ir.innerHTML='<span style="color:#fca5a5">❌ خطا شبکه</span>';});
}
function closePhase2(){const m=document.getElementById('phase2Container');if(m)m.remove();}
function mb_substr(s,len){if(!s)return'';if(s.length<=len)return s;return s.substring(0,len)+'…';}
var bslReportData={sent:[],updated:[],skipped:[],failed:[],retired:[]};
var wooReportData={sent:[],updated:[],skipped:[],failed:[],retired:[]};
function bslReportTypeKey(type){
    const t=String(type||'');
    if(t==='updated'||t==='update'||t.includes('آپدیت'))return'updated';
    if(t==='failed'||t==='fail'||t.includes('خطا'))return'failed';
    if(t==='sent'||t==='ok'||t.includes('ایجاد'))return'sent';
    if(t==='skipped'||t==='skip'||t.includes('تکرار'))return'skipped';
    if(t==='retired'||t.includes('بایگانی'))return'retired';
    return t;
}
function bslReportVal(v){return (v===undefined||v===null||v==='')?'':String(v);}
function bslReportBits(item,type){
    item=item||{};const t=bslReportTypeKey(type);const bits=[];
    const shop=[item.shop_name||'',item.vendor_id?('#'+item.vendor_id):''].filter(Boolean).join(' ');
    if(shop)bits.push('غرفه: '+shop);
    if(item.remote_id)bits.push('شناسه باسلام: #'+item.remote_id);
    if(item.lookup_source)bits.push('روش یافتن محصول: '+item.lookup_source);
    if(item.category)bits.push('دسته: '+item.category+(item.category_id?' (#'+item.category_id+')':''));
    if(t==='updated'){
        const reason=bslReportVal(item.update_reason||item.changes);if(reason)bits.push('علت آپدیت: '+reason);
        const detail=bslReportVal(item.changes_detail);if(detail&&detail!==reason)bits.push('جزئیات تغییر: '+detail);
        if(item.before_price_toman!==undefined||item.after_price_toman!==undefined)bits.push('قیمت: '+bslReportVal(item.before_price_toman)+' → '+bslReportVal(item.after_price_toman)+' تومان');
        if(item.before_stock!==undefined||item.after_stock!==undefined)bits.push('موجودی: '+bslReportVal(item.before_stock)+' → '+bslReportVal(item.after_stock));
        if(item.before_status!==undefined||item.after_status!==undefined)bits.push('وضعیت: '+bslReportVal(item.before_status)+' → '+bslReportVal(item.after_status));
        if(item.image_note)bits.push('تصویر: '+item.image_note);
        if(item.action)bits.push('مسیر: '+item.action);
    }else if(t==='failed'){
        if(item.error)bits.push('خطا: '+item.error);
        if(item.error_code!==undefined&&item.error_code!==null&&String(item.error_code)!=='')bits.push('کد HTTP/شبکه: '+item.error_code);
        if(item.reason_kind)bits.push('نوع خطا: '+item.reason_kind);
        if(Array.isArray(item.tried_cat_ids)&&item.tried_cat_ids.length)bits.push('دسته‌های دستی امتحان‌شده: '+item.tried_cat_ids.map(function(c){return '#'+c;}).join(' ← '));
        if(item.ai_cat_queued||item.reason_kind==='category_ai_pending')bits.push('وضعیت هوش مصنوعی: 🤖 کنار گذاشته شد برای تصحیح دسته‌بندی با هوش مصنوعی');
        if(item.error_step)bits.push('مرحله: '+item.error_step);
        if(item.endpoint)bits.push('اندپوینت: '+item.endpoint);
        if(item.error_detail&&item.error_detail!==item.error)bits.push('پاسخ خام/جزئیات: '+item.error_detail);
        if(item.status_value!==undefined)bits.push('وضعیت مقصد: '+item.status_value);
    }else{
        const d=bslReportVal(item.detail||item.reason||item.note||item.error||item.update_reason||item.changes);
        if(d)bits.push(d);
    }
    return bits.filter(x=>String(x||'').trim()!=='');
}
function bslReportDetailHtml(item,type){
    const bits=bslReportBits(item,type);
    if(!bits.length)return'<span style="color:#64748b">—</span>';
    return bits.map(x=>'<div style="margin:2px 0;line-height:1.55">'+esc(x)+'</div>').join('');
}
function showBslReport(type){
