// v7.82: Product card renderer for send logs
function renderSendCard(d){
    // d = {title, image, price, category, result:'ok'|'update'|'skip'|'fail'|'retired', error, remote_id, edit_url, changes, price_unit, link}
    const img=d.image?'<img class="scard-img" src="?image_proxy='+encodeURIComponent(d.image)+'">':'<div class="scard-noimg">📷</div>';
    const rc={ok:'scard-ok',update:'scard-up',skip:'scard-skip',fail:'scard-fail',retired:'scard-retired'};
    const ri={ok:'✅ ایجاد شد',update:'⚡ آپدیت شد',skip:'⏭ تکراری',fail:'❌ خطا',retired:'🗂 بایگانی/حذف'};
    const rc2=rc[d.result]||'scard-fail';
    const ri2=ri[d.result]||d.result;
    let priceStr=d.price?toFa(Number(d.price).toLocaleString('en-US'))+(d.price_unit==='rial'?' ریال':' تومان'):'—';
    let catStr=d.category||'—';
    let errStr=d.error?'<div class="scard-err">⚠️ '+esc(d.error)+'</div>':'';
    if(d.result==='fail'&&(d.error_detail||d.error_code||d.error_step||d.endpoint)){
        errStr+='<div class="scard-err" style="font-size:9px;line-height:1.5">'+bslReportDetailHtml(d,'failed')+'</div>';
    }
    /* v10.127: جزئیاتِ حذف/بایگانی (بازنشستگی) — ردیف‌هایِ retire در صف
       «detail» دارند که توضیح می‌دهد چه شد (انجام شد/یافت نشد/خطا). */
    let retStr=d.result==='retired'?(d.detail||d.reason)?'<div class="scard-reason">🗂 '+esc(d.detail||d.reason)+'</div>':'' : '';
    let ridStr=d.remote_id?'<div class="scard-rid">'+(d.edit_url?'<a href="'+esc(d.edit_url)+'" target="_blank">🔗</a> ':'')+'#'+d.remote_id+'</div>':'';
    /* v8.82: روی محصول ناموفق، یک دکمه که همان را در مدیریت محصولات باز
       می‌کند. تا حالا کاربر شناسه را می‌دید ولی راهی برای رسیدن به محصول
       نداشت و در هیچ سربرگی پیدایش نمی‌کرد. */
    let findStr='';
    if(d.result==='fail'){
        const term=d.remote_id?String(d.remote_id):(d.title||'');
        /* v8.84: قبلاً مقدار با JSON.stringify داخل onclick گذاشته می‌شد.
           JSON.stringify رشته را با «کوتیشن دوتایی» می‌پیچد، ولی خودِ
           onclick هم با کوتیشن دوتایی بسته می‌شود؛ پس مرورگر هندلر را سرِ
           اولین کوتیشنِ داخلی می‌بُرید و می‌شد «bslOpenAndSearch(» که
           همان خطای Unexpected end of input را می‌داد. حالا مثل بقیهٔ
           جاهای فایل، مقدار esc می‌شود و داخل کوتیشن تکی می‌نشیند. */
        if(term)findStr='<div style="margin-top:3px"><button class="btn btn-blue" style="font-size:9px;padding:2px 7px" '
            +'onclick="bslOpenAndSearch(\''+jsAttr(term)+'\')">🔍 پیدا کردن در غرفه</button></div>';
    }
    let changesStr=d.changes?'<span style="color:#facc15;font-size:9px">('+esc(d.changes)+')</span>':'';
    let reasonStr=(d.result==='update'&&(d.update_reason||d.changes||d.changes_detail))?'<div class="scard-reason">📋 '+bslReportDetailHtml(d,'updated')+'</div>':'';
    return '<div class="scard scard-'+d.result+'">'+img+'<div class="scard-body"><div class="scard-title">'+esc(d.title||'—')+'</div><div class="scard-meta"><span class="scard-price">💰 '+priceStr+'</span><span class="scard-cat">📂 '+esc(catStr)+'</span>'+(d.link?'<span><a href="'+esc(d.link)+'" target="_blank" style="color:#60a5fa">🔗</a></span>':'')+'</div><div class="scard-result '+rc2+'">'+ri2+' '+changesStr+'</div>'+reasonStr+retStr+errStr+ridStr+findStr+'</div></div>';
}
/* v10.273: چراغ زندهٔ نوار بالا. /sc محیط سروری و مسیر افزونه محیط هاست
   نام‌گذاری می‌شود؛ معیار «زنده» پاسخ معتبر خود همین runtime است، نه آنلاین
   بودن مرورگر. کلیک روی چراغ یک بررسی فوری انجام می‌دهد. */
let s4RuntimeHealthBusy=false,s4RuntimeHealthFailures=0,s4RuntimeHealthLastOk=0,s4RuntimeHealthRequest=0,s4RuntimeHealthAbort=null;
async function s4RuntimeHealthCheck(force=false){
  const el=document.getElementById('runtimePulse'),tag=document.getElementById('runtimePulseTag');if(!el)return;
  if(s4RuntimeHealthBusy){if(!force)return;try{if(s4RuntimeHealthAbort)s4RuntimeHealthAbort.abort();}catch(_e){}}
  const request=++s4RuntimeHealthRequest,serverMode=/\/sc(?:\/|$)/i.test(location.pathname),kind=serverMode?'سرور':'هاست',short=serverMode?'S':'H';
  s4RuntimeHealthBusy=true;
  if(force||!el.dataset.checked){el.classList.remove('online','offline');el.classList.add('checking');if(tag)tag.textContent='…';el.title='در حال بررسی '+kind+'…';}
  const ac=typeof AbortController!=='undefined'?new AbortController():null;s4RuntimeHealthAbort=ac;
  const timer=ac?setTimeout(()=>ac.abort(),12000):null;
  try{
    const r=await fetch('?runtime_health=1&_health='+Date.now(),{cache:'no-store',credentials:'same-origin',signal:ac?ac.signal:undefined});
    if(!r.ok)throw new Error('HTTP '+r.status);const d=await r.json();if(!d||d.ok!==true||!d.version)throw new Error('invalid response');
    if(request!==s4RuntimeHealthRequest)return;
    s4RuntimeHealthFailures=0;s4RuntimeHealthLastOk=Date.now();
    el.classList.remove('checking','offline');el.classList.add('online');el.dataset.checked=String(s4RuntimeHealthLastOk);if(tag)tag.textContent=short;
    el.title='● '+kind+' زنده است · PHP v'+String(d.version)+' پاسخ می‌دهد';el.setAttribute('aria-label',kind+' زنده است');
  }catch(e){
    if(request!==s4RuntimeHealthRequest)return;
    s4RuntimeHealthFailures++;
    const browserOffline=navigator.onLine===false,recentOk=s4RuntimeHealthLastOk>0&&(Date.now()-s4RuntimeHealthLastOk)<90000;
    if(!browserOffline&&(s4RuntimeHealthFailures<3||recentOk)){
      /* A loaded PHP host can miss one probe while normal requests still work.
         Keep this amber/degraded; red is reserved for sustained failure. */
      el.classList.remove('online','offline');el.classList.add('checking');if(tag)tag.textContent='~';
      el.title='● پاسخ '+kind+' کند یا موقتاً مشغول است · تلاش '+String(s4RuntimeHealthFailures)+' از ۳';
      el.setAttribute('aria-label',kind+' موقتاً کند است');
    }else{
      el.classList.remove('checking','online');el.classList.add('offline');if(tag)tag.textContent='!';
      el.title=browserOffline?'● اتصال مرورگر قطع است':'● '+kind+' پس از ۳ بررسی پاسخ نداده است';el.setAttribute('aria-label',kind+' پاسخ نمی‌دهد');
    }
  }finally{if(timer)clearTimeout(timer);if(request===s4RuntimeHealthRequest){s4RuntimeHealthBusy=false;s4RuntimeHealthAbort=null;}}
}
(function runtimeHealthPulse(){setTimeout(()=>s4RuntimeHealthCheck(true),700);setInterval(()=>s4RuntimeHealthCheck(false),15000);window.addEventListener('online',()=>s4RuntimeHealthCheck(true));window.addEventListener('focus',()=>s4RuntimeHealthCheck(true));document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')s4RuntimeHealthCheck(true);});window.addEventListener('offline',()=>{s4RuntimeHealthFailures=3;const e=document.getElementById('runtimePulse'),t=document.getElementById('runtimePulseTag');if(e){e.classList.remove('online','checking');e.classList.add('offline');e.title='اتصال مرورگر قطع است';if(t)t.textContent='!';}});})();
/* v10.400: keep the top health pulser in sync with every internal/external cron arrival. */
(function s4CronArrivalPulse(){
  const FLASH_CLASS=['cron-pulse-internal','cron-pulse-external'],PULSE_MS=2500,PULSE_GAP_MS=120,POLL_MS=2200;
  const pulseEl=document.getElementById('runtimePulse');
  let cursor=Math.max(0,parseInt(pulseEl&&pulseEl.dataset.cronPulseCursor)||0),busy=false,active=false,ready=false,queue=[];
  const runNext=()=>{
    if(active||!queue.length)return;const el=document.getElementById('runtimePulse');
    if(!el){setTimeout(runNext,300);return;}
    const kind=queue.shift(),cls=kind==='internal'?FLASH_CLASS[0]:FLASH_CLASS[1];
    el.classList.remove(...FLASH_CLASS);el.classList.add(cls);active=true;
    setTimeout(()=>{el.classList.remove(cls);setTimeout(()=>{active=false;runNext();},PULSE_GAP_MS);},PULSE_MS);
  };
  const poll=(syncOnly=false)=>{
    if(busy||document.visibilityState==='hidden')return;busy=true;
    const u='?cron_visual_pulse=1&after='+encodeURIComponent(cursor);
    fetch(u,{cache:'no-store',credentials:'same-origin'}).then(r=>r.ok?r.json():null).then(d=>{
      if(!d||d.ok!==true)return;const latest=Math.max(0,parseInt(d.latest_id)||0);
      if(latest<cursor){cursor=latest;ready=true;return;}
      const events=Array.isArray(d.events)?d.events:[];
      if(!ready||!syncOnly){events.slice().sort((a,b)=>(parseInt(a.id)||0)-(parseInt(b.id)||0)).forEach(e=>{if(e.kind==='internal'||e.kind==='external')queue.push(e.kind);});runNext();}
      cursor=latest;ready=true;
    }).catch(()=>{}).finally(()=>{busy=false;});
  };
  setTimeout(()=>poll(false),650);setInterval(()=>poll(false),POLL_MS);
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')poll(true);});
  window.addEventListener('focus',()=>poll(true));
})();
/* v10.369: صفحهٔ باز، مرجع feedback کران داخلی را زنده نگه می‌دارد. receiver
   فاصلهٔ ذخیره‌شده، lock و enabled را enforce می‌کند؛ چند tab امن هستند. */
(function opsFeedbackPulse(){
  if(window._s4OpsPulse)return;window._s4OpsPulse=true;
  const cronReference='https://scraper4.42web.io/scraper4.php';
  const localBeat=()=>fetch('?ops_feedback=1&repair=1',{cache:'no-store',credentials:'same-origin',keepalive:true}).catch(()=>{});
  const cronBeat=()=>{
    const u=cronReference+'?internal_cron_feedback=1&_pulse='+Date.now();
    return fetch(u,{method:'GET',mode:'no-cors',cache:'no-store',keepalive:true}).catch(()=>{});
  };
  const cronRunBeat=()=>{
    if(window._s4BrowserCronBusy)return;window._s4BrowserCronBusy=true;
    const u=cronReference+'?cron_run=1&internal_browser_keep=1&_pulse='+Date.now();
    fetch(u,{method:'GET',mode:'no-cors',cache:'no-store'}).catch(()=>{}).finally(()=>{window._s4BrowserCronBusy=false;});
  };
  const matrixBeat=()=>{
    if(window._s4MatrixFeedbackBusy)return;window._s4MatrixFeedbackBusy=true;
    const u=cronReference+'?internal_matrix_feedback=1&_pulse='+Date.now();
    fetch(u,{method:'GET',mode:'no-cors',cache:'no-store'}).catch(()=>{}).finally(()=>{window._s4MatrixFeedbackBusy=false;});
  };
  const wake=()=>{localBeat();cronBeat();cronRunBeat();matrixBeat();};
  setTimeout(wake,1200);setInterval(cronBeat,15000);setInterval(matrixBeat,20000);setInterval(cronRunBeat,30000);setInterval(localBeat,120000);
  window.addEventListener('pageshow',wake);window.addEventListener('online',wake);
  window.addEventListener('focus',wake);
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')wake();});
})();
</script>
</body>
</html>
